;@ path: engine/battle/safari_zone
;@ def PrintSafariZoneBattleText()
;@ The Safari Zone's turn message: while bait lasts the wild Pokémon is "eating"; while it is still angry from a
;@ rock it is "angry", and when the anger wears off its catch rate goes back to normal.
PrintSafariZoneBattleText:
;> if wSafariBaitFactor:
	ld hl, wSafariBaitFactor
	ld a, [hl]
	and a
	jr z, .no_bait
;>     wSafariBaitFactor -= 1
	dec [hl]
;>     text = SafariZoneEatingText
	ld hl, SafariZoneEatingText
	jr .done
;> else:
.no_bait
;>     if wSafariEscapeFactor == 0:
;>         return
	dec hl
	ld a, [hl]
	and a
	ret z
;>     wSafariEscapeFactor -= 1
	dec [hl]
;>     text = SafariZoneAngryText
	ld hl, SafariZoneAngryText
;>     if wSafariEscapeFactor == 0:
	jr nz, .done
;>         wCurSpecies = mem[wEnemyMonSpecies]
	push hl
	ld a, [wEnemyMonSpecies]
	ld [wCurSpecies], a
;>         GetMonHeader()
	call GetMonHeader
;>         wEnemyMonActualCatchRate = wMonHCatchRate
	ld a, [wMonHCatchRate]
	ld [wEnemyMonActualCatchRate], a
	pop hl
.done
;> LoadScreenTilesFromBuffer1()
	push hl
	call LoadScreenTilesFromBuffer1
	pop hl
;> PrintText(text)
	jp PrintText

;@ path: engine/battle/safari_zone
SafariZoneEatingText:
	db TX_FAR
	dw _SafariZoneEatingText
	db BANK(_SafariZoneEatingText)
	db TX_END

;@ path: engine/battle/safari_zone
SafariZoneAngryText:
	db TX_FAR
	dw _SafariZoneAngryText
	db BANK(_SafariZoneAngryText)
	db TX_END
;@ path: engine/movie/title
;@ def CopyDebugName(src: hl, dest: de)
;@ Copy a name (NAME_LENGTH bytes).
;@ test: src = rand(0x4000, 0x7F00); dest = rand(0xC000, 0xCF00)
CopyDebugName:
;> CopyData(src, dest, NAME_LENGTH)
	ld bc, NAME_LENGTH
	jp CopyData

;@ path: engine/movie/title
;@ def PrepareTitleScreen()
;@ Before the title screen: default names (replaced later anyway), all story flags of the last session cleared,
;@ the title music's bank; then the title screen.
;@ test: skip shows the title screen
PrepareTitleScreen::
	; These debug names are already copied later in PrepareOakSpeech.
	; Removing the unused copies below has no apparent impact.
	; CopyDebugName can also be safely deleted afterwards.
;> CopyDebugName(DebugNewGamePlayerName, addr(wPlayerName))
	ld hl, DebugNewGamePlayerName
	ld de, wPlayerName
	call CopyDebugName
;> CopyDebugName(DebugNewGameRivalName, addr(wRivalName))
	ld hl, DebugNewGameRivalName
	ld de, wRivalName
	call CopyDebugName
;> hWY = 0
	xor a
	ldh [hWY], a
;> wLetterPrintingDelayFlags = 0
	ld [wLetterPrintingDelayFlags], a
;> wStatusFlags6 = 0
	ld hl, wStatusFlags6
	ld [hli], a
	ASSERT wStatusFlags6 + 1 == wStatusFlags7
;> wStatusFlags7 = 0
	ld [hli], a
	ASSERT wStatusFlags7 + 1 == wElite4Flags
;> wElite4Flags = 0
	ld [hl], a
;> wAudioROMBank = BANK(Music_TitleScreen)
	ld a, BANK(Music_TitleScreen)
	ld [wAudioROMBank], a
;> wAudioSavedROMBank = BANK(Music_TitleScreen)
	ld [wAudioSavedROMBank], a
;> DisplayTitleScreen()

;@ path: engine/movie/title
;@ def DisplayTitleScreen()
;@ The title screen: the Pokémon logo drops in and bounces, "Red Version" slides in from the right, and the
;@ player stands there while Pokémon scroll past one after another until a button is pressed. Then the main
;@ menu, or with Up + Select + B held, the dialogue that clears the save file.
;@ test: skip runs the title screen
DisplayTitleScreen:
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> hTileAnimations = 0
;> hSCX = 0
	xor a
	ldh [hTileAnimations], a
	ldh [hSCX], a
;> hSCY = 0x40                                   # the logo starts above the screen
	ld a, $40
	ldh [hSCY], a
;> hWY = 0x90                                    # the window below it
	ld a, $90
	ldh [hWY], a
;> ClearScreen()
	call ClearScreen
;> DisableLCD()
	call DisableLCD
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> FarCopyData2(BANK(NintendoCopyrightLogoGraphics), NintendoCopyrightLogoGraphics, vTitleLogo2 + 16 * TILE_SIZE, 5 * TILE_SIZE)
	ld hl, NintendoCopyrightLogoGraphics
	ld de, vTitleLogo2 + TILE_SIZE * 16
	ld bc, 5 * TILE_SIZE
	ld a, BANK(NintendoCopyrightLogoGraphics)
	call FarCopyData2
;> FarCopyData2(BANK(GameFreakLogoGraphics), GameFreakLogoGraphics, vTitleLogo2 + (16 + 5) * TILE_SIZE, 9 * TILE_SIZE)
	ld hl, GameFreakLogoGraphics
	ld de, vTitleLogo2 + TILE_SIZE * (16 + 5)
	ld bc, 9 * TILE_SIZE
	ld a, BANK(GameFreakLogoGraphics)
	call FarCopyData2
;> FarCopyData2(BANK(PokemonLogoGraphics), PokemonLogoGraphics, vTitleLogo, 0x60 * TILE_SIZE)
	ld hl, PokemonLogoGraphics
	ld de, vTitleLogo
	ld bc, $60 * TILE_SIZE
	ld a, BANK(PokemonLogoGraphics)
	call FarCopyData2          ; first chunk
;> FarCopyData2(BANK(PokemonLogoGraphics), PokemonLogoGraphics + 0x60 * TILE_SIZE, vTitleLogo2, 0x10 * TILE_SIZE)
	ld hl, PokemonLogoGraphics + TILE_SIZE * $60
	ld de, vTitleLogo2
	ld bc, $10 * TILE_SIZE
	ld a, BANK(PokemonLogoGraphics)
	call FarCopyData2          ; second chunk
;> FarCopyDataDouble(BANK(Version_GFX), Version_GFX, vChars2 + 0x60 * TILE_SIZE + (10 * TILE_SIZE - (Version_GFXEnd - Version_GFX) * 2) // 2, Version_GFXEnd - Version_GFX)
	ld hl, Version_GFX
	ld de, vChars2 + TILE_SIZE * $60 + (10 * TILE_SIZE - (Version_GFXEnd - Version_GFX) * 2) / 2
	ld bc, Version_GFXEnd - Version_GFX
	ld a, BANK(Version_GFX)
	call FarCopyDataDouble
;> ClearBothBGMaps()
	call ClearBothBGMaps

; place tiles for pokemon logo (except for the last row)
;> # the Pokémon logo: 6 rows of 16 tiles from $80, and a last row from $31
;> at, tile = coord(2, 1), 0x80
	ld hl, (1) * SCREEN_WIDTH + (2) + wTileMap
	ld a, $80
	ld de, SCREEN_WIDTH
;> for row in range(6):
	ld c, 6
.pokemonLogoTileLoop
;>     for column in range(16):
	ld b, $10
	push hl
.pokemonLogoTileRowLoop ; place tiles for one row
;>         mem[at + column] = tile; tile += 1
	ld [hli], a
	inc a
	dec b
	jr nz, .pokemonLogoTileRowLoop
;>     at += SCREEN_WIDTH
	pop hl
	add hl, de
	dec c
	jr nz, .pokemonLogoTileLoop

; place tiles for the last row of the pokemon logo
;> for column in range(16):
	ld hl, (7) * SCREEN_WIDTH + (2) + wTileMap
	ld a, $31
	ld b, $10
.pokemonLogoLastTileRowLoop
;>     mem[coord(2 + column, 7)] = 0x31 + column
	ld [hli], a
	inc a
	dec b
	jr nz, .pokemonLogoLastTileRowLoop

;> DrawPlayerCharacter()
	call DrawPlayerCharacter

; put a pokeball in the player's hand
;> mem[addr(wShadowOAMSprite10)] = 0x74          # a Poké Ball in the player's hand
	ld hl, wShadowOAMSprite10
	ld a, $74
	ld [hl], a

; place tiles for title screen copyright
;> for i in range(16):                           # ©'95.'96.'98 GAME FREAK inc.
	ld hl, (17) * SCREEN_WIDTH + (2) + wTileMap
	ld de, .tileScreenCopyrightTiles
	ld b, .tileScreenCopyrightTilesEnd - .tileScreenCopyrightTiles
.tileScreenCopyrightTilesLoop
;>     mem[coord(2 + i, 17)] = mem[DisplayTitleScreen.tileScreenCopyrightTiles + i]
	ld a, [de]
	ld [hli], a
	inc de
	dec b
	jr nz, .tileScreenCopyrightTilesLoop

	jr .next

.tileScreenCopyrightTiles
	db $41,$42,$43,$42,$44,$42,$45,$46,$47,$48,$49,$4A,$4B,$4C,$4D,$4E ; ©'95.'96.'98 GAME FREAK inc.
.tileScreenCopyrightTilesEnd

.next
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> EnableLCD()
	call EnableLCD

;> wTitleMonSpecies = STARTER1                   # Blue starts with STARTER2
;> LoadTitleMonSprite(wTitleMonSpecies)
	ld a, STARTER1 ; which Pokemon to show first on the title screen
	ld [wTitleMonSpecies], a
	call LoadTitleMonSprite

;> TitleScreenCopyTileMapToVRAM((vBGMap0 + 0x300) >> 8)
	ld a, HIGH(vBGMap0 + $300)
	call TitleScreenCopyTileMapToVRAM
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> hWY = 0x40
	ld a, $40
	ldh [hWY], a
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> TitleScreenCopyTileMapToVRAM(vBGMap0 >> 8)
	ld a, HIGH(vBGMap0)
	call TitleScreenCopyTileMapToVRAM
;> RunPaletteCommand(SET_PAL_TITLE_SCREEN)
	ld b, SET_PAL_TITLE_SCREEN
	call RunPaletteCommand
;> GBPalNormal()
	call GBPalNormal
;> rOBP0 = 0b11100100
	ld a, %11100100
	ldh [rOBP0], a

; make pokemon logo bounce up and down
;> # the logo bounces: (pixels, frames) pairs from the table, a crash sound at the first -3
;> scrolls = DisplayTitleScreen.TitleScreenPokemonLogoYScrolls
	ld bc, hSCY ; background scroll Y
	ld hl, .TitleScreenPokemonLogoYScrolls
;> while mem[scrolls]:
.bouncePokemonLogoLoop
	ld a, [hli]
	and a
	jr z, .finishedBouncingPokemonLogo
;>     amount = mem[scrolls]
	ld d, a
;>     if amount == u8(-3):
;>         PlaySound(SFX_INTRO_CRASH)
	cp -3
	jr nz, .skipPlayingSound
	ld a, SFX_INTRO_CRASH
	call PlaySound
.skipPlayingSound
;>@times     for _ in range(mem[scrolls + 1]):
	ld a, [hli]
	ld e, a
	call .ScrollTitleScreenPokemonLogo
;>@frame         DelayFrame()
;>@scy         hSCY = u8(hSCY + amount)
;>     scrolls += 2
	jr .bouncePokemonLogoLoop

.TitleScreenPokemonLogoYScrolls:
; Controls the bouncing effect of the Pokemon logo on the title screen
	db -4,16  ; y scroll amount, number of times to scroll
	db 3,4
	db -3,4
	db 2,2
	db -2,2
	db 1,2
	db -1,2
	db 0      ; terminate list with 0

.ScrollTitleScreenPokemonLogo:
; Scrolls the Pokemon logo on the title screen to create the bouncing effect
; Scrolls d pixels e times
;=@frame
	call DelayFrame
;=@scy
	ld a, [bc] ; background scroll Y
	add d
	ld [bc], a
;=@times
	dec e
	jr nz, .ScrollTitleScreenPokemonLogo
	ret

.finishedBouncingPokemonLogo
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> DelayFrames(36)
	ld c, 36
	call DelayFrames
;> PlaySound(SFX_INTRO_WHOOSH)
	ld a, SFX_INTRO_WHOOSH
	call PlaySound

; scroll game version in from the right
;> # the version name slides in from the right on its band of the screen
;> PrintGameVersionOnTitleScreen()
	call PrintGameVersionOnTitleScreen
;> hWY = SCREEN_HEIGHT_PX
	ld a, SCREEN_HEIGHT_PX
	ldh [hWY], a
;> scx = 144
	ld d, 144
;> while True:
.scrollTitleScreenGameVersionLoop
;>     ScrollTitleScreenGameVersion(64, scx)
	ld h, d
	ld l, 64
	call ScrollTitleScreenGameVersion
;>     ScrollTitleScreenGameVersion(80, 0)
	ld h, 0
	ld l, 80
	call ScrollTitleScreenGameVersion
;>     scx = u8(scx + 4)
	ld a, d
	add 4
	ld d, a
;>     if scx == 0:
;>         break
	and a
	jr nz, .scrollTitleScreenGameVersionLoop

;> TitleScreenCopyTileMapToVRAM(vBGMap1 >> 8)
	ld a, HIGH(vBGMap1)
	call TitleScreenCopyTileMapToVRAM
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> PrintGameVersionOnTitleScreen()
	call PrintGameVersionOnTitleScreen
;> Delay3()
	call Delay3
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> wNewSoundID = MUSIC_TITLE_SCREEN
;> PlaySound(MUSIC_TITLE_SCREEN)
	ld a, MUSIC_TITLE_SCREEN
	ld [wNewSoundID], a
	call PlaySound
;> wUnusedFlag = 0
	xor a
	ld [wUnusedFlag], a

; Keep scrolling in new mons indefinitely until the user performs input.
;> while not CheckForUserInterruption(200):      # until a button is pressed
.awaitUserInterruptionLoop
	ld c, 200
	call CheckForUserInterruption
	jr c, .finishedWaiting
;>     TitleScreenScrollInMon()
	call TitleScreenScrollInMon
;>     if CheckForUserInterruption(1):
;>         break
	ld c, 1
	call CheckForUserInterruption
	jr c, .finishedWaiting
;>     TitleScreenAnimateBallIfStarterOut()
	ld b, BANK(TitleScreenAnimateBallIfStarterOut)
	ld hl, TitleScreenAnimateBallIfStarterOut
	call Bankswitch
;>     TitleScreenPickNewMon()
	call TitleScreenPickNewMon
	jr .awaitUserInterruptionLoop

.finishedWaiting
;> PlayCry(wTitleMonSpecies)
	ld a, [wTitleMonSpecies]
	call PlayCry
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearSprites()
	call ClearSprites
;> hWY = 0
	xor a
	ldh [hWY], a
;> hAutoBGTransferEnabled = 1
	inc a
	ldh [hAutoBGTransferEnabled], a
;> ClearScreen()
	call ClearScreen
;> TitleScreenCopyTileMapToVRAM(vBGMap0 >> 8)
	ld a, HIGH(vBGMap0)
	call TitleScreenCopyTileMapToVRAM
;> TitleScreenCopyTileMapToVRAM(vBGMap1 >> 8)
	ld a, HIGH(vBGMap1)
	call TitleScreenCopyTileMapToVRAM
;> Delay3()
;> LoadGBPal()
	call Delay3
	call LoadGBPal
;> if hJoyHeld & (PAD_UP | PAD_SELECT | PAD_B) == PAD_UP | PAD_SELECT | PAD_B:
	ldh a, [hJoyHeld]
	ld b, a
	and PAD_UP | PAD_SELECT | PAD_B
	cp PAD_UP | PAD_SELECT | PAD_B
	jp z, .doClearSaveDialogue
;>@clear     return DoClearSaveDialogue()
;> return MainMenu()                             # debug builds: Select opens the debug menu
	jp MainMenu

.doClearSaveDialogue
;=@clear
	ld b, BANK(DoClearSaveDialogue)
	ld hl, DoClearSaveDialogue
	jp Bankswitch

;@ path: engine/movie/title
;@ def TitleScreenPickNewMon()
;@ Pick another random Pokémon from TitleMons (never the one shown) and scroll the current one out.
;@ test: skip waits for frames
TitleScreenPickNewMon:
;> TitleScreenCopyTileMapToVRAM(vBGMap0 >> 8)
	ld a, HIGH(vBGMap0)
	call TitleScreenCopyTileMapToVRAM

;> while True:
.loop
; Keep looping until a mon different from the current one is picked.
;>     pick = Random() & 0xF
	call Random
	and $f
;>     at = TitleMons + pick
	ld c, a
	ld b, 0
	ld hl, TitleMons
	add hl, bc
;>     species = mem[at]
	ld a, [hl]
	ld hl, wTitleMonSpecies

; Can't be the same as before.
;>     if species != wTitleMonSpecies:
;>         break
	cp [hl]
	jr z, .loop

;> wTitleMonSpecies = species
	ld [hl], a
;> LoadTitleMonSprite(species)
	call LoadTitleMonSprite

;> hWY = 0x90
	ld a, $90
	ldh [hWY], a
;> TitleScroll(1)
	ld d, 1 ; scroll out
	ld b, BANK(TitleScroll)
	ld hl, TitleScroll
	call Bankswitch
;> return
	ret

;@ path: engine/movie/title
;@ def TitleScreenScrollInMon()
;@ Scroll the title Pokémon in from the right.
;@ test: skip waits for screen lines
TitleScreenScrollInMon:
;> TitleScroll(0)
	ld d, 0 ; scroll in
	ld b, BANK(TitleScroll)
	ld hl, TitleScroll
	call Bankswitch
;> hWY = 0
	xor a
	ldh [hWY], a
	ret

;@ path: engine/movie/title
;@ def ScrollTitleScreenGameVersion(line: l, scx: h)
;@ Wait for screen line `line`, set the horizontal scroll to `scx`, then wait while the line equals `scx`.
;@ test: skip waits for screen lines
ScrollTitleScreenGameVersion:
.wait
;> wait_ly(line)
	ldh a, [rLY]
	cp l
	jr nz, .wait

;> rSCX = scx
	ld a, h
	ldh [rSCX], a

.wait2
;> while rLY == scx:
;>     wait_ly()    # the LCD moves rLY on
	ldh a, [rLY]
	cp h
	jr z, .wait2
	ret

;@ path: engine/movie/title
;@ def DrawPlayerCharacter()
;@ The player on the title screen: load the sprite tiles and place 7 rows of 5 sprites from (X $5A, Y $60).
;@ test: hLoadedROMBank = 1
DrawPlayerCharacter:
;> FarCopyData2(BANK(PlayerCharacterTitleGraphics), PlayerCharacterTitleGraphics, vSprites, PlayerCharacterTitleGraphicsEnd - PlayerCharacterTitleGraphics)
	ld hl, PlayerCharacterTitleGraphics
	ld de, vSprites
	ld bc, PlayerCharacterTitleGraphicsEnd - PlayerCharacterTitleGraphics
	ld a, BANK(PlayerCharacterTitleGraphics)
	call FarCopyData2
;> ClearSprites()
	call ClearSprites
;> wPlayerCharacterOAMTile = 0
	xor a
	ld [wPlayerCharacterOAMTile], a
;> oam = addr(wShadowOAM)
	ld hl, wShadowOAM
;> y = 0x60
	ld de, (($60) & $ff) << 8 + (($5a) & $ff)
;> for row in range(7):
	ld b, 7
.loop
;>     x = 0x5A
	push de
;>     for column in range(5):
	ld c, 5
.innerLoop
;>         mem[oam] = y
	ld a, d
	ld [hli], a ; Y
;>         mem[oam + 1] = x
	ld a, e
	ld [hli], a ; X
;>         x = u8(x + 8)
	add 8
	ld e, a
;>         mem[oam + 2] = wPlayerCharacterOAMTile
	ld a, [wPlayerCharacterOAMTile]
	ld [hli], a ; tile
;>         wPlayerCharacterOAMTile = u8(wPlayerCharacterOAMTile + 1)
	inc a
	ld [wPlayerCharacterOAMTile], a
;>         oam += OBJ_SIZE
	inc hl
	dec c
	jr nz, .innerLoop
	pop de
;>     y = u8(y + 8)
	ld a, 8
	add d
	ld d, a
	dec b
	jr nz, .loop
	ret

;@ path: engine/movie/title
;@ def ClearBothBGMaps()
;@ Blank both BG maps.
ClearBothBGMaps:
;> FillMemory(vBGMap0, 2 * TILEMAP_AREA, charmap(' ')[0])
	ld hl, vBGMap0
	ld bc, 2 * TILEMAP_AREA
	ld a, ' '
	jp FillMemory

