;@ path: engine/movie/title
;@ def LoadCopyrightTiles()
;@ The copyright screen: Nintendo, Creatures and Game Freak logos and the copyright line.
;@ test: skip copies to VRAM over several VBlanks
LoadCopyrightTiles:
;> CopyVideoData(vChars2 + 0x60 * TILE_SIZE, NintendoCopyrightLogoGraphics, BANK(NintendoCopyrightLogoGraphics), (GameFreakLogoGraphicsEnd - NintendoCopyrightLogoGraphics) // TILE_SIZE)
	ld de, NintendoCopyrightLogoGraphics
	ld hl, vChars2 + TILE_SIZE * $60
	ld bc, ((BANK(NintendoCopyrightLogoGraphics)) & $ff) << 8 + (((GameFreakLogoGraphicsEnd - NintendoCopyrightLogoGraphics) / TILE_SIZE) & $ff)
	call CopyVideoData
;> PlaceString(CopyrightTextString, coord(2, 7))
	ld hl, (7) * SCREEN_WIDTH + (2) + wTileMap
	ld de, CopyrightTextString
	jp PlaceString

