;@ path: engine/pokemon/load_mon_data
;@ def LoadMonData_()
;@ Copy Pokémon number wWhichPokemon of the list wMonDataLocation names (party, enemy party, box or day care)
;@ to wLoadedMon, with its species in wCurPartySpecies and its base data in wMonHeader.
LoadMonData_::
; Load monster [wWhichPokemon] from list [wMonDataLocation]:
;  0: partymon
;  1: enemymon
;  2: boxmon
;  3: daycaremon
; Return monster id at wCurPartySpecies and its data at wLoadedMon.
; Also load base stats at wMonHeader for convenience.

;> wCurPartySpecies = mem[wDayCareMonSpecies]
	ld a, [wDayCareMonSpecies]
	ld [wCurPartySpecies], a
;> loc = wMonDataLocation
;> if loc != DAYCARE_DATA:
	ld a, [wMonDataLocation]
	cp DAYCARE_DATA
	jr z, .GetMonHeader

;>     GetMonSpecies(wWhichPokemon)              # into wCurPartySpecies
	ld a, [wWhichPokemon]
	ld e, a
	ld hl, GetMonSpecies
	ld b, BANK(GetMonSpecies)
	call Bankswitch

.GetMonHeader
;> wCurSpecies = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader

;> src, size = addr(wPartyMons), PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMons
	ld bc, PARTYMON_STRUCT_LENGTH
;> if loc >= ENEMY_PARTY_DATA:
	ld a, [wMonDataLocation]
	cp ENEMY_PARTY_DATA
	jr c, .getMonEntry

;>     src = addr(wEnemyMons)
;>     if loc != ENEMY_PARTY_DATA:
	ld hl, wEnemyMons
	jr z, .getMonEntry

;>         src, size = addr(wBoxMons), BOXMON_STRUCT_LENGTH
;>         if loc != BOX_DATA:
	cp BOX_DATA
	ld hl, wBoxMons
	ld bc, BOXMON_STRUCT_LENGTH
	jr z, .getMonEntry

;>             src = addr(wDayCareMon)           # a single record: no index to add
	ld hl, wDayCareMon
	jr .copyMonData

.getMonEntry
;> if loc != DAYCARE_DATA:
;>     src += wWhichPokemon * size
	ld a, [wWhichPokemon]
	call AddNTimes

.copyMonData
;> CopyData(src, addr(wLoadedMon), PARTYMON_STRUCT_LENGTH)
	ld de, wLoadedMon
	ld bc, PARTYMON_STRUCT_LENGTH
	jp CopyData
