;@ path: engine/gfx/sprite_oam
;@ def PrepareOAMData()
;@ Build the OAM entries of all visible map sprites in wShadowOAM from wSpriteStateData1/2: each sprite's
;@ picture slot, facing and walking frame select a list of tiles with offsets, placed at its screen position.
;@ The rest of wShadowOAM is moved off screen, except the last four entries while jumping a ledge or fishing
;@ (they hold the shadow or the rod). With wUpdateSpritesEnabled 0, hide all sprites once and mark them hidden.
;@ test: wUpdateSpritesEnabled = rand(0, 2)
PrepareOAMData::
; Determine OAM data for currently visible
; sprites and write it to wShadowOAM.

;> if wUpdateSpritesEnabled != 1:
	ld a, [wUpdateSpritesEnabled]
	dec a
	jr z, .updateEnabled

;>     if wUpdateSpritesEnabled != 0:
;>         return
	cp -1
	ret nz
;>     wUpdateSpritesEnabled = 0xFF              # hide them only once
	ld [wUpdateSpritesEnabled], a
;>     return HideSprites()
	jp HideSprites

.updateEnabled
;> hOAMBufferOffset = 0
	xor a
	ldh [hOAMBufferOffset], a

.spriteLoop
;>@slots for slot in range(0, 0x100, 0x10):
;>     hSpriteOffset2 = slot
	ldh [hSpriteOffset2], a

;>     sprite = addr(wSpriteStateData1) + slot
	ld d, HIGH(wSpriteStateData1)
	ldh a, [hSpriteOffset2]
	ld e, a
;>     if mem[sprite] == 0:                      # no picture: an empty slot
;>         continue
	ld a, [de] ; [x#SPRITESTATEDATA1_PICTUREID]
	and a
	jp z, .nextSprite

;>     image = mem[sprite + 2]
	inc e
	inc e
	ld a, [de] ; [x#SPRITESTATEDATA1_IMAGEINDEX]
;>     wSavedSpriteImageIndex = image
	ld [wSavedSpriteImageIndex], a
;>     if image == 0xFF:                         # off screen
	cp $ff ; off-screen (don't draw)
	jr nz, .visible

;>         GetSpriteScreenXY(sprite + 2)
	call GetSpriteScreenXY
;>         continue
	jr .nextSprite

.visible
;>     if image >= 0xA0:                         # looks the same in every direction
	cp $a0 ; is the sprite unchanging like an item ball or boulder?
	jr c, .usefacing

; unchanging
;>         entry = (image & 0xF) + 0x10          # the table's second half
	and $f
	add $10 ; skip to the second half of the table which doesn't account for facing direction
	jr .next

.usefacing
;>     else:
;>         entry = image & 0xF                   # facing and walking frame
	and $f

.next
	ld l, a

; get sprite priority
;>     grass = addr(wSpriteStateData2) + slot + 7
	push de
	inc d
	ld a, e
	add $5
	ld e, a
;>     hSpritePriority = mem[grass] & 0x80       # behind grass
	ld a, [de] ; [x#SPRITESTATEDATA2_GRASSPRIORITY]
	and $80
	ldh [hSpritePriority], a ; temp store sprite priority
	pop de

; read the entry from the table
;>     entry_at = SpriteFacingAndAnimationTable + 4 * entry
	ld h, 0
	ld bc, SpriteFacingAndAnimationTable
	add hl, hl
	add hl, hl
	add hl, bc
;>     tiles = mem16[entry_at]                   # tile numbers
	ld a, [hli]
	ld c, a
	ld a, [hli]
	ld b, a
;>     offsets = mem16[entry_at + 2]             # Y, X offsets and flags
	ld a, [hli]
	ld h, [hl]
	ld l, a

;>     GetSpriteScreenXY(sprite + 2)
	call GetSpriteScreenXY

;>     oam = hOAMBufferOffset
;>     oam_page = addr(wShadowOAM) & 0xFF00
	ldh a, [hOAMBufferOffset]
	ld e, a
	ld d, HIGH(wShadowOAM)

;>     while True:
.tileLoop
;>         mem[oam_page | oam] = u8(hSpriteScreenY + 0x10 + mem[offsets])
	ldh a, [hSpriteScreenY]   ; temp for sprite Y position
	add $10                  ; Y=16 is top of screen (Y=0 is invisible)
	add [hl]                 ; add Y offset from table
	ld [de], a               ; write new sprite OAM Y position
;>         offsets += 1
	inc hl
;>         mem[oam_page | u8(oam + 1)] = u8(hSpriteScreenX + 8 + mem[offsets])
	ldh a, [hSpriteScreenX]   ; temp for sprite X position
	add $8                   ; X=8 is left of screen (X=0 is invisible)
	add [hl]                 ; add X offset from table
	inc e
	ld [de], a               ; write new sprite OAM X position
	inc e
;>         tile = mem[tiles]
	ld a, [bc]               ; read pattern number offset (accommodates orientation (offset 0,4 or 8) and animation (offset 0 or $80))
;>         tiles += 1
	inc bc
	push bc
	ld b, a

;>         picture = wSavedSpriteImageIndex >> 4
	ld a, [wSavedSpriteImageIndex]
	swap a                   ; high nybble determines sprite used (0 is always player sprite, next are some npcs)
	and $f

	; Sprites $a and $b have one face (and therefore 4 tiles instead of 12).
	; As a result, sprite $b's tile offset is less than normal.
;>         if picture == 0xB:                    # follows slot $A, which has only 4 tiles
	cp $b
	jr nz, .notFourTileSprite
;>             first_tile = 0xA * 12 + 4
	ld a, $a * 12 + 4
	jr .next2

.notFourTileSprite
;>         else:
;>             first_tile = picture * 12         # 12 tiles per picture slot
	; a *= 12
	sla a
	sla a
	ld c, a
	sla a
	add c

.next2
;>         mem[oam_page | u8(oam + 2)] = u8(first_tile + tile)
	add b ; add the tile offset from the table (based on frame and facing direction)
	pop bc
	ld [de], a ; tile id
;>         offsets += 1
;>         flags = mem[offsets]
	inc hl
	inc e
	ld a, [hl]
;>         if flags >> BIT_SPRITE_UNDER_GRASS & 1:
	bit BIT_SPRITE_UNDER_GRASS, a
	jr z, .skipPriority
;>             flags |= hSpritePriority
	ldh a, [hSpritePriority]
	or [hl]
.skipPriority
;>         offsets += 1
	inc hl
;>         mem[oam_page | u8(oam + 3)] = flags
	ld [de], a
;>         oam = u8(oam + 4)
	inc e
;>         if flags >> BIT_END_OF_OAM_DATA & 1:
;>             break
	bit BIT_END_OF_OAM_DATA, a
	jr z, .tileLoop

;>     hOAMBufferOffset = oam
	ld a, e
	ldh [hOAMBufferOffset], a

.nextSprite
;=@slots
	ldh a, [hSpriteOffset2]
	add $10
	cp LOW($100)
	jp nz, .spriteLoop

	; Clear unused OAM.
;> # move the unused entries below the screen
;> at = (addr(wShadowOAM) & 0xFF00) | hOAMBufferOffset
	ldh a, [hOAMBufferOffset]
	ld l, a
	ld h, HIGH(wShadowOAM)
	ld de, OBJ_SIZE
	ld b, SCREEN_HEIGHT_PX + OAM_Y_OFS
;> end = addr(wShadowOAMEnd) & 0xFF
;> if wMovementFlags >> BIT_LEDGE_OR_FISHING & 1:
	ld a, [wMovementFlags]
	bit BIT_LEDGE_OR_FISHING, a
	ld a, LOW(wShadowOAMEnd)
	jr z, .clear

; Don't clear the last 4 entries because they are used for the shadow in the
; jumping down ledge animation and the rod in the fishing animation.
;>     end = addr(wShadowOAMSprite36) & 0xFF     # keep the ledge shadow or the fishing rod
	ld a, LOW(wShadowOAMSprite36)

.clear
;> while at & 0xFF != end:
	cp l
	ret z
;>     mem[at] = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [hl], b
;>     at += OBJ_SIZE
	add hl, de
	jr .clear

;@ path: engine/gfx/sprite_oam
;@ def GetSpriteScreenXY(sprite: de) -> de
;@ For the sprite record whose image index field is at `sprite`: copy its pixel position to hSpriteScreenY and
;@ hSpriteScreenX, and store it rounded to the 16-pixel grid (Y + 4 for the 4-pixel lift) as its adjusted
;@ position.
;@ test: sprite = wSpriteStateData1 + 16 * rand(0, 15) + 2
GetSpriteScreenXY:
;> hSpriteScreenY = mem[sprite + 2]
	inc e
	inc e
	ld a, [de] ; [x#SPRITESTATEDATA1_YPIXELS]
	ldh [hSpriteScreenY], a
;> hSpriteScreenX = mem[sprite + 4]
	inc e
	inc e
	ld a, [de] ; [x#SPRITESTATEDATA1_XPIXELS]
	ldh [hSpriteScreenX], a
;> at = sprite + 8
	ld a, 4
	add e
	ld e, a
;> mem[at] = u8(hSpriteScreenY + 4) & 0xF0      # snapped to the 16-pixel grid
	ldh a, [hSpriteScreenY]
	add 4
	and $f0
	ld [de], a ; [x#SPRITESTATEDATA1_YADJUSTED]
;> mem[at + 1] = hSpriteScreenX & 0xF0
	inc e
	ldh a, [hSpriteScreenX]
	and $f0
	ld [de], a  ; [x#SPRITESTATEDATA1_XADJUSTED]
;> return at + 1
	ret
;@ path: engine/gfx/oam_dma
;@ def WriteDMACodeToHRAM()
;@ Copy the OAM DMA routine to HRAM, where it has to run since the CPU can only reach HRAM during OAM DMA.
WriteDMACodeToHRAM::
; Since no other memory is available during OAM DMA,
; DMARoutine is copied to HRAM and executed there.
;> for i in range(10):                           # DMARoutine.End - DMARoutine
	ld c, LOW(hDMARoutine)
	ld b, DMARoutine.End - DMARoutine
	ld hl, DMARoutine
.copy
;>     mem[addr(hDMARoutine) + i] = mem[DMARoutine + i]
	ld a, [hli]
	ldh [c], a
	inc c
	dec b
	jr nz, .copy
	ret

;@ path: engine/gfx/oam_dma
DMARoutine:
LOAD "OAM DMA", HRAM
hDMARoutine::
	; initiate DMA
	ld a, HIGH(wShadowOAM)
	ldh [rDMA], a
	; wait for DMA to finish
	ld a, $28
.wait
	dec a
	jr nz, .wait
	ret
ENDL
.End:
;@ path: engine/link/print_waiting_text
;@ def PrintWaitingText()
;@ "Waiting...!" in a small box (battle or trade style) while the other Game Boy catches up, shown for 50 frames.
;@ test: skip waits for frames
PrintWaitingText::
;> if wIsInBattle:
	ld hl, (10) * SCREEN_WIDTH + (3) + wTileMap
	ld b, 1
	ld c, 11
	ld a, [wIsInBattle]
	and a
	jr z, .trade
; battle
;>     TextBoxBorder(coord(3, 10), 1, 11)
	call TextBoxBorder
	jr .border_done
.trade
;> else:
;>     CableClub_TextBoxBorder(coord(3, 10), 1, 11)
	call CableClub_TextBoxBorder
.border_done
;> PlaceString(WaitingText, coord(4, 11))
	ld hl, (11) * SCREEN_WIDTH + (4) + wTileMap
	ld de, WaitingText
	call PlaceString
;> DelayFrames(50)
	ld c, 50
	jp DelayFrames

;@ path: engine/link/print_waiting_text
WaitingText:
	db "Waiting...!@"
;@ path: engine/overworld/sprite_collisions
;@ def _UpdateSprites()
;@ Once a frame: update every sprite in use - the player's (VRAM slot 1) and the NPCs'.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC) (IsObjectHidden)
_UpdateSprites::
;>@loop for sprite in range(16):
	ld h, HIGH(wSpriteStateData1)
	inc h
	ld a, SPRITESTATEDATA2_IMAGEBASEOFFSET
.spriteLoop
;>     hCurrentSpriteOffset = 16 * sprite
	ld l, a
	sub SPRITESTATEDATA2_IMAGEBASEOFFSET
	ld c, a
	ldh [hCurrentSpriteOffset], a
;>     slot = wSpriteStateData2[16 * sprite + SPRITESTATEDATA2_IMAGEBASEOFFSET]
	ld a, [hl]
;>     if slot:                                 # in use
	and a
	jr z, .skipSprite   ; tests SPRITESTATEDATA2_IMAGEBASEOFFSET
;>@which         if slot == 1:                        # through .updateCurrentSprite, registers saved
	push hl
	push de
	push bc
	call .updateCurrentSprite
;>@player             UpdatePlayerSprite()
;>         else:
;>@npc             UpdateNonPlayerSprite(slot)
;=@which
	pop bc
	pop de
	pop hl
.skipSprite
;=@loop
	ld a, l
	add $10             ; move to next sprite
	cp SPRITESTATEDATA2_IMAGEBASEOFFSET ; test for overflow (back at beginning)
	jr nz, .spriteLoop
	ret
.updateCurrentSprite
;=@which
	cp $1
;=@npc
	jp nz, UpdateNonPlayerSprite
;=@player
	jp UpdatePlayerSprite

;@ path: engine/overworld/sprite_collisions
;@ def UpdateNonPlayerSprite(slot: a)
;@ An NPC: moved in step with the player if it is the one wNPCMovementScriptSpriteOffset names, otherwise on
;@ its own. Its first image (16 per VRAM slot) goes to hTilePlayerStandingOn for UpdateSpriteImage.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC) (IsObjectHidden)
UpdateNonPlayerSprite:
;> hTilePlayerStandingOn = swap(u8(slot - 1))
	dec a
	swap a
	ldh [hTilePlayerStandingOn], a  ; $10 * sprite#
;> if hCurrentSpriteOffset == wNPCMovementScriptSpriteOffset:     # it walks along with the player
	ld a, [wNPCMovementScriptSpriteOffset] ; some sprite offset?
	ld b, a
	ldh a, [hCurrentSpriteOffset]
	cp b
	jr nz, .unequal
;>     return DoScriptedNPCMovement()
	jp DoScriptedNPCMovement
.unequal
;> return UpdateNPCSprite()
	jp UpdateNPCSprite

; This detects if the current sprite (whose offset is at hCurrentSpriteOffset)
; is going to collide with another sprite by looping over the other sprites.
; The current sprite's offset will be labelled with i (e.g. i#SPRITESTATEDATA1_PICTUREID).
; The loop sprite's offset will labelled with j (e.g. j#SPRITESTATEDATA1_PICTUREID).
;
; Note that the Y coordinate of the sprite (in [k#SPRITESTATEDATA1_YPIXELS])
; is one of the following 9 values when the sprite is aligned with the grid:
; $fc, $0c, $1c, $2c, ..., $7c.
; The reason that 4 is added below to the coordinate is to make it align with a
; multiple of $10 to make comparisons easier.
;@ path: engine/overworld/sprite_collisions
;@ def DetectCollisionBetweenSprites()
;@ Does the current sprite bump into another one? Both positions are rounded to their 16-pixel square,
;@ pushed 7 pixels in the walking direction. A sprite counts as touching when it is within 7 pixels (9 when
;@ moving) on both axes. Each touch adds its direction bits to SPRITESTATEDATA1_COLLISIONDATA (bits 0-1 x,
;@ 2-3 y) and the other sprite's bit to the two bytes after it.
;@ test: hCurrentSpriteOffset = 16 * rand(0, 15)
DetectCollisionBetweenSprites:
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
	nop

	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add LOW(wSpriteStateData1)
	ld l, a

;> if mem[s1 + SPRITESTATEDATA1_PICTUREID] == 0:
;>     return
	ld a, [hl] ; a = [i#SPRITESTATEDATA1_PICTUREID] (0 if slot is unused)
	and a ; is this sprite slot slot used?
	ret z ; return if not used

;> b, c = SetSpriteCollisionValues(mem[s1 + SPRITESTATEDATA1_YSTEPVECTOR])
	ld a, l
	add 3
	ld l, a

	ld a, [hli] ; a = [i#SPRITESTATEDATA1_YSTEPVECTOR] (-1, 0, or 1)
	call SetSpriteCollisionValues

;> hCollidingSpriteTempYValue = u8(mem[s1 + SPRITESTATEDATA1_YPIXELS] + 4 + b) & 0xF0 | c
	ld a, [hli] ; a = [i#SPRITESTATEDATA1_YPIXELS]
	add 4 ; align with multiple of $10

; The effect of the following 3 lines is to
; add 7 to a if moving south or
; subtract 7 from a if moving north.
	add b
	and $f0
	or c

	ldh [hCollidingSpriteTempYValue], a ; y adjusted for direction of movement

;> b, c = SetSpriteCollisionValues(mem[s1 + SPRITESTATEDATA1_XSTEPVECTOR])
	ld a, [hli] ; a = [i#SPRITESTATEDATA1_XSTEPVECTOR] (-1, 0, or 1)
	call SetSpriteCollisionValues
;> hCollidingSpriteTempXValue = u8(mem[s1 + SPRITESTATEDATA1_XPIXELS] + b) & 0xF0 | c
	ld a, [hl] ; a = [i#SPRITESTATEDATA1_XPIXELS]

; The effect of the following 3 lines is to
; add 7 to a if moving east or
; subtract 7 from a if moving west.
	add b
	and $f0
	or c

	ldh [hCollidingSpriteTempXValue], a ; x adjusted for direction of movement

;> mem[s1 + 0x0D] = 0
	ld a, l
	add 7
	ld l, a

	xor a
	ld [hld], a ; zero [i#SPRITESTATEDATA1_0D] XXX what's this for?
;> mem[s1 + SPRITESTATEDATA1_COLLISIONDATA] = 0
	ld [hld], a ; zero [i#SPRITESTATEDATA1_COLLISIONDATA]

;> mem[s1 + SPRITESTATEDATA1_XADJUSTED] = hCollidingSpriteTempXValue
	ldh a, [hCollidingSpriteTempXValue]
	ld [hld], a ; [i#SPRITESTATEDATA1_XADJUSTED]
;> mem[s1 + SPRITESTATEDATA1_YADJUSTED] = hCollidingSpriteTempYValue
	ldh a, [hCollidingSpriteTempYValue]
	ld [hl], a ; [i#SPRITESTATEDATA1_YADJUSTED]

;>@others for j in range(16):
	xor a ; zero the loop counter

.loop
;>     hCollidingSpriteOffset = j
	ldh [hCollidingSpriteOffset], a
;>     other = addr(wSpriteStateData1) + 16 * j
	swap a
	ld e, a
;>     if 16 * j == hCurrentSpriteOffset:        # itself
;>         continue
	ldh a, [hCurrentSpriteOffset]
	cp e ; does the loop sprite match the current sprite?
	jp z, .next ; go to the next sprite if they match

;>     if mem[other + SPRITESTATEDATA1_PICTUREID] == 0:     # an unused slot
;>         continue
	ld d, h
	ld a, [de] ; a = [j#SPRITESTATEDATA1_PICTUREID] (0 if slot is unused)
	and a ; is this sprite slot slot used?
	jp z, .next ; go the next sprite if not used

;>     if mem[other + SPRITESTATEDATA1_IMAGEINDEX] == 0xFF:      # off screen
;>         continue
	inc e
	inc e
	ld a, [de] ; a = [j#SPRITESTATEDATA1_IMAGEINDEX] ($ff means the sprite is offscreen)
	inc a
	jp z, .next ; go the next sprite if offscreen

;>     b, c = SetSpriteCollisionValues(mem[other + SPRITESTATEDATA1_YSTEPVECTOR])
	ldh a, [hCurrentSpriteOffset]
	add 10
	ld l, a

	inc e
	ld a, [de] ; a = [j#SPRITESTATEDATA1_YSTEPVECTOR]
	call SetSpriteCollisionValues

;>     y = u8(mem[other + SPRITESTATEDATA1_YPIXELS] + 4 + b) & 0xF0 | c
	inc e
	ld a, [de] ; a = [j#SPRITESTATEDATA1_YPIXELS]
	add 4 ; align with multiple of $10

; The effect of the following 3 lines is to
; add 7 to a if moving south or
; subtract 7 from a if moving north.
	add b
	and $f0
	or c

;>     distance = abs(y - mem[s1 + SPRITESTATEDATA1_YADJUSTED])
	sub [hl] ; subtract [i#SPRITESTATEDATA1_YADJUSTED] from [j#SPRITESTATEDATA1_YADJUSTED]

; calculate the absolute value of the difference to get the distance
	jr nc, .noCarry1
	cpl
	inc a
.noCarry1
	ldh [hCollidingSpriteTempYValue], a ; store the distance between the two sprites' adjusted Y values
;>     ours_lower = y < mem[s1 + SPRITESTATEDATA1_YADJUSTED]     # our sprite is further down (kept in c)

; Use the carry flag set by the above subtraction to determine which sprite's
; Y coordinate is larger. This information is used later to set
; [i#SPRITESTATEDATA1_COLLISIONDATA].
; The following 5 lines set the lowest 2 bits of c, which are later shifted left by 2.
; If sprite i's Y is larger, set lowest 2 bits of c to 10.
; If sprite j's Y is larger or both are equal, set lowest 2 bits of c to 01.
	push af
	rl c
	pop af
	ccf
	rl c

; If sprite i's delta Y is 0, then b = 7, else b = 9.
;>     reach = 9 if mem[s1 + SPRITESTATEDATA1_YADJUSTED] & 0xF else 7
	ld b, 7
	ld a, [hl] ; a = [i#SPRITESTATEDATA1_YADJUSTED]
	and $f
	jr z, .next1
	ld b, 9

.next1
;>     hCollidingSpriteAdjustedDistance = u8(distance - reach)
	ldh a, [hCollidingSpriteTempYValue] ; a = distance between adjusted Y coordinates
	sub b
	ldh [hCollidingSpriteAdjustedDistance], a
;>     hCollidingSpriteTempYValue = reach
	ld a, b
	ldh [hCollidingSpriteTempYValue], a ; store 7 or 9 depending on sprite i's delta Y
;>     if distance >= reach:
	jr c, .checkXDistance

; If sprite j's delta Y is 0, then b = 7, else b = 9.
;>         reach_other = 7
	ld b, 7
;>         if mem[other + SPRITESTATEDATA1_YSTEPVECTOR]:       # the other sprite moving
;>             reach_other = 9
	dec e
	ld a, [de] ; a = [j#SPRITESTATEDATA1_YSTEPVECTOR]
	inc e
	and a
	jr z, .next2
	ld b, 9

.next2
;>         if hCollidingSpriteAdjustedDistance > reach_other:
;>             continue
	ldh a, [hCollidingSpriteAdjustedDistance]
	sub b ; adjust distance using sprite j's direction
	jr z, .checkXDistance
	jr nc, .next ; go to next sprite if distance is still positive after both adjustments

.checkXDistance
;>     b, c = SetSpriteCollisionValues(mem[other + SPRITESTATEDATA1_XSTEPVECTOR])
	inc e
	inc l
	ld a, [de] ; a = [j#SPRITESTATEDATA1_XSTEPVECTOR]

	push bc

	call SetSpriteCollisionValues
;>     x = u8(mem[other + SPRITESTATEDATA1_XPIXELS] + b) & 0xF0 | c
	inc e
	ld a, [de] ; a = [j#SPRITESTATEDATA1_XPIXELS]

; The effect of the following 3 lines is to
; add 7 to a if moving east or
; subtract 7 from a if moving west.
	add b
	and $f0
	or c

	pop bc

;>     distance = abs(x - mem[s1 + SPRITESTATEDATA1_XADJUSTED])
	sub [hl] ; subtract [i#SPRITESTATEDATA1_XADJUSTED] from [j#SPRITESTATEDATA1_XADJUSTED]

; calculate the absolute value of the difference to get the distance
	jr nc, .noCarry2
	cpl
	inc a
.noCarry2
	ldh [hCollidingSpriteTempXValue], a ; store the distance between the two sprites' adjusted X values
;>     ours_right = x < mem[s1 + SPRITESTATEDATA1_XADJUSTED]     # our sprite is further right (kept in c)

; Use the carry flag set by the above subtraction to determine which sprite's
; X coordinate is larger. This information is used later to set
; [i#SPRITESTATEDATA1_COLLISIONDATA].
; The following 5 lines set the lowest 2 bits of c.
; If sprite i's X is larger, set lowest 2 bits of c to 10.
; If sprite j's X is larger or both are equal, set lowest 2 bits of c to 01.
	push af
	rl c
	pop af
	ccf
	rl c

; If sprite i's delta X is 0, then b = 7, else b = 9.
;>     reach = 9 if mem[s1 + SPRITESTATEDATA1_XADJUSTED] & 0xF else 7
	ld b, 7
	ld a, [hl] ; a = [i#SPRITESTATEDATA1_XADJUSTED]
	and $f
	jr z, .next3
	ld b, 9

.next3
;>     hCollidingSpriteAdjustedDistance = u8(distance - reach)
	ldh a, [hCollidingSpriteTempXValue] ; a = distance between adjusted X coordinates
	sub b
	ldh [hCollidingSpriteAdjustedDistance], a
;>     hCollidingSpriteTempXValue = reach
	ld a, b
	ldh [hCollidingSpriteTempXValue], a ; store 7 or 9 depending on sprite i's delta X
;>     if distance >= reach:
	jr c, .collision

; If sprite j's delta X is 0, then b = 7, else b = 9.
;>         reach_other = 7
	ld b, 7
;>         if mem[other + SPRITESTATEDATA1_XSTEPVECTOR]:       # the other sprite moving
;>             reach_other = 9
	dec e
	ld a, [de] ; a = [j#SPRITESTATEDATA1_XSTEPVECTOR]
	inc e
	and a
	jr z, .next4
	ld b, 9

.next4
;>         if hCollidingSpriteAdjustedDistance > reach_other:
;>             continue
	ldh a, [hCollidingSpriteAdjustedDistance]
	sub b ; adjust distance using sprite j's direction
	jr z, .collision
	jr nc, .next ; go to next sprite if distance is still positive after both adjustments

.collision
;>     if hCollidingSpriteTempYValue < hCollidingSpriteTempXValue:     # only x moving: the x bits
	ldh a, [hCollidingSpriteTempXValue] ; a = 7 or 9 depending on sprite i's delta X
	ld b, a
	ldh a, [hCollidingSpriteTempYValue] ; a = 7 or 9 depending on sprite i's delta Y
	inc l

; If delta X isn't 0 and delta Y is 0, then b = %0011, else b = %1100.
; (note that normally if delta X isn't 0, then delta Y must be 0 and vice versa)
	cp b
	jr c, .next5
;>@xbits         axis = 0b0011
;>     else:
;>         axis = 0b1100
	ld b, %1100
	jr .next6
.next5
;=@xbits
	ld b, %0011

.next6
;>     bits = (2 if ours_lower else 1) << 2 | (2 if ours_right else 1)     # (in c)
;>     mem[s1 + SPRITESTATEDATA1_COLLISIONDATA] = mem[s1 + SPRITESTATEDATA1_COLLISIONDATA] | bits & axis
	ld a, c ; c has 2 bits set (one of bits 0-1 is set for the X axis and one of bits 2-3 for the Y axis)
	and b ; we select either the bit in bits 0-1 or bits 2-3 based on the calculation immediately above
	or [hl] ; or with existing collision direction bits in [i#SPRITESTATEDATA1_COLLISIONDATA]
	ld [hl], a ; store new value
	ld a, c ; useless code because a is overwritten before being used again

; set bit in [i#SPRITESTATEDATA1_0E] or [i#SPRITESTATEDATA1_0F]
; to indicate which sprite the collision occurred with
;=@flag0
	inc l
	inc l
;>@t     t = SpriteCollisionBitTable + 2 * j          # the other sprite's bit
	ldh a, [hCollidingSpriteOffset]
	ld de, SpriteCollisionBitTable
	add a
	add e
	ld e, a
;=@t
	jr nc, .noCarry3
	inc d
.noCarry3
;>@flag0     mem[s1 + 0x0E] = mem[s1 + 0x0E] | mem[t]
	ld a, [de]
	or [hl]
	ld [hli], a
;>     mem[s1 + 0x0F] = mem[s1 + 0x0F] | mem[t + 1]
	inc de
	ld a, [de]
	or [hl]
	ld [hl], a

.next
;=@others
	ldh a, [hCollidingSpriteOffset]
	inc a
	cp $10
	jp nz, .loop
	ret

; takes delta X or delta Y in a
; b = delta X/Y
; c = 0 if delta X/Y is 0
; c = 7 if delta X/Y is 1
; c = 9 if delta X/Y is -1
;@ path: engine/overworld/sprite_collisions
;@ def SetSpriteCollisionValues(value: a) -> (b, c)
;@ For DetectCollisionBetweenSprites: (0, 0) for 0, ($FF, 9) for $FF, otherwise (0, 7).
SetSpriteCollisionValues:
;> if value == 0:
;>     return (0, 0)
	and a
	ld b, 0
	ld c, 0
	jr z, .done
;> if value == 0xFF:
;>     return (0xFF, 9)
	ld c, 9
	cp -1
	jr z, .ok
;> return (0, 7)
	ld c, 7
	ld a, 0
.ok
	ld b, a
.done
	ret

;@ path: engine/overworld/sprite_collisions
SpriteCollisionBitTable:
	db HIGH(1 << $0), LOW(1 << $0)
	db HIGH(1 << $1), LOW(1 << $1)
	db HIGH(1 << $2), LOW(1 << $2)
	db HIGH(1 << $3), LOW(1 << $3)
	db HIGH(1 << $4), LOW(1 << $4)
	db HIGH(1 << $5), LOW(1 << $5)
	db HIGH(1 << $6), LOW(1 << $6)
	db HIGH(1 << $7), LOW(1 << $7)
	db HIGH(1 << $8), LOW(1 << $8)
	db HIGH(1 << $9), LOW(1 << $9)
	db HIGH(1 << $A), LOW(1 << $A)
	db HIGH(1 << $B), LOW(1 << $B)
	db HIGH(1 << $C), LOW(1 << $C)
	db HIGH(1 << $D), LOW(1 << $D)
	db HIGH(1 << $E), LOW(1 << $E)
	db HIGH(1 << $F), LOW(1 << $F)
;@ path: engine/debug/debug_menu
;@ def DebugMenu()
;@ The debug build's start menu: FIGHT starts a test battle, DEBUG a new game with a ready-made party. Only debug
;@ builds assemble it; here it just returns.
DebugMenu:
;> return
	ret

;@ path: engine/debug/debug_menu
;@ def TestBattle()
;@ Debug: a battle between two level 20 Rhydon, started over and over. With the Earth Badge set, the player's
;@ Rhydon always obeys.
;@ test: skip never returns
TestBattle: ; unreferenced except in _DEBUG
.loop
;> while True:
;>     GBPalNormal()
	call GBPalNormal

	; Don't mess around with obedience.
;>     wObtainedBadges = 1 << BIT_EARTHBADGE
	ld a, 1 << BIT_EARTHBADGE
	ld [wObtainedBadges], a

;>     wStatusFlags7 = wStatusFlags7 | 1 << BIT_TEST_BATTLE
	ld hl, wStatusFlags7
	set BIT_TEST_BATTLE, [hl]

	; wNumBagItems and wBagItems are not initialized here,
	; and their garbage values happen to act as if EXP_ALL
	; is in the bag at the end of the test battle.
	; pokeyellow fixes this by initializing them with a
	; list of items.

	; Reset the party.
;>     wPartyCount = 0
	ld hl, wPartyCount
	xor a
	ld [hli], a
;>     wPartySpecies[0] = 0xFF                       # empty party
	dec a
	ld [hl], a

	; Give the player a level 20 Rhydon.
;>     wCurPartySpecies = RHYDON
	ld a, RHYDON
	ld [wCurPartySpecies], a
;>     wCurEnemyLevel = 20
	ld a, 20
	ld [wCurEnemyLevel], a
;>     wMonDataLocation = 0
	xor a
	ld [wMonDataLocation], a
;>     wCurMap = 0
	ld [wCurMap], a
;>     AddPartyMon()
	call AddPartyMon

	; Fight against a level 20 Rhydon.
;>     wCurOpponent = RHYDON
	ld a, RHYDON
	ld [wCurOpponent], a

;>     Predef((InitOpponentPredef - PredefPointers) // 3)        # InitOpponent: the battle
	ld a, (InitOpponentPredef - PredefPointers) / 3
	call Predef

	; When the battle ends, do it all again.
	; There are some graphical quirks in SGB mode.
;>     wUpdateSpritesEnabled = 1
	ld a, 1
	ld [wUpdateSpritesEnabled], a
;>     hAutoBGTransferEnabled = 1
	ldh [hAutoBGTransferEnabled], a
	jr .loop
;@ path: engine/events/pick_up_item
;@ def PickUpItem()
;@ The player talked to an item ball: give its item (the sprite's extra data byte) and hide the ball, or say
;@ the bag is full.
PickUpItem:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing

;> p = addr(wToggleableObjectList)               # entries: sprite, toggleable object index
	ldh a, [hSpriteIndex]
	ld b, a
	ld hl, wToggleableObjectList
.toggleableObjectsListLoop
;>@find while mem[p] != hSpriteIndex:
;>     if mem[p] == 0xFF: return
	ld a, [hli]
	cp $ff
	ret z
;=@find
	cp b
	jr z, .isToggleable
;>     p += 2
	inc hl
;=@find
	jr .toggleableObjectsListLoop

.isToggleable
;> hToggleableObjectIndex = mem[p + 1]
	ld a, [hl]
	ldh [hToggleableObjectIndex], a

;> extra = addr(wMapSpriteExtraData)            # 2 bytes per sprite: the first is the item
	ld hl, wMapSpriteExtraData
;> extra += u8(2 * (hSpriteIndex - 1))
	ldh a, [hSpriteIndex]
	dec a
	add a
	ld d, 0
	ld e, a
	add hl, de
;> item = mem[extra]
	ld a, [hl]
;> if GiveItem(item, 1):
	ld b, a ; item
	ld c, 1 ; quantity
	call GiveItem
	jr nc, .BagFull

;>     wToggleableObjectIndex = hToggleableObjectIndex
	ldh a, [hToggleableObjectIndex]
	ld [wToggleableObjectIndex], a
;>     HideObject()                             # a predef
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;>     wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, 1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>@found     PrintText(FoundItemText)
	ld hl, FoundItemText
	jr .print

.BagFull
;> else:
;>     PrintText(NoMoreRoomForItemText)
	ld hl, NoMoreRoomForItemText
.print
	call PrintText
	ret

;@ path: engine/events/pick_up_item
FoundItemText:
	db TX_FAR
	dw _FoundItemText
	db BANK(_FoundItemText)
	db TX_SOUND_GET_ITEM_1
	db TX_END

;@ path: engine/events/pick_up_item
NoMoreRoomForItemText:
	db TX_FAR
	dw _NoMoreRoomForItemText
	db BANK(_NoMoreRoomForItemText)
	db TX_END
;@ path: engine/overworld/movement
;@ def UpdatePlayerSprite()
;@ Once a frame: the player's sprite. Hidden while a warp's walk animation runs or a text box covers it;
;@ otherwise it faces the way the player moves, steps through its walking frames, and sinks behind the
;@ grass on grass tiles.
;@ test: hCurrentSpriteOffset = 0
UpdatePlayerSprite:
;> counter = wSpritePlayerStateData2WalkAnimationCounter
	ld a, [wSpritePlayerStateData2WalkAnimationCounter]
;> if counter:                                  # a warp's walk animation keeps the sprite hidden
	and a
	jr z, .checkIfTextBoxInFrontOfSprite
;>     if counter != 0xFF:                      # $FF: hidden until something else clears it
	cp $ff
	jr z, .disableSprite
;>         wSpritePlayerStateData2WalkAnimationCounter = counter - 1
	dec a
	ld [wSpritePlayerStateData2WalkAnimationCounter], a
;>     wSpritePlayerStateData1ImageIndex = 0xFF                    # (at .disableSprite)
;>     return
	jr .disableSprite
; check if a text box is in front of the sprite by checking if the lower left
; background tile the sprite is standing on is greater than $5F, which is
; the maximum number for map tiles
.checkIfTextBoxInFrontOfSprite
;> hTilePlayerStandingOn = mem[coord(8, 9)]
	ld a, [(9) * SCREEN_WIDTH + (8) + wTileMap]
	ldh [hTilePlayerStandingOn], a
;> if hTilePlayerStandingOn >= MAP_TILESET_SIZE:     # not a map tile: a text box covers the player
	cp MAP_TILESET_SIZE
	jr c, .lowerLeftTileIsMapTile
.disableSprite
;>     wSpritePlayerStateData1ImageIndex = 0xFF                    # hidden
	ld a, $ff
	ld [wSpritePlayerStateData1ImageIndex], a
;>     return
	ret
.lowerLeftTileIsMapTile
;> DetectCollisionBetweenSprites()
	call DetectCollisionBetweenSprites
	ld h, HIGH(wSpriteStateData1)
;> animate = True
;> if wWalkCounter == 0:                        # not mid-step: face the way the player moves
	ld a, [wWalkCounter]
	and a
	jr nz, .moving
;>     moving = wPlayerMovingDirection
	ld a, [wPlayerMovingDirection]
; check if down
;>     if moving >> PLAYER_DIR_BIT_DOWN & 1:
	bit PLAYER_DIR_BIT_DOWN, a
	jr z, .checkIfUp
;>         facing = SPRITE_FACING_DOWN
	xor a ; SPRITE_FACING_DOWN
	jr .next
.checkIfUp
;>     elif moving >> PLAYER_DIR_BIT_UP & 1:
	bit PLAYER_DIR_BIT_UP, a
	jr z, .checkIfLeft
;>         facing = SPRITE_FACING_UP
	ld a, SPRITE_FACING_UP
	jr .next
.checkIfLeft
;>     elif moving >> PLAYER_DIR_BIT_LEFT & 1:
	bit PLAYER_DIR_BIT_LEFT, a
	jr z, .checkIfRight
;>         facing = SPRITE_FACING_LEFT
	ld a, SPRITE_FACING_LEFT
	jr .next
.checkIfRight
;>     elif moving >> PLAYER_DIR_BIT_RIGHT & 1:
	bit PLAYER_DIR_BIT_RIGHT, a
	jr z, .notMoving
;>         facing = SPRITE_FACING_RIGHT
	ld a, SPRITE_FACING_RIGHT
	jr .next
.notMoving
;>     else:
;>@none         facing = None                        # no direction held
;>@face     if facing is not None:                   # (.next below)
;>@turn         wSpritePlayerStateData1FacingDirection = facing
;>@font         animate = not wFontLoaded >> BIT_FONT_LOADED & 1     # a text box open: stand still
;>     else:
;>@still         animate = False
;>     if not animate:                          # standing: back to the first frame
; zero the animation counters
;>         wSpritePlayerStateData1IntraAnimFrameCounter = 0
	xor a
	ld [wSpritePlayerStateData1IntraAnimFrameCounter], a
;>         wSpritePlayerStateData1AnimFrameCounter = 0
	ld [wSpritePlayerStateData1AnimFrameCounter], a
	jr .calcImageIndex
.next
;=@turn
	ld [wSpritePlayerStateData1FacingDirection], a
;=@font
	ld a, [wFontLoaded]
	bit BIT_FONT_LOADED, a
	jr nz, .notMoving
.moving
;> spinning = animate and wMovementFlags >> BIT_SPINNING & 1    # spinning: the image is set elsewhere
;> if animate and not spinning:                 # a new walking frame every 4 frames
	ld a, [wMovementFlags]
	bit BIT_SPINNING, a
	jr nz, .skipSpriteAnim
;>     ticks = addr(wSpriteStateData1) + u8(hCurrentSpriteOffset + SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER)
	ldh a, [hCurrentSpriteOffset]
	add $7
	ld l, a
;>     mem[ticks] = u8(mem[ticks] + 1)
	ld a, [hl]
	inc a
	ld [hl], a
;>     if mem[ticks] == 4:
	cp 4
	jr nz, .calcImageIndex
;>         mem[ticks] = 0
	xor a
	ld [hl], a
;>         mem[ticks + 1] = (mem[ticks + 1] + 1) & 3     # the next of 4 animation frames
	inc hl
	ld a, [hl]
	inc a
	and $3
	ld [hl], a
.calcImageIndex
;> if not spinning:
;>     wSpritePlayerStateData1ImageIndex = u8(wSpritePlayerStateData1AnimFrameCounter + wSpritePlayerStateData1FacingDirection)
	ld a, [wSpritePlayerStateData1AnimFrameCounter]
	ld b, a
	ld a, [wSpritePlayerStateData1FacingDirection]
	add b
	ld [wSpritePlayerStateData1ImageIndex], a
.skipSpriteAnim
; If the player is standing on a grass tile, make the player's sprite have
; lower priority than the background so that it's partially obscured by the
; grass. Only the lower half of the sprite is permitted to have the priority
; bit set by later logic.
;>@prio priority = OAM_PRIO if wGrassTile == hTilePlayerStandingOn else 0     # behind the grass
	ldh a, [hTilePlayerStandingOn]
	ld c, a
	ld a, [wGrassTile]
	cp c
	ld a, 0
	jr nz, .next2
;=@prio
	ld a, OAM_PRIO
.next2
;> wSpritePlayerStateData2GrassPriority = priority
	ld [wSpritePlayerStateData2GrassPriority], a
	ret

;@ path: engine/overworld/movement
;@ def UnusedReadSpriteDataFunction(field: a) -> l
;@ Unused: the low byte of the address of a field of the current sprite's data.
UnusedReadSpriteDataFunction:
;> offset = hCurrentSpriteOffset
	push bc
	push af
	ldh a, [hCurrentSpriteOffset]
	ld c, a
	pop af
;> return u8(field + offset)
	add c
	ld l, a
	pop bc
	ret

;@ path: engine/overworld/movement
;@ def UpdateNPCSprite()
;@ Once a frame for each NPC: set it up the first time, hide it off screen or behind a text box, turn it to
;@ face the player who talks to it, count down its pause, animate its step, or start the next step - the
;@ next one of a scripted walk, or a random one within its allowed directions.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC) (IsObjectHidden)
UpdateNPCSprite:
;> index = 2 * (hCurrentSpriteOffset // 16 - 1)   # its entry in wMapSpriteData
	ldh a, [hCurrentSpriteOffset]
	swap a
	dec a
	add a
;> # (the low byte of the address wraps without carry: sprite 15 reads $D400)
;> entry = (addr(wMapSpriteData) & 0xFF00) | u8(addr(wMapSpriteData) + index)
	ld hl, wMapSpriteData
	add l
	ld l, a
;> wCurSpriteMovement2 = mem[entry]
	ld a, [hl]        ; read movement byte 2
	ld [wCurSpriteMovement2], a
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	ld l, a
;> if mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS] == 0:           # its very first frame
;>     return InitializeSpriteStatus(s1 + SPRITESTATEDATA1_MOVEMENTSTATUS)
	inc l
	ld a, [hl]        ; x#SPRITESTATEDATA1_MOVEMENTSTATUS
	and a
	jp z, InitializeSpriteStatus
;> if CheckSpriteAvailability(): return
;> tile_id = mem[GetTileSpriteStandsOn() - SCREEN_WIDTH + 1]   # left in c by CheckSpriteAvailability: its top right tile
	call CheckSpriteAvailability
	ret c             ; don't do anything if sprite is invisible
;> status = mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS]
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	ld l, a
	inc l
	ld a, [hl]        ; x#SPRITESTATEDATA1_MOVEMENTSTATUS
;> if status >> BIT_FACE_PLAYER & 1:                           # the player talks to it
;>     return MakeNPCFacePlayer(s1 + SPRITESTATEDATA1_MOVEMENTSTATUS)
	bit BIT_FACE_PLAYER, a
	jp nz, MakeNPCFacePlayer
;> if wFontLoaded >> BIT_FONT_LOADED & 1:                      # a text box is open
;>     return NotYetMoving()
	ld b, a
	ld a, [wFontLoaded]
	bit BIT_FONT_LOADED, a
	jp nz, NotYetMoving
;> if status == 2:                                              # pausing
;>     return UpdateSpriteMovementDelay()
	ld a, b
	cp $2
	jp z, UpdateSpriteMovementDelay  ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] == 2
;> if status == 3:                                              # walking
;>     return UpdateSpriteInWalkingAnimation()
	cp $3
	jp z, UpdateSpriteInWalkingAnimation  ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] == 3
;> if wWalkCounter:                                             # wait for the player to finish a step
;>     return
	ld a, [wWalkCounter]
	and a
	ret nz           ; don't do anything yet if player is currently moving
;> InitializeSpriteScreenPosition()
	call InitializeSpriteScreenPosition
;> tile = s2 + SPRITESTATEDATA2_MOVEMENTBYTE1                  # scripted steps keep this pointer as "tile"
;> byte1 = mem[tile]
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add $6
	ld l, a
	ld a, [hl]       ; x#SPRITESTATEDATA2_MOVEMENTBYTE1
;> if byte1 not in (STAY, WALK):                                # scripted: byte 1 indexes wNPCMovementDirections
	inc a
	jr z, .randomMovement  ; value STAY
	inc a
	jr z, .randomMovement  ; value WALK
; scripted movement
;>     mem[tile] = byte1 + 1
	dec a
	ld [hl], a       ; increment movement byte 1 (movement data index)
;>     wNPCNumScriptedSteps -= 1
	dec a
	push hl
	ld hl, wNPCNumScriptedSteps
	dec [hl]         ; decrement wNPCNumScriptedSteps
	pop hl
;>     step = LoadDEPlusA(wNPCMovementDirections, byte1)
	ld de, wNPCMovementDirections
	call LoadDEPlusA ; a = [wNPCMovementDirections + movement byte 1]
;>     if step == NPC_CHANGE_FACING:
;>         return ChangeFacingDirection(wXCoord, tile_id, tile)
	cp NPC_CHANGE_FACING
	jp z, ChangeFacingDirection
;>     if step == STAY:                                         # the end of the list
	cp STAY
	jr nz, .next
; reached end of wNPCMovementDirections list
;>         mem[tile] = STAY                                     # scripted walk over
	ld [hl], a ; store $ff in movement byte 1, disabling scripted movement
;>         wStatusFlags5 &= ~(1 << BIT_SCRIPTED_NPC_MOVEMENT)
	ld hl, wStatusFlags5
	res BIT_SCRIPTED_NPC_MOVEMENT, [hl]
;>         wSimulatedJoypadStatesIndex = 0
	xor a
	ld [wSimulatedJoypadStatesIndex], a
;>         wUnusedOverrideSimulatedJoypadStatesIndex = 0
	ld [wUnusedOverrideSimulatedJoypadStatesIndex], a
;>         return
	ret
.next
;>     if step == WALK:
	cp WALK
	jr nz, .determineDirection
; current NPC movement data is WALK ($fe). this seems buggy
;>         mem[tile] = 1
	ld [hl], $1     ; set movement byte 1 to $1
;>         step = LoadDEPlusA(wNPCMovementDirections, WALK)
	ld de, wNPCMovementDirections
	call LoadDEPlusA ; a = [wNPCMovementDirections + $fe] (?)
	jr .determineDirection
;> else:                                                        # random movement
;>     tile = GetTileSpriteStandsOn()
.randomMovement
	call GetTileSpriteStandsOn
;>     step = Random()
	call Random
.determineDirection
;> allowed = wCurSpriteMovement2
	ld b, a
	ld a, [wCurSpriteMovement2]
;>@fixed if allowed in (DOWN, UP, LEFT, RIGHT):                # a fixed direction
;>     way = allowed
	cp DOWN
	jr z, .moveDown
	cp UP
	jr z, .moveUp
	cp LEFT
	jr z, .moveLeft
;=@fixed
	cp RIGHT
	jr z, .moveRight
;> elif step < NPC_MOVEMENT_UP:                                # otherwise the step picks one of 4 ways
	ld a, b
	cp NPC_MOVEMENT_UP ; NPC_MOVEMENT_DOWN <= a < NPC_MOVEMENT_UP: down (or left)
	jr nc, .notDown
;>     way = LEFT if allowed == LEFT_RIGHT else DOWN            # bent to fit a two-way walker
	ld a, [wCurSpriteMovement2]
	cp LEFT_RIGHT
	jr z, .moveLeft
.moveDown
;>@up elif step < NPC_MOVEMENT_LEFT:
;>@upway     way = RIGHT if allowed == LEFT_RIGHT else UP
;=@down
	ld de, 2*SCREEN_WIDTH
	add hl, de         ; move tile pointer two rows down
	ld de, ((1) & $ff) << 8 + ((0) & $ff)
	ld bc, ((4) & $ff) << 8 + ((SPRITE_FACING_DOWN) & $ff)
	jr TryWalking
.notDown
;=@up
	cp NPC_MOVEMENT_LEFT ; NPC_MOVEMENT_UP <= a < NPC_MOVEMENT_LEFT: up (or right)
	jr nc, .notUp
;=@upway
	ld a, [wCurSpriteMovement2]
	cp LEFT_RIGHT
	jr z, .moveRight
.moveUp
;>@left elif step < NPC_MOVEMENT_RIGHT:
;>@leftway     way = UP if allowed == UP_DOWN else LEFT
;=@moveup
	ld de, -2*SCREEN_WIDTH
	add hl, de         ; move tile pointer two rows up
	ld de, ((-1) & $ff) << 8 + ((0) & $ff)
	ld bc, ((8) & $ff) << 8 + ((SPRITE_FACING_UP) & $ff)
	jr TryWalking
.notUp
;=@left
	cp NPC_MOVEMENT_RIGHT ; NPC_MOVEMENT_LEFT <= a < NPC_MOVEMENT_RIGHT: left (or up)
	jr nc, .notLeft
;=@leftway
	ld a, [wCurSpriteMovement2]
	cp UP_DOWN
	jr z, .moveUp
.moveLeft
;> else:
;>@rightway     way = DOWN if allowed == UP_DOWN else RIGHT
;=@moveleft
	dec hl
	dec hl             ; move tile pointer two columns left
	ld de, ((0) & $ff) << 8 + ((-1) & $ff)
	ld bc, ((2) & $ff) << 8 + ((SPRITE_FACING_LEFT) & $ff)
	jr TryWalking
.notLeft               ; NPC_MOVEMENT_RIGHT <= a: right (or down)
;=@rightway
	ld a, [wCurSpriteMovement2]
	cp UP_DOWN
	jr z, .moveDown
.moveRight
;> # the tile pointer moves one block (2 tiles) that way
;>@down if way == DOWN: return TryWalking(4, SPRITE_FACING_DOWN, 1, 0, tile + 2 * SCREEN_WIDTH)
;>@moveup if way == UP: return TryWalking(8, SPRITE_FACING_UP, 0xFF, 0, tile - 2 * SCREEN_WIDTH)
;>@moveleft if way == LEFT: return TryWalking(2, SPRITE_FACING_LEFT, 0, 0xFF, tile - 2)
;> return TryWalking(1, SPRITE_FACING_RIGHT, 0, 1, tile + 2)
	inc hl
	inc hl             ; move tile pointer two columns right
	ld de, ((0) & $ff) << 8 + ((1) & $ff)
	ld bc, ((1) & $ff) << 8 + ((SPRITE_FACING_RIGHT) & $ff)
	jr TryWalking

; changes facing direction by zeroing the movement delta and calling TryWalking
;@ path: engine/overworld/movement
;@ def ChangeFacingDirection(direction: b, facing: c, tile: hl)
;@ Turn the current sprite to `facing` without moving: TryWalking with no step.
;@ test: hLoadedROMBank = 1; hCurrentSpriteOffset = 16 * rand(1, 15)
ChangeFacingDirection:
;> return TryWalking(direction, facing, 0, 0, tile)
	ld de, $0
	; fall through

; b: direction (1,2,4 or 8)
; c: new facing direction (0,4,8 or $c)
; d: Y movement delta (-1, 0 or 1)
; e: X movement delta (-1, 0 or 1)
; hl: pointer to tile the sprite would walk onto
; set carry on failure, clears carry on success
;@ path: engine/overworld/movement
;@ def TryWalking(direction: b, facing: c, dy: d, dx: e, tile: hl)
;@ Turn the current sprite to `facing` and, if it may walk onto the tile at `tile` in that direction (1 right,
;@ 2 left, 4 down, 8 up), start a step of (dy, dx): its map position moves now, the pixels over 16 frames.
;@ test: hLoadedROMBank = 1; hCurrentSpriteOffset = 16 * rand(1, 15)
TryWalking:
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
	push hl
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add $9
	ld l, a
;> mem[s1 + SPRITESTATEDATA1_FACINGDIRECTION] = facing
	ld [hl], c          ; x#SPRITESTATEDATA1_FACINGDIRECTION
;> mem[s1 + SPRITESTATEDATA1_YSTEPVECTOR] = dy
	ldh a, [hCurrentSpriteOffset]
	add $3
	ld l, a
	ld [hl], d          ; x#SPRITESTATEDATA1_YSTEPVECTOR
;> mem[s1 + SPRITESTATEDATA1_XSTEPVECTOR] = dx
	inc l
	inc l
	ld [hl], e          ; x#SPRITESTATEDATA1_XSTEPVECTOR
	pop hl
;> if CanWalkOntoTile(direction, mem[tile], dy, dx):           # blocked: it only turns
;>     return
	push de
	ld c, [hl]          ; read tile to walk onto
	call CanWalkOntoTile
	pop de
	ret c               ; cannot walk there (reinitialization of delay values already done)
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add $4
	ld l, a
;> mem[s2 + SPRITESTATEDATA2_MAPY] = u8(mem[s2 + SPRITESTATEDATA2_MAPY] + dy)
	ld a, [hl]          ; x#SPRITESTATEDATA2_MAPY
	add d
	ld [hli], a         ; update Y position
;> mem[s2 + SPRITESTATEDATA2_MAPX] = u8(mem[s2 + SPRITESTATEDATA2_MAPX] + dx)
	ld a, [hl]          ; x#SPRITESTATEDATA2_MAPX
	add e
	ld [hl], a          ; update X position
;> mem[s2 + SPRITESTATEDATA2_WALKANIMATIONCOUNTER] = 16         # 16 frames of walking
	ldh a, [hCurrentSpriteOffset]
	ld l, a
	ld [hl], $10        ; [x#SPRITESTATEDATA2_WALKANIMATIONCOUNTER] = 16
;> mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS] = 3                # walking
	dec h
	inc l
	ld [hl], $3         ; x#SPRITESTATEDATA1_MOVEMENTSTATUS
;> UpdateSpriteImage()
	jp UpdateSpriteImage

; update the walking animation parameters for a sprite that is currently walking
;@ path: engine/overworld/movement
;@ def UpdateSpriteInWalkingAnimation(table: h)
;@ One frame of the current sprite's step: next walking frame every 4 frames, one pixel along the step. After
;@ 16 frames it is ready for the next step - scripted walkers at once, the others after a random pause.
;@ `table` is the high byte of wSpriteStateData1, which the caller has loaded.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15); table = 0xC1
UpdateSpriteInWalkingAnimation:
;> s1 = table << 8 | hCurrentSpriteOffset                      # wSpriteStateData1
;> ticks = s1 + SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER
	ldh a, [hCurrentSpriteOffset]
	add $7
	ld l, a
;> mem[ticks] = u8(mem[ticks] + 1)
	ld a, [hl]                       ; x#SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER
	inc a
	ld [hl], a                       ; [x#SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER]++
;> if mem[ticks] == 4:                                         # every 4 frames
	cp $4
	jr nz, .noNextAnimationFrame
;>     mem[ticks] = 0
	xor a
	ld [hl], a                       ; [x#SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER] = 0
;>     mem[s1 + SPRITESTATEDATA1_ANIMFRAMECOUNTER] = (mem[s1 + SPRITESTATEDATA1_ANIMFRAMECOUNTER] + 1) & 3
	inc l
	ld a, [hl]                       ; x#SPRITESTATEDATA1_ANIMFRAMECOUNTER
	inc a
	and $3
	ld [hl], a                       ; advance to next animation frame every 4 ticks (16 ticks total for one step)
.noNextAnimationFrame
;> step = mem[s1 + SPRITESTATEDATA1_YSTEPVECTOR]
	ldh a, [hCurrentSpriteOffset]
	add $3
	ld l, a
	ld a, [hli]                      ; x#SPRITESTATEDATA1_YSTEPVECTOR
	ld b, a
;> mem[s1 + SPRITESTATEDATA1_YPIXELS] = u8(mem[s1 + SPRITESTATEDATA1_YPIXELS] + step)
	ld a, [hl]                       ; x#SPRITESTATEDATA1_YPIXELS
	add b
	ld [hli], a                      ; update [x#SPRITESTATEDATA1_YPIXELS]
;> step = mem[s1 + SPRITESTATEDATA1_XSTEPVECTOR]
	ld a, [hli]                      ; x#SPRITESTATEDATA1_XSTEPVECTOR
	ld b, a
;> mem[s1 + SPRITESTATEDATA1_XPIXELS] = u8(mem[s1 + SPRITESTATEDATA1_XPIXELS] + step)
	ld a, [hl]                       ; x#SPRITESTATEDATA1_XPIXELS
	add b
	ld [hl], a                       ; update [x#SPRITESTATEDATA1_XPIXELS]
;> s2 = s1 + 0x100                                             # wSpriteStateData2
	ldh a, [hCurrentSpriteOffset]
	ld l, a
	inc h
;> mem[s2 + SPRITESTATEDATA2_WALKANIMATIONCOUNTER] = u8(mem[s2 + SPRITESTATEDATA2_WALKANIMATIONCOUNTER] - 1)
	ld a, [hl]                       ; x#SPRITESTATEDATA2_WALKANIMATIONCOUNTER
	dec a
	ld [hl], a                       ; update walk animation counter
;> if mem[s2 + SPRITESTATEDATA2_WALKANIMATIONCOUNTER]: return   # the step goes on
	ret nz
;> if mem[s2 + SPRITESTATEDATA2_MOVEMENTBYTE1] < WALK:          # scripted: ready at once
	ld a, $6                         ; walking finished, update state
	add l
	ld l, a
	ld a, [hl]                       ; x#SPRITESTATEDATA2_MOVEMENTBYTE1
	cp WALK
	jr nc, .initNextMovementCounter  ; values WALK or STAY
;>     mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS] = 1
	ldh a, [hCurrentSpriteOffset]
	inc a
	ld l, a
	dec h
	ld [hl], $1                      ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] = 1 (movement status ready)
;>     return
	ret
.initNextMovementCounter
;> Random()
	call Random
;> mem[s2 + SPRITESTATEDATA2_MOVEMENTDELAY] = hRandomAdd & 0x7F  # 0 means 256 frames
	ldh a, [hCurrentSpriteOffset]
	add $8
	ld l, a
	ldh a, [hRandomAdd]
	and $7f
	ld [hl], a                       ; x#SPRITESTATEDATA2_MOVEMENTDELAY:
	                                 ; set next movement delay to a random value in [0,$7f]
	                                 ; note that value 0 actually makes the delay $100 (bug?)
;> mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS] = 2                 # pausing
	dec h ; HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	inc a
	ld l, a
	ld [hl], $2                      ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] = 2 (movement status)
;> mem[s1 + SPRITESTATEDATA1_YSTEPVECTOR] = 0
	inc l
	inc l
	xor a
	ld b, [hl]                       ; x#SPRITESTATEDATA1_YSTEPVECTOR
	ld [hli], a                      ; [x#SPRITESTATEDATA1_YSTEPVECTOR] = 0
;> mem[s1 + SPRITESTATEDATA1_XSTEPVECTOR] = 0
	inc l
	ld c, [hl]                       ; x#SPRITESTATEDATA1_XSTEPVECTOR
	ld [hl], a                       ; [x#SPRITESTATEDATA1_XSTEPVECTOR] = 0
	ret

; update [x#SPRITESTATEDATA2_MOVEMENTDELAY] for sprites in the delayed state (x#SPRITESTATEDATA1_MOVEMENTSTATUS)
;@ path: engine/overworld/movement
;@ def UpdateSpriteMovementDelay()
;@ The current sprite pauses between steps: count the pause down (scripted walkers do not pause), then mark it
;@ ready to move. Either way it stands on its first walking frame.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15)
UpdateSpriteMovementDelay:
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add $6
	ld l, a
;> delay = s2 + SPRITESTATEDATA2_MOVEMENTDELAY
;> if mem[s2 + SPRITESTATEDATA2_MOVEMENTBYTE1] < WALK:          # scripted walkers do not pause
	ld a, [hl]              ; x#SPRITESTATEDATA2_MOVEMENTBYTE1
	inc l
	inc l
	cp WALK
	jr nc, .tickMoveCounter ; values WALK or STAY
;>     mem[delay] = 0
	ld [hl], $0
	jr .moving
.tickMoveCounter
;> else:
;>     mem[delay] = u8(mem[delay] - 1)
	dec [hl]                ; x#SPRITESTATEDATA2_MOVEMENTDELAY
;>     if mem[delay]: return NotYetMoving()
	jr nz, NotYetMoving
.moving
;> mem[addr(wSpriteStateData1) + hCurrentSpriteOffset + SPRITESTATEDATA1_MOVEMENTSTATUS] = 1   # ready
	dec h
	ldh a, [hCurrentSpriteOffset]
	inc a
	ld l, a
	ld [hl], $1             ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] = 1 (mark as ready to move)
	; fallthrough
;> return NotYetMoving()
;@ path: engine/overworld/movement
;@ def NotYetMoving()
;@ The current sprite stands still: back to its first walking frame.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15)
NotYetMoving:
;> mem[addr(wSpriteStateData1) + hCurrentSpriteOffset + SPRITESTATEDATA1_ANIMFRAMECOUNTER] = 0
;> UpdateSpriteImage()
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_ANIMFRAMECOUNTER
	ld l, a
	ld [hl], $0             ; [x#SPRITESTATEDATA1_ANIMFRAMECOUNTER] = 0 (walk animation frame)
	jp UpdateSpriteImage

;@ path: engine/overworld/movement
;@ def MakeNPCFacePlayer(status: hl)
;@ The player talked to this NPC: turn it to face the player (unless that is switched off, as while the
;@ S.S. Anne's captain gets his back rubbed). `status` points to its movement status byte.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15); status = 0xC101 + hCurrentSpriteOffset
MakeNPCFacePlayer:
; Make an NPC face the player if the player has spoken to him or her.

; Check if the behaviour of the NPC facing the player when spoken to is
; disabled. This is only done when rubbing the S.S. Anne captain's back.
;> if wStatusFlags3 >> BIT_NO_NPC_FACE_PLAYER & 1:
;>     return NotYetMoving()
	ld a, [wStatusFlags3]
	bit BIT_NO_NPC_FACE_PLAYER, a
	jr nz, NotYetMoving
;> mem[status] &= ~(1 << BIT_FACE_PLAYER)
	res BIT_FACE_PLAYER, [hl]
;> player = wPlayerDirection
	ld a, [wPlayerDirection]
;> if player >> PLAYER_DIR_BIT_UP & 1:
	bit PLAYER_DIR_BIT_UP, a
	jr z, .notFacingDown
;>     facing = SPRITE_FACING_DOWN
	ld c, SPRITE_FACING_DOWN
	jr .facingDirectionDetermined
.notFacingDown
;> elif player >> PLAYER_DIR_BIT_DOWN & 1:
	bit PLAYER_DIR_BIT_DOWN, a
	jr z, .notFacingUp
;>     facing = SPRITE_FACING_UP
	ld c, SPRITE_FACING_UP
	jr .facingDirectionDetermined
.notFacingUp
;> elif player >> PLAYER_DIR_BIT_LEFT & 1:
	bit PLAYER_DIR_BIT_LEFT, a
	jr z, .notFacingRight
;>     facing = SPRITE_FACING_RIGHT
	ld c, SPRITE_FACING_RIGHT
	jr .facingDirectionDetermined
.notFacingRight
;> else:
;>     facing = SPRITE_FACING_LEFT
	ld c, SPRITE_FACING_LEFT
.facingDirectionDetermined
;> mem[addr(wSpriteStateData1) + hCurrentSpriteOffset + SPRITESTATEDATA1_FACINGDIRECTION] = facing
	ldh a, [hCurrentSpriteOffset]
	add $9
	ld l, a
	ld [hl], c              ; [x#SPRITESTATEDATA1_FACINGDIRECTION]: set facing direction
;> return NotYetMoving()
	jr NotYetMoving

;@ path: engine/overworld/movement
;@ def InitializeSpriteStatus(status: hl)
;@ A sprite's first frame: ready to move, not drawn yet, drawn 8 pixels in from its position. `status` points
;@ to its movement status byte.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15); status = 0xC101 + hCurrentSpriteOffset
InitializeSpriteStatus:
;> mem[status] = 1                                              # ready
	ld [hl], $1   ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] = ready
;> mem[status + 1] = 0xFF                                       # image index: not drawn
	inc l
	ld [hl], $ff  ; [x#SPRITESTATEDATA1_IMAGEINDEX] = invisible/off screen
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	inc h ; HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add $2
	ld l, a
;> mem[s2 + SPRITESTATEDATA2_YDISPLACEMENT] = 8
	ld a, $8
	ld [hli], a   ; [x#SPRITESTATEDATA2_YDISPLACEMENT] = 8
;> mem[s2 + SPRITESTATEDATA2_XDISPLACEMENT] = 8
	ld [hl], a    ; [x#SPRITESTATEDATA2_XDISPLACEMENT] = 8
	ret

; calculates the sprite's screen position from its map position and the player position
;@ path: engine/overworld/movement
;@ def InitializeSpriteScreenPosition()
;@ Place the current sprite on screen from its map position relative to the player: 16 pixels a step, and 4
;@ pixels up so it stands on its tiles.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15)
InitializeSpriteScreenPosition:
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA2_MAPY
	ld l, a
;> dy = u8(mem[s2 + SPRITESTATEDATA2_MAPY] - wYCoord)          # steps from the player
	ld a, [wYCoord]
	ld b, a
	ld a, [hl]      ; x#SPRITESTATEDATA2_MAPY
	sub b           ; relative to player position
;> mem[s1 + SPRITESTATEDATA1_YPIXELS] = u8(swap(dy) - 4)        # 16 pixels a step, 4 up
	swap a          ; * 16
	sub $4          ; - 4
	dec h
	ld [hli], a     ; [x#SPRITESTATEDATA1_YPIXELS]
;> dx = u8(mem[s2 + SPRITESTATEDATA2_MAPX] - wXCoord)
	inc h
	ld a, [wXCoord]
	ld b, a
	ld a, [hli]     ; x#SPRITESTATEDATA2_MAPX
	sub b           ; relative to player position
;> mem[s1 + SPRITESTATEDATA1_XPIXELS] = swap(dx)
	swap a          ; * 16
	dec h
	ld [hl], a      ; [x#SPRITESTATEDATA1_XPIXELS]
	ret

; tests if sprite is off screen or otherwise unable to do anything
;@ path: engine/overworld/movement
;@ def CheckSpriteAvailability() -> carry
;@ Should the current sprite be drawn? Not if it is switched off on this map, if a wandering sprite is off
;@ screen, or if a text box covers any of its four tiles - then it is hidden and carry is set. A visible
;@ sprite gets its image (when the player is not mid-step) and sinks behind grass on grass tiles.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC) (IsObjectHidden)
CheckSpriteAvailability:
;> IsObjectHidden()
	ld a, (IsObjectHiddenPredef - PredefPointers) / 3
	call Predef
;> hidden = hIsToggleableObjectOff != 0                        # switched off on this map
	ldh a, [hIsToggleableObjectOff]
	and a
	jp nz, .spriteInvisible
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA2_MOVEMENTBYTE1
	ld l, a
;> if not hidden and mem[s2 + SPRITESTATEDATA2_MOVEMENTBYTE1] >= WALK:   # a wanderer: on screen?
	ld a, [hl]      ; x#SPRITESTATEDATA2_MOVEMENTBYTE1
	cp WALK
	jr c, .skipXVisibilityTest ; movement byte 1 < WALK (i.e. the sprite's movement is scripted)
;>     y = mem[s2 + SPRITESTATEDATA2_MAPY]
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA2_MAPY
	ld l, a
	ld b, [hl]      ; x#SPRITESTATEDATA2_MAPY
;>     if y != wYCoord:
	ld a, [wYCoord]
	cp b
	jr z, .skipYVisibilityTest
;>         hidden = y < wYCoord or y > u8(wYCoord + SCREEN_HEIGHT // 2 - 1)    # above or below the screen
	jr nc, .spriteInvisible ; above screen region
	add SCREEN_HEIGHT / 2 - 1
	cp b
	jr c, .spriteInvisible  ; below screen region
.skipYVisibilityTest
;>     x = mem[s2 + SPRITESTATEDATA2_MAPX]
	inc l
	ld b, [hl]      ; x#SPRITESTATEDATA2_MAPX
;>     if not hidden and x != wXCoord:
	ld a, [wXCoord]
	cp b
	jr z, .skipXVisibilityTest
;>         hidden = x < wXCoord or x > u8(wXCoord + SCREEN_WIDTH // 2 - 1)     # left or right of it
	jr nc, .spriteInvisible ; left of screen region
	add SCREEN_WIDTH / 2 - 1
	cp b
	jr c, .spriteInvisible  ; right of screen region
.skipXVisibilityTest
; make the sprite invisible if a text box is in front of it
; $5F is the maximum number for map tiles
;> if not hidden:                                               # a text box over any of its four tiles?
;>     tile = GetTileSpriteStandsOn()
	call GetTileSpriteStandsOn
	ld d, MAP_TILESET_SIZE
;>     hidden = mem[tile] >= MAP_TILESET_SIZE                   # not a map tile
	ld a, [hli]
	cp d
	jr nc, .spriteInvisible ; standing on tile with ID >=MAP_TILESET_SIZE (bottom left tile)
;>     hidden = hidden or mem[tile + 1] >= MAP_TILESET_SIZE
	ld a, [hld]
	cp d
	jr nc, .spriteInvisible ; standing on tile with ID >=MAP_TILESET_SIZE (bottom right tile)
;>     hidden = hidden or mem[tile - SCREEN_WIDTH] >= MAP_TILESET_SIZE
	ld bc, -SCREEN_WIDTH
	add hl, bc              ; go back one row of tiles
	ld a, [hli]
	cp d
	jr nc, .spriteInvisible ; standing on tile with ID >=MAP_TILESET_SIZE (top left tile)
;>     hidden = hidden or mem[tile - SCREEN_WIDTH + 1] >= MAP_TILESET_SIZE
	ld a, [hl]
	cp d
	jr c, .spriteVisible    ; standing on tile with ID >=MAP_TILESET_SIZE (top right tile)
.spriteInvisible
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
;> if hidden:
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_IMAGEINDEX
	ld l, a
;>     mem[s1 + SPRITESTATEDATA1_IMAGEINDEX] = 0xFF
	ld [hl], $ff       ; x#SPRITESTATEDATA1_IMAGEINDEX
;>     return True
	scf
	jr .done
.spriteVisible
;> if wWalkCounter: return False                                # the player is mid-step: nothing more yet
	ld c, a
	ld a, [wWalkCounter]
	and a
	jr nz, .done           ; if player is currently walking, we're done
;> UpdateSpriteImage()
	call UpdateSpriteImage
;> grass = s2 + SPRITESTATEDATA2_GRASSPRIORITY
	inc h
	ldh a, [hCurrentSpriteOffset]
	add $7
	ld l, a
;>@prio priority = OAM_PRIO if wGrassTile == mem[tile - SCREEN_WIDTH + 1] else 0   # behind the grass
	ld a, [wGrassTile]
	cp c
	ld a, 0
	jr nz, .notInGrass
;=@prio
	ld a, OAM_PRIO
.notInGrass
;> mem[grass] = priority
	ld [hl], a       ; x#SPRITESTATEDATA2_GRASSPRIORITY
;> return False
	and a
.done
	ret

;@ path: engine/overworld/movement
;@ def UpdateSpriteImage()
;@ The current sprite's image: walking frame + facing direction + its first image (left in
;@ hTilePlayerStandingOn by UpdateNonPlayerSprite; 0 for the player).
;@ test: hCurrentSpriteOffset = 16 * rand(0, 15)
UpdateSpriteImage:
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add $8
	ld l, a
;> image = u8(mem[s1 + SPRITESTATEDATA1_ANIMFRAMECOUNTER] + mem[s1 + SPRITESTATEDATA1_FACINGDIRECTION])
	ld a, [hli]        ; x#SPRITESTATEDATA1_ANIMFRAMECOUNTER
	ld b, a
	ld a, [hl]         ; x#SPRITESTATEDATA1_FACINGDIRECTION
	add b
	ld b, a
;> image = u8(image + hTilePlayerStandingOn)
	ldh a, [hTilePlayerStandingOn]
	add b
	ld b, a
;> mem[s1 + SPRITESTATEDATA1_IMAGEINDEX] = image
	ldh a, [hCurrentSpriteOffset]
	add $2
	ld l, a
	ld [hl], b         ; x#SPRITESTATEDATA1_IMAGEINDEX
	ret

; tests if sprite can walk the specified direction
; b: direction (1,2,4 or 8)
; c: ID of tile the sprite would walk onto
; d: Y movement delta (-1, 0 or 1)
; e: X movement delta (-1, 0 or 1)
; set carry on failure, clears carry on success
;@ path: engine/overworld/movement
;@ def CanWalkOntoTile(direction: b, tile: c, dy: d, dx: e) -> carry
;@ May the current sprite step (dy, dx) onto tile `tile` in `direction` (1 right, 2 left, 4 down, 8 up)?
;@ Scripted walkers always may. Others need a walkable tile, must stay on screen, must not bump into another
;@ sprite, and must not wander too far from home (the displacement counters start at 8). If not, carry
;@ is set and the sprite pauses for a random time.
;@ test: hCurrentSpriteOffset = 16 * rand(1, 15); dy = rand(0, 2) - 1; dx = 0 if dy else rand(0, 1) * 2 - 1
CanWalkOntoTile:
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA2_MOVEMENTBYTE1
	ld l, a
;> if mem[s2 + SPRITESTATEDATA2_MOVEMENTBYTE1] < WALK:          # scripted walkers always may
	ld a, [hl]         ; x#SPRITESTATEDATA2_MOVEMENTBYTE1
	cp WALK
	jr nc, .notScripted    ; values WALK or STAY
; always allow walking if the movement is scripted
;>     return False
	and a
	ret
.notScripted
;> walkable = wTilesetCollisionPtr[0] | wTilesetCollisionPtr[1] << 8   # the tileset's walkable tiles
	ld a, [wTilesetCollisionPtr]
	ld l, a
	ld a, [wTilesetCollisionPtr+1]
	ld h, a
.tilePassableLoop
;> while mem[walkable] != 0xFF and mem[walkable] != tile:
;>     walkable += 1
	ld a, [hli]
	cp $ff
	jr z, .impassable
	cp c
	jr nz, .tilePassableLoop
;> byte1 = mem[s2 + SPRITESTATEDATA2_MOVEMENTBYTE1]
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add $6
	ld l, a
	ld a, [hl]         ; x#SPRITESTATEDATA2_MOVEMENTBYTE1
;> blocked = mem[walkable] == 0xFF or byte1 == STAY            # STAY: may only turn
	inc a
	jr z, .impassable  ; if $ff, no movement allowed (however, changing direction is)
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
;> if not blocked:                                              # stay on screen
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_YPIXELS
	ld l, a
;>     blocked = u8(mem[s1 + SPRITESTATEDATA1_YPIXELS] + 4 + dy) >= 0x80
	ld a, [hli]        ; x#SPRITESTATEDATA1_YPIXELS
	add $4             ; align to blocks (Y pos is always 4 pixels off)
	add d              ; add Y delta
	cp $80             ; if value is >$80, the destination is off screen (either $81 or $FF underflow)
	jr nc, .impassable ; don't walk off screen
;>     blocked = blocked or u8(mem[s1 + SPRITESTATEDATA1_XPIXELS] + dx) >= 0x90
	inc l
	ld a, [hl]         ; x#SPRITESTATEDATA1_XPIXELS
	add e              ; add X delta
	cp $90             ; if value is >$90, the destination is off screen (either $91 or $FF underflow)
	jr nc, .impassable ; don't walk off screen
;> if not blocked:                                              # another sprite in the way?
;>     DetectCollisionBetweenSprites()
	push de
	push bc
	call DetectCollisionBetweenSprites
	pop bc
	pop de
;>     collisions = mem[s1 + SPRITESTATEDATA1_COLLISIONDATA]
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add $c
	ld l, a
	ld a, [hl]         ; x#SPRITESTATEDATA1_COLLISIONDATA (directions in which sprite collision would occur)
;>     blocked = collisions & direction != 0
	and b              ; check against chosen direction (1,2,4 or 8)
	jr nz, .impassable ; collision between sprites, don't go there
;> if not blocked:                                              # how far from home (bug: down and right are not limited)
;>     ydisp, xdisp = mem[s2 + SPRITESTATEDATA2_YDISPLACEMENT], mem[s2 + SPRITESTATEDATA2_XDISPLACEMENT]
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA2_YDISPLACEMENT
	ld l, a
	ld a, [hli]        ; x#SPRITESTATEDATA2_YDISPLACEMENT (initialized at $8, keep track of where a sprite did go)
;>     if dy & 0x80:                                            # going up
;>@upchk         blocked = ydisp == 0
;>@updec         ydisp -= 1
;>@yelse     else:
	bit 7, d           ; check if going upwards (d == -1)
	jr nz, .upwards
;>         ydisp = u8(ydisp + dy)
	add d
	; bug: these tests against $5 probably were supposed to prevent
	; sprites from walking out too far, but this line makes sprites get
	; stuck whenever they walked upwards 5 steps
	; on the other hand, the amount a sprite can walk out to the
	; right of bottom is not limited (until the counter overflows)
;>         blocked = ydisp < 5                                  # (bug: stuck after walking up 5 steps)
	cp $5
	jr c, .impassable  ; if [x#SPRITESTATEDATA2_YDISPLACEMENT]+d < 5, don't go
	jr .checkHorizontal
.upwards
;=@updec
	sub $1
;=@upchk
	jr c, .impassable  ; if [x#SPRITESTATEDATA2_YDISPLACEMENT] == 0, don't go
.checkHorizontal
;>     if not blocked:
	ld d, a
	ld a, [hl]         ; x#SPRITESTATEDATA2_XDISPLACEMENT (initialized at $8, keep track of where a sprite did go)
;>         if dx & 0x80:                                        # going left
;>@leftchk             blocked = xdisp == 0
;>@leftdec             xdisp -= 1
;>@xelse         else:
	bit 7, e           ; check if going left (e == -1)
	jr nz, .left
;>             xdisp = u8(xdisp + dx)                           # (the limit check is missing here)
	add e
	cp $5              ; compare, but no conditional jump like in the vertical check above (bug?)
	jr .passable
.left
;=@leftdec
	sub $1
;=@leftchk
	jr c, .impassable  ; if [x#SPRITESTATEDATA2_XDISPLACEMENT] == 0, don't go
.passable
;>     if not blocked:
;>         mem[s2 + SPRITESTATEDATA2_XDISPLACEMENT] = xdisp
	ld [hld], a        ; update x#SPRITESTATEDATA2_XDISPLACEMENT
;>         mem[s2 + SPRITESTATEDATA2_YDISPLACEMENT] = ydisp
	ld [hl], d         ; update x#SPRITESTATEDATA2_YDISPLACEMENT
;>         return False
	and a              ; clear carry (marking success)
	ret
.impassable
;> mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS] = 2                # blocked: pause instead
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	inc a
	ld l, a
	ld [hl], $2        ; [x#SPRITESTATEDATA1_MOVEMENTSTATUS] = 2 (delayed)
;> mem[s1 + SPRITESTATEDATA1_YSTEPVECTOR] = 0
	inc l
	inc l
	xor a
	ld [hli], a        ; [x#SPRITESTATEDATA1_YSTEPVECTOR] = 0
;> mem[s1 + SPRITESTATEDATA1_XSTEPVECTOR] = 0
	inc l
	ld [hl], a         ; [x#SPRITESTATEDATA1_XSTEPVECTOR] = 0
;> Random()
	inc h
	ldh a, [hCurrentSpriteOffset]
	add $8
	ld l, a
	call Random
;> mem[s2 + SPRITESTATEDATA2_MOVEMENTDELAY] = hRandomAdd & 0x7F
	ldh a, [hRandomAdd]
	and $7f
	ld [hl], a         ; x#SPRITESTATEDATA2_MOVEMENTDELAY: set to a random value in [0,$7f] (again with delay $100 if value is 0)
;> return True
	scf                ; set carry (marking failure to walk)
	ret

; calculates the tile pointer pointing to the tile the current sprite stands on
; this is always the lower left tile of the 2x2 tile blocks all sprites are snapped to
; hl: output pointer
;@ path: engine/overworld/movement
;@ def GetTileSpriteStandsOn() -> hl
;@ Address in wTileMap of the bottom left tile of the 2x2 block the current sprite stands on.
;@ test: hCurrentSpriteOffset = 16 * rand(0, 15)
GetTileSpriteStandsOn:
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_YPIXELS
	ld l, a
;> row = (u8(mem[s1 + SPRITESTATEDATA1_YPIXELS] + 4) & 0xF0) >> 3   # its top tile row (y is 4 pixels off)
	ld a, [hli]     ; x#SPRITESTATEDATA1_YPIXELS
	add $4          ; align to 2*2 tile blocks (Y position is always off 4 pixels to the top)
	and $f0         ; in case object is currently moving
	srl a           ; screen Y tile * 4
	ld c, a
	ld b, $0
;> col = mem[s1 + SPRITESTATEDATA1_XPIXELS] >> 3
	inc l
	ld a, [hl]      ; x#SPRITESTATEDATA1_XPIXELS
	srl a
	srl a
	srl a            ; screen X tile
;> col += SCREEN_WIDTH                                         # one row further down: the bottom tile
	add SCREEN_WIDTH ; screen X tile + 20
	ld d, $0
	ld e, a
;> p = coord(0, 0) + SCREEN_WIDTH * row
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	add hl, bc
	add hl, bc
	add hl, bc
	add hl, bc
	add hl, bc
;> return p + col
	add hl, de     ; wTileMap + 20*(screen Y tile + 1) + screen X tile
	ret

; loads [de+a] into a
;@ path: engine/overworld/movement
;@ def LoadDEPlusA(table: de, index: a) -> a
;@ The byte at table + index.
LoadDEPlusA:
;> return mem[table + index]
	add e
	ld e, a
	jr nc, .noCarry
	inc d
.noCarry
	ld a, [de]
	ret

;@ path: engine/overworld/movement
;@ def DoScriptedNPCMovement()
;@ The other way to move an NPC, in step with the player (when an NPC leads the player somewhere): one pixel
;@ pair of the step in wNPCMovementDirections2 per frame, 8 frames a step.
DoScriptedNPCMovement:
; This is an alternative method of scripting an NPC's movement and is only used
; a few times in the game. It is used when the NPC and player must walk together
; in sync, such as when the player is following the NPC somewhere. An NPC can't
; be moved in sync with the player using the other method.
;> if not wStatusFlags5 >> BIT_SCRIPTED_MOVEMENT_STATE & 1:
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_MOVEMENT_STATE, a
	ret z
;> first = not wStatusFlags4 >> BIT_INIT_SCRIPTED_MOVEMENT & 1
	ld hl, wStatusFlags4
	bit BIT_INIT_SCRIPTED_MOVEMENT, [hl]
;> wStatusFlags4 |= 1 << BIT_INIT_SCRIPTED_MOVEMENT
	set BIT_INIT_SCRIPTED_MOVEMENT, [hl]
;> if first:                                   # the first frame sets it up
;>     return InitScriptedNPCMovement()
	jp z, InitScriptedNPCMovement
;> p = addr(wNPCMovementDirections2) + wNPCMovementDirections2Index
	ld hl, wNPCMovementDirections2
	ld a, [wNPCMovementDirections2Index]
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
;> step = mem[p]
	ld a, [hl]
; check if moving up
;> if step == NPC_MOVEMENT_UP:
	cp NPC_MOVEMENT_UP
	jr nz, .checkIfMovingDown
;>     pos, facing, delta = GetSpriteScreenYPointer(), SPRITE_FACING_UP, 0xFE
	call GetSpriteScreenYPointer
	ld c, SPRITE_FACING_UP
	ld a, -2
	jr .move
.checkIfMovingDown
;> elif step == NPC_MOVEMENT_DOWN:
	cp NPC_MOVEMENT_DOWN
	jr nz, .checkIfMovingLeft
;>     pos, facing, delta = GetSpriteScreenYPointer(), SPRITE_FACING_DOWN, 2
	call GetSpriteScreenYPointer
	ld c, SPRITE_FACING_DOWN
	ld a, 2
	jr .move
.checkIfMovingLeft
;> elif step == NPC_MOVEMENT_LEFT:
	cp NPC_MOVEMENT_LEFT
	jr nz, .checkIfMovingRight
;>     pos, facing, delta = GetSpriteScreenXPointer(), SPRITE_FACING_LEFT, 0xFE
	call GetSpriteScreenXPointer
	ld c, SPRITE_FACING_LEFT
	ld a, -2
	jr .move
.checkIfMovingRight
;> elif step == NPC_MOVEMENT_RIGHT:
	cp NPC_MOVEMENT_RIGHT
	jr nz, .noMatch
;>     pos, facing, delta = GetSpriteScreenXPointer(), SPRITE_FACING_RIGHT, 2
	call GetSpriteScreenXPointer
	ld c, SPRITE_FACING_RIGHT
	ld a, 2
	jr .move
.noMatch
;> else:                                       # the end of the list
;>     return
	cp $ff
	ret
.move
;> mem[pos] = u8(mem[pos] + delta)             # two pixels
	ld b, a
	ld a, [hl]
	add b
	ld [hl], a
;> mem[(pos & 0xFF00) | u8(hCurrentSpriteOffset + SPRITESTATEDATA1_FACINGDIRECTION)] = facing
	ldh a, [hCurrentSpriteOffset]
	add $9
	ld l, a
	ld a, c
	ld [hl], a ; facing direction
;> AnimScriptedNPCMovement()
	call AnimScriptedNPCMovement
;> wScriptedNPCWalkCounter -= 1
	ld hl, wScriptedNPCWalkCounter
	dec [hl]
;> if wScriptedNPCWalkCounter: return
	ret nz
;> wScriptedNPCWalkCounter = 8                 # step done: the next one
	ld a, 8
	ld [wScriptedNPCWalkCounter], a
;> wNPCMovementDirections2Index += 1
	ld hl, wNPCMovementDirections2Index
	inc [hl]
	ret

;@ path: engine/overworld/movement
;@ def InitScriptedNPCMovement()
;@ Start a walk in step with the player: first step, 8 frames per step.
InitScriptedNPCMovement:
;> wNPCMovementDirections2Index = 0
	xor a
	ld [wNPCMovementDirections2Index], a
;> wScriptedNPCWalkCounter = 8
	ld a, 8
	ld [wScriptedNPCWalkCounter], a
;> AnimScriptedNPCMovement()
	jp AnimScriptedNPCMovement

;@ path: engine/overworld/movement
;@ def GetSpriteScreenYPointer() -> hl
;@ Address of the current sprite's Y pixel position.
GetSpriteScreenYPointer:
;> return GetSpriteScreenXYPointerCommon(SPRITESTATEDATA1_YPIXELS)
	ld a, SPRITESTATEDATA1_YPIXELS
	ld b, a
	jr GetSpriteScreenXYPointerCommon

;@ path: engine/overworld/movement
;@ def GetSpriteScreenXPointer() -> hl
;@ Address of the current sprite's X pixel position.
GetSpriteScreenXPointer:
;> return GetSpriteScreenXYPointerCommon(SPRITESTATEDATA1_XPIXELS)
	ld a, SPRITESTATEDATA1_XPIXELS
	ld b, a

;@ path: engine/overworld/movement
;@ def GetSpriteScreenXYPointerCommon(field: b) -> hl
;@ Address of a field of the current sprite in wSpriteStateData1.
GetSpriteScreenXYPointerCommon:
;> return addr(wSpriteStateData1) + u8(hCurrentSpriteOffset + field)
	ld hl, wSpriteStateData1
	ldh a, [hCurrentSpriteOffset]
	add l
	add b
	ld l, a
	ret

;@ path: engine/overworld/movement
;@ def AnimScriptedNPCMovement()
;@ The walking image of an NPC moved in step with the player: its first image (16 per VRAM slot) + its facing
;@ direction + the walking frame.
AnimScriptedNPCMovement:
;> vram_slot = mem[addr(wSpriteStateData2) + u8(hCurrentSpriteOffset + SPRITESTATEDATA2_IMAGEBASEOFFSET)]
	ld hl, wSpriteStateData2
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA2_IMAGEBASEOFFSET
	ld l, a
	ld a, [hl] ; VRAM slot
;> first_image = swap(u8(vram_slot - 1))       # 16 images per slot
	dec a
	swap a
	ld b, a
;> facing = mem[addr(wSpriteStateData1) + u8(hCurrentSpriteOffset + SPRITESTATEDATA1_FACINGDIRECTION)]
	ld hl, wSpriteStateData1
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_FACINGDIRECTION
	ld l, a
	ld a, [hl] ; facing direction
;>@facing if facing not in (SPRITE_FACING_DOWN, SPRITE_FACING_UP, SPRITE_FACING_LEFT, SPRITE_FACING_RIGHT):
	cp SPRITE_FACING_DOWN
	jr z, .anim
	cp SPRITE_FACING_UP
	jr z, .anim
	cp SPRITE_FACING_LEFT
	jr z, .anim
;=@facing
	cp SPRITE_FACING_RIGHT
	jr z, .anim
;>     return
	ret
.anim
;> hSpriteVRAMSlotAndFacing = u8(facing + first_image)
	add b
	ld b, a
	ldh [hSpriteVRAMSlotAndFacing], a
;> AdvanceScriptedNPCAnimFrameCounter(addr(wSpriteStateData1) >> 8)
	call AdvanceScriptedNPCAnimFrameCounter
;> p = addr(wSpriteStateData1) + u8(hCurrentSpriteOffset + SPRITESTATEDATA1_IMAGEINDEX)
	ld hl, wSpriteStateData1
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_IMAGEINDEX
	ld l, a
;> mem[p] = u8(hSpriteVRAMSlotAndFacing + hSpriteAnimFrameCounter)
	ldh a, [hSpriteVRAMSlotAndFacing]
	ld b, a
	ldh a, [hSpriteAnimFrameCounter]
	add b
	ld [hl], a
	ret

;@ path: engine/overworld/movement
;@ def AdvanceScriptedNPCAnimFrameCounter(table: h)
;@ Next walking frame every 4 frames (also in hSpriteAnimFrameCounter). `table` is the high byte of
;@ wSpriteStateData1, which the caller has loaded.
;@ test: table = 0xC1
AdvanceScriptedNPCAnimFrameCounter:
;> ticks = table << 8 | u8(hCurrentSpriteOffset + SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER)
	ldh a, [hCurrentSpriteOffset]
	add $7
	ld l, a
;> mem[ticks] = u8(mem[ticks] + 1)
	ld a, [hl] ; intra-animation frame counter
	inc a
	ld [hl], a
;> if mem[ticks] != 4:
;>     return
	cp 4
	ret nz
;> mem[ticks] = 0
	xor a
	ld [hl], a ; reset intra-animation frame counter
;> frame = table << 8 | u8(hCurrentSpriteOffset + SPRITESTATEDATA1_ANIMFRAMECOUNTER)
	inc l
;> mem[frame] = (mem[frame] + 1) & 3
	ld a, [hl] ; animation frame counter
	inc a
	and $3
	ld [hl], a
;> hSpriteAnimFrameCounter = mem[frame]
	ldh [hSpriteAnimFrameCounter], a
	ret
; performs the appropriate action when the player uses the gameboy on the table in the Colosseum or Trade Center
; In the Colosseum, it starts a battle. In the Trade Center, it displays the trade selection screen.
; Before doing either action, it swaps random numbers, trainer names and party data with the other gameboy.
;@ path: engine/link/cable_club
;@ def CableClub_DoBattleOrTrade()
;@ Entering the Cable Club's trade or battle: "PLEASE WAIT!", then the data exchange.
;@ test: skip talks over the link cable
CableClub_DoBattleOrTrade:
;> DelayFrames(80)
	ld c, 80
	call DelayFrames
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;> LoadTrainerInfoTextBoxTiles()
	call LoadTrainerInfoTextBoxTiles
;> CableClub_TextBoxBorder(coord(3, 8), 2, 12)
	ld hl, (8) * SCREEN_WIDTH + (3) + wTileMap
	ld b, 2
	ld c, 12
	call CableClub_TextBoxBorder
;> PlaceString(PleaseWaitString, coord(4, 10))
	ld hl, (10) * SCREEN_WIDTH + (4) + wTileMap
	ld de, PleaseWaitString
	call PlaceString
;> wPlayerNumHits = 0
	ld hl, wPlayerNumHits
	xor a
	ld [hli], a
;> mem[addr(wPlayerNumHits) + 1] = 0x50
	ld [hl], $50
;> CableClub_DoBattleOrTradeAgain()
	; fall through

; This is called after completing a trade.
;@ path: engine/link/cable_club
;@ def CableClub_DoBattleOrTradeAgain()
;@ Swap data with the other Game Boy: random numbers for the battle (the clocking side's list is used by both),
;@ then the player's name and party, then the patch lists. A byte $FE means "no data" on the link, so party
;@ bytes that happen to be $FE are sent as $FF and listed by offset, and changed back on arrival. Then start
;@ the link battle, or the trade menus to Game Corner music.
;@ test: skip talks over the link cable
CableClub_DoBattleOrTradeAgain:
;> # preambles that let the receiver find where the real data starts
;> at = addr(wSerialPlayerDataBlock)
	ld hl, wSerialPlayerDataBlock
	ld a, SERIAL_PREAMBLE_BYTE
	ld b, 6
;> for i in range(6):
;>     mem[at + i] = SERIAL_PREAMBLE_BYTE
.writePlayerDataBlockPreambleLoop
	ld [hli], a
	dec b
	jr nz, .writePlayerDataBlockPreambleLoop
;> at = addr(wSerialRandomNumberListBlock)
	ld hl, wSerialRandomNumberListBlock
	ld a, SERIAL_PREAMBLE_BYTE
	ld b, 7
;> for i in range(7):
;>     mem[at + i] = SERIAL_PREAMBLE_BYTE
.writeRandomNumberListPreambleLoop
	ld [hli], a
	dec b
	jr nz, .writeRandomNumberListPreambleLoop
;> at += 7
;> for i in range(10):
	ld b, 10
.generateRandomNumberListLoop
;>     while True:
;>         r = Random()
	call Random
;>         if r < SERIAL_PREAMBLE_BYTE:          # all below the preamble byte
;>             break
	cp SERIAL_PREAMBLE_BYTE ; all the random numbers have to be less than the preamble byte
	jr nc, .generateRandomNumberListLoop
;>     mem[at + i] = r
	ld [hli], a
	dec b
	jr nz, .generateRandomNumberListLoop
;> patches = addr(wSerialPartyMonsPatchList)
	ld hl, wSerialPartyMonsPatchList
;> for i in range(3):
;>     mem[patches + i] = SERIAL_PREAMBLE_BYTE
	ld a, SERIAL_PREAMBLE_BYTE
	ld [hli], a
	ld [hli], a
	ld [hli], a
;> for i in range(200):
;>     mem[patches + 3 + i] = 0
	ld b, $c8
	xor a
.zeroPlayerDataPatchListLoop
	ld [hli], a
	dec b
	jr nz, .zeroPlayerDataPatchListLoop
;> for at in range(addr(wLinkEnemyTrainerName), addr(wTrainerHeaderPtr)):
	ld hl, wLinkEnemyTrainerName
	ld bc, wTrainerHeaderPtr - wLinkEnemyTrainerName
.zeroEnemyPartyLoop
;>     mem[at] = 0
	xor a
	ld [hli], a
	dec bc
	ld a, b
	or c
	jr nz, .zeroEnemyPartyLoop
;> # patch list: offsets from wPartyMons of bytes equal to SERIAL_NO_DATA_BYTE, in two parts of up to 252
;> at = addr(wPartyMons) - 1
	ld hl, wPartyMons - 1
;> out = patches + 10
	ld de, wSerialPartyMonsPatchList + 10
;> second_part, offset = False, 0
	ld bc, 0
;> while True:
.patchPartyMonsLoop
;>     offset += 1
	inc c
;>     if offset == SERIAL_PREAMBLE_BYTE:        # part 1 is full: end it, count from 1 again
	ld a, c
	cp SERIAL_PREAMBLE_BYTE
	jr z, .startPatchListPart2
;>@end1         mem[out] = SERIAL_PATCH_LIST_PART_TERMINATOR; out += 1
;>@part2         second_part, offset = True, 0
;>@again         continue
;>     if second_part:
	ld a, b
	dec a ; are we in part 2 of the patch list?
	jr nz, .checkPlayerDataByte ; jump if in part 1
; if we're in part 2
;>         if offset == (addr(wPartyMonOT) - (addr(wPartyMons) - 1)) - (SERIAL_PREAMBLE_BYTE - 1):
;>             break                             # up to the OT names
	ld a, c
	cp (wPartyMonOT - (wPartyMons - 1)) - (SERIAL_PREAMBLE_BYTE - 1)
	jr z, .finishedPatchingPlayerData
.checkPlayerDataByte
;>     at += 1
;>     if mem[at] == SERIAL_NO_DATA_BYTE:
	inc hl
	ld a, [hl]
	cp SERIAL_NO_DATA_BYTE
	jr nz, .patchPartyMonsLoop
; if the player data byte matches SERIAL_NO_DATA_BYTE, patch it with $FF and record the offset in the patch list
;>         mem[out] = offset
	ld a, c
	ld [de], a
;>         out += 1
	inc de
;>         mem[at] = 0xFF
	ld [hl], $ff
	jr .patchPartyMonsLoop
.startPatchListPart2
;=@end1
	ld a, SERIAL_PATCH_LIST_PART_TERMINATOR
	ld [de], a ; end of part 1
	inc de
;=@part2
	ld bc, ((1) & $ff) << 8 + ((0) & $ff)
;=@again
	jr .patchPartyMonsLoop
.finishedPatchingPlayerData
;> mem[out] = SERIAL_PATCH_LIST_PART_TERMINATOR
	ld a, SERIAL_PATCH_LIST_PART_TERMINATOR
	ld [de], a ; end of part 2
;> Serial_SyncAndExchangeNybble()
	call Serial_SyncAndExchangeNybble
;> if hSerialConnectionStatus == USING_INTERNAL_CLOCK:
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr nz, .skipSendingTwoZeroBytes
; if using internal clock
; send two zero bytes for syncing purposes?
;>     # two zero bytes to get in step
;>     Delay3()
	call Delay3
;>     hSerialSendData = 0
	xor a
	ldh [hSerialSendData], a
;>     rSC = SC_START | SC_INTERNAL
	ld a, SC_START | SC_INTERNAL
	ldh [rSC], a
;>     DelayFrame()
	call DelayFrame
;>     hSerialSendData = 0
	xor a
	ldh [hSerialSendData], a
;>     rSC = SC_START | SC_INTERNAL
	ld a, SC_START | SC_INTERNAL
	ldh [rSC], a
.skipSendingTwoZeroBytes
;> Delay3()
;> rIE = IE_SERIAL                               # only the serial interrupt while exchanging
	call Delay3
	ld a, IE_SERIAL
	ldh [rIE], a
;> count = SERIAL_RN_PREAMBLE_LENGTH + SERIAL_RNS_LENGTH
;> Serial_ExchangeBytes(addr(wSerialRandomNumberListBlock), addr(wSerialOtherGameboyRandomNumberListBlock), count)
	ld hl, wSerialRandomNumberListBlock
	ld de, wSerialOtherGameboyRandomNumberListBlock
	ld bc, SERIAL_RN_PREAMBLE_LENGTH + SERIAL_RNS_LENGTH
	call Serial_ExchangeBytes
;> mem[addr(wSerialOtherGameboyRandomNumberListBlock) + count] = SERIAL_NO_DATA_BYTE
	ld a, SERIAL_NO_DATA_BYTE
	ld [de], a
;> count = SERIAL_PREAMBLE_LENGTH + NAME_LENGTH + 1 + PARTY_LENGTH + 1 + (PARTYMON_STRUCT_LENGTH + NAME_LENGTH * 2) * PARTY_LENGTH + 3
;> Serial_ExchangeBytes(addr(wSerialPlayerDataBlock), addr(wSerialEnemyDataBlock), count)
	ld hl, wSerialPlayerDataBlock
	ld de, wSerialEnemyDataBlock
	ld bc, SERIAL_PREAMBLE_LENGTH + NAME_LENGTH + 1 + PARTY_LENGTH + 1 + (PARTYMON_STRUCT_LENGTH + NAME_LENGTH * 2) * PARTY_LENGTH + 3
	call Serial_ExchangeBytes
;> mem[addr(wSerialEnemyDataBlock) + count] = SERIAL_NO_DATA_BYTE
	ld a, SERIAL_NO_DATA_BYTE
	ld [de], a
;> Serial_ExchangeBytes(addr(wSerialPartyMonsPatchList), addr(wSerialEnemyMonsPatchList), 200)
	ld hl, wSerialPartyMonsPatchList
	ld de, wSerialEnemyMonsPatchList
	ld bc, 200
	call Serial_ExchangeBytes
;> rIE = IE_SERIAL | IE_TIMER | IE_VBLANK
	ld a, IE_SERIAL | IE_TIMER | IE_VBLANK
	ldh [rIE], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> if hSerialConnectionStatus != USING_INTERNAL_CLOCK:   # the clocking side's list is used by both
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr z, .skipCopyingRandomNumberList ; the list generated by the gameboy clocking the connection is used by both gameboys
;>     at = addr(wSerialOtherGameboyRandomNumberListBlock)
;>     while True:                               # past the preamble and any gaps
	ld hl, wSerialOtherGameboyRandomNumberListBlock
.findStartOfRandomNumberListLoop
;>         value = mem[at]
;>         at += 1
	ld a, [hli]
;>         if value not in (0, SERIAL_PREAMBLE_BYTE, SERIAL_NO_DATA_BYTE):
;>             break
	and a
	jr z, .findStartOfRandomNumberListLoop
	cp SERIAL_PREAMBLE_BYTE
	jr z, .findStartOfRandomNumberListLoop
	cp SERIAL_NO_DATA_BYTE
	jr z, .findStartOfRandomNumberListLoop
;>     at -= 1                                   # back on the first number
	dec hl
;>     out = addr(wLinkBattleRandomNumberList)
	ld de, wLinkBattleRandomNumberList
;>     for _ in range(10):                       # ten numbers, skipping "no data" bytes
;>         while True:
	ld c, 10
.copyRandomNumberListLoop
;>             value = mem[at]
;>             at += 1
	ld a, [hli]
;>             if value != SERIAL_NO_DATA_BYTE:
;>                 break
	cp SERIAL_NO_DATA_BYTE
	jr z, .copyRandomNumberListLoop
;>         mem[out] = value
	ld [de], a
;>         out += 1
	inc de
	dec c
	jr nz, .copyRandomNumberListLoop
.skipCopyingRandomNumberList
;> # the other player's name, then their party up to wTrainerHeaderPtr, without the "no data" bytes
;> at = addr(wSerialEnemyDataBlock) + 3
;> while True:                                   # past the preamble and any gaps
	ld hl, wSerialEnemyDataBlock + 3
.findStartOfEnemyNameLoop
;>     value = mem[at]
;>     at += 1
	ld a, [hli]
;>     if value not in (0, SERIAL_PREAMBLE_BYTE, SERIAL_NO_DATA_BYTE):
;>         break
	and a
	jr z, .findStartOfEnemyNameLoop
	cp SERIAL_PREAMBLE_BYTE
	jr z, .findStartOfEnemyNameLoop
	cp SERIAL_NO_DATA_BYTE
	jr z, .findStartOfEnemyNameLoop
;> at -= 1                                       # back on the first byte of the name
	dec hl
;> for out in range(addr(wLinkEnemyTrainerName), addr(wLinkEnemyTrainerName) + NAME_LENGTH):
	ld de, wLinkEnemyTrainerName
	ld c, NAME_LENGTH
;>     while mem[at] == SERIAL_NO_DATA_BYTE:
;>         at += 1
.copyEnemyNameLoop
	ld a, [hli]
	cp SERIAL_NO_DATA_BYTE
	jr z, .copyEnemyNameLoop
;>     mem[out] = mem[at]
;>     at += 1
	ld [de], a
	inc de
	dec c
	jr nz, .copyEnemyNameLoop
;> for out in range(addr(wEnemyPartyCount), addr(wTrainerHeaderPtr)):
	ld de, wEnemyPartyCount
	ld bc, wTrainerHeaderPtr - wEnemyPartyCount
;>     while mem[at] == SERIAL_NO_DATA_BYTE:
;>         at += 1
.copyEnemyPartyLoop
	ld a, [hli]
	cp SERIAL_NO_DATA_BYTE
	jr z, .copyEnemyPartyLoop
;>     mem[out] = mem[at]
;>     at += 1
	ld [de], a
	inc de
	dec bc
	ld a, b
	or c
	jr nz, .copyEnemyPartyLoop
;> # put the $FE bytes back, first in the player's party
;> patches, base = addr(wSerialPartyMonsPatchList), addr(wPartyMons)
	ld de, wSerialPartyMonsPatchList
	ld hl, wPartyMons
;> parts = 2
;> while parts:
	ld c, 2 ; patch list has 2 parts
.unpatchPartyMonsLoop
;>     offset = mem[patches]
;>     patches += 1
	ld a, [de]
	inc de
;>     if offset in (0, SERIAL_PREAMBLE_BYTE, SERIAL_NO_DATA_BYTE):
;>         continue
	and a
	jr z, .unpatchPartyMonsLoop
	cp SERIAL_PREAMBLE_BYTE
	jr z, .unpatchPartyMonsLoop
	cp SERIAL_NO_DATA_BYTE
	jr z, .unpatchPartyMonsLoop
;>     if offset != SERIAL_PATCH_LIST_PART_TERMINATOR:
	cp SERIAL_PATCH_LIST_PART_TERMINATOR
	jr z, .finishedPartyMonsPatchListPart
;>         at = base + offset - 1
	push hl
	push bc
	ld b, 0
	dec a
	ld c, a
	add hl, bc
;>         mem[at] = SERIAL_NO_DATA_BYTE
	ld a, SERIAL_NO_DATA_BYTE
	ld [hl], a
;>         continue
	pop bc
	pop hl
	jr .unpatchPartyMonsLoop
.finishedPartyMonsPatchListPart
;>     base = addr(wPartyMons) + SERIAL_PREAMBLE_BYTE - 1     # part 2 counts from here
;>     parts -= 1
	ld hl, wPartyMons + (SERIAL_PREAMBLE_BYTE - 1)
	dec c ; is there another part?
	jr nz, .unpatchPartyMonsLoop
;> # then in the other player's party
;> patches, base = addr(wSerialEnemyMonsPatchList), addr(wEnemyMons)
	ld de, wSerialEnemyMonsPatchList
	ld hl, wEnemyMons
;> parts = 2
;> while parts:
	ld c, 2 ; patch list has 2 parts
.unpatchEnemyMonsLoop
;>     offset = mem[patches]
;>     patches += 1
	ld a, [de]
	inc de
;>     if offset in (0, SERIAL_PREAMBLE_BYTE, SERIAL_NO_DATA_BYTE):
;>         continue
	and a
	jr z, .unpatchEnemyMonsLoop
	cp SERIAL_PREAMBLE_BYTE
	jr z, .unpatchEnemyMonsLoop
	cp SERIAL_NO_DATA_BYTE
	jr z, .unpatchEnemyMonsLoop
;>     if offset != SERIAL_PATCH_LIST_PART_TERMINATOR:
	cp SERIAL_PATCH_LIST_PART_TERMINATOR
	jr z, .finishedEnemyMonsPatchListPart
;>         at = base + offset - 1
	push hl
	push bc
	ld b, 0
	dec a
	ld c, a
	add hl, bc
;>         mem[at] = SERIAL_NO_DATA_BYTE
	ld a, SERIAL_NO_DATA_BYTE
	ld [hl], a
;>         continue
	pop bc
	pop hl
	jr .unpatchEnemyMonsLoop
.finishedEnemyMonsPatchListPart
;>     base = addr(wEnemyMons) + SERIAL_PREAMBLE_BYTE - 1
;>     parts -= 1
	ld hl, wEnemyMons + (SERIAL_PREAMBLE_BYTE - 1)
	dec c
	jr nz, .unpatchEnemyMonsLoop
;> wUnusedNamePointer[0] = addr(wEnemyMonOT) & 0xFF
;> wUnusedNamePointer[1] = addr(wEnemyMonOT) >> 8
	ld a, LOW(wEnemyMonOT)
	ld [wUnusedNamePointer], a
	ld a, HIGH(wEnemyMonOT)
	ld [wUnusedNamePointer + 1], a
;> wTradeCenterPointerTableIndex = 0
	xor a
	ld [wTradeCenterPointerTableIndex], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> if hSerialConnectionStatus == USING_INTERNAL_CLOCK:
;>     DelayFrames(66)
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	ld c, 66
	call z, DelayFrames ; delay if using internal clock
;> start_battle = wLinkState == LINK_STATE_START_BATTLE
	ld a, [wLinkState]
	cp LINK_STATE_START_BATTLE
;> wLinkState = LINK_STATE_TRADING
	ld a, LINK_STATE_TRADING
	ld [wLinkState], a
;> if start_battle:
	jr nz, .trading
;>     wLinkState = LINK_STATE_BATTLING
;>     wCurOpponent = OPP_RIVAL1
	ld a, LINK_STATE_BATTLING
	ld [wLinkState], a
	ld a, OPP_RIVAL1
	ld [wCurOpponent], a
;>     ClearScreen()
;>     Delay3()
	call ClearScreen
	call Delay3
;>     wOptions = wOptions & ~(1 << BIT_BATTLE_ANIMATION) & 0xFF
	ld hl, wOptions
	res BIT_BATTLE_ANIMATION, [hl]
;>     Predef((InitOpponentPredef - PredefPointers) // 3)    # InitOpponent: the battle
	ld a, (InitOpponentPredef - PredefPointers) / 3
	call Predef
;>     Predef((HealPartyPredef - PredefPointers) // 3)       # HealParty
	ld a, (HealPartyPredef - PredefPointers) / 3
	call Predef
;>     return ReturnToCableClubRoom()
	jp ReturnToCableClubRoom
.trading
;> PlayMusic(MUSIC_GAME_CORNER, BANK(Music_GameCorner))
	ld c, BANK(Music_GameCorner)
	ld a, MUSIC_GAME_CORNER
	call PlayMusic
;> return CallCurrentTradeCenterFunction()
	jr CallCurrentTradeCenterFunction

;@ path: engine/link/cable_club
PleaseWaitString:
	db "PLEASE WAIT!@"

;@ path: engine/link/cable_club
;@ def CallCurrentTradeCenterFunction()
;@ Go to the trade center step wTradeCenterPointerTableIndex (choosing, trading), or to the title screen at $FF.
;@ test: skip jumps through a table of functions
CallCurrentTradeCenterFunction:
;> index = wTradeCenterPointerTableIndex
	ld hl, TradeCenterPointerTable
	ld b, 0
	ld a, [wTradeCenterPointerTableIndex]
;> if index == 0xFF:
;>     return DisplayTitleScreen()
	cp $ff
	jp z, DisplayTitleScreen
;> entry_at = TradeCenterPointerTable + 2 * index
	add a
	ld c, a
	add hl, bc
;> return call(mem16[entry_at])
	ld a, [hli]
	ld h, [hl]
	ld l, a
	jp hl

;@ path: engine/link/cable_club
;@ def TradeCenter_SelectMon()
;@ The trade center's selection screen: both parties side by side. The player moves between their own list
;@ and the other player's (Right / Left), looks at a Pokémon's stats, or offers one for trade; CANCEL below
;@ ends the session when both players choose it.
;@ test: skip runs the trade menus
TradeCenter_SelectMon:
;> ClearScreen()
	call ClearScreen
;> LoadTrainerInfoTextBoxTiles()
	call LoadTrainerInfoTextBoxTiles
;> TradeCenter_DrawPartyLists()
	call TradeCenter_DrawPartyLists
;> TradeCenter_DrawCancelBox()
	call TradeCenter_DrawCancelBox
;> for i in range(4):
;>     mem[addr(wSerialSyncAndExchangeNybbleReceiveData) + i] = 0
	xor a
	ld hl, wSerialSyncAndExchangeNybbleReceiveData
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wMenuWatchMovingOutOfBounds = 0
	ld [wMenuWatchMovingOutOfBounds], a
;> wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuJoypadPollCount = 0
	ld [wMenuJoypadPollCount], a
;> wSerialExchangeNybbleSendData = 1
	inc a
	ld [wSerialExchangeNybbleSendData], a
;> step = 'own list'                             # start in the player's own list
	jp .playerMonMenu
;>@loop while True:
.enemyMonMenu
;>     if step == 'other list':                  # the cursor goes to the other player's list
;>         wMenuWatchMovingOutOfBounds = 0
	xor a
	ld [wMenuWatchMovingOutOfBounds], a
;>         wWhichTradeMonSelectionMenu = 1
	inc a
	ld [wWhichTradeMonSelectionMenu], a
;>         wMenuWatchedKeys = PAD_DOWN | PAD_LEFT | PAD_A
	ld a, PAD_DOWN | PAD_LEFT | PAD_A
	ld [wMenuWatchedKeys], a
;>         wMaxMenuItem = wEnemyPartyCount
	ld a, [wEnemyPartyCount]
	ld [wMaxMenuItem], a
;>         wTopMenuItemY = 9
	ld a, 9
	ld [wTopMenuItemY], a
;>         wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;>@k1         step = 'keys'
.enemyMonMenu_HandleInput
;>     if step == 'keys' and wWhichTradeMonSelectionMenu == 1:     # a key in the other player's list
;>         hUILayoutFlags |= 1 << BIT_DOUBLE_SPACED_MENU
	ld hl, hUILayoutFlags
	set BIT_DOUBLE_SPACED_MENU, [hl]
;>         keys = HandleMenuInput()
	call HandleMenuInput
;>         hUILayoutFlags &= ~(1 << BIT_DOUBLE_SPACED_MENU) & 0xFF
	ld hl, hUILayoutFlags
	res BIT_DOUBLE_SPACED_MENU, [hl]
;>         if keys == 0:
;>             continue
	and a
	jp z, .getNewInput
;>         if keys >> B_PAD_A & 1:
	bit B_PAD_A, a
	jr z, .enemyMonMenu_ANotPressed
; if A button pressed
;>             # A: the stats of the other player's Pokémon
;>             if wCurrentMenuItem >= wMaxMenuItem:
	ld a, [wMaxMenuItem]
	ld c, a
	ld a, [wCurrentMenuItem]
	cp c
	jr c, .displayEnemyMonStats
;>                 wCurrentMenuItem = wMaxMenuItem - 1
	ld a, [wMaxMenuItem]
	dec a
	ld [wCurrentMenuItem], a
.displayEnemyMonStats
;>             wInitListType = INIT_ENEMYOT_LIST
	ld a, INIT_ENEMYOT_LIST
	ld [wInitListType], a
	; the list isn't used
;>             InitList()                        # the list is not used
	ld hl, InitList
	ld b, BANK(InitList)
	call Bankswitch
;>             TradeCenter_DisplayStats(addr(wEnemyMons))
	ld hl, wEnemyMons
	call TradeCenter_DisplayStats
	jp .getNewInput
.enemyMonMenu_ANotPressed
;>         elif keys >> B_PAD_LEFT & 1:
	bit B_PAD_LEFT, a
	jr z, .enemyMonMenu_LeftNotPressed
; if Left pressed, switch back to the player mon menu
;>             # Left: back to the player's own list
;>             wWhichTradeMonSelectionMenu = 0
	xor a ; player mon menu
	ld [wWhichTradeMonSelectionMenu], a
;>             mem[mem16[addr(wMenuCursorLocation)]] = wTileBehindCursor     # take the cursor away
	ld a, [wMenuCursorLocation]
	ld l, a
	ld a, [wMenuCursorLocation + 1]
	ld h, a
	ld a, [wTileBehindCursor]
	ld [hl], a
;>             if wPartyCount - 1 < wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, [wPartyCount]
	dec a
	cp b
	jr nc, .playerMonMenu
;>                 wCurrentMenuItem = wPartyCount - 1
	ld [wCurrentMenuItem], a
;>             step = 'own list'
	jr .playerMonMenu
.enemyMonMenu_LeftNotPressed
;>         elif keys >> B_PAD_DOWN & 1:
	bit B_PAD_DOWN, a
	jp z, .getNewInput
;>             step = 'cancel'
	jp .selectedCancelMenuItem ; jump if Down pressed
.playerMonMenu
;>     if step == 'own list':                    # the cursor goes to the player's own list
;>         wWhichTradeMonSelectionMenu = 0
	xor a ; player mon menu
	ld [wWhichTradeMonSelectionMenu], a
;>         wMenuWatchMovingOutOfBounds = 0
	ld [wMenuWatchMovingOutOfBounds], a
;>         wMenuWatchedKeys = PAD_DOWN | PAD_RIGHT | PAD_A
	ld a, PAD_DOWN | PAD_RIGHT | PAD_A
	ld [wMenuWatchedKeys], a
;>         wMaxMenuItem = wPartyCount
	ld a, [wPartyCount]
	ld [wMaxMenuItem], a
;>         wTopMenuItemY = 1
;>         wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemY], a
	ld a, 1
	ld [wTopMenuItemX], a
;>         ClearScreenArea(coord(1, 1), 1, 6)
	ld hl, (1) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, ((6) & $ff) << 8 + ((1) & $ff)
	call ClearScreenArea
;>@k2         step = 'keys'
.playerMonMenu_HandleInput
;>     if step == 'keys' and wWhichTradeMonSelectionMenu == 0:     # a key in the player's list
;>         hUILayoutFlags |= 1 << BIT_DOUBLE_SPACED_MENU
	ld hl, hUILayoutFlags
	set BIT_DOUBLE_SPACED_MENU, [hl]
;>         keys = HandleMenuInput()
	call HandleMenuInput
;>         hUILayoutFlags &= ~(1 << BIT_DOUBLE_SPACED_MENU) & 0xFF
	ld hl, hUILayoutFlags
	res BIT_DOUBLE_SPACED_MENU, [hl]
;>         if keys == 0:
;>             continue
	and a ; was anything pressed?
	jr nz, .playerMonMenu_SomethingPressed
	jp .getNewInput
.playerMonMenu_SomethingPressed
;>         if keys >> B_PAD_A & 1:
;>             step = 'chosen'
	bit B_PAD_A, a
	jr z, .playerMonMenu_ANotPressed
	jp .chosePlayerMon ; jump if A button pressed
; unreachable code
;>             if False:                         # never reached: would show the Pokémon's stats
;>                 wInitListType = INIT_PLAYEROT_LIST
	ld a, INIT_PLAYEROT_LIST
	ld [wInitListType], a
	; the list isn't used
;>                 InitList()
	ld hl, InitList
	ld b, BANK(InitList)
	call Bankswitch
;>                 TradeCenter_DisplayStats()
	call TradeCenter_DisplayStats
	jp .getNewInput
.playerMonMenu_ANotPressed
;>         elif keys >> B_PAD_RIGHT & 1:
	bit B_PAD_RIGHT, a
	jr z, .playerMonMenu_RightNotPressed
; if Right pressed, switch to the enemy mon menu
;>             # Right: over to the other player's list
;>             wWhichTradeMonSelectionMenu = 1
	ld a, $1 ; enemy mon menu
	ld [wWhichTradeMonSelectionMenu], a
;>             mem[mem16[addr(wMenuCursorLocation)]] = wTileBehindCursor     # take the cursor away
	ld a, [wMenuCursorLocation]
	ld l, a
	ld a, [wMenuCursorLocation + 1]
	ld h, a
	ld a, [wTileBehindCursor]
	ld [hl], a
;>             if wEnemyPartyCount - 1 < wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, [wEnemyPartyCount]
	dec a
	cp b
	jr nc, .notPastLastEnemyMon
; when switching to the enemy mon menu, if the menu selection would be past the last enemy mon, select the last enemy mon
;>                 wCurrentMenuItem = wEnemyPartyCount - 1
	ld [wCurrentMenuItem], a
.notPastLastEnemyMon
;>             step = 'other list'
	jp .enemyMonMenu
.playerMonMenu_RightNotPressed
;>         elif keys >> B_PAD_DOWN & 1:
	bit B_PAD_DOWN, a
	jr z, .getNewInput
;>             step = 'cancel'
	jp .selectedCancelMenuItem ; jump if Down pressed
.getNewInput
;=@loop
	ld a, [wWhichTradeMonSelectionMenu]
	and a
	jp z, .playerMonMenu_HandleInput
	jp .enemyMonMenu_HandleInput
.chosePlayerMon
;>     if step == 'chosen':                      # STATS or TRADE for the player's Pokémon
;>         SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>         PlaceUnfilledArrowMenuCursor()
	call PlaceUnfilledArrowMenuCursor
;>         choice = wCurrentMenuItem
;>         if choice >= wMaxMenuItem:
	ld a, [wMaxMenuItem]
	ld c, a
	ld a, [wCurrentMenuItem]
	cp c
	jr c, .displayStatsTradeMenu
;>             choice = wMaxMenuItem - 1
	ld a, [wMaxMenuItem]
	dec a
.displayStatsTradeMenu
;>         # (kept on the stack meanwhile)
	push af
;>         CableClub_TextBoxBorder(coord(0, 14), 2, 18)
	ld hl, (14) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 2
	ld c, 18
	call CableClub_TextBoxBorder
;>         PlaceString(TradeCenter_SelectMon.statsTrade, coord(2, 16))    # "STATS     TRADE"
	ld hl, (16) * SCREEN_WIDTH + (2) + wTileMap
	ld de, .statsTrade
	call PlaceString
;>         wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;>         wLastMenuItem = 0
	ld [wLastMenuItem], a
;>         wMenuJoypadPollCount = 0
	ld [wMenuJoypadPollCount], a
;>         wMaxMenuItem = 0
	ld [wMaxMenuItem], a
;>         wTopMenuItemY = 16
	ld a, 16
	ld [wTopMenuItemY], a
;>@ontrade         on_trade = False
;>@loop2         while True:
.selectStatsMenuItem
;>             if not on_trade:                  # the cursor on STATS
;>                 mem[coord(11, 16)] = charmap(' ')[0]
	ld a, ' '
	ld [(16) * SCREEN_WIDTH + (11) + wTileMap], a
;>                 wMenuWatchedKeys = PAD_RIGHT | PAD_B | PAD_A
	ld a, PAD_RIGHT | PAD_B | PAD_A
	ld [wMenuWatchedKeys], a
;>                 wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;>                 keys = HandleMenuInput()
	call HandleMenuInput
;>                 if keys >> B_PAD_RIGHT & 1:
;>@toTrade                     on_trade = True
;>@toTrade2                     continue
	bit B_PAD_RIGHT, a
	jr nz, .selectTradeMenuItem
;=@isback
	bit B_PAD_B, a
	jr z, .displayPlayerMonStats
.cancelPlayerMonChoice
;=@cur
	pop af
	ld [wCurrentMenuItem], a
;=@back
	call LoadScreenTilesFromBuffer1
	jp .playerMonMenu
.selectTradeMenuItem
;>@trade             else:                             # the cursor on TRADE
;>                 mem[coord(1, 16)] = charmap(' ')[0]
	ld a, ' '
	ld [(16) * SCREEN_WIDTH + (1) + wTileMap], a
;>                 wMenuWatchedKeys = PAD_LEFT | PAD_B | PAD_A
	ld a, PAD_LEFT | PAD_B | PAD_A
	ld [wMenuWatchedKeys], a
;>                 wTopMenuItemX = 11
	ld a, 11
	ld [wTopMenuItemX], a
;>                 keys = HandleMenuInput()
	call HandleMenuInput
;>                 if keys >> B_PAD_LEFT & 1:
;>@toStats                     on_trade = False
;>@toStats2                     continue
	bit B_PAD_LEFT, a
	jr nz, .selectStatsMenuItem
;>             break
;=@isback
	bit B_PAD_B, a
	jr nz, .cancelPlayerMonChoice
;=@trade
	jr .choseTrade
.displayPlayerMonStats
;>@cur         wCurrentMenuItem = choice
;>@isback         if keys >> B_PAD_B & 1:              # B: back to the list
;>@back             LoadScreenTilesFromBuffer1(); step = 'own list'
;>         elif not on_trade:                    # A on STATS
;=@cur
	pop af
	ld [wCurrentMenuItem], a
;>             wInitListType = INIT_PLAYEROT_LIST
	ld a, INIT_PLAYEROT_LIST
	ld [wInitListType], a
	; the list isn't used
;>             InitList()                        # the list is not used
	ld hl, InitList
	ld b, BANK(InitList)
	call Bankswitch
;>             TradeCenter_DisplayStats()
	call TradeCenter_DisplayStats
;>             LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>             step = 'own list'
	jp .playerMonMenu
.choseTrade
;>         else:                                 # A on TRADE: offer it, learn the other player's offer
;>             PlaceUnfilledArrowMenuCursor()
	call PlaceUnfilledArrowMenuCursor
;=@cur
	pop af
	ld [wCurrentMenuItem], a
;>             wTradingWhichPlayerMon = choice
	ld [wTradingWhichPlayerMon], a
;>             wSerialExchangeNybbleSendData = choice
	ld [wSerialExchangeNybbleSendData], a
;>             Serial_PrintWaitingTextAndSyncAndExchangeNybble()
	call Serial_PrintWaitingTextAndSyncAndExchangeNybble
;>             if wSerialSyncAndExchangeNybbleReceiveData == 0xF:     # they cancelled: start over
;>                 return CallCurrentTradeCenterFunction()
	ld a, [wSerialSyncAndExchangeNybbleReceiveData]
	cp $f
	jp z, CallCurrentTradeCenterFunction ; go back to the beginning of the trade selection menu if the other person cancelled
;>             wTradingWhichEnemyMon = wSerialSyncAndExchangeNybbleReceiveData
	ld [wTradingWhichEnemyMon], a
;>             TradeCenter_PlaceSelectedEnemyMonMenuCursor()
	call TradeCenter_PlaceSelectedEnemyMonMenuCursor
;>             wTradeCenterPointerTableIndex = 1     # TradeCenter_Trade
	ld a, $1 ; TradeCenter_Trade
	ld [wTradeCenterPointerTableIndex], a
;>             return CallCurrentTradeCenterFunction()
	jp CallCurrentTradeCenterFunction
.statsTrade
	db "STATS     TRADE@"
.selectedCancelMenuItem
;>     if step == 'cancel':
;>         if wCurrentMenuItem != wMaxMenuItem:  # Down reaches CANCEL only from the last row
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, [wMaxMenuItem]
	cp b
;>             step = 'keys'
;>             continue
	jp nz, .getNewInput
;>         mem[mem16[addr(wMenuCursorLocation)]] = charmap(' ')[0]      # take the cursor away
	ld a, [wMenuCursorLocation]
	ld l, a
	ld a, [wMenuCursorLocation + 1]
	ld h, a
	ld a, ' '
	ld [hl], a
;>         while True:
.cancelMenuItem_Loop
;>             mem[coord(1, 16)] = 0xED          # ▶
	ld a, '▶' ; filled arrow cursor
	ld [(16) * SCREEN_WIDTH + (1) + wTileMap], a
;>             while True:
.cancelMenuItem_JoypadLoop
;>                 JoypadLowSensitivity()
	call JoypadLowSensitivity
;>                 keys = hJoy5
	ldh a, [hJoy5]
;>                 if keys >> B_PAD_A & 1 or keys >> B_PAD_UP & 1:
;>                     break
	and a ; pressed anything?
	jr z, .cancelMenuItem_JoypadLoop
	bit B_PAD_A, a
	jr nz, .cancelMenuItem_APressed
	bit B_PAD_UP, a
	jr z, .cancelMenuItem_JoypadLoop
; if Up pressed
;>             if not keys >> B_PAD_A & 1:       # Up: back to the last Pokémon of the player's list
;>                 mem[coord(1, 16)] = charmap(' ')[0]
	ld a, ' '
	ld [(16) * SCREEN_WIDTH + (1) + wTileMap], a
;>                 wCurrentMenuItem = wPartyCount - 1
	ld a, [wPartyCount]
	dec a
	ld [wCurrentMenuItem], a
;>                 step = 'own list'
;>                 break
	jp .playerMonMenu
.cancelMenuItem_APressed
;>             # A: CANCEL chosen; tell the other player
;>             mem[coord(1, 16)] = 0xEC          # ▷
	ld a, '▷' ; unfilled arrow cursor
	ld [(16) * SCREEN_WIDTH + (1) + wTileMap], a
;>             wSerialExchangeNybbleSendData = 0xF
	ld a, $f
	ld [wSerialExchangeNybbleSendData], a
;>             Serial_PrintWaitingTextAndSyncAndExchangeNybble()
	call Serial_PrintWaitingTextAndSyncAndExchangeNybble
;>             if wSerialSyncAndExchangeNybbleReceiveData == 0xF:     # both cancelled
;>                 return ReturnToCableClubRoom()
	ld a, [wSerialSyncAndExchangeNybbleReceiveData]
	cp $f ; did the other person choose Cancel too?
	jr nz, .cancelMenuItem_Loop
	; fall through

;@ path: engine/link/cable_club
;@ def ReturnToCableClubRoom()
;@ After a link battle or the end of trading: reload the Cable Club map with the player at the table again.
;@ test: skip reloads the map
ReturnToCableClubRoom:
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> font = wFontLoaded
	ld hl, wFontLoaded
	ld a, [hl]
	push af
	push hl
;> wFontLoaded = wFontLoaded & ~(1 << BIT_FONT_LOADED) & 0xFF
	res BIT_FONT_LOADED, [hl]
;> wStatusFlags3 = 0
	xor a
	ld [wStatusFlags3], a ; clears BIT_INIT_TRADE_CENTER_FACING
;> wDestinationWarpID = 0xFF
	dec a
	ld [wDestinationWarpID], a
;> LoadMapData()
	call LoadMapData
;> ClearVariablesOnEnterMap()
	ld b, BANK(ClearVariablesOnEnterMap)
	ld hl, ClearVariablesOnEnterMap
	call Bankswitch
;> wFontLoaded = font
	pop hl
	pop af
	ld [hl], a
;> GBFadeInFromWhite()
	call GBFadeInFromWhite
	ret

;@ path: engine/link/cable_club
;@ def TradeCenter_DrawCancelBox()
;@ The CANCEL box below the two party lists.
;@ test: skip draws with CableClub_TextBoxBorder
TradeCenter_DrawCancelBox:
;> FillMemory(coord(11, 15), 2 * SCREEN_WIDTH + 9, 0x7E)
	ld hl, (15) * SCREEN_WIDTH + (11) + wTileMap
	ld a, $7e
	ld bc, 2 * SCREEN_WIDTH + 9
	call FillMemory
;> CableClub_TextBoxBorder(coord(0, 15), 1, 9)
	ld hl, (15) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 1
	ld c, 9
	call CableClub_TextBoxBorder
;> return PlaceString(CancelTextString, coord(2, 16))
	ld hl, (16) * SCREEN_WIDTH + (2) + wTileMap
	ld de, CancelTextString
	jp PlaceString

;@ path: engine/link/cable_club
CancelTextString:
	db "CANCEL@"

;@ path: engine/link/cable_club
;@ def TradeCenter_PlaceSelectedEnemyMonMenuCursor()
;@ Mark the Pokémon the other player offered (wSerialSyncAndExchangeNybbleReceiveData) with an empty arrow.
;@ test: wSerialSyncAndExchangeNybbleReceiveData = rand(0, 5)
TradeCenter_PlaceSelectedEnemyMonMenuCursor:
;> mem[coord(1, 9) + SCREEN_WIDTH * wSerialSyncAndExchangeNybbleReceiveData] = 0xEC     # ▷
	ld a, [wSerialSyncAndExchangeNybbleReceiveData]
	ld hl, (9) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, SCREEN_WIDTH
	call AddNTimes
	ld [hl], '▷' ; cursor
	ret

;@ path: engine/link/cable_club
;@ def TradeCenter_DisplayStats()
;@ The two summary pages of the Pokémon under the cursor, then the trade screen again.
;@ test: skip draws the summary
TradeCenter_DisplayStats:
;> wWhichPokemon = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wWhichPokemon], a
;> StatusScreen()
	ld a, (StatusScreenPredef - PredefPointers) / 3
	call Predef
;> StatusScreen2()
	ld a, (StatusScreen2Predef - PredefPointers) / 3
	call Predef
;> GBPalNormal()
	call GBPalNormal
;> LoadTrainerInfoTextBoxTiles()
	call LoadTrainerInfoTextBoxTiles
;> TradeCenter_DrawPartyLists()
	call TradeCenter_DrawPartyLists
;> TradeCenter_DrawCancelBox()
	jp TradeCenter_DrawCancelBox

;@ path: engine/link/cable_club
;@ def TradeCenter_DrawPartyLists()
;@ The two boxes of the trade screen: the player's name and party on top, the other player's below.
;@ test: skip prints names through GetMonName
TradeCenter_DrawPartyLists:
;> CableClub_TextBoxBorder(coord(0, 0), 6, 18)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 6
	ld c, 18
	call CableClub_TextBoxBorder
;> CableClub_TextBoxBorder(coord(0, 8), 6, 18)
	ld hl, (8) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 6
	ld c, 18
	call CableClub_TextBoxBorder
;> PlaceString(addr(wPlayerName), coord(5, 0))
	ld hl, (0) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PlaceString(addr(wLinkEnemyTrainerName), coord(5, 8))
	ld hl, (8) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wLinkEnemyTrainerName
	call PlaceString
;> TradeCenter_PrintPartyListNames(coord(2, 1), addr(wPartySpecies))
	ld hl, (1) * SCREEN_WIDTH + (2) + wTileMap
	ld de, wPartySpecies
	call TradeCenter_PrintPartyListNames
;> TradeCenter_PrintPartyListNames(coord(2, 9), addr(wEnemyPartySpecies))
	ld hl, (9) * SCREEN_WIDTH + (2) + wTileMap
	ld de, wEnemyPartySpecies
	; fall through

;@ path: engine/link/cable_club
;@ def TradeCenter_PrintPartyListNames(dest: hl, species: de)
;@ The names of the species in the $FF-terminated list at `species`, one per row from dest.
;@ test: skip prints names through GetMonName
TradeCenter_PrintPartyListNames:
;> i = 0
	ld c, $0
.loop
;> while mem[species] != 0xFF:
	ld a, [de]
	cp $ff
	ret z
;>     wNamedObjectIndex = mem[species]
	ld [wNamedObjectIndex], a
	push bc
	push hl
	push de
	push hl
;>     hPastLeadingZeros = i
	ld a, c
	ldh [hPastLeadingZeros], a
;>     PlaceString(GetMonName(), dest)
	call GetMonName
	pop hl
	call PlaceString
;>     species += 1
	pop de
	inc de
;>     dest += SCREEN_WIDTH
	pop hl
	ld bc, SCREEN_WIDTH
	add hl, bc
;>     i += 1
	pop bc
	inc c
	jr .loop

;@ path: engine/link/cable_club
;@ def TradeCenter_Trade()
;@ "Trade <mon> for <mon>?" TRADE / CANCEL, wait for the other player's answer, and if both agree swap the
;@ Pokémon (with original trainer and ID kept for the trade animation), play the animation, let the new one
;@ evolve if it does by trade, and save. Then back to the selection screen.
;@ test: skip talks over the link cable
TradeCenter_Trade:
;> DelayFrames(100)
	ld c, 100
	call DelayFrames
;> mem[addr(wSerialExchangeNybbleSendData) + 1] = 0     # not needed
;> wSerialExchangeNybbleReceiveData = 0
	xor a
	ld [wSerialExchangeNybbleSendData + 1], a ; unnecessary
	ld [wSerialExchangeNybbleReceiveData], a
;> wMenuWatchMovingOutOfBounds = 0
;> wMenuJoypadPollCount = 0
	ld [wMenuWatchMovingOutOfBounds], a
	ld [wMenuJoypadPollCount], a
;> CableClub_TextBoxBorder(coord(0, 12), 4, 18)
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 18
	call CableClub_TextBoxBorder
;> species = wPartySpecies[wTradingWhichPlayerMon]
	ld a, [wTradingWhichPlayerMon]
	ld hl, wPartySpecies
	ld c, a
	ld b, 0
	add hl, bc
	ld a, [hl]
;> wNamedObjectIndex = species
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> CopyData(addr(wNameBuffer), addr(wNameOfPlayerMonToBeTraded), NAME_LENGTH)
	ld hl, wNameBuffer
	ld de, wNameOfPlayerMonToBeTraded
	ld bc, NAME_LENGTH
	call CopyData
;> species = wEnemyPartySpecies[wTradingWhichEnemyMon]
	ld a, [wTradingWhichEnemyMon]
	ld hl, wEnemyPartySpecies
	ld c, a
	ld b, 0
	add hl, bc
	ld a, [hl]
;> wNamedObjectIndex = species
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> TextCommandProcessor(WillBeTradedText, coord(1, 14))  # "Trade <mon> for <mon>?"
	ld hl, WillBeTradedText
	ld bc, (14) * SCREEN_WIDTH + (1) + wTileMap
	call TextCommandProcessor
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> wTwoOptionMenuID = TRADE_CANCEL_MENU
;> wTextBoxID = TWO_OPTION_MENU
	ld hl, (7) * SCREEN_WIDTH + (10) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((11) & $ff)
	ld a, TRADE_CANCEL_MENU
	ld [wTwoOptionMenuID], a
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;> DisplayTextBoxID()                            # TRADE / CANCEL at coord(10, 7)
	call DisplayTextBoxID
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> if wCurrentMenuItem:                          # CANCEL
	ld a, [wCurrentMenuItem]
	and a
	jr z, .tradeConfirmed
; if trade cancelled
;>     wSerialExchangeNybbleSendData = 1
	ld a, $1
	ld [wSerialExchangeNybbleSendData], a
;>     CableClub_TextBoxBorder(coord(0, 12), 4, 18)
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 18
	call CableClub_TextBoxBorder
;>     PlaceString(TradeCanceled, coord(1, 14))
	ld hl, (14) * SCREEN_WIDTH + (1) + wTileMap
	ld de, TradeCanceled
	call PlaceString
;>     Serial_PrintWaitingTextAndSyncAndExchangeNybble()
	call Serial_PrintWaitingTextAndSyncAndExchangeNybble
;>     traded = False
	jp .tradeCancelled
.tradeConfirmed
;> else:
;>     wSerialExchangeNybbleSendData = 2
	ld a, $2
	ld [wSerialExchangeNybbleSendData], a
;>     Serial_PrintWaitingTextAndSyncAndExchangeNybble()
	call Serial_PrintWaitingTextAndSyncAndExchangeNybble
;>     traded = wSerialSyncAndExchangeNybbleReceiveData != 1
	ld a, [wSerialSyncAndExchangeNybbleReceiveData]
	dec a ; did the other person cancel?
;>     if not traded:                            # the other player cancelled
	jr nz, .doTrade
; if the other person cancelled
;>         CableClub_TextBoxBorder(coord(0, 12), 4, 18)
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 18
	call CableClub_TextBoxBorder
;>         PlaceString(TradeCanceled, coord(1, 14))
	ld hl, (14) * SCREEN_WIDTH + (1) + wTileMap
	ld de, TradeCanceled
	call PlaceString
	jp .tradeCancelled
.doTrade
;> if traded:
;>     # remember both Pokémon's original trainers and IDs for the trade animation
;>     CopyData(SkipFixedLengthTextEntries(addr(wPartyMonOT), wTradingWhichPlayerMon), addr(wTradedPlayerMonOT), NAME_LENGTH)
	ld a, [wTradingWhichPlayerMon]
	ld hl, wPartyMonOT
	call SkipFixedLengthTextEntries
	ld de, wTradedPlayerMonOT
	ld bc, NAME_LENGTH
	call CopyData
;>     mon = addr(wPartyMon1Species) + wTradingWhichPlayerMon * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Species
	ld a, [wTradingWhichPlayerMon]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     wTradedPlayerMonOTID[0] = mem[mon + MON_OTID]
;>     wTradedPlayerMonOTID[1] = mem[mon + MON_OTID + 1]
	ld bc, MON_OTID
	add hl, bc
	ld a, [hli]
	ld [wTradedPlayerMonOTID], a
	ld a, [hl]
	ld [wTradedPlayerMonOTID + 1], a
;>     CopyData(SkipFixedLengthTextEntries(addr(wEnemyMonOT), wTradingWhichEnemyMon), addr(wTradedEnemyMonOT), NAME_LENGTH)
	ld a, [wTradingWhichEnemyMon]
	ld hl, wEnemyMonOT
	call SkipFixedLengthTextEntries
	ld de, wTradedEnemyMonOT
	ld bc, NAME_LENGTH
	call CopyData
;>     mon = addr(wEnemyMons) + wTradingWhichEnemyMon * PARTYMON_STRUCT_LENGTH
	ld hl, wEnemyMons
	ld a, [wTradingWhichEnemyMon]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     wTradedEnemyMonOTID[0] = mem[mon + MON_OTID]
;>     wTradedEnemyMonOTID[1] = mem[mon + MON_OTID + 1]
	ld bc, MON_OTID
	add hl, bc
	ld a, [hli]
	ld [wTradedEnemyMonOTID], a
	ld a, [hl]
	ld [wTradedEnemyMonOTID + 1], a
;>     # the player's Pokémon leaves, the other one joins at the end of the party
;>     wWhichPokemon = wTradingWhichPlayerMon
	ld a, [wTradingWhichPlayerMon]
	ld [wWhichPokemon], a
;>     wTradedPlayerMonSpecies = wPartySpecies[wTradingWhichPlayerMon]
	ld hl, wPartySpecies
	ld b, 0
	ld c, a
	add hl, bc
	ld a, [hl]
	ld [wTradedPlayerMonSpecies], a
;>     wRemoveMonFromBox = 0
;>     RemovePokemon()
	xor a
	ld [wRemoveMonFromBox], a
	call RemovePokemon
;>     wWhichPokemon = wTradingWhichEnemyMon
	ld a, [wTradingWhichEnemyMon]
	ld c, a
	ld [wWhichPokemon], a
;>     wCurPartySpecies = wEnemyPartySpecies[wTradingWhichEnemyMon]
	ld hl, wEnemyPartySpecies
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
	ld [wCurPartySpecies], a
;>     mon = addr(wEnemyMons) + wTradingWhichEnemyMon * PARTYMON_STRUCT_LENGTH
	ld hl, wEnemyMons
	ld a, c
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     CopyData(mon, addr(wLoadedMon), PARTYMON_STRUCT_LENGTH)
	ld de, wLoadedMon
	ld bc, PARTYMON_STRUCT_LENGTH
	call CopyData
;>     AddEnemyMonToPlayerParty()
	call AddEnemyMonToPlayerParty
;>     wWhichPokemon = wPartyCount - 1           # the new one, last in the party
	ld a, [wPartyCount]
	dec a
	ld [wWhichPokemon], a
;>     wForceEvolution = TRUE                    # trade evolutions
	ld a, TRUE
	ld [wForceEvolution], a
;>     species = wEnemyPartySpecies[wTradingWhichEnemyMon]
	ld a, [wTradingWhichEnemyMon]
	ld hl, wEnemyPartySpecies
	ld b, 0
	ld c, a
	add hl, bc
	ld a, [hl]
;>     wTradedEnemyMonSpecies = species
	ld [wTradedEnemyMonSpecies], a
;>     wAudioFadeOutControl = 10
;>     wAudioSavedROMBank = BANK(Music_SafariZone)
	ld a, 10
	ld [wAudioFadeOutControl], a
	ld a, BANK(Music_SafariZone)
	ld [wAudioSavedROMBank], a
;>     wNewSoundID = MUSIC_SAFARI_ZONE
;>     PlaySound(MUSIC_SAFARI_ZONE)              # fade into the trade music
	ld a, MUSIC_SAFARI_ZONE
	ld [wNewSoundID], a
	call PlaySound
;>     DelayFrames(100)
	ld c, 100
	call DelayFrames
;>     ClearScreen()
	call ClearScreen
;>     LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;>     wUnusedFlag = 0
	xor a
	ld [wUnusedFlag], a
;>     if hSerialConnectionStatus != USING_EXTERNAL_CLOCK:
	ldh a, [hSerialConnectionStatus]
	cp USING_EXTERNAL_CLOCK
	jr z, .usingExternalClock
;>         Predef((InternalClockTradeAnimPredef - PredefPointers) // 3)
	ld a, (InternalClockTradeAnimPredef - PredefPointers) / 3
	call Predef
	jr .tradeCompleted
.usingExternalClock
;>     else:
;>         Predef((ExternalClockTradeAnimPredef - PredefPointers) // 3)
	ld a, (ExternalClockTradeAnimPredef - PredefPointers) / 3
	call Predef
.tradeCompleted
;>     TryEvolvingMon()
	ld hl, TryEvolvingMon
	ld b, BANK(TryEvolvingMon)
	call Bankswitch
;>     ClearScreen()
	call ClearScreen
;>     LoadTrainerInfoTextBoxTiles()
	call LoadTrainerInfoTextBoxTiles
;>     Serial_PrintWaitingTextAndSyncAndExchangeNybble()
	call Serial_PrintWaitingTextAndSyncAndExchangeNybble
;>     DelayFrames(40)
	ld c, 40
	call DelayFrames
;>     CableClub_TextBoxBorder(coord(0, 12), 4, 18)
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 18
	call CableClub_TextBoxBorder
;>     PlaceString(TradeCompleted, coord(1, 14))
	ld hl, (14) * SCREEN_WIDTH + (1) + wTileMap
	ld de, TradeCompleted
	call PlaceString
	; this allows reset into Pokecenter
;>     Predef((SavePartyAndDexDataPredef - PredefPointers) // 3)    # so a reset comes back in the Pokémon Center
	ld a, (SavePartyAndDexDataPredef - PredefPointers) / 3
	call Predef
;>     DelayFrames(50)
	ld c, 50
	call DelayFrames
;>     wTradeCenterPointerTableIndex = 0
;>     return CableClub_DoBattleOrTradeAgain()
	xor a
	ld [wTradeCenterPointerTableIndex], a
	jp CableClub_DoBattleOrTradeAgain
.tradeCancelled
;> # cancelled: back to the selection screen
;> DelayFrames(100)
	ld c, 100
	call DelayFrames
;> wTradeCenterPointerTableIndex = 0             # TradeCenter_SelectMon
;> return CallCurrentTradeCenterFunction()
	xor a ; TradeCenter_SelectMon
	ld [wTradeCenterPointerTableIndex], a
	jp CallCurrentTradeCenterFunction

;@ path: engine/link/cable_club
WillBeTradedText:
	db TX_FAR
	dw _WillBeTradedText
	db BANK(_WillBeTradedText)
	db TX_END

;@ path: engine/link/cable_club
TradeCompleted:
	db "Trade completed!@"

;@ path: engine/link/cable_club
TradeCanceled:
	db   "Too bad! The trade"
	db "<NEXT>", "was canceled!@"

;@ path: engine/link/cable_club
TradeCenterPointerTable:
	dw TradeCenter_SelectMon
	dw TradeCenter_Trade

;@ path: engine/link/cable_club
;@ def CableClub_Run()
;@ When the Cable Club is entered for a trade or battle: do the exchange, then set up the Cable Club room's
;@ tileset and music. (A reset link state would restart the game; it is never set.)
;@ test: skip talks over the link cable
CableClub_Run:
;> if wLinkState not in (LINK_STATE_START_TRADE, LINK_STATE_START_BATTLE):
	ld a, [wLinkState]
	cp LINK_STATE_START_TRADE
	jr z, .doBattleOrTrade
	cp LINK_STATE_START_BATTLE
	jr z, .doBattleOrTrade
;>     if wLinkState != LINK_STATE_RESET:
;>         return
	cp LINK_STATE_RESET ; this is never used
	ret nz
;>     Predef((EmptyFuncPredef - PredefPointers) // 3)
	ld a, (EmptyFuncPredef - PredefPointers) / 3
	call Predef
;>     return Init()
	jp Init
.doBattleOrTrade
;> CableClub_DoBattleOrTrade()
	call CableClub_DoBattleOrTrade
;> wTilesetGfxPtr[0] = Club_GFX & 0xFF
;> wTilesetGfxPtr[1] = Club_GFX >> 8
	ld hl, Club_GFX
	ld a, h
	ld [wTilesetGfxPtr + 1], a
	ld a, l
	ld [wTilesetGfxPtr], a
;> wTilesetBank = BANK(Club_GFX)
	ld a, BANK(Club_GFX)
	ld [wTilesetBank], a
;> wTilesetCollisionPtr[0] = Club_Coll & 0xFF
;> wTilesetCollisionPtr[1] = Club_Coll >> 8
	ld hl, Club_Coll
	ld a, h
	ld [wTilesetCollisionPtr + 1], a
	ld a, l
	ld [wTilesetCollisionPtr], a
;> wGrassRate = 0
	xor a
	ld [wGrassRate], a
;> wLinkState = LINK_STATE_IN_CABLE_CLUB
	inc a ; LINK_STATE_IN_CABLE_CLUB
	ld [wLinkState], a
;> hJoy5 = LINK_STATE_IN_CABLE_CLUB
	ldh [hJoy5], a
;> wAudioFadeOutControl = 10
	ld a, 10
	ld [wAudioFadeOutControl], a
;> wAudioSavedROMBank = BANK(Music_Celadon)
	ld a, BANK(Music_Celadon)
	ld [wAudioSavedROMBank], a
;> wNewSoundID = MUSIC_CELADON
	ld a, MUSIC_CELADON
	ld [wNewSoundID], a
;> return PlaySound(MUSIC_CELADON)
	jp PlaySound

;@ path: engine/link/cable_club
;@ def EmptyFunc()
;@ Does nothing.
EmptyFunc:
;> return
	ret

;@ path: engine/link/cable_club
;@ def Diploma_TextBoxBorder()
;@ CableClub_TextBoxBorder with corner, height and width from the predef's hl, b and c (the diploma's frame).
;@ test: mem[wPredefHL] = 0xC1; mem[wPredefHL + 1] = rand(0, 255); mem[wPredefBC] = rand(1, 8); mem[wPredefBC + 1] = rand(1, 18)
Diploma_TextBoxBorder:
;> corner, _, bc = GetPredefRegisters()
;> CableClub_TextBoxBorder(corner, bc >> 8, bc & 0xFF)
	call GetPredefRegisters

; b = height
; c = width
;@ path: engine/link/cable_club
;@ def CableClub_TextBoxBorder(corner: hl, height: b, width: c)
;@ A box in the trade screen's frame tiles: `height` rows of `width` blank tiles inside the border.
;@ test: corner = rand(0xC000, 0xCC00); height = rand(1, 8); width = rand(1, 18)
CableClub_TextBoxBorder:
;> row = corner
	push hl
;> mem[row] = 0x78                                   # ┌
	ld a, $78 ; border upper left corner tile
	ld [hli], a
;> end = CableClub_DrawHorizontalLine(row + 1, 0x79, width)
	inc a ; border top horizontal line tile
	call CableClub_DrawHorizontalLine
;> mem[end] = 0x7A                                   # ┐
	inc a ; border upper right corner tile
	ld [hl], a
;> for _ in range(height):
;>     row += SCREEN_WIDTH
	pop hl
	ld de, 20
	add hl, de
.loop
;>     mem[row] = 0x7B                               # │
	push hl
	ld a, $7b ; border left vertical line tile
	ld [hli], a
;>     end = CableClub_DrawHorizontalLine(row + 1, charmap(' ')[0], width)
	ld a, ' '
	call CableClub_DrawHorizontalLine
;>     mem[end] = 0x77                               # │
	ld [hl], $77 ; border right vertical line tile
;> row += SCREEN_WIDTH
	pop hl
	ld de, 20
	add hl, de
	dec b
	jr nz, .loop
;> mem[row] = 0x7C                                   # └
	ld a, $7c ; border lower left corner tile
	ld [hli], a
;> end = CableClub_DrawHorizontalLine(row + 1, 0x76, width)
	ld a, $76 ; border bottom horizontal line tile
	call CableClub_DrawHorizontalLine
;> mem[end] = 0x7D                                   # ┘
	ld [hl], $7d ; border lower right corner tile
	ret

; c = width
;@ path: engine/link/cable_club
;@ def CableClub_DrawHorizontalLine(dest: hl, tile: a, width: c) -> hl
;@ `width` copies of `tile` from dest on. Returns the address after them.
;@ test: dest = rand(0xC000, 0xCF00); width = rand(1, 20)
CableClub_DrawHorizontalLine:
;> for i in range(width):
	ld d, c
.loop
;>     mem[dest + i] = tile
	ld [hli], a
	dec d
	jr nz, .loop
;> return dest + width
	ret

;@ path: engine/link/cable_club
;@ def LoadTrainerInfoTextBoxTiles()
;@ Load the trade screen's frame tiles over the box tiles.
;@ test: skip copies to VRAM over several VBlanks
LoadTrainerInfoTextBoxTiles:
;> CopyVideoData(vChars2 + 0x76 * TILE_SIZE, TrainerInfoTextBoxTileGraphics, BANK(TrainerInfoTextBoxTileGraphics), (TrainerInfoTextBoxTileGraphicsEnd - TrainerInfoTextBoxTileGraphics) // TILE_SIZE)
	ld de, TrainerInfoTextBoxTileGraphics
	ld hl, vChars2 + TILE_SIZE * $76
	ld bc, ((BANK(TrainerInfoTextBoxTileGraphics)) & $ff) << 8 + (((TrainerInfoTextBoxTileGraphicsEnd - TrainerInfoTextBoxTileGraphics) / TILE_SIZE) & $ff)
	jp CopyVideoData
;@ def MainMenu()
;@ The menu after the title screen: CONTINUE (when there is a save file), NEW GAME and OPTION. CONTINUE shows the
;@ save's summary and starts on A; B goes back to the title screen. A game saved in the Hall of Fame continues
;@ in Pallet Town.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/menus/main_menu
MainMenu:
; Check save file
;> InitOptions()
	call InitOptions
;> wOptionsInitialized = 0
	xor a
	ld [wOptionsInitialized], a
;> wSaveFileStatus = 1                         # 1: no save file, 2: a save file
	inc a
	ld [wSaveFileStatus], a
;> if CheckForPlayerNameInSRAM():
	call CheckForPlayerNameInSRAM
	jr nc, .mainMenuLoop

;>     TryLoadSaveFile()
	ld a, (TryLoadSaveFilePredef - PredefPointers) / 3
	call Predef

;> while True:
.mainMenuLoop
;>     DelayFrames(20)
	ld c, 20
	call DelayFrames
;>     wLinkState = LINK_STATE_NONE
	xor a ; LINK_STATE_NONE
	ld [wLinkState], a
;>     for i in range(4):                      # the remembered menu positions
;>         mem[addr(wPartyAndBillsPCSavedMenuItem) + i] = 0
	ld hl, wPartyAndBillsPCSavedMenuItem
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;>     wDefaultMap = 0
	ld [wDefaultMap], a
;>     wStatusFlags4 &= ~(1 << BIT_LINK_CONNECTED) & 0xFF
	ld hl, wStatusFlags4
	res BIT_LINK_CONNECTED, [hl]
;>     ClearScreen()
	call ClearScreen
;>     RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>     LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;>     LoadFontTilePatterns()
	call LoadFontTilePatterns
;>     wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;>     if wSaveFileStatus == 1:                # no save file: NEW GAME and OPTION
	ld a, [wSaveFileStatus]
	cp 1
	jr z, .noSaveFile
;>@nsbox         TextBoxBorder(coord(0, 0), 4, 13)
;>@nstext         PlaceString(NewGameText, coord(2, 2))
; there's a save file
;>     else:                                   # CONTINUE, NEW GAME and OPTION
;>         TextBoxBorder(coord(0, 0), 6, 13)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 6
	ld c, 13
	call TextBoxBorder
;>         PlaceString(ContinueText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, ContinueText
	call PlaceString
	jr .next2
.noSaveFile
;=@nsbox
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 13
	call TextBoxBorder
;=@nstext
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, NewGameText
	call PlaceString
.next2
;>     wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;>     UpdateSprites()
	call UpdateSprites
;>     wCurrentMenuItem = wLastMenuItem = wMenuJoypadPollCount = 0
	xor a
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
	ld [wMenuJoypadPollCount], a
;>     wTopMenuItemX = 1
	inc a
	ld [wTopMenuItemX], a
;>     wTopMenuItemY = 2
	inc a
	ld [wTopMenuItemY], a
;>     wMenuWatchedKeys = PAD_A | PAD_B | PAD_START
	ld a, PAD_A | PAD_B | PAD_START
	ld [wMenuWatchedKeys], a
;>     wMaxMenuItem = wSaveFileStatus
	ld a, [wSaveFileStatus]
	ld [wMaxMenuItem], a
;>     if HandleMenuInput() & PAD_B:
;>         return DisplayTitleScreen()
	call HandleMenuInput
	bit B_PAD_B, a
	jp nz, DisplayTitleScreen ; if so, go back to the title screen
;>     DelayFrames(20)
	ld c, 20
	call DelayFrames
;>     choice = wCurrentMenuItem               # 0 CONTINUE, 1 NEW GAME, 2 OPTION
	ld a, [wCurrentMenuItem]
	ld b, a
;>     if wSaveFileStatus != 2:
	ld a, [wSaveFileStatus]
	cp 2
	jp z, .skipInc
; If there's no save file, increment the current menu item so that the numbers
; are the same whether or not there's a save file.
;>         choice = (choice + 1) & 0xFF
	inc b
.skipInc
;>     if choice != 0:
	ld a, b
	and a
	jr z, .choseContinue
;>         if choice == 1:
;>             return StartNewGame()
	cp 1
	jp z, StartNewGame
;>         DisplayOptionMenu()
	call DisplayOptionMenu
;>         wOptionsInitialized = TRUE
	ld a, TRUE
	ld [wOptionsInitialized], a
;>         continue
	jp .mainMenuLoop
.choseContinue
;>     DisplayContinueGameInfo()
	call DisplayContinueGameInfo
;>     wCurrentMapScriptFlags |= 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
.inputLoop
;>@wait     while True:                         # wait for A or B
;>         hJoyPressed = hJoyReleased = hJoyHeld = 0
	xor a
	ldh [hJoyPressed], a
	ldh [hJoyReleased], a
	ldh [hJoyHeld], a
;>         Joypad()
	call Joypad
;>         pressed = hJoyHeld
	ldh a, [hJoyHeld]
;>         if pressed & (PAD_A | PAD_B):
;>             break
	bit B_PAD_A, a
	jr nz, .pressedA
	bit B_PAD_B, a
	jp nz, .mainMenuLoop
;=@wait
	jr .inputLoop
;>@pa     if pressed & PAD_A:                     # (B shows the menu again)
;>@pab         break
.pressedA
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> wPlayerDirection = PLAYER_DIR_DOWN
	ld a, PLAYER_DIR_DOWN
	ld [wPlayerDirection], a
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> if wNumHoFTeams and wCurMap == HALL_OF_FAME:
	ld a, [wNumHoFTeams]
	and a
	jp z, SpecialEnterMap
	ld a, [wCurMap]
	cp HALL_OF_FAME
	jp nz, SpecialEnterMap
;>     wDestinationMap = PALLET_TOWN
	xor a
	ld [wDestinationMap], a
;>     wStatusFlags6 |= 1 << BIT_FLY_OR_DUNGEON_WARP
	ld hl, wStatusFlags6
	set BIT_FLY_OR_DUNGEON_WARP, [hl]
;>     PrepareForSpecialWarp()
	call PrepareForSpecialWarp
;> return SpecialEnterMap()
	jp SpecialEnterMap

;@ def InitOptions()
;@ The options of a new game: medium text speed, battle animations on, battle style shift.
;@ path: engine/menus/main_menu
InitOptions:
;> wLetterPrintingDelayFlags = 1 << BIT_FAST_TEXT_DELAY
;> wOptions = TEXT_DELAY_MEDIUM
	ld a, 1 << BIT_FAST_TEXT_DELAY
	ld [wLetterPrintingDelayFlags], a
	ld a, TEXT_DELAY_MEDIUM
	ld [wOptions], a
	ret

;@ def LinkMenu()
;@ The Cable Club desk over a link cable: TRADE CENTER, COLOSSEUM or CANCEL. Both Game Boys keep sending their
;@ cursor and keys ($D0 + keys * 4 + item) until one presses A or B; if both did, the one clocking the link
;@ decides. Then a warp into the chosen room, or the link is closed.
;@ path: engine/menus/main_menu
LinkMenu:
;> wLetterPrintingDelayFlags = 0
	xor a
	ld [wLetterPrintingDelayFlags], a
;> wStatusFlags4 |= 1 << BIT_LINK_CONNECTED
	ld hl, wStatusFlags4
	set BIT_LINK_CONNECTED, [hl]
;> PrintText(LinkMenuEmptyText)
	ld hl, LinkMenuEmptyText
	call PrintText
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> PrintText(WhereWouldYouLikeText)
	ld hl, WhereWouldYouLikeText
	call PrintText
;> TextBoxBorder(coord(5, 5), 6, 13)
	ld hl, (5) * SCREEN_WIDTH + (5) + wTileMap
	ld b, $6
	ld c, $d
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> PlaceString(CableClubOptionsText, coord(7, 7))
	ld hl, (7) * SCREEN_WIDTH + (7) + wTileMap
	ld de, CableClubOptionsText
	call PlaceString
;> wUnusedLinkMenuByte = 0
	xor a
	ld [wUnusedLinkMenuByte], a
;> wCableClubDestinationMap = 0
	ld [wCableClubDestinationMap], a
;> wTopMenuItemY = 7
	ld hl, wTopMenuItemY
	ld a, 7
	ld [hli], a
	ASSERT wTopMenuItemY + 1 == wTopMenuItemX
;> wTopMenuItemX = 6
	ld a, 6
	ld [hli], a
	ASSERT wTopMenuItemX + 1 == wCurrentMenuItem
;> wCurrentMenuItem = 0
	xor a
	ld [hli], a
;> wMaxMenuItem = 2
	inc hl
	ASSERT wCurrentMenuItem + 2 == wMaxMenuItem
	ld a, 2
	ld [hli], a
	ASSERT wMaxMenuItem + 1 == wMenuWatchedKeys
	ASSERT 2 + 1 == PAD_A | PAD_B
;> wMenuWatchedKeys = PAD_A | PAD_B
	inc a
	ld [hli], a
	ASSERT wMenuWatchedKeys + 1 == wLastMenuItem
;> wLastMenuItem = 0
	xor a
	ld [hl], a
;>@snd send = addr(wLinkMenuSelectionSendBuffer)
;>@rcv receive = addr(wLinkMenuSelectionReceiveBuffer)
;>@wl while True:
.waitForInputLoop
;>     keys = HandleMenuInput() & (PAD_A | PAD_B)
	call HandleMenuInput
	and PAD_A | PAD_B
;>     sel = (keys * 4 + wCurrentMenuItem + 0xD0) & 0xFF      # keys and cursor, marked with $D0
	add a
	add a
	ld b, a
	ld a, [wCurrentMenuItem]
	add b
	add $d0
;>     mem[send] = mem[send + 1] = sel
	ld [wLinkMenuSelectionSendBuffer], a
	ld [wLinkMenuSelectionSendBuffer + 1], a
;>     while True:                             # until the other side's selection arrives
.exchangeMenuSelectionLoop
;>         Serial_ExchangeLinkMenuSelection()
	call Serial_ExchangeLinkMenuSelection
;>         other = mem[receive]
	ld a, [wLinkMenuSelectionReceiveBuffer]
	ld b, a
;>         if other & 0xF0 == 0xD0:
;>             break
	and $f0
	cp $d0
	jr z, .checkEnemyMenuSelection
;>         other = mem[receive + 1]
	ld a, [wLinkMenuSelectionReceiveBuffer + 1]
	ld b, a
;>         if other & 0xF0 == 0xD0:
;>             break
	and $f0
	cp $d0
	jr nz, .exchangeMenuSelectionLoop
.checkEnemyMenuSelection
;>     if other & 0xC:                         # the other player pressed A or B
	ld a, b
	and $c ; did the enemy press A or B?
	jr nz, .enemyPressedAOrB
;>@mine         mine = mem[send] & 0xC
;>@clock         if not mine or hSerialConnectionStatus != USING_INTERNAL_CLOCK:   # if both did, the clocking side wins
;>@take             mem[send] = other           # take the other side's choice
;>@item             wCurrentMenuItem = other & 3
;>@brk1         break
; the enemy didn't press A or B
;>     elif mem[send] & 0xC:                   # only the player did
;>         break
	ld a, [wLinkMenuSelectionSendBuffer]
	and $c ; did the player press A or B?
	jr z, .waitForInputLoop ; if neither the player nor the enemy pressed A or B, try again
	jr .doneChoosingMenuSelection ; if the player pressed A or B but the enemy didn't, use the player's selection
.enemyPressedAOrB
;=@mine
	ld a, [wLinkMenuSelectionSendBuffer]
	and $c ; did the player press A or B?
;=@clock
	jr z, .useEnemyMenuSelection ; if the enemy pressed A or B but the player didn't, use the enemy's selection
; the enemy and the player both pressed A or B
; The gameboy that is clocking the connection wins.
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr z, .doneChoosingMenuSelection
.useEnemyMenuSelection
;=@take
	ld a, b
	ld [wLinkMenuSelectionSendBuffer], a
;=@item
	and $3
	ld [wCurrentMenuItem], a
.doneChoosingMenuSelection
;> if hSerialConnectionStatus == USING_INTERNAL_CLOCK:
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr nz, .skipStartingTransfer
;>     DelayFrame()
	call DelayFrame
;>     DelayFrame()
	call DelayFrame
;>     rSC = SC_START | SC_INTERNAL
	ld a, SC_START | SC_INTERNAL
	ldh [rSC], a
.skipStartingTransfer
;> b, c, d = 0x7F, 0x7F, 0xEC                  # ' ', ' ', '▷': a hollow arrow on the choice
	ld b, ' '
	ld c, ' '
	ld d, '▷'
;> if not mem[send] & (PAD_B << 2):            # A: the arrow moves up to the choice
	ld a, [wLinkMenuSelectionSendBuffer]
	and PAD_B << 2 ; was B button pressed?
	jr nz, .updateCursorPosition
; A button was pressed
;>     if wCurrentMenuItem != 2:
	ld a, [wCurrentMenuItem]
	cp $2
	jr z, .updateCursorPosition
;>         c, d = d, b
	ld c, d
	ld d, b
;>         if wCurrentMenuItem == 0:
;>             b, c = c, d
	dec a
	jr z, .updateCursorPosition
	ld b, c
	ld c, d
.updateCursorPosition
;> mem[coord(6, 7)] = b
	ld a, b
	ld [(7) * SCREEN_WIDTH + (6) + wTileMap], a
;> mem[coord(6, 9)] = c
	ld a, c
	ld [(9) * SCREEN_WIDTH + (6) + wTileMap], a
;> mem[coord(6, 11)] = d
	ld a, d
	ld [(11) * SCREEN_WIDTH + (6) + wTileMap], a
;> DelayFrames(40)
	ld c, 40
	call DelayFrames
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> if mem[send] & (PAD_B << 2) or wCurrentMenuItem == 2:      # B or CANCEL
	ld a, [wLinkMenuSelectionSendBuffer]
	and PAD_B << 2 ; was B button pressed?
	jr nz, .choseCancel ; cancel if B pressed
	ld a, [wCurrentMenuItem]
	cp $2
	jr z, .choseCancel
;>@c1     wMenuJoypadPollCount = 0
;>@c2     Delay3()
;>@c3     CloseLinkConnection()
;>@c4     PrintText(LinkCanceledText)
;>@c5     wStatusFlags4 &= ~(1 << BIT_LINK_CONNECTED) & 0xFF
;>@c6     return
;> wWalkBikeSurfState = 0
	xor a
	ld [wWalkBikeSurfState], a ; start walking
;> wCableClubDestinationMap = COLOSSEUM if wCurrentMenuItem else TRADE_CENTER
	ld a, [wCurrentMenuItem]
	and a
	ld a, COLOSSEUM
	jr nz, .next
	ld a, TRADE_CENTER
.next
	ld [wCableClubDestinationMap], a
;> PrintText(PleaseWaitText)
	ld hl, PleaseWaitText
	call PrintText
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> wStatusFlags6 &= ~(1 << BIT_DEBUG_MODE) & 0xFF
	ld hl, wStatusFlags6
	res BIT_DEBUG_MODE, [hl]
;> wDestinationMap = wDefaultMap
	ld a, [wDefaultMap]
	ld [wDestinationMap], a
;> PrepareForSpecialWarp()
	call PrepareForSpecialWarp
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> wMenuJoypadPollCount = 0
	xor a
	ld [wMenuJoypadPollCount], a
;> wSerialExchangeNybbleSendData = 0
	ld [wSerialExchangeNybbleSendData], a
;> wLinkState = wEnteringCableClub = LINK_STATE_IN_CABLE_CLUB
	inc a ; LINK_STATE_IN_CABLE_CLUB
	ld [wLinkState], a
	ld [wEnteringCableClub], a
;> return SpecialEnterMap()
	jr SpecialEnterMap
.choseCancel
;=@c1
	xor a
	ld [wMenuJoypadPollCount], a
;=@c2
	call Delay3
;=@c3
	call CloseLinkConnection
;=@c4
	ld hl, LinkCanceledText
	call PrintText
;=@c5
	ld hl, wStatusFlags4
	res BIT_LINK_CONNECTED, [hl]
;=@c6
	ret

;@ path: engine/menus/main_menu
WhereWouldYouLikeText:
	db TX_FAR
	dw _WhereWouldYouLikeText
	db BANK(_WhereWouldYouLikeText)
	db TX_END

;@ path: engine/menus/main_menu
PleaseWaitText:
	db TX_FAR
	dw _PleaseWaitText
	db BANK(_PleaseWaitText)
	db TX_END

;@ path: engine/menus/main_menu
LinkCanceledText:
	db TX_FAR
	dw _LinkCanceledText
	db BANK(_LinkCanceledText)
	db TX_END

;@ def StartNewGame()
;@ NEW GAME: debug mode off, then Professor Oak's introduction.
;@ path: engine/menus/main_menu
StartNewGame:
;> wStatusFlags6 &= ~(1 << BIT_DEBUG_MODE) & 0xFF
;> return StartNewGameDebug()
	ld hl, wStatusFlags6
	; Ensure debug mode is not used when starting a regular new game.
	; Debug mode persists in saved games for both debug and non-debug builds, and is
	; only reset here by the main menu.
	res BIT_DEBUG_MODE, [hl]
	; fallthrough
;@ def StartNewGameDebug()
;@ Professor Oak's introduction, then into the player's room.
;@ path: engine/menus/main_menu
StartNewGameDebug:
;> OakSpeech()
	call OakSpeech
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> return SpecialEnterMap()                     # it follows

; enter map after using a special warp or loading the game from the main menu
;@ def SpecialEnterMap()
;@ Enter the map after a special warp, a new game or CONTINUE: the play-time clock starts and the player sprite
;@ is reset. Entering the Cable Club stops before the map (the link code takes over).
;@ path: engine/menus/main_menu
SpecialEnterMap::
;> hJoyPressed = hJoyHeld = hJoy5 = 0
	xor a
	ldh [hJoyPressed], a
	ldh [hJoyHeld], a
	ldh [hJoy5], a
;> wCableClubDestinationMap = 0
	ld [wCableClubDestinationMap], a
;> wStatusFlags6 |= 1 << BIT_GAME_TIMER_COUNTING
	ld hl, wStatusFlags6
	set BIT_GAME_TIMER_COUNTING, [hl]
;> ResetPlayerSpriteData()
	call ResetPlayerSpriteData
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> if wEnteringCableClub:
;>     return
	ld a, [wEnteringCableClub]
	and a
	ret nz
;> return EnterMap()
	jp EnterMap

;@ path: engine/menus/main_menu
ContinueText:
	db "CONTINUE"
	db "<NEXT>", ""
	; fallthrough

;@ path: engine/menus/main_menu
NewGameText:
	db   "NEW GAME"
	db "<NEXT>", "OPTION@"

;@ path: engine/menus/main_menu
CableClubOptionsText:
	db   "TRADE CENTER"
	db "<NEXT>", "COLOSSEUM"
	db "<NEXT>", "CANCEL@"

;@ def DisplayContinueGameInfo()
;@ The summary under the main menu for CONTINUE: the player's name, badges, Pokédex count and play time.
;@ path: engine/menus/main_menu
DisplayContinueGameInfo:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> TextBoxBorder(coord(4, 7), 8, 14)
	ld hl, (7) * SCREEN_WIDTH + (4) + wTileMap
	ld b, 8
	ld c, 14
	call TextBoxBorder
;> PlaceString(SaveScreenInfoText, coord(5, 9))
	ld hl, (9) * SCREEN_WIDTH + (5) + wTileMap
	ld de, SaveScreenInfoText
	call PlaceString
;> PlaceString(addr(wPlayerName), coord(12, 9))
	ld hl, (9) * SCREEN_WIDTH + (12) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PrintNumBadges(coord(17, 11))
	ld hl, (11) * SCREEN_WIDTH + (17) + wTileMap
	call PrintNumBadges
;> PrintNumOwnedMons(coord(16, 13))
	ld hl, (13) * SCREEN_WIDTH + (16) + wTileMap
	call PrintNumOwnedMons
;> PrintPlayTime(coord(13, 15))
	ld hl, (15) * SCREEN_WIDTH + (13) + wTileMap
	call PrintPlayTime
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> return DelayFrames(30)
	ld c, 30
	jp DelayFrames

;@ def PrintSaveScreenText()
