	ld hl, (2) * SCREEN_WIDTH + (5) + wTileMap
	ld de, SaveScreenInfoText
	call PlaceString
;> PlaceString(addr(wPlayerName), coord(12, 2))
	ld hl, (2) * SCREEN_WIDTH + (12) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PrintNumBadges(coord(17, 4))
	ld hl, (4) * SCREEN_WIDTH + (17) + wTileMap
	call PrintNumBadges
;> PrintNumOwnedMons(coord(16, 6))
	ld hl, (6) * SCREEN_WIDTH + (16) + wTileMap
	call PrintNumOwnedMons
