;@ def PrintNumBadges(dest: hl)
;@ Print the number of badges the player has at dest.
;@ path: engine/menus/main_menu
PrintNumBadges:
;> CountSetBits(addr(wObtainedBadges), 1)
	push hl
	ld hl, wObtainedBadges
	ld b, $1
	call CountSetBits
	pop hl
;> PrintNumber(addr(wNumSetBits), dest, 1, 2)
	ld de, wNumSetBits
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	jp PrintNumber

;@ def PrintNumOwnedMons(dest: hl)
;@ Print the number of Pokémon the player has owned at dest.
;@ path: engine/menus/main_menu
PrintNumOwnedMons:
;> CountSetBits(wPokedexOwned, wPokedexOwnedEnd - wPokedexOwned)
	push hl
	ld hl, wPokedexOwned
	ld b, wPokedexOwnedEnd - wPokedexOwned
	call CountSetBits
	pop hl
;> PrintNumber(addr(wNumSetBits), dest, 1, 3)
	ld de, wNumSetBits
	ld bc, ((1) & $ff) << 8 + ((3) & $ff)
	jp PrintNumber

;@ def PrintPlayTime(dest: hl)
;@ Print the play time at dest as hours:minutes.
;@ test: dest = wTileMap + rand(0, 300)
;@ path: engine/menus/main_menu
PrintPlayTime:
;> dest = PrintNumber(addr(wPlayTimeHours), dest, 1, 3)
	ld de, wPlayTimeHours
	ld bc, ((1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> mem[dest] = 0x6D                                           # :
	ld [hl], $6d
	inc hl
;> PrintNumber(addr(wPlayTimeMinutes), dest + 1, LEADING_ZEROES | 1, 2)
	ld de, wPlayTimeMinutes
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((2) & $ff)
	jp PrintNumber

;@ path: engine/menus/main_menu
SaveScreenInfoText:
	db   "PLAYER"
	db "<NEXT>", "BADGES    "
	db "<NEXT>", "#DEX    "
	db "<NEXT>", "TIME@"

;@ def DisplayOptionMenu()
;@ The OPTION screen: TEXT SPEED (FAST, MEDIUM, SLOW), BATTLE ANIMATION (ON, OFF), BATTLE STYLE (SHIFT, SET) and
;@ CANCEL. UP and DOWN move between the rows (wrapping round), LEFT and RIGHT change the setting, which takes
;@ effect at once; B, START or A on CANCEL leave.
;@ path: engine/menus/main_menu
DisplayOptionMenu:
;> TextBoxBorder(coord(0, 0), 3, 18)           # a box for each setting
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 3
	ld c, 18
	call TextBoxBorder
;> TextBoxBorder(coord(0, 5), 3, 18)
	ld hl, (5) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 3
	ld c, 18
	call TextBoxBorder
;> TextBoxBorder(coord(0, 10), 3, 18)
	ld hl, (10) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 3
	ld c, 18
	call TextBoxBorder
;> PlaceString(TextSpeedOptionText, coord(1, 1))
	ld hl, (1) * SCREEN_WIDTH + (1) + wTileMap
	ld de, TextSpeedOptionText
	call PlaceString
;> PlaceString(BattleAnimationOptionText, coord(1, 6))
	ld hl, (6) * SCREEN_WIDTH + (1) + wTileMap
	ld de, BattleAnimationOptionText
	call PlaceString
;> PlaceString(BattleStyleOptionText, coord(1, 11))
	ld hl, (11) * SCREEN_WIDTH + (1) + wTileMap
	ld de, BattleStyleOptionText
	call PlaceString
;> PlaceString(OptionMenuCancelText, coord(2, 16))
	ld hl, (16) * SCREEN_WIDTH + (2) + wTileMap
	ld de, OptionMenuCancelText
	call PlaceString
;> wCurrentMenuItem = wLastMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
	ASSERT BIT_FAST_TEXT_DELAY == 0
;> wLetterPrintingDelayFlags = 1 << BIT_FAST_TEXT_DELAY
	inc a ; 1 << BIT_FAST_TEXT_DELAY
	ld [wLetterPrintingDelayFlags], a
;> wOptionsCancelCursorX = 1
	ld [wOptionsCancelCursorX], a
;> wTopMenuItemY = 3
	ld a, 3 ; text speed cursor Y coordinate
	ld [wTopMenuItemY], a
;> SetCursorPositionsFromOptions()
	call SetCursorPositionsFromOptions
;> wTopMenuItemX = wOptionsTextSpeedCursorX
	ld a, [wOptionsTextSpeedCursorX] ; text speed cursor X coordinate
	ld [wTopMenuItemX], a
;> hAutoBGTransferEnabled = 1
	ld a, $01
	ldh [hAutoBGTransferEnabled], a ; enable auto background transfer
;> Delay3()
	call Delay3
;> cursors = addr(wOptionsTextSpeedCursorX)    # the X of each row's cursor: speed, animation, style, cancel
;>@lp while True:
.loop
;>     PlaceMenuCursor(coord(0, 0))            # (hl only matters for a menu at row 0)
	call PlaceMenuCursor
;>     SetOptionsFromCursorPositions()         # the settings follow the cursors at once
;>     keys = 0
	call SetOptionsFromCursorPositions
;>@kw     while not keys & ~PAD_SELECT & 0xFF:    # any key but SELECT
.getJoypadStateLoop
;>         JoypadLowSensitivity()
	call JoypadLowSensitivity
;>         keys = hJoy5
	ldh a, [hJoy5]
	ld b, a
	and ~PAD_SELECT ; any key besides select pressed?
;=@kw
	jr z, .getJoypadStateLoop
;>     if keys & (PAD_B | PAD_START):
;>         break
	bit B_PAD_B, b
	jr nz, .exitMenu
	bit B_PAD_START, b
	jr nz, .exitMenu
;>     if keys & PAD_A:
	bit B_PAD_A, b
	jr z, .checkDirectionKeys
; A was pressed
;>         if wTopMenuItemY == 16:             # A on CANCEL leaves too
;>             break
	ld a, [wTopMenuItemY]
	cp 16 ; is the cursor on Cancel?
;>@ct         continue
;=@ct
	jr nz, .loop
.exitMenu
;=@exit
	ld a, SFX_PRESS_AB
	call PlaySound
	ret
.eraseOldMenuCursor
;=@setx
	ld [wTopMenuItemX], a
;=@erase
	call EraseMenuCursor
	jp .loop
.checkDirectionKeys
;>     y = wTopMenuItemY                       # rows 3, 8, 13 and 16 (CANCEL)
	ld a, [wTopMenuItemY]
;>     if keys & PAD_DOWN:
	bit B_PAD_DOWN, b
	jr nz, .downPressed
;=@up
	bit B_PAD_UP, b
	jr nz, .upPressed
;=@y8
	cp 8 ; cursor in Battle Animation section?
	jr z, .cursorInBattleAnimation
;=@y13
	cp 13 ; cursor in Battle Style section?
	jr z, .cursorInBattleStyle
;=@y16
	cp 16 ; cursor on Cancel?
	jr z, .loop
; cursor in Text Speed
;=@lft
	bit B_PAD_LEFT, b
	jp nz, .pressedLeftInTextSpeed
;=@rgt
	jp .pressedRightInTextSpeed
.downPressed
;>         if y == 16:
;>             row, step = 0, -13                  # from CANCEL round to the top
	cp 16
	ld b, -13
	ld hl, wOptionsTextSpeedCursorX
	jr z, .updateMenuVariables
;>         elif y == 3:
;>             row, step = 1, 5
	ld b, 5
	cp 3
	inc hl
	jr z, .updateMenuVariables
;>         elif y == 8:
;>             row, step = 2, 5
	cp 8
	inc hl
	jr z, .updateMenuVariables
;>         else:
;>             row, step = 3, 3                    # down to CANCEL
	ld b, 3
	inc hl
	jr .updateMenuVariables
.upPressed
;>@up     elif keys & PAD_UP:
;>         if y == 8:
;>             row, step = 0, -5
	cp 8
	ld b, -5
	ld hl, wOptionsTextSpeedCursorX
	jr z, .updateMenuVariables
;>         elif y == 13:
;>             row, step = 1, -5
	cp 13
	inc hl
	jr z, .updateMenuVariables
;>         elif y == 16:
;>             row, step = 2, -3
	cp 16
	ld b, -3
	inc hl
	jr z, .updateMenuVariables
;>         else:
;>             row, step = 3, 13                   # from the top round to CANCEL
	ld b, 13
	inc hl
.updateMenuVariables
;>     if keys & (PAD_DOWN | PAD_UP):
;>         wTopMenuItemY = (y + step) & 0xFF
	add b
	ld [wTopMenuItemY], a
;>         wTopMenuItemX = mem[cursors + row]      # the new row's cursor column
	ld a, [hl]
	ld [wTopMenuItemX], a
;>         PlaceUnfilledArrowMenuCursor(wTopMenuItemX)
	call PlaceUnfilledArrowMenuCursor
;>         continue
	jp .loop
.cursorInBattleAnimation
;>@y8     if y == 8:                              # BATTLE ANIMATION: ON / OFF
;>         wOptionsBattleAnimCursorX ^= 1 ^ 10     # between columns 1 and 10
	ld a, [wOptionsBattleAnimCursorX] ; battle animation cursor X coordinate
	xor 1 ^ 10 ; toggle between 1 and 10
	ld [wOptionsBattleAnimCursorX], a
;>         x = wOptionsBattleAnimCursorX
	jp .eraseOldMenuCursor
.cursorInBattleStyle
;>@y13     elif y == 13:                           # BATTLE STYLE: SHIFT / SET
;>         wOptionsBattleStyleCursorX ^= 1 ^ 10
	ld a, [wOptionsBattleStyleCursorX] ; battle style cursor X coordinate
	xor 1 ^ 10 ; toggle between 1 and 10
	ld [wOptionsBattleStyleCursorX], a
;>         x = wOptionsBattleStyleCursorX
	jp .eraseOldMenuCursor
;>@y16     elif y == 16:                           # CANCEL has nothing to change
;>@y16c         continue
;>     else:                                   # TEXT SPEED: columns 1, 7 and 14
;>@lft         if keys & PAD_LEFT:
.pressedLeftInTextSpeed
;>             x = wOptionsTextSpeedCursorX
	ld a, [wOptionsTextSpeedCursorX] ; text speed cursor X coordinate
;>             if x != 1:
	cp 1
	jr z, .updateTextSpeedXCoord
;>                 if x == 7:
	cp 7
	jr nz, .fromSlowToMedium
;>                     x -= 6                  # MEDIUM to FAST
	sub 6
	jr .updateTextSpeedXCoord
;>                 else:
;>                     x -= 7                  # SLOW to MEDIUM
.fromSlowToMedium
	sub 7
	jr .updateTextSpeedXCoord
.pressedRightInTextSpeed
;>@rgt         if not keys & PAD_LEFT:             # RIGHT
;>             x = wOptionsTextSpeedCursorX
	ld a, [wOptionsTextSpeedCursorX] ; text speed cursor X coordinate
;>             if x != 14:
	cp 14
	jr z, .updateTextSpeedXCoord
;>                 if x == 7:
	cp 7
	jr nz, .fromFastToMedium
;>                     x += 7                  # MEDIUM to SLOW
	add 7
	jr .updateTextSpeedXCoord
;>                 else:
;>                     x += 6                  # FAST to MEDIUM
.fromFastToMedium
	add 6
.updateTextSpeedXCoord
;>         wOptionsTextSpeedCursorX = x
	ld [wOptionsTextSpeedCursorX], a ; text speed cursor X coordinate
	jp .eraseOldMenuCursor
;>@setx     wTopMenuItemX = x                       # the cursor moves to the new setting
;>@erase     EraseMenuCursor()
;>@exit PlaySound(SFX_PRESS_AB)
;> return

;@ path: engine/menus/main_menu
TextSpeedOptionText:
	db   "TEXT SPEED"
	db "<NEXT>", " FAST  MEDIUM SLOW@"

;@ path: engine/menus/main_menu
BattleAnimationOptionText:
	db   "BATTLE ANIMATION"
	db "<NEXT>", " ON       OFF@"

;@ path: engine/menus/main_menu
BattleStyleOptionText:
	db   "BATTLE STYLE"
	db "<NEXT>", " SHIFT    SET@"

;@ path: engine/menus/main_menu
OptionMenuCancelText:
	db "CANCEL@"

; sets the options variable according to the current placement of the menu cursors in the options menu
;@ def SetOptionsFromCursorPositions()
;@ Leaving the OPTION menu: turn the three cursor positions back into wOptions (text delay, animations off,
;@ battle style set).
;@ test: wOptionsTextSpeedCursorX = [14, 7, 1][rand(0, 2)]; wOptionsBattleAnimCursorX = [1, 10][rand(0, 1)]; wOptionsBattleStyleCursorX = [1, 10][rand(0, 1)]
;@ path: engine/menus/main_menu
SetOptionsFromCursorPositions:
;> x = wOptionsTextSpeedCursorX
	ld hl, TextSpeedOptionData
	ld a, [wOptionsTextSpeedCursorX] ; text speed cursor X coordinate
	ld c, a
;> p = TextSpeedOptionData                      # entries: cursor column, text delay
.loop
;>@lp while mem[p] != x:
	ld a, [hli]
	cp c
	jr z, .textSpeedMatchFound
;>     p += 2
	inc hl
;=@lp
	jr .loop
.textSpeedMatchFound
;> options = mem[p + 1]
	ld a, [hl]
	ld d, a
;> if wOptionsBattleAnimCursorX != 1:
	ld a, [wOptionsBattleAnimCursorX] ; battle animation cursor X coordinate
	dec a
	jr z, .battleAnimationOn
; battle animation Off
;>     options |= 1 << BIT_BATTLE_ANIMATION                  # animations off
	set BIT_BATTLE_ANIMATION, d
	jr .checkBattleStyle
;> else:
;>     options &= ~(1 << BIT_BATTLE_ANIMATION)               # on
.battleAnimationOn
	res BIT_BATTLE_ANIMATION, d
.checkBattleStyle
;> if wOptionsBattleStyleCursorX != 1:
	ld a, [wOptionsBattleStyleCursorX] ; battle style cursor X coordinate
	dec a
	jr z, .battleStyleShift
; battle style Set
;>     options |= 1 << BIT_BATTLE_SHIFT                      # set
	set BIT_BATTLE_SHIFT, d
	jr .storeOptions
;> else:
;>     options &= ~(1 << BIT_BATTLE_SHIFT)                   # shift
.battleStyleShift
	res BIT_BATTLE_SHIFT, d
.storeOptions
;> wOptions = options
	ld a, d
	ld [wOptions], a
	ret

; reads the options variable and places menu cursors in the correct positions within the options menu
;@ def SetCursorPositionsFromOptions()
;@ Opening the OPTION menu: place the three cursors (▷) from wOptions, plus the one in front of CANCEL.
;@ path: engine/menus/main_menu
SetCursorPositionsFromOptions:
;> speed = wOptions & 0x3F                      # the text delay part
	ld hl, TextSpeedOptionData + 1
	ld a, [wOptions]
	ld c, a
	and $3f
;> index, p, found = IsInArray(speed, TextSpeedOptionData + 1, 2)
	push bc
	ld de, 2
	call IsInArray
	pop bc
;> wOptionsTextSpeedCursorX = mem[p - 1]
	dec hl
	ld a, [hl]
	ld [wOptionsTextSpeedCursorX], a ; text speed cursor X coordinate
;> mem[coord(0, 3) + wOptionsTextSpeedCursorX] = 0xEC         # ▷
	ld hl, (3) * SCREEN_WIDTH + (0) + wTileMap
	call .placeUnfilledRightArrow
;> wOptionsBattleAnimCursorX = 10 if wOptions >> 7 & 1 else 1     # OFF / ON
	sla c
	ld a, 1 ; On
	jr nc, .storeBattleAnimationCursorX
	ld a, 10 ; Off
.storeBattleAnimationCursorX
	ld [wOptionsBattleAnimCursorX], a ; battle animation cursor X coordinate
;> mem[coord(0, 8) + wOptionsBattleAnimCursorX] = 0xEC
	ld hl, (8) * SCREEN_WIDTH + (0) + wTileMap
	call .placeUnfilledRightArrow
;> wOptionsBattleStyleCursorX = 10 if wOptions >> 6 & 1 else 1    # SET / SHIFT
	sla c
	ld a, 1
	jr nc, .storeBattleStyleCursorX
	ld a, 10
.storeBattleStyleCursorX
	ld [wOptionsBattleStyleCursorX], a ; battle style cursor X coordinate
;> mem[coord(0, 13) + wOptionsBattleStyleCursorX] = 0xEC
	ld hl, (13) * SCREEN_WIDTH + (0) + wTileMap
	call .placeUnfilledRightArrow
; cursor in front of Cancel
;> mem[coord(0, 16) + 1] = 0xEC
	ld hl, (16) * SCREEN_WIDTH + (0) + wTileMap
	ld a, 1
.placeUnfilledRightArrow
;> # .placeUnfilledRightArrow (also called above): '▷' at hl + a
	ld e, a
	ld d, 0
	add hl, de
	ld [hl], '▷'
	ret

; table that indicates how the 3 text speed options affect frame delays
; Format:
; 00: X coordinate of menu cursor
; 01: delay after printing a letter (in frames)
;@ path: engine/menus/main_menu
TextSpeedOptionData:
	db 14, TEXT_DELAY_SLOW
	db  7, TEXT_DELAY_MEDIUM
	db  1, TEXT_DELAY_FAST
	db  7, -1 ; end (default X coordinate)

;@ def CheckForPlayerNameInSRAM() -> carry
;@ Whether SRAM holds a save file: carry if the player's name there has its '@' terminator.
;@ path: engine/menus/main_menu
CheckForPlayerNameInSRAM:
; Check if the player name data in SRAM has a string terminator character
; (indicating that a name may have been saved there) and return whether it does
; in carry.
;> open_sram(1)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ASSERT BANK(sPlayerName) == BMODE_ADVANCED
	ld [rRAMB], a
;>@each for i in range(NAME_LENGTH):
	ld b, NAME_LENGTH
	ld hl, sPlayerName
.loop
;>     if mem[sPlayerName + i] == 0x50:         # the name's '@' terminator
	ld a, [hli]
	cp '@'
	jr z, .found
;>@fclose         close_sram()
;>@fret         return True
;=@each
	dec b
	jr nz, .loop
; not found
;> close_sram()
	xor a
	ld [rRAMG], a
	ld [rBMODE], a
;> return False
	and a
	ret
.found
;=@fclose
	xor a
	ld [rRAMG], a
	ld [rBMODE], a
;=@fret
	scf
	ret
;@ path: engine/movie/oak_speech/oak_speech
;@ def PrepareOakSpeech()
;@ Before a new game: clear the player's whole save data and the sprite data (keeping the text speed, options
;@ and debug flag), set default options on a fresh start, and put in default names.
PrepareOakSpeech:
;> letter_delay = wLetterPrintingDelayFlags
	ld a, [wLetterPrintingDelayFlags]
	push af
;> options = wOptions
	ld a, [wOptions]
	push af
	; Retrieve BIT_DEBUG_MODE set in DebugMenu for StartNewGameDebug.
	; BUG: StartNewGame carries over BIT_ALWAYS_ON_BIKE from previous save files,
	; which causes CheckForceBikeOrSurf to not return.
	; To fix this in debug builds, reset BIT_ALWAYS_ON_BIKE here or in StartNewGame.
	; In non-debug builds, the instructions can be removed.
;> flags6 = wStatusFlags6                            # keeps the debug mode set by the debug menu
	ld a, [wStatusFlags6]
	push af
;> FillMemory(addr(wPlayerName), addr(wBoxDataEnd) - addr(wPlayerName), 0)
	ld hl, wPlayerName
	ld bc, wBoxDataEnd - wPlayerName
	xor a
	call FillMemory
;> FillMemory(addr(wSpriteDataStart), addr(wSpriteDataEnd) - addr(wSpriteDataStart), 0)
	ld hl, wSpriteDataStart
	ld bc, wSpriteDataEnd - wSpriteDataStart
	xor a
	call FillMemory
;> wStatusFlags6 = flags6
	pop af
	ld [wStatusFlags6], a
;> wOptions = options
	pop af
	ld [wOptions], a
;> wLetterPrintingDelayFlags = letter_delay
	pop af
	ld [wLetterPrintingDelayFlags], a
;> if not wOptionsInitialized:
;>     InitOptions()
	ld a, [wOptionsInitialized]
	and a
	call z, InitOptions
	; These debug names are used for StartNewGameDebug.
	; TestBattle uses the debug names from DebugMenu.
	; A variant of this process is performed in PrepareTitleScreen.
;> CopyData(DebugNewGamePlayerName, addr(wPlayerName), NAME_LENGTH)
	ld hl, DebugNewGamePlayerName
	ld de, wPlayerName
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(DebugNewGameRivalName, addr(wRivalName), NAME_LENGTH)
	ld hl, DebugNewGameRivalName
	ld de, wRivalName
	ld bc, NAME_LENGTH
	jp CopyData

;@ path: engine/movie/oak_speech/oak_speech
;@ def OakSpeech()
;@ The start of a new game: Prof. Oak's welcome, a Nidorino, the player's name, the rival's name, and the
;@ player shrinking into the overworld sprite. A Potion goes into the PC, and the game starts in the player's
;@ room. In debug mode the speech is skipped.
;@ test: skip runs the new game speech
OakSpeech:
;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> PlayMusic(MUSIC_ROUTES2, BANK(Music_Routes2))
	ld a, BANK(Music_Routes2)
	ld c, a
	ld a, MUSIC_ROUTES2
	call PlayMusic
;> ClearScreen()
	call ClearScreen
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> PrepareOakSpeech()
	call PrepareOakSpeech
;> InitPlayerData2()                                 # through the predef table
	ld a, (InitPlayerData2Predef - PredefPointers) / 3
	call Predef
;> wCurItem = POTION
	ld hl, wNumBoxItems
	ld a, POTION
	ld [wCurItem], a
;> wItemQuantity = 1
	ld a, 1
	ld [wItemQuantity], a
;> AddItemToInventory(addr(wNumBoxItems))            # a Potion in the PC
	call AddItemToInventory
;> wDestinationMap = wDefaultMap
	ld a, [wDefaultMap]
	ld [wDestinationMap], a
;> PrepareForSpecialWarp()
	call PrepareForSpecialWarp
;> hTileAnimations = 0
	xor a
	ldh [hTileAnimations], a
;> if not wStatusFlags6 >> BIT_DEBUG_MODE & 1:
	ld a, [wStatusFlags6]
	bit BIT_DEBUG_MODE, a
	jp nz, .skipSpeech
;>     IntroDisplayPicCenteredOrUpperRight(ProfOakPic, BANK(ProfOakPic), 0)
	ld de, ProfOakPic
	ld bc, ((BANK(ProfOakPic)) & $ff) << 8 + (($00) & $ff)
	call IntroDisplayPicCenteredOrUpperRight
;>     FadeInIntroPic()
	call FadeInIntroPic
;>     PrintText(OakSpeechText1)
	ld hl, OakSpeechText1
	call PrintText
;>     GBFadeOutToWhite()
	call GBFadeOutToWhite
;>     ClearScreen()
	call ClearScreen
;>     wCurSpecies = NIDORINO
	ld a, NIDORINO
	ld [wCurSpecies], a
;>     wCurPartySpecies = NIDORINO
	ld [wCurPartySpecies], a
;>     GetMonHeader()
	call GetMonHeader
;>     LoadFlippedFrontSpriteByMonIndex(coord(6, 4))
	ld hl, (4) * SCREEN_WIDTH + (6) + wTileMap
	call LoadFlippedFrontSpriteByMonIndex
;>     MovePicLeft()
	call MovePicLeft
;>     PrintText(OakSpeechText2)
	ld hl, OakSpeechText2
	call PrintText
;>     GBFadeOutToWhite()
	call GBFadeOutToWhite
;>     ClearScreen()
	call ClearScreen
;>     IntroDisplayPicCenteredOrUpperRight(RedPicFront, BANK(RedPicFront), 0)
	ld de, RedPicFront
	ld bc, ((BANK(RedPicFront)) & $ff) << 8 + (($00) & $ff)
	call IntroDisplayPicCenteredOrUpperRight
;>     MovePicLeft()
	call MovePicLeft
;>     PrintText(IntroducePlayerText)
	ld hl, IntroducePlayerText
	call PrintText
;>     ChoosePlayerName()
	call ChoosePlayerName
;>     GBFadeOutToWhite()
	call GBFadeOutToWhite
;>     ClearScreen()
	call ClearScreen
;>     IntroDisplayPicCenteredOrUpperRight(Rival1Pic, BANK(Rival1Pic), 0)
	ld de, Rival1Pic
	ld bc, ((BANK(Rival1Pic)) & $ff) << 8 + (($00) & $ff)
	call IntroDisplayPicCenteredOrUpperRight
;>     FadeInIntroPic()
	call FadeInIntroPic
;>     PrintText(IntroduceRivalText)
	ld hl, IntroduceRivalText
	call PrintText
;>     ChooseRivalName()
	call ChooseRivalName
.skipSpeech
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> ClearScreen()
	call ClearScreen
;> IntroDisplayPicCenteredOrUpperRight(RedPicFront, BANK(RedPicFront), 0)
	ld de, RedPicFront
	ld bc, ((BANK(RedPicFront)) & $ff) << 8 + (($00) & $ff)
	call IntroDisplayPicCenteredOrUpperRight
;> GBFadeInFromWhite()
	call GBFadeInFromWhite
;> if not wStatusFlags3:
	ld a, [wStatusFlags3]
	and a ; ???
	jr nz, .next
;>     PrintText(OakSpeechText3)
	ld hl, OakSpeechText3
	call PrintText
.next
;> # the player shrinks
;> bank = hLoadedROMBank
	ldh a, [hLoadedROMBank]
	push af
;> PlaySound(SFX_SHRINK)
	ld a, SFX_SHRINK
	call PlaySound
	pop af
; bug: switching ROM Bank should not happen outside of Home Bank
; This code does nothing, as PlaySound does all necessary Bank switch
; It looks like a leftover from an early development stage
;> hLoadedROMBank = bank                             # a needless bank switch back
	ldh [hLoadedROMBank], a
;> rROMB = bank
	ld [rROMB], a
;> DelayFrames(4)
	ld c, 4
	call DelayFrames
;> CopyVideoData(vSprites, RedSprite, BANK(RedSprite), 0x0C)
	ld de, RedSprite
	ld hl, vSprites
	ld bc, ((BANK(RedSprite)) & $ff) << 8 + (($0C) & $ff)
	call CopyVideoData
;> IntroDisplayPicCenteredOrUpperRight(ShrinkPic1, BANK(ShrinkPic1), 0)
	ld de, ShrinkPic1
	ld bc, ((BANK(ShrinkPic1)) & $ff) << 8 + (($00) & $ff)
	call IntroDisplayPicCenteredOrUpperRight
;> DelayFrames(4)
	ld c, 4
	call DelayFrames
;> IntroDisplayPicCenteredOrUpperRight(ShrinkPic2, BANK(ShrinkPic2), 0)
	ld de, ShrinkPic2
	ld bc, ((BANK(ShrinkPic2)) & $ff) << 8 + (($00) & $ff)
	call IntroDisplayPicCenteredOrUpperRight
;> ResetPlayerSpriteData()
	call ResetPlayerSpriteData
;> bank = hLoadedROMBank
	ldh a, [hLoadedROMBank]
	push af
;> wAudioROMBank = BANK(Music_PalletTown)
	ld a, BANK(Music_PalletTown)
	ld [wAudioROMBank], a
;> wAudioSavedROMBank = BANK(Music_PalletTown)
	ld [wAudioSavedROMBank], a
;> wAudioFadeOutControl = 10
	ld a, 10
	ld [wAudioFadeOutControl], a
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
	pop af
; bug: switching ROM Bank should not happen outside of Home Bank
;> hLoadedROMBank = bank
	ldh [hLoadedROMBank], a
;> rROMB = bank
	ld [rROMB], a
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> ClearScreenArea(coord(6, 5), 7, 7)
	ld hl, (5) * SCREEN_WIDTH + (6) + wTileMap
	ld b, 7
	ld c, 7
	call ClearScreenArea
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> wUpdateSpritesEnabled = 1
	ld a, 1
	ld [wUpdateSpritesEnabled], a
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> ClearScreen()
	jp ClearScreen

