;@ path: engine/movie/oak_speech/oak_speech
;@ def FadeInIntroPic()
;@ Fade the picture in through six palettes, 10 frames each.
;@ test: skip waits for frames
FadeInIntroPic:
;> for i in range(6):                            # the picture fades in
	ld hl, IntroFadePalettes
	ld b, 6
.next
;>     rBGP = mem[IntroFadePalettes + i]
	ld a, [hli]
	ldh [rBGP], a
;>     DelayFrames(10)
	ld c, 10
	call DelayFrames
	dec b
	jr nz, .next
	ret

;@ path: engine/movie/oak_speech/oak_speech
IntroFadePalettes:
	db ((1) << 6) | ((1) << 4) | ((1) << 2) | (0)
	db ((2) << 6) | ((2) << 4) | ((2) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((1) << 2) | (0)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)

;@ path: engine/movie/oak_speech/oak_speech
;@ def MovePicLeft()
;@ Slide the window (with the picture) in from the right, 8 pixels a frame.
;@ test: skip waits for frames
MovePicLeft:
;> rWX = 119
	ld a, 119
	ldh [rWX], a
;> DelayFrame()
	call DelayFrame

;> rBGP = 0b11100100
	ld a, %11100100
	ldh [rBGP], a
;> while True:
.next
;>     DelayFrame()
	call DelayFrame
;>     if u8(rWX - 8) == 0xFF:
;>         return
	ldh a, [rWX]
	sub 8
	cp $FF
	ret z
;>     rWX = u8(rWX - 8)
	ldh [rWX], a
	jr .next

;@ path: engine/movie/oak_speech/oak_speech
;@ def DisplayPicCenteredOrUpperRight()
;@ IntroDisplayPicCenteredOrUpperRight with the predef's registers.
;@ test: skip decompresses into VRAM
DisplayPicCenteredOrUpperRight:
;> _, de, bc = GetPredefRegisters()
;> IntroDisplayPicCenteredOrUpperRight(de, bc >> 8, bc & 0xFF)
	call GetPredefRegisters
;@ path: engine/movie/oak_speech/oak_speech
;@ def IntroDisplayPicCenteredOrUpperRight(pic: de, bank: b, upper_right: c)
;@ Decompress a picture into VRAM and show it in the middle of the screen, or at the top right.
;@ test: skip decompresses into VRAM
IntroDisplayPicCenteredOrUpperRight:
; b = bank
; de = address of compressed pic
; c: 0 = centred, non-zero = upper-right
;> UncompressSpriteFromDE(bank, pic)
	push bc
	ld a, b
	call UncompressSpriteFromDE
;> CopyData(sSpriteBuffer1, sSpriteBuffer0, 2 * SPRITEBUFFERSIZE)
	ld hl, sSpriteBuffer1
	ld de, sSpriteBuffer0
	ld bc, 2 * SPRITEBUFFERSIZE
	call CopyData
;> InterlaceMergeSpriteBuffers(vFrontPic)
	ld de, vFrontPic
	call InterlaceMergeSpriteBuffers
;> at = coord(15, 1)
	pop bc
	ld a, c
	and a
	ld hl, (1) * SCREEN_WIDTH + (15) + wTileMap
;> if not upper_right:
;>     at = coord(6, 4)
	jr nz, .next
	ld hl, (4) * SCREEN_WIDTH + (6) + wTileMap
.next
;> hStartTileID = 0
	xor a
	ldh [hStartTileID], a
;> CopyUncompressedPicToTilemap(at)              # through the predef table
	ld a, (CopyUncompressedPicToTilemapPredef - PredefPointers) / 3
	jp Predef
;@ path: engine/overworld/special_warps
;@ def PrepareForSpecialWarp()
;@ Before a warp that is not a plain warp tile (fly, dungeon warp, blackout, new game, link room): load the
;@ destination and its tileset, and remember the map to return to in wLastMap.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
PrepareForSpecialWarp::
;> LoadSpecialWarpData()
	call LoadSpecialWarpData
;> LoadTilesetHeader()                          # a predef
	ld a, (LoadTilesetHeaderPredef - PredefPointers) / 3
	call Predef
;> special = wStatusFlags6 & (1 << BIT_FLY_OR_DUNGEON_WARP)
	ld hl, wStatusFlags6
	bit BIT_FLY_OR_DUNGEON_WARP, [hl]
;> wStatusFlags6 = wStatusFlags6 & ~(1 << BIT_FLY_OR_DUNGEON_WARP) & 0xFF
	res BIT_FLY_OR_DUNGEON_WARP, [hl]
;> if special:
	jr z, .debugNewGameWarp
;>     last = wDestinationMap
	ld a, [wDestinationMap]
	jr .next
.debugNewGameWarp
;> else:                                        # a new game starts in front of the player's house
;>     if wStatusFlags6 & (1 << BIT_DEBUG_MODE):
	bit BIT_DEBUG_MODE, [hl]
	jr z, .setNewGameMatWarp ; apply to StartNewGameDebug only
;>         PrepareNewGameDebug()
	call PrepareNewGameDebug
.setNewGameMatWarp
	; This is called by OakSpeech during StartNewGame and
	; loads the first warp event for the specified map index.
;>     last = PALLET_TOWN
	ld a, PALLET_TOWN
.next
;> if wStatusFlags3:                            # then wStatusFlags3 itself is stored
;>     last = wStatusFlags3
	ld b, a
	ld a, [wStatusFlags3]
	and a ; ???
	jr nz, .next2
	ld a, b
.next2
;> if wStatusFlags6 & (1 << BIT_DUNGEON_WARP):
;>     return
	ld hl, wStatusFlags6
	bit BIT_DUNGEON_WARP, [hl]
	ret nz
;> wLastMap = last
	ld [wLastMap], a
	ret

;@ path: engine/overworld/special_warps
;@ def LoadSpecialWarpData()
;@ Load the destination of a special warp. Link rooms and a new game copy a fixed 8-byte entry (map, map
;@ view pointer, coordinates, tileset). A dungeon warp, a blackout (to wLastBlackoutMap) or Fly (to
;@ wDestinationMap) copy 6 bytes of position data from their tables, on the overworld tileset.
;@ test: wCableClubDestinationMap = [TRADE_CENTER, COLOSSEUM, 0][rand(0, 2)]; wStatusFlags6 = rand(0, 255) & ~(1 << BIT_DUNGEON_WARP); wDestinationMap = rand(0, 10); wLastBlackoutMap = rand(0, 10)
LoadSpecialWarpData:
;> src = None
;> if wCableClubDestinationMap == TRADE_CENTER:
	ld a, [wCableClubDestinationMap]
	cp TRADE_CENTER
	jr nz, .notTradeCenter
;>     src = TradeCenterPlayerWarp if hSerialConnectionStatus == USING_INTERNAL_CLOCK else TradeCenterFriendWarp
	ld hl, TradeCenterPlayerWarp
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr z, .copyWarpData
	ld hl, TradeCenterFriendWarp
	jr .copyWarpData
.notTradeCenter
;> elif wCableClubDestinationMap == COLOSSEUM:
	cp COLOSSEUM
	jr nz, .notColosseum
;>     src = ColosseumPlayerWarp if hSerialConnectionStatus == USING_INTERNAL_CLOCK else ColosseumFriendWarp
	ld hl, ColosseumPlayerWarp
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr z, .copyWarpData
	ld hl, ColosseumFriendWarp
	jr .copyWarpData
.notColosseum
;> elif not wStatusFlags6 & (1 << BIT_DEBUG_MODE | 1 << BIT_FLY_OR_DUNGEON_WARP):
	ld a, [wStatusFlags6]
	bit BIT_DEBUG_MODE, a
	; warp to wLastMap (PALLET_TOWN) for StartNewGameDebug
	jr nz, .notNewGameWarp
	bit BIT_FLY_OR_DUNGEON_WARP, a
	jr nz, .notNewGameWarp
;>     src = NewGameWarp
	ld hl, NewGameWarp
.copyWarpData
;> if src is not None:
;>@copy7     for i in range(7):                       # wCurMap, map view pointer, coordinates
	ld de, wCurMap
	ld c, $7
.copyWarpDataLoop
;>         mem[addr(wCurMap) + i] = mem[src + i]
	ld a, [hli]
	ld [de], a
	inc de
;=@copy7
	dec c
	jr nz, .copyWarpDataLoop
;>     wCurMapTileset = mem[src + 7]
	ld a, [hli]
	ld [wCurMapTileset], a
	xor a
	jr .done
.notNewGameWarp
;> else:
	ld a, [wLastMap] ; this value is overwritten before it's ever read
;>     if not wStatusFlags6 & (1 << BIT_DUNGEON_WARP):
	ld hl, wStatusFlags6
	bit BIT_DUNGEON_WARP, [hl]
	jr nz, .usedDungeonWarp
;>         escape = wStatusFlags6 & (1 << BIT_ESCAPE_WARP)
	bit BIT_ESCAPE_WARP, [hl]
;>         wStatusFlags6 = wStatusFlags6 & ~(1 << BIT_ESCAPE_WARP) & 0xFF
	res BIT_ESCAPE_WARP, [hl]
;>@dest         wCurMap = wLastBlackoutMap if escape else wDestinationMap   # a blackout, or Fly
	jr z, .otherDestination
	ld a, [wLastBlackoutMap]
;>@fly         p = FlyWarpDataPtr                   # entries: map, 0, pointer
	jr .usedFlyWarp
;>@flyloop         while mem[p] != wCurMap: p += 4
;>@flysrc         src = mem16[p + 2]
;>     else:                                    # a dungeon warp
;>         wStatusFlags3 = wStatusFlags3 & ~(1 << BIT_ON_DUNGEON_WARP) & 0xFF
.usedDungeonWarp
	ld hl, wStatusFlags3
	res BIT_ON_DUNGEON_WARP, [hl]
;>         wCurMap = wDungeonWarpDestinationMap
	ld a, [wDungeonWarpDestinationMap]
	ld b, a
	ld [wCurMap], a
;>         p, offset = DungeonWarpList, 0        # entries: map, which warp
	ld a, [wWhichDungeonWarp]
	ld c, a
	ld hl, DungeonWarpList
	ld de, 0
;>         wDungeonWarpDataEntrySize = 6
	ld a, 6
	ld [wDungeonWarpDataEntrySize], a
.dungeonWarpListLoop
;>@dsearch         while not (mem[p] == wCurMap and mem[p + 1] == wWhichDungeonWarp):
	ld a, [hli]
	cp b
	jr z, .matchedDungeonWarpDestinationMap
	inc hl
	jr .nextDungeonWarp
.matchedDungeonWarpDestinationMap
;=@dsearch
	ld a, [hli]
	cp c
	jr z, .matchedDungeonWarpID
.nextDungeonWarp
;>             p += 2
;>             offset = u8(offset + 6)
	ld a, [wDungeonWarpDataEntrySize]
	add e
	ld e, a
	jr .dungeonWarpListLoop
.matchedDungeonWarpID
;>         src = DungeonWarpData + offset
	ld hl, DungeonWarpData
	add hl, de
	jr .copyWarpData2
.otherDestination
;=@dest
	ld a, [wDestinationMap]
.usedFlyWarp
	ld b, a
	ld [wCurMap], a
;=@fly
	ld hl, FlyWarpDataPtr
.flyWarpDataPtrLoop
;=@flyloop
	ld a, [hli]
	inc hl
	cp b
	jr z, .foundFlyWarpMatch
;=@flyloop
	inc hl
	inc hl
	jr .flyWarpDataPtrLoop
.foundFlyWarpMatch
;=@flysrc
	ld a, [hli]
	ld h, [hl]
	ld l, a
.copyWarpData2
;>@copy6     for i in range(6):                       # map view pointer, coordinates
	ld de, wCurrentTileBlockMapViewPointer
	ld c, $6
.copyWarpDataLoop2
;>         mem[addr(wCurrentTileBlockMapViewPointer) + i] = mem[src + i]
	ld a, [hli]
	ld [de], a
	inc de
;=@copy6
	dec c
	jr nz, .copyWarpDataLoop2
;>     wCurMapTileset = OVERWORLD
	xor a ; OVERWORLD
	ld [wCurMapTileset], a
.done
;> wYOffsetSinceLastSpecialWarp = 0
	ld [wYOffsetSinceLastSpecialWarp], a
;> wXOffsetSinceLastSpecialWarp = 0
	ld [wXOffsetSinceLastSpecialWarp], a
;> wDestinationWarpID = 0xFF                    # not a normal warp
	ld a, -1 ; exclude normal warps
	ld [wDestinationWarpID], a
	ret

; Format: (size 2 bytes)
; 00: target map ID
; 01: which dungeon warp in the source map was used
;@ path: engine/overworld/special_warps
DungeonWarpList:
	db SEAFOAM_ISLANDS_B1F, 1
	db SEAFOAM_ISLANDS_B1F, 2
	db SEAFOAM_ISLANDS_B2F, 1
	db SEAFOAM_ISLANDS_B2F, 2
	db SEAFOAM_ISLANDS_B3F, 1
	db SEAFOAM_ISLANDS_B3F, 2
	db SEAFOAM_ISLANDS_B4F, 1
	db SEAFOAM_ISLANDS_B4F, 2
	db VICTORY_ROAD_2F,     2
	db POKEMON_MANSION_1F,  1
	db POKEMON_MANSION_1F,  2
	db POKEMON_MANSION_2F,  3
	db -1 ; end



;@ path: engine/overworld/special_warps
DungeonWarpData:
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B1F_WIDTH) + ((SEAFOAM_ISLANDS_B1F_WIDTH) + 6) * ((7) >> 1) + ((18) >> 1))
	db 7, 18
	db ((7) & $01)
	db ((18) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B1F_WIDTH) + ((SEAFOAM_ISLANDS_B1F_WIDTH) + 6) * ((7) >> 1) + ((23) >> 1))
	db 7, 23
	db ((7) & $01)
	db ((23) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * ((7) >> 1) + ((19) >> 1))
	db 7, 19
	db ((7) & $01)
	db ((19) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B2F_WIDTH) + ((SEAFOAM_ISLANDS_B2F_WIDTH) + 6) * ((7) >> 1) + ((22) >> 1))
	db 7, 22
	db ((7) & $01)
	db ((22) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * ((7) >> 1) + ((18) >> 1))
	db 7, 18
	db ((7) & $01)
	db ((18) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B3F_WIDTH) + ((SEAFOAM_ISLANDS_B3F_WIDTH) + 6) * ((7) >> 1) + ((19) >> 1))
	db 7, 19
	db ((7) & $01)
	db ((19) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B4F_WIDTH) + ((SEAFOAM_ISLANDS_B4F_WIDTH) + 6) * ((14) >> 1) + ((4) >> 1))
	db 14, 4
	db ((14) & $01)
	db ((4) & $01)
	dw (wOverworldMap + 7 + (SEAFOAM_ISLANDS_B4F_WIDTH) + ((SEAFOAM_ISLANDS_B4F_WIDTH) + 6) * ((14) >> 1) + ((5) >> 1))
	db 14, 5
	db ((14) & $01)
	db ((5) & $01)
	dw (wOverworldMap + 7 + (VICTORY_ROAD_2F_WIDTH) + ((VICTORY_ROAD_2F_WIDTH) + 6) * ((16) >> 1) + ((22) >> 1))
	db 16, 22
	db ((16) & $01)
	db ((22) & $01)
	dw (wOverworldMap + 7 + (POKEMON_MANSION_1F_WIDTH) + ((POKEMON_MANSION_1F_WIDTH) + 6) * ((14) >> 1) + ((16) >> 1))
	db 14, 16
	db ((14) & $01)
	db ((16) & $01)
	dw (wOverworldMap + 7 + (POKEMON_MANSION_1F_WIDTH) + ((POKEMON_MANSION_1F_WIDTH) + 6) * ((14) >> 1) + ((16) >> 1))
	db 14, 16
	db ((14) & $01)
	db ((16) & $01)
	dw (wOverworldMap + 7 + (POKEMON_MANSION_2F_WIDTH) + ((POKEMON_MANSION_2F_WIDTH) + 6) * ((14) >> 1) + ((18) >> 1))
	db 14, 18
	db ((14) & $01)
	db ((18) & $01)



;@ path: engine/overworld/special_warps
NewGameWarp:
	db REDS_HOUSE_2F
	dw (wOverworldMap + 7 + (REDS_HOUSE_2F_WIDTH) + ((REDS_HOUSE_2F_WIDTH) + 6) * ((6) >> 1) + ((3) >> 1))
	db 6, 3
	db ((6) & $01)
	db ((3) & $01)
	db REDS_HOUSE_2
;@ path: engine/overworld/special_warps
TradeCenterPlayerWarp:
	db TRADE_CENTER
	dw (wOverworldMap + 7 + (TRADE_CENTER_WIDTH) + ((TRADE_CENTER_WIDTH) + 6) * ((4) >> 1) + ((3) >> 1))
	db 4, 3
	db ((4) & $01)
	db ((3) & $01)
	db CLUB
;@ path: engine/overworld/special_warps
TradeCenterFriendWarp:
	db TRADE_CENTER
	dw (wOverworldMap + 7 + (TRADE_CENTER_WIDTH) + ((TRADE_CENTER_WIDTH) + 6) * ((4) >> 1) + ((6) >> 1))
	db 4, 6
	db ((4) & $01)
	db ((6) & $01)
	db CLUB
;@ path: engine/overworld/special_warps
ColosseumPlayerWarp:
	db COLOSSEUM
	dw (wOverworldMap + 7 + (COLOSSEUM_WIDTH) + ((COLOSSEUM_WIDTH) + 6) * ((4) >> 1) + ((3) >> 1))
	db 4, 3
	db ((4) & $01)
	db ((3) & $01)
	db CLUB
;@ path: engine/overworld/special_warps
ColosseumFriendWarp:
	db COLOSSEUM
	dw (wOverworldMap + 7 + (COLOSSEUM_WIDTH) + ((COLOSSEUM_WIDTH) + 6) * ((4) >> 1) + ((6) >> 1))
	db 4, 6
	db ((4) & $01)
	db ((6) & $01)
	db CLUB



;@ path: engine/overworld/special_warps
FlyWarpDataPtr:
	db PALLET_TOWN, 0
	dw .PalletTown
	db VIRIDIAN_CITY, 0
	dw .ViridianCity
	db PEWTER_CITY, 0
	dw .PewterCity
	db CERULEAN_CITY, 0
	dw .CeruleanCity
	db LAVENDER_TOWN, 0
	dw .LavenderTown
	db VERMILION_CITY, 0
	dw .VermilionCity
	db CELADON_CITY, 0
	dw .CeladonCity
	db FUCHSIA_CITY, 0
	dw .FuchsiaCity
	db CINNABAR_ISLAND, 0
	dw .CinnabarIsland
	db INDIGO_PLATEAU, 0
	dw .IndigoPlateau
	db SAFFRON_CITY, 0
	dw .SaffronCity
	db ROUTE_4, 0
	dw .Route4
	db ROUTE_10, 0
	dw .Route10

.PalletTown:
	dw (wOverworldMap + 7 + (PALLET_TOWN_WIDTH) + ((PALLET_TOWN_WIDTH) + 6) * ((6) >> 1) + ((5) >> 1))
