	db ((26) & $01)
	db ((23) & $01)
.PewterCity:
	dw (wOverworldMap + 7 + (PEWTER_CITY_WIDTH) + ((PEWTER_CITY_WIDTH) + 6) * ((26) >> 1) + ((13) >> 1))
	db 26, 13
	db ((26) & $01)
	db ((13) & $01)
