.CeladonCity:
	dw (wOverworldMap + 7 + (CELADON_CITY_WIDTH) + ((CELADON_CITY_WIDTH) + 6) * ((10) >> 1) + ((41) >> 1))
	db 10, 41
	db ((10) & $01)
	db ((41) & $01)
.FuchsiaCity:
	dw (wOverworldMap + 7 + (FUCHSIA_CITY_WIDTH) + ((FUCHSIA_CITY_WIDTH) + 6) * ((28) >> 1) + ((19) >> 1))
	db 28, 19
	db ((28) & $01)
	db ((19) & $01)
.CinnabarIsland:
	dw (wOverworldMap + 7 + (CINNABAR_ISLAND_WIDTH) + ((CINNABAR_ISLAND_WIDTH) + 6) * ((12) >> 1) + ((11) >> 1))
	db 12, 11
	db ((12) & $01)
	db ((11) & $01)
.IndigoPlateau:
	dw (wOverworldMap + 7 + (INDIGO_PLATEAU_WIDTH) + ((INDIGO_PLATEAU_WIDTH) + 6) * ((6) >> 1) + ((9) >> 1))
	db 6, 9
	db ((6) & $01)
	db ((9) & $01)
.SaffronCity:
	dw (wOverworldMap + 7 + (SAFFRON_CITY_WIDTH) + ((SAFFRON_CITY_WIDTH) + 6) * ((30) >> 1) + ((9) >> 1))
	db 30, 9
	db ((30) & $01)
	db ((9) & $01)
.Route4:
	dw (wOverworldMap + 7 + (ROUTE_4_WIDTH) + ((ROUTE_4_WIDTH) + 6) * ((6) >> 1) + ((11) >> 1))
	db 6, 11
	db ((6) & $01)
	db ((11) & $01)
.Route10:
	dw (wOverworldMap + 7 + (ROUTE_10_WIDTH) + ((ROUTE_10_WIDTH) + 6) * ((20) >> 1) + ((11) >> 1))
	db 20, 11
	db ((20) & $01)
	db ((11) & $01)
;@ path: engine/debug/debug_party
;@ def SetDebugNewGameParty()
;@ Debug: add the Pokémon of DebugNewGameParty (species, level pairs up to -1) to the party.
;@ test: skip adds Pokémon through AddPartyMon
SetDebugNewGameParty: ; unreferenced except in _DEBUG
;> entry = DebugNewGameParty
	ld de, DebugNewGameParty
.loop
;> while mem[entry] != 0xFF:
	ld a, [de]
	cp -1
	ret z
;>     wCurPartySpecies = mem[entry]
	ld [wCurPartySpecies], a
;>     wCurEnemyLevel = mem[entry + 1]
	inc de
	ld a, [de]
	ld [wCurEnemyLevel], a
;>     entry += 2
	inc de
;>     AddPartyMon()
	call AddPartyMon
	jr .loop

;@ path: engine/debug/debug_party
DebugNewGameParty: ; unreferenced except in _DEBUG
	; Exeggutor is the only debug party member shared with Red, Green, and Japanese Blue.
	; "Tsunekazu Ishihara: Exeggutor is my favorite. That's because I was
	; always using this character while I was debugging the program."
	; From https://web.archive.org/web/20000607152840/http://pocket.ign.com/news/14973.html
	db EXEGGUTOR, 90
	db MEW, 20
	db JOLTEON, 56
	db DUGTRIO, 56
	db ARTICUNO, 57
	db -1 ; end

;@ path: engine/debug/debug_party
;@ def PrepareNewGameDebug()
;@ Debug: start a new game with a strong party, the HMs, all badges but the Earth Badge, items, every town
;@ visited and a full Pokédex. Only debug builds assemble it; here it just returns.
PrepareNewGameDebug: ; dummy except in _DEBUG
;> return
	ret
;@ def AskName()
;@ After a catch or a trade: "Do you want to give a nickname to <MON>?" YES opens the naming screen; NO, or no
;@ name entered, gives the species name. The name goes where the predef's hl points.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/menus/naming_screen
AskName:
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> dest, _, _ = GetPredefRegisters()
	call GetPredefRegisters
	push hl
;> if wIsInBattle == 1:                        # a wild battle: clear the enemy's HUD for the text box
;>     ClearScreenArea(coord(0, 0), 11, 4)
	ld a, [wIsInBattle]
	dec a
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 11
	call z, ClearScreenArea ; only if in wild battle
;> wNamedObjectIndex = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> PrintText(DoYouWantToNicknameText)
	ld hl, DoYouWantToNicknameText
	call PrintText
;> wTextBoxID = TWO_OPTION_MENU                # YES/NO at coord(14, 7)
;> DisplayTextBoxID()
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID
;> if wCurrentMenuItem == 0:                   # YES
	pop hl
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .declinedNickname
;>     sprites = wUpdateSpritesEnabled
	ld a, [wUpdateSpritesEnabled]
	push af
;>     wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;>     wNamingScreenType = NAME_MON_SCREEN
;>     DisplayNamingScreen(dest)
	push hl
	ld a, NAME_MON_SCREEN
	ld [wNamingScreenType], a
	call DisplayNamingScreen
;>     if not wIsInBattle:
;>         ReloadMapSpriteTilePatterns()
	ld a, [wIsInBattle]
	and a
	jr nz, .inBattle
	call ReloadMapSpriteTilePatterns
.inBattle
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     wUpdateSpritesEnabled = sprites
	pop hl
	pop af
	ld [wUpdateSpritesEnabled], a
;>     if mem[addr(wStringBuffer)] != 0x50:    # a name was entered
;>         return
	ld a, [wStringBuffer]
	cp '@'
	ret nz
.declinedNickname
;> return CopyData(addr(wNameBuffer), dest, NAME_LENGTH)
	ld d, h
	ld e, l
	ld hl, wNameBuffer
	ld bc, NAME_LENGTH
	jp CopyData

;@ path: engine/menus/naming_screen
DoYouWantToNicknameText:
	db TX_FAR
	dw _DoYouWantToNicknameText
	db BANK(_DoYouWantToNicknameText)
	db TX_END

;@ def DisplayNameRaterScreen() -> carry
;@ The Name Rater's naming screen for party Pokémon wWhichPokemon: the new nickname replaces the old one. Carry if
;@ no name was entered.
;@ path: engine/menus/naming_screen
DisplayNameRaterScreen::
;> dest = addr(wBuffer)                         # the new name goes here first
	ld hl, wBuffer
;> wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;> wNamingScreenType = NAME_MON_SCREEN
	ld a, NAME_MON_SCREEN
	ld [wNamingScreenType], a
;> DisplayNamingScreen(addr(wBuffer))
	call DisplayNamingScreen
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;> LoadGBPal()
	call LoadGBPal
;> if mem[addr(wStringBuffer)] == 0x50:
;>     return True
	ld a, [wStringBuffer]
	cp '@'
	jr z, .playerCancelled
;> nick = AddNTimes(addr(wPartyMonNicks), NAME_LENGTH, wWhichPokemon)
	ld hl, wPartyMonNicks
	ld bc, NAME_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;> CopyData(addr(wBuffer), nick, NAME_LENGTH)
	ld e, l
	ld d, h
	ld hl, wBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> return False
	and a
	ret
.playerCancelled
	scf
	ret

;@ def DisplayNamingScreen(dest: hl)
;@ The naming screen (wNamingScreenType: the player, the rival or a Pokémon). The D-pad moves over the letter grid
;@ (wrapping round), A types a letter or presses ED or the case switch, B deletes the last letter, SELECT switches
;@ case, START or ED finish. The name (or just '@' if empty) is copied to dest.
;@ path: engine/menus/naming_screen
DisplayNamingScreen:
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	push hl
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> RunPaletteCommand(SET_PAL_GENERIC)
	ld b, SET_PAL_GENERIC
	call RunPaletteCommand
;> LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;> LoadEDTile()
	call LoadEDTile
;> farcall(LoadMonPartySpriteGfx)
	ld b, BANK(LoadMonPartySpriteGfx)
	ld hl, LoadMonPartySpriteGfx
	call Bankswitch
;> TextBoxBorder(coord(0, 4), 9, 18)
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 9
	ld c, 18
	call TextBoxBorder
;> PrintNamingText()
	call PrintNamingText
;> wTopMenuItemY = 3
	ld a, 3
	ld [wTopMenuItemY], a
;> wTopMenuItemX = wLastMenuItem = wCurrentMenuItem = 1
	ld a, 1
	ld [wTopMenuItemX], a
	ld [wLastMenuItem], a
	ld [wCurrentMenuItem], a
;> wMenuWatchedKeys = 0xFF
	ld a, $ff
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 7
	ld a, 7
	ld [wMaxMenuItem], a
;> mem[addr(wStringBuffer)] = 0x50             # empty
	ld a, '@'
	ld [wStringBuffer], a
;> wNamingScreenSubmitName = 0
	xor a
	ld hl, wNamingScreenSubmitName
	ld [hli], a
;> mem[addr(wNamingScreenSubmitName) + 1] = 0  # upper case
	ld [hli], a
;> wAnimCounter = 0
;> redraw = 'alphabet'                         # what to redraw before the next key
	ld [wAnimCounter], a
;>@main while True:
;>     if redraw == 'alphabet':
.selectReturnPoint
;>         PrintAlphabet()
	call PrintAlphabet
;>         GBPalNormal()
	call GBPalNormal
;>@nc     if redraw != 'cursor':
.ABStartReturnPoint
;>         if wNamingScreenSubmitName:
;>             break
	ld a, [wNamingScreenSubmitName]
	and a
	jr nz, .submitNickname
;>         PrintNicknameAndUnderscores()
	call PrintNicknameAndUnderscores
.dPadReturnPoint
;>     PlaceMenuCursor(coord(0, 0))            # (hl only matters for a menu at row 0)
	call PlaceMenuCursor
;>     while True:
.inputLoop
;>         item = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	push af
;>         farcall(AnimatePartyMon_ForceSpeed1)            # the Pokémon icon hops
	ld b, BANK(AnimatePartyMon_ForceSpeed1)
	ld hl, AnimatePartyMon_ForceSpeed1
	call Bankswitch
;>         wCurrentMenuItem = item
	pop af
	ld [wCurrentMenuItem], a
;>         JoypadLowSensitivity()
	call JoypadLowSensitivity
;>         if hJoyPressed:
;>             break
	ldh a, [hJoyPressed]
	and a
	jr z, .inputLoop
;>     keys = hJoyPressed
;>     p = label('DisplayNamingScreen.namingScreenButtonFunctions')   # 4 bytes per key: return point, handler
	ld hl, .namingScreenButtonFunctions
.checkForPressedButton
;>@sc     for n in range(8):
;>         if keys << n & 0x80:                # the highest key bit pressed picks the entry
;>             break
	sla a
	jr c, .foundPressedButton
;>         p += 4
	inc hl
	inc hl
	inc hl
	inc hl
;=@sc
	jr .checkForPressedButton
.foundPressedButton
;>     redraw = 'cursor' if keys & (PAD_DOWN | PAD_UP | PAD_LEFT | PAD_RIGHT) else 'alphabet' if keys & PAD_SELECT else 'name'   # where its handler returns to
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;>     x = None                                # a new cursor column, if any
;>     if keys & PAD_DOWN:                     # the key's handler:
	ld a, [hli]
	ld h, [hl]
	ld l, a
	push de
	jp hl
;>@dn1         wCurrentMenuItem += 1
;>@dn2         if wCurrentMenuItem == 7:           # past the bottom row: the top row
;>@dn3             wCurrentMenuItem = 1
;>@dn4             x = 1
;>@dn5         elif wCurrentMenuItem == 6:         # the case switch row has one column
;>@dn6             x = 1
;>@cup     elif keys & PAD_UP:
;>@up1         wCurrentMenuItem -= 1
;>@up2         if wCurrentMenuItem == 0:
;>@up3             wCurrentMenuItem = 6            # round to the bottom row
;>@up4             x = 1
;>@cleft     elif keys & PAD_LEFT:
;>@lf1         if wCurrentMenuItem != 6:           # (the case switch row has one column)
;>@lf2             if wTopMenuItemX == 1:
;>@lf3                 x = 0x11                    # round to the last column
;>@lf4             else:
;>@lf5                 x = (wTopMenuItemX - 2) & 0xFF
;>@cright     elif keys & PAD_RIGHT:
;>@rt1         if wCurrentMenuItem != 6:
;>@rt2             if wTopMenuItemX == 0x11:
;>@rt3                 x = 1                       # round to the first column
;>@rt4             else:
;>@rt5                 x = (wTopMenuItemX + 2) & 0xFF
;>@cstart     elif keys & PAD_START:
;>@st1         wNamingScreenSubmitName = 1
;>@csel     elif keys & PAD_SELECT:
;>@sel1         wAlphabetCase ^= 1                  # the other case
;>@cb     elif keys & PAD_B:
;>@b1         if wNamingScreenNameLength:
;>@b2             _, end = CalcStringLength()
;>@b3             mem[end - 1] = 0x50                 # the last letter goes
;>@ca     else:                                   # A
;>@a1         if wCurrentMenuItem == 5 and wTopMenuItemX == 0x11:      # on ED
;>@a2             wNamingScreenSubmitName = 1     # (the START code)
;>@a3         elif wCurrentMenuItem == 6 and wTopMenuItemX == 1:       # on the case switch
;>@a4             redraw = 'alphabet'
;>@a5             wAlphabetCase ^= 1              # (the SELECT code)
;>@a6         else:                               # on a letter
;>@a7             cursor = mem16[addr(wMenuCursorLocation)]
;>@a7b             wNamingScreenLetter = mem[cursor + 1]      # the letter under the cursor
;>@a8             _, end = CalcStringLength()
;>@a9             if wNamingScreenLetter in (0xE5, 0xE4):      # a dakuten / handakuten mark changes the last kana
;>@a10                 add = DakutensAndHandakutens(Dakutens if wNamingScreenLetter == 0xE5 else Handakutens)
;>@a11                 if add:
;>@a12                     end -= 1                # the marked kana replaces the last letter
;>@a13             elif wNamingScreenType >= NAME_MON_SCREEN:
;>@a14                 add = wNamingScreenNameLength < NAME_LENGTH - 1
;>@a15             else:
;>@a16                 add = wNamingScreenNameLength < PLAYER_NAME_LENGTH - 1
;>@a17             if add:
;>@a18                 mem[end] = wNamingScreenLetter
;>@a19                 mem[end + 1] = 0x50
;>@a20                 PlaySound(SFX_PRESS_AB)
;>@xs     if x is not None:
;>@xt         wTopMenuItemX = x
;>@xe         EraseMenuCursor()
.submitNickname
;> CopyData(addr(wStringBuffer), dest, NAME_LENGTH)
	pop de
	ld hl, wStringBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> ClearSprites()
	call ClearSprites
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> GBPalNormal()
	call GBPalNormal
;> wAnimCounter = 0
	xor a
	ld [wAnimCounter], a
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> if not wIsInBattle:
;>     return LoadTextBoxTilePatterns()
	ld a, [wIsInBattle]
	and a
	jp z, LoadTextBoxTilePatterns
;> return farcall(LoadHudTilePatterns)
	ld hl, LoadHudTilePatterns
	ld b, BANK(LoadHudTilePatterns)
	jp Bankswitch

.namingScreenButtonFunctions
	dw .dPadReturnPoint
	dw .pressedDown
	dw .dPadReturnPoint
	dw .pressedUp
	dw .dPadReturnPoint
	dw .pressedLeft
	dw .dPadReturnPoint
	dw .pressedRight
	dw .ABStartReturnPoint
	dw .pressedStart
	dw .selectReturnPoint
	dw .pressedSelect
	dw .ABStartReturnPoint
	dw .pressedB
	dw .ABStartReturnPoint
	dw .pressedA

.pressedA_changedCase
;=@a4
	pop de
	ld de, .selectReturnPoint
	push de
.pressedSelect
;=@sel1
	ld a, [wAlphabetCase]
	xor $1
	ld [wAlphabetCase], a
	ret

.pressedStart
;=@st1
	ld a, 1
	ld [wNamingScreenSubmitName], a
	ret

.pressedA
;=@a1
	ld a, [wCurrentMenuItem]
	cp $5 ; "ED" row
	jr nz, .didNotPressED
	ld a, [wTopMenuItemX]
	cp $11 ; "ED" column
	jr z, .pressedStart
.didNotPressED
;=@a3
	ld a, [wCurrentMenuItem]
	cp $6 ; case switch row
	jr nz, .didNotPressCaseSwitch
	ld a, [wTopMenuItemX]
	cp $1 ; case switch column
	jr z, .pressedA_changedCase
.didNotPressCaseSwitch
;=@a7
	ld hl, wMenuCursorLocation
	ld a, [hli]
	ld h, [hl]
	ld l, a
;=@a7b
	inc hl
	ld a, [hl]
	ld [wNamingScreenLetter], a
;=@a8
	call CalcStringLength
;=@a9
	ld a, [wNamingScreenLetter]
	cp 'ﾞ'
	ld de, Dakutens
	jr z, .dakutensAndHandakutens
;=@a9
	cp 'ﾟ'
	ld de, Handakutens
	jr z, .dakutensAndHandakutens
;=@a13
	ld a, [wNamingScreenType]
	cp NAME_MON_SCREEN
	jr nc, .checkMonNameLength
;=@a16
	ld a, [wNamingScreenNameLength]
	cp PLAYER_NAME_LENGTH - 1
	jr .checkNameLength
.checkMonNameLength
;=@a14
	ld a, [wNamingScreenNameLength]
	cp NAME_LENGTH - 1
.checkNameLength
;=@a17
	jr c, .addLetter
	ret

.dakutensAndHandakutens
;=@a10
	push hl
	call DakutensAndHandakutens
	pop hl
;=@a11
	ret nc
;=@a12
	dec hl
.addLetter
;=@a18
	ld a, [wNamingScreenLetter]
	ld [hli], a
;=@a19
	ld [hl], '@'
;=@a20
	ld a, SFX_PRESS_AB
	call PlaySound
	ret
.pressedB
;=@b1
	ld a, [wNamingScreenNameLength]
	and a
	ret z
;=@b2
	call CalcStringLength
;=@b3
	dec hl
	ld [hl], '@'
	ret
.pressedRight
;=@rt1
	ld a, [wCurrentMenuItem]
	cp $6
	ret z ; can't scroll right on bottom row
;=@rt2
	ld a, [wTopMenuItemX]
	cp $11 ; max
	jp z, .wrapToFirstColumn
;=@rt5
	inc a
	inc a
	jr .done
.wrapToFirstColumn
;=@rt3
	ld a, $1
	jr .done
.pressedLeft
;=@lf1
	ld a, [wCurrentMenuItem]
	cp $6
	ret z ; can't scroll right on bottom row
;=@lf2
	ld a, [wTopMenuItemX]
	dec a
	jp z, .wrapToLastColumn
;=@lf5
	dec a
	jr .done
.wrapToLastColumn
;=@lf3
	ld a, $11 ; max
	jr .done
.pressedUp
;=@up1
	ld a, [wCurrentMenuItem]
	dec a
	ld [wCurrentMenuItem], a
;=@up2
	and a
	ret nz
;=@up3
	ld a, $6 ; wrap to bottom row
	ld [wCurrentMenuItem], a
;=@up4
	ld a, $1 ; force left column
	jr .done
.pressedDown
;=@dn1
	ld a, [wCurrentMenuItem]
	inc a
	ld [wCurrentMenuItem], a
;=@dn2
	cp $7
	jr nz, .wrapToTopRow
;=@dn3
	ld a, $1
	ld [wCurrentMenuItem], a
;=@dn4
	jr .done
.wrapToTopRow
;=@dn5
	cp $6
	ret nz
;=@dn6
	ld a, $1
.done
;=@xt
	ld [wTopMenuItemX], a
;=@xe
	jp EraseMenuCursor

;@ def LoadEDTile()
;@ Copy the ED tile (the naming screen's END key) to tile $70 of the font in VRAM.
;@ path: engine/menus/naming_screen
LoadEDTile:
;> CopyVideoDataDouble(vFont + 0x70 * 16, ED_Tile, 0, (ED_TileEnd - ED_Tile) // 8)     # bank 0 works only by luck
	ld de, ED_Tile
	ld hl, vFont + TILE_SIZE * $70
	; BUG: BANK("Home") should be BANK(ED_Tile), although it coincidentally works as-is
	ld bc, ((BANK("Home")) & $ff) << 8 + (((ED_TileEnd - ED_Tile) / TILE_1BPP_SIZE) & $ff)
	jp CopyVideoDataDouble

;@ path: engine/menus/naming_screen
ED_Tile:
	db $f0, $c0, $f0, $ce, $fd, $0d, $0d, $0e
;@ path: engine/menus/naming_screen
ED_TileEnd:

;@ def PrintAlphabet()
;@ The letter grid of the naming screen in the current case: 5 rows of 9 letters, every other column, then the
;@ bottom row (the rest of the alphabet string).
;@ path: engine/menus/naming_screen
PrintAlphabet:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> src = LowerCaseAlphabet if wAlphabetCase else UpperCaseAlphabet
	ld a, [wAlphabetCase]
	and a
	ld de, LowerCaseAlphabet
	jr nz, .lowercase
	ld de, UpperCaseAlphabet
.lowercase
;> dest = coord(2, 5)
	ld hl, (5) * SCREEN_WIDTH + (2) + wTileMap
	; 5 rows, 9 columns
;> for row in range(5):
	ld bc, ((5) & $ff) << 8 + ((9) & $ff)
.outerLoop
;>     for col in range(9):
	push bc
.innerLoop
;>         mem[dest] = mem[src]
	ld a, [de]
	ld [hli], a
;>         dest += 2
	inc hl
;>         src += 1
	inc de
	dec c
	jr nz, .innerLoop
;>     dest += SCREEN_WIDTH + 2                # two rows down
	ld bc, SCREEN_WIDTH + 2
	add hl, bc
	pop bc
	dec b
	jr nz, .outerLoop
;> PlaceString(src, dest)
	call PlaceString
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> return Delay3()
	jp Delay3

;@ path: engine/menus/naming_screen
LowerCaseAlphabet:
	db "abcdefghi"
	db "jklmnopqr"
	db "stuvwxyz "
	db "×():;[]<PK><MN>"
	db "-?!♂♀/<DOT>,<ED>"
	db "UPPER CASE@"

;@ path: engine/menus/naming_screen
UpperCaseAlphabet:
	db "ABCDEFGHI"
	db "JKLMNOPQR"
	db "STUVWXYZ "
	db "×():;[]<PK><MN>"
	db "-?!♂♀/<DOT>,<ED>"
	db "lower case@"

;@ def PrintNicknameAndUnderscores()
;@ The name typed so far over a row of underscores (7 for a player's name, 10 for a Pokémon's), the next place
;@ raised. A full name moves the cursor onto ED.
;@ path: engine/menus/naming_screen
PrintNicknameAndUnderscores:
;> length, _ = CalcStringLength()
	call CalcStringLength
;> wNamingScreenNameLength = length
	ld a, c
	ld [wNamingScreenNameLength], a
;> ClearScreenArea(coord(10, 2), 10, 1)
	ld hl, (2) * SCREEN_WIDTH + (10) + wTileMap
	ld bc, ((1) & $ff) << 8 + ((10) & $ff)
	call ClearScreenArea
;> PlaceString(addr(wStringBuffer), coord(10, 2))
	ld hl, (2) * SCREEN_WIDTH + (10) + wTileMap
	ld de, wStringBuffer
	call PlaceString
;> pos = coord(10, 3)
	ld hl, (3) * SCREEN_WIDTH + (10) + wTileMap
;> most = NAME_LENGTH - 1 if wNamingScreenType >= NAME_MON_SCREEN else PLAYER_NAME_LENGTH - 1
	ld a, [wNamingScreenType]
	cp NAME_MON_SCREEN
	jr nc, .pokemon
; player or rival
	ld b, PLAYER_NAME_LENGTH - 1
	jr .gotUnderscoreCount
.pokemon
	ld b, NAME_LENGTH - 1
.gotUnderscoreCount
;> for i in range(most):
;>     mem[pos + i] = 0x76                     # underscore
	ld a, $76 ; underscore tile id
.placeUnderscoreLoop
	ld [hli], a
	dec b
	jr nz, .placeUnderscoreLoop
;> mon = wNamingScreenType >= NAME_MON_SCREEN
	ld a, [wNamingScreenType]
	cp NAME_MON_SCREEN
;> raised = wNamingScreenNameLength            # the next place
	ld a, [wNamingScreenNameLength]
;> if raised == most:                          # the name is full
	jr nc, .pokemon2
; player or rival
	cp PLAYER_NAME_LENGTH - 1
	jr .checkEmptySpaces
.pokemon2
	cp NAME_LENGTH - 1
.checkEmptySpaces
	jr nz, .placeRaisedUnderscore ; jump if empty spaces remain
	; when all spaces are filled, force the cursor onto the ED tile,
	; and keep the last underscore raised
;>     EraseMenuCursor()
	call EraseMenuCursor
;>     wTopMenuItemX = 0x11                    # ED
	ld a, $11 ; "ED" x coord
	ld [wTopMenuItemX], a
;>     wCurrentMenuItem = 5
	ld a, $5 ; "ED" y coord
	ld [wCurrentMenuItem], a
;>     raised = most - 1
	ld a, [wNamingScreenType]
	cp NAME_MON_SCREEN
	ld a, NAME_LENGTH - 2
	jr nc, .placeRaisedUnderscore
	ld a, PLAYER_NAME_LENGTH - 2
.placeRaisedUnderscore
;> mem[coord(10, 3) + raised] = 0x77           # raised underscore
	ld c, a
	ld b, $0
	ld hl, (3) * SCREEN_WIDTH + (10) + wTileMap
	add hl, bc
	ld [hl], $77 ; raised underscore tile id
	ret

;@ def DakutensAndHandakutens(table: de) -> carry
;@ The Japanese naming screen's ゛ and ゜ keys: look the last character typed up in `table` (pairs of before and
;@ after) and put the marked character in wNamingScreenLetter. Carry if it can take the mark.
;@ test: mem[wStringBuffer + rand(1, 10)] = 0x50; table = rand_ram(20); mem[table + 2 * rand(0, 8)] = 0xFF
;@ path: engine/menus/naming_screen
DakutensAndHandakutens:
;> n, end = CalcStringLength()
	push de
	call CalcStringLength
;> index, entry, found = IsInArray(mem[end - 1], table, 2)
	dec hl
	ld a, [hl]
	pop hl
	ld de, $2
	call IsInArray
;> if not found:
;>     return False
	ret nc
;> wNamingScreenLetter = mem[entry + 1]        # the marked character
	inc hl
	ld a, [hl]
	ld [wNamingScreenLetter], a
;> return True
	ret

;@ path: engine/menus/naming_screen
Dakutens:
	db "かが", "きぎ", "くぐ", "けげ", "こご"
	db "さざ", "しじ", "すず", "せぜ", "そぞ"
	db "ただ", "ちぢ", "つづ", "てで", "とど"
	db "はば", "ひび", "ふぶ", "へべ", "ほぼ"
	db "カガ", "キギ", "クグ", "ケゲ", "コゴ"
	db "サザ", "シジ", "スズ", "セゼ", "ソゾ"
	db "タダ", "チヂ", "ツヅ", "テデ", "トド"
	db "ハバ", "ヒビ", "フブ", "へべ", "ホボ"
	db -1 ; end

;@ path: engine/menus/naming_screen
Handakutens:
	db "はぱ", "ひぴ", "ふぷ", "へぺ", "ほぽ"
	db "ハパ", "ヒピ", "フプ", "へぺ", "ホポ"
	db -1 ; end

; calculates the length of the string at wStringBuffer and stores it in c
;@ def CalcStringLength() -> (c, hl)
;@ The length of the name being typed in wStringBuffer (up to its '@'), and the address of the '@'.
;@ test: mem[wStringBuffer + rand(0, 15)] = 0x50
;@ path: engine/menus/naming_screen
CalcStringLength:
;> p = wStringBuffer
	ld hl, wStringBuffer
;> n = 0
	ld c, $0
;> while mem[p] != 0x50:
.loop
	ld a, [hl]
	cp '@'
	ret z
;>     p += 1
	inc hl
;>     n += 1
	inc c
	jr .loop
;> return (n & 0xFF, p)

;@ def PrintNamingText()
;@ The naming screen's title: "YOUR NAME?", "RIVAL's NAME?", or the Pokémon's icon and "<MON>'s NICKNAME?".
;@ path: engine/menus/naming_screen
PrintNamingText:
;> pos = coord(0, 1)
	ld hl, (1) * SCREEN_WIDTH + (0) + wTileMap
;> kind = wNamingScreenType
	ld a, [wNamingScreenType]
;> nickname = False
;> text = YourTextString                       # the player
	ld de, YourTextString
;> if kind != 0:
	and a
	jr z, .notNickname
;>     text = RivalsTextString                 # the rival
	ld de, RivalsTextString
;>     nickname = kind != 1                    # or a Pokémon
	dec a
	jr z, .notNickname
;> if nickname:
;>     species = wCurPartySpecies
	ld a, [wCurPartySpecies]
;>     wMonPartySpriteSpecies = species
	ld [wMonPartySpriteSpecies], a
;>     farcall(WriteMonPartySpriteOAMBySpecies)   # its icon
	push af
	ld b, BANK(WriteMonPartySpriteOAMBySpecies)
	ld hl, WriteMonPartySpriteOAMBySpecies
	call Bankswitch
	pop af
;>     wNamedObjectIndex = species
	ld [wNamedObjectIndex], a
;>     end, _ = PlaceString(GetMonName(), coord(4, 1))
	call GetMonName
	ld hl, (1) * SCREEN_WIDTH + (4) + wTileMap
	call PlaceString
;>     mem[end + 1] = 0xC9                     # 'の', a blank tile outside Japan
	ld hl, $1
	add hl, bc
	ld [hl], 'の' ; leftover from Japanese version; blank tile $c9 in English
;>     return PlaceString(NicknameTextString, coord(1, 3))
	ld hl, (3) * SCREEN_WIDTH + (1) + wTileMap
	ld de, NicknameTextString
	jr .placeString
.notNickname
;> end, _ = PlaceString(text, pos)
	call PlaceString
;> return PlaceString(NameTextString, end)
	ld l, c
	ld h, b
	ld de, NameTextString
.placeString
	jp PlaceString

