;@ def OakSpeechSlidePicLeft(name: de)
;@ After a default name was picked: clear the name list, store the name at `name`, and slide the picture back
;@ to the middle.
;@ test: skip waits for frames
OakSpeechSlidePicLeft:
;> ClearScreenArea(coord(0, 0), 11, 12)         # the name list
	push de
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((12) & $ff) << 8 + ((11) & $ff)
	call ClearScreenArea ; clear the name list text box
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> CopyData(addr(wNameBuffer), name, NAME_LENGTH)
	pop de
	ld hl, wNameBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> Delay3()
	call Delay3
;> OakSpeechSlidePicCommon(coord(12, 4), 6, 6 * SCREEN_WIDTH + 5, 0xFF)
	ld hl, (4) * SCREEN_WIDTH + (12) + wTileMap
	ld de, ((6) & $ff) << 8 + ((6 * SCREEN_WIDTH + 5) & $ff)
	ld a, $ff
	jr OakSpeechSlidePicCommon

;@ path: engine/movie/oak_speech/oak_speech2
;@ def OakSpeechSlidePicRight()
;@ Slide the picture from the middle to the right, to make room for the name list.
;@ test: skip waits for frames
OakSpeechSlidePicRight:
;> OakSpeechSlidePicCommon(coord(5, 4), 6, 6 * SCREEN_WIDTH + 5, 0)
	ld hl, (4) * SCREEN_WIDTH + (5) + wTileMap
	ld de, ((6) & $ff) << 8 + ((6 * SCREEN_WIDTH + 5) & $ff)
	xor a

;@ path: engine/movie/oak_speech/oak_speech2
;@ def OakSpeechSlidePicCommon(pic: hl, amount: d, size: e, left: a)
;@ Slide the `size`-byte stretch of screen tiles at `pic` `amount` tiles left or right, one tile every 3 frames.
;@ test: skip waits for frames
OakSpeechSlidePicCommon:
;> hSlideDirection = left
	push hl
	push de
	push bc
	ldh [hSlideDirection], a
;> hSlideAmount = amount
	ld a, d
	ldh [hSlideAmount], a
;> hSlidingRegionSize = size
	ld a, e
	ldh [hSlidingRegionSize], a
;> start = pic
	ld c, a
;> if not left:                                  # sliding right goes from the end
	ldh a, [hSlideDirection]
	and a
	jr nz, .next
; If sliding right, point hl to the end of the pic's tiles.
;>     start = pic + size
	ld d, 0
	add hl, de
.next
	ld d, h
	ld e, l
;> while True:
.loop
;>     hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;>@at     at = start
;>@tiles     for _ in range(size):
;>         if not left:
	ldh a, [hSlideDirection]
	and a
	jr nz, .slideLeft
; sliding right
;>             mem[at + 1] = mem[at]
;>             at -= 1
	ld a, [hli]
	ld [hld], a
	dec hl
	jr .next2
.slideLeft
;>         else:
;>             mem[at - 1] = mem[at]
;>             at += 1
	ld a, [hld]
	ld [hli], a
	inc hl
.next2
	dec c
	jr nz, .loop
;>     if left:
	ldh a, [hSlideDirection]
	and a
	jr z, .next3
; If sliding left, we need to zero the last tile in the pic (there is no need
; to take a corresponding action when sliding right because hl initially points
; to a 0 tile in that case).
;>         mem[at - 1] = 0                       # the tile that moved on is blank now
	xor a
	dec hl
	ld [hl], a
.next3
;>     hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;>     Delay3()
	call Delay3
;>     # the next round: size tiles again, one tile further
	ldh a, [hSlidingRegionSize]
	ld c, a
	ld h, d
	ld l, e
;>     if not left:
	ldh a, [hSlideDirection]
	and a
	jr nz, .slideLeft2
;>         start += 1
	inc hl
	jr .next4
.slideLeft2
;>     else:
;>         start -= 1
	dec hl
.next4
	ld d, h
	ld e, l
;>     hSlideAmount -= 1
	ldh a, [hSlideAmount]
	dec a
	ldh [hSlideAmount], a
;>     if hSlideAmount == 0:
;>         break
	jr nz, .loop
	pop bc
	pop de
	pop hl
	ret

;@ path: engine/movie/oak_speech/oak_speech2
;@ def DisplayIntroNameTextBox(names: de) -> a
;@ The NAME box with NEW NAME and three default names (`names`); returns the keys from the menu.
;@ test: skip runs a menu
DisplayIntroNameTextBox:
;> TextBoxBorder(coord(0, 0), 10, 9)
	push de
