	call TextBoxBorder
;> PlaceString(DisplayIntroNameTextBox.namestring, coord(3, 0))     # "NAME"
	ld hl, (0) * SCREEN_WIDTH + (3) + wTileMap
	ld de, .namestring
	call PlaceString
;> PlaceString(names, coord(2, 2))
	pop de
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
;> UpdateSprites()
	call UpdateSprites
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wTopMenuItemX = 1
	inc a
	ld [wTopMenuItemX], a
;> wMenuWatchedKeys = PAD_A
	ld [wMenuWatchedKeys], a ; PAD_A
;> wTopMenuItemY = 2
	inc a
	ld [wTopMenuItemY], a
;> wMaxMenuItem = 3
	inc a
	ld [wMaxMenuItem], a
;> return HandleMenuInput()
	jp HandleMenuInput

.namestring
	db "NAME@"

