;@ def GetDefaultName(index: a, names: hl)
;@ Copy name `index` of a list of @-terminated names into wNameBuffer.
;@ test: index = rand(0, 3); names = 0x6AF2    # DefaultNamesPlayerList
GetDefaultName:
; a = name index
; hl = name list
;> i = 0
;> while True:                                   # name i of the list
	ld b, a
	ld c, 0
.loop
;>     start = names
;>     while True:                               # to the end of this name
	ld d, h
	ld e, l
.innerLoop
;>         c = mem[names]
;>         names += 1
	ld a, [hli]
;>         if c == charmap('@')[0]:
;>             break
	cp '@'
	jr nz, .innerLoop
;>     if i == index:
;>         break
	ld a, b
	cp c
	jr z, .foundName
;>     i += 1
	inc c
	jr .loop
.foundName
;> CopyData(start, addr(wNameBuffer), NAME_BUFFER_LENGTH)
	ld h, d
	ld l, e
	ld de, wNameBuffer
	ld bc, NAME_BUFFER_LENGTH
	jp CopyData

