; subtracts the amount the player paid from their money
; OUTPUT: carry = 0(success) or 1(fail because there is not enough money)
;@ def SubtractAmountPaidFromMoney_() -> carry
;@ Pay the price in hMoney from the player's money and redraw the money box. Carry (and nothing paid) if the player
;@ has less than that.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/subtract_paid_money
SubtractAmountPaidFromMoney_::
;> if StringCmp(wPlayerMoney, hMoney, 3)[0]:
;>     return True
	ld de, wPlayerMoney
	ld hl, hMoney ; total price of items
	ld c, 3 ; length of money in bytes
	call StringCmp
	ret c
;> SubBCD(wPlayerMoney + 2, hMoney + 2, 3)
	ld de, wPlayerMoney + 2
	ld hl, hMoney + 2 ; total price of items
	ld c, 3 ; length of money in bytes
	; subtract total price from money
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;> wTextBoxID = MONEY_BOX
;> DisplayTextBoxID()
	ld a, MONEY_BOX
	ld [wTextBoxID], a
	call DisplayTextBoxID ; redraw money text box
;> return False
	and a
	ret
;@ def HandleItemListSwapping()
;@ SELECT in an item list: the first press marks an item, the second swaps it with the item under the cursor, or
;@ merges the two slots if they hold the same item (as much as fits in 99, removing the emptied slot). Then back
;@ to the list menu.
;@ path: engine/menus/swap_items
HandleItemListSwapping::
;> if wListMenuID != ITEMLISTMENU:             # only item lists can be rearranged
;>     return DisplayListMenuIDLoop()
	ld a, [wListMenuID]
	cp ITEMLISTMENU
	jp nz, DisplayListMenuIDLoop ; only rearrange item list menus
;> items = mem16[addr(wListPointer)]
	push hl
	ld hl, wListPointer
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> items += 1                                  # past the count byte
	inc hl ; hl = beginning of list entries
;> i = (wCurrentMenuItem + wListScrollOffset) & 0xFF
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, [wListScrollOffset]
	add b
;> sel = items + (2 * i & 0xFF)                # the entry under the cursor
	add a
	ld c, a
	ld b, 0
	add hl, bc ; hl = address of currently selected item entry
;> if mem[sel] == 0xFF:                        # CANCEL can't be moved
;>     return DisplayListMenuIDLoop()
	ld a, [hl]
	pop hl
	inc a
	jp z, DisplayListMenuIDLoop ; ignore attempts to swap the Cancel menu item
;> if not wMenuItemToSwap:                     # (counts from 1)
	ld a, [wMenuItemToSwap] ; ID of item chosen for swapping (counts from 1)
	and a ; has the first item to swap already been chosen?
	jr nz, .swapItems
; if not, set the currently selected item as the first item
;>     wMenuItemToSwap = (wCurrentMenuItem + 1 + wListScrollOffset) & 0xFF   # mark this one
	ld a, [wCurrentMenuItem]
	inc a
	ld b, a
	ld a, [wListScrollOffset] ; index of top (visible) menu item within the list
	add b
	ld [wMenuItemToSwap], a ; ID of item chosen for swapping (counts from 1)
;>     DelayFrames(20)
	ld c, 20
	call DelayFrames
;>     return DisplayListMenuIDLoop()
	jp DisplayListMenuIDLoop
.swapItems
;> here = (wCurrentMenuItem + 1 + wListScrollOffset) & 0xFF
	ld a, [wCurrentMenuItem]
	inc a
	ld b, a
	ld a, [wListScrollOffset]
	add b
	ld b, a
;> if wMenuItemToSwap == here:                 # the same item twice
;>     return DisplayListMenuIDLoop()
	ld a, [wMenuItemToSwap] ; ID of item chosen for swapping (counts from 1)
	cp b ; is the currently selected item the same as the first item to swap?
	jp z, DisplayListMenuIDLoop ; ignore attempts to swap an item with itself
;> wMenuItemToSwap -= 1                        # now counting from 0
	dec a
	ld [wMenuItemToSwap], a ; ID of item chosen for swapping (counts from 1)
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> items = mem16[addr(wListPointer)]
	push hl
	push de
	ld hl, wListPointer
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> items += 1
	inc hl ; hl = beginning of list entries
;> base = items
	ld d, h
	ld e, l ; de = beginning of list entries
;> i = (wCurrentMenuItem + wListScrollOffset) & 0xFF
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, [wListScrollOffset]
	add b
;> sel = items + (2 * i & 0xFF)
	add a
	ld c, a
	ld b, 0
	add hl, bc ; hl = address of currently selected item entry
;> first = base + (2 * wMenuItemToSwap & 0xFF)  # the marked entry
	ld a, [wMenuItemToSwap] ; ID of item chosen for swapping (counts from 1)
	add a
	add e
	ld e, a
	jr nc, .noCarry
	inc d
.noCarry ; de = address of first item to swap
;> if mem[first] != mem[sel]:                  # different items: swap the slots
	ld a, [de]
	ld b, a
	ld a, [hli]
	cp b
	jr z, .swapSameItemType
; swap different items
;>     hSwapItemID = mem[sel]
	ldh [hSwapItemID], a ; save second item ID
;>     hSwapItemQuantity = mem[sel + 1]
	ld a, [hld]
	ldh [hSwapItemQuantity], a ; save second item quantity
;>     mem[sel] = mem[first]
	ld a, [de]
	ld [hli], a ; put first item ID in second item slot
;>     mem[sel + 1] = mem[first + 1]
	inc de
	ld a, [de]
	ld [hl], a ; put first item quantity in second item slot
;>     mem[first + 1] = hSwapItemQuantity
	ldh a, [hSwapItemQuantity]
	ld [de], a ; put second item quantity in first item slot
;>     mem[first] = hSwapItemID
	dec de
	ldh a, [hSwapItemID]
	ld [de], a ; put second item ID in first item slot
;>     wMenuItemToSwap = 0                     # nothing marked any more
	xor a
	ld [wMenuItemToSwap], a ; 0 means no item is currently being swapped
;>     return DisplayListMenuIDLoop()
	pop de
	pop hl
	jp DisplayListMenuIDLoop
.swapSameItemType
;> total = (mem[sel + 1] + mem[first + 1]) & 0xFF   # the same item: both quantities
	inc de
	ld a, [hl]
	ld b, a
	ld a, [de]
	add b ; a = sum of both item quantities
;> if total >= 100:                            # too many for one slot
	cp 100 ; is the sum too big for one item slot?
	jr c, .combineItemSlots
; swap enough items from the first slot to max out the second slot if they can't be combined
;>     mem[first + 1] = total - 99             # the rest stays in the first slot
	sub 99
	ld [de], a
;>     mem[sel + 1] = 99
	ld a, 99
	ld [hl], a
	jr .done
;> else:
.combineItemSlots
;>     mem[sel + 1] = total
	ld [hl], a ; put the sum in the second item slot
;>     count = mem16[addr(wListPointer)]
	ld hl, wListPointer
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     mem[count] -= 1                         # one slot fewer
	dec [hl] ; decrease the number of items
;>     wListCount = mem[count]
	ld a, [hl]
	ld [wListCount], a ; update number of items variable
;>     if mem[count] == 1:
;>         wMaxMenuItem = 1
	cp 1
	jr nz, .skipSettingMaxMenuItemID
	ld [wMaxMenuItem], a ; if the number of items is only one now, update the max menu item ID
.skipSettingMaxMenuItemID
;>     dest = first
	dec de
;>     src = first + 2                         # the slots after it move up
	ld h, d
	ld l, e
	inc hl
	inc hl ; hl = address of item after first item to swap
;>@mv     while True:                             # item, then quantity
.moveItemsUpLoop ; erase the first item slot and move up all the following item slots to fill the gap
;>         v = mem[src]
	ld a, [hli]
;>         mem[dest] = v
;>         src, dest = src + 1, dest + 1
	ld [de], a
	inc de
;>         if v == 0xFF:
;>             break
	inc a ; reached the $ff terminator?
	jr z, .afterMovingItemsUp
;>         mem[dest] = mem[src]
;>         src, dest = src + 1, dest + 1
	ld a, [hli]
	ld [de], a
	inc de
;=@mv
	jr .moveItemsUpLoop
.afterMovingItemsUp
;>     wListScrollOffset = 0
	xor a
	ld [wListScrollOffset], a
;>     wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
.done
;> wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a ; 0 means no item is currently being swapped
;> return DisplayListMenuIDLoop()
	pop de
	pop hl
	jp DisplayListMenuIDLoop
;@ path: engine/events/pokemart
;@ def DisplayPokemartDialogue_()
;@ The Poké Mart clerk: BUY, SELL or QUIT, until QUIT or B. Buying lists the mart's items with prices: choose
;@ a quantity, confirm, and pay if there is money and room in the bag. Selling lists the bag (key items and
;@ HMs cannot be sold) at half price.
;@ test: skip shows menus
DisplayPokemartDialogue_::
;> wSavedListScrollOffset = wListScrollOffset
	ld a, [wListScrollOffset]
	ld [wSavedListScrollOffset], a
;> UpdateSprites()
	call UpdateSprites
;> wBoughtOrSoldItemInMart = 0
	xor a
	ld [wBoughtOrSoldItemInMart], a
;> while True:
.loop
;>     wListScrollOffset = 0
	xor a
	ld [wListScrollOffset], a
;>     wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;>     wPlayerMonNumber = 0
	ld [wPlayerMonNumber], a
;>     wPrintItemPrices = 1
	inc a
	ld [wPrintItemPrices], a
;>     wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>     DisplayTextBoxID()
	call DisplayTextBoxID
;>     wTextBoxID = BUY_SELL_QUIT_MENU
	ld a, BUY_SELL_QUIT_MENU
	ld [wTextBoxID], a
;>     DisplayTextBoxID()
	call DisplayTextBoxID

; This code is useless. It copies the address of the pokemart's inventory to hl,
; but the address is never used.
	ld hl, wItemListPointer
	ld a, [hli]
	ld l, [hl]
	ld h, a

;>@quit     if wMenuExitMethod == CANCELLED_MENU or wChosenMenuItem == 2:    # B or QUIT
;>         break
	ld a, [wMenuExitMethod]
	cp CANCELLED_MENU
	jp z, .done
;>@sell     if wChosenMenuItem != 0:                 # SELL (BUY is the else below)
	ld a, [wChosenMenuItem]
	and a ; buying?
	jp z, .buyMenu
;=@sell
	dec a ; selling?
	jp z, .sellMenu
;=@quit
	dec a ; quitting?
	jp z, .done
.sellMenu

; the same variables are set again below, so this code has no effect
;>         wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>         wInitListType = INIT_BAG_ITEM_LIST
	ld a, INIT_BAG_ITEM_LIST
	ld [wInitListType], a
;>         InitList()                           # in another bank
	ld hl, InitList
	ld b, BANK(InitList)
	call Bankswitch

;>         if wNumBagItems == 0:
;>@bagtxt             PrintText(PokemartItemBagEmptyText)
;>@bagsave             SaveScreenTilesToBuffer1()
	ld a, [wNumBagItems]
	and a
	jp z, .bagEmpty
;>         else:
;>             PrintText(PokemonSellingGreetingText)
	ld hl, PokemonSellingGreetingText
	call PrintText
;>             SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1 ; save screen
;>             while True:
.sellMenuLoop
;>                 LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1 ; restore saved screen
;>                 wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>                 DisplayTextBoxID()
	call DisplayTextBoxID ; draw money text box
;>                 wListPointer[0] = addr(wNumBagItems) & 0xFF
;>                 wListPointer[1] = addr(wNumBagItems) >> 8
	ld hl, wNumBagItems
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;>                 wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>                 wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;>                 wListMenuID = ITEMLISTMENU
	ld a, ITEMLISTMENU
	ld [wListMenuID], a
;>                 if DisplayListMenuID():          # carry: the menu was closed
;>                     break
	call DisplayListMenuID
	jp c, .returnToMainPokemartMenu ; if the player closed the menu
; if the player is trying to sell a specific item, confirm the sale
;>                 IsKeyItem()
	call IsKeyItem
;>                 if wIsKeyItem or IsItemHM(wCurItem):
;>@unsell                     PrintText(PokemartUnsellableItemText)
;>@unbreak                     break
	ld a, [wIsKeyItem]
	and a
	jr nz, .unsellableItem
	ld a, [wCurItem]
	call IsItemHM
	jr c, .unsellableItem
;>                 wListMenuID = PRICEDITEMLISTMENU
	ld a, PRICEDITEMLISTMENU
	ld [wListMenuID], a
;>                 hHalveItemPrices = PRICEDITEMLISTMENU     # nonzero: half price
	ldh [hHalveItemPrices], a ; halve prices when selling
;>                 if DisplayChooseQuantityMenu() == 0xFF:   # B
;>                     continue
	call DisplayChooseQuantityMenu
	inc a
	jr z, .sellMenuLoop ; if the player closed the choose quantity menu with the B button
;>                 PrintText(PokemartTellSellPriceText)
	ld hl, PokemartTellSellPriceText
	; location that PrintText always prints to, this is useless
	ld bc, ((14) & $ff) << 8 + ((1) & $ff)
	call PrintText
;>                 wTextBoxID = TWO_OPTION_MENU     # yes/no at (14, 7)
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;>                 DisplayTextBoxID()
	call DisplayTextBoxID ; yes/no menu
;>                 if wMenuExitMethod == CHOSE_SECOND_ITEM or wChosenMenuItem == 1:
;>                     continue
	ld a, [wMenuExitMethod]
	cp CHOSE_SECOND_ITEM
	jr z, .sellMenuLoop ; if the player chose No or pressed the B button

; The following code is supposed to check if the player chose No, but the above
; check already catches it.
	ld a, [wChosenMenuItem]
	dec a
	jr z, .sellMenuLoop

; sell item
;>                 if not wBoughtOrSoldItemInMart:
;>                     wBoughtOrSoldItemInMart = 1
	ld a, [wBoughtOrSoldItemInMart]
	and a
	jr nz, .skipSettingFlag1
	inc a
	ld [wBoughtOrSoldItemInMart], a
.skipSettingFlag1
;>                 AddAmountSoldToMoney()
	call AddAmountSoldToMoney
;>                 RemoveItemFromInventory(addr(wNumBagItems))
	ld hl, wNumBagItems
	call RemoveItemFromInventory
	jp .sellMenuLoop
.unsellableItem
;=@unsell
	ld hl, PokemartUnsellableItemText
	call PrintText
;=@unbreak
	jp .returnToMainPokemartMenu
.bagEmpty
;=@bagtxt
	ld hl, PokemartItemBagEmptyText
	call PrintText
;=@bagsave
	call SaveScreenTilesToBuffer1
	jp .returnToMainPokemartMenu
.buyMenu

; the same variables are set again below, so this code has no effect
;>     else:                                    # BUY
;>         wPrintItemPrices = 1
	ld a, 1
	ld [wPrintItemPrices], a
;>         wInitListType = INIT_OTHER_ITEM_LIST
	ld a, INIT_OTHER_ITEM_LIST
	ld [wInitListType], a
;>         InitList()                           # in another bank
	ld hl, InitList
	ld b, BANK(InitList)
	call Bankswitch

;>         PrintText(PokemartBuyingGreetingText)
	ld hl, PokemartBuyingGreetingText
	call PrintText
;>         SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>         while True:
.buyMenuLoop
;>             LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>             wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>             DisplayTextBoxID()
	call DisplayTextBoxID
;>             wListPointer[0] = addr(wItemList) & 0xFF
;>             wListPointer[1] = addr(wItemList) >> 8
	ld hl, wItemList
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;>             wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;>             wPrintItemPrices = 1
	inc a
	ld [wPrintItemPrices], a
;>             wListMenuID = PRICEDITEMLISTMENU
	inc a ; a = 2 (PRICEDITEMLISTMENU)
	ld [wListMenuID], a
;>             if DisplayListMenuID():              # carry: the menu was closed
;>                 break
	call DisplayListMenuID
	jr c, .returnToMainPokemartMenu ; if the player closed the menu
;>             wMaxItemQuantity = 99
	ld a, 99
	ld [wMaxItemQuantity], a
;>             hHalveItemPrices = 0
	xor a
	ldh [hHalveItemPrices], a ; don't halve item prices when buying
;>             if DisplayChooseQuantityMenu() == 0xFF:
;>                 continue
	call DisplayChooseQuantityMenu
	inc a
	jr z, .buyMenuLoop ; if the player closed the choose quantity menu with the B button
;>             wNamedObjectIndex = wCurItem
	ld a, [wCurItem]
	ld [wNamedObjectIndex], a
;>             CopyToStringBuffer(GetItemName())
	call GetItemName
	call CopyToStringBuffer
;>             PrintText(PokemartTellBuyPriceText)
	ld hl, PokemartTellBuyPriceText
	call PrintText
;>             wTextBoxID = TWO_OPTION_MENU
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;>             DisplayTextBoxID()
	call DisplayTextBoxID ; yes/no menu
;>             if wMenuExitMethod == CHOSE_SECOND_ITEM or wChosenMenuItem == 1:
;>                 continue
	ld a, [wMenuExitMethod]
	cp CHOSE_SECOND_ITEM
	jp z, .buyMenuLoop ; if the player chose No or pressed the B button

; The following code is supposed to check if the player chose No, but the above
; check already catches it.
	ld a, [wChosenMenuItem]
	dec a
	jr z, .buyMenuLoop

; buy item
;>@cmp             notEnough, _ = StringCmp(addr(wPlayerMoney), addr(hMoney), 3)   # the price is in hMoney
;>             if notEnough:
;>@poor                 PrintText(PokemartNotEnoughMoneyText)
;>@poorbrk                 break
	call .isThereEnoughMoney
	jr c, .notEnoughMoney
;>             if not AddItemToInventory(addr(wNumBagItems)):
;>@full                 PrintText(PokemartItemBagFullText)
;>@fullbrk                 break
	ld hl, wNumBagItems
	call AddItemToInventory
	jr nc, .bagFull
;>             SubtractAmountPaidFromMoney()
	call SubtractAmountPaidFromMoney
;>             if not wBoughtOrSoldItemInMart:
;>                 wBoughtOrSoldItemInMart = 1
	ld a, [wBoughtOrSoldItemInMart]
	and a
	jr nz, .skipSettingFlag2
	ld a, 1
	ld [wBoughtOrSoldItemInMart], a
.skipSettingFlag2
;>             PlaySoundWaitForCurrent(SFX_PURCHASE)
	ld a, SFX_PURCHASE
	call PlaySoundWaitForCurrent
;>             WaitForSoundToFinish()
	call WaitForSoundToFinish
;>             PrintText(PokemartBoughtItemText)
	ld hl, PokemartBoughtItemText
	call PrintText
	jp .buyMenuLoop
.returnToMainPokemartMenu
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;>     DisplayTextBoxID()
	call DisplayTextBoxID
;>     PrintText(PokemartAnythingElseText)
	ld hl, PokemartAnythingElseText
	call PrintText
	jp .loop
.isThereEnoughMoney
;=@cmp
	ld de, wPlayerMoney
	ld hl, hMoney
	ld c, 3 ; length of money in bytes
	jp StringCmp
.notEnoughMoney
;=@poor
	ld hl, PokemartNotEnoughMoneyText
	call PrintText
;=@poorbrk
	jr .returnToMainPokemartMenu
.bagFull
;=@full
	ld hl, PokemartItemBagFullText
	call PrintText
;=@fullbrk
	jr .returnToMainPokemartMenu
.done
;> PrintText(PokemartThankYouText)
	ld hl, PokemartThankYouText
	call PrintText
;> wUpdateSpritesEnabled = 1
	ld a, 1
	ld [wUpdateSpritesEnabled], a
;> UpdateSprites()
	call UpdateSprites
;> wListScrollOffset = wSavedListScrollOffset
	ld a, [wSavedListScrollOffset]
	ld [wListScrollOffset], a
	ret

