;@ path: engine/pokemon/learn_move
;@ def LearnMove() -> b
;@ Party Pokémon wWhichPokemon learns move wMoveNum, asking which old move to forget if all four slots are
;@ taken. Returns 1 if it learned the move, 0 if the player gave up.
LearnMove:
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;> CopyData(addr(wNameBuffer), addr(wLearnMoveMonName), NAME_LENGTH)
	ld hl, wNameBuffer
	ld de, wLearnMoveMonName
	ld bc, NAME_LENGTH
	call CopyData
;> return DontAbandonLearning()                  # it runs on into it

;@ path: engine/pokemon/learn_move
;@ def DontAbandonLearning() -> b
;@ Put move wMoveNum into a free move slot (or the one the player chooses to forget), with full PP, and into
;@ the battle copy if this is the Pokémon in battle.
DontAbandonLearning:
;> moves = addr(wPartyMon1Moves) + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;> slot = moves
;> for _ in range(NUM_MOVES):
	ld d, h
	ld e, l
	ld b, NUM_MOVES
.findEmptyMoveSlotLoop
;>     if mem[slot] == 0:                        # a free slot
;>         break
	ld a, [hl]
	and a
	jr z, .next
;>     slot += 1
	inc hl
	dec b
	jr nz, .findEmptyMoveSlotLoop
;> else:                                         # all four are taken
;>     gave_up, slot, forgotten = TryingToLearn(slot)
	push de
	call TryingToLearn
	pop de
;>     if gave_up:
;>         return AbandonLearning()
	jp c, AbandonLearning
;>     wNamedObjectIndex = forgotten
	push hl
	push de
	ld [wNamedObjectIndex], a
;>     GetMoveName()
	call GetMoveName
;>     PrintText(OneTwoAndText)                  # "1, 2 and... Poof!"
	ld hl, OneTwoAndText
	call PrintText
	pop de
	pop hl
.next
;> mem[slot] = wMoveNum
;> pp = slot + MON_PP - MON_MOVES
	ld a, [wMoveNum]
	ld [hl], a
	ld bc, MON_PP - MON_MOVES
	add hl, bc
;> entry = Moves + u8(wMoveNum - 1) * MOVE_LENGTH
	push hl
	push de
	dec a
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;> FarCopyData(BANK(Moves), entry, addr(wBuffer), MOVE_LENGTH)
	ld de, wBuffer
	ld a, BANK(Moves)
	call FarCopyData
;> mem[pp] = wBuffer[MOVE_PP]                    # full PP
	ld a, [wBuffer + MOVE_PP]
	pop de
	pop hl
	ld [hl], a
;> if not wIsInBattle:
;>     return PrintLearnedMove()
	ld a, [wIsInBattle]
	and a
	jp z, PrintLearnedMove
;> if wWhichPokemon != wPlayerMonNumber:         # not the Pokémon in battle
;>     return PrintLearnedMove()
	ld a, [wWhichPokemon]
	ld b, a
	ld a, [wPlayerMonNumber]
	cp b
	jp nz, PrintLearnedMove
;> CopyData(moves, addr(wBattleMonMoves), NUM_MOVES)     # the battle copy too
	ld h, d
	ld l, e
	ld de, wBattleMonMoves
	ld bc, NUM_MOVES
	call CopyData
;> CopyData(moves + MON_PP - MON_MOVES, addr(wBattleMonPP), NUM_MOVES)
	ld bc, MON_PP - MON_OTID
	add hl, bc
	ld de, wBattleMonPP
	ld bc, NUM_MOVES
	call CopyData
;> return PrintLearnedMove()
	jp PrintLearnedMove

;@ path: engine/pokemon/learn_move
;@ def AbandonLearning() -> b
;@ "Abandon learning ...?" with a YES/NO box: NO goes back to choosing a move to forget, YES gives up (returns 0).
AbandonLearning:
;> PrintText(AbandonLearningText)
	ld hl, AbandonLearningText
	call PrintText
;> wTextBoxID = TWO_OPTION_MENU
;> DisplayTextBoxID(coord(14, 7), 8, 15)
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID ; yes/no menu
;> if wCurrentMenuItem:
;>     return DontAbandonLearning()
	ld a, [wCurrentMenuItem]
	and a
	jp nz, DontAbandonLearning
;> PrintText(DidNotLearnText)
	ld hl, DidNotLearnText
	call PrintText
;> return 0
	ld b, 0
	ret

;@ path: engine/pokemon/learn_move
;@ def PrintLearnedMove() -> b
;@ "... learned ...!" Returns 1.
PrintLearnedMove:
;> PrintText(LearnedMove1Text)
;> return 1
	ld hl, LearnedMove1Text
	call PrintText
	ld b, 1
	ret

;@ path: engine/pokemon/learn_move
;@ def TryingToLearn(moves_end: hl) -> (carry, hl, a)
;@ All four move slots are full: ask whether to forget one, and which (HMs cannot be forgotten). Returns
;@ carry if the player says no or cancels, otherwise the chosen slot's address and the move it held.
TryingToLearn:
;> PrintText(TryingToLearnText)
	push hl
	ld hl, TryingToLearnText
	call PrintText
;> wTextBoxID = TWO_OPTION_MENU
;> DisplayTextBoxID(coord(14, 7), 8, 15)        # YES / NO
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID ; yes/no menu
	pop hl
;> if wCurrentMenuItem & 1:                      # NO
;>     return (True, moves_end, wCurrentMenuItem >> 1)
	ld a, [wCurrentMenuItem]
	rra
	ret c
;> moves = moves_end - NUM_MOVES
	ld bc, -NUM_MOVES
	add hl, bc
;> CopyData(moves, addr(wMoves), NUM_MOVES)
	push hl
	ld de, wMoves
	ld bc, NUM_MOVES
	call CopyData
;> FormatMovesString()
	ld hl, FormatMovesString
	ld b, BANK(FormatMovesString)
	call Bankswitch
	pop hl
;> while True:
.loop
;>     PrintText(WhichMoveToForgetText)
	push hl
	ld hl, WhichMoveToForgetText
	call PrintText
;>     TextBoxBorder(coord(4, 7), 4, 14)
	ld hl, (7) * SCREEN_WIDTH + (4) + wTileMap
	ld b, 4
	ld c, 14
	call TextBoxBorder
;>     hUILayoutFlags = hUILayoutFlags | 1 << BIT_SINGLE_SPACED_LINES
;>     PlaceString(coord(6, 8), addr(wMovesString))
	ld hl, (8) * SCREEN_WIDTH + (6) + wTileMap
	ld de, wMovesString
	ldh a, [hUILayoutFlags]
	set BIT_SINGLE_SPACED_LINES, a
	ldh [hUILayoutFlags], a
	call PlaceString
;>     hUILayoutFlags = hUILayoutFlags & ~(1 << BIT_SINGLE_SPACED_LINES) & 0xFF
	ldh a, [hUILayoutFlags]
	res BIT_SINGLE_SPACED_LINES, a
	ldh [hUILayoutFlags], a
;>     wTopMenuItemY = 8
	ld hl, wTopMenuItemY
	ld a, 8
	ld [hli], a ; wTopMenuItemY
;>     wTopMenuItemX = 5
	ld a, 5
	ld [hli], a ; wTopMenuItemX
;>     wCurrentMenuItem = 0
	xor a
	ld [hli], a ; wCurrentMenuItem
	inc hl
;>     wMaxMenuItem = wNumMovesMinusOne
	ld a, [wNumMovesMinusOne]
	ld [hli], a ; wMaxMenuItem
;>     wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [hli], a ; wMenuWatchedKeys
;>     wLastMenuItem = 0
	ld [hl], 0 ; wLastMenuItem
;>     hUILayoutFlags = hUILayoutFlags | 1 << BIT_DOUBLE_SPACED_MENU
	ld hl, hUILayoutFlags
	set BIT_DOUBLE_SPACED_MENU, [hl]
;>     keys = HandleMenuInput()
	call HandleMenuInput
;>     hUILayoutFlags = hUILayoutFlags & ~(1 << BIT_DOUBLE_SPACED_MENU) & 0xFF
	ld hl, hUILayoutFlags
	res BIT_DOUBLE_SPACED_MENU, [hl]
;>     LoadScreenTilesFromBuffer1()
	push af
	call LoadScreenTilesFromBuffer1
	pop af
	pop hl
;>     if keys >> B_PAD_B & 1:
	bit B_PAD_B, a
	jr nz, .cancel
;>@cancel         return (True, moves, keys)
;>     move = mem[moves + wCurrentMenuItem]
	push hl
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, 0
	add hl, bc
	ld a, [hl]
;>     hm = IsMoveHM(move)
	push af
	push bc
	call IsMoveHM
	pop bc
	pop de
	ld a, d
;>     if not hm:
	jr c, .hm
;>         return (False, moves + wCurrentMenuItem, move)
	pop hl
	add hl, bc
	and a
	ret
.hm
;>     PrintText(HMCantDeleteText)               # and ask again
	ld hl, HMCantDeleteText
	call PrintText
	pop hl
	jr .loop
.cancel
;=@cancel
	scf
	ret

