;@ path: engine/events/pokecenter
;@ def DisplayPokemonCenterDialogue_()
;@ The Pokémon Center nurse: on YES the Center becomes the blackout point, the party is healed with the
;@ machine's animation and jingle, the map music returns and the nurse bows.
;@ test: skip asks the player a question
DisplayPokemonCenterDialogue_::
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1 ; save screen
;> PrintText(PokemonCenterWelcomeText)
	ld hl, PokemonCenterWelcomeText
	call PrintText
;> used = wStatusFlags4 & (1 << BIT_USED_POKECENTER)
	ld hl, wStatusFlags4
	bit BIT_USED_POKECENTER, [hl]
;> wStatusFlags4 = wStatusFlags4 | 1 << BIT_UNKNOWN_4_1 | 1 << BIT_USED_POKECENTER
	set BIT_UNKNOWN_4_1, [hl]
	set BIT_USED_POKECENTER, [hl]
;> if not used:
	jr nz, .skipShallWeHealYourPokemon
;>     PrintText(ShallWeHealYourPokemonText)
	ld hl, ShallWeHealYourPokemonText
	call PrintText
.skipShallWeHealYourPokemon
;> YesNoChoicePokeCenter()
	call YesNoChoicePokeCenter ; yes/no menu
;> if wCurrentMenuItem == 0:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .declinedHealing ; if the player chose No
;>     SetLastBlackoutMap()
	call SetLastBlackoutMap
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1 ; restore screen
;>     PrintText(NeedYourPokemonText)
	ld hl, NeedYourPokemonText
	call PrintText
;>     mem[wSprite01StateData1ImageIndex] = 0x18    # the nurse turns to the machine
	ld a, $18
	ld [wSprite01StateData1ImageIndex], a ; make the nurse turn to face the machine
;>     Delay3()
	call Delay3
;>     HealParty()                              # a predef
	ld a, (HealPartyPredef - PredefPointers) / 3
	call Predef
	; do the healing machine animation
;>     AnimateHealingMachine()                  # in another bank
	ld b, BANK(AnimateHealingMachine)
	ld hl, AnimateHealingMachine
	call Bankswitch
;>     wAudioFadeOutControl = 0
	xor a
	ld [wAudioFadeOutControl], a
;>     wAudioROMBank = wAudioSavedROMBank
	ld a, [wAudioSavedROMBank]
	ld [wAudioROMBank], a
;>     wLastMusicSoundID = wMapMusicSoundID
	ld a, [wMapMusicSoundID]
	ld [wLastMusicSoundID], a
;>     wNewSoundID = wMapMusicSoundID
	ld [wNewSoundID], a
;>     PlaySound(wMapMusicSoundID)
	call PlaySound
;>     PrintText(PokemonFightingFitText)
	ld hl, PokemonFightingFitText
	call PrintText
;>     mem[wSprite01StateData1ImageIndex] = 0x14    # the nurse bows
	ld a, $14
	ld [wSprite01StateData1ImageIndex], a ; make the nurse bow
;>     DelayFrames(0x14)
	ld c, a
	call DelayFrames
	jr .done
.declinedHealing
;> else:
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1 ; restore screen
.done
;> PrintText(PokemonCenterFarewellText)
	ld hl, PokemonCenterFarewellText
	call PrintText
;> UpdateSprites()
	jp UpdateSprites

