;@ path: engine/events/set_blackout_map
;@ def SetLastBlackoutMap()
;@ Remember the current map as the place to return to after blacking out or using Teleport or Dig - unless
;@ it is one of the Safari Zone rest houses.
SetLastBlackoutMap:
; Set the map to return to when
; blacking out or using Teleport or Dig.
; Safari rest houses don't count.

;> house = SafariZoneRestHouses
	push hl
	ld hl, SafariZoneRestHouses
	ld a, [wCurMap]
	ld b, a
.loop
;> while mem[house] != 0xFF:
	ld a, [hli]
	cp -1
	jr z, .notresthouse
;>     if mem[house] == wCurMap:                # a rest house: keep the old one
	cp b
	jr nz, .loop
;>         return
;>@next     house += 1
	jr .done

.notresthouse
;> wLastBlackoutMap = wLastMap
	ld a, [wLastMap]
	ld [wLastBlackoutMap], a
.done
	pop hl
	ret

;@ path: engine/events/set_blackout_map
SafariZoneRestHouses:
	db SAFARI_ZONE_WEST_REST_HOUSE
	db SAFARI_ZONE_EAST_REST_HOUSE
	db SAFARI_ZONE_NORTH_REST_HOUSE
	db -1 ; end
; function that performs initialization for DisplayTextID
;@ def DisplayTextIDInit()
;@ Get ready to show a text box: draw its border (unless turned off; the START menu's is taller with the Pokédex),
;@ remember which way each NPC faced, stop walking animations, copy the screen to the window and load the font.
;@ path: engine/menus/display_text_id_init
DisplayTextIDInit::
;> wListMenuID = 0
	xor a
	ld [wListMenuID], a
;> if not wAutoTextBoxDrawingControl >> BIT_NO_AUTO_TEXT_BOX & 1:
	ld a, [wAutoTextBoxDrawingControl]
	bit BIT_NO_AUTO_TEXT_BOX, a
	jr nz, .skipDrawingTextBoxBorder
;>     if hTextID == 0:                        # the START menu
	ldh a, [hTextID]
	and a
	jr nz, .notStartMenu
; if text ID is 0 (i.e. the start menu)
; Note that the start menu text border is also drawn in the function directly
; below this, so this seems unnecessary.
;>         dex = event(EVENT_GOT_POKEDEX)
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
; start menu with pokedex
;>         rows = 0x0E                         # a row for POKéDEX
	ld hl, (0) * SCREEN_WIDTH + (10) + wTileMap
	ld b, $0e
	ld c, $08
	jr nz, .drawTextBoxBorder
; start menu without pokedex
;>         if not dex:
;>             rows = 0x0C
	ld hl, (0) * SCREEN_WIDTH + (10) + wTileMap
	ld b, $0c
	ld c, $08
	jr .drawTextBoxBorder
;>@tb         TextBoxBorder(coord(10, 0), rows, 8)    # (the call below)
; if text ID is not 0 (i.e. not the start menu) then do a standard dialogue text box
;>     else:
;>         TextBoxBorder(coord(0, 12), 4, 18)
.notStartMenu
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld b, $04
	ld c, $12
.drawTextBoxBorder
	call TextBoxBorder
.skipDrawingTextBoxBorder
;> wFontLoaded |= 1 << BIT_FONT_LOADED
	ld hl, wFontLoaded
	set BIT_FONT_LOADED, [hl]
;> no_update = wMiscFlags >> BIT_NO_SPRITE_UPDATES & 1
	ld hl, wMiscFlags
	bit BIT_NO_SPRITE_UPDATES, [hl]
;> wMiscFlags &= ~(1 << BIT_NO_SPRITE_UPDATES) & 0xFF
	res BIT_NO_SPRITE_UPDATES, [hl]
;> if not no_update:
;>     UpdateSprites()
	jr nz, .skipMovingSprites
	call UpdateSprites
.skipMovingSprites
; loop to copy [x#SPRITESTATEDATA1_FACINGDIRECTION] to
; [x#SPRITESTATEDATA2_ORIGFACINGDIRECTION] for each non-player sprite
; this is done because when you talk to an NPC, they turn to look your way
; the original direction they were facing must be restored after the dialogue is over
;> p = addr(wSprite01StateData1FacingDirection)
;> for _ in range(NUM_SPRITESTATEDATA_STRUCTS - 1):    # facing direction -> original facing direction
	ld hl, wSprite01StateData1FacingDirection
	ld c, NUM_SPRITESTATEDATA_STRUCTS - 1
	ld de, SPRITESTATEDATA1_LENGTH
.spriteFacingDirectionCopyLoop
;>     mem[p + 0x100] = mem[p]                 # (the second sprite state table is $100 bytes on)
	ld a, [hl] ; x#SPRITESTATEDATA1_FACINGDIRECTION
	inc h
	ld [hl], a ; [x#SPRITESTATEDATA2_ORIGFACINGDIRECTION]
	dec h
;>     p += SPRITESTATEDATA1_LENGTH
	add hl, de
	dec c
	jr nz, .spriteFacingDirectionCopyLoop
; loop to force all the sprites in the middle of animation to stand still
; (so that they don't like they're frozen mid-step during the dialogue)
;> p = addr(wSpritePlayerStateData1ImageIndex)
;> for _ in range(SPRITESTATEDATA1_LENGTH):    # every visible sprite to its standing frame
	ld hl, wSpritePlayerStateData1ImageIndex
	ld de, SPRITESTATEDATA1_LENGTH
	ASSERT NUM_SPRITESTATEDATA_STRUCTS == SPRITESTATEDATA1_LENGTH
	ld c, e
.spriteStandStillLoop
;>     if mem[p] != 0xFF:
	ld a, [hl]
	cp $ff ; is the sprite visible?
	jr z, .nextSprite
; if it is visible
;>         mem[p] &= 0xFC
	and $fc
	ld [hl], a
.nextSprite
;>     p += SPRITESTATEDATA1_LENGTH
	add hl, de
	dec c
	jr nz, .spriteStandStillLoop
;> CopyScreenTileBufferToVRAM(addr(vBGMap1) >> 8)
	ld b, HIGH(vBGMap1)
	call CopyScreenTileBufferToVRAM ; transfer background in WRAM to VRAM
;> hWY = 0                                     # the window over the whole screen
	xor a
	ldh [hWY], a ; put the window on the screen
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> hAutoBGTransferEnabled = 1
	ld a, $01
	ldh [hAutoBGTransferEnabled], a ; enable continuous WRAM to VRAM transfer each V-blank
	ret
; function that displays the start menu
;@ def DrawStartMenu()
;@ Draw the START menu: POKéDEX (once the player has it), POKéMON, ITEM, the player's name, SAVE (RESET while
;@ linked), OPTION and EXIT, with the cursor on the entry chosen last time.
;@ path: engine/menus/draw_start_menu
DrawStartMenu::
;> dex = event(EVENT_GOT_POKEDEX)
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
; menu with pokedex
;> rows = 0x0E                                  # a row for POKéDEX
	ld hl, (0) * SCREEN_WIDTH + (10) + wTileMap
	ld b, $0e
	ld c, $08
	jr nz, .drawTextBoxBorder
; shorter menu if the player doesn't have the pokedex
;> if not dex:
;>     rows = 0x0C
	ld hl, (0) * SCREEN_WIDTH + (10) + wTileMap
	ld b, $0c
	ld c, $08
.drawTextBoxBorder
;> TextBoxBorder(coord(10, 0), rows, 8)
	call TextBoxBorder
;> wMenuWatchedKeys = PAD_DOWN | PAD_UP | PAD_START | PAD_B | PAD_A
	ld a, PAD_DOWN | PAD_UP | PAD_START | PAD_B | PAD_A
	ld [wMenuWatchedKeys], a
;> wTopMenuItemY = 2
	ld a, $02
	ld [wTopMenuItemY], a ; Y position of first menu choice
;> wTopMenuItemX = 0x0B
	ld a, $0b
	ld [wTopMenuItemX], a ; X position of first menu choice
;> wCurrentMenuItem = wLastMenuItem = wBattleAndStartSavedMenuItem
	ld a, [wBattleAndStartSavedMenuItem] ; remembered menu selection from last time
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
;> wMenuWatchMovingOutOfBounds = 0
	xor a
	ld [wMenuWatchMovingOutOfBounds], a
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> pos = coord(12, 2)
	ld hl, (2) * SCREEN_WIDTH + (12) + wTileMap
;> if dex:
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
; case for not having pokedex
	ld a, $06
	jr z, .storeMenuItemCount
; case for having pokedex
;>     pos = PrintStartMenuItem(StartMenuPokedexText, pos)
	ld de, StartMenuPokedexText
	call PrintStartMenuItem
;>     wMaxMenuItem = 7
;> else:
;>     wMaxMenuItem = 6
	ld a, $07
.storeMenuItemCount
	ld [wMaxMenuItem], a ; number of menu items
;> pos = PrintStartMenuItem(StartMenuPokemonText, pos)
	ld de, StartMenuPokemonText
	call PrintStartMenuItem
;> pos = PrintStartMenuItem(StartMenuItemText, pos)
	ld de, StartMenuItemText
	call PrintStartMenuItem
;> pos = PrintStartMenuItem(addr(wPlayerName), pos)
	ld de, wPlayerName ; player's name
	call PrintStartMenuItem
;> pos = PrintStartMenuItem(StartMenuResetText if wStatusFlags4 >> BIT_LINK_CONNECTED & 1 else StartMenuSaveText, pos)
	ld a, [wStatusFlags4]
	bit BIT_LINK_CONNECTED, a
; case for not using link feature
	ld de, StartMenuSaveText
	jr z, .printSaveOrResetText
; case for using link feature
	ld de, StartMenuResetText
.printSaveOrResetText
	call PrintStartMenuItem
;> pos = PrintStartMenuItem(StartMenuOptionText, pos)
	ld de, StartMenuOptionText
	call PrintStartMenuItem
;> PlaceString(StartMenuExitText, pos)
	ld de, StartMenuExitText
	call PlaceString
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
	ret

;@ path: engine/menus/draw_start_menu
StartMenuPokedexText:
	db "POKéDEX@"

;@ path: engine/menus/draw_start_menu
StartMenuPokemonText:
	db "POKéMON@"

;@ path: engine/menus/draw_start_menu
StartMenuItemText:
	db "ITEM@"

;@ path: engine/menus/draw_start_menu
StartMenuSaveText:
	db "SAVE@"

;@ path: engine/menus/draw_start_menu
StartMenuResetText:
	db "RESET@"

;@ path: engine/menus/draw_start_menu
StartMenuExitText:
	db "EXIT@"

;@ path: engine/menus/draw_start_menu
StartMenuOptionText:
	db "OPTION@"

;@ def PrintStartMenuItem(text: de, pos: hl) -> hl
;@ One START menu entry; the next one goes two rows lower.
;@ test: pos = wTileMap + rand(0, 200); text = wTileMap + 300; mem[text] = rand(0x80, 0x99); mem[text + 1] = 0x50
;@ test: wStatusFlags5 = 1 << BIT_NO_TEXT_DELAY
;@ path: engine/menus/draw_start_menu
PrintStartMenuItem:
;> PlaceString(text, pos)
;> return pos + SCREEN_WIDTH * 2
	push hl
	call PlaceString
	pop hl
	ld de, SCREEN_WIDTH * 2
	add hl, de
	ret
;@ path: engine/link/cable_club_npc
;@ def CableClubNPC()
;@ The Cable Club receptionist: once the player has the Pokédex, try to reach another Game Boy over the cable
;@ (90 tries). If one answers, the game must be saved first; then both sides sync and go to the link menu.
;@ test: skip talks over the link cable
CableClubNPC::
;> PrintText(CableClubNPCWelcomeText)
	ld hl, CableClubNPCWelcomeText
	call PrintText
;> if not event(EVENT_GOT_POKEDEX):
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	jp nz, .receivedPokedex
; if the player hasn't received the pokedex
;>     DelayFrames(60)
	ld c, 60
	call DelayFrames
;>     PrintText(CableClubNPCMakingPreparationsText)
	ld hl, CableClubNPCMakingPreparationsText
	call PrintText
	jp .didNotConnect
.receivedPokedex
;> else:                                         # try to reach the other Game Boy
;>     wMenuJoypadPollCount = 1
	ld a, $1
	ld [wMenuJoypadPollCount], a
;>     wLinkTimeoutCounter = 90
;>     linked = True
	ld a, 90
	ld [wLinkTimeoutCounter], a
;>     while hSerialConnectionStatus not in (USING_INTERNAL_CLOCK, USING_EXTERNAL_CLOCK):
.establishConnectionLoop
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr z, .establishedConnection
	cp USING_EXTERNAL_CLOCK
	jr z, .establishedConnection
;>         # listen as the clocked side, then try once as the clocking side
;>         hSerialConnectionStatus = CONNECTION_NOT_ESTABLISHED
	ld a, CONNECTION_NOT_ESTABLISHED
	ldh [hSerialConnectionStatus], a
;>         rSB = ESTABLISH_CONNECTION_WITH_EXTERNAL_CLOCK
	ld a, ESTABLISH_CONNECTION_WITH_EXTERNAL_CLOCK
	ldh [rSB], a
;>         hSerialReceiveData = 0
	xor a
	ldh [hSerialReceiveData], a
;>         rSC = SC_START | SC_EXTERNAL
	ld a, SC_START | SC_EXTERNAL
; This vc_hook causes the Virtual Console to set [hSerialConnectionStatus] to
; USING_INTERNAL_CLOCK, which allows the player to proceed past the link
; receptionist's "Please wait." It assumes that hSerialConnectionStatus is at
; its original address.
	ldh [rSC], a
;>         wLinkTimeoutCounter -= 1
;>         if wLinkTimeoutCounter == 0:
	ld a, [wLinkTimeoutCounter]
	dec a
	ld [wLinkTimeoutCounter], a
	jr z, .failedToEstablishConnection
;>@nolink             linked = False
;>@giveup             break
;>         rSB = ESTABLISH_CONNECTION_WITH_INTERNAL_CLOCK
	ld a, ESTABLISH_CONNECTION_WITH_INTERNAL_CLOCK
	ldh [rSB], a
;>         rSC = SC_START | SC_INTERNAL
	ld a, SC_START | SC_INTERNAL
	ldh [rSC], a
;>         DelayFrame()
	call DelayFrame
	jr .establishConnectionLoop
.establishedConnection
;>     if not linked:
;>@fail         PrintText(CableClubNPCAreaReservedFor2FriendsLinkedByCableText)    # nobody answered
;>     else:
;>         Serial_SendZeroByte()
	call Serial_SendZeroByte
;>         DelayFrame()
	call DelayFrame
;>         Serial_SendZeroByte()
	call Serial_SendZeroByte
;>         DelayFrames(50)
	ld c, 50
	call DelayFrames
;>         PrintText(CableClubNPCPleaseApplyHereHaveToSaveText)
	ld hl, CableClubNPCPleaseApplyHereHaveToSaveText
	call PrintText
;>         wMenuJoypadPollCount = 0
	xor a
	ld [wMenuJoypadPollCount], a
;>         YesNoChoice()
	call YesNoChoice
;>         wMenuJoypadPollCount = 1
	ld a, $1
	ld [wMenuJoypadPollCount], a
;>         if wCurrentMenuItem:                  # NO
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .choseNo
;>@no1             CloseLinkConnection()
;>@no2             PrintText(CableClubNPCPleaseComeAgainText)
;>         else:
;>             SaveGameData()
	ld hl, SaveGameData
	ld b, BANK(SaveGameData)
	call Bankswitch
;>             WaitForSoundToFinish()
	call WaitForSoundToFinish
;>             PlaySoundWaitForCurrent(SFX_SAVE)
	ld a, SFX_SAVE
	call PlaySoundWaitForCurrent
;>             PrintText(CableClubNPCPleaseWaitText)
	ld hl, CableClubNPCPleaseWaitText
	call PrintText
;>             wUnknownSerialCounter[0] = 3
;>             wUnknownSerialCounter[1] = 0
	ld hl, wUnknownSerialCounter
	ld a, $3
	ld [hli], a
	xor a
	ld [hl], a
;>             hSerialReceivedNewData = 0
;>             wSerialExchangeNybbleSendData = 0
	ldh [hSerialReceivedNewData], a
	ld [wSerialExchangeNybbleSendData], a
;>             Serial_SyncAndExchangeNybble()
	call Serial_SyncAndExchangeNybble
;>             in_step = wUnknownSerialCounter[0] != 0xFF or wUnknownSerialCounter[1] != 0xFF
	ld hl, wUnknownSerialCounter
	ld a, [hli]
	inc a
	jr nz, .connected
	ld a, [hl]
	inc a
;>             if in_step:
	jr nz, .connected
;>@c1                 wUnknownSerialCounter[1] = 0; wUnknownSerialCounter[0] = 0
;>@c2                 return LinkMenu()
;>             # the other side went quiet
;>             for _ in range(10):
	ld b, 10
.syncLoop
;>                 DelayFrame()
	call DelayFrame
;>                 Serial_SendZeroByte()
	call Serial_SendZeroByte
	dec b
	jr nz, .syncLoop
;>             CloseLinkConnection()
	call CloseLinkConnection
;>             PrintText(CableClubNPCLinkClosedBecauseOfInactivityText)
	ld hl, CableClubNPCLinkClosedBecauseOfInactivityText
	call PrintText
	jr .didNotConnect
.failedToEstablishConnection
;=@fail
	ld hl, CableClubNPCAreaReservedFor2FriendsLinkedByCableText
	call PrintText
	jr .didNotConnect
.choseNo
;=@no1
	call CloseLinkConnection
;=@no2
	ld hl, CableClubNPCPleaseComeAgainText
	call PrintText
.didNotConnect
;> # no link
;> wUnknownSerialCounter[0] = 0
;> wUnknownSerialCounter[1] = 0
	xor a
	ld hl, wUnknownSerialCounter
	ld [hli], a
	ld [hl], a
;> wStatusFlags4 = wStatusFlags4 & ~(1 << BIT_LINK_CONNECTED) & 0xFF
	ld hl, wStatusFlags4
	res BIT_LINK_CONNECTED, [hl]
;> wMenuJoypadPollCount = 0
	xor a
	ld [wMenuJoypadPollCount], a
	ret
.connected
;=@c1
	xor a
	ld [hld], a
	ld [hl], a
;=@c2
	ld hl, LinkMenu
	ld b, BANK(LinkMenu)
	jp Bankswitch

;@ path: engine/link/cable_club_npc
CableClubNPCAreaReservedFor2FriendsLinkedByCableText:
	db TX_FAR
	dw _CableClubNPCAreaReservedFor2FriendsLinkedByCableText
	db BANK(_CableClubNPCAreaReservedFor2FriendsLinkedByCableText)
	db TX_END

