	db TX_FAR
	dw _CableClubNPCMakingPreparationsText
	db BANK(_CableClubNPCMakingPreparationsText)
	db TX_END

;@ path: engine/link/cable_club_npc
;@ def CloseLinkConnection()
;@ Hang up the link: back to listening as the clocked side with no connection.
;@ test: skip waits for frames
CloseLinkConnection:
;> Delay3()
	call Delay3
;> hSerialConnectionStatus = CONNECTION_NOT_ESTABLISHED
	ld a, CONNECTION_NOT_ESTABLISHED
	ldh [hSerialConnectionStatus], a
;> rSB = ESTABLISH_CONNECTION_WITH_EXTERNAL_CLOCK
	ld a, ESTABLISH_CONNECTION_WITH_EXTERNAL_CLOCK
	ldh [rSB], a
;> hSerialReceiveData = 0
	xor a
	ldh [hSerialReceiveData], a
;> rSC = SC_START | SC_EXTERNAL
	ld a, SC_START | SC_EXTERNAL
	ldh [rSC], a
	ret
; function to draw various text boxes
;@ def DisplayTextBoxID_(corner: hl = 0, y: b = 0, x: c = 0)
;@ Draw text box wTextBoxID. A two-option menu gets its corner and text position from the caller (hl, b, c);
;@ every other box comes from a table: one that runs its own function, one that is just a border, or a border
;@ with text in it.
;@ path: engine/menus/text_box
DisplayTextBoxID_::
;> if wTextBoxID == TWO_OPTION_MENU:
;>     return DisplayTwoOptionMenu(corner, y, x)
	ld a, [wTextBoxID]
	cp TWO_OPTION_MENU
	jp z, DisplayTwoOptionMenu
;> entry, found = SearchTextBoxTable(TextBoxFunctionTable, wTextBoxID, 3)
	ld c, a
	ld hl, TextBoxFunctionTable
	ld de, 3
	call SearchTextBoxTable
;> if found:
	jr c, .functionTableMatch
;>@func     call(mem16[entry])                    # the box's own drawing function
;>     return
;> entry, found = SearchTextBoxTable(TextBoxCoordTable, wTextBoxID, 5)
	ld hl, TextBoxCoordTable
	ld de, 5
	call SearchTextBoxTable
;> if found:                                   # just a border
	jr c, .coordTableMatch
;>@coords     rows, cols, top, left, _ = GetTextBoxIDCoords(entry)
;>@border     return TextBoxBorder(GetAddressOfScreenCoords(top, left), rows, cols)
;> entry, found = SearchTextBoxTable(TextBoxTextAndCoordTable, wTextBoxID, 9)
	ld hl, TextBoxTextAndCoordTable
	ld de, 9
	call SearchTextBoxTable
;> if not found:
;>     return
	jr c, .textAndCoordTableMatch
.done
	ret
.functionTableMatch
;=@func
	ld a, [hli]
	ld h, [hl]
	ld l, a ; hl = address of function
	ld de, .done
	push de
	jp hl ; jump to the function
.coordTableMatch
;=@coords
	call GetTextBoxIDCoords
;=@border
	call GetAddressOfScreenCoords
	call TextBoxBorder
	ret
.textAndCoordTableMatch
;> rows, cols, top, left, entry = GetTextBoxIDCoords(entry)   # a border with text in it
	call GetTextBoxIDCoords
;> TextBoxBorder(GetAddressOfScreenCoords(top, left), rows, cols)
	push hl
	call GetAddressOfScreenCoords
	call TextBoxBorder
;> text, dest = GetTextBoxIDText(entry)
	pop hl
	call GetTextBoxIDText
;> flags = wStatusFlags5
	ld a, [wStatusFlags5]
	push af
;> wStatusFlags5 = flags | 1 << BIT_NO_TEXT_DELAY
	ld a, [wStatusFlags5]
	set BIT_NO_TEXT_DELAY, a
	ld [wStatusFlags5], a
;> PlaceString(text, dest)
	call PlaceString
;> wStatusFlags5 = flags
	pop af
	ld [wStatusFlags5], a
;> UpdateSprites()
	call UpdateSprites
	ret

; function to search a table terminated with $ff for a byte matching c in increments of de
; sets carry flag if a match is found and clears carry flag if not
;@ def SearchTextBoxTable(table: hl, id: c, stride: de) -> (hl, carry)
;@ Find text box `id` in a table of stride-byte entries ending in $FF. Carry and hl just past the ID if found.
;@ test: stride = rand(1, 6); table = rand_ram(64); mem[table + stride * rand(0, 9)] = 0xFF
;@ path: engine/menus/text_box
SearchTextBoxTable:
;> while True:
	dec de
.loop
;>     v = mem[table]
;>     table += 1
	ld a, [hli]
;>     if v == 0xFF:
;>         return (table, False)
	cp $ff
	jr z, .notFound
;>     if v == id:
;>         return (table, True)
	cp c
	jr z, .found
;>     table += stride - 1
	add hl, de
	jr .loop
.found
	scf
.notFound
	ret

; function to load coordinates from the TextBoxCoordTable or the TextBoxTextAndCoordTable
; INPUT:
; hl = address of coordinates
; OUTPUT:
; b = height
; c = width
; d = row of upper left corner
; e = column of upper left corner
;@ def GetTextBoxIDCoords(src: hl) -> (b, c, d, e, hl)
;@ A text box's corners (left, top, right, bottom) from a table: returns height and width inside the border, then
;@ top row and left column.
;@ path: engine/menus/text_box
GetTextBoxIDCoords:
;> left = mem[src]                             # the upper left corner
;> top = mem[src + 1]
	ld a, [hli] ; column of upper left corner
	ld e, a
	ld a, [hli] ; row of upper left corner
	ld d, a
;> width = (mem[src + 2] - left - 1) & 0xFF    # inside the border
	ld a, [hli] ; column of lower right corner
	sub e
	dec a
	ld c, a     ; c = width
;> height = (mem[src + 3] - top - 1) & 0xFF
	ld a, [hli] ; row of lower right corner
	sub d
	dec a
	ld b, a     ; b = height
;> return (height, width, top, left, src + 4)
	ret

; function to load a text address and text coordinates from the TextBoxTextAndCoordTable
;@ def GetTextBoxIDText(src: hl) -> (de, hl)
;@ A text box's text from a table entry: the text's address, and where on the screen it goes.
;@ path: engine/menus/text_box
GetTextBoxIDText:
;> text = mem16[src]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a ; de = address of text
	push de ; save text address
;> col, row = mem[src + 2], mem[src + 3]       # where the text goes
	ld a, [hli]
	ld e, a ; column of upper left corner of text
	ld a, [hl]
	ld d, a ; row of upper left corner of text
;> dest = GetAddressOfScreenCoords(row, col)
	call GetAddressOfScreenCoords
;> return (text, dest)
	pop de ; restore text address
	ret

; function to point hl to the screen coordinates
; INPUT:
; d = row
; e = column
; OUTPUT:
; hl = address of upper left corner of text box
;@ def GetAddressOfScreenCoords(row: d, col: e) -> hl
;@ The address of screen tile (col, row) in wTileMap.
;@ path: engine/menus/text_box
GetAddressOfScreenCoords:
;> addr = coord(0, 0)
	push bc
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
;> step = SCREEN_WIDTH
	ld bc, SCREEN_WIDTH
.loop ; loop to add d rows to the base address
;>@lp while row:
	ld a, d
	and a
	jr z, .addedRows
;>     addr += step
	add hl, bc
;>     row -= 1
	dec d
;=@lp
	jr .loop
.addedRows
;> return addr + col
	pop bc
	add hl, de
	ret

