;@ def DisplayMoneyBox()
;@ The MONEY box at the top right, with the player's money.
;@ test: hLoadedROMBank = 1    # the bank this code runs in (DisplayTextBoxID switches back to it)
;@ path: engine/menus/text_box
DisplayMoneyBox:
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> wTextBoxID = MONEY_BOX_TEMPLATE
	ld a, MONEY_BOX_TEMPLATE
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
;> ClearScreenArea(coord(13, 1), 6, 1)
	ld hl, (1) * SCREEN_WIDTH + (13) + wTileMap
	ld b, 1
	ld c, 6
	call ClearScreenArea
;> PrintBCDNumber(addr(wPlayerMoney), coord(12, 1), 3 | LEADING_ZEROES | MONEY_SIGN)
	ld hl, (1) * SCREEN_WIDTH + (12) + wTileMap
	ld de, wPlayerMoney
	ld c, 3 | LEADING_ZEROES | MONEY_SIGN
	call PrintBCDNumber
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
	ret

