;@ def DoBuySellQuitMenu() -> carry
;@ A shop's BUY / SELL / QUIT menu. The choice goes to wChosenMenuItem; QUIT or B sets wMenuExitMethod to
;@ CANCELLED_MENU and returns carry.
;@ test: hLoadedROMBank = 1    # the bank this code runs in (DisplayTextBoxID switches back to it)
;@ path: engine/menus/text_box
DoBuySellQuitMenu:
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld a, [wStatusFlags5]
	set BIT_NO_TEXT_DELAY, a
	ld [wStatusFlags5], a
;> wChosenMenuItem = 0
	xor a
	ld [wChosenMenuItem], a
;> wTextBoxID = BUY_SELL_QUIT_MENU_TEMPLATE
	ld a, BUY_SELL_QUIT_MENU_TEMPLATE
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 2
	ld a, $2
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 1
	ld a, $1
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, $1
	ld [wTopMenuItemX], a
;> wCurrentMenuItem = wLastMenuItem = wMenuWatchMovingOutOfBounds = 0
	xor a
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
	ld [wMenuWatchMovingOutOfBounds], a
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld a, [wStatusFlags5]
	res BIT_NO_TEXT_DELAY, a
	ld [wStatusFlags5], a
;> keys = PlaceUnfilledArrowMenuCursor(HandleMenuInput())
	call HandleMenuInput
	call PlaceUnfilledArrowMenuCursor
;> chosen = keys & PAD_A or not keys & PAD_B   # (B is the only other key watched)
	bit B_PAD_A, a
	jr nz, .pressedA
	bit B_PAD_B, a ; always true since only A/B are watched
	jr z, .pressedA
;> if not chosen:
;>     wMenuExitMethod = CANCELLED_MENU
	ld a, CANCELLED_MENU
	ld [wMenuExitMethod], a
	jr .quit
.pressedA
;> if chosen:
;>     wMenuExitMethod = CHOSE_MENU_ITEM
	ld a, CHOSE_MENU_ITEM
	ld [wMenuExitMethod], a
;>     wChosenMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wChosenMenuItem], a
;>     if wCurrentMenuItem != wMaxMenuItem:    # not QUIT
;>         return wMaxMenuItem < wCurrentMenuItem
	ld b, a
	ld a, [wMaxMenuItem]
	cp b
	jr z, .quit
	ret
.quit
;> wMenuExitMethod = CANCELLED_MENU
	ld a, CANCELLED_MENU
	ld [wMenuExitMethod], a
;> wChosenMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wChosenMenuItem], a
;> return True
	scf
	ret

; displays a menu with two options to choose from
; b = Y of upper left corner of text region
; c = X of upper left corner of text region
; hl = address where the text box border should be drawn
;@ def DisplayTwoOptionMenu(corner: hl, y: b, x: c) -> carry
;@ A two-option menu (YES/NO and the like, wTwoOptionMenuID) with its border at corner and its cursor at (x, y).
;@ The tiles under it are kept and put back. B picks the second option, except in the NO/YES menu where B does
;@ nothing. Carry when the second option was chosen.
;@ path: engine/menus/text_box
DisplayTwoOptionMenu:
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	push hl
	ld a, [wStatusFlags5]
	set BIT_NO_TEXT_DELAY, a
	ld [wStatusFlags5], a

; pointless because both values are overwritten before they are read
;> wChosenMenuItem = 0
	xor a
	ld [wChosenMenuItem], a
;> wMenuExitMethod = 0
	ld [wMenuExitMethod], a

;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 1
	ld a, $1
	ld [wMaxMenuItem], a
;> wTopMenuItemY = y
	ld a, b
	ld [wTopMenuItemY], a
;> wTopMenuItemX = x
	ld a, c
	ld [wTopMenuItemX], a
;> wLastMenuItem = 0
	xor a
	ld [wLastMenuItem], a
;> wMenuWatchMovingOutOfBounds = 0
	ld [wMenuWatchMovingOutOfBounds], a
;> second = wTwoOptionMenuID >> BIT_SECOND_MENU_OPTION_DEFAULT & 1
	push hl
	ld hl, wTwoOptionMenuID
	bit BIT_SECOND_MENU_OPTION_DEFAULT, [hl]
;> wTwoOptionMenuID &= ~(1 << BIT_SECOND_MENU_OPTION_DEFAULT) & 0xFF
	res BIT_SECOND_MENU_OPTION_DEFAULT, [hl]
;> wCurrentMenuItem = second                   # the cursor may start on option 2
	jr z, .storeCurrentMenuItem
	inc a
.storeCurrentMenuItem
	ld [wCurrentMenuItem], a
;> TwoOptionMenu_SaveScreenTiles(corner)
	pop hl
	push hl
	push hl
	call TwoOptionMenu_SaveScreenTiles
;> id = wTwoOptionMenuID
	ld a, [wTwoOptionMenuID]
;> entry = TwoOptionMenuStrings               # 5 bytes per menu: width, height, blank line?, text
	ld hl, TwoOptionMenuStrings
	ld e, a
	ld d, $0
;>@m5 for _ in range(5):
	ld a, $5
.menuStringLoop
;>     entry += id
	add hl, de
;=@m5
	dec a
	jr nz, .menuStringLoop
;> cols, rows = mem[entry], mem[entry + 1]
	ld a, [hli]
	ld c, a
	ld a, [hli]
	ld b, a
	ld e, l
	ld d, h
;> if wTwoOptionMenuID == TRADE_CANCEL_MENU:
	pop hl
	push de
	ld a, [wTwoOptionMenuID]
	cp TRADE_CANCEL_MENU
	jr nz, .notTradeCancelMenu
;>     CableClub_TextBoxBorder(corner, rows, cols)
	call CableClub_TextBoxBorder
	jr .afterTextBoxBorder
;> else:
;>     TextBoxBorder(corner, rows, cols)
.notTradeCancelMenu
	call TextBoxBorder
.afterTextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> offset = 2 * SCREEN_WIDTH + 2 if mem[entry + 2] else SCREEN_WIDTH + 2    # a blank line before the first option?
	pop hl
	ld a, [hli]
	and a ; put blank line before first menu item?
	ld bc, SCREEN_WIDTH + 2
	jr z, .noBlankLine
	ld bc, 2 * SCREEN_WIDTH + 2
.noBlankLine
;> text = mem16[entry + 3]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;> PlaceString(text, corner + offset)
	pop hl
	add hl, bc
	call PlaceString
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> if wTwoOptionMenuID == NO_YES_MENU:
	ld a, [wTwoOptionMenuID]
	cp NO_YES_MENU
	jr nz, .notNoYesMenu
; No/Yes menu
; this menu type ignores the B button
; it only seems to be used when confirming the deletion of a save file
;>     wTwoOptionMenuID = 0
	xor a
	ld [wTwoOptionMenuID], a
;>     flags = wMiscFlags
	ld a, [wMiscFlags]
	push af
;>     wMiscFlags |= 1 << BIT_NO_MENU_BUTTON_SOUND
	push hl
	ld hl, wMiscFlags
	bit BIT_NO_MENU_BUTTON_SOUND, [hl]
	set BIT_NO_MENU_BUTTON_SOUND, [hl]
	pop hl
;>@ny     while True:                             # only A counts
.noYesMenuInputLoop
;>         if not HandleMenuInput() & PAD_B:
;>             break
	call HandleMenuInput
	bit B_PAD_B, a
	jr nz, .noYesMenuInputLoop ; try again if B was not pressed
;>     wMiscFlags = flags
	pop af
	pop hl
	ld [wMiscFlags], a
;>     PlaySound(SFX_PRESS_AB)
	ld a, SFX_PRESS_AB
	call PlaySound
;>     pressed_b = False
	jr .pressedAButton
;> else:
;>     wTwoOptionMenuID = 0
.notNoYesMenu
	xor a
	ld [wTwoOptionMenuID], a
;>     pressed_b = HandleMenuInput() & PAD_B      # B picks the second option
	call HandleMenuInput
	pop hl
	bit B_PAD_B, a
	jr nz, .choseSecondMenuItem ; automatically choose the second option if B is pressed
.pressedAButton
;> if not pressed_b:
;>     wChosenMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wChosenMenuItem], a
;> if pressed_b or wCurrentMenuItem != 0:
	and a
	jr nz, .choseSecondMenuItem
;>@s1     wCurrentMenuItem = wChosenMenuItem = 1
;>@s2     wMenuExitMethod = CHOSE_SECOND_ITEM
;>@s3     DelayFrames(15)
;>@s4     TwoOptionMenu_RestoreScreenTiles(corner)
;>@s5     return True
; chose first menu item
;> wMenuExitMethod = CHOSE_FIRST_ITEM
	ld a, CHOSE_FIRST_ITEM
	ld [wMenuExitMethod], a
;> DelayFrames(15)
	ld c, 15
	call DelayFrames
;> TwoOptionMenu_RestoreScreenTiles(corner)
	call TwoOptionMenu_RestoreScreenTiles
;> return False
	and a
	ret
.choseSecondMenuItem
;=@s1
	ld a, 1
	ld [wCurrentMenuItem], a
	ld [wChosenMenuItem], a
;=@s2
	ld a, CHOSE_SECOND_ITEM
	ld [wMenuExitMethod], a
;=@s3
	ld c, 15
	call DelayFrames
;=@s4
	call TwoOptionMenu_RestoreScreenTiles
;=@s5
	scf
	ret

; Some of the wider/taller two option menus will not have the screen areas
; they cover be fully saved/restored by the two functions below.
; The bottom and right edges of the menu may remain after the function returns.

;@ def TwoOptionMenu_SaveScreenTiles(src: hl) -> hl
;@ Keep the 6 x 5 tiles a YES / NO menu will cover in wBuffer.
;@ test: src = rand(0xC3A0, 0xC400)
;@ path: engine/menus/text_box
TwoOptionMenu_SaveScreenTiles:
;>@rows for row in range(5):
;>@cols     for col in range(6):
	ld de, wBuffer
	ld bc, ((5) & $ff) << 8 + ((6) & $ff)
.loop
;>         wBuffer[row * 6 + col] = mem[src + col]
	ld a, [hli]
	ld [de], a
	inc de
;=@cols
	dec c
	jr nz, .loop
;>     src += SCREEN_WIDTH                     # the next row
	push bc
	ld bc, SCREEN_WIDTH - 6
	add hl, bc
	pop bc
;=@rows
	ld c, $6
	dec b
	jr nz, .loop
;> return src
	ret

;@ def TwoOptionMenu_RestoreScreenTiles(dest: hl)
;@ Put back the tiles TwoOptionMenu_SaveScreenTiles kept.
;@ test: dest = rand(0xC3A0, 0xC400)
;@ path: engine/menus/text_box
TwoOptionMenu_RestoreScreenTiles:
;>@rows for row in range(5):
;>@cols     for col in range(6):
	ld de, wBuffer
	ld bc, ((5) & $ff) << 8 + ((6) & $ff)
.loop
;>         mem[dest + col] = wBuffer[row * 6 + col]
	ld a, [de]
	inc de
	ld [hli], a
;=@cols
	dec c
	jr nz, .loop
;>     dest += SCREEN_WIDTH                    # the next row
	push bc
	ld bc, SCREEN_WIDTH - 6
	add hl, bc
	pop bc
;=@rows
	ld c, 6
	dec b
	jr nz, .loop
;> UpdateSprites()
	call UpdateSprites
	ret


;@ path: engine/menus/text_box
TwoOptionMenuStrings:
; entries correspond to *_MENU constants
	; width, height, blank line before first menu item?, text pointer
	db 4, 3, FALSE
	dw .YesNoMenu
	db 6, 3, FALSE
	dw .NorthWestMenu
	db 6, 3, FALSE
	dw .SouthEastMenu
	db 6, 3, FALSE
	dw .YesNoMenu
	db 6, 3, FALSE
	dw .NorthEastMenu
	db 7, 3, FALSE
	dw .TradeCancelMenu
	db 7, 4, TRUE
	dw .HealCancelMenu
	db 4, 3, FALSE
	dw .NoYesMenu

