;@ def DisplayFieldMoveMonMenu()
;@ The menu for a party Pokémon: its field moves (CUT, FLY...) above STATS / SWITCH / CANCEL, in a box that grows
;@ two rows taller and as much wider as the longest field move name needs.
;@ path: engine/menus/text_box
DisplayFieldMoveMonMenu:
;> for i in range(4):
;>     mem[addr(wFieldMoves) + i] = 0
	xor a
	ld hl, wFieldMoves
	ld [hli], a ; wFieldMoves
	ld [hli], a ; wFieldMoves + 1
	ld [hli], a ; wFieldMoves + 2
	ld [hli], a ; wFieldMoves + 3
;> wNumFieldMoves = 0
;> wFieldMovesLeftmostXCoord = 12
	ld [hli], a ; wNumFieldMoves
	ld [hl], 12 ; wFieldMovesLeftmostXCoord
;> GetMonFieldMoves()
	call GetMonFieldMoves
;> n = wNumFieldMoves
;> if not n:
	ld a, [wNumFieldMoves]
	and a
	jr nz, .fieldMovesExist

; no field moves
;>     TextBoxBorder(coord(11, 11), 5, 7)
	ld hl, (11) * SCREEN_WIDTH + (11) + wTileMap
	ld b, 5
	ld c, 7
	call TextBoxBorder
;>     UpdateSprites()
	call UpdateSprites
;>     hFieldMoveMonMenuTopMenuItemX = 12
	ld a, 12
	ldh [hFieldMoveMonMenuTopMenuItemX], a
;>     return PlaceString(PokemonMenuEntries, coord(13, 12))
	ld hl, (12) * SCREEN_WIDTH + (13) + wTileMap
	ld de, PokemonMenuEntries
	jp PlaceString

.fieldMovesExist
	push af

; Calculate the text box position and dimensions based on the leftmost X coord
; of the field move names before adjusting for the number of field moves.
;> left = (wFieldMovesLeftmostXCoord - 1) & 0xFF
	ld hl, (11) * SCREEN_WIDTH + (0) + wTileMap
	ld a, [wFieldMovesLeftmostXCoord]
	dec a
	ld e, a
;> corner = coord(0, 11) + left
	ld d, 0
	add hl, de
;> rows, cols = 5, (18 - left) & 0xFF
	ld b, 5
	ld a, 18
	sub e
	ld c, a
	pop af

; For each field move, move the top of the text box up 2 rows while the leaving
; the bottom of the text box at the bottom of the screen.
;>@fh for _ in range(n):
	ld de, -SCREEN_WIDTH * 2
.textBoxHeightLoop
;>     corner -= 2 * SCREEN_WIDTH
	add hl, de
;>     rows += 2
	inc b
	inc b
;=@fh
	dec a
	jr nz, .textBoxHeightLoop

; Make space for an extra blank row above the top field move.
;> corner -= SCREEN_WIDTH
;> rows += 1
	ld de, -SCREEN_WIDTH
	add hl, de
	inc b

;> TextBoxBorder(corner, rows, cols)
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites

; Calculate the position of the first field move name to print.
;> pos = coord(0, 12) + wFieldMovesLeftmostXCoord + 1
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld a, [wFieldMovesLeftmostXCoord]
	inc a
	ld e, a
	ld d, 0
	add hl, de
;> for _ in range(n):
;>     pos -= 2 * SCREEN_WIDTH
	ld de, -SCREEN_WIDTH * 2
	ld a, [wNumFieldMoves]
.calcFirstFieldMoveYLoop
	add hl, de
	dec a
	jr nz, .calcFirstFieldMoveYLoop

;> wNumFieldMoves = 0                          # also ends the list in wFieldMoves
;> p = addr(wFieldMoves)
	xor a
	ld [wNumFieldMoves], a
	ld de, wFieldMoves
.printNamesLoop
;>@names while True:
;>     name = FieldMoveNames
	push hl
	ld hl, FieldMoveNames
;>     if not mem[p]:
;>         break
	ld a, [de]
	and a
	jr z, .donePrintingNames
;>     index = mem[p]
;>     p += 1
	inc de
	ld b, a ; index of name
.skipNamesLoop ; skip past names before the name we want
;>@skip     for _ in range((index - 1) & 0xFF):     # skip the names before it
	dec b
	jr z, .reachedName
.skipNameLoop ; skip past current name
;>@sn         while True:                        # past the next '@'
;>             ch = mem[name]
;>             name += 1
	ld a, [hli]
;>             if ch == 0x50:
;>                 break
	cp '@'
	jr nz, .skipNameLoop
;=@skip
	jr .skipNamesLoop
.reachedName
;>     text = name
	ld b, h
	ld c, l
	pop hl
;>     PlaceString(text, pos)
	push de
	ld d, b
	ld e, c
	call PlaceString
;>     pos += 2 * SCREEN_WIDTH
	ld bc, SCREEN_WIDTH * 2
	add hl, bc
	pop de
;=@names
	jr .printNamesLoop

.donePrintingNames
;> hFieldMoveMonMenuTopMenuItemX = wFieldMovesLeftmostXCoord
	pop hl
	ld a, [wFieldMovesLeftmostXCoord]
	ldh [hFieldMoveMonMenuTopMenuItemX], a
;> pos = coord(0, 12) + wFieldMovesLeftmostXCoord + 1
	ld hl, (12) * SCREEN_WIDTH + (0) + wTileMap
	ld a, [wFieldMovesLeftmostXCoord]
	inc a
	ld e, a
	ld d, 0
	add hl, de
;> return PlaceString(PokemonMenuEntries, pos)  # STATS, SWITCH, CANCEL
	ld de, PokemonMenuEntries
	jp PlaceString

; see also FieldMoveDisplayData
;@ path: engine/menus/text_box
FieldMoveNames:
	db "CUT@"
	db "FLY@"
	db "@"
	db "SURF@"
	db "STRENGTH@"
	db "FLASH@"
	db "DIG@"
	db "TELEPORT@"
	db "SOFTBOILED@"

;@ path: engine/menus/text_box
PokemonMenuEntries:
	db   "STATS"
	db "<NEXT>", "SWITCH"
	db "<NEXT>", "CANCEL@"

;@ def GetMonFieldMoves()
;@ List the field moves (CUT, FLY, SURF...) party Pokémon wWhichPokemon knows, for its menu: their name indexes in
;@ wFieldMoves, how many in wNumFieldMoves, and the leftmost column the menu needs in wFieldMovesLeftmostXCoord.
;@ test: wWhichPokemon = rand(0, 5)
;@ path: engine/menus/text_box
GetMonFieldMoves:
;> moves = AddNTimes(wPartyMon1Moves, PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld a, [wWhichPokemon]
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld d, h
	ld e, l
;> out = wFieldMoves
;>@moves for i in range(NUM_MOVES):
	ld c, NUM_MOVES + 1
	ld hl, wFieldMoves
.loop
;=@moves
	push hl
.nextMove
	dec c
	jr z, .done
;>     move = mem[moves + i]
	ld a, [de] ; move ID
;>     if move == 0:
;>         break
	and a
	jr z, .done
	ld b, a
	inc de
;>     p = FieldMoveDisplayData
	ld hl, FieldMoveDisplayData
.fieldMoveLoop
;>@scan     while mem[p] != 0xFF:                  # (the end: not a field move)
	ld a, [hli]
	cp $ff
	jr z, .nextMove ; if the move is not a field move
;>         if mem[p] == move:
	cp b
	jr z, .foundFieldMove
;>@f1             wLastFieldMoveID = move
;>@f2             mem[out] = mem[p + 1]               # its name index
;>@f3             out += 1
;>@f4             wNumFieldMoves += 1
;>@f5             if mem[p + 2] <= wFieldMovesLeftmostXCoord:   # the column its name needs
;>@f6                 wFieldMovesLeftmostXCoord = mem[p + 2]
;>@f7             break
;>         p += 3
	inc hl
	inc hl
;=@scan
	jr .fieldMoveLoop
.foundFieldMove
;=@f1
	ld a, b
	ld [wLastFieldMoveID], a
;=@f2
	ld a, [hli] ; field move name index
	ld b, [hl] ; field move leftmost X coordinate
	pop hl
	ld [hli], a ; store name index in wFieldMoves
;=@f4
	ld a, [wNumFieldMoves]
	inc a
	ld [wNumFieldMoves], a
;=@f5
	ld a, [wFieldMovesLeftmostXCoord]
	cp b
	jr c, .skipUpdatingLeftmostXCoord
;=@f6
	ld a, b
	ld [wFieldMovesLeftmostXCoord], a
.skipUpdatingLeftmostXCoord
;=@f7
	ld a, [wLastFieldMoveID]
	ld b, a
	jr .loop
.done
;> return
	pop hl
	ret

;@ path: engine/menus/text_box
FieldMoveDisplayData:
	; move id, FieldMoveNames index, leftmost tile
	; (leftmost tile = -1 + tile column in which the first
	;  letter of the move's name should be displayed)
	db CUT,        1, $0C
	db FLY,        2, $0C
	db ANIM_B4,    3, $0C ; unused
	db SURF,       4, $0C
	db STRENGTH,   5, $0A
	db FLASH,      6, $0C
	db DIG,        7, $0C
	db TELEPORT,   8, $0A
	db SOFTBOILED, 9, $08
	db -1 ; end
;@ path: engine/battle/move_effects/drain_hp
;@ def DrainHPEffect_()
;@ Absorb, Mega Drain, Leech Life and Dream Eater: the attacker regains half the damage it dealt (at least 1 HP),
;@ never beyond its maximum, and its HP bar slides up.
DrainHPEffect_:
;> damage = (mem[wDamage] << 8 | mem[wDamage + 1]) >> 1     # half the damage dealt
	ld hl, wDamage
	ld a, [hl]
	srl a ; divide damage by 2
;> mem[wDamage] = hi(damage)
	ld [hli], a
;> mem[wDamage + 1] = lo(damage)                    # (the bit shifted out goes in at the top)
	ld a, [hl]
	rr a
	ld [hld], a
;> if damage == 0:
	or [hl] ; is damage 0?
	jr nz, .getAttackerHP
; if damage is 0, increase to 1 so that the attacker gains at least 1 HP
;>     damage = 1
;>     mem[wDamage + 1] = 1
	inc hl
	inc [hl]
.getAttackerHP
;> if hWhoseTurn == 0:
;>     hp, max_hp = wBattleMonHP, wBattleMonMaxHP
	ld hl, wBattleMonHP
	ld de, wBattleMonMaxHP
	ldh a, [hWhoseTurn]
	and a
	jp z, .addDamageToAttackerHP
;> else:
;>     hp, max_hp = wEnemyMonHP, wEnemyMonMaxHP
	ld hl, wEnemyMonHP
	ld de, wEnemyMonMaxHP
.addDamageToAttackerHP
;> # the HP bar keeps its numbers little-endian
;> mem[wHPBarOldHP], mem[wHPBarOldHP + 1] = mem[hp + 1], mem[hp]
	ld bc, wHPBarOldHP+1
; copy current HP to wHPBarOldHP
	ld a, [hli]
	ld [bc], a
	ld a, [hl]
	dec bc
	ld [bc], a
;> mem[wHPBarMaxHP + 1] = mem[max_hp]
; copy max HP to wHPBarMaxHP
	ld a, [de]
	dec bc
	ld [bc], a
;> mem[wHPBarMaxHP] = mem[max_hp + 1]
	inc de
	ld a, [de]
	dec bc
	ld [bc], a
;> new = (mem[hp] << 8 | mem[hp + 1]) + damage
;> mem[hp + 1] = mem[wHPBarNewHP] = lo(new)
; add damage to attacker's HP and copy new HP to wHPBarNewHP
	ld a, [wDamage + 1]
	ld b, [hl]
	add b
	ld [hld], a
	ld [wHPBarNewHP], a
;> mem[hp] = mem[wHPBarNewHP + 1] = hi(new)    # past 65535 goes straight to the cap
	ld a, [wDamage]
	ld b, [hl]
	adc b
	ld [hli], a
	ld [wHPBarNewHP+1], a
	jr c, .capToMaxHP ; if HP > 65,535, cap to max HP
;> top = mem[max_hp] << 8 | mem[max_hp + 1]
; compare HP with max HP
	ld a, [hld]
	ld b, a
	ld a, [de]
	dec de
	sub b
;> if new > top:
	ld a, [hli]
	ld b, a
	ld a, [de]
	inc de
	sbc b
	jr nc, .next
.capToMaxHP
;>     new = top
;>     mem[hp + 1] = mem[wHPBarNewHP] = lo(new)
	ld a, [de]
	ld [hld], a
	ld [wHPBarNewHP], a
;>     mem[hp] = mem[wHPBarNewHP + 1] = hi(new)
	dec de
	ld a, [de]
	ld [hli], a
	ld [wHPBarNewHP+1], a
	inc de
.next
;> if hWhoseTurn == 0:
;>     bar, bar_type = coord(10, 9), 1      # the player's bar
	ldh a, [hWhoseTurn]
	and a
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ld a, $1
	jr z, .next2
;> else:
;>     bar, bar_type = coord(2, 2), 0       # the enemy's bar
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	xor a
.next2
;> wHPBarType = bar_type
;> predef(UpdateHPBar2, hl=bar)
	ld [wHPBarType], a
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;> predef(DrawPlayerHUDAndHPBar)
	ld a, (DrawPlayerHUDAndHPBarPredef - PredefPointers) / 3
	call Predef
;> predef(DrawEnemyHUDAndHPBar)
	ld a, (DrawEnemyHUDAndHPBarPredef - PredefPointers) / 3
	call Predef
;> ReadPlayerMonCurHPAndStatus()
	ld hl, ReadPlayerMonCurHPAndStatus
	ld b, BANK(ReadPlayerMonCurHPAndStatus)
	call Bankswitch
;> text = SuckedHealthText
;> effect = wPlayerMoveEffect if hWhoseTurn == 0 else wEnemyMoveEffect
	ld hl, SuckedHealthText
	ldh a, [hWhoseTurn]
	and a
	ld a, [wPlayerMoveEffect]
	jr z, .next3
	ld a, [wEnemyMoveEffect]
.next3
;> if effect == DREAM_EATER_EFFECT:
;>     text = DreamWasEatenText
	cp DREAM_EATER_EFFECT
	jr nz, .printText
	ld hl, DreamWasEatenText
.printText
;> PrintText(text)
	jp PrintText

;@ path: engine/battle/move_effects/drain_hp
SuckedHealthText:
	db TX_FAR
	dw _SuckedHealthText
	db BANK(_SuckedHealthText)
	db TX_END

;@ path: engine/battle/move_effects/drain_hp
DreamWasEatenText:
	db TX_FAR
	dw _DreamWasEatenText
	db BANK(_DreamWasEatenText)
	db TX_END
;@ def PlayerPC()
;@ The player's own item storage. Turned on from the bedroom PC it plays the PC sound and greeting first; from a
;@ Pokémon Center PC (BIT_USING_GENERIC_PC) it goes straight to the menu.
;@ path: engine/menus/players_pc
PlayerPC::
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> wNameListType = ITEM_NAME
	ld a, ITEM_NAME
	ld [wNameListType], a
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> wBagSavedMenuItem = 0
	xor a
	ld [wBagSavedMenuItem], a
;> wParentMenuItem = 0
	ld [wParentMenuItem], a
;> if not wMiscFlags >> BIT_USING_GENERIC_PC & 1:
	ld a, [wMiscFlags]
	bit BIT_USING_GENERIC_PC, a
	jr nz, PlayerPCMenu
; accessing it directly
;>     PlaySound(SFX_TURN_ON_PC)
	ld a, SFX_TURN_ON_PC
	call PlaySound
;>     PrintText(TurnedOnPC2Text)
	ld hl, TurnedOnPC2Text
	call PrintText
;> return PlayerPCMenu()

;@ def PlayerPCMenu()
;@ The item PC menu: WITHDRAW ITEM, DEPOSIT ITEM, TOSS ITEM or LOG OFF (or B).
;@ path: engine/menus/players_pc
PlayerPCMenu:
;> wCurrentMenuItem = wParentMenuItem
	ld a, [wParentMenuItem]
	ld [wCurrentMenuItem], a
;> wMiscFlags |= 1 << BIT_NO_MENU_BUTTON_SOUND
	ld hl, wMiscFlags
	set BIT_NO_MENU_BUTTON_SOUND, [hl]
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> TextBoxBorder(coord(0, 0), 8, 14)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, $8
	ld c, $e
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> PlaceString(PlayersPCMenuEntries, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, PlayersPCMenuEntries
	call PlaceString
;> wTopMenuItemY = 2
	ld hl, wTopMenuItemY
	ld a, 2
	ld [hli], a ; wTopMenuItemY
;> wTopMenuItemX = 1
	dec a
	ld [hli], a ; wTopMenuItemX
;> wMaxMenuItem = 3
	inc hl
	inc hl
	ld a, 3
	ld [hli], a ; wMaxMenuItem
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [hli], a ; wMenuWatchedKeys
;> wLastMenuItem = 0
	xor a
	ld [hl], a
;> wListScrollOffset = 0
	ld hl, wListScrollOffset
	ld [hli], a ; wListScrollOffset
;> wMenuWatchMovingOutOfBounds = 0
	ld [hl], a ; wMenuWatchMovingOutOfBounds
;> wPlayerMonNumber = 0
	ld [wPlayerMonNumber], a
;> PrintText(WhatDoYouWantText)
	ld hl, WhatDoYouWantText
	call PrintText
;> keys = HandleMenuInput()
	call HandleMenuInput
;> if keys & PAD_B:
;>     return ExitPlayerPC()
	bit B_PAD_B, a
	jp nz, ExitPlayerPC
;> PlaceUnfilledArrowMenuCursor(keys)
	call PlaceUnfilledArrowMenuCursor
;> wParentMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wParentMenuItem], a
;> if wCurrentMenuItem == 0:
;>     return PlayerPCWithdraw()
	and a
	jp z, PlayerPCWithdraw
;> if wCurrentMenuItem == 1:
;>     return PlayerPCDeposit()
	dec a
	jp z, PlayerPCDeposit
;> if wCurrentMenuItem == 2:
;>     return PlayerPCToss()
	dec a
	jp z, PlayerPCToss
;> return ExitPlayerPC()

;@ def ExitPlayerPC()
;@ Leave the item PC (with the switch-off sound when it was the bedroom PC) and restore the screen.
;@ path: engine/menus/players_pc
ExitPlayerPC:
;> if not wMiscFlags >> BIT_USING_GENERIC_PC & 1:
	ld a, [wMiscFlags]
	bit BIT_USING_GENERIC_PC, a
	jr nz, .next
; accessing it directly
;>     PlaySound(SFX_TURN_OFF_PC)
	ld a, SFX_TURN_OFF_PC
	call PlaySound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
.next
;> wMiscFlags &= ~(1 << BIT_NO_MENU_BUTTON_SOUND) & 0xFF
	ld hl, wMiscFlags
	res BIT_NO_MENU_BUTTON_SOUND, [hl]
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> wListScrollOffset = 0
	xor a
	ld [wListScrollOffset], a
;> wBagSavedMenuItem = 0
	ld [wBagSavedMenuItem], a
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> wDoNotWaitForButtonPressAfterDisplayingText = 0
	xor a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ret

;@ def PlayerPCDeposit()
;@ DEPOSIT ITEM: pick items from the bag (and how many, except key items) and move them into the PC box, until B.
;@ path: engine/menus/players_pc
PlayerPCDeposit:
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wListScrollOffset = 0
	ld [wListScrollOffset], a
;> if not mem[addr(wNumBagItems)]:
	ld a, [wNumBagItems]
	and a
	jr nz, .loop
;>     PrintText(NothingToDepositText)
	ld hl, NothingToDepositText
	call PrintText
;>     return PlayerPCMenu()
	jp PlayerPCMenu
;> while True:
.loop
;>     PrintText(WhatToDepositText)
	ld hl, WhatToDepositText
	call PrintText
;>     mem16[addr(wListPointer)] = addr(wNumBagItems)
	ld hl, wNumBagItems
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;>     wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>     wListMenuID = ITEMLISTMENU
	ld a, ITEMLISTMENU
	ld [wListMenuID], a
;>     if DisplayListMenuID():                 # carry: B pressed
;>         return PlayerPCMenu()
	call DisplayListMenuID
	jp c, PlayerPCMenu
;>     IsKeyItem()
	call IsKeyItem
;>     wItemQuantity = 1
	ld a, 1
	ld [wItemQuantity], a
;>     if not wIsKeyItem:
	ld a, [wIsKeyItem]
	and a
	jr nz, .next
; if it's not a key item, there can be more than one of the item
;>         PrintText(DepositHowManyText)
	ld hl, DepositHowManyText
	call PrintText
;>         if DisplayChooseQuantityMenu() == 0xFF:
;>             continue
	call DisplayChooseQuantityMenu
	cp $ff
	jp z, .loop
.next
;>     if not AddItemToInventory(addr(wNumBoxItems)):
	ld hl, wNumBoxItems
	call AddItemToInventory
	jr c, .roomAvailable
;>         PrintText(NoRoomToStoreText)
	ld hl, NoRoomToStoreText
	call PrintText
;>         continue
	jp .loop
.roomAvailable
;>     RemoveItemFromInventory(addr(wNumBagItems))
	ld hl, wNumBagItems
	call RemoveItemFromInventory
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;>     PlaySound(SFX_WITHDRAW_DEPOSIT)
	ld a, SFX_WITHDRAW_DEPOSIT
	call PlaySound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;>     PrintText(ItemWasStoredText)
	ld hl, ItemWasStoredText
	call PrintText
	jp .loop

;@ def PlayerPCWithdraw()
;@ WITHDRAW ITEM: pick items from the PC box (and how many, except key items) and move them into the bag, until B.
;@ path: engine/menus/players_pc
PlayerPCWithdraw:
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wListScrollOffset = 0
	ld [wListScrollOffset], a
;> if not mem[addr(wNumBoxItems)]:
	ld a, [wNumBoxItems]
	and a
	jr nz, .loop
;>     PrintText(NothingStoredText)
	ld hl, NothingStoredText
	call PrintText
;>     return PlayerPCMenu()
	jp PlayerPCMenu
;> while True:
.loop
;>     PrintText(WhatToWithdrawText)
	ld hl, WhatToWithdrawText
	call PrintText
;>     mem16[addr(wListPointer)] = addr(wNumBoxItems)
	ld hl, wNumBoxItems
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;>     wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>     wListMenuID = ITEMLISTMENU
	ld a, ITEMLISTMENU
	ld [wListMenuID], a
;>     if DisplayListMenuID():                 # carry: B pressed
;>         return PlayerPCMenu()
	call DisplayListMenuID
	jp c, PlayerPCMenu
;>     IsKeyItem()
	call IsKeyItem
;>     wItemQuantity = 1
	ld a, 1
	ld [wItemQuantity], a
;>     if not wIsKeyItem:
	ld a, [wIsKeyItem]
	and a
	jr nz, .next
; if it's not a key item, there can be more than one of the item
;>         PrintText(WithdrawHowManyText)
	ld hl, WithdrawHowManyText
	call PrintText
;>         if DisplayChooseQuantityMenu() == 0xFF:
;>             continue
	call DisplayChooseQuantityMenu
	cp $ff
	jp z, .loop
.next
;>     if not AddItemToInventory(addr(wNumBagItems)):
	ld hl, wNumBagItems
	call AddItemToInventory
	jr c, .roomAvailable
;>         PrintText(CantCarryMoreText)
	ld hl, CantCarryMoreText
	call PrintText
;>         continue
	jp .loop
.roomAvailable
;>     RemoveItemFromInventory(addr(wNumBoxItems))
	ld hl, wNumBoxItems
	call RemoveItemFromInventory
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;>     PlaySound(SFX_WITHDRAW_DEPOSIT)
	ld a, SFX_WITHDRAW_DEPOSIT
	call PlaySound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;>     PrintText(WithdrewItemText)
	ld hl, WithdrewItemText
	call PrintText
	jp .loop

;@ def PlayerPCToss()
;@ TOSS ITEM: throw away items stored in the PC box (how many, except for key items and HMs), until B.
;@ path: engine/menus/players_pc
PlayerPCToss:
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wListScrollOffset = 0
	ld [wListScrollOffset], a
;> if not mem[addr(wNumBoxItems)]:
	ld a, [wNumBoxItems]
	and a
	jr nz, .loop
;>     PrintText(NothingStoredText)
	ld hl, NothingStoredText
	call PrintText
;>     return PlayerPCMenu()
	jp PlayerPCMenu
;> while True:
.loop
;>     PrintText(WhatToTossText)
	ld hl, WhatToTossText
	call PrintText
;>     mem16[addr(wListPointer)] = addr(wNumBoxItems)
	ld hl, wNumBoxItems
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;>     wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>     wListMenuID = ITEMLISTMENU
	ld a, ITEMLISTMENU
	ld [wListMenuID], a
;>     if DisplayListMenuID():                 # carry: B pressed
;>         return PlayerPCMenu()
	push hl
	call DisplayListMenuID
	pop hl
	jp c, PlayerPCMenu
;>     IsKeyItem()
	push hl
	call IsKeyItem
	pop hl
;>     wItemQuantity = 1
	ld a, 1
	ld [wItemQuantity], a
;>     if not wIsKeyItem and not IsItemHM(wCurItem):
	ld a, [wIsKeyItem]
	and a
	jr nz, .next
	ld a, [wCurItem]
	call IsItemHM
	jr c, .next
; if it's not a key item, there can be more than one of the item
;>         PrintText(TossHowManyText)
	push hl
	ld hl, TossHowManyText
	call PrintText
;>         if DisplayChooseQuantityMenu() == 0xFF:
;>             continue
	call DisplayChooseQuantityMenu
	pop hl
	cp $ff
	jp z, .loop
.next
;>     TossItem(addr(wNumBoxItems))            # it refuses key items itself
	call TossItem ; disallows tossing key items
	jp .loop

