;@ path: engine/pokemon/remove_mon
;@ def _RemovePokemon()
;@ Remove Pokémon wWhichPokemon from the party (or the current box if wRemoveMonFromBox): its species, data,
;@ original trainer name and nickname, moving everything after it up one place.
_RemovePokemon::
;> box = wRemoveMonFromBox
;> lst = addr(wBoxCount) if box else addr(wPartyCount)
	ld hl, wPartyCount
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .gotCount
	ld hl, wBoxCount
.gotCount
;> mem[lst] = u8(mem[lst] - 1)
	ld a, [hl]
	dec a
	ld [hli], a

;> i = lst + 1 + wWhichPokemon
	ld a, [wWhichPokemon]
	ld c, a
	ld b, 0
	add hl, bc
;> while True:                                   # the species list moves up, with its $FF end
	ld e, l
	ld d, h
	inc de
.shiftMonSpeciesLoop
;>     species = mem[i + 1]
	ld a, [de]
	inc de
;>     mem[i] = species
;>     i += 1
	ld [hli], a
;>     if species == 0xFF:
;>         break
	inc a ; reached terminator?
	jr nz, .shiftMonSpeciesLoop ; if not, continue shifting species

;> ot = addr(wPartyMonOT)
	ld hl, wPartyMonOT
;> last = PARTY_LENGTH - 1
	ld d, PARTY_LENGTH - 1 ; max number of pokemon to shift
;> if box:
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .gotOTsPointer
;>     ot = addr(wBoxMonOT)
	ld hl, wBoxMonOT
;>     last = MONS_PER_BOX - 1
	ld d, MONS_PER_BOX - 1
.gotOTsPointer
;> ot += wWhichPokemon * NAME_LENGTH
	ld a, [wWhichPokemon]
	call SkipFixedLengthTextEntries
;> if wWhichPokemon == last:
	ld a, [wWhichPokemon]
	cp d ; are we removing the last pokemon?
	jr nz, .notRemovingLastMon ; if not, shift the pokemon below

	; bug: to erase a string, this should be ld [hl], '@'
	; This is not needed, as wBoxSpecies/wPartySpecies determine if a slot is used.
	; Besides, existing mon nick is left untouched
;>     mem[ot] = 0xFF                            # meant as '@'; nothing reads it anyway
;>     return
	ld [hl], $ff
	ret

.notRemovingLastMon
;> src = ot + NAME_LENGTH
	ld d, h
	ld e, l
	ld bc, NAME_LENGTH
	add hl, bc
;> end = addr(wBoxMonNicks) if box else addr(wPartyMonNicks)
	ld bc, wPartyMonNicks
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .gotNicksPointer
	ld bc, wBoxMonNicks
.gotNicksPointer
;> CopyDataUntil(src, ot, end)                   # the later OT names move up
	call CopyDataUntil

;> mon = addr(wPartyMons)
	ld hl, wPartyMons
;> size = PARTYMON_STRUCT_LENGTH
	ld bc, PARTYMON_STRUCT_LENGTH
;> if box:
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .gotMonStructs
;>     mon = addr(wBoxMons)
	ld hl, wBoxMons
;>     size = BOXMON_STRUCT_LENGTH
	ld bc, BOXMON_STRUCT_LENGTH
.gotMonStructs
;> mon += wWhichPokemon * size
	ld a, [wWhichPokemon]
	call AddNTimes ; get address of the pokemon removed

;> if box:
	ld d, h ; de = start address for CopyDataUntil
	ld e, l
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .copyUntilPartyMonOT
; copy until wBoxMonOT
;>     src, end = mon + BOXMON_STRUCT_LENGTH, addr(wBoxMonOT)
	ld bc, BOXMON_STRUCT_LENGTH
	add hl, bc ; get address of next slot
	ld bc, wBoxMonOT
	jr .shiftOTs
.copyUntilPartyMonOT
;> else:
;>     src, end = mon + PARTYMON_STRUCT_LENGTH, addr(wPartyMonOT)
	ld bc, PARTYMON_STRUCT_LENGTH
	add hl, bc ; get address of next slot
	ld bc, wPartyMonOT
.shiftOTs
;> CopyDataUntil(src, mon, end)                  # the later Pokémon move up
	call CopyDataUntil ; shift all pokemon data up one slot

;> nick = addr(wBoxMonNicks) if box else addr(wPartyMonNicks)
	ld hl, wPartyMonNicks
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .gotNicksPointer2
	ld hl, wBoxMonNicks
.gotNicksPointer2
;> nick += wWhichPokemon * NAME_LENGTH
	ld bc, NAME_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes

;> src = nick + NAME_LENGTH
	ld d, h
	ld e, l
	ld bc, NAME_LENGTH
	add hl, bc
;> end = addr(wBoxMonNicksEnd) if box else addr(wPartyMonNicksEnd)
	ld bc, wPartyMonNicksEnd
	ld a, [wRemoveMonFromBox]
	and a
	jr z, .shiftMonNicks
	ld bc, wBoxMonNicksEnd
.shiftMonNicks
;> CopyDataUntil(src, nick, end)                 # and the later nicknames
	jp CopyDataUntil ; shift all pokemon nicknames up one slot
;@ path: engine/events/display_pokedex
;@ def _DisplayPokedex()
;@ Show the Pokédex entry of wPokedexNum outside the Pokédex (e.g. from Bill's PC), then restore the map and
;@ mark the Pokémon as seen.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
_DisplayPokedex::
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> ShowPokedexData()                            # a predef
	ld a, (ShowPokedexDataPredef - PredefPointers) / 3
	call Predef
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> ReloadMapData()
	call ReloadMapData
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> IndexToPokedex()                             # a predef
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> index = u8(wPokedexNum - 1)
	ld a, [wPokedexNum]
	dec a
	ld c, a
;> FlagAction(addr(wPokedexSeen), index, FLAG_SET)   # seen; through FlagActionPredef
	ld b, FLAG_SET
	ld hl, wPokedexSeen
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ret


SECTION "bank3", ROMX

;@ path: engine/joypad
;@ def _Joypad()
;@ Turn the raw buttons in hJoyInput into hJoyHeld, hJoyPressed (new this frame) and hJoyReleased, minus the
;@ buttons wJoyIgnore masks out. A + B + Select + Start together asks for a soft reset.
;@ test: hJoyInput = rand(0, 254); hJoyInput = hJoyInput + (hJoyInput >= PAD_BUTTONS)
_Joypad::
; hJoyReleased: (hJoyLast ^ hJoyInput) & hJoyLast
; hJoyPressed:  (hJoyLast ^ hJoyInput) & hJoyInput

;> held = hJoyInput
	ldh a, [hJoyInput]
;> if held == PAD_BUTTONS:                       # A + B + Select + Start
;>     return TrySoftReset()
	cp PAD_BUTTONS ; soft reset
	jp z, TrySoftReset

;> changed = hJoyLast ^ held
	ld b, a
	ldh a, [hJoyLast]
	ld e, a
	xor b
	ld d, a
;> hJoyReleased = changed & hJoyLast
	and e
	ldh [hJoyReleased], a
;> hJoyPressed = changed & held
	ld a, d
	and b
	ldh [hJoyPressed], a
;> hJoyLast = held
	ld a, b
	ldh [hJoyLast], a

;> if wStatusFlags5 >> BIT_DISABLE_JOYPAD & 1:
;>     return DiscardButtonPresses()
	ld a, [wStatusFlags5]
	bit BIT_DISABLE_JOYPAD, a
	jr nz, DiscardButtonPresses

;> hJoyHeld = held
	ldh a, [hJoyLast]
	ldh [hJoyHeld], a

;> if wJoyIgnore:
	ld a, [wJoyIgnore]
	and a
	ret z

;>     keep = ~wJoyIgnore & 0xFF
	cpl
	ld b, a
;>     hJoyHeld = hJoyHeld & keep
	ldh a, [hJoyHeld]
	and b
	ldh [hJoyHeld], a
;>     hJoyPressed = hJoyPressed & keep
	ldh a, [hJoyPressed]
	and b
	ldh [hJoyPressed], a
	ret

;@ path: engine/joypad
;@ def DiscardButtonPresses()
;@ Forget this frame's buttons: nothing held, pressed or released (the joypad is disabled during scripted movement).
DiscardButtonPresses:
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hJoyPressed = 0
	ldh [hJoyPressed], a
;> hJoyReleased = 0
	ldh [hJoyReleased], a
	ret

;@ path: engine/joypad
;@ def TrySoftReset()
;@ All four of A, B, Select and Start are held: count hSoftReset down once per frame and reset the game when it
;@ reaches zero, otherwise read the joypad again.
TrySoftReset:
;> DelayFrame()
	call DelayFrame

	; deselect (redundant)
;> rJOYP = 0x30                                  # no button group selected (not needed)
	ld a, $30
	ldh [rJOYP], a

;> hSoftReset = u8(hSoftReset - 1)
	ld hl, hSoftReset
	dec [hl]
;> if hSoftReset == 0:
;>     return SoftReset()
	jp z, SoftReset

;> return Joypad()
	jp Joypad
