	db $11 ; UNUSED_MAP_F2
	db $11 ; UNUSED_MAP_F3
	db $11 ; UNUSED_MAP_F4
	db BANK(LoreleisRoom_h)
	db BANK(BrunosRoom_h)
	db BANK(AgathasRoom_h)
;@ path: engine/overworld/clear_variables
;@ def ClearVariablesOnEnterMap()
;@ Entering a map: hide the window, stop the automatic BG transfer, forget buttons and steps, and clear the
;@ per-map state from wWhichTrade up to wStandingOnWarpPadOrHole.
ClearVariablesOnEnterMap::
;> hWY = SCREEN_HEIGHT_PX
	ld a, SCREEN_HEIGHT_PX
	ldh [hWY], a
;> rWY = SCREEN_HEIGHT_PX
	ldh [rWY], a
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> wStepCounter = 0
	ld [wStepCounter], a
;> wLoneAttackNo = 0
	ld [wLoneAttackNo], a
;> hJoyPressed = 0
	ldh [hJoyPressed], a
;> hJoyReleased = 0
	ldh [hJoyReleased], a
;> hJoyHeld = 0
	ldh [hJoyHeld], a
;> wActionResultOrTookBattleTurn = 0
	ld [wActionResultOrTookBattleTurn], a
;> wUnusedMapVariable = 0
	ld [wUnusedMapVariable], a
;> wCardKeyDoorY = 0
	ld hl, wCardKeyDoorY
	ld [hli], a
;> wCardKeyDoorX = 0
	ld [hl], a
;> FillMemory(addr(wWhichTrade), addr(wStandingOnWarpPadOrHole) - addr(wWhichTrade), 0)
	ld hl, wWhichTrade
	ld bc, wStandingOnWarpPadOrHole - wWhichTrade
	call FillMemory
	ret
; only used for setting BIT_STANDING_ON_WARP of wMovementFlags upon entering a new map
;@ path: engine/overworld/player_state
;@ def IsPlayerStandingOnWarp()
;@ If the player stands on one of the map's warps, remember where it leads (wDestinationWarpID and the
;@ destination map) and set the standing-on-warp flag.
;@ test: wNumberOfWarps = rand(0, 32)
IsPlayerStandingOnWarp::
;>@warps for i in range(wNumberOfWarps):
	ld a, [wNumberOfWarps]
	and a
	ret z
	ld c, a
;>@warp     warp = wWarpEntries + 4 * i                  # y, x, destination warp, destination map
	ld hl, wWarpEntries
.loop
;>@here     if mem[warp] == wYCoord and mem[warp + 1] == wXCoord:
	ld a, [wYCoord]
	cp [hl]
	jr nz, .nextWarp1
	inc hl
;=@here
	ld a, [wXCoord]
	cp [hl]
	jr nz, .nextWarp2
	inc hl
;>         wDestinationWarpID = mem[warp + 2]
	ld a, [hli] ; target warp
	ld [wDestinationWarpID], a
;>         hWarpDestinationMap = mem[warp + 3]
	ld a, [hl] ; target map
	ldh [hWarpDestinationMap], a
;>         wMovementFlags |= 1 << BIT_STANDING_ON_WARP
	ld hl, wMovementFlags
	set BIT_STANDING_ON_WARP, [hl]
;>         return
	ret
.nextWarp1
;=@warp
	inc hl
.nextWarp2
	inc hl
	inc hl
	inc hl
;=@warps
	dec c
	jr nz, .loop
	ret

;@ path: engine/overworld/player_state
;@ def CheckForceBikeOrSurf()
;@ On the spots listed in ForcedBikeOrSurfMaps (map, y, x) the player is put on the bike - Cycling Road - or,
;@ in the two lowest floors of the Seafoam Islands, made to surf (where the boulders move the current).
CheckForceBikeOrSurf::
;> if wStatusFlags6 >> BIT_ALWAYS_ON_BIKE & 1:
;>     return
	ld hl, wStatusFlags6
	bit BIT_ALWAYS_ON_BIKE, [hl]
	ret nz
;> spot = ForcedBikeOrSurfMaps
	ld hl, ForcedBikeOrSurfMaps
;> y, x, here = wYCoord, wXCoord, wCurMap
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
	ld a, [wCurMap]
	ld d, a
.loop
;> while mem[spot] != 0xFF:
	ld a, [hli]
	cp $ff
	ret z ; if we reach FF then it's not part of the list
;>@spot     if mem[spot] == here and mem[spot + 1] == y and mem[spot + 2] == x:
	cp d ; compare to current map
	jr nz, .incorrectMap
	ld a, [hli]
	cp b ; compare y-coord
	jr nz, .incorrectY
;=@spot
	ld a, [hli]
	cp c ; compare x-coord
	jr nz, .loop ; incorrect x-coord, check next item
;>         wSeafoamIslandsB3FCurScript = SCRIPT_SEAFOAMISLANDSB3F_MOVE_OBJECT
	ld a, [wCurMap]
	cp SEAFOAM_ISLANDS_B3F
	ld a, SCRIPT_SEAFOAMISLANDSB3F_MOVE_OBJECT
	ld [wSeafoamIslandsB3FCurScript], a
;>         if wCurMap != SEAFOAM_ISLANDS_B3F:
	jr z, .forceSurfing
;>             wSeafoamIslandsB4FCurScript = SCRIPT_SEAFOAMISLANDSB4F_MOVE_OBJECT
	ld a, [wCurMap]
	cp SEAFOAM_ISLANDS_B4F
	ld a, SCRIPT_SEAFOAMISLANDSB4F_MOVE_OBJECT
	ld [wSeafoamIslandsB4FCurScript], a
;>         if wCurMap in (SEAFOAM_ISLANDS_B3F, SEAFOAM_ISLANDS_B4F):   # the current there: surf
;>@surf             state = 2
;>         else:
	jr z, .forceSurfing
;>             wStatusFlags6 |= 1 << BIT_ALWAYS_ON_BIKE                # Cycling Road: the bike
	ld hl, wStatusFlags6
	set BIT_ALWAYS_ON_BIKE, [hl]
;>             state = 1
	ld a, $1
;>@state         wWalkBikeSurfState = state
	ld [wWalkBikeSurfState], a
;>@copy         wWalkBikeSurfStateCopy = state
	ld [wWalkBikeSurfStateCopy], a
;>@force         return ForceBikeOrSurf()
	jp ForceBikeOrSurf
.incorrectMap
;>     spot += 3
	inc hl
.incorrectY
	inc hl
	jr .loop
.forceSurfing
;=@surf
	ld a, $2
;=@state
	ld [wWalkBikeSurfState], a
;=@copy
	ld [wWalkBikeSurfStateCopy], a
;=@force
	jp ForceBikeOrSurf


;@ path: engine/overworld/player_state
ForcedBikeOrSurfMaps:
	; map id, x, y
	db ROUTE_16, 10, 17
	db ROUTE_16, 11, 17
	db ROUTE_18, 8, 33
	db ROUTE_18, 9, 33
	db SEAFOAM_ISLANDS_B3F, 7, 18
	db SEAFOAM_ISLANDS_B3F, 7, 19
	db SEAFOAM_ISLANDS_B4F, 14, 4
	db SEAFOAM_ISLANDS_B4F, 14, 5
	db -1 ; end

;@ path: engine/overworld/player_state
;@ def IsPlayerFacingEdgeOfMap() -> carry
;@ Whether the player looks out over the edge of the map: the next step would leave it.
;@ test: mem[0xC109] = 4 * rand(0, 3)
IsPlayerFacingEdgeOfMap::
;> facing = wSpritePlayerStateData1FacingDirection
	push hl
	push de
	push bc
	ld a, [wSpritePlayerStateData1FacingDirection]
;>@yx y, x = wYCoord, wXCoord
;>@pick if facing == SPRITE_FACING_DOWN:             # one check per direction, from .functionPointerTable
;=@pick
	srl a
	ld c, a
	ld b, $0
	ld hl, .functionPointerTable
	add hl, bc
;=@pick
	ld a, [hli]
	ld h, [hl]
	ld l, a
;=@yx
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
;=@pick
	ld de, .return
	push de
	jp hl
.return
;=@edge
	pop bc
	pop de
	pop hl
	ret

.functionPointerTable
	dw .facingDown
	dw .facingUp
	dw .facingLeft
	dw .facingRight

.facingDown
;>     edge = wYCoord == u8(wCurMapHeight * 2 - 1)     # the map size is in blocks of two steps
	ld a, [wCurMapHeight]
	add a
	dec a
	cp b
	jr z, .setCarry
	jr .resetCarry

.facingUp
;> elif facing == SPRITE_FACING_UP:
;>     edge = wYCoord == 0
	ld a, b
	and a
	jr z, .setCarry
	jr .resetCarry

.facingLeft
;> elif facing == SPRITE_FACING_LEFT:
;>     edge = wXCoord == 0
	ld a, c
	and a
	jr z, .setCarry
	jr .resetCarry

.facingRight
;> else:
;>     edge = wXCoord == u8(wCurMapWidth * 2 - 1)
	ld a, [wCurMapWidth]
	add a
	dec a
	cp c
	jr z, .setCarry
	jr .resetCarry
.resetCarry
;>@edge return edge
	and a
	ret
.setCarry
	scf
	ret

;@ path: engine/overworld/player_state
;@ def IsWarpTileInFrontOfPlayer() -> carry
;@ Whether the tile the player faces is a warp tile for that direction (the lists in WarpTileListPointers);
;@ on the S.S. Anne's bow only tile $15 counts.
;@ test: mem[0xC109] = 4 * rand(0, 3)
IsWarpTileInFrontOfPlayer::
;> _GetTileAndCoordsInFrontOfPlayer()
	push hl
	push de
	push bc
	call _GetTileAndCoordsInFrontOfPlayer
;> if wCurMap == SS_ANNE_BOW:
;>     return IsSSAnneBowWarpTileInFrontOfPlayer()
	ld a, [wCurMap]
	cp SS_ANNE_BOW
	jr z, IsSSAnneBowWarpTileInFrontOfPlayer
;> index = wSpritePlayerStateData1FacingDirection >> 1    # a list per direction
	ld a, [wSpritePlayerStateData1FacingDirection]
	srl a
	ld c, a
	ld b, 0
;> tiles = mem16[WarpTileListPointers + index]
	ld hl, WarpTileListPointers
	add hl, bc
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> _, _, found = IsInArray(wTileInFrontOfPlayer, tiles, 1)
	ld a, [wTileInFrontOfPlayer]
	ld de, $1
	call IsInArray
.done
;> return found
	pop bc
	pop de
	pop hl
	ret

;@ path: engine/overworld/player_state
WarpTileListPointers:
	dw .FacingDownWarpTiles
	dw .FacingUpWarpTiles
	dw .FacingLeftWarpTiles
	dw .FacingRightWarpTiles


.FacingDownWarpTiles:
	db $01,$12,$17,$3D,$04,$18,$33
	db -1

.FacingUpWarpTiles:
	db $01,$5C
	db -1

.FacingLeftWarpTiles:
	db $1A,$4B
	db -1

.FacingRightWarpTiles:
	db $0F,$4E
	db -1

;@ path: engine/overworld/player_state
;@ def IsSSAnneBowWarpTileInFrontOfPlayer() -> carry
;@ The S.S. Anne's bow has one warp tile: $15.
;@ test: skip jumps back into IsWarpTileInFrontOfPlayer, which saved registers on the stack for it
IsSSAnneBowWarpTileInFrontOfPlayer:
;> if wTileInFrontOfPlayer == 0x15: return True     # (through IsWarpTileInFrontOfPlayer.done)
	ld a, [wTileInFrontOfPlayer]
	cp $15
	jr nz, .notSSAnne5Warp
	scf
	jr IsWarpTileInFrontOfPlayer.done
.notSSAnne5Warp
;> return False
	and a
	jr IsWarpTileInFrontOfPlayer.done

;@ path: engine/overworld/player_state
;@ def IsPlayerStandingOnDoorTileOrWarpTile()
;@ Stepping onto a door or warp tile of the current tileset clears the standing-on-warp flag again.
;@ test: hLoadedROMBank = 3
IsPlayerStandingOnDoorTileOrWarpTile::
;>@door if IsPlayerStandingOnDoorTile():                 # in another bank
;>     return
;=@done
	push hl
	push de
	push bc
;=@door
	ld b, BANK(IsPlayerStandingOnDoorTile)
	ld hl, IsPlayerStandingOnDoorTile
	call Bankswitch
	jr c, .done
;> index = u8(2 * wCurMapTileset)                  # a list per tileset
	ld a, [wCurMapTileset]
	add a
	ld c, a
	ld b, $0
;> tiles = mem16[WarpTileIDPointers + index]
	ld hl, WarpTileIDPointers
	add hl, bc
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> _, _, found = IsInArray(mem[coord(8, 9)], tiles, 1)     # the tile under the player
	ld de, $1
	ld a, [(9) * SCREEN_WIDTH + (8) + wTileMap]
	call IsInArray
;> if found:
	jr nc, .done
;>     wMovementFlags &= ~(1 << BIT_STANDING_ON_WARP)
	ld hl, wMovementFlags
	res BIT_STANDING_ON_WARP, [hl]
.done
;>@done return
	pop bc
	pop de
	pop hl
	ret

