;@ path: engine/overworld/player_state
;@ def PrintSafariZoneSteps()
;@ In the Safari Zone: the box in the top left corner with the steps left and the Safari Balls left.
PrintSafariZoneSteps::
;> if not SAFARI_ZONE_EAST <= wCurMap < CERULEAN_CAVE_2F:
;>     return
	ld a, [wCurMap]
	cp SAFARI_ZONE_EAST
	ret c
	cp CERULEAN_CAVE_2F
	ret nc
;> TextBoxBorder(coord(0, 0), 3, 7)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 3
	ld c, 7
	call TextBoxBorder
;> PrintNumber(coord(1, 1), wSafariSteps, 2, 3)       # 2 bytes, 3 digits
	ld hl, (1) * SCREEN_WIDTH + (1) + wTileMap
	ld de, wSafariSteps
	ld bc, ((2) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> PlaceString(coord(4, 1), SafariSteps)
	ld hl, (1) * SCREEN_WIDTH + (4) + wTileMap
	ld de, SafariSteps
	call PlaceString
;> PlaceString(coord(1, 3), SafariBallText)
	ld hl, (3) * SCREEN_WIDTH + (1) + wTileMap
	ld de, SafariBallText
	call PlaceString
;> if wNumSafariBalls < 10:
;>     mem[coord(5, 3)] = 0x7F                      # blank out a leftover tens digit
	ld a, [wNumSafariBalls]
	cp 10
	jr nc, .tenOrMore
	ld hl, (3) * SCREEN_WIDTH + (5) + wTileMap
	ld a, ' '
	ld [hl], a
.tenOrMore
;> PrintNumber(coord(6, 3), wNumSafariBalls, 1, 2)
	ld hl, (3) * SCREEN_WIDTH + (6) + wTileMap
	ld de, wNumSafariBalls
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	jp PrintNumber

;@ path: engine/overworld/player_state
SafariSteps:
	db "/500@"

;@ path: engine/overworld/player_state
SafariBallText:
	db "BALL×× @"

;@ path: engine/overworld/player_state
;@ def GetTileAndCoordsInFrontOfPlayer() -> (c, d, e)
;@ The predef version of _GetTileAndCoordsInFrontOfPlayer: takes its registers from the predef call first.
GetTileAndCoordsInFrontOfPlayer:
;> GetPredefRegisters()
;> return _GetTileAndCoordsInFrontOfPlayer()
	call GetPredefRegisters

;@ path: engine/overworld/player_state
;@ def _GetTileAndCoordsInFrontOfPlayer() -> (c, d, e)
;@ The tile the player faces on screen (also in wTileInFrontOfPlayer) and the map coordinates (y, x) of that spot.
;@ test: mem[0xC109] = 4 * rand(0, 3)
_GetTileAndCoordsInFrontOfPlayer:
;> y, x = wYCoord, wXCoord
	ld a, [wYCoord]
	ld d, a
	ld a, [wXCoord]
	ld e, a
;> facing = wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
;> if facing == SPRITE_FACING_DOWN:
	and a ; cp SPRITE_FACING_DOWN
	jr nz, .notFacingDown
; facing down
;>     tile, y = mem[coord(8, 11)], y + 1           # the player stands at tiles (8, 9)
	ld a, [(11) * SCREEN_WIDTH + (8) + wTileMap]
	inc d
	jr .storeTile
.notFacingDown
;> elif facing == SPRITE_FACING_UP:
	cp SPRITE_FACING_UP
	jr nz, .notFacingUp
; facing up
;>     tile, y = mem[coord(8, 7)], y - 1
	ld a, [(7) * SCREEN_WIDTH + (8) + wTileMap]
	dec d
	jr .storeTile
.notFacingUp
;> elif facing == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr nz, .notFacingLeft
; facing left
;>     tile, x = mem[coord(6, 9)], x - 1
	ld a, [(9) * SCREEN_WIDTH + (6) + wTileMap]
	dec e
	jr .storeTile
.notFacingLeft
;> elif facing == SPRITE_FACING_RIGHT:
	cp SPRITE_FACING_RIGHT
;>@right     tile, x = mem[coord(10, 9)], x + 1
;> else:
;>     tile = facing                                # not a direction: nothing is looked up
	jr nz, .storeTile
; facing right
;=@right
	ld a, [(9) * SCREEN_WIDTH + (10) + wTileMap]
	inc e
.storeTile
;> wTileInFrontOfPlayer = tile
	ld c, a
	ld [wTileInFrontOfPlayer], a
;> return (tile, u8(y), u8(x))
	ret

; hPlayerFacing
	; 0
DEF BIT_FACING_DOWN EQU 0
	; 1
DEF BIT_FACING_UP EQU 1
	; 2
DEF BIT_FACING_LEFT EQU 2
	; 3
DEF BIT_FACING_RIGHT EQU 3

;@ path: engine/overworld/player_state
;@ def GetTileTwoStepsInFrontOfPlayer() -> (c, d, e)
;@ Like _GetTileAndCoordsInFrontOfPlayer, two steps ahead (where a pushed boulder would go): the tile, and the
;@ coordinates one step ahead. The facing direction is kept as a bit in hPlayerFacing.
;@ test: mem[0xC109] = 4 * rand(0, 3)
GetTileTwoStepsInFrontOfPlayer:
;> hPlayerFacing = 0
	xor a
	ldh [hPlayerFacing], a
;> y, x = wYCoord, wXCoord
	ld hl, wYCoord
	ld a, [hli]
	ld d, a
	ld e, [hl]
;> facing = wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
;> if facing == SPRITE_FACING_DOWN:
	and a ; cp SPRITE_FACING_DOWN
	jr nz, .notFacingDown
; facing down
;>     hPlayerFacing = 1 << BIT_FACING_DOWN
	ld hl, hPlayerFacing
	set BIT_FACING_DOWN, [hl]
;>     tile, y = mem[coord(8, 13)], y + 1
	ld a, [(13) * SCREEN_WIDTH + (8) + wTileMap]
	inc d
	jr .storeTile
.notFacingDown
;> elif facing == SPRITE_FACING_UP:
	cp SPRITE_FACING_UP
	jr nz, .notFacingUp
; facing up
;>     hPlayerFacing = 1 << BIT_FACING_UP
	ld hl, hPlayerFacing
	set BIT_FACING_UP, [hl]
;>     tile, y = mem[coord(8, 5)], y - 1
	ld a, [(5) * SCREEN_WIDTH + (8) + wTileMap]
	dec d
	jr .storeTile
.notFacingUp
;> elif facing == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr nz, .notFacingLeft
; facing left
;>     hPlayerFacing = 1 << BIT_FACING_LEFT
	ld hl, hPlayerFacing
	set BIT_FACING_LEFT, [hl]
;>     tile, x = mem[coord(4, 9)], x - 1
	ld a, [(9) * SCREEN_WIDTH + (4) + wTileMap]
	dec e
	jr .storeTile
.notFacingLeft
;> elif facing == SPRITE_FACING_RIGHT:
	cp SPRITE_FACING_RIGHT
;>@rfacing     hPlayerFacing = 1 << BIT_FACING_RIGHT
;>@rtile     tile, x = mem[coord(12, 9)], x + 1
;> else:
;>     tile = facing                                # not a direction: nothing is looked up
	jr nz, .storeTile
; facing right
;=@rfacing
	ld hl, hPlayerFacing
	set BIT_FACING_RIGHT, [hl]
;=@rtile
	ld a, [(9) * SCREEN_WIDTH + (12) + wTileMap]
	inc e
.storeTile
;> wTileInFrontOfBoulderAndBoulderCollisionResult = tile
	ld c, a
	ld [wTileInFrontOfBoulderAndBoulderCollisionResult], a
;> wTileInFrontOfPlayer = tile
	ld [wTileInFrontOfPlayer], a
;> return (tile, u8(y), u8(x))
	ret

;@ path: engine/overworld/player_state
;@ def CheckForCollisionWhenPushingBoulder()
;@ Can the boulder in front of the player move? The answer goes to
;@ wTileInFrontOfBoulderAndBoulderCollisionResult: $FF if it is blocked - the tile behind it is not walkable,
;@ is a ledge or height step, is stairs, or a sprite stands there - otherwise 0.
CheckForCollisionWhenPushingBoulder:
;> tile = GetTileTwoStepsInFrontOfPlayer()[0]
	call GetTileTwoStepsInFrontOfPlayer
;> walkable = wTilesetCollisionPtr[0] | wTilesetCollisionPtr[1] << 8
	ld hl, wTilesetCollisionPtr
	ld a, [hli]
	ld h, [hl]
	ld l, a
.loop
;>@scan while mem[walkable] != 0xFF and mem[walkable] != tile:
;>     walkable += 1
	ld a, [hli]
	cp $ff
;=@stop
	jr z, .done ; if the tile two steps ahead is not passable
;=@scan
	cp c
	jr nz, .loop
;>@stop if mem[walkable] == 0xFF:                        # not walkable
;>@stopresult     result = 0xFF                             # (a is $FF from the compare)
;> elif CheckForTilePairCollisions2(TilePairCollisionsLand):
;>     result = 0xFF                                # a height difference
	ld hl, TilePairCollisionsLand
	call CheckForTilePairCollisions2
	ld a, $ff
	jr c, .done ; if there is an elevation difference between the current tile and the one two steps ahead
;> elif wTileInFrontOfBoulderAndBoulderCollisionResult == 0x15:
;>     result = 0xFF                                # stairs
	ld a, [wTileInFrontOfBoulderAndBoulderCollisionResult]
	cp $15 ; stairs tile
	ld a, $ff
	jr z, .done ; if the tile two steps ahead is stairs
;> else:
;>     result = CheckForBoulderCollisionWithSprites()
	call CheckForBoulderCollisionWithSprites
.done
;> wTileInFrontOfBoulderAndBoulderCollisionResult = result
	ld [wTileInFrontOfBoulderAndBoulderCollisionResult], a
	ret

; sets a to $ff if there is a collision and $00 if there is no collision
;@ path: engine/overworld/player_state
;@ def CheckForBoulderCollisionWithSprites() -> a
;@ $FF if a sprite stands on the spot the boulder (sprite wBoulderSpriteIndex) would be pushed to, else 0.
;@ Direction: hPlayerFacing from GetTileTwoStepsInFrontOfPlayer. The boulder's map position is left in
;@ hPlayerYCoord / hPlayerXCoord.
;@ test: wBoulderSpriteIndex = rand(1, 16); wNumSprites = rand(1, 15); hPlayerFacing = 1 << rand(0, 3)
CheckForBoulderCollisionWithSprites:
;> index = swap(u8(wBoulderSpriteIndex - 1))       # 16 bytes per sprite
	ld a, [wBoulderSpriteIndex]
	dec a
	swap a
	ld d, 0
	ld e, a
;> boulder = addr(wSprite01StateData2MapY) + index
	ld hl, wSprite01StateData2MapY
	add hl, de
;> hPlayerYCoord = mem[boulder]
	ld a, [hli] ; map Y position
	ldh [hPlayerYCoord], a
;> hPlayerXCoord = mem[boulder + 1]
	ld a, [hl] ; map X position
	ldh [hPlayerXCoord], a
;> sprite = addr(wSprite01StateData2MapY)                 # each sprite's map y, x
	ld a, [wNumSprites]
	ld c, a
	ld de, $f
	ld hl, wSprite01StateData2MapY
;> if hPlayerFacing & (1 << BIT_FACING_UP | 1 << BIT_FACING_DOWN):     # pushed up or down
	ldh a, [hPlayerFacing]
	and (1 << BIT_FACING_UP) | (1 << BIT_FACING_DOWN)
	jr z, .pushingHorizontallyLoop
.pushingVerticallyLoop
;>@loop1     for i in range(wNumSprites or 256):
;>         if mem[sprite + 1] == hPlayerXCoord:
	inc hl
	ldh a, [hPlayerXCoord]
	cp [hl]
	jr nz, .nextSprite1 ; if X coordinates don't match
;>             y = mem[sprite]
	dec hl
	ld a, [hli]
	ld b, a
;>             if hPlayerFacing & 1 << BIT_FACING_DOWN:
	ldh a, [hPlayerFacing]
	ASSERT BIT_FACING_DOWN == 0
	rrca
	jr c, .pushingDown
;>@down                 to_y = u8(hPlayerYCoord + 1)
;>             else:
; pushing up
;>                 to_y = u8(hPlayerYCoord - 1)
	ldh a, [hPlayerYCoord]
	dec a
	jr .compareYCoords
.pushingDown
;=@down
	ldh a, [hPlayerYCoord]
	inc a
.compareYCoords
;>             if y == to_y:                        # someone stands there
;>@fail1                 return 0xFF
	cp b
	jr z, .failure
.nextSprite1
;=@loop1
	dec c
	jr z, .success
;>         sprite += 16
	add hl, de
;=@loop1
	jr .pushingVerticallyLoop
.pushingHorizontallyLoop
;> else:                                            # pushed left or right
;>@loop2     for i in range(wNumSprites or 256):
;>         if mem[sprite] == hPlayerYCoord:
	ld a, [hli]
	ld b, a
	ldh a, [hPlayerYCoord]
	cp b
	jr nz, .nextSprite2
;>             x = mem[sprite + 1]
	ld b, [hl]
;>             if hPlayerFacing & 1 << BIT_FACING_LEFT:
	ldh a, [hPlayerFacing]
	bit BIT_FACING_LEFT, a
	jr nz, .pushingLeft
;>@left                 to_x = u8(hPlayerXCoord - 1)
;>             else:
; pushing right
;>                 to_x = u8(hPlayerXCoord + 1)
	ldh a, [hPlayerXCoord]
	inc a
	jr .compareXCoords
.pushingLeft
;=@left
	ldh a, [hPlayerXCoord]
	dec a
.compareXCoords
;>             if x == to_x:
;>@fail2                 return 0xFF
	cp b
	jr z, .failure
.nextSprite2
;=@loop2
	dec c
	jr z, .success
;>         sprite += 16
	add hl, de
;=@loop2
	jr .pushingHorizontallyLoop
.failure
;=@fail2
	ld a, $ff
	ret
.success
;> return 0
	xor a
	ret
;@ path: engine/events/poison
;@ def ApplyOutOfBattlePoisonDamage()
;@ Every fourth step outside scripted movement: each poisoned party Pokémon loses 1 HP (one that drops to 0
;@ faints, with a text, and loses its poison). The screen flashes with a sound if any is poisoned. When nobody
;@ can fight any more the player blacks out (wOutOfBattleBlackout $FF). The day care Pokémon gains experience
;@ on every step.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
ApplyOutOfBattlePoisonDamage:
;> blackout = False
;>@walk if not wStatusFlags5 & (1 << BIT_SCRIPTED_MOVEMENT_STATE) and wPartyCount:   # not in a scripted walk
	ld a, [wStatusFlags5]
	ASSERT BIT_SCRIPTED_MOVEMENT_STATE == 7
	add a ; overflows scripted movement state bit into carry flag
	jp c, .noBlackOut ; no black out if joypad states are being simulated
;=@walk
	ld a, [wPartyCount]
	and a
	jp z, .noBlackOut
;>     IncrementDayCareMonExp()
	call IncrementDayCareMonExp
;>     if wStepCounter & 3 == 0:
	ld a, [wStepCounter]
	and $3 ; is the counter a multiple of 4?
	jp nz, .noBlackOut ; only apply poison damage every fourth step
;>         wWhichPokemon = 0
	ld [wWhichPokemon], a
;>         status = addr(wPartyMon1Status)
	ld hl, wPartyMon1Status
;>         species = addr(wPartySpecies)
	ld de, wPartySpecies
;>         while True:
.applyDamageLoop
;>             if mem[status] & (1 << PSN):              # poisoned
	ld a, [hl]
	and 1 << PSN
	jr z, .nextMon2 ; not poisoned
;>                 hp = mem[status - 3] << 8 | mem[status - 2]
	dec hl
	dec hl
	ld a, [hld]
	ld b, a
	ld a, [hli]
;>                 if hp:                                # not fainted yet
	or b
	jr z, .nextMon ; already fainted
; subtract 1 from HP
;>                     hp -= 1
;>                     mem[status - 2] = hp & 0xFF
	ld a, [hl]
	dec a
	ld [hld], a
;>                     if hp & 0xFF == 0xFF:             # a borrow from the high byte
	inc a
	jr nz, .noBorrow
; borrow 1 from upper byte of HP
;>                         mem[status - 3] = hp >> 8
	dec [hl]
	inc hl
	jr .nextMon
.noBorrow
;>                     elif hp == 0:                     # fainted from the poison
	ld a, [hli]
	or [hl]
	jr nz, .nextMon ; didn't faint from damage
; the mon fainted from the damage
;>                         mem[status] = 0
	push hl
	inc hl
	inc hl
	ld [hl], a
;>                         wPokedexNum = mem[species]
	ld a, [de]
	ld [wPokedexNum], a
;>                         GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	push de
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;>                         wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
;>                         EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;>                         hTextID = TEXT_MON_FAINTED
	ld a, TEXT_MON_FAINTED
	ldh [hTextID], a
;>                         DisplayTextID()
	call DisplayTextID
	pop de
	pop hl
.nextMon
	inc hl
	inc hl
.nextMon2
;>             species += 1
	inc de
;>             if mem[species] == 0xFF:
;>                 break
	ld a, [de]
	inc a
	jr z, .applyDamageLoopDone
;>             status += PARTYMON_STRUCT_LENGTH
	ld bc, PARTYMON_STRUCT_LENGTH
	add hl, bc
;>             wWhichPokemon = u8(wWhichPokemon + 1)
	push hl
	ld hl, wWhichPokemon
	inc [hl]
	pop hl
	jr .applyDamageLoop
.applyDamageLoopDone
;>         poisoned = 0
;>@count         for i in range(wPartyCount):
	ld hl, wPartyMon1Status
	ld a, [wPartyCount]
	ld d, a
	ld e, 0
.countPoisonedLoop
;>             poisoned = poisoned | mem[addr(wPartyMon1Status) + i * PARTYMON_STRUCT_LENGTH] & (1 << PSN)
	ld a, [hl]
	and 1 << PSN
	or e
	ld e, a
;=@count
	ld bc, PARTYMON_STRUCT_LENGTH
	add hl, bc
	dec d
	jr nz, .countPoisonedLoop
;>         if poisoned:
	ld a, e
	and a ; are any party members poisoned?
	jr z, .skipPoisonEffectAndSound
;>             ChangeBGPalColor0_4Frames()          # a predef: white turns dark gray for 4 frames
	ld b, $2
	; change BG white to dark gray for 4 frames
	ld a, (ChangeBGPalColor0_4FramesPredef - PredefPointers) / 3
	call Predef
;>             PlaySound(SFX_POISONED)
	ld a, SFX_POISONED
	call PlaySound
.skipPoisonEffectAndSound
;>         _, alive = AnyPartyAlive()               # a predef
	ld a, (AnyPartyAlivePredef - PredefPointers) / 3
	call Predef
;>         if not alive:
	ld a, d
	and a
	jr nz, .noBlackOut
;>             EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;>             hTextID = TEXT_BLACKED_OUT
	ld a, TEXT_BLACKED_OUT
	ldh [hTextID], a
;>             DisplayTextID()
	call DisplayTextID
;>             wStatusFlags4 = wStatusFlags4 | 1 << BIT_BATTLE_OVER_OR_BLACKOUT
	ld hl, wStatusFlags4
	set BIT_BATTLE_OVER_OR_BLACKOUT, [hl]
;>             blackout = True
	ld a, $ff
	jr .done
.noBlackOut
	xor a
.done
;> wOutOfBattleBlackout = 0xFF if blackout else 0
	ld [wOutOfBattleBlackout], a
	ret
;@ path: engine/overworld/tilesets
;@ def LoadTilesetHeader()
;@ Copy the current tileset's 12-byte header (bank, block and tile pointers, collision list, counter tiles,
;@ grass tile, animation type). In a dungeon or on a tileset change, a warp's arrival position is loaded
;@ too, and the block coordinates follow the new step coordinates.
;@ test: hLoadedROMBank = 3; wCurMapTileset = rand(0, NUM_TILESETS - 1)
LoadTilesetHeader:
;> hl, _, _ = GetPredefRegisters()
	call GetPredefRegisters
	push hl
;> four = 4 * wCurMapTileset
	ld d, 0
	ld a, [wCurMapTileset]
	add a
	add a
	ld b, a
;> offset = 3 * four                            # 12 bytes per tileset
	add a
	add b ; a = tileset * 12
	jr nc, .noCarry
	inc d
.noCarry
	ld e, a
;> src = Tilesets + offset
	ld hl, Tilesets
	add hl, de
;>@copy for i in range(11):
	ld de, wTilesetBank
	ld c, $b
.copyTilesetHeaderLoop
;>     mem[addr(wTilesetBank) + i] = mem[src + i]
	ld a, [hli]
	ld [de], a
	inc de
;=@copy
	dec c
	jr nz, .copyTilesetHeaderLoop
;> hTileAnimations = mem[src + 11]
	ld a, [hl]
	ldh [hTileAnimations], a
;> hMovingBGTilesCounter1 = 0
	xor a
	ldh [hMovingBGTilesCounter1], a
	pop hl
;> _, _, dungeon = IsInArray(wCurMapTileset, DungeonTilesets, 1)
	ld a, [wCurMapTileset]
	push hl
	push de
	ld hl, DungeonTilesets
	ld de, $1
	call IsInArray
;>@new if dungeon or wCurMapTileset != hPreviousTileset:     # a dungeon, or a new tileset
	pop de
	pop hl
	jr c, .dungeon
;=@new
	ld a, [wCurMapTileset]
	ld b, a
	ldh a, [hPreviousTileset]
	cp b
	jr z, .done
.dungeon
;>     if wDestinationWarpID != 0xFF:
	ld a, [wDestinationWarpID]
	cp $ff
	jr z, .done
;>         LoadDestinationWarpPosition(wDestinationWarpID, hl)
	call LoadDestinationWarpPosition
;>         wYBlockCoord = wYCoord & 1
	ld a, [wYCoord]
	and $1
	ld [wYBlockCoord], a
;>         wXBlockCoord = wXCoord & 1
	ld a, [wXCoord]
	and $1
	ld [wXBlockCoord], a
.done
	ret

