;@ path: engine/overworld/daycare_exp
;@ def IncrementDayCareMonExp()
;@ One step with a Pokemon in the Day Care: one more experience point for it. The experience is a 3-byte
;@ big-endian number; when the count carries into the top byte it stops at $500000.
IncrementDayCareMonExp:
;> if not wDayCareInUse:
;>     return
	ld a, [wDayCareInUse]
	and a
	ret z
;> exp = wDayCareMonExp
;> mem[exp + 2] = u8(mem[exp + 2] + 1)
	ld hl, wDayCareMonExp + 2
	inc [hl]
;> if mem[exp + 2]:
;>     return
	ret nz
;> mem[exp + 1] = u8(mem[exp + 1] + 1)
	dec hl
	inc [hl]
;> if mem[exp + 1]:
;>     return
	ret nz
;> mem[exp] = u8(mem[exp] + 1)
	dec hl
	inc [hl]
;> if mem[exp] >= 0x50: mem[exp] = 0x50          # capped
	ld a, [hl]
	cp $50
	ret c
	ld a, $50
	ld [hl], a
	ret
