;@ Strength is used: switch it on for boulder pushing and say so.
PrintStrengthText:
;> wStatusFlags1 = wStatusFlags1 | 1 << BIT_STRENGTH_ACTIVE
	ld hl, wStatusFlags1
	set BIT_STRENGTH_ACTIVE, [hl]
;> PrintText(UsedStrengthText)
	ld hl, UsedStrengthText
	call PrintText
;> PrintText(CanMoveBouldersText)
	ld hl, CanMoveBouldersText
	jp PrintText

;@ path: engine/overworld/field_move_messages
;@ def UsedStrengthText() -> hl
;@ "<MON> used STRENGTH." followed by the Pokémon's cry.
;@ test: skip a text script: the code after text_asm is run by the text engine
UsedStrengthText:
	db TX_FAR
	dw _UsedStrengthText
	db BANK(_UsedStrengthText)
	db TX_START_ASM
;> PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry
;> Delay3()
	call Delay3
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/overworld/field_move_messages
CanMoveBouldersText:
	db TX_FAR
	dw _CanMoveBouldersText
	db BANK(_CanMoveBouldersText)
	db TX_END

;@ path: engine/overworld/field_move_messages
;@ def IsSurfingAllowed()
;@ May the player surf here? Not on the Cycling Road, and not near the stairs of Seafoam Islands B4F until
;@ both boulders have been pushed down to slow the current. The answer is BIT_SURF_ALLOWED of
;@ wStatusFlags1; a refusal is explained with a text.
IsSurfingAllowed:
; Returns whether surfing is allowed in BIT_SURF_ALLOWED of wStatusFlags1.
; Surfing isn't allowed on the Cycling Road or in the lowest level of the
; Seafoam Islands before the current has been slowed with boulders.
;> wStatusFlags1 = wStatusFlags1 | 1 << BIT_SURF_ALLOWED
	ld hl, wStatusFlags1
	set BIT_SURF_ALLOWED, [hl]
;> if wStatusFlags6 & (1 << BIT_ALWAYS_ON_BIKE):        # the Cycling Road
;>@bike     wStatusFlags1 = wStatusFlags1 & ~(1 << BIT_SURF_ALLOWED) & 0xFF
;>@biketext     PrintText(CyclingIsFunText)
;>@bikeret     return
	ld a, [wStatusFlags6]
	bit BIT_ALWAYS_ON_BIKE, a
	jr nz, .forcedToRideBike
;> if wCurMap != SEAFOAM_ISLANDS_B4F:
;>     return
	ld a, [wCurMap]
	cp SEAFOAM_ISLANDS_B4F
	ret nz
;> if event(EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) and event(EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE):
;>     return
	ld a, [wEventFlags + ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) / 8)]
	and (1 << ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8))
	cp (1 << ((EVENT_SEAFOAM4_BOULDER1_DOWN_HOLE) % 8)) | (1 << ((EVENT_SEAFOAM4_BOULDER2_DOWN_HOLE) % 8))
	ret z
;> if not ArePlayerCoordsInArray(SeafoamIslandsB4FStairsCoords):
;>     return
	ld hl, SeafoamIslandsB4FStairsCoords
	call ArePlayerCoordsInArray
	ret nc
;> wStatusFlags1 = wStatusFlags1 & ~(1 << BIT_SURF_ALLOWED) & 0xFF
	ld hl, wStatusFlags1
	res BIT_SURF_ALLOWED, [hl]
;> PrintText(CurrentTooFastText)
	ld hl, CurrentTooFastText
	jp PrintText
.forcedToRideBike
;=@bike
	ld hl, wStatusFlags1
	res BIT_SURF_ALLOWED, [hl]
;=@biketext
	ld hl, CyclingIsFunText
	jp PrintText

;@ path: engine/overworld/field_move_messages
SeafoamIslandsB4FStairsCoords:
	db 11, 7
	db -1 ; end

;@ path: engine/overworld/field_move_messages
CurrentTooFastText:
	db TX_FAR
	dw _CurrentTooFastText
	db BANK(_CurrentTooFastText)
	db TX_END

;@ path: engine/overworld/field_move_messages
CyclingIsFunText:
	db TX_FAR
	dw _CyclingIsFunText
	db BANK(_CyclingIsFunText)
	db TX_END
; function to add an item (in varying quantities) to the player's bag or PC box
; INPUT:
; hl = address of inventory (either wNumBagItems or wNumBoxItems)
; [wCurItem] = item ID
; [wItemQuantity] = item quantity
; sets carry flag if successful, unsets carry flag if unsuccessful
;@ def AddItemToInventory_(inventory: hl) -> carry
;@ Add wItemQuantity of item wCurItem to the bag or the PC's item box (`inventory` points at its count). A slot holds
;@ at most 99: the rest goes into a new slot. Carry if it all fitted; no carry if there was no free slot.
;@ test: inventory = [wBagItems - 1, wBoxItems - 1][rand(0, 1)]; n = rand(0, 20); mem[inventory] = n
;@ test: [mem.__setitem__(inventory + 1 + i, [rand(1, 8), rand(1, 99)][i % 2]) for i in range(2 * n)]; mem[inventory + 1 + 2 * n] = 0xFF
;@ test: wCurItem = rand(1, 8); wItemQuantity = rand(1, 99)
;@ path: engine/items/inventory
AddItemToInventory_::
;> quantity = wItemQuantity
	ld a, [wItemQuantity] ; a = item quantity
	push af
;> # (bc, de and the inventory pointer are kept)
	push bc
	push de
	push hl
	push hl
;> capacity = PC_ITEM_CAPACITY
	ld d, PC_ITEM_CAPACITY ; how many items the PC can hold
;> if inventory == addr(wNumBagItems):
	ld a, LOW(wNumBagItems)
	cp l
	jr nz, .checkIfInventoryFull
	ld a, HIGH(wNumBagItems)
	cp h
	jr nz, .checkIfInventoryFull
; if the destination is the bag
;>     capacity = BAG_ITEM_CAPACITY
	ld d, BAG_ITEM_CAPACITY ; how many items the bag can hold
.checkIfInventoryFull
;> room = mem[inventory] != capacity                 # room for another slot
	ld a, [hl]
	sub d
	ld d, a
;> count = mem[inventory]
;> p = inventory + 1
	ld a, [hli]
;>@an added = None
;> if count:
	and a
	jr z, .addNewItem
;>@wl     while True:
.notAtEndOfInventory
;>         item = mem[p]
;>         p += 1
	ld a, [hli]
	ld b, a ; b = ID of current item in table
;>         if item == wCurItem:
;>@t1             total = (mem[p] + wItemQuantity) & 0xFF
;>@t2             if total < 100:
;>@t3                 mem[p] = total
;>@t4                 added = True
;>@t5                 break
;>@t6             wItemQuantity = total - 99            # the rest goes into a new slot
;>@t7             if not room:
;>@t8                 added = False
;>@t9                 break
;>@t10             mem[p] = 99
;>@t11             p += 1
;>@t12             continue
	ld a, [wCurItem] ; a = ID of item being added
	cp b ; does the current item in the table match the item being added?
	jp z, .increaseItemQuantity ; if so, increase the item's quantity
;>         p += 1
	inc hl
;>         if mem[p] == 0xFF:
;>             break
	ld a, [hl]
	cp $ff ; is it the end of the table?
	jr nz, .notAtEndOfInventory
.addNewItem ; add an item not yet in the inventory
;> if added is None:
;>     if room:
	pop hl
	ld a, d
	and a ; is there room for a new item slot?
	jr z, .done
; if there is room
;>         mem[inventory] += 1
	inc [hl] ; increment the number of items in the inventory
;>         slot = inventory + ((2 * mem[inventory] - 1) & 0xFF)
	ld a, [hl] ; the number of items will be the index of the new item
	add a
	dec a
	ld c, a
	ld b, 0
	add hl, bc ; hl = address to store the item
;>         mem[slot] = wCurItem
	ld a, [wCurItem]
	ld [hli], a ; store item ID
;>         mem[slot + 1] = wItemQuantity
	ld a, [wItemQuantity]
	ld [hli], a ; store item quantity
;>         mem[slot + 2] = 0xFF
	ld [hl], $ff ; store terminator
;>     added = room
	jp .success
.increaseItemQuantity ; increase the quantity of an item already in the inventory
;=@t1
	ld a, [wItemQuantity]
	ld b, a ; b = quantity to add
	ld a, [hl] ; a = existing item quantity
	add b ; a = new item quantity
;=@t2
	cp 100
	jp c, .storeNewQuantity ; if the new quantity is less than 100, store it
; if the new quantity is greater than or equal to 100,
; try to max out the current slot and add the rest in a new slot
;=@t6
	sub 99
	ld [wItemQuantity], a ; a = amount left over (to put in the new slot)
;=@t7
	ld a, d
	and a ; is there room for a new item slot?
	jr z, .increaseItemQuantityFailed
; if so, store 99 in the current slot and store the rest in a new slot
;=@t10
	ld a, 99
	ld [hli], a
;=@t12
	jp .notAtEndOfInventory
.increaseItemQuantityFailed
;=@t8
	pop hl
	and a
;=@t9
	jr .done
.storeNewQuantity
;=@t3
	ld [hl], a
;=@t4
	pop hl
.success
	scf
.done
;> # (the kept registers come back; b holds the first quantity)
	pop hl
	pop de
	pop bc
	pop bc
;> wItemQuantity = quantity
	ld a, b
	ld [wItemQuantity], a ; restore the initial value from when the function was called
;> return added
	ret

; function to remove an item (in varying quantities) from the player's bag or PC box
; INPUT:
; hl = address of inventory (either wNumBagItems or wNumBoxItems)
; [wWhichPokemon] = index (within the inventory) of the item to remove
; [wItemQuantity] = quantity to remove
;@ def RemoveItemFromInventory_(inventory: hl)
;@ Take wItemQuantity of the item in slot wWhichPokemon out of the bag or the PC box. An emptied slot is removed,
;@ the slots below move up and the list menu goes back to the top.
;@ test: inventory = [wBagItems - 1, wBoxItems - 1][rand(0, 1)]; n = rand(1, 20); mem[inventory] = n
;@ test: [mem.__setitem__(inventory + 1 + i, [rand(1, 80), rand(1, 99)][i % 2]) for i in range(2 * n)]; mem[inventory + 1 + 2 * n] = 0xFF
;@ test: w = rand(0, n - 1); wWhichPokemon = w; wItemQuantity = [rand(1, 99), mem[inventory + 2 + 2 * w]][rand(0, 1)]
;@ path: engine/items/inventory
RemoveItemFromInventory_::
;> # (inventory is kept)
	push hl
;> q = inventory + 1
	inc hl
;> q += (2 * wWhichPokemon) & 0xFF            # the slot's item
	ld a, [wWhichPokemon] ; index (within the inventory) of the item being removed
	sla a
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
;> q += 1                                     # its quantity
	inc hl
;> left = (mem[q] - wItemQuantity) & 0xFF
	ld a, [wItemQuantity] ; quantity being removed
	ld e, a
	ld a, [hl] ; a = current quantity
	sub e
;> mem[q] = left
	ld [hld], a ; store new quantity
;> wMaxItemQuantity = left
	ld [wMaxItemQuantity], a
;> if left == 0:
	and a
	jr nz, .skipMovingUpSlots
; if the remaining quantity is 0,
; remove the emptied item slot and move up all the following item slots
;>     dest = q - 1                            # the emptied slot
;>     src = q + 1                             # the slots below move up
	ld e, l
	ld d, h
	inc de
	inc de ; de = address of the slot following the emptied one
.loop ; loop to move up the following slots
;>@lp     while True:
;>         b = mem[src]
	ld a, [de]
;>         src += 1
	inc de
;>         mem[dest] = b
;>         dest += 1
	ld [hli], a
;>         if b == 0xFF:
;>             break
	cp $ff
	jr nz, .loop
; update menu info
;>     wListScrollOffset = 0
	xor a
	ld [wListScrollOffset], a
;>     wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;>     wBagSavedMenuItem = 0
	ld [wBagSavedMenuItem], a
;>     wSavedListScrollOffset = 0
	ld [wSavedListScrollOffset], a
;>     n = (mem[inventory] - 1) & 0xFF
	pop hl
	ld a, [hl] ; a = number of items in inventory
	dec a ; decrement the number of items
;>     mem[inventory] = n
	ld [hl], a ; store new number of items
;>     wListCount = n
	ld [wListCount], a
;>     if n >= 2:
	cp 2
	jr c, .done
;>         wMaxMenuItem = n
	ld [wMaxMenuItem], a
	jr .done
.skipMovingUpSlots
;> else:
;>     pass                                    # (the kept pointer is dropped)
	pop hl
.done
;> return
	ret
;@ path: engine/overworld/wild_mons
;@ def LoadWildData()
;@ Load the current map's wild Pokémon: encounter rate and 10 (level, species) pairs for grass, then the
;@ same for water. A rate of 0 means none and has no list after it.
;@ test: wCurMap = rand(0, NUM_MAPS - 1)
LoadWildData::
;> entry = WildDataPointers + 2 * wCurMap
	ld hl, WildDataPointers
	ld a, [wCurMap]

	; get wild data for current map
	ld c, a
	ld b, 0
	add hl, bc
	add hl, bc
;> p = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a       ; hl now points to wild data for current map
;> wGrassRate = mem[p]
;> p += 1
	ld a, [hli]
	ld [wGrassRate], a
;> if wGrassRate:
	and a
	jr z, .NoGrassData ; if no grass data, skip to surfing data
;>     CopyData(p, addr(wGrassMons), WILDDATA_LENGTH - 1)
	push hl
	ld de, wGrassMons ; otherwise, load grass data
	ld bc, WILDDATA_LENGTH - 1
	call CopyData
	pop hl
;>     p += WILDDATA_LENGTH - 1
	ld bc, WILDDATA_LENGTH - 1
	add hl, bc
.NoGrassData
;> wWaterRate = mem[p]
;> p += 1
	ld a, [hli]
	ld [wWaterRate], a
;> if wWaterRate:
	and a
	ret z        ; if no water data, we're done
;>     CopyData(p, addr(wWaterMons), WILDDATA_LENGTH - 1)
	ld de, wWaterMons  ; otherwise, load surfing data
	ld bc, WILDDATA_LENGTH - 1
	jp CopyData

