; wild pokemon data is divided into two parts.
; first part:  pokemon found in grass
; second part: pokemon found while surfing
; each part goes as follows:
    ; if first byte == 0, then
        ; no wild pokemon on this map
    ; if first byte != 0, then
        ; first byte is encounter rate
        ; followed by 20 bytes:
        ; level, species (ten times)

;@ path: engine/overworld/wild_mons
NothingWildMons:
	; encounter rate
._def_grass_wildmons_0:
	db 0

	; encounter rate
._def_water_wildmons_0:
	db 0
;@ path: engine/overworld/wild_mons
Route1WildMons:
	; encounter rate
._def_grass_wildmons_25:
	db 25
	db  3, PIDGEY
	db  3, RATTATA
	db  3, RATTATA
	db  2, RATTATA
	db  2, PIDGEY
	db  3, PIDGEY
	db  3, PIDGEY
	db  4, RATTATA
	db  4, PIDGEY
	db  5, PIDGEY

	; encounter rate
._def_water_wildmons_0:
	db 0
;@ path: engine/overworld/wild_mons
Route2WildMons:
	; encounter rate
._def_grass_wildmons_25:
	db 25
	db  3, RATTATA
	db  3, PIDGEY
	db  4, PIDGEY
	db  4, RATTATA
	db  5, PIDGEY
	db  3, WEEDLE
	db  2, RATTATA
	db  5, RATTATA
	db  4, WEEDLE
	db  5, WEEDLE

	; encounter rate
._def_water_wildmons_0:
	db 0
;@ path: engine/overworld/wild_mons
Route22WildMons:
	; encounter rate
._def_grass_wildmons_25:
	db 25
	db  3, RATTATA
	db  3, NIDORAN_M
	db  4, RATTATA
	db  4, NIDORAN_M
	db  2, RATTATA
	db  2, NIDORAN_M
	db  3, SPEAROW
	db  5, SPEAROW
	db  3, NIDORAN_F
	db  4, NIDORAN_F

	; encounter rate
._def_water_wildmons_0:
	db 0
;@ path: engine/overworld/wild_mons
ViridianForestWildMons:
	; encounter rate
._def_grass_wildmons_8:
	db 8
	db  4, WEEDLE
	db  5, KAKUNA
	db  3, WEEDLE
	db  5, WEEDLE
	db  4, KAKUNA
