;@ def UseItem_()
;@ Use item wCurItem: TMs and HMs go to the TM/HM handler, every other item to its entry in ItemUsePtrTable.
;@ wActionResultOrTookBattleTurn starts at 1 (used); a handler sets it to 0 when the item had no effect.
;@ test: wCurItem = [rand(1, 0x50), rand(0xC4, 0xFF)][rand(0, 1)]
;@ path: engine/items/item_effects
UseItem_::
;> wActionResultOrTookBattleTurn = 1           # used, unless the handler says otherwise
	ld a, 1
	ld [wActionResultOrTookBattleTurn], a ; initialise to success value
;> if wCurItem >= HM01:
;>     return ItemUseTMHM()
	ld a, [wCurItem]
	cp HM01
	jp nc, ItemUseTMHM
;> p = ItemUsePtrTable + 2 * (wCurItem - 1)
	ld hl, ItemUsePtrTable
	dec a
	add a
	ld c, a
	ld b, 0
	add hl, bc
;> handler = ItemUsePtrTable[wCurItem - 1]     # the entry at p
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> return handler()
	jp hl

;@ path: engine/items/item_effects
ItemUsePtrTable:
; entries correspond to item ids
	dw ItemUseBall       ; MASTER_BALL
	dw ItemUseBall       ; ULTRA_BALL
	dw ItemUseBall       ; GREAT_BALL
	dw ItemUseBall       ; POKE_BALL
	dw ItemUseTownMap    ; TOWN_MAP
	dw ItemUseBicycle    ; BICYCLE
	dw ItemUseSurfboard  ; SURFBOARD
	dw ItemUseBall       ; SAFARI_BALL
	dw ItemUsePokedex    ; POKEDEX
	dw ItemUseEvoStone   ; MOON_STONE
	dw ItemUseMedicine   ; ANTIDOTE
	dw ItemUseMedicine   ; BURN_HEAL
	dw ItemUseMedicine   ; ICE_HEAL
	dw ItemUseMedicine   ; AWAKENING
	dw ItemUseMedicine   ; PARLYZ_HEAL
	dw ItemUseMedicine   ; FULL_RESTORE
	dw ItemUseMedicine   ; MAX_POTION
	dw ItemUseMedicine   ; HYPER_POTION
	dw ItemUseMedicine   ; SUPER_POTION
	dw ItemUseMedicine   ; POTION
	dw ItemUseBait       ; BOULDERBADGE
	dw ItemUseRock       ; CASCADEBADGE
	dw UnusableItem      ; THUNDERBADGE
	dw UnusableItem      ; RAINBOWBADGE
	dw UnusableItem      ; SOULBADGE
	dw UnusableItem      ; MARSHBADGE
	dw UnusableItem      ; VOLCANOBADGE
	dw UnusableItem      ; EARTHBADGE
	dw ItemUseEscapeRope ; ESCAPE_ROPE
	dw ItemUseRepel      ; REPEL
	dw UnusableItem      ; OLD_AMBER
	dw ItemUseEvoStone   ; FIRE_STONE
	dw ItemUseEvoStone   ; THUNDER_STONE
	dw ItemUseEvoStone   ; WATER_STONE
	dw ItemUseVitamin    ; HP_UP
	dw ItemUseVitamin    ; PROTEIN
	dw ItemUseVitamin    ; IRON
	dw ItemUseVitamin    ; CARBOS
	dw ItemUseVitamin    ; CALCIUM
	dw ItemUseVitamin    ; RARE_CANDY
	dw UnusableItem      ; DOME_FOSSIL
	dw UnusableItem      ; HELIX_FOSSIL
	dw UnusableItem      ; SECRET_KEY
	dw UnusableItem      ; ITEM_2C
	dw UnusableItem      ; BIKE_VOUCHER
	dw ItemUseXAccuracy  ; X_ACCURACY
	dw ItemUseEvoStone   ; LEAF_STONE
	dw ItemUseCardKey    ; CARD_KEY
	dw UnusableItem      ; NUGGET
	dw UnusableItem      ; ITEM_32
	dw ItemUsePokeDoll   ; POKE_DOLL
	dw ItemUseMedicine   ; FULL_HEAL
	dw ItemUseMedicine   ; REVIVE
	dw ItemUseMedicine   ; MAX_REVIVE
	dw ItemUseGuardSpec  ; GUARD_SPEC
	dw ItemUseSuperRepel ; SUPER_REPEL
	dw ItemUseMaxRepel   ; MAX_REPEL
	dw ItemUseDireHit    ; DIRE_HIT
	dw UnusableItem      ; COIN
	dw ItemUseMedicine   ; FRESH_WATER
	dw ItemUseMedicine   ; SODA_POP
	dw ItemUseMedicine   ; LEMONADE
	dw UnusableItem      ; S_S_TICKET
	dw UnusableItem      ; GOLD_TEETH
	dw ItemUseXStat      ; X_ATTACK
	dw ItemUseXStat      ; X_DEFEND
	dw ItemUseXStat      ; X_SPEED
	dw ItemUseXStat      ; X_SPECIAL
	dw ItemUseCoinCase   ; COIN_CASE
	dw ItemUseOaksParcel ; OAKS_PARCEL
	dw ItemUseItemfinder ; ITEMFINDER
	dw UnusableItem      ; SILPH_SCOPE
	dw ItemUsePokeFlute  ; POKE_FLUTE
	dw UnusableItem      ; LIFT_KEY
	dw UnusableItem      ; EXP_ALL
	dw ItemUseOldRod     ; OLD_ROD
	dw ItemUseGoodRod    ; GOOD_ROD
	dw ItemUseSuperRod   ; SUPER_ROD
	dw ItemUsePPUp       ; PP_UP
	dw ItemUsePPRestore  ; ETHER
	dw ItemUsePPRestore  ; MAX_ETHER
	dw ItemUsePPRestore  ; ELIXER
	dw ItemUsePPRestore  ; MAX_ELIXER

;@ def ItemUseBall()
;@ Throw a Poké Ball at a wild Pokémon. The catch formula picks a random number in the ball's range, lowers it for
;@ a status ailment and compares it with the catch rate and the Pokémon's remaining HP; a miss still shows 0 to 3
;@ shakes. A caught Pokémon goes into the Pokédex and the party, or into the PC box when the party is full.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
ItemUseBall:

; Balls can't be used out of battle.
;> if not wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp z, ItemUseNotTime

; Balls can't catch trainers' Pokémon.
;> if wIsInBattle != 1:                        # a trainer's Pokémon
;>     return ThrowBallAtTrainerMon()
	dec a
	jp nz, ThrowBallAtTrainerMon

; If this is for the old man battle, skip checking if the party & box are full.
;> if wBattleType != BATTLE_TYPE_OLD_MAN:      # (the old man's demonstration skips this)
	ld a, [wBattleType]
	dec a
	jr z, .canUseBall

;>     if wPartyCount == PARTY_LENGTH:
	ld a, [wPartyCount] ; is party full?
	cp PARTY_LENGTH
	jr nz, .canUseBall
;>         if wBoxCount == MONS_PER_BOX:
;>             return BoxFullCannotThrowBall()
	ld a, [wBoxCount] ; is box full?
	cp MONS_PER_BOX
	jp z, BoxFullCannotThrowBall

.canUseBall
;> wCapturedMonSpecies = 0
	xor a
	ld [wCapturedMonSpecies], a

;> if wBattleType == BATTLE_TYPE_SAFARI:
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jr nz, .skipSafariZoneCode

.safariZone
;>     wNumSafariBalls -= 1
	ld hl, wNumSafariBalls
	dec [hl] ; remove a Safari Ball

.skipSafariZoneCode
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand

;> wPokeBallAnimData = 0x43                    # caught
	ld a, $43 ; successful capture value
	ld [wPokeBallAnimData], a

;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> PrintText(ItemUseText00)
	ld hl, ItemUseText00
	call PrintText

; If the player is fighting an unidentified ghost, set the value that indicates
; the Pokémon can't be caught and skip the capture calculations.
;> anim = None                                 # None: work it out; 'caught': keep $43
;> ghost = farcall(IsGhostBattle)              # an unidentified ghost can't be caught
	ld hl, IsGhostBattle
	ld b, BANK(IsGhostBattle)
	call Bankswitch
;> if ghost:
;>     anim = 0x10
	ld b, $10 ; can't be caught value
	jp z, .setAnimData

;> elif wBattleType == BATTLE_TYPE_OLD_MAN:     # the old man's catching demonstration
	ld a, [wBattleType]
	dec a
	jr nz, .notOldManBattle

; Old Man battle
;>     # wGrassRate goes back over wPlayerName: the player's name was kept in the wild Pokémon data during the
;>     # demonstration (the start of the Cinnabar Island Missingno. glitch)
;>     CopyData(addr(wGrassRate), addr(wPlayerName), NAME_LENGTH)
	ld hl, wGrassRate
	ld de, wPlayerName
	ld bc, NAME_LENGTH
	call CopyData ; save the player's name in the Wild Monster data (part of the Cinnabar Island Missingno. glitch)
;>     anim = 'caught'
	jp .captured

.notOldManBattle
; If the player is fighting the ghost Marowak, set the value that indicates the
; Pokémon can't be caught and skip the capture calculations.
;> elif wCurMap == POKEMON_TOWER_6F and wEnemyMonSpecies2 == RESTLESS_SOUL:   # the ghost Marowak
	ld a, [wCurMap]
	cp POKEMON_TOWER_6F
	jr nz, .loop
	ld a, [wEnemyMonSpecies2]
	cp RESTLESS_SOUL
;>     anim = 0x10
	ld b, $10 ; can't be caught value
	jp z, .setAnimData

; Get the first random number. Let it be called Rand1.
; Rand1 must be within a certain range according the kind of ball being thrown.
; The ranges are as follows.
; Poké Ball:         [0, 255]
; Great Ball:        [0, 200]
; Ultra/Safari Ball: [0, 150]
; Loop until an acceptable number is found.

.loop
;> else:
;>     while True:                             # Rand1, within 0-255 / 0-200 (Great) / 0-150 (Ultra, Safari)
;>         rand1 = Random(False)
	call Random
	ld b, a

; Get the item ID.
;>         ball = wCurItem
	ld hl, wCurItem
	ld a, [hl]

; The Master Ball always succeeds.
;>         if ball == MASTER_BALL:
;>@mb             anim = 'caught'
;>             break
	cp MASTER_BALL
	jp z, .captured

; Anything will do for the basic Poké Ball.
;>         if ball == POKE_BALL:
;>             break
	cp POKE_BALL
	jr z, .checkForAilments

; If it's a Great/Ultra/Safari Ball and Rand1 is greater than 200, try again.
;>         if rand1 > 200:
;>             continue
	ld a, 200
	cp b
	jr c, .loop

; Less than or equal to 200 is good enough for a Great Ball.
;>         if ball == GREAT_BALL:
;>             break
	ld a, [hl]
	cp GREAT_BALL
	jr z, .checkForAilments

; If it's an Ultra/Safari Ball and Rand1 is greater than 150, try again.
;>         if rand1 <= 150:
;>             break
	ld a, 150
	cp b
	jr c, .loop

.checkForAilments
; Pokémon can be caught more easily with a status ailment.
; Depending on the status ailment, a certain value will be subtracted from
; Rand1. Let this value be called Status.
; The larger Status is, the more easily the Pokémon can be caught.
; no status ailment:     Status = 0
; Burn/Paralysis/Poison: Status = 12
; Freeze/Sleep:          Status = 25
; If Status is greater than Rand1, the Pokémon will be caught for sure.
;>     status = wEnemyMonStatus
	ld a, [wEnemyMonStatus]
;>     if anim is None and status:             # an ailment makes it easier
	and a
	jr z, .skipAilmentValueSubtraction ; no ailments
;>         sub = 12                            # burned, paralysed, poisoned
;>         if status & ((1 << FRZ) | SLP_MASK):
	and (1 << FRZ) | SLP_MASK
	ld c, 12
	jr z, .notFrozenOrAsleep
;>             sub = 25                        # frozen, asleep
	ld c, 25
.notFrozenOrAsleep
;>@rs         rand1 -= sub
	ld a, b
	sub c
;>         if rand1 < 0:
;>@ac             anim = 'caught'
	jp c, .captured
;=@rs
	ld b, a

.skipAilmentValueSubtraction
;>     if anim is None:
;>         # (rand1 is kept)
	push bc ; save (Rand1 - Status)

; Calculate MaxHP * 255.
;>         # W = MaxHP * 255 / BallFactor (8 Great, else 12) / max(HP / 4, 1); X = min(W, 255)
;>         mem[addr(hMultiplicand)] = 0
	xor a
	ldh [hMultiplicand], a
;>         mem[addr(hMultiplicand) + 1] = mem[addr(wEnemyMonMaxHP)]
	ld hl, wEnemyMonMaxHP
	ld a, [hli]
	ldh [hMultiplicand + 1], a
;>         mem[addr(hMultiplicand) + 2] = mem[addr(wEnemyMonMaxHP) + 1]
	ld a, [hl]
	ldh [hMultiplicand + 2], a
;>         mem[addr(hMultiplier)] = 255
	ld a, 255
	ldh [hMultiplier], a
;>         Multiply()
	call Multiply

; Determine BallFactor. It's 8 for Great Balls and 12 for the others.
;>         great = wCurItem == GREAT_BALL
	ld a, [wCurItem]
	cp GREAT_BALL
;>         factor = 12                         # BallFactor
	ld a, 12
;>         if great:
;>             factor = 8
	jr nz, .skip1
	ld a, 8

.skip1
; Note that the results of all division operations are floored.

; Calculate (MaxHP * 255) / BallFactor.
;>         mem[addr(hDivisor)] = factor
	ldh [hDivisor], a
;>         Divide(4)
	ld b, 4 ; number of bytes in dividend
	call Divide

; Divide the enemy's current HP by 4. HP is not supposed to exceed 999 so
; the result should fit in a. If the division results in a quotient of 0,
; change it to 1.
;>         hp = mem[addr(wEnemyMonHP)] << 8 | mem[addr(wEnemyMonHP) + 1]
	ld hl, wEnemyMonHP
	ld a, [hli]
	ld b, a
	ld a, [hl]
;>         quarter = (hp >> 2) & 0xFF
	srl b
	rr a
	srl b
	rr a
;>         if quarter == 0:
;>             quarter = 1
	and a
	jr nz, .skip2
	inc a

.skip2
; Let W = ((MaxHP * 255) / BallFactor) / max(HP / 4, 1). Calculate W.
;>         mem[addr(hDivisor)] = quarter
	ldh [hDivisor], a
;>         Divide(4)                           # W
	ld b, 4
	call Divide

; If W > 255, store 255 in [hQuotient + 3].
; Let X = min(W, 255) = [hQuotient + 3].
;>         if mem[addr(hQuotient) + 2]:        # W > 255
	ldh a, [hQuotient + 2]
	and a
	jr z, .skip3
;>             mem[addr(hQuotient) + 3] = 255  # X = min(W, 255)
	ld a, 255
	ldh [hQuotient + 3], a

.skip3
;>         # (rand1 comes back)
	pop bc ; b = Rand1 - Status

; If Rand1 - Status > CatchRate, the ball fails to capture the Pokémon.
;>         if wEnemyMonActualCatchRate < rand1:
;>@f1             caught = False
	ld a, [wEnemyMonActualCatchRate]
	cp b
	jr c, .failedToCapture

; If W > 255, the ball captures the Pokémon.
;>         elif mem[addr(hQuotient) + 2]:
;>@c1             caught = True
	ldh a, [hQuotient + 2]
	and a
	jr nz, .captured

;>         else:
;>             rand2 = Random(False)
	call Random ; Let this random number be called Rand2.

; If Rand2 > X, the ball fails to capture the Pokémon.
;>             caught = rand2 <= mem[addr(hQuotient) + 3]
	ld b, a
	ldh a, [hQuotient + 3]
	cp b
	jr c, .failedToCapture

.captured
;>         if caught:
;>             anim = 'caught'
	jr .skipShakeCalculations

.failedToCapture
;>     if anim is None:                        # missed: how many shakes?
;>         mem[addr(wPokeBallCaptureCalcTemp)] = mem[addr(hQuotient) + 3]      # X
	ldh a, [hQuotient + 3]
	ld [wPokeBallCaptureCalcTemp], a ; Save X.

; Calculate CatchRate * 100.
;>         mem[addr(hMultiplicand)] = 0
;>         mem[addr(hMultiplicand) + 1] = 0
	xor a
	ldh [hMultiplicand], a
	ldh [hMultiplicand + 1], a
;>         mem[addr(hMultiplicand) + 2] = wEnemyMonActualCatchRate
	ld a, [wEnemyMonActualCatchRate]
	ldh [hMultiplicand + 2], a
;>         mem[addr(hMultiplier)] = 100
	ld a, 100
	ldh [hMultiplier], a
;>         Multiply()
	call Multiply

; Determine BallFactor2.
; Poké Ball:         BallFactor2 = 255
; Great Ball:        BallFactor2 = 200
; Ultra/Safari Ball: BallFactor2 = 150
;>         ball = wCurItem
	ld a, [wCurItem]
;>         factor2 = 255                       # BallFactor2
	ld b, 255
;>         if ball != POKE_BALL:
	cp POKE_BALL
	jr z, .skip4
;>             factor2 = 200
	ld b, 200
;>             if ball != GREAT_BALL:
	cp GREAT_BALL
	jr z, .skip4
;>                 factor2 = 150
	ld b, 150
;>                 if ball == ULTRA_BALL:      # (a Safari Ball gets 150 all the same)
;>                     pass
	cp ULTRA_BALL
	jr z, .skip4

.skip4
; Let Y = (CatchRate * 100) / BallFactor2. Calculate Y.
;>         mem[addr(hDivisor)] = factor2
	ld a, b
	ldh [hDivisor], a
;>         Divide(4)                           # Y = CatchRate * 100 / BallFactor2
	ld b, 4
	call Divide

; If Y > 255, there are 3 shakes.
; Note that this shouldn't be possible.
; The maximum value of Y is (255 * 100) / 150 = 170.
;>         if mem[addr(hQuotient) + 2]:        # Y > 255 (it cannot be)
;>             anim = 0x63
	ldh a, [hQuotient + 2]
	and a
	ld b, $63 ; 3 shakes
	jr nz, .setAnimData

; Calculate X * Y.
;>         else:
;>             mem[addr(hMultiplier)] = mem[addr(wPokeBallCaptureCalcTemp)]
	ld a, [wPokeBallCaptureCalcTemp]
	ldh [hMultiplier], a
;>             Multiply()                      # X * Y
	call Multiply

; Calculate (X * Y) / 255.
;>             mem[addr(hDivisor)] = 255
	ld a, 255
	ldh [hDivisor], a
;>             Divide(4)                       # Z = X * Y / 255, plus 10 (frozen, asleep) or 5 (other ailments)
	ld b, 4
	call Divide

; Determine Status2.
; no status ailment:     Status2 = 0
; Burn/Paralysis/Poison: Status2 = 5
; Freeze/Sleep:          Status2 = 10
;>             status = wEnemyMonStatus
;>             if status:
	ld a, [wEnemyMonStatus]
	and a
	jr z, .skip5
;>                 extra = 5
;>                 if status & ((1 << FRZ) | SLP_MASK):
	and (1 << FRZ) | SLP_MASK
	ld b, 5
	jr z, .addAilmentValue
;>                     extra = 10
	ld b, 10

.addAilmentValue
; If the Pokémon has a status ailment, add Status2.
;>                 mem[addr(hQuotient) + 3] = (mem[addr(hQuotient) + 3] + extra) & 0xFF
	ldh a, [hQuotient + 3]
	add b
	ldh [hQuotient + 3], a

.skip5
; Finally determine the number of shakes.
; Let Z = ((X * Y) / 255) + Status2 = [hQuotient + 3].
; The number of shakes depend on the range Z is in.
; 0  ≤ Z < 10: 0 shakes (the ball misses)
; 10 ≤ Z < 30: 1 shake
; 30 ≤ Z < 70: 2 shakes
; 70 ≤ Z:      3 shakes
;>             z = mem[addr(hQuotient) + 3]
	ldh a, [hQuotient + 3]
;>             if z < 10:
;>                 anim = 0x20                 # missed
	cp 10
	ld b, $20
	jr c, .setAnimData
;>             elif z < 30:
;>                 anim = 0x61                 # one shake
	cp 30
	ld b, $61
	jr c, .setAnimData
;>             elif z < 70:
;>                 anim = 0x62                 # two
	cp 70
	ld b, $62
	jr c, .setAnimData
;>             else:
;>                 anim = 0x63                 # three
	ld b, $63

.setAnimData
;> if anim != 'caught':
;>     wPokeBallAnimData = anim                # $10 can't be caught, $20 missed, $61-$63 one to three shakes
	ld a, b
	ld [wPokeBallAnimData], a

.skipShakeCalculations
;> DelayFrames(20)
	ld c, 20
	call DelayFrames

; Do the animation.
;> wAnimationID = TOSS_ANIM
	ld a, TOSS_ANIM
	ld [wAnimationID], a
;> hWhoseTurn = 0
	xor a
	ldh [hWhoseTurn], a
;> wAnimationType = 0
	ld [wAnimationType], a
;> wDamageMultipliers = 0
	ld [wDamageMultipliers], a
;> which = wWhichPokemon
	ld a, [wWhichPokemon]
	push af
;> item = wCurItem
	ld a, [wCurItem]
	push af
;> MoveAnimation()
	ld a, (MoveAnimationPredef - PredefPointers) / 3
	call Predef
;> wCurItem = item
	pop af
	ld [wCurItem], a
;> wWhichPokemon = which
	pop af
	ld [wWhichPokemon], a

; Determine the message to display from the animation.
;> shown = wPokeBallAnimData
	ld a, [wPokeBallAnimData]
;>@tn text = None
;> if shown == 0x10:                           # it can't be caught
;>     text = ItemUseBallText00
	cp $10
	ld hl, ItemUseBallText00
	jp z, .printMessage
;> elif shown == 0x20:                         # missed
;>     text = ItemUseBallText01
	cp $20
	ld hl, ItemUseBallText01
	jp z, .printMessage
;> elif shown == 0x61:                         # one shake
;>     text = ItemUseBallText02
	cp $61
	ld hl, ItemUseBallText02
	jp z, .printMessage
;> elif shown == 0x62:                         # two
;>     text = ItemUseBallText03
	cp $62
	ld hl, ItemUseBallText03
	jp z, .printMessage
;> elif shown == 0x63:                         # three
;>     text = ItemUseBallText04
	cp $63
	ld hl, ItemUseBallText04
	jp z, .printMessage

; Save current HP.
;> else:                                       # caught: reload its data as a fresh Pokémon, keeping its HP and status
;>     e = addr(wEnemyMonHP)
	ld hl, wEnemyMonHP
;>     hp_hi = mem[e]
	ld a, [hli]
	push af
;>     hp_lo = mem[e + 1]
	ld a, [hli]
	push af

; Save status ailment.
;>     ailment = mem[e + 3]
	inc hl
	ld a, [hl]
	push af

;>     # (e + 3 is kept)
	push hl

; Bug: If the Pokémon is transformed, the Pokémon is assumed to be a Ditto.
; This is a bug because a wild Pokémon could have used Transform via
; Mirror Move even though the only wild Pokémon that knows Transform is Ditto.
;>     if wEnemyBattleStatus3 & (1 << TRANSFORMED):
	ld hl, wEnemyBattleStatus3
	bit TRANSFORMED, [hl]
	jr z, .notTransformed
;>         wEnemyMonSpecies2 = DITTO           # bug: any transformed Pokémon is taken for a Ditto
	ld a, DITTO
	ld [wEnemyMonSpecies2], a
	jr .skip6

.notTransformed
; If the Pokémon is not transformed, set the transformed bit and copy the
; DVs to wTransformedEnemyMonOriginalDVs so that LoadEnemyMonData won't generate
; new DVs.
;>     else:
;>         wEnemyBattleStatus3 |= 1 << TRANSFORMED          # so LoadEnemyMonData keeps its DVs
	set TRANSFORMED, [hl]
;>         mem[addr(wTransformedEnemyMonOriginalDVs)] = mem[addr(wEnemyMonDVs)]
	ld hl, wTransformedEnemyMonOriginalDVs
	ld a, [wEnemyMonDVs]
	ld [hli], a
;>         mem[addr(wTransformedEnemyMonOriginalDVs) + 1] = mem[addr(wEnemyMonDVs) + 1]
	ld a, [wEnemyMonDVs + 1]
	ld [hl], a

.skip6
;>     species = wCurPartySpecies
	ld a, [wCurPartySpecies]
	push af
;>     wCurPartySpecies = wEnemyMonSpecies2
	ld a, [wEnemyMonSpecies2]
	ld [wCurPartySpecies], a
;>     wCurEnemyLevel = wEnemyMonLevel
	ld a, [wEnemyMonLevel]
	ld [wCurEnemyLevel], a
;>     farcall(LoadEnemyMonData)
	ld hl, LoadEnemyMonData
	ld b, BANK(LoadEnemyMonData)
	call Bankswitch
;>     wCurPartySpecies = species
	pop af
	ld [wCurPartySpecies], a
;>     # (e + 3 comes back)
	pop hl
;>     mem[e + 3] = ailment
	pop af
	ld [hld], a
;>     mem[e + 1] = hp_lo
	dec hl
	pop af
	ld [hld], a
;>     mem[e] = hp_hi
	pop af
	ld [hl], a
;>     wCapturedMonSpecies = wCurPartySpecies = wPokedexNum = wEnemyMonSpecies
	ld a, [wEnemyMonSpecies]
	ld [wCapturedMonSpecies], a
	ld [wCurPartySpecies], a
	ld [wPokedexNum], a
;>     if wBattleType == BATTLE_TYPE_OLD_MAN:  # the old man keeps it
;>@om         text = ItemUseBallText05
;>     else:
	ld a, [wBattleType]
	dec a ; is this the old man battle?
	jr z, .oldManCaughtMon ; if so, don't give the player the caught Pokémon

;>         PrintText(ItemUseBallText05)
	ld hl, ItemUseBallText05
	call PrintText

; Add the caught Pokémon to the Pokédex.
;>         IndexToPokedex()
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;>         bit = (wPokedexNum - 1) & 0xFF
	ld a, [wPokedexNum]
	dec a
	ld c, a
;>         owned = FlagAction(addr(wPokedexOwned), bit, FLAG_TEST)
	ld b, FLAG_TEST
	ld hl, wPokedexOwned
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
	ld a, c
;>         # (owned is kept)
	push af
;>         bit = (wPokedexNum - 1) & 0xFF
	ld a, [wPokedexNum]
	dec a
	ld c, a
;>         FlagAction(addr(wPokedexOwned), bit, FLAG_SET)
	ld b, FLAG_SET
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;>         # (owned comes back)
	pop af

;>         if not owned:                       # new: show its Pokédex entry
	and a ; was the Pokémon already in the Pokédex?
	jr nz, .skipShowingPokedexData ; if so, don't show the Pokédex data

;>             PrintText(ItemUseBallText06)
	ld hl, ItemUseBallText06
	call PrintText
;>             ClearSprites()
	call ClearSprites
;>             wPokedexNum = wEnemyMonSpecies
	ld a, [wEnemyMonSpecies]
	ld [wPokedexNum], a
;>             ShowPokedexData()
	ld a, (ShowPokedexDataPredef - PredefPointers) / 3
	call Predef

.skipShowingPokedexData
;>         if wPartyCount != PARTY_LENGTH:
	ld a, [wPartyCount]
	cp PARTY_LENGTH ; is party full?
	jr z, .sendToBox
;>             wMonDataLocation = PLAYER_PARTY_DATA
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;>             ClearSprites()
	call ClearSprites
;>             AddPartyMon()
	call AddPartyMon
	jr .done

.sendToBox
;>         else:
;>             ClearSprites()
	call ClearSprites
;>             SendNewMonToBox()
	call SendNewMonToBox
;>             where = ItemUseBallText07       # "BILL's PC"
	ld hl, ItemUseBallText07
;>             if not event(EVENT_MET_BILL):
	ld a, [wEventFlags + $AA]
	bit (EVENT_MET_BILL) % 8, a
	jr nz, .printTransferredToPCText
;>                 where = ItemUseBallText08   # "someone's PC"
	ld hl, ItemUseBallText08
.printTransferredToPCText
;>             PrintText(where)
	call PrintText
	jr .done

.oldManCaughtMon
;=@om
	ld hl, ItemUseBallText05

.printMessage
;> if text:
;>     PrintText(text)
	call PrintText
;>     ClearSprites()
	call ClearSprites

.done
;> if wBattleType:                             # the old man's and Safari Balls are not in the bag
;>     return
	ld a, [wBattleType]
	and a ; is this the old man battle?
	ret nz ; if so, don't remove a ball from the bag

; Remove a ball from the bag.
;> inventory = addr(wNumBagItems)
	ld hl, wNumBagItems
;> wItemQuantity = 1
	inc a
	ld [wItemQuantity], a
;> return RemoveItemFromInventory(inventory)
	jp RemoveItemFromInventory

