;@ def ItemUseTownMap()
;@ The Town Map: opens the map screen, but not in battle.
;@ path: engine/items/item_effects
ItemUseTownMap:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> return farcall(DisplayTownMap)
	ld b, BANK(DisplayTownMap)
	ld hl, DisplayTownMap
	jp Bankswitch

;@ def ItemUseBicycle()
;@ Get on or off the bicycle. Not in battle and not while surfing; getting on only where the map allows cycling.
;@ path: engine/items/item_effects
ItemUseBicycle:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> wWalkBikeSurfStateCopy = wWalkBikeSurfState
	ld a, [wWalkBikeSurfState]
	ld [wWalkBikeSurfStateCopy], a
;> if wWalkBikeSurfState == 2:                  # surfing
;>     return ItemUseNotTime()
	cp 2 ; is the player surfing?
	jp z, ItemUseNotTime
;> if wWalkBikeSurfState == 1:                  # already riding: get off
	dec a ; is player already bicycling?
	jr nz, .tryToGetOnBike
; get off bike
;>     ItemUseReloadOverworldData()
	call ItemUseReloadOverworldData
;>     wWalkBikeSurfState = 0
	xor a
	ld [wWalkBikeSurfState], a ; change player state to walking
;>     PlayDefaultMusic()
	call PlayDefaultMusic ; play walking music
;>     return PrintText(GotOffBicycleText)
	ld hl, GotOffBicycleText
	jr .printText
.tryToGetOnBike
;> if not IsBikeRidingAllowed():
;>     return NoCyclingAllowedHere()
	call IsBikeRidingAllowed
	jp nc, NoCyclingAllowedHere
;> ItemUseReloadOverworldData()
	call ItemUseReloadOverworldData
;> hJoyHeld = 0
	xor a ; no keys pressed
	ldh [hJoyHeld], a ; current joypad state
;> wWalkBikeSurfState = 1
	inc a
	ld [wWalkBikeSurfState], a ; change player state to bicycling
;> PlayDefaultMusic()                          # the cycling tune
;> return PrintText(GotOnBicycleText)
	ld hl, GotOnBicycleText
	call PlayDefaultMusic ; play bike riding music
.printText
	jp PrintText

; indirectly used by SURF in StartMenu_Pokemon.surf
;@ def ItemUseSurfboard()
;@ SURF: get onto the water in front of the player, or back onto land when already surfing. Either way the player
;@ takes one step forward, made by a simulated button press in the direction they face.
;@ path: engine/items/item_effects
ItemUseSurfboard:
;> wWalkBikeSurfStateCopy = wWalkBikeSurfState
	ld a, [wWalkBikeSurfState]
	ld [wWalkBikeSurfStateCopy], a
;> if wWalkBikeSurfState != 2:
	cp 2 ; is the player already surfing?
	jr z, .tryToStopSurfing
; try to Surf
;>     if IsNextTileShoreOrWater() or CheckForTilePairCollisions(TilePairCollisionsWater):
;>         return SurfingAttemptFailed()
	call IsNextTileShoreOrWater
	jp c, SurfingAttemptFailed
	ld hl, TilePairCollisionsWater
	call CheckForTilePairCollisions
	jp c, SurfingAttemptFailed
; surfing
;>     press = (PAD_UP if wPlayerDirection & (1 << PLAYER_DIR_BIT_UP) else
;>              PAD_DOWN if wPlayerDirection & (1 << PLAYER_DIR_BIT_DOWN) else
;>              PAD_LEFT if wPlayerDirection & (1 << PLAYER_DIR_BIT_LEFT) else PAD_RIGHT)   # one step forward
;>     mem[addr(wSimulatedJoypadStatesEnd)], mem[addr(wUnusedSimulatedJoypadStatesMask)], mem[addr(wSimulatedJoypadStatesIndex)] = press, 0, 1
	call .makePlayerMoveForward
;>     wStatusFlags5 |= 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;>     wWalkBikeSurfState = 2
	ld a, 2
	ld [wWalkBikeSurfState], a ; change player state to surfing
;>     PlayDefaultMusic()                      # the surfing tune
	call PlayDefaultMusic ; play surfing music
;>     return PrintText(SurfingGotOnText)
	ld hl, SurfingGotOnText
	jp PrintText
.tryToStopSurfing
;> hSpriteIndex = 0
	xor a
	ldh [hSpriteIndex], a
;> flags = IsSpriteInFrontOfPlayer2(16)       # someone standing on the shore, within talking range?
	ld d, 16 ; talking range in pixels (normal range)
	call IsSpriteInFrontOfPlayer2
;> mem[flags] &= ~(1 << BIT_FACE_PLAYER) & 0xFF
	res BIT_FACE_PLAYER, [hl]
;> if hSpriteIndex or CheckForTilePairCollisions(TilePairCollisionsWater):
;>     return PrintText(SurfingNoPlaceToGetOffText)
	ldh a, [hSpriteIndex]
	and a ; is there a sprite in the way?
	jr nz, .cannotStopSurfing
	ld hl, TilePairCollisionsWater
	call CheckForTilePairCollisions
	jr c, .cannotStopSurfing
;> p = mem16[addr(wTilesetCollisionPtr)]       # the tileset's list of walkable tiles
	ld hl, wTilesetCollisionPtr ; pointer to list of passable tiles
	ld a, [hli]
	ld h, [hl]
	ld l, a ; hl now points to passable tiles
;> tile = wTileInFrontOfPlayer
	ld a, [wTileInFrontOfPlayer] ; tile in front of the player
	ld b, a
;>@lp while True:
.passableTileLoop
;>     t = mem[p]
;>     p += 1
	ld a, [hli]
;>     if t == tile:
;>         break
	cp b
	jr z, .stopSurfing
;>     if t == 0xFF:
;>         return PrintText(SurfingNoPlaceToGetOffText)
	cp $ff
	jr nz, .passableTileLoop
.cannotStopSurfing
	ld hl, SurfingNoPlaceToGetOffText
	jp PrintText
.stopSurfing
;> press = (PAD_UP if wPlayerDirection & (1 << PLAYER_DIR_BIT_UP) else
;>          PAD_DOWN if wPlayerDirection & (1 << PLAYER_DIR_BIT_DOWN) else
;>          PAD_LEFT if wPlayerDirection & (1 << PLAYER_DIR_BIT_LEFT) else PAD_RIGHT)   # one step forward
;> mem[addr(wSimulatedJoypadStatesEnd)], mem[addr(wUnusedSimulatedJoypadStatesMask)], mem[addr(wSimulatedJoypadStatesIndex)] = press, 0, 1
	call .makePlayerMoveForward
;> wStatusFlags5 |= 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wWalkBikeSurfState = 0
	xor a
	ld [wWalkBikeSurfState], a ; change player state to walking
;> wJoyIgnore = 0xFF
	dec a
	ld [wJoyIgnore], a
;> PlayDefaultMusic()
	call PlayDefaultMusic ; play walking music
;> return LoadWalkingPlayerSpriteGraphics()
	jp LoadWalkingPlayerSpriteGraphics
; uses a simulated button press to make the player move forward
.makePlayerMoveForward
;> # .makePlayerMoveForward, called twice above:
;> #     d = wPlayerDirection
	ld a, [wPlayerDirection] ; direction the player is going
;> #     if d & (1 << PLAYER_DIR_BIT_UP): press = PAD_UP
	bit PLAYER_DIR_BIT_UP, a
	ld b, PAD_UP
	jr nz, .storeSimulatedButtonPress
;> #     elif d & (1 << PLAYER_DIR_BIT_DOWN): press = PAD_DOWN
	bit PLAYER_DIR_BIT_DOWN, a
	ld b, PAD_DOWN
	jr nz, .storeSimulatedButtonPress
;> #     elif d & (1 << PLAYER_DIR_BIT_LEFT): press = PAD_LEFT
	bit PLAYER_DIR_BIT_LEFT, a
	ld b, PAD_LEFT
	jr nz, .storeSimulatedButtonPress
;> #     else: press = PAD_RIGHT
	ld b, PAD_RIGHT
.storeSimulatedButtonPress
;> #     mem[addr(wSimulatedJoypadStatesEnd)] = press
	ld a, b
	ld [wSimulatedJoypadStatesEnd], a
;> #     wUnusedSimulatedJoypadStatesMask = 0
	xor a
	ld [wUnusedSimulatedJoypadStatesMask], a
;> #     wSimulatedJoypadStatesIndex = 1
	inc a
	ld [wSimulatedJoypadStatesIndex], a
;> #     return
	ret

;@ path: engine/items/item_effects
SurfingGotOnText:
	db TX_FAR
	dw _SurfingGotOnText
	db BANK(_SurfingGotOnText)
	db TX_END

;@ path: engine/items/item_effects
SurfingNoPlaceToGetOffText:
	db TX_FAR
	dw _SurfingNoPlaceToGetOffText
	db BANK(_SurfingNoPlaceToGetOffText)
	db TX_END

;@ def ItemUsePokedex()
;@ The Pokédex item opens the Pokédex menu.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
ItemUsePokedex:
;> return ShowPokedexMenu()
	ld a, (ShowPokedexMenuPredef - PredefPointers) / 3
	jp Predef

;@ def ItemUseEvoStone()
;@ An evolution stone: pick a Pokémon in the party menu and try to evolve it with the stone. The stone is used up
;@ only if the Pokémon evolved.
;@ path: engine/items/item_effects
ItemUseEvoStone:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> which = wWhichPokemon
	ld a, [wWhichPokemon]
	push af
;> stone = wCurItem
;> wEvoStoneItemID = stone
	ld a, [wCurItem]
	ld [wEvoStoneItemID], a
	push af
;> wPartyMenuTypeOrMessageID = EVO_STONE_PARTY_MENU
	ld a, EVO_STONE_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> cancelled = DisplayPartyMenu()             # (the stone comes back too)
	call DisplayPartyMenu
	pop bc
;> if not cancelled:
	jr c, .canceledItemUse
;>     wCurPartySpecies = stone
	ld a, b
	ld [wCurPartySpecies], a
;>     wForceEvolution = TRUE
	ld a, TRUE
	ld [wForceEvolution], a
;>     PlaySoundWaitForCurrent(SFX_HEAL_AILMENT)
	ld a, SFX_HEAL_AILMENT
	call PlaySoundWaitForCurrent
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
	; try to evolve pokemon
;>     farcall(TryEvolvingMon)
	ld hl, TryEvolvingMon
	ld b, BANK(TryEvolvingMon)
	call Bankswitch
;>     if not wEvolutionOccurred:
;>@ne         ItemUseNoEffect()
;>@nc         cancelled = True                    # the same ending as cancelling
	ld a, [wEvolutionOccurred]
	and a
	jr z, .noEffect
;>     else:
;>         wWhichPokemon = which
	pop af
	ld [wWhichPokemon], a
;>         inventory = addr(wNumBagItems)
	ld hl, wNumBagItems
;>         wItemQuantity = 1                   # one stone is used up
	ld a, 1 ; remove 1 stone
	ld [wItemQuantity], a
;>         return RemoveItemFromInventory(inventory)
	jp RemoveItemFromInventory
.noEffect
;=@ne
	call ItemUseNoEffect
.canceledItemUse
;> wActionResultOrTookBattleTurn = 0           # not used
	xor a
	ld [wActionResultOrTookBattleTurn], a ; item not used
;> return                                      # (`which` is dropped)
	pop af
	ret

;@ def ItemUseVitamin()
;@ HP Up, Protein and the other vitamins: not in battle; otherwise handled like medicine.
;@ path: engine/items/item_effects
ItemUseVitamin:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> return ItemUseMedicine()                    # it follows

;@ def ItemUseMedicine()
;@ Medicine used on a party Pokémon picked in the party menu: status cures, potions and drinks (Full Restore also
;@ cures), Revive (half HP) and Max Revive for fainted Pokémon, vitamins (stat experience up to 25600) and Rare
;@ Candy (one level, new moves, maybe evolution). SOFTBOILED comes here too: the user gives a fifth of its max HP
;@ to another Pokémon.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
ItemUseMedicine:
;> if not wPartyCount:
;>@ep1     wActionResultOrTookBattleTurn = 0
;>@ep2     return PrintText(label('ItemUseMedicine.emptyPartyText'))
	ld a, [wPartyCount]
	and a
	jp z, .emptyParty
;> which = wWhichPokemon
	ld a, [wWhichPokemon]
	push af
;> item = wCurItem
	ld a, [wCurItem]
	push af
;> wPartyMenuTypeOrMessageID = USE_ITEM_PARTY_MENU
	ld a, USE_ITEM_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> if wPseudoItemID:                           # SOFTBOILED: the menu is open already
	ld a, [wPseudoItemID]
	and a ; using Softboiled?
	jr z, .notUsingSoftboiled
; if using softboiled
;>     cancelled = GoBackToPartyMenu()
	call GoBackToPartyMenu
	jr .getPartyMonDataAddress
.emptyParty
;=@ep2
	ld hl, .emptyPartyText
;=@ep1
	xor a
	ld [wActionResultOrTookBattleTurn], a ; item use failed
;=@ep2
	jp PrintText
.emptyPartyText
	db TX_START, "You don't have"
	db "<LINE>", "any #MON!"
	db "<PROMPT>"
.notUsingSoftboiled
;> else:
;>     cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
.getPartyMonDataAddress
;> outcome = None                              # None: cancelled, 'none': no effect, 'healed'
;> if cancelled:
;>@cx     wActionResultOrTookBattleTurn = 0       # (which and item are dropped)
	jp c, .canceledItemUse
;> else:
;>     mon = AddNTimes(addr(wPartyMons), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld hl, wPartyMons
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;>     target = wUsedItemOnWhichPokemon = wWhichPokemon
	ld a, [wWhichPokemon]
	ld [wUsedItemOnWhichPokemon], a
	ld d, a
;>     species = wCurSpecies = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld e, a
	ld [wCurSpecies], a
;>     wCurItem = item
	pop af
	ld [wCurItem], a
;>     wWhichPokemon = which                   # for SOFTBOILED: the Pokémon using it
	pop af
	ld [wWhichPokemon], a
;>     if wPseudoItemID:
	ld a, [wPseudoItemID]
	and a ; using Softboiled?
	jr z, .checkItemType
; if using softboiled
;>         if wWhichPokemon == target:         # not on itself: choose again
;>             return ItemUseMedicine()
	ld a, [wWhichPokemon]
	cp d ; is the pokemon trying to use softboiled on itself?
	jr z, ItemUseMedicine ; if so, force another choice
.checkItemType
;>     it = wCurItem
	ld a, [wCurItem]
;>     if it >= REVIVE:
;>         kind = 'hp'
	cp REVIVE
	jr nc, .healHP ; if it's a Revive or Max Revive
;>     elif it == FULL_HEAL:
;>         kind = 'status'
	cp FULL_HEAL
	jr z, .cureStatusAilment ; if it's a Full Heal
;>     elif it >= HP_UP:                       # vitamins and Rare Candy
;>         kind = 'vitamin'
	cp HP_UP
	jp nc, .useVitamin ; if it's a vitamin or Rare Candy
;>     elif it >= FULL_RESTORE:                # Full Restore and the potions
;>         kind = 'hp'
	cp FULL_RESTORE
	jr nc, .healHP ; if it's a Full Restore or one of the potions
; fall through if it's one of the status-specific healing items
;>     else:
;>         kind = 'status'
;>@v0     if kind == 'vitamin':
;>@v1         wCurSpecies = wPokedexNum = mem[mon]
;>@v2         wCurEnemyLevel = mem[mon + MON_LEVEL]
;>@v3         GetMonHeader()
;>@v4         GetPartyMonName(target, addr(wPartyMonNicks))
;>@v5         if wCurItem != RARE_CANDY:
;>@v6             off = 2 * (wCurItem - HP_UP) & 0xFF
;>@v7             exp = mon + MON_HP_EXP + off    # the stat's experience, high byte first
;>@v8             add = 10                        # + 2560
;>@v9             if mem[exp] >= 100:             # 25600 already
;>@v10                 PrintText(VitaminNoEffectText)
;>@v11                 return GBPalWhiteOut()
;>@v12             mem[exp] = min(mem[exp] + add, 255)
;>@v13             stats = mon + MON_STATS
;>@v14             exp_lo = mon + MON_EXP + 2
;>@v15             CalcStats(stats, 1, exp_lo)
