.cureStatusAilment
;>             status = mon + MON_STATUS
	ld bc, MON_STATUS
	add hl, bc ; hl now points to status
;>             it = wCurItem
	ld a, [wCurItem]
;>             msg, cures = ANTIDOTE_MSG, 1 << PSN
	ld bc, ((ANTIDOTE_MSG) & $ff) << 8 + ((1 << PSN) & $ff)
;>             if it != ANTIDOTE:
	cp ANTIDOTE
	jr z, .checkMonStatus
;>                 msg, cures = BURN_HEAL_MSG, 1 << BRN
	ld bc, ((BURN_HEAL_MSG) & $ff) << 8 + ((1 << BRN) & $ff)
;>                 if it != BURN_HEAL:
	cp BURN_HEAL
	jr z, .checkMonStatus
;>                     msg, cures = ICE_HEAL_MSG, 1 << FRZ
	ld bc, ((ICE_HEAL_MSG) & $ff) << 8 + ((1 << FRZ) & $ff)
;>                     if it != ICE_HEAL:
	cp ICE_HEAL
	jr z, .checkMonStatus
;>                         msg, cures = AWAKENING_MSG, SLP_MASK
	ld bc, ((AWAKENING_MSG) & $ff) << 8 + ((SLP_MASK) & $ff)
;>                         if it != AWAKENING:
	cp AWAKENING
	jr z, .checkMonStatus
;>                             msg, cures = PARALYZ_HEAL_MSG, 1 << PAR
	ld bc, ((PARALYZ_HEAL_MSG) & $ff) << 8 + ((1 << PAR) & $ff)
;>                             if it != PARLYZ_HEAL:
	cp PARLYZ_HEAL
	jr z, .checkMonStatus
	; Full Heal
;>                                 msg, cures = FULL_HEAL_MSG, 0xFF
	ld bc, ((FULL_HEAL_MSG) & $ff) << 8 + (($ff) & $ff)
.checkMonStatus
;>             if not mem[status] & cures:     # nothing to cure
;>@sn                 outcome = 'none'
;>                 break
	ld a, [hl] ; pokemon's status
	and c ; does the pokemon have a status ailment the item can cure?
	jp z, .healingItemNoEffect
; if the pokemon has a status the item can heal
;>             mem[status] = 0
	xor a
	ld [hl], a ; remove the status ailment in the party data
;>             wPartyMenuTypeOrMessageID = msg
	ld a, b
	ld [wPartyMenuTypeOrMessageID], a ; the message to display for the item used
;>             if wPlayerMonNumber == target:  # in battle now: cure the battle copy too
	ld a, [wPlayerMonNumber]
	cp d ; is pokemon the item was used on active in battle?
	jp nz, .doneHealing
; if it is active in battle
;>                 wBattleMonStatus = 0
	xor a
	ld [wBattleMonStatus], a ; remove the status ailment in the in-battle pokemon data
;>                 wPlayerBattleStatus3 &= ~(1 << BADLY_POISONED) & 0xFF
	push hl
	ld hl, wPlayerBattleStatus3
	res BADLY_POISONED, [hl] ; heal Toxic status
	pop hl
;>                 stats = mon + MON_STATS
	ld bc, MON_STATS - MON_STATUS
	add hl, bc ; hl now points to party stats
;>                 CopyData(stats, addr(wBattleMonStats), NUM_STATS * 2)    # undo the stat drop
	ld de, wBattleMonStats
	ld bc, NUM_STATS * 2
	call CopyData ; copy party stats to in-battle stat data
;>                 predef(DoubleOrHalveSelectedStats)
	ld a, (DoubleOrHalveSelectedStatsPredef - PredefPointers) / 3
	call Predef
;>             outcome = 'healed'
;>             break
	jp .doneHealing
.healHP
;>         hp = mon + MON_HP                   # HP items
	inc hl ; hl = address of current HP
;>         hi = mem[hp]
	ld a, [hli]
	ld b, a
;>         mem[addr(wHPBarOldHP) + 1] = hi
	ld [wHPBarOldHP+1], a
;>         lo = mem[hp + 1]
	ld a, [hl]
	ld c, a
;>         mem[addr(wHPBarOldHP)] = lo
	ld [wHPBarOldHP], a ; current HP stored at wHPBarOldHP (2 bytes, big-endian)
;>         old = hi << 8 | lo
;>         if old == 0:                        # fainted: only the revives
	or b
	jr nz, .notFainted
; fainted
;>             if wCurItem != REVIVE and wCurItem != MAX_REVIVE:
;>@f1                 outcome = 'none'
;>                 break
	ld a, [wCurItem]
	cp REVIVE
	jr z, .updateInBattleFaintedData
	cp MAX_REVIVE
	jr z, .updateInBattleFaintedData
	jp .healingItemNoEffect
.updateInBattleFaintedData
;>             if wIsInBattle:                 # a revived Pokémon that fought still shares the experience
	ld a, [wIsInBattle]
	and a
	jr z, .compareCurrentHPToMaxHP
;>                 # (hl, de and bc are kept)
	push hl
	push de
	push bc
;>                 fought = FlagAction(addr(wPartyFoughtCurrentEnemyFlags), wUsedItemOnWhichPokemon, FLAG_TEST)
	ld a, [wUsedItemOnWhichPokemon]
	ld c, a
	ld hl, wPartyFoughtCurrentEnemyFlags
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;>                 if fought:
	ld a, c
	and a
	jr z, .next
;>                     FlagAction(addr(wPartyGainExpFlags), wUsedItemOnWhichPokemon, FLAG_SET)
	ld a, [wUsedItemOnWhichPokemon]
	ld c, a
	ld hl, wPartyGainExpFlags
	ld b, FLAG_SET
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
.next
;>                 # (they come back)
	pop bc
	pop de
	pop hl
	jr .compareCurrentHPToMaxHP
.notFainted
;>         else:                               # the others only for Pokémon still standing
;>             if wCurItem in (REVIVE, MAX_REVIVE):
;>@f2                 outcome = 'none'
;>                 break
	ld a, [wCurItem]
	cp REVIVE
	jp z, .healingItemNoEffect
	cp MAX_REVIVE
	jp z, .healingItemNoEffect
.compareCurrentHPToMaxHP
;>         # (hp + 1 and old are kept)
	push hl
	push bc
;>         maxhp = mon + MON_MAXHP
	ld bc, MON_MAXHP - (MON_HP + 1)
	add hl, bc ; hl now points to max HP
	pop bc
;>         top = mem[maxhp] << 8 | mem[maxhp + 1]
;>         at_max = old == top
	ld a, [hli]
	cp b
	jr nz, .skipComparingLSB ; no need to compare the LSB's if the MSB's don't match
	ld a, [hl]
	cp c
.skipComparingLSB
;>         # (hp + 1 comes back)
	pop hl
;>         if at_max:                          # full HP: only a Full Restore can still cure
	jr nz, .notFullHP
