	ld a, FULL_HEAL
	ld [wCurItem], a
;>             kind = 'status'                 # (back to mon)
;>             continue
	dec hl
	dec hl
	dec hl
	jp .cureStatusAilment
.notFullHP ; if the pokemon's current HP doesn't equal its max HP
;>         wLowHealthAlarm = 0
	xor a
