;>         mem[addr(wHPBarMaxHP)] = mem[maxhp + 1]
	ld a, [hl]
	ld [wHPBarMaxHP], a ; max HP stored at wHPBarMaxHP (2 bytes, big-endian)
;>         if wPseudoItemID:                   # SOFTBOILED: the user loses a fifth of its max HP
	ld a, [wPseudoItemID]
	and a ; using Softboiled?
	jp z, .notUsingSoftboiled2
; if using softboiled
;>             bars = addr(wHPBarMaxHP)        # the max and old HP, kept on the stack
	ld hl, wHPBarMaxHP
;>             kept = [mem[bars], mem[bars + 1]]
	ld a, [hli]
