	ld a, [hli]
	push af
;>             kept += [mem[bars + 2], mem[bars + 3]]
	ld a, [hli]
	push af
	ld a, [hl]
	push af
;>             user = AddNTimes(addr(wPartyMon1MaxHP), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld hl, wPartyMon1MaxHP
	ld a, [wWhichPokemon]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>             mem[addr(wHPBarMaxHP) + 1] = mem[addr(hDividend)] = mem[user]
	ld a, [hli]
	ld [wHPBarMaxHP + 1], a
	ldh [hDividend], a
;>             mem[addr(wHPBarMaxHP)] = mem[addr(hDividend) + 1] = mem[user + 1]
	ld a, [hl]
	ld [wHPBarMaxHP], a
	ldh [hDividend + 1], a
;>             mem[addr(hDivisor)] = 5
	ld a, 5
	ldh [hDivisor], a
;>             Divide(2)
	ld b, 2 ; number of bytes
	call Divide ; get 1/5 of max HP of pokemon that used Softboiled
;>             low = user + 1 + MON_HP - MON_MAXHP     # its HP, low byte
	ld bc, (MON_HP + 1) - (MON_MAXHP + 1)
	add hl, bc ; hl now points to LSB of current HP of pokemon that used Softboiled
; subtract 1/5 of max HP from current HP of pokemon that used Softboiled
;>             q_lo = mem[addr(hQuotient) + 3]          # (kept)
	ldh a, [hQuotient + 3]
	push af
	ld b, a
;>             mem[addr(wHPBarOldHP)] = mem[low]
	ld a, [hl]
	ld [wHPBarOldHP], a
;>             borrow = mem[low] < q_lo
;>             mem[low] = mem[addr(wHPBarNewHP)] = (mem[low] - q_lo) & 0xFF
	sub b
	ld [hld], a
	ld [wHPBarNewHP], a
;>             q_hi = mem[addr(hQuotient) + 2]
	ldh a, [hQuotient + 2]
	ld b, a
;>             mem[addr(wHPBarOldHP) + 1] = mem[low - 1]
	ld a, [hl]
	ld [wHPBarOldHP+1], a
;>             mem[low - 1] = mem[addr(wHPBarNewHP) + 1] = (mem[low - 1] - q_hi - borrow) & 0xFF
	sbc b
	ld [hl], a
	ld [wHPBarNewHP+1], a
;>             bar = AddNTimes(coord(4, 1), 2 * SCREEN_WIDTH, wWhichPokemon)    # the user's HP bar
	ld hl, (1) * SCREEN_WIDTH + (4) + wTileMap
	ld a, [wWhichPokemon]
	ld bc, 2 * SCREEN_WIDTH
	call AddNTimes ; calculate coordinates of HP bar of pokemon that used Softboiled
;>             PlaySoundWaitForCurrent(SFX_HEAL_HP)
	ld a, SFX_HEAL_HP
	call PlaySoundWaitForCurrent
;>             hUILayoutFlags |= 1 << BIT_PARTY_MENU_HP_BAR
	ldh a, [hUILayoutFlags]
	set BIT_PARTY_MENU_HP_BAR, a
	ldh [hUILayoutFlags], a
;>             wHPBarType = 2
	ld a, $02
	ld [wHPBarType], a
	; animate HP bar decrease of pokemon that used Softboiled
;>             predef(UpdateHPBar2, hl=bar)    # its bar goes down
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;>             hUILayoutFlags &= ~(1 << BIT_PARTY_MENU_HP_BAR) & 0xFF
	ldh a, [hUILayoutFlags]
	res BIT_PARTY_MENU_HP_BAR, a
	ldh [hUILayoutFlags], a
;>             heal = q_lo
	pop af
	ld b, a ; store heal amount (1/5 of max HP)
;>             p = bars + 3
	ld hl, wHPBarOldHP + 1
;>             mem[p], mem[p - 1] = kept[3], kept[2]
	pop af
	ld [hld], a
	pop af
	ld [hld], a
;>             mem[p - 2], mem[p - 3] = kept[1], kept[0]
	pop af
	ld [hld], a
	pop af
	ld [hl], a
	jr .addHealAmount
.notUsingSoftboiled2
;>         else:
;>             it = wCurItem
	ld a, [wCurItem]
;>             if it == SODA_POP:
;>                 heal = 60
	cp SODA_POP
	ld b, 60 ; Soda Pop heal amount
	jr z, .addHealAmount
;>             elif it > SODA_POP:             # Lemonade
;>                 heal = 80
	ld b, 80 ; Lemonade heal amount
	jr nc, .addHealAmount
;>             elif it == FRESH_WATER:
;>                 heal = 50
	cp FRESH_WATER
	ld b, 50 ; Fresh Water heal amount
	jr z, .addHealAmount
;>             elif it < SUPER_POTION:         # Hyper Potion (Full Restore and Max Potion fill up below)
;>                 heal = 200
	cp SUPER_POTION
	ld b, 200 ; Hyper Potion heal amount
	jr c, .addHealAmount
;>             elif it == SUPER_POTION:
;>                 heal = 50
	ld b, 50 ; Super Potion heal amount
	jr z, .addHealAmount
;>             else:
;>                 heal = 20                   # Potion
	ld b, 20 ; Potion heal amount
.addHealAmount
