	pop de
	pop hl
;>         low = mem[hp + 1] + heal
	ld a, [hl]
	add b
;>         mem[hp + 1] = mem[addr(wHPBarNewHP)] = low & 0xFF
	ld [hld], a
	ld [wHPBarNewHP], a
;>         mem[addr(wHPBarNewHP) + 1] = mem[hp]
	ld a, [hl]
	ld [wHPBarNewHP+1], a
;>         if low > 0xFF:
	jr nc, .noCarry
;>             mem[hp] += 1
	inc [hl]
;>             mem[addr(wHPBarNewHP) + 1] = mem[hp]
	ld a, [hl]
	ld [wHPBarNewHP + 1], a
.noCarry
;>         # (target is kept)
	push de
;>         cur = hp + 1
	inc hl
	ld d, h
	ld e, l ; de now points to current HP
;>         maxlo = mon + MON_MAXHP + 1
	ld hl, (MON_MAXHP + 1) - (MON_HP + 1)
	add hl, de ; hl now points to max HP
;>         if wCurItem == REVIVE:
;>@h1             half = top >> 1                 # half the max HP
;>@h2             mem[hp] = mem[addr(wHPBarNewHP) + 1] = half >> 8
;>@h3             mem[hp + 1] = mem[addr(wHPBarNewHP)] = half & 0xFF
;>@h4             cur = hp
	ld a, [wCurItem]
	cp REVIVE
	jr z, .setCurrentHPToHalfMaxHP
;>         else:
;>             diff_lo = mem[hp + 1] - (top & 0xFF)
	ld a, [hld]
	ld b, a
	ld a, [de]
	sub b
;>             cur = hp
	dec de
;>             full = mem[hp] - (top >> 8) - (diff_lo < 0) >= 0     # the new HP reaches the max
	ld b, [hl]
	ld a, [de]
	sbc b
;>             if full or wCurItem < HYPER_POTION or wCurItem == MAX_REVIVE:     # Full Restore, Max Potion, Max Revive: all of it
;>@x1                 mem[hp] = mem[addr(wHPBarNewHP) + 1] = top >> 8
;>@x2                 mem[hp + 1] = mem[addr(wHPBarNewHP)] = top & 0xFF
;>@x3                 cur = hp
	jr nc, .setCurrentHPToMaxHp ; if current HP exceeds max HP after healing
	ld a, [wCurItem]
	cp HYPER_POTION
	jr c, .setCurrentHPToMaxHp ; if using a Full Restore or Max Potion
	cp MAX_REVIVE
	jr z, .setCurrentHPToMaxHp ; if using a Max Revive
;>             else:
;>                 pass                        # (the HP stays as healed)
	jr .updateInBattleData
.setCurrentHPToHalfMaxHP
;=@h1
	dec hl
	dec de
;=@h2
	ld a, [hli]
