;>             status = mon + MON_STATUS
	ld bc, MON_STATUS - (MON_MAXHP + 1)
	add hl, bc
;>             mem[status] = 0
	xor a
	ld [hl], a ; remove the status ailment in the party data
.updateInBattleData
;>         # (hl = hp; target comes back)
	ld h, d
	ld l, e
	pop de
;>         if wPlayerMonNumber == target:      # in battle now: the battle copy too
	ld a, [wPlayerMonNumber]
	cp d ; is pokemon the item was used on active in battle?
