	ld a, [hli]
	ld [wBattleMonHP], a
;>             mem[addr(wBattleMonHP) + 1] = mem[hp + 1]
	ld a, [hld]
	ld [wBattleMonHP + 1], a
;>             if wCurItem == FULL_RESTORE:
	ld a, [wCurItem]
	cp FULL_RESTORE
	jr nz, .calculateHPBarCoords
