;>     hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;>     ClearScreen()
	call ClearScreen
;>     wUpdateSpritesEnabled = 0xFF
	dec a
	ld [wUpdateSpritesEnabled], a
;>     RedrawPartyMenu()                       # with the message
	call RedrawPartyMenu ; redraws the party menu and displays the message
;>     hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;>     DelayFrames(50)
	ld c, 50
	call DelayFrames
;>     WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
	jr .done
.canceledItemUse
;=@cx
	xor a
	ld [wActionResultOrTookBattleTurn], a ; item use failed
	pop af
	pop af
.done
;> if wPseudoItemID:
;>     return
	ld a, [wPseudoItemID]
	and a ; using Softboiled?
	ret nz ; if so, return
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> RunDefaultPaletteCommand()                  # (a call on the zero flag, which is set here)
	call z, RunDefaultPaletteCommand
;> if wIsInBattle:
;>     return
	ld a, [wIsInBattle]
	and a
	ret nz
;> return ReloadMapData()
	jp ReloadMapData
.useVitamin
;=@v1
	push hl
	ld a, [hl]
	ld [wCurSpecies], a
	ld [wPokedexNum], a
;=@v2
	ld bc, MON_LEVEL
	add hl, bc ; hl now points to level
	ld a, [hl] ; a = level
	ld [wCurEnemyLevel], a ; store level
;=@v3
	call GetMonHeader
;=@v4
	push de
	ld a, d
	ld hl, wPartyMonNicks
	call GetPartyMonName
	pop de
	pop hl
;=@v5
	ld a, [wCurItem]
	cp RARE_CANDY
	jp z, .useRareCandy
;=@v6
	push hl
	sub HP_UP
	add a
;=@v7
	ld bc, MON_HP_EXP
	add hl, bc
	add l
	ld l, a
	jr nc, .noCarry2
	inc h
.noCarry2
;=@v8
	ld a, 10
	ld b, a
;=@v9
	ld a, [hl] ; a = MSB of stat experience of the appropriate stat
	cp 100 ; is there already at least 25600 (256 * 100) stat experience?
	jr nc, .vitaminNoEffect ; if so, vitamins can't add any more
;=@v12
	add b ; add 2560 (256 * 10) stat experience
	jr nc, .noCarry3 ; a carry should be impossible here, so this will always jump
	ld a, 255
.noCarry3
	ld [hl], a
	pop hl
;=@v15
	call .recalculateStats
;=@v16
	ld hl, VitaminStats
;=@v17
	ld a, [wCurItem]
	sub HP_UP - 1
	ld c, a
.statNameLoop ; loop to get the address of the name of the stat the vitamin increases
;=@v19
	dec c
;=@v20
	jr z, .gotStatName
.statNameInnerLoop
;=@v23
	ld a, [hli]
	ld b, a
;=@v25
	ld a, '@'
	cp b
	jr nz, .statNameInnerLoop
;=@v18
	jr .statNameLoop
.gotStatName
;=@v27
	ld de, wStringBuffer
	ld bc, STAT_NAME_LENGTH
	call CopyData ; copy the stat's name to wStringBuffer
;=@v28
	ld a, SFX_HEAL_AILMENT
	call PlaySound
;=@v29
	ld hl, VitaminStatRoseText
	call PrintText
;=@v30
	jp RemoveUsedItem
.vitaminNoEffect
;=@v10
	pop hl
	ld hl, VitaminNoEffectText
	call PrintText
;=@v11
	jp GBPalWhiteOut
.recalculateStats
;=@v13
	ld bc, MON_STATS
	add hl, bc
	ld d, h
	ld e, l ; de now points to stats
;=@v14
	ld bc, (MON_EXP + 2) - MON_STATS
	add hl, bc ; hl now points to LSB of experience
;=@v15
	ld b, 1
	jp CalcStats ; recalculate stats
.useRareCandy
;=@c1
	push hl
	ld bc, MON_LEVEL
	add hl, bc ; hl now points to level
;=@c2
	ld a, [hl] ; a = level
	cp MAX_LEVEL
	jr z, .vitaminNoEffect ; can't raise level above 100
;=@c5
	inc a
	ld [hl], a ; store incremented level
;=@c6
	ld [wCurEnemyLevel], a
	push hl
	push de
;=@c7
	ld d, a
	; calculate experience for next level and store it at hExperience
	ld hl, CalcExperience
	ld b, BANK(CalcExperience)
	call Bankswitch
;=@c8
	pop de
	pop hl
	ld bc, MON_EXP - MON_LEVEL
	add hl, bc ; hl now points to MSB of experience
; update experience to minimum for new level
;=@c9
	ldh a, [hExperience]
	ld [hli], a
;=@c10
	ldh a, [hExperience + 1]
	ld [hli], a
;=@c11
	ldh a, [hExperience + 2]
	ld [hl], a
;=@c12
	pop hl
	ld a, [wWhichPokemon]
	push af
;=@c13
	ld a, [wCurItem]
	push af
;=@c14
	push de
	push hl
	ld bc, MON_MAXHP
	add hl, bc ; hl now points to MSB of max HP
;=@c15
	ld a, [hli]
	ld b, a
	ld c, [hl]
	pop hl
	push bc
	push hl
;=@c16
	call .recalculateStats
	pop hl
;=@c17
	ld bc, (MON_MAXHP + 1)
	add hl, bc ; hl now points to LSB of max HP
	pop bc
;=@c18
	ld a, [hld]
	sub c
	ld c, a
	ld a, [hl]
	sbc b
	ld b, a ; bc = the amount of max HP gained from leveling up
; add the amount gained to the current HP
;=@c19
	ld de, (MON_HP + 1) - MON_MAXHP
	add hl, de ; hl now points to LSB of current HP
;=@c20
	ld a, [hl]
	add c
	ld [hld], a
;=@c21
	ld a, [hl]
	adc b
	ld [hl], a
;=@c22
	ld a, RARE_CANDY_MSG
	ld [wPartyMenuTypeOrMessageID], a
;=@c23
	call RedrawPartyMenu
;=@c24
	pop de
	ld a, d
	ld [wWhichPokemon], a
;=@c25
	ld a, e
	ld [wPokedexNum], a
;=@c26
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;=@c27
	call LoadMonData
;=@c28
	ld d, LEVEL_UP_STATS_BOX
	ld hl, PrintStatsBox
	ld b, BANK(PrintStatsBox)
	call Bankswitch
;=@c29
	call WaitForTextScrollButtonPress
;=@c30
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;=@c31
	ld a, (LearnMoveFromLevelUpPredef - PredefPointers) / 3
	call Predef
;=@c32
	xor a
	ld [wForceEvolution], a
;=@c33
	ld hl, TryEvolvingMon
	ld b, BANK(TryEvolvingMon)
	call Bankswitch
;=@c34
	ld a, $01
	ld [wUpdateSpritesEnabled], a
;=@c35
	pop af
	ld [wCurItem], a
;=@c36
	pop af
	ld [wWhichPokemon], a
;=@c37
	jp RemoveUsedItem

;@ path: engine/items/item_effects
VitaminStatRoseText:
	db TX_FAR
	dw _VitaminStatRoseText
	db BANK(_VitaminStatRoseText)
	db TX_END

;@ path: engine/items/item_effects
VitaminNoEffectText:
	db TX_FAR
	dw _VitaminNoEffectText
	db BANK(_VitaminNoEffectText)
	db TX_END

; Stats that vitamins can raise or lower

;@ path: engine/items/item_effects
VitaminStats:
	db "HEALTH", "@"
	db "ATTACK", "@"
	db "DEFENSE", "@"
	db "SPEED", "@"
	db "SPECIAL", "@"

; for BOULDERBADGE when used from the
; ITEM window, which corresponds to
; SAFARI_BAIT during Safari Game encounters
;@ def ItemUseBait()
;@ Safari Zone bait: the wild Pokémon is half as easy to catch, but less likely to run.
;@ path: engine/items/item_effects
ItemUseBait:
;> PrintText(ThrewBaitText)
	ld hl, ThrewBaitText
	call PrintText
;> wEnemyMonActualCatchRate >>= 1
	ld hl, wEnemyMonActualCatchRate
	srl [hl] ; halve catch rate
;> return BaitRockCommon(BAIT_ANIM, addr(wSafariBaitFactor), addr(wSafariEscapeFactor))
	ld a, BAIT_ANIM
	ld hl, wSafariBaitFactor
	ld de, wSafariEscapeFactor
	jr BaitRockCommon

; for CASCADEBADGE when used from the
; ITEM window, which corresponds to
; SAFARI_ROCK during Safari Game encounters
;@ def ItemUseRock()
;@ Safari Zone rock: the wild Pokémon is twice as easy to catch, but more likely to run.
;@ path: engine/items/item_effects
ItemUseRock:
;> PrintText(ThrewRockText)
	ld hl, ThrewRockText
	call PrintText
;> rate = wEnemyMonActualCatchRate * 2
	ld hl, wEnemyMonActualCatchRate
	ld a, [hl]
	add a ; double catch rate
;> if rate > 0xFF:
;>     rate = 0xFF
	jr nc, .noCarry
	ld a, $ff
.noCarry
;> wEnemyMonActualCatchRate = rate
	ld [hl], a
;> return BaitRockCommon(ROCK_ANIM, addr(wSafariEscapeFactor), addr(wSafariBaitFactor))    # it follows
	ld a, ROCK_ANIM
	ld hl, wSafariEscapeFactor
	ld de, wSafariBaitFactor

;@ def BaitRockCommon(anim: a, factor: hl, other: de)
;@ The rest of a bait or rock throw: clear the other factor, raise this one by 1 to 5 (at most 255), play the
;@ throw animation and pause.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
BaitRockCommon:
;> wAnimationID = anim
	ld [wAnimationID], a
;> wAnimationType = 0
	xor a
	ld [wAnimationType], a
;> hWhoseTurn = 0
	ldh [hWhoseTurn], a
;> mem[other] = 0
	ld [de], a ; zero escape factor (for bait), zero bait factor (for rock)
;> while True:
.randomLoop ; loop until a random number less than 5 is generated
;>     r = Random(False) & 7
	call Random
	and 7
;>     if r < 5:
;>         break
	cp 5
	jr nc, .randomLoop
;> amount = r + 1                              # 1 to 5
	inc a ; increment the random number, giving a range from 1 to 5 inclusive
	ld b, a
;> total = mem[factor] + amount
	ld a, [hl]
	add b ; increase bait factor (for bait), increase escape factor (for rock)
;> if total > 0xFF:
;>     total = 0xFF
	jr nc, .noCarry
	ld a, $ff
.noCarry
;> mem[factor] = total
	ld [hl], a
	; do animation
;> MoveAnimation()
	ld a, (MoveAnimationPredef - PredefPointers) / 3
	call Predef
;> DelayFrames(70)
	ld c, 70
	jp DelayFrames

;@ path: engine/items/item_effects
ThrewBaitText:
	db TX_FAR
	dw _ThrewBaitText
	db BANK(_ThrewBaitText)
	db TX_END

;@ path: engine/items/item_effects
ThrewRockText:
	db TX_FAR
	dw _ThrewRockText
	db BANK(_ThrewRockText)
	db TX_END

; indirectly used by DIG in StartMenu_Pokemon.dig
;@ def ItemUseEscapeRope()
;@ Escape Rope (and DIG outside battle): warp back to the last Pokémon Center, only from caves and other
;@ tilesets in EscapeRopeTilesets, and never from Agatha's room. Leaving also ends a Safari Game.
;@ path: engine/items/item_effects
ItemUseEscapeRope:
;> if wIsInBattle or wCurMap == AGATHAS_ROOM:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jr nz, .notUsable
	ld a, [wCurMap]
	cp AGATHAS_ROOM
	jr z, .notUsable
;> tileset = wCurMapTileset
	ld a, [wCurMapTileset]
	ld b, a
;> p = EscapeRopeTilesets
	ld hl, EscapeRopeTilesets
;>@lp while True:
.loop
;>     t = mem[p]
;>     p += 1
	ld a, [hli]
;>     if t == 0xFF:
;>         return ItemUseNotTime()
	cp $ff
	jr z, .notUsable
;>     if t == tileset:
;>         break
	cp b
	jr nz, .loop
;> wStatusFlags6 |= (1 << BIT_FLY_WARP) | (1 << BIT_ESCAPE_WARP)
	ld hl, wStatusFlags6
	set BIT_FLY_WARP, [hl]
	set BIT_ESCAPE_WARP, [hl]
;> wStatusFlags4 &= ~(1 << BIT_NO_BATTLES) & 0xFF
	ld hl, wStatusFlags4
	res BIT_NO_BATTLES, [hl]
;> reset_event(EVENT_IN_SAFARI_ZONE)
	ld hl, wEventFlags + $49
	res (EVENT_IN_SAFARI_ZONE) % 8, [hl]
;> wNumSafariBalls = 0
	xor a
	ld [wNumSafariBalls], a
;> wSafariZoneGateCurScript = 0
	ld [wSafariZoneGateCurScript], a ; SCRIPT_SAFARIZONEGATE_DEFAULT
;> wEscapedFromBattle = 1
	inc a
	ld [wEscapedFromBattle], a
;> wActionResultOrTookBattleTurn = 1
	ld [wActionResultOrTookBattleTurn], a ; item used
;> if wPseudoItemID:                           # DIG: nothing to use up
;>     return
	ld a, [wPseudoItemID]
	and a ; using Dig?
	ret nz ; if so, return
;> ItemUseReloadOverworldData()
	call ItemUseReloadOverworldData
;> DelayFrames(30)
	ld c, 30
	call DelayFrames
;> return RemoveUsedItem()
	jp RemoveUsedItem
.notUsable
	jp ItemUseNotTime

;@ path: engine/items/item_effects
EscapeRopeTilesets:
	db FOREST
	db CEMETERY
	db CAVERN
	db FACILITY
	db INTERIOR
	db -1 ; end

;@ def ItemUseRepel()
;@ Repel: wild Pokémon weaker than the lead stay away for 100 steps.
;@ path: engine/items/item_effects
ItemUseRepel:
;> return ItemUseRepelCommon(100)
	ld b, 100

;@ def ItemUseRepelCommon(steps: b)
;@ Any repel: set the step counter and use the item up (not in battle).
;@ path: engine/items/item_effects
ItemUseRepelCommon:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> wRepelRemainingSteps = steps
	ld a, b
	ld [wRepelRemainingSteps], a
;> return PrintItemUseTextAndRemoveItem()
	jp PrintItemUseTextAndRemoveItem

; handles X Accuracy item
;@ def ItemUseXAccuracy()
;@ X Accuracy: in battle, the player's moves never miss from now on.
;@ path: engine/items/item_effects
ItemUseXAccuracy:
;> if not wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp z, ItemUseNotTime
;> wPlayerBattleStatus2 |= 1 << USING_X_ACCURACY
	ld hl, wPlayerBattleStatus2
	set USING_X_ACCURACY, [hl] ; X Accuracy bit
;> return PrintItemUseTextAndRemoveItem()
	jp PrintItemUseTextAndRemoveItem

; This function is bugged and never works. It always jumps to ItemUseNotTime.
; The Card Key is handled in a different way.
;@ def ItemUseCardKey()
;@ Card Key used from the bag. It reads its tile from the first code byte of GetTileAndCoordsInFrontOfPlayer
;@ instead of the tile in front of the player, so it never matches and always says it is not the time. The doors
;@ in Silph Co. open another way.
;@ path: engine/items/item_effects
ItemUseCardKey:
;> wUnusedCardKeyGateID = 0
	xor a
	ld [wUnusedCardKeyGateID], a
;> _, y, x = GetTileAndCoordsInFrontOfPlayer()
	call GetTileAndCoordsInFrontOfPlayer
;> tile = mem[GetTileAndCoordsInFrontOfPlayer]       # the bug: a code byte, not the tile
	ld a, [GetTileAndCoordsInFrontOfPlayer]
;> if tile == 0x18:
	cp $18
	jr nz, .next0
;>     p = CardKeyTable1
	ld hl, CardKeyTable1
	jr .next1
.next0
;> elif tile == 0x24:
	cp $24
	jr nz, .next2
;>     p = CardKeyTable2
	ld hl, CardKeyTable2
	jr .next1
.next2
;> else:
;>     if tile != 0x5E:
;>         return ItemUseNotTime()
	cp $5e
	jp nz, ItemUseNotTime
;>     p = CardKeyTable3
	ld hl, CardKeyTable3
.next1
;> map_ = wCurMap
	ld a, [wCurMap]
	ld b, a
.loop
;>@lp while True:                              # entries: map, y, x, gate
;>     m = mem[p]
	ld a, [hli]
;>     if m == 0xFF:
;>         return ItemUseNotTime()
	cp -1
	jp z, ItemUseNotTime
;>     if m == map_:
	cp b
	jr nz, .nextEntry1
;>         if mem[p + 1] == y:
	ld a, [hli]
	cp d
	jr nz, .nextEntry2
;>             if mem[p + 2] == x:
	ld a, [hli]
	cp e
	jr nz, .nextEntry3
;>                 wUnusedCardKeyGateID = mem[p + 3]
	ld a, [hl]
	ld [wUnusedCardKeyGateID], a
;>                 break
	jr .done
;>     p += 4
.nextEntry1
	inc hl
.nextEntry2
	inc hl
.nextEntry3
	inc hl
;=@lp
	jr .loop
.done
;> PrintText(ItemUseText00)
	ld hl, ItemUseText00
	call PrintText
;> wStatusFlags1 |= 1 << BIT_UNUSED_CARD_KEY
	ld hl, wStatusFlags1
	set BIT_UNUSED_CARD_KEY, [hl] ; never checked
;> return
	ret

; These tables are probably supposed to be door locations in Silph Co.,
; but they are unused.
; The reason there are 3 tables is unknown.

; Format: map ID, Y, X, gate ID?

;@ path: engine/items/item_effects
CardKeyTable1:
	db  SILPH_CO_2F, $04, $04, 0
	db  SILPH_CO_2F, $04, $05, 1
	db  SILPH_CO_4F, $0C, $04, 2
	db  SILPH_CO_4F, $0C, $05, 3
	db  SILPH_CO_7F, $06, $0A, 4
	db  SILPH_CO_7F, $06, $0B, 5
	db  SILPH_CO_9F, $04, $12, 6
	db  SILPH_CO_9F, $04, $13, 7
	db SILPH_CO_10F, $08, $0A, 8
	db SILPH_CO_10F, $08, $0B, 9
	db -1 ; end

;@ path: engine/items/item_effects
CardKeyTable2:
	db SILPH_CO_3F, $08, $09, 10
	db SILPH_CO_3F, $09, $09, 11
	db SILPH_CO_5F, $04, $07, 12
	db SILPH_CO_5F, $05, $07, 13
	db SILPH_CO_6F, $0C, $05, 14
	db SILPH_CO_6F, $0D, $05, 15
	db SILPH_CO_8F, $08, $07, 16
	db SILPH_CO_8F, $09, $07, 17
	db SILPH_CO_9F, $08, $03, 18
	db SILPH_CO_9F, $09, $03, 19
	db -1 ; end

;@ path: engine/items/item_effects
CardKeyTable3:
	db SILPH_CO_11F, $08, $09, 20
	db SILPH_CO_11F, $09, $09, 21
	db -1 ; end

;@ def ItemUsePokeDoll()
;@ Poké Doll: escape from a wild battle for sure (not from a trainer, not outside battle).
;@ path: engine/items/item_effects
ItemUsePokeDoll:
;> if wIsInBattle != 1:                        # only from a wild battle
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	dec a
	jp nz, ItemUseNotTime
;> wEscapedFromBattle = 1
	ld a, $01
	ld [wEscapedFromBattle], a
;> return PrintItemUseTextAndRemoveItem()
	jp PrintItemUseTextAndRemoveItem

;@ def ItemUseGuardSpec()
;@ Guard Spec.: in battle, protects the player's Pokémon from stat drops like the move Mist.
;@ path: engine/items/item_effects
ItemUseGuardSpec:
;> if not wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp z, ItemUseNotTime
;> wPlayerBattleStatus2 |= 1 << PROTECTED_BY_MIST
	ld hl, wPlayerBattleStatus2
	set PROTECTED_BY_MIST, [hl] ; Mist bit
;> return PrintItemUseTextAndRemoveItem()
	jp PrintItemUseTextAndRemoveItem

;@ def ItemUseSuperRepel()
;@ Super Repel: 200 steps.
;@ path: engine/items/item_effects
ItemUseSuperRepel:
;> return ItemUseRepelCommon(200)
	ld b, 200
	jp ItemUseRepelCommon

;@ def ItemUseMaxRepel()
;@ Max Repel: 250 steps.
;@ path: engine/items/item_effects
ItemUseMaxRepel:
;> return ItemUseRepelCommon(250)
	ld b, 250
	jp ItemUseRepelCommon

;@ def ItemUseDireHit()
;@ Dire Hit: in battle, raises the critical hit rate like Focus Energy.
;@ path: engine/items/item_effects
ItemUseDireHit:
;> if not wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp z, ItemUseNotTime
;> wPlayerBattleStatus2 |= 1 << GETTING_PUMPED
	ld hl, wPlayerBattleStatus2
	set GETTING_PUMPED, [hl] ; Focus Energy bit
;> return PrintItemUseTextAndRemoveItem()
	jp PrintItemUseTextAndRemoveItem

;@ def ItemUseXStat()
;@ X Attack, X Defend, X Speed and X Special: in battle, run the matching stat-up move effect for the player,
;@ with the player's move number and effect saved and put back around it.
;@ path: engine/items/item_effects
ItemUseXStat:
;> if not wIsInBattle:
	ld a, [wIsInBattle]
	and a
	jr nz, .inBattle
;>     ItemUseNotTime()
	call ItemUseNotTime
;>     wActionResultOrTookBattleTurn = 2
	ld a, 2
	ld [wActionResultOrTookBattleTurn], a ; item not used
;>     return
	ret
.inBattle
;> move, effect = wPlayerMoveNum, wPlayerMoveEffect
	ld hl, wPlayerMoveNum
	ld a, [hli]
	push af ; save [wPlayerMoveNum]
	ld a, [hl]
	push af ; save [wPlayerMoveEffect]
	push hl
;> wPlayerMoveEffect = (wCurItem - (X_ATTACK - ATTACK_UP1_EFFECT)) & 0xFF
	ld a, [wCurItem]
	sub X_ATTACK - ATTACK_UP1_EFFECT
	ld [hl], a ; store player move effect
;> PrintItemUseTextAndRemoveItem()
	call PrintItemUseTextAndRemoveItem
;> wPlayerMoveNum = XSTATITEM_ANIM
	ld a, XSTATITEM_ANIM ; X stat item animation ID
	ld [wPlayerMoveNum], a
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1 ; restore saved screen
;> Delay3()
	call Delay3
;> hWhoseTurn = 0
	xor a
	ldh [hWhoseTurn], a ; set turn to player's turn
	; do stat increase move
;> farcall(StatModifierUpEffect)
	ld b, BANK(StatModifierUpEffect)
	ld hl, StatModifierUpEffect
	call Bankswitch
;> wPlayerMoveEffect = effect
	pop hl
	pop af
	ld [hld], a ; restore [wPlayerMoveEffect]
;> wPlayerMoveNum = move
	pop af
	ld [hl], a ; restore [wPlayerMoveNum]
	ret

;@ def ItemUsePokeFlute()
;@ Poké Flute. Outside battle it wakes the sleeping Snorlax on Route 12 or 16 when the player stands next to it.
;@ In battle it wakes every Pokémon on both sides (the enemy party only in a trainer battle) and plays its tune.
;@ path: engine/items/item_effects
ItemUsePokeFlute:
;> if not wIsInBattle:
	ld a, [wIsInBattle]
	and a
	jr nz, .inBattle
; if not in battle
;>     ItemUseReloadOverworldData()
	call ItemUseReloadOverworldData
;>     if wCurMap == ROUTE_12:
	ld a, [wCurMap]
	cp ROUTE_12
	jr nz, .notRoute12
;>         if not event(EVENT_BEAT_ROUTE12_SNORLAX) and ArePlayerCoordsInArray(Route12SnorlaxFluteCoords):
	ld a, [wEventFlags + $91]
	bit (EVENT_BEAT_ROUTE12_SNORLAX) % 8, a
	jr nz, .noSnorlaxToWakeUp
; if the player hasn't beaten Route 12 Snorlax
	ld hl, Route12SnorlaxFluteCoords
	call ArePlayerCoordsInArray
	jr nc, .noSnorlaxToWakeUp
;>             PrintText(PlayedFluteHadEffectText)
	ld hl, PlayedFluteHadEffectText
	call PrintText
;>             set_event(EVENT_FIGHT_ROUTE12_SNORLAX)
	ld hl, wEventFlags + $91
	set (EVENT_FIGHT_ROUTE12_SNORLAX) % 8, [hl]
;>             return
	ret
.notRoute12
;>     elif wCurMap == ROUTE_16:
	cp ROUTE_16
	jr nz, .noSnorlaxToWakeUp
;>         if not event(EVENT_BEAT_ROUTE16_SNORLAX) and ArePlayerCoordsInArray(Route16SnorlaxFluteCoords):
	ld a, [wEventFlags + $99]
	bit (EVENT_BEAT_ROUTE16_SNORLAX) % 8, a
	jr nz, .noSnorlaxToWakeUp
; if the player hasn't beaten Route 16 Snorlax
	ld hl, Route16SnorlaxFluteCoords
	call ArePlayerCoordsInArray
	jr nc, .noSnorlaxToWakeUp
;>             PrintText(PlayedFluteHadEffectText)
	ld hl, PlayedFluteHadEffectText
	call PrintText
;>             set_event(EVENT_FIGHT_ROUTE16_SNORLAX)
	ld hl, wEventFlags + $99
	set (EVENT_FIGHT_ROUTE16_SNORLAX) % 8, [hl]
;>             return
	ret
.noSnorlaxToWakeUp
;>     return PrintText(PlayedFluteNoEffectText)
	ld hl, PlayedFluteNoEffectText
	jp PrintText
.inBattle
;> mem[addr(wWereAnyMonsAsleep)] = 0
	xor a
	ld [wWereAnyMonsAsleep], a
;> awake = ~SLP_MASK & 0xFF
	ld b, ~SLP_MASK
;> WakeUpEntireParty(addr(wPartyMon1Status), awake)
	ld hl, wPartyMon1Status
	call WakeUpEntireParty
;> if wIsInBattle != 1:                        # a trainer's party wakes up too
	ld a, [wIsInBattle]
	dec a ; is it a trainer battle?
	jr z, .skipWakingUpEnemyParty
; if it's a trainer battle
;>     WakeUpEntireParty(addr(wEnemyMon1Status), awake)
	ld hl, wEnemyMon1Status
	call WakeUpEntireParty
.skipWakingUpEnemyParty
;> wBattleMonStatus &= awake
	ld hl, wBattleMonStatus
	ld a, [hl]
	and b ; remove Sleep status
	ld [hl], a
;> wEnemyMonStatus &= awake
	ld hl, wEnemyMonStatus
	ld a, [hl]
	and b ; remove Sleep status
	ld [hl], a
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2 ; restore saved screen
;> if not mem[addr(wWereAnyMonsAsleep)]:
;>     return PrintText(PlayedFluteNoEffectText)
	ld a, [wWereAnyMonsAsleep]
	and a ; were any pokemon asleep before playing the flute?
	ld hl, PlayedFluteNoEffectText
	jp z, PrintText ; if no pokemon were asleep
; if some pokemon were asleep
;> PrintText(PlayedFluteHadEffectText)
	ld hl, PlayedFluteHadEffectText
	call PrintText
;> if not wLowHealthAlarm & 0x80:
	ld a, [wLowHealthAlarm]
	and $80
	jr nz, .skipMusic
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish ; wait for sound to end
	; play in-battle pokeflute music
;>     farcall(Music_PokeFluteInBattle)
	ld b, BANK(Music_PokeFluteInBattle)
	ld hl, Music_PokeFluteInBattle
	call Bankswitch
;>     while mem[addr(wChannelSoundIDs) + CHAN7]:    # the sound interrupt plays the tune to its end
;>         wait_vblank_flag()
.musicWaitLoop ; wait for music to finish playing
	ld a, [wChannelSoundIDs + CHAN7]
	and a ; music off?
	jr nz, .musicWaitLoop
.skipMusic
;> return PrintText(FluteWokeUpText)
	ld hl, FluteWokeUpText
	jp PrintText

; wakes up all party pokemon
; INPUT:
; hl must point to status of first pokemon in party (player's or enemy's)
; b must equal ~SLP
; [wWereAnyMonsAsleep] should be initialized to 0
; OUTPUT:
; [wWereAnyMonsAsleep]: set to 1 if any pokemon were asleep
;@ def WakeUpEntireParty(status: hl, awake: b)
;@ Clear the sleep counter of all six party slots, starting at the first one's status byte (awake = ~SLP_MASK).
;@ Sets wWereAnyMonsAsleep to 1 if any of them was asleep.
;@ test: status = rand(0xC000, 0xDE00); awake = 0xF8
;@ path: engine/items/item_effects
WakeUpEntireParty:
;> step = PARTYMON_STRUCT_LENGTH
	ld de, PARTYMON_STRUCT_LENGTH
;>@lp for _ in range(PARTY_LENGTH):
	ld c, PARTY_LENGTH
.loop
;>     s = mem[status]
	ld a, [hl]
	push af
;>     if s & SLP_MASK:
	and SLP_MASK
	jr z, .notAsleep
;>         wWereAnyMonsAsleep = 1
	ld a, 1
	ld [wWereAnyMonsAsleep], a ; indicate that a pokemon had to be woken up
.notAsleep
;>     mem[status] = s & awake
	pop af
	and b ; remove Sleep status
	ld [hl], a
;>     status += step
	add hl, de
;=@lp
	dec c
	jr nz, .loop
;> return
	ret

;@ path: engine/items/item_effects
Route12SnorlaxFluteCoords:
	; one space West of Snorlax
	db 62, 9
	; one space North of Snorlax
	db 61, 10
	; one space South of Snorlax
	db 63, 10
	; one space East of Snorlax
	db 62, 11
	db -1 ; end

;@ path: engine/items/item_effects
Route16SnorlaxFluteCoords:
	; one space East of Snorlax
	db 10, 27
	; one space West of Snorlax
	db 10, 25
	db -1 ; end

;@ path: engine/items/item_effects
PlayedFluteNoEffectText:
	db TX_FAR
	dw _PlayedFluteNoEffectText
	db BANK(_PlayedFluteNoEffectText)
	db TX_END

;@ path: engine/items/item_effects
FluteWokeUpText:
	db TX_FAR
	dw _FluteWokeUpText
	db BANK(_FluteWokeUpText)
	db TX_END

;@ def PlayedFluteHadEffectText() -> hl
;@ The "played the Poké Flute" text. Outside battle its script then stops the music, plays the flute tune to
;@ its end and starts the map's music again.
;@ test: skip a text script: the text engine prints the text and then runs the code after text_asm
;@ path: engine/items/item_effects
PlayedFluteHadEffectText:
	db TX_FAR
	dw _PlayedFluteHadEffectText
	db BANK(_PlayedFluteHadEffectText)
	db TX_PROMPT_BUTTON
	db TX_START_ASM
;> if not wIsInBattle:
	ld a, [wIsInBattle]
	and a
	jr nz, .done
; play out-of-battle pokeflute music
;>     PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;>     PlayMusic(SFX_POKEFLUTE, BANK(SFX_Pokeflute))
	ld a, SFX_POKEFLUTE
	ld c, BANK(SFX_Pokeflute)
	call PlayMusic
;>     while mem[addr(wChannelSoundIDs) + CHAN3] == SFX_POKEFLUTE:   # wait for the tune to end
;>         wait_vblank_flag()
.musicWaitLoop ; wait for music to finish playing
	ld a, [wChannelSoundIDs + CHAN3]
	cp SFX_POKEFLUTE
	jr z, .musicWaitLoop
;>     PlayDefaultMusic()
	call PlayDefaultMusic ; start playing normal music again
.done
;> return TextScriptEnd()
	jp TextScriptEnd ; end text

;@ def ItemUseCoinCase()
;@ Coin Case: shows how many Game Corner coins the player has (not in battle).
;@ path: engine/items/item_effects
ItemUseCoinCase:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> return PrintText(CoinCaseNumCoinsText)
	ld hl, CoinCaseNumCoinsText
	jp PrintText

;@ path: engine/items/item_effects
CoinCaseNumCoinsText:
	db TX_FAR
	dw _CoinCaseNumCoinsText
	db BANK(_CoinCaseNumCoinsText)
	db TX_END

;@ def ItemUseOldRod()
;@ Old Rod: always a bite, always a level 5 Magikarp.
;@ path: engine/items/item_effects
ItemUseOldRod:
;> if FishingInit():
;>     return ItemUseNotTime()
	call FishingInit
	jp c, ItemUseNotTime
;> return RodResponse(1, 5, MAGIKARP)
	ld bc, ((5) & $ff) << 8 + ((MAGIKARP) & $ff)
	ld a, $1 ; set bite
	jr RodResponse

;@ def ItemUseGoodRod()
;@ Good Rod: half the time nothing bites; otherwise one of the two GoodRodMons (level, species) pairs.
;@ path: engine/items/item_effects
ItemUseGoodRod:
;> if FishingInit():
;>     return ItemUseNotTime()
	call FishingInit
	jp c, ItemUseNotTime
;> while True:
.RandomLoop
;>     r = Random(False)
	call Random
;>     if r & 1:
;>         return RodResponse(0, 0, 0)         # nothing bites
	srl a
	jr c, .SetBite
;>     r = (r >> 1) & 3
	and %11
;>     if r < 2:
;>         break
	cp 2
	jr nc, .RandomLoop
	; choose which monster appears
;> p = GoodRodMons + 2 * r
	ld hl, GoodRodMons
	add a
	ld c, a
	ld b, 0
	add hl, bc
;> level = mem[p]
	ld b, [hl]
;> species = mem[p + 1]
	inc hl
	ld c, [hl]
;> return RodResponse(1, level, species)      # (the bite flag comes from the carry: here 1, from the jump above 0)
	and a
.SetBite
	ld a, 0
	rla
	xor 1
	jr RodResponse

; random choice of 2 good rod encounters
;@ path: engine/items/item_effects
GoodRodMons:
	; level, species
	db 10, GOLDEEN
	db 10, POLIWAG

;@ def ItemUseSuperRod()
;@ Super Rod: the fish depend on the map (SuperRodData).
;@ path: engine/items/item_effects
ItemUseSuperRod:
;> if FishingInit():
;>     return ItemUseNotTime()
	call FishingInit
	jp c, ItemUseNotTime
;> bite, level, species = ReadSuperRodData()
	call ReadSuperRodData
	ld a, e
;> return RodResponse(bite, level, species)    # it follows
;@ def RodResponse(bite: a, level: b, species: c)
;@ Store the fishing result (1 = a bite, 0 = nothing, 2 = no fish here). A bite sets up a wild battle with that
;@ level and species. Then the fishing animation, drawn with the walking player sprite.
;@ path: engine/items/item_effects
RodResponse:
;> wRodResponse = bite
	ld [wRodResponse], a

;> if bite == 1:
	dec a ; is there a bite?
	jr nz, .next
	; if yes, store level and species data
;>     wMoveMissed = 1
	ld a, 1
	ld [wMoveMissed], a
;>     wCurEnemyLevel = level
	ld a, b ; level
	ld [wCurEnemyLevel], a
;>     wCurOpponent = species
	ld a, c ; species
	ld [wCurOpponent], a

.next
;> state = wWalkBikeSurfState
	ld hl, wWalkBikeSurfState
	ld a, [hl] ; store the value in a
	push af
	push hl
;> wWalkBikeSurfState = 0
	ld [hl], 0
;> farcall(FishingAnim)
	ld b, BANK(FishingAnim)
	ld hl, FishingAnim
	call Bankswitch
;> wWalkBikeSurfState = state
	pop hl
	pop af
	ld [hl], a
	ret

; checks if fishing is possible and if so, runs initialization code common to all rods
; unsets carry if fishing is possible, sets carry if not
;@ def FishingInit() -> carry
;@ Can the player fish here? Not in battle, not while surfing, and only facing shore or water. If so: redraw the
;@ map, print the "used the rod" text, play a sound and wait. Carry if fishing is not possible.
;@ path: engine/items/item_effects
FishingInit:
;> if wIsInBattle:
;>     return True
	ld a, [wIsInBattle]
	and a
	jr z, .notInBattle
	scf ; can't fish during battle
	ret
.notInBattle
;> if IsNextTileShoreOrWater():
;>     return True
	call IsNextTileShoreOrWater
	ret c
;> if wWalkBikeSurfState == 2:
;>     return True
	ld a, [wWalkBikeSurfState]
	cp 2 ; Surfing?
	jr z, .surfing
;> ItemUseReloadOverworldData()
	call ItemUseReloadOverworldData
;> PrintText(ItemUseText00)
	ld hl, ItemUseText00
	call PrintText
;> PlaySound(SFX_HEAL_AILMENT)
	ld a, SFX_HEAL_AILMENT
	call PlaySound
;> DelayFrames(80)
	ld c, 80
	call DelayFrames
;> return False
	and a
	ret
.surfing
	scf ; can't fish when surfing
	ret

;@ def ItemUseOaksParcel()
;@ Oak's Parcel is not the player's to use.
;@ path: engine/items/item_effects
ItemUseOaksParcel:
;> return ItemUseNotYoursToUse()
	jp ItemUseNotYoursToUse

;@ def ItemUseItemfinder()
;@ Itemfinder: beeps four times if a hidden item is near the player (not in battle).
;@ path: engine/items/item_effects
ItemUseItemfinder:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> ItemUseReloadOverworldData()
	call ItemUseReloadOverworldData
	; check for hidden items
;> if not farcall(HiddenItemNear):
;>     return PrintText(ItemfinderFoundNothingText)
	ld b, BANK(HiddenItemNear)
	ld hl, HiddenItemNear
	call Bankswitch
	ld hl, ItemfinderFoundNothingText
	jr nc, .printText ; if no hidden items
;> for _ in range(4):
	ld c, 4
.loop
;>     PlaySoundWaitForCurrent(SFX_HEALING_MACHINE)
	ld a, SFX_HEALING_MACHINE
	call PlaySoundWaitForCurrent
;>     PlaySoundWaitForCurrent(SFX_PURCHASE)
	ld a, SFX_PURCHASE
	call PlaySoundWaitForCurrent
	dec c
	jr nz, .loop
;> return PrintText(ItemfinderFoundItemText)
	ld hl, ItemfinderFoundItemText
.printText
	jp PrintText

;@ path: engine/items/item_effects
ItemfinderFoundItemText:
	db TX_FAR
	dw _ItemfinderFoundItemText
	db BANK(_ItemfinderFoundItemText)
	db TX_END

;@ path: engine/items/item_effects
ItemfinderFoundNothingText:
	db TX_FAR
	dw _ItemfinderFoundNothingText
	db BANK(_ItemfinderFoundNothingText)
	db TX_END

;@ def ItemUsePPUp()
;@ PP Up: not in battle; otherwise handled with the other PP items.
;@ path: engine/items/item_effects
ItemUsePPUp:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> return ItemUsePPRestore()                   # it follows

;@ def ItemUsePPRestore()
;@ PP Up, Ether, Max Ether, Elixir and Max Elixir: pick a Pokémon, and for PP Up and the Ethers a move. A PP Up
;@ raises the move's max PP by a fifth (at most three times); an Ether restores 10 PP, a Max Ether all of it; the
;@ Elixirs do the same for all four moves. Max Ether and Max Elixir miss "no effect" on a full move that had PP Ups.
;@ path: engine/items/item_effects
ItemUsePPRestore:
;> which = wWhichPokemon
	ld a, [wWhichPokemon]
	push af
;> wPPRestoreItem = wCurItem
	ld a, [wCurItem]
	ld [wPPRestoreItem], a
;>@r0 result = None
;>@cp while result is None:                       # choose a Pokémon
.chooseMon
;>     wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;>     wPartyMenuTypeOrMessageID = USE_ITEM_PARTY_MENU
	ld a, USE_ITEM_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;>     if DisplayPartyMenu():
	call DisplayPartyMenu
	jr nc, .chooseMove
;>         result = 'not used'
;>         break
	jp .itemNotUsed
;>@cm     while True:                             # choose a move
.chooseMove
;>         if wPPRestoreItem >= ELIXER:
;>@x1             result = 'elixir'
;>             break
	ld a, [wPPRestoreItem]
	cp ELIXER
	jp nc, .useElixir ; if Elixir or Max Elixir
;>         wMoveMenuType = 2
	ld a, $02
	ld [wMoveMenuType], a
;>         text = RaisePPWhichTechniqueText
	ld hl, RaisePPWhichTechniqueText
;>         if wPPRestoreItem >= ETHER:         # not a PP Up
	ld a, [wPPRestoreItem]
	cp ETHER ; is it a PP Up?
	jr c, .printWhichTechniqueMessage ; if so, print the raise PP message
;>             text = RestorePPWhichTechniqueText
	ld hl, RestorePPWhichTechniqueText ; otherwise, print the restore PP message
.printWhichTechniqueMessage
;>         PrintText(text)
	call PrintText
;>         wPlayerMoveListIndex = 0
	xor a
	ld [wPlayerMoveListIndex], a
	; move selection menu
;>         cancelled = farcall(MoveSelectionMenu)
	ld hl, MoveSelectionMenu
	ld b, BANK(MoveSelectionMenu)
	call Bankswitch
;>         wPlayerMoveListIndex = 0
	ld a, 0
	ld [wPlayerMoveListIndex], a
;>         if cancelled:                       # back to the party menu
;>             break
	jr nz, .chooseMon
;>         move = GetSelectedMoveOffset(addr(wPartyMon1Moves), PARTYMON_STRUCT_LENGTH)
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	call GetSelectedMoveOffset
;>         wNamedObjectIndex = mem[move]
	push hl
	ld a, [hl]
	ld [wNamedObjectIndex], a
;>         CopyToStringBuffer(GetMoveName())
	call GetMoveName
	call CopyToStringBuffer
;>         if wPPRestoreItem >= ETHER:         # (move comes back first)
;>@x2             result = 'ether'
;>             break
	pop hl
	ld a, [wPPRestoreItem]
	cp ETHER
	jr nc, .useEther ; if Ether or Max Ether
; use PP Up
;>         pp = move + MON_PP - MON_MOVES      # PP Up
	ld bc, MON_PP - MON_MOVES
	add hl, bc
;>         if mem[pp] >= 3 << 6:
	ld a, [hl] ; move PP
	cp 3 << 6 ; have 3 PP Ups already been used?
	jr c, .PPNotMaxedOut
;>             PrintText(PPMaxedOutText)
	ld hl, PPMaxedOutText
	call PrintText
;>             continue
	jr .chooseMove
.PPNotMaxedOut
;>         mem[pp] += 1 << 6
	ld a, [hl]
	add 1 << 6 ; increase PP Up count by 1
	ld [hl], a
;>         wUsingPPUp = 1
	ld a, 1 ; 1 PP Up used
	ld [wUsingPPUp], a
;>         RestoreBonusPP()
	call RestoreBonusPP ; add the bonus PP to current PP
;>         PrintText(PPIncreasedText)
	ld hl, PPIncreasedText
	call PrintText
;>@pu         result = 'used'
;>@pb         break
;>@e0 if result in ('ether', 'elixir'):
;>@e1     elixir = result == 'elixir'
;>@e2     if elixir:
;>@e3         wPPRestoreItem -= 2                 # ELIXER -> ETHER, MAX_ELIXER -> MAX_ETHER
;>@e4         wCurrentMenuItem = 0
;>@e5         wTileBehindCursor = 0               # counts the moves that got PP back
;>@e6     restored = False
;>@e7     for _ in range(NUM_MOVES if elixir else 1):
;>@e8         if elixir:
;>@e9             move = GetSelectedMoveOffset(addr(wPartyMon1Moves), PARTYMON_STRUCT_LENGTH)
;>@e10         if not elixir or mem[move]:         # (an empty slot is skipped)
;>@r1             wMonDataLocation = PLAYER_PARTY_DATA
;>@r2             GetMaxPP()
;>@r3             move = GetSelectedMoveOffset(addr(wPartyMon1Moves), PARTYMON_STRUCT_LENGTH)
;>@r4             pp = move + MON_PP - MON_MOVES
;>@r5             new = wMaxPP
;>@r6             if wPPRestoreItem == MAX_ETHER:
;>@r7                 changed = mem[pp] != new    # bug: the PP Up bits are compared too
;>             else:
;>@r8                 cur = mem[pp] & PP_MASK
;>@r9                 changed = cur != new
;>@r10                 new = min(cur + 10, new)
;>@r11             if changed:
;>@r12                 mem[pp] = ((mem[pp] & PP_UP_MASK) + new) & 0xFF
;>@r13                 restored = True
;>@r14                 if elixir:
;>@r15                     wTileBehindCursor += 1
;>@e11         if elixir:
;>@e12             wCurrentMenuItem += 1
;>@e13     if restored:
;>@e14         if wPlayerMonNumber == wWhichPokemon:     # in battle now: update the battle copy too
;>@e15             p = AddNTimes(addr(wPartyMon1PP), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
;>@e16             CopyData(p, addr(wBattleMonPP), NUM_MOVES)
;>@e17         PlaySound(SFX_HEAL_AILMENT)
;>@e18         PrintText(PPRestoredText)
;>@e19         result = 'used'
;>     else:
;>@e20         ItemUseNoEffect()
;>@e21         result = 'not used'
;> if result == 'used':
.done
;>     wWhichPokemon = which
	pop af
	ld [wWhichPokemon], a
;>     GBPalWhiteOut()
	call GBPalWhiteOut
;>     RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>     return RemoveUsedItem()
	jp RemoveUsedItem
.afterRestoringPP ; after using a (Max) Ether/Elixir
;=@e14
	ld a, [wWhichPokemon]
	ld b, a
	ld a, [wPlayerMonNumber]
	cp b ; is the pokemon whose PP was restored active in battle?
	jr nz, .skipUpdatingInBattleData
;=@e15
	ld hl, wPartyMon1PP
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;=@e16
	ld de, wBattleMonPP
	ld bc, NUM_MOVES
	call CopyData ; copy party data to in-battle data
.skipUpdatingInBattleData
;=@e17
	ld a, SFX_HEAL_AILMENT
	call PlaySound
;=@e18
	ld hl, PPRestoredText
	call PrintText
;=@e19
	jr .done
.useEther
;=@r1
	call .restorePP
;=@e13
	jr nz, .afterRestoringPP
;=@e20
	jp .noEffect
; unsets zero flag if PP was restored, sets zero flag if not
; however, this is bugged for Max Ethers and Max Elixirs (see below)
.restorePP
;=@r1
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;=@r2
	call GetMaxPP
;=@r3
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	call GetSelectedMoveOffset
;=@r4
	ld bc, MON_PP - MON_MOVES
	add hl, bc ; hl now points to move's PP
;=@r5
	ld a, [wMaxPP]
	ld b, a
;=@r6
	ld a, [wPPRestoreItem]
	cp MAX_ETHER
	jr z, .fullyRestorePP
;=@r8
	ld a, [hl] ; move PP
	and PP_MASK
;=@r9
	cp b ; does current PP equal max PP?
	ret z ; if so, return
;=@r10
	add 10 ; increase current PP by 10
; b holds the max PP amount and b will hold the new PP amount.
; So, if the new amount meets or exceeds the max amount,
; cap the amount to the max amount by leaving b unchanged.
; Otherwise, store the new amount in b.
	cp b ; does the new amount meet or exceed the maximum?
	jr nc, .storeNewAmount
	ld b, a
.storeNewAmount
;=@r12
	ld a, [hl] ; move PP
	and PP_UP_MASK
	add b
	ld [hl], a
	ret
.fullyRestorePP
;=@r7
	ld a, [hl] ; move PP
; Bug: This code doesn't mask out the upper two bits, which are used to count
; how many PP Ups have been used on the move.
; So, Max Ethers and Max Elixirs will not be detected as having no effect on
; a move with full PP if the move has had any PP Ups used on it.
	cp b ; does current PP equal max PP?
	ret z
	jr .storeNewAmount
.useElixir
; decrement the item ID so that ELIXER becomes ETHER and MAX_ELIXER becomes MAX_ETHER
;=@e3
	ld hl, wPPRestoreItem
	dec [hl]
	dec [hl]
;=@e4
	xor a
	ld hl, wCurrentMenuItem
	ld [hli], a
;=@e5
	ld [hl], a ; zero the counter for number of moves that had their PP restored
;=@e7
	ld b, 4
; loop through each move and restore PP
.elixirLoop
	push bc
;=@e9
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	call GetSelectedMoveOffset
;=@e10
	ld a, [hl]
	and a ; does the current slot have a move?
	jr z, .nextMove
;=@r1
	call .restorePP
;=@r11
	jr z, .nextMove
; if some PP was restored
;=@r15
	ld hl, wTileBehindCursor ; counter for number of moves that had their PP restored
	inc [hl]
.nextMove
;=@e12
	ld hl, wCurrentMenuItem
	inc [hl]
;=@e7
	pop bc
	dec b
	jr nz, .elixirLoop
;=@e13
	ld a, [wTileBehindCursor]
	and a ; did any moves have their PP restored?
	jp nz, .afterRestoringPP
.noEffect
;=@e20
	call ItemUseNoEffect
.itemNotUsed
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> # (which is dropped)
	pop af
;> wActionResultOrTookBattleTurn = 0           # not used
	xor a
	ld [wActionResultOrTookBattleTurn], a ; item use failed
;> return
	ret

