; for items that can't be used from the Item menu
;@ def UnusableItem()
;@ Items that do nothing when used from the bag.
;@ path: engine/items/item_effects
UnusableItem:
;> return ItemUseNotTime()
	jp ItemUseNotTime

;@ def ItemUseTMHM()
;@ Boot up a TM or HM, ask whether to teach its move, then pick a Pokémon that can learn it and does not know it
;@ yet. A TM is used up when the move was learned; an HM never is.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
ItemUseTMHM:
;> if wIsInBattle:
;>     return ItemUseNotTime()
	ld a, [wIsInBattle]
	and a
	jp nz, ItemUseNotTime
;> is_hm = wCurItem < TM01                     # HMs come before TMs in the item list
;> n = (wCurItem - TM01) & 0xFF
	ld a, [wCurItem]
	sub TM01 ; underflows below 0 for HM items (before TM items)
	push af
;> if is_hm:
	jr nc, .skipAdding
;>     n = (n + NUM_TMS + NUM_HMS) & 0xFF      # number HMs after the TMs
	add NUM_TMS + NUM_HMS ; adjust HM IDs to come after TM IDs
.skipAdding
;> wTempTMHM = (n + 1) & 0xFF
	inc a
	ld [wTempTMHM], a
	; get move ID from TM/HM ID
;> TMToMove()                                  # the machine number becomes its move
	ld a, (TMToMovePredef - PredefPointers) / 3
	call Predef
;> wMoveNum = wTempTMHM
	ld a, [wTempTMHM]
	ld [wMoveNum], a
;> CopyToStringBuffer(GetMoveName())
	call GetMoveName
	call CopyToStringBuffer
;> PrintText(BootedUpHMText if is_hm else BootedUpTMText)
	pop af
	ld hl, BootedUpTMText
	jr nc, .printBootedUpMachineText
	ld hl, BootedUpHMText
.printBootedUpMachineText
	call PrintText
;> PrintText(TeachMachineMoveText)
	ld hl, TeachMachineMoveText
	call PrintText
;> wTextBoxID = TWO_OPTION_MENU                # YES/NO at coord(14, 7)
;> DisplayTextBoxID()
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID ; yes/no menu
;> if wCurrentMenuItem:                        # NO
	ld a, [wCurrentMenuItem]
	and a
	jr z, .useMachine
;>     wActionResultOrTookBattleTurn = 2
	ld a, 2
	ld [wActionResultOrTookBattleTurn], a ; item not used
;>     return
	ret
.useMachine
;> which, item = wWhichPokemon, wCurItem
	ld a, [wWhichPokemon]
	push af
	ld a, [wCurItem]
	push af
;> while True:
.chooseMon
;>     CopyData(addr(wStringBuffer), addr(wTempMoveNameBuffer), MOVE_NAME_LENGTH)   # the party menu overwrites it
	ld hl, wStringBuffer
	ld de, wTempMoveNameBuffer
	ld bc, MOVE_NAME_LENGTH
	call CopyData ; save the move name because DisplayPartyMenu will overwrite it
;>     wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;>     wPartyMenuTypeOrMessageID = TMHM_PARTY_MENU
	ld a, TMHM_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;>     cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
	push af
;>     CopyData(addr(wTempMoveNameBuffer), addr(wStringBuffer), MOVE_NAME_LENGTH)
	ld hl, wTempMoveNameBuffer
	ld de, wStringBuffer
	ld bc, MOVE_NAME_LENGTH
	call CopyData
;>     if cancelled:
	pop af
	jr nc, .checkIfAbleToLearnMove
; if the player canceled teaching the move
;>         GBPalWhiteOutWithDelay3()
	pop af
	pop af
	call GBPalWhiteOutWithDelay3
;>         ClearSprites()
	call ClearSprites
;>         RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>         return LoadScreenTilesFromBuffer1()
	jp LoadScreenTilesFromBuffer1 ; restore saved screen
.checkIfAbleToLearnMove
	; check if the pokemon can learn the move
;>     can_learn = CanLearnTM()
	ld a, (CanLearnTMPredef - PredefPointers) / 3
	call Predef
;>     GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	push bc
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
	pop bc
;>     if not can_learn:
	ld a, c
	and a ; can the pokemon learn the move?
	jr nz, .checkIfAlreadyLearnedMove
; if the pokemon can't learn the move
;>         PlaySoundWaitForCurrent(SFX_DENIED)
	ld a, SFX_DENIED
	call PlaySoundWaitForCurrent
;>         PrintText(MonCannotLearnMachineMoveText)
	ld hl, MonCannotLearnMachineMoveText
	call PrintText
;>         continue
	jr .chooseMon
.checkIfAlreadyLearnedMove
	; check if the pokemon already knows the move
;>     if farcall(CheckIfMoveIsKnown):
;>         continue
	ld hl, CheckIfMoveIsKnown
	ld b, BANK(CheckIfMoveIsKnown)
	call Bankswitch
	jr c, .chooseMon
	; teach move
;>     learned = LearnMove()
;>     break
	ld a, (LearnMovePredef - PredefPointers) / 3
	call Predef
;> wCurItem = item
	pop af
	ld [wCurItem], a
;> wWhichPokemon = which
	pop af
	ld [wWhichPokemon], a
;> if not learned or IsItemHM(wCurItem):
;>     return
	ld a, b
	and a
	ret z
	ld a, [wCurItem]
	call IsItemHM
	ret c
;> return RemoveUsedItem()
	jp RemoveUsedItem

