; restores bonus PP (from PP Ups) when healing at a pokemon center
; also, when a PP Up is used, it increases the current PP by one PP Up bonus
; INPUT:
; [wWhichPokemon] = index of pokemon in party
; [wCurrentMenuItem] = index of move (when using a PP Up)
;@ def RestoreBonusPP()
;@ Add the bonus from PP Ups back onto the PP of party Pokémon wWhichPokemon's moves: all four moves, or with a
;@ PP Up being used (wUsingPPUp = 1) only the chosen move wCurrentMenuItem.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
RestoreBonusPP:
;> moves = AddNTimes(addr(wPartyMon1Moves), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;> LoadMovePPs()                              # the moves' normal max PP into wNormalMaxPPList
	push hl
	ld de, wNormalMaxPPList - 1
	; loads the normal max PP of each of the pokemon's moves to wNormalMaxPPList
	ld a, (LoadMovePPsPredef - PredefPointers) / 3
	call Predef
;> pp = moves + MON_PP - MON_MOVES
	pop hl
	ld c, MON_PP - MON_MOVES
	ld b, 0
	add hl, bc ; hl now points to move 1 PP
;> normal = addr(wNormalMaxPPList)
	ld de, wNormalMaxPPList
;> i = 0                                       # the move number, from 1
	ld b, 0 ; initialize move counter to zero
; loop through the pokemon's moves
.loop
;>@lp while True:
;>     i += 1
	inc b
;>     if i == NUM_MOVES + 1:
;>         return
	ld a, b
	cp 5 ; reached the end of the pokemon's moves?
	ret z ; if so, return
;>     use = True
;>     if wUsingPPUp == 1:
	ld a, [wUsingPPUp]
	dec a ; using a PP Up?
	jr nz, .skipMenuItemIDCheck
; if using a PP Up, check if this is the move it's being used on
;>         use = wCurrentMenuItem + 1 == i     # only the chosen move
	ld a, [wCurrentMenuItem]
	inc a
	cp b
	jr nz, .nextMove
.skipMenuItemIDCheck
;>     if use and mem[pp] & PP_UP_MASK:
;>         AddBonusPP(normal, pp)
	ld a, [hl]
	and PP_UP_MASK
	call nz, AddBonusPP ; if so, add bonus PP
.nextMove
;>     pp += 1
;>     normal += 1
	inc hl
	inc de
;=@lp
	jr .loop

; adds bonus PP from PP Ups to current PP
; 1/5 of normal max PP (capped at 7) is added for each PP Up
; INPUT:
; [de] = normal max PP
; [hl] = move PP
;@ def AddBonusPP(max_pp: de, pp: hl)
;@ Add the PP Up bonus to the PP byte at pp: a fifth of the move's normal max PP (at most 7) for each PP Up in
;@ the top two bits, or once only while a PP Up is being used (wUsingPPUp = 1).
;@ test: max_pp = rand(0xC000, 0xDE00); pp = rand(0xC000, 0xDE00); hLoadedROMBank = 3    # the bank this code runs in
;@ path: engine/items/item_effects
AddBonusPP:
;> mem[addr(hDividend) + 3] = mem[max_pp]
	push bc
	ld a, [de] ; normal max PP of move
	ldh [hDividend + 3], a
;> mem[addr(hDividend)] = 0
	xor a
	ldh [hDividend], a
;> mem[addr(hDividend) + 1] = 0
	ldh [hDividend + 1], a
;> mem[addr(hDividend) + 2] = 0
	ldh [hDividend + 2], a
;> mem[addr(hDivisor)] = 5
	ld a, 5
	ldh [hDivisor], a
;> Divide(4)
	ld b, 4
	call Divide
;> b = mem[pp]
	ld a, [hl] ; move PP
	ld b, a
;> ups = b >> 6
	swap a
	and %00001111
	srl a
	srl a
	ld c, a ; c = number of PP Ups used
;> for _ in range(ups or 256):                 # (with no PP Ups the count wraps round to 256)
.loop
;>     b = (b + min(mem[addr(hQuotient) + 3], 7)) & 0xFF
	ldh a, [hQuotient + 3]
	cp 8 ; is the amount greater than or equal to 8?
	jr c, .addAmount
	ld a, 7 ; cap the amount at 7
.addAmount
	add b
	ld b, a
;>     if wUsingPPUp == 1:
;>         break
	ld a, [wUsingPPUp]
	dec a ; is the player using a PP Up right now?
	jr z, .done ; if so, only add the bonus once
	dec c
	jr nz, .loop
.done
;> mem[pp] = b
	ld [hl], b
	pop bc
	ret

; gets max PP of a pokemon's move (including PP from PP Ups)
; INPUT:
; [wWhichPokemon] = index of pokemon within party/box
; [wMonDataLocation] = pokemon source
; 00: player's party
; 01: enemy's party
; 02: current box
; 03: daycare
; 04: player's in-battle pokemon
; [wCurrentMenuItem] = move index
; OUTPUT:
; [wMaxPP] = max PP
;@ def GetMaxPP()
;@ wMaxPP = the max PP, PP Ups included, of move wCurrentMenuItem of Pokémon wWhichPokemon in the place
;@ wMonDataLocation names (0 party, 1 enemy party, 2 current box, 3 day care, 4 the player's Pokémon in battle).
;@ test: wMonDataLocation = rand(0, 4); wWhichPokemon = rand(0, 5); wCurrentMenuItem = rand(0, 3); hLoadedROMBank = 3
;@ path: engine/items/item_effects
GetMaxPP:
;> src = wMonDataLocation
	ld a, [wMonDataLocation]
	and a
;> moves = addr(wPartyMon1Moves)
	ld hl, wPartyMon1Moves
;> size = PARTYMON_STRUCT_LENGTH
	ld bc, PARTYMON_STRUCT_LENGTH
;> if src != 0:
	jr z, .sourceWithMultipleMon
;>     moves = addr(wEnemyMon1Moves)
	ld hl, wEnemyMon1Moves
;>     if src != 1:
	dec a
	jr z, .sourceWithMultipleMon
;>         moves = addr(wBoxMon1Moves)
	ld hl, wBoxMon1Moves
;>         size = BOXMON_STRUCT_LENGTH
	ld bc, BOXMON_STRUCT_LENGTH
;>         if src != 2:                        # a place with just one Pokémon
	dec a
	jr z, .sourceWithMultipleMon
;>             moves = addr(wDayCareMonMoves)
	ld hl, wDayCareMonMoves
;>             if src != 3:
	dec a
	jr z, .sourceWithOneMon
;>                 moves = addr(wBattleMonMoves)
	ld hl, wBattleMonMoves ; player's in-battle pokemon
.sourceWithOneMon
;>             move = GetSelectedMoveOffset2(moves)
	call GetSelectedMoveOffset2
	jr .next
.sourceWithMultipleMon
;> if src < 3:
;>     move = GetSelectedMoveOffset(moves, size)
	call GetSelectedMoveOffset
.next
;> i = (mem[move] - 1) & 0xFF                  # (move is kept)
	ld a, [hl]
	dec a
	push hl
;> entry = AddNTimes(Moves, MOVE_LENGTH, i)
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;> FarCopyData(BANK(Moves), entry, addr(wMoveData), MOVE_LENGTH)
	ld de, wMoveData
	ld a, BANK(Moves)
	call FarCopyData
;> normal = mem[addr(wMoveData) + MOVE_PP]
	ld de, wMoveData + MOVE_PP
	ld a, [de]
	ld b, a ; b = normal max PP
;> # (move comes back; normal is kept)
	pop hl
	push bc
;> offset = MON_PP - MON_MOVES
	ld bc, MON_PP - MON_MOVES ; PP offset if not player's in-battle pokemon data
;> if wMonDataLocation == 4:                   # the player's Pokémon in battle
	ld a, [wMonDataLocation]
	cp 4 ; player's in-battle pokemon?
	jr nz, .addPPOffset
;>     offset = addr(wBattleMonPP) - addr(wBattleMonMoves)
	ld bc, wBattleMonPP - wBattleMonMoves ; PP offset if player's in-battle pokemon data
.addPPOffset
;> pp = move + offset
	add hl, bc
;> value = (mem[pp] & PP_UP_MASK) | normal
	ld a, [hl] ; a = current PP
	and PP_UP_MASK
	pop bc
	or b ; place normal max PP in 6 lower bits of a
	ASSERT wMoveData + MOVE_PP + 1 == wPPUpCountAndMaxPP
;> mem[addr(wPPUpCountAndMaxPP)] = value
	ld h, d
	ld l, e
	inc hl ; hl = wPPUpCountAndMaxPP
	ld [hl], a
;> wUsingPPUp = 0
	xor a ; add the bonus for the existing PP Up count
	ld [wUsingPPUp], a
;> AddBonusPP(addr(wMoveData) + MOVE_PP, addr(wPPUpCountAndMaxPP))
	call AddBonusPP ; add bonus PP from PP Ups
;> wMaxPP = mem[addr(wPPUpCountAndMaxPP)] & PP_MASK
	ld a, [hl]
	and PP_MASK
	ld [wMaxPP], a ; store max PP
;> return
	ret

;@ def GetSelectedMoveOffset(moves: hl, step: bc) -> hl
;@ The address of move wCurrentMenuItem of Pokémon wWhichPokemon in a list of step-byte Pokémon structs.
;@ path: engine/items/item_effects
GetSelectedMoveOffset:
;> return GetSelectedMoveOffset2(AddNTimes(moves, step, wWhichPokemon))
	ld a, [wWhichPokemon]
	call AddNTimes

;@ def GetSelectedMoveOffset2(moves: hl) -> hl
;@ The address of move wCurrentMenuItem in a Pokémon's move list.
;@ path: engine/items/item_effects
GetSelectedMoveOffset2:
;> return (moves + wCurrentMenuItem) & 0xFFFF
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, 0
	add hl, bc
	ret

; confirms the item toss and then tosses the item
; INPUT:
; hl = address of inventory (either wNumBagItems or wNumBoxItems)
; [wCurItem] = item ID
; [wWhichPokemon] = index of item within inventory
; [wItemQuantity] = quantity to toss
; OUTPUT:
; clears carry flag if the item is tossed, sets carry flag if not
;@ def TossItem_(inventory: hl) -> carry
;@ Toss item wCurItem (slot wWhichPokemon, wItemQuantity of it) after a yes/no question. HMs and key items are
;@ too important to toss. Carry if nothing was tossed.
;@ path: engine/items/item_effects
TossItem_::
;> # (inventory is kept)
	push hl
;> hm = IsItemHM(wCurItem)
	ld a, [wCurItem]
	call IsItemHM
	pop hl
;> if not hm:
	jr c, .tooImportantToToss
;>     # (inventory is kept)
	push hl
;>     IsKeyItem_()
	call IsKeyItem_
;>     key = wIsKeyItem
	ld a, [wIsKeyItem]
	pop hl
;> if hm or key:
;>@ti1     PrintText(TooImportantToTossText)
;>@ti2     return True
	and a
	jr nz, .tooImportantToToss
;> # (inventory is kept)
	push hl
;> wNamedObjectIndex = wCurItem
	ld a, [wCurItem]
	ld [wNamedObjectIndex], a
;> CopyToStringBuffer(GetItemName())
	call GetItemName
	call CopyToStringBuffer
;> PrintText(IsItOKToTossItemText)
	ld hl, IsItOKToTossItemText
	call PrintText
;> wTextBoxID = TWO_OPTION_MENU                # a YES/NO menu at coord(14, 7)
;> DisplayTextBoxID()
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID ; yes/no menu
;> if wMenuExitMethod == CHOSE_SECOND_ITEM:    # NO
;>     return True
	ld a, [wMenuExitMethod]
	cp CHOSE_SECOND_ITEM
	pop hl
	scf
	ret z ; return if the player chose No
; if the player chose Yes
;> RemoveItemFromInventory(inventory)
	push hl
	ld a, [wWhichPokemon]
	call RemoveItemFromInventory
;> wNamedObjectIndex = wCurItem
	ld a, [wCurItem]
	ld [wNamedObjectIndex], a
;> CopyToStringBuffer(GetItemName())
	call GetItemName
	call CopyToStringBuffer
;> PrintText(ThrewAwayItemText)
	ld hl, ThrewAwayItemText
	call PrintText
;> return False
	pop hl
	and a
	ret
.tooImportantToToss
;=@ti1
	push hl
	ld hl, TooImportantToTossText
	call PrintText
	pop hl
;=@ti2
	scf
	ret

;@ path: engine/items/item_effects
ThrewAwayItemText:
	db TX_FAR
	dw _ThrewAwayItemText
	db BANK(_ThrewAwayItemText)
	db TX_END

;@ path: engine/items/item_effects
IsItOKToTossItemText:
	db TX_FAR
	dw _IsItOKToTossItemText
	db BANK(_IsItOKToTossItemText)
	db TX_END

;@ path: engine/items/item_effects
TooImportantToTossText:
	db TX_FAR
	dw _TooImportantToTossText
	db BANK(_TooImportantToTossText)
	db TX_END

; checks if an item is a key item
; INPUT:
; [wCurItem] = item ID
; OUTPUT:
; [wIsKeyItem] = result
; 00: item is not key item
; 01: item is key item
;@ def IsKeyItem_()
;@ wIsKeyItem = 1 if item wCurItem is a key item (its bit in KeyItemFlags) or an HM, else 0. TMs are not.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
IsKeyItem_::
;> wIsKeyItem = 1
	ld a, $01
	ld [wIsKeyItem], a
;> if wCurItem < HM01:
	ld a, [wCurItem]
	cp HM01 ; is the item an HM or TM?
	jr nc, .checkIfItemIsHM
; if the item is not an HM or TM
;>     CopyData(KeyItemFlags, addr(wBuffer), 15)
	push af
	ld hl, KeyItemFlags
	ld de, wBuffer
	ld bc, 15 ; only 11 bytes are actually used
	ASSERT 15 >= (NUM_ITEMS + 7) / 8
	call CopyData
;>     bit = wCurItem - 1
	pop af
	dec a
	ld c, a
;>     isset = FlagAction(addr(wBuffer), bit, FLAG_TEST)
	ld hl, wBuffer
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;>     if isset:                               # a key item
;>         return
	ld a, c
	and a
	ret nz
.checkIfItemIsHM
;> if not IsItemHM(wCurItem):
	ld a, [wCurItem]
	call IsItemHM
	ret c
;>     wIsKeyItem = 0
	xor a
	ld [wIsKeyItem], a
	ret

;@ path: engine/items/item_effects
KeyItemFlags:
	DEF CURRENT_BIT_ARRAY_START EQUS #.
	; MASTER_BALL
	; ULTRA_BALL
