	; MOON_STONE
	; ANTIDOTE
	; BURN_HEAL
	; ICE_HEAL
	; AWAKENING
	; PARLYZ_HEAL
	; FULL_RESTORE
	db $1
	; MAX_POTION
	; HYPER_POTION
	; SUPER_POTION
	; POTION
	; BOULDERBADGE
	; CASCADEBADGE
	; THUNDERBADGE
	; RAINBOWBADGE
	db $F0
	; SOULBADGE
	; MARSHBADGE
	; VOLCANOBADGE
	; EARTHBADGE
	; ESCAPE_ROPE
	; REPEL
	; OLD_AMBER
	; FIRE_STONE
	db $4F
	; THUNDER_STONE
	; WATER_STONE
	; HP_UP
	; PROTEIN
	; IRON
	; CARBOS
	; CALCIUM
	; RARE_CANDY
	db $0
	; DOME_FOSSIL
	; HELIX_FOSSIL
	; SECRET_KEY
	; ITEM_2C
	; BIKE_VOUCHER
	; X_ACCURACY
	; LEAF_STONE
	; CARD_KEY
	db $9F
	; NUGGET
	; ITEM_32
	; POKE_DOLL
	; FULL_HEAL
	; REVIVE
	; MAX_REVIVE
	; GUARD_SPEC
	; SUPER_REPEL
	db $0
	; MAX_REPEL
	; DIRE_HIT
	; COIN
	; FRESH_WATER
	; SODA_POP
	; LEMONADE
	; S_S_TICKET
