; store the new mon in the first slot, shifting all existing box data down
;@ def SendNewMonToBox()
;@ Put the Pokémon just caught (wEnemyMon, species wCurPartySpecies) at the front of the current PC box: every
;@ list in the box moves down one slot, the player becomes its original trainer, and the player names it.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/item_effects
SendNewMonToBox:
;> p = addr(wBoxCount)
	ld de, wBoxCount
;> mem[p] += 1
	ld a, [de]
	inc a
	ld [de], a

;> wCurSpecies = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wCurSpecies], a
;> species = wCurPartySpecies
	ld c, a
;>@sl while True:                              # the species list moves down, up to its $FF end
.shiftSpeciesLoop
;>     p += 1
	inc de
;>     old = mem[p]
	ld a, [de]
	ld b, a
;>     put = species
;>     species = old
	ld a, c
	ld c, b
;>     mem[p] = put
	ld [de], a
;>     if put == 0xFF:
;>         break
	cp -1
	jr nz, .shiftSpeciesLoop

;> GetMonHeader()
	call GetMonHeader
;> n = wBoxCount - 1                           # the Pokémon already in the box
	ld hl, wBoxMonOT
	ld bc, NAME_LENGTH
	ld a, [wBoxCount]
	dec a
;> if n:                                       # each list moves down one place, from its end
	jr z, .skipOTshift ; if the box was empty, there is nothing to shift

;>     src = AddNTimes(addr(wBoxMonOT), NAME_LENGTH, n - 1)
	dec a
	call AddNTimes
;>     dest = src + NAME_LENGTH
	push hl
	ld bc, NAME_LENGTH
	add hl, bc
	ld d, h
	ld e, l
	pop hl
;>@ol     for _ in range(n):
	ld a, [wBoxCount]
	dec a
	ld b, a
.shiftMonOTLoop
;>         # (the count and src are kept)
	push bc
	push hl
;>         CopyData(src, dest, NAME_LENGTH)
	ld bc, NAME_LENGTH
	call CopyData
;>         dest = src
	pop hl
	ld d, h
	ld e, l
;>         src -= NAME_LENGTH
	ld bc, -NAME_LENGTH
	add hl, bc
	pop bc
;=@ol
	dec b
	jr nz, .shiftMonOTLoop

.skipOTshift
;> CopyData(addr(wPlayerName), addr(wBoxMon1OT), NAME_LENGTH)
	ld hl, wPlayerName
	ld de, wBoxMon1OT
	ld bc, NAME_LENGTH
	call CopyData

;> if n:
	ld a, [wBoxCount]
	dec a
	jr z, .skipNickShift

;>     src = AddNTimes(addr(wBoxMonNicks), NAME_LENGTH, n - 1)
	ld hl, wBoxMonNicks
	ld bc, NAME_LENGTH
	dec a
	call AddNTimes
;>     dest = src + NAME_LENGTH
	push hl
	ld bc, NAME_LENGTH
	add hl, bc
	ld d, h
	ld e, l
	pop hl
;>@nl     for _ in range(n):
	ld a, [wBoxCount]
	dec a
	ld b, a
.shiftNickLoop
;>         # (the count and src are kept)
	push bc
	push hl
;>         CopyData(src, dest, NAME_LENGTH)
	ld bc, NAME_LENGTH
	call CopyData
;>         dest = src
	pop hl
	ld d, h
	ld e, l
;>         src -= NAME_LENGTH
	ld bc, -NAME_LENGTH
	add hl, bc
	pop bc
;=@nl
	dec b
	jr nz, .shiftNickLoop

.skipNickShift
;> name = addr(wBoxMon1Nick)
	ld hl, wBoxMon1Nick
;> wNamingScreenType = NAME_MON_SCREEN
	ld a, NAME_MON_SCREEN
	ld [wNamingScreenType], a
;> AskName(name)
	ld a, (AskNamePredef - PredefPointers) / 3
	call Predef

;> if n:
	ld a, [wBoxCount]
	dec a
	jr z, .skipMonDataShift

;>     src = AddNTimes(addr(wBoxMons), BOXMON_STRUCT_LENGTH, n - 1)
	ld hl, wBoxMons
	ld bc, BOXMON_STRUCT_LENGTH
	dec a
	call AddNTimes
;>     dest = src + BOXMON_STRUCT_LENGTH
	push hl
	ld bc, BOXMON_STRUCT_LENGTH
	add hl, bc
	ld d, h
	ld e, l
	pop hl
;>@dl     for _ in range(n):
	ld a, [wBoxCount]
	dec a
	ld b, a
.shiftMonDataLoop
;>         # (the count and src are kept)
	push bc
	push hl
;>         CopyData(src, dest, BOXMON_STRUCT_LENGTH)
	ld bc, BOXMON_STRUCT_LENGTH
	call CopyData
;>         dest = src
	pop hl
	ld d, h
	ld e, l
;>         src -= BOXMON_STRUCT_LENGTH
	ld bc, -BOXMON_STRUCT_LENGTH
	add hl, bc
	pop bc
;=@dl
	dec b
	jr nz, .shiftMonDataLoop

.skipMonDataShift
;> wEnemyMonBoxLevel = wEnemyMonLevel
	ld a, [wEnemyMonLevel]
	ld [wEnemyMonBoxLevel], a
;> CopyData(addr(wEnemyMon), addr(wBoxMon1), addr(wEnemyMonDVs) - addr(wEnemyMon))    # species, HP, level, status, types, catch rate, moves
;> d = addr(wBoxMon1) + addr(wEnemyMonDVs) - addr(wEnemyMon)                         # just after them
	ld hl, wEnemyMon
	ld de, wBoxMon1
	ld bc, wEnemyMonDVs - wEnemyMon
	call CopyData
;> mem[d] = mem[addr(wPlayerID)]               # the player's trainer ID
	ld hl, wPlayerID
	ld a, [hli]
	ld [de], a
;> mem[d + 1] = mem[addr(wPlayerID) + 1]
	inc de
	ld a, [hl]
	ld [de], a
;> d += 2
	inc de
;> # (d is kept)
	push de
;> farcall(CalcExperience, wCurEnemyLevel)    # experience for its level (3 bytes)
	ld a, [wCurEnemyLevel]
	ld d, a
	ld hl, CalcExperience
	ld b, BANK(CalcExperience)
	call Bankswitch
;> # (d comes back)
	pop de
;> mem[d] = mem[addr(hExperience)]
	ldh a, [hExperience]
	ld [de], a
;> mem[d + 1] = mem[addr(hExperience) + 1]
	inc de
	ldh a, [hExperience + 1]
	ld [de], a
;> mem[d + 2] = mem[addr(hExperience) + 2]
	inc de
	ldh a, [hExperience + 2]
	ld [de], a
;> d += 3
	inc de
;>@sx for _ in range(NUM_STATS * 2):          # no stat experience yet
	xor a
	ld b, NUM_STATS * 2
.statLoop
;>     mem[d] = 0
;>     d += 1
	ld [de], a
	inc de
;=@sx
	dec b
	jr nz, .statLoop

;> mem[d] = mem[addr(wEnemyMonDVs)]
	ld hl, wEnemyMonDVs
	ld a, [hli]
	ld [de], a
;> mem[d + 1] = mem[addr(wEnemyMonDVs) + 1]
	inc de
	ld a, [hli]
	ld [de], a
;> src = addr(wEnemyMonPP)
	ld hl, wEnemyMonPP
;>@pl for _ in range(NUM_MOVES):
	ld b, NUM_MOVES
.movePPLoop
;>     pp = mem[src]
;>     src += 1
	ld a, [hli]
;>     d += 1
	inc de
;>     mem[d] = pp
	ld [de], a
;=@pl
	dec b
	jr nz, .movePPLoop
;> return
	ret

; checks if the tile in front of the player is a shore or water tile
; used for surfing and fishing
; unsets carry if it is, sets carry if not
;@ def IsNextTileShoreOrWater() -> carry
;@ Whether the player faces water or a shore tile, in a tileset that has water. Carry if NOT (the Vermilion dock
;@ tileset has no shore tiles).
;@ path: engine/items/item_effects
IsNextTileShoreOrWater:
;> _, _, found = IsInArray(wCurMapTileset, WaterTilesets, 1)
	ld a, [wCurMapTileset]
	ld hl, WaterTilesets
	ld de, 1
	call IsInArray
;> if not found:
;>     return True
	jr nc, .notShoreOrWater
;> dock = wCurMapTileset == SHIP_PORT
	ld a, [wCurMapTileset]
	cp SHIP_PORT ; Vermilion Dock tileset
;> tile = wTileInFrontOfPlayer
	ld a, [wTileInFrontOfPlayer] ; tile in front of player
;> if not dock:                                # (the dock has no shore tiles)
	jr z, .skipShoreTiles ; if it's the Vermilion Dock tileset
;>     if tile in (0x48, 0x32):                # the Safari Zone's eastern shore, the usual one
;>         return False
	cp $48 ; eastern shore tile in Safari Zone
	jr z, .shoreOrWater
	cp $32 ; usual eastern shore tile
	jr z, .shoreOrWater
.skipShoreTiles
;> if tile == 0x14:                            # water
;>@sw     return False
	cp $14 ; water tile
	jr z, .shoreOrWater
.notShoreOrWater
;> return True
	scf
	ret
.shoreOrWater
;=@sw
	and a
	ret

; tilesets with water
;@ path: engine/items/item_effects
WaterTilesets:
	db OVERWORLD
	db FOREST
	db DOJO
	db GYM
	db SHIP
	db SHIP_PORT
	db CAVERN
	db FACILITY
	db PLATEAU
	db -1 ; end

;@ def ReadSuperRodData() -> (e, b, c)
;@ Fish for the Super Rod on map wCurMap: e = 2 if the map has no fish, 0 half the time (nothing bites), else
;@ e = 1 with b = level and c = species picked from the map's group.
;@ test: hLoadedROMBank = 3    # the bank this code runs in (Random switches back to it)
;@ path: engine/items/item_effects
ReadSuperRodData:
; return e = 2 if no fish on this map
; return e = 1 if a bite, bc = level,species
; return e = 0 if no bite
;> b, p, found = IsInArray(wCurMap, SuperRodData, 3)
	ld a, [wCurMap]
	ld de, 3 ; each fishing group is three bytes wide
	ld hl, SuperRodData
	call IsInArray
;> if not found:
;>     return 2, b, wCurMap                     # (c still holds the map)
	jr c, .ReadFishingGroup
	ld e, $2 ; $2 if no fishing groups found
	ret

.ReadFishingGroup
; hl points to the fishing group entry in the index
;> p = mem16[p + 1]                            # the map's fishing group
	inc hl ; skip map id

	; read fishing group address
	ld a, [hli]
	ld h, [hl]
	ld l, a

;> b = mem[p]                                  # how many kinds of fish
	ld b, [hl] ; how many mons in group
	inc hl ; point to data
;> carry = True
	ld e, $0 ; no bite yet

;> while True:
.RandomLoop
;>     r = Random(carry)
	call Random
;>     if r & 1:
;>         return 0, b, wCurMap
	srl a
	ret c ; 50% chance of no battle

;>     r = (r >> 1) & 3
	and %11 ; 2-bit random number
;>     if r < b:
;>         break
;>@cf     carry = False
	cp b
	jr nc, .RandomLoop ; if a is greater than the number of mons, regenerate

	; get the mon
;> q = p + 1 + 2 * r                           # its level and species
	add a
	ld c, a
	ld b, $0
	add hl, bc
;> return 1, mem[q], mem[q + 1]
	ld b, [hl] ; level
	inc hl
	ld c, [hl] ; species
	ld e, $1 ; $1 if there's a bite
	ret

