; reloads map view and processes sprite data
; for items that cause the overworld to be displayed
;@ def ItemUseReloadOverworldData()
;@ Redraw the map and the sprites (after a menu covered them).
;@ path: engine/items/item_effects
ItemUseReloadOverworldData:
;> LoadCurrentMapView()
;> return UpdateSprites()
	call LoadCurrentMapView
	jp UpdateSprites

; creates a list at wBuffer of maps where the mon in [wPokedexNum] can be found.
; this is used by the pokedex to display locations the mon can be found on the map.
;@ def FindWildLocationsOfMon()
;@ For the Pokédex area map: list in wBuffer the maps (by index in WildDataPointers) where species wPokedexNum
;@ appears in the grass or the water, ending with $FF.
;@ path: engine/items/item_effects
FindWildLocationsOfMon:
;> p = WildDataPointers
	ld hl, WildDataPointers
;> out = addr(wBuffer)
	ld de, wBuffer
;> index = 0
	ld c, $0
;> while mem[p + 1] != 0xFF:                   # the pointer list ends with $FFFF
.loop
	inc hl
	ld a, [hld]
	inc a
	jr z, .done
;>     data = mem16[p]
	push hl
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     rate = mem[data]                        # the grass: a rate byte, then the slots
;>     data += 1
	ld a, [hli]
;>     if rate:
;>         data, out = CheckMapForMon(data, out, index)
	and a
	call nz, CheckMapForMon ; land
;>     rate = mem[data]                        # then the water
;>     data += 1
	ld a, [hli]
;>     if rate:
;>         data, out = CheckMapForMon(data, out, index)
	and a
	call nz, CheckMapForMon ; water
;>     p += 2
	pop hl
	inc hl
	inc hl
;>     index = (index + 1) & 0xFF
	inc c
	jr .loop
.done
;> mem[out] = 0xFF
	ld a, $ff ; list terminator
	ld [de], a
	ret

;@ def CheckMapForMon(slots: hl, out: de, index: c) -> (hl, de)
;@ Append index to the list at out once for each of the NUM_WILDMONS (level, species) slots holding species
;@ wPokedexNum. Returns the address after the slots and the new end of the list.
;@ test: out = rand(0xC000, 0xDE00)
;@ path: engine/items/item_effects
CheckMapForMon:
;> p = slots + 1
	inc hl
;> for _ in range(NUM_WILDMONS):
	ld b, NUM_WILDMONS
.loop
;>     if mem[p] == wPokedexNum:
	ld a, [wPokedexNum]
	cp [hl]
	jr nz, .nextEntry
;>         mem[out] = index
	ld a, c
	ld [de], a
;>         out += 1
	inc de
.nextEntry
;>     p += 2
	inc hl
	inc hl
	dec b
	jr nz, .loop
;> return (p - 1) & 0xFFFF, out & 0xFFFF
	dec hl
	ret
;@ def DrawBadges()
;@ The badge area of the trainer card: eight numbered gym leader faces in two rows, each face swapped for its
;@ badge once the player owns it, and a name plate under the faces not won yet (the plates are blank tiles).
;@ path: engine/menus/draw_badges
DrawBadges:
; Draw 4x2 gym leader faces, with the faces replaced by
; badges if they are owned. Used in the player status screen.

; In Japanese versions, names are displayed above faces.
; Instead of removing relevant code, the name graphics were erased.

; Tile ids for face/badge graphics.
;> faces = addr(wBadgeOrFaceTiles)
;> CopyData(label('DrawBadges.FaceBadgeTiles'), faces, NUM_BADGES)   # the leaders' face tiles $20, $28, ... $58
	ld de, wBadgeOrFaceTiles
	ld hl, .FaceBadgeTiles
	ld bc, NUM_BADGES
	call CopyData

; Booleans for each badge.
;> owned = addr(wTempObtainedBadgesBooleans)
;> FillMemory(owned, NUM_BADGES, 0)
	ld hl, wTempObtainedBadgesBooleans
	ld bc, NUM_BADGES
	xor a
	call FillMemory

; Alter these based on owned badges.
;>@chk for i in range(NUM_BADGES):
	ld de, wTempObtainedBadgesBooleans
	ld hl, wBadgeOrFaceTiles
	ld a, [wObtainedBadges]
	ld b, a
	ld c, NUM_BADGES
.CheckBadge
;>     if wObtainedBadges >> i & 1:
	srl b
	jr nc, .NextBadge
;>         mem[faces + i] += 4                 # the badge tiles follow each face
	ld a, [hl]
	add 4 ; Badge graphics are after each face
	ld [hl], a
;>         mem[owned + i] = 1
	ld a, 1
	ld [de], a
.NextBadge
;=@chk
	inc hl
	inc de
	dec c
	jr nz, .CheckBadge

; Draw two rows of badges.
;> mem[addr(wBadgeNumberTile)] = 0xD8          # "1"
	ld hl, wBadgeNumberTile
	ld a, $d8 ; [1]
	ld [hli], a
;> mem[addr(wBadgeNameTile)] = 0x60
	ld [hl], $60 ; First name

;> for row in range(2):
	ld hl, (11) * SCREEN_WIDTH + (2) + wTileMap
	ld de, wTempObtainedBadgesBooleans
	call .DrawBadgeRow

	ld hl, (14) * SCREEN_WIDTH + (2) + wTileMap
	ld de, wTempObtainedBadgesBooleans + 4
	; fallthrough

.DrawBadgeRow
; Draw 4 badges.

;>@k     for k in range(4):
	ld c, 4
.DrawBadge
;>         p = coord(2, 11 + 3 * row) + 4 * k
	push de
	push hl

; Badge no.
;>         mem[p] = mem[addr(wBadgeNumberTile)]
	ld a, [wBadgeNumberTile]
	ld [hli], a
;>         mem[addr(wBadgeNumberTile)] += 1
	inc a
	ld [wBadgeNumberTile], a

; Names aren't printed if the badge is owned.
;>         name = mem[addr(wBadgeNameTile)]
;>         if not mem[owned + 4 * row + k]:
	ld a, [de]
	and a
	ld a, [wBadgeNameTile]
	jr nz, .SkipName
;>             mem[p + 1] = name
;>             mem[p + 2] = name + 1
	call .PlaceTiles
	jr .PlaceBadge

.SkipName
	inc a
	inc a
	inc hl

.PlaceBadge
;>         mem[addr(wBadgeNameTile)] = name + 2
	ld [wBadgeNameTile], a
;>         t = mem[faces]                      # a 2x2 face or badge
	ld de, SCREEN_WIDTH - 1
	add hl, de
	ld a, [wBadgeOrFaceTiles]
;>         mem[p + SCREEN_WIDTH + 1] = t
;>         mem[p + SCREEN_WIDTH + 2] = t + 1
	call .PlaceTiles
;>         mem[p + 2 * SCREEN_WIDTH + 1] = t + 2
;>         mem[p + 2 * SCREEN_WIDTH + 2] = t + 3
	add hl, de
	call .PlaceTiles

; Shift badge array back one byte.
;>         CopyData(faces + 1, faces, NUM_BADGES)  # the next badge moves to the front
	push bc
	ld hl, wBadgeOrFaceTiles + 1
	ld de, wBadgeOrFaceTiles
	ld bc, NUM_BADGES
	call CopyData
	pop bc

;=@k
	pop hl
	ld de, 4
	add hl, de

	pop de
	inc de
;=@k
	dec c
	jr nz, .DrawBadge
	ret

.PlaceTiles
;> # .PlaceTiles, used above: tiles a and a + 1 side by side
	ld [hli], a
	inc a
	ld [hl], a
	inc a
	ret

.FaceBadgeTiles
	db $20, $28, $30, $38, $40, $48, $50, $58

