; replaces a tile block with the one specified in [wNewTileBlockID]
; and redraws the map view if necessary
; b = Y
; c = X
;@ path: engine/overworld/update_map
;@ def ReplaceTileBlock()
;@ Put block wNewTileBlockID at block (x, y) = (c, b) of the predef registers into the map (its rows have a
;@ 3-block border on each side). If that block is inside the visible part, the screen is redrawn.
;@ test: wIsInBattle = 0xFF; mem[0xCC53] = rand(0, 8); mem[0xCC54] = rand(0, 8); wCurMapWidth = rand(1, 20)
ReplaceTileBlock:
;> _, _, bc = GetPredefRegisters()
	call GetPredefRegisters
;> y, x = bc >> 8, bc & 0xFF
;> width = u8(wCurMapWidth + 6)                    # with the border on both sides
	ld hl, wOverworldMap
	ld a, [wCurMapWidth]
	add $6
	ld e, a
	ld d, $0
;> p = addr(wOverworldMap) + 3 * width + 3          # block (0, 0), inside the border
	add hl, de
	add hl, de
	add hl, de
	ld e, $3
	add hl, de
	ld e, a
;> p += y * width
	ld a, b
	and a
	jr z, .addX
; add width * Y
.addWidthYTimesLoop
	add hl, de
	dec b
	jr nz, .addWidthYTimesLoop
.addX
;> p += x
	add hl, bc ; add X
;> mem[p] = wNewTileBlockID
	ld a, [wNewTileBlockID]
	ld [hl], a
;> view = mem16[addr(wCurrentTileBlockMapViewPointer)]
	ld a, [wCurrentTileBlockMapViewPointer]
	ld c, a
	ld a, [wCurrentTileBlockMapViewPointer + 1]
	ld b, a
;> if p < view:                                     # above the visible part
;>     return
	call CompareHLWithBC
	ret c ; return if the replaced tile block is below the map view in memory
;>@last last = view + 4 * width + 6                      # the last block of the visible part
	push hl
	ld l, e
	ld h, $0
	ld e, $6
	ld d, h
;=@last
	add hl, hl
	add hl, hl
	add hl, de
	add hl, bc
	pop bc
;> if last < p:                                     # below it
;>     return
	call CompareHLWithBC
	ret c ; return if the replaced tile block is above the map view in memory
;> RedrawMapView()

;@ path: engine/overworld/update_map
;@ def RedrawMapView()
;@ Rebuild the screen from the map (not in a lost battle): reload the map view, then send the visible rows of
;@ blocks to the background map, one row of 2x2 tiles per frame, with tile animation and automatic transfer
;@ paused.
;@ test: skip redraws the screen one row per frame
RedrawMapView:
;> if wIsInBattle == 0xFF:
;>     return
	ld a, [wIsInBattle]
	inc a
	ret z
;> savedTransfer, savedAnimations = hAutoBGTransferEnabled, hTileAnimations
	ldh a, [hAutoBGTransferEnabled]
	push af
	ldh a, [hTileAnimations]
	push af
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> hTileAnimations = 0
	ldh [hTileAnimations], a
;> LoadCurrentMapView()
	call LoadCurrentMapView
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> view = mem16[addr(wMapViewVRAMPointer)]
	ld hl, wMapViewVRAMPointer
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> vram = (view - 2 * TILEMAP_WIDTH) & 0xFFFF       # two rows up (the wrap computed here is not used)
	ld de, -2 * TILEMAP_WIDTH
	add hl, de
	ld a, h
	and $3
	or $98
;> wBuffer[0] = vram & 0xFF
	ld a, l
	ld [wBuffer], a
;> wBuffer[1] = vram >> 8
	ld a, h
	ld [wBuffer + 1], a ; this copy of the address is not used
;> hRedrawMapViewRowOffset = 2
	ld a, 2
	ldh [hRedrawMapViewRowOffset], a
;>@rows for row in range(SCREEN_HEIGHT // 2):         # rows of 2x2 tiles: the whole screen
	ld c, SCREEN_HEIGHT / 2 ; number of rows of 2x2 tiles (this covers the whole screen)
.redrawRowLoop
	push bc
	push hl
	push hl
;>     src = addr(wTileMap) - 2 * SCREEN_WIDTH + SCREEN_WIDTH * hRedrawMapViewRowOffset
	ld hl, wTileMap - 2 * SCREEN_WIDTH
	ld de, SCREEN_WIDTH
	ldh a, [hRedrawMapViewRowOffset]
.calcWRAMAddrLoop
	add hl, de
	dec a
	jr nz, .calcWRAMAddrLoop
;>     CopyToRedrawRowOrColumnSrcTiles(src)
	call CopyToRedrawRowOrColumnSrcTiles
;>@dest     dest = (vram + TILEMAP_WIDTH * hRedrawMapViewRowOffset) & 0xFFFF
	pop hl
	ld de, TILEMAP_WIDTH
	ldh a, [hRedrawMapViewRowOffset]
	ld c, a
.calcVRAMAddrLoop
	add hl, de
;=@high
	ld a, h
	and $3
	or $98
;=@dest
	dec c
	jr nz, .calcVRAMAddrLoop
;>@high     hRedrawRowOrColumnDest[1] = (dest >> 8) & 3 | 0x98    # wraps around the background map
	ldh [hRedrawRowOrColumnDest + 1], a
;>     hRedrawRowOrColumnDest[0] = dest & 0xFF
	ld a, l
	ldh [hRedrawRowOrColumnDest], a
;>     hRedrawRowOrColumnMode = REDRAW_ROW
	ld a, REDRAW_ROW
	ldh [hRedrawRowOrColumnMode], a
;>     DelayFrame()
	call DelayFrame
;>     hRedrawMapViewRowOffset = u8(hRedrawMapViewRowOffset + 2)
	ld hl, hRedrawMapViewRowOffset
	inc [hl]
	inc [hl]
;=@rows
	pop hl
	pop bc
	dec c
	jr nz, .redrawRowLoop
;> hTileAnimations = savedAnimations
	pop af
	ldh [hTileAnimations], a
;> hAutoBGTransferEnabled = savedTransfer
	pop af
	ldh [hAutoBGTransferEnabled], a
	ret

;@ path: engine/overworld/update_map
;@ def CompareHLWithBC(hl: hl, bc: bc) -> (carry, zero)
;@ Compare two addresses: carry if hl < bc, zero if they are equal.
CompareHLWithBC:
;> return hl < bc, hl == bc
	ld a, h
	sub b
	ret nz
	ld a, l
	sub c
	ret
;@ path: engine/overworld/cut
;@ def UsedCut()
;@ The field move Cut. Works on a cut tree or tall grass outdoors, or on the gym's cut tree. Then: name the
;@ Pokémon, print "used CUT", show the cut animation, swap the map block for one without the tree and
;@ redraw the screen. wActionResultOrTookBattleTurn tells the menu whether it worked.
UsedCut:
;> wActionResultOrTookBattleTurn = 0
	xor a
	ld [wActionResultOrTookBattleTurn], a ; initialise to failure value
;> tile = wTileInFrontOfPlayer
;> if wCurMapTileset == OVERWORLD:
	ld a, [wCurMapTileset]
	and a ; OVERWORLD
	jr z, .overworld
;>@outside     ok = tile == 0x3D or tile == 0x52        # cut tree, grass
;> else:
;>     ok = wCurMapTileset == GYM and tile == 0x50   # gym cut tree
	cp GYM
	jr nz, .nothingToCut
	ld a, [wTileInFrontOfPlayer]
	cp $50 ; gym cut tree
	jr nz, .nothingToCut
	jr .canCut
.overworld
;=@outside
	dec a
	ld a, [wTileInFrontOfPlayer]
	cp $3d ; cut tree
	jr z, .canCut
	cp $52 ; grass
	jr z, .canCut
.nothingToCut
;> if not ok:
;>     PrintText(0x6F7D)                        # UsedCut.NothingToCutText
;>@cutret     return
	ld hl, .NothingToCutText
	jp PrintText

.NothingToCutText
	db TX_FAR
	dw _NothingToCutText
	db BANK(_NothingToCutText)
	db TX_END

.canCut
;> wCutTile = tile
	ld [wCutTile], a
;> wActionResultOrTookBattleTurn = 1
	ld a, 1
	ld [wActionResultOrTookBattleTurn], a ; used cut
;> GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearSprites()
	call ClearSprites
;> RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;> hWY = SCREEN_HEIGHT_PX
	ld a, SCREEN_HEIGHT_PX
	ldh [hWY], a
;> Delay3()
	call Delay3
;> LoadGBPal()
	call LoadGBPal
;> LoadCurrentMapView()
	call LoadCurrentMapView
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> Delay3()
	call Delay3
;> hWY = 0
	xor a
	ldh [hWY], a
;> PrintText(UsedCutText)
	ld hl, UsedCutText
	call PrintText
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> InitCutAnimOAM()
	call InitCutAnimOAM
;> ReplaceTreeTileBlock(CutTreeBlockSwaps)
	ld de, CutTreeBlockSwaps
	call ReplaceTreeTileBlock
;> RedrawMapView()
	call RedrawMapView
;> AnimCut()                                    # in another bank
	ld b, BANK(AnimCut)
	ld hl, AnimCut
	call Bankswitch
;> wUpdateSpritesEnabled = 1
	ld a, $1
	ld [wUpdateSpritesEnabled], a
;> PlaySound(SFX_CUT)
	ld a, SFX_CUT
	call PlaySound
;> hWY = 0x90
	ld a, $90
	ldh [hWY], a
;> UpdateSprites()
	call UpdateSprites
;> RedrawMapView()
	jp RedrawMapView

;@ path: engine/overworld/cut
UsedCutText:
	db TX_FAR
	dw _UsedCutText
	db BANK(_UsedCutText)
	db TX_END

;@ path: engine/overworld/cut
;@ def InitCutAnimOAM()
;@ Set up the four sprites of the cut animation in front of the player: the tree's two tile rows from the
;@ overworld graphics, or four leaf tiles for grass, flipped in turn so they fly apart.
InitCutAnimOAM:
;> wWhichAnimationOffsets = 0                   # the cut offsets
	xor a
	ld [wWhichAnimationOffsets], a
;> rOBP1 = 0b11100100
	ld a, %11100100
	ldh [rOBP1], a
;> if wCutTile != 0x52:                         # tree
	ld a, [wCutTile]
	cp $52
	jr z, .grass
; tree
;>     CopyVideoData(addr(vChars1) + 0x7C * TILE_SIZE, Overworld_GFX + 0x2D * TILE_SIZE, BANK(Overworld_GFX), 2)
	ld de, Overworld_GFX + TILE_SIZE * $2d ; cuttable tree sprite top row
	ld hl, vChars1 + TILE_SIZE * $7c
	ld bc, ((BANK(Overworld_GFX)) & $ff) << 8 + ((2) & $ff)
	call CopyVideoData
;>     CopyVideoData(addr(vChars1) + 0x7E * TILE_SIZE, Overworld_GFX + 0x3D * TILE_SIZE, BANK(Overworld_GFX), 2)
	ld de, Overworld_GFX + TILE_SIZE * $3d ; cuttable tree sprite bottom row
	ld hl, vChars1 + TILE_SIZE * $7e
	ld bc, ((BANK(Overworld_GFX)) & $ff) << 8 + ((2) & $ff)
	call CopyVideoData
;>     WriteCutOrBoulderDustAnimationOAMBlock()
;>     return
	jr WriteCutOrBoulderDustAnimationOAMBlock
.grass
;> LoadCutGrassAnimationTilePattern(addr(vChars1) + 0x7C * TILE_SIZE)     # four grass tiles
	ld hl, vChars1 + TILE_SIZE * $7c
	call LoadCutGrassAnimationTilePattern
;> LoadCutGrassAnimationTilePattern(addr(vChars1) + 0x7D * TILE_SIZE)
	ld hl, vChars1 + TILE_SIZE * $7d
	call LoadCutGrassAnimationTilePattern
;> LoadCutGrassAnimationTilePattern(addr(vChars1) + 0x7E * TILE_SIZE)
	ld hl, vChars1 + TILE_SIZE * $7e
	call LoadCutGrassAnimationTilePattern
;> LoadCutGrassAnimationTilePattern(addr(vChars1) + 0x7F * TILE_SIZE)
	ld hl, vChars1 + TILE_SIZE * $7f
	call LoadCutGrassAnimationTilePattern
;> WriteCutOrBoulderDustAnimationOAMBlock()
	call WriteCutOrBoulderDustAnimationOAMBlock
;> attributes = OAM_XFLIP | OAM_PAL1
;> for i in range(OBJ_SIZE):
	ld hl, wShadowOAMSprite36Attributes
	ld de, OBJ_SIZE
	ld a, OAM_XFLIP | OAM_PAL1
	ld c, e
.loop
;>     mem[wShadowOAMSprite36Attributes + i * OBJ_SIZE] = attributes
	ld [hl], a
	add hl, de
;>     attributes = attributes ^ (OAM_YFLIP | OAM_XFLIP)
	xor OAM_YFLIP | OAM_XFLIP
	dec c
	jr nz, .loop
	ret

;@ path: engine/overworld/cut
;@ def LoadCutGrassAnimationTilePattern(dest: hl)
;@ Copy the leaf tile of the move animations to `dest` in video memory.
LoadCutGrassAnimationTilePattern:
;> CopyVideoData(dest, MoveAnimationTiles1 + 6 * TILE_SIZE, BANK(MoveAnimationTiles1), 1)
	ld de, MoveAnimationTiles1 + TILE_SIZE * 6 ; tile depicting a leaf
	ld bc, ((BANK(MoveAnimationTiles1)) & $ff) << 8 + ((1) & $ff)
	jp CopyVideoData

;@ path: engine/overworld/cut
;@ def WriteCutOrBoulderDustAnimationOAMBlock()
;@ Place the 2x2 sprite block of the cut or boulder dust animation (tiles $FC-$FF) as OAM block 9 in front
;@ of the player.
WriteCutOrBoulderDustAnimationOAMBlock:
;> y, x = GetCutOrBoulderDustAnimationOffsets()
;> WriteOAMBlock(9, y, x, 0x7060)    # WriteCutOrBoulderDustAnimationOAMBlock.OAMBlock
	call GetCutOrBoulderDustAnimationOffsets
	ld a, $9
	ld de, .OAMBlock
	jp WriteOAMBlock

.OAMBlock:
; tile ID, attributes
	db $fc, OAM_PAL1
	db $fd, OAM_PAL1
	db $fe, OAM_PAL1
	db $ff, OAM_PAL1

;@ path: engine/overworld/cut
;@ def GetCutOrBoulderDustAnimationOffsets() -> (b, c)
;@ Screen position (y, x) for the cut or boulder dust animation: the player's sprite position plus the
;@ offset for the facing direction from CutAnimationOffsets or BoulderDustAnimationOffsets
;@ (wWhichAnimationOffsets).
;@ test: mem[0xC109] = 4 * rand(0, 3)
GetCutOrBoulderDustAnimationOffsets:
;> y = wSpritePlayerStateData1YPixels
	ld hl, wSpritePlayerStateData1YPixels
	ld a, [hli] ; player's sprite screen Y position
	ld b, a
;> x = wSpritePlayerStateData1XPixels
	inc hl
	ld a, [hli] ; player's sprite screen X position
	ld c, a ; bc holds ypos/xpos of player's sprite
;> facing = wSpritePlayerStateData1FacingDirection
	inc hl
	inc hl
	ld a, [hl] ; a holds direction of player (00: down, 04: up, 08: left, 0C: right)
;> offset = facing >> 1                         # 2-byte entries: x, y
	srl a
	ld e, a
	ld d, $0 ; de holds direction (00: down, 02: up, 04: left, 06: right)
;> table = BoulderDustAnimationOffsets if wWhichAnimationOffsets else CutAnimationOffsets
	ld a, [wWhichAnimationOffsets]
	and a
	ld hl, CutAnimationOffsets
	jr z, .next
	ld hl, BoulderDustAnimationOffsets
.next
;> dx, dy = mem[table + offset], mem[table + offset + 1]
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;> y = u8(y + dy)
	ld a, b
	add d
	ld b, a
;> x = u8(x + dx)
	ld a, c
	add e
	ld c, a
;> return y, x
	ret

;@ path: engine/overworld/cut
CutAnimationOffsets:
; Each pair represents the x and y pixels offsets from the player of where the cut tree animation should be drawn
	db  8, 36 ; player is facing down
	db  8,  4 ; player is facing up
	db -8, 20 ; player is facing left
	db 24, 20 ; player is facing right

;@ path: engine/overworld/cut
BoulderDustAnimationOffsets:
; Each pair represents the x and y pixels offsets from the player of where the cut tree animation should be drawn
; These offsets represent 2 blocks away from the player
	db  8,  52 ; player is facing down
	db  8, -12 ; player is facing up
	db -24, 20 ; player is facing left
	db 40,  20 ; player is facing right

;@ path: engine/overworld/cut
;@ def ReplaceTreeTileBlock(swaps: de)
;@ Find the map block holding the tile in front of the player and replace it using `swaps`, a list of
;@ (old block, new block) pairs ended by $FF. The block depends on the facing direction and on which half
;@ of the current block the player stands in.
;@ test: swaps = rand_ram(16); mem[swaps + 2 * rand(3, 7)] = 0xFF; v = rand_ram(64); mem[0xD35F] = v & 0xFF; mem[0xD360] = v >> 8; wCurMapWidth = rand(0, 10); mem[0xC109] = 4 * rand(0, 3)
ReplaceTreeTileBlock:
; Determine the address of the tile block that contains the tile in front of the
; player (i.e. where the tree is) and replace it with the corresponding tile
; block that doesn't have the tree.
;> width = u8(wCurMapWidth + 6)                # map rows have a 3-block border on each side
	push de
	ld a, [wCurMapWidth]
	add 6
	ld c, a
	ld b, 0
	ld d, 0
;> p = mem16[addr(wCurrentTileBlockMapViewPointer)] + width
	ld hl, wCurrentTileBlockMapViewPointer
	ld a, [hli]
	ld h, [hl]
	ld l, a
	add hl, bc
;> facing = wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
;> dy, dx = 1, 2                                # the block the player stands in
;> if facing == SPRITE_FACING_DOWN:
	and a
	jr z, .down
;>@down     if wYBlockCoord: dy = 2              # in the lower half: the block below
;> elif facing == SPRITE_FACING_UP:
	cp SPRITE_FACING_UP
	jr z, .up
;>@up     if not wYBlockCoord: dy = 0          # in the upper half: the block above
;> elif facing == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr z, .left
; right
;>@left     if not wXBlockCoord: dx = 1
;> elif wXBlockCoord:                           # facing right
;>     dx = 3
	ld a, [wXBlockCoord]
	and a
	jr z, .centerTileBlock
	jr .rightOfCenter
.down
;=@down
	ld a, [wYBlockCoord]
	and a
	jr z, .centerTileBlock
	jr .belowCenter
.up
;=@up
	ld a, [wYBlockCoord]
	and a
	jr z, .aboveCenter
	jr .centerTileBlock
.left
;=@left
	ld a, [wXBlockCoord]
	and a
	jr z, .leftOfCenter
	jr .centerTileBlock
.belowCenter
;>@add p += dy * width + dx
	add hl, bc
.centerTileBlock
	add hl, bc
.aboveCenter
	ld e, $2
	add hl, de
	jr .next
.leftOfCenter
;=@add
	ld e, $1
	add hl, bc
	add hl, de
	jr .next
.rightOfCenter
;=@add
	ld e, $3
	add hl, bc
	add hl, de
.next
;> block = mem[p]
	pop de
	ld a, [hl]
	ld c, a
.loop ; find the matching tile block in the array
;> while mem[swaps] != 0xFF:                    # (old block, new block) pairs
	ld a, [de]
	inc de
	inc de
	cp $ff
	ret z
;>     if mem[swaps] == block:
	cp c
	jr nz, .loop
;>         mem[p] = mem[swaps + 1]
	dec de
	ld a, [de] ; replacement tile block from matching array entry
	ld [hl], a
;>         return
	ret
;>@next     swaps += 2

;@ path: engine/overworld/cut
CutTreeBlockSwaps:
	; first byte = tileset block containing the cut tree
	; second byte = corresponding tileset block after the cut animation happens
	db $32, $6D
	db $33, $6C
	db $34, $6F
	db $35, $4C
	db $60, $6E
	db $0B, $0A
	db $3C, $35
	db $3F, $35
	db $3D, $36
	db -1 ; end
;@ path: engine/overworld/toggleable_objects
;@ def MarkTownVisitedAndLoadToggleableObjects()
;@ On entering a map: a town gets its "visited" flag (so Fly can go there), and the map's entries of the
;@ toggleable object table are copied to wToggleableObjectList as pairs (sprite number on this map,
;@ global object index), ended by $FF. The global index of the map's first entry is its position in the
;@ big table, found by dividing the pointer distance by the entry size 3.
;@ test: hLoadedROMBank = 3; wCurMap = rand(FIRST_ROUTE_MAP, NUM_MAPS - 1)
MarkTownVisitedAndLoadToggleableObjects::
;> if wCurMap < FIRST_ROUTE_MAP:
	ld a, [wCurMap]
	cp FIRST_ROUTE_MAP
	jr nc, .notInTown
;>     FlagAction(addr(wTownVisitedFlag), wCurMap, FLAG_SET)     # through FlagActionPredef
	ld c, a
	ld b, FLAG_SET
	ld hl, wTownVisitedFlag   ; mark town as visited (for flying)
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
.notInTown
;> entry = ToggleableObjectMapPointers + 2 * wCurMap
	ld hl, ToggleableObjectMapPointers
	ld a, [wCurMap]
	ld b, $0
	ld c, a
	add hl, bc
	add hl, bc
;> p = mem16[entry]                              # this map's part of ToggleableObjectStates
	ld a, [hli] ; load toggleable objects pointer in hl
	ld h, [hl]
	ld l, a
;>@diff diff = (p - ToggleableObjectStates) & 0xFFFF
	push hl
	ld de, ToggleableObjectStates ; calculate difference between out pointer and the base pointer
	ld a, l
	sub e
	jr nc, .noCarry
	dec h
.noCarry
;=@diff
	ld l, a
	ld a, h
	sub d
	ld h, a
	; divide difference by 3, resulting in the global offset (number of toggleable items before ours)
;> hDividend[0] = diff >> 8
	ld a, h
	ldh [hDividend], a
;> hDividend[1] = diff & 0xFF
	ld a, l
	ldh [hDividend+1], a
;> hDividend[2] = 0
	xor a
	ldh [hDividend+2], a
;> hDividend[3] = 0
	ldh [hDividend+3], a
;> hDivisor = 3
	ld a, $3
	ldh [hDivisor], a
;> Divide(2)
	ld b, $2
	call Divide
;> index = hDividend[3]
	ld a, [wCurMap]
	ld b, a
	ldh a, [hDividend+3]
	ld c, a                    ; store global offset in c
;> out = addr(wToggleableObjectList)
	ld de, wToggleableObjectList
	pop hl
.writeToggleableObjectsListLoop
;> while mem[p] != 0xFF and mem[p] == wCurMap:     # entries: map, sprite, initial state
	ld a, [hli]
	cp -1
	jr z, .done     ; end of list
	cp b
	jr nz, .done    ; not for current map anymore
;>     mem[out] = mem[p + 1]
	ld a, [hli]
	inc hl
	ld [de], a                 ; write (map-local) sprite ID
;>     mem[out + 1] = index
	inc de
	ld a, c
;>     index = u8(index + 1)
	inc c
	ld [de], a                 ; write (global) toggleable object index
;>     out += 2
;>     p += 3
	inc de
	jr .writeToggleableObjectsListLoop
.done
;> mem[out] = 0xFF
	ld a, -1
	ld [de], a                 ; write sentinel
	ret

;@ path: engine/overworld/toggleable_objects
;@ def InitializeToggleableObjectsFlags()
;@ At the start of a new game: clear all toggleable object flags, then set the flag ("hidden") of every
;@ object whose initial state in the table is OFF.
InitializeToggleableObjectsFlags:
;> FillMemory(addr(wToggleableObjectFlags), addr(wToggleableObjectFlagsEnd) - addr(wToggleableObjectFlags), 0)
	ld hl, wToggleableObjectFlags
	ld bc, wToggleableObjectFlagsEnd - wToggleableObjectFlags
	xor a
	call FillMemory ; clear toggleable objects flags
;> p = ToggleableObjectStates
	ld hl, ToggleableObjectStates
;> wToggleableObjectCounter = 0
	xor a
	ld [wToggleableObjectCounter], a
.toggleableObjectsLoop
;> while mem[p] != 0xFF:
	ld a, [hli]
	cp -1 ; end of list
	ret z
;>     if mem[p + 2] == OFF:
	push hl
	inc hl
	ld a, [hl]
	cp OFF
	jr nz, .skip
;>         ToggleableObjectFlagAction(addr(wToggleableObjectFlags), wToggleableObjectCounter, FLAG_SET)
	ld hl, wToggleableObjectFlags
	ld a, [wToggleableObjectCounter]
	ld c, a
	ld b, FLAG_SET
	call ToggleableObjectFlagAction ; set flag if object is toggled off
.skip
;>     wToggleableObjectCounter = u8(wToggleableObjectCounter + 1)
	ld hl, wToggleableObjectCounter
	inc [hl]
;>     p += 3
	pop hl
	inc hl
	inc hl
	jr .toggleableObjectsLoop

; tests if current object is toggled off/has been hidden
;@ path: engine/overworld/toggleable_objects
;@ def IsObjectHidden()
;@ Is the current sprite a toggleable object that is switched off? Looks it up in this map's
;@ wToggleableObjectList and leaves its flag in hIsToggleableObjectOff (0 when visible or not toggleable).
;@ test: k = rand(1, 15); hCurrentSpriteOffset = 16 * k; mem[0xD5CE + 2 * rand(6, 15)] = 0xFF; mem[0xD5CE + 2 * rand(0, 5)] = k
IsObjectHidden:
;> sprite = swap(hCurrentSpriteOffset)
	ldh a, [hCurrentSpriteOffset]
	swap a
	ld b, a
;> p = addr(wToggleableObjectList)
	ld hl, wToggleableObjectList
.loop
;>@scan while mem[p] != 0xFF and mem[p] != sprite:
;>     p += 2
	ld a, [hli]
	cp -1
;=@none
	jr z, .notHidden ; not toggleable -> not hidden
;=@scan
	cp b
	ld a, [hli]
	jr nz, .loop
;>@none if mem[p] == 0xFF:                        # not toggleable: shown
;>@shown     hIsToggleableObjectOff = 0
;> else:
;>     off = ToggleableObjectFlagAction(addr(wToggleableObjectFlags), mem[p + 1], FLAG_TEST)
	ld c, a
	ld b, FLAG_TEST
	ld hl, wToggleableObjectFlags
	call ToggleableObjectFlagAction
;>@store     hIsToggleableObjectOff = off
	ld a, c
	and a
	jr nz, .hidden
.notHidden
;=@shown
	xor a
.hidden
;=@store
	ldh [hIsToggleableObjectOff], a
	ret

; adds toggleable object (items, leg. pokemon, etc.) to the map
; [wToggleableObjectIndex]: index of the toggleable object to be added (global index)
;@ path: engine/overworld/toggleable_objects
ShowObject:
;@ path: engine/overworld/toggleable_objects
;@ def ShowObject2()
;@ Make toggleable object number wToggleableObjectIndex (global index) appear: clear its "hidden" flag and
;@ redraw the sprites.
ShowObject2:
;> ToggleableObjectFlagAction(addr(wToggleableObjectFlags), wToggleableObjectIndex, FLAG_RESET)
;> UpdateSprites()
	ld hl, wToggleableObjectFlags
	ld a, [wToggleableObjectIndex]
	ld c, a
	ld b, FLAG_RESET
	call ToggleableObjectFlagAction   ; reset "removed" flag
	jp UpdateSprites

; removes toggleable object (items, leg. pokemon, etc.) from the map
; [wToggleableObjectIndex]: index of the toggleable object to be removed (global index)
;@ path: engine/overworld/toggleable_objects
;@ def HideObject()
;@ Make toggleable object number wToggleableObjectIndex (global index) disappear, for example an item ball
;@ that was picked up: set its "hidden" flag and redraw the sprites.
HideObject:
;> ToggleableObjectFlagAction(addr(wToggleableObjectFlags), wToggleableObjectIndex, FLAG_SET)
;> UpdateSprites()
	ld hl, wToggleableObjectFlags
	ld a, [wToggleableObjectIndex]
	ld c, a
	ld b, FLAG_SET
	call ToggleableObjectFlagAction   ; set "removed" flag
	jp UpdateSprites

;@ path: engine/overworld/toggleable_objects
;@ def ToggleableObjectFlagAction(flags: hl, index: c, action: b) -> c
;@ Reset (action 0), set (1) or test (2) bit number `index` of the bit field at `flags`. Returns the bit's
;@ byte after the change, or for a test that byte masked to the bit (nonzero if set).
;@ test: flags = rand_ram(32)
ToggleableObjectFlagAction:
; identical to FlagAction

;>@bit bit = index & 7
;=@done
	push hl
	push de
	push bc

	; bit
;=@bit
	ld a, c
	ld d, a
	and 7
	ld e, a

;> offset = index >> 3
	; byte
	ld a, d
	srl a
	srl a
	srl a
;> byte = flags + offset
	add l
	ld l, a
	jr nc, .ok
	inc h
.ok

;> mask = 1 << bit
	; d = 1 << e (bitmask)
	inc e
	ld d, 1
.shift
	dec e
	jr z, .shifted
	sla d
	jr .shift
.shifted

;> if action == FLAG_RESET:
	ld a, b
	and a
	jr z, .reset
;>@clear     mem[byte] = mem[byte] & ~mask & 0xFF
;>@cleared     return mem[byte]
;> elif action == FLAG_TEST:
	cp FLAG_TEST
	jr z, .read

;>@test     return mem[byte] & mask
;> else:
; set
;>     mem[byte] = mem[byte] | mask
	ld a, [hl]
	ld b, a
	ld a, d
	or b
	ld [hl], a
;>@done     return mem[byte]
	jr .done

.reset
;=@clear
	ld a, [hl]
	ld b, a
	ld a, d
	xor $ff
	and b
	ld [hl], a
;=@cleared
	jr .done

.read
;=@test
	ld a, [hl]
	ld b, a
	ld a, d
	and b

.done
;=@done
	pop bc
	pop de
	pop hl
	ld c, a
	ret
;@ path: engine/overworld/push_boulder
;@ def TryPushingBoulder()
;@ With Strength active and the player facing a boulder: the first push only arms it (BIT_TRIED_PUSH_BOULDER);
;@ the next push with the matching direction held moves the boulder one step, if nothing blocks it, plays the
;@ push sound and asks for the dust animation. Facing anything else clears both boulder flags.
TryPushingBoulder::
;> if not wStatusFlags1 & (1 << BIT_STRENGTH_ACTIVE):
;>     return
	ld a, [wStatusFlags1]
	bit BIT_STRENGTH_ACTIVE, a
	ret z
;> if wMiscFlags & (1 << BIT_BOULDER_DUST):
;>     return
	ld a, [wMiscFlags]
	bit BIT_BOULDER_DUST, a
	ret nz
;> hSpriteIndex = 0
	xor a
	ldh [hSpriteIndex], a
;> IsSpriteInFrontOfPlayer()
	call IsSpriteInFrontOfPlayer
;> wBoulderSpriteIndex = hSpriteIndex
	ldh a, [hSpriteIndex]
	ld [wBoulderSpriteIndex], a
;> if hSpriteIndex == 0:                        # no boulder in front
;>     return ResetBoulderPushFlags()
	and a
	jp z, ResetBoulderPushFlags
;> status = addr(wSpritePlayerStateData1MovementStatus) + swap(hSpriteIndex)
	ld hl, wSpritePlayerStateData1MovementStatus
	ld d, $0
	ldh a, [hSpriteIndex]
	swap a
	ld e, a
	add hl, de
;> mem[status] = mem[status] & ~(1 << BIT_FACE_PLAYER) & 0xFF
	res BIT_FACE_PLAYER, [hl]
;> if mem[GetSpriteMovementByte2Pointer()] != BOULDER_MOVEMENT_BYTE_2:      # not a boulder
;>     return ResetBoulderPushFlags()
	call GetSpriteMovementByte2Pointer
	ld a, [hl]
	cp BOULDER_MOVEMENT_BYTE_2
	jp nz, ResetBoulderPushFlags
;> tried = wMiscFlags & (1 << BIT_TRIED_PUSH_BOULDER)
	ld hl, wMiscFlags
	bit BIT_TRIED_PUSH_BOULDER, [hl]
;> wMiscFlags = wMiscFlags | 1 << BIT_TRIED_PUSH_BOULDER
	set BIT_TRIED_PUSH_BOULDER, [hl]
;> if not tried:                                # the player must push twice
;>     return
	ret z ; the player must try pushing twice before the boulder will move
;> if not hJoyHeld & PAD_CTRL_PAD:
;>     return
	ldh a, [hJoyHeld]
	and PAD_CTRL_PAD
	ret z
;> CheckForCollisionWhenPushingBoulder()
	ld a, (CheckForCollisionWhenPushingBoulderPredef - PredefPointers) / 3
	call Predef
;> if wTileInFrontOfBoulderAndBoulderCollisionResult:     # blocked
;>     return ResetBoulderPushFlags()
	ld a, [wTileInFrontOfBoulderAndBoulderCollisionResult]
	and a ; was there a collision?
	jp nz, ResetBoulderPushFlags
;> held = hJoyHeld
	ldh a, [hJoyHeld]
	ld b, a
;> facing = wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
;> if facing == SPRITE_FACING_UP:               # the direction held must match
	cp SPRITE_FACING_UP
	jr z, .pushBoulderUp
;>@upheld     if not held >> B_PAD_UP & 1: return
;>@upmoves     moves = PushBoulderUpMovementData
;> elif facing == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr z, .pushBoulderLeft
;>@leftheld     if not held >> B_PAD_LEFT & 1: return
;>@leftmoves     moves = PushBoulderLeftMovementData
;> elif facing == SPRITE_FACING_RIGHT:
	cp SPRITE_FACING_RIGHT
	jr z, .pushBoulderRight
; push boulder down
;>@rightheld     if not held >> B_PAD_RIGHT & 1: return
;>@rightmoves     moves = PushBoulderRightMovementData
;> else:
;>     if not held >> B_PAD_DOWN & 1: return
	bit B_PAD_DOWN, b
	ret z
;>     moves = PushBoulderDownMovementData
	ld de, PushBoulderDownMovementData
	jr .done
.pushBoulderUp
;=@upheld
	bit B_PAD_UP, b
	ret z
;=@upmoves
	ld de, PushBoulderUpMovementData
	jr .done
.pushBoulderLeft
;=@leftheld
	bit B_PAD_LEFT, b
	ret z
;=@leftmoves
	ld de, PushBoulderLeftMovementData
	jr .done
.pushBoulderRight
;=@rightheld
	bit B_PAD_RIGHT, b
	ret z
;=@rightmoves
	ld de, PushBoulderRightMovementData
.done
;> MoveSprite(moves)
	call MoveSprite
;> PlaySound(SFX_PUSH_BOULDER)
	ld a, SFX_PUSH_BOULDER
	call PlaySound
;> wMiscFlags = wMiscFlags | 1 << BIT_BOULDER_DUST
	ld hl, wMiscFlags
	set BIT_BOULDER_DUST, [hl]
	ret

;@ path: engine/overworld/push_boulder
PushBoulderUpMovementData:
	db NPC_MOVEMENT_UP
	db -1 ; end

;@ path: engine/overworld/push_boulder
PushBoulderDownMovementData:
	db NPC_MOVEMENT_DOWN
	db -1 ; end

;@ path: engine/overworld/push_boulder
PushBoulderLeftMovementData:
	db NPC_MOVEMENT_LEFT
	db -1 ; end

;@ path: engine/overworld/push_boulder
PushBoulderRightMovementData:
	db NPC_MOVEMENT_RIGHT
	db -1 ; end

;@ path: engine/overworld/push_boulder
;@ def DoBoulderDustAnimation()
;@ After a boulder push (outside scripted movement): show the dust cloud, mark the boulder as pushed, restore
;@ the boulder's movement byte and play the cut sound.
DoBoulderDustAnimation::
;> if wStatusFlags5 & (1 << BIT_SCRIPTED_NPC_MOVEMENT):
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz
;> AnimateBoulderDust()                         # in another bank
	ld hl, AnimateBoulderDust
	ld b, BANK(AnimateBoulderDust)
	call Bankswitch
;> DiscardButtonPresses()
	call DiscardButtonPresses
;> wJoyIgnore = 0
	ld [wJoyIgnore], a
;> ResetBoulderPushFlags()
	call ResetBoulderPushFlags
;> wMiscFlags = wMiscFlags | 1 << BIT_PUSHED_BOULDER
	set BIT_PUSHED_BOULDER, [hl]
;> hSpriteIndex = wBoulderSpriteIndex
	ld a, [wBoulderSpriteIndex]
	ldh [hSpriteIndex], a
;> mem[GetSpriteMovementByte2Pointer()] = BOULDER_MOVEMENT_BYTE_2
	call GetSpriteMovementByte2Pointer
	ld [hl], $10
;> PlaySound(SFX_CUT)
	ld a, SFX_CUT
	jp PlaySound

;@ path: engine/overworld/push_boulder
;@ def ResetBoulderPushFlags()
;@ Clear the boulder flags: no dust animation pending, no push tried yet.
ResetBoulderPushFlags:
;> wMiscFlags = wMiscFlags & ~(1 << BIT_BOULDER_DUST | 1 << BIT_TRIED_PUSH_BOULDER) & 0xFF
	ld hl, wMiscFlags
	res BIT_BOULDER_DUST, [hl]
	res BIT_TRIED_PUSH_BOULDER, [hl]
	ret
;@ path: engine/pokemon/add_mon
;@ def _AddPartyMon() -> carry
;@ Add a new Pokémon of species wCurPartySpecies at level wCurEnemyLevel to the player's party (or, if the low
;@ nibble of wMonDataLocation is set, the enemy's): species list, original trainer, nickname (asked for when
;@ wMonDataLocation is 0), DVs, HP, types, moves, experience, PP and stats. Returns carry if it was added.
_AddPartyMon::
; Adds a new mon to the player's or enemy's party.
; [wMonDataLocation] is used in an unusual way in this function.
; If the lower nybble is 0, the mon is added to the player's party, else the enemy's.
; If the entire value is 0, then the player is allowed to name the mon.
;> enemy = wMonDataLocation & 0xF
;> lst = addr(wEnemyPartyCount) if enemy else addr(wPartyCount)
	ld de, wPartyCount
	ld a, [wMonDataLocation]
	and $f
	jr z, .next
	ld de, wEnemyPartyCount
.next
;> n = u8(mem[lst] + 1)
	ld a, [de]
	inc a
;> if n >= PARTY_LENGTH + 1:
;>     return False                              # the party is full
	cp PARTY_LENGTH + 1
	ret nc ; return if the party is already full
;> mem[lst] = n
	ld [de], a
;> hNewPartyLength = n
	ld a, [de]
	ldh [hNewPartyLength], a
;> mem[lst + n] = wCurPartySpecies
	add e
	ld e, a
	jr nc, .noCarry
	inc d
.noCarry
	ld a, [wCurPartySpecies]
	ld [de], a ; write species of new mon in party list
;> mem[lst + n + 1] = 0xFF
	inc de
	ld a, $ff ; terminator
	ld [de], a
;> ot = addr(wEnemyMonOT) if enemy else addr(wPartyMonOT)
	ld hl, wPartyMonOT
	ld a, [wMonDataLocation]
	and $f
	jr z, .next2
	ld hl, wEnemyMonOT
.next2
;> ot += (n - 1) * NAME_LENGTH
	ldh a, [hNewPartyLength]
	dec a
	call SkipFixedLengthTextEntries
;> CopyData(addr(wPlayerName), ot, NAME_LENGTH)  # the player is the original trainer
	ld d, h
	ld e, l
	ld hl, wPlayerName
	ld bc, NAME_LENGTH
	call CopyData
;> if wMonDataLocation == 0:                     # the player gives it a nickname
	ld a, [wMonDataLocation]
	and a
	jr nz, .skipNaming
;>     nick = addr(wPartyMonNicks) + (n - 1) * NAME_LENGTH
	ld hl, wPartyMonNicks
	ldh a, [hNewPartyLength]
	dec a
	call SkipFixedLengthTextEntries
;>     wNamingScreenType = NAME_MON_SCREEN
	ld a, NAME_MON_SCREEN
	ld [wNamingScreenType], a
;>     AskName(nick)
	ld a, (AskNamePredef - PredefPointers) / 3
	call Predef
.skipNaming
;> mon = addr(wEnemyMons) if enemy else addr(wPartyMons)
	ld hl, wPartyMons
	ld a, [wMonDataLocation]
	and $f
	jr z, .next3
	ld hl, wEnemyMons
.next3
;> mon += (n - 1) * PARTYMON_STRUCT_LENGTH
	ldh a, [hNewPartyLength]
	dec a
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> at = mon                                      # filled in field by field
	ld e, l
	ld d, h
	push hl
;> wCurSpecies = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> mem[mon] = wMonHeader[0]                      # species
	ld hl, wMonHeader
	ld a, [hli]
	ld [de], a ; species
	inc de
	pop hl
	push hl
;> if enemy:
;>     dvs = (ATKDEFDV_TRAINER, SPDSPCDV_TRAINER)  # fixed, average DVs for trainers' Pokémon
	ld a, [wMonDataLocation]
	and $f
	ld a, ATKDEFDV_TRAINER  ; set enemy trainer mon IVs to fixed average values
	ld b, SPDSPCDV_TRAINER
	jr nz, .next4

; If the mon is being added to the player's party, update the pokedex.
;> else:
;>     # a new Pokémon for the player: seen and owned in the Pokédex
;>     wPokedexNum = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wPokedexNum], a
;>     IndexToPokedex()
	push de
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
	pop de
;>     dex = u8(wPokedexNum - 1)
	ld a, [wPokedexNum]
	dec a
	ld c, a
;>     wUnusedAlreadyOwnedFlag = FlagAction(addr(wPokedexOwned), dex, FLAG_TEST)
	ld b, FLAG_TEST
	ld hl, wPokedexOwned
	call FlagAction
	ld a, c ; whether the mon was already flagged as owned
	ld [wUnusedAlreadyOwnedFlag], a
;>     dex = u8(wPokedexNum - 1)                 # (again)
	ld a, [wPokedexNum]
	dec a
	ld c, a
;>     FlagAction(addr(wPokedexOwned), dex, FLAG_SET)
	ld b, FLAG_SET
	push bc
	call FlagAction
	pop bc
;>     FlagAction(addr(wPokedexSeen), dex, FLAG_SET)
	ld hl, wPokedexSeen
	call FlagAction

	pop hl
	push hl

;>     if not wIsInBattle:                       # not a wild one caught in battle
	ld a, [wIsInBattle]
	and a ; is this a wild mon caught in battle?
	jr nz, .copyEnemyMonData

; Not wild.
;>         spd_spc = Random()
	call Random ; generate random IVs
	ld b, a
;>         dvs = (Random(), spd_spc)
	call Random

.next4
;> if enemy or not wIsInBattle:
;>     mem[mon + MON_DVS] = dvs[0]
	push bc
	ld bc, MON_DVS
	add hl, bc
	pop bc
	ld [hli], a
;>     mem[mon + MON_DVS + 1] = dvs[1]
	ld [hl], b         ; write IVs
;>     stat_exp = mon + MON_HP_EXP - 1
	ld bc, (MON_HP_EXP - 1) - (MON_DVS + 1)
	add hl, bc
;>     CalcStat(stat_exp, 1, 0)                  # the HP stat, at full HP
	ld a, 1
	ld c, a
	xor a
	ld b, a
	call CalcStat      ; calc HP stat (set cur Hp to max HP)
;>     mem[mon + 1] = hMultiplicand[1]
	ldh a, [hMultiplicand+1]
	ld [de], a
	inc de
;>     mem[mon + 2] = hMultiplicand[2]
	ldh a, [hMultiplicand+2]
	ld [de], a
	inc de
;>     mem[mon + 3] = 0                          # box level
	xor a
	ld [de], a         ; box level
	inc de
;>     mem[mon + 4] = 0                          # status
	ld [de], a         ; status ailments
	inc de
	jr .copyMonTypesAndMoves
.copyEnemyMonData
;> else:
;>     # caught in battle: the DVs, HP and status of the wild Pokémon
;>     mem[mon + MON_DVS] = mem[wEnemyMonDVs]
	ld bc, MON_DVS
	add hl, bc
	ld a, [wEnemyMonDVs] ; copy IVs from cur enemy mon
	ld [hli], a
;>     mem[mon + MON_DVS + 1] = mem[wEnemyMonDVs + 1]
	ld a, [wEnemyMonDVs + 1]
	ld [hl], a
;>     mem[mon + 1] = mem[wEnemyMonHP]
	ld a, [wEnemyMonHP]    ; copy HP from cur enemy mon
	ld [de], a
	inc de
;>     mem[mon + 2] = mem[wEnemyMonHP + 1]
	ld a, [wEnemyMonHP+1]
	ld [de], a
	inc de
;>     mem[mon + 3] = 0
	xor a
	ld [de], a                ; box level
	inc de
;>     mem[mon + 4] = mem[wEnemyMonStatus]
	ld a, [wEnemyMonStatus]   ; copy status ailments from cur enemy mon
	ld [de], a
	inc de
.copyMonTypesAndMoves
;> mem[mon + 5] = wMonHTypes[0]
	ld hl, wMonHTypes
	ld a, [hli]       ; type 1
	ld [de], a
	inc de
;> mem[mon + 6] = wMonHTypes[1]
	ld a, [hli]       ; type 2
	ld [de], a
	inc de
;> mem[mon + 7] = wMonHTypes[2]                  # the catch rate
	ld a, [hli]       ; catch rate (held item in gen 2)
	ld [de], a
;> # the moves of the base data first
;> mem[mon + MON_MOVES] = wMonHMoves[0]
	ld hl, wMonHMoves
	ld a, [hli]
	inc de
	push de
	ld [de], a
;> mem[mon + MON_MOVES + 1] = wMonHMoves[1]
	ld a, [hli]
	inc de
	ld [de], a
;> mem[mon + MON_MOVES + 2] = wMonHMoves[2]
	ld a, [hli]
	inc de
	ld [de], a
;> mem[mon + MON_MOVES + 3] = wMonHMoves[3]
	ld a, [hli]
	inc de
	ld [de], a
;> moves = mon + MON_MOVES
	push de
	dec de
	dec de
	dec de
;> wLearningMovesFromDayCare = 0
	xor a
	ld [wLearningMovesFromDayCare], a
;> WriteMonMoves(moves)                          # then those learned up to its level
	ld a, (WriteMonMovesPredef - PredefPointers) / 3
	call Predef
	pop de
;> mem[mon + 12] = wPlayerID[0]                  # the player's trainer ID
	ld a, [wPlayerID]  ; set trainer ID to player ID
	inc de
	ld [de], a
;> mem[mon + 13] = wPlayerID[1]
	ld a, [wPlayerID + 1]
	inc de
	ld [de], a
;> CalcExperience(wCurEnemyLevel)
	push de
	ld a, [wCurEnemyLevel]
	ld d, a
;> # (a far call)
	ld hl, CalcExperience
	ld b, BANK(CalcExperience)
	call Bankswitch
	pop de
;> mem[mon + 14] = hProduct[1]                   # the experience
	inc de
	ldh a, [hExperience] ; write experience
	ld [de], a
;> mem[mon + 15] = hProduct[2]
	inc de
	ldh a, [hExperience + 1]
	ld [de], a
;> mem[mon + 16] = hProduct[3]
	inc de
	ldh a, [hExperience + 2]
	ld [de], a
;> for i in range(NUM_STATS * 2):                # no stat experience yet
	xor a
	ld b, NUM_STATS * 2
.writeEVsLoop              ; set all EVs to 0
;>     mem[mon + 17 + i] = 0
	inc de
	ld [de], a
	dec b
	jr nz, .writeEVsLoop
;> pp = mon + MON_PP - 1
	inc de
	inc de
;> AddPartyMon_WriteMovePP(mon + MON_MOVES, mon + MON_PP - 1)
	pop hl
	call AddPartyMon_WriteMovePP
;> mem[mon + MON_LEVEL] = wCurEnemyLevel
	inc de
	ld a, [wCurEnemyLevel]
	ld [de], a
	inc de
;> if wIsInBattle == 1:                          # a wild one keeps its stats
	ld a, [wIsInBattle]
	dec a
	jr nz, .calcFreshStats
;>     CopyData(addr(wEnemyMonMaxHP), mon + MON_STATS, NUM_STATS * 2)
	ld hl, wEnemyMonMaxHP
	ld bc, NUM_STATS * 2
	call CopyData          ; copy stats of cur enemy mon
	pop hl
	jr .done
.calcFreshStats
;> else:
;>     CalcStats(mon + MON_HP_EXP - 1, mon + MON_STATS, 0)
	pop hl
	ld bc, MON_HP_EXP - 1
	add hl, bc
	ld b, $0
	call CalcStats         ; calculate fresh set of stats
.done
;> return True
	scf
	ret

;@ path: engine/pokemon/add_mon
;@ def LoadMovePPs() -> (de, hl)
;@ AddPartyMon_WriteMovePP with the registers the predef call saved (wPredefHL, wPredefDE).
;@ test: hLoadedROMBank = 3; m = rand_ram(4); d = rand_ram(8); mem[wPredefHL] = m >> 8; mem[wPredefHL + 1] = m & 0xFF; mem[wPredefDE] = d >> 8; mem[wPredefDE + 1] = d & 0xFF
LoadMovePPs:
;> return AddPartyMon_WriteMovePP(wPredefHL[0] << 8 | wPredefHL[1], wPredefDE[0] << 8 | wPredefDE[1])
	call GetPredefRegisters
	; fallthrough
;@ path: engine/pokemon/add_mon
;@ def AddPartyMon_WriteMovePP(moves: hl, dest: de) -> (de, hl)
;@ Write the full PP of the four moves at `moves` to dest + 1 ... dest + 4 (0 for an empty slot), looking each
;@ move up in the Moves table.
;@ test: hLoadedROMBank = 3; moves = rand_ram(4); dest = rand_ram(8)
AddPartyMon_WriteMovePP:
;> for i in range(NUM_MOVES):
	ld b, NUM_MOVES
.pploop
;>     move = pp = mem[moves + i]                # pp 0 for an empty slot
	ld a, [hli]     ; read move ID
;>     if move:
	and a
	jr z, .empty
;>         index = move - 1
	dec a
	push hl
	push de
	push bc
;>         entry = Moves + index * MOVE_LENGTH
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;>         FarCopyData(BANK(Moves), entry, addr(wMoveData), MOVE_LENGTH)
	ld de, wMoveData
	ld a, BANK(Moves)
	call FarCopyData
;>         pp = wMoveData[MOVE_PP]
	pop bc
	pop de
	pop hl
	ld a, [wMoveData + MOVE_PP]
.empty
;>     mem[dest + 1 + i] = pp
	inc de
	ld [de], a
	dec b
	jr nz, .pploop ; there are still moves to read
;> return (dest + NUM_MOVES, moves + NUM_MOVES)
	ret

; adds enemy mon [wCurPartySpecies] (at position [wWhichPokemon] in enemy list) to own party
; used in the cable club trade center
;@ path: engine/pokemon/add_mon
;@ def _AddEnemyMonToPlayerParty() -> carry
;@ Trade center: the Pokémon in wLoadedMon (enemy party slot wWhichPokemon) joins the player's party with its
;@ original trainer and nickname, and is marked seen and owned. Returns carry if the party is full.
;@ test: hLoadedROMBank = 3; wPartyCount = rand(0, 6); wWhichPokemon = rand(0, 5); wCurPartySpecies = rand(1, 190)
_AddEnemyMonToPlayerParty::
;> n = wPartyCount
	ld hl, wPartyCount
	ld a, [hl]
;> if n == PARTY_LENGTH:
;>     return True                               # the party is full
	cp PARTY_LENGTH
	scf
	ret z            ; party full, return failure
;> n += 1
;> wPartyCount = n
	inc a
	ld [hl], a       ; add 1 to party members
;> mem[addr(wPartyCount) + n] = wCurPartySpecies
	ld c, a
	ld b, $0
	add hl, bc
	ld a, [wCurPartySpecies]
	ld [hli], a      ; add mon as last list entry
;> mem[addr(wPartyCount) + n + 1] = 0xFF
	ld [hl], $ff     ; write new sentinel
;> mon = addr(wPartyMons) + (n - 1) * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMons
	ld a, [wPartyCount]
	dec a
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> CopyData(addr(wLoadedMon), mon, PARTYMON_STRUCT_LENGTH)
	ld e, l
	ld d, h
	ld hl, wLoadedMon
	call CopyData    ; write new mon's data (from wLoadedMon)
;> ot = addr(wPartyMonOT) + (n - 1) * NAME_LENGTH
	ld hl, wPartyMonOT
	ld a, [wPartyCount]
	dec a
	call SkipFixedLengthTextEntries
	ld d, h
	ld e, l
;> CopyData(addr(wEnemyMonOT) + wWhichPokemon * NAME_LENGTH, ot, NAME_LENGTH)
	ld hl, wEnemyMonOT
	ld a, [wWhichPokemon]
	call SkipFixedLengthTextEntries
	ld bc, NAME_LENGTH
	call CopyData    ; write new mon's OT name (from an enemy mon)
;> nick = addr(wPartyMonNicks) + (n - 1) * NAME_LENGTH
	ld hl, wPartyMonNicks
	ld a, [wPartyCount]
	dec a
	call SkipFixedLengthTextEntries
	ld d, h
	ld e, l
;> CopyData(addr(wEnemyMonNicks) + wWhichPokemon * NAME_LENGTH, nick, NAME_LENGTH)
	ld hl, wEnemyMonNicks
	ld a, [wWhichPokemon]
	call SkipFixedLengthTextEntries
	ld bc, NAME_LENGTH
	call CopyData    ; write new mon's nickname (from an enemy mon)
;> wPokedexNum = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wPokedexNum], a
;> Predef((IndexToPokedexPredef - PredefPointers) // 3)      # IndexToPokedex
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> dex = u8(wPokedexNum - 1)
	ld a, [wPokedexNum]
	dec a
	ld c, a
;> FlagAction(addr(wPokedexOwned), dex, FLAG_SET)
	ld b, FLAG_SET
	ld hl, wPokedexOwned
	push bc
	call FlagAction ; add to owned pokemon
	pop bc
;> FlagAction(addr(wPokedexSeen), dex, FLAG_SET)
	ld hl, wPokedexSeen
	call FlagAction ; add to seen pokemon
;> return False
	and a
	ret                  ; return success

;@ path: engine/pokemon/add_mon
;@ def _MoveMon() -> carry
;@ Move Pokémon wWhichPokemon between the box, the party and the day care, as wMoveMonType says: data,
;@ original trainer and nickname. Coming back to the party it gets its level and stats recalculated from its
;@ experience. Returns carry if the party or box is full.
;@ test: hLoadedROMBank = 3; wMoveMonType = rand(0, 3); wWhichPokemon = rand(0, 5); wPartyCount = rand(0, 6); wBoxCount = rand(0, 20)
_MoveMon::
;> t = wMoveMonType
;> if t == PARTY_TO_DAYCARE:
	ld a, [wMoveMonType]
	and a   ; BOX_TO_PARTY
	jr z, .checkPartyMonSlots
	cp DAYCARE_TO_PARTY
	jr z, .checkPartyMonSlots
	cp PARTY_TO_DAYCARE
;>     dest = addr(wDayCareMon)                  # a single record: no list to extend
	ld hl, wDayCareMon
	jr z, .findMonDataSrc
	; else it's PARTY_TO_BOX
;> else:
;>     if t == PARTY_TO_BOX:
;>         lst, full = addr(wBoxCount), MONS_PER_BOX
	ld hl, wBoxCount
;=@full
	ld a, [hl]
	cp MONS_PER_BOX
	jr nz, .partyOrBoxNotFull
	jr .boxFull
.checkPartyMonSlots
;>     else:
;>         lst, full = addr(wPartyCount), PARTY_LENGTH
	ld hl, wPartyCount
;=@full
	ld a, [hl]
	cp PARTY_LENGTH
	jr nz, .partyOrBoxNotFull
.boxFull
;>@full     if mem[lst] == full:
;>         return True
	scf
	ret
.partyOrBoxNotFull
;>     n = mem[lst] + 1
;>     mem[lst] = n
	inc a
	ld [hl], a           ; increment number of mons in party/box
;>     at = lst + n
	ld c, a
	ld b, 0
	add hl, bc
;>     mem[at] = wDayCareMon if t == DAYCARE_TO_PARTY else wCurPartySpecies
	ld a, [wMoveMonType]
	cp DAYCARE_TO_PARTY
	ld a, [wDayCareMon]
	jr z, .copySpecies
	ld a, [wCurPartySpecies]
.copySpecies
	ld [hli], a          ; write new mon ID
;>     mem[at + 1] = 0xFF
	ld [hl], $ff         ; write new sentinel
; find mon data dest
;>     if t != PARTY_TO_BOX:
;>         dest, size, count = addr(wPartyMons), PARTYMON_STRUCT_LENGTH, wPartyCount
	ld a, [wMoveMonType]
	dec a
	ld hl, wPartyMons
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wPartyCount]
	jr nz, .addMonOffset
	; if it's PARTY_TO_BOX
;>     else:
;>         dest, size, count = addr(wBoxMons), BOXMON_STRUCT_LENGTH, wBoxCount
	ld hl, wBoxMons
	ld bc, BOXMON_STRUCT_LENGTH
	ld a, [wBoxCount]
.addMonOffset
;>     dest += (count - 1) * size                # the new last slot
	dec a
	call AddNTimes
.findMonDataSrc
;> if t == BOX_TO_PARTY:
	push hl
	ld e, l
	ld d, h
	ld a, [wMoveMonType]
	and a
;>     src = addr(wBoxMons) + wWhichPokemon * BOXMON_STRUCT_LENGTH
	ld hl, wBoxMons
	ld bc, BOXMON_STRUCT_LENGTH
	jr z, .addMonOffset2
;> elif t == DAYCARE_TO_PARTY:
;>     src = addr(wDayCareMon)
	cp DAYCARE_TO_PARTY
	ld hl, wDayCareMon
	jr z, .copyMonData
;> else:
;>     src = addr(wPartyMons) + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMons
	ld bc, PARTYMON_STRUCT_LENGTH
.addMonOffset2
	ld a, [wWhichPokemon]
	call AddNTimes
.copyMonData
;> CopyData(src, dest, BOXMON_STRUCT_LENGTH)
	push hl
	push de
	ld bc, BOXMON_STRUCT_LENGTH
	call CopyData
	pop de
	pop hl
;> if t == PARTY_TO_BOX or t == PARTY_TO_DAYCARE:
	ld a, [wMoveMonType]
	and a ; BOX_TO_PARTY
	jr z, .findOTdest
	cp DAYCARE_TO_PARTY
	jr z, .findOTdest
;>     level = mem[src + MON_LEVEL]
	ld bc, BOXMON_STRUCT_LENGTH
	add hl, bc
	ld a, [hl] ; hl = Level
;>     mem[dest + 3] = level                     # the box record keeps the level here
	inc de
	inc de
	inc de
	ld [de], a ; de = BoxLevel
.findOTdest
;> if t == PARTY_TO_DAYCARE:
;>     ot = addr(wDayCareMonOT)
	ld a, [wMoveMonType]
	cp PARTY_TO_DAYCARE
	ld de, wDayCareMonOT
	jr z, .findOTsrc
;> else:
;>     if t != PARTY_TO_BOX:
;>         names, count = addr(wPartyMonOT), wPartyCount
	dec a
	ld hl, wPartyMonOT
	ld a, [wPartyCount]
	jr nz, .addOToffset
;>     else:
;>         names, count = addr(wBoxMonOT), wBoxCount
	ld hl, wBoxMonOT
	ld a, [wBoxCount]
.addOToffset
;>     ot = names + (count - 1) * NAME_LENGTH
	dec a
	call SkipFixedLengthTextEntries
	ld d, h
	ld e, l
.findOTsrc
;> if t == BOX_TO_PARTY:
;>     ot_src = addr(wBoxMonOT) + wWhichPokemon * NAME_LENGTH
	ld hl, wBoxMonOT
	ld a, [wMoveMonType]
	and a
	jr z, .addOToffset2
;> elif t == DAYCARE_TO_PARTY:
;>     ot_src = addr(wDayCareMonOT)
	ld hl, wDayCareMonOT
	cp DAYCARE_TO_PARTY
	jr z, .copyOT
;> else:
;>     ot_src = addr(wPartyMonOT) + wWhichPokemon * NAME_LENGTH
	ld hl, wPartyMonOT
.addOToffset2
	ld a, [wWhichPokemon]
	call SkipFixedLengthTextEntries
.copyOT
;> CopyData(ot_src, ot, NAME_LENGTH)
	ld bc, NAME_LENGTH
	call CopyData
;> if t == PARTY_TO_DAYCARE:
;>     nick = addr(wDayCareMonName)
	ld a, [wMoveMonType]
; find nick dest
	cp PARTY_TO_DAYCARE
	ld de, wDayCareMonName
	jr z, .findNickSrc
;> else:
;>     if t != PARTY_TO_BOX:
;>         names, count = addr(wPartyMonNicks), wPartyCount
	dec a
	ld hl, wPartyMonNicks
	ld a, [wPartyCount]
	jr nz, .addNickOffset
;>     else:
;>         names, count = addr(wBoxMonNicks), wBoxCount
	ld hl, wBoxMonNicks
	ld a, [wBoxCount]
.addNickOffset
;>     nick = names + (count - 1) * NAME_LENGTH
	dec a
	call SkipFixedLengthTextEntries
	ld d, h
	ld e, l
.findNickSrc
;> if t == BOX_TO_PARTY:
;>     nick_src = addr(wBoxMonNicks) + wWhichPokemon * NAME_LENGTH
	ld hl, wBoxMonNicks
	ld a, [wMoveMonType]
	and a
	jr z, .addNickOffset2
;> elif t == DAYCARE_TO_PARTY:
;>     nick_src = addr(wDayCareMonName)
	ld hl, wDayCareMonName
	cp DAYCARE_TO_PARTY
	jr z, .copyNick
;> else:
;>     nick_src = addr(wPartyMonNicks) + wWhichPokemon * NAME_LENGTH
	ld hl, wPartyMonNicks
.addNickOffset2
	ld a, [wWhichPokemon]
	call SkipFixedLengthTextEntries
.copyNick
;> CopyData(nick_src, nick, NAME_LENGTH)
	ld bc, NAME_LENGTH
	call CopyData
	pop hl
;> if t == BOX_TO_PARTY or t == DAYCARE_TO_PARTY:
	ld a, [wMoveMonType]
	cp PARTY_TO_BOX
	jr z, .done
	cp PARTY_TO_DAYCARE
	jr z, .done
	; returning mon to party, compute level and stats
;>     # back in the party: level and stats from the experience
;>     wMonDataLocation = (t >> 1) + 2
	push hl
	srl a
	add $2
	ld [wMonDataLocation], a
;>     LoadMonData()
	call LoadMonData
;>     level = CalcLevelFromExperience()
	ld b, BANK(CalcLevelFromExperience)
	ld hl, CalcLevelFromExperience
	call Bankswitch
;>     wCurEnemyLevel = level
	ld a, d
	ld [wCurEnemyLevel], a
;>     mem[dest + MON_LEVEL] = level
	pop hl
	ld bc, BOXMON_STRUCT_LENGTH
	add hl, bc ; hl = wPartyMon*Level
	ld [hli], a
;>     CalcStats(dest + MON_HP_EXP - 1, dest + MON_STATS, 1)
	ld d, h
	ld e, l
	ld bc, (MON_HP_EXP - 1) - MON_STATS
	add hl, bc ; hl = wPartyMon*HPExp - 1
	ld b, $1
	call CalcStats
.done
;> return False
	and a
	ret
;@ path: engine/flag_action
;@ def FlagActionPredef() -> c
;@ FlagAction with the registers the predef call saved (wPredefHL, wPredefBC).
;@ test: f = rand_ram(32); mem[wPredefHL] = f >> 8; mem[wPredefHL + 1] = f & 0xFF
FlagActionPredef:
;> return FlagAction(wPredefHL[0] << 8 | wPredefHL[1], wPredefBC[1], wPredefBC[0])
	call GetPredefRegisters

;@ path: engine/flag_action
;@ def FlagAction(field: hl, bit: c, action: b) -> c
;@ Reset (action 0), set (1) or test (2) bit number `bit` of the bit field at `field`. Returns the bit's byte
;@ after the change, or for a test that byte masked to the bit (nonzero if set).
;@ test: field = rand_ram(32)
FlagAction:
; Perform action b on bit c
; in the bitfield at hl.
;  0: reset
;  1: set
;  2: read
; Return the result in c.

;> # hl, de and bc are kept
	push hl
	push de
	push bc

	; bit
;> shift = bit & 7
	ld a, c
	ld d, a
	and 7
	ld e, a

	; byte
;> offset = bit >> 3
	ld a, d
	srl a
	srl a
	srl a
;> at = field + offset
	add l
	ld l, a
	jr nc, .ok
	inc h
.ok

	; d = 1 << e (bitmask)
;> mask = 1 << shift
	inc e
	ld d, 1
.shift
	dec e
	jr z, .shifted
	sla d
	jr .shift
.shifted

;> if action == FLAG_RESET:
	ld a, b
	and a
	jr z, .reset
;>@reset     mem[at] = mem[at] & ~mask & 0xFF
;>@resetdone     result = mem[at]
;> elif action == FLAG_TEST:
	cp FLAG_TEST
	jr z, .read
;>@read     result = mem[at] & mask
;> else:

; set
;>     mem[at] = mem[at] | mask
	ld b, [hl]
	ld a, d
	or b
	ld [hl], a
;>     result = mem[at]
	jr .done

.reset
;=@reset
	ld b, [hl]
	ld a, d
	xor $ff
	and b
	ld [hl], a
;=@resetdone
	jr .done

.read
;=@read
	ld b, [hl]
	ld a, d
	and b
.done
;> return result
	pop bc
	pop de
	pop hl
	ld c, a
	ret
;@ path: engine/events/heal_party
;@ def HealParty()
;@ Heal the whole party: no status, full HP, and the full PP of each move (keeping the PP Up count). Then the
;@ extra PP from PP Ups are restored for every party member.
;@ test: skip calls RestoreBonusPP, which goes through the predef table (it keeps its registers in wPredefHL/DE/BC)
HealParty:
; Restore HP and PP.

;> mon = addr(wPartyMon1HP)
;> i = 0
	ld hl, wPartySpecies
	ld de, wPartyMon1HP
.healmon
;>@heal while wPartySpecies[i] != 0xFF:
	ld a, [hli]
	cp $ff
	jr z, .done

	push hl
	push de

;>     mem[mon + MON_STATUS - MON_HP] = 0
	ld hl, MON_STATUS - MON_HP
	add hl, de
	xor a
	ld [hl], a

;>     k = 0                                    # an empty slot is read again: the rest is empty too
;>@moves     for _ in range(NUM_MOVES):
	push de
	ld b, NUM_MOVES ; A Pokémon has 4 moves
.pp
;>         move = mem[mon + k + MON_MOVES - MON_HP]
	ld hl, MON_MOVES - MON_HP
	add hl, de

;>         if move:
	ld a, [hl]
	and a
	jr z, .nextmove

;>             pp = mon + k + MON_PP - MON_HP
	dec a
	ld hl, MON_PP - MON_HP
	add hl, de

;>             entry = AddNTimes(Moves, MOVE_LENGTH, move - 1)
	push hl
	push de
	push bc

	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;>             FarCopyData(BANK(Moves), entry, addr(wMoveData), MOVE_LENGTH)
	ld de, wMoveData
	ld a, BANK(Moves)
	call FarCopyData
;>             full = wMoveData[MOVE_PP]
	ld a, [wMoveData + MOVE_PP]

	pop bc
	pop de
	pop hl

;>             k += 1
	inc de
;>             ups = mem[pp] & PP_UP_MASK               # keep the PP Up count
	push bc
	ld b, a
	ld a, [hl]
	and PP_UP_MASK
;>             mem[pp] = u8(ups + full)
	add b
	ld [hl], a
	pop bc

.nextmove
;=@moves
	dec b
	jr nz, .pp
	pop de

;>     mem[mon] = mem[mon + MON_MAXHP - MON_HP]
	ld hl, MON_MAXHP - MON_HP
	add hl, de
	ld a, [hli]
	ld [de], a
;>     mem[mon + 1] = mem[mon + MON_MAXHP - MON_HP + 1]
	inc de
	ld a, [hl]
	ld [de], a

	pop de
	pop hl

;>@mon     mon += PARTYMON_STRUCT_LENGTH
	push hl
	ld bc, PARTYMON_STRUCT_LENGTH
	ld h, d
	ld l, e
	add hl, bc
;=@mon
	ld d, h
	ld e, l
	pop hl
;>@next     i += 1
;=@heal
	jr .healmon

.done
;> wWhichPokemon = 0
	xor a
	ld [wWhichPokemon], a
;> wUsingPPUp = 0
	ld [wUsingPPUp], a

;> for _ in range(wPartyCount or 256):
	ld a, [wPartyCount]
	ld b, a
.ppup
;>     RestoreBonusPP()
	push bc
	call RestoreBonusPP
	pop bc
;>     wWhichPokemon = u8(wWhichPokemon + 1)
	ld hl, wWhichPokemon
	inc [hl]
	dec b
	jr nz, .ppup
	ret
; divide hMoney by hDivideBCDDivisor
; return output in hDivideBCDQuotient (same as hDivideBCDDivisor)
; used only to halve player money upon losing a fight
;@ path: engine/math/bcd
DivideBCDPredef::
;@ path: engine/math/bcd
DivideBCDPredef2::
;@ path: engine/math/bcd
DivideBCDPredef3:: ; only used function
;@ path: engine/math/bcd
;@ def DivideBCDPredef4()
;@ DivideBCD, reached through the predef table.
;@ test: fill_bcd(hMoney, 3); fill_bcd(hDivideBCDDivisor, 3); mem[hDivideBCDDivisor + 2] |= 1
DivideBCDPredef4::
;> DivideBCD()
	call GetPredefRegisters

;@ path: engine/math/bcd
;@ def DivideBCD()
;@ Divide the 6-digit BCD number in hMoney by the one in hDivideBCDDivisor: the quotient replaces the divisor
;@ (hDivideBCDQuotient), the remainder is left in hMoney. Long division, one decimal digit at a time.
;@ test: fill_bcd(hMoney, 3); fill_bcd(hDivideBCDDivisor, 3); mem[hDivideBCDDivisor + 2] |= 1
DivideBCD::
;> for i in range(3):
;>     hDivideBCDBuffer[i] = 0
	xor a
	ldh [hDivideBCDBuffer], a
	ldh [hDivideBCDBuffer+1], a
	ldh [hDivideBCDBuffer+2], a
;> places = 1                                    # quotient digits to work out
	ld d, $1
.mulBy10Loop
; multiply the divisor by 10 until the leading digit is nonzero
; to set up the standard long division algorithm
;> # move the divisor left until its leading digit is nonzero, as in long division on paper
;> while hDivideBCDDivisor[0] & 0xF0 == 0:
	ldh a, [hDivideBCDDivisor]
	and $f0
	jr nz, .next
;>     places += 1
	inc d
;>     high = hDivideBCDDivisor[0] << 4 & 0xF0
	ldh a, [hDivideBCDDivisor]
	swap a
	and $f0
	ld b, a
;>     hDivideBCDDivisor[0] = high | hDivideBCDDivisor[1] >> 4
	ldh a, [hDivideBCDDivisor+1]
	swap a
	ldh [hDivideBCDDivisor+1], a
	and $f
	or b
	ldh [hDivideBCDDivisor], a
;>     high = hDivideBCDDivisor[1] << 4 & 0xF0
	ldh a, [hDivideBCDDivisor+1]
	and $f0
	ld b, a
;>     hDivideBCDDivisor[1] = high | hDivideBCDDivisor[2] >> 4
	ldh a, [hDivideBCDDivisor+2]
	swap a
	ldh [hDivideBCDDivisor+2], a
	and $f
	or b
	ldh [hDivideBCDDivisor+1], a
;>     hDivideBCDDivisor[2] = hDivideBCDDivisor[2] << 4 & 0xFF
	ldh a, [hDivideBCDDivisor+2]
	and $f0
	ldh [hDivideBCDDivisor+2], a
	jr .mulBy10Loop

.next
;> for i in range(6):                            # the assembly writes these steps out six times
	push de
;>@lower     if i: DivideBCD_divDivisorBy10()    # one digit position lower
;>@get     digit = DivideBCD_getNextDigit()      # how often the divisor fits into hMoney
	push de
	call DivideBCD_getNextDigit
	pop de
;>@high     if i % 2 == 0:
;>@high2         hDivideBCDBuffer[i // 2] = digit << 4 & 0xF0
	ld a, b
	swap a
	and $f0
	ldh [hDivideBCDBuffer], a
;>@low     else:
;>@low2         hDivideBCDBuffer[i // 2] |= digit
;>@last     if i + 1 == places:
	dec d
;>@stop         break
	jr z, .next2
;>     # the second digit
;=@lower
	push de
	call DivideBCD_divDivisorBy10
;=@get
	call DivideBCD_getNextDigit
	pop de
;=@low2
	ldh a, [hDivideBCDBuffer]
	or b
	ldh [hDivideBCDBuffer], a
;=@last
	dec d
;=@stop
	jr z, .next2
;>     # the third digit
;=@lower
	push de
	call DivideBCD_divDivisorBy10
;=@get
	call DivideBCD_getNextDigit
	pop de
;=@high2
	ld a, b
	swap a
	and $f0
	ldh [hDivideBCDBuffer+1], a
;=@last
	dec d
;=@stop
	jr z, .next2
;>     # the fourth digit
;=@lower
	push de
	call DivideBCD_divDivisorBy10
;=@get
	call DivideBCD_getNextDigit
	pop de
;=@low2
	ldh a, [hDivideBCDBuffer+1]
	or b
	ldh [hDivideBCDBuffer+1], a
;=@last
	dec d
;=@stop
	jr z, .next2
;>     # the fifth digit
;=@lower
	push de
	call DivideBCD_divDivisorBy10
;=@get
	call DivideBCD_getNextDigit
	pop de
;=@high2
	ld a, b
	swap a
	and $f0
	ldh [hDivideBCDBuffer+2], a
;=@last
	dec d
;=@stop
	jr z, .next2
;>     # the sixth digit
;=@lower
	push de
	call DivideBCD_divDivisorBy10
;=@get
	call DivideBCD_getNextDigit
	pop de
;=@low2
	ldh a, [hDivideBCDBuffer+2]
	or b
	ldh [hDivideBCDBuffer+2], a
.next2
;> for i in range(3):
;>     hDivideBCDQuotient[i] = hDivideBCDBuffer[i]   # where the divisor was
	ldh a, [hDivideBCDBuffer]
	ldh [hDivideBCDQuotient], a ; the same memory location as hDivideBCDDivisor
	ldh a, [hDivideBCDBuffer+1]
	ldh [hDivideBCDQuotient+1], a
	ldh a, [hDivideBCDBuffer+2]
	ldh [hDivideBCDQuotient+2], a
;> for _ in range(6 - places):                   # the digits are left-aligned: move them into place
	pop de
	ld a, $6
	sub d
	and a
	ret z
.divResultBy10loop
;>     DivideBCD_divDivisorBy10()
	push af
	call DivideBCD_divDivisorBy10
	pop af
	dec a
	jr nz, .divResultBy10loop
	ret

;@ path: engine/math/bcd
;@ def DivideBCD_divDivisorBy10()
;@ Shift the 3-byte BCD number in hDivideBCDDivisor one digit to the right (divide by 10).
DivideBCD_divDivisorBy10:
;> low = hDivideBCDDivisor[2] >> 4
	ldh a, [hDivideBCDDivisor+2]
	swap a
	and $f
	ld b, a
;> hDivideBCDDivisor[2] = (hDivideBCDDivisor[1] << 4 & 0xF0) | low
	ldh a, [hDivideBCDDivisor+1]
	swap a
	ldh [hDivideBCDDivisor+1], a
	and $f0
	or b
	ldh [hDivideBCDDivisor+2], a
;> low = hDivideBCDDivisor[1] >> 4
	ldh a, [hDivideBCDDivisor+1]
	and $f
	ld b, a
;> hDivideBCDDivisor[1] = (hDivideBCDDivisor[0] << 4 & 0xF0) | low
	ldh a, [hDivideBCDDivisor]
	swap a
	ldh [hDivideBCDDivisor], a
	and $f0
	or b
	ldh [hDivideBCDDivisor+1], a
;> hDivideBCDDivisor[0] = hDivideBCDDivisor[0] >> 4
	ldh a, [hDivideBCDDivisor]
	and $f
	ldh [hDivideBCDDivisor], a
	ret

;@ path: engine/math/bcd
;@ def DivideBCD_getNextDigit() -> b
;@ Subtract the divisor from hMoney as often as it fits and return how often: one digit of the quotient.
;@ test: fill_bcd(hMoney, 3); fill_bcd(hDivideBCDDivisor, 3); mem[hDivideBCDDivisor] = to_bcd(rand(10, 99)); mem[hMoney] = to_bcd(rand(0, 99))
DivideBCD_getNextDigit:
;> digit = 0
	ld bc, $3
;> while True:
.loop
;>     smaller, _ = StringCmp(hMoney, hDivideBCDDivisor, 3)
	ld de, hMoney ; the dividend
	ld hl, hDivideBCDDivisor
	push bc
	call StringCmp
	pop bc
;>     if smaller:
;>         return digit
	ret c
;>     digit += 1
	inc b
;>     SubBCD(hMoney + 2, hDivideBCDDivisor + 2, 3)
	ld de, hMoney + 2 ; since SubBCD works starting from the least significant digit
	ld hl, hDivideBCDDivisor + 2
	push bc
	call SubBCD
	pop bc
	jr .loop


;@ path: engine/math/bcd
;@ def AddBCDPredef() -> carry
;@ AddBCD with the registers the predef call saved (wPredefDE, wPredefHL, wPredefBC).
;@ test: d = rand_ram(8) + 7; s = rand_ram(8) + 7; fill_bcd(d - 7, 8); fill_bcd(s - 7, 8)
;@ test: mem[wPredefDE] = d >> 8; mem[wPredefDE + 1] = d & 0xFF; mem[wPredefHL] = s >> 8; mem[wPredefHL + 1] = s & 0xFF; mem[wPredefBC + 1] = rand(1, 4)
AddBCDPredef::
;> return AddBCD(wPredefDE[0] << 8 | wPredefDE[1], wPredefHL[0] << 8 | wPredefHL[1], wPredefBC[1])
	call GetPredefRegisters

;@ path: engine/math/bcd
;@ def AddBCD(dest: de, src: hl, count: c) -> carry
;@ Add the count-byte BCD number ending at src to the one ending at dest (big-endian: both point at the last,
;@ lowest byte). If the sum does not fit, dest becomes all 9s and carry is set.
;@ test: count = rand(1, 4); dest = rand_ram(8) + 7; src = rand_ram(8) + 7; fill_bcd(dest - 7, 8); fill_bcd(src - 7, 8)
AddBCD::
;> carry = 0
	and a
	ld b, c
;> for i in range(count):
.add
;>     s = bcd_to_int(mem[dest - i]) + bcd_to_int(mem[src - i]) + carry
	ld a, [de]
	adc [hl]
;>     carry = s >= 100
	daa
;>     mem[dest - i] = to_bcd(s % 100)
	ld [de], a
	dec de
	dec hl
	dec c
	jr nz, .add
;> if carry:
	jr nc, .done
;>     for i in range(count):
;>         mem[dest - i] = 0x99
	ld a, $99
	inc de
.fill
	ld [de], a
	inc de
	dec b
	jr nz, .fill
.done
;> return carry
	ret


;@ path: engine/math/bcd
;@ def SubBCDPredef() -> carry
;@ SubBCD with the registers the predef call saved (wPredefDE, wPredefHL, wPredefBC).
;@ test: d = rand_ram(8) + 7; s = rand_ram(8) + 7; fill_bcd(d - 7, 8); fill_bcd(s - 7, 8)
;@ test: mem[wPredefDE] = d >> 8; mem[wPredefDE + 1] = d & 0xFF; mem[wPredefHL] = s >> 8; mem[wPredefHL + 1] = s & 0xFF; mem[wPredefBC + 1] = rand(1, 4)
SubBCDPredef::
;> return SubBCD(wPredefDE[0] << 8 | wPredefDE[1], wPredefHL[0] << 8 | wPredefHL[1], wPredefBC[1])
	call GetPredefRegisters

;@ path: engine/math/bcd
;@ def SubBCD(dest: de, src: hl, count: c) -> carry
;@ Subtract the count-byte BCD number ending at src from the one ending at dest (both point at the last, lowest
;@ byte). If the result would go below zero, dest becomes 0 and carry is set.
;@ test: count = rand(1, 4); dest = rand_ram(8) + 7; src = rand_ram(8) + 7; fill_bcd(dest - 7, 8); fill_bcd(src - 7, 8)
SubBCD::
;> borrow = 0
	and a
	ld b, c
;> for i in range(count):
.sub
;>     d = bcd_to_int(mem[dest - i]) - bcd_to_int(mem[src - i]) - borrow
	ld a, [de]
	sbc [hl]
;>     borrow = d < 0
	daa
;>     mem[dest - i] = to_bcd(d % 100)
	ld [de], a
	dec de
	dec hl
	dec c
	jr nz, .sub
;> if borrow:
	jr nc, .done
;>     for i in range(count):
;>         mem[dest - i] = 0
	ld a, $00
	inc de
.fill
	ld [de], a
	inc de
	dec b
	jr nz, .fill
;> return borrow
	scf
.done
	ret
;@ path: engine/movie/oak_speech/init_player_data
InitPlayerData:
;@ path: engine/movie/oak_speech/init_player_data
;@ def InitPlayerData2()
;@ New game data: a random trainer ID, empty party, box, bag and PC item lists, 3000 money, no badges, no coins,
;@ no game progress, and the default visibility of all toggleable objects.
;@ test: skip the random ID depends on the carry flag left by the first Random
InitPlayerData2:

;> Random()
	call Random
;> wPlayerID[0] = hRandomSub
	ldh a, [hRandomSub]
	ld [wPlayerID], a

;> Random()
	call Random
;> wPlayerID[1] = hRandomAdd
	ldh a, [hRandomAdd]
	ld [wPlayerID + 1], a

;> wUnusedPlayerDataByte = 0xFF
	ld a, $ff
	ld [wUnusedPlayerDataByte], a

;> InitializeEmptyList(addr(wPartyCount))
	ld hl, wPartyCount
	call InitializeEmptyList
;> InitializeEmptyList(addr(wBoxCount))
	ld hl, wBoxCount
	call InitializeEmptyList
;> InitializeEmptyList(addr(wNumBagItems))
	ld hl, wNumBagItems
	call InitializeEmptyList
;> InitializeEmptyList(addr(wNumBoxItems))
	ld hl, wNumBoxItems
	call InitializeEmptyList

DEF START_MONEY EQU $3000
;> wPlayerMoney[1] = 0x30                        # 3000, BCD
	ld hl, wPlayerMoney + 1
	ld a, HIGH(START_MONEY)
	ld [hld], a
;> wPlayerMoney[0] = 0
	xor a ; LOW(START_MONEY)
	ld [hli], a
;> wPlayerMoney[2] = 0
	inc hl
	ld [hl], a

;> wMonDataLocation = 0
	ld [wMonDataLocation], a

;> wObtainedBadges = 0
	ld hl, wObtainedBadges
	ld [hli], a
	ASSERT wObtainedBadges + 1 == wUnusedObtainedBadges
;> wUnusedObtainedBadges = 0
	ld [hl], a

;> wPlayerCoins[0] = 0
	ld hl, wPlayerCoins
	ld [hli], a
;> wPlayerCoins[1] = 0
	ld [hl], a

;> FillMemory(addr(wGameProgressFlags), addr(wGameProgressFlagsEnd) - addr(wGameProgressFlags), 0)
	ld hl, wGameProgressFlags
	ld bc, wGameProgressFlagsEnd - wGameProgressFlags
	call FillMemory ; clear all game progress flags

;> InitializeToggleableObjectsFlags()
	jp InitializeToggleableObjectsFlags

;@ path: engine/movie/oak_speech/init_player_data
;@ def InitializeEmptyList(list: hl)
;@ An empty list: count 0, then the $FF end marker.
;@ test: list = rand(0xC000, 0xCF00)
InitializeEmptyList:
;> mem[list] = 0
;> mem[list + 1] = 0xFF
	xor a ; count
	ld [hli], a
	dec a ; terminator
	ld [hl], a
	ret
;@ def GetQuantityOfItemInBag() -> b
;@ How many of an item the bag holds (0 if none). The item ID comes in b through the predef call.
;@ test: [mem.__setitem__(wBagItems + i, rand(1, 30) if i % 2 == 0 else rand(1, 99)) for i in range(40)]; mem[wBagItems + 2 * rand(0, 19)] = 0xFF; mem[wPredefBC] = rand(1, 30)
;@ path: engine/items/get_bag_item_quantity
GetQuantityOfItemInBag:
; In: b = item ID
; Out: b = how many of that item are in the bag
;> hl, de, bc = GetPredefRegisters()
;> item = bc >> 8
	call GetPredefRegisters
;> p = addr(wNumBagItems)
	ld hl, wNumBagItems
.loop
;>@lp while True:
;>     p += 1                                  # the next slot
	inc hl
;>     here = mem[p]
;>     p += 1
	ld a, [hli]
;>     if here == 0xFF:
;>@nb         return 0                            # not in the bag
	cp $ff
	jr z, .notInBag
;>     if here == item:
;>@rq         return mem[p]
	cp b
	jr nz, .loop
;=@rq
	ld a, [hl]
	ld b, a
	ret
.notInBag
;=@nb
	ld b, 0
	ret
;@ path: engine/overworld/pathfinding
;@ def FindPathToPlayer()
;@ Plan a path for an NPC to walk to the player, given the distances in steps and the relative position
;@ flags (from CalcPositionOfPlayerRelativeToNPC). Each step reduces whichever distance is still larger;
;@ the directions go to wNPCMovementDirections2, ended by $FF, and are counted in hFindPathNumSteps.
;@ test: hNPCPlayerYDistance = rand(0, 4); hNPCPlayerXDistance = rand(0, 4)
FindPathToPlayer:
;> hFindPathNumSteps = 0
	xor a
	ld hl, hFindPathNumSteps
	ld [hli], a ; hFindPathNumSteps
;> hFindPathFlags = 0
	ld [hli], a ; hFindPathFlags
;> hFindPathYProgress = 0
	ld [hli], a ; hFindPathYProgress
;> hFindPathXProgress = 0
	ld [hl], a  ; hFindPathXProgress
;> p = addr(wNPCMovementDirections2)
	ld hl, wNPCMovementDirections2
	ld de, $0
;> while True:
.loop
;>     dy, _ = CalcDifference(hNPCPlayerYDistance, hFindPathYProgress)
	ldh a, [hFindPathYProgress]
	ld b, a
	ldh a, [hNPCPlayerYDistance] ; Y distance in steps
	call CalcDifference
	ld d, a
;>     if dy == 0:
	and a
	jr nz, .stillHasYProgress
;>         hFindPathFlags = hFindPathFlags | 1 << BIT_PATH_FOUND_Y
	ldh a, [hFindPathFlags]
	set BIT_PATH_FOUND_Y, a
	ldh [hFindPathFlags], a
.stillHasYProgress
;>     dx, _ = CalcDifference(hNPCPlayerXDistance, hFindPathXProgress)
	ldh a, [hFindPathXProgress]
	ld b, a
	ldh a, [hNPCPlayerXDistance] ; X distance in steps
	call CalcDifference
	ld e, a
;>     if dx == 0:
	and a
	jr nz, .stillHasXProgress
;>         hFindPathFlags = hFindPathFlags | 1 << BIT_PATH_FOUND_X
	ldh a, [hFindPathFlags]
	set BIT_PATH_FOUND_X, a
	ldh [hFindPathFlags], a
.stillHasXProgress
;>     if hFindPathFlags == 1 << BIT_PATH_FOUND_X | 1 << BIT_PATH_FOUND_Y:
;>         break
	ldh a, [hFindPathFlags]
	cp (1 << BIT_PATH_FOUND_X) | (1 << BIT_PATH_FOUND_Y)
	jr z, .done
; Compare whether the X distance between the player and the current of the path
; is greater or if the Y distance is. Then, try to reduce whichever is greater.
;>     if dx >= dy:
	ld a, e
	cp d
	jr c, .yDistanceGreater
; x distance is greater
;>         direction = NPC_MOVEMENT_LEFT if hNPCPlayerRelativePosFlags & (1 << BIT_PLAYER_LOWER_X) else NPC_MOVEMENT_RIGHT
	ldh a, [hNPCPlayerRelativePosFlags]
	bit BIT_PLAYER_LOWER_X, a
	jr nz, .playerIsLeftOfNPC
	ld d, NPC_MOVEMENT_RIGHT
	jr .next1
.playerIsLeftOfNPC
	ld d, NPC_MOVEMENT_LEFT
.next1
;>         hFindPathXProgress = u8(hFindPathXProgress + 1)
	ldh a, [hFindPathXProgress]
	add 1
	ldh [hFindPathXProgress], a
	jr .storeDirection
.yDistanceGreater
;>     else:
;>         direction = NPC_MOVEMENT_UP if hNPCPlayerRelativePosFlags & (1 << BIT_PLAYER_LOWER_Y) else NPC_MOVEMENT_DOWN
	ldh a, [hNPCPlayerRelativePosFlags]
	bit BIT_PLAYER_LOWER_Y, a
	jr nz, .playerIsAboveNPC
	ld d, NPC_MOVEMENT_DOWN
	jr .next2
.playerIsAboveNPC
	ld d, NPC_MOVEMENT_UP
.next2
;>         hFindPathYProgress = u8(hFindPathYProgress + 1)
	ldh a, [hFindPathYProgress]
	add 1
	ldh [hFindPathYProgress], a
.storeDirection
;>     mem[p] = direction
;>     p += 1
	ld a, d
	ld [hli], a
;>     hFindPathNumSteps = u8(hFindPathNumSteps + 1)
	ldh a, [hFindPathNumSteps]
	inc a
	ldh [hFindPathNumSteps], a
	jp .loop
.done
;> mem[p] = 0xFF
	ld [hl], $ff
	ret

;@ path: engine/overworld/pathfinding
;@ def CalcPositionOfPlayerRelativeToNPC()
;@ Where is the player compared with NPC hNPCSpriteOffset? The distances in steps (screen pixels / 16) go to
;@ hNPCPlayerYDistance and hNPCPlayerXDistance; BIT_PLAYER_LOWER_Y / _X are set when the NPC is above or
;@ left of the player. With hNPCPlayerRelativePosPerspective set, both bits are flipped (seen from the
;@ player).
;@ test: hNPCSpriteOffset = 16 * rand(1, 15)
CalcPositionOfPlayerRelativeToNPC:
;> hNPCPlayerRelativePosFlags = 0
	xor a
	ldh [hNPCPlayerRelativePosFlags], a
;> py, px = wSpritePlayerStateData1YPixels, wSpritePlayerStateData1XPixels
	ld a, [wSpritePlayerStateData1YPixels]
	ld d, a
	ld a, [wSpritePlayerStateData1XPixels]
	ld e, a
;>@npc npc = addr(wSpriteStateData1) + hNPCSpriteOffset + SPRITESTATEDATA1_YPIXELS
	ld hl, wSpriteStateData1
	ldh a, [hNPCSpriteOffset]
	add l
	add SPRITESTATEDATA1_YPIXELS
	ld l, a
;=@npc
	jr nc, .noCarry
	inc h
.noCarry
;> distance, above = CalcDifference(mem[npc], py)
	ld a, d
	ld b, a
	ld a, [hli] ; NPC sprite screen Y position in pixels
	call CalcDifference
;> if above:
	jr nc, .NPCSouthOfOrAlignedWithPlayer
; NPC north of player
;>     hNPCPlayerRelativePosFlags = hNPCPlayerRelativePosFlags | 1 << BIT_PLAYER_LOWER_Y
	push hl
	ld hl, hNPCPlayerRelativePosFlags
	bit BIT_PLAYER_LOWER_Y, [hl]
	set BIT_PLAYER_LOWER_Y, [hl]
	pop hl
	jr .divideYDistance
.NPCSouthOfOrAlignedWithPlayer
;> else:
;>     hNPCPlayerRelativePosFlags = hNPCPlayerRelativePosFlags & ~(1 << BIT_PLAYER_LOWER_Y) & 0xFF
	push hl
	ld hl, hNPCPlayerRelativePosFlags
	bit BIT_PLAYER_LOWER_Y, [hl]
	res BIT_PLAYER_LOWER_Y, [hl]
	pop hl
.divideYDistance
;> hDividend2 = distance
	push hl
	ld hl, hDividend2
	ld [hli], a
;> hDivisor2 = 16
	ld a, 16
	ld [hli], a
;> DivideBytes()
	call DivideBytes ; divide Y absolute distance by 16
;> hNPCPlayerYDistance = hQuotient2
	ld a, [hl] ; quotient
	ldh [hNPCPlayerYDistance], a
;> distance, left = CalcDifference(mem[npc + 2], px)
	pop hl
	inc hl
	ld b, e
	ld a, [hl] ; NPC sprite screen X position in pixels
	call CalcDifference
;> if left:
	jr nc, .NPCEastOfOrAlignedWithPlayer
; NPC west of player
;>     hNPCPlayerRelativePosFlags = hNPCPlayerRelativePosFlags | 1 << BIT_PLAYER_LOWER_X
	push hl
	ld hl, hNPCPlayerRelativePosFlags
	bit BIT_PLAYER_LOWER_X, [hl]
	set BIT_PLAYER_LOWER_X, [hl]
	pop hl
	jr .divideXDistance
.NPCEastOfOrAlignedWithPlayer
;> else:
;>     hNPCPlayerRelativePosFlags = hNPCPlayerRelativePosFlags & ~(1 << BIT_PLAYER_LOWER_X) & 0xFF
	push hl
	ld hl, hNPCPlayerRelativePosFlags
	bit BIT_PLAYER_LOWER_X, [hl]
	res BIT_PLAYER_LOWER_X, [hl]
	pop hl
.divideXDistance
;> hDividend2 = distance
	ldh [hDividend2], a
;> hDivisor2 = 16
	ld a, 16
	ldh [hDivisor2], a
;> DivideBytes()
	call DivideBytes ; divide X absolute distance by 16
;> hNPCPlayerXDistance = hQuotient2
	ldh a, [hQuotient2]
	ldh [hNPCPlayerXDistance], a
;> if hNPCPlayerRelativePosPerspective:
	ldh a, [hNPCPlayerRelativePosPerspective]
	and a
	ret z
;>     hNPCPlayerRelativePosFlags = ~hNPCPlayerRelativePosFlags & 3
	ldh a, [hNPCPlayerRelativePosFlags]
	cpl
	and $3
	ldh [hNPCPlayerRelativePosFlags], a
	ret

;@ path: engine/overworld/pathfinding
;@ def ConvertNPCMovementDirectionsToJoypadMasks()
;@ Turn the hNPCMovementDirections2Index directions in wNPCMovementDirections2 into simulated button
;@ presses, last direction first (the simulated joypad states are played back from the end).
;@ test: hNPCMovementDirections2Index = rand(1, 10)
ConvertNPCMovementDirectionsToJoypadMasks:
;> n = hNPCMovementDirections2Index
;> wNPCMovementDirections2Index = n
	ldh a, [hNPCMovementDirections2Index]
	ld [wNPCMovementDirections2Index], a
;>@src src = addr(wNPCMovementDirections2) + u8(n - 1)     # read backwards from the last step
	dec a
;> out = addr(wSimulatedJoypadStatesEnd)
	ld de, wSimulatedJoypadStatesEnd
;=@src
	ld hl, wNPCMovementDirections2
	add l
	ld l, a
	jr nc, .loop
	inc h
;>@steps while True:
.loop
;>     mem[out] = ConvertNPCMovementDirectionToJoypadMask(mem[src])
	ld a, [hld]
	call ConvertNPCMovementDirectionToJoypadMask
	ld [de], a
;>@back     src -= 1
;>     out += 1
	inc de
;>     hNPCMovementDirections2Index = u8(hNPCMovementDirections2Index - 1)
	ldh a, [hNPCMovementDirections2Index]
	dec a
	ldh [hNPCMovementDirections2Index], a
;>     if hNPCMovementDirections2Index == 0: break
	jr nz, .loop
	ret

;@ path: engine/overworld/pathfinding
;@ def ConvertNPCMovementDirectionToJoypadMask(direction: a) -> a
;@ The button for an NPC movement direction (UP, DOWN, LEFT, RIGHT), or $FF for anything else.
ConvertNPCMovementDirectionToJoypadMask:
;> p = 0x79D2                                   # NPCMovementDirectionsToJoypadMasksTable
	push hl
	ld b, a
	ld hl, NPCMovementDirectionsToJoypadMasksTable
.loop
;>@scan while mem[p] != 0xFF:                   # (direction, button) pairs
	ld a, [hli]
	cp $ff
	jr z, .done
;>     if mem[p] == direction:
	cp b
	jr z, .loadJoypadMask
;>@found         return mem[p + 1]
;>     p += 2
	inc hl
;=@scan
	jr .loop
.loadJoypadMask
;=@found
	ld a, [hl]
.done
;> return 0xFF                                  # (a is still $FF)
	pop hl
	ret

;@ path: engine/overworld/pathfinding
;@ def NPCMovementDirectionsToJoypadMasksTable()
;@ The table (NPC movement direction, button) read by ConvertNPCMovementDirectionToJoypadMask, ended by $FF.
;@ The single `ret` after it is never called.
;@ test: skip a data table, not code
NPCMovementDirectionsToJoypadMasksTable:
	db NPC_MOVEMENT_UP, PAD_UP
	db NPC_MOVEMENT_DOWN, PAD_DOWN
	db NPC_MOVEMENT_LEFT, PAD_LEFT
	db NPC_MOVEMENT_RIGHT, PAD_RIGHT
	db $ff

; unreferenced
	ret
;@ path: engine/gfx/hp_bar
;@ def HPBarLength() -> e
;@ GetHPBarLength with the HP and max HP from the predef's bc and de.
;@ test: hLoadedROMBank = 3; m = rand(1, 999); h = rand(0, m); mem[wPredefDE] = m >> 8; mem[wPredefDE + 1] = m & 0xFF; mem[wPredefBC] = h >> 8; mem[wPredefBC + 1] = h & 0xFF
HPBarLength:
;> _, max_hp, hp = GetPredefRegisters()
;> return GetHPBarLength(hp, max_hp)
	call GetPredefRegisters

; calculates bc * 48 / de, the number of pixels the HP bar has
; the result is always at least 1
;@ path: engine/gfx/hp_bar
;@ def GetHPBarLength(hp: bc, max_hp: de) -> e
;@ The filled length of a 48-pixel HP bar: hp * 48 / max_hp, at least 1. A max HP of 256 or more is divided by 4
;@ first, together with the product, so the divisor fits in a byte.
;@ test: hLoadedROMBank = 3; max_hp = rand(1, 999); hp = rand(0, max_hp)
GetHPBarLength:
;> hMultiplicand[0] = 0
	push hl
	xor a
	ld hl, hMultiplicand
	ld [hli], a
;> hMultiplicand[1] = hp >> 8
;> hMultiplicand[2] = hp & 0xFF
	ld a, b
	ld [hli], a
	ld a, c
	ld [hli], a
;> hMultiplier = 48                              # the bar is 48 pixels long
	ld [hl], $30
;> Multiply()
	call Multiply      ; 48 * bc (hp bar is 48 pixels long)
;> if max_hp >> 8:                               # the divisor must fit in a byte: divide both by 4
	ld a, d
	and a
	jr z, .maxHPSmaller256
;>     max_hp >>= 2
	srl d              ; make HP in de fit into 1 byte by dividing by 4
	rr e
	srl d
	rr e
;>     product = hMultiplicand[1] << 8 | hMultiplicand[2]
	ldh a, [hMultiplicand+1]
	ld b, a
	ldh a, [hMultiplicand+2]
;>     product >>= 2
	srl b              ; divide multiplication result as well
	rr a
	srl b
	rr a
;>     hMultiplicand[2] = product & 0xFF
;>     hMultiplicand[1] = product >> 8
	ldh [hMultiplicand+2], a
	ld a, b
	ldh [hMultiplicand+1], a
.maxHPSmaller256
;> hDivisor = max_hp & 0xFF
	ld a, e
	ldh [hDivisor], a
;> Divide(4)
	ld b, $4
	call Divide
;> pixels = hMultiplicand[2]
	ldh a, [hMultiplicand+2]
	ld e, a            ; e = bc * 48 / de (num of pixels of HP bar)
	pop hl
;> if pixels:
;>     return pixels
	and a
	ret nz
;> return 1                                      # at least one pixel
	ld e, $1           ; make result at least 1
	ret

; predef $48
;@ path: engine/gfx/hp_bar
UpdateHPBar:
;@ path: engine/gfx/hp_bar
;@ def UpdateHPBar2()
;@ Animate the HP bar at the predef's hl from wHPBarOldHP to wHPBarNewHP one HP at a time, redrawing the bar
;@ whenever its length changes and the HP number on the way (not in the enemy's box).
;@ test: skip animates over many frames
UpdateHPBar2:
;> old = wHPBarOldHP[0] | wHPBarOldHP[1] << 8
	push hl
	ld hl, wHPBarOldHP
	ld a, [hli]
	ld c, a      ; old HP into bc
	ld a, [hli]
	ld b, a
;> target = wHPBarNewHP[0] | wHPBarNewHP[1] << 8
	ld a, [hli]
	ld e, a      ; new HP into de
	ld d, [hl]
	pop hl
;> difference = UpdateHPBar_CalcHPDifference(old, target)
	push de
	push bc
	call UpdateHPBar_CalcHPDifference
;> wHPBarHPDifference[1] = difference & 0xFF
;> wHPBarHPDifference[0] = difference >> 8
	ld a, e
	ld [wHPBarHPDifference+1], a
	ld a, d
	ld [wHPBarHPDifference], a
	pop bc
	pop de
;> if target == old:
;>     return
	call UpdateHPBar_CompareNewHPToOldHP
	ret z
;> wHPBarDelta = 0xFF if target < old else 1    # the bar shrinks or grows
	ld a, $ff
	jr c, .HPdecrease
	ld a, $1
.HPdecrease
	ld [wHPBarDelta], a
;> bar, _, _ = GetPredefRegisters()
	call GetPredefRegisters
	ld a, [wHPBarNewHP]
	ld e, a
	ld a, [wHPBarNewHP+1]
	ld d, a
.animateHPBarLoop
;> while True:                                   # one HP per round
;>     hp = wHPBarOldHP[0] | wHPBarOldHP[1] << 8
	push de
	ld a, [wHPBarOldHP]
	ld c, a
	ld a, [wHPBarOldHP+1]
	ld b, a
;>     if hp == target:
;>         break
	call UpdateHPBar_CompareNewHPToOldHP
	jr z, .animateHPBarDone
;>     if target < hp:
	jr nc, .HPIncrease
; HP decrease
;>         hp -= 1
	dec bc        ; subtract 1 HP
;>         wHPBarNewHP[0] = hp & 0xFF
;>         wHPBarNewHP[1] = hp >> 8
	ld a, c
	ld [wHPBarNewHP], a
	ld a, b
	ld [wHPBarNewHP+1], a
;>         new_pixels, old_pixels = UpdateHPBar_CalcOldNewHPBarPixels()
	call UpdateHPBar_CalcOldNewHPBarPixels
;>         change = u8(old_pixels - new_pixels)
	ld a, e
	sub d         ; calc pixel difference
	jr .ok
.HPIncrease
;>     else:
;>         hp += 1
	inc bc        ; add 1 HP
;>         wHPBarNewHP[0] = hp & 0xFF
;>         wHPBarNewHP[1] = hp >> 8
	ld a, c
	ld [wHPBarNewHP], a
	ld a, b
	ld [wHPBarNewHP+1], a
;>         new_pixels, old_pixels = UpdateHPBar_CalcOldNewHPBarPixels()
	call UpdateHPBar_CalcOldNewHPBarPixels
;>         change = u8(new_pixels - old_pixels)
	ld a, d
	sub e         ; calc pixel difference
.ok
;>     UpdateHPBar_PrintHPNumber(bar)
	call UpdateHPBar_PrintHPNumber
;>     if change:                                # the bar's length changes
;>         UpdateHPBar_AnimateHPBar(bar, change, old_pixels, 0)
	and a
	jr z, .noPixelDifference
	call UpdateHPBar_AnimateHPBar
.noPixelDifference
;>     wHPBarOldHP[0] = wHPBarNewHP[0]
;>     wHPBarOldHP[1] = wHPBarNewHP[1]
	ld a, [wHPBarNewHP]
	ld [wHPBarOldHP], a
	ld a, [wHPBarNewHP+1]
	ld [wHPBarOldHP+1], a
	pop de
	jr .animateHPBarLoop
.animateHPBarDone
;> wHPBarOldHP[0] = target & 0xFF
;> wHPBarOldHP[1] = target >> 8
	pop de
	ld a, e
	ld [wHPBarOldHP], a
	ld a, d
	ld [wHPBarOldHP+1], a
;> pixels = 0
;> if target:
	or e
	jr z, .monFainted
;>     pixels = UpdateHPBar_CalcOldNewHPBarPixels()[1]
	call UpdateHPBar_CalcOldNewHPBarPixels
	ld d, e
.monFainted
;> UpdateHPBar_PrintHPNumber(bar)
	call UpdateHPBar_PrintHPNumber
;> UpdateHPBar_AnimateHPBar(bar, 1, pixels, 0)   # the final length
	ld a, $1
	call UpdateHPBar_AnimateHPBar
;> Delay3()
	jp Delay3

; animates the HP bar going up or down for (a) ticks (two waiting frames each)
; stops prematurely if bar is filled up
; e: current health (in pixels) to start with
;@ path: engine/gfx/hp_bar
;@ def UpdateHPBar_AnimateHPBar(bar: hl, ticks: a, pixels: e, sliver: c)
;@ Draw the HP bar at `bar` with `pixels` pixels, wait two frames and step the length by wHPBarDelta, `ticks`
;@ times, stopping early once it would leave the 0-48 range.
;@ test: skip waits for frames
UpdateHPBar_AnimateHPBar:
;> for _ in range(ticks):
	push hl
.barAnimationLoop
;>     DrawHPBar(bar, 6, pixels, sliver)
	push af
	push de
	ld d, $6
	call DrawHPBar
;>     DelayFrames(2)
;>     sliver = 0
	ld c, 2
	call DelayFrames
;>     following = u8(pixels + wHPBarDelta)
	pop de
	ld a, [wHPBarDelta] ; +1 or -1
	add e
;>     if following >= 49:                       # beyond full or empty
	cp $31
	jr nc, .barFilledUp
;>@stop         return
;>     pixels = following
	ld e, a
	pop af
	dec a
	jr nz, .barAnimationLoop
	pop hl
	ret
.barFilledUp
;=@stop
	pop af
	pop hl
	ret

; compares old HP and new HP and sets c and z flags accordingly
;@ path: engine/gfx/hp_bar
;@ def UpdateHPBar_CompareNewHPToOldHP(old: bc, new: de) -> (carry, zero)
;@ Compare two HP values: carry if new < old, zero if they are equal.
;@ test: old = rand(0, 999); new = rand(0, 999)
UpdateHPBar_CompareNewHPToOldHP:
;> return new < old, new == old
	ld a, d
	sub b
	ret nz
	ld a, e
	sub c
	ret

; calcs HP difference between bc and de (into de)
;@ path: engine/gfx/hp_bar
;@ def UpdateHPBar_CalcHPDifference(old: bc, new: de) -> de
;@ How far apart two HP values are.
;@ test: old = rand(0, 999); new = rand(0, 999)
UpdateHPBar_CalcHPDifference:
;> high = (new >> 8) - (old >> 8)
	ld a, d
	sub b
;> if high < 0:                                  # the old HP is greater
;>@old     diff = old - new
;>@oldret     return diff
	jr c, .oldHPGreater
;> if high == 0:                                 # the high bytes match: the low ones decide
	jr z, .testLowerByte
;>@low     if new & 0xFF < old & 0xFF:
;>@old2         diff = old - new
;>@oldret2         return diff
;>@same     if new & 0xFF == old & 0xFF:
;>@zero         return 0
.newHPGreater
;> diff = new - old                              # the new HP is greater
	ld a, e
	sub c
	ld e, a
	ld a, d
	sbc b
	ld d, a
;> return diff
	ret
.oldHPGreater
;> # .oldHPGreater: old - new, the low bytes first
;=@old
	ld a, c
	sub e
	ld e, a
	ld a, b
	sbc d
	ld d, a
;=@oldret
	ret
.testLowerByte
;> # .testLowerByte: compare the low bytes
;=@low
	ld a, e
	sub c
	jr c, .oldHPGreater
;=@same
	jr nz, .newHPGreater
;=@zero
	ld de, $0
	ret

;@ path: engine/gfx/hp_bar
;@ def UpdateHPBar_PrintHPNumber(bar: hl)
;@ Print wHPBarOldHP over the old number next to (party menu) or below the HP bar at `bar`, then wait a frame;
;@ not for the enemy's box, which shows no number.
;@ test: skip waits a frame
UpdateHPBar_PrintHPNumber:
;> if wHPBarType == 0:
;>     return
	push af
	push de
	ld a, [wHPBarType]
	and a
	jr z, .done ; don't print number in enemy HUD
; convert from little-endian to big-endian for PrintNumber
;> wHPBarTempHP[0] = wHPBarOldHP[1]                 # PrintNumber wants big-endian
;> wHPBarTempHP[1] = wHPBarOldHP[0]
	ld a, [wHPBarOldHP]
	ld [wHPBarTempHP + 1], a
	ld a, [wHPBarOldHP + 1]
	ld [wHPBarTempHP], a
;> # (bar is kept)
	push hl
;> if hUILayoutFlags >> BIT_PARTY_MENU_HP_BAR & 1:   # the party menu: right of the bar
	ldh a, [hUILayoutFlags]
	bit BIT_PARTY_MENU_HP_BAR, a
	jr z, .hpBelowBar
;>     offset = 9
	ld de, $9
	jr .next
.hpBelowBar
;> else:                                         # elsewhere: below it
;>     offset = SCREEN_WIDTH + 1
	ld de, $15
.next
;> at = bar + offset
	add hl, de
;> for i in range(3):
;>     mem[at + i] = charmap(' ')[0]
	push hl
	ld a, ' '
	ld [hli], a
	ld [hli], a
	ld [hli], a
;> PrintNumber(addr(wHPBarTempHP), at, 2, 3)
	pop hl
	ld de, wHPBarTempHP
	ld bc, ((2) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> DelayFrame()
	call DelayFrame
	pop hl
.done
	pop de
	pop af
	ret

; calcs number of HP bar pixels for old and new HP value
; d: new pixels
; e: old pixels
;@ path: engine/gfx/hp_bar
;@ def UpdateHPBar_CalcOldNewHPBarPixels() -> (d, e)
;@ The HP bar lengths for wHPBarNewHP and wHPBarOldHP out of wHPBarMaxHP: returns (new, old).
;@ test: hLoadedROMBank = 3; m = rand(1, 999); o = rand(0, m); n = rand(0, m); mem[wHPBarMaxHP] = m & 0xFF; mem[wHPBarMaxHP + 1] = m >> 8; mem[wHPBarOldHP] = o & 0xFF; mem[wHPBarOldHP + 1] = o >> 8; mem[wHPBarNewHP] = n & 0xFF; mem[wHPBarNewHP + 1] = n >> 8
UpdateHPBar_CalcOldNewHPBarPixels:
;> max_hp = wHPBarMaxHP[0] | wHPBarMaxHP[1] << 8
	push hl
	ld hl, wHPBarMaxHP
	ld a, [hli]  ; max HP into de
	ld e, a
	ld a, [hli]
	ld d, a
;> old_hp = wHPBarOldHP[0] | wHPBarOldHP[1] << 8
	ld a, [hli]  ; old HP into bc
	ld c, a
	ld a, [hli]
	ld b, a
;> new_hp = wHPBarNewHP[0] | wHPBarNewHP[1] << 8
	ld a, [hli]  ; new HP into hl
	ld h, [hl]
	ld l, a
;> old = GetHPBarLength(old_hp, max_hp)
	push hl
	push de
	call GetHPBarLength ; calc num pixels for old HP
	ld a, e
;> new = GetHPBarLength(new_hp, max_hp)
	pop de
	pop bc
	push af
	call GetHPBarLength ; calc num pixels for new HP
	pop af
;> return new, old
	ld d, e
	ld e, a
	pop hl
	ret
; prints text for bookshelves in buildings without sign events
;@ path: engine/events/hidden_events/bookshelves
;@ def PrintBookshelfText()
;@ The player inspects something while facing up: if the tile above is a bookshelf, statue or similar
;@ object of this tileset (BookshelfTileIDs: tileset, tile, text), print its text. Otherwise try the card
;@ key doors.
;@ test: skip prints a text
PrintBookshelfText::
;> if wSpritePlayerStateData1FacingDirection == SPRITE_FACING_UP:
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	jr nz, .noMatch
; facing up
;>     tileset = wCurMapTileset
	ld a, [wCurMapTileset]
	ld b, a
;>     tile = mem[coord(8, 7)]                     # the tile above the player
	ld a, [(7) * SCREEN_WIDTH + (8) + wTileMap]
	ld c, a
;>     p = BookshelfTileIDs
	ld hl, BookshelfTileIDs
.loop
;>     while mem[p] != 0xFF:                    # (tileset, tile, text)
	ld a, [hli]
	cp $ff
	jr z, .noMatch
;>         if mem[p] == tileset and mem[p + 1] == tile:
	cp b
	jr nz, .nextBookshelfEntry1
	ld a, [hli]
	cp c
	jr nz, .nextBookshelfEntry2
;>             EnableAutoTextBoxDrawing()
	ld a, [hl]
	push af
	call EnableAutoTextBoxDrawing
	pop af
;>             PrintPredefTextID(mem[p + 2])
	call PrintPredefTextID
;>             hInteractedWithBookshelf = 0             # found
	xor a
	ldh [hInteractedWithBookshelf], a
;>             return
	ret
.nextBookshelfEntry1
;>         p += 3
	inc hl
.nextBookshelfEntry2
	inc hl
	jr .loop
.noMatch
;> hInteractedWithBookshelf = 0xFF
	ld a, $ff
	ldh [hInteractedWithBookshelf], a
;> PrintCardKeyText()                           # in another bank
	ld b, BANK(PrintCardKeyText)
	ld hl, PrintCardKeyText
	jp Bankswitch


;@ path: engine/events/hidden_events/bookshelves
BookshelfTileIDs:
	; tileset id, bookshelf tile id, text id
	db PLATEAU, $30
	db (IndigoPlateauStatues_id - TextPredefs) / 2 + 1
	db HOUSE, $3D
	db (TownMapText_id - TextPredefs) / 2 + 1
	db HOUSE, $1E
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db MANSION, $32
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db REDS_HOUSE_1, $32
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db LAB, $28
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db LOBBY, $16
	db (ElevatorText_id - TextPredefs) / 2 + 1
	db GYM, $1D
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db DOJO, $1D
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db GATE, $22
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db MART, $54
	db (PokemonStuffText_id - TextPredefs) / 2 + 1
	db MART, $55
	db (PokemonStuffText_id - TextPredefs) / 2 + 1
	db POKECENTER, $54
	db (PokemonStuffText_id - TextPredefs) / 2 + 1
	db POKECENTER, $55
	db (PokemonStuffText_id - TextPredefs) / 2 + 1
	db LOBBY, $50
	db (PokemonStuffText_id - TextPredefs) / 2 + 1
	db LOBBY, $52
	db (PokemonStuffText_id - TextPredefs) / 2 + 1
	db SHIP, $36
	db (BookOrSculptureText_id - TextPredefs) / 2 + 1
	db -1 ; end
;@ path: engine/events/hidden_events/indigo_plateau_statues
;@ def IndigoPlateauStatues() -> hl
;@ The statues at the Indigo Plateau: the first line, then one of two texts depending on which statue
;@ (even or odd x).
;@ test: skip a text script: the code after text_asm is run by the text engine
IndigoPlateauStatues::
	db TX_START_ASM
;> PrintText(IndigoPlateauStatuesText1)
	ld hl, IndigoPlateauStatuesText1
	call PrintText
;>@which text = IndigoPlateauStatuesText2 if wXCoord & 1 else IndigoPlateauStatuesText3   # which statue
	ld a, [wXCoord]
	bit 0, a ; even or odd?
	ld hl, IndigoPlateauStatuesText2
	jr nz, .ok
;=@which
	ld hl, IndigoPlateauStatuesText3
.ok
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/events/hidden_events/indigo_plateau_statues
IndigoPlateauStatuesText1:
	db TX_FAR
	dw _IndigoPlateauStatuesText1
	db BANK(_IndigoPlateauStatuesText1)
	db TX_END

;@ path: engine/events/hidden_events/indigo_plateau_statues
IndigoPlateauStatuesText2:
	db TX_FAR
	dw _IndigoPlateauStatuesText2
	db BANK(_IndigoPlateauStatuesText2)
	db TX_END

;@ path: engine/events/hidden_events/indigo_plateau_statues
IndigoPlateauStatuesText3:
	db TX_FAR
	dw _IndigoPlateauStatuesText3
	db BANK(_IndigoPlateauStatuesText3)
	db TX_END
;@ path: engine/events/hidden_events/book_or_sculpture
;@ def BookOrSculptureText() -> hl
;@ A shelf of Pokémon books, except for the Diglett sculpture in Celadon Mansion.
;@ test: skip a text script: the code after text_asm is run by the text engine
BookOrSculptureText::
	db TX_START_ASM
;> text = PokemonBooksText
	ld hl, PokemonBooksText
;> if wCurMapTileset == MANSION and mem[coord(8, 6)] == 0x38:    # the sculpture's tile
	ld a, [wCurMapTileset]
	cp MANSION ; Celadon Mansion tileset
	jr nz, .ok
	ld a, [(6) * SCREEN_WIDTH + (8) + wTileMap]
	cp $38
	jr nz, .ok
;>     text = DiglettSculptureText
	ld hl, DiglettSculptureText
.ok
;> PrintText(text)
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/events/hidden_events/book_or_sculpture
PokemonBooksText:
	db TX_FAR
	dw _PokemonBooksText
	db BANK(_PokemonBooksText)
	db TX_END

;@ path: engine/events/hidden_events/book_or_sculpture
DiglettSculptureText:
	db TX_FAR
	dw _DiglettSculptureText
	db BANK(_DiglettSculptureText)
	db TX_END
;@ path: engine/events/hidden_events/elevator
ElevatorText::
	db TX_FAR
	dw _ElevatorText
	db BANK(_ElevatorText)
	db TX_END
;@ path: engine/events/hidden_events/town_map
;@ def TownMapText() -> hl
;@ "A TOWN MAP." on a wall: after the text, the Town Map opens; closing it ends the text.
;@ test: skip a text script: the code after text_asm is run by the text engine
TownMapText::
	db TX_FAR
	dw _TownMapText
	db BANK(_TownMapText)
	db TX_PROMPT_BUTTON
	db TX_START_ASM
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> hWY = 0
	xor a
	ldh [hWY], a
;> hAutoBGTransferEnabled = 1
	inc a
	ldh [hAutoBGTransferEnabled], a
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> DisplayTownMap()                             # in another bank
	ld b, BANK(DisplayTownMap)
	ld hl, DisplayTownMap
	call Bankswitch
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> CloseTextDisplay()                           # it returns through TextScriptEnd
;> return TextScriptEnd()
	ld de, TextScriptEnd
	push de
	ldh a, [hLoadedROMBank]
	push af
	jp CloseTextDisplay
;@ path: engine/events/hidden_events/pokemon_stuff
PokemonStuffText::
	db TX_FAR
	dw _PokemonStuffText
	db BANK(_PokemonStuffText)
	db TX_END


