	db $1b, $1f, $39, $21, $39, $21, $1b, $1f, $15, $1f, $12, $1f, $0d, $0e, $03, $03
	db $00, $00, $00, $00, $00, $00, $80, $80, $c0, $c0, $20, $20, $e0, $20, $c0, $c0
;@ path: gfx/font
PlayerCharacterTitleGraphicsEnd:


SECTION "Battle Engine 1", ROMX

; returns whether the player is one tile outside the map in Z
;@ path: engine/overworld/is_player_just_outside_map
;@ def IsPlayerJustOutsideMap() -> zero
;@ Has the player stepped just past the edge of the map? True when a coordinate is -1 or twice the map's
;@ height or width (coordinates count in steps, dimensions in blocks of 2x2 steps).
;@ test: wCurMapHeight = rand(0, 40); wCurMapWidth = rand(0, 40); wYCoord = [0xFF, 2 * wCurMapHeight, rand(0, 80)][rand(0, 2)]; wXCoord = [0xFF, 2 * wCurMapWidth, rand(0, 80)][rand(0, 2)]
IsPlayerJustOutsideMap:
;> if wYCoord == u8(2 * wCurMapHeight) or wYCoord == 0xFF:    # through .compareCoordWithMapDimension
;>     return True
	ld a, [wYCoord]
	ld b, a
	ld a, [wCurMapHeight]
	call .compareCoordWithMapDimension
	ret z
;> return wXCoord == u8(2 * wCurMapWidth) or wXCoord == 0xFF
	ld a, [wXCoord]
	ld b, a
	ld a, [wCurMapWidth]
.compareCoordWithMapDimension
;> # .compareCoordWithMapDimension: coordinate == 2 * dimension, or -1
	add a
	cp b
	ret z
	inc b
	ret
;@ path: engine/pokemon/status_screen
;@ def DrawHP() -> e
;@ The HP bar and HP numbers of wLoadedMon on the status screen, at the predef's hl. Returns the bar length
;@ in pixels.
DrawHP:
; Draws the HP bar in the stats screen
;> hl, _, _ = GetPredefRegisters()
;> return DrawHP_(1, hl)
	call GetPredefRegisters
	ld a, $1
	jr DrawHP_

;@ path: engine/pokemon/status_screen
;@ def DrawHP2() -> e
;@ The HP bar and HP numbers of wLoadedMon in the party menu, at the predef's hl.
DrawHP2:
; Draws the HP bar in the party screen
;> hl, _, _ = GetPredefRegisters()
;> return DrawHP_(2, hl)
	call GetPredefRegisters
	ld a, $2

;@ path: engine/pokemon/status_screen
;@ def DrawHP_(bar_type: a, dest: hl) -> e
;@ Draw wLoadedMon's HP bar at dest (6 tiles of 8 pixels, filled in proportion to HP / max HP) and print
;@ "HP/MAX" right of it in the party menu, or below it on the status screen. Returns the bar length in pixels.
;@ test: skip the bar length comes from the HPBarLength predef
DrawHP_:
;> wHPBarType = bar_type
	ld [wHPBarType], a
	push hl
;> hp = mem[wLoadedMonHP] << 8 | mem[wLoadedMonHP + 1]
	ld a, [wLoadedMonHP]
	ld b, a
	ld a, [wLoadedMonHP + 1]
	ld c, a
;> if hp == 0:
	or b
	jr nz, .nonzeroHP
;>     pixels = sliver = 0
	xor a
	ld c, a
	ld e, a
	ld a, $6
	ld d, a
	jp .drawHPBarAndPrintFraction
.nonzeroHP
;> else:
;>     max_hp = mem[wLoadedMonMaxHP] << 8 | mem[wLoadedMonMaxHP + 1]
	ld a, [wLoadedMonMaxHP]
	ld d, a
	ld a, [wLoadedMonMaxHP + 1]
	ld e, a
;>     pixels = GetHPBarLength(hp, max_hp)       # through the predef table (HPBarLength)
	ld a, (HPBarLengthPredef - PredefPointers) / 3
	call Predef
;>     sliver = 6
	ld a, $6
	ld d, a
	ld c, a
.drawHPBarAndPrintFraction
;> DrawHPBar(dest, 6, pixels, sliver)            # 6 tiles
	pop hl
	push de
	push hl
	push hl
	call DrawHPBar
	pop hl
;> if hUILayoutFlags >> BIT_PARTY_MENU_HP_BAR & 1:
;>     at = dest + 9                             # right of the bar (party menu)
	ldh a, [hUILayoutFlags]
	bit BIT_PARTY_MENU_HP_BAR, a
	jr z, .printFractionBelowBar
	ld bc, $9 ; right of bar
	jr .printFraction
.printFractionBelowBar
;> else:
;>     at = dest + SCREEN_WIDTH + 1              # below it
	ld bc, SCREEN_WIDTH + 1 ; below bar
.printFraction
;> at = PrintNumber(wLoadedMonHP, at, 2, 3)
	add hl, bc
	ld de, wLoadedMonHP
	ld bc, ((2) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> mem[at] = charmap('/')[0]
	ld a, '/'
	ld [hli], a
;> PrintNumber(wLoadedMonMaxHP, at + 1, 2, 3)
	ld de, wLoadedMonMaxHP
	ld bc, ((2) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> return pixels
	pop hl
	pop de
	ret

;@ path: engine/pokemon/status_screen
;@ def StatusScreen()
;@ The first page of a Pokémon's summary: picture, name, number, level, HP, status, types, original trainer and
;@ ID, and the four stats. Box and day-care Pokémon get their stats worked out from their level first.
;@ test: skip draws the screen and waits for a button
StatusScreen:
;> LoadMonData()
	call LoadMonData
;> if wMonDataLocation >= BOX_DATA:              # box and day care: the stats come from the level
	ld a, [wMonDataLocation]
	cp BOX_DATA
	jr c, .DontRecalculate
; mon is in a box or daycare
;>     mem[wLoadedMonLevel] = mem[wLoadedMonBoxLevel]
;>     wCurEnemyLevel = mem[wLoadedMonBoxLevel]
	ld a, [wLoadedMonBoxLevel]
	ld [wLoadedMonLevel], a
	ld [wCurEnemyLevel], a
;>     CalcStats(wLoadedMonHPExp - 1, wLoadedMonStats, 1)
	ld hl, wLoadedMonHPExp - 1
	ld de, wLoadedMonStats
	ld b, $1
	call CalcStats
.DontRecalculate
;> wStatusFlags2 = wStatusFlags2 | 1 << BIT_NO_AUDIO_FADE_OUT
	ld hl, wStatusFlags2
	set BIT_NO_AUDIO_FADE_OUT, [hl]
;> rAUDVOL = 0x33                                # music quieter while the cry plays
	ld a, $33
	ldh [rAUDVOL], a ; Reduce the volume
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;> # the box lines and the bold P, from the battle HUD and font graphics
;> CopyVideoDataDouble(vChars2 + 0x6D * 16, BattleHudTiles1, BANK(BattleHudTiles1), 3)
	ld de, BattleHudTiles1  ; source
	ld hl, vChars2 + TILE_SIZE * $6d ; dest
	ld bc, ((BANK(BattleHudTiles1)) & $ff) << 8 + ((3) & $ff)
	call CopyVideoDataDouble ; ·│ :L and halfarrow line end
;> CopyVideoDataDouble(vChars2 + 0x78 * 16, BattleHudTiles2, BANK(BattleHudTiles2), 1)
	ld de, BattleHudTiles2
	ld hl, vChars2 + TILE_SIZE * $78
	ld bc, ((BANK(BattleHudTiles2)) & $ff) << 8 + ((1) & $ff)
	call CopyVideoDataDouble ; │
;> CopyVideoDataDouble(vChars2 + 0x76 * 16, BattleHudTiles3, BANK(BattleHudTiles3), 2)
	ld de, BattleHudTiles3
	ld hl, vChars2 + TILE_SIZE * $76
	ld bc, ((BANK(BattleHudTiles3)) & $ff) << 8 + ((2) & $ff)
	call CopyVideoDataDouble ; ─ ┘
;> CopyVideoDataDouble(vChars2 + 0x72 * 16, PTile, BANK(PTile), 1)
	ld de, PTile
	ld hl, vChars2 + TILE_SIZE * $72
	ld bc, ((BANK(PTile)) & $ff) << 8 + ((1) & $ff)
	call CopyVideoDataDouble ; bold P (for PP)
;> saved_tile_animations = hTileAnimations
;> hTileAnimations = 0
	ldh a, [hTileAnimations]
	push af
	xor a
	ldh [hTileAnimations], a
;> end = DrawLineBox(coord(19, 1), 6, 10)        # around name, HP and status
	ld hl, (1) * SCREEN_WIDTH + (19) + wTileMap
	ld bc, ((6) & $ff) << 8 + ((10) & $ff)
	call DrawLineBox ; Draws the box around name, HP and status
;> mem[end - 6] = 0xF2                           # "No."
;> mem[end - 7] = 0x74
	ld de, -6
	add hl, de
	ld [hl], '<DOT>'
	dec hl
	ld [hl], '№'
;> DrawLineBox(coord(19, 9), 8, 6)               # around types, ID No. and OT
	ld hl, (9) * SCREEN_WIDTH + (19) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((6) & $ff)
	call DrawLineBox ; Draws the box around types, ID No. and OT
;> PlaceString(TypesIDNoOTText, coord(10, 9))
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ld de, TypesIDNoOTText
	call PlaceString
;> pixels = DrawHP()                             # through the predef table, at coord(11, 3)
	ld hl, (3) * SCREEN_WIDTH + (11) + wTileMap
	ld a, (DrawHPPredef - PredefPointers) / 3
	call Predef
;> GetHealthBarColor(pixels, addr(wStatusScreenHPBarColor))
	ld hl, wStatusScreenHPBarColor
	call GetHealthBarColor
;> RunPaletteCommand(SET_PAL_STATUS_SCREEN)
	ld b, SET_PAL_STATUS_SCREEN
	call RunPaletteCommand
;> if not PrintStatusCondition(wLoadedMonStatus, coord(16, 6)):
	ld hl, (6) * SCREEN_WIDTH + (16) + wTileMap
	ld de, wLoadedMonStatus
	call PrintStatusCondition
	jr nz, .StatusWritten
;>     PlaceString(OKText, coord(16, 6))
	ld hl, (6) * SCREEN_WIDTH + (16) + wTileMap
	ld de, OKText
	call PlaceString ; "OK"
.StatusWritten
;> PlaceString(StatusText, coord(9, 6))
	ld hl, (6) * SCREEN_WIDTH + (9) + wTileMap
	ld de, StatusText
	call PlaceString ; "STATUS/"
;> PrintLevel(coord(14, 2))
	ld hl, (2) * SCREEN_WIDTH + (14) + wTileMap
	call PrintLevel
;> wPokedexNum = wMonHIndex
;> wCurSpecies = wMonHIndex
	ld a, [wMonHIndex]
	ld [wPokedexNum], a
	ld [wCurSpecies], a
;> Predef((IndexToPokedexPredef - PredefPointers) // 3)      # IndexToPokedex
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> PrintNumber(addr(wPokedexNum), coord(3, 7), LEADING_ZEROES | 1, 3)
	ld hl, (7) * SCREEN_WIDTH + (3) + wTileMap
	ld de, wPokedexNum
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber ; Pokémon no.
;> PrintMonType()                                # through the predef table, at coord(11, 10)
	ld hl, (10) * SCREEN_WIDTH + (11) + wTileMap
	ld a, (PrintMonTypePredef - PredefPointers) / 3
	call Predef
;>@lists lists = NamePointers2 + 2 * wMonDataLocation          # the nickname lists
	ld hl, NamePointers2
	call .GetStringPointer
;>@list names = mem16[lists]
;>@one if wMonDataLocation != DAYCARE_DATA:      # the day care has just one
;>@entry     names = SkipFixedLengthTextEntries(names, wWhichPokemon)
;> PlaceString(names, coord(9, 1))
	ld d, h
	ld e, l
	ld hl, (1) * SCREEN_WIDTH + (9) + wTileMap
	call PlaceString ; Pokémon name
;> lists = OTPointers + 2 * wMonDataLocation    # the original trainers' names
	ld hl, OTPointers
	call .GetStringPointer
;>@list2 trainers = mem16[lists]
;>@one2 if wMonDataLocation != DAYCARE_DATA:
;>@entry2     trainers = SkipFixedLengthTextEntries(trainers, wWhichPokemon)
;> PlaceString(trainers, coord(12, 16))
	ld d, h
	ld e, l
	ld hl, (16) * SCREEN_WIDTH + (12) + wTileMap
	call PlaceString ; OT
;> PrintNumber(wLoadedMonOTID, coord(12, 14), LEADING_ZEROES | 2, 5)
	ld hl, (14) * SCREEN_WIDTH + (12) + wTileMap
	ld de, wLoadedMonOTID
	ld bc, ((LEADING_ZEROES | 2) & $ff) << 8 + ((5) & $ff)
	call PrintNumber ; ID Number
;> PrintStatsBox(STATUS_SCREEN_STATS_BOX)
	ld d, STATUS_SCREEN_STATS_BOX
	call PrintStatsBox
;> Delay3()
;> GBPalNormal()
	call Delay3
	call GBPalNormal
;> LoadFlippedFrontSpriteByMonIndex(coord(1, 0))
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	call LoadFlippedFrontSpriteByMonIndex ; draw Pokémon picture
;> PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry
;> WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;> hTileAnimations = saved_tile_animations
	pop af
	ldh [hTileAnimations], a
	ret

.GetStringPointer
;> # .GetStringPointer: the list for wMonDataLocation, then its entry wWhichPokemon
;=@lists
	ld a, [wMonDataLocation]
	add a
	ld c, a
	ld b, 0
	add hl, bc
;=@list
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> # (not for the day care)
;=@one
	ld a, [wMonDataLocation]
	cp DAYCARE_DATA
	ret z
;=@entry
	ld a, [wWhichPokemon]
	jp SkipFixedLengthTextEntries

;@ path: engine/pokemon/status_screen
OTPointers:
	dw wPartyMonOT
	dw wEnemyMonOT
	dw wBoxMonOT
	dw wDayCareMonOT

;@ path: engine/pokemon/status_screen
NamePointers2:
	dw wPartyMonNicks
	dw wEnemyMonNicks
	dw wBoxMonNicks
	dw wDayCareMonName

;@ path: engine/pokemon/status_screen
TypesIDNoOTText:
	db   "TYPE1/"
	db "<NEXT>", "TYPE2/"
	db "<NEXT>", "<ID>№/"
	db "<NEXT>", "OT/"
	db "<NEXT>", "@"

;@ path: engine/pokemon/status_screen
StatusText:
	db "STATUS/@"

;@ path: engine/pokemon/status_screen
OKText:
	db "OK@"

; Draws a line starting from hl high b and wide c
;@ path: engine/pokemon/status_screen
;@ def DrawLineBox(corner: hl, height: b, width: c) -> hl
;@ Draw the status screen's thin box edge: a line down from corner, then left along the bottom, ending in a
;@ half arrow. Returns the address of the arrow.
;@ test: height = rand(1, 8); width = rand(1, 10); corner = rand_ram(200) + 20
DrawLineBox:
;> at = corner
;> for _ in range(height):
	ld de, SCREEN_WIDTH ; New line
.PrintVerticalLine
;>     mem[at] = 0x78                            # │
	ld [hl], $78 ; │
;>     at += SCREEN_WIDTH
	add hl, de
	dec b
	jr nz, .PrintVerticalLine
;> mem[at] = 0x77                                # ┘
	ld [hl], $77 ; ┘
;> at -= 1
	dec hl
;> for _ in range(width):
.PrintHorizLine
;>     mem[at] = 0x76                            # ─
	ld [hl], $76 ; ─
;>     at -= 1
	dec hl
	dec c
	jr nz, .PrintHorizLine
;> mem[at] = 0x6F                                # the half arrow
	ld [hl], $6f ; ← (halfarrow ending)
;> return at
	ret

;@ path: engine/pokemon/status_screen
PTile:
	db $00, $fc, $c6, $c6, $c6, $fc, $c0, $c0

;@ path: engine/pokemon/status_screen
;@ def PrintStatsBox(kind: d)
;@ The box with ATTACK, DEFENSE, SPEED and SPECIAL of wLoadedMon: on the status screen, or (level up, Rare
;@ Candy) in the box on the right.
;@ test: skip prints numbers through PrintNumber's tile drawing
PrintStatsBox:
;> if kind == STATUS_SCREEN_STATS_BOX:
	ld a, d
	ASSERT STATUS_SCREEN_STATS_BOX == 0
	and a
	jr nz, .LevelUpStatsBox ; battle or Rare Candy
;>     TextBoxBorder(coord(0, 8), 8, 8)
	ld hl, (8) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 8
	ld c, 8
	call TextBoxBorder
;>     at, step = coord(1, 9), SCREEN_WIDTH + 5
	ld hl, (9) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, SCREEN_WIDTH + 5 ; one row down and 5 columns right
	jr .PrintStats
.LevelUpStatsBox
;> else:                                         # level up or Rare Candy: on the right
;>     TextBoxBorder(coord(9, 2), 8, 9)
	ld hl, (2) * SCREEN_WIDTH + (9) + wTileMap
	ld b, 8
	ld c, 9
	call TextBoxBorder
;>     at, step = coord(11, 3), SCREEN_WIDTH + 4
	ld hl, (3) * SCREEN_WIDTH + (11) + wTileMap
	ld bc, SCREEN_WIDTH + 4 ; one row down and 4 columns right
.PrintStats
;> PlaceString(addr(PrintStatsBox.StatsText), at)
	push bc
	push hl
	ld de, .StatsText
	call PlaceString
	pop hl
	pop bc
;> at += step                                    # where the numbers go
	add hl, bc
;> for stat in (wLoadedMonAttack, wLoadedMonDefense, wLoadedMonSpeed, wLoadedMonSpecial):
	ld de, wLoadedMonAttack
	ld bc, ((2) & $ff) << 8 + ((3) & $ff)
	call .PrintStat
;>     # (the same for DEFENSE and SPEED; SPECIAL goes straight to PrintNumber)
	ld de, wLoadedMonDefense
	call .PrintStat
	ld de, wLoadedMonSpeed
	call .PrintStat
	ld de, wLoadedMonSpecial
	jp PrintNumber

.PrintStat:
;>@num     PrintNumber(stat, at, 2, 3)
	push hl
	call PrintNumber
	pop hl
;>@down     at += SCREEN_WIDTH * 2
	ld de, SCREEN_WIDTH * 2
	add hl, de
	ret

.StatsText:
	db   "ATTACK"
	db "<NEXT>", "DEFENSE"
	db "<NEXT>", "SPEED"
	db "<NEXT>", "SPECIAL@"

;@ path: engine/pokemon/status_screen
;@ def StatusScreen2()
;@ The second page of the summary: the four moves with PP, the experience points, and the points still needed
;@ for the next level.
;@ test: skip draws the screen and waits for a button
StatusScreen2:
;> saved_tile_animations = hTileAnimations
	ldh a, [hTileAnimations]
	push af
;> hTileAnimations = 0
	xor a
	ldh [hTileAnimations], a
;> hAutoBGTransferEnabled = 0
	ldh [hAutoBGTransferEnabled], a
;> FillMemory(addr(wMoves), NUM_MOVES + 1, 0)
	ld bc, NUM_MOVES + 1
	ld hl, wMoves
	call FillMemory
;> CopyData(wLoadedMonMoves, addr(wMoves), NUM_MOVES)
	ld hl, wLoadedMonMoves
	ld de, wMoves
	ld bc, NUM_MOVES
	call CopyData
;> FormatMovesString()
	ld hl, FormatMovesString
	ld b, BANK(FormatMovesString)
	call Bankswitch
;> ClearScreenArea(coord(9, 2), 10, 5)           # under the name
	ld hl, (2) * SCREEN_WIDTH + (9) + wTileMap
	ld bc, ((5) & $ff) << 8 + ((10) & $ff)
	call ClearScreenArea ; Clear under name
;> mem[coord(19, 3)] = 0x78
	ld hl, (3) * SCREEN_WIDTH + (19) + wTileMap
	ld [hl], $78
;> TextBoxBorder(coord(0, 8), 8, 18)             # the moves box
	ld hl, (8) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 8
	ld c, 18
	call TextBoxBorder ; Draw move container
;> PlaceString(addr(wMovesString), coord(2, 9))
	ld hl, (9) * SCREEN_WIDTH + (2) + wTileMap
	ld de, wMovesString
	call PlaceString ; Print moves
;> known = wNumMovesMinusOne + 1
	ld a, [wNumMovesMinusOne]
	inc a
	ld c, a ; number of known moves
;> blank = NUM_MOVES - known
	ld a, NUM_MOVES
	sub c
	ld b, a ; number of blank moves
;> at = StatusScreen_PrintPP(coord(11, 10), SCREEN_WIDTH * 2, known, 0x72)    # "PP" with the bold P
	ld hl, (10) * SCREEN_WIDTH + (11) + wTileMap
	ld de, SCREEN_WIDTH * 2
	ld a, '<BOLD_P>'
	call StatusScreen_PrintPP ; Print "PP"
;> if blank:
;>     StatusScreen_PrintPP(at, SCREEN_WIDTH * 2, blank, charmap('-')[0])    # "--" for the empty slots
	ld a, b
	and a
	jr z, .InitPP
	ld c, a
	ld a, '-'
	call StatusScreen_PrintPP ; Fill the rest with --
.InitPP
;> at = coord(14, 10)
	ld hl, wLoadedMonMoves
	ld de, (10) * SCREEN_WIDTH + (14) + wTileMap
;> for i in range(NUM_MOVES):
	ld b, 0
.PrintPP
;>     if mem[wLoadedMonMoves + i] == 0:
;>         break
	ld a, [hli]
	and a
	jr z, .PPDone
;>     keep = wCurrentMenuItem
	push bc
	push hl
	push de
	ld hl, wCurrentMenuItem
	ld a, [hl]
	push af
;>     wCurrentMenuItem = i
	ld a, b
	ld [hl], a
	push hl
;>     GetMaxPP()                                # into wMaxPP
	ld hl, GetMaxPP
	ld b, BANK(GetMaxPP)
	call Bankswitch
	pop hl
;>     wCurrentMenuItem = keep
	pop af
	ld [hl], a
	pop de
	pop hl
	push hl
;>     wStatusScreenCurrentPP = mem[wLoadedMonMoves + i + MON_PP - MON_MOVES] & PP_MASK
	ld bc, MON_PP - MON_MOVES - 1
	add hl, bc
	ld a, [hl]
	and PP_MASK
	ld [wStatusScreenCurrentPP], a
;>     end = PrintNumber(addr(wStatusScreenCurrentPP), at, 1, 2)
	ld h, d
	ld l, e
	push hl
	ld de, wStatusScreenCurrentPP
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
;>     mem[end] = charmap('/')[0]
	ld a, '/'
	ld [hli], a
;>     PrintNumber(addr(wMaxPP), end + 1, 1, 2)
	ld de, wMaxPP
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
;>     at += SCREEN_WIDTH * 2
	pop hl
	ld de, SCREEN_WIDTH * 2
	add hl, de
	ld d, h
	ld e, l
;>     # on to the next move
	pop hl
	pop bc
	inc b
	ld a, b
	cp NUM_MOVES
	jr nz, .PrintPP
.PPDone
;> PlaceString(StatusScreenExpText, coord(9, 3))
	ld hl, (3) * SCREEN_WIDTH + (9) + wTileMap
	ld de, StatusScreenExpText
	call PlaceString
;> level = mem[wLoadedMonLevel]
	ld a, [wLoadedMonLevel]
	push af
;> if level != MAX_LEVEL:
;>     mem[wLoadedMonLevel] = level + 1          # "to :L" shows the next level
	cp MAX_LEVEL
	jr z, .Level100
	inc a
	ld [wLoadedMonLevel], a ; Increase temporarily if not 100
.Level100
;> mem[coord(14, 6)] = 0x70                      # "to"
	ld hl, (6) * SCREEN_WIDTH + (14) + wTileMap
	ld [hl], '<to>'
;> PrintLevel(coord(16, 6))
	inc hl
	inc hl
	call PrintLevel
;> mem[wLoadedMonLevel] = level
	pop af
	ld [wLoadedMonLevel], a
;> PrintNumber(wLoadedMonExp, coord(12, 4), 3, 7)
	ld de, wLoadedMonExp
	ld hl, (4) * SCREEN_WIDTH + (12) + wTileMap
	ld bc, ((3) & $ff) << 8 + ((7) & $ff)
	call PrintNumber ; exp
;> CalcExpToLevelUp()
	call CalcExpToLevelUp
;> PrintNumber(wLoadedMonExp, coord(7, 6), 3, 7)  # now the points still needed
	ld de, wLoadedMonExp
	ld hl, (6) * SCREEN_WIDTH + (7) + wTileMap
	ld bc, ((3) & $ff) << 8 + ((7) & $ff)
	call PrintNumber ; exp needed to level up

	; unneeded, this clears the diacritic characters in JPN versions
;> StatusScreen_ClearName(coord(9, 0))          # not needed: the accent row of the Japanese version
	ld hl, (0) * SCREEN_WIDTH + (9) + wTileMap
	call StatusScreen_ClearName

;> StatusScreen_ClearName(coord(9, 1))
	ld hl, (1) * SCREEN_WIDTH + (9) + wTileMap
	call StatusScreen_ClearName
;> wNamedObjectIndex = wMonHIndex
	ld a, [wMonHIndex]
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> PlaceString(addr(wNameBuffer), coord(9, 1))
	ld hl, (1) * SCREEN_WIDTH + (9) + wTileMap
	call PlaceString
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
;> WaitForTextScrollButtonPress()
	call Delay3
	call WaitForTextScrollButtonPress
;> hTileAnimations = saved_tile_animations
	pop af
	ldh [hTileAnimations], a
;> wStatusFlags2 = wStatusFlags2 & ~(1 << BIT_NO_AUDIO_FADE_OUT) & 0xFF
	ld hl, wStatusFlags2
	res BIT_NO_AUDIO_FADE_OUT, [hl]
;> rAUDVOL = 0x77                                # full volume again
	ld a, $77
	ldh [rAUDVOL], a
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> ClearScreen()
	jp ClearScreen

;@ path: engine/pokemon/status_screen
;@ def CalcExpToLevelUp()
;@ Replace wLoadedMon's experience with the points it still needs for the next level (0 at level 100).
;@ test: hLoadedROMBank = 4; wMonHGrowthRate = rand(0, 5); mem[0xCFB9] = rand(1, 100)    # wLoadedMonLevel
CalcExpToLevelUp:
;> level = mem[wLoadedMonLevel]
	ld a, [wLoadedMonLevel]
;> if level == MAX_LEVEL:
	cp MAX_LEVEL
	jr z, .atMaxLevel
;>@max     mem[wLoadedMonExp] = mem[wLoadedMonExp + 1] = mem[wLoadedMonExp + 2] = 0
;>@maxret     return
;> set_rom_bank(0x16)                           # a far call into CalcExperience's bank
	inc a
	ld d, a
	ld hl, CalcExperience
	ld b, BANK(CalcExperience)
;> CalcExperience(level + 1)
;> set_rom_bank(hLoadedROMBank)
	call Bankswitch
;> needed = ((hExperience[0] << 16 | hExperience[1] << 8 | hExperience[2]) - (mem[wLoadedMonExp] << 16 | mem[wLoadedMonExp + 1] << 8 | mem[wLoadedMonExp + 2])) & 0xFFFFFF
;> mem[wLoadedMonExp + 2] = needed & 0xFF        # subtracted from the low byte up
	ld hl, wLoadedMonExp + 2
	ldh a, [hExperience + 2]
	sub [hl]
	ld [hld], a
;> mem[wLoadedMonExp + 1] = needed >> 8 & 0xFF
	ldh a, [hExperience + 1]
	sbc [hl]
	ld [hld], a
;> mem[wLoadedMonExp] = needed >> 16
	ldh a, [hExperience]
	sbc [hl]
	ld [hld], a
	ret
.atMaxLevel
;=@max
	ld hl, wLoadedMonExp
	xor a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;=@maxret
	ret

;@ path: engine/pokemon/status_screen
StatusScreenExpText:
	db   "EXP POINTS"
	db "<NEXT>", "LEVEL UP@"

;@ path: engine/pokemon/status_screen
;@ def StatusScreen_ClearName(dest: hl)
;@ Blank one line of a name (10 spaces) at dest.
;@ test: dest = rand_ram(16)
StatusScreen_ClearName:
;> FillMemory(dest, NAME_LENGTH - 1, charmap(' ')[0])
	ld bc, NAME_LENGTH - 1
	ld a, ' '
	jp FillMemory

;@ path: engine/pokemon/status_screen
;@ def StatusScreen_PrintPP(dest: hl, step: de, count: c, tile: a) -> hl
;@ Put two tiles `tile` side by side count times, going down `step` bytes each time ("PP" or "--").
;@ test: count = rand(1, 4); dest = rand_ram(200); step = 2 * SCREEN_WIDTH
StatusScreen_PrintPP:
; print PP or -- c times, going down two rows each time
;> for _ in range(count):
;>     mem[dest] = tile
	ld [hli], a
;>     mem[dest + 1] = tile
	ld [hld], a
;>     dest += step
	add hl, de
	dec c
	jr nz, StatusScreen_PrintPP
;> return dest
	ret
;@ def DrawPartyMenu_()
;@ Draw the party menu from scratch: clear the screen, load the Pokémon icons (LCD off), then the entries.
;@ path: engine/menus/party_menu
DrawPartyMenu_::
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
	; load pokemon icon graphics
;> farcall(LoadMonPartySpriteGfxWithLCDDisabled)
	ld b, BANK(LoadMonPartySpriteGfxWithLCDDisabled)
	ld hl, LoadMonPartySpriteGfxWithLCDDisabled
	call Bankswitch
;> return RedrawPartyMenu_()                    # it follows

;@ def RedrawPartyMenu_()
;@ The party menu's entries: name, icon and level, then status and HP bar, or for a TM or an evolution stone
;@ whether each Pokémon is ABLE or NOT ABLE; '▷' marks the one being moved. Then the menu's message
;@ (wPartyMenuTypeOrMessageID), or after an item the item's message with the Pokémon's name.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/menus/party_menu
RedrawPartyMenu_::
;> if wPartyMenuTypeOrMessageID != SWAP_MONS_PARTY_MENU:
	ld a, [wPartyMenuTypeOrMessageID]
	cp SWAP_MONS_PARTY_MENU
	jp z, .printMessage
;>     ErasePartyMenuCursors()
	call ErasePartyMenuCursors
;>     farcall(InitPartyMenuBlkPacket)
	ld b, BANK(InitPartyMenuBlkPacket)
	ld hl, InitPartyMenuBlkPacket
	call Bankswitch
;>     pos = coord(3, 0)
	ld hl, (0) * SCREEN_WIDTH + (3) + wTileMap
;>     species = addr(wPartySpecies)
	ld de, wPartySpecies
;>     i = hPartyMonIndex = 0
	xor a
	ld c, a
	ldh [hPartyMonIndex], a
;>     wWhichPartyMenuHPBar = 0
	ld [wWhichPartyMenuHPBar], a
;>@pl     while mem[species + i] != 0xFF:
.loop
	ld a, [de]
	cp $FF ; reached the terminator?
	jp z, .afterDrawingMonEntries
;>         # (i, the species pointer and pos are kept)
	push bc
	push de
	push hl
;>         name = GetPartyMonName(i, addr(wPartyMonNicks))
	ld a, c
	push hl
	ld hl, wPartyMonNicks
	call GetPartyMonName
	pop hl
;>         PlaceString(name, pos)
	call PlaceString ; print the pokemon's name
	; place the appropriate pokemon icon
;>         farcall(WriteMonPartySpriteOAMByPartyIndex)
	ld b, BANK(WriteMonPartySpriteOAMByPartyIndex)
	ld hl, WriteMonPartySpriteOAMByPartyIndex
	call Bankswitch
;>         wWhichPokemon = hPartyMonIndex
	ldh a, [hPartyMonIndex]
	ld [wWhichPokemon], a
;>         hPartyMonIndex += 1
	inc a
	ldh [hPartyMonIndex], a
;>         LoadMonData()
	call LoadMonData
;>         if wMenuItemToSwap:                 # Pokémon are being moved
	pop hl
	push hl
	ld a, [wMenuItemToSwap]
	and a ; is the player swapping pokemon positions?
	jr z, .skipUnfilledRightArrow
; if the player is swapping pokemon positions
;>             if wMenuItemToSwap - 1 == wWhichPokemon:     # this is the one
	dec a
	ld b, a
	ld a, [wWhichPokemon]
	cp b ; is the player swapping the current pokemon in the list?
	jr nz, .skipUnfilledRightArrow
; the player is swapping the current pokemon in the list
;>                 pos -= 3
	dec hl
	dec hl
	dec hl
;>                 mem[pos] = 0xEC             # '▷'
	ld a, '▷' ; unfilled right arrow menu cursor
	ld [hli], a ; place the cursor
;>                 pos += 3
	inc hl
	inc hl
.skipUnfilledRightArrow
;>         if wPartyMenuTypeOrMessageID == TMHM_PARTY_MENU:      # can it learn the TM / HM?
	ld a, [wPartyMenuTypeOrMessageID] ; menu type
	cp TMHM_PARTY_MENU
	jr z, .teachMoveMenu
;>@tm1             able = predef(CanLearnTM)
;>@tm2             text = label('RedrawPartyMenu_.ableToLearnMoveText' if able else 'RedrawPartyMenu_.notAbleToLearnMoveText')
;>@tm3             PlaceString(text, pos + SCREEN_WIDTH + 9)
;>         elif wPartyMenuTypeOrMessageID == EVO_STONE_PARTY_MENU:   # would the stone evolve it?
	cp EVO_STONE_PARTY_MENU
	jr z, .evolutionStoneMenu
;>@ev0a             i = (wLoadedMonSpecies - 1) & 0xFF
;>@ev0             src = EvosMovesPointerTable + 2 * i             # its pointer to evolutions and moves
;>@ev1             FarCopyData(BANK(EvosMovesPointerTable), src, addr(wEvoDataBuffer), 2)
;>@ev2a             ptr = mem16[addr(wEvoDataBuffer)]
;>@ev2             FarCopyData(BANK(EvosMovesPointerTable), ptr, addr(wEvoDataBuffer), addr(wEvoDataBufferEnd) - addr(wEvoDataBuffer))
;>@ev3             p = addr(wEvoDataBuffer)            # its evolution entries: method, item, level, species
;>@ev4             able = False
;>@ev5             while mem[p]:
;>@ev6                 method = mem[p]
;>@ev7                 p += 3
;>@ev8                 if method == EVOLVE_ITEM:
;>@ev9                     item = mem[p - 2]
;>@ev9b                     p += 1
;>@ev10                     if item == wEvoStoneItemID:      # the stone the player used
;>@ev11                         able = True
;>@ev12                         break
;>@ev13             text = label('RedrawPartyMenu_.ableToEvolveText' if able else 'RedrawPartyMenu_.notAbleToEvolveText')
;>@ev14             PlaceString(text, pos + SCREEN_WIDTH + 9)
;>         else:
;>             PrintStatusCondition(addr(wLoadedMonStatus), pos + 14)
	push hl
	ld bc, 14 ; 14 columns to the right
	add hl, bc
	ld de, wLoadedMonStatus
	call PrintStatusCondition
;>             hUILayoutFlags |= 1 << BIT_PARTY_MENU_HP_BAR
	pop hl
	push hl
	ld bc, SCREEN_WIDTH + 1 ; down 1 row and right 1 column
	ldh a, [hUILayoutFlags]
	set BIT_PARTY_MENU_HP_BAR, a
	ldh [hUILayoutFlags], a
;>             length = predef(DrawHP2, hl=pos + SCREEN_WIDTH + 1)     # the HP bar and HP
	add hl, bc
	; draw HP bar and prints current / max HP
	ld a, (DrawHP2Predef - PredefPointers) / 3
	call Predef
;>             hUILayoutFlags &= ~(1 << BIT_PARTY_MENU_HP_BAR) & 0xFF
	ldh a, [hUILayoutFlags]
	res BIT_PARTY_MENU_HP_BAR, a
	ldh [hUILayoutFlags], a
;>             SetPartyMenuHPBarColor(length)
	call SetPartyMenuHPBarColor ; color the HP bar (on SGB)
	pop hl
	jr .printLevel
.teachMoveMenu
;=@tm1
	push hl
	; check if the pokemon can learn the move
	ld a, (CanLearnTMPredef - PredefPointers) / 3
	call Predef
	pop hl
;=@tm2
	ld de, .ableToLearnMoveText
	ld a, c
	and a
	jr nz, .placeMoveLearnabilityString
	ld de, .notAbleToLearnMoveText
.placeMoveLearnabilityString
;=@tm3
	ld bc, SCREEN_WIDTH + 9 ; 1 row down and 9 columns right
	push hl
	add hl, bc
	call PlaceString
	pop hl
.printLevel
;>         PrintLevel(pos + 10)
	ld bc, 10 ; move 10 columns to the right
	add hl, bc
	call PrintLevel
	pop hl
	pop de
	inc de
;>         pos += 2 * SCREEN_WIDTH
	ld bc, 2 * SCREEN_WIDTH
	add hl, bc
;>         i += 1
	pop bc
	inc c
	jp .loop
.ableToLearnMoveText
	db "ABLE@"
.notAbleToLearnMoveText
	db "NOT ABLE@"
.evolutionStoneMenu
;=@ev0a
	push hl
	ld hl, EvosMovesPointerTable
	ld b, 0
	ld a, [wLoadedMonSpecies]
	dec a
;=@ev0
	add a
	rl b
	ld c, a
	add hl, bc
;=@ev1
	ld de, wEvoDataBuffer
	ld a, BANK(EvosMovesPointerTable)
	ld bc, 2
	call FarCopyData
;=@ev2a
	ld hl, wEvoDataBuffer
	ld a, [hli]
	ld h, [hl]
	ld l, a
;=@ev2
	ld de, wEvoDataBuffer
	ld a, BANK(EvosMovesPointerTable)
	ld bc, wEvoDataBufferEnd - wEvoDataBuffer
	call FarCopyData
;=@ev3
	ld hl, wEvoDataBuffer
;=@ev4
	ld de, .notAbleToEvolveText
; loop through the pokemon's evolution entries
.checkEvolutionsLoop
;=@ev5
	ld a, [hli]
	and a ; reached terminator?
	jr z, .placeEvolutionStoneString ; if so, place the "NOT ABLE" string
;=@ev7
	inc hl
	inc hl
;=@ev8
	cp EVOLVE_ITEM
	jr nz, .checkEvolutionsLoop
; if it's a stone evolution entry
;=@ev9
	dec hl
	dec hl
	ld b, [hl]
;=@ev10
	ld a, [wEvoStoneItemID] ; the stone the player used
;=@ev9b
	inc hl
	inc hl
	inc hl
;=@ev10
	cp b ; does the player's stone match this evolution entry's stone?
	jr nz, .checkEvolutionsLoop
; if it does match
;=@ev11
	ld de, .ableToEvolveText
.placeEvolutionStoneString
;=@ev14
	ld bc, SCREEN_WIDTH + 9 ; down 1 row and right 9 columns
	pop hl
	push hl
	add hl, bc
	call PlaceString
;=@ev14
	pop hl
	jr .printLevel
.ableToEvolveText
	db "ABLE@"
.notAbleToEvolveText
	db "NOT ABLE@"
.afterDrawingMonEntries
;>     RunPaletteCommand(SET_PAL_PARTY_MENU)
	ld b, SET_PAL_PARTY_MENU
	call RunPaletteCommand
.printMessage
;> flags = wStatusFlags5
	ld hl, wStatusFlags5
	ld a, [hl]
	push af
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	push hl
	set BIT_NO_TEXT_DELAY, [hl]
;> message = wPartyMenuTypeOrMessageID
	ld a, [wPartyMenuTypeOrMessageID] ; message ID
;> if message < FIRST_PARTY_MENU_TEXT_ID:
	cp FIRST_PARTY_MENU_TEXT_ID
	jr nc, .printItemUseMessage
;>     p = PartyMenuMessagePointers + (2 * message & 0xFF)
	add a
	ld hl, PartyMenuMessagePointers
	ld b, 0
	ld c, a
	add hl, bc
;>     text = mem16[p]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     PrintText(text)
	call PrintText
;>@iuelse else:                                 # a message after using an item on a Pokémon
;>@iu1a     p = PartyMenuItemUseMessagePointers + 2 * (message & 0xF)
;>@iu1     text = mem16[p]
;>@iu2     GetPartyMonName(wUsedItemOnWhichPokemon, addr(wPartyMonNicks))     # its name for the message
;>@iu3     PrintText(text)
.done
;> wStatusFlags5 = flags
	pop hl
	pop af
	ld [hl], a
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> return GBPalNormal()
	jp GBPalNormal
.printItemUseMessage
;=@iu1a
	and $0F
	ld hl, PartyMenuItemUseMessagePointers
	add a
	ld c, a
	ld b, 0
	add hl, bc
;=@iu1
	ld a, [hli]
	ld h, [hl]
	ld l, a
;=@iu2
	push hl
	ld a, [wUsedItemOnWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
	pop hl
;=@iu3
	call PrintText
	jr .done

;@ path: engine/menus/party_menu
