;@ def SetPartyMenuHPBarColor(length: e)
;@ On the Super Game Boy, colour the next party HP bar green, yellow or red by its length.
;@ test: hLoadedROMBank = 4    # the bank this code runs in (RunPaletteCommand switches back to it)
;@ path: engine/menus/party_menu
SetPartyMenuHPBarColor:
;> GetHealthBarColor(length, addr(wPartyMenuHPBarColors) + wWhichPartyMenuHPBar)
	ld hl, wPartyMenuHPBarColors
	ld a, [wWhichPartyMenuHPBar]
	ld c, a
	ld b, 0
	add hl, bc
	call GetHealthBarColor
;> RunPaletteCommand(SET_PAL_PARTY_MENU_HP_BARS)
	ld b, SET_PAL_PARTY_MENU_HP_BARS
	call RunPaletteCommand
;> wWhichPartyMenuHPBar += 1
	ld hl, wWhichPartyMenuHPBar
	inc [hl]
	ret
