	db $77, $3f, $b8, $94, $f3, $17, $f5, $07, $ea, $05, $7d, $3c, $3a, $88, $ad, $23
	db $7a, $8f, $16, $8e, $15, $f8, $f5, $15, $4f, $0e, $8c, $14, $85, $48, $a8, $f0
	db $ef, $57, $e5, $42, $0b, $f5, $4f, $1a, $a2, $6b, $e2, $68, $ff, $2b, $e7, $fd
	db $10, $80
;@ path: engine/overworld/turn_sprite
;@ def UpdateSpriteFacingOffsetAndDelayMovement()
;@ Freeze the current sprite facing its direction: longest movement delay, animation reset, the facing
;@ added to its image, and movement status 2 (delayed).
;@ test: hCurrentSpriteOffset = 16 * rand(0, 15)
UpdateSpriteFacingOffsetAndDelayMovement::
;> s2 = addr(wSpriteStateData2) + hCurrentSpriteOffset
	ld h, HIGH(wSpriteStateData2)
	ldh a, [hCurrentSpriteOffset]
	add $8
	ld l, a
;> mem[s2 + SPRITESTATEDATA2_MOVEMENTDELAY] = 0x7F            # the longest pause
	ld a, $7f ; maximum movement delay
	ld [hl], a ; x#SPRITESTATEDATA2_MOVEMENTDELAY
;> s1 = addr(wSpriteStateData1) + hCurrentSpriteOffset
	dec h ; HIGH(wSpriteStateData1)
	ldh a, [hCurrentSpriteOffset]
	add $9
	ld l, a
;> facing = mem[s1 + SPRITESTATEDATA1_FACINGDIRECTION]
	ld a, [hld] ; x#SPRITESTATEDATA1_FACINGDIRECTION
	ld b, a
;> mem[s1 + SPRITESTATEDATA1_ANIMFRAMECOUNTER] = 0
	xor a
	ld [hld], a ; x#SPRITESTATEDATA1_ANIMFRAMECOUNTER
;> mem[s1 + SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER] = 0
	ld [hl], a ; x#SPRITESTATEDATA1_INTRAANIMFRAMECOUNTER
;> mem[s1 + SPRITESTATEDATA1_IMAGEINDEX] = mem[s1 + SPRITESTATEDATA1_IMAGEINDEX] | facing
	ldh a, [hCurrentSpriteOffset]
	add SPRITESTATEDATA1_IMAGEINDEX
	ld l, a
	ld a, [hl] ; x#SPRITESTATEDATA1_IMAGEINDEX
	or b ; or in the facing direction
	ld [hld], a
;> mem[s1 + SPRITESTATEDATA1_MOVEMENTSTATUS] = 2
	ld a, $2 ; delayed movement status
	ld [hl], a ; x#SPRITESTATEDATA1_MOVEMENTSTATUS
	ret
;@ def StartMenu_Pokedex(saved)
;@ START menu POKéDEX: the Pokédex, then back to the START menu.
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
StartMenu_Pokedex::
;> predef(ShowPokedexMenu)
	ld a, (ShowPokedexMenuPredef - PredefPointers) / 3
	call Predef
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> Delay3()
	call Delay3
;> LoadGBPal()
	call LoadGBPal
;> UpdateSprites()
	call UpdateSprites
;> return RedisplayStartMenu(saved)
	jp RedisplayStartMenu

;@ def StartMenu_Pokemon(saved)
;@ START menu POKéMON: the party menu, and for a chosen Pokémon its menu of field moves, STATS, SWITCH and CANCEL.
;@ Field moves need their badge (CUT Cascade, FLY Thunder, SURF Soul, STRENGTH Rainbow, FLASH Boulder); FLY,
;@ SURF, DIG and TELEPORT end at the map, SOFTBOILED gives a fifth of the user's max HP to another Pokémon.
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
StartMenu_Pokemon::
;> if not wPartyCount:
;>     return RedisplayStartMenu(saved)
	ld a, [wPartyCount]
	and a
	jp z, RedisplayStartMenu
;> wMenuItemToSwap = wPartyMenuTypeOrMessageID = wUpdateSpritesEnabled = 0
	xor a
	ld [wMenuItemToSwap], a
	ld [wPartyMenuTypeOrMessageID], a
	ld [wUpdateSpritesEnabled], a
;> cancelled = DisplayPartyMenu()              # carry: B pressed
	call DisplayPartyMenu
	jr .checkIfPokemonChosen
.loop
;=@back1
	xor a
	ld [wMenuItemToSwap], a
	ld [wPartyMenuTypeOrMessageID], a
;=@back2
	call GoBackToPartyMenu
.checkIfPokemonChosen
;> while True:
;>     if cancelled:
	jr nc, .chosePokemon
.exitMenu
;>         GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>         RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;>         LoadGBPal()
	call LoadGBPal
;>         return RedisplayStartMenu(saved)
	jp RedisplayStartMenu
.chosePokemon
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     wTextBoxID = FIELD_MOVE_MON_MENU
;>     DisplayTextBoxID()
	ld a, FIELD_MOVE_MON_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID ; display pokemon menu options
;>     moves = 0                               # each field move adds a menu row on top
	ld hl, wFieldMoves
	; max menu item ID, top menu item Y
	ld bc, ((2) & $ff) << 8 + ((12) & $ff)
	ld e, 5
;>     while moves < 4 and mem[addr(wFieldMoves) + moves]:
.adjustMenuVariablesLoop
	dec e
	jr z, .storeMenuVariables
	ld a, [hli]
	and a ; end of field moves?
	jr z, .storeMenuVariables
;>         moves += 1
	inc b
	dec c
	dec c
	jr .adjustMenuVariablesLoop
.storeMenuVariables
;>     wTopMenuItemY = 12 - 2 * moves
	ld hl, wTopMenuItemY
	ld a, c
	ld [hli], a ; top menu item Y
;>     wTopMenuItemX = hFieldMoveMonMenuTopMenuItemX
	ldh a, [hFieldMoveMonMenuTopMenuItemX]
	ld [hli], a ; top menu item X
;>     wCurrentMenuItem = 0
	xor a
	ld [hli], a ; current menu item ID
;>     wMaxMenuItem = 2 + moves
	inc hl
	ld a, b
	ld [hli], a ; max menu item ID
;>     wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [hli], a ; menu watched keys
;>     wLastMenuItem = 0
	xor a
	ld [hl], a
;>     keys = HandleMenuInput()
	call HandleMenuInput
	push af
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
	pop af
;>     if not keys & PAD_B:                    # (B: back to the party menu)
	bit B_PAD_B, a
	jp nz, .loop
; if the B button wasn't pressed
;>         item, last = wCurrentMenuItem, wMaxMenuItem
	ld a, [wMaxMenuItem]
	ld b, a
	ld a, [wCurrentMenuItem] ; menu selection
;>         if item == last:                    # CANCEL
;>@cx             cancelled = True
;>             continue
	cp b
	jp z, .exitMenu ; if the player chose Cancel
;>         if item == last - 1:                # SWITCH
	dec b
	cp b
	jr z, .choseSwitch
;>@sw1             if wPartyCount < 2:
;>@sw2                 return StartMenu_Pokemon(saved)
;>@sw3             SwitchPartyMon_InitVarOrSwapData()      # remember the Pokémon to move
;>@sw4             wPartyMenuTypeOrMessageID = SWAP_MONS_PARTY_MENU
;>@sw5             cancelled = GoBackToPartyMenu()
;>@sw6             continue
;>         if item == last - 2:                # STATS
	dec b
	cp b
	jp z, .choseStats
;>@st1             ClearSprites()
;>@st2             wMonDataLocation = PLAYER_PARTY_DATA
;>@st3             predef(StatusScreen)
;>@st4             predef(StatusScreen2)
;>@st5             ReloadMapData()
;>@st6             return StartMenu_Pokemon(saved)
;>         move = mem[addr(wFieldMoves) + item]    # 1 CUT, 2 FLY, 3-4 SURF, 5 STRENGTH, 6 FLASH, 7 DIG, 8 TELEPORT, 9 SOFTBOILED
	ld c, a
	ld b, 0
	ld hl, wFieldMoves
	add hl, bc
	jp .choseOutOfBattleMove
.choseSwitch
;=@sw1
	ld a, [wPartyCount]
	cp 2 ; is there more than one pokemon in the party?
;=@sw2
	jp c, StartMenu_Pokemon ; if not, no switching
;=@sw3
	call SwitchPartyMon_InitVarOrSwapData ; init [wMenuItemToSwap]
;=@sw4
	ld a, SWAP_MONS_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;=@sw5
	call GoBackToPartyMenu
;=@sw6
	jp .checkIfPokemonChosen
.choseStats
;=@st1
	call ClearSprites
;=@st2
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;=@st3
	ld a, (StatusScreenPredef - PredefPointers) / 3
	call Predef
;=@st4
	ld a, (StatusScreen2Predef - PredefPointers) / 3
	call Predef
;=@st5
	call ReloadMapData
;=@st6
	jp StartMenu_Pokemon
.choseOutOfBattleMove
;>         GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))   # for the messages
	push hl
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
	pop hl
;>         i = (move - 1) * 2 & 0xFF
	ld a, [hl]
	dec a
	add a
	ld b, 0
	ld c, a
;>         p = label('StartMenu_Pokemon.outOfBattleMovePointers') + i
	ld hl, .outOfBattleMovePointers
	add hl, bc
;>         handler = mem16[p]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>         badges = wObtainedBadges                # each move's handler first checks its badge
;>         to_map = False                          # whether the move ends at the map
	ld a, [wObtainedBadges]
	jp hl
.outOfBattleMovePointers
	dw .cut
	dw .fly
	dw .surf
	dw .surf
	dw .strength
	dw .flash
	dw .dig
	dw .teleport
	dw .softboiled
.fly
;>         if move == 2:                           # FLY
;>             if not badges >> BIT_THUNDERBADGE & 1:
	bit BIT_THUNDERBADGE, a
	jp z, .newBadgeRequired
;>@nb                 PrintText(label('StartMenu_Pokemon.newBadgeRequiredText'))    # (.newBadgeRequired, shared)
;>             elif CheckIfInOutsideMap():
	call CheckIfInOutsideMap
	jr z, .canFly
;>@fl1                 ChooseFlyDestination()
;>@fl2                 if wStatusFlags6 >> BIT_FLY_WARP & 1:
;>@fl3                     to_map = True
;>@fl4                 else:                   # no destination chosen
;>@fl5                     LoadFontTilePatterns()
;>@fl6                     wStatusFlags4 |= 1 << BIT_UNKNOWN_4_1
;>@fl7                     return StartMenu_Pokemon(saved)
;>             else:
;>                 GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;>                 PrintText(label('StartMenu_Pokemon.cannotFlyHereText'))
	ld hl, .cannotFlyHereText
	call PrintText
	jp .loop
.canFly
;=@fl1
	call ChooseFlyDestination
;=@fl2
	ld a, [wStatusFlags6]
	bit BIT_FLY_WARP, a
	jp nz, .goBackToMap
;=@fl5
	call LoadFontTilePatterns
;=@fl6
	ld hl, wStatusFlags4
	set BIT_UNKNOWN_4_1, [hl]
;=@fl7
	jp StartMenu_Pokemon
.cut
;>         elif move == 1:                         # CUT
;>             if not badges >> BIT_CASCADEBADGE & 1:
	bit BIT_CASCADEBADGE, a
	jp z, .newBadgeRequired
;>@nb2                 PrintText(label('StartMenu_Pokemon.newBadgeRequiredText'))
;>             else:
;>                 predef(UsedCut)
	ld a, (UsedCutPredef - PredefPointers) / 3
	call Predef
;>                 if wActionResultOrTookBattleTurn:      # a tree was cut
;>                     return CloseTextDisplay(saved)
	ld a, [wActionResultOrTookBattleTurn]
	and a
	jp z, .loop
	jp CloseTextDisplay
.surf
;>         elif move in (3, 4):                    # SURF
;>             if not badges >> BIT_SOULBADGE & 1:
	bit BIT_SOULBADGE, a
	jp z, .newBadgeRequired
;>@nb3                 PrintText(label('StartMenu_Pokemon.newBadgeRequiredText'))
;>             else:
;>                 farcall(IsSurfingAllowed)
	ld b, BANK(IsSurfingAllowed)
	ld hl, IsSurfingAllowed
	call Bankswitch
;>                 allowed = wStatusFlags1 >> BIT_SURF_ALLOWED & 1
	ld hl, wStatusFlags1
	bit BIT_SURF_ALLOWED, [hl]
;>                 wStatusFlags1 &= ~(1 << BIT_SURF_ALLOWED) & 0xFF
	res BIT_SURF_ALLOWED, [hl]
;>                 if allowed:
	jp z, .loop
;>                     wCurItem = wPseudoItemID = SURFBOARD
	ld a, SURFBOARD
	ld [wCurItem], a
	ld [wPseudoItemID], a
;>                     UseItem()
	call UseItem
;>                     if wActionResultOrTookBattleTurn:
	ld a, [wActionResultOrTookBattleTurn]
	and a
	jp z, .loop
;>                         GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>                         to_map = True
	jp .goBackToMap
.strength
;>         elif move == 5:                         # STRENGTH
;>             if not badges >> BIT_RAINBOWBADGE & 1:
	bit BIT_RAINBOWBADGE, a
	jp z, .newBadgeRequired
;>@nb5                 PrintText(label('StartMenu_Pokemon.newBadgeRequiredText'))
;>             else:
;>                 predef(PrintStrengthText)
	ld a, (PrintStrengthTextPredef - PredefPointers) / 3
	call Predef
;>                 GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>                 to_map = True
	jp .goBackToMap
.flash
;>         elif move == 6:                         # FLASH
;>             if not badges >> BIT_BOULDERBADGE & 1:
	bit BIT_BOULDERBADGE, a
	jp z, .newBadgeRequired
;>@nb6                 PrintText(label('StartMenu_Pokemon.newBadgeRequiredText'))
;>             else:
;>                 wMapPalOffset = 0               # the cave is lit
	xor a
	ld [wMapPalOffset], a
;>                 PrintText(label('StartMenu_Pokemon.flashLightsAreaText'))
	ld hl, .flashLightsAreaText
	call PrintText
;>                 GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>                 to_map = True
	jp .goBackToMap
.flashLightsAreaText
	db TX_FAR
	dw _FlashLightsAreaText
	db BANK(_FlashLightsAreaText)
	db TX_END
.dig
;>         elif move == 7:                         # DIG
;>             wCurItem = wPseudoItemID = ESCAPE_ROPE     # works like an Escape Rope
	ld a, ESCAPE_ROPE
	ld [wCurItem], a
	ld [wPseudoItemID], a
;>             UseItem()
	call UseItem
;>             if wActionResultOrTookBattleTurn:
	ld a, [wActionResultOrTookBattleTurn]
	and a
	jp z, .loop
;>                 GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>                 to_map = True
	jp .goBackToMap
.teleport
;>         elif move == 8:                         # TELEPORT
;>             if CheckIfInOutsideMap():
	call CheckIfInOutsideMap
	jr z, .canTeleport
;>@tp1                 PrintText(label('StartMenu_Pokemon.warpToLastPokemonCenterText'))
;>@tp2                 wStatusFlags6 |= (1 << BIT_FLY_WARP) | (1 << BIT_ESCAPE_WARP)
;>@tp3                 wStatusFlags4 |= 1 << BIT_UNKNOWN_4_1
;>@tp4                 wStatusFlags4 &= ~(1 << BIT_NO_BATTLES) & 0xFF
;>@tp5                 DelayFrames(60)
;>@tp6                 GBPalWhiteOutWithDelay3()
;>@tp7                 to_map = True
;>             else:
;>                 GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;>                 PrintText(label('StartMenu_Pokemon.cannotUseTeleportNowText'))
	ld hl, .cannotUseTeleportNowText
	call PrintText
	jp .loop
.canTeleport
;=@tp1
	ld hl, .warpToLastPokemonCenterText
	call PrintText
;=@tp2
	ld hl, wStatusFlags6
	set BIT_FLY_WARP, [hl]
	set BIT_ESCAPE_WARP, [hl]
;=@tp3
	ld hl, wStatusFlags4
	set BIT_UNKNOWN_4_1, [hl]
;=@tp4
	res BIT_NO_BATTLES, [hl]
;=@tp5
	ld c, 60
	call DelayFrames
;=@tp6
	call GBPalWhiteOutWithDelay3
;=@tp7
	jp .goBackToMap
.warpToLastPokemonCenterText
	db TX_FAR
	dw _WarpToLastPokemonCenterText
	db BANK(_WarpToLastPokemonCenterText)
	db TX_END
.cannotUseTeleportNowText
	db TX_FAR
	dw _CannotUseTeleportNowText
	db BANK(_CannotUseTeleportNowText)
	db TX_END
.cannotFlyHereText
	db TX_FAR
	dw _CannotFlyHereText
	db BANK(_CannotFlyHereText)
	db TX_END
;>         elif move == 9:                         # SOFTBOILED
.softboiled
;>             mon = AddNTimes(addr(wPartyMon1MaxHP), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld hl, wPartyMon1MaxHP
	ld a, [wWhichPokemon]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>             mem[addr(hDividend)] = mem[mon]
	ld a, [hli]
	ldh [hDividend], a
;>             mem[addr(hDividend) + 1] = mem[mon + 1]
	ld a, [hl]
	ldh [hDividend + 1], a
;>             mem[addr(hDivisor)] = 5
	ld a, 5
	ldh [hDivisor], a
;>             Divide(2)
	ld b, 2 ; number of bytes
	call Divide
;>             hp = mon + MON_HP - MON_MAXHP
	ld bc, MON_HP - MON_MAXHP
	add hl, bc
;>             hpv = mem[hp] << 8 | mem[hp + 1]
;>             fifth = mem[addr(hQuotient) + 2] << 8 | mem[addr(hQuotient) + 3]    # a fifth of its max HP
	ld a, [hld]
	ld b, a
	ldh a, [hQuotient + 3]
	sub b
;>             if hpv <= fifth:
	ld b, [hl]
	ldh a, [hQuotient + 2]
	sbc b
	jp nc, .notHealthyEnough
;>@nh                 PrintText(label('StartMenu_Pokemon.notHealthyEnoughText'))
;>             else:
;>                 kept = wPartyAndBillsPCSavedMenuItem
	ld a, [wPartyAndBillsPCSavedMenuItem]
	push af
;>                 wCurItem = wPseudoItemID = POTION   # healing works like a Potion
	ld a, POTION
	ld [wCurItem], a
	ld [wPseudoItemID], a
;>                 UseItem()
	call UseItem
;>                 wPartyAndBillsPCSavedMenuItem = kept
	pop af
	ld [wPartyAndBillsPCSavedMenuItem], a
	jp .loop
.notHealthyEnough ; if current HP is less than 1/5 of max HP
;=@nh
	ld hl, .notHealthyEnoughText
	call PrintText
	jp .loop
.notHealthyEnoughText
	db TX_FAR
	dw _NotHealthyEnoughText
	db BANK(_NotHealthyEnoughText)
	db TX_END
;>         if to_map:
.goBackToMap
;>             RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;>             return CloseTextDisplay(saved)
	jp CloseTextDisplay
;>@back1     wMenuItemToSwap = wPartyMenuTypeOrMessageID = 0     # back to the party menu
;>@back2     cancelled = GoBackToPartyMenu()
.newBadgeRequired
;=@nb
	ld hl, .newBadgeRequiredText
	call PrintText
	jp .loop
.newBadgeRequiredText
	db TX_FAR
	dw _NewBadgeRequiredText
	db BANK(_NewBadgeRequiredText)
	db TX_END

; writes a blank tile to all possible menu cursor positions on the party menu
;@ def ErasePartyMenuCursors()
;@ Blank the six places the party menu's cursor can be.
;@ path: engine/menus/start_sub_menus
ErasePartyMenuCursors::
;> p = coord(0, 1)
	ld hl, (1) * SCREEN_WIDTH + (0) + wTileMap
;> step = 2 * SCREEN_WIDTH
	ld bc, 2 * SCREEN_WIDTH ; menu cursor positions are 2 rows apart
;>@lp for _ in range(6):
	ld a, 6 ; 6 menu cursor positions
.loop
;>     mem[p] = 0x7F
	ld [hl], ' '
;>     p += step
	add hl, bc
;=@lp
	dec a
	jr nz, .loop
	ret

;@ def ItemMenuLoop(saved)
;@ Back to the bag after using or tossing an item.
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
ItemMenuLoop:
;> LoadScreenTilesFromBuffer2DisableBGTransfer()
	call LoadScreenTilesFromBuffer2DisableBGTransfer
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> return StartMenu_Item(saved)                 # it follows

;@ def StartMenu_Item(saved)
;@ START menu ITEM: the bag, then USE or TOSS for the chosen item (the bicycle is always used). Items like the
;@ bicycle close the menu, medicine and the like open the party menu, the rest are used on the spot. Not in the
;@ Cable Club rooms.
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
StartMenu_Item::
;> if wLinkState == LINK_STATE_IN_CABLE_CLUB:
	ld a, [wLinkState]
	dec a ; is the player in the Colosseum or Trade Centre?
	jr nz, .notInCableClubRoom
;>     PrintText(CannotUseItemsHereText)
	ld hl, CannotUseItemsHereText
	call PrintText
;>     cancelled = True
	jr .exitMenu
;> else:
.notInCableClubRoom
;>     mem16[addr(wListPointer)] = addr(wNumBagItems)
	ld bc, wNumBagItems
	ld hl, wListPointer
	ld a, c
	ld [hli], a
	ld [hl], b ; store item bag pointer in wListPointer (for DisplayListMenuID)
;>     wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;>     wListMenuID = ITEMLISTMENU
	ld a, ITEMLISTMENU
	ld [wListMenuID], a
;>     wCurrentMenuItem = wBagSavedMenuItem
	ld a, [wBagSavedMenuItem]
	ld [wCurrentMenuItem], a
;>     cancelled = DisplayListMenuID()         # carry: B pressed
	call DisplayListMenuID
;>     wBagSavedMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wBagSavedMenuItem], a
;> if cancelled:
	jr nc, .choseItem
.exitMenu
;>     LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;>     LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;>     UpdateSprites()
	call UpdateSprites
;>     return RedisplayStartMenu(saved)
	jp RedisplayStartMenu
.choseItem
; erase menu cursor (blank each tile in front of an item name)
;> for row in (4, 6, 8, 10):                   # erase the list's cursor
;>     mem[coord(5, row)] = 0x7F
	ld a, ' '
	ld [(4) * SCREEN_WIDTH + (5) + wTileMap], a
	ld [(6) * SCREEN_WIDTH + (5) + wTileMap], a
	ld [(8) * SCREEN_WIDTH + (5) + wTileMap], a
	ld [(10) * SCREEN_WIDTH + (5) + wTileMap], a
;> PlaceUnfilledArrowMenuCursor(0)
	call PlaceUnfilledArrowMenuCursor
;> wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a
;> if wCurItem != BICYCLE:
	ld a, [wCurItem]
	cp BICYCLE
	jp z, .useOrTossItem
; not Bicycle
;>     wTextBoxID = USE_TOSS_MENU_TEMPLATE
	ld a, USE_TOSS_MENU_TEMPLATE
	ld [wTextBoxID], a
;>     DisplayTextBoxID()
	call DisplayTextBoxID
;>     wTopMenuItemY = 11
	ld hl, wTopMenuItemY
	ld a, 11
	ld [hli], a ; top menu item Y
;>     wTopMenuItemX = 14
	ld a, 14
	ld [hli], a ; top menu item X
;>     wCurrentMenuItem = 0
	xor a
	ld [hli], a ; current menu item ID
;>     wMaxMenuItem = 1
	inc hl
	inc a ; a = 1
	ld [hli], a ; max menu item ID
;>     wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [hli], a ; menu watched keys
;>     wLastMenuItem = 0
	xor a
	ld [hl], a ; old menu item id
;>     if PlaceUnfilledArrowMenuCursor(HandleMenuInput()) & PAD_B:
;>         return ItemMenuLoop(saved)
	call HandleMenuInput
	call PlaceUnfilledArrowMenuCursor
	bit B_PAD_B, a
	jr z, .useOrTossItem
	jp ItemMenuLoop
.useOrTossItem
;> wNamedObjectIndex = wCurItem
	ld a, [wCurItem]
	ld [wNamedObjectIndex], a
;> CopyToStringBuffer(GetItemName())
	call GetItemName
	call CopyToStringBuffer
;> if wCurItem == BICYCLE:
	ld a, [wCurItem]
	cp BICYCLE
	jr nz, .notBicycle
;>     if wStatusFlags6 >> BIT_ALWAYS_ON_BIKE & 1:     # Cycling Road
	ld a, [wStatusFlags6]
	bit BIT_ALWAYS_ON_BIKE, a
	jr z, .useItem_closeMenu
;>         PrintText(CannotGetOffHereText)
	ld hl, CannotGetOffHereText
	call PrintText
;>         return ItemMenuLoop(saved)
	jp ItemMenuLoop
;>     how = 'close'
.notBicycle
;> elif wCurrentMenuItem:                      # TOSS
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .tossItem
;>@t1     IsKeyItem()
;>@t2     if not wIsKeyItem and not IsItemHM(wCurItem):     # key items and HMs go all at once
;>@t3         if DisplayChooseQuantityMenu() == 0xFF:      # cancelled
;>@t4             return ItemMenuLoop(saved)
;>@t5     TossItem(addr(wNumBagItems))
;>@t6     return ItemMenuLoop(saved)
; use item
;> else:                                       # USE
;>     wPseudoItemID = 0
	ld [wPseudoItemID], a ; a must be 0 due to above conditional jump
;>     if wCurItem >= HM01:
;>         how = 'party'
	ld a, [wCurItem]
	cp HM01
	jr nc, .useItem_partyMenu
;>     elif IsInArray(wCurItem, UsableItems_CloseMenu, 1)[2]:
;>         how = 'close'
	ld hl, UsableItems_CloseMenu
	ld de, 1
	call IsInArray
	jr c, .useItem_closeMenu
;>     elif IsInArray(wCurItem, UsableItems_PartyMenu, 1)[2]:
;>         how = 'party'
	ld a, [wCurItem]
	ld hl, UsableItems_PartyMenu
	ld de, 1
	call IsInArray
	jr c, .useItem_partyMenu
;>     else:
;>         UseItem()
	call UseItem
;>         return ItemMenuLoop(saved)
	jp ItemMenuLoop
.useItem_closeMenu
;> if how == 'close':
;>     wPseudoItemID = 0
	xor a
	ld [wPseudoItemID], a
;>     UseItem()
	call UseItem
;>     if not wActionResultOrTookBattleTurn:
;>         return ItemMenuLoop(saved)
	ld a, [wActionResultOrTookBattleTurn]
	and a
	jp z, ItemMenuLoop
;>     return CloseStartMenu(saved)
	jp CloseStartMenu
.useItem_partyMenu
;> sprites = wUpdateSpritesEnabled
	ld a, [wUpdateSpritesEnabled]
	push af
;> UseItem()
	call UseItem
;> if wActionResultOrTookBattleTurn == 2:      # the party menu never opened
	ld a, [wActionResultOrTookBattleTurn]
	cp $02
	jp z, .partyMenuNotDisplayed
;>@pm1     wUpdateSpritesEnabled = sprites
;>@pm2     return ItemMenuLoop(saved)
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;> wUpdateSpritesEnabled = sprites
	pop af
	ld [wUpdateSpritesEnabled], a
;> return StartMenu_Item(saved)
	jp StartMenu_Item
.partyMenuNotDisplayed
;=@pm1
	pop af
	ld [wUpdateSpritesEnabled], a
;=@pm2
	jp ItemMenuLoop
.tossItem
;=@t1
	call IsKeyItem
;=@t2
	ld a, [wIsKeyItem]
	and a
	jr nz, .skipAskingQuantity
	ld a, [wCurItem]
	call IsItemHM
	jr c, .skipAskingQuantity
;=@t3
	call DisplayChooseQuantityMenu
	inc a
;=@t4
	jr z, .tossZeroItems
.skipAskingQuantity
;=@t5
	ld hl, wNumBagItems
	call TossItem
.tossZeroItems
;=@t6
	jp ItemMenuLoop

