;@ def StartMenu_TrainerInfo(saved)
;@ START menu <player>: the trainer card with name, money, play time and badges, until a button press.
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
StartMenu_TrainerInfo::
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> animations = hTileAnimations
	ldh a, [hTileAnimations]
	push af
;> hTileAnimations = 0
	xor a
	ldh [hTileAnimations], a
;> DrawTrainerInfo()
	call DrawTrainerInfo
;> predef(DrawBadges)
	ld a, (DrawBadgesPredef - PredefPointers) / 3
	call Predef
;> RunPaletteCommand(SET_PAL_TRAINER_CARD)
	ld b, SET_PAL_TRAINER_CARD
	call RunPaletteCommand
;> GBPalNormal()
	call GBPalNormal
;> WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> ReloadMapData()
	call ReloadMapData
;> LoadGBPal()
	call LoadGBPal
;> hTileAnimations = animations
	pop af
	ldh [hTileAnimations], a
;> return RedisplayStartMenu(saved)
	jp RedisplayStartMenu

; loads tile patterns and draws everything except for gym leader faces / badges
;@ def DrawTrainerInfo()
;@ The trainer card without the badges: the player's picture, the card's tiles (loaded with the LCD off), its two
;@ frames, and NAME, MONEY and TIME.
;@ path: engine/menus/start_sub_menus
DrawTrainerInfo:
;> predef(DisplayPicCenteredOrUpperRight, de=RedPicFront, bc=BANK(RedPicFront) << 8 | 1)    # in the upper right
	ld de, RedPicFront
	ld bc, ((BANK(RedPicFront)) & $ff) << 8 + (($01) & $ff)
	ld a, (DisplayPicCenteredOrUpperRightPredef - PredefPointers) / 3
	call Predef
;> DisableLCD()
	call DisableLCD
;> TrainerInfo_DrawVerticalLine(coord(0, 2), 0x7F)
	ld hl, (2) * SCREEN_WIDTH + (0) + wTileMap
	ld a, ' '
	call TrainerInfo_DrawVerticalLine
;> TrainerInfo_DrawVerticalLine(coord(1, 2), 0x7F)
	ld hl, (2) * SCREEN_WIDTH + (1) + wTileMap
	call TrainerInfo_DrawVerticalLine
;> CopyData(addr(vChars2) + 7 * 16, addr(vChars2), 0x1C * 16)     # move the picture's tiles to the start
	ld hl, vChars2 + TILE_SIZE * $07
	ld de, vChars2 + TILE_SIZE * $00
	ld bc, $1c * TILE_SIZE
	call CopyData
;> TrainerInfo_FarCopyData(TrainerInfoTextBoxTileGraphics, addr(vChars2) + 0x77 * 16, 8 * 16)
	ld hl, TrainerInfoTextBoxTileGraphics
	ld de, vChars2 + TILE_SIZE * $77
	ld bc, 8 * TILE_SIZE
	push bc
	call TrainerInfo_FarCopyData
;> TrainerInfo_FarCopyData(BlankLeaderNames, addr(vChars2) + 0x60 * 16, 0x17 * 16)
	ld hl, BlankLeaderNames
	ld de, vChars2 + TILE_SIZE * $60
	ld bc, $17 * TILE_SIZE
	call TrainerInfo_FarCopyData
;> TrainerInfo_FarCopyData(BadgeNumbersTileGraphics, addr(vChars1) + 0x58 * 16, 8 * 16)
	pop bc
	ld hl, BadgeNumbersTileGraphics
	ld de, vChars1 + TILE_SIZE * $58
	call TrainerInfo_FarCopyData
;> FarCopyData2(BANK(GymLeaderFaceAndBadgeTileGraphics), GymLeaderFaceAndBadgeTileGraphics,
;>              addr(vChars2) + 0x20 * 16, 8 * 8 * 16)
	ld hl, GymLeaderFaceAndBadgeTileGraphics
	ld de, vChars2 + TILE_SIZE * $20
	ld bc, 8 * 8 * TILE_SIZE
	ld a, BANK(GymLeaderFaceAndBadgeTileGraphics)
	call FarCopyData2
;> colon = TextBoxGraphics + 13 * 16
	ld hl, TextBoxGraphics
	ld de, 13 * TILE_SIZE
	add hl, de ; hl = colon tile pattern
;> FarCopyData2(BANK(TextBoxGraphics), colon, addr(vChars1) + 0x56 * 16, 16)
	ld de, vChars1 + TILE_SIZE * $56
	ld bc, TILE_SIZE
	ld a, BANK(TextBoxGraphics)
	push bc
	call FarCopyData2
;> TrainerInfo_FarCopyData(TrainerInfoTextBoxTileGraphics + 8 * 16, addr(vChars1) + 0x57 * 16, 16)  # background
	pop bc
	ld hl, TrainerInfoTextBoxTileGraphics + TILE_SIZE * 8 ; background tile pattern
	ld de, vChars1 + TILE_SIZE * $57
	call TrainerInfo_FarCopyData
;> EnableLCD()
	call EnableLCD
;> wTrainerInfoTextBoxWidthPlus1 = 19
	ld hl, wTrainerInfoTextBoxWidthPlus1
	ld a, 18 + 1
	ld [hli], a
;> wTrainerInfoTextBoxWidth = 18
	dec a
	ld [hli], a
;> wTrainerInfoTextBoxNextRowOffset = 1
	ld [hl], 1
;> TrainerInfo_DrawTextBox(coord(0, 0))
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	call TrainerInfo_DrawTextBox
;> wTrainerInfoTextBoxWidthPlus1 = 17
	ld hl, wTrainerInfoTextBoxWidthPlus1
	ld a, 16 + 1
	ld [hli], a
;> wTrainerInfoTextBoxWidth = 16
	dec a
	ld [hli], a
;> wTrainerInfoTextBoxNextRowOffset = 3
	ld [hl], 3
;> TrainerInfo_DrawTextBox(coord(1, 10))
	ld hl, (10) * SCREEN_WIDTH + (1) + wTileMap
	call TrainerInfo_DrawTextBox
;> TrainerInfo_DrawVerticalLine(coord(0, 10), 0xD7)
	ld hl, (10) * SCREEN_WIDTH + (0) + wTileMap
	ld a, $d7
	call TrainerInfo_DrawVerticalLine
;> TrainerInfo_DrawVerticalLine(coord(19, 10), 0xD7)
	ld hl, (10) * SCREEN_WIDTH + (19) + wTileMap
	call TrainerInfo_DrawVerticalLine
;> PlaceString(TrainerInfo_BadgesText, coord(6, 9))
	ld hl, (9) * SCREEN_WIDTH + (6) + wTileMap
	ld de, TrainerInfo_BadgesText
	call PlaceString
;> PlaceString(TrainerInfo_NameMoneyTimeText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, TrainerInfo_NameMoneyTimeText
	call PlaceString
;> PlaceString(addr(wPlayerName), coord(7, 2))
	ld hl, (2) * SCREEN_WIDTH + (7) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PrintBCDNumber(addr(wPlayerMoney), coord(8, 4), 3 | LEADING_ZEROES | LEFT_ALIGN | MONEY_SIGN)
	ld hl, (4) * SCREEN_WIDTH + (8) + wTileMap
	ld de, wPlayerMoney
	ld c, 3 | LEADING_ZEROES | LEFT_ALIGN | MONEY_SIGN
	call PrintBCDNumber
;> end = PrintNumber(addr(wPlayTimeHours), coord(9, 6), LEFT_ALIGN | 1, 3)
	ld hl, (6) * SCREEN_WIDTH + (9) + wTileMap
	ld de, wPlayTimeHours
	ld bc, ((LEFT_ALIGN | 1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> mem[end] = 0xD6                             # colon
	ld [hl], $d6 ; colon tile ID
;> return PrintNumber(addr(wPlayTimeMinutes), end + 1, LEADING_ZEROES | 1, 2)
	inc hl
	ld de, wPlayTimeMinutes
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((2) & $ff)
	jp PrintNumber

;@ def TrainerInfo_FarCopyData(src: hl, dest: de, count: bc)
;@ Copy trainer card graphics from their bank.
;@ test: count = rand(1, 256); dest = rand(0xC000, 0xD000); hLoadedROMBank = 4
;@ path: engine/menus/start_sub_menus
TrainerInfo_FarCopyData:
;> return FarCopyData2(BANK(TrainerInfoTextBoxTileGraphics), src, dest, count)
	ld a, BANK(TrainerInfoTextBoxTileGraphics)
	jp FarCopyData2

;@ path: engine/menus/start_sub_menus
TrainerInfo_NameMoneyTimeText:
	db   "NAME/"
	db "<NEXT>", "MONEY/"
	db "<NEXT>", "TIME/@"

; $76 is a circle tile
;@ path: engine/menus/start_sub_menus
TrainerInfo_BadgesText:
	db $76,"BADGES",$76,"@"

; draws a text box on the trainer info screen
; height is always 6
; INPUT:
; hl = destination address
; [wTrainerInfoTextBoxWidthPlus1] = width
; [wTrainerInfoTextBoxWidth] = width - 1
; [wTrainerInfoTextBoxNextRowOffset] = distance from the end of a text box row to the start of the next
;@ def TrainerInfo_DrawTextBox(corner: hl)
;@ One of the trainer card's frames, wTrainerInfoTextBoxWidth wide and 6 rows high inside, rows
;@ wTrainerInfoTextBoxNextRowOffset tiles apart after each edge.
;@ test: corner = wTileMap + rand(0, 40)
;@ path: engine/menus/start_sub_menus
TrainerInfo_DrawTextBox:
;> p = TrainerInfo_DrawHorizontalEdge(corner, 0x79, 0x7A, 0x7B)
	ld a, $79 ; upper left corner tile ID
	; top edge and upper right corner tile ID's
	ld de, (($7a) & $ff) << 8 + (($7b) & $ff)
	call TrainerInfo_DrawHorizontalEdge ; draw top edge
;> p = TrainerInfo_NextTextBoxRow(p)
	call TrainerInfo_NextTextBoxRow
;> for _ in range(6):
	ld a, [wTrainerInfoTextBoxWidthPlus1]
	ld e, a
	ld d, 0
	ld c, 6 ; height of the text box
.loop
;>     mem[p] = 0x7C
	ld [hl], $7c ; left edge tile ID
;>     p += wTrainerInfoTextBoxWidthPlus1
	add hl, de
;>     mem[p] = 0x78
	ld [hl], $78 ; right edge tile ID
;>     p = TrainerInfo_NextTextBoxRow(p)
	call TrainerInfo_NextTextBoxRow
	dec c
	jr nz, .loop
;> TrainerInfo_DrawHorizontalEdge(p, 0x7D, 0x77, 0x7E)
	ld a, $7d ; lower left corner tile ID
	; bottom edge and lower right corner tile ID's
	ld de, (($77) & $ff) << 8 + (($7e) & $ff)

;@ def TrainerInfo_DrawHorizontalEdge(dest: hl, left: a, edge: d, right: e) -> hl
;@ A frame's top or bottom row: a corner, wTrainerInfoTextBoxWidth edge tiles, the other corner (hl stays on it).
;@ test: dest = wTileMap + rand(0, 100)
;@ path: engine/menus/start_sub_menus
TrainerInfo_DrawHorizontalEdge:
;> mem[dest] = left
;> dest += 1
	ld [hli], a ; place left corner tile
;> for _ in range(wTrainerInfoTextBoxWidth or 256):
	ld a, [wTrainerInfoTextBoxWidth]
	ld c, a
	ld a, d
.loop
;>     mem[dest] = edge
;>     dest += 1
	ld [hli], a ; place edge tile
	dec c
	jr nz, .loop
;> mem[dest] = right
	ld a, e
	ld [hl], a ; place right corner tile
;> return dest
	ret

;@ def TrainerInfo_NextTextBoxRow(p: hl) -> hl
;@ Move wTrainerInfoTextBoxNextRowOffset tiles on (0 means 256).
;@ path: engine/menus/start_sub_menus
TrainerInfo_NextTextBoxRow:
;> return (p + (wTrainerInfoTextBoxNextRowOffset or 256)) & 0xFFFF
	ld a, [wTrainerInfoTextBoxNextRowOffset] ; distance to the start of the next row
.loop
	inc hl
	dec a
	jr nz, .loop
	ret

; draws a vertical line
; INPUT:
; hl = address of top tile in the line
; a = tile ID
;@ def TrainerInfo_DrawVerticalLine(top: hl, tile: a)
;@ A column of 8 tiles downwards from top.
;@ test: top = wTileMap + rand(0, 100)
;@ path: engine/menus/start_sub_menus
TrainerInfo_DrawVerticalLine:
;> step = SCREEN_WIDTH
	ld de, SCREEN_WIDTH
;>@lp for _ in range(8):
	ld c, 8
.loop
;>     mem[top] = tile
	ld [hl], a
;>     top += step
	add hl, de
;=@lp
	dec c
	jr nz, .loop
	ret

;@ def StartMenu_SaveReset(saved)
;@ START menu SAVE (or RESET while linked, which restarts the game).
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
StartMenu_SaveReset::
;> if wStatusFlags4 >> BIT_LINK_CONNECTED & 1:      # RESET while linked
;>     return Init()
	ld a, [wStatusFlags4]
	bit BIT_LINK_CONNECTED, a
	jp nz, Init
;> predef(SaveMenu)
	ld a, (SaveMenuPredef - PredefPointers) / 3
	call Predef
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> return HoldTextDisplayOpen(saved)
	jp HoldTextDisplayOpen

;@ def StartMenu_Option(saved)
;@ START menu OPTION.
;@ test: skip saved is the ROM bank DisplayTextID left on the stack
;@ path: engine/menus/start_sub_menus
StartMenu_Option::
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> farcall(DisplayOptionMenu)
	ld hl, DisplayOptionMenu
	ld b, BANK(DisplayOptionMenu)
	call Bankswitch
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> UpdateSprites()
	call UpdateSprites
;> return RedisplayStartMenu(saved)
	jp RedisplayStartMenu

;@ def SwitchPartyMon()
;@ Swap two party Pokémon (wMenuItemToSwap and the one under the cursor), blank both rows with a sound, and
;@ redraw the party menu.
;@ path: engine/menus/start_sub_menus
SwitchPartyMon::
;> SwitchPartyMon_InitVarOrSwapData()
	call SwitchPartyMon_InitVarOrSwapData ; swap data
;> SwitchPartyMon_ClearGfx(wSwappedMenuItem)
	ld a, [wSwappedMenuItem]
	call SwitchPartyMon_ClearGfx
;> SwitchPartyMon_ClearGfx(wCurrentMenuItem)
	ld a, [wCurrentMenuItem]
	call SwitchPartyMon_ClearGfx
;> return RedrawPartyMenu_()
	jp RedrawPartyMenu_

;@ def SwitchPartyMon_ClearGfx(slot: a)
;@ Blank party menu row `slot` and hide its icon, then the swap sound.
;@ test: slot = rand(0, 5)
;@ path: engine/menus/start_sub_menus
SwitchPartyMon_ClearGfx:
;> p = AddNTimes(coord(0, 0), SCREEN_WIDTH * 2, slot)
	push af
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_WIDTH * 2
	call AddNTimes
;> for i in range(SCREEN_WIDTH * 2):
;>     mem[p + i] = 0x7F
	ld c, SCREEN_WIDTH * 2
	ld a, ' '
.clearMonBGLoop ; clear the mon's row in the party menu
	ld [hli], a
	dec c
	jr nz, .clearMonBGLoop
;> icon = AddNTimes(addr(wShadowOAMSprite00YCoord), OBJ_SIZE * 4, slot)
	pop af
	ld hl, wShadowOAMSprite00YCoord
	ld bc, OBJ_SIZE * 4
	call AddNTimes
;> for i in range(OBJ_SIZE):                   # its four sprites below the screen
;>     mem[icon + OBJ_SIZE * i] = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld de, OBJ_SIZE
	ld c, e
.clearMonOAMLoop
	ld [hl], SCREEN_HEIGHT_PX + OAM_Y_OFS
	add hl, de
	dec c
	jr nz, .clearMonOAMLoop
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> return PlaySound(SFX_SWAP)
	ld a, SFX_SWAP
	jp PlaySound

;@ path: engine/menus/start_sub_menus
;@ def SwitchPartyMon_InitVarOrSwapData()
;@ The first call remembers the Pokémon to move (wMenuItemToSwap, counting from 1); the second swaps its species,
;@ data, original trainer and nickname with the Pokémon under the cursor (nothing if it is the same one).
;@ test: wMenuItemToSwap = rand(0, 6); wCurrentMenuItem = rand(0, 5); wWhichPokemon = rand(0, 5)
SwitchPartyMon_InitVarOrSwapData:
; This is used to initialise [wMenuItemToSwap] and to actually swap the data.
;> if not wMenuItemToSwap:
	ld a, [wMenuItemToSwap]
	and a ; has [wMenuItemToSwap] been initialised yet?
	jr nz, .pickedMonsToSwap
; If not, initialise [wMenuItemToSwap] so that it matches the current mon.
;>     wMenuItemToSwap = wWhichPokemon + 1
	ld a, [wWhichPokemon]
	inc a ; [wMenuItemToSwap] counts from 1
	ld [wMenuItemToSwap], a
;>     return
	ret
.pickedMonsToSwap
;> wPartyMenuTypeOrMessageID = 0
	xor a
	ld [wPartyMenuTypeOrMessageID], a
;> first = wMenuItemToSwap - 1
	ld a, [wMenuItemToSwap]
	dec a
	ld b, a
;> wSwappedMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wSwappedMenuItem], a
;> if wCurrentMenuItem == first:
	cp b ; swapping a mon with itself?
	jr nz, .swappingDifferentMons
; can't swap a mon with itself
;>     wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a
;>     wPartyMenuTypeOrMessageID = 0
	ld [wPartyMenuTypeOrMessageID], a
;>     return
	ret
.swappingDifferentMons
;> wMenuItemToSwap = first
	ld a, b
	ld [wMenuItemToSwap], a
;> # (hl and de are kept)
	push hl
	push de
;> base = addr(wPartySpecies)
	ld hl, wPartySpecies
	ld d, h
	ld e, l
;> x = base + wCurrentMenuItem                 # the two species
	ld a, [wCurrentMenuItem]
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
;> y = addr(wPartySpecies) + first
	ld a, [wMenuItemToSwap]
	add e
	ld e, a
	jr nc, .noCarry2
	inc d
.noCarry2
;> hSwapTemp = mem[x]
	ld a, [hl]
	ldh [hSwapTemp], a
;> mem[x] = mem[y]
	ld a, [de]
	ld [hl], a
;> mem[y] = hSwapTemp
	ldh a, [hSwapTemp]
	ld [de], a
;> tmp = addr(wSwitchPartyMonTempBuffer)
;> x = AddNTimes(addr(wPartyMons), PARTYMON_STRUCT_LENGTH, wCurrentMenuItem)   # the two data structs
	ld hl, wPartyMons
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wCurrentMenuItem]
	call AddNTimes
;> CopyData(x, tmp, PARTYMON_STRUCT_LENGTH)
	push hl
	ld de, wSwitchPartyMonTempBuffer
	ld bc, PARTYMON_STRUCT_LENGTH
	call CopyData
;> y = AddNTimes(addr(wPartyMons), PARTYMON_STRUCT_LENGTH, wMenuItemToSwap)
	ld hl, wPartyMons
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wMenuItemToSwap]
	call AddNTimes
;> CopyData(y, x, PARTYMON_STRUCT_LENGTH)
	pop de
	push hl
	ld bc, PARTYMON_STRUCT_LENGTH
	call CopyData
;> CopyData(tmp, y, PARTYMON_STRUCT_LENGTH)
	pop de
	ld hl, wSwitchPartyMonTempBuffer
	ld bc, PARTYMON_STRUCT_LENGTH
	call CopyData
;> x = SkipFixedLengthTextEntries(addr(wPartyMonOT), wCurrentMenuItem)        # the original trainers' names
	ld hl, wPartyMonOT
	ld a, [wCurrentMenuItem]
	call SkipFixedLengthTextEntries
;> CopyData(x, tmp, NAME_LENGTH)
	push hl
	ld de, wSwitchPartyMonTempBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> y = SkipFixedLengthTextEntries(addr(wPartyMonOT), wMenuItemToSwap)
	ld hl, wPartyMonOT
	ld a, [wMenuItemToSwap]
	call SkipFixedLengthTextEntries
;> CopyData(y, x, NAME_LENGTH)
	pop de
	push hl
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(tmp, y, NAME_LENGTH)
	pop de
	ld hl, wSwitchPartyMonTempBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> x = SkipFixedLengthTextEntries(addr(wPartyMonNicks), wCurrentMenuItem)     # the nicknames
	ld hl, wPartyMonNicks
	ld a, [wCurrentMenuItem]
	call SkipFixedLengthTextEntries
;> CopyData(x, tmp, NAME_LENGTH)
	push hl
	ld de, wSwitchPartyMonTempBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> y = SkipFixedLengthTextEntries(addr(wPartyMonNicks), wMenuItemToSwap)
	ld hl, wPartyMonNicks
	ld a, [wMenuItemToSwap]
	call SkipFixedLengthTextEntries
;> CopyData(y, x, NAME_LENGTH)
	pop de
	push hl
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(tmp, y, NAME_LENGTH)
	pop de
	ld hl, wSwitchPartyMonTempBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> wSwappedMenuItem = wMenuItemToSwap
	ld a, [wMenuItemToSwap]
	ld [wSwappedMenuItem], a
;> wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a
;> wPartyMenuTypeOrMessageID = 0
	ld [wPartyMenuTypeOrMessageID], a
	pop de
	pop hl
	ret
; tests if mon [wCurPartySpecies] can learn move [wMoveNum]
;@ def CanLearnTM() -> c
;@ Whether Pokémon wCurPartySpecies can learn TM / HM move wMoveNum: its bit in the species' learnset. Nonzero if so.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/tms
CanLearnTM:
;> wCurSpecies = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> learnset = addr(wMonHLearnset)
	ld hl, wMonHLearnset
	push hl
;> move = wMoveNum
	ld a, [wMoveNum]
	ld b, a
;> tm = 0
	ld c, $0
;> p = TechnicalMachines
	ld hl, TechnicalMachines
.findTMloop
;>@lp while True:
;>     here = mem[p]
;>     p += 1
	ld a, [hli]
;>     if here == move:
;>         break
	cp b
	jr z, .TMfoundLoop
;>     tm += 1
	inc c
;=@lp
	jr .findTMloop
.TMfoundLoop
;> return FlagAction(learnset, tm, FLAG_TEST)
	pop hl
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	jp Predef

; converts TM/HM number in [wTempTMHM] into move number
; HMs start at 51
;@ def TMToMove()
;@ Turn TM / HM number wTempTMHM (HMs follow the TMs, from 51) into the move it teaches, in place.
;@ path: engine/items/tms
TMToMove:
;> i = (wTempTMHM - 1) & 0xFF
	ld a, [wTempTMHM]
	dec a
;> p = TechnicalMachines + i
	ld hl, TechnicalMachines
	ld b, $0
	ld c, a
	add hl, bc
;> wTempTMHM = mem[p]
	ld a, [hl]
	ld [wTempTMHM], a
;> return
	ret

