;@ path: engine/battle/end_of_battle
;@ def EndOfBattle()
;@ After any battle. A link battle saves the opponent's status and shows YOU WIN / YOU LOSE / DRAW; a won battle
;@ hands over the Pay Day money. Then Pokémon that can evolve do, and all battle variables are cleared.
;@ test: skip waits for the sound to finish
EndOfBattle:
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .notLinkBattle
; link battle
;>     # the opponent's party keeps the status its Pokémon ended with
;>     mem[AddNTimes(wEnemyMon1Status, PARTYMON_STRUCT_LENGTH, wEnemyMonPartyPos)] = wEnemyMonStatus
	ld a, [wEnemyMonPartyPos]
	ld hl, wEnemyMon1Status
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld a, [wEnemyMonStatus]
	ld [hl], a
;>     ClearScreen()
	call ClearScreen
;>     DisplayLinkBattleVersusTextBox()
	ld hl, DisplayLinkBattleVersusTextBox
	ld b, BANK(DisplayLinkBattleVersusTextBox)
	call Bankswitch
;>     if wBattleResult == 0:
;>         text = YouWinText
	ld a, [wBattleResult]
	cp $1
	ld de, YouWinText
	jr c, .placeWinOrLoseString
;>     elif wBattleResult == 1:
;>         text = YouLoseText
	ld de, YouLoseText
	jr z, .placeWinOrLoseString
;>     else:
;>         text = DrawText
	ld de, DrawText
.placeWinOrLoseString
;>     PlaceString(text, coord(6, 8))
	ld hl, (8) * SCREEN_WIDTH + (6) + wTileMap
	call PlaceString
;>     DelayFrames(200)
;>     evolve = True
	ld c, 200
	call DelayFrames
	jr .evolution
.notLinkBattle
;> else:
;>     evolve = wBattleResult == 0            # only after a won battle
;>     if evolve:
	ld a, [wBattleResult]
	and a
	jr nz, .resetVariables
;>         if wTotalPayDayMoney[0] or wTotalPayDayMoney[1] or wTotalPayDayMoney[2]:
	ld hl, wTotalPayDayMoney
	ld a, [hli]
	or [hl]
	inc hl
	or [hl]
	jr z, .evolution ; if pay day money is 0, jump
;>             predef(AddBCDPredef, hl=wTotalPayDayMoney + 2, de=wPlayerMoney + 2, bc=3)
	ld de, wPlayerMoney + 2
	ld c, $3
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;>             PrintText(PickUpPayDayMoneyText)
	ld hl, PickUpPayDayMoneyText
	call PrintText
.evolution
;> if evolve:
;>     wForceEvolution = 0
	xor a
	ld [wForceEvolution], a
;>     EvolutionAfterBattle()
	ld a, (EvolutionAfterBattlePredef - PredefPointers) / 3
	call Predef
.resetVariables
;> wLowHealthAlarm = 0                      # the low-HP beeping stops
;> wChannelSoundIDs[CHAN5] = 0
	xor a
	ld [wLowHealthAlarm], a ;disable low health alarm
	ld [wChannelSoundIDs + CHAN5], a
;> wIsInBattle = wBattleType = wMoveMissed = wCurOpponent = 0
	ld [wIsInBattle], a
	ld [wBattleType], a
	ld [wMoveMissed], a
	ld [wCurOpponent], a
;> wForcePlayerToChooseMon = wNumRunAttempts = wEscapedFromBattle = 0
	ld [wForcePlayerToChooseMon], a
	ld [wNumRunAttempts], a
	ld [wEscapedFromBattle], a
;> fill(addr(wPartyAndBillsPCSavedMenuItem), 0, 4)
	ld hl, wPartyAndBillsPCSavedMenuItem
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wListScrollOffset = 0
	ld [wListScrollOffset], a
;> fill(addr(wBattleStatusData), 0, addr(wBattleStatusDataEnd) - addr(wBattleStatusData))
	ld hl, wBattleStatusData
	ld b, wBattleStatusDataEnd - wBattleStatusData
.loop
	ld [hli], a
	dec b
	jr nz, .loop
;> wStatusFlags2 |= 1 << BIT_WILD_ENCOUNTER_COOLDOWN   # no wild battle right away
	ld hl, wStatusFlags2
	set BIT_WILD_ENCOUNTER_COOLDOWN, [hl]
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> wDestinationWarpID = 0xFF
	ld a, $ff
	ld [wDestinationWarpID], a
	ret

;@ path: engine/battle/end_of_battle
YouWinText:
	db "YOU WIN@"

;@ path: engine/battle/end_of_battle
YouLoseText:
	db "YOU LOSE@"

;@ path: engine/battle/end_of_battle
DrawText:
	db "  DRAW@"

;@ path: engine/battle/end_of_battle
PickUpPayDayMoneyText:
	db TX_FAR
	dw _PickUpPayDayMoneyText
	db BANK(_PickUpPayDayMoneyText)
	db TX_END
; try to initiate a wild pokemon encounter
; returns success in Z
;@ path: engine/battle/wild_encounters
;@ def TryDoWildEncounter() -> zero
;@ After each step: does a wild Pokémon appear? Zero (and a = 0) means yes. Grass and water tiles have their own
;@ encounter rates; in caves and other indoor maps (except forests) every tile counts as grass. Repel blocks
;@ Pokémon below the level of the first party Pokémon, and its last step shows "REPEL's effect wore off".
TryDoWildEncounter:
;> if wNPCMovementScriptPointerTableNum:      # a scripted walk
;>     return False
	ld a, [wNPCMovementScriptPointerTableNum]
	and a
	ret nz
;> if wMovementFlags:                       # exiting a door, jumping a ledge or fishing
;>     return False
	ld a, [wMovementFlags]
	and a ; is player exiting a door, jumping over a ledge, or fishing?
	ret nz
;> if IsPlayerStandingOnDoorTileOrWarpTile():
	ld hl, IsPlayerStandingOnDoorTileOrWarpTile
	ld b, BANK(IsPlayerStandingOnDoorTileOrWarpTile)
	call Bankswitch
	jr nc, .notStandingOnDoorOrWarpTile
;>     return False
.CantEncounter
	ld a, $1
	and a
	ret
.notStandingOnDoorOrWarpTile
;> if IsPlayerJustOutsideMap():
;>     return False
	ld hl, IsPlayerJustOutsideMap
	ld b, BANK(IsPlayerJustOutsideMap)
	call Bankswitch
	jr z, .CantEncounter
;> if wRepelRemainingSteps:
	ld a, [wRepelRemainingSteps]
	and a
	jr z, .next
;>@dec     wRepelRemainingSteps -= 1
;>     if wRepelRemainingSteps == 0:        # the last step: the Repel wears off
	dec a
	jr z, .lastRepelStep
;=@dec
	ld [wRepelRemainingSteps], a
;>@txt         hTextID = TEXT_REPEL_WORE_OFF
;>@show         EnableAutoTextBoxDrawing(); DisplayTextID()
;>@no         return False
.next
; determine if wild pokemon can appear in the half-block we're standing in
; is the bottom right tile (9,9) of the half-block we're standing in a grass/water tile?
;> tile = mem[coord(9, 9)]                  # bottom right tile of the half-block we stand in
	ld hl, (9) * SCREEN_WIDTH + (9) + wTileMap
	ld c, [hl]
;> if tile == wGrassTile:
;>     rate = wGrassRate
	ld a, [wGrassTile]
	cp c
	ld a, [wGrassRate]
	jr z, .CanEncounter
;> elif tile == 0x14:                       # the water tile in every tileset that has water
;>     rate = wWaterRate
	ld a, $14 ; in all tilesets with a water tile, this is its id
	cp c
	ld a, [wWaterRate]
	jr z, .CanEncounter
; even if not in grass/water, standing anywhere we can encounter pokemon
; so long as the map is "indoor" and has wild pokemon defined.
; ...as long as it's not Viridian Forest or Safari Zone.
;> elif wCurMap < FIRST_INDOOR_MAP or wCurMapTileset == FOREST:
;>     return False
	ld a, [wCurMap]
	cp FIRST_INDOOR_MAP ; is this an indoor map?
	jr c, .CantEncounter2
	ld a, [wCurMapTileset]
	cp FOREST ; Viridian Forest/Safari Zone
	jr z, .CantEncounter2
;> else:
;>     rate = wGrassRate                    # indoors every tile counts as grass
	ld a, [wGrassRate]
.CanEncounter
; compare encounter chance with a random number to determine if there will be an encounter
;> if hRandomAdd >= rate:
;>     return False
	ld b, a
	ldh a, [hRandomAdd]
	cp b
	jr nc, .CantEncounter2
;> r = hRandomSub
;> slot = WildMonEncounterSlotChances
	ldh a, [hRandomSub]
	ld b, a
	ld hl, WildMonEncounterSlotChances
.determineEncounterSlot
;> while mem[slot] < r:                     # the first slot whose chance reaches r
;>     slot += 2
	ld a, [hli]
	cp b
	jr nc, .gotEncounterSlot
	inc hl
	jr .determineEncounterSlot
.gotEncounterSlot
; determine which wild pokemon (grass or water) can appear in the half-block we're standing in
;> offset = mem[slot + 1]
;> mons = wWaterMons if mem[coord(8, 9)] == 0x14 else wGrassMons
	ld c, [hl]
	ld hl, wGrassMons
	ld a, [(9) * SCREEN_WIDTH + (8) + wTileMap]
	cp $14 ; is the bottom left tile (8,9) of the half-block we're standing in a water tile?
	jr nz, .gotWildEncounterType ; else, it's treated as a grass tile by default
	ld hl, wWaterMons
; since the bottom right tile of a "left shore" half-block is $14 but the bottom left tile is not,
; "left shore" half-blocks (such as the one in the east coast of Cinnabar) load grass encounters.
.gotWildEncounterType
;> wCurEnemyLevel = mem[mons + offset]
	ld b, 0
	add hl, bc
	ld a, [hli]
	ld [wCurEnemyLevel], a
;> wCurPartySpecies = wEnemyMonSpecies2 = mem[mons + offset + 1]
	ld a, [hl]
	ld [wCurPartySpecies], a
	ld [wEnemyMonSpecies2], a
;> if wRepelRemainingSteps:                          # Repel keeps weaker Pokémon away
	ld a, [wRepelRemainingSteps]
	and a
	jr z, .willEncounter
;>     if wCurEnemyLevel < mem[wPartyMon1Level]:
;>         return False
	ld a, [wPartyMon1Level]
	ld b, a
	ld a, [wCurEnemyLevel]
	cp b
	jr c, .CantEncounter2 ; repel prevents encounters if the leading party mon's level is higher than the wild mon
;>@yes return True
	jr .willEncounter
.lastRepelStep
;=@dec
	ld [wRepelRemainingSteps], a
;=@txt
	ld a, TEXT_REPEL_WORE_OFF
	ldh [hTextID], a
;=@show
	call EnableAutoTextBoxDrawing
	call DisplayTextID
.CantEncounter2
;=@no
	ld a, $1
	and a
	ret
.willEncounter
;=@yes
	xor a
	ret



;@ path: engine/battle/wild_encounters
WildMonEncounterSlotChances:
; There are 10 slots for wild pokemon, and this is the list that defines how common each of
; those 10 slots is. A random number is generated and then the cumulative chance value up to the current
; slot (included) is compared against that random number. If the random number is less than or equal
; to said cumulative value, then that slot is chosen.
	; 51/256 = 19.9% chance of slot 0
	db $33 - 1
	db $0 * 2
	; 51/256 = 19.9% chance of slot 1
	db $66 - 1
	db $1 * 2
	; 39/256 = 15.2% chance of slot 2
	db $8D - 1
	db $2 * 2
	; 25/256 =  9.8% chance of slot 3
	db $A6 - 1
	db $3 * 2
	; 25/256 =  9.8% chance of slot 4
	db $BF - 1
	db $4 * 2
	; 25/256 =  9.8% chance of slot 5
	db $D8 - 1
	db $5 * 2
	; 13/256 =  5.1% chance of slot 6
	db $E5 - 1
	db $6 * 2
	; 13/256 =  5.1% chance of slot 7
	db $F2 - 1
	db $7 * 2
	; 11/256 =  4.3% chance of slot 8
	db $FD - 1
	db $8 * 2
	;  3/256 =  1.2% chance of slot 9
	db $100 - 1
	db $9 * 2
;@ path: engine/battle/move_effects/recoil
;@ def RecoilEffect_()
;@ Recoil moves hurt the attacker by a quarter of the damage dealt (Struggle: half), at least 1 HP; its HP stops
;@ at 0 and the bar slides down.
RecoilEffect_:
;> if hWhoseTurn == 0:
;>     move, max_hp = wPlayerMoveNum, wBattleMonMaxHP
	ldh a, [hWhoseTurn]
	and a
	ld a, [wPlayerMoveNum]
	ld hl, wBattleMonMaxHP
	jr z, .recoilEffect
;> else:
;>     move, max_hp = wEnemyMoveNum, wEnemyMonMaxHP
	ld a, [wEnemyMoveNum]
	ld hl, wEnemyMonMaxHP
.recoilEffect
;> damage = mem[wDamage] << 8 | mem[wDamage + 1]
	ld d, a
	ld a, [wDamage]
	ld b, a
	ld a, [wDamage + 1]
	ld c, a
;> recoil = damage >> 1
	srl b
	rr c
;> if move != STRUGGLE:
;>     recoil >>= 1                         # a quarter of the damage
	ld a, d
	cp STRUGGLE ; struggle deals 50% recoil damage
	jr z, .gotRecoilDamage
	srl b
	rr c
.gotRecoilDamage
;> if recoil == 0:
;>     recoil = 1
	ld a, b
	or c
	jr nz, .updateHP
	inc c ; minimum recoil damage is 1
.updateHP
;> mem[wHPBarMaxHP + 1], mem[wHPBarMaxHP] = mem[max_hp], mem[max_hp + 1]
; subtract HP from user due to the recoil damage
	ld a, [hli]
	ld [wHPBarMaxHP+1], a
	ld a, [hl]
	ld [wHPBarMaxHP], a
;> hp = max_hp + (wBattleMonHP - wBattleMonMaxHP)
	push bc
	ld bc, wBattleMonHP - wBattleMonMaxHP
	add hl, bc
	pop bc
;> old = mem[hp] << 8 | mem[hp + 1]
;> mem[wHPBarOldHP] = lo(old)
	ld a, [hl]
	ld [wHPBarOldHP], a
;> new = old - recoil
;> mem[hp + 1] = mem[wHPBarNewHP] = lo(new)
	sub c
	ld [hld], a
	ld [wHPBarNewHP], a
;> mem[wHPBarOldHP + 1] = hi(old)
;> mem[hp] = mem[wHPBarNewHP + 1] = hi(new)
	ld a, [hl]
	ld [wHPBarOldHP+1], a
	sbc b
	ld [hl], a
	ld [wHPBarNewHP+1], a
;> if new < 0:
	jr nc, .getHPBarCoords
; if recoil damage is higher than the Pokemon's HP, set its HP to 0
;>     mem[hp], mem[hp + 1] = 0, 0
;>     mem[wHPBarNewHP], mem[wHPBarNewHP + 1] = 0, 0
	xor a
	ld [hli], a
	ld [hl], a
	ld hl, wHPBarNewHP
	ld [hli], a
	ld [hl], a
.getHPBarCoords
;> if hWhoseTurn == 0:
;>     bar, bar_type = coord(10, 9), 1
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ldh a, [hWhoseTurn]
	and a
	ld a, $1
	jr z, .updateHPBar
;> else:
;>     bar, bar_type = coord(2, 2), 0
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	xor a
.updateHPBar
;> wHPBarType = bar_type
;> predef(UpdateHPBar2, hl=bar)
	ld [wHPBarType], a
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;> PrintText(HitWithRecoilText)
	ld hl, HitWithRecoilText
	jp PrintText
;@ path: engine/battle/move_effects/recoil
HitWithRecoilText:
	db TX_FAR
	dw _HitWithRecoilText
	db BANK(_HitWithRecoilText)
	db TX_END
;@ path: engine/battle/move_effects/conversion
;@ def ConversionEffect_()
;@ Conversion: the attacker takes on the target's two types - unless the target is out of reach underground or in
;@ the air (Dig, Fly).
ConversionEffect_:
;> if hWhoseTurn == 0:
;>     src, dest, status = wEnemyMonType1, wBattleMonType1, wEnemyBattleStatus1
	ld hl, wEnemyMonType1
	ld de, wBattleMonType1
	ldh a, [hWhoseTurn]
	and a
	ld a, [wEnemyBattleStatus1]
	jr z, .conversionEffect
;> else:
;>     src, dest, status = wBattleMonType1, wEnemyMonType1, wPlayerBattleStatus1
	push hl
	ld h, d
	ld l, e
	pop de
	ld a, [wPlayerBattleStatus1]
.conversionEffect
;> if status >> INVULNERABLE & 1:
;>     return PrintButItFailedText()
	bit INVULNERABLE, a ; is mon immune to typical attacks (dig/fly)
	jr nz, PrintButItFailedText
;> mem[dest] = mem[src]
;> mem[dest + 1] = mem[src + 1]
; copy target's types to user
	ld a, [hli]
	ld [de], a
	inc de
	ld a, [hl]
	ld [de], a
;> CallBankF(PlayCurrentMoveAnimation)
	ld hl, PlayCurrentMoveAnimation
	call CallBankF
;> PrintText(ConvertedTypeText)
	ld hl, ConvertedTypeText
	jp PrintText

;@ path: engine/battle/move_effects/conversion
ConvertedTypeText:
	db TX_FAR
	dw _ConvertedTypeText
	db BANK(_ConvertedTypeText)
	db TX_END

;@ path: engine/battle/move_effects/conversion
;@ def PrintButItFailedText()
;@ "But it failed!", through the battle core's bank.
PrintButItFailedText:
;> return CallBankF(PrintButItFailedText_)
	ld hl, PrintButItFailedText_
;@ path: engine/battle/move_effects/conversion
;@ def CallBankF(target: hl)
;@ Run a routine of the battle core's bank (bank $F) from here.
;@ test: skip jumps to the routine whose address is in hl
CallBankF:
;> return Bankswitch(BANK(PrintButItFailedText_), target)
	ld b, BANK(PrintButItFailedText_)
	jp Bankswitch
;@ path: engine/battle/move_effects/haze
;@ def HazeEffect_()
;@ Haze: every stat stage on both sides back to normal, the battle stats back to the unmodified ones, the target's
;@ major status cured (a sleeping or frozen target also loses its chosen move this turn) and both sides' disabled
;@ moves, confusion, focus energy, mist, leech seed, toxic, Reflect and Light Screen cleared.
HazeEffect_:
;> ResetStatMods(addr(wPlayerMonAttackMod), 7)
	ld a, $7
; store 7 on every stat mod
	ld hl, wPlayerMonAttackMod
	call ResetStatMods
;> ResetStatMods(addr(wEnemyMonAttackMod), 7)
	ld hl, wEnemyMonAttackMod
	call ResetStatMods
;> ResetStats(wPlayerMonUnmodifiedAttack, wBattleMonAttack)
; copy unmodified stats to battle stats
	ld hl, wPlayerMonUnmodifiedAttack
	ld de, wBattleMonAttack
	call ResetStats
;> ResetStats(wEnemyMonUnmodifiedAttack, wEnemyMonAttack)
	ld hl, wEnemyMonUnmodifiedAttack
	ld de, wEnemyMonAttack
	call ResetStats
;> # cure the target's major status
;> if hWhoseTurn == 0:
;>     status, move = wEnemyMonStatus, addr(wEnemySelectedMove)
; cure non-volatile status, but only for the target
	ld hl, wEnemyMonStatus
	ld de, wEnemySelectedMove
	ldh a, [hWhoseTurn]
	and a
	jr z, .cureStatuses
;> else:
;>     status, move = wBattleMonStatus, addr(wPlayerSelectedMove)
	ld hl, wBattleMonStatus
	dec de ; wPlayerSelectedMove

.cureStatuses
;> old = mem[status]
;> mem[status] = 0
	ld a, [hl]
	ld [hl], $0
;> if old & (1 << FRZ | SLP_MASK):
;>     mem[move] = 0xFF                     # asleep or frozen: no move this turn
	and (1 << FRZ) | SLP_MASK
	jr z, .cureVolatileStatuses
; prevent the Pokemon from executing a move if it was asleep or frozen
	ld a, $ff
	ld [de], a

.cureVolatileStatuses
;> wPlayerDisabledMove = 0
	xor a
	ld [wPlayerDisabledMove], a
;> wEnemyDisabledMove = 0
	ld [wEnemyDisabledMove], a
;> mem[addr(wPlayerDisabledMoveNumber)] = 0
	ld hl, wPlayerDisabledMoveNumber
	ld [hli], a
;> mem[addr(wPlayerDisabledMoveNumber) + 1] = 0     # (wEnemyDisabledMoveNumber)
	ld [hl], a
;> CureVolatileStatuses(addr(wPlayerBattleStatus1))
	ld hl, wPlayerBattleStatus1
	call CureVolatileStatuses
;> CureVolatileStatuses(addr(wEnemyBattleStatus1))
	ld hl, wEnemyBattleStatus1
	call CureVolatileStatuses
;> CallBankF(PlayCurrentMoveAnimation)
	ld hl, PlayCurrentMoveAnimation
	call CallBankF
;> PrintText(StatusChangesEliminatedText)
	ld hl, StatusChangesEliminatedText
	jp PrintText

;@ path: engine/battle/move_effects/haze
;@ def CureVolatileStatuses(status: hl)
;@ Clear confusion (status byte 1); X Accuracy, mist, focus energy and leech seed (byte 2); toxic, Reflect and
;@ Light Screen (byte 3), keeping a transformation.
;@ test: status = rand_ram(3)
CureVolatileStatuses:
;> mem[status] &= ~(1 << CONFUSED) & 0xFF
	res CONFUSED, [hl]
;> mem[status + 1] &= ~(1 << USING_X_ACCURACY | 1 << PROTECTED_BY_MIST | 1 << GETTING_PUMPED | 1 << SEEDED) & 0xFF
	inc hl ; BATTSTATUS2
	ld a, [hl]
	; clear USING_X_ACCURACY, PROTECTED_BY_MIST, GETTING_PUMPED, and SEEDED statuses
	and ~((1 << USING_X_ACCURACY) | (1 << PROTECTED_BY_MIST) | (1 << GETTING_PUMPED) | (1 << SEEDED))
	ld [hli], a ; BATTSTATUS3
;> mem[status + 2] &= 0xF0 | 1 << TRANSFORMED       # Toxic, Reflect and Light Screen end
	ld a, [hl]
	and %11110000 | (1 << TRANSFORMED) ; clear Bad Poison, Reflect and Light Screen statuses
	ld [hl], a
	ret

;@ path: engine/battle/move_effects/haze
;@ def ResetStatMods(mods: hl, value: a)
;@ Set all NUM_STAT_MODS stat stages to value (7 is normal).
;@ test: mods = rand_ram(NUM_STAT_MODS)
ResetStatMods:
;> fill(mods, value, NUM_STAT_MODS)
	ld b, NUM_STAT_MODS
.loop
	ld [hli], a
	dec b
	jr nz, .loop
	ret

;@ path: engine/battle/move_effects/haze
;@ def ResetStats(src: hl, dest: de)
;@ Copy attack, defense, speed and special (two bytes each) from src to dest.
;@ test: src = rand_ram(8); dest = rand_ram(8)
ResetStats:
;> for i in range((NUM_STATS - 1) * 2):            # (not the HP)
	ld b, (NUM_STATS - 1) * 2 ; doesn't reset STAT_HEALTH
.loop
;>     mem[dest + i] = mem[src + i]
	ld a, [hli]
	ld [de], a
	inc de
	dec b
	jr nz, .loop
	ret

;@ path: engine/battle/move_effects/haze
StatusChangesEliminatedText:
	db TX_FAR
	dw _StatusChangesEliminatedText
	db BANK(_StatusChangesEliminatedText)
	db TX_END
;@ path: engine/battle/get_trainer_name
;@ def GetTrainerName_()
;@ The opponent's name into wTrainerName: the other player's in a link battle, your rival's name, or the trainer
;@ class name ("BUG CATCHER").
GetTrainerName_::
;> if wLinkState:
;>     src = wLinkEnemyTrainerName
	ld hl, wLinkEnemyTrainerName
	ld a, [wLinkState]
	and a
	jr nz, .foundName
;>@riv elif wTrainerClass in (RIVAL1, RIVAL2, RIVAL3):
;>     src = wRivalName
	ld hl, wRivalName
	ld a, [wTrainerClass]
	cp RIVAL1
	jr z, .foundName
;=@riv
	cp RIVAL2
	jr z, .foundName
	cp RIVAL3
	jr z, .foundName
;> else:
;>     wNameListIndex = wTrainerClass
	ld [wNameListIndex], a
;>     wNameListType = TRAINER_NAME
	ld a, TRAINER_NAME
	ld [wNameListType], a
;>     wPredefBank = BANK(TrainerNames)
	ld a, BANK(TrainerNames)
	ld [wPredefBank], a
;>     GetName()
	call GetName
;>     src = wNameBuffer
	ld hl, wNameBuffer
.foundName
;> CopyData(src, wTrainerName, TRAINER_NAME_LENGTH)
	ld de, wTrainerName
	ld bc, TRAINER_NAME_LENGTH
	jp CopyData
;@ path: engine/math/random
;@ def Random_(carry_in: carry) -> a
;@ Stir the two random bytes with the divider register rDIV, which counts up 16384 times a second: hRandomAdd
;@ gains it, hRandomSub loses it. Returns hRandomSub.
Random_::
; Generate a random 16-bit value.
;> total = hRandomAdd + rDIV + carry_in
	ldh a, [rDIV]
	ld b, a
	ldh a, [hRandomAdd]
	adc b
;> hRandomAdd = total & 0xFF
	ldh [hRandomAdd], a
;> hRandomSub = (hRandomSub - rDIV - (total > 0xFF)) & 0xFF
	ldh a, [rDIV]
	ld b, a
	ldh a, [hRandomSub]
	sbc b
	ldh [hRandomSub], a
;> return hRandomSub
	ret


SECTION "Battle Engine 2", ROMX

; Loads tile patterns for tiles used in the pokedex.
;@ path: engine/gfx/load_pokedex_tiles
;@ def LoadPokedexTilePatterns()
;@ Load the Pokédex screen's tiles, and the Poké Ball that marks caught Pokémon.
;@ test: skip copies to VRAM over several VBlanks
LoadPokedexTilePatterns:
;> LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;> CopyVideoData(vChars2 + 0x60 * 16, PokedexTileGraphics, BANK(PokedexTileGraphics), (PokedexTileGraphicsEnd - PokedexTileGraphics) // TILE_SIZE)
	ld de, PokedexTileGraphics
	ld hl, vChars2 + TILE_SIZE * $60
	ld bc, ((BANK(PokedexTileGraphics)) & $ff) << 8 + (((PokedexTileGraphicsEnd - PokedexTileGraphics) / TILE_SIZE) & $ff)
	call CopyVideoData
;> CopyVideoData(vChars2 + 0x72 * 16, PokeballTileGraphics, BANK(PokeballTileGraphics), 1)
	ld de, PokeballTileGraphics
	ld hl, vChars2 + TILE_SIZE * $72
	ld bc, ((BANK(PokeballTileGraphics)) & $ff) << 8 + ((1) & $ff)
	jp CopyVideoData ; load pokeball tile for marking caught mons
; Loads tile patterns for map's sprites.
; For outside maps, it loads one of several fixed sets of sprites.
; For inside maps, it loads each sprite picture ID used in the map header.
; This is also called after displaying text because loading
; text tile patterns overwrites half of the sprite tile pattern data.
; Note on notation:
; x#SPRITESTATEDATA1_* and x#SPRITESTATEDATA2_* are used to denote wSpriteStateData1 and
; wSpriteStateData2 sprite slot, respectively, within loops. The X is the loop index.
; If there is an inner loop, Y is the inner loop index, i.e. y#SPRITESTATEDATA1_* and
; y#SPRITESTATEDATA2_* denote fields of the sprite slots iterated over in the inner loop.
;@ path: engine/overworld/map_sprites
;@ def InitMapSprites()
;@ Load the sprite graphics for a new map. Outdoors the map's sprite set decides (InitOutsideMapSprites).
;@ Indoors each sprite slot's picture ID is copied to its second data table, and the pictures in use are
;@ loaded.
;@ test: hLoadedROMBank = 5; wFontLoaded = 0; wCurMap = rand(FIRST_INDOOR_MAP, NUM_MAPS - 1); wNumSprites = rand(0, 15)
InitMapSprites::
;> if InitOutsideMapSprites():                  # a town or route: all done there
;>     return
	call InitOutsideMapSprites
	ret c ; return if the map is an outside map (already handled by above call)
; if the map is an inside map (i.e. mapID >= FIRST_INDOOR_MAP)
;>@copy for i in range(NUM_SPRITESTATEDATA_STRUCTS):
;>     mem[addr(wSpritePlayerStateData2PictureID) + 16 * i] = mem[addr(wSpritePlayerStateData1PictureID) + 16 * i]
;=@copy
	ld hl, wSpritePlayerStateData1PictureID
	ld de, wSpritePlayerStateData2PictureID
; Loop to copy picture IDs from [x#SPRITESTATEDATA1_PICTUREID]
; to [x#SPRITESTATEDATA2_PICTUREID] for LoadMapSpriteTilePatterns.
.copyPictureIDLoop
	ld a, [hl] ; a = [x#SPRITESTATEDATA1_PICTUREID]
	ld [de], a ; [x#SPRITESTATEDATA2_PICTUREID] = a
;=@copy
	ld a, SPRITESTATEDATA1_LENGTH
	add e
	ld e, a
;=@copy
	ld a, SPRITESTATEDATA1_LENGTH
	add l
	ld l, a
	jr nz, .copyPictureIDLoop
;> LoadMapSpriteTilePatterns()

; This is used for both inside and outside maps, since it is called by
; InitOutsideMapSprites.
; Loads tile pattern data for sprites into VRAM.
;@ path: engine/overworld/map_sprites
;@ def LoadMapSpriteTilePatterns()
;@ Load the graphics of the first wNumSprites sprites into video memory. Each new picture gets the next free
;@ slot of 12 tiles (standing frames at $8000, walking frames $800 higher); a still 4-tile picture uses
;@ slot 11 or 12 at tiles $78 / $7C. A picture already loaded for an earlier sprite shares its slot. The
;@ slot ends up in each sprite's SPRITESTATEDATA2_IMAGEBASEOFFSET. While text is shown (font loaded) the
;@ standing frames are kept and the walking frames go through CopyVideoData, as the screen is on.
;@ test: hLoadedROMBank = 5; wFontLoaded = 0; wNumSprites = rand(1, 15)
LoadMapSpriteTilePatterns:
;> n = wNumSprites
	ld a, [wNumSprites]
;> if n == 0: return
	and a ; are there any sprites?
	jr nz, .spritesExist
	ret
.spritesExist
;>@four hFourTileSpriteCount = 0
;>@pics for i in range(NUM_SPRITESTATEDATA_STRUCTS):      # picture IDs into the image base offsets, for now
;=@pics
	ld c, a ; c = [wNumSprites]
	ld b, NUM_SPRITESTATEDATA_STRUCTS
	ld hl, wSpritePlayerStateData2PictureID
;=@four
	xor a
	ldh [hFourTileSpriteCount], a
; Loop to copy picture IDs from [x#SPRITESTATEDATA2_PICTUREID]
; to [x#SPRITESTATEDATA2_IMAGEBASEOFFSET].
.copyPictureIDLoop
;>     s2 = addr(wSpriteStateData2) + 16 * i
;>     mem[s2 + SPRITESTATEDATA2_IMAGEBASEOFFSET] = mem[s2 + SPRITESTATEDATA2_PICTUREID]
	ld a, [hli] ; a = [x#SPRITESTATEDATA2_PICTUREID]
	ld [hld], a ; [x#SPRITESTATEDATA2_IMAGEBASEOFFSET] = a
;=@pics
	ld a, l
	add SPRITESTATEDATA1_LENGTH
	ld l, a
	dec b
	jr nz, .copyPictureIDLoop
;> cur = addr(wSprite01StateData2ImageBaseOffset)
	ld hl, wSprite01StateData2ImageBaseOffset
;>@sprites for _ in range(n):
.loadTilePatternLoop
;>     earlier = cur & 0xFF00 | 0x10 | SPRITESTATEDATA2_PICTUREID     # from sprite 1 on
	ld de, wSprite01StateData2PictureID
; Check if the current picture ID has already had its tile patterns loaded.
; This done by looping through the previous sprite slots and seeing if any of
; their picture ID's match that of the current sprite slot.
.checkIfAlreadyLoadedLoop
;>@scan     while (earlier & 0xF0) != (cur & 0xF0) and mem[earlier] != mem[cur]:
	ld a, e
	and $f0
	ld b, a ; b = offset of the wSpriteStateData2 sprite slot being checked against
	ld a, l
	and $f0 ; a = offset of current wSpriteStateData2 sprite slot
	cp b ; done checking all previous sprite slots?
;=@scan
	jr z, .notAlreadyLoaded
	ld a, [de] ; picture ID of the wSpriteStateData2 sprite slot being checked against
	cp [hl] ; do the picture ID's match?
	jp z, .alreadyLoaded
;>         earlier = earlier & 0xFF00 | u8(earlier + 16)
	ld a, e
	add SPRITESTATEDATA1_LENGTH
	ld e, a
	jr .checkIfAlreadyLoadedLoop
.notAlreadyLoaded
;>@shared     if (earlier & 0xF0) != (cur & 0xF0):      # an earlier sprite has this picture: share its slot
;>@share         mem[cur] = mem[earlier + 1]
;>     else:
;>         q = cur & 0xFF00 | SPRITESTATEDATA2_IMAGEBASEOFFSET
	ld de, wSpritePlayerStateData2ImageBaseOffset
;>         best = 1                             # the highest slot 1-10 used so far
	ld b, 1
; loop to find the highest tile pattern VRAM slot (among the first 10 slots) used by a previous sprite slot
; this is done in order to find the first free VRAM slot available
.findNextVRAMSlotLoop
;>         while True:
;>             q = q & 0xFF00 | u8(q + 16)
	ld a, e
	add SPRITESTATEDATA1_LENGTH
	ld e, a
;>             if q == cur:
;>                 break
	ld a, l
	cp e ; reached current slot?
	jr z, .foundNextVRAMSlot
;>             if best <= mem[q] < 11:
	ld a, [de] ; y#SPRITESTATEDATA2_IMAGEBASEOFFSET
	cp 11 ; is it one of the first 10 slots?
	jr nc, .findNextVRAMSlotLoop
	cp b ; compare the slot being checked to the current max
	jr c, .findNextVRAMSlotLoop ; if the slot being checked is less than the current max
; if the slot being checked is greater than or equal to the current max
;>                 best = mem[q]
	ld b, a ; store new max VRAM slot
	jr .findNextVRAMSlotLoop
.foundNextVRAMSlot
;>         slot = best + 1                      # the first free one
	inc b ; increment previous max value to get next VRAM tile pattern slot
	ld a, b ; a = next VRAM tile pattern slot
	push af
;>         picture = mem[cur]
	ld a, [hl] ; [x#SPRITESTATEDATA2_IMAGEBASEOFFSET]
	ld b, a ; b = current sprite picture ID
;>         if picture >= FIRST_STILL_SPRITE:     # a still 4-tile picture: slot 11 or 12
	cp FIRST_STILL_SPRITE ; is it a 4-tile sprite?
	jr c, .notFourTileSprite
;>             slot = u8(hFourTileSpriteCount + 11)
	pop af
	ldh a, [hFourTileSpriteCount]
	add 11
	jr .storeVRAMSlot
.notFourTileSprite
	pop af
.storeVRAMSlot
;>         mem[cur] = slot
	ld [hl], a ; store VRAM slot at [x#SPRITESTATEDATA2_IMAGEBASEOFFSET]
;>         hVRAMSlot = slot
	ldh [hVRAMSlot], a ; used to determine if it's 4-tile sprite later
;>         index = 4 * u8(picture - 1) & 0x1FF
	ld a, b ; a = current sprite picture ID
	dec a
	add a
	add a
	push bc
	push hl
;>@entry         entry = SpriteSheetPointerTable + index
	ld hl, SpriteSheetPointerTable
	jr nc, .noCarry
	inc h
.noCarry
;=@entry
	add l
	ld l, a
	jr nc, .noCarry2
	inc h
.noCarry2
;>         bank, length, src, _ = ReadSpriteSheetData(entry)
	push hl
	call ReadSpriteSheetData
	push af
	push de
	push bc
;>         if slot < 11:
	ld hl, vNPCSprites ; VRAM base address
	ld bc, 12 * TILE_SIZE ; number of bytes per VRAM slot
	ldh a, [hVRAMSlot]
	cp 11 ; is it a 4-tile sprite?
	jr nc, .fourTileSpriteVRAMAddr
;>             dest = addr(vNPCSprites) + 12 * TILE_SIZE * (slot - 1)
	ld d, a
	dec d
; hl = vSprites + [hVRAMSlot] * 12 tiles
.calculateVRAMAddrLoop
	add hl, bc
	dec d
	jr nz, .calculateVRAMAddrLoop
	jr .loadStillTilePattern
.fourTileSpriteVRAMAddr
;>         elif hFourTileSpriteCount:
;>             dest = addr(vSprites) + 0x7C * TILE_SIZE    # the second 4-tile picture
	ld hl, vSprites + TILE_SIZE * $7c ; address for second 4-tile sprite
	ldh a, [hFourTileSpriteCount]
	and a
	jr nz, .loadStillTilePattern
; if it's the first 4-tile sprite
;>         else:
;>             dest = addr(vSprites) + 0x78 * TILE_SIZE
	ld hl, vSprites + TILE_SIZE * $78 ; address for first 4-tile sprite
;>             hFourTileSpriteCount = 1
	inc a
	ldh [hFourTileSpriteCount], a
.loadStillTilePattern
;>@font1         if not wFontLoaded & (1 << BIT_FONT_LOADED):     # text shown: the standing frames stay
;>@still             FarCopyData2(bank, src, dest, length & 0xFF)     # standing frames
;=@still
	pop bc
	pop de
	pop af
;=@still
	push hl
	push hl
	ld h, d
	ld l, e
	pop de
	ld b, a
;=@font1
	ld a, [wFontLoaded]
	bit BIT_FONT_LOADED, a ; reloading upper half of tile patterns after displaying text?
	jr nz, .skipFirstLoad ; if so, skip loading data into the lower half
;=@still
	ld a, b
	ld b, 0
	call FarCopyData2 ; load tile pattern data for sprite when standing still
.skipFirstLoad
;>         if slot < 11:                         # 4-tile pictures have no walking frames
	pop de
	pop hl
	ldh a, [hVRAMSlot]
	cp 11 ; is it a 4-tile sprite?
	jr nc, .skipSecondLoad ; if so, there is no second block
;>             bank, length, src, _ = ReadSpriteSheetData(entry)
	push de
	call ReadSpriteSheetData
	push af
;>             src = (src + 0xC0) & 0xFFFF       # the walking frames follow the standing ones
	ld a, $c0
	add e
	ld e, a
	jr nc, .noCarry3
	inc d
.noCarry3
;>             if wFontLoaded & (1 << BIT_FONT_LOADED):
;>@lcdon                 CopyVideoData(dest | 0x800, src, bank, swap(length & 0xFF))
;>             else:
	ld a, [wFontLoaded]
	bit BIT_FONT_LOADED, a ; reloading upper half of tile patterns after displaying text?
	jr nz, .loadWhileLCDOn
;>@walk                 FarCopyData2(bank, src, dest | 0x800, length)   # walking frames
	pop af
	pop hl
	set 3, h ; add $800 ($80 tiles) to hl (1 << 3 == $8)
;=@walk
	push hl
	ld h, d
	ld l, e
	pop de
	call FarCopyData2 ; load tile pattern data for sprite when walking
	jr .skipSecondLoad
; When reloading the upper half of tile patterns after displaying text, the LCD
; will be on, so CopyVideoData (which writes to VRAM only during V-blank) must
; be used instead of FarCopyData2.
.loadWhileLCDOn
;=@lcdon
	pop af
	pop hl
	set 3, h ; add $800 ($80 tiles) to hl (1 << 3 == $8)
	ld b, a
	swap c
	call CopyVideoData ; load tile pattern data for sprite when walking
.skipSecondLoad
;=@sprites
	pop hl
	pop bc
	jr .nextSpriteSlot
.alreadyLoaded ; if the current picture ID has already had its tile patterns loaded
;=@share
	inc de
	ld a, [de] ; a = [y#SPRITESTATEDATA2_IMAGEBASEOFFSET]
	ld [hl], a ; [x#SPRITESTATEDATA2_IMAGEBASEOFFSET] = a
.nextSpriteSlot
;>     cur = cur & 0xFF00 | u8(cur + SPRITESTATEDATA2_LENGTH)
	ld a, l
	add SPRITESTATEDATA2_LENGTH
	ld l, a
;=@sprites
	dec c
	jp nz, .loadTilePatternLoop
;>@zero for i in range(NUM_SPRITESTATEDATA_STRUCTS):      # the copied picture IDs are no longer needed
	ld hl, wSpritePlayerStateData2PictureID
	ld b, NUM_SPRITESTATEDATA_STRUCTS
; the pictures IDs stored at [x#SPRITESTATEDATA2_PICTUREID] are no longer needed,
; so zero them
.zeroStoredPictureIDLoop
;>     mem[addr(wSpritePlayerStateData2PictureID) + 16 * i] = 0
	xor a
	ld [hl], a ; [x#SPRITESTATEDATA2_PICTUREID]
;=@zero
	ld a, SPRITESTATEDATA2_LENGTH
	add l
	ld l, a
	dec b
	jr nz, .zeroStoredPictureIDLoop
	ret

; reads data from SpriteSheetPointerTable
; INPUT:
; hl = address of sprite sheet entry
; OUTPUT:
; de = pointer to sprite sheet
; bc = length in bytes
; a = ROM bank
;@ path: engine/overworld/map_sprites
;@ def ReadSpriteSheetData(entry: hl) -> (a, bc, de, hl)
;@ Read a SpriteSheetPointerTable entry: returns the bank, the length in bytes, the graphics pointer and the
;@ address after the entry.
;@ test: entry = rand_ram(4)
ReadSpriteSheetData:
;> src = mem16[entry]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;> length = mem[entry + 2]
	ld a, [hli]
	ld c, a
	xor a
	ld b, a
;> bank = mem[entry + 3]
	ld a, [hli]
;> return bank, length, src, entry + 4
	ret

; Loads sprite set for outside maps (cities and routes) and sets VRAM slots.
; sets carry if the map is a city or route, unsets carry if not
;@ path: engine/overworld/map_sprites
;@ def InitOutsideMapSprites() -> carry
;@ For a town or route (carry set): load its sprite set (for maps with two, the one for the player's side)
;@ unless it is already loaded, then give every sprite the slot of its picture: its place in the sprite set
;@ plus one, as the player's own picture comes first. Indoors nothing happens and carry is clear.
;@ test: hLoadedROMBank = 5; wFontLoaded = 0; wCurMap = rand(0, FIRST_INDOOR_MAP); [mem.__setitem__(0xC100 + 16 * i, 0) for i in range(1, 16)]
InitOutsideMapSprites:
;> if wCurMap >= FIRST_INDOOR_MAP:
;>     return False
	ld a, [wCurMap]
	cp FIRST_INDOOR_MAP ; is the map a city or a route?
	ret nc ; if not, return
;> set_id = mem[MapSpriteSets + wCurMap]
	ld hl, MapSpriteSets
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
	ld a, [hl] ; a = spriteSetID
;> if set_id >= FIRST_SPLIT_SET - 1:
;>     set_id = GetSplitMapSpriteSetID(set_id)
	cp FIRST_SPLIT_SET - 1 ; does the map have 2 sprite sets?
	call nc, GetSplitMapSpriteSetID ; if so, choose the appropriate one
;>@load if wFontLoaded & (1 << BIT_FONT_LOADED) or wSpriteSetID != set_id:    # reload after text, or a new set
	ld b, a ; b = spriteSetID
	ld a, [wFontLoaded]
	bit BIT_FONT_LOADED, a ; reloading upper half of tile patterns after displaying text?
	jr nz, .loadSpriteSet ; if so, forcibly reload the sprite set
;=@load
	ld a, [wSpriteSetID]
	cp b ; has the sprite set ID changed?
	jr z, .skipLoadingSpriteSet ; if not, don't load it again
.loadSpriteSet
;>     wSpriteSetID = set_id
	ld a, b
	ld [wSpriteSetID], a
;>@index     index = u8(SPRITE_SET_LENGTH * (set_id - 1))     # 11 = 8 + 2 + 1
	dec a
	ld b, a
	sla a
	ld c, a
;=@index
	sla a
	sla a
	add c
	add b ; a = (spriteSetID - 1) * SPRITE_SET_LENGTH
;>     src = SpriteSets + index
	ld de, SpriteSets
; add a to de to get offset of sprite set
	add e
	ld e, a
	jr nc, .noCarry2
	inc d
.noCarry2
;>     wSpritePlayerStateData2PictureID = SPRITE_RED
	ld hl, wSpritePlayerStateData2PictureID
	ld a, SPRITE_RED
	ld [hl], a
;>     for i in range(SPRITE_SET_LENGTH):        # slots 1-11 get the set's pictures, to load them all
	ld bc, wSpriteSet
; Load the sprite set into RAM.
; This loop also fills [x#SPRITESTATEDATA2_PICTUREID] where X is from $0 to $A
; with picture IDs. This is done so that LoadMapSpriteTilePatterns will
; load tile patterns for all sprite pictures in the sprite set.
.loadSpriteSetLoop
;>         mem[addr(wSpritePlayerStateData2PictureID) + 16 * (i + 1)] = mem[src + i]
	ld a, SPRITESTATEDATA2_LENGTH
	add l
	ld l, a
	ld a, [de] ; sprite picture ID from sprite set
	ld [hl], a ; [x#SPRITESTATEDATA2_PICTUREID]
;>         wSpriteSet[i] = mem[src + i]
	ld [bc], a
	inc de
	inc bc
	ld a, l
	cp 11 * SPRITESTATEDATA2_LENGTH + SPRITESTATEDATA2_PICTUREID ; reached 11th sprite slot?
	jr nz, .loadSpriteSetLoop
;>@rest     for i in range(12, 16):
	ld b, 4 ; 4 remaining sprite slots
.zeroRemainingSlotsLoop ; loop to zero the picture ID's of the remaining sprite slots
;>         mem[addr(wSpritePlayerStateData2PictureID) + 16 * i] = 0
	ld a, SPRITESTATEDATA2_LENGTH
	add l
	ld l, a
	xor a
	ld [hl], a ; [x#SPRITESTATEDATA2_PICTUREID]
;=@rest
	dec b
	jr nz, .zeroRemainingSlotsLoop
;>     saved = wNumSprites
	ld a, [wNumSprites]
	push af ; save number of sprites
;>     wNumSprites = SPRITE_SET_LENGTH
	ld a, SPRITE_SET_LENGTH ; 11 sprites in sprite set
	ld [wNumSprites], a
;>     LoadMapSpriteTilePatterns()
	call LoadMapSpriteTilePatterns
;>     wNumSprites = saved
	pop af
	ld [wNumSprites], a ; restore number of sprites
;>@clear     for i in range(1, 16):                   # those slots were in sprite set order: clear them
	ld hl, wSprite01StateData2ImageBaseOffset
	ld b, NUM_SPRITESTATEDATA_STRUCTS - 1
; The VRAM tile pattern slots that LoadMapSpriteTilePatterns set are in the
; order of the map's sprite set, not the order of the actual sprites loaded
; for the current map. So, they are not needed and are zeroed by this loop.
.zeroVRAMSlotsLoop
;>         mem[addr(wSprite01StateData2ImageBaseOffset) + 16 * (i - 1)] = 0
	xor a
	ld [hl], a ; [x#SPRITESTATEDATA2_IMAGEBASEOFFSET]
	ld a, SPRITESTATEDATA2_LENGTH
	add l
	ld l, a
;=@clear
	dec b
	jr nz, .zeroVRAMSlotsLoop
.skipLoadingSpriteSet
;>@slots for i in range(1, 16):
	ld hl, wSprite01StateData1
; This loop stores the correct VRAM tile pattern slots according the sprite
; data from the map's header. Since the VRAM tile pattern slots are filled in
; the order of the sprite set, in order to find the VRAM tile pattern slot
; for a sprite slot, the picture ID for the sprite is looked up within the
; sprite set. The index of the picture ID within the sprite set plus one
; (since the Red sprite always has the first VRAM tile pattern slot) is the
; VRAM tile pattern slot.
.storeVRAMSlotsLoop
;>     picture = mem[addr(wSpritePlayerStateData1PictureID) + 16 * i]
;>     slot = 0
	ld c, 0
	ld a, [hl] ; [x#SPRITESTATEDATA1_PICTUREID] (zero if sprite slot is not used)
;>     if picture:
	and a ; is the sprite slot used?
	jr z, .skipGettingPictureIndex ; if the sprite slot is not used
;>         k = 0
;>@find         while wSpriteSet[k] != picture:
	ld b, a ; b = picture ID
	ld de, wSpriteSet
; Loop to find the index of the sprite's picture ID within the sprite set.
.getPictureIndexLoop
;>             k += 1
	inc c
;=@find
	ld a, [de]
	inc de
	cp b ; does the picture ID match?
	jr nz, .getPictureIndexLoop
;>         slot = k + 2                         # slot 1 is the player's
	inc c
.skipGettingPictureIndex
;>     entry = addr(wSprite01StateData2ImageBaseOffset) + 16 * (i - 1)
	push hl
	inc h ; HIGH(wSpriteStateData2)
	ld a, SPRITESTATEDATA2_IMAGEBASEOFFSET - SPRITESTATEDATA1_PICTUREID
	add l
	ld l, a
;>     mem[entry] = slot
	ld a, c ; a = VRAM slot (zero if sprite slot is not used)
	ld [hl], a ; [x#SPRITESTATEDATA2_IMAGEBASEOFFSET]
	pop hl
;=@slots
	ld a, SPRITESTATEDATA1_LENGTH
	add l
	ld l, a
	and a
	jr nz, .storeVRAMSlotsLoop
;> return True
	scf
	ret

; Chooses the correct sprite set ID depending on the player's position within
; the map for maps with two sprite sets.
;@ path: engine/overworld/map_sprites
;@ def GetSplitMapSpriteSetID(set_id: a) -> a
;@ For a map with two sprite sets: which one applies where the player stands? SplitMapSpriteSets gives the
;@ split direction, the dividing coordinate and the sets for the west/north and east/south sides. Route 20
;@ has a more complex border and is decided by hand.
;@ test: set_id = rand(FIRST_SPLIT_SET, SPLITSET_ROUTE_20); wXCoord = rand(0, 90); wYCoord = rand(0, 30)
GetSplitMapSpriteSetID:
;> if set_id == SPLITSET_ROUTE_20:              # its border has a more complex shape
;>@west     if wXCoord < 43: return SPRITESET_PALLET_VIRIDIAN
;>@east     if wXCoord >= 62: return SPRITESET_FUCHSIA
;>@split     split = 8 if wXCoord >= 55 else 13
	cp SPLITSET_ROUTE_20
	jr z, .route20
;>@north     return SPRITESET_FUCHSIA if wYCoord < split else SPRITESET_PALLET_VIRIDIAN
;>@p p = SplitMapSpriteSets + u8(4 * ((set_id & 0x0F) - 1))    # direction, dividing line, two sets
	ld hl, SplitMapSpriteSets
	and $0f
	dec a
	sla a
	sla a
;=@p
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
;>@pos pos = wXCoord if mem[p] == EAST_WEST else wYCoord
	ld a, [hli] ; whether the map is split EAST_WEST or NORTH_SOUTH
	cp EAST_WEST
;> divide = mem[p + 1]
	ld a, [hli] ; position of dividing line
	ld b, a
;=@pos
	jr z, .eastWestDivide
.northSouthDivide
	ld a, [wYCoord]
	jr .compareCoord
.eastWestDivide
	ld a, [wXCoord]
.compareCoord
;> return mem[p + 2] if pos < divide else mem[p + 3]     # west/north side, else east/south
	cp b
	jr c, .loadSpriteSetID
; if in the east side or south side
	inc hl
.loadSpriteSetID
	ld a, [hl]
	ret
; Uses sprite set SPRITESET_PALLET_VIRIDIAN for west side and SPRITESET_FUCHSIA for east side.
; Route 20 is a special case because the two map sections have a more complex
; shape instead of the map simply being split horizontally or vertically.
.route20
;=@west
	ld hl, wXCoord
	; Use SPRITESET_PALLET_VIRIDIAN if X < 43
	ld a, [hl]
	cp 43
	ld a, SPRITESET_PALLET_VIRIDIAN
	ret c
	; Use SPRITESET_FUCHSIA if X >= 62.
;=@east
	ld a, [hl]
	cp 62
	ld a, SPRITESET_FUCHSIA
	ret nc
	; If 55 <= X < 62, split Y at 8; else 43 <= X < 55, so split Y at 13
;=@split
	ld a, [hl]
	cp 55
	ld b, 8
	jr nc, .next
	ld b, 13
.next
	; Use SPRITESET_FUCHSIA if Y < split; else use SPRITESET_PALLET_VIRIDIAN
;=@north
	ld a, [wYCoord]
	cp b
	ld a, SPRITESET_FUCHSIA
	ret c
	ld a, SPRITESET_PALLET_VIRIDIAN
	ret

