;@ path: engine/overworld/emotion_bubbles
;@ def EmotionBubble()
;@ Show emotion bubble wWhichEmotionBubble (shock, question, happy) above sprite wEmotionBubbleSpriteIndex
;@ for one second. The other sprites' OAM entries move up by four to make room for the bubble at the front.
EmotionBubble:
;> entry = EmotionBubblesPointerTable + 2 * wWhichEmotionBubble
	ld a, [wWhichEmotionBubble]
	ld c, a
	ld b, 0
	ld hl, EmotionBubblesPointerTable
	add hl, bc
	add hl, bc
;> src = mem16[entry]
	ld e, [hl]
	inc hl
	ld d, [hl]
;> CopyVideoData(addr(vChars1) + 0x78 * TILE_SIZE, src, BANK(EmotionBubbles), 4)
	ld hl, vChars1 + TILE_SIZE * $78
	ld bc, ((BANK(EmotionBubbles)) & $ff) << 8 + ((4) & $ff)
	call CopyVideoData
;> saved = wUpdateSpritesEnabled
	ld a, [wUpdateSpritesEnabled]
	push af
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;>@special if wMovementFlags & (1 << BIT_LEDGE_OR_FISHING):     # the last 4 entries hold a shadow or fishing rod
	ld a, [wMovementFlags]
	bit BIT_LEDGE_OR_FISHING, a ; are the last 4 OAM entries reserved for a shadow or fishing rod?
;>@spare     last, dest = addr(wShadowOAMSprite31Attributes), addr(wShadowOAMSprite35Attributes)
;> else:
;>     last, dest = addr(wShadowOAMSprite35Attributes), addr(wShadowOAMSprite39Attributes)
	ld hl, wShadowOAMSprite35Attributes
	ld de, wShadowOAMSprite39Attributes
;=@special
	jr z, .next
;=@spare
	ld hl, wShadowOAMSprite31Attributes
	ld de, wShadowOAMSprite35Attributes

; Copy OAM data 16 bytes forward to make room for emotion bubble OAM data at the
; start of the OAM buffer.
.next
;>@move for i in range(0x90):                        # back to front
	ld bc, $90
.loop
;>     mem[dest - i] = mem[last - i]
	ld a, [hl]
	ld [de], a
	dec hl
	dec de
;=@move
	dec bc
	ld a, c
	or b
	jr nz, .loop

; get the screen coordinates of the sprite the bubble is to be displayed above
;> s = addr(wSpritePlayerStateData1YPixels) + swap(wEmotionBubbleSpriteIndex)
	ld hl, wSpritePlayerStateData1YPixels
	ld a, [wEmotionBubbleSpriteIndex]
	swap a
	ld c, a
	ld b, 0
	add hl, bc
;> y = mem[s]
	ld a, [hli]
	ld b, a
;> x = u8(mem[s + 2] + 8)
	inc hl
	ld a, [hl]
	add $8
	ld c, a

;> WriteOAMBlock(0, y, x, EmotionBubblesOAMBlock)       # above that sprite
	ld de, EmotionBubblesOAMBlock
	xor a
	call WriteOAMBlock
;> DelayFrames(60)
	ld c, 60
	call DelayFrames
;> wUpdateSpritesEnabled = saved
	pop af
	ld [wUpdateSpritesEnabled], a
;> DelayFrame()
	call DelayFrame
;> UpdateSprites()
	jp UpdateSprites

;@ path: engine/overworld/emotion_bubbles
EmotionBubblesPointerTable:
; entries correspond to *_BUBBLE constants
	dw ShockEmote
	dw QuestionEmote
	dw HappyEmote

;@ path: engine/overworld/emotion_bubbles
EmotionBubblesOAMBlock:
; tile ID, attributes
	db $f8, 0
	db $f9, 0
	db $fa, 0
	db $fb, 0

;@ path: engine/overworld/emotion_bubbles
EmotionBubbles:
