ShockEmote:
	db $1f, $00, $3f, $1f, $7f, $20, $ff, $41, $ff, $41, $ff, $41, $ff, $41, $ff, $41
	db $f8, $00, $fc, $f8, $fe, $04, $ff, $82, $ff, $82, $ff, $82, $ff, $82, $ff, $82
	db $ff, $40, $ff, $41, $ff, $41, $7f, $20, $3f, $1f, $1f, $00, $01, $00, $01, $00
	db $ff, $02, $ff, $82, $ff, $82, $fe, $04, $fc, $f8, $f8, $c0, $c0, $80, $80, $00
;@ path: engine/overworld/emotion_bubbles
QuestionEmote:
	db $1f, $00, $3f, $1f, $7f, $20, $ff, $4f, $ff, $5c, $ff, $5c, $ff, $41, $ff, $41
	db $f8, $00, $fc, $f8, $fe, $04, $ff, $f2, $ff, $3a, $ff, $3a, $ff, $f2, $ff, $82
	db $ff, $40, $ff, $41, $ff, $41, $7f, $20, $3f, $1f, $1f, $00, $01, $00, $01, $00
	db $ff, $02, $ff, $82, $ff, $82, $fe, $04, $fc, $f8, $f8, $c0, $c0, $80, $80, $00
;@ path: engine/overworld/emotion_bubbles
HappyEmote:
	db $1f, $00, $3f, $1f, $7f, $20, $ff, $40, $ff, $4c, $ff, $52, $ff, $52, $ff, $40
	db $f8, $00, $fc, $f8, $fe, $04, $ff, $02, $ff, $32, $ff, $4a, $ff, $4a, $ff, $02
	db $ff, $40, $ff, $44, $ff, $43, $7f, $20, $3f, $1f, $1f, $00, $01, $00, $01, $00
	db $ff, $02, $ff, $22, $ff, $c2, $fe, $04, $fc, $f8, $f8, $c0, $c0, $80, $80, $00
;@ path: engine/events/evolve_trade
;@ def InGameTrade_CheckForTradeEvo()
;@ After an in-game trade: a received Pokémon named GRAVELER or SPECTRE (Haunter's early name) evolves as
;@ if traded by cable. None of the final trades gives one.
InGameTrade_CheckForTradeEvo:
; In Japanese Blue, TradeMons include a Graveler and a Haunter,
; both of which have Japanese names that start with "ゴ",
; which is what this routine originally checked in that game.
; For English Red and Blue, this routine was adjusted for
; Graveler's English name and Haunter's early English name "Spectre".
; The final release replaced Graveler and Haunter in TradeMons.
;> name = wInGameTradeReceiveMonName
;> if name[0] != charmap('G')[0]:                 # not GRAVELER
	ld a, [wInGameTradeReceiveMonName]
	cp 'G' ; GRAVELER
	jr z, .nameMatched
	; "SPECTRE" (HAUNTER)
;>     if name[0] != charmap('S')[0] or name[1] != charmap('P')[0]:     # nor SPECTRE (Haunter)
;>         return
	cp 'S'
	ret nz
	ld a, [wInGameTradeReceiveMonName + 1]
	cp 'P'
	ret nz
.nameMatched
;> wWhichPokemon = u8(wPartyCount - 1)
	ld a, [wPartyCount]
	dec a
	ld [wWhichPokemon], a
;> wForceEvolution = TRUE
	ld a, TRUE
	ld [wForceEvolution], a
;> wLinkState = LINK_STATE_TRADING
	ld a, LINK_STATE_TRADING
	ld [wLinkState], a
;> TryEvolvingMon()                             # in another bank
	ld hl, TryEvolvingMon
	ld b, BANK(TryEvolvingMon)
	call Bankswitch
;> wLinkState = LINK_STATE_NONE
	xor a ; LINK_STATE_NONE
	ld [wLinkState], a
;> PlayDefaultMusic()
	jp PlayDefaultMusic
;@ path: engine/battle/move_effects/substitute
;@ def SubstituteEffect_()
;@ Substitute: a quarter of the user's maximum HP goes into a decoy. Fails if one is already up or the user has too
;@ little HP (but it can leave the user at exactly 0 HP).
SubstituteEffect_:
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> if hWhoseTurn == 0:
;>     max_hp, sub_hp, status = wBattleMonMaxHP, addr(wPlayerSubstituteHP), addr(wPlayerBattleStatus2)
	ld hl, wBattleMonMaxHP
	ld de, wPlayerSubstituteHP
	ld bc, wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	jr z, .notEnemy
;> else:
;>     max_hp, sub_hp, status = wEnemyMonMaxHP, addr(wEnemySubstituteHP), addr(wEnemyBattleStatus2)
	ld hl, wEnemyMonMaxHP
	ld de, wEnemySubstituteHP
	ld bc, wEnemyBattleStatus2
.notEnemy
;> if mem[status] >> HAS_SUBSTITUTE_UP & 1:
;>@has     return PrintText(HasSubstituteText)
	ld a, [bc]
	bit HAS_SUBSTITUTE_UP, a ; user already has substitute?
	jr nz, .alreadyHasSubstitute
;> top = mem[max_hp] << 8 | mem[max_hp + 1]
; quarter health to remove from user
; assumes max HP is 1023 or lower
	push bc
	ld a, [hli]
	ld b, [hl]
;> quarter = (top >> 2) & 0xFF                      # assumes max HP <= 1023
	srl a
	rr b
	srl a
	rr b ; max hp / 4
;> hp = max_hp + (wBattleMonHP - wBattleMonMaxHP)
	push de
	ld de, wBattleMonHP - wBattleMonMaxHP
	add hl, de ; point hl to current HP low byte
	pop de
;> mem[sub_hp] = quarter                            # the decoy's HP
	ld a, b
	ld [de], a ; save copy of HP to subtract in wPlayerSubstituteHP/wEnemySubstituteHP
;> left = (mem[hp] << 8 | mem[hp + 1]) - quarter
	ld a, [hld]
; subtract [max hp / 4] to current HP
	sub b
	ld d, a
	ld a, [hl]
	sbc 0
;> if left < 0:                                     # (exactly 0 is allowed: a bug)
;>@weak     return PrintText(TooWeakSubstituteText)
	pop bc
	jr c, .notEnoughHP ; underflow means user would be left with negative health
                       ; bug: since it only branches on carry, it will possibly leave user with 0 HP
;> mem[hp], mem[hp + 1] = hi(left), lo(left)
; user has 0 or more HP
	ld [hli], a ; save resulting HP after subtraction into current HP
	ld [hl], d
;> mem[status] |= 1 << HAS_SUBSTITUTE_UP
	ld h, b
	ld l, c
	set HAS_SUBSTITUTE_UP, [hl]
;> off = wOptions >> BIT_BATTLE_ANIMATION & 1        # animations off?
	ld a, [wOptions]
	bit BIT_BATTLE_ANIMATION, a
;> anim = PlayCurrentMoveAnimation
	ld hl, PlayCurrentMoveAnimation
	ld b, BANK(PlayCurrentMoveAnimation)
;> if off:                                          # then the doll just appears
;>     anim = AnimationSubstitute
	jr z, .animationEnabled
	ld hl, AnimationSubstitute
	ld b, BANK(AnimationSubstitute)
.animationEnabled
;> anim()
	call Bankswitch ; jump to routine depending on animation setting
;> PrintText(SubstituteText)
	ld hl, SubstituteText
	call PrintText
;> return DrawHUDsAndHPBars()
	ld hl, DrawHUDsAndHPBars
	ld b, BANK(DrawHUDsAndHPBars)
	jp Bankswitch
.alreadyHasSubstitute
;=@has
	ld hl, HasSubstituteText
	jr .printText
.notEnoughHP
;=@weak
	ld hl, TooWeakSubstituteText
.printText
	jp PrintText

;@ path: engine/battle/move_effects/substitute
SubstituteText:
	db TX_FAR
	dw _SubstituteText
	db BANK(_SubstituteText)
	db TX_END

;@ path: engine/battle/move_effects/substitute
HasSubstituteText:
	db TX_FAR
	dw _HasSubstituteText
	db BANK(_HasSubstituteText)
	db TX_END

;@ path: engine/battle/move_effects/substitute
TooWeakSubstituteText:
	db TX_FAR
	dw _TooWeakSubstituteText
	db BANK(_TooWeakSubstituteText)
	db TX_END
;@ def ActivatePC()
;@ Turn on a Pokémon Center or other public PC and open its main menu.
;@ path: engine/menus/pc
ActivatePC::
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> PlaySound(SFX_TURN_ON_PC)
	ld a, SFX_TURN_ON_PC
	call PlaySound
;> PrintText(TurnedOnPC1Text)
	ld hl, TurnedOnPC1Text
	call PrintText
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> wMiscFlags |= 1 << BIT_USING_GENERIC_PC
	ld hl, wMiscFlags
	set BIT_USING_GENERIC_PC, [hl]
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> Delay3()
	call Delay3
;> return PCMainMenu()
;@ def PCMainMenu()
;@ The PC's main menu, which grows with the story: BILL's (or SOMEONE's) PC, the player's PC, then PROF.OAK's PC
;@ once the player has the Pokédex and the Hall of Fame PC after the League; the last entry or B logs off.
;@ path: engine/menus/pc
PCMainMenu:
;> farcall(DisplayPCMainMenu)
	ld b, BANK(DisplayPCMainMenu)
	ld hl, DisplayPCMainMenu
	call Bankswitch
;> wMiscFlags |= 1 << BIT_NO_MENU_BUTTON_SOUND
	ld hl, wMiscFlags
	set BIT_NO_MENU_BUTTON_SOUND, [hl]
;> if HandleMenuInput() & PAD_B:
;>     return LogOff()
	call HandleMenuInput
	bit B_PAD_B, a
	jp nz, LogOff
;> item = wCurrentMenuItem
;> if wMaxMenuItem == 2:                       # before the Pokédex: BILL's PC, the player's PC, LOG OFF
	ld a, [wMaxMenuItem]
	cp 2
	jr nz, .next ;if not 2 menu items (not counting log off) (2 occurs before you get the pokedex)
;>     if item == 0:
;>         return BillsPC()
	ld a, [wCurrentMenuItem]
	and a
	jp z, BillsPC    ;if current menu item id is 0, it's bills pc
;>     if item != 1:
	cp 1
	jr z, .playersPC ;if current menu item id is 1, it's players pc
;>         return LogOff()
	jp LogOff        ;otherwise, it's 2, and you're logging off
.next
;> elif wMaxMenuItem == 3:                     # then PROF.OAK's PC too
	cp 3
	jr nz, .next2 ;if not 3 menu items (not counting log off) (3 occurs after you get the pokedex, before you beat the pokemon league)
;>     if item == 0:
;>         return BillsPC()
	ld a, [wCurrentMenuItem]
	and a
	jp z, BillsPC    ;if current menu item id is 0, it's bills pc
;>     if item != 1:
	cp 1
	jr z, .playersPC ;if current menu item id is 1, it's players pc
;>         if item == 2:
;>             return OaksPC()
	cp 2
	jp z, OaksPC     ;if current menu item id is 2, it's oaks pc
;>         return LogOff()
	jp LogOff        ;otherwise, it's 3, and you're logging off
.next2
;> else:                                       # after the League: the Hall of Fame PC too
;>     if item == 0:
;>         return BillsPC()
	ld a, [wCurrentMenuItem]
	and a
	jp z, BillsPC    ;if current menu item id is 0, it's bills pc
;>     if item != 1:
	cp 1
	jr z, .playersPC ;if current menu item id is 1, it's players pc
;>         if item == 2:
;>             return OaksPC()
	cp 2
	jp z, OaksPC     ;if current menu item id is 2, it's oaks pc
;>         if item == 3:
;>             return PKMNLeague()
	cp 3
	jp z, PKMNLeague ;if current menu item id is 3, it's pkmnleague
;>         return LogOff()
	jp LogOff        ;otherwise, it's 4, and you're logging off
.playersPC
;> # item 1: the player's own PC
;> wMiscFlags &= ~(1 << BIT_NO_MENU_BUTTON_SOUND) & 0xFF
	ld hl, wMiscFlags
	res BIT_NO_MENU_BUTTON_SOUND, [hl]
;> wMiscFlags |= 1 << BIT_USING_GENERIC_PC
	set BIT_USING_GENERIC_PC, [hl]
;> PlaySound(SFX_ENTER_PC)
	ld a, SFX_ENTER_PC
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PrintText(AccessedMyPCText)
	ld hl, AccessedMyPCText
	call PrintText
;> farcall(PlayerPC)
	ld b, BANK(PlayerPC)
	ld hl, PlayerPC
	call Bankswitch
;> return ReloadMainMenu()
	jr ReloadMainMenu
;@ def OaksPC()
;@ PROF.OAK's PC: the Pokédex rating.
;@ path: engine/menus/pc
OaksPC:
;> PlaySound(SFX_ENTER_PC)
	ld a, SFX_ENTER_PC
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> farcall(OpenOaksPC)
	ld b, BANK(OpenOaksPC)
	ld hl, OpenOaksPC
	call Bankswitch
;> return ReloadMainMenu()
	jr ReloadMainMenu
;@ def PKMNLeague()
;@ The Hall of Fame PC.
;@ path: engine/menus/pc
PKMNLeague:
;> PlaySound(SFX_ENTER_PC)
	ld a, SFX_ENTER_PC
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> farcall(PKMNLeaguePC)
	ld b, BANK(PKMNLeaguePC)
	ld hl, PKMNLeaguePC
	call Bankswitch
;> return ReloadMainMenu()
	jr ReloadMainMenu
;@ def BillsPC()
;@ The Pokémon storage system, called SOMEONE's PC until the player has met BILL.
;@ path: engine/menus/pc
BillsPC:
;> PlaySound(SFX_ENTER_PC)
	ld a, SFX_ENTER_PC
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> if event(EVENT_MET_BILL):
	ld a, [wEventFlags + $AA]
	bit (EVENT_MET_BILL) % 8, a
	jr nz, .billsPC ;if you've met bill, use that bill's instead of someone's
;>@bill     text = AccessedBillsPCText
;> else:
;>     text = AccessedSomeonesPCText
	ld hl, AccessedSomeonesPCText
	jr .printText
.billsPC
;=@bill
	ld hl, AccessedBillsPCText
.printText
;> PrintText(text)
	call PrintText
;> farcall(BillsPC_)
	ld b, BANK(BillsPC_)
	ld hl, BillsPC_
	call Bankswitch
;> return ReloadMainMenu()                      # it follows
;@ def ReloadMainMenu()
;@ Back from one of the PC's systems: redraw the map behind and show the main menu again.
;@ path: engine/menus/pc
ReloadMainMenu:
;> wDoNotWaitForButtonPressAfterDisplayingText = 0
	xor a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> ReloadMapData()
	call ReloadMapData
;> UpdateSprites()
	call UpdateSprites
;> return PCMainMenu()
	jp PCMainMenu
;@ def LogOff()
;@ LOG OFF: the switch-off sound, and the PC flags are cleared.
;@ path: engine/menus/pc
LogOff:
;> PlaySound(SFX_TURN_OFF_PC)
	ld a, SFX_TURN_OFF_PC
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> flags = addr(wMiscFlags)
	ld hl, wMiscFlags
;> mem[flags] &= ~((1 << BIT_USING_GENERIC_PC) | (1 << BIT_NO_MENU_BUTTON_SOUND)) & 0xFF
	res BIT_USING_GENERIC_PC, [hl]
	res BIT_NO_MENU_BUTTON_SOUND, [hl]
;> return
	ret

;@ path: engine/menus/pc
TurnedOnPC1Text:
	db TX_FAR
	dw _TurnedOnPC1Text
	db BANK(_TurnedOnPC1Text)
	db TX_END

;@ path: engine/menus/pc
AccessedBillsPCText:
	db TX_FAR
