	db BANK(_AccessedBillsPCText)
	db TX_END

;@ path: engine/menus/pc
AccessedSomeonesPCText:
	db TX_FAR
	dw _AccessedSomeonesPCText
	db BANK(_AccessedSomeonesPCText)
	db TX_END

;@ path: engine/menus/pc
AccessedMyPCText:
	db TX_FAR
	dw _AccessedMyPCText
	db BANK(_AccessedMyPCText)
	db TX_END

; removes one of the specified item ID [hItemToRemoveID] from bag (if existent)
;@ def RemoveItemByID()
;@ Take one of item hItemToRemoveID out of the bag, if it is there.
;@ test: [mem.__setitem__(wBagItems + i, rand(1, 30) if i % 2 == 0 else rand(1, 99)) for i in range(40)]; n = rand(1, 19); mem[wBagItems + 2 * n] = 0xFF; mem[wBagItems - 1] = n; hItemToRemoveID = rand(1, 30)
;@ test: hLoadedROMBank = 5    # the bank this code runs in
;@ path: engine/menus/pc
RemoveItemByID::
;> p = wBagItems
	ld hl, wBagItems
;> hItemToRemoveIndex = 0
	ldh a, [hItemToRemoveID]
	ld b, a
	xor a
	ldh [hItemToRemoveIndex], a
;>@scan while mem[p] != 0xFF:
.loop
	ld a, [hli]
	cp -1 ; reached terminator?
	ret z
;>     if mem[p] == hItemToRemoveID:
	cp b
	jr z, .foundItem
;>@f1         wItemQuantity = 1
;>@f2         wWhichPokemon = hItemToRemoveIndex
;>@f3         return RemoveItemFromInventory(addr(wNumBagItems))
;>     p += 2
	inc hl
;>     hItemToRemoveIndex += 1
	ldh a, [hItemToRemoveIndex]
	inc a
	ldh [hItemToRemoveIndex], a
;=@scan
	jr .loop
.foundItem
;=@f1
	ld a, $1
	ld [wItemQuantity], a
;=@f2
	ldh a, [hItemToRemoveIndex]
	ld [wWhichPokemon], a
;=@f3
	ld hl, wNumBagItems
	jp RemoveItemFromInventory


SECTION "Play Time", ROMX

;@ path: engine/play_time
;@ def TrackPlayTime()
;@ Once per frame: count the play time on in frames, seconds, minutes and hours while the game timer runs,
;@ stopping for good at 255 hours (wPlayTimeMaxed).
TrackPlayTime::
;> CountDownIgnoreInputBitReset()
	call CountDownIgnoreInputBitReset
;> if not wStatusFlags6 >> BIT_GAME_TIMER_COUNTING & 1 or wPlayTimeMaxed:
;>     return
	ld a, [wStatusFlags6]
	bit BIT_GAME_TIMER_COUNTING, a
	ret z
	ld a, [wPlayTimeMaxed]
	and a
	ret nz
;> wPlayTimeFrames = u8(wPlayTimeFrames + 1)
	ld a, [wPlayTimeFrames]
	inc a
	ld [wPlayTimeFrames], a
;> if wPlayTimeFrames != 60:
;>     return
	cp 60
	ret nz
;> wPlayTimeFrames = 0
	xor a
	ld [wPlayTimeFrames], a
;> wPlayTimeSeconds = u8(wPlayTimeSeconds + 1)
	ld a, [wPlayTimeSeconds]
	inc a
	ld [wPlayTimeSeconds], a
;> if wPlayTimeSeconds != 60:
;>     return
	cp 60
	ret nz
;> wPlayTimeSeconds = 0
	xor a
	ld [wPlayTimeSeconds], a
;> wPlayTimeMinutes = u8(wPlayTimeMinutes + 1)
	ld a, [wPlayTimeMinutes]
	inc a
	ld [wPlayTimeMinutes], a
;> if wPlayTimeMinutes != 60:
;>     return
	cp 60
	ret nz
;> wPlayTimeMinutes = 0
	xor a
	ld [wPlayTimeMinutes], a
;> wPlayTimeHours = u8(wPlayTimeHours + 1)
	ld a, [wPlayTimeHours]
	inc a
	ld [wPlayTimeHours], a
;> if wPlayTimeHours == 0xFF:
	cp $ff
	ret nz
;>     wPlayTimeMaxed = 0xFF
	ld a, $ff
	ld [wPlayTimeMaxed], a
	ret

;@ path: engine/play_time
;@ def CountDownIgnoreInputBitReset()
;@ Count wIgnoreInputCounter down; when it runs out, give the player the joypad back (and drop the buttons
;@ held while it was disabled).
CountDownIgnoreInputBitReset:
;> counter = wIgnoreInputCounter
	ld a, [wIgnoreInputCounter]
;> if counter == 0:
	and a
	jr nz, .decrement
;>     counter = 0xFF
	ld a, $ff
	jr .continue
.decrement
;> else:
;>     counter -= 1
	dec a
.continue
;> wIgnoreInputCounter = counter
	ld [wIgnoreInputCounter], a
;> if counter:
;>     return
	and a
	ret nz
;> flags = wStatusFlags5 & ~(1 << BIT_UNKNOWN_5_1 | 1 << BIT_UNKNOWN_5_2) & 0xFF
	ld a, [wStatusFlags5]
	res BIT_UNKNOWN_5_1, a
	res BIT_UNKNOWN_5_2, a
;> was_disabled = flags >> BIT_DISABLE_JOYPAD & 1
	bit BIT_DISABLE_JOYPAD, a
;> wStatusFlags5 = flags & ~(1 << BIT_DISABLE_JOYPAD) & 0xFF
	res BIT_DISABLE_JOYPAD, a
	ld [wStatusFlags5], a
;> if was_disabled:
	ret z
;>     hJoyPressed = 0
	xor a
	ldh [hJoyPressed], a
;>     hJoyHeld = 0
	ldh [hJoyHeld], a
	ret


SECTION "Doors and Ledges", ROMX

;@ path: engine/overworld/auto_movement
;@ def PlayerStepOutFromDoor()
;@ On arriving through a door: if the player stands on a door tile, take one automatic step down out of it
;@ with the buttons locked. Otherwise clear the simulated steps and the door flags.
PlayerStepOutFromDoor::
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_UNKNOWN_5_1) & 0xFF
	ld hl, wStatusFlags5
	res BIT_UNKNOWN_5_1, [hl]
;> if IsPlayerStandingOnDoorTile():
	call IsPlayerStandingOnDoorTile
	jr nc, .notStandingOnDoor
;>     wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;>     wMovementFlags = wMovementFlags | 1 << BIT_EXITING_DOOR
	ld hl, wMovementFlags
	set BIT_EXITING_DOOR, [hl]
;>     wSimulatedJoypadStatesIndex = 1
	ld a, $1
	ld [wSimulatedJoypadStatesIndex], a
;>     wSimulatedJoypadStatesEnd = PAD_DOWN
	ld a, PAD_DOWN
	ld [wSimulatedJoypadStatesEnd], a
;>     mem[wSpritePlayerStateData1ImageIndex] = 0
	xor a
	ld [wSpritePlayerStateData1ImageIndex], a
;>     StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;>     return
	ret
.notStandingOnDoor
;> wUnusedOverrideSimulatedJoypadStatesIndex = 0
	xor a
	ld [wUnusedOverrideSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesIndex = 0
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = 0
	ld [wSimulatedJoypadStatesEnd], a
;> wMovementFlags = wMovementFlags & ~(1 << BIT_STANDING_ON_DOOR | 1 << BIT_EXITING_DOOR) & 0xFF
	ld hl, wMovementFlags
	res BIT_STANDING_ON_DOOR, [hl]
	res BIT_EXITING_DOOR, [hl]
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_SCRIPTED_MOVEMENT_STATE) & 0xFF
	ld hl, wStatusFlags5
	res BIT_SCRIPTED_MOVEMENT_STATE, [hl]
	ret

;@ path: engine/overworld/auto_movement
;@ def _EndNPCMovementScript()
;@ End a scripted movement sequence: clear its flags, its script numbers and the simulated steps.
_EndNPCMovementScript::
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_SCRIPTED_MOVEMENT_STATE) & 0xFF
	ld hl, wStatusFlags5
	res BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wStatusFlags4 = wStatusFlags4 & ~(1 << BIT_INIT_SCRIPTED_MOVEMENT) & 0xFF
	ld hl, wStatusFlags4
	res BIT_INIT_SCRIPTED_MOVEMENT, [hl]
;> wMovementFlags = wMovementFlags & ~(1 << BIT_STANDING_ON_DOOR | 1 << BIT_EXITING_DOOR) & 0xFF
	ld hl, wMovementFlags
	res BIT_STANDING_ON_DOOR, [hl]
	res BIT_EXITING_DOOR, [hl]
;> wNPCMovementScriptSpriteOffset = 0
	xor a
	ld [wNPCMovementScriptSpriteOffset], a
;> wNPCMovementScriptPointerTableNum = 0
	ld [wNPCMovementScriptPointerTableNum], a
;> wNPCMovementScriptFunctionNum = 0
	ld [wNPCMovementScriptFunctionNum], a
;> wUnusedOverrideSimulatedJoypadStatesIndex = 0
	ld [wUnusedOverrideSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesIndex = 0
	ld [wSimulatedJoypadStatesIndex], a
;> wSimulatedJoypadStatesEnd = 0
	ld [wSimulatedJoypadStatesEnd], a
	ret

;@ path: engine/overworld/auto_movement
PalletMovementScriptPointerTable::
	dw PalletMovementScript_OakMoveLeft
	dw PalletMovementScript_PlayerMoveLeft
	dw PalletMovementScript_WaitAndWalkToLab
	dw PalletMovementScript_WalkToLab
	dw PalletMovementScript_Done

;@ path: engine/overworld/auto_movement
;@ def PalletMovementScript_OakMoveLeft()
;@ Oak stops the player leaving Pallet Town. If the player is on the right tile of the path (x 11), Oak first
;@ steps left below the player; otherwise the script can go straight to the walk to the lab. The map music
;@ stays off and the buttons are locked.
;@ test: wXCoord = rand(10, 11)
PalletMovementScript_OakMoveLeft:
;> steps = u8(wXCoord - 10)
	ld a, [wXCoord]
	sub $a
;> wNumStepsToTake = steps
	ld [wNumStepsToTake], a
;> if steps:
	jr z, .playerOnLeftTile
; The player is on the right tile of the northern path out of Pallet Town and
; Prof. Oak is below.
; Make Prof. Oak step to the left.
;>     end = FillMemory(addr(wNPCMovementDirections2), steps, NPC_MOVEMENT_LEFT)
	ld b, 0
	ld c, a
	ld hl, wNPCMovementDirections2
	ld a, NPC_MOVEMENT_LEFT
	call FillMemory
;>     mem[end] = 0xFF
	ld [hl], $ff
;>     hSpriteIndex = wSpriteIndex
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
;>     MoveSprite(addr(wNPCMovementDirections2))
	ld de, wNPCMovementDirections2
	call MoveSprite
;>     wNPCMovementScriptFunctionNum = 1
	ld a, $1
	ld [wNPCMovementScriptFunctionNum], a
	jr .done
; The player is on the left tile of the northern path out of Pallet Town and
; Prof. Oak is below.
; Prof. Oak is already where he needs to be.
.playerOnLeftTile
;> else:
;>     wNPCMovementScriptFunctionNum = 3
	ld a, $3
	ld [wNPCMovementScriptFunctionNum], a
.done
;> wStatusFlags7 = wStatusFlags7 | 1 << BIT_NO_MAP_MUSIC
	ld hl, wStatusFlags7
	set BIT_NO_MAP_MUSIC, [hl]
;> wJoyIgnore = PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld a, PAD_SELECT | PAD_START | PAD_CTRL_PAD
	ld [wJoyIgnore], a
	ret

;@ path: engine/overworld/auto_movement
;@ def PalletMovementScript_PlayerMoveLeft()
;@ Once Oak has stopped moving, the player follows him left by the same number of steps.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
PalletMovementScript_PlayerMoveLeft:
;> if wStatusFlags5 & (1 << BIT_SCRIPTED_NPC_MOVEMENT):     # Oak still moving
;>     return
	ld a, [wStatusFlags5]
	bit BIT_SCRIPTED_NPC_MOVEMENT, a
	ret nz ; return if Oak is still moving
;> wSimulatedJoypadStatesIndex = wNumStepsToTake
	ld a, [wNumStepsToTake]
	ld [wSimulatedJoypadStatesIndex], a
;> hNPCMovementDirections2Index = wNumStepsToTake
	ldh [hNPCMovementDirections2Index], a
;> ConvertNPCMovementDirectionsToJoypadMasks()  # a predef
	ld a, (ConvertNPCMovementDirectionsToJoypadMasksPredef - PredefPointers) / 3
	call Predef
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wNPCMovementScriptFunctionNum = 2
	ld a, $2
	ld [wNPCMovementScriptFunctionNum], a
	ret

;@ path: engine/overworld/auto_movement
;@ def PalletMovementScript_WaitAndWalkToLab()
;@ When the player has finished stepping left, start the walk to the lab.
PalletMovementScript_WaitAndWalkToLab:
;> if wSimulatedJoypadStatesIndex: return       # still walking left
	ld a, [wSimulatedJoypadStatesIndex]
	and a ; is the player done moving left yet?
	ret nz
;> PalletMovementScript_WalkToLab()

;@ path: engine/overworld/auto_movement
;@ def PalletMovementScript_WalkToLab()
;@ Oak leads the player to his lab: both walking routes are unpacked from their run-length lists, the player's
;@ as simulated buttons and Oak's as NPC directions.
PalletMovementScript_WalkToLab:
;> wOverrideSimulatedJoypadStatesMask = 0
	xor a
	ld [wOverrideSimulatedJoypadStatesMask], a
;> wNPCMovementScriptSpriteOffset = swap(wSpriteIndex)
	ld a, [wSpriteIndex]
	swap a
	ld [wNPCMovementScriptSpriteOffset], a
;> mem[wSpritePlayerStateData2MovementByte1] = 0
	xor a
	ld [wSpritePlayerStateData2MovementByte1], a
;> wSimulatedJoypadStatesIndex = u8(DecodeRLEList(addr(wSimulatedJoypadStatesEnd), RLEList_PlayerWalkToLab) - 1)
	ld hl, wSimulatedJoypadStatesEnd
	ld de, RLEList_PlayerWalkToLab
	call DecodeRLEList
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> DecodeRLEList(addr(wNPCMovementDirections2), RLEList_ProfOakWalkToLab)
	ld hl, wNPCMovementDirections2
	ld de, RLEList_ProfOakWalkToLab
	call DecodeRLEList
;> wStatusFlags4 = wStatusFlags4 & ~(1 << BIT_INIT_SCRIPTED_MOVEMENT) & 0xFF
	ld hl, wStatusFlags4
	res BIT_INIT_SCRIPTED_MOVEMENT, [hl]
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_SCRIPTED_MOVEMENT_STATE
	ld hl, wStatusFlags5
	set BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wNPCMovementScriptFunctionNum = 4
	ld a, $4
	ld [wNPCMovementScriptFunctionNum], a
	ret

;@ path: engine/overworld/auto_movement
RLEList_ProfOakWalkToLab:
	db NPC_MOVEMENT_DOWN, 5
	db NPC_MOVEMENT_LEFT, 1
	db NPC_MOVEMENT_DOWN, 5
	db NPC_MOVEMENT_RIGHT, 3
	db NPC_MOVEMENT_UP, 1
	db NPC_CHANGE_FACING, 1
	db -1 ; end

;@ path: engine/overworld/auto_movement
RLEList_PlayerWalkToLab:
	db PAD_UP, 2
	db PAD_RIGHT, 3
	db PAD_DOWN, 5
	db PAD_LEFT, 1
	db PAD_DOWN, 6
	db -1 ; end

;@ path: engine/overworld/auto_movement
;@ def PalletMovementScript_Done()
;@ At the lab door: Oak's overworld sprite disappears and the scripted movement ends.
PalletMovementScript_Done:
;> if wSimulatedJoypadStatesIndex:
;>     return
	ld a, [wSimulatedJoypadStatesIndex]
	and a
	ret nz
;> wToggleableObjectIndex = TOGGLE_PALLET_TOWN_OAK
	ld a, TOGGLE_PALLET_TOWN_OAK
	ld [wToggleableObjectIndex], a
;> HideObject()                                 # a predef
	ld a, (HideObjectPredef - PredefPointers) / 3
	call Predef
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_SCRIPTED_MOVEMENT_STATE) & 0xFF
	ld hl, wStatusFlags5
	res BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wStatusFlags4 = wStatusFlags4 & ~(1 << BIT_INIT_SCRIPTED_MOVEMENT) & 0xFF
	ld hl, wStatusFlags4
	res BIT_INIT_SCRIPTED_MOVEMENT, [hl]
;> EndNPCMovementScript()
	jp EndNPCMovementScript

