;@ A Pewter City man takes the player to the museum: his tune starts, and the player's and his routes are
;@ unpacked from their run-length lists.
;@ test: skip PewterGuys needs the player on one of the guide's starting tiles
PewterMovementScript_WalkToMuseum:
;> wAudioROMBank = BANK(Music_MuseumGuy)
	ld a, BANK(Music_MuseumGuy)
	ld [wAudioROMBank], a
;> wAudioSavedROMBank = BANK(Music_MuseumGuy)
	ld [wAudioSavedROMBank], a
;> wNewSoundID = MUSIC_MUSEUM_GUY
	ld a, MUSIC_MUSEUM_GUY
	ld [wNewSoundID], a
;> PlaySound(MUSIC_MUSEUM_GUY)
	call PlaySound
;> wNPCMovementScriptSpriteOffset = swap(wSpriteIndex)
	ld a, [wSpriteIndex]
	swap a
	ld [wNPCMovementScriptSpriteOffset], a
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wSimulatedJoypadStatesIndex = u8(DecodeRLEList(addr(wSimulatedJoypadStatesEnd), RLEList_PewterMuseumPlayer) - 1)
	ld hl, wSimulatedJoypadStatesEnd
	ld de, RLEList_PewterMuseumPlayer
	call DecodeRLEList
	dec a
	ld [wSimulatedJoypadStatesIndex], a
;> wWhichPewterGuy = 0
	xor a
	ld [wWhichPewterGuy], a
;> PewterGuys()                                 # a predef
	ld a, (PewterGuysPredef - PredefPointers) / 3
	call Predef
;> DecodeRLEList(addr(wNPCMovementDirections2), RLEList_PewterMuseumGuy)
	ld hl, wNPCMovementDirections2
	ld de, RLEList_PewterMuseumGuy
	call DecodeRLEList
