;@ path: engine/overworld/auto_movement
;@ def SetEnemyTrainerToStayAndFaceAnyDirection()
;@ After a trainer battle the trainer stays put (movement bytes $FF), except the rival and the Rockets of
;@ Pokémon Tower 7F, who leave.
;@ test: wCurMap = rand(0, NUM_MAPS - 1); hCurrentSpriteOffset = 16 * rand(1, 15)
SetEnemyTrainerToStayAndFaceAnyDirection::
;> if wCurMap == POKEMON_TOWER_7F:
;>     return
	ld a, [wCurMap]
	cp POKEMON_TOWER_7F
	ret z ; the Rockets on Pokemon Tower 7F leave after battling, so don't set them
;> p = RivalIDs
	ld hl, RivalIDs
	ld a, [wEngagedTrainerClass]
	ld b, a
.loop
;>@rival while mem[p] != 0xFF:
	ld a, [hli]
	cp -1
	jr z, .notRival
;>     if mem[p] == wEngagedTrainerClass: return    # the rival leaves after battling
	cp b
	ret z ; the rival leaves after battling, so don't set him
;>@next     p += 1
;=@rival
	jr .loop
.notRival
;> hSpriteIndex = wSpriteIndex
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
;> SetSpriteMovementBytesToFF()
	jp SetSpriteMovementBytesToFF

;@ path: engine/overworld/auto_movement
RivalIDs:
	db OPP_RIVAL1
	db OPP_RIVAL2
	db OPP_RIVAL3
	db -1 ; end
; returns whether the player is standing on a door tile in carry
;@ path: engine/overworld/doors
;@ def IsPlayerStandingOnDoorTile() -> carry
;@ Is the player standing on a door? Looks up the current tileset's door tile list (DoorTileIDPointers:
;@ tileset, pointer) and compares the tile under the lower left of the player's sprite with it.
;@ test: wCurMapTileset = rand(0, NUM_TILESETS - 1)
IsPlayerStandingOnDoorTile:
;> _, p, found = IsInArray(wCurMapTileset, DoorTileIDPointers, 3)   # (tileset, door list) entries
	push de
	ld hl, DoorTileIDPointers
	ld a, [wCurMapTileset]
	ld de, $3
	call IsInArray
	pop de
;> if not found: return False                   # a tileset without doors
	jr nc, .notStandingOnDoor
;> doors = mem16[p + 1]
	inc hl
	ld a, [hli]
	ld h, [hl]
	ld l, a
	; a = lower left background tile under player's sprite
;> tile = mem[coord(8, 9)]
	ld a, [(9) * SCREEN_WIDTH + (8) + wTileMap]
	ld b, a
.loop
;>@doors while mem[doors]:                       # the list ends with 0
	ld a, [hli]
	and a
	jr z, .notStandingOnDoor
;>     if mem[doors] == tile: return True
	cp b
	jr nz, .loop
	scf
	ret
;>@next     doors += 1
.notStandingOnDoor
;> return False
	and a
	ret

;@ path: engine/overworld/doors
DoorTileIDPointers:
	db OVERWORLD
	dw .OverworldDoorTileIDs
	db FOREST
	dw .ForestDoorTileIDs
	db MART
	dw .MartDoorTileIDs
	db HOUSE
	dw .HouseDoorTileIDs
	db FOREST_GATE
	dw .TilesetMuseumDoorTileIDs
	db MUSEUM
	dw .TilesetMuseumDoorTileIDs
	db GATE
	dw .TilesetMuseumDoorTileIDs
	db SHIP
	dw .ShipDoorTileIDs
	db LOBBY
	dw .LobbyDoorTileIDs
	db MANSION
	dw .MansionDoorTileIDs
	db LAB
	dw .LabDoorTileIDs
	db FACILITY
	dw .FacilityDoorTileIDs
	db PLATEAU
	dw .PlateauDoorTileIDs
	db -1 ; end


.OverworldDoorTileIDs:
	db $1B,$58
	db 0

.ForestDoorTileIDs:
	db $3a
	db 0

.MartDoorTileIDs:
	db $5e
	db 0

.HouseDoorTileIDs:
	db $54
	db 0

.TilesetMuseumDoorTileIDs:
	db $3b
	db 0

.ShipDoorTileIDs:
	db $1e
	db 0

.LobbyDoorTileIDs:
	db $1c,$38,$1a
	db 0

.MansionDoorTileIDs:
	db $1a,$1c,$53
	db 0

.LabDoorTileIDs:
	db $34
	db 0

.FacilityDoorTileIDs:
	db $43,$58,$1b
	db 0

.PlateauDoorTileIDs:
	db $3b,$1b
	db 0
;@ path: engine/overworld/ledges
;@ def HandleLedges()
;@ Outdoors only: is the player facing down a ledge? LedgeTiles lists (facing, tile stood on, tile in front,
;@ button). If that button is held, the hop starts: the joypad is locked, two simulated steps in that
;@ direction are queued, the shadow sprite appears and the ledge sound plays.
HandleLedges::
;> if wMovementFlags & (1 << BIT_LEDGE_OR_FISHING):
;>     return
	ld a, [wMovementFlags]
	bit BIT_LEDGE_OR_FISHING, a
	ret nz
;> if wCurMapTileset != OVERWORLD:
;>     return
	ld a, [wCurMapTileset]
	and a ; OVERWORLD
	ret nz
;> GetTileAndCoordsInFrontOfPlayer()
	ld a, (GetTileAndCoordsInFrontOfPlayerPredef - PredefPointers) / 3
	call Predef
;> facing = wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
	ld b, a
;> standing = mem[coord(8, 9)]
	ld a, [(9) * SCREEN_WIDTH + (8) + wTileMap]
	ld c, a
;> front = wTileInFrontOfPlayer
	ld a, [wTileInFrontOfPlayer]
	ld d, a
;> p = LedgeTiles
	ld hl, LedgeTiles
.loop
;> while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
;=@noledge
	ret z
;>@match     if mem[p] == facing and mem[p + 1] == standing and mem[p + 2] == front:
	cp b
	jr nz, .nextLedgeTile1
	ld a, [hli]
	cp c
	jr nz, .nextLedgeTile2
;=@match
	ld a, [hli]
	cp d
	jr nz, .nextLedgeTile3
;>         button = mem[p + 3]
	ld a, [hl]
	ld e, a
;>         break
	jr .foundMatch
.nextLedgeTile1
;>     p += 4
	inc hl
.nextLedgeTile2
	inc hl
.nextLedgeTile3
	inc hl
	jr .loop
;> else:                                        # no ledge here
;>@noledge     return
.foundMatch
;> if not hJoyHeld & button:
;>     return
	ldh a, [hJoyHeld]
	and e
	ret z
;> wJoyIgnore = PAD_BUTTONS | PAD_CTRL_PAD
	ld a, PAD_BUTTONS | PAD_CTRL_PAD
	ld [wJoyIgnore], a
;> wMovementFlags = wMovementFlags | 1 << BIT_LEDGE_OR_FISHING
	ld hl, wMovementFlags
	set BIT_LEDGE_OR_FISHING, [hl]
;> StartSimulatingJoypadStates()
	call StartSimulatingJoypadStates
;> wSimulatedJoypadStatesEnd = button
	ld a, e
	ld [wSimulatedJoypadStatesEnd], a
;> mem[addr(wSimulatedJoypadStatesEnd) + 1] = button
	ld [wSimulatedJoypadStatesEnd + 1], a
;> wSimulatedJoypadStatesIndex = 2
	ld a, $2
	ld [wSimulatedJoypadStatesIndex], a
;> LoadHoppingShadowOAM()
	call LoadHoppingShadowOAM
;> PlaySound(SFX_LEDGE)
	ld a, SFX_LEDGE
	call PlaySound
	ret

;@ path: engine/overworld/ledges
LedgeTiles:
	; player direction, tile player standing on, ledge tile, input required
	db SPRITE_FACING_DOWN,  $2C, $37, PAD_DOWN
	db SPRITE_FACING_DOWN,  $39, $36, PAD_DOWN
	db SPRITE_FACING_DOWN,  $39, $37, PAD_DOWN
	db SPRITE_FACING_LEFT,  $2C, $27, PAD_LEFT
	db SPRITE_FACING_LEFT,  $39, $27, PAD_LEFT
	db SPRITE_FACING_RIGHT, $2C, $0D, PAD_RIGHT
	db SPRITE_FACING_RIGHT, $2C, $1D, PAD_RIGHT
	db SPRITE_FACING_RIGHT, $39, $0D, PAD_RIGHT
	db -1 ; end

;@ path: engine/overworld/ledges
;@ def LoadHoppingShadowOAM()
;@ The shadow under a hopping player: copy its 1bpp tile to tile $7F of the sprite tiles and place it with
;@ OAM block 9 at y $54, x $48.
LoadHoppingShadowOAM:
;> CopyVideoDataDouble(addr(vChars1) + 0x7F * 16, LedgeHoppingShadow, BANK(LedgeHoppingShadow),
;>                     (LedgeHoppingShadowEnd - LedgeHoppingShadow) // TILE_1BPP_SIZE)
	ld hl, vChars1 + TILE_SIZE * $7f
	ld de, LedgeHoppingShadow
	ld bc, ((BANK(LedgeHoppingShadow)) & $ff) << 8 + (((LedgeHoppingShadowEnd - LedgeHoppingShadow) / TILE_1BPP_SIZE) & $ff)
	call CopyVideoDataDouble
;> WriteOAMBlock(9, 0x54, 0x48, LedgeHoppingShadowOAMBlock)     # the shadow below the player
	ld a, $9
	; b, c = y, x coordinates of shadow
	ld bc, (($54) & $ff) << 8 + (($48) & $ff)
	ld de, LedgeHoppingShadowOAMBlock
	call WriteOAMBlock
	ret

;@ path: engine/overworld/ledges
LedgeHoppingShadow:
	db $00, $00, $00, $00, $07, $1f, $3f, $7f
;@ path: engine/overworld/ledges
LedgeHoppingShadowEnd:

;@ path: engine/overworld/ledges
LedgeHoppingShadowOAMBlock:
; tile ID, attributes
	db $ff, OAM_PAL1
	db $ff, OAM_XFLIP
	db $ff, OAM_YFLIP
	db $ff, OAM_XFLIP | OAM_YFLIP


