;@ path: engine/movie/oak_speech/clear_save
;@ def DoClearSaveDialogue()
;@ "Clear all saved data?" NO / YES; YES erases the save RAM. Then the game restarts.
;@ test: skip runs a menu
DoClearSaveDialogue:
;> ClearScreen()
	call ClearScreen
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> PrintText(ClearSaveDataText)
	ld hl, ClearSaveDataText
	call PrintText
;> wTwoOptionMenuID = NO_YES_MENU
	ld hl, (7) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((15) & $ff)
	ld a, NO_YES_MENU
	ld [wTwoOptionMenuID], a
;> wTextBoxID = TWO_OPTION_MENU
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;> DisplayTextBoxID()                            # at coord(14, 7)
	call DisplayTextBoxID
;> if wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	and a
	jp z, Init
;>     ClearAllSRAMBanks()
	ld b, BANK(ClearAllSRAMBanks)
	ld hl, ClearAllSRAMBanks
	call Bankswitch
;> Init()
	jp Init

;@ path: engine/movie/oak_speech/clear_save
ClearSaveDataText:
	db TX_FAR
	dw _ClearSaveDataText
	db BANK(_ClearSaveDataText)
	db TX_END
;@ path: engine/events/elevator
;@ def DisplayElevatorFloorMenu()
;@ An elevator panel: choose a floor from the list in wItemList; the first two warps of the elevator map then
;@ lead to that floor (wElevatorWarpMaps: warp, map per floor).
;@ test: skip shows a menu
DisplayElevatorFloorMenu:
;> PrintText(WhichFloorText)
	ld hl, WhichFloorText
	call PrintText
;> wListPointer[0] = addr(wItemList) & 0xFF
;> wListPointer[1] = addr(wItemList) >> 8
	ld hl, wItemList
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;> saved = wListScrollOffset
	ld a, [wListScrollOffset]
	push af
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wListScrollOffset = 0
	ld [wListScrollOffset], a
;> wPrintItemPrices = 0
	ld [wPrintItemPrices], a
;> wListMenuID = SPECIALLISTMENU
	ld a, SPECIALLISTMENU
	ld [wListMenuID], a
;> closed = DisplayListMenuID()                 # carry: the menu was closed
	call DisplayListMenuID
;> wListScrollOffset = saved
	pop bc
	ld a, b
	ld [wListScrollOffset], a
;> if closed:
;>     return
	ret c
;> wCurrentMapScriptFlags = wCurrentMapScriptFlags | 1 << BIT_CUR_MAP_USED_ELEVATOR
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_USED_ELEVATOR, [hl]
;> p = addr(wElevatorWarpMaps) + u8(2 * wWhichPokemon)    # the chosen floor
	ld hl, wElevatorWarpMaps
	ld a, [wWhichPokemon]
	add a
	ld d, 0
	ld e, a
	add hl, de
;> warp, dest_map = mem[p], mem[p + 1]
	ld a, [hli]
	ld b, a
	ld a, [hl]
	ld c, a
;> for i in range(2):
	ld hl, wWarpEntries
	call .UpdateWarp

.UpdateWarp
;>     mem[addr(wWarpEntries) + 4 * i + 2] = warp            # destination warp
	inc hl
	inc hl
	ld a, b
	ld [hli], a ; destination warp ID
;>     mem[addr(wWarpEntries) + 4 * i + 3] = dest_map        # destination map
	ld a, c
	ld [hli], a ; destination map ID
	ret

;@ path: engine/events/elevator
WhichFloorText:
	db TX_FAR
	dw _WhichFloorText
	db BANK(_WhichFloorText)
	db TX_END


SECTION "Hidden Events 1", ROMX

;@ def OpenOaksPC()
;@ PROF.OAK's PC: offers to rate the Pokédex and, on YES, shows his rating.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/menus/oaks_pc
OpenOaksPC:
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> PrintText(AccessedOaksPCText)
	ld hl, AccessedOaksPCText
	call PrintText
;> PrintText(GetDexRatedText)
	ld hl, GetDexRatedText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem == 0:                   # YES
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .closePC
;>     DisplayDexRating()
	ld a, (DisplayDexRatingPredef - PredefPointers) / 3
	call Predef
.closePC
;> PrintText(ClosedOaksPCText)
	ld hl, ClosedOaksPCText
	call PrintText
;> return LoadScreenTilesFromBuffer2()
	jp LoadScreenTilesFromBuffer2

