;@ path: engine/events/hidden_events/safari_game
;@ def SafariZoneCheck()
;@ After a Safari battle: the game is over when the last Safari Ball is gone (only inside the Safari Zone).
;@ test: wNumSafariBalls = rand(1, 30)
SafariZoneCheck::
;>@over if event(EVENT_IN_SAFARI_ZONE) and wNumSafariBalls == 0:
	; if we are not in the Safari Zone,
	ld hl, wEventFlags + $49
	bit (EVENT_IN_SAFARI_ZONE) % 8, [hl]
	jr z, SafariZoneGameStillGoing ; don't bother printing game over text
;=@over
	ld a, [wNumSafariBalls]
	and a
;>     SafariZoneGameOver()
	jr z, SafariZoneGameOver
;> else:
;>     SafariZoneGameStillGoing()
	jr SafariZoneGameStillGoing

;@ path: engine/events/hidden_events/safari_game
;@ def SafariZoneCheckSteps()
;@ Count down one Safari Zone step (wSafariSteps, high byte first); the game is over when none are left.
;@ test: mem[wSafariSteps] = rand(0, 1); mem[wSafariSteps + 1] = rand(1, 255)
SafariZoneCheckSteps::
;> steps = wSafariSteps[0] << 8 | wSafariSteps[1]
	ld a, [wSafariSteps]
	ld b, a
	ld a, [wSafariSteps + 1]
	ld c, a
;> if steps == 0:
;>     return SafariZoneGameOver()
	or b
	jr z, SafariZoneGameOver
;> steps -= 1
	dec bc
;> wSafariSteps[0] = steps >> 8
	ld a, b
	ld [wSafariSteps], a
;> wSafariSteps[1] = steps & 0xFF
	ld a, c
	ld [wSafariSteps + 1], a
;> SafariZoneGameStillGoing()
;@ path: engine/events/hidden_events/safari_game
;@ def SafariZoneGameStillGoing()
;@ The Safari game goes on.
SafariZoneGameStillGoing:
;> wSafariZoneGameOver = 0
	xor a
	ld [wSafariZoneGameOver], a
	ret

;@ path: engine/events/hidden_events/safari_game
;@ def SafariZoneGameOver()
;@ Time or balls are up: the music stops, the gate's announcement chime plays, the game-over text is shown
;@ and the player is sent back to the Safari Zone gate.
;@ test: skip waits until the sound engine has started the announcement
SafariZoneGameOver:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wAudioFadeOutControl = 0
	xor a
	ld [wAudioFadeOutControl], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	dec a ; SFX_STOP_ALL_MUSIC
	call PlaySound
;> PlayMusic(SFX_SAFARI_ZONE_PA, BANK(SFX_Safari_Zone_PA))
	ld c, BANK(SFX_Safari_Zone_PA)
	ld a, SFX_SAFARI_ZONE_PA
	call PlayMusic
.waitForMusicToPlay
;> while wChannelSoundIDs[CHAN5] != SFX_SAFARI_ZONE_PA:
;>     wait_vblank_flag()    # the audio engine runs in the VBlank interrupt
	ld a, [wChannelSoundIDs + CHAN5]
	cp SFX_SAFARI_ZONE_PA
	jr nz, .waitForMusicToPlay
;> hTextID = TEXT_SAFARI_GAME_OVER
	ld a, TEXT_SAFARI_GAME_OVER
	ldh [hTextID], a
;> DisplayTextID()
	call DisplayTextID
;> wPlayerMovingDirection = 0
	xor a
	ld [wPlayerMovingDirection], a
;> hWarpDestinationMap = SAFARI_ZONE_GATE
	ld a, SAFARI_ZONE_GATE
	ldh [hWarpDestinationMap], a
;> wDestinationWarpID = 3
	ld a, $3
	ld [wDestinationWarpID], a
;> wSafariZoneGateCurScript = SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI
	ld a, SCRIPT_SAFARIZONEGATE_LEAVING_SAFARI
	ld [wSafariZoneGateCurScript], a
;> set_event(EVENT_SAFARI_GAME_OVER)
	ld hl, wEventFlags + $49
	set (EVENT_SAFARI_GAME_OVER) % 8, [hl]
;> wSafariZoneGameOver = 1
	ld a, 1
	ld [wSafariZoneGameOver], a
	ret

