;@ path: engine/events/hidden_events/cinnabar_gym_quiz
;@ def CinnabarGymGateFlagAction(bit: c, action: b) -> c
;@ FlagAction on the Cinnabar Gym gate flags, which start at EVENT_CINNABAR_GYM_GATE0_UNLOCKED's byte.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
CinnabarGymGateFlagAction:
;> return FlagAction(addr(wEventFlags) + EVENT_CINNABAR_GYM_GATE0_UNLOCKED // 8, bit, action)   # through FlagActionPredef
	ld hl, wEventFlags + $55
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/events/hidden_events/cinnabar_gym_quiz
;@ def CinnabarGymQuiz_AskQuestion()
;@ Yes or no? The right answer opens the gate for good (event flag and map block, with a chime). A wrong one
;@ plays the "denied" sound and, if that gate's trainer is still unbeaten, makes them come and battle.
;@ test: skip asks the player a question
CinnabarGymQuiz_AskQuestion:
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem == hGymGateAnswer:
	ldh a, [hGymGateAnswer]
	ld c, a
	ld a, [wCurrentMenuItem]
	cp c
	jr nz, .wrongAnswer
;>     wCurrentMapScriptFlags = wCurrentMapScriptFlags | 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;>     hBackupGymGateIndex = hGymGateIndex
	ldh a, [hGymGateIndex]
	ldh [hBackupGymGateIndex], a
;>     PrintText(CinnabarGymQuizCorrectText)
	ld hl, CinnabarGymQuizCorrectText
	call PrintText
;>     CinnabarGymGateFlagAction(u8(hBackupGymGateIndex + EVENT_CINNABAR_GYM_GATE0_UNLOCKED % 8), FLAG_SET)
	ldh a, [hBackupGymGateIndex]
	ld c, a
	ld b, FLAG_SET
	call CinnabarGymGateFlagAction
;>     UpdateCinnabarGymGateTileBlocks_()
;>     return
	jp UpdateCinnabarGymGateTileBlocks_
.wrongAnswer
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PlaySound(SFX_DENIED)
	ld a, SFX_DENIED
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PrintText(CinnabarGymQuizIncorrectText)
	ld hl, CinnabarGymQuizIncorrectText
	call PrintText
;> trainer = u8(hGymGateIndex + EVENT_BEAT_CINNABAR_GYM_TRAINER_0 % 8)    # this gate's trainer
	ldh a, [hGymGateIndex]
	add $2
	ld c, a
;> beaten = FlagAction(addr(wEventFlags) + EVENT_BEAT_CINNABAR_GYM_TRAINER_0 // 8, trainer, FLAG_TEST)   # through FlagActionPredef
	ld b, FLAG_TEST
	ld hl, wEventFlags + $53
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> if beaten:
;>     return
	ld a, c
	and a
	ret nz
;> wOpponentAfterWrongAnswer = u8(hGymGateIndex + 2)
	ldh a, [hGymGateIndex]
	add $2
	ld [wOpponentAfterWrongAnswer], a
	ret

;@ path: engine/events/hidden_events/cinnabar_gym_quiz
;@ def CinnabarGymQuizCorrectText() -> hl
;@ "You're absolutely correct!" with a jingle; then, if the gate was not open yet, the gate sound.
;@ test: skip a text script: the code after text_asm is run by the text engine
CinnabarGymQuizCorrectText:
	db TX_SOUND_GET_ITEM_1
	db TX_FAR
	dw _CinnabarGymQuizCorrectText
	db BANK(_CinnabarGymQuizCorrectText)
	db TX_PROMPT_BUTTON
	db TX_START_ASM

;> opened = CinnabarGymGateFlagAction(u8(hBackupGymGateIndex + EVENT_CINNABAR_GYM_GATE0_UNLOCKED % 8), FLAG_TEST)
	ldh a, [hBackupGymGateIndex]
	ld c, a
	ld b, FLAG_TEST
	call CinnabarGymGateFlagAction
;> if opened: return TextScriptEnd()            # already open: no gate sound
	ld a, c
	and a
	jp nz, TextScriptEnd
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/events/hidden_events/cinnabar_gym_quiz
CinnabarGymQuizIncorrectText:
	db TX_FAR
	dw _CinnabarGymQuizIncorrectText
	db BANK(_CinnabarGymQuizIncorrectText)
	db TX_END

;@ path: engine/events/hidden_events/cinnabar_gym_quiz
;@ def UpdateCinnabarGymGateTileBlocks_()
;@ Draw the six gates of the Cinnabar Gym: open floor (block $0E) where the gate's flag is set, the gate block
;@ from CinnabarGymGateCoords (x, y, block) otherwise.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
UpdateCinnabarGymGateTileBlocks_::
; Update the overworld map with open floor blocks or locked gate blocks
; depending on event flags.
;> hGymGateIndex = 6
	ld a, 6
	ldh [hGymGateIndex], a
;> while True:
.loop
;>     index = u8(4 * (hGymGateIndex - 1))
	ldh a, [hGymGateIndex]
	dec a
	add a
	add a
	ld d, 0
	ld e, a
;>     p = CinnabarGymGateCoords + index
	ld hl, CinnabarGymGateCoords
	add hl, de
;>     x, y = mem[p], mem[p + 1]
	ld a, [hli]
	ld b, [hl]
	ld c, a
	inc hl
;>     wGymGateTileBlock = mem[p + 2]
	ld a, [hl]
	ld [wGymGateTileBlock], a
	push bc
;>     hBackupGymGateIndex = hGymGateIndex
	ldh a, [hGymGateIndex]
	ldh [hBackupGymGateIndex], a
;>     if CinnabarGymGateFlagAction(u8(hBackupGymGateIndex + EVENT_CINNABAR_GYM_GATE0_UNLOCKED % 8), FLAG_TEST):
	ld c, a
	ld b, FLAG_TEST
	call CinnabarGymGateFlagAction
	ld a, c
	and a
	jr nz, .unlocked
;>@open         block = 0x0E                         # unlocked: open floor
;>     else:
;>         block = wGymGateTileBlock
	ld a, [wGymGateTileBlock]
	jr .next
.unlocked
;=@open
	ld a, $e
.next
;>     wNewTileBlockID = block
	pop bc
	ld [wNewTileBlockID], a
;>     ReplaceTileBlock()                       # a predef, at block (x, y)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
;>     hGymGateIndex -= 1
	ld hl, hGymGateIndex
	dec [hl]
;>     if hGymGateIndex == 0:
;>         break
	jr nz, .loop
	ret


DEF HORIZONTAL_GATE_BLOCK EQU $54
DEF VERTICAL_GATE_BLOCK   EQU $5f

;@ path: engine/events/hidden_events/cinnabar_gym_quiz
CinnabarGymGateCoords:
	; x coord, y coord, block id
	db 9, 3, HORIZONTAL_GATE_BLOCK, 0
	db 6, 3, HORIZONTAL_GATE_BLOCK, 0
	db 6, 6, HORIZONTAL_GATE_BLOCK, 0
	db 3, 8, VERTICAL_GATE_BLOCK, 0
	db 2, 6, HORIZONTAL_GATE_BLOCK, 0
	db 2, 3, HORIZONTAL_GATE_BLOCK, 0
