;@ path: engine/events/hidden_events/bills_house_pc
;@ def BillsHousePC()
;@ Bill's computer, from below. Before Bill asks for help it only shows its screen. When he has asked, it
;@ runs the Cell Separator (sounds and all). After the player has left his house, it offers his list of
;@ Eevee evolutions.
;@ test: skip prints a text
BillsHousePC:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> if wSpritePlayerStateData1FacingDirection != SPRITE_FACING_UP:
;>     return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> if event(EVENT_LEFT_BILLS_HOUSE_AFTER_HELPING):      # his list of Eevee evolutions
;>@list1     wDoNotWaitForButtonPressAfterDisplayingText = 1
;>@list2     PrintPredefTextID((BillsHousePokemonList_id - TextPredefs) // 2 + 1)
;>@list3     return
	ld a, [wEventFlags + $AB]
	bit (EVENT_LEFT_BILLS_HOUSE_AFTER_HELPING) % 8, a
	jr nz, .displayBillsHousePokemonList
;> if event(EVENT_USED_CELL_SEPARATOR_ON_BILL) or not event(EVENT_BILL_SAID_USE_CELL_SEPARATOR):
	bit (EVENT_USED_CELL_SEPARATOR_ON_BILL) % 8, a
	jr nz, .displayBillsHouseMonitorText
	bit (EVENT_BILL_SAID_USE_CELL_SEPARATOR) % 8, a
	jr nz, .doCellSeparator
.displayBillsHouseMonitorText
;>     PrintPredefTextID((BillsHouseMonitorText_id - TextPredefs) // 2 + 1)
;>     return
	ld a, (BillsHouseMonitorText_id - TextPredefs) / 2 + 1
	jp PrintPredefTextID
.doCellSeparator
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> PrintPredefTextID((BillsHouseInitiatedText_id - TextPredefs) // 2 + 1)
	ld a, (BillsHouseInitiatedText_id - TextPredefs) / 2 + 1
	call PrintPredefTextID
;> DelayFrames(32)                              # the Cell Separator at work
	ld c, 32
	call DelayFrames
;> PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> DelayFrames(80)
	ld c, 80
	call DelayFrames
;> PlaySound(SFX_SHRINK)
	ld a, SFX_SHRINK
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> DelayFrames(48)
	ld c, 48
	call DelayFrames
;> PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> DelayFrames(32)
	ld c, 32
	call DelayFrames
;> PlaySound(SFX_GET_ITEM_1)
	ld a, SFX_GET_ITEM_1
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PlayDefaultMusic()
	call PlayDefaultMusic
;> set_event(EVENT_USED_CELL_SEPARATOR_ON_BILL)
	ld hl, wEventFlags + $AB
	set (EVENT_USED_CELL_SEPARATOR_ON_BILL) % 8, [hl]
	ret
.displayBillsHousePokemonList
;=@list1
	ld a, $1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;=@list2
	ld a, (BillsHousePokemonList_id - TextPredefs) / 2 + 1
	call PrintPredefTextID
;=@list3
	ret

;@ path: engine/events/hidden_events/bills_house_pc
BillsHouseMonitorText::
	db TX_FAR
	dw _BillsHouseMonitorText
	db BANK(_BillsHouseMonitorText)
	db TX_END

;@ path: engine/events/hidden_events/bills_house_pc
