	db BANK(_BillsHouseInitiatedText)
	db TX_PROMPT_BUTTON
	db TX_START_ASM
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> DelayFrames(16)
	ld c, 16
	call DelayFrames
;> PlaySound(SFX_SWITCH)
	ld a, SFX_SWITCH
	call PlaySound
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> DelayFrames(60)
	ld c, 60
	call DelayFrames
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/events/hidden_events/bills_house_pc
;@ def BillsHousePokemonList() -> hl
;@ Bill's favourite Pokémon: a menu of Eevee and its three evolutions; choosing one shows its Pokédex
;@ entry, B or CANCEL leaves.
;@ test: skip a text script: the code after text_asm is run by the text engine
BillsHousePokemonList::
	db TX_START_ASM
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> PrintText(BillsHousePokemonListText1)
	ld hl, BillsHousePokemonListText1
	call PrintText
;> wMenuItemOffset = 0
	xor a
	ld [wMenuItemOffset], a ; not used
;> wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 4
	ld a, 4
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> while True:
.billsPokemonLoop
;>     wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;>     TextBoxBorder(coord(0, 0), 10, 9)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 10
	ld c, 9
	call TextBoxBorder
;>     PlaceString(BillsMonListText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, BillsMonListText
	call PlaceString
;>     PrintText(BillsHousePokemonListText2)
	ld hl, BillsHousePokemonListText2
	call PrintText
;>     SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;>     if HandleMenuInput() & (1 << B_PAD_B):
;>         break
	call HandleMenuInput
	bit B_PAD_B, a
	jr nz, .cancel
;>     mon = u8(wCurrentMenuItem + EEVEE)
	ld a, [wCurrentMenuItem]
	add EEVEE
;>@valid     if mon not in (EEVEE, FLAREON, JOLTEON, VAPOREON):      # CANCEL
	cp EEVEE
	jr z, .displayPokedex
	cp FLAREON
	jr z, .displayPokedex
	cp JOLTEON
	jr z, .displayPokedex
;=@valid
	cp VAPOREON
	jr z, .displayPokedex
;>         break
	jr .cancel
.displayPokedex
;>     DisplayPokedex(mon)
	call DisplayPokedex
;>     LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
	jr .billsPokemonLoop
.cancel
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/events/hidden_events/bills_house_pc
BillsHousePokemonListText1:
	db TX_FAR
	dw _BillsHousePokemonListText1
	db BANK(_BillsHousePokemonListText1)
	db TX_END

