BillsMonListText:
	db   "EEVEE"
	db "<NEXT>", "FLAREON"
	db "<NEXT>", "JOLTEON"
	db "<NEXT>", "VAPOREON"
	db "<NEXT>", "CANCEL@"

;@ path: engine/events/hidden_events/bills_house_pc
BillsHousePokemonListText2:
	db TX_FAR
	dw _BillsHousePokemonListText2
	db BANK(_BillsHousePokemonListText2)
	db TX_END
