;@ The e-mail on Oak's computer, readable from below.
;@ test: skip prints a text
DisplayOakLabEmailText:
;> if wSpritePlayerStateData1FacingDirection != SPRITE_FACING_UP: return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> PrintPredefTextID((OakLabEmailText_id - TextPredefs) // 2 + 1)
	ld a, (OakLabEmailText_id - TextPredefs) / 2 + 1
	jp PrintPredefTextID

;@ path: engine/events/hidden_events/oaks_lab_email
OakLabEmailText::
	db TX_FAR
