	db BANK(_OakLabEmailText)
	db TX_END


SECTION "Bill's PC", ROMX

;@ path: engine/pokemon/bills_pc
;@ def DisplayPCMainMenu()
;@ The PC's first menu: BILL's (or SOMEONE's) PC, the player's PC, PROF.OAK's PC once the player has the
;@ Pokédex, the Pokémon League PC once a team is in the Hall of Fame, and LOG OFF.
;@ test: skip draws a menu
DisplayPCMainMenu::
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> if wNumHoFTeams:
	ld a, [wNumHoFTeams]
	and a
	jr nz, .leaguePCAvailable
;>@ten     height = 10                           # room for the League PC
;> elif not event(EVENT_GOT_POKEDEX):
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	jr z, .noOaksPC
;>@six     height = 6
;> else:                                         # (checks the Hall of Fame once more)
	ld a, [wNumHoFTeams]
	and a
	jr nz, .leaguePCAvailable
;>     height = 8                                # room for PROF.OAK's PC
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 8
	ld c, 14
	jr .next
.noOaksPC
;> # .noOaksPC
;=@six
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 6
	ld c, 14
	jr .next
.leaguePCAvailable
;> # .leaguePCAvailable
;=@ten
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 10
	ld c, 14
.next
;> TextBoxBorder(coord(0, 0), height, 14)
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> wMaxMenuItem = 3
	ld a, 3
	ld [wMaxMenuItem], a
;> if event(EVENT_MET_BILL):
	ld a, [wEventFlags + $AA]
	bit (EVENT_MET_BILL) % 8, a
	jr nz, .metBill
;>@bill     PlaceString(BillsPCText, coord(2, 2))
;> else:
;>     PlaceString(SomeonesPCText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, SomeonesPCText
	jr .next2
.metBill
;> # .metBill
;=@bill
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, BillsPCText
.next2
	call PlaceString
;> after, _ = PlaceString(addr(wPlayerName), coord(2, 4))
	ld hl, (4) * SCREEN_WIDTH + (2) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PlaceString(PlayersPCText, after)             # "<player>'s PC"
	ld l, c
	ld h, b
	ld de, PlayersPCText
	call PlaceString
;> if event(EVENT_GOT_POKEDEX):
	ld a, [wEventFlags + $4]
	bit (EVENT_GOT_POKEDEX) % 8, a
	jr z, .noOaksPC2
;>     PlaceString(OaksPCText, coord(2, 6))
	ld hl, (6) * SCREEN_WIDTH + (2) + wTileMap
	ld de, OaksPCText
	call PlaceString
;>     if wNumHoFTeams:
	ld a, [wNumHoFTeams]
	and a
	jr z, .noLeaguePC
;>         wMaxMenuItem = 4
	ld a, 4
	ld [wMaxMenuItem], a
;>         PlaceString(PKMNLeaguePCText, coord(2, 8))
	ld hl, (8) * SCREEN_WIDTH + (2) + wTileMap
	ld de, PKMNLeaguePCText
	call PlaceString
;>         PlaceString(LogOffPCText, coord(2, 10))
	ld hl, (10) * SCREEN_WIDTH + (2) + wTileMap
	ld de, LogOffPCText
	jr .next3
.noLeaguePC
;>     else:
;>         PlaceString(LogOffPCText, coord(2, 8))
	ld hl, (8) * SCREEN_WIDTH + (2) + wTileMap
	ld de, LogOffPCText
	jr .next3
.noOaksPC2
;> else:
;>     wMaxMenuItem = 2
	ld a, $2
	ld [wMaxMenuItem], a
;>     PlaceString(LogOffPCText, coord(2, 6))
	ld hl, (6) * SCREEN_WIDTH + (2) + wTileMap
	ld de, LogOffPCText
.next3
	call PlaceString
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> wCurrentMenuItem = 0
;> wLastMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
	ret

;@ path: engine/pokemon/bills_pc
SomeonesPCText:   db "SOMEONE's PC@"
;@ path: engine/pokemon/bills_pc
BillsPCText:      db "BILL's PC@"
;@ path: engine/pokemon/bills_pc
PlayersPCText:    db "'s PC@"
;@ path: engine/pokemon/bills_pc
OaksPCText:       db "PROF.OAK's PC@"
;@ path: engine/pokemon/bills_pc
PKMNLeaguePCText: db "<PKMN>LEAGUE@"
;@ path: engine/pokemon/bills_pc
LogOffPCText:     db "LOG OFF@"

;@ path: engine/pokemon/bills_pc
;@ def BillsPC_()
;@ Turn on Bill's PC (the Pokémon storage system) and run its menu.
;@ test: skip runs the PC menus
BillsPC_::
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> wParentMenuItem = 0
	xor a
	ld [wParentMenuItem], a
;> wNameListType = MONSTER_NAME
	inc a               ; MONSTER_NAME
	ld [wNameListType], a
;> LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;> # wListScrollOffset is kept on the stack until ExitBillsPC
	ld a, [wListScrollOffset]
	push af
;> if not wMiscFlags >> BIT_USING_GENERIC_PC & 1:
	ld a, [wMiscFlags]
	bit BIT_USING_GENERIC_PC, a
	jr nz, BillsPCMenu
; accessing it directly
;>     PlaySound(SFX_TURN_ON_PC)
	ld a, SFX_TURN_ON_PC
	call PlaySound
;>     PrintText(SwitchOnText)
	ld hl, SwitchOnText
	call PrintText
;> BillsPCMenu()

;@ path: engine/pokemon/bills_pc
;@ def BillsPCMenu()
;@ WITHDRAW PKMN, DEPOSIT PKMN, RELEASE PKMN, CHANGE BOX or SEE YA!, with the current box number below.
;@ test: skip runs the PC menus
BillsPCMenu:
;> wCurrentMenuItem = wParentMenuItem
	ld a, [wParentMenuItem]
	ld [wCurrentMenuItem], a
;> CopyVideoData(vChars2 + 0x78 * 16, PokeballTileGraphics, BANK(PokeballTileGraphics), 1)
	ld hl, vChars2 + TILE_SIZE * $78
	ld de, PokeballTileGraphics
	ld bc, ((BANK(PokeballTileGraphics)) & $ff) << 8 + ((1) & $ff)
	call CopyVideoData
;> LoadScreenTilesFromBuffer2DisableBGTransfer()
	call LoadScreenTilesFromBuffer2DisableBGTransfer
;> TextBoxBorder(coord(0, 0), 10, 12)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 10
	ld c, 12
	call TextBoxBorder
;> PlaceString(BillsPCMenuText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, BillsPCMenuText
	call PlaceString
;> wTopMenuItemY = 2
	ld hl, wTopMenuItemY
	ld a, 2
	ld [hli], a ; wTopMenuItemY
;> wTopMenuItemX = 1
	dec a
	ld [hli], a ; wTopMenuItemX
	inc hl
	inc hl
;> wMaxMenuItem = 4
	ld a, 4
	ld [hli], a ; wMaxMenuItem
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [hli], a ; wMenuWatchedKeys
;> wLastMenuItem = 0
;> wPartyAndBillsPCSavedMenuItem = 0
	xor a
	ld [hli], a ; wLastMenuItem
	ld [hli], a ; wPartyAndBillsPCSavedMenuItem
;> wListScrollOffset = 0
	ld hl, wListScrollOffset
	ld [hli], a ; wListScrollOffset
;> wMenuWatchMovingOutOfBounds = 0
	ld [hl], a ; wMenuWatchMovingOutOfBounds
;> wPlayerMonNumber = 0
	ld [wPlayerMonNumber], a
;> PrintText(WhatText)
	ld hl, WhatText
	call PrintText
;> TextBoxBorder(coord(9, 14), 2, 9)             # for "BOX No."
	ld hl, (14) * SCREEN_WIDTH + (9) + wTileMap
	ld b, 2
	ld c, 9
	call TextBoxBorder
;> box = wCurrentBoxNum & BOX_NUM_MASK           # counted from 0
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
;> if box >= 9:                                  # boxes 10 to 12
	cp 9
	jr c, .singleDigitBoxNum
; two digit box num
;>     mem[coord(17, 16)] = charmap('1')[0]
;>     digit = charmap('0')[0] + box - 9
	sub 9
	ld hl, (16) * SCREEN_WIDTH + (17) + wTileMap
	ld [hl], '1'
	add '0'
	jr .next
.singleDigitBoxNum
;> else:
;>     digit = charmap('1')[0] + box
	add '1'
.next
;> mem[coord(18, 16)] = digit
	ld [(16) * SCREEN_WIDTH + (18) + wTileMap], a
;> PlaceString(BoxNoPCText, coord(10, 16))
	ld hl, (16) * SCREEN_WIDTH + (10) + wTileMap
	ld de, BoxNoPCText
	call PlaceString
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> keys = HandleMenuInput()
	call HandleMenuInput
;> if keys >> B_PAD_B & 1:
;>     return ExitBillsPC()
	bit B_PAD_B, a
	jp nz, ExitBillsPC
;> PlaceUnfilledArrowMenuCursor()
	call PlaceUnfilledArrowMenuCursor
;> choice = wCurrentMenuItem
;> wParentMenuItem = choice
	ld a, [wCurrentMenuItem]
	ld [wParentMenuItem], a
;> if choice == 0:
;>     return BillsPCWithdraw()
	and a
	jp z, BillsPCWithdraw ; withdraw
;> if choice == 1:
;>     return BillsPCDeposit()
	cp $1
	jp z, BillsPCDeposit ; deposit
;> if choice == 2:
;>     return BillsPCRelease()
	cp $2
	jp z, BillsPCRelease ; release
;> if choice == 3:
;>     return BillsPCChangeBox()
	cp $3
	jp z, BillsPCChangeBox ; change box
;> return ExitBillsPC()                          # SEE YA! (the code runs on into it)

;@ path: engine/pokemon/bills_pc
;@ def ExitBillsPC()
;@ SEE YA!: turn the PC off (with its sound, unless it was opened from another PC menu) and put the screen back.
;@ test: skip takes wListScrollOffset back off the stack
ExitBillsPC:
;> if not wMiscFlags >> BIT_USING_GENERIC_PC & 1:
	ld a, [wMiscFlags]
	bit BIT_USING_GENERIC_PC, a
	jr nz, .next
; accessing it directly
;>     LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;>     PlaySound(SFX_TURN_OFF_PC)
	ld a, SFX_TURN_OFF_PC
	call PlaySound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
.next
;> wMiscFlags = wMiscFlags & ~(1 << BIT_NO_MENU_BUTTON_SOUND) & 0xFF
	ld hl, wMiscFlags
	res BIT_NO_MENU_BUTTON_SOUND, [hl]
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> # wListScrollOffset comes back off the stack
	pop af
	ld [wListScrollOffset], a
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
	ret

;@ path: engine/pokemon/bills_pc
;@ def BillsPCDeposit()
;@ DEPOSIT PKMN: put a party Pokémon into the current box (never the last one, and not into a full box).
;@ test: skip runs the PC menus
BillsPCDeposit:
;> if wPartyCount == 1:                          # the last one has to stay
	ld a, [wPartyCount]
	dec a
	jr nz, .partyLargeEnough
;>     PrintText(CantDepositLastMonText)
;>     return BillsPCMenu()
	ld hl, CantDepositLastMonText
	call PrintText
	jp BillsPCMenu
.partyLargeEnough
;> if wBoxCount == MONS_PER_BOX:
	ld a, [wBoxCount]
	cp MONS_PER_BOX
	jr nz, .boxNotFull
;>     PrintText(BoxFullText)
;>     return BillsPCMenu()
	ld hl, BoxFullText
	call PrintText
	jp BillsPCMenu
.boxNotFull
;> if DisplayMonListMenu(addr(wPartyCount)):     # nothing chosen
;>     return BillsPCMenu()
	ld hl, wPartyCount
	call DisplayMonListMenu
	jp c, BillsPCMenu
;> if not DisplayDepositWithdrawMenu():
;>     return BillsPCMenu()
	call DisplayDepositWithdrawMenu
	jp nc, BillsPCMenu
;> PlaySoundWaitForCurrent(GetCryData(wCurPartySpecies))
	ld a, [wCurPartySpecies]
	call GetCryData
	call PlaySoundWaitForCurrent
;> wMoveMonType = PARTY_TO_BOX
;> MoveMon()
	ld a, PARTY_TO_BOX
	ld [wMoveMonType], a
	call MoveMon
;> wRemoveMonFromBox = 0
;> RemovePokemon()                               # out of the party
	xor a
	ld [wRemoveMonFromBox], a
	call RemovePokemon
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> at = addr(wBoxNumString)
;> box = wCurrentBoxNum & BOX_NUM_MASK
	ld hl, wBoxNumString
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
;> if box >= 9:
	cp 9
	jr c, .singleDigitBoxNum
;>     box -= 9
	sub 9
;>     mem[at] = charmap('1')[0]
;>     at += 1
	ld [hl], '1'
	inc hl
;>     digit = charmap('0')[0] + box
	add '0'
	jr .next
.singleDigitBoxNum
;> else:
;>     digit = charmap('1')[0] + box
	add '1'
.next
;> mem[at] = digit
;> mem[at + 1] = charmap('@')[0]
	ld [hli], a
	ld [hl], '@'
;> PrintText(MonWasStoredText)                   # "<mon> was stored in Box <n>."
;> return BillsPCMenu()
	ld hl, MonWasStoredText
	call PrintText
	jp BillsPCMenu

;@ path: engine/pokemon/bills_pc
;@ def BillsPCWithdraw()
;@ WITHDRAW PKMN: take a Pokémon from the current box into the party, if there is room.
;@ test: skip runs the PC menus
BillsPCWithdraw:
;> if wBoxCount == 0:
	ld a, [wBoxCount]
	and a
	jr nz, .boxNotEmpty
;>     PrintText(NoMonText)
	ld hl, NoMonText
	call PrintText
;>     return BillsPCMenu()
	jp BillsPCMenu
.boxNotEmpty
;> if wPartyCount == PARTY_LENGTH:
	ld a, [wPartyCount]
	cp PARTY_LENGTH
	jr nz, .partyNotFull
;>     PrintText(CantTakeMonText)
	ld hl, CantTakeMonText
	call PrintText
;>     return BillsPCMenu()
	jp BillsPCMenu
.partyNotFull
;> if DisplayMonListMenu(addr(wBoxCount)) or not DisplayDepositWithdrawMenu():
;>     return BillsPCMenu()
	ld hl, wBoxCount
	call DisplayMonListMenu
	jp c, BillsPCMenu
	call DisplayDepositWithdrawMenu
	jp nc, BillsPCMenu
;> GetPartyMonName(wWhichPokemon, addr(wBoxMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wBoxMonNicks
	call GetPartyMonName
;> PlaySoundWaitForCurrent(GetCryData(wCurPartySpecies))
	ld a, [wCurPartySpecies]
	call GetCryData
	call PlaySoundWaitForCurrent
;> wMoveMonType = BOX_TO_PARTY
	xor a ; BOX_TO_PARTY
	ld [wMoveMonType], a
;> MoveMon()
	call MoveMon
;> wRemoveMonFromBox = 1
	ld a, 1
	ld [wRemoveMonFromBox], a
;> RemovePokemon()
	call RemovePokemon
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PrintText(MonIsTakenOutText)
	ld hl, MonIsTakenOutText
	call PrintText
;> return BillsPCMenu()
	jp BillsPCMenu

;@ path: engine/pokemon/bills_pc
;@ def BillsPCRelease()
;@ RELEASE PKMN: let a Pokémon from the box go, after a "once released, gone forever" YES / NO.
;@ test: skip runs the PC menus
BillsPCRelease:
;> if wBoxCount == 0:
	ld a, [wBoxCount]
	and a
	jr nz, .loop
;>     PrintText(NoMonText)
;>     return BillsPCMenu()
	ld hl, NoMonText
	call PrintText
	jp BillsPCMenu
;> while True:
.loop
;>     cancelled = DisplayMonListMenu(addr(wBoxCount))
	ld hl, wBoxCount
	call DisplayMonListMenu
;>     if cancelled:
;>         return BillsPCMenu()
	jp c, BillsPCMenu
;>     PrintText(OnceReleasedText)
	ld hl, OnceReleasedText
	call PrintText
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem == 0:                 # YES
;>         break
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .loop
;> wRemoveMonFromBox = 1
	inc a
	ld [wRemoveMonFromBox], a
;> RemovePokemon()
;> WaitForSoundToFinish()
	call RemovePokemon
	call WaitForSoundToFinish
;> PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry
;> PrintText(MonWasReleasedText)
;> return BillsPCMenu()
	ld hl, MonWasReleasedText
	call PrintText
	jp BillsPCMenu

