;@ CHANGE BOX, then back to the PC menu.
;@ test: skip runs the PC menus
BillsPCChangeBox:
;> ChangeBox()
;> return BillsPCMenu()
	ld b, BANK(ChangeBox)
	ld hl, ChangeBox
	call Bankswitch
	jp BillsPCMenu

;@ path: engine/pokemon/bills_pc
;@ def DisplayMonListMenu(list: hl) -> carry
;@ Let the player pick a Pokémon from the species list at `list` (party or box). Carry if they cancelled.
;@ test: skip runs a list menu
DisplayMonListMenu:
;> wListPointer[0] = list & 0xFF
	ld a, l
	ld [wListPointer], a
;> wListPointer[1] = list >> 8
	ld a, h
	ld [wListPointer + 1], a
;> wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;> wListMenuID = 0
	ld [wListMenuID], a
;> wNameListType = MONSTER_NAME
	inc a                ; MONSTER_NAME
	ld [wNameListType], a
;> wCurrentMenuItem = wPartyAndBillsPCSavedMenuItem
	ld a, [wPartyAndBillsPCSavedMenuItem]
	ld [wCurrentMenuItem], a
;> cancelled = DisplayListMenuID()
	call DisplayListMenuID
;> wPartyAndBillsPCSavedMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wPartyAndBillsPCSavedMenuItem], a
;> return cancelled
	ret

