BoxNoPCText:
	db "BOX No.@"

;@ path: engine/pokemon/bills_pc
;@ def KnowsHMMove() -> carry
;@ Whether party Pokémon wWhichPokemon knows an HM move.
;@ test: wWhichPokemon = rand(0, 5)
KnowsHMMove::
; returns whether mon with party index [wWhichPokemon] knows an HM move
;> moves, size = addr(wPartyMon1Moves), PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	jr .next
; unreachable
;> if False:                                     # never reached: the same for a box Pokémon
;>     moves, size = addr(wBoxMon1Moves), BOXMON_STRUCT_LENGTH
	ld hl, wBoxMon1Moves
	ld bc, BOXMON_STRUCT_LENGTH
.next
;> moves += wWhichPokemon * size
	ld a, [wWhichPokemon]
	call AddNTimes
;> for i in range(NUM_MOVES):
	ld b, NUM_MOVES
.loop
;>     hm = IsInArray(mem[moves + i], HMMoveArray, 1)[2]
	ld a, [hli]
	push hl
	push bc
	ld hl, HMMoveArray
	ld de, 1
	call IsInArray
;>     if hm:
	pop bc
	pop hl
;>         return True
	ret c
;> return False
	dec b
	jr nz, .loop
	and a
	ret

;@ path: engine/pokemon/bills_pc
HMMoveArray:
; This file is INCLUDEd twice:
; - for HMMoves in home/names.asm
; - for HMMoveArray in engine/pokemon/bills_pc.asm

	db CUT
	db FLY
	db SURF
	db STRENGTH
	db FLASH
	db -1 ; end

;@ path: engine/pokemon/bills_pc
;@ def DisplayDepositWithdrawMenu() -> carry
;@ DEPOSIT (or WITHDRAW), STATS, CANCEL for the chosen Pokémon: carry if the first was chosen. STATS shows the
;@ two summary pages and comes back to this menu.
;@ test: skip runs a menu
DisplayDepositWithdrawMenu:
;> TextBoxBorder(coord(9, 10), 6, 9)
	ld hl, (10) * SCREEN_WIDTH + (9) + wTileMap
	ld b, 6
	ld c, 9
	call TextBoxBorder
;> if wParentMenuItem:                           # chosen in the menu before: DEPOSIT or WITHDRAW
;>     label = DepositPCText
	ld a, [wParentMenuItem]
	and a ; was the Deposit or Withdraw item selected in the parent menu?
	ld de, DepositPCText
	jr nz, .next
;> else:
;>     label = WithdrawPCText
	ld de, WithdrawPCText
.next
;> PlaceString(label, coord(11, 12))
	ld hl, (12) * SCREEN_WIDTH + (11) + wTileMap
	call PlaceString
;> PlaceString(StatsCancelPCText, coord(11, 14))
	ld hl, (14) * SCREEN_WIDTH + (11) + wTileMap
	ld de, StatsCancelPCText
	call PlaceString
;> wTopMenuItemY = 12
	ld hl, wTopMenuItemY
	ld a, 12
	ld [hli], a ; wTopMenuItemY
;> wTopMenuItemX = 10
	ld a, 10
	ld [hli], a ; wTopMenuItemX
;> wCurrentMenuItem = 0
	xor a
	ld [hli], a ; wCurrentMenuItem
	inc hl
;> wMaxMenuItem = 2
	ld a, 2
	ld [hli], a ; wMaxMenuItem
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [hli], a ; wMenuWatchedKeys
;> wLastMenuItem = 0
	xor a
	ld [hl], a ; wLastMenuItem
;> wListScrollOffset = 0
;> wMenuWatchMovingOutOfBounds = 0
	ld hl, wListScrollOffset
	ld [hli], a ; wListScrollOffset
	ld [hl], a ; wMenuWatchMovingOutOfBounds
;> wPlayerMonNumber = 0
;> wPartyAndBillsPCSavedMenuItem = 0
	ld [wPlayerMonNumber], a
	ld [wPartyAndBillsPCSavedMenuItem], a
;> while True:
.loop
;>     keys = HandleMenuInput()
	call HandleMenuInput
;>     if keys >> B_PAD_B & 1:
;>         return False
	bit B_PAD_B, a
	jr nz, .exit
;>     if wCurrentMenuItem == 0:                 # DEPOSIT / WITHDRAW
	ld a, [wCurrentMenuItem]
	and a
	jr z, .choseDepositWithdraw
;>@chose         return True
;>     if wCurrentMenuItem != 1:                 # CANCEL
	dec a
	jr z, .viewStats
.exit
;>         return False
	and a
	ret
.choseDepositWithdraw
;=@chose
	scf
	ret
.viewStats
;>     # STATS: both summary pages, then this menu again
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     wMonDataLocation = PLAYER_PARTY_DATA if wParentMenuItem else BOX_DATA
	ld a, [wParentMenuItem]
	and a
	ld a, PLAYER_PARTY_DATA
	jr nz, .next2
	ld a, BOX_DATA
.next2
	ld [wMonDataLocation], a
;>     StatusScreen()
	ld a, (StatusScreenPredef - PredefPointers) / 3
	call Predef
;>     StatusScreen2()
	ld a, (StatusScreen2Predef - PredefPointers) / 3
	call Predef
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     ReloadTilesetTilePatterns()
	call ReloadTilesetTilePatterns
;>     RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>     LoadGBPal()
	call LoadGBPal
	jr .loop

