SECTION "Battle Engine 3", ROMX

; [wCurSpecies] = pokemon ID
; hl = dest addr
;@ path: engine/battle/print_type
;@ def PrintMonType()
;@ Print a species' types at the screen position the predef call saved: TYPE1 on its line, TYPE2 two lines
;@ lower, or the "TYPE2/" label erased if the species has a single type.
PrintMonType:
;> dest, _, _ = GetPredefRegisters()
	call GetPredefRegisters
;> GetMonHeader()
	push hl
	call GetMonHeader
	pop hl
;> PrintType(wMonHType1, dest)
	push hl
	ld a, [wMonHType1]
	call PrintType
;> if wMonHType2 == wMonHType1:
;>     return EraseType2Text(dest)
	ld a, [wMonHType1]
	ld b, a
	ld a, [wMonHType2]
	cp b
	pop hl
	jr z, EraseType2Text
;> return PrintType(wMonHType2, dest + SCREEN_WIDTH * 2)
	ld bc, SCREEN_WIDTH * 2
	add hl, bc

; a = type
; hl = dest addr
;@ path: engine/battle/print_type
;@ def PrintType(type: a, dest: hl)
;@ Print the name of a type ("WATER") at dest.
PrintType:
;> return PrintType_(type, dest)
	push hl
	jr PrintType_

; erase "TYPE2/" if the mon only has 1 type
;@ path: engine/battle/print_type
;@ def EraseType2Text(dest: hl) -> hl
;@ Blank out the six characters of the "TYPE2/" label on the line below dest.
;@ test: dest = rand_ram(40)
EraseType2Text:
;> return FillMemory(dest + SCREEN_WIDTH - 1, 6, 0x7F)
	ld a, ' '
	ld bc, SCREEN_WIDTH - 1
	add hl, bc
	ld bc, CHARLEN("TYPE2/")
	jp FillMemory

;@ path: engine/battle/print_type
;@ def PrintMoveType()
;@ Print the type of the player's selected move at the screen position the predef call saved.
PrintMoveType:
;> dest, _, _ = GetPredefRegisters()
;> return PrintType_(wPlayerMoveType, dest)
	call GetPredefRegisters
	push hl
	ld a, [wPlayerMoveType]
; fall through

;@ path: engine/battle/print_type
;@ def PrintType_(type: a, dest: hl)
;@ Print the name of a type from TypeNames. Its callers push the screen position on the stack, so dest arrives
;@ there rather than in hl.
;@ test: skip takes the screen position from the stack
PrintType_:
;> entry = TypeNames + type * 2
	add a
	ld hl, TypeNames
	ld e, a
	ld d, $0
	add hl, de
;> name = mem16[entry]
	ld a, [hli]
	ld e, a
	ld d, [hl]
;> PlaceString(name, dest)                         # dest comes from the stack
	pop hl
	jp PlaceString

