;@ path: engine/battle/save_trainer_name
;@ def SaveTrainerName()
;@ Copy the name of the current trainer class into wNameBuffer, from TrainerNamePointers.
;@ test: wTrainerClass = rand(1, 47)
SaveTrainerName::
;> table = TrainerNamePointers
	ld hl, TrainerNamePointers
;> index = wTrainerClass - 1 & 0xFF
	ld a, [wTrainerClass]
	dec a
;> entry = table + 2 * index
	ld c, a
	ld b, 0
	add hl, bc
	add hl, bc
;> src = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> dest = wNameBuffer
;> while True:
	ld de, wNameBuffer
.CopyCharacter
;>     c = mem[src]
;>     src += 1
	ld a, [hli]
;>     mem[dest] = c
	ld [de], a
;>     dest += 1
	inc de
;>     if c == 0x50:
;>         return
	cp '@'
	jr nz, .CopyCharacter
	ret

