;@ path: engine/battle/move_effects/focus_energy
;@ def FocusEnergyEffect_()
;@ Focus Energy: the user gets pumped (in this game that lowers its critical hit rate) unless it already is.
FocusEnergyEffect_:
;> status = addr(wPlayerBattleStatus2) if hWhoseTurn == 0 else addr(wEnemyBattleStatus2)
	ld hl, wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	jr z, .notEnemy
	ld hl, wEnemyBattleStatus2
.notEnemy
;> if mem[status] >> GETTING_PUMPED & 1:
;>@wait     DelayFrames(50)
;>@fail     return PrintButItFailedText_()
	bit GETTING_PUMPED, [hl] ; is mon already using focus energy?
	jr nz, .alreadyUsing
;> mem[status] |= 1 << GETTING_PUMPED
	set GETTING_PUMPED, [hl] ; mon is now using focus energy
;> PlayCurrentMoveAnimation()
	ld hl, PlayCurrentMoveAnimation
	ld b, BANK(PlayCurrentMoveAnimation)
	call Bankswitch
;> PrintText(GettingPumpedText)
	ld hl, GettingPumpedText
	jp PrintText
.alreadyUsing
;=@wait
	ld c, 50
	call DelayFrames
;=@fail
	ld hl, PrintButItFailedText_
	ld b, BANK(PrintButItFailedText_)
	jp Bankswitch

;@ path: engine/battle/move_effects/focus_energy
GettingPumpedText:
	db TX_PAUSE
	db TX_FAR
	dw _GettingPumpedText
	db BANK(_GettingPumpedText)
	db TX_END


SECTION "Battle Engine 4", ROMX

;@ path: engine/battle/move_effects/leech_seed
;@ def LeechSeedEffect_()
;@ Leech Seed: seeds the target unless the move misses, the target is Grass-type or already seeded.
LeechSeedEffect_:
;> MoveHitTest()
	ld hl, MoveHitTest
	ld b, BANK(MoveHitTest)
	call Bankswitch
;> if wMoveMissed:
;>@wait     DelayFrames(50)
;>@miss     return PrintText(EvadedAttackText)
	ld a, [wMoveMissed]
	and a
	jr nz, .moveMissed
;> if hWhoseTurn == 0:
;>     status, types = addr(wEnemyBattleStatus2), wEnemyMonType1
	ld hl, wEnemyBattleStatus2
	ld de, wEnemyMonType1
	ldh a, [hWhoseTurn]
	and a
	jr z, .leechSeedEffect
;> else:
;>     status, types = addr(wPlayerBattleStatus2), wBattleMonType1
	ld hl, wPlayerBattleStatus2
	ld de, wBattleMonType1
.leechSeedEffect
; miss if the target is grass-type or already seeded
;> if mem[types] == GRASS:                          # Grass types can't be seeded (same failure as above)
;>     return PrintText(EvadedAttackText)
	ld a, [de]
	cp GRASS
	jr z, .moveMissed
;> if mem[types + 1] == GRASS:
;>     return PrintText(EvadedAttackText)
	inc de
	ld a, [de]
	cp GRASS
	jr z, .moveMissed
;> if mem[status] >> SEEDED & 1:                    # already seeded
;>     return PrintText(EvadedAttackText)
	bit SEEDED, [hl]
	jr nz, .moveMissed
;> mem[status] |= 1 << SEEDED
	set SEEDED, [hl]
;> PlayCurrentMoveAnimation()
	ld hl, PlayCurrentMoveAnimation
	ld b, BANK(PlayCurrentMoveAnimation)
	call Bankswitch
;> PrintText(WasSeededText)
	ld hl, WasSeededText
	jp PrintText
.moveMissed
;=@wait
	ld c, 50
	call DelayFrames
;=@miss
	ld hl, EvadedAttackText
	jp PrintText

;@ path: engine/battle/move_effects/leech_seed
WasSeededText:
	db TX_FAR
	dw _WasSeededText
	db BANK(_WasSeededText)
	db TX_END

;@ path: engine/battle/move_effects/leech_seed
EvadedAttackText:
	db TX_FAR
	dw _EvadedAttackText
	db BANK(_EvadedAttackText)
	db TX_END


SECTION "Battle Engine 5", ROMX

;@ path: engine/battle/display_effectiveness
;@ def DisplayEffectiveness()
;@ "It's super effective!" or "It's not very effective..." after a hit; nothing for normal damage.
DisplayEffectiveness:
;> m = wDamageMultipliers & 0x7F                    # (without the STAB bit)
	ld a, [wDamageMultipliers]
	and $7F
;> if m == EFFECTIVE:
