; checks if the mon in [wWhichPokemon] already knows the move in [wMoveNum]
;@ def CheckIfMoveIsKnown() -> carry
;@ Before teaching a TM: carry (after "already knows") if party Pokémon wWhichPokemon knows move wMoveNum already.
;@ test: wWhichPokemon = rand(0, 5)
;@ path: engine/items/tmhm
CheckIfMoveIsKnown:
;> moves = AddNTimes(wPartyMon1Moves, PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld a, [wWhichPokemon]
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> move = wMoveNum
	ld a, [wMoveNum]
	ld b, a
;>@lp for _ in range(NUM_MOVES):
	ld c, NUM_MOVES
.loop
;>     here = mem[moves]
;>     moves += 1
	ld a, [hli]
;>     if here == move:
;>@ak1         PrintText(AlreadyKnowsText)
;>@ak2         return True
	cp b
	jr z, .alreadyKnown ; found a match
;=@lp
	dec c
	jr nz, .loop
;> return False
	and a
	ret
.alreadyKnown
;=@ak1
	ld hl, AlreadyKnowsText
	call PrintText
;=@ak2
	scf
	ret

;@ path: engine/items/tmhm
AlreadyKnowsText:
	db TX_FAR
	dw _AlreadyKnowsText
	db BANK(_AlreadyKnowsText)
	db TX_END
; scales both uncompressed sprite chunks by two in every dimension (creating 2x2 output pixels per input pixel)
; assumes that input sprite chunks are 4x4 tiles, and the rightmost and bottommost 4 pixels will be ignored
; resulting in a 7*7 tile output sprite chunk
;@ path: engine/battle/scale_sprites
;@ def ScaleSpriteByTwo() -> (de, hl)
;@ Blow a 4 x 4 tile Pokémon picture up to 7 x 7 tiles by doubling every pixel: the back pictures the battle
;@ shows. Both bitplanes, in sSpriteBuffer1 and sSpriteBuffer2, are scaled into sSpriteBuffer0 and sSpriteBuffer1,
;@ working backwards from the end.
ScaleSpriteByTwo:
;> de, hl = ScaleLastSpriteColumnByTwo(sSpriteBuffer1 + 4 * 4 * 8 - 5, sSpriteBuffer0 + SPRITEBUFFERSIZE - 1)
	ld de, sSpriteBuffer1 + (4*4*8) - 5          ; last byte of input data, last 4 rows already skipped
	ld hl, sSpriteBuffer0 + SPRITEBUFFERSIZE - 1 ; end of destination buffer
	call ScaleLastSpriteColumnByTwo              ; last tile column is special case
;> de, hl = ScaleFirstThreeSpriteColumnsByTwo(de, hl)
	call ScaleFirstThreeSpriteColumnsByTwo       ; scale first 3 tile columns
;> de, hl = ScaleLastSpriteColumnByTwo(sSpriteBuffer2 + 4 * 4 * 8 - 5, sSpriteBuffer1 + SPRITEBUFFERSIZE - 1)
	ld de, sSpriteBuffer2 + (4*4*8) - 5          ; last byte of input data, last 4 rows already skipped
	ld hl, sSpriteBuffer1 + SPRITEBUFFERSIZE - 1 ; end of destination buffer
	call ScaleLastSpriteColumnByTwo              ; last tile column is special case
;> return ScaleFirstThreeSpriteColumnsByTwo(de, hl)  # (falls through)

;@ path: engine/battle/scale_sprites
;@ def ScaleFirstThreeSpriteColumnsByTwo(src: de, dest: hl) -> (de, hl)
;@ Scale the first three tile columns of one bitplane (each source byte holds two pixel columns, one per nybble).
;@ test: src = rand(0xC200, 0xCF00); dest = rand(0xC200, 0xCF00)
ScaleFirstThreeSpriteColumnsByTwo:
;> for column in range(3):
	ld b, $3 ; 3 tile columns
.columnLoop
;>@row     for row in range(4 * 8 - 4):
	ld c, 4*8 - 4 ; $1c, 4 tiles minus 4 unused rows
.columnInnerLoop
;>         dest = ScalePixelsByTwo(mem[src], dest, u16(-7 * 8 + 1))
	push bc
	ld a, [de]
	ld bc, -(7*8)+1       ; -$37, scale lower nybble and seek to previous output column
	call ScalePixelsByTwo
;>         pixels = mem[src] >> 4
;>         src -= 1
	ld a, [de]
	dec de
	swap a
;>         dest = ScalePixelsByTwo(pixels, dest, 7 * 8 + 1 - 2)   # then on to the next 2 rows
	ld bc, 7*8+1-2        ; $37, scale upper nybble and seek back to current output column and to the next 2 rows
	call ScalePixelsByTwo
;=@row
	pop bc
	dec c
	jr nz, .columnInnerLoop
;>     src -= 4
	dec de
	dec de
	dec de
	dec de
;>     dest = u16(dest - 7 * 8)
	ld a, b
	ld bc, -7*8 ; -$38, skip one output column (which has already been written along with the current one)
	add hl, bc
	ld b, a
	dec b
	jr nz, .columnLoop
;> return (src, dest)
	ret

;@ path: engine/battle/scale_sprites
;@ def ScaleLastSpriteColumnByTwo(src: de, dest: hl) -> (de, hl)
;@ Scale the last tile column of one bitplane: only the high nybbles hold pixels there.
;@ test: src = rand(0xC100, 0xCF00); dest = rand(0xC100, 0xCF00)
ScaleLastSpriteColumnByTwo:
;> hSpriteInterlaceCounter = 4 * 8 - 4      # 4 tiles minus the 4 unused rows
	ld a, 4*8 - 4 ; $1c, 4 tiles minus 4 unused rows
	ldh [hSpriteInterlaceCounter], a
;> step = 0xFFFF                                    # one byte back
;> while True:
	ld bc, -1
.columnInnerLoop
;>     pixels = mem[src] >> 4                       # only the high nybble holds pixels
;>     src -= 1
	ld a, [de]
	dec de
	swap a                    ; only high nybble contains information
;>     dest = ScalePixelsByTwo(pixels, dest, step)
	call ScalePixelsByTwo
;>     hSpriteInterlaceCounter -= 1
	ldh a, [hSpriteInterlaceCounter]
	dec a
	ldh [hSpriteInterlaceCounter], a
;>     if hSpriteInterlaceCounter == 0:
;>         break
	jr nz, .columnInnerLoop
;> return (src - 4, dest)                   # skip the last 4 rows of the new column
	dec de                    ; skip last 4 rows of new column
	dec de
	dec de
	dec de
	ret

; scales the given 4 bits in a (4x1 pixels) to 2 output bytes (8x2 pixels)
; hl: destination pointer
; bc: destination pointer offset (added after the two bytes have been written)
;@ path: engine/battle/scale_sprites
;@ def ScalePixelsByTwo(pixels: a, dest: hl, step: bc) -> hl
;@ Double four pixels sideways (DuplicateBitsTable) and write the byte twice, for two rows; then move dest by step.
;@ test: dest = rand_ram(4) + 2
ScalePixelsByTwo:
;> pixels &= 0xF
	push hl
	and $f
;> entry = DuplicateBitsTable + pixels              # every bit twice
	ld hl, DuplicateBitsTable
	add l
	ld l, a
	jr nc, .noCarry
	inc h
.noCarry
;> b = mem[entry]
	ld a, [hl]
;> mem[dest] = b                            # two rows high
;> mem[dest - 1] = b
	pop hl
	ld [hld], a  ; write output byte twice to make it 2 pixels high
	ld [hl], a
;> return u16(dest - 1 + step)
	add hl, bc   ; add offset
	ret

; repeats each input bit twice, e.g. DuplicateBitsTable[%0101] = %00110011
;@ path: engine/battle/scale_sprites
DuplicateBitsTable:
	db ($0 & 1) * 3 + ($0 & 2) * 6 + ($0 & 4) * 12 + ($0 & 8) * 24
	db ($1 & 1) * 3 + ($1 & 2) * 6 + ($1 & 4) * 12 + ($1 & 8) * 24
	db ($2 & 1) * 3 + ($2 & 2) * 6 + ($2 & 4) * 12 + ($2 & 8) * 24
	db ($3 & 1) * 3 + ($3 & 2) * 6 + ($3 & 4) * 12 + ($3 & 8) * 24
	db ($4 & 1) * 3 + ($4 & 2) * 6 + ($4 & 4) * 12 + ($4 & 8) * 24
	db ($5 & 1) * 3 + ($5 & 2) * 6 + ($5 & 4) * 12 + ($5 & 8) * 24
	db ($6 & 1) * 3 + ($6 & 2) * 6 + ($6 & 4) * 12 + ($6 & 8) * 24
	db ($7 & 1) * 3 + ($7 & 2) * 6 + ($7 & 4) * 12 + ($7 & 8) * 24
	db ($8 & 1) * 3 + ($8 & 2) * 6 + ($8 & 4) * 12 + ($8 & 8) * 24
	db ($9 & 1) * 3 + ($9 & 2) * 6 + ($9 & 4) * 12 + ($9 & 8) * 24
	db ($A & 1) * 3 + ($A & 2) * 6 + ($A & 4) * 12 + ($A & 8) * 24
	db ($B & 1) * 3 + ($B & 2) * 6 + ($B & 4) * 12 + ($B & 8) * 24
	db ($C & 1) * 3 + ($C & 2) * 6 + ($C & 4) * 12 + ($C & 8) * 24
	db ($D & 1) * 3 + ($D & 2) * 6 + ($D & 4) * 12 + ($D & 8) * 24
	db ($E & 1) * 3 + ($E & 2) * 6 + ($E & 4) * 12 + ($E & 8) * 24
	db ($F & 1) * 3 + ($F & 2) * 6 + ($F & 4) * 12 + ($F & 8) * 24
;@ path: engine/battle/move_effects/pay_day
;@ def PayDayEffect_()
;@ Pay Day: coins worth twice the attacker's level scatter; the amount, as BCD, adds to the money picked up after
;@ the battle (wTotalPayDayMoney).
PayDayEffect_:
;> mem[wPayDayMoney] = 0
	xor a
	ld hl, wPayDayMoney
	ld [hli], a
;> level = wBattleMonLevel if hWhoseTurn == 0 else wEnemyMonLevel
	ldh a, [hWhoseTurn]
	and a
	ld a, [wBattleMonLevel]
	jr z, .payDayEffect
	ld a, [wEnemyMonLevel]
.payDayEffect
;> amount = level * 2 & 0xFF
;> hDividend[0:4] = [0, 0, 0, amount]
; level * 2
	add a
	ldh [hDividend + 3], a
	xor a
	ldh [hDividend], a
	ldh [hDividend + 1], a
	ldh [hDividend + 2], a
; convert to BCD
;> hDivisor = 100                                   # to BCD: the hundreds
	ld a, 100
	ldh [hDivisor], a
;> Divide(4)
	ld b, $4
	call Divide
;> mem[wPayDayMoney + 1] = amount // 100
	ldh a, [hQuotient + 3]
	ld [hli], a ; wPayDayMoney + 1
;> hDividend[3] = amount % 100
	ldh a, [hRemainder]
	ldh [hDividend + 3], a
;> hDivisor = 10                                    # then tens and ones
	ld a, 10
	ldh [hDivisor], a
;> Divide(4)
	ld b, $4
	call Divide
;> mem[wPayDayMoney + 2] = amount // 10 % 10 << 4 | amount % 10
	ldh a, [hQuotient + 3]
	swap a
	ld b, a
	ldh a, [hRemainder]
	add b
	ld [hl], a ; wPayDayMoney + 2
;> predef(AddBCDPredef, hl=wPayDayMoney + 2, de=wTotalPayDayMoney + 2, bc=3)
	ld de, wTotalPayDayMoney + 2
	ld c, $3
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;> PrintText(CoinsScatteredText)
	ld hl, CoinsScatteredText
	jp PrintText

;@ path: engine/battle/move_effects/pay_day
CoinsScatteredText:
	db TX_FAR
	dw _CoinsScatteredText
	db BANK(_CoinsScatteredText)
	db TX_END
;@ path: engine/slots/game_corner_slots2
;@ def AbleToPlaySlotsCheck()
;@ Facing a slot machine (up): wCanPlaySlots is nonzero if the player has the Coin Case and coins; otherwise
;@ say which is missing and set it to 0.
;@ test: skip reads the item count from a predef's register
AbleToPlaySlotsCheck:
;> if not mem[wSpritePlayerStateData1ImageIndex] & 8:     # not facing a machine
;>@no     wCanPlaySlots = 0
;>@noret     return
	ld a, [wSpritePlayerStateData1ImageIndex]
	and $8
	jr z, .done ; not able
;> count = GetQuantityOfItemInBag()                  # through the predef table, for COIN_CASE
	ld b, COIN_CASE
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
;> if count:
	ld a, b
	and a
	ld b, (GameCornerCoinCaseText_id - TextPredefs) / 2 + 1
	jr z, .printCoinCaseRequired
;>     if wPlayerCoins[0] | wPlayerCoins[1]:
;>@able         wCanPlaySlots = wPlayerCoins[0] | wPlayerCoins[1]
;>@ableret         return
	ld hl, wPlayerCoins
	ld a, [hli]
	or [hl]
	jr nz, .done ; able to play
;>     text = (GameCornerNoCoinsText_id - TextPredefs) // 2 + 1
;> else:
;>     text = (GameCornerCoinCaseText_id - TextPredefs) // 2 + 1
	ld b, (GameCornerNoCoinsText_id - TextPredefs) / 2 + 1
.printCoinCaseRequired
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> PrintPredefTextID(text)
	ld a, b
	call PrintPredefTextID
;> wCanPlaySlots = 0
	xor a
.done
	ld [wCanPlaySlots], a
	ret

;@ path: engine/slots/game_corner_slots2
GameCornerCoinCaseText::
	db TX_FAR
	dw _GameCornerCoinCaseText
	db BANK(_GameCornerCoinCaseText)
	db TX_END

;@ path: engine/slots/game_corner_slots2
GameCornerNoCoinsText::
	db TX_FAR
	dw _GameCornerNoCoinsText
	db BANK(_GameCornerNoCoinsText)
	db TX_END


SECTION "Battle Engine 6", ROMX

;@ path: engine/battle/move_effects/mist
;@ def MistEffect_()
;@ Mist: protects the user's stats from being lowered, unless it is already shrouded.
MistEffect_:
;> status = addr(wPlayerBattleStatus2) if hWhoseTurn == 0 else addr(wEnemyBattleStatus2)
	ld hl, wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	jr z, .mistEffect
	ld hl, wEnemyBattleStatus2
.mistEffect
;> if mem[status] >> PROTECTED_BY_MIST & 1:
	bit PROTECTED_BY_MIST, [hl] ; is mon protected by mist?
	jr nz, .mistAlreadyInUse
;>     return PrintButItFailedText_()
;> mem[status] |= 1 << PROTECTED_BY_MIST
	set PROTECTED_BY_MIST, [hl] ; mon is now protected by mist
;> PlayCurrentMoveAnimation()
	ld hl, PlayCurrentMoveAnimation
	ld b, BANK(PlayCurrentMoveAnimation)
	call Bankswitch
;> PrintText(ShroudedInMistText)
	ld hl, ShroudedInMistText
	jp PrintText
.mistAlreadyInUse
	ld hl, PrintButItFailedText_
	ld b, BANK(PrintButItFailedText_)
	jp Bankswitch

;@ path: engine/battle/move_effects/mist
ShroudedInMistText:
	db TX_FAR
	dw _ShroudedInMistText
	db BANK(_ShroudedInMistText)
	db TX_END
;@ path: engine/battle/move_effects/one_hit_ko
;@ def OneHitKOEffect_()
;@ Fissure, Guillotine and Horn Drill: they knock out the target only if the user is at least as fast; otherwise
;@ they miss.
OneHitKOEffect_:
;> mem[wDamage], mem[wDamage + 1] = 0, 0
	ld hl, wDamage
	xor a
	ld [hli], a
	ld [hl], a ; set the damage output to zero
;> wCriticalHitOrOHKO = 0xFF
	dec a
	ld [wCriticalHitOrOHKO], a
;> if hWhoseTurn == 0:
;>     user, target = wBattleMonSpeed, wEnemyMonSpeed
	ld hl, wBattleMonSpeed + 1
	ld de, wEnemyMonSpeed + 1
	ldh a, [hWhoseTurn]
	and a
	jr z, .compareSpeed
;> else:
;>     user, target = wEnemyMonSpeed, wBattleMonSpeed
	ld hl, wEnemyMonSpeed + 1
	ld de, wBattleMonSpeed + 1
.compareSpeed
; set damage to 65535 and OHKO flag if the user's current speed is higher than the target's
;> low = mem[user + 1] - mem[target + 1]            # the user's speed minus the target's
	ld a, [de]
	dec de
	ld b, a
	ld a, [hld]
	sub b
;> high = mem[user] - mem[target] - (low < 0)
	ld a, [de]
	ld b, a
	ld a, [hl]
	sbc b
;> if high >= 0:                                    # the user is at least as fast: a knock-out
	jr c, .userIsSlower
;>     mem[wDamage], mem[wDamage + 1] = 0xFF, 0xFF
	ld hl, wDamage
	ld a, $ff
	ld [hli], a
	ld [hl], a
;>     wCriticalHitOrOHKO = 2
	ld a, $2
	ld [wCriticalHitOrOHKO], a
;>     return
	ret
.userIsSlower
;> wMoveMissed = 1
; keep damage at 0 and set move missed flag if target's current speed is higher instead
	ld a, $1
	ld [wMoveMissed], a
	ret


