;@ path: engine/movie/title2
;@ def TitleScroll(direction: d)
;@ Scroll the title Pokémon's band of the screen: with `direction` set by the TitleScroll_In steps from X $88,
;@ otherwise by the TitleScroll_Out steps from 0.
;@ test: skip waits for screen lines
TitleScroll:
;> steps, scx, ball = TitleScroll_In, 0x88, 0
	ld a, d

	ld bc, TitleScroll_In
	ld d, $88
	ld e, 0 ; don't animate titleball

;> if direction:
;>     return _TitleScroll(steps, scx, ball)
	and a
	jr nz, _TitleScroll

;> return _TitleScroll(TitleScroll_Out, 0, 0)  # the code runs on into it
	ld bc, TitleScroll_Out
	ld d, $00
	ld e, 0 ; don't animate titleball
	; fallthrough

;@ path: engine/movie/title2
;@ def _TitleScroll(steps: bc, scx: d, ball: e)
;@ Scroll the band between screen lines $48 and $88 by a list of steps (high nybble: pixels per frame, low
;@ nybble: frames; 0 ends), the rest of the screen staying put. With `ball` set, the Poké Ball in the player's
;@ hand hops along TitleBallYTable meanwhile.
;@ test: skip waits for screen lines
_TitleScroll:
;> while mem[steps]:
	ld a, [bc]
	and a
	ret z

;>     step = mem[steps]
;>     steps += 1
	inc bc
	push bc

;>     frames = step & 0xF
	ld b, a
	and $f
	ld c, a
;>     speed = step >> 4
	ld a, b
	and $f0
	swap a
	ld b, a

;>     for _ in range(frames):
.loop
;>@wait1         wait_ly(0x48)                        # the band starts
	ld h, d
	ld l, $48
	call .ScrollBetween
;>@scx1         rSCX = scx
;>@line1         while rLY == scx:
;>             wait_ly()    # the LCD moves rLY on

;>         wait_ly(0x88)                        # and ends
	ld h, $00
	ld l, $88
	call .ScrollBetween
;>@scx2         rSCX = 0
;>@line2         while rLY == 0:
;>@line2b             wait_ly()    # the LCD moves rLY on

;>         scx = u8(scx + speed)
	ld a, d
	add b
	ld d, a

;>         ball = GetTitleBallY(ball)
	call GetTitleBallY
	dec c
	jr nz, .loop

	pop bc
	jr _TitleScroll

.ScrollBetween:
;> # .ScrollBetween: wait for screen line l, set rSCX to h, wait until the line has passed
.wait
;=@wait1
	ldh a, [rLY] ; rLY
	cp l
	jr nz, .wait

;=@scx1
	ld a, h
	ldh [rSCX], a

.wait2
;=@line1
	ldh a, [rLY] ; rLY
	cp h
	jr z, .wait2
	ret

;@ path: engine/movie/title2
TitleBallYTable:
; OBJ y-positions for the Poke Ball held by Red in the title screen.
; This is really two 0-terminated lists. Initiated with an index of 1.
	db 0, $71, $6f, $6e, $6d, $6c, $6d, $6e, $6f, $71, $74, 0

;@ path: engine/movie/title2
;@ def TitleScreenAnimateBallIfStarterOut()
;@ After a starter Pokémon scrolled out: a pause while the Poké Ball in the player's hand hops.
;@ test: skip waits for screen lines
TitleScreenAnimateBallIfStarterOut:
; Animate the TitleBall if a starter just got scrolled out.
;> species = wTitleMonSpecies
	ld a, [wTitleMonSpecies]
;> if species in (STARTER1, STARTER2, STARTER3):  # a starter just scrolled out
	cp STARTER1
	jr z, .ok
	cp STARTER2
	jr z, .ok
	cp STARTER3
	ret nz
.ok
;>     _TitleScroll(TitleScroll_WaitBall, 0, 1)
	ld e, 1 ; animate titleball
	ld bc, TitleScroll_WaitBall
	ld d, 0
	jp _TitleScroll

;@ path: engine/movie/title2
;@ def GetTitleBallY(position: e) -> e
;@ Move the title screen's Poké Ball to Y TitleBallYTable[position] and return the next position; at the
;@ table's 0 it stays.
;@ test: position = rand(0, 12)
GetTitleBallY:
; Get position e from TitleBallYTable
;> at = TitleBallYTable + position
	push de
	push hl
	xor a
	ld d, a
	ld hl, TitleBallYTable
	add hl, de
;> y = mem[at]
	ld a, [hl]
	pop hl
	pop de
;> if y == 0:
;>     return position
	and a
	ret z
;> mem[addr(wShadowOAMSprite10YCoord)] = y
	ld [wShadowOAMSprite10YCoord], a
;> return u8(position + 1)
	inc e
	ret
; display "[player] VS [enemy]" text box with pokeballs representing their parties next to the names
;@ path: engine/battle/link_battle_versus_text
;@ def DisplayLinkBattleVersusTextBox()
;@ The box before a link battle: both players' names, a bold "VS" between them and each side's Poké Balls.
DisplayLinkBattleVersusTextBox:
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> TextBoxBorder(coord(3, 4), 7, 12)
	ld hl, (4) * SCREEN_WIDTH + (3) + wTileMap
	ld b, 7
	ld c, 12
	call TextBoxBorder
;> PlaceString(wPlayerName, coord(4, 5))
	ld hl, (5) * SCREEN_WIDTH + (4) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PlaceString(wLinkEnemyTrainerName, coord(4, 10))
	ld hl, (10) * SCREEN_WIDTH + (4) + wTileMap
	ld de, wLinkEnemyTrainerName
	call PlaceString
; place bold "VS" tiles between the names
;> mem[coord(9, 8)] = 0x69                        # bold "V"
	ld hl, (8) * SCREEN_WIDTH + (9) + wTileMap
	ld a, CHARVAL(STRCHAR("<BOLD_V><BOLD_S>", $0))
	ld [hli], a
;> mem[coord(10, 8)] = 0x6A                       # bold "S"
	ld [hl], CHARVAL(STRCHAR("<BOLD_V><BOLD_S>", CHARLEN("<BOLD_V><BOLD_S>") - 1))
;> wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;> SetupPlayerAndEnemyPokeballs()
	ld hl, SetupPlayerAndEnemyPokeballs
	ld b, BANK(SetupPlayerAndEnemyPokeballs)
	call Bankswitch
;> DelayFrames(150)
	ld c, 150
	jp DelayFrames
;@ path: engine/slots/slot_machine
;@ def PromptUserToPlaySlots()
;@ "A slot machine! Want to play?" On YES: a smile bubble, the slot machine screen, and the game until the
;@ player stops; then the map comes back.
;@ test: skip runs the slot machine
PromptUserToPlaySlots:
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> wAutoTextBoxDrawingControl = 1 << BIT_NO_AUTO_TEXT_BOX
	ld a, BANK(DisplayTextIDInit)
	ASSERT BANK(DisplayTextIDInit) == 1 << BIT_NO_AUTO_TEXT_BOX
	ld [wAutoTextBoxDrawingControl], a ; 1 << BIT_NO_AUTO_TEXT_BOX
;> Bankswitch(BANK(DisplayTextIDInit), DisplayTextIDInit)
	ld b, a ; BANK(DisplayTextIDInit)
	ld hl, DisplayTextIDInit
	call Bankswitch
;> PrintText(PlaySlotMachineText)
	ld hl, PlaySlotMachineText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem == 0:
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .done ; if player chose No
;>     wUpdateSpritesEnabled = 0xFF
	dec a
	ld [wUpdateSpritesEnabled], a
;>     wSlotMachineRerollCounter = 0
	ld hl, wSlotMachineRerollCounter
	xor a
	ld [hli], a
;>     mem[addr(wSlotMachineRerollCounter) + 1] = SMILE_BUBBLE
	ld [hl], SMILE_BUBBLE
;>     EmotionBubble()                               # through the predef table
	ld a, (EmotionBubblePredef - PredefPointers) / 3
	call Predef
;>     GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>     LoadSlotMachineTiles()
	call LoadSlotMachineTiles
;>     LoadFontTilePatterns()
	call LoadFontTilePatterns
;>     RunPaletteCommand(SET_PAL_SLOTS)
	ld b, SET_PAL_SLOTS
	call RunPaletteCommand
;>     GBPalNormal()
	call GBPalNormal
;>     rOBP0 = 0xE4
	ld a, $e4
	ldh [rOBP0], a
;>     wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;>     wSlotMachineAllowMatchesCounter = 0
	xor a
	ld [wSlotMachineAllowMatchesCounter], a
;>     FillMemory(addr(wStoppingWhichSlotMachineWheel), 0x14, 0)
	ld hl, wStoppingWhichSlotMachineWheel
	ld bc, $14
	call FillMemory
;>     MainSlotMachineLoop()
	call MainSlotMachineLoop
;>     wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;>     wSlotMachineAllowMatchesCounter = 0
	xor a
	ld [wSlotMachineAllowMatchesCounter], a
;>     GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;>     wUpdateSpritesEnabled = 1
	ld a, $1
	ld [wUpdateSpritesEnabled], a
;>     RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>     ReloadMapSpriteTilePatterns()
	call ReloadMapSpriteTilePatterns
;>     ReloadTilesetTilePatterns()
	call ReloadTilesetTilePatterns
.done
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> Delay3()
	call Delay3
;> GBPalNormal()
	call GBPalNormal
;> return CloseTextDisplay(wSlotMachineSavedROMBank)
	ld a, [wSlotMachineSavedROMBank]
	push af
	jp CloseTextDisplay

;@ path: engine/slots/slot_machine
PlaySlotMachineText:
	db TX_FAR
	dw _PlaySlotMachineText
	db BANK(_PlaySlotMachineText)
	db TX_END

;@ path: engine/slots/slot_machine
;@ def MainSlotMachineLoop()
;@ One game after another: choose a bet of 1 to 3 coins (B quits), spin, stop the wheels, collect, and "One
;@ more go?" until the player says no or runs out of coins.
;@ test: skip runs the slot machine
MainSlotMachineLoop:
;> while True:
;>     SlotMachine_PrintCreditCoins()
	call SlotMachine_PrintCreditCoins
;>     wPayoutCoins[0] = 0
	xor a
	ld hl, wPayoutCoins
	ld [hli], a
;>     wPayoutCoins[1] = 0
	ld [hl], a
;>     SlotMachine_PrintPayoutCoins()
	call SlotMachine_PrintPayoutCoins
;>     PrintText(BetHowManySlotMachineText)
	ld hl, BetHowManySlotMachineText
	call PrintText
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     while True:
.loop
;>         wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;>         wMaxMenuItem = 2
	ld a, 2
	ld [wMaxMenuItem], a
;>         wTopMenuItemY = 12
	ld a, 12
	ld [wTopMenuItemY], a
;>         wTopMenuItemX = 15
	ld a, 15
	ld [wTopMenuItemX], a
;>         wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;>         wLastMenuItem = 0
	ld [wLastMenuItem], a
;>         wMenuWatchMovingOutOfBounds = 0
	ld [wMenuWatchMovingOutOfBounds], a
;>         TextBoxBorder(coord(14, 11), 5, 4)
	ld hl, (11) * SCREEN_WIDTH + (14) + wTileMap
	ld b, 5
	ld c, 4
	call TextBoxBorder
;>         PlaceString(CoinMultiplierSlotMachineText, coord(16, 12))
	ld hl, (12) * SCREEN_WIDTH + (16) + wTileMap
	ld de, CoinMultiplierSlotMachineText
	call PlaceString
;>         if HandleMenuInput() & PAD_B:
;>             return LoadScreenTilesFromBuffer1()
	call HandleMenuInput
	and PAD_B
	jp nz, LoadScreenTilesFromBuffer1
;>         bet = 3 - wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, 3
	sub b
;>         wSlotMachineBet = bet
	ld [wSlotMachineBet], a
;>         coins = addr(wPlayerCoins)
	ld hl, wPlayerCoins
	ld c, a
;>         if mem[coins]:                        # 100 coins or more
;>             break
	ld a, [hli]
	and a
	jr nz, .skip1
;>         if mem[coins + 1] >= bet:             # BCD, so the low byte compares as is
;>             break
	ld a, [hl]
	cp c
	jr nc, .skip1
;>         PrintText(NotEnoughCoinsSlotMachineText)
	ld hl, NotEnoughCoinsSlotMachineText
	call PrintText
	jr .loop
.skip1
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     SlotMachine_SubtractBetFromPlayerCoins()
	call SlotMachine_SubtractBetFromPlayerCoins
;>     SlotMachine_LightBalls()
	call SlotMachine_LightBalls
;>     SlotMachine_SetFlags()
	call SlotMachine_SetFlags
;>     wSlotMachineWheel1SlipCounter = 4
	ld a, 4
	ld hl, wSlotMachineWheel1SlipCounter
	ld [hli], a
;>     mem[addr(wSlotMachineWheel1SlipCounter) + 1] = 4
	ld [hli], a
;>     wSlotMachineWheel2SlipCounter = 4
	ld [hl], a
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
;>     PlaySound(SFX_SLOTS_NEW_SPIN)
	ld a, SFX_SLOTS_NEW_SPIN
	call PlaySound
;>     PrintText(StartSlotMachineText)
	ld hl, StartSlotMachineText
	call PrintText
;>     SlotMachine_SpinWheels()
	call SlotMachine_SpinWheels
;>     SlotMachine_CheckForMatches()
	call SlotMachine_CheckForMatches
;>     if not (wPlayerCoins[0] or wPlayerCoins[1]):
	ld hl, wPlayerCoins
	ld a, [hli]
	or [hl]
	jr nz, .skip2
;>         PrintText(OutOfCoinsSlotMachineText)
	ld hl, OutOfCoinsSlotMachineText
	call PrintText
;>         return DelayFrames(60)
	ld c, 60
	jp DelayFrames
.skip2
;>     PrintText(OneMoreGoSlotMachineText)
	ld hl, OneMoreGoSlotMachineText
	call PrintText
;>     wTwoOptionMenuID = YES_NO_MENU
	ld hl, (12) * SCREEN_WIDTH + (14) + wTileMap
	ld bc, ((13) & $ff) << 8 + ((15) & $ff)
	xor a ; YES_NO_MENU
	ld [wTwoOptionMenuID], a
;>     wTextBoxID = TWO_OPTION_MENU
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;>     DisplayTextBoxID()                        # at coord(14, 12)
	call DisplayTextBoxID
;>     if wCurrentMenuItem:
;>         return
	ld a, [wCurrentMenuItem]
	and a
	ret nz
;>     SlotMachine_PutOutLitBalls()
	call SlotMachine_PutOutLitBalls
	jp MainSlotMachineLoop

