;@ path: engine/slots/slot_machine
;@ def SlotMachine_SetFlags()
;@ Decide before the spin whether this game may pay out: once in 7/BAR mode it stays so until a big win. A
;@ running "allow matches" streak lets small wins through; otherwise a random number gives a 1/256 chance of
;@ such a streak of 60 games, a small chance of 7/BAR mode (more on the lucky machine), and above 210 the chance
;@ of a small win.
;@ test: hLoadedROMBank = 0x0D
SlotMachine_SetFlags:
;> if wSlotMachineFlags >> BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR & 1:
;>     return
	ld hl, wSlotMachineFlags
	bit BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR, [hl]
	ret nz
;> if wSlotMachineAllowMatchesCounter:            # a streak is running
;>@win     wSlotMachineFlags = wSlotMachineFlags | 1 << BIT_SLOTS_CAN_WIN
;>@winret     return
	ld a, [wSlotMachineAllowMatchesCounter]
	and a
	jr nz, .allowMatches
;> r = Random()
	call Random
;> if r == 0:
;>@streak     wSlotMachineAllowMatchesCounter = 60
	and a
	jr z, .setAllowMatchesCounter ; 1/256 (~0.4%) chance
;> elif wSlotMachineSevenAndBarModeChance < r:
;>@seven     wSlotMachineFlags = wSlotMachineFlags | 1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR
	ld b, a
	ld a, [wSlotMachineSevenAndBarModeChance]
	cp b
	jr c, .allowSevenAndBarMatches
;> elif 210 < r:
;>@win2     wSlotMachineFlags = wSlotMachineFlags | 1 << BIT_SLOTS_CAN_WIN
	ld a, 210
	cp b
	jr c, .allowMatches ; 55/256 (~21.5%) chance
;> else:
;>     wSlotMachineFlags = 0
	ld [hl], 0
	ret
.allowMatches
;=@win
	set BIT_SLOTS_CAN_WIN, [hl]
;=@winret
	ret
.setAllowMatchesCounter
;=@streak
	ld a, 60
	ld [wSlotMachineAllowMatchesCounter], a
	ret
.allowSevenAndBarMatches
;=@seven
	set BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR, [hl]
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_SpinWheels()
;@ Spin all three wheels for 20 steps, then keep spinning while the player stops them one by one with A, until
;@ the third has stopped.
;@ test: skip waits for frames
SlotMachine_SpinWheels:
;> for _ in range(20):
	ld c, 20
.loop1
;>     SlotMachine_AnimWheel1()
	push bc
	call SlotMachine_AnimWheel1
;>     SlotMachine_AnimWheel2()
	call SlotMachine_AnimWheel2
;>     SlotMachine_AnimWheel3()
	call SlotMachine_AnimWheel3
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
	pop bc
	dec c
	jr nz, .loop1
;> wStoppingWhichSlotMachineWheel = 0
	xor a
	ld [wStoppingWhichSlotMachineWheel], a
;> while True:
.loop2
;>     SlotMachine_HandleInputWhileWheelsSpin()
	call SlotMachine_HandleInputWhileWheelsSpin
;>     SlotMachine_StopOrAnimWheel1()
	call SlotMachine_StopOrAnimWheel1
;>     SlotMachine_StopOrAnimWheel2()
	call SlotMachine_StopOrAnimWheel2
;>     if SlotMachine_StopOrAnimWheel3():
;>         return
	call SlotMachine_StopOrAnimWheel3
	ret c
;>     DelayFrames((wOnSGB ^ 1) + 1)
	ld a, [wOnSGB]
	xor $1
	inc a
	ld c, a
	call DelayFrames
	jr .loop2

; Note that the wheels can only stop when a symbol is centred in the wheel
; and thus 3 full symbols rather than 2 full symbols and 2 half symbols are
; visible. The 3 functions below ensure this by checking if the wheel offset
; is even before stopping the wheel.

;@ path: engine/slots/slot_machine
;@ def SlotMachine_StopOrAnimWheel1()
;@ Turn wheel 1 a step, unless the player has stopped it and a symbol sits in the middle: then it slips on a
;@ few more steps (wSlotMachineWheel1SlipCounter) unless it may stop early.
;@ test: hLoadedROMBank = 0x0D
SlotMachine_StopOrAnimWheel1:
;> if wStoppingWhichSlotMachineWheel >= 1:
	ld a, [wStoppingWhichSlotMachineWheel]
	cp 1
	jr c, .animWheel
;>     if wSlotMachineWheel1Offset & 1:          # a symbol sits in the middle
	ld de, wSlotMachineWheel1Offset
	ld a, [de]
	rra
	jr nc, .animWheel ; check that a symbol is centred in the wheel
;>         if wSlotMachineWheel1SlipCounter == 0:
;>             return
	ld hl, wSlotMachineWheel1SlipCounter
	ld a, [hl]
	and a
	ret z
;>         wSlotMachineWheel1SlipCounter -= 1
	dec [hl]
;>         if not SlotMachine_StopWheel1Early():
;>             return
	call SlotMachine_StopWheel1Early
	ret nz
.animWheel
;> SlotMachine_AnimWheel1()
	jp SlotMachine_AnimWheel1

;@ path: engine/slots/slot_machine
;@ def SlotMachine_StopOrAnimWheel2()
;@ The same for wheel 2.
;@ test: hLoadedROMBank = 0x0D
SlotMachine_StopOrAnimWheel2:
;> if wStoppingWhichSlotMachineWheel >= 2:
	ld a, [wStoppingWhichSlotMachineWheel]
	cp 2
	jr c, .animWheel
;>     if wSlotMachineWheel2Offset & 1:          # a symbol sits in the middle
	ld de, wSlotMachineWheel2Offset
	ld a, [de]
	rra
	jr nc, .animWheel ; check that a symbol is centred in the wheel
;>         if wSlotMachineWheel2SlipCounter == 0:
;>             return
	ld hl, wSlotMachineWheel2SlipCounter
	ld a, [hl]
	and a
	ret z
;>         wSlotMachineWheel2SlipCounter -= 1
	dec [hl]
;>         if SlotMachine_StopWheel2Early():
;>             return
	call SlotMachine_StopWheel2Early
	ret z
.animWheel
;> SlotMachine_AnimWheel2()
	jp SlotMachine_AnimWheel2

;@ path: engine/slots/slot_machine
;@ def SlotMachine_StopOrAnimWheel3() -> carry
;@ Wheel 3 stops as soon as it is stopped with a symbol in the middle (carry); otherwise it turns a step.
;@ test: hLoadedROMBank = 0x0D
SlotMachine_StopOrAnimWheel3:
;> if wStoppingWhichSlotMachineWheel >= 3:
	ld a, [wStoppingWhichSlotMachineWheel]
	cp 3
	jr c, .animWheel
;>     if wSlotMachineWheel3Offset & 1:          # a symbol sits in the middle
	ld de, wSlotMachineWheel3Offset
	ld a, [de]
	rra
	jr nc, .animWheel ; check that a symbol is centred in the wheel
; wheel 3 stops as soon as possible
;>         return True
	scf
	ret
.animWheel
;> SlotMachine_AnimWheel3()
	call SlotMachine_AnimWheel3
;> return False
	and a
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_StopWheel1Early() -> zero
;@ Whether wheel 1 keeps slipping (zero). Normally it stops at once unless a cherry is in the middle. In 7/BAR
;@ mode the check meant to stop it on a 7 never matches, so it slips the full count.
;@ test: hLoadedROMBank = 0x0D
SlotMachine_StopWheel1Early:
;> SlotMachine_GetWheel1Tiles()
	call SlotMachine_GetWheel1Tiles
;> tiles = addr(wSlotMachineWheel1BottomTile)
	ld hl, wSlotMachineWheel1BottomTile
;> if wSlotMachineFlags >> BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR & 1:
;>@for     for _ in range(3):                        # meant to stop on a 7, but never does
;>@tile         tile = mem[tiles]
;>@tile2         tiles += 1
;>@low         if tile < SLOTS7 >> 8:
;>@stop1             wSlotMachineWheel1SlipCounter = 0
;>@stop1r             return u8(tile + 1) == 0
;>@slip     return True                               # slips the full count
	ld a, [wSlotMachineFlags]
	and 1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR
	jr nz, .sevenAndBarMode
; Stop early if the middle symbol is not a cherry.
;> tile = wSlotMachineWheel1MiddleTile
	inc hl
	ld a, [hl]
;> if tile != SLOTSCHERRY >> 8:                  # stops at once unless a cherry shows
;>@stop2     wSlotMachineWheel1SlipCounter = 0
;>@stop2r     return u8(tile + 1) == 0
	cp HIGH(SLOTSCHERRY)
	jr nz, .stopWheel
;> return True
	ret
; Bug: This looks intended to make the wheel stop when a
; 7 symbol was visible, but instead the wheel stops randomly.
.sevenAndBarMode
;=@for
	ld c, $3
.loop
;=@tile
	ld a, [hli]
;=@low
	cp HIGH(SLOTS7)
	jr c, .stopWheel ; condition never true
;=@for
	dec c
	jr nz, .loop
;=@slip
	ret
.stopWheel
;=@stop2r
	inc a
;=@stop2
	ld hl, wSlotMachineWheel1SlipCounter
	ld [hl], 0
;=@stop2r
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_StopWheel2Early() -> zero
;@ Whether wheel 2 stops now (zero): normally as soon as it lines up a symbol with wheel 1; in 7/BAR mode when
;@ that symbol is a 7 or BAR, or when nothing lines up and its bottom symbol is a 7 or BAR.
;@ test: hLoadedROMBank = 0x0D
SlotMachine_StopWheel2Early:
;> SlotMachine_GetWheel2Tiles()
	call SlotMachine_GetWheel2Tiles
;> if wSlotMachineFlags >> BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR & 1:
;>@match1     lined_up, symbol = SlotMachine_FindWheel1Wheel2Matches()
;>@cmp     if mem[symbol] >= (SLOTSBAR >> 8) + 1:        # neither a 7 nor a BAR
;>@keep         return mem[symbol] == (SLOTSBAR >> 8) + 1
	ld a, [wSlotMachineFlags]
	and 1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR
	jr nz, .sevenAndBarMode
; Stop early if any symbols are lined up in the first two wheels.
;> else:
;>     lined_up, symbol = SlotMachine_FindWheel1Wheel2Matches()
	call SlotMachine_FindWheel1Wheel2Matches
;>     if not lined_up:
;>         return False
	ret nz
	jr .stopWheel
; Stop early if two 7 symbols or two bar symbols are lined up in the first two
; wheels OR if no symbols are lined up and the bottom symbol in wheel 2 is a
; 7 symbol or bar symbol. The second part could be a bug or a way to reduce the
; player's odds.
.sevenAndBarMode
;=@match1
	call SlotMachine_FindWheel1Wheel2Matches
;=@cmp
	ld a, [de]
	cp HIGH(SLOTSBAR) + 1
;=@keep
	ret nc
.stopWheel
;> wSlotMachineWheel2SlipCounter = 0
	xor a
	ld [wSlotMachineWheel2SlipCounter], a
;> return True
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_FindWheel1Wheel2Matches() -> (zero, de)
;@ Whether wheels 1 and 2 line up a symbol that wheel 3 could complete (zero), and the address of wheel 2's
;@ symbol in the line (its bottom symbol if there is none).
SlotMachine_FindWheel1Wheel2Matches:
; return whether wheel 1 and wheel 2's current positions allow a match (given
; that wheel 3 stops in a good position) in Z
;> wheel1 = addr(wSlotMachineWheel1BottomTile)
	ld hl, wSlotMachineWheel1BottomTile
;> wheel2 = addr(wSlotMachineWheel2BottomTile)
	ld de, wSlotMachineWheel2BottomTile
;> if mem[wheel2] == mem[wheel1]:                # both bottom symbols
;>     return True, wheel2
	ld a, [de]
	cp [hl] ; wheel 1 bottom, wheel 2 bottom
	ret z
;> wheel2 += 1
	inc de
;> if mem[wheel2] == mem[wheel1]:                # wheel 2 middle, wheel 1 bottom
;>     return True, wheel2
	ld a, [de]
	cp [hl] ; wheel 1 bottom, wheel 2 middle
	ret z
;> wheel1 += 1
	inc hl
;> if mem[wheel2] == mem[wheel1]:                # both middle symbols
;>     return True, wheel2
	cp [hl] ; wheel 1 middle, wheel 2 middle
	ret z
;> wheel1 += 1
	inc hl
;> if mem[wheel2] == mem[wheel1]:                # wheel 2 middle, wheel 1 top
;>     return True, wheel2
	cp [hl] ; wheel 1 top, wheel 2 middle
	ret z
;> wheel2 += 1
	inc de
;> if mem[wheel2] == mem[wheel1]:                # both top symbols
;>     return True, wheel2
	ld a, [de]
	cp [hl] ; wheel 1 top, wheel 2 top
	ret z
;> return False, wheel2 - 2                      # the bottom symbol
	dec de
	dec de
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_CheckForMatches()
;@ Look for three equal symbols on the lines the bet pays for: the middle row for 1 coin, also top and bottom
;@ rows for 2, also both diagonals for 3. If this game may not win (or may not win a 7/BAR), wheel 3 is
;@ nudged down a symbol and the lines are checked again (a few times without a match when wins are allowed).
;@ A win flashes the screen, shows the symbol, and pays out.
;@ test: skip jumps to the reward functions
SlotMachine_CheckForMatches:
;> while True:
;>     SlotMachine_GetWheel3Tiles()
	call SlotMachine_GetWheel3Tiles
;>     bet = wSlotMachineBet
	ld a, [wSlotMachineBet]
;>     diagonals = bet == 3                      # 3 coins: the diagonals as well
;>@rows     rows = bet >= 2                           # 2 coins or more: the top and bottom rows as well
	cp 2
	jr z, .checkMatchesFor2CoinBet
	cp 1
	jr z, .checkMatchFor1CoinBet
; 3 coin bet allows diagonal matches (plus the matches for 1/2 coin bets)
;>     if diagonals and SlotMachine_CheckForMatch(addr(wSlotMachineWheel1BottomTile), addr(wSlotMachineWheel2MiddleTile), addr(wSlotMachineWheel3TopTile)):
;>@m1         match = addr(wSlotMachineWheel1BottomTile)
	ld hl, wSlotMachineWheel1BottomTile
	ld de, wSlotMachineWheel2MiddleTile
	ld bc, wSlotMachineWheel3TopTile
	call SlotMachine_CheckForMatch
	jp z, .foundMatch
;>     elif diagonals and SlotMachine_CheckForMatch(addr(wSlotMachineWheel1TopTile), addr(wSlotMachineWheel2MiddleTile), addr(wSlotMachineWheel3BottomTile)):
;>@m2         match = addr(wSlotMachineWheel1TopTile)
	ld hl, wSlotMachineWheel1TopTile
	ld de, wSlotMachineWheel2MiddleTile
	ld bc, wSlotMachineWheel3BottomTile
	call SlotMachine_CheckForMatch
	jr z, .foundMatch
; 2 coin bet allows top/bottom horizontal matches (plus the match for a 1 coin bet)
.checkMatchesFor2CoinBet
;>     elif rows and SlotMachine_CheckForMatch(addr(wSlotMachineWheel1TopTile), addr(wSlotMachineWheel2TopTile), addr(wSlotMachineWheel3TopTile)):
;>@m3         match = addr(wSlotMachineWheel1TopTile)
	ld hl, wSlotMachineWheel1TopTile
	ld de, wSlotMachineWheel2TopTile
	ld bc, wSlotMachineWheel3TopTile
	call SlotMachine_CheckForMatch
	jr z, .foundMatch
;>     elif rows and SlotMachine_CheckForMatch(addr(wSlotMachineWheel1BottomTile), addr(wSlotMachineWheel2BottomTile), addr(wSlotMachineWheel3BottomTile)):
;>@m4         match = addr(wSlotMachineWheel1BottomTile)
	ld hl, wSlotMachineWheel1BottomTile
	ld de, wSlotMachineWheel2BottomTile
	ld bc, wSlotMachineWheel3BottomTile
	call SlotMachine_CheckForMatch
	jr z, .foundMatch
; 1 coin bet only allows a middle horizontal match
.checkMatchFor1CoinBet
;>     elif SlotMachine_CheckForMatch(addr(wSlotMachineWheel1MiddleTile), addr(wSlotMachineWheel2MiddleTile), addr(wSlotMachineWheel3MiddleTile)):
;>@m5         match = addr(wSlotMachineWheel1MiddleTile)
	ld hl, wSlotMachineWheel1MiddleTile
	ld de, wSlotMachineWheel2MiddleTile
	ld bc, wSlotMachineWheel3MiddleTile
	call SlotMachine_CheckForMatch
	jr z, .foundMatch
;>     else:                                     # nothing lined up
;>         may_win = wSlotMachineFlags & (1 << BIT_SLOTS_CAN_WIN | 1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR)
	ld a, [wSlotMachineFlags]
	and (1 << BIT_SLOTS_CAN_WIN) | (1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR)
;>         if may_win:
	jr z, .noMatch
;>             wSlotMachineRerollCounter = u8(wSlotMachineRerollCounter - 1)
	ld hl, wSlotMachineRerollCounter
	dec [hl]
;>             if wSlotMachineRerollCounter:     # nudge wheel 3 down a symbol and look again
;>@r1                 for _ in range(2):            # one symbol is two steps
;>@r1a                     SlotMachine_AnimWheel3()
;>@r1d                     DelayFrame()
;>@r1c                 continue
	jr nz, .rollWheel3DownByOneSymbol
.noMatch
;>         PrintText(NotThisTimeText)
	ld hl, NotThisTimeText
	call PrintText
;>@brk         break
.done
;=@done
	xor a
	ld [wMuteAudioAndPauseMusic], a
	ret
.rollWheel3DownByOneSymbol
;=@r1a
	call SlotMachine_AnimWheel3
;=@r1d
	call DelayFrame
;=@r1a
	call SlotMachine_AnimWheel3
;=@r1d
	call DelayFrame
;=@r1c
	jp SlotMachine_CheckForMatches
.foundMatch
;>     if not wSlotMachineFlags & (1 << BIT_SLOTS_CAN_WIN | 1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR):    # may not win
;>@r2         for _ in range(2):
;>@r2a             SlotMachine_AnimWheel3()
;>@r2d             DelayFrame()
;>@r2c         continue
	ld a, [wSlotMachineFlags]
	and (1 << BIT_SLOTS_CAN_WIN) | (1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR)
	jr z, .rollWheel3DownByOneSymbol ; roll wheel if player isn't allowed to win
;>     if not wSlotMachineFlags >> BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR & 1:
	and 1 << BIT_SLOTS_CAN_WIN_WITH_7_OR_BAR
	jr nz, .acceptMatch
; if 7/bar matches aren't enabled and the match was a 7/bar symbol, roll wheel
;>         if mem[match] < (SLOTSBAR >> 8) + 1:  # a 7 or BAR, which this game may not pay
;>@r3             for _ in range(2):
;>@r3a                 SlotMachine_AnimWheel3()
;>@r3d                 DelayFrame()
;>@r3c             continue
	ld a, [hl]
	cp HIGH(SLOTSBAR) + 1
	jr c, .rollWheel3DownByOneSymbol
.acceptMatch
;>     symbol = mem[match] - 2
	ld a, [hl]
	sub $2
;>     wSlotMachineWinningSymbol = symbol
	ld [wSlotMachineWinningSymbol], a
;>     entry = SlotRewardPointers + symbol
	ld hl, SlotRewardPointers
	ld c, a
	ld b, 0
	add hl, bc
;>     reward = mem16[entry]                     # (kept)
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
	push de
;>     text = mem16[entry + 2]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     CopyData(text, addr(wStringBuffer), 4)    # every reward text is at most 4 bytes
	ld de, wStringBuffer
	ld bc, 4 ; every SlotReward*Text is at most 4 bytes
	call CopyData
;>     flashes, coins = call(reward)             # it returns to the flashing below
	pop hl
	ld de, .flashScreenLoop
	push de
	jp hl

;>@flash     for _ in range(flashes):
.flashScreenLoop
;>         rBGP ^= 0x40
	ldh a, [rBGP]
	xor $40
	ldh [rBGP], a
;>         DelayFrames(5)
	ld c, 5
	call DelayFrames
;=@flash
	dec b
	jr nz, .flashScreenLoop
;>     wPayoutCoins[0] = coins >> 8
	ld hl, wPayoutCoins
	ld [hl], d
;>     wPayoutCoins[1] = coins & 0xFF
	inc hl
	ld [hl], e
;>     SlotMachine_PrintPayoutCoins()
	call SlotMachine_PrintPayoutCoins
;>     PrintText(SymbolLinedUpSlotMachineText)
	ld hl, SymbolLinedUpSlotMachineText
	call PrintText
;>     WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;>     SlotMachine_PayCoinsToPlayer()
	call SlotMachine_PayCoinsToPlayer
;>     SlotMachine_PrintPayoutCoins()
	call SlotMachine_PrintPayoutCoins
;>     rOBP0 = 0xE4
	ld a, $e4
	ldh [rOBP0], a
;>     break
	jp .done
;>@done wMuteAudioAndPauseMusic = 0

;@ path: engine/slots/slot_machine
;@ def SymbolLinedUpSlotMachineText() -> hl
;@ Text script: draw the winning symbol in the text box, then go on with "lined up!".
;@ test: skip runs inside the text engine
SymbolLinedUpSlotMachineText:
	db TX_START_ASM
;> # (bc is kept)
	push bc
;> SlotMachine_PrintWinningSymbol()
	call SlotMachine_PrintWinningSymbol
;> text = LinedUpText
	ld hl, LinedUpText
;> # (bc back, moved on past this part of the script)
	pop bc
	inc bc
	inc bc
	inc bc
	inc bc
;> return text
	ret

;@ path: engine/slots/slot_machine
LinedUpText:
	db TX_FAR
	dw _LinedUpText
	db BANK(_LinedUpText)
	db TX_END

;@ path: engine/slots/slot_machine
SlotRewardPointers:
	dw SlotReward300Func
	dw SlotReward300Text
	dw SlotReward100Func
	dw SlotReward100Text
	dw SlotReward8Func
	dw SlotReward8Text
	dw SlotReward15Func
	dw SlotReward15Text
	dw SlotReward15Func
	dw SlotReward15Text
	dw SlotReward15Func
	dw SlotReward15Text

;@ path: engine/slots/slot_machine
SlotReward300Text:
	db "300@"

;@ path: engine/slots/slot_machine
SlotReward100Text:
	db "100@"

;@ path: engine/slots/slot_machine
SlotReward8Text:
	db "8@"

;@ path: engine/slots/slot_machine
SlotReward15Text:
	db "15@"

;@ path: engine/slots/slot_machine
NotThisTimeText:
	db TX_FAR
	dw _NotThisTimeText
	db BANK(_NotThisTimeText)
	db TX_END

; compares the slot machine tiles at bc, de, and hl
;@ path: engine/slots/slot_machine
;@ def SlotMachine_CheckForMatch(first: hl, second: de, third: bc) -> zero
;@ Whether the symbols at the three addresses are the same.
;@ test: first = 0xCD41 + rand(0, 2); second = 0xCD44 + rand(0, 2); third = 0xCD47 + rand(0, 2)    # the wheel tiles
SlotMachine_CheckForMatch:
;> return mem[second] == mem[first] and mem[third] == mem[first]
	ld a, [de]
	cp [hl]
	ret nz
	ld a, [bc]
	cp [hl]
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_GetWheel3Tiles()
;@ The three visible symbols of each wheel (bottom to top) from their offsets: wheel 3, then 2 and 1.
SlotMachine_GetWheel3Tiles:
;> SlotMachine_GetWheelTiles(SlotMachineWheel3, wSlotMachineWheel3Offset, addr(wSlotMachineWheel3BottomTile))
;> SlotMachine_GetWheel2Tiles()
	ld de, wSlotMachineWheel3BottomTile
	ld hl, SlotMachineWheel3
	ld a, [wSlotMachineWheel3Offset]
	call SlotMachine_GetWheelTiles

;@ path: engine/slots/slot_machine
;@ def SlotMachine_GetWheel2Tiles()
;@ The visible symbols of wheels 2 and 1.
SlotMachine_GetWheel2Tiles:
;> SlotMachine_GetWheelTiles(SlotMachineWheel2, wSlotMachineWheel2Offset, addr(wSlotMachineWheel2BottomTile))
;> SlotMachine_GetWheel1Tiles()
	ld de, wSlotMachineWheel2BottomTile
	ld hl, SlotMachineWheel2
	ld a, [wSlotMachineWheel2Offset]
	call SlotMachine_GetWheelTiles

;@ path: engine/slots/slot_machine
;@ def SlotMachine_GetWheel1Tiles()
;@ The visible symbols of wheel 1.
SlotMachine_GetWheel1Tiles:
;> SlotMachine_GetWheelTiles(SlotMachineWheel1, wSlotMachineWheel1Offset, addr(wSlotMachineWheel1BottomTile))
	ld de, wSlotMachineWheel1BottomTile
	ld hl, SlotMachineWheel1
	ld a, [wSlotMachineWheel1Offset]

;@ path: engine/slots/slot_machine
;@ def SlotMachine_GetWheelTiles(wheel: hl, offset: a, dest: de)
;@ Three symbols of a wheel from `offset` on (every other byte: each symbol takes two steps) into dest.
;@ test: offset = rand(0, 29); dest = 0xCD41    # wSlotMachineWheel1BottomTile
SlotMachine_GetWheelTiles:
;> p = wheel + offset
	ld c, a
	ld b, 0
	add hl, bc
;>@lp for _ in range(3):
	ld c, 3
.loop
;>     mem[dest] = mem[p]
	ld a, [hli]
	ld [de], a
;>     dest += 1
	inc de
;>     p += 2                                    # each symbol takes two steps
	inc hl
;=@lp
	dec c
	jr nz, .loop
	ret

;@ path: engine/slots/slot_machine
;@ def SlotReward8Func() -> (b, de)
;@ Cherries: 8 coins and 2 flashes; one game of an "allow matches" streak is used up.
SlotReward8Func:
;> if wSlotMachineAllowMatchesCounter:
	ld hl, wSlotMachineAllowMatchesCounter
	ld a, [hl]
	and a
	jr z, .skip
;>     wSlotMachineAllowMatchesCounter -= 1
	dec [hl]
.skip
;> return 2, 8
	ld b, $2
	ld de, 8
	ret

;@ path: engine/slots/slot_machine
;@ def SlotReward15Func() -> (b, de)
;@ Fish, bird or mouse: 15 coins and 4 flashes; one game of an "allow matches" streak is used up.
SlotReward15Func:
;> if wSlotMachineAllowMatchesCounter:
	ld hl, wSlotMachineAllowMatchesCounter
	ld a, [hl]
	and a
	jr z, .skip
;>     wSlotMachineAllowMatchesCounter -= 1
	dec [hl]
.skip
;> return 4, 15
	ld b, $4
	ld de, 15
	ret

;@ path: engine/slots/slot_machine
;@ def SlotReward100Func() -> (b, de)
;@ BAR: 100 coins and 8 flashes, with a jingle; this game's win chances end.
;@ test: skip plays a sound
SlotReward100Func:
;> PlaySound(SFX_GET_KEY_ITEM)
	ld a, SFX_GET_KEY_ITEM
	call PlaySound
;> wSlotMachineFlags = 0
	xor a
	ld [wSlotMachineFlags], a
;> return 8, 100
	ld b, $8
	ld de, 100
	ret

;@ path: engine/slots/slot_machine
;@ def SlotReward300Func() -> (b, de)
;@ 7: "Yeah!", 300 coins and 20 flashes. The streak ends; half the time 7/BAR mode ends too.
;@ test: skip prints a text
SlotReward300Func:
;> PrintText(YeahText)
	ld hl, YeahText
	call PrintText
;> PlaySound(SFX_GET_ITEM_2)
	ld a, SFX_GET_ITEM_2
	call PlaySound
;> if Random() >= 0x80:
;>     wSlotMachineFlags = 0
	call Random
	cp $80
	ld a, 0
	jr c, .skip
	ld [wSlotMachineFlags], a
.skip
;> wSlotMachineAllowMatchesCounter = 0
	ld [wSlotMachineAllowMatchesCounter], a
;> return 0x14, 300
	ld b, $14
	ld de, 300
	ret

;@ path: engine/slots/slot_machine
YeahText:
	db TX_FAR
	dw _YeahText
	db BANK(_YeahText)
	db TX_PAUSE
	db TX_END

;@ path: engine/slots/slot_machine
;@ def SlotMachine_PrintWinningSymbol()
;@ Draw the winning symbol (2x2 tiles) at the start of the text box, and the ▼ prompt.
SlotMachine_PrintWinningSymbol:
; prints winning symbol and down arrow in text box
;> tile = u8(mem[addr(wSlotMachineWinningSymbol)] + 0x25)
	ld hl, (14) * SCREEN_WIDTH + (2) + wTileMap
	ld a, [wSlotMachineWinningSymbol]
	add $25
;> mem[coord(2, 14)] = tile
	ld [hli], a
;> mem[coord(3, 14)] = u8(tile + 1)
	inc a
	ld [hld], a
;> mem[coord(2, 13)] = u8(tile + 2)
	inc a
	ld de, -SCREEN_WIDTH
	add hl, de
	ld [hli], a
;> mem[coord(3, 13)] = u8(tile + 3)
	inc a
	ld [hl], a
;> mem[coord(18, 16)] = 0xEE                         # ▼
	ld hl, (16) * SCREEN_WIDTH + (18) + wTileMap
	ld [hl], '▼'
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_SubtractBetFromPlayerCoins()
;@ Take the bet from the player's coins and show the new count.
;@ test: skip goes through the predef table
SlotMachine_SubtractBetFromPlayerCoins:
;> wTempCoins2[1] = wSlotMachineBet
	ld hl, wTempCoins2 + 1
	ld a, [wSlotMachineBet]
	ld [hld], a
;> wTempCoins2[0] = 0
	xor a
	ld [hli], a
;> Predef((SubBCDPredefPredef - PredefPointers) // 3)          # wPlayerCoins -= wTempCoins2, 2-byte BCD
	ld de, wPlayerCoins + 1
	ld c, $2
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;> return SlotMachine_PrintCreditCoins()          # it follows

;@ path: engine/slots/slot_machine
;@ def SlotMachine_PrintCreditCoins()
;@ The player's coins at the top left of the slot machine screen.
;@ test: skip prints through PrintBCDNumber
SlotMachine_PrintCreditCoins:
;> PrintBCDNumber(addr(wPlayerCoins), coord(5, 1), 2)
	ld hl, (1) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wPlayerCoins
	ld c, 2
	jp PrintBCDNumber

;@ path: engine/slots/slot_machine
;@ def SlotMachine_PrintPayoutCoins()
;@ The coins being paid out, 4 digits with leading zeroes.
;@ test: skip prints through PrintNumber
SlotMachine_PrintPayoutCoins:
;> PrintNumber(addr(wPayoutCoins), coord(11, 1), LEADING_ZEROES | 2, 4)
	ld hl, (1) * SCREEN_WIDTH + (11) + wTileMap
	ld de, wPayoutCoins
	; 2 bytes, 4 digits
	ld bc, ((LEADING_ZEROES | 2) & $ff) << 8 + ((4) & $ff)
	jp PrintNumber

;@ path: engine/slots/slot_machine
;@ def SlotMachine_PayCoinsToPlayer()
;@ Move the payout to the player's coins one at a time, with a sound each and the wheel symbols flashing; 7 and
;@ BAR pay twice as fast.
;@ test: skip waits for frames
SlotMachine_PayCoinsToPlayer:
;> wMuteAudioAndPauseMusic = TRUE
	ld a, TRUE
	ld [wMuteAudioAndPauseMusic], a
;> WaitForSoundToFinish()
	call WaitForSoundToFinish

; Put 1 in the temp coins variable. This value is added to the player's coins
; repeatedly so the player can watch the value go up 1 coin at a time.
;> wTempCoins1[0] = 0
	ld hl, wTempCoins1
	xor a
	ld [hli], a
;> wTempCoins1[1] = 1
	inc a
	ld [hl], a

;> wAnimCounter = 5
	ld a, 5
	ld [wAnimCounter], a

; Subtract 1 from the payout amount and add 1 to the player's coins each
; iteration until the payout amount reaches 0.
;>@lp while wPayoutCoins[0] | wPayoutCoins[1]:
.loop
	ld a, [wPayoutCoins + 1]
	ld l, a
	ld a, [wPayoutCoins]
	ld h, a
	or l
	ret z
;>     left = (wPayoutCoins[0] << 8 | wPayoutCoins[1]) - 1
	ld de, -1
	add hl, de
;>     wPayoutCoins[0] = left >> 8
;>     wPayoutCoins[1] = left & 0xFF
	ld a, l
	ld [wPayoutCoins + 1], a
	ld a, h
	ld [wPayoutCoins], a
;>     Predef((AddBCDPredefPredef - PredefPointers) // 3)      # wPlayerCoins += wTempCoins1, 2-byte BCD
	ld hl, wTempCoins1 + 1
	ld de, wPlayerCoins + 1
	ld c, $2
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;>     SlotMachine_PrintCreditCoins()
	call SlotMachine_PrintCreditCoins
;>     SlotMachine_PrintPayoutCoins()
	call SlotMachine_PrintPayoutCoins
;>     PlaySound(SFX_SLOTS_REWARD)
	ld a, SFX_SLOTS_REWARD
	call PlaySound
;>     wAnimCounter -= 1
;>     if wAnimCounter == 0:
	ld a, [wAnimCounter]
	dec a
	jr nz, .skip1
;>         rOBP0 ^= 0x40
	ldh a, [rOBP0]
	xor $40 ; make the slot wheel symbols flash
	ldh [rOBP0], a
;>         wAnimCounter = 5
	ld a, 5
.skip1
	ld [wAnimCounter], a
;>     big = mem[addr(wSlotMachineWinningSymbol)] < (SLOTSBAR >> 8) + 1     # a 7 or BAR
	ld a, [wSlotMachineWinningSymbol]
	cp HIGH(SLOTSBAR) + 1
;>     frames = 8
	ld c, 8
;>     if big:
	jr nc, .skip2
;>         frames = 4                            # twice as fast
	srl c ; c = 4 (make the the coins transfer faster if the symbol was 7 or bar)
.skip2
;>     DelayFrames(frames)
	call DelayFrames
;=@lp
	jr .loop

;@ path: engine/slots/slot_machine
;@ def SlotMachine_PutOutLitBalls()
;@ Turn all five bet lamps off.
SlotMachine_PutOutLitBalls:
;> mem[addr(wNewSlotMachineBallTile)] = 0x23
;> SlotMachine_UpdateThreeCoinBallTiles()
	ld a, $23
	ld [wNewSlotMachineBallTile], a
	jr SlotMachine_UpdateThreeCoinBallTiles

;@ path: engine/slots/slot_machine
;@ def SlotMachine_LightBalls()
;@ Light the lamps of the lines the bet pays for: the middle one for 1 coin, three for 2, all five for 3.
SlotMachine_LightBalls:
;> mem[addr(wNewSlotMachineBallTile)] = 0x14
	ld a, $14
	ld [wNewSlotMachineBallTile], a
;> if wSlotMachineBet == 1:
;>     SlotMachine_UpdateOneCoinBallTiles()
	ld a, [wSlotMachineBet]
	dec a
	jr z, SlotMachine_UpdateOneCoinBallTiles
;> elif wSlotMachineBet == 2:
;>     SlotMachine_UpdateTwoCoinBallTiles()
	dec a
	jr z, SlotMachine_UpdateTwoCoinBallTiles
;> else:
;>     SlotMachine_UpdateThreeCoinBallTiles()

;@ path: engine/slots/slot_machine
;@ def SlotMachine_UpdateThreeCoinBallTiles()
;@ Set the lamps of the diagonals (rows 2 and 10), then those of the 2-coin and 1-coin lines.
SlotMachine_UpdateThreeCoinBallTiles:
;> SlotMachine_UpdateBallTiles(coord(3, 2))
	ld hl, (2) * SCREEN_WIDTH + (3) + wTileMap
	call SlotMachine_UpdateBallTiles
;> SlotMachine_UpdateBallTiles(coord(3, 10))
	ld hl, (10) * SCREEN_WIDTH + (3) + wTileMap
	call SlotMachine_UpdateBallTiles
;> SlotMachine_UpdateTwoCoinBallTiles()          # it follows

;@ path: engine/slots/slot_machine
;@ def SlotMachine_UpdateTwoCoinBallTiles()
;@ Set the lamps of the top and bottom rows (rows 4 and 8), then the middle one.
SlotMachine_UpdateTwoCoinBallTiles:
;> SlotMachine_UpdateBallTiles(coord(3, 4))
	ld hl, (4) * SCREEN_WIDTH + (3) + wTileMap
	call SlotMachine_UpdateBallTiles
;> SlotMachine_UpdateBallTiles(coord(3, 8))
	ld hl, (8) * SCREEN_WIDTH + (3) + wTileMap
	call SlotMachine_UpdateBallTiles
;> SlotMachine_UpdateOneCoinBallTiles()          # it follows

;@ path: engine/slots/slot_machine
;@ def SlotMachine_UpdateOneCoinBallTiles()
;@ Set the lamps of the middle row.
SlotMachine_UpdateOneCoinBallTiles:
;> SlotMachine_UpdateBallTiles(coord(3, 6))
	ld hl, (6) * SCREEN_WIDTH + (3) + wTileMap

;@ path: engine/slots/slot_machine
;@ def SlotMachine_UpdateBallTiles(at: hl)
;@ One pair of lamps, left and right of the wheels (13 tiles apart), two tiles high, in wNewSlotMachineBallTile.
;@ test: at = rand(0xC000, 0xCF00)
SlotMachine_UpdateBallTiles:
;> tile = mem[addr(wNewSlotMachineBallTile)]
	ld a, [wNewSlotMachineBallTile]
;> mem[at] = tile
	ld [hl], a
;> at += 13                                      # the right lamp
	ld bc, 13
	add hl, bc
;> mem[at] = tile
	ld [hl], a
;> at += SCREEN_WIDTH - 13                       # the row below, on the left
	ld bc, 7
	add hl, bc
;> tile = u8(tile + 1)
	inc a
;> mem[at] = tile
	ld [hl], a
;> at += 13
	ld bc, 13
	add hl, bc
;> mem[at] = tile
	ld [hl], a
	ret

