;@ path: engine/slots/slot_machine
;@ def SlotMachine_AnimWheel(wheel: bc, offset: de, oam: hl)
;@ Draw a wheel as 6 rows of 2 sprites (each symbol is two rows), bottom up from Y $58 at X wBaseCoordX, from
;@ the wheel's symbol tiles at its offset; then advance the offset (30 steps around).
;@ test: wheel = rand(0x4000, 0x7F00); offset = rand(0xC000, 0xCF00); oam = rand(0xD000, 0xDF00)
SlotMachine_AnimWheel:
;> wBaseCoordY = 0x58
	ld a, $58
	ld [wBaseCoordY], a
;> # (offset is kept)
	push de
;> src = wheel + mem[offset]
	ld a, [de]
	ld d, b
	add c
	ld e, a
	jr nc, .loop
	inc d
;> while True:
.loop
;>     mem[oam] = wBaseCoordY
	ld a, [wBaseCoordY]
	ld [hli], a
;>     mem[oam + 1] = wBaseCoordX
	ld a, [wBaseCoordX]
	ld [hli], a
;>     mem[oam + 2] = mem[src]
	ld a, [de]
	ld [hli], a
;>     mem[oam + 3] = 0x80                           # behind the background
	ld a, $80
	ld [hli], a
;>     mem[oam + 4] = wBaseCoordY
	ld a, [wBaseCoordY]
	ld [hli], a
;>     mem[oam + 5] = u8(wBaseCoordX + 8)
	ld a, [wBaseCoordX]
	add $8
	ld [hli], a
;>     mem[oam + 6] = u8(mem[src] + 1)
	ld a, [de]
	inc a
	ld [hli], a
;>     mem[oam + 7] = 0x80
	ld a, $80
	ld [hli], a
;>     oam += 8
;>     src += 1
	inc de
;>     wBaseCoordY = u8(wBaseCoordY - 8)
	ld a, [wBaseCoordY]
	sub $8
	ld [wBaseCoordY], a
;>     if wBaseCoordY == 0x28:
;>         break
	cp $28
	jr nz, .loop
;> step = u8(mem[offset] + 1)
	pop de
	ld a, [de]
	inc a ; advance the offset so that the wheel animates
;> mem[offset] = 0 if step == 30 else step
	cp 30
	jr nz, .skip
	xor a ; wrap around to 0 when the offset reaches 30
.skip
	ld [de], a
	ret

;@ path: engine/slots/slot_machine
;@ def SlotMachine_HandleInputWhileWheelsSpin()
;@ Wait a frame; A stops the next wheel, but not while the previous one is still slipping.
;@ test: skip waits a frame
SlotMachine_HandleInputWhileWheelsSpin:
;> DelayFrame()
	call DelayFrame
;> JoypadLowSensitivity()
	call JoypadLowSensitivity
;> if not hJoy5 & PAD_A:
;>     return
	ldh a, [hJoy5]
	and PAD_A
	ret z
;> stopping = wStoppingWhichSlotMachineWheel
	ld hl, wStoppingWhichSlotMachineWheel
	ld a, [hl]
;> if stopping == 1:
;>@slip1     slip = addr(wSlotMachineWheel1SlipCounter)
	dec a
;=@slip1
	ld de, wSlotMachineWheel1SlipCounter
	jr z, .skip
;> elif stopping == 2:
;>@slip2     slip = addr(wSlotMachineWheel2SlipCounter)
	dec a
;=@slip2
	ld de, wSlotMachineWheel2SlipCounter
	jr z, .skip
;> else:
;>     slip = None
;>@check if slip is not None and mem[slip]:       # the previous wheel is still slipping
;>@wait     return
.loop
;> wStoppingWhichSlotMachineWheel += 1
	inc [hl]
;> PlaySound(SFX_SLOTS_STOP_WHEEL)
	ld a, SFX_SLOTS_STOP_WHEEL
	jp PlaySound
.skip
;=@check
	ld a, [de]
	and a
;=@wait
	ret nz
;=@check
	jr .loop

;@ path: engine/slots/slot_machine
;@ def LoadSlotMachineTiles()
;@ With the screen off, load the slot machine's tiles (the symbol tiles twice: as sprites and as background)
;@ and its screen, then draw the wheels at their start.
;@ test: skip turns the LCD off
LoadSlotMachineTiles:
;> DisableLCD()
	call DisableLCD
;> FarCopyData2(BANK(SlotMachineTiles2), SlotMachineTiles2, vChars0, 0x1C * TILE_SIZE)
	ld hl, SlotMachineTiles2
	ld de, vChars0
	ld bc, $1c * TILE_SIZE ; should be SlotMachineTiles2End - SlotMachineTiles2, or $18 tiles
	ld a, BANK(SlotMachineTiles2)
	call FarCopyData2
;> FarCopyData2(BANK(SlotMachineTiles1), SlotMachineTiles1, vChars2, SlotMachineTiles1End - SlotMachineTiles1)
	ld hl, SlotMachineTiles1
	ld de, vChars2
	ld bc, SlotMachineTiles1End - SlotMachineTiles1
	ld a, BANK(SlotMachineTiles1)
	call FarCopyData2
;> FarCopyData2(BANK(SlotMachineTiles2), SlotMachineTiles2, vChars2 + 0x25 * TILE_SIZE, 0x1C * TILE_SIZE)
	ld hl, SlotMachineTiles2
	ld de, vChars2 + TILE_SIZE * $25
	ld bc, $1c * TILE_SIZE ; should be SlotMachineTiles2End - SlotMachineTiles2, or $18 tiles
	ld a, BANK(SlotMachineTiles2)
	call FarCopyData2
;> CopyData(SlotMachineMap, coord(0, 0), SlotMachineMapEnd - SlotMachineMap)
	ld hl, SlotMachineMap
	ld de, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SlotMachineMapEnd - SlotMachineMap
	call CopyData
;> EnableLCD()
	call EnableLCD
;> wSlotMachineWheel1Offset = 0x1C
	ld hl, wSlotMachineWheel1Offset
	ld a, $1c
	ld [hli], a
;> wSlotMachineWheel2Offset = 0x1C
	ld [hli], a
;> wSlotMachineWheel3Offset = 0x1C
	ld [hl], a
;> SlotMachine_AnimWheel1()
	call SlotMachine_AnimWheel1
;> SlotMachine_AnimWheel2()
	call SlotMachine_AnimWheel2
;> SlotMachine_AnimWheel3()
	jp SlotMachine_AnimWheel3

