;@ path: engine/events/pewter_guys
;@ def PewterGuys()
;@ Add the steps from where the player stands to the museum or gym (guide wWhichPewterGuy) to the simulated
;@ joypad states. PewterGuysCoordsTable lists (y, x, steps) per starting tile; the steps overwrite the last
;@ queued state.
;@ test: skip needs the player on one of the guide's starting tiles
PewterGuys:
;> wSimulatedJoypadStatesIndex = u8(wSimulatedJoypadStatesIndex - 1)
	ld hl, wSimulatedJoypadStatesEnd
	ld a, [wSimulatedJoypadStatesIndex]
	dec a ; this decrement causes it to overwrite the last byte before $FF in the list
	ld [wSimulatedJoypadStatesIndex], a
;> dest = addr(wSimulatedJoypadStatesEnd) + wSimulatedJoypadStatesIndex
	ld d, 0
	ld e, a
	add hl, de
	ld d, h
	ld e, l
;> entry = PewterGuysCoordsTable + 2 * wWhichPewterGuy
	ld hl, PewterGuysCoordsTable
	ld a, [wWhichPewterGuy]
	add a
	ld b, 0
	ld c, a
	add hl, bc
;> p = mem16[entry]                             # this guide's (y, x, steps) list
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> y, x = wYCoord, wXCoord
	ld a, [wYCoord]
	ld b, a
	ld a, [wXCoord]
	ld c, a
.findMatchingCoordsLoop
;> while not (mem[p] == y and mem[p + 1] == x):
;>@next     p += 4
	ld a, [hli]
	cp b
	jr nz, .nextEntry1
	ld a, [hli]
	cp c
	jr nz, .nextEntry2
;> steps = mem16[p + 2]
	ld a, [hli]
	ld h, [hl]
	ld l, a
.copyMovementDataLoop
;> while mem[steps] != 0xFF:
	ld a, [hli]
	cp $ff
	ret z
;>     mem[dest] = mem[steps]
	ld [de], a
;>     dest += 1
;>     steps += 1
	inc de
;>     wSimulatedJoypadStatesIndex = u8(wSimulatedJoypadStatesIndex + 1)
	ld a, [wSimulatedJoypadStatesIndex]
	inc a
	ld [wSimulatedJoypadStatesIndex], a
	jr .copyMovementDataLoop
.nextEntry1
;=@next
	inc hl
.nextEntry2
	inc hl
	inc hl
	jr .findMatchingCoordsLoop

;@ path: engine/events/pewter_guys
PewterGuysCoordsTable:
	dw PewterMuseumGuyCoords
	dw PewterGymGuyCoords

; these are the four coordinates of the spaces below, above, to the left and
; to the right of the museum guy, and pointers to different movements for
; the player to make to get positioned before the main movement.
;@ path: engine/events/pewter_guys
PewterMuseumGuyCoords:
	db 18, 27
	dw .down
