.five
	db PAD_LEFT, PAD_DOWN, PAD_LEFT, $00, $00, $00, $00, $00, $00, $00, $00, $ff
;@ path: engine/math/multiply_divide
;@ def _Multiply()
;@ hProduct = hMultiplicand (3 bytes) * hMultiplier (1 byte), all big-endian, by shifting and adding one
;@ multiplier bit at a time. The multiplier ends up 0; the product is also left in hMultiplyBuffer.
_Multiply::
;> bits = 8
	ld a, $8
	ld b, a
;> hProduct[0] = 0                               # hProduct[0..3]: the multiplicand widened to 4 bytes
	xor a
	ldh [hProduct], a
;> for i in range(4):
;>     hMultiplyBuffer[i] = 0                    # the sum
	ldh [hMultiplyBuffer], a
	ldh [hMultiplyBuffer+1], a
	ldh [hMultiplyBuffer+2], a
	ldh [hMultiplyBuffer+3], a
;> while True:
.loop
;>     low = hMultiplier & 1                     # the multiplier's bits, from the lowest
	ldh a, [hMultiplier]
	srl a
;>     hMultiplier = hMultiplier >> 1
	ldh [hMultiplier], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
;>     if low:
	jr nc, .smallMultiplier
;>         s = (hMultiplyBuffer[0] << 24 | hMultiplyBuffer[1] << 16 | hMultiplyBuffer[2] << 8 | hMultiplyBuffer[3]) + (hProduct[0] << 24 | hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3])
;>         hMultiplyBuffer[3] = s & 0xFF         # added byte by byte, with carry
	ldh a, [hMultiplyBuffer+3]
	ld c, a
	ldh a, [hMultiplicand+2]
	add c
	ldh [hMultiplyBuffer+3], a
;>         hMultiplyBuffer[2] = s >> 8 & 0xFF
	ldh a, [hMultiplyBuffer+2]
	ld c, a
	ldh a, [hMultiplicand+1]
	adc c
	ldh [hMultiplyBuffer+2], a
;>         hMultiplyBuffer[1] = s >> 16 & 0xFF
	ldh a, [hMultiplyBuffer+1]
	ld c, a
	ldh a, [hMultiplicand] ; (aliases: hMultiplicand)
	adc c
	ldh [hMultiplyBuffer+1], a
;>         hMultiplyBuffer[0] = s >> 24 & 0xFF
	ldh a, [hMultiplyBuffer]
	ld c, a
	ldh a, [hProduct] ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
	adc c
	ldh [hMultiplyBuffer], a
.smallMultiplier
;>     bits -= 1
	dec b
;>     if bits == 0:
;>         break
	jr z, .done
;>     m = (hProduct[0] << 24 | hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3]) << 1
;>     hProduct[3] = m & 0xFF                    # the multiplicand doubles for the next bit
	ldh a, [hMultiplicand+2]
	sla a
	ldh [hMultiplicand+2], a
;>     hProduct[2] = m >> 8 & 0xFF
	ldh a, [hMultiplicand+1]
	rl a
	ldh [hMultiplicand+1], a
;>     hProduct[1] = m >> 16 & 0xFF
	ldh a, [hMultiplicand]
	rl a
	ldh [hMultiplicand], a
;>     hProduct[0] = m >> 24 & 0xFF
	ldh a, [hProduct]
	rl a
	ldh [hProduct], a
	jr .loop
.done
;> hProduct[3] = hMultiplyBuffer[3]
	ldh a, [hMultiplyBuffer+3]
	ldh [hProduct+3], a
;> hProduct[2] = hMultiplyBuffer[2]
	ldh a, [hMultiplyBuffer+2]
	ldh [hProduct+2], a
;> hProduct[1] = hMultiplyBuffer[1]
	ldh a, [hMultiplyBuffer+1]
	ldh [hProduct+1], a
;> hProduct[0] = hMultiplyBuffer[0]
	ldh a, [hMultiplyBuffer]
	ldh [hProduct], a
	ret

;@ path: engine/math/multiply_divide
;@ def _Divide(nbytes: b)
;@ hQuotient = the first nbytes bytes of hDividend (big-endian) / hDivisor, remainder in hRemainder: long
;@ division a bit at a time. With a 1-byte dividend the remainder is not computed (hRemainder gets the
;@ dividend's second byte).
;@ test: nbytes = rand(1, 4); hDivisor = rand(1, 255)
_Divide::
;> for i in range(5):
;>     hDivideBuffer[i] = 0                      # [0]: the divisor's low byte, [1..4]: the quotient
	xor a
	ldh [hDivideBuffer], a
	ldh [hDivideBuffer+1], a
	ldh [hDivideBuffer+2], a
	ldh [hDivideBuffer+3], a
	ldh [hDivideBuffer+4], a
;> steps = 9
	ld a, $9
	ld e, a
;> while True:
.loop
;>     # take the divisor (hDivisor, hDivideBuffer[0]) off the top two dividend bytes while it fits
;>     low = hDividend[1] - hDivideBuffer[0]
	ldh a, [hDivideBuffer]
	ld c, a
	ldh a, [hDividend+1] ; (aliases: hMultiplicand)
	sub c
	ld d, a
;>     diff = (hDividend[0] - hDivisor) * 256 + low
	ldh a, [hDivisor] ; (aliases: hDivisor, hMultiplier, hPowerOf10)
	ld c, a
	ldh a, [hDividend] ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
	sbc c
;>     if diff >= 0:
	jr c, .next
;>         hDividend[0] = diff >> 8
;>         hDividend[1] = diff & 0xFF
	ldh [hDividend], a ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
	ld a, d
	ldh [hDividend+1], a ; (aliases: hMultiplicand)
;>         hDivideBuffer[4] = u8(hDivideBuffer[4] + 1)
;>         continue
	ldh a, [hDivideBuffer+4]
	inc a
	ldh [hDivideBuffer+4], a
	jr .loop
.next
;>     if nbytes == 1:
;>         break
	ld a, b
	cp $1
	jr z, .done
;>     q = (hDivideBuffer[1] << 24 | hDivideBuffer[2] << 16 | hDivideBuffer[3] << 8 | hDivideBuffer[4]) << 1
;>     hDivideBuffer[4] = q & 0xFF               # the quotient moves one bit left
	ldh a, [hDivideBuffer+4]
	sla a
	ldh [hDivideBuffer+4], a
;>     hDivideBuffer[3] = q >> 8 & 0xFF
	ldh a, [hDivideBuffer+3]
	rl a
	ldh [hDivideBuffer+3], a
;>     hDivideBuffer[2] = q >> 16 & 0xFF
	ldh a, [hDivideBuffer+2]
	rl a
	ldh [hDivideBuffer+2], a
;>     hDivideBuffer[1] = q >> 24 & 0xFF
	ldh a, [hDivideBuffer+1]
	rl a
	ldh [hDivideBuffer+1], a
;>     steps -= 1
;>     if steps == 0:                            # 8 bits done: on to the next dividend byte
	dec e
	jr nz, .next2
;>         steps = 8
	ld a, $8
	ld e, a
;>         hDivisor = hDivideBuffer[0]
;>         hDivideBuffer[0] = 0
	ldh a, [hDivideBuffer]
	ldh [hDivisor], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
	xor a
	ldh [hDivideBuffer], a
;>         hDividend[0] = hDividend[1]
	ldh a, [hDividend+1] ; (aliases: hMultiplicand)
	ldh [hDividend], a ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
;>         hDividend[1] = hDividend[2]
	ldh a, [hDividend+2]
	ldh [hDividend+1], a ; (aliases: hMultiplicand)
;>         hDividend[2] = hDividend[3]
	ldh a, [hDividend+3]
	ldh [hDividend+2], a
.next2
;>     if steps == 1:
;>         nbytes -= 1
	ld a, e
	cp $1
	jr nz, .okay
	dec b
.okay
;>     d = (hDivisor << 8 | hDivideBuffer[0]) >> 1
;>     hDivisor = d >> 8                         # the divisor moves one bit right
	ldh a, [hDivisor] ; (aliases: hDivisor, hMultiplier, hPowerOf10)
	srl a
	ldh [hDivisor], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
;>     hDivideBuffer[0] = d & 0xFF
	ldh a, [hDivideBuffer]
	rr a
	ldh [hDivideBuffer], a
	jr .loop
.done
;> hRemainder = hDividend[1]
	ldh a, [hDividend+1] ; (aliases: hMultiplicand)
	ldh [hRemainder], a ; (aliases: hDivisor, hMultiplier, hPowerOf10)
;> hQuotient[3] = hDivideBuffer[4]
	ldh a, [hDivideBuffer+4]
	ldh [hQuotient+3], a
;> hQuotient[2] = hDivideBuffer[3]
	ldh a, [hDivideBuffer+3]
	ldh [hQuotient+2], a
;> hQuotient[1] = hDivideBuffer[2]
	ldh a, [hDivideBuffer+2]
	ldh [hQuotient+1], a ; (aliases: hMultiplicand)
;> hQuotient[0] = hDivideBuffer[1]
	ldh a, [hDivideBuffer+1]
	ldh [hDividend], a ; (aliases: hProduct, hPastLeadingZeros, hQuotient)
	ret
;@ path: engine/slots/game_corner_slots
;@ def StartSlotMachine()
;@ Using a Game Corner slot machine: some are out of order, out to lunch, or have someone's keys on them. The
;@ one machine chosen as lucky for this visit gets better 7/BAR chances.
;@ test: skip prints a text
StartSlotMachine:
;> arg = wHiddenEventFunctionArgument
	ld a, [wHiddenEventFunctionArgument]
;> if arg == SLOTS_OUTOFORDER:
;>@ooo     text = (GameCornerOutOfOrderText_id - TextPredefs) // 2 + 1
	cp SLOTS_OUTOFORDER
	jr z, .printOutOfOrder
;> elif arg == SLOTS_OUTTOLUNCH:
;>@otl     text = (GameCornerOutToLunchText_id - TextPredefs) // 2 + 1
	cp SLOTS_OUTTOLUNCH
	jr z, .printOutToLunch
;> elif arg == SLOTS_SOMEONESKEYS:
;>@keys     text = (GameCornerSomeonesKeysText_id - TextPredefs) // 2 + 1
	cp SLOTS_SOMEONESKEYS
	jr z, .printSomeonesKeys
;> else:
;>@none     text = None
;>@shown if text is not None:                       # this machine can't be played: say why
;>@en     EnableAutoTextBoxDrawing()
;>@pr     return PrintPredefTextID(text)
;> AbleToPlaySlotsCheck()
	ld b, BANK(AbleToPlaySlotsCheck)
	ld hl, AbleToPlaySlotsCheck
	call Bankswitch
;> if not wCanPlaySlots:
;>     return
	ld a, [wCanPlaySlots]
	and a
	ret z
;> if wHiddenEventIndex + 1 == wLuckySlotHiddenEventIndex:     # the lucky machine of this visit
	ld a, [wLuckySlotHiddenEventIndex]
	ld b, a
	ld a, [wHiddenEventIndex]
	inc a
	cp b
	jr z, .match
;>@lucky     chance = 250
;> else:
;>     chance = 253
	ld a, 253
	jr .next
.match
;=@lucky
	ld a, 250
.next
;> wSlotMachineSevenAndBarModeChance = chance
	ld [wSlotMachineSevenAndBarModeChance], a
;> wSlotMachineSavedROMBank = hLoadedROMBank
	ldh a, [hLoadedROMBank]
	ld [wSlotMachineSavedROMBank], a
;> PromptUserToPlaySlots()
	call PromptUserToPlaySlots
	ret
.printOutOfOrder
;=@ooo
	ld a, (GameCornerOutOfOrderText_id - TextPredefs) / 2 + 1
	jr .printText
.printOutToLunch
;=@otl
	ld a, (GameCornerOutToLunchText_id - TextPredefs) / 2 + 1
	jr .printText
.printSomeonesKeys
;=@keys
	ld a, (GameCornerSomeonesKeysText_id - TextPredefs) / 2 + 1
.printText
;=@en
	push af
	call EnableAutoTextBoxDrawing
	pop af
;=@pr
	call PrintPredefTextID
	ret

;@ path: engine/slots/game_corner_slots
GameCornerOutOfOrderText::
	db TX_FAR
	dw _GameCornerOutOfOrderText
	db BANK(_GameCornerOutOfOrderText)
	db TX_END

;@ path: engine/slots/game_corner_slots
GameCornerOutToLunchText::
	db TX_FAR
	dw _GameCornerOutToLunchText
	db BANK(_GameCornerOutToLunchText)
	db TX_END

;@ path: engine/slots/game_corner_slots
GameCornerSomeonesKeysText::
	db TX_FAR
	dw _GameCornerSomeonesKeysText
	db BANK(_GameCornerSomeonesKeysText)
	db TX_END


