; does nothing since no stats are ever selected (barring glitches)
;@ path: engine/battle/unused_stats_functions
;@ def DoubleSelectedStats()
;@ Double the stats chosen by a bit mask (bit 0 attack, 1 defense, 2 speed, 3 special) of the Pokémon whose turn
;@ it is. Overflow above 65535 is lost.
DoubleSelectedStats:
;> if hWhoseTurn == 0:
;>     flags, stats = wPlayerStatsToDouble, wBattleMonAttack
	ldh a, [hWhoseTurn]
	and a
	ld a, [wPlayerStatsToDouble]
	ld hl, wBattleMonAttack + 1
	jr z, .notEnemyTurn
;> else:
;>     flags, stats = wEnemyStatsToDouble, wEnemyMonAttack
	ld a, [wEnemyStatsToDouble]
	ld hl, wEnemyMonAttack + 1
.notEnemyTurn
;>@lp for i in range(4):
	ld c, 4
	ld b, a
.loop
;>     if flags >> i & 1:                            # (.doubleStat)
;>@low         low = mem[stats + 2 * i + 1] * 2
;>@stl         mem[stats + 2 * i + 1] = low & 0xFF
;>@high         mem[stats + 2 * i] = (mem[stats + 2 * i] * 2 + (low >> 8)) & 0xFF   # the carry moves up
	srl b
	call c, .doubleStat
;=@lp
	inc hl
	inc hl
	dec c
	ret z
	jr .loop

.doubleStat
;=@low
	ld a, [hl]
	add a
;=@stl
	ld [hld], a
;=@high
	ld a, [hl]
	rl a
	ld [hli], a
	ret

; does nothing since no stats are ever selected (barring glitches)
;@ path: engine/battle/unused_stats_functions
;@ def HalveSelectedStats()
;@ Halve the stats chosen by a bit mask (as in DoubleSelectedStats), never below 1.
HalveSelectedStats:
;> if hWhoseTurn == 0:
;>     flags, stats = wPlayerStatsToHalve, wBattleMonAttack
	ldh a, [hWhoseTurn]
	and a
	ld a, [wPlayerStatsToHalve]
	ld hl, wBattleMonAttack
	jr z, .notEnemyTurn
;> else:
;>     flags, stats = wEnemyStatsToHalve, wEnemyMonAttack
	ld a, [wEnemyStatsToHalve]
	ld hl, wEnemyMonAttack
.notEnemyTurn
;>@lp for i in range(4):
	ld c, 4
	ld b, a
.loop
;>     if flags >> i & 1:                            # (.halveStat)
;>@hi         high = mem[stats + 2 * i]
;>@sh         mem[stats + 2 * i] = high >> 1
;>@lo         mem[stats + 2 * i + 1] = mem[stats + 2 * i + 1] >> 1 | (high & 1) << 7
;>@min         if not (high >> 1 | mem[stats + 2 * i + 1]):     # at least 1
;>@one             mem[stats + 2 * i + 1] = 1
	srl b
	call c, .halveStat
;=@lp
	inc hl
	inc hl
	dec c
	ret z
	jr .loop

.halveStat
;=@hi
	ld a, [hl]
;=@sh
	srl a
	ld [hli], a
;=@lo
	rr [hl]
;=@min
	or [hl]
	jr nz, .nonzeroStat
;=@one
	ld [hl], 1
.nonzeroStat
	dec hl
	ret
;@ path: engine/battle/scroll_draw_trainer_pic
;@ def _ScrollTrainerPicAfterBattle()
;@ After beating a trainer, its picture slides in from the right edge, one tile column every 4 frames.
_ScrollTrainerPicAfterBattle:
; Load the enemy trainer's pic and scrolls it into
; the screen from the right.
;> wEnemyMonSpecies2 = 0
	xor a
	ld [wEnemyMonSpecies2], a
;> RunPaletteCommand(SET_PAL_BATTLE)
	ld b, SET_PAL_BATTLE
	call RunPaletteCommand
;> _LoadTrainerPic()
	ld hl, _LoadTrainerPic
	ld b, BANK(_LoadTrainerPic)
	call Bankswitch
;> right = coord(19, 0)
	ld hl, (0) * SCREEN_WIDTH + (19) + wTileMap
;>@w for width in range(1, 7):
	ld c, $0
.scrollLoop
;=@w
	inc c
	ld a, c
	cp 7
	ret z
;>     tile = 0
	ld d, $0
;>@i     for i in range(width):
	push bc
	push hl
.drawTrainerPicLoop
;>         DrawTrainerPicColumn(right + i, tile)
	call DrawTrainerPicColumn
;=@i
	inc hl
;>         tile += 7
	ld a, 7
	add d
	ld d, a
;=@i
	dec c
	jr nz, .drawTrainerPicLoop
;>     DelayFrames(4)
	ld c, 4
	call DelayFrames
;=@i
	pop hl
	pop bc
;>     right -= 1
	dec hl
;=@w
	jr .scrollLoop

; write one 7-tile column of the trainer pic to the tilemap
;@ path: engine/battle/scroll_draw_trainer_pic
;@ def DrawTrainerPicColumn(dest: hl, tile: d)
;@ Put seven tile numbers, tile to tile + 6, down one screen column from dest.
;@ test: dest = rand_ram(130)
DrawTrainerPicColumn:
;> for i in range(7):
	push hl
	push de
	push bc
	ld e, 7
.loop
;>     mem[dest + i * SCREEN_WIDTH] = tile + i
	ld [hl], d
	ld bc, SCREEN_WIDTH
	add hl, bc
	inc d
	dec e
	jr nz, .loop
;> return
	pop bc
	pop de
	pop hl
	ret
; creates a set of moves that may be used and returns its address in hl
; unused slots are filled with 0, all used slots may be chosen with equal probability
;@ path: engine/battle/trainer_ai
;@ def AIEnemyTrainerChooseMoves() -> hl
;@ The trainer's choice of moves: every move starts with a score of 10 (a disabled move 80), the trainer class's
;@ modification rules (TrainerClassMoveChoiceModifications) raise or lower the scores, and only the moves with the
;@ lowest score stay in wBuffer - the others become 0. A class without rules uses its move set as it is.
;@ test: wTrainerClass = rand(1, 47); mem[0xCFED] = rand(1, 165); hLoadedROMBank = 0x0E
AIEnemyTrainerChooseMoves:
;> fill(wBuffer + 0, 10, NUM_MOVES)         # the lower the score, the likelier the move
	ld a, $a
	ld hl, wBuffer ; init temporary move selection array. Only the moves with the lowest numbers are chosen in the end
	ld [hli], a   ; move 1
	ld [hli], a   ; move 2
	ld [hli], a   ; move 3
	ld [hl], a    ; move 4
;> disabled = wEnemyDisabledMove >> 4
;> if disabled:
	ld a, [wEnemyDisabledMove] ; forbid disabled move (if any)
	swap a
	and $f
	jr z, .noMoveDisabled
;>     wBuffer[disabled - 1] = 0x50         # a disabled move is highly discouraged
	ld hl, wBuffer
	dec a
	ld c, a
	ld b, $0
	add hl, bc    ; advance pointer to forbidden move
	ld [hl], $50  ; forbid (highly discourage) disabled move
.noMoveDisabled
;> rules = TrainerClassMoveChoiceModifications
	ld hl, TrainerClassMoveChoiceModifications
	ld a, [wTrainerClass]
	ld b, a
.loopTrainerClasses
;> for _ in range(wTrainerClass - 1 & 0xFF):   # skip the rule lists of the classes before
	dec b
	jr z, .readTrainerClassData
.loopTrainerClassData
;>     while mem[rules] != 0:
;>         rules += 1
	ld a, [hli]
	and a
	jr nz, .loopTrainerClassData
;>     rules += 1                                    # past the 0
	jr .loopTrainerClasses
.readTrainerClassData
;> if mem[rules] == 0:                      # no rules: the moves as they are
;>     return wEnemyMonMoves
	ld a, [hl]
	and a
	jp z, .useOriginalMoveSet
;> while True:
	push hl
.nextMoveChoiceModification
;>     rule = mem[rules]
;>     rules += 1
	pop hl
	ld a, [hli]
;>     if rule == 0:
;>         break
	and a
	jr z, .loopFindMinimumEntries
;>     table = AIMoveChoiceModificationFunctionPointers
	push hl
	ld hl, AIMoveChoiceModificationFunctionPointers
;>     entry = table + 2 * (rule - 1)
	dec a
	add a
	ld c, a
	ld b, 0
	add hl, bc    ; skip to pointer
;>     func = (AIMoveChoiceModification1, AIMoveChoiceModification2, AIMoveChoiceModification3,
;>             AIMoveChoiceModification4)[rule - 1]     # = mem16[entry]
	ld a, [hli]   ; read pointer into hl
	ld h, [hl]
	ld l, a
;>     func()                               # it returns to the next rule
	ld de, .nextMoveChoiceModification  ; set return address
	push de
	jp hl         ; execute modification function
.loopFindMinimumEntries ; all entries will be decremented sequentially until one of them is zero
;> # take 1 from every score (up to the first empty move slot), round after round, until one reaches 0
;> found = None
;>@wh while found is None:
;>@for     for i in range(NUM_MOVES):
	ld hl, wBuffer  ; temp move selection array
	ld de, wEnemyMonMoves  ; enemy moves
	ld c, NUM_MOVES
.loopDecrementEntries
;>         if mem[wEnemyMonMoves + i] == 0:     # the end of the move list: next round
;>             break
	ld a, [de]
	inc de
	and a
	jr z, .loopFindMinimumEntries
;>         wBuffer[i] = wBuffer[i] - 1 & 0xFF
	dec [hl]
;>         if wBuffer[i] == 0:
;>             found = i
	jr z, .minimumEntriesFound
;>             break
;=@for
	inc hl
	dec c
;=@wh
	jr z, .loopFindMinimumEntries
;=@for
	jr .loopDecrementEntries
.minimumEntriesFound
;> for j in range(found, -1, -1):           # take that round back: the lowest scores end up at 1
;>     wBuffer[j] += 1
	ld a, c
.loopUndoPartialIteration ; undo last (partial) loop iteration
	inc [hl]
	dec hl
	inc a
	cp NUM_MOVES + 1
	jr nz, .loopUndoPartialIteration
;> for i in range(NUM_MOVES):               # only the slots at 1 keep their move
	ld hl, wBuffer  ; temp move selection array
	ld de, wEnemyMonMoves  ; enemy moves
	ld c, NUM_MOVES
.filterMinimalEntries ; all minimal entries now have value 1. All other slots will be disabled (move set to 0)
;>     if mem[wEnemyMonMoves + i] == 0:
;>         wBuffer[i] = 0
	ld a, [de]
	and a
	jr nz, .moveExisting
	ld [hl], a
.moveExisting
;>     if wBuffer[i] != 1:
;>         wBuffer[i] = 0
	ld a, [hl]
	dec a
	jr z, .slotWithMinimalValue
	xor a
	ld [hli], a     ; disable move slot
	jr .next
.slotWithMinimalValue
;>     else:
;>         wBuffer[i] = mem[wEnemyMonMoves + i]
	ld a, [de]
	ld [hli], a     ; enable move slot
.next
	inc de
	dec c
	jr nz, .filterMinimalEntries
;> return wBuffer + 0
	ld hl, wBuffer    ; use created temporary array as move set
	ret
.useOriginalMoveSet
	ld hl, wEnemyMonMoves    ; use original move set
	ret

;@ path: engine/battle/trainer_ai
AIMoveChoiceModificationFunctionPointers:
	dw AIMoveChoiceModification1
	dw AIMoveChoiceModification2
	dw AIMoveChoiceModification3
	dw AIMoveChoiceModification4 ; unused, does nothing

; discourages moves that cause no damage but only a status ailment if player's mon already has one
;@ path: engine/battle/trainer_ai
;@ def AIMoveChoiceModification1()
;@ Rule 1: if the player's mon already has a status, strongly discourage (+5) moves that only inflict one.
;@ test: hLoadedROMBank = 0x0E
AIMoveChoiceModification1:
;> if mem[wBattleMonStatus] == 0:
;>     return
	ld a, [wBattleMonStatus]
	and a
	ret z ; return if no status ailment on player's mon
;>@lp for i in range(NUM_MOVES):
	ld hl, wBuffer - 1 ; temp move selection array (-1 byte offset)
	ld de, wEnemyMonMoves ; enemy moves
	ld b, NUM_MOVES + 1
.nextMove
;=@lp
	dec b
	ret z ; processed all 4 moves
	inc hl
;>     move = mem[wEnemyMonMoves + i]
	ld a, [de]
;>     if move == 0:
;>         return
	and a
	ret z ; no more moves in move set
;=@lp
	inc de
;>     ReadMove(move)
	call ReadMove
;>     if wEnemyMovePower == 0:                      # a move without power
	ld a, [wEnemyMovePower]
	and a
	jr nz, .nextMove
;>         effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
	push hl
	push de
	push bc
;>         _, _, found = IsInArray(effect, StatusAilmentMoveEffects, 1)   # one that only inflicts a status?
	ld hl, StatusAilmentMoveEffects
	ld de, 1
	call IsInArray
	pop bc
	pop de
	pop hl
;>         if found:
;>             wBuffer[i] = wBuffer[i] + 5 & 0xFF    # heavily discouraged
	jr nc, .nextMove
	ld a, [hl]
	add $5 ; heavily discourage move
	ld [hl], a
	jr .nextMove

;@ path: engine/battle/trainer_ai
StatusAilmentMoveEffects:
	db EFFECT_01 ; unused sleep effect
	db SLEEP_EFFECT
	db POISON_EFFECT
	db PARALYZE_EFFECT
	db -1 ; end

; slightly encourage moves with specific effects.
; in particular, stat-modifying moves and other move effects
; that fall in-between
;@ path: engine/battle/trainer_ai
;@ def AIMoveChoiceModification2()
;@ Rule 2: on the trainer's second turn (wAILayer2Encouragement = 1), slightly encourage (-1) the moves that raise
;@ the user's stats or lower the target's.
;@ test: hLoadedROMBank = 0x0E
AIMoveChoiceModification2:
;> if wAILayer2Encouragement != 1:
;>     return
	ld a, [wAILayer2Encouragement]
	cp $1
	ret nz
;>@lp for i in range(NUM_MOVES):
	ld hl, wBuffer - 1 ; temp move selection array (-1 byte offset)
	ld de, wEnemyMonMoves ; enemy moves
	ld b, NUM_MOVES + 1
.nextMove
;=@lp
	dec b
	ret z ; processed all 4 moves
	inc hl
;>     move = mem[wEnemyMonMoves + i]
	ld a, [de]
;>     if move == 0:
;>         return
	and a
	ret z ; no more moves in move set
;=@lp
	inc de
;>     ReadMove(move)
	call ReadMove
;>     effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
;>     prefer = ATTACK_UP1_EFFECT <= effect < BIDE_EFFECT          # raises a stat of the user
	cp ATTACK_UP1_EFFECT
	jr c, .nextMove
	cp BIDE_EFFECT
	jr c, .preferMove
;>     prefer = prefer or ATTACK_UP2_EFFECT <= effect < POISON_EFFECT
	cp ATTACK_UP2_EFFECT
	jr c, .nextMove
	cp POISON_EFFECT
	jr c, .preferMove
	jr .nextMove
.preferMove
;>     if prefer:
;>         wBuffer[i] = wBuffer[i] - 1 & 0xFF        # slightly encouraged
	dec [hl] ; slightly encourage this move
	jr .nextMove

; encourages moves that are effective against the player's mon (even if non-damaging).
; discourage damaging moves that are ineffective or not very effective against the player's mon,
; unless there's no damaging move that deals at least neutral damage
;@ path: engine/battle/trainer_ai
;@ def AIMoveChoiceModification3()
;@ Rule 3: slightly encourage (-1) super effective moves, and slightly discourage (+1) not very effective ones if
;@ there is a better move: Super Fang, a fixed-damage move, Fly, or a damaging move of another type.
;@ test: hLoadedROMBank = 0x0E
AIMoveChoiceModification3:
;>@lp for i in range(NUM_MOVES):
	ld hl, wBuffer - 1 ; temp move selection array (-1 byte offset)
	ld de, wEnemyMonMoves ; enemy moves
	ld b, NUM_MOVES + 1
.nextMove
;=@lp
	dec b
	ret z ; processed all 4 moves
	inc hl
;>     move = mem[wEnemyMonMoves + i]
	ld a, [de]
;>     if move == 0:
;>         return
	and a
	ret z ; no more moves in move set
;=@lp
	inc de
;>     ReadMove(move)
	call ReadMove
;>@te     AIGetTypeEffectiveness()
	push hl
	push bc
	push de
	ld hl, AIGetTypeEffectiveness
	ld b, BANK(AIGetTypeEffectiveness)
	call Bankswitch
;=@te
	pop de
	pop bc
	pop hl
;>     if wTypeEffectiveness > 0x10:                 # super effective
	ld a, [wTypeEffectiveness]
	cp $10
	jr z, .nextMove
	jr c, .notEffectiveMove
;>         wBuffer[i] = wBuffer[i] - 1 & 0xFF        # slightly encouraged
	dec [hl] ; slightly encourage this move
	jr .nextMove
.notEffectiveMove ; discourages non-effective moves if better moves are available
;>     elif wTypeEffectiveness < 0x10:               # not very effective: is there a better move?
;>         own_type = wEnemyMoveType
	push hl
	push de
	push bc
	ld a, [wEnemyMoveType]
	ld d, a
;>         better = False
;>@j         for j in range(NUM_MOVES):
	ld hl, wEnemyMonMoves  ; enemy moves
	ld b, NUM_MOVES + 1
	ld c, $0
.loopMoves
;=@j
	dec b
	jr z, .done
;>             other = mem[wEnemyMonMoves + j]
	ld a, [hli]
;>             if other == 0:
;>                 break
	and a
	jr z, .done
;>             ReadMove(other)
	call ReadMove
;>             effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
;>             if effect in (SUPER_FANG_EFFECT, SPECIAL_DAMAGE_EFFECT, FLY_EFFECT):   # fixed damage, or Fly
;>@bf                 better = True
;>                 break
	cp SUPER_FANG_EFFECT
	jr z, .betterMoveFound ; Super Fang is considered to be a better move
	cp SPECIAL_DAMAGE_EFFECT
	jr z, .betterMoveFound ; any special damage moves are considered to be better moves
	cp FLY_EFFECT
	jr z, .betterMoveFound ; Fly is considered to be a better move
;>             if wEnemyMoveType != own_type:        # a damaging move of another type
	ld a, [wEnemyMoveType]
	cp d
	jr z, .loopMoves
;>                 better = wEnemyMovePower != 0
	ld a, [wEnemyMovePower]
	and a
;>                 if better:
;>                     break
	jr nz, .betterMoveFound ; damaging moves of a different type are considered to be better moves
	jr .loopMoves
.betterMoveFound
;=@bf
	ld c, a
.done
;>         if better:
	ld a, c
	pop bc
	pop de
	pop hl
	and a
	jr z, .nextMove
;>             wBuffer[i] = wBuffer[i] + 1 & 0xFF    # slightly discouraged
	inc [hl] ; slightly discourage this move
	jr .nextMove
;@ path: engine/battle/trainer_ai
;@ def AIMoveChoiceModification4()
;@ Rule 4: does nothing.
;@ test: hLoadedROMBank = 0x0E
AIMoveChoiceModification4:
;> return
	ret

;@ path: engine/battle/trainer_ai
;@ def ReadMove(move: a)
;@ Copy a move's data (Moves) to wEnemyMoveNum and the bytes after it; keeps hl, de and bc.
;@ test: hLoadedROMBank = 0x0E
ReadMove:
;> index = move - 1 & 0xFF                           # (hl, de and bc are kept)
	push hl
	push de
	push bc
	dec a
;> src = Moves + index * MOVE_LENGTH
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;> CopyData(src, addr(wEnemyMoveNum), MOVE_LENGTH)
	ld de, wEnemyMoveNum
	call CopyData
;> return
	pop bc
	pop de
	pop hl
	ret



