; formats a string at wMovesString that lists the moves at wMoves
;@ path: engine/battle/trainer_ai
;@ def FormatMovesString()
;@ The names of the moves in wMoves as one string in wMovesString, one per line; empty slots show "-".
;@ wNumMovesMinusOne ends up as the number of moves - 1.
;@ test: hLoadedROMBank = 0x0E
FormatMovesString:
;> dest = wMovesString + 0
;> n = 0
	ld hl, wMoves
	ld de, wMovesString
	ld b, $0
.printMoveNameLoop
;> while wMoves[n]:
	ld a, [hli]
	and a ; end of move list?
	jr z, .printDashLoop ; print dashes when no moves are left
;>     wNameListIndex = wMoves[n]
	push hl
	ld [wNameListIndex], a
;>     wPredefBank = BANK(MoveNames)
	ld a, BANK(MoveNames)
	ld [wPredefBank], a
;>     wNameListType = MOVE_NAME
	ld a, MOVE_NAME
	ld [wNameListType], a
;>     GetName()
	call GetName
;>     i = 0
	ld hl, wNameBuffer
.copyNameLoop
;>     while mem[wNameBuffer + i] != 0x50:           # '@'
	ld a, [hli]
	cp '@'
	jr z, .doneCopyingName
;>         mem[dest] = mem[wNameBuffer + i]
	ld [de], a
;>         dest += 1
;>         i += 1
	inc de
	jr .copyNameLoop
.doneCopyingName
;>     wNumMovesMinusOne = n
	ld a, b
	ld [wNumMovesMinusOne], a
;>     n += 1
	inc b
;>     mem[dest] = 0x4E                              # <NEXT>
	ld a, '<NEXT>'
	ld [de], a
;>     dest += 1
	inc de
	pop hl
;>     if n == NUM_MOVES:
;>         break
	ld a, b
	cp NUM_MOVES
	jr z, .done
	jr .printMoveNameLoop
.printDashLoop
;> while n < NUM_MOVES:                              # the empty slots
;>     mem[dest] = 0xE3                              # '-'
	ld a, '-'
	ld [de], a
;>     dest += 1
	inc de
;>     n += 1
	inc b
;>     if n == NUM_MOVES:
;>         break
	ld a, b
	cp NUM_MOVES
	jr z, .done
;>     mem[dest] = 0x4E                              # <NEXT>
	ld a, '<NEXT>'
	ld [de], a
;>     dest += 1
	inc de
	jr .printDashLoop
.done
;> mem[dest] = 0x50                                  # '@'
	ld a, '@'
	ld [de], a
	ret

; XXX this is called in a few places, but it doesn't appear to do anything useful
;@ path: engine/battle/trainer_ai
;@ def InitList()
;@ Set up the list pointer, name list type and item prices for the list kind in wInitListType. Only the name list
;@ type is still used later.
;@ test: hLoadedROMBank = 0x0E
InitList:
;> kind = wInitListType
	ld a, [wInitListType]
;> if kind == INIT_ENEMYOT_LIST:
	cp INIT_ENEMYOT_LIST
	jr nz, .notEnemy
;>     items, names, name_type = addr(wEnemyPartyCount), wEnemyMonOT + 0, ENEMYOT_NAME
	ld hl, wEnemyPartyCount
	ld de, wEnemyMonOT
	ld a, ENEMYOT_NAME
	jr .done
.notEnemy
;> elif kind == INIT_PLAYEROT_LIST:
	cp INIT_PLAYEROT_LIST
	jr nz, .notPlayer
;>     items, names, name_type = addr(wPartyCount), wPartyMonOT + 0, PLAYEROT_NAME
	ld hl, wPartyCount
	ld de, wPartyMonOT
	ld a, PLAYEROT_NAME
	jr .done
.notPlayer
;> elif kind == INIT_MON_LIST:
	cp INIT_MON_LIST
	jr nz, .notMonster
;>     items, names, name_type = wItemList + 0, MonsterNames, MONSTER_NAME
	ld hl, wItemList
	ld de, MonsterNames
	ld a, MONSTER_NAME
	jr .done
.notMonster
;> elif kind == INIT_BAG_ITEM_LIST:
	cp INIT_BAG_ITEM_LIST
	jr nz, .notBag
;>     items, names, name_type = addr(wNumBagItems), ItemNames, ITEM_NAME
	ld hl, wNumBagItems
	ld de, ItemNames
	ld a, ITEM_NAME
	jr .done
.notBag
;> else:
;>     items, names, name_type = wItemList + 0, ItemNames, ITEM_NAME
	ld hl, wItemList
	ld de, ItemNames
	ld a, ITEM_NAME
.done
;> wNameListType = name_type
	ld [wNameListType], a
;> wListPointer[0], wListPointer[1] = lo(items), hi(items)
	ld a, l
	ld [wListPointer], a
	ld a, h
	ld [wListPointer + 1], a
;> wUnusedNamePointer[0], wUnusedNamePointer[1] = lo(names), hi(names)
	ld a, e
	ld [wUnusedNamePointer], a
	ld a, d
	ld [wUnusedNamePointer + 1], a
;> wItemPrices[0], wItemPrices[1] = lo(ItemPrices), hi(ItemPrices)
	ld bc, ItemPrices
	ld a, c
	ld [wItemPrices], a
	ld a, b
	ld [wItemPrices + 1], a
	ret

; get species of mon e in list [wMonDataLocation] for LoadMonData
;@ path: engine/battle/trainer_ai
;@ def GetMonSpecies(n: e)
;@ wCurPartySpecies = the species of mon n in the list wMonDataLocation names: the party, the enemy's party or the
;@ box.
;@ test: hLoadedROMBank = 0x0E
GetMonSpecies:
;> if wMonDataLocation == 0:
;>     species = wPartySpecies
	ld hl, wPartySpecies
	ld a, [wMonDataLocation]
	and a
	jr z, .getSpecies
;> elif wMonDataLocation == 1:
	dec a
	jr z, .enemyParty
;>     species = wEnemyPartySpecies
;> else:
;>     species = wBoxSpecies
	ld hl, wBoxSpecies
	jr .getSpecies
.enemyParty
	ld hl, wEnemyPartySpecies
.getSpecies
;> wCurPartySpecies = mem[species + n]
	ld d, 0
	add hl, de
	ld a, [hl]
	ld [wCurPartySpecies], a
	ret

;@ path: engine/battle/trainer_ai
;@ def ReadTrainer()
;@ Build the enemy trainer's party from TrainerDataPointers (class wCurOpponent, trainer wTrainerNo). The data is
;@ either one level for the whole team followed by species, or $FF followed by level/species pairs; teams of the
;@ second kind can get a special move: a gym leader's lone move (LoneMoves, by wLoneAttackNo), a class's team move
;@ (TeamMoves, on the fifth mon), or the champion's Sky Attack and starter move. Then the prize money is the base
;@ money times the level of the last mon. Nothing happens in a link battle.
;@ test: wLinkState = 0; wCurOpponent = rand(OPP_ID_OFFSET + 1, OPP_ID_OFFSET + 47); wTrainerNo = rand(1, 3); wLoneAttackNo = rand(0, 8); hLoadedROMBank = 0x0E
ReadTrainer:

; don't change any moves in a link battle
;> if wLinkState:
;>     return
	ld a, [wLinkState]
	and a
	ret nz

; set [wEnemyPartyCount] to 0, [wEnemyPartySpecies] to FF
; XXX first is total enemy pokemon?
; XXX second is species of first pokemon?
;> wEnemyPartyCount = 0
;> wEnemyPartySpecies[0] = 0xFF
	ld hl, wEnemyPartyCount
	xor a
	ld [hli], a
	dec a
	ld [hl], a

; get the pointer to trainer data for this class
;> index = wCurOpponent - (OPP_ID_OFFSET + 1) & 0xFF # the trainer class
	ld a, [wCurOpponent]
	sub OPP_ID_OFFSET + 1 ; convert value from pokemon to trainer
;> entry = TrainerDataPointers + (2 * index & 0xFF)
	add a
	ld hl, TrainerDataPointers
	ld c, a
	ld b, 0
	add hl, bc ; hl points to trainer class
;> data = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> for _ in range(wTrainerNo - 1 & 0xFF):   # skip the trainers before
	ld a, [wTrainerNo]
	ld b, a
; At this point b contains the trainer number,
; and hl points to the trainer class.
; Our next task is to iterate through the trainers,
; decrementing b each time, until we get to the right one.
.CheckNextTrainer
	dec b
	jr z, .IterateTrainer
.SkipTrainer
;>     while mem[data] != 0:
;>         data += 1
	ld a, [hli]
	and a
	jr nz, .SkipTrainer
;>     data += 1                                     # past the 0
	jr .CheckNextTrainer

; if the first byte of trainer data is FF,
; - each pokemon has a specific level
;      (as opposed to the whole team being of the same level)
; - if [wLoneAttackNo] != 0, one pokemon on the team has a special move
; else the first byte is the level of every pokemon on the team
.IterateTrainer
;> first = mem[data]
;> data += 1
	ld a, [hli]
;> if first != 0xFF:                                 # one level for the whole team
	cp $FF ; is the trainer special?
	jr z, .SpecialTrainer ; if so, check for special moves
;>     wCurEnemyLevel = first
	ld [wCurEnemyLevel], a
.LoopTrainerData
;>     while mem[data]:
	ld a, [hli]
	and a ; have we reached the end of the trainer data?
	jr z, .FinishUp
;>         wCurPartySpecies = mem[data]
;>         data += 1
	ld [wCurPartySpecies], a
;>         wMonDataLocation = ENEMY_PARTY_DATA
;>         AddPartyMon()
	ld a, ENEMY_PARTY_DATA
	ld [wMonDataLocation], a
	push hl
	call AddPartyMon
	pop hl
	jr .LoopTrainerData
.SpecialTrainer
; if this code is being run:
; - each pokemon has a specific level
;      (as opposed to the whole team being of the same level)
; - if [wLoneAttackNo] != 0, one pokemon on the team has a special move
;> else:                                   # $FF: a level for each mon
;>     while mem[data]:
;>         wCurEnemyLevel = mem[data]
	ld a, [hli]
	and a ; have we reached the end of the trainer data?
	jr z, .AddLoneMove
	ld [wCurEnemyLevel], a
;>         wCurPartySpecies = mem[data + 1]
;>         data += 2
	ld a, [hli]
	ld [wCurPartySpecies], a
;>         wMonDataLocation = ENEMY_PARTY_DATA
;>         AddPartyMon()
	ld a, ENEMY_PARTY_DATA
	ld [wMonDataLocation], a
	push hl
	call AddPartyMon
	pop hl
	jr .SpecialTrainer
.AddLoneMove
; does the trainer have a single monster with a different move?
;>     if wLoneAttackNo:                    # a gym leader: Brock 1, Misty 2, Erika 4, ...
	ld a, [wLoneAttackNo] ; Brock is 01, Misty is 02, Erika is 04, etc
	and a
	jr z, .AddTeamMove
;>         entry = LoneMoves + (2 * (wLoneAttackNo - 1) & 0xFF)
	dec a
	add a
	ld c, a
	ld b, 0
	ld hl, LoneMoves
	add hl, bc
;>         mon, move = mem[entry], mem[entry + 1]
	ld a, [hli]
	ld d, [hl]
;>         mem[wEnemyMon1Moves + 2 + mon * PARTYMON_STRUCT_LENGTH] = move   # that mon's third move
	ld hl, wEnemyMon1Moves + 2
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld [hl], d
	jr .FinishUp
.AddTeamMove
; check if our trainer's team has special moves

; get trainer class number
;>     else:
;>         trainer_class = wCurOpponent - OPP_ID_OFFSET & 0xFF
;>         entry = TeamMoves
	ld a, [wCurOpponent]
	sub OPP_ID_OFFSET
	ld b, a
	ld hl, TeamMoves

; iterate through entries in TeamMoves, checking each for our trainer class
.IterateTeamMoves
;>         while True:
;>             found = mem[entry]
	ld a, [hli]
;>             if found == trainer_class:
;>                 break
	cp b
	jr z, .GiveTeamMoves ; is there a match?
;>             entry += 2
	inc hl ; if not, go to the next entry
;>             if found == 0xFF:                     # the end of the list
;>                 break
	inc a
	jr nz, .IterateTeamMoves

; no matches found. is this trainer champion rival?
;>         if found != trainer_class:       # no match: is this the champion rival?
;>             champion = trainer_class == RIVAL3
	ld a, b
	cp RIVAL3
	jr z, .ChampionRival
	jr .FinishUp ; nope
.GiveTeamMoves
;>         else:                            # the fifth mon's third move
;>             champion = False
;>             mem[wEnemyMon5Moves + 2] = mem[entry + 1]
	ld a, [hl]
	ld [wEnemyMon5Moves + 2], a
	jr .FinishUp
.ChampionRival ; give moves to his team

; pidgeot
;>         if champion:
;>             mem[wEnemyMon1Moves + 2] = SKY_ATTACK   # Pidgeot
	ld a, SKY_ATTACK
	ld [wEnemyMon1Moves + 2], a

; starter
;>             if wRivalStarter == STARTER3:
;>                 move = MEGA_DRAIN
	ld a, [wRivalStarter]
	cp STARTER3
	ld b, MEGA_DRAIN
	jr z, .GiveStarterMove
;>             elif wRivalStarter == STARTER1:
;>                 move = FIRE_BLAST
	cp STARTER1
	ld b, FIRE_BLAST
	jr z, .GiveStarterMove
;>             else:
;>                 move = BLIZZARD          # Squirtle's line
	ld b, BLIZZARD ; must be squirtle
.GiveStarterMove
;>             mem[wEnemyMon6Moves + 2] = move
	ld a, b
	ld [wEnemyMon6Moves + 2], a
.FinishUp
; clear wAmountMoneyWon addresses
;> wAmountMoneyWon[0] = 0
	xor a
	ld de, wAmountMoneyWon
	ld [de], a
;> wAmountMoneyWon[1] = 0
	inc de
	ld [de], a
;> wAmountMoneyWon[2] = 0
	inc de
	ld [de], a
;> left = wCurEnemyLevel                    # the prize: base money times the level
	ld a, [wCurEnemyLevel]
	ld b, a
.LastLoop
; update wAmountMoneyWon addresses (money to win) based on enemy's level
;> while True:
;>     predef(AddBCDPredef, hl=wTrainerBaseMoney + 1, de=wAmountMoneyWon + 2, bc=left << 8 | 2)
	ld hl, wTrainerBaseMoney + 1
	ld c, 2 ; wAmountMoneyWon is a 3-byte number
	push bc
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
	pop bc
;>     left = left - 1 & 0xFF
	inc de
	inc de
	dec b
;>     if left == 0:
;>         break
	jr nz, .LastLoop ; repeat wCurEnemyLevel times
	ret

; unique moves for gym leaders
; this is not automatic! you have to write the index you want to [wLoneAttackNo]
; first. e.g., erika's script writes 4 to [wLoneAttackNo] to get mega drain,
; the fourth entry in the list.
;@ path: engine/battle/trainer_ai
LoneMoves:
	; pokemon index, move to give nth pokemon
	db 1, BIDE
	db 1, BUBBLEBEAM
	db 2, THUNDERBOLT
	db 2, MEGA_DRAIN
	db 3, TOXIC
	db 3, PSYWAVE
	db 3, FIRE_BLAST
	db 4, FISSURE

; unique moves for elite 4
; all trainers in this class are given this move automatically
; (unrelated to LoneMoves)
;@ path: engine/battle/trainer_ai
TeamMoves:
	; trainer, move
	db LORELEI, BLIZZARD
	db BRUNO,   FISSURE
	db AGATHA,  TOXIC
	db LANCE,   BARRIER
	db -1 ; end

