;@ path: engine/battle/trainer_ai
;@ def TrainerAI() -> carry
;@ Give the enemy trainer's class AI (TrainerAIPointers) a chance to use an item or switch instead of attacking,
;@ with a random number. Each class has a number of uses per battle (wAICount, $FF until the first use). Carry if
;@ the AI acted. Not for wild or link battles.
;@ test: hLoadedROMBank = 0x0E
TrainerAI:
;> if wIsInBattle == 1:                              # a wild battle
;>     return False
	and a
	ld a, [wIsInBattle]
	dec a
	ret z ; if not a trainer, we're done here
;> if wLinkState == LINK_STATE_BATTLING:
;>     return False
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ret z ; if in a link battle, we're done as well
;> index = wTrainerClass - 1 & 0xFF
	ld a, [wTrainerClass] ; what trainer class is this?
	dec a
;> entry = TrainerAIPointers + 3 * index
	ld c, a
	ld b, 0
	ld hl, TrainerAIPointers
	add hl, bc
	add hl, bc
	add hl, bc
;> if wAICount == 0:
;>     return False
	ld a, [wAICount]
	and a
	ret z ; if no AI uses left, we're done here
;> if wAICount == 0xFF:
	inc hl
	inc a
	jr nz, .getpointer
;>     wAICount = mem[entry]
	dec hl
	ld a, [hli]
	ld [wAICount], a
.getpointer
;> routine = mem16[entry + 1]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> r = Random(False)
	call Random
;> return call(routine)                              # the class's routine, with r in a
	jp hl

;@ path: engine/battle/trainer_ai
TrainerAIPointers:
	; one entry per trainer class
	; first byte, number of times (per Pokémon) it can occur
	; next two bytes, pointer to AI subroutine for trainer class
	; subroutines are defined in engine/battle/trainer_ai.asm
	; YOUNGSTER
	db 3
	dw GenericAI
	; BUG_CATCHER
	db 3
	dw GenericAI
	; LASS
	db 3
	dw GenericAI
	; SAILOR
	db 3
	dw GenericAI
	; JR_TRAINER_M
	db 3
	dw GenericAI
