;@ path: engine/battle/trainer_ai
;@ def AIUseFullRestore() -> carry
;@ The trainer uses a Full Restore: status cured and HP back to the maximum, with the HP bar sliding up.
;@ test: mem[0xCFE8] = rand(0, 5); hLoadedROMBank = 0x0E
AIUseFullRestore:
;> AICureStatus()
	call AICureStatus
;> wAIItem = FULL_RESTORE
	ld a, FULL_RESTORE
	ld [wAIItem], a
;> # the HP bar keeps its numbers little-endian
;> wHPBarOldHP[0] = mem[wEnemyMonHP + 1]
	ld de, wHPBarOldHP
	ld hl, wEnemyMonHP + 1
	ld a, [hld]
	ld [de], a
;> wHPBarOldHP[1] = mem[wEnemyMonHP]
	inc de
	ld a, [hl]
	ld [de], a
	inc de
;> wHPBarNewHP[0] = wHPBarMaxHP[0] = mem[wEnemyMonHP + 1] = mem[wEnemyMonMaxHP + 1]   # full HP
	ld hl, wEnemyMonMaxHP + 1
	ld a, [hld]
	ld [de], a
	inc de
	ld [wHPBarMaxHP], a
	ld [wEnemyMonHP + 1], a
;> wHPBarNewHP[1] = wHPBarMaxHP[1] = mem[wEnemyMonHP] = mem[wEnemyMonMaxHP]
	ld a, [hl]
	ld [de], a
	ld [wHPBarMaxHP+1], a
	ld [wEnemyMonHP], a
;> return AIPrintItemUseAndUpdateHPBar()
	jr AIPrintItemUseAndUpdateHPBar

;@ path: engine/battle/trainer_ai
