;@ path: engine/battle/trainer_ai
;@ def AIRecoverHP(item: a, amount: b) -> carry
;@ The trainer uses a healing item: the enemy's mon gets `amount` HP, up to its maximum, with the HP bar sliding up.
;@ test: hLoadedROMBank = 0x0E
AIRecoverHP:
; heal b HP and print "trainer used $(a) on pokemon!"
;> wAIItem = item
	ld [wAIItem], a
;> old = mem[wEnemyMonHP] << 8 | mem[wEnemyMonHP + 1]
;> wHPBarOldHP[0] = lo(old)
	ld hl, wEnemyMonHP + 1
	ld a, [hl]
	ld [wHPBarOldHP], a
;> new = old + amount & 0xFFFF
;> mem[wEnemyMonHP + 1] = wHPBarNewHP[0] = lo(new)
	add b
	ld [hld], a
	ld [wHPBarNewHP], a
;> wHPBarOldHP[1] = wHPBarNewHP[1] = hi(old)
	ld a, [hl]
	ld [wHPBarOldHP+1], a
	ld [wHPBarNewHP+1], a
;> if hi(new) != hi(old):                   # a carry into the high byte
;>     mem[wEnemyMonHP] = wHPBarNewHP[1] = hi(new)
	jr nc, .next
	inc a
	ld [hl], a
	ld [wHPBarNewHP+1], a
.next
;> top = mem[wEnemyMonMaxHP] << 8 | mem[wEnemyMonMaxHP + 1]
	inc hl
	ld a, [hld]
	ld b, a
	ld de, wEnemyMonMaxHP + 1
	ld a, [de]
	dec de
;> wHPBarMaxHP[0] = lo(top)
	ld [wHPBarMaxHP], a
;> low = lo(top) - lo(new)                          # top minus new, low bytes first
	sub b
;> wHPBarMaxHP[1] = hi(top)
	ld a, [hli]
	ld b, a
	ld a, [de]
	ld [wHPBarMaxHP+1], a
;> if new > top:                                    # (the high bytes with the borrow)
	sbc b
	jr nc, AIPrintItemUseAndUpdateHPBar
;>     new = top
;>     mem[wEnemyMonHP + 1] = wHPBarNewHP[0] = lo(new)
	inc de
	ld a, [de]
	dec de
	ld [hld], a
	ld [wHPBarNewHP], a
;>     mem[wEnemyMonHP] = wHPBarNewHP[1] = hi(new)
	ld a, [de]
	ld [hl], a
	ld [wHPBarNewHP+1], a
;> return AIPrintItemUseAndUpdateHPBar()
	; fallthrough

;@ path: engine/battle/trainer_ai
;@ def AIPrintItemUseAndUpdateHPBar() -> carry
;@ "<trainer> used <item>!", the enemy's HP bar slides to its new value, and one AI use is spent.
;@ test: hLoadedROMBank = 0x0E
AIPrintItemUseAndUpdateHPBar:
;> AIPrintItemUse_()
	call AIPrintItemUse_
;> bar = coord(2, 2)                                # the enemy's bar
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
;> wHPBarType = 0
	xor a
	ld [wHPBarType], a
;> predef(UpdateHPBar2, hl=bar)
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;> return DecrementAICount()
	jp DecrementAICount

;@ path: engine/battle/trainer_ai
;@ def AISwitchIfEnoughMons() -> carry
;@ The trainer withdraws its mon if at least two of its mons (the active one included) can still fight.
;@ test: wEnemyPartyCount = rand(1, 6); hLoadedROMBank = 0x0E
AISwitchIfEnoughMons:
; enemy trainer switches if there are 2 or more unfainted mons in party
;>@al alive = 0
;>@lp for i in range(wEnemyPartyCount or 256):
	ld a, [wEnemyPartyCount]
	ld c, a
	ld hl, wEnemyMon1HP

;=@al
	ld d, 0 ; keep count of unfainted monsters

	; count how many monsters haven't fainted yet
.loop
;>     hp = wEnemyMon1HP + i * PARTYMON_STRUCT_LENGTH & 0xFFFF
;>     if mem[hp] or mem[hp + 1]:
	ld a, [hli]
	ld b, a
	ld a, [hld]
	or b
	jr z, .Fainted ; has monster fainted?
;>         alive += 1
	inc d
.Fainted
;=@lp
	push bc
	ld bc, PARTYMON_STRUCT_LENGTH
	add hl, bc
	pop bc
	dec c
	jr nz, .loop

;> if alive & 0xFF >= 2:
;>     return SwitchEnemyMon()
	ld a, d ; how many available monsters are there?
	cp 2    ; don't bother if only 1
	jp nc, SwitchEnemyMon
;> return False
	and a
	ret

;@ path: engine/battle/trainer_ai
;@ def SwitchEnemyMon() -> carry
;@ Withdraw the enemy's mon - its HP and status go back to its party entry - and send out the next one. The player
;@ doesn't get to switch in answer. Carry unless in a link battle.
;@ test: hLoadedROMBank = 0x0E
SwitchEnemyMon:

; prepare to withdraw the active monster: copy HP, party pos, and status to roster

;> entry = wEnemyMon1HP + mem[wEnemyMonPartyPos] * PARTYMON_STRUCT_LENGTH
	ld a, [wEnemyMonPartyPos]
	ld hl, wEnemyMon1HP
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> CopyData(wEnemyMonHP, entry, MON_STATUS + 1 - MON_HP)  # HP, party position, status
	ld d, h
	ld e, l
	ld hl, wEnemyMonHP
	ld bc, MON_STATUS + 1 - MON_HP ; also copies party pos in-between HP and status
	call CopyData

;> PrintText(AIBattleWithdrawText)
	ld hl, AIBattleWithdrawText
	call PrintText

	; This wFirstMonsNotOutYet variable is abused to prevent the player from
	; switching in a new mon in response to this switch.
;> wFirstMonsNotOutYet = 1
	ld a, 1
	ld [wFirstMonsNotOutYet], a
;> Bankswitch(BANK(EnemySendOut), EnemySendOut)
	ld hl, EnemySendOut
	ld b, BANK(EnemySendOut)
	call Bankswitch
;> wFirstMonsNotOutYet = 0
	xor a
	ld [wFirstMonsNotOutYet], a

;> return wLinkState != LINK_STATE_BATTLING
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ret z
	scf
	ret

;@ path: engine/battle/trainer_ai
AIBattleWithdrawText:
	db TX_FAR
	dw _AIBattleWithdrawText
	db BANK(_AIBattleWithdrawText)
	db TX_END

;@ path: engine/battle/trainer_ai
;@ def AIUseFullHeal() -> carry
