;@ test: skip waits for the sound
AIUseFullHeal:
;> AIPlayRestoringSFX()
	call AIPlayRestoringSFX
;> AICureStatus()
	call AICureStatus
;> return AIPrintItemUse(FULL_HEAL)
	ld a, FULL_HEAL
	jp AIPrintItemUse

;@ path: engine/battle/trainer_ai
;@ def AICureStatus()
;@ Cure the enemy's active mon, in battle and in its party, and end the growing Toxic damage.
;@ test: mem[0xCFE8] = rand(0, 5); hLoadedROMBank = 0x0E
AICureStatus:
; cures the status of enemy's active pokemon
;> party_status = wEnemyMon1Status + mem[wEnemyMonPartyPos] * PARTYMON_STRUCT_LENGTH
	ld a, [wEnemyMonPartyPos]
	ld hl, wEnemyMon1Status
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> mem[party_status] = 0
	xor a
	ld [hl], a ; clear status in enemy team roster
;> mem[wEnemyMonStatus] = 0
	ld [wEnemyMonStatus], a ; clear status of active enemy
;> wEnemyBattleStatus3 &= ~(1 << BADLY_POISONED) & 0xFF
	ld hl, wEnemyBattleStatus3
	res BADLY_POISONED, [hl]
	ret

;@ path: engine/battle/trainer_ai
;@ def AIUseXAccuracy() -> carry
;@ The trainer uses an X Accuracy (no trainer does).
;@ test: skip waits for the sound
AIUseXAccuracy: ; unreferenced
