	call AIPlayRestoringSFX
;> wEnemyBattleStatus2 |= 1 << USING_X_ACCURACY
	ld hl, wEnemyBattleStatus2
	set USING_X_ACCURACY, [hl]
;> return AIPrintItemUse(X_ACCURACY)
	ld a, X_ACCURACY
	jp AIPrintItemUse

