;@ path: engine/battle/trainer_ai
;@ def AICheckIfHPBelowFraction(fraction: a) -> carry
;@ Carry if the enemy's mon has less than 1/fraction of its maximum HP.
;@ test: fraction = rand(1, 10); hLoadedROMBank = 0x0E
AICheckIfHPBelowFraction:
; return carry if enemy trainer's current HP is below 1 / a of the maximum
;> hDivisor = fraction
	ldh [hDivisor], a
;> hDividend[0], hDividend[1] = mem[wEnemyMonMaxHP], mem[wEnemyMonMaxHP + 1]
	ld hl, wEnemyMonMaxHP
	ld a, [hli]
	ldh [hDividend], a
	ld a, [hl]
	ldh [hDividend + 1], a
;> Divide(2)
	ld b, 2
	call Divide
;> limit = hQuotient[2] << 8 | hQuotient[3]
	ldh a, [hQuotient + 3]
	ld c, a
	ldh a, [hQuotient + 2]
	ld b, a
;> hp = mem[wEnemyMonHP] << 8 | mem[wEnemyMonHP + 1]
	ld hl, wEnemyMonHP + 1
	ld a, [hld]
	ld e, a
	ld a, [hl]
	ld d, a
;> return hp < limit
	ld a, d
	sub b
	ret nz
	ld a, e
	sub c
	ret

;@ path: engine/battle/trainer_ai
;@ def AIUseXAttack() -> carry
;@ The trainer uses an X Attack.
;@ test: hLoadedROMBank = 0x0E
AIUseXAttack:
;> return AIIncreaseStat(X_ATTACK, ATTACK_UP1_EFFECT)
	ld b, ATTACK_UP1_EFFECT
	ld a, X_ATTACK
	jr AIIncreaseStat

;@ path: engine/battle/trainer_ai
;@ def AIUseXDefend() -> carry
;@ The trainer uses an X Defend.
;@ test: hLoadedROMBank = 0x0E
AIUseXDefend:
;> return AIIncreaseStat(X_DEFEND, DEFENSE_UP1_EFFECT)
	ld b, DEFENSE_UP1_EFFECT
	ld a, X_DEFEND
	jr AIIncreaseStat

;@ path: engine/battle/trainer_ai
;@ def AIUseXSpeed() -> carry
;@ The trainer uses an X Speed.
;@ test: hLoadedROMBank = 0x0E
AIUseXSpeed:
;> return AIIncreaseStat(X_SPEED, SPEED_UP1_EFFECT)
	ld b, SPEED_UP1_EFFECT
	ld a, X_SPEED
	jr AIIncreaseStat

;@ path: engine/battle/trainer_ai
;@ def AIUseXSpecial() -> carry
;@ The trainer uses an X Special.
;@ test: hLoadedROMBank = 0x0E
AIUseXSpecial:
;> return AIIncreaseStat(X_SPECIAL, SPECIAL_UP1_EFFECT)
	ld b, SPECIAL_UP1_EFFECT
	ld a, X_SPECIAL
	; fallthrough

;@ path: engine/battle/trainer_ai
;@ def AIIncreaseStat(item: a, effect: b) -> carry
;@ The trainer uses a stat-raising item: "<trainer> used <item>!", then the enemy's move is briefly replaced by one
;@ with the item's animation and the stat-raising effect, and run.
;@ test: hLoadedROMBank = 0x0E
AIIncreaseStat:
;> wAIItem = item
	ld [wAIItem], a
;> AIPrintItemUse_()
	push bc
	call AIPrintItemUse_
	pop bc
;> saved_effect, saved_move = wEnemyMoveEffect, wEnemyMoveNum
	ld hl, wEnemyMoveEffect
	ld a, [hld]
	push af
	ld a, [hl]
	push af
	push hl
;> wEnemyMoveNum = XSTATITEM_DUPLICATE_ANIM
	ld a, XSTATITEM_DUPLICATE_ANIM
	ld [hli], a
;> wEnemyMoveEffect = effect
	ld [hl], b
;> Bankswitch(BANK(StatModifierUpEffect), StatModifierUpEffect)
	ld hl, StatModifierUpEffect
	ld b, BANK(StatModifierUpEffect)
	call Bankswitch
;> wEnemyMoveNum = saved_move
	pop hl
	pop af
	ld [hli], a
;> wEnemyMoveEffect = saved_effect
	pop af
	ld [hl], a
;> return DecrementAICount()
	jp DecrementAICount

;@ path: engine/battle/trainer_ai
;@ def AIPrintItemUse(item: a) -> carry
;@ "<trainer> used <item>!" and one AI use is spent.
;@ test: hLoadedROMBank = 0x0E
AIPrintItemUse:
;> wAIItem = item
	ld [wAIItem], a
;> AIPrintItemUse_()
	call AIPrintItemUse_
;> return DecrementAICount()
	jp DecrementAICount

;@ path: engine/battle/trainer_ai
;@ def AIPrintItemUse_()
;@ "<trainer> used <item>!" for the item in wAIItem.
;@ test: hLoadedROMBank = 0x0E
AIPrintItemUse_:
; print "x used [wAIItem] on z!"
;> wNamedObjectIndex = wAIItem
	ld a, [wAIItem]
	ld [wNamedObjectIndex], a
;> GetItemName()
	call GetItemName
;> PrintText(AIBattleUseItemText)
	ld hl, AIBattleUseItemText
	jp PrintText

;@ path: engine/battle/trainer_ai
AIBattleUseItemText:
	db TX_FAR
	dw _AIBattleUseItemText
	db BANK(_AIBattleUseItemText)
	db TX_END
;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def DrawAllPokeballs()
;@ The rows of balls for both parties next to the HUDs (only the player's in a wild battle).
DrawAllPokeballs:
;> LoadPartyPokeballGfx()
	call LoadPartyPokeballGfx
;> SetupOwnPartyPokeballs()
	call SetupOwnPartyPokeballs
;> if wIsInBattle == 1:                     # a wild battle: no enemy balls
;>     return
	ld a, [wIsInBattle]
	dec a
	ret z ; return if wild pokémon
;> SetupEnemyPartyPokeballs()
	jp SetupEnemyPartyPokeballs

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def DrawEnemyPokeballs()
;@ The row of balls for the enemy trainer's party.
DrawEnemyPokeballs:
;> LoadPartyPokeballGfx()
;> SetupEnemyPartyPokeballs()
	call LoadPartyPokeballGfx
	jp SetupEnemyPartyPokeballs

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def LoadPartyPokeballGfx()
;@ Load the four ball tiles (normal, statused, fainted, empty slot) into sprite tiles $31-$34.
LoadPartyPokeballGfx:
;> CopyVideoData(vSprites + 0x31 * TILE_SIZE, PokeballTileGraphics, BANK(PokeballTileGraphics),
;>               (PokeballTileGraphicsEnd - PokeballTileGraphics) // TILE_SIZE)
	ld de, PokeballTileGraphics
	ld hl, vSprites + TILE_SIZE * $31
	ld bc, ((BANK(PokeballTileGraphics)) & $ff) << 8 + (((PokeballTileGraphicsEnd - PokeballTileGraphics) / TILE_SIZE) & $ff)
	jp CopyVideoData

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def SetupOwnPartyPokeballs()
;@ The player's HUD frame and a row of balls for the party, as sprites from x = $60 rightwards, at y = $60.
;@ test: wPartyCount = rand(1, 6)
SetupOwnPartyPokeballs:
;> PlacePlayerHUDTiles()
	call PlacePlayerHUDTiles
;> SetupPokeballs(wPartyMons + 0, addr(wPartyCount))
	ld hl, wPartyMons
	ld de, wPartyCount
	call SetupPokeballs
;> wBaseCoordX = 0x60
;> wBaseCoordY = 0x60
	ld a, $60
	ld hl, wBaseCoordX
	ld [hli], a
	ld [hl], a
;> wHUDPokeballGfxOffsetX = 8
	ld a, 8
	ld [wHUDPokeballGfxOffsetX], a
;> WritePokeballOAMData(wShadowOAM + 0)
	ld hl, wShadowOAM
	jp WritePokeballOAMData

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def SetupEnemyPartyPokeballs()
;@ The enemy's HUD frame and a row of balls for its party, as sprites from x = $48 leftwards, at y = $20.
;@ test: wEnemyPartyCount = rand(1, 6)
SetupEnemyPartyPokeballs:
;> PlaceEnemyHUDTiles()
	call PlaceEnemyHUDTiles
;> SetupPokeballs(wEnemyMons + 0, addr(wEnemyPartyCount))
	ld hl, wEnemyMons
	ld de, wEnemyPartyCount
	call SetupPokeballs
;> wBaseCoordX = 0x48
	ld hl, wBaseCoordX
	ld a, $48
	ld [hli], a
;> wBaseCoordY = 0x20
	ld [hl], $20
;> wHUDPokeballGfxOffsetX = -8 & 0xFF
	ld a, -8
	ld [wHUDPokeballGfxOffsetX], a
;> WritePokeballOAMData(wShadowOAMSprite06)
	ld hl, wShadowOAMSprite06
	jp WritePokeballOAMData

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def SetupPokeballs(mons: hl, count: de)
;@ wBuffer = one ball tile per party slot: empty slots $34, the mons as PickPokeball chooses.
;@ test: mons = rand(0xD000, 0xDE00); count = rand_ram(1); mem[count] = rand(1, 6)
SetupPokeballs:
;> n = mem[count]
	ld a, [de]
	push af
;> for i in range(PARTY_LENGTH):                    # all empty balls first
	ld de, wBuffer
	ld c, PARTY_LENGTH
	ld a, $34 ; empty pokeball
.emptyloop
;>     wBuffer[i] = 0x34
	ld [de], a
	inc de
	dec c
	jr nz, .emptyloop
;>@ml for i in range(n or 256):
	pop af
	ld de, wBuffer
.monloop
;>     mons = PickPokeball(mons, wBuffer + i)
	push af
	call PickPokeball
;=@ml
	inc de
	pop af
	dec a
	jr nz, .monloop
	ret

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def PickPokeball(mon: hl, dest: de) -> hl
;@ The ball tile for a mon's party entry: $33 fainted, $32 with a status, else $31. Returns the next entry.
;@ test: mon = rand_ram(44); dest = rand_ram(1)
PickPokeball:
;> if mem[mon + 1] == 0 and mem[mon + 2] == 0:      # no HP left: fainted
	inc hl
	ld a, [hli]
	and a
	jr nz, .alive
	ld a, [hl]
	and a
;>@ft     tile = 0x33
	ld b, $33 ; crossed ball (fainted)
	jr z, .done_fainted
.alive
;> elif mem[mon + MON_STATUS]:
;>     tile = 0x32
	inc hl
	inc hl
	ld a, [hl] ; status
	and a
	ld b, $32 ; black ball (status)
	jr nz, .done
;> else:
;>     tile = 0x31
	dec b ; regular ball
	jr .done
.done_fainted
;=@ft
	inc hl
	inc hl
.done
;> mem[dest] = tile
	ld a, b
	ld [de], a
;> return mon + PARTYMON_STRUCT_LENGTH & 0xFFFF
	ld bc, PARTYMON_STRUCT_LENGTH - MON_STATUS
	add hl, bc ; next mon struct
	ret

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def WritePokeballOAMData(oam: hl)
;@ Six sprites for the balls in wBuffer, from (wBaseCoordX, wBaseCoordY), wHUDPokeballGfxOffsetX apart.
;@ test: oam = rand_ram(24)
WritePokeballOAMData:
;>@lp for i in range(PARTY_LENGTH):
	ld de, wBuffer
	ld c, PARTY_LENGTH
.loop
;>     mem[oam] = wBaseCoordY
	ld a, [wBaseCoordY]
	ld [hli], a
;>     mem[oam + 1] = wBaseCoordX
	ld a, [wBaseCoordX]
	ld [hli], a
;>     mem[oam + 2] = wBuffer[i]
	ld a, [de]
	ld [hli], a
;>     mem[oam + 3] = 0
;>     oam += 4
	xor a
	ld [hli], a
;>     wBaseCoordX = wBaseCoordX + wHUDPokeballGfxOffsetX & 0xFF
	ld a, [wBaseCoordX]
	ld b, a
	ld a, [wHUDPokeballGfxOffsetX]
	add b
	ld [wBaseCoordX], a
;=@lp
	inc de
	dec c
	jr nz, .loop
	ret

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def PlacePlayerHUDTiles()
;@ The frame under the player's mon's name: its tiles (PlayerBattleHUDGraphicsTiles) go to wHUDGraphicsTiles, then
;@ the line is drawn from (18, 10) leftwards.
PlacePlayerHUDTiles:
;> CopyData(PlayerBattleHUDGraphicsTiles, addr(wHUDGraphicsTiles), addr(wHUDGraphicsTilesEnd) - addr(wHUDGraphicsTiles))
	ld hl, PlayerBattleHUDGraphicsTiles
	ld de, wHUDGraphicsTiles
	ld bc, wHUDGraphicsTilesEnd - wHUDGraphicsTiles
	call CopyData
;> PlaceHUDTiles(coord(18, 10), -1 & 0xFFFF)       # leftwards
	ld hl, (10) * SCREEN_WIDTH + (18) + wTileMap
	ld de, -1
	jr PlaceHUDTiles

;@ path: engine/battle/draw_hud_pokeball_gfx
PlayerBattleHUDGraphicsTiles:
; The tile numbers for specific parts of the battle display for the player's pokemon
	db $73 ; unused ($73 is hardcoded into the routine that uses these bytes)
	db $77 ; lower-right corner tile of the HUD
	db $6F ; lower-left triangle tile of the HUD

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def PlaceEnemyHUDTiles()
;@ The frame under the enemy mon's name, drawn from (1, 2) rightwards.
PlaceEnemyHUDTiles:
;> CopyData(EnemyBattleHUDGraphicsTiles, addr(wHUDGraphicsTiles), addr(wHUDGraphicsTilesEnd) - addr(wHUDGraphicsTiles))
	ld hl, EnemyBattleHUDGraphicsTiles
	ld de, wHUDGraphicsTiles
	ld bc, wHUDGraphicsTilesEnd - wHUDGraphicsTiles
	call CopyData
;> PlaceHUDTiles(coord(1, 2), 1)                   # rightwards
	ld hl, (2) * SCREEN_WIDTH + (1) + wTileMap
	ld de, $1
	jr PlaceHUDTiles

;@ path: engine/battle/draw_hud_pokeball_gfx
EnemyBattleHUDGraphicsTiles:
; The tile numbers for specific parts of the battle display for the enemy
	db $73 ; unused ($73 is hardcoded in the routine that uses these bytes)
	db $74 ; lower-left corner tile of the HUD
	db $78 ; lower-right triangle tile of the HUD

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def PlaceHUDTiles(pos: hl, step: de)
;@ A HUD frame: tile $73 at pos, then on the row below the corner tile, eight line tiles ($76) and the triangle
;@ tile, going in the direction of step (1 or -1).
;@ test: pos = rand(0xC3B0, 0xC4C0); step = 1 if rand(0, 1) else 0xFFFF
PlaceHUDTiles:
;> mem[pos] = 0x73
	ld [hl], $73
;> pos += SCREEN_WIDTH
	ld bc, SCREEN_WIDTH
	add hl, bc
;> mem[pos] = wHUDCornerTile
	ld a, [wHUDCornerTile] ; leftmost tile
	ld [hl], a
;> for _ in range(8):
	ld a, 8
.loop
;>     pos = pos + step & 0xFFFF
	add hl, de
;>     mem[pos] = 0x76
	ld [hl], $76
	dec a
	jr nz, .loop
;> pos = pos + step & 0xFFFF
	add hl, de
;> mem[pos] = wHUDTriangleTile
	ld a, [wHUDTriangleTile] ; rightmost tile
	ld [hl], a
	ret

;@ path: engine/battle/draw_hud_pokeball_gfx
;@ def SetupPlayerAndEnemyPokeballs()
;@ Both parties' rows of balls in the middle of the screen, without HUD frames: the player's at y = $40, the
;@ enemy's at y = $68, both from x = $50 rightwards.
;@ test: wPartyCount = rand(1, 6); wEnemyPartyCount = rand(1, 6)
SetupPlayerAndEnemyPokeballs:
;> LoadPartyPokeballGfx()
	call LoadPartyPokeballGfx
;> SetupPokeballs(wPartyMons + 0, addr(wPartyCount))
	ld hl, wPartyMons
	ld de, wPartyCount
	call SetupPokeballs
;> wBaseCoordX = 0x50
	ld hl, wBaseCoordX
	ld a, $50
	ld [hli], a
;> wBaseCoordY = 0x40
	ld [hl], $40
;> wHUDPokeballGfxOffsetX = 8
	ld a, 8
	ld [wHUDPokeballGfxOffsetX], a
;> WritePokeballOAMData(wShadowOAM + 0)
	ld hl, wShadowOAM
	call WritePokeballOAMData
;> SetupPokeballs(wEnemyMons + 0, addr(wEnemyPartyCount))
	ld hl, wEnemyMons
	ld de, wEnemyPartyCount
	call SetupPokeballs
;> wBaseCoordX = 0x50
	ld hl, wBaseCoordX
	ld a, $50
	ld [hli], a
;> wBaseCoordY = 0x68
	ld [hl], $68
;> WritePokeballOAMData(wShadowOAMSprite06)
	ld hl, wShadowOAMSprite06
	jp WritePokeballOAMData

