	db $07, $07, $18, $1f, $38, $27, $78, $47, $78, $47, $f8, $87, $f8, $87, $f8, $87
	db $00, $00, $00, $00, $03, $03, $0f, $0c, $13, $1c, $13, $1c, $23, $3c, $23, $3c
	db $00, $00, $00, $00, $1f, $1f, $ff, $ff, $e0, $ff, $00, $ff, $03, $fc, $ff, $00
	db $07, $07, $1f, $1f, $78, $7f, $e0, $ff, $c0, $ff, $03, $fc, $1f, $e0, $ff, $00
;@ path: gfx/trade
TradingAnimationGraphics2End:
; try to evolve the mon in [wWhichPokemon]
;@ path: engine/pokemon/evos_moves
;@ def TryEvolvingMon()
;@ Outside battle (an evolution stone): let party Pokémon wWhichPokemon, and only it, try to evolve.
;@ test: skip runs the evolution screens
TryEvolvingMon:
;> mem[addr(wCanEvolveFlags)] = 0
	ld hl, wCanEvolveFlags
	xor a
	ld [hl], a
;> Evolution_FlagAction(addr(wCanEvolveFlags), wWhichPokemon, FLAG_SET)
	ld a, [wWhichPokemon]
	ld c, a
	ld b, FLAG_SET
	call Evolution_FlagAction
;> EvolutionAfterBattle()                        # the code runs on into it

; this is only called after battle
; it is supposed to do level up evolutions, though there is a bug that allows item evolutions to occur
;@ path: engine/pokemon/evos_moves
;@ def EvolutionAfterBattle()
;@ Go through the party and evolve every Pokémon flagged in wCanEvolveFlags whose evolution condition holds:
;@ level, item, or trade (only while trading).
;@ test: skip runs the evolution screens
EvolutionAfterBattle:
;> saved_tile_animations = hTileAnimations
	ldh a, [hTileAnimations]
	push af
;> wEvolutionOccurred = 0
	xor a
	ld [wEvolutionOccurred], a
;> wWhichPokemon = 0xFF                          # the loop starts by counting up
	dec a
	ld [wWhichPokemon], a
;> # hl, bc and de are kept, then the place in the party list
	push hl
	push bc
	push de
	ld hl, wPartyCount
	push hl
;> Evolution_PartyMonLoop()                      # the code runs on into it

;@ path: engine/pokemon/evos_moves
;@ def Evolution_PartyMonLoop()
;@ The loop of EvolutionAfterBattle, one party Pokémon after another (it keeps its place in the party list
;@ on the stack, which is why CancelledEvolution can jump back in).
;@ test: skip keeps its party list pointer on the stack
Evolution_PartyMonLoop: ; loop over party mons
;> while True:
;>     wWhichPokemon = u8(wWhichPokemon + 1)
	ld hl, wWhichPokemon
	inc [hl]
;>     slot = addr(wPartySpecies) + wWhichPokemon     # the place in the list, kept on the stack
	pop hl
	inc hl
;>     species = mem[slot]
	ld a, [hl]
;>     if species == 0xFF:                       # the end of the party
;>         break
	cp $ff ; have we reached the end of the party?
	jp z, .done
;>     wEvoOldSpecies = species
	ld [wEvoOldSpecies], a
	push hl
;>     can = Evolution_FlagAction(addr(wCanEvolveFlags), wWhichPokemon, FLAG_TEST)
	ld a, [wWhichPokemon]
	ld c, a
	ld hl, wCanEvolveFlags
	ld b, FLAG_TEST
	call Evolution_FlagAction
;>     if not can:
;>         continue
	ld a, c
	and a ; is the mon's bit set?
	jp z, Evolution_PartyMonLoop ; if not, go to the next mon
;>     index = u8(wEvoOldSpecies - 1)
	ld a, [wEvoOldSpecies]
	dec a
;>     entry_at = EvosMovesPointerTable + 2 * index
	ld b, 0
	ld hl, EvosMovesPointerTable
	add a
	rl b
	ld c, a
	add hl, bc
;>     p = mem16[entry_at]                       # its evolution entries
	ld a, [hli]
	ld h, [hl]
	ld l, a
	push hl
;>     keep = wCurPartySpecies
	ld a, [wCurPartySpecies]
	push af
;>     wMonDataLocation = PLAYER_PARTY_DATA
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;>     LoadMonData()
	call LoadMonData
;>     wCurPartySpecies = keep
	pop af
	ld [wCurPartySpecies], a
;>     while True:
	pop hl

.evoEntryLoop ; loop over evolution entries
;>         method = mem[p]
;>         p += 1
	ld a, [hli]
;>         if method == 0:                       # no more entries
;>             break
	and a ; have we reached the end of the evolution data?
	jr z, Evolution_PartyMonLoop
;>         if method == EVOLVE_TRADE:
	ld b, a ; evolution type
	cp EVOLVE_TRADE
	jr z, .checkTradeEvo
;>@tr             if wLinkState != LINK_STATE_TRADING:     # only while trading
;>@tr2                 p += 2
;>@tr3                 continue
;>@trreq             required = mem[p]
;>@trreq2             p += 1
;>@trlow             if mem[wLoadedMonLevel] < required:
;>@trlow2                 break
;>         else:
; not trade evolution
;>             if wLinkState == LINK_STATE_TRADING:
;>                 break
	ld a, [wLinkState]
	cp LINK_STATE_TRADING
	jr z, Evolution_PartyMonLoop ; if trading, go the next mon
;>             if method == EVOLVE_ITEM:
	ld a, b
	cp EVOLVE_ITEM
	jr z, .checkItemEvo
;>@item                 item = mem[p]
;>@item2                 p += 1
;>                 # bug: wCurItem is also wCurPartySpecies, so a wild Pokémon's species can count as the stone
;>@itemcmp                 if wCurItem != item:
;>@itemskip                     p += 2
;>@item3                     continue
;>             elif wForceEvolution:             # level evolutions only right after a battle
;>                 break
	ld a, [wForceEvolution]
	and a
	jr nz, Evolution_PartyMonLoop
;>             # an EVOLVE_LEVEL entry goes on to the level check (other kinds would count as trades)
	ld a, b
	cp EVOLVE_LEVEL
	jr z, .checkLevel
.checkTradeEvo
;=@tr
	ld a, [wLinkState]
	cp LINK_STATE_TRADING
	jp nz, .nextEvoEntry1 ; if not trading, go to the next evolution entry
;=@trreq
	ld a, [hli] ; level requirement
	ld b, a
;=@trlow
	ld a, [wLoadedMonLevel]
	cp b ; is the mon's level greater than the evolution requirement?
	jp c, Evolution_PartyMonLoop ; if so, go the next mon
	jr .doEvolution
.checkItemEvo
;=@item
	ld a, [hli]
	; Bug: Wild encounters can cause stone evolutions without
	; having any stones available. This was fixed in Yellow.
;=@itemcmp
	ld b, a ; evolution item
	ld a, [wCurItem] ; same as [wCurPartySpecies]
	cp b ; was the evolution item in this entry used?
	jp nz, .nextEvoEntry1 ; if not, go to the next evolution entry
.checkLevel
;>             required = mem[p]
;>             p += 1
	ld a, [hli] ; level requirement
	ld b, a
;>             if mem[wLoadedMonLevel] < required:   # not yet
	ld a, [wLoadedMonLevel]
	cp b ; is the mon's level greater than the evolution requirement?
	jp c, .nextEvoEntry2 ; if so, go the next evolution entry
;>@lvskip                 p += 1
;>@lvnext                 continue
.doEvolution
;>         # it evolves into mem[p]
;>         wCurEnemyLevel = mem[wLoadedMonLevel]
	ld [wCurEnemyLevel], a
;>         wEvolutionOccurred = 1
	ld a, 1
	ld [wEvolutionOccurred], a
;>         wEvoNewSpecies = mem[p]
	push hl
	ld a, [hl]
	ld [wEvoNewSpecies], a
;>         GetPartyMonName(wWhichPokemon, addr(wPartyMonNicks))
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;>         CopyToStringBuffer(addr(wNameBuffer))
	call CopyToStringBuffer
;>         PrintText(IsEvolvingText)
	ld hl, IsEvolvingText
	call PrintText
;>         DelayFrames(50)
	ld c, 50
	call DelayFrames
;>         hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;>         ClearScreenArea(coord(0, 0), 12, 20)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((12) & $ff) << 8 + ((20) & $ff)
	call ClearScreenArea
;>         hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;>         wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;>         ClearSprites()
	call ClearSprites
;>         cancelled = EvolveMon()                   # B stops it
	ld hl, EvolveMon
	ld b, BANK(EvolveMon)
	call Bankswitch
;>         if cancelled:
;>             return CancelledEvolution()
	jp c, CancelledEvolution
;>         PrintText(EvolvedText)
	ld hl, EvolvedText
	call PrintText
;>         new = mem[p]
	pop hl
	ld a, [hl]
;>         wCurSpecies = new
;>         mem[wLoadedMonSpecies] = new
	ld [wCurSpecies], a
	ld [wLoadedMonSpecies], a
;>         wEvoNewSpecies = new
	ld [wEvoNewSpecies], a
;>         wNameListType = MONSTER_NAME
	ld a, MONSTER_NAME
	ld [wNameListType], a
;>         wPredefBank = BANK(TrainerNames)      # not used for Pokémon names
	ld a, BANK(TrainerNames) ; bank is not used for monster names
	ld [wPredefBank], a
;>         GetName()
	call GetName
	push hl
;>         PrintText_NoCreatingTextBox(IntoText)
	ld hl, IntoText
	call PrintText_NoCreatingTextBox
;>         PlaySoundWaitForCurrent(SFX_GET_ITEM_2)
	ld a, SFX_GET_ITEM_2
	call PlaySoundWaitForCurrent
;>         WaitForSoundToFinish()
	call WaitForSoundToFinish
;>         DelayFrames(40)
	ld c, 40
	call DelayFrames
;>         ClearScreen()
	call ClearScreen
;>         RenameEvolvedMon()
	call RenameEvolvedMon
;>         # the new species' base data and stats
;>         dex_saved = wPokedexNum
	ld a, [wPokedexNum]
	push af
;>         wPokedexNum = wCurSpecies
	ld a, [wCurSpecies]
	ld [wPokedexNum], a
;>         IndexToPokedex()
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;>         stats = BaseStats + (wPokedexNum - 1) * BASE_DATA_SIZE
	ld a, [wPokedexNum]
	dec a
	ld hl, BaseStats
	ld bc, BASE_DATA_SIZE
	call AddNTimes
;>         CopyData(stats, addr(wMonHeader), BASE_DATA_SIZE)
	ld de, wMonHeader
	call CopyData
;>         wMonHIndex = wCurSpecies
	ld a, [wCurSpecies]
	ld [wMonHIndex], a
;>         wPokedexNum = dex_saved
	pop af
	ld [wPokedexNum], a
;>         CalcStats(wLoadedMonHPExp - 1, wLoadedMonStats, 1)
	ld hl, wLoadedMonHPExp - 1
	ld de, wLoadedMonStats
	ld b, $1
	call CalcStats
;>         # the current HP goes up by as much as the maximum did
;>         mon = addr(wPartyMon1) + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	ld hl, wPartyMon1
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld e, l
	ld d, h
;>         at = mon + MON_MAXHP
	push hl
	push bc
	ld bc, MON_MAXHP
	add hl, bc
;>         old_max = mem[at] << 8 | mem[at + 1]
	ld a, [hli]
	ld b, a
	ld c, [hl]
;>         gain = (mem[wLoadedMonMaxHP] << 8 | mem[wLoadedMonMaxHP + 1]) - old_max
	ld hl, wLoadedMonMaxHP + 1
	ld a, [hld]
	sub c
	ld c, a
;>         # (the high byte, with the borrow)
	ld a, [hl]
	sbc b
	ld b, a
;>         hp = (mem[wLoadedMonHP] << 8 | mem[wLoadedMonHP + 1]) + gain
;>         mem[wLoadedMonHP + 1] = hp & 0xFF
	ld hl, wLoadedMonHP + 1
	ld a, [hl]
	add c
	ld [hld], a
;>         mem[wLoadedMonHP] = hp >> 8 & 0xFF
	ld a, [hl]
	adc b
	ld [hl], a
	dec hl
;>         CopyData(addr(wLoadedMon), mon, PARTYMON_STRUCT_LENGTH)
	pop bc
	call CopyData
;>         wPokedexNum = wCurSpecies
	ld a, [wCurSpecies]
	ld [wPokedexNum], a
;>         wMonDataLocation = 0
	xor a
	ld [wMonDataLocation], a
;>         LearnMoveFromLevelUp()
	call LearnMoveFromLevelUp
;>         SetPartyMonTypes()                    # through the predef, for the struct at mon
	pop hl
	ld a, (SetPartyMonTypesPredef - PredefPointers) / 3
	call Predef
;>         if not wIsInBattle:
;>             Evolution_ReloadTilesetTilePatterns()
	ld a, [wIsInBattle]
	and a
	call z, Evolution_ReloadTilesetTilePatterns
;>         IndexToPokedex()
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;>         dex = u8(wPokedexNum - 1)
	ld a, [wPokedexNum]
	dec a
	ld c, a
;>         Evolution_FlagAction(addr(wPokedexOwned), dex, FLAG_SET)
	ld b, FLAG_SET
	ld hl, wPokedexOwned
	push bc
	call Evolution_FlagAction
	pop bc
;>         Evolution_FlagAction(addr(wPokedexSeen), dex, FLAG_SET)
	ld hl, wPokedexSeen
	call Evolution_FlagAction
	pop de
	pop hl
;>         mem[slot] = mem[wLoadedMonSpecies]    # then on with its next entry
	ld a, [wLoadedMonSpecies]
	ld [hl], a
	push hl
	ld l, e
	ld h, d
	jr .nextEvoEntry2

.nextEvoEntry1
;=@itemskip
	inc hl

.nextEvoEntry2
;=@lvskip
	inc hl
	jp .evoEntryLoop

.done
;> # hl, bc and de as EvolutionAfterBattle found them
	pop de
	pop bc
	pop hl
;> # hTileAnimations back as EvolutionAfterBattle saved it on the stack
	pop af
	ldh [hTileAnimations], a
;> if wLinkState == LINK_STATE_TRADING:
;>     return
	ld a, [wLinkState]
	cp LINK_STATE_TRADING
	ret z
;> if wIsInBattle:
;>     return
	ld a, [wIsInBattle]
	and a
	ret nz
;> if wEvolutionOccurred:
;>     PlayDefaultMusic()
	ld a, [wEvolutionOccurred]
	and a
	call nz, PlayDefaultMusic
	ret

;@ path: engine/pokemon/evos_moves
;@ def RenameEvolvedMon()
;@ An evolved Pokémon that still had its species' standard name gets its new species' name; a nickname stays.
;@ test: skip GetName reads the name tables in other banks
RenameEvolvedMon:
; Renames the mon to its new, evolved form's standard name unless it had a
; nickname, in which case the nickname is kept.
;> # wCurSpecies and wNameListIndex are the same byte
	ASSERT wCurSpecies == wNameListIndex ; save+restore wCurSpecies while using wNameListIndex
;> new = wCurSpecies
	ld a, [wCurSpecies]
	push af
;> wNameListIndex = wMonHIndex
	ld a, [wMonHIndex]
	ld [wNameListIndex], a
;> GetName()                                     # the old species' standard name
	call GetName
;> wCurSpecies = new
	pop af
	ld [wCurSpecies], a
;> standard, name = addr(wNameBuffer), addr(wStringBuffer)     # the standard name, its current name
;> while True:
	ld hl, wNameBuffer
	ld de, wStringBuffer
.compareNamesLoop
;>     c = mem[name]
;>     name += 1
	ld a, [de]
	inc de
;>     different = c != mem[standard]
	cp [hl]
;>     standard += 1
	inc hl
;>     if different:                             # a nickname: it stays
;>         return
	ret nz
;>     if c == 0x50:                             # '@', the end
;>         break
	cp '@'
	jr nz, .compareNamesLoop
;> nick = addr(wPartyMonNicks) + wWhichPokemon * NAME_LENGTH
	ld a, [wWhichPokemon]
	ld bc, NAME_LENGTH
	ld hl, wPartyMonNicks
	call AddNTimes
	push hl
;> GetName()                                     # the new species' name
	call GetName
;> CopyData(addr(wNameBuffer), nick, NAME_LENGTH)
	ld hl, wNameBuffer
	pop de
	jp CopyData

;@ path: engine/pokemon/evos_moves
;@ def CancelledEvolution()
;@ The player pressed B during the evolution: "... stopped evolving", then on with the next Pokémon.
;@ test: skip jumps back into the party loop, whose pointer is on the stack
CancelledEvolution:
;> PrintText(StoppedEvolvingText)
	ld hl, StoppedEvolvingText
	call PrintText
;> ClearScreen()
	call ClearScreen
	pop hl
;> Evolution_ReloadTilesetTilePatterns()
	call Evolution_ReloadTilesetTilePatterns
;> return Evolution_PartyMonLoop()
	jp Evolution_PartyMonLoop

;@ path: engine/pokemon/evos_moves
EvolvedText:
	db TX_FAR
	dw _EvolvedText
	db BANK(_EvolvedText)
	db TX_END

;@ path: engine/pokemon/evos_moves
IntoText:
	db TX_FAR
	dw _IntoText
	db BANK(_IntoText)
	db TX_END

;@ path: engine/pokemon/evos_moves
StoppedEvolvingText:
	db TX_FAR
	dw _StoppedEvolvingText
	db BANK(_StoppedEvolvingText)
	db TX_END

;@ path: engine/pokemon/evos_moves
IsEvolvingText:
	db TX_FAR
	dw _IsEvolvingText
	db BANK(_IsEvolvingText)
	db TX_END

;@ path: engine/pokemon/evos_moves
;@ def Evolution_ReloadTilesetTilePatterns()
;@ Reload the map's tiles after the evolution screen, unless the evolution happened during a trade.
Evolution_ReloadTilesetTilePatterns:
;> if wLinkState == LINK_STATE_TRADING:
;>     return
	ld a, [wLinkState]
	cp LINK_STATE_TRADING
	ret z
;> ReloadTilesetTilePatterns()
	jp ReloadTilesetTilePatterns

;@ path: engine/pokemon/evos_moves
;@ def LearnMoveFromLevelUp()
;@ Species wPokedexNum just reached level wCurEnemyLevel: if its learnset has a move for that level that party
;@ Pokémon wWhichPokemon does not know yet, try to learn it.
;@ test: hLoadedROMBank = 0x0E; wPokedexNum = rand(1, 190); wMonDataLocation = 0; wWhichPokemon = rand(0, 5)
LearnMoveFromLevelUp:
;> species = wPokedexNum
	ld hl, EvosMovesPointerTable
	ld a, [wPokedexNum] ; species
;> wCurPartySpecies = species
	ld [wCurPartySpecies], a
;> index = u8(species - 1)
	dec a
	ld bc, 0
	ld hl, EvosMovesPointerTable
;> entry_at = EvosMovesPointerTable + 2 * index
	add a
	rl b
	ld c, a
	add hl, bc
;> p = mem16[entry_at]
;> while True:                                   # past the evolution entries and their 0
	ld a, [hli]
	ld h, [hl]
	ld l, a
.skipEvolutionDataLoop ; loop to skip past the evolution data, which comes before the move data
;>     value = mem[p]
;>     p += 1
	ld a, [hli]
;>     if value == 0:
;>         break
	and a ; have we reached the end of the evolution data?
	jr nz, .skipEvolutionDataLoop ; if not, jump back up
;> while True:                                   # the learnset: level and move pairs, up to a 0
.learnSetLoop ; loop over the learn set until we reach a move that is learnt at the current level or the end of the list
;>     level = mem[p]
	ld a, [hli]
;>     if level == 0:
;>         break
	and a ; have we reached the end of the learn set?
	jr z, .done ; if we've reached the end of the learn set, jump
;>     now = level == wCurEnemyLevel
	ld b, a ; level the move is learnt at
	ld a, [wCurEnemyLevel]
	cp b ; is the move learnt at the mon's current level?
;>     move = mem[p + 1]
;>     p += 2
	ld a, [hli] ; move ID
;>     if not now:
;>         continue
	jr nz, .learnSetLoop
;>     new_move = move
	ld d, a ; ID of move to learn
;>     if wMonDataLocation == PLAYER_PARTY_DATA:  # always so: other lists would not work here
	ld a, [wMonDataLocation]
	and a
	jr nz, .next
; If [wMonDataLocation] is 0 (PLAYER_PARTY_DATA), get the address of the mon's
; current moves in party data. Every call to this function sets
; [wMonDataLocation] to 0 because other data locations are not supported.
; If it is not 0, this function will not work properly.
;>         moves = addr(wPartyMon1Moves) + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Moves
	ld a, [wWhichPokemon]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
.next
;>     if new_move in mem[moves:moves + NUM_MOVES]:  # known already
;>         break
	ld b, NUM_MOVES
.checkCurrentMovesLoop ; check if the move to learn is already known
	ld a, [hli]
	cp d
	jr z, .done ; if already known, jump
	dec b
	jr nz, .checkCurrentMovesLoop
;>     wMoveNum = new_move
;>     wNamedObjectIndex = new_move
	ld a, d
	ld [wMoveNum], a
	ld [wNamedObjectIndex], a
;>     GetMoveName()
	call GetMoveName
;>     CopyToStringBuffer(addr(wNameBuffer))
	call CopyToStringBuffer
;>     LearnMove()
	ld a, (LearnMovePredef - PredefPointers) / 3
	call Predef
;>     break
.done
;> wPokedexNum = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wPokedexNum], a
	ret

; writes the moves a mon has at level [wCurEnemyLevel] to [de]
; move slots are being filled up sequentially and shifted if all slots are full
;@ path: engine/pokemon/evos_moves
;@ def WriteMonMoves()
;@ Fill the move slots at the predef's de with the moves species wCurPartySpecies knows by level
;@ wCurEnemyLevel, in learnset order: new moves go into empty slots, and once all four are full the oldest
;@ is pushed out. From the day care (wLearningMovesFromDayCare) only moves above wDayCareStartLevel, with PP.
;@ test: hLoadedROMBank = 0x0E; wCurPartySpecies = rand(1, 190); wCurEnemyLevel = rand(1, 100); d = rand_ram(40)
;@ test: mem[wPredefDE] = d >> 8; mem[wPredefDE + 1] = d & 0xFF; mem[wLearningMovesFromDayCare] = rand(0, 1)
WriteMonMoves:
;> dest = wPredefDE[0] << 8 | wPredefDE[1]
	call GetPredefRegisters
;> # hl, de and bc are kept
	push hl
	push de
	push bc
;> index = u8(wCurPartySpecies - 1)
	ld hl, EvosMovesPointerTable
	ld b, 0
	ld a, [wCurPartySpecies]
	dec a
;> entry_at = EvosMovesPointerTable + 2 * index
	add a
	rl b
	ld c, a
	add hl, bc
;> p = mem16[entry_at]
;> while True:                                   # past the evolution entries and their 0
	ld a, [hli]
	ld h, [hl]
	ld l, a
.skipEvoEntriesLoop
;>     value = mem[p]
;>     p += 1
	ld a, [hli]
;>     if value == 0:
;>         break
	and a
	jr nz, .skipEvoEntriesLoop
	jr .firstMove
;> while True:                                   # the learnset: level and move pairs, up to a 0
.nextMove
;=@known
	pop de
.nextMove2
;=@next
	inc hl
.firstMove
;>     level = mem[p]
	ld a, [hli]       ; read level of next move in learnset
;>     if level == 0:
;>         break
	and a
	jp z, .done       ; end of list
;>     if wCurEnemyLevel < level:                # sorted by level: the rest come later
;>         break
	ld b, a
	ld a, [wCurEnemyLevel]
	cp b
	jp c, .done       ; mon level < move level (assumption: learnset is sorted by level)
;>     if wLearningMovesFromDayCare:
	ld a, [wLearningMovesFromDayCare]
	and a
	jr z, .skipMinLevelCheck
;>         if wDayCareStartLevel >= level:       # known when it went in
	ld a, [wDayCareStartLevel]
	cp b
	jr nc, .nextMove2 ; min level >= move level
;>@dcskip             p += 1
;>@dcnext             continue

.skipMinLevelCheck

; check if the move is already known
;>     move = mem[p]
	push de
	ld c, NUM_MOVES
;>@known     if move in mem[dest:dest + NUM_MOVES]:
.alreadyKnowsCheckLoop
	ld a, [de]
	inc de
	cp [hl]
	jr z, .nextMove
	dec c
	jr nz, .alreadyKnowsCheckLoop
;>@known2         p += 1
;>@known3         continue

; try to find an empty move slot
;>     slot = dest
	pop de
	push de
;>     for _ in range(NUM_MOVES):
	ld c, NUM_MOVES
.findEmptySlotLoop
;>         if mem[slot] == 0:                    # an empty slot
;>             break
	ld a, [de]
	and a
	jr z, .writeMoveToSlot2
;>         slot += 1
	inc de
	dec c
	jr nz, .findEmptySlotLoop

; no empty move slots found
;>     else:                                     # all four taken: the first goes, the others move up
;>         WriteMonMoves_ShiftMoveData(dest, dest)
	pop de
	push de
	push hl
	ld h, d
	ld l, e
	call WriteMonMoves_ShiftMoveData ; shift all moves one up (deleting move 1)
;>         if wLearningMovesFromDayCare:
	ld a, [wLearningMovesFromDayCare]
	and a
	jr z, .writeMoveToSlot

; shift PP as well if learning moves from day care
;>             pp = dest + MON_PP - MON_MOVES        # the PP move up with them
	push de
	ld bc, MON_PP - (MON_MOVES + 3)
	add hl, bc
	ld d, h
	ld e, l
;>             WriteMonMoves_ShiftMoveData(pp, pp)
	call WriteMonMoves_ShiftMoveData ; shift all move PP data one up
	pop de

.writeMoveToSlot
;>         slot = dest + NUM_MOVES - 1
	pop hl
.writeMoveToSlot2
;>     mem[slot] = move
	ld a, [hl]
	ld [de], a
;>     if wLearningMovesFromDayCare:             # from the day care: with full PP
	ld a, [wLearningMovesFromDayCare]
	and a
	jr z, .nextMove

; write move PP value if learning moves from day care
;>         pp_slot = slot + MON_PP - MON_MOVES
;>         index = move - 1
	push hl
	ld a, [hl]
	ld hl, MON_PP - MON_MOVES
	add hl, de
	push hl
	dec a
;>         entry = Moves + index * MOVE_LENGTH
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;>         FarCopyData(BANK(Moves), entry, addr(wBuffer), MOVE_LENGTH)
	ld de, wBuffer
	ld a, BANK(Moves)
	call FarCopyData
;>         mem[pp_slot] = wBuffer[MOVE_PP]
	ld a, [wBuffer + MOVE_PP]
	pop hl
	ld [hl], a
	pop hl
	jr .nextMove
;>@next     p += 1                                # past the move

.done
;> # hl, de and bc back
	pop bc
	pop de
	pop hl
	ret

; shifts all move data one up (freeing 4th move slot)
;@ path: engine/pokemon/evos_moves
;@ def WriteMonMoves_ShiftMoveData(dest: hl, src: de) -> hl
;@ Move the four bytes at src one place forward to dest (dest[0..2] = src[1..3]), freeing the fourth slot.
;@ test: src = rand_ram(8); dest = src
WriteMonMoves_ShiftMoveData:
;> for i in range(NUM_MOVES - 1):
	ld c, NUM_MOVES - 1
.loop
;>     mem[dest + i] = mem[src + 1 + i]
	inc de
	ld a, [de]
	ld [hli], a
	dec c
	jr nz, .loop
;> return dest + NUM_MOVES - 1
	ret

;@ path: engine/pokemon/evos_moves
;@ def Evolution_FlagAction(field: hl, bit: c, action: b) -> c
;@ FlagAction through the predef table: Predef saves hl, de and bc, switches to FlagActionPredef's bank and
;@ calls it, and FlagActionPredef takes its arguments back.
;@ test: skip through Predef, which calls the function its table names
Evolution_FlagAction:
;> return Predef((FlagActionPredefPredef - PredefPointers) // 3)
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	jp Predef

; Evos+moves data structure:
; - Evolution methods:
;    * db EVOLVE_LEVEL, level, species
;    * db EVOLVE_ITEM, used item, min level (1), species
;    * db EVOLVE_TRADE, min level (1), species
; - db 0 ; no more evolutions
; - Learnset (in increasing level order):
;    * db level, move
; - db 0 ; no more level-up moves

