;@ path: engine/battle/move_effects/heal
;@ def HealEffect_()
;@ Recover, Softboiled and Rest. Fails at full HP (only the low bytes are compared, so it also fails 255 or 511
;@ points below full). Rest puts the user to sleep for two turns, curing any status, and heals fully; the others
;@ heal half the maximum HP.
HealEffect_:
;> if hWhoseTurn == 0:
;>     hp, max_hp, move = wBattleMonHP, wBattleMonMaxHP, wPlayerMoveNum
	ldh a, [hWhoseTurn]
	and a
	ld de, wBattleMonHP
	ld hl, wBattleMonMaxHP
	ld a, [wPlayerMoveNum]
	jr z, .healEffect
;> else:
;>     hp, max_hp, move = wEnemyMonHP, wEnemyMonMaxHP, wEnemyMoveNum
	ld de, wEnemyMonHP
	ld hl, wEnemyMonMaxHP
	ld a, [wEnemyMoveNum]
.healEffect
;> # at full HP it fails - but only the low bytes count; the high bytes just add their borrow
;> borrow = mem[hp] < mem[max_hp]
	ld b, a
	ld a, [de]
	cp [hl] ; most significant bytes comparison is ignored
	        ; causes the move to miss if max HP is 255 or 511 points higher than the current HP
;> if mem[hp + 1] - mem[max_hp + 1] - borrow & 0xFF == 0:
;>@wait     DelayFrames(50)
;>@fail     return EffectCallBattleCore(PrintButItFailedText_)
	inc de
	inc hl
	ld a, [de]
	sbc [hl]
	jp z, .failed ; no effect if user's HP is already at its maximum
;> if move == REST:
	ld a, b
	cp REST
	jr nz, .healHP
;>     DelayFrames(50)
	push hl
	push de
	push af
	ld c, 50
	call DelayFrames
;>     status = wBattleMonStatus if hWhoseTurn == 0 else wEnemyMonStatus
	ld hl, wBattleMonStatus
	ldh a, [hWhoseTurn]
	and a
	jr z, .restEffect
	ld hl, wEnemyMonStatus
.restEffect
;>     had_status = mem[status]
;>     mem[status] = 2                      # any status cured; asleep for two turns
	ld a, [hl]
	and a
	ld [hl], 2 ; clear status and set number of turns asleep to 2
;>     text = FellAsleepBecameHealthyText if had_status else StartedSleepingEffect
	ld hl, StartedSleepingEffect ; if mon didn't have an status
	jr z, .printRestText
	ld hl, FellAsleepBecameHealthyText ; if mon had an status
.printRestText
;>     PrintText(text)
	call PrintText
	pop af
	pop de
	pop hl
.healHP
;> top = mem[max_hp] << 8 | mem[max_hp + 1]
;> mem[wHPBarMaxHP], mem[wHPBarMaxHP + 1] = lo(top), hi(top)
	ld a, [hld]
	ld [wHPBarMaxHP], a
	ld c, a
	ld a, [hl]
	ld [wHPBarMaxHP+1], a
	ld b, a
;> heal = top if move == REST else top >> 1
	jr z, .gotHPAmountToHeal
; Recover and Softboiled only heal for half the mon's max HP
	srl b
	rr c
.gotHPAmountToHeal
; update HP
;> old = mem[hp] << 8 | mem[hp + 1]
;> mem[wHPBarOldHP] = lo(old)
	ld a, [de]
	ld [wHPBarOldHP], a
;> new = old + heal
;> mem[hp + 1] = mem[wHPBarNewHP] = lo(new)
	add c
	ld [de], a
	ld [wHPBarNewHP], a
;> mem[wHPBarOldHP + 1] = hi(old)
;> mem[hp] = mem[wHPBarNewHP + 1] = hi(new)
	dec de
	ld a, [de]
	ld [wHPBarOldHP+1], a
	adc b
	ld [de], a
	ld [wHPBarNewHP+1], a
;> low = lo(new) - lo(top)                          # new minus top, low bytes first
	inc hl
	inc de
	ld a, [de]
	dec de
	sub [hl]
;> if new & 0xFFFF >= top:                          # (the high bytes with the borrow)
	dec hl
	ld a, [de]
	sbc [hl]
	jr c, .playAnim
; copy max HP to current HP if an overflow occurred
;>     new = top
;>     mem[hp] = mem[wHPBarNewHP + 1] = hi(new)
	ld a, [hli]
	ld [de], a
	ld [wHPBarNewHP+1], a
;>     mem[hp + 1] = mem[wHPBarNewHP] = lo(new)
	inc de
	ld a, [hl]
	ld [de], a
	ld [wHPBarNewHP], a
.playAnim
;> EffectCallBattleCore(PlayCurrentMoveAnimation)
	ld hl, PlayCurrentMoveAnimation
	call EffectCallBattleCore
;> if hWhoseTurn == 0:
;>     bar, bar_type = coord(10, 9), 1
	ldh a, [hWhoseTurn]
	and a
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ld a, $1
	jr z, .updateHPBar
;> else:
;>     bar, bar_type = coord(2, 2), 0
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	xor a
.updateHPBar
;> wHPBarType = bar_type
;> predef(UpdateHPBar2, hl=bar)
	ld [wHPBarType], a
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;> EffectCallBattleCore(DrawHUDsAndHPBars)
	ld hl, DrawHUDsAndHPBars
	call EffectCallBattleCore
;> PrintText(RegainedHealthText)
	ld hl, RegainedHealthText
	jp PrintText
.failed
;=@wait
	ld c, 50
	call DelayFrames
;=@fail
	ld hl, PrintButItFailedText_
	jp EffectCallBattleCore

;@ path: engine/battle/move_effects/heal
StartedSleepingEffect:
	db TX_FAR
	dw _StartedSleepingEffect
	db BANK(_StartedSleepingEffect)
	db TX_END

;@ path: engine/battle/move_effects/heal
FellAsleepBecameHealthyText:
	db TX_FAR
	dw _FellAsleepBecameHealthyText
	db BANK(_FellAsleepBecameHealthyText)
	db TX_END

;@ path: engine/battle/move_effects/heal
RegainedHealthText:
	db TX_FAR
	dw _RegainedHealthText
	db BANK(_RegainedHealthText)
	db TX_END
;@ path: engine/battle/move_effects/transform
;@ def TransformEffect_()
;@ Transform: the user copies the target's species, types, moves (5 PP each), DVs, stats and stat stages. The
;@ check for a target out of reach (Dig, Fly) never works: it looks at the wrong status byte.
TransformEffect_:
;> src, dest, status3 = wBattleMonSpecies, wEnemyMonSpecies, addr(wEnemyBattleStatus3)
	ld hl, wBattleMonSpecies
	ld de, wEnemyMonSpecies
	ld bc, wEnemyBattleStatus3
	; bug: on enemy's turn, a is overloaded with hWhoseTurn,
	; before the check for INVULNERABLE
;> check = hWhoseTurn                       # bug: meant to be wEnemyBattleStatus1
;> if hWhoseTurn == 0:
	ld a, [wEnemyBattleStatus1]
	ldh a, [hWhoseTurn]
	and a
	jr nz, .hitTest
; player's turn
;>     src, dest, status3 = wEnemyMonSpecies, wBattleMonSpecies, addr(wPlayerBattleStatus3)
	ld hl, wEnemyMonSpecies
	ld de, wBattleMonSpecies
	ld bc, wPlayerBattleStatus3
;>     wPlayerMoveListIndex = 0
	ld [wPlayerMoveListIndex], a
	; bug: this should be target's BattleStatus1 (i.e. wEnemyBattleStatus1)
;>     check = wPlayerBattleStatus1         # bug: the user's byte, not the target's
	ld a, [wPlayerBattleStatus1]
.hitTest
;> if check >> INVULNERABLE & 1:            # out of reach (Dig, Fly) - never true, see above
;>@fail     return EffectCallBattleCore(PrintButItFailedText_)
	bit INVULNERABLE, a ; is mon invulnerable to typical attacks? (fly/dig)
	                    ; this check doesn't work due to above bugs
	jp nz, .failed
	push hl
	push de
	push bc
;> status2 = addr(wPlayerBattleStatus2) if hWhoseTurn == 0 else addr(wEnemyBattleStatus2)
	ld hl, wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	jr z, .transformEffect
	ld hl, wEnemyBattleStatus2
.transformEffect
; animation(s) played are different if target has Substitute up
;> substitute = mem[status2] >> HAS_SUBSTITUTE_UP & 1
	bit HAS_SUBSTITUTE_UP, [hl]
	push af
;> if substitute:
;>     HideSubstituteShowMonAnim()
	ld hl, HideSubstituteShowMonAnim
	ld b, BANK(HideSubstituteShowMonAnim)
	call nz, Bankswitch
;> off = wOptions >> BIT_BATTLE_ANIMATION & 1        # animations off?
	ld a, [wOptions]
	add a
;> anim = PlayCurrentMoveAnimation
	ld hl, PlayCurrentMoveAnimation
	ld b, BANK(PlayCurrentMoveAnimation)
;> if off:
;>     anim = AnimationTransformMon
	jr nc, .gotAnimToPlay
	ld hl, AnimationTransformMon
	ld b, BANK(AnimationTransformMon)
.gotAnimToPlay
;> anim()
	call Bankswitch
;> if substitute:
;>     ReshowSubstituteAnim()
	ld hl, ReshowSubstituteAnim
	ld b, BANK(ReshowSubstituteAnim)
	pop af
	call nz, Bankswitch
;> mem[status3] |= 1 << TRANSFORMED
	pop bc
	ld a, [bc]
	set TRANSFORMED, a ; mon is now transformed
	ld [bc], a
;> mem[dest] = mem[src]                     # species
	pop de
	pop hl
	push hl
; transform user into opposing Pokemon
; species
	ld a, [hl]
	ld [de], a
; type 1, type 2, catch rate, and moves
;> from_ = src + 5                                  # types, catch rate and moves
	ld bc, $5
	add hl, bc
;> to_ = dest + 5
	inc de
	inc de
	inc de
	inc de
	inc de
;> CopyData(from_, to_, 8)
	inc bc
	inc bc
	call CopyData
;> if hWhoseTurn != 0:                      # the enemy keeps its own DVs for later
	ldh a, [hWhoseTurn]
	and a
	jr z, .next
; save enemy mon DVs at wTransformedEnemyMonOriginalDVs
;>     wTransformedEnemyMonOriginalDVs[0] = mem[dest + 13]
;>     wTransformedEnemyMonOriginalDVs[1] = mem[dest + 14]
	ld a, [de]
	ld [wTransformedEnemyMonOriginalDVs], a
	inc de
	ld a, [de]
	ld [wTransformedEnemyMonOriginalDVs + 1], a
	dec de
.next
; DVs
;> mem[dest + 13] = mem[src + 13]           # DVs
;> mem[dest + 14] = mem[src + 14]
	ld a, [hli]
	ld [de], a
	inc de
	ld a, [hli]
	ld [de], a
	inc de
; Skip level and max HP
;> from_ = src + 18                                 # attack, defense, speed, special (not level, max HP)
	inc hl
	inc hl
	inc hl
;> to_ = dest + 18
	inc de
	inc de
	inc de
; Attack, Defense, Speed, and Special stats
;> CopyData(from_, to_, (NUM_STATS - 1) * 2)
	ld bc, (NUM_STATS - 1) * 2
	call CopyData
;> moves, pp = src + 8, dest + 26
;> i = 0
	ld bc, wBattleMonMoves - wBattleMonPP
	add hl, bc ; ld hl, wBattleMonMoves
	ld b, NUM_MOVES
.copyPPLoop
; 5 PP for all moves
;> while i < NUM_MOVES and mem[moves + i]:  # 5 PP for each move
	ld a, [hli]
	and a
	jr z, .lessThanFourMoves
;>     mem[pp + i] = 5
;>     i += 1
	ld a, 5
	ld [de], a
	inc de
	dec b
	jr nz, .copyPPLoop
	jr .copyStats
.lessThanFourMoves
; 0 PP for blank moves
;> while i < NUM_MOVES:                             # 0 PP for the blank slots
;>     mem[pp + i] = 0
	xor a
	ld [de], a
;>     i += 1
	inc de
	dec b
	jr nz, .lessThanFourMoves
.copyStats
; original (unmodified) stats and stat mods
;> wNamedObjectIndex = mem[src]
;> GetMonName()
	pop hl
	ld a, [hl]
	ld [wNamedObjectIndex], a
	call GetMonName
;> # .copyBasedOnTurn: from the target to the user
;>@turn frm, to = (wEnemyMonUnmodifiedAttack, wPlayerMonUnmodifiedAttack) if hWhoseTurn == 0 else (wPlayerMonUnmodifiedAttack, wEnemyMonUnmodifiedAttack)
;>@cp CopyData(frm, to, (NUM_STATS - 1) * 2)      # the unmodified stats
	ld hl, wEnemyMonUnmodifiedAttack
	ld de, wPlayerMonUnmodifiedAttack
	call .copyBasedOnTurn ; original (unmodified) stats
;> frm, to = (wEnemyMonStatMods, wPlayerMonStatMods) if hWhoseTurn == 0 else (wPlayerMonStatMods, wEnemyMonStatMods)
;> CopyData(frm, to, (NUM_STATS - 1) * 2)      # the stat stages
	ld hl, wEnemyMonStatMods
	ld de, wPlayerMonStatMods
	call .copyBasedOnTurn ; stat mods
;> PrintText(TransformedText)
	ld hl, TransformedText
	jp PrintText

.copyBasedOnTurn
;=@turn
	ldh a, [hWhoseTurn]
	and a
	jr z, .gotStatsOrModsToCopy
;=@turn
	push hl
	ld h, d
	ld l, e
	pop de
.gotStatsOrModsToCopy
;=@cp
	ld bc, (NUM_STATS - 1) * 2
	jp CopyData

.failed
;=@fail
	ld hl, PrintButItFailedText_
	jp EffectCallBattleCore

;@ path: engine/battle/move_effects/transform
TransformedText:
	db TX_FAR
	dw _TransformedText
	db BANK(_TransformedText)
	db TX_END
;@ path: engine/battle/move_effects/reflect_light_screen
;@ def ReflectLightScreenEffect_()
;@ Reflect and Light Screen: put the screen up for the user's side, unless it already is.
ReflectLightScreenEffect_:
;> if hWhoseTurn == 0:
;>     status, effect = addr(wPlayerBattleStatus3), wPlayerMoveEffect
	ld hl, wPlayerBattleStatus3
	ld de, wPlayerMoveEffect
	ldh a, [hWhoseTurn]
	and a
	jr z, .reflectLightScreenEffect
;> else:
;>     status, effect = addr(wEnemyBattleStatus3), wEnemyMoveEffect
	ld hl, wEnemyBattleStatus3
	ld de, wEnemyMoveEffect
.reflectLightScreenEffect
;> if effect == LIGHT_SCREEN_EFFECT:
	ld a, [de]
	cp LIGHT_SCREEN_EFFECT
	jr nz, .reflect
;>     already = mem[status] >> HAS_LIGHT_SCREEN_UP & 1
	bit HAS_LIGHT_SCREEN_UP, [hl] ; is mon already protected by light screen?
	jr nz, .moveFailed
;>     if not already:
;>         mem[status] |= 1 << HAS_LIGHT_SCREEN_UP
	set HAS_LIGHT_SCREEN_UP, [hl] ; mon is now protected by light screen
;>         text = LightScreenProtectedText
	ld hl, LightScreenProtectedText
	jr .playAnim
.reflect
;> else:
;>     already = mem[status] >> HAS_REFLECT_UP & 1
	bit HAS_REFLECT_UP, [hl] ; is mon already protected by reflect?
	jr nz, .moveFailed
;>     if not already:
;>         mem[status] |= 1 << HAS_REFLECT_UP
	set HAS_REFLECT_UP, [hl] ; mon is now protected by reflect
;>         text = ReflectGainedArmorText
	ld hl, ReflectGainedArmorText
.playAnim
;> if already:                              # the screen is already up
;>@wait     DelayFrames(50)
;>@fail     return EffectCallBattleCore(PrintButItFailedText_)
;> EffectCallBattleCore(PlayCurrentMoveAnimation)
	push hl
	ld hl, PlayCurrentMoveAnimation
	call EffectCallBattleCore
	pop hl
;> return PrintText(text)
	jp PrintText
.moveFailed
;=@wait
	ld c, 50
	call DelayFrames
;=@fail
	ld hl, PrintButItFailedText_
	jp EffectCallBattleCore

;@ path: engine/battle/move_effects/reflect_light_screen
LightScreenProtectedText:
	db TX_FAR
	dw _LightScreenProtectedText
	db BANK(_LightScreenProtectedText)
	db TX_END

;@ path: engine/battle/move_effects/reflect_light_screen
ReflectGainedArmorText:
	db TX_FAR
	dw _ReflectGainedArmorText
	db BANK(_ReflectGainedArmorText)
	db TX_END

;@ path: engine/battle/move_effects/reflect_light_screen
;@ def EffectCallBattleCore(target: hl)
;@ Run a routine of the battle core's bank from a move effect in another bank.
;@ test: skip jumps to the routine whose address is in hl
EffectCallBattleCore:
;> return Bankswitch(BANK(BattleCore), target)
	ld b, BANK(BattleCore)
	jp Bankswitch


SECTION "Battle Core", ROMX

;@ path: engine/battle/core
BattleCore:

; These are move effects (second value from the Moves table in bank $E).
;@ path: engine/battle/core
ResidualEffects1:
; most non-side effects
	db CONVERSION_EFFECT
	db HAZE_EFFECT
	db SWITCH_AND_TELEPORT_EFFECT
	db MIST_EFFECT
	db FOCUS_ENERGY_EFFECT
	db CONFUSION_EFFECT
	db HEAL_EFFECT
	db TRANSFORM_EFFECT
	db LIGHT_SCREEN_EFFECT
	db REFLECT_EFFECT
	db POISON_EFFECT
	db PARALYZE_EFFECT
	db SUBSTITUTE_EFFECT
	db MIMIC_EFFECT
	db LEECH_SEED_EFFECT
	db SPLASH_EFFECT
	db -1 ; end
;@ path: engine/battle/core
SetDamageEffects:
; moves that do damage but not through normal calculations
; e.g., Super Fang, Psywave
	db SUPER_FANG_EFFECT
	db SPECIAL_DAMAGE_EFFECT
	db -1 ; end
;@ path: engine/battle/core
ResidualEffects2:
; non-side effects not included in ResidualEffects1
; stat-affecting moves, sleep-inflicting moves, and Bide
; e.g., Meditate, Bide, Hypnosis
	db EFFECT_01
	db ATTACK_UP1_EFFECT
	db DEFENSE_UP1_EFFECT
	db SPEED_UP1_EFFECT
	db SPECIAL_UP1_EFFECT
	db ACCURACY_UP1_EFFECT
	db EVASION_UP1_EFFECT
	db ATTACK_DOWN1_EFFECT
	db DEFENSE_DOWN1_EFFECT
	db SPEED_DOWN1_EFFECT
	db SPECIAL_DOWN1_EFFECT
	db ACCURACY_DOWN1_EFFECT
	db EVASION_DOWN1_EFFECT
	db BIDE_EFFECT
	db SLEEP_EFFECT
	db ATTACK_UP2_EFFECT
	db DEFENSE_UP2_EFFECT
	db SPEED_UP2_EFFECT
	db SPECIAL_UP2_EFFECT
	db ACCURACY_UP2_EFFECT
	db EVASION_UP2_EFFECT
	db ATTACK_DOWN2_EFFECT
	db DEFENSE_DOWN2_EFFECT
	db SPEED_DOWN2_EFFECT
	db SPECIAL_DOWN2_EFFECT
	db ACCURACY_DOWN2_EFFECT
	db EVASION_DOWN2_EFFECT
	db -1 ; end
;@ path: engine/battle/core
AlwaysHappenSideEffects:
; Attacks that aren't finished after they faint the opponent.
	db DRAIN_HP_EFFECT
	db EXPLODE_EFFECT
	db DREAM_EATER_EFFECT
	db PAY_DAY_EFFECT
	db TWO_TO_FIVE_ATTACKS_EFFECT
	db EFFECT_1E
	db ATTACK_TWICE_EFFECT
	db RECOIL_EFFECT
	db TWINEEDLE_EFFECT
	db RAGE_EFFECT
	db -1 ; end
;@ path: engine/battle/core
SpecialEffects:
; Effects from arrays 2, 4, and 5B, minus Twineedle and Rage.
; Includes all effects that do not need to be called at the end of
; ExecutePlayerMove (or ExecuteEnemyMove), because they have already been handled
	db DRAIN_HP_EFFECT
	db EXPLODE_EFFECT
	db DREAM_EATER_EFFECT
	db PAY_DAY_EFFECT
	db SWIFT_EFFECT
	db TWO_TO_FIVE_ATTACKS_EFFECT
	db EFFECT_1E
	db CHARGE_EFFECT
	db SUPER_FANG_EFFECT
	db SPECIAL_DAMAGE_EFFECT
	db FLY_EFFECT
	db ATTACK_TWICE_EFFECT
	db JUMP_KICK_EFFECT
	db RECOIL_EFFECT
	; fallthrough
;@ path: engine/battle/core
SpecialEffectsCont:
; damaging moves whose effect is executed prior to damage calculation
	db THRASH_PETAL_DANCE_EFFECT
	db TRAPPING_EFFECT
	db -1 ; end

;@ path: engine/battle/core
;@ def SlidePlayerAndEnemySilhouettesOnScreen()
;@ The battle intro: the player's back and the opponent's picture slide in from both sides as dark silhouettes
;@ (the opponent and the player's body by scrolling part of the screen, the player's head as sprites), then get
;@ their colors and "Wild <MON> appeared!" or "<TRAINER> wants to fight!".
;@ test: skip times its scrolling to screen lines
SlidePlayerAndEnemySilhouettesOnScreen:
;> LoadPlayerBackPic()
	call LoadPlayerBackPic
;> wTextBoxID = MESSAGE_BOX
	ld a, MESSAGE_BOX ; the usual text box at the bottom of the screen
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
;> ClearScreenArea(coord(1, 5), 7, 3)
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, ((3) & $ff) << 8 + ((7) & $ff)
	call ClearScreenArea
;> DisableLCD()
	call DisableLCD
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> LoadHudAndHpBarAndStatusTilePatterns()
	call LoadHudAndHpBarAndStatusTilePatterns
;>@clr for i in range(TILEMAP_AREA):
	ld hl, vBGMap0
	ld bc, TILEMAP_AREA
.clearBackgroundLoop
;>     mem[vBGMap0 + i] = charmap(' ')[0]
	ld a, ' '
	ld [hli], a
;=@clr
	dec bc
	ld a, b
	or c
	jr nz, .clearBackgroundLoop
; copy the work RAM tile map to VRAM
;>@rows for row in range(SCREEN_HEIGHT):
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld de, vBGMap0
	ld b, SCREEN_HEIGHT
.copyRowLoop
;>     copy(vBGMap0 + row * TILEMAP_WIDTH, coord(0, row), SCREEN_WIDTH)
	ld c, SCREEN_WIDTH
.copyColumnLoop
	ld a, [hli]
	ld [de], a
	inc e
	dec c
	jr nz, .copyColumnLoop
;>     # the 12 tiles past the screen's right edge are skipped
	ld a, 12 ; number of off screen tiles to the right of screen in VRAM
	add e ; skip the off screen tiles
	ld e, a
	jr nc, .noCarry
	inc d
.noCarry
;=@rows
	dec b
	jr nz, .copyRowLoop
;> EnableLCD()
	call EnableLCD
;> hWY = 0x90                                        # window off screen
;> rWY = 0x90
	ld a, $90
	ldh [hWY], a
	ldh [rWY], a
;> hTileAnimations = 0
;> hSCY = 0
	xor a
	ldh [hTileAnimations], a
	ldh [hSCY], a
;> wUpdateSpritesEnabled = 0xFF
	dec a
	ld [wUpdateSpritesEnabled], a
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> body = 0x70
	ld b, $70
;> scroll = 0x90
	ld c, $90
;> hSCX = scroll
	ld a, c
	ldh [hSCX], a
;> DelayFrame()
	call DelayFrame
;> rBGP = 0b11100100                                 # silhouettes: dark palettes
	ld a, %11100100 ; inverted palette for silhouette effect
	ldh [rBGP], a
;> rOBP0 = 0b11100100
	ldh [rOBP0], a
;> rOBP1 = 0b11100100
	ldh [rOBP1], a
;> while scroll:
.slideSilhouettesLoop ; slide silhouettes of the player's pic and the enemy's pic onto the screen
;>     SetScrollXForSlidingPlayerBodyLeft(0x40, body)    # lines 0x40-0x5F: the player's body moves left
	ld h, b
	ld l, $40
	call SetScrollXForSlidingPlayerBodyLeft ; begin background scrolling on line $40
;>     body += 2
	inc b
	inc b
;>     SetScrollXForSlidingPlayerBodyLeft(0x60, 0)
	ld h, $0
	ld l, $60
	call SetScrollXForSlidingPlayerBodyLeft ; end background scrolling on line $60
;>     SlidePlayerHeadLeft()
	call SlidePlayerHeadLeft
;>     hSCX = scroll                                  # the rest: the opponent moves right
	ld a, c
	ldh [hSCX], a
;>     scroll -= 2
	dec c
	dec c
	jr nz, .slideSilhouettesLoop
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> hStartTileID = 0x31
	ld a, $31
	ldh [hStartTileID], a
;> predef(CopyUncompressedPicToTilemap, hl=coord(1, 5))   # the player's back
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld a, (CopyUncompressedPicToTilemapPredef - PredefPointers) / 3
	call Predef
;> hWY = 0
;> rWY = 0
	xor a
	ldh [hWY], a
	ldh [rWY], a
;> hAutoBGTransferEnabled = 1
	inc a
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> RunPaletteCommand(SET_PAL_BATTLE)
	ld b, SET_PAL_BATTLE
	call RunPaletteCommand
;> HideSprites()
	call HideSprites
;> farcall(PrintBeginningBattleText)
	ld hl, PrintBeginningBattleText
	ld b, BANK(PrintBeginningBattleText)
	jp Bankswitch

; when a battle is starting, silhouettes of the player's pic and the enemy's pic are slid onto the screen
; the lower of the player's pic (his body) is part of the background, but his head is a sprite
; the reason for this is that it shares Y coordinates with the lower part of the enemy pic, so background scrolling wouldn't work for both pics
; instead, the enemy pic is part of the background and uses the scroll register, while the player's head is a sprite and is slid by changing its X coordinates in a loop
;@ path: engine/battle/core
;@ def SlidePlayerHeadLeft()
;@ Move the 21 sprites of the player's head (the part of the back picture drawn as sprites) 2 pixels left.
SlidePlayerHeadLeft:
;> for i in range(7 * 3):                   # (keeps bc)
	push bc
	ld hl, wShadowOAMSprite00XCoord
	ld c, 7 * 3 ; number of OAM entries
	ld de, OBJ_SIZE
.loop
;>     mem[wShadowOAMSprite00XCoord + i * OBJ_SIZE] = (mem[wShadowOAMSprite00XCoord + i * OBJ_SIZE] - 2) & 0xFF
	dec [hl] ; decrement X
	dec [hl] ; decrement X
	add hl, de ; next OAM entry
	dec c
	jr nz, .loop
;> return
	pop bc
	ret

;@ path: engine/battle/core
;@ def SetScrollXForSlidingPlayerBodyLeft(line: l, scroll: h)
;@ Wait for screen line `line`, then set the horizontal scroll to `scroll` for the lines below it, and wait until
;@ the screen has left line `scroll` (used as a line number too).
;@ test: skip waits for screen lines
SetScrollXForSlidingPlayerBodyLeft:
;> wait_ly(line)
	ldh a, [rLY]
	cp l
	jr nz, SetScrollXForSlidingPlayerBodyLeft
;> rSCX = scroll
	ld a, h
	ldh [rSCX], a
.loop
;> if rLY == scroll:                                 # (the line is compared with the scroll value)
;>     wait_ly((scroll + 1) % 154)                   # until the screen has left that line
	ldh a, [rLY]
	cp h
	jr z, .loop
	ret

;@ path: engine/battle/core
;@ def StartBattle()
;@ Begin the battle: note the opponent's first Pokemon that can fight, let a trainer send it out, then send out
;@ the player's first Pokemon that can fight and enter the battle loop. In the Safari Zone there is no Pokemon to
;@ send out: the loop is the Safari menu (ball, bait, rock, run), after which the wild Pokemon may flee.
;@ test: skip runs the whole battle
StartBattle:
;> wPartyGainExpFlags = 0
	xor a
	ld [wPartyGainExpFlags], a
;> wPartyFoughtCurrentEnemyFlags = 0
	ld [wPartyFoughtCurrentEnemyFlags], a
;> wActionResultOrTookBattleTurn = 0
	ld [wActionResultOrTookBattleTurn], a
;> wFirstMonsNotOutYet = 1
	inc a
	ld [wFirstMonsNotOutYet], a
;> i = 0
	ld hl, wEnemyMon1HP
	ld bc, PARTYMON_STRUCT_LENGTH - 1
	ld d, $3
;> while not (mem[wEnemyMon1HP + i * PARTYMON_STRUCT_LENGTH] | mem[wEnemyMon1HP + i * PARTYMON_STRUCT_LENGTH + 1]):
.findFirstAliveEnemyMonLoop
	inc d
	ld a, [hli]
	or [hl]
	jr nz, .foundFirstAliveEnemyMon
;>     i += 1
	add hl, bc
	jr .findFirstAliveEnemyMonLoop
.foundFirstAliveEnemyMon
;> wSerialExchangeNybbleReceiveData = i + 4
	ld a, d
	ld [wSerialExchangeNybbleReceiveData], a
;> if wIsInBattle != 1:                              # a trainer battle
;>     EnemySendOutFirstMon()
	ld a, [wIsInBattle]
	dec a ; is it a trainer battle?
	call nz, EnemySendOutFirstMon ; if it is a trainer battle, send out enemy mon
;> DelayFrames(40)
	ld c, 40
	call DelayFrames
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> while True:
.checkAnyPartyAlive
;>     _, alive = AnyPartyAlive()
	call AnyPartyAlive
;>     if not alive:
;>         return HandlePlayerBlackOut()
	ld a, d
	and a
	jp z, HandlePlayerBlackOut ; jump if no mon is alive
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     if not wBattleType:
;>         break
	ld a, [wBattleType]
	and a ; is it a normal battle?
	jp z, .playerSendOutFirstMon ; if so, send out player mon
; safari zone battle
;>@saf     while True:                                   # Safari Zone
.displaySafariZoneBattleMenu
;>         if DisplayBattleMenu():
;>             return                                # the player ran
	call DisplayBattleMenu
	ret c ; return if the player ran from battle
;>         if wActionResultOrTookBattleTurn:
;>             break
	ld a, [wActionResultOrTookBattleTurn]
	and a ; was the item used successfully?
;=@saf
	jr z, .displaySafariZoneBattleMenu ; if not, display the menu again; XXX does this ever jump?
;>     if not wNumSafariBalls:
	ld a, [wNumSafariBalls]
	and a
	jr nz, .notOutOfSafariBalls
;>         LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>         return PrintText(addr(EnemyRan) - 90)             # its local text "You have no SAFARI BALLs!"
	ld hl, .outOfSafariBallsText
	jp PrintText
.notOutOfSafariBalls
;>     farcall(PrintSafariZoneBattleText)
	ld hl, PrintSafariZoneBattleText
	ld b, BANK(PrintSafariZoneBattleText)
	call Bankswitch
;>     speed = mem[wEnemyMonSpeed + 1]               # (the low byte of its Speed)
;>     chance = speed * 2
	ld a, [wEnemyMonSpeed + 1]
	add a
	ld b, a ; init b (which is later compared with random value) to (enemy speed % 256) * 2
;>     if speed > 127:
;>         return EnemyRan()
	jp c, EnemyRan ; if (enemy speed % 256) > 127, the enemy runs
;>     if wSafariBaitFactor:
	ld a, [wSafariBaitFactor]
	and a ; is bait factor 0?
	jr z, .checkEscapeFactor
; bait factor is not 0
; divide b by 4 (making the mon less likely to run)
;>         chance >>= 2
	srl b
	srl b
.checkEscapeFactor
;>     capped = False
;>     if wSafariEscapeFactor:
	ld a, [wSafariEscapeFactor]
	and a ; is escape factor 0?
	jr z, .compareWithRandomValue
; escape factor is not 0
; multiply b by 2 (making the mon more likely to run)
;>         chance *= 2
	sla b
;>         capped = chance > 0xFF
	jr nc, .compareWithRandomValue
; cap b at 255
;>         chance = min(chance, 0xFF)
	ld b, $ff
.compareWithRandomValue
;>     if Random(capped) < chance:
;>         return EnemyRan()
	call Random
	cp b
	jr nc, .checkAnyPartyAlive
	jr EnemyRan ; if b was greater than the random value, the enemy runs

.outOfSafariBallsText
	db TX_FAR
	dw _OutOfSafariBallsText
	db BANK(_OutOfSafariBallsText)
	db TX_END

.playerSendOutFirstMon
;> wWhichPokemon = 0
	xor a
	ld [wWhichPokemon], a
;> while HasMonFainted():
.findFirstAliveMonLoop
	call HasMonFainted
	jr nz, .foundFirstAliveMon
; fainted, go to the next one
;>     wWhichPokemon += 1
	ld hl, wWhichPokemon
	inc [hl]
	jr .findFirstAliveMonLoop
.foundFirstAliveMon
;> wPlayerMonNumber = wWhichPokemon
	ld a, [wWhichPokemon]
	ld [wPlayerMonNumber], a
;> entry = wPartySpecies - 1 + (wWhichPokemon + 1)
	inc a
	ld hl, wPartySpecies - 1
	ld c, a
	ld b, 0
	add hl, bc
;> wCurPartySpecies = mem[entry]
	ld a, [hl] ; species
	ld [wCurPartySpecies], a
;> wBattleMonSpecies2 = wCurPartySpecies
	ld [wBattleMonSpecies2], a
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> SlideTrainerPicOffScreen(coord(1, 5), 9)
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld a, $9
	call SlideTrainerPicOffScreen
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> flag = FLAG_SET << 8 | wWhichPokemon             # it has taken part
	ld a, [wWhichPokemon]
	ld c, a
	ld b, FLAG_SET
	push bc
;> predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=flag)
	ld hl, wPartyGainExpFlags
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> predef(FlagActionPredef, hl=wPartyFoughtCurrentEnemyFlags, bc=FLAG_SET << 8 | wWhichPokemon)
	ld hl, wPartyFoughtCurrentEnemyFlags
	pop bc
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> LoadBattleMonFromParty()
	call LoadBattleMonFromParty
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> SendOutMon()
	call SendOutMon
;> MainInBattleLoop()
	jr MainInBattleLoop

; wild mon or link battle enemy ran from battle
;@ path: engine/battle/core
;@ def EnemyRan()
;@ The wild Pokemon (or the link opponent) fled: "Wild <MON> ran!" with the running sound, and its picture
;@ slides away.
;@ test: skip waits for the sound to finish
EnemyRan:
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ld hl, WildRanText
	jr nz, .printText
; link battle
;>     wBattleResult = 0
	xor a
	ld [wBattleResult], a
;>     PrintText(EnemyRanText)
;> else:
;>     PrintText(WildRanText)
	ld hl, EnemyRanText
.printText
	call PrintText
;> PlaySoundWaitForCurrent(SFX_RUN)
	ld a, SFX_RUN
	call PlaySoundWaitForCurrent
;> hWhoseTurn = 0
	xor a
	ldh [hWhoseTurn], a
;> farcall(AnimationSlideEnemyMonOff)
	ld hl, AnimationSlideEnemyMonOff
	ld b, BANK(AnimationSlideEnemyMonOff)
	jp Bankswitch

;@ path: engine/battle/core
WildRanText:
	db TX_FAR
	dw _WildRanText
	db BANK(_WildRanText)
	db TX_END

;@ path: engine/battle/core
EnemyRanText:
	db TX_FAR
	dw _EnemyRanText
	db BANK(_EnemyRanText)
	db TX_END

;@ path: engine/battle/core
;@ def MainInBattleLoop()
;@ One battle turn after another: stop when a Pokemon faints, show the battle menu and the move menu (not while
;@ recharging, raging, thrashing, charging, asleep, frozen, biding or trapped), let the opponent choose, decide
;@ who moves first (Quick Attack first, Counter last, else the faster Pokemon, a coin toss on a tie), then both
;@ attacks with the poison/burn/Leech Seed damage after each.
;@ test: skip runs the whole battle
MainInBattleLoop:
;> while True:
;>     ReadPlayerMonCurHPAndStatus()
	call ReadPlayerMonCurHPAndStatus
;>     if not (mem[wBattleMonHP] | mem[wBattleMonHP + 1]):
;>         return HandlePlayerMonFainted()
	ld hl, wBattleMonHP
	ld a, [hli]
	or [hl] ; is battle mon HP 0?
	jp z, HandlePlayerMonFainted  ; if battle mon HP is 0, jump
;>     if not (mem[wEnemyMonHP] | mem[wEnemyMonHP + 1]):
;>         return HandleEnemyMonFainted()
	ld hl, wEnemyMonHP
	ld a, [hli]
	or [hl] ; is enemy mon HP 0?
	jp z, HandleEnemyMonFainted ; if enemy mon HP is 0, jump
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     wFirstMonsNotOutYet = 0
	xor a
	ld [wFirstMonsNotOutYet], a
;>     if not wPlayerBattleStatus2 & (1 << NEEDS_TO_RECHARGE | 1 << USING_RAGE):
	ld a, [wPlayerBattleStatus2]
	and (1 << NEEDS_TO_RECHARGE) | (1 << USING_RAGE) ; check if the player is using Rage or needs to recharge
	jr nz, .selectEnemyMove
; the player is not using Rage and doesn't need to recharge
;>         wEnemyBattleStatus1 &= ~(1 << FLINCHED)
	ld hl, wEnemyBattleStatus1
	res FLINCHED, [hl] ; reset flinch bit
;>         wPlayerBattleStatus1 &= ~(1 << FLINCHED)
	ld hl, wPlayerBattleStatus1
	res FLINCHED, [hl] ; reset flinch bit
;>         if not wPlayerBattleStatus1 & (1 << THRASHING_ABOUT | 1 << CHARGING_UP):
	ld a, [hl]
	and (1 << THRASHING_ABOUT) | (1 << CHARGING_UP) ; check if the player is thrashing about or charging for an attack
	jr nz, .selectEnemyMove ; if so, jump
; the player is neither thrashing about nor charging for an attack
;>             if DisplayBattleMenu():
;>                 return                            # the player ran
	call DisplayBattleMenu ; show battle menu
	ret c ; return if player ran from battle
;>             if wEscapedFromBattle:
;>                 return                            # (Poke Doll)
	ld a, [wEscapedFromBattle]
	and a
	ret nz ; return if pokedoll was used to escape from battle
;>             busy = mem[wBattleMonStatus] & (1 << FRZ | SLP_MASK) or wPlayerBattleStatus1 & (1 << STORING_ENERGY | 1 << USING_TRAPPING_MOVE)
;>             if not busy:
	ld a, [wBattleMonStatus]
	and (1 << FRZ) | SLP_MASK
	jr nz, .selectEnemyMove ; if so, jump
	ld a, [wPlayerBattleStatus1]
	and (1 << STORING_ENERGY) | (1 << USING_TRAPPING_MOVE) ; check player is using Bide or using a multi-turn attack like wrap
	jr nz, .selectEnemyMove ; if so, jump
;>                 if wEnemyBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	ld a, [wEnemyBattleStatus1]
	bit USING_TRAPPING_MOVE, a ; check if enemy is using a multi-turn attack like wrap
	jr z, .selectPlayerMove ; if not, jump
; enemy is using a multi-turn attack like wrap, so player is trapped and cannot execute a move
;>                     wPlayerSelectedMove = CANNOT_MOVE
	ld a, CANNOT_MOVE
	ld [wPlayerSelectedMove], a
	jr .selectEnemyMove
.selectPlayerMove
;>                 elif not wActionResultOrTookBattleTurn:
	ld a, [wActionResultOrTookBattleTurn]
	and a ; has the player already used the turn (e.g. by using an item, trying to run or switching pokemon)
	jr nz, .selectEnemyMove
;>                     wMoveMenuType = 0
	ld [wMoveMenuType], a
;>                     wAnimationID = 1
	inc a
	ld [wAnimationID], a
;>                     wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a
;>                     chosen = MoveSelectionMenu()
	call MoveSelectionMenu
	push af
;>                     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>                     DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;>                     if not chosen:
;>                         continue                  # back to the battle menu
	pop af
	jr nz, MainInBattleLoop ; if the player didn't select a move, jump
.selectEnemyMove
;>     SelectEnemyMove()
	call SelectEnemyMove
;>     if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .noLinkBattle
; link battle
;>         received = wSerialExchangeNybbleReceiveData
	ld a, [wSerialExchangeNybbleReceiveData]
;>         if received == LINKBATTLE_RUN:
;>             return EnemyRan()
	cp LINKBATTLE_RUN
	jp z, EnemyRan
;>         if received not in (LINKBATTLE_STRUGGLE, LINKBATTLE_NO_ACTION) and received >= 4:   # it switched
	cp LINKBATTLE_STRUGGLE
	jr z, .noLinkBattle
	cp LINKBATTLE_NO_ACTION
	jr z, .noLinkBattle
	sub 4
	jr c, .noLinkBattle
; the link battle enemy has switched mons
;>             if wPlayerBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	ld a, [wPlayerBattleStatus1]
	bit USING_TRAPPING_MOVE, a ; check if using multi-turn move like Wrap
	jr z, .specialMoveNotUsed
;>                 move = mem[wBattleMonMoves + wPlayerMoveListIndex]
	ld a, [wPlayerMoveListIndex]
	ld hl, wBattleMonMoves
	ld c, a
	ld b, 0
	add hl, bc
	ld a, [hl]
;>                 if move == METRONOME:             # (no Mirror Move check)
	cp METRONOME ; a MIRROR MOVE check is missing, might lead to a desync in link battles
	             ; when combined with multi-turn moves
	jr nz, .specialMoveNotUsed
;>                     wPlayerSelectedMove = METRONOME
	ld [wPlayerSelectedMove], a
.specialMoveNotUsed
;>             farcall(SwitchEnemyMon)
	ld hl, SwitchEnemyMon
	ld b, BANK(SwitchEnemyMon)
	call Bankswitch
.noLinkBattle
;>     player, enemy = wPlayerSelectedMove, wEnemySelectedMove
;>     if player == QUICK_ATTACK and enemy != QUICK_ATTACK:
	ld a, [wPlayerSelectedMove]
	cp QUICK_ATTACK
	jr nz, .playerDidNotUseQuickAttack
	ld a, [wEnemySelectedMove]
	cp QUICK_ATTACK
	jr z, .compareSpeed  ; if both used Quick Attack
;>         player_first = True
	jp .playerMovesFirst ; if player used Quick Attack and enemy didn't
.playerDidNotUseQuickAttack
;>     elif enemy == QUICK_ATTACK and player != QUICK_ATTACK:
;>         player_first = False
	ld a, [wEnemySelectedMove]
	cp QUICK_ATTACK
	jr z, .enemyMovesFirst ; if enemy used Quick Attack and player didn't
;>     elif player == COUNTER and enemy != COUNTER:
	ld a, [wPlayerSelectedMove]
	cp COUNTER
	jr nz, .playerDidNotUseCounter
	ld a, [wEnemySelectedMove]
	cp COUNTER
	jr z, .compareSpeed ; if both used Counter
;>         player_first = False
	jr .enemyMovesFirst ; if player used Counter and enemy didn't
.playerDidNotUseCounter
;>     elif enemy == COUNTER and player != COUNTER:
;>         player_first = True
	ld a, [wEnemySelectedMove]
	cp COUNTER
	jr z, .playerMovesFirst ; if enemy used Counter and player didn't
.compareSpeed
;>     else:
;>         slower, same = StringCmp(wBattleMonSpeed, wEnemyMonSpeed, 2)
	ld de, wBattleMonSpeed ; player speed value
	ld hl, wEnemyMonSpeed ; enemy speed value
	ld c, $2
	call StringCmp ; compare speed values
;>         if same:                                  # a coin toss; both Game Boys of a link battle agree on it
;>@inv             invert = hSerialConnectionStatus == USING_INTERNAL_CLOCK
;>@toss             player_first = (BattleRandom() < 128) != invert
	jr z, .speedEqual
;>         else:
;>             player_first = not slower
	jr nc, .playerMovesFirst ; if player is faster
	jr .enemyMovesFirst ; if enemy is faster
.speedEqual ; 50/50 chance for both players
;=@inv
	ldh a, [hSerialConnectionStatus]
	cp USING_INTERNAL_CLOCK
	jr z, .invertOutcome
;=@toss
	call BattleRandom
	cp 50 * $ff / 100 + 1
	jr c, .playerMovesFirst
	jr .enemyMovesFirst
.invertOutcome
;=@toss
	call BattleRandom
	cp 50 * $ff / 100 + 1
	jr c, .enemyMovesFirst
	jr .playerMovesFirst
.enemyMovesFirst
;>     if not player_first:
;>         hWhoseTurn = 1
	ld a, $1
	ldh [hWhoseTurn], a
;>         if not farcall(TrainerAI):                       # the AI may use an item or switch instead
	ld hl, TrainerAI
	ld b, BANK(TrainerAI)
	call Bankswitch
	jr c, .AIActionUsedEnemyFirst
;>             ExecuteEnemyMove()
	call ExecuteEnemyMove
;>             if wEscapedFromBattle:
;>                 return
	ld a, [wEscapedFromBattle]
	and a ; was Teleport, Roar, or Whirlwind used to escape from battle?
	ret nz ; if so, return
;>             if not b:                             # b = 0: the target fainted
;>                 return HandlePlayerMonFainted()
	ld a, b
	and a
	jp z, HandlePlayerMonFainted
.AIActionUsedEnemyFirst
;>         if HandlePoisonBurnLeechSeed():
;>             return HandleEnemyMonFainted()
	call HandlePoisonBurnLeechSeed
	jp z, HandleEnemyMonFainted
;>         DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;>         ExecutePlayerMove()
	call ExecutePlayerMove
;>         if wEscapedFromBattle:
;>             return
	ld a, [wEscapedFromBattle]
	and a ; was Teleport, Roar, or Whirlwind used to escape from battle?
	ret nz ; if so, return
;>         if not b:
;>             return HandleEnemyMonFainted()
	ld a, b
	and a
	jp z, HandleEnemyMonFainted
;>         if HandlePoisonBurnLeechSeed():
;>             return HandlePlayerMonFainted()
	call HandlePoisonBurnLeechSeed
	jp z, HandlePlayerMonFainted
;=@dh
	call DrawHUDsAndHPBars
;=@cn
	call CheckNumAttacksLeft
	jp MainInBattleLoop
.playerMovesFirst
;>     else:
;>         ExecutePlayerMove()
	call ExecutePlayerMove
;>         if wEscapedFromBattle:
;>             return
	ld a, [wEscapedFromBattle]
	and a ; was Teleport, Roar, or Whirlwind used to escape from battle?
	ret nz ; if so, return
;>         if not b:
;>             return HandleEnemyMonFainted()
	ld a, b
	and a
	jp z, HandleEnemyMonFainted
;>         if HandlePoisonBurnLeechSeed():
;>             return HandlePlayerMonFainted()
	call HandlePoisonBurnLeechSeed
	jp z, HandlePlayerMonFainted
;>         DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;>         hWhoseTurn = 1
	ld a, $1
	ldh [hWhoseTurn], a
;>         if not farcall(TrainerAI):
	ld hl, TrainerAI
	ld b, BANK(TrainerAI)
	call Bankswitch
	jr c, .AIActionUsedPlayerFirst
;>             ExecuteEnemyMove()
	call ExecuteEnemyMove
;>             if wEscapedFromBattle:
;>                 return
	ld a, [wEscapedFromBattle]
	and a ; was Teleport, Roar, or Whirlwind used to escape from battle?
	ret nz ; if so, return
;>             if not b:
;>                 return HandlePlayerMonFainted()
	ld a, b
	and a
	jp z, HandlePlayerMonFainted
.AIActionUsedPlayerFirst
;>         if HandlePoisonBurnLeechSeed():
;>             return HandleEnemyMonFainted()
	call HandlePoisonBurnLeechSeed
	jp z, HandleEnemyMonFainted
;>@dh     DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;>@cn     CheckNumAttacksLeft()                      # and the next turn
	call CheckNumAttacksLeft
	jp MainInBattleLoop

;@ path: engine/battle/core
;@ def HandlePoisonBurnLeechSeed() -> zero
;@ End of turn damage for the Pokemon whose turn it is: burn or poison takes 1/16 of its max HP (more each turn
;@ with Toxic), Leech Seed drains 1/16 to the opponent. Zero if it fainted.
HandlePoisonBurnLeechSeed:
;> if hWhoseTurn == 0:
;>     hp, status = wBattleMonHP, mem[wBattleMonStatus]
	ld hl, wBattleMonHP
	ld de, wBattleMonStatus
	ldh a, [hWhoseTurn]
	and a
	jr z, .playersTurn
;> else:
;>     hp, status = wEnemyMonHP, mem[wEnemyMonStatus]
	ld hl, wEnemyMonHP
	ld de, wEnemyMonStatus
.playersTurn
;> if status & (1 << BRN | 1 << PSN):
	ld a, [de]
	and (1 << BRN) | (1 << PSN)
	jr z, .notBurnedOrPoisoned
;>     text = HurtByPoisonText
	push hl
	ld hl, HurtByPoisonText
;>     if status & 1 << BRN:
;>         text = HurtByBurnText
	ld a, [de]
	and 1 << BRN
	jr z, .poisoned
	ld hl, HurtByBurnText
.poisoned
;>     PrintText(text)
	call PrintText
;>     wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>     PlayMoveAnimation(BURN_PSN_ANIM)
	ld a, BURN_PSN_ANIM
	call PlayMoveAnimation   ; play burn/poison animation
;>     HandlePoisonBurnLeechSeed_DecreaseOwnHP(hp)
	pop hl
	call HandlePoisonBurnLeechSeed_DecreaseOwnHP
.notBurnedOrPoisoned
;> status2 = wPlayerBattleStatus2 if hWhoseTurn == 0 else wEnemyBattleStatus2
	ld de, wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	jr z, .playersTurn2
	ld de, wEnemyBattleStatus2
.playersTurn2
;> if status2 >> SEEDED & 1:                         # seeded (the top bit)
	ld a, [de]
	add a
	jr nc, .notLeechSeeded
;>     turn = hWhoseTurn
	push hl
	ldh a, [hWhoseTurn]
	push af
;>     hWhoseTurn ^= 1                               # the animation comes from the opponent
	xor $1
	ldh [hWhoseTurn], a
;>     wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>     PlayMoveAnimation(ABSORB)
	ld a, ABSORB
	call PlayMoveAnimation ; play leech seed animation (from opposing mon)
;>     hWhoseTurn = turn
	pop af
	ldh [hWhoseTurn], a
;>     drained = HandlePoisonBurnLeechSeed_DecreaseOwnHP(hp)
	pop hl
	call HandlePoisonBurnLeechSeed_DecreaseOwnHP
;>     HandlePoisonBurnLeechSeed_IncreaseEnemyHP(drained)
	call HandlePoisonBurnLeechSeed_IncreaseEnemyHP
;>     PrintText(HurtByLeechSeedText)
	push hl
	ld hl, HurtByLeechSeedText
	call PrintText
	pop hl
.notLeechSeeded
;> if mem[hp] | mem[hp + 1]:
;>     return False
	ld a, [hli]
	or [hl]
	ret nz          ; test if fainted
;> DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
;> return True
	xor a
	ret

;@ path: engine/battle/core
HurtByPoisonText:
	db TX_FAR
	dw _HurtByPoisonText
	db BANK(_HurtByPoisonText)
	db TX_END

;@ path: engine/battle/core
HurtByBurnText:
	db TX_FAR
	dw _HurtByBurnText
	db BANK(_HurtByBurnText)
	db TX_END

;@ path: engine/battle/core
HurtByLeechSeedText:
	db TX_FAR
	dw _HurtByLeechSeedText
	db BANK(_HurtByLeechSeedText)
	db TX_END

; decreases the mon's current HP by 1/16 of the Max HP (multiplied by number of toxic ticks if active)
; note that the toxic ticks are considered even if the damage is not poison (hence the Leech Seed glitch)
; hl: HP pointer
; bc (out): total damage
;@ path: engine/battle/core
;@ def HandlePoisonBurnLeechSeed_DecreaseOwnHP(hp: hl) -> bc
;@ Take 1/16 of the max HP (at least 1; times the Toxic counter, which goes up by one, if badly poisoned) off the
;@ HP at hp (wBattleMonHP or wEnemyMonHP) and animate the bar. Returns the damage, even when the HP had less left.
HandlePoisonBurnLeechSeed_DecreaseOwnHP:
;> max_hp = mem[hp + 14] << 8 | mem[hp + 15]
	push hl
	push hl
	ld bc, $e      ; skip to max HP
	add hl, bc
;> wHPBarMaxHP[1] = mem[hp + 14]
	ld a, [hli]    ; load max HP
	ld [wHPBarMaxHP+1], a
	ld b, a
;> wHPBarMaxHP[0] = mem[hp + 15]
	ld a, [hl]
	ld [wHPBarMaxHP], a
	ld c, a
;> damage = (max_hp >> 10) << 8 | (max_hp >> 2 & 0xFF) >> 2  # max HP / 16 while it is below 1024
	srl b
	rr c
	srl b
	rr c
	srl c
	srl c         ; c = max HP/16 (assumption: HP < 1024)
;> if not damage & 0xFF:
;>     damage += 1
	ld a, c
	and a
	jr nz, .nonZeroDamage
	inc c         ; damage is at least 1
.nonZeroDamage
;> if hWhoseTurn == 0:
;>     status3, counter = wPlayerBattleStatus3, addr(wPlayerToxicCounter)
	ld hl, wPlayerBattleStatus3
	ld de, wPlayerToxicCounter
	ldh a, [hWhoseTurn]
	and a
	jr z, .playersTurn
;> else:
;>     status3, counter = wEnemyBattleStatus3, addr(wEnemyToxicCounter)
	ld hl, wEnemyBattleStatus3
	ld de, wEnemyToxicCounter
.playersTurn
;> if status3 >> BADLY_POISONED & 1:        # badly poisoned (Toxic)
	bit BADLY_POISONED, [hl]
	jr z, .noToxic
;>     n = mem[counter] = mem[counter] + 1 & 0xFF   # the counter goes up each time
	ld a, [de]    ; increment toxic counter
	inc a
	ld [de], a
;>     damage = damage * (n or 256) & 0xFFFF
	ld hl, 0
.toxicTicksLoop
	add hl, bc
	dec a
	jr nz, .toxicTicksLoop
	ld b, h       ; bc = damage * toxic counter
	ld c, l
.noToxic
;> old = mem[hp] << 8 | mem[hp + 1]
;> wHPBarOldHP[0] = old & 0xFF
	pop hl
	inc hl
	ld a, [hl]    ; subtract total damage from current HP
	ld [wHPBarOldHP], a
;> new = old - damage
;> mem[hp + 1] = wHPBarNewHP[0] = new & 0xFF
	sub c
	ld [hld], a
	ld [wHPBarNewHP], a
;> wHPBarOldHP[1] = old >> 8
;> mem[hp] = wHPBarNewHP[1] = new >> 8 & 0xFF
	ld a, [hl]
	ld [wHPBarOldHP+1], a
	sbc b
	ld [hl], a
	ld [wHPBarNewHP+1], a
;> if new < 0:                                      # overkill: zero HP
;>     mem[hp], mem[hp + 1] = 0, 0
	jr nc, .noOverkill
	xor a         ; overkill: zero HP
	ld [hli], a
	ld [hl], a
;>     wHPBarNewHP[0], wHPBarNewHP[1] = 0, 0
	ld [wHPBarNewHP], a
	ld [wHPBarNewHP+1], a
.noOverkill
;> UpdateCurMonHPBar()
	call UpdateCurMonHPBar
;> return damage
	pop hl
	ret

; adds bc to enemy HP
; bc isn't updated if HP subtracted was capped to prevent overkill
;@ path: engine/battle/core
;@ def HandlePoisonBurnLeechSeed_IncreaseEnemyHP(amount: bc)
;@ Leech Seed: give the drained HP to the opponent of the Pokemon whose turn it is (up to its max HP) and animate
;@ its bar.
HandlePoisonBurnLeechSeed_IncreaseEnemyHP:
;> max_hp_at = wBattleMonMaxHP if hWhoseTurn else wEnemyMonMaxHP
;> hp_at = max_hp_at + (wBattleMonHP - wBattleMonMaxHP)
	push hl
	ld hl, wEnemyMonMaxHP
	ldh a, [hWhoseTurn]
	and a
	jr z, .playersTurn
	ld hl, wBattleMonMaxHP
.playersTurn
;> max_hp = mem[max_hp_at] << 8 | mem[max_hp_at + 1]
;> wHPBarMaxHP[1] = max_hp >> 8
	ld a, [hli]
	ld [wHPBarMaxHP+1], a
;> wHPBarMaxHP[0] = max_hp & 0xFF
	ld a, [hl]
	ld [wHPBarMaxHP], a
	ld de, wBattleMonHP - wBattleMonMaxHP
	add hl, de           ; skip back from max hp to current hp
;> old = mem[hp_at] << 8 | mem[hp_at + 1]
;> wHPBarOldHP[0] = old & 0xFF
	ld a, [hl]
	ld [wHPBarOldHP], a ; add bc to current HP
;> new = (old + amount) & 0xFFFF
;> mem[hp_at + 1] = wHPBarNewHP[0] = new & 0xFF
	add c
	ld [hld], a
	ld [wHPBarNewHP], a
;> wHPBarOldHP[1] = old >> 8
;> mem[hp_at] = wHPBarNewHP[1] = new >> 8
	ld a, [hl]
	ld [wHPBarOldHP+1], a
	adc b
	ld [hli], a
	ld [wHPBarNewHP+1], a
;> low = lo(new) - lo(max_hp)                       # new minus max_hp, low bytes first
	ld a, [wHPBarMaxHP]
	ld c, a
	ld a, [hld]
	sub c
;> if new >= max_hp:                                # overfull: just the max
	ld a, [wHPBarMaxHP+1]
	ld b, a
	ld a, [hl]
	sbc b
	jr c, .noOverfullHeal
;>     new = max_hp
;>     mem[hp_at] = wHPBarNewHP[1] = new >> 8
	ld a, b                ; overfull heal, set HP to max HP
	ld [hli], a
	ld [wHPBarNewHP+1], a
;>     mem[hp_at + 1] = wHPBarNewHP[0] = new & 0xFF
	ld a, c
	ld [hl], a
	ld [wHPBarNewHP], a
.noOverfullHeal
;> hWhoseTurn ^= 1
	ldh a, [hWhoseTurn]
	xor $1
	ldh [hWhoseTurn], a
;> UpdateCurMonHPBar()
	call UpdateCurMonHPBar
;> hWhoseTurn ^= 1
	ldh a, [hWhoseTurn]
	xor $1
	ldh [hWhoseTurn], a
	pop hl
	ret

;@ path: engine/battle/core
;@ def UpdateCurMonHPBar()
;@ Animate the HP bar of the Pokemon whose turn it is (the player's at the bottom right, the enemy's at the top).
UpdateCurMonHPBar:
;> if hWhoseTurn:
	; tile pointer to player HP bar
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ldh a, [hWhoseTurn]
	and a
	ld a, $1
	jr z, .playersTurn
;>     wHPBarType = 0
;>     predef(UpdateHPBar2, hl=coord(2, 2))
	; tile pointer to enemy HP bar
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	xor a
.playersTurn
;> else:
;>     wHPBarType = 1
;>     predef(UpdateHPBar2, hl=coord(10, 9))
	push bc
	ld [wHPBarType], a
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
	pop bc
	ret

;@ path: engine/battle/core
;@ def CheckNumAttacksLeft()
;@ A trapping move (Wrap, Bind...) ends for a side that has no attacks left in it.
CheckNumAttacksLeft:
;> if not wPlayerNumAttacksLeft:
;>     wPlayerBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld a, [wPlayerNumAttacksLeft]
	and a
	jr nz, .checkEnemy
; player has 0 attacks left
	ld hl, wPlayerBattleStatus1
	res USING_TRAPPING_MOVE, [hl] ; player not using multi-turn attack like wrap any more
.checkEnemy
;> if not wEnemyNumAttacksLeft:
;>     wEnemyBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld a, [wEnemyNumAttacksLeft]
	and a
	ret nz
; enemy has 0 attacks left
	ld hl, wEnemyBattleStatus1
	res USING_TRAPPING_MOVE, [hl] ; enemy not using multi-turn attack like wrap any more
	ret

;@ path: engine/battle/core
;@ def HandleEnemyMonFainted()
;@ The opponent's Pokemon fainted: experience and so on (FaintEnemyPokemon). The battle ends if the player has
;@ no Pokemon left, in a wild battle, or when the trainer has none left; otherwise the player may need to send out
;@ another Pokemon, the trainer sends out the next one and the battle goes on.
;@ test: skip runs the whole battle
HandleEnemyMonFainted:
;> wInHandlePlayerMonFainted = 0
	xor a
	ld [wInHandlePlayerMonFainted], a
;> FaintEnemyPokemon()
	call FaintEnemyPokemon
;> if not AnyPartyAlive()[1]:
;>     return HandlePlayerBlackOut()
	call AnyPartyAlive
	ld a, d
	and a
	jp z, HandlePlayerBlackOut ; if no party mons are alive, the player blacks out
;> if mem[wBattleMonHP] | mem[wBattleMonHP + 1]:
;>     DrawPlayerHUDAndHPBar()
	ld hl, wBattleMonHP
	ld a, [hli]
	or [hl] ; is battle mon HP zero?
	call nz, DrawPlayerHUDAndHPBar ; if battle mon HP is not zero, draw player HD and HP bar
;> if wIsInBattle == 1:
;>     return                                        # wild battle: won
	ld a, [wIsInBattle]
	dec a
	ret z ; return if it's a wild battle
;> if AnyEnemyPokemonAliveCheck():
;>     return TrainerBattleVictory()
	call AnyEnemyPokemonAliveCheck
	jp z, TrainerBattleVictory
;> if not (mem[wBattleMonHP] | mem[wBattleMonHP + 1]):
	ld hl, wBattleMonHP
	ld a, [hli]
	or [hl] ; does battle mon have 0 HP?
	jr nz, .skipReplacingBattleMon ; if not, skip replacing battle mon
;>     if DoUseNextMonDialogue():                    # (only asks in wild battles, so never here)
;>         return
	call DoUseNextMonDialogue ; this call is useless in a trainer battle. it shouldn't be here
	ret c
;>     ChooseNextMon()
	call ChooseNextMon
.skipReplacingBattleMon
;> wActionResultOrTookBattleTurn = 1
	ld a, $1
	ld [wActionResultOrTookBattleTurn], a
;> if ReplaceFaintedEnemyMon():
;>     return EnemyRan()
	call ReplaceFaintedEnemyMon
	jp z, EnemyRan
;> wActionResultOrTookBattleTurn = 0
	xor a
	ld [wActionResultOrTookBattleTurn], a
;> MainInBattleLoop()
	jp MainInBattleLoop

;@ path: engine/battle/core
;@ def FaintEnemyPokemon()
;@ The opponent's Pokemon faints: zero its HP in the party, clear the battle effects, slide its picture down with
;@ the faint sound (or the wild victory music), "Enemy <MON> fainted!", and give experience to the Pokemon that
;@ fought it - with an EXP.ALL in the bag half of it is shared by the whole party. Only the high byte of the
;@ player's Bide damage is cleared.
;@ test: skip waits for sound effects
FaintEnemyPokemon:
;> ReadPlayerMonCurHPAndStatus()
	call ReadPlayerMonCurHPAndStatus
;> if wIsInBattle != 1:
	ld a, [wIsInBattle]
	dec a
	jr z, .wild
;>     hp = wEnemyMon1HP + mem[wEnemyMonPartyPos] * PARTYMON_STRUCT_LENGTH
	ld a, [wEnemyMonPartyPos]
	ld hl, wEnemyMon1HP
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     mem[hp] = 0
;>     mem[hp + 1] = 0
	xor a
	ld [hli], a
	ld [hl], a
.wild
;> wPlayerBattleStatus1 &= ~(1 << ATTACKING_MULTIPLE_TIMES)
	ld hl, wPlayerBattleStatus1
	res ATTACKING_MULTIPLE_TIMES, [hl]
; Bug. This only zeroes the high byte of the player's accumulated damage,
; setting the accumulated damage to itself mod 256 instead of 0 as was probably
; intended. That alone is problematic, but this mistake has another more severe
; effect. This function's counterpart for when the player mon faints,
; RemoveFaintedPlayerMon, zeroes both the high byte and the low byte. In a link
; battle, the other player's Game Boy will call that function in response to
; the enemy mon (the player mon from the other side's perspective) fainting,
; and the states of the two Game Boys will go out of sync unless the damage
; was congruent to 0 modulo 256.
;> wPlayerBideAccumulatedDamage[0] = 0
	xor a
	ld [wPlayerBideAccumulatedDamage], a
;> fill(addr(wEnemyStatsToDouble), 0, 5)            # wEnemyStatsToDouble ... wEnemyBattleStatus3
	ld hl, wEnemyStatsToDouble ; clear enemy statuses
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wEnemyDisabledMove = 0
	ld [wEnemyDisabledMove], a
;> wEnemyDisabledMoveNumber = 0
	ld [wEnemyDisabledMoveNumber], a
;> wEnemyMonMinimized = 0
	ld [wEnemyMonMinimized], a
;> wPlayerUsedMove = 0
	ld hl, wPlayerUsedMove
	ld [hli], a
;> wEnemyUsedMove = 0
	ld [hl], a
;> SlideDownFaintedMonPic(coord(12, 5), coord(12, 6))
	ld hl, (5) * SCREEN_WIDTH + (12) + wTileMap
	ld de, (6) * SCREEN_WIDTH + (12) + wTileMap
	call SlideDownFaintedMonPic
;> ClearScreenArea(coord(0, 0), 11, 4)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((4) & $ff) << 8 + ((11) & $ff)
	call ClearScreenArea
;> if wIsInBattle == 1:                              # a wild battle: the victory music
;>@e1     EndLowHealthAlarm()
;>@e2     PlayBattleVictoryMusic(MUSIC_DEFEATED_WILD_MON)  # even if the player's Pokemon fainted too
	ld a, [wIsInBattle]
	dec a
	jr z, .wild_win
;> else:
;>     wFrequencyModifier = 0
	xor a
	ld [wFrequencyModifier], a
;>     wTempoModifier = 0
	ld [wTempoModifier], a
;>     PlaySoundWaitForCurrent(SFX_FAINT_FALL)
	ld a, SFX_FAINT_FALL
	call PlaySoundWaitForCurrent
.sfxwait
;>     while wChannelSoundIDs[CHAN5] == SFX_FAINT_FALL:
;>         wait_vblank_flag()                        # the sound plays on in the VBlank interrupt
	ld a, [wChannelSoundIDs + CHAN5]
	cp SFX_FAINT_FALL
	jr z, .sfxwait
;>     PlaySound(SFX_FAINT_THUD)
	ld a, SFX_FAINT_THUD
	call PlaySound
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
	jr .sfxplayed
.wild_win
;=@e1
	call EndLowHealthAlarm
;=@e2
	ld a, MUSIC_DEFEATED_WILD_MON
	call PlayBattleVictoryMusic
.sfxplayed
; bug: win sfx is played for wild battles before checking for player mon HP
; this can lead to odd scenarios where both player and enemy faint, as the win sfx plays yet the player never won the battle
;> if not (mem[wBattleMonHP] | mem[wBattleMonHP + 1]):   # the player's Pokemon fainted too
	ld hl, wBattleMonHP
	ld a, [hli]
	or [hl]
	jr nz, .playermonnotfaint
;>     if not wInHandlePlayerMonFainted:            # (not twice)
	ld a, [wInHandlePlayerMonFainted]
	and a ; was this called by HandlePlayerMonFainted?
	jr nz, .playermonnotfaint ; if so, don't call RemoveFaintedPlayerMon twice
;>         RemoveFaintedPlayerMon()
	call RemoveFaintedPlayerMon
.playermonnotfaint
;> if not AnyPartyAlive()[1]:
;>     return
	call AnyPartyAlive
	ld a, d
	and a
	ret z
;> PrintText(EnemyMonFaintedText)
	ld hl, EnemyMonFaintedText
	call PrintText
;> PrintEmptyString()
	call PrintEmptyString
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> wBattleResult = 0
	xor a
	ld [wBattleResult], a
;> exp_all = not IsItemInBag(EXP_ALL)
	ld b, EXP_ALL
	call IsItemInBag
	push af
;> if exp_all:                                       # halve base stats and base experience
	jr z, .giveExpToMonsThatFought ; if no exp all, then jump

; the player has exp all
; first, we halve the values that determine exp gain
; the enemy mon base stats are added to stat exp, so they are halved
; the base exp (which determines normal exp) is also halved
;>     for i in range(NUM_STATS + 2):
	ld hl, wEnemyMonBaseStats
	ld b, NUM_STATS + 2
.halveExpDataLoop
;>         mem[addr(wEnemyMonBaseStats) + i] >>= 1
	srl [hl]
	inc hl
	dec b
	jr nz, .halveExpDataLoop

; give exp (divided evenly) to the mons that actually fought in battle against the enemy mon that has fainted
; if exp all is in the bag, this will be only be half of the stat exp and normal exp, due to the above loop
.giveExpToMonsThatFought
;> wBoostExpByExpAll = 0
	xor a
	ld [wBoostExpByExpAll], a
;> farcall(GainExperience)
	ld hl, GainExperience
	ld b, BANK(GainExperience)
	call Bankswitch
;> if not exp_all:
;>     return
	pop af
	ret z ; return if no exp all

; the player has exp all
; now, set the gain exp flag for every party member
; half of the total stat exp and normal exp will divided evenly amongst every party member
;> wBoostExpByExpAll = TRUE
	ld a, TRUE
	ld [wBoostExpByExpAll], a
;> n = wPartyCount
	ld a, [wPartyCount]
;> flags = 0
	ld b, 0
;>@fl for _ in range(n or 256):                       # one bit for each party Pokemon
.gainExpFlagsLoop
;>     flags = (flags << 1 | 1) & 0xFF
	scf
	rl b
;=@fl
	dec a
	jr nz, .gainExpFlagsLoop
;> wPartyGainExpFlags = flags
	ld a, b
	ld [wPartyGainExpFlags], a
;> farcall(GainExperience)
	ld hl, GainExperience
	ld b, BANK(GainExperience)
	jp Bankswitch

;@ path: engine/battle/core
EnemyMonFaintedText:
	db TX_FAR
	dw _EnemyMonFaintedText
	db BANK(_EnemyMonFaintedText)
	db TX_END

;@ path: engine/battle/core
;@ def EndLowHealthAlarm()
;@ The battle is won: stop the low HP beeping and keep it off until the next battle.
EndLowHealthAlarm:
; This function is called when the player has the won the battle. It turns off
; the low health alarm and prevents it from reactivating until the next battle.
;> wLowHealthAlarm = 0
	xor a
	ld [wLowHealthAlarm], a ; turn off low health alarm
;> wChannelSoundIDs[CHAN5] = 0
	ld [wChannelSoundIDs + CHAN5], a
;> wLowHealthAlarmDisabled = 1                       # until the next battle
	inc a
	ld [wLowHealthAlarmDisabled], a ; prevent it from reactivating
	ret

;@ path: engine/battle/core
;@ def AnyEnemyPokemonAliveCheck() -> zero
;@ Zero if none of the opponent's Pokemon has HP left.
;@ test: wEnemyPartyCount = rand(1, 6)
AnyEnemyPokemonAliveCheck:
;> alive = 0
;>@lp for i in range(wEnemyPartyCount):
	ld a, [wEnemyPartyCount]
	ld b, a
	xor a
	ld hl, wEnemyMon1HP
	ld de, PARTYMON_STRUCT_LENGTH
.nextPokemon
;>     hp = wEnemyMon1HP + i * PARTYMON_STRUCT_LENGTH
;>     alive |= mem[hp] | mem[hp + 1]
	or [hl]
	inc hl
	or [hl]
	dec hl
;=@lp
	add hl, de
	dec b
	jr nz, .nextPokemon
;> return alive == 0
	and a
	ret

; stores whether enemy ran in Z flag
;@ path: engine/battle/core
;@ def ReplaceFaintedEnemyMon() -> zero
;@ The trainer sends out its next Pokemon (after updating the Poke Ball row). Zero if instead the link opponent
;@ ran.
;@ test: skip draws and animates the new Pokemon
ReplaceFaintedEnemyMon:
;> GetBattleHealthBarColor(addr(wEnemyHPBarColor), 0x30)
	ld hl, wEnemyHPBarColor
	ld e, $30
	call GetBattleHealthBarColor
;> farcall(DrawEnemyPokeballs)
	ld hl, DrawEnemyPokeballs
	ld b, BANK(DrawEnemyPokeballs)
	call Bankswitch
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .notLinkBattle
; link battle
;>     LinkBattleExchangeData()
	call LinkBattleExchangeData
;>     if wSerialExchangeNybbleReceiveData == LINKBATTLE_RUN:
;>         return True
	ld a, [wSerialExchangeNybbleReceiveData]
	cp LINKBATTLE_RUN
	ret z
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
.notLinkBattle
;> EnemySendOut()
	call EnemySendOut
;> wEnemyMoveNum = 0
	xor a
	ld [wEnemyMoveNum], a
;> wActionResultOrTookBattleTurn = 0
	ld [wActionResultOrTookBattleTurn], a
;> wAILayer2Encouragement = 0
	ld [wAILayer2Encouragement], a
;> return False
	inc a ; reset Z flag
	ret

;@ path: engine/battle/core
;@ def TrainerBattleVictory()
;@ The trainer is beaten: victory music (the gym leader tune for leaders and the final rival battle, which also
;@ keeps the map music off afterwards), "<TRAINER> was defeated!", its picture slides back with its closing words,
;@ and the prize money is added. A link battle ends after the text.
;@ test: skip waits for the music and texts
TrainerBattleVictory:
;> EndLowHealthAlarm()
	call EndLowHealthAlarm
;> music = MUSIC_DEFEATED_GYM_LEADER if wGymLeaderNo else MUSIC_DEFEATED_TRAINER
	ld b, MUSIC_DEFEATED_GYM_LEADER
	ld a, [wGymLeaderNo]
	and a
	jr nz, .gymleader
	ld b, MUSIC_DEFEATED_TRAINER
.gymleader
;> if wTrainerClass == RIVAL3:
	ld a, [wTrainerClass]
	cp RIVAL3 ; final battle against rival
	jr nz, .notrival
;>     music = MUSIC_DEFEATED_GYM_LEADER
	ld b, MUSIC_DEFEATED_GYM_LEADER
;>     wStatusFlags7 |= 1 << BIT_NO_MAP_MUSIC
	ld hl, wStatusFlags7
	set BIT_NO_MAP_MUSIC, [hl]
.notrival
;> if wLinkState != LINK_STATE_BATTLING:
;>     PlayBattleVictoryMusic(music)
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ld a, b
	call nz, PlayBattleVictoryMusic
;> PrintText(TrainerDefeatedText)
	ld hl, TrainerDefeatedText
	call PrintText
;> if wLinkState == LINK_STATE_BATTLING:
;>     return
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ret z
;> ScrollTrainerPicAfterBattle()
	call ScrollTrainerPicAfterBattle
;> DelayFrames(40)
	ld c, 40
	call DelayFrames
;> PrintEndBattleText()
	call PrintEndBattleText
; win money
;> PrintText(MoneyForWinningText)
	ld hl, MoneyForWinningText
	call PrintText
;> predef(AddBCDPredef, hl=wAmountMoneyWon + 2, de=wPlayerMoney + 2, bc=3)   # add the prize money
	ld de, wPlayerMoney + 2
	ld hl, wAmountMoneyWon + 2
	ld c, $3
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/battle/core
MoneyForWinningText:
	db TX_FAR
	dw _MoneyForWinningText
	db BANK(_MoneyForWinningText)
	db TX_END

;@ path: engine/battle/core
TrainerDefeatedText:
	db TX_FAR
	dw _TrainerDefeatedText
	db BANK(_TrainerDefeatedText)
	db TX_END

;@ path: engine/battle/core
;@ def PlayBattleVictoryMusic(music: a)
;@ Stop all music and play a victory tune (from the bank of the trainer victory music).
;@ test: skip waits for the current sound to finish
PlayBattleVictoryMusic:
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	push af
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySoundWaitForCurrent(SFX_STOP_ALL_MUSIC)
	call PlaySoundWaitForCurrent
;> PlayMusic(music, BANK(Music_DefeatedTrainer))
	ld c, BANK(Music_DefeatedTrainer)
	pop af
	call PlayMusic
;> Delay3()
	jp Delay3

;@ path: engine/battle/core
;@ def HandlePlayerMonFainted()
;@ The player's Pokemon fainted: if the opponent's fainted as well handle that first, then black out if no
;@ Pokemon is left, else send out the next one (in a wild battle the player may run instead) and go on.
;@ test: skip runs the whole battle
HandlePlayerMonFainted:
;> wInHandlePlayerMonFainted = 1
	ld a, 1
	ld [wInHandlePlayerMonFainted], a
;> RemoveFaintedPlayerMon()
	call RemoveFaintedPlayerMon
;> if not AnyPartyAlive()[1]:
;>     return HandlePlayerBlackOut()
	call AnyPartyAlive     ; test if any more mons are alive
	ld a, d
	and a
	jp z, HandlePlayerBlackOut
;> if not (mem[wEnemyMonHP] | mem[wEnemyMonHP + 1]):
	ld hl, wEnemyMonHP
	ld a, [hli]
	or [hl] ; is enemy mon's HP 0?
	jr nz, .doUseNextMonDialogue ; if not, jump
; the enemy mon has 0 HP
;>     FaintEnemyPokemon()
	call FaintEnemyPokemon
;>     if wIsInBattle == 1:
;>         return
	ld a, [wIsInBattle]
	dec a
	ret z            ; if wild encounter, battle is over
;>     if AnyEnemyPokemonAliveCheck():
;>         return TrainerBattleVictory()
	call AnyEnemyPokemonAliveCheck
	jp z, TrainerBattleVictory
.doUseNextMonDialogue
;> if DoUseNextMonDialogue():
;>     return                                        # ran away
	call DoUseNextMonDialogue
	ret c ; return if the player ran from battle
;> if not ChooseNextMon():
;>     return MainInBattleLoop()
	call ChooseNextMon
	jp nz, MainInBattleLoop ; if the enemy mon has more than 0 HP, go back to battle loop
; the enemy mon has 0 HP
;> wActionResultOrTookBattleTurn = 1                 # the opponent's Pokemon fainted too: replace it
	ld a, $1
	ld [wActionResultOrTookBattleTurn], a
;> if ReplaceFaintedEnemyMon():
;>     return EnemyRan()
	call ReplaceFaintedEnemyMon
	jp z, EnemyRan ; if enemy ran from battle rather than sending out another mon, jump
;> wActionResultOrTookBattleTurn = 0
	xor a
	ld [wActionResultOrTookBattleTurn], a
;> MainInBattleLoop()
	jp MainInBattleLoop

; resets flags, slides mon's pic down, plays cry, and prints fainted message
;@ path: engine/battle/core
;@ def RemoveFaintedPlayerMon()
;@ The player's Pokemon faints: it gets no experience, the low HP beeping stops, its picture slides down, and
;@ (unless the opponent's fainting is handled first) its cry and "<MON> fainted!".
;@ test: skip plays the cry and waits for sounds
RemoveFaintedPlayerMon:
;> predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=FLAG_RESET << 8 | wPlayerMonNumber)
	ld a, [wPlayerMonNumber]
	ld c, a
	ld hl, wPartyGainExpFlags
	ld b, FLAG_RESET
	; clear gain exp flag for fainted mon
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> wEnemyBattleStatus1 &= ~(1 << ATTACKING_MULTIPLE_TIMES)
	ld hl, wEnemyBattleStatus1
	res ATTACKING_MULTIPLE_TIMES, [hl]
;> if wLowHealthAlarm >> BIT_LOW_HEALTH_ALARM & 1:
	ld a, [wLowHealthAlarm]
	bit BIT_LOW_HEALTH_ALARM, a
	jr z, .skipWaitForSound
;>     wLowHealthAlarm = DISABLE_LOW_HEALTH_ALARM
	ld a, DISABLE_LOW_HEALTH_ALARM
	ld [wLowHealthAlarm], a
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
.skipWaitForSound
; a is 0, so this zeroes the enemy's accumulated damage.
;> wEnemyBideAccumulatedDamage[0] = 0
;> wEnemyBideAccumulatedDamage[1] = 0
	ld hl, wEnemyBideAccumulatedDamage
	ld [hli], a
	ld [hl], a
;> mem[wBattleMonStatus] = 0
	ld [wBattleMonStatus], a
;> ReadPlayerMonCurHPAndStatus()
	call ReadPlayerMonCurHPAndStatus
;> ClearScreenArea(coord(9, 7), 11, 5)
	ld hl, (7) * SCREEN_WIDTH + (9) + wTileMap
	ld bc, ((5) & $ff) << 8 + ((11) & $ff)
	call ClearScreenArea
;> SlideDownFaintedMonPic(coord(1, 10), coord(1, 11))
	ld hl, (10) * SCREEN_WIDTH + (1) + wTileMap
	ld de, (11) * SCREEN_WIDTH + (1) + wTileMap
	call SlideDownFaintedMonPic
;> wBattleResult = 1
	ld a, $1
	ld [wBattleResult], a

; When the player mon and enemy mon faint at the same time and the fact that the
; enemy mon has fainted is detected first (e.g. when the player mon knocks out
; the enemy mon using a move with recoil and faints due to the recoil), don't
; play the player mon's cry or show the "[player mon] fainted!" message.
;> if not wInHandlePlayerMonFainted:
;>     return
	ld a, [wInHandlePlayerMonFainted]
	and a ; was this called by HandleEnemyMonFainted?
	ret z ; if so, return

;> PlayCry(mem[wBattleMonSpecies])
	ld a, [wBattleMonSpecies]
	call PlayCry
;> PrintText(PlayerMonFaintedText)
	ld hl, PlayerMonFaintedText
	jp PrintText

;@ path: engine/battle/core
PlayerMonFaintedText:
	db TX_FAR
	dw _PlayerMonFaintedText
	db BANK(_PlayerMonFaintedText)
	db TX_END

; asks if you want to use next mon
; stores whether you ran in C flag
;@ path: engine/battle/core
;@ def DoUseNextMonDialogue() -> carry
;@ In a wild battle: "Use next POKeMON?" yes/no. No means trying to run (carry if that worked).
;@ test: skip waits for the player's answer
DoUseNextMonDialogue:
;> PrintEmptyString()
	call PrintEmptyString
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> if wIsInBattle != 1:
;>     return False
	ld a, [wIsInBattle]
	and a
	dec a
	ret nz ; return if it's a trainer battle
;> PrintText(UseNextMonText)
	ld hl, UseNextMonText
	call PrintText
.displayYesNoBox
;> while True:
;>     wTextBoxID = TWO_OPTION_MENU
	ld hl, (9) * SCREEN_WIDTH + (13) + wTileMap
	ld bc, ((10) & $ff) << 8 + ((14) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;>     DisplayTextBoxID()                            # the YES/NO box at coord(13, 9)
	call DisplayTextBoxID
;>     if wMenuExitMethod != CHOSE_SECOND_ITEM:
;>         return False
	ld a, [wMenuExitMethod]
	cp CHOSE_SECOND_ITEM ; did the player choose NO?
	jr z, .tryRunning ; if the player chose NO, try running
	and a ; reset carry
	ret
.tryRunning
;>     if wCurrentMenuItem:
;>         break
	ld a, [wCurrentMenuItem]
	and a
	jr z, .displayYesNoBox ; xxx when does this happen?
;> return TryRunningFromBattle(wPartyMon1Speed, wEnemyMonSpeed)   # the first party Pokemon's Speed, not the fainted one's
	ld hl, wPartyMon1Speed
	ld de, wEnemyMonSpeed
	jp TryRunningFromBattle

;@ path: engine/battle/core
UseNextMonText:
	db TX_FAR
	dw _UseNextMonText
	db BANK(_UseNextMonText)
	db TX_END

; choose next player mon to send out
; stores whether enemy mon has no HP left in Z flag
;@ path: engine/battle/core
;@ def ChooseNextMon() -> zero
;@ The party menu until the player picks a Pokemon that can fight; send it out (a link battle tells the other
;@ side). Zero if the opponent's Pokemon has no HP left.
;@ test: skip waits for the player's choice
ChooseNextMon:
;> wPartyMenuTypeOrMessageID = BATTLE_PARTY_MENU
	ld a, BATTLE_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;> cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
.checkIfMonChosen
;> while True:
;>     while cancelled:
	jr nc, .monChosen
.goBackToPartyMenu
;>         cancelled = GoBackToPartyMenu()
	call GoBackToPartyMenu
	jr .checkIfMonChosen
.monChosen
;>     if not HasMonFainted():
;>         break
	call HasMonFainted
	jr z, .goBackToPartyMenu ; if mon fainted, you have to choose another
;>     cancelled = GoBackToPartyMenu()               # (the code above: it can't fight)
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .notLinkBattle
;>     wActionResultOrTookBattleTurn = 1
	inc a ; 1
	ld [wActionResultOrTookBattleTurn], a
;>     LinkBattleExchangeData()
	call LinkBattleExchangeData
.notLinkBattle
;> wActionResultOrTookBattleTurn = 0
	xor a
	ld [wActionResultOrTookBattleTurn], a
;> ClearSprites()
	call ClearSprites
;> wPlayerMonNumber = wWhichPokemon
	ld a, [wWhichPokemon]
	ld [wPlayerMonNumber], a
;> predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=FLAG_SET << 8 | wWhichPokemon)
	ld c, a
	ld hl, wPartyGainExpFlags
	ld b, FLAG_SET
	push bc
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> predef(FlagActionPredef, hl=wPartyFoughtCurrentEnemyFlags, bc=FLAG_SET << 8 | wWhichPokemon)
	pop bc
	ld hl, wPartyFoughtCurrentEnemyFlags
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> LoadBattleMonFromParty()
	call LoadBattleMonFromParty
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> LoadHudTilePatterns()
	call LoadHudTilePatterns
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> GBPalNormal()
	call GBPalNormal
;> SendOutMon()
	call SendOutMon
;> return not (mem[wEnemyMonHP] | mem[wEnemyMonHP + 1])
	ld hl, wEnemyMonHP
	ld a, [hli]
	or [hl]
	ret

; called when player is out of usable mons.
; prints appropriate lose message, sets carry flag if player blacked out (special case for initial rival fight)
;@ path: engine/battle/core
;@ def HandlePlayerBlackOut() -> carry
;@ The player has no Pokemon left. Losing the first rival battle shows the rival's words, and in Oak's lab
;@ (the starter battle) that is all (no carry). Otherwise the screen goes dark: "<PLAYER> blacked out!" (or the
;@ link battle loss text), the player gets off the bike, carry set.
;@ test: skip shows texts and fades the screen
HandlePlayerBlackOut:
;> if wLinkState != LINK_STATE_BATTLING and wCurOpponent == OPP_RIVAL1:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr z, .notRival1Battle
	ld a, [wCurOpponent]
	cp OPP_RIVAL1
	jr nz, .notRival1Battle
	; rival 1 battle
;>     ClearScreenArea(coord(0, 0), 21, 8)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((21) & $ff)
	call ClearScreenArea
;>     ScrollTrainerPicAfterBattle()
	call ScrollTrainerPicAfterBattle
;>     DelayFrames(40)
	ld c, 40
	call DelayFrames
;>     PrintText(Rival1WinText)
	ld hl, Rival1WinText
	call PrintText
;>     if wCurMap == OAKS_LAB:
;>         return False
	ld a, [wCurMap]
	cp OAKS_LAB
	ret z            ; starter battle in oak's lab: don't black out
.notRival1Battle
;> RunPaletteCommand(SET_PAL_BATTLE_BLACK)
	ld b, SET_PAL_BATTLE_BLACK
	call RunPaletteCommand
;> PrintText(LinkBattleLostText if wLinkState == LINK_STATE_BATTLING else PlayerBlackedOutText2)
	ld hl, PlayerBlackedOutText2
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .noLinkBattle
	ld hl, LinkBattleLostText
.noLinkBattle
	call PrintText
;> wStatusFlags6 &= ~(1 << BIT_ALWAYS_ON_BIKE)
	ld a, [wStatusFlags6]
	res BIT_ALWAYS_ON_BIKE, a
	ld [wStatusFlags6], a
;> ClearScreen()
	call ClearScreen
;> return True
	scf
	ret

;@ path: engine/battle/core
Rival1WinText:
	db TX_FAR
	dw _Rival1WinText
	db BANK(_Rival1WinText)
	db TX_END

;@ path: engine/battle/core
PlayerBlackedOutText2:
	db TX_FAR
	dw _PlayerBlackedOutText2
	db BANK(_PlayerBlackedOutText2)
	db TX_END

;@ path: engine/battle/core
LinkBattleLostText:
	db TX_FAR
	dw _LinkBattleLostText
	db BANK(_LinkBattleLostText)
	db TX_END

; slides pic of fainted mon downwards until it disappears
; bug: when this is called, [hAutoBGTransferEnabled] is non-zero, so there is screen tearing
;@ path: engine/battle/core
;@ def SlideDownFaintedMonPic(src: hl, dest: de)
;@ A fainted Pokemon's picture sinks out of view: seven times, every row of the 7x7 picture moves one row down
;@ (src is its second-to-last row, dest the last) and the top row becomes blank, two frames apart. Text is
;@ printed without delay meanwhile.
;@ test: src = 0xC3A0 + rand(6, 16) * SCREEN_WIDTH + rand(0, 13); dest = src + SCREEN_WIDTH
SlideDownFaintedMonPic:
;> saved = wStatusFlags5
	ld a, [wStatusFlags5]
	push af
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	set BIT_NO_TEXT_DELAY, a
	ld [wStatusFlags5], a
;>@st for _ in range(PIC_HEIGHT):
	ld b, PIC_HEIGHT ; number of times to slide
.slideStepLoop ; each iteration, the mon is slid down one row
;>     r, w = src, dest
	push bc
	push de
	push hl
;>@rw     for _ in range(PIC_HEIGHT - 1):       # bottom up
	ld b, PIC_HEIGHT - 1 ; number of rows
.rowLoop
;>         CopyData(r, w, PIC_WIDTH)
	push bc
	push hl
	push de
	ld bc, PIC_WIDTH
	call CopyData
;>         r -= SCREEN_WIDTH
	pop de
	pop hl
	ld bc, -SCREEN_WIDTH
	add hl, bc
;>@w         w -= SCREEN_WIDTH
	push hl
	ld h, d
	ld l, e
	add hl, bc
;=@w
	ld d, h
	ld e, l
	pop hl
;=@rw
	pop bc
	dec b
	jr nz, .rowLoop
;>     PlaceString(SevenSpacesText, r + SCREEN_WIDTH)  # the top row blank
	ld bc, SCREEN_WIDTH
	add hl, bc
	ld de, SevenSpacesText
	call PlaceString
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
;=@st
	pop hl
	pop de
	pop bc
	dec b
	jr nz, .slideStepLoop
;> wStatusFlags5 = saved
	pop af
	ld [wStatusFlags5], a
	ret

;@ path: engine/battle/core
SevenSpacesText:
	ds PIC_WIDTH, ' '
	db "@"

; slides the player or enemy trainer off screen
; a is the number of tiles to slide it horizontally (always 9 for the player trainer or 8 for the enemy trainer)
; if a is 8, the slide is to the right, else it is to the left
; bug: when this is called, [hAutoBGTransferEnabled] is non-zero, so there is screen tearing
;@ path: engine/battle/core
;@ def SlideTrainerPicOffScreen(dest: hl, amount: a)
;@ Slide a 7-row picture `amount` tiles sideways, one tile every two frames: with 8 the enemy trainer slides
;@ right (dest is the picture's right edge), otherwise the player slides left (dest is the left edge).
;@ test: dest = 0xC3A0 + rand(0, 11) * SCREEN_WIDTH + rand(9, 10); amount = rand(8, 9)
SlideTrainerPicOffScreen:
;> hSlideAmount = amount
	ldh [hSlideAmount], a
;>@steps for _ in range(amount):
	ld c, a
.slideStepLoop ; each iteration, the trainer pic is slid one tile left/right
	push bc
	push hl
;>@rows     for row in range(PIC_HEIGHT):
	ld b, PIC_HEIGHT ; number of rows
.rowLoop
;>         p = dest + row * SCREEN_WIDTH
	push hl
;>@cols         for _ in range(amount):
	ldh a, [hSlideAmount]
	ld c, a
.columnLoop
;>             if amount == 8:                       # shift the row right, from its right end
;>@right                 mem[p + 1] = mem[p]
;>@right2                 p -= 1
	ldh a, [hSlideAmount]
	cp 8
	jr z, .slideRight
; slide player sprite left off screen
;>             else:                                 # shift the row left, from its left end
;>                 mem[p - 1] = mem[p]
;>                 p += 1
	ld a, [hld]
	ld [hli], a
	inc hl
	jr .nextColumn
.slideRight ; slide enemy trainer sprite off screen
;=@right
	ld a, [hli]
	ld [hld], a
;=@right2
	dec hl
.nextColumn
;=@cols
	dec c
	jr nz, .columnLoop
;=@rows
	pop hl
	ld de, SCREEN_WIDTH
	add hl, de
	dec b
	jr nz, .rowLoop
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
;=@steps
	pop hl
	pop bc
	dec c
	jr nz, .slideStepLoop
	ret

; send out a trainer's mon
;@ path: engine/battle/core
;@ def EnemySendOut()
;@ The trainer sends out its next Pokemon: only the Pokemon now out is marked as having fought it.
EnemySendOut:
;> wPartyGainExpFlags = 0
	ld hl, wPartyGainExpFlags
	xor a
	ld [hl], a
;> predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=FLAG_SET << 8 | wPlayerMonNumber)
	ld a, [wPlayerMonNumber]
	ld c, a
	ld b, FLAG_SET
	push bc
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> wPartyFoughtCurrentEnemyFlags = 0
	ld hl, wPartyFoughtCurrentEnemyFlags
	xor a
	ld [hl], a
;> predef(FlagActionPredef, hl=wPartyFoughtCurrentEnemyFlags, bc=FLAG_SET << 8 | wPlayerMonNumber)
	pop bc
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> EnemySendOutFirstMon()                   # (falls through)

; don't change wPartyGainExpFlags or wPartyFoughtCurrentEnemyFlags
;@ path: engine/battle/core
;@ def EnemySendOutFirstMon()
;@ The trainer's picture slides away and it sends out its next Pokemon that can fight (in a link battle the one
;@ the other side chose). With the Shift battle style the player is first asked "Will <PLAYER> change POKeMON?"
;@ and may switch.
;@ test: skip animates and asks the player
EnemySendOutFirstMon:
;> fill(addr(wEnemyStatsToDouble), 0, 2)            # wEnemyStatsToDouble ... wEnemyBattleStatus3 cleared
	xor a
	ld hl, wEnemyStatsToDouble ; clear enemy statuses
	ld [hli], a
	ld [hli], a
;> fill(addr(wEnemyStatsToDouble) + 2, 0, 3)
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wEnemyDisabledMove = 0
	ld [wEnemyDisabledMove], a
;> wEnemyDisabledMoveNumber = 0
	ld [wEnemyDisabledMoveNumber], a
;> wEnemyMonMinimized = 0
	ld [wEnemyMonMinimized], a
;> wPlayerUsedMove = 0
	ld hl, wPlayerUsedMove
	ld [hli], a
;> wEnemyUsedMove = 0
	ld [hl], a
;> wAICount = 0xFF
	dec a
	ld [wAICount], a
;> wPlayerBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld hl, wPlayerBattleStatus1
	res USING_TRAPPING_MOVE, [hl]
;> SlideTrainerPicOffScreen(coord(18, 0), 8)
	ld hl, (0) * SCREEN_WIDTH + (18) + wTileMap
	ld a, 8
	call SlideTrainerPicOffScreen
;> PrintEmptyString()
	call PrintEmptyString
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .next
;>     wWhichPokemon = wSerialExchangeNybbleReceiveData - 4
	ld a, [wSerialExchangeNybbleReceiveData]
	sub 4
	ld [wWhichPokemon], a
	jr .next3
.next
;> else:
;>     mon = -1
	ld b, $ff
.next2
;>     while True:                                   # the next one with HP, not the one just out
;>         mon += 1
	inc b
;>         if mon == mem[wEnemyMonPartyPos]:
;>             continue
	ld a, [wEnemyMonPartyPos]
	cp b
	jr z, .next2
;>         wWhichPokemon = mon
	ld hl, wEnemyMon1
	ld a, b
	ld [wWhichPokemon], a
;>         hp = wEnemyMon1HP + mon * PARTYMON_STRUCT_LENGTH
	push bc
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	pop bc
;>         if mem[hp] | mem[hp + 1]:
;>             break
	inc hl
	ld a, [hli]
	ld c, a
	ld a, [hl]
	or c
	jr z, .next2
.next3
;> wCurEnemyLevel = mem[wEnemyMon1Level + wWhichPokemon * PARTYMON_STRUCT_LENGTH]
	ld a, [wWhichPokemon]
	ld hl, wEnemyMon1Level
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld a, [hl]
	ld [wCurEnemyLevel], a
;> entry = wEnemyPartyCount + wWhichPokemon + 1      # its species in wEnemyPartySpecies
	ld a, [wWhichPokemon]
	inc a
	ld hl, wEnemyPartyCount
	ld c, a
	ld b, 0
	add hl, bc
;> wEnemyMonSpecies2 = mem[entry]
	ld a, [hl]
	ld [wEnemyMonSpecies2], a
;> wCurPartySpecies = wEnemyMonSpecies2
	ld [wCurPartySpecies], a
;> LoadEnemyMonData()
	call LoadEnemyMonData
;> wLastSwitchInEnemyMonHP[0] = mem[wEnemyMonHP]
	ld hl, wEnemyMonHP
	ld a, [hli]
	ld [wLastSwitchInEnemyMonHP], a
;> wLastSwitchInEnemyMonHP[1] = mem[wEnemyMonHP + 1]
	ld a, [hl]
	ld [wLastSwitchInEnemyMonHP + 1], a
;> wCurrentMenuItem = 1
	ld a, 1
	ld [wCurrentMenuItem], a
;> # the Shift style offers a switch - not for the first Pokemon, not with only one, not in a link battle
;> ask = wFirstMonsNotOutYet != 1 and wPartyCount != 1
	ld a, [wFirstMonsNotOutYet]
	dec a
	jr z, .next4
	ld a, [wPartyCount]
	dec a
	jr z, .next4
;> ask = ask and wLinkState != LINK_STATE_BATTLING and not wOptions >> BIT_BATTLE_SHIFT & 1
;> if ask:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr z, .next4
	ld a, [wOptions]
	bit BIT_BATTLE_SHIFT, a
	jr nz, .next4
;>     PrintText(TrainerAboutToUseText)
	ld hl, TrainerAboutToUseText
	call PrintText
;>     wTextBoxID = TWO_OPTION_MENU
	ld hl, (7) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((1) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
;>     DisplayTextBoxID()                            # YES/NO at coord(0, 7)
	call DisplayTextBoxID
;>     if not wCurrentMenuItem:                      # yes: pick a Pokemon to switch to
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .next4
;>         wPartyMenuTypeOrMessageID = BATTLE_PARTY_MENU
	ld a, BATTLE_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;>         cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
.next9
;>         while True:
;>             wCurrentMenuItem = 1
	ld a, 1
	ld [wCurrentMenuItem], a
;>             if cancelled:
;>                 break
	jr c, .next7
;>             if wWhichPokemon == wPlayerMonNumber:
	ld hl, wPlayerMonNumber
	ld a, [wWhichPokemon]
	cp [hl]
	jr nz, .next6
;>                 PrintText(AlreadyOutText)
	ld hl, AlreadyOutText
	call PrintText
.next8
;=@gb
	call GoBackToPartyMenu
	jr .next9
.next6
;>             elif not HasMonFainted():
	call HasMonFainted
	jr z, .next8
;>                 wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;>                 break
;>@gb             cancelled = GoBackToPartyMenu()
.next7
;>         GBPalWhiteOut()
	call GBPalWhiteOut
;>         LoadHudTilePatterns()
	call LoadHudTilePatterns
;>         LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
.next4
;> ClearSprites()
	call ClearSprites
;> ClearScreenArea(coord(0, 0), 11, 4)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((4) & $ff) << 8 + ((11) & $ff)
	call ClearScreenArea
;> RunPaletteCommand(SET_PAL_BATTLE)
	ld b, SET_PAL_BATTLE
	call RunPaletteCommand
;> GBPalNormal()
	call GBPalNormal
;> PrintText(TrainerSentOutText)
	ld hl, TrainerSentOutText
	call PrintText
;> wCurPartySpecies = wEnemyMonSpecies2
	ld a, [wEnemyMonSpecies2]
	ld [wCurPartySpecies], a
;> wCurSpecies = wEnemyMonSpecies2
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> LoadMonFrontSprite(vFrontPic)
	ld de, vFrontPic
	call LoadMonFrontSprite
;> hStartTileID = -0x31 & 0xFF
	ld a, -$31
	ldh [hStartTileID], a
;> predef(AnimateSendingOutMon, hl=coord(15, 6))
	ld hl, (6) * SCREEN_WIDTH + (15) + wTileMap
	ld a, (AnimateSendingOutMonPredef - PredefPointers) / 3
	call Predef
;> PlayCry(wEnemyMonSpecies2)
	ld a, [wEnemyMonSpecies2]
	call PlayCry
;> DrawEnemyHUDAndHPBar()
	call DrawEnemyHUDAndHPBar
;> if wCurrentMenuItem:
;>     return
	ld a, [wCurrentMenuItem]
	and a
	ret nz
;> wPartyGainExpFlags = 0
	xor a
	ld [wPartyGainExpFlags], a
;> wPartyFoughtCurrentEnemyFlags = 0
	ld [wPartyFoughtCurrentEnemyFlags], a
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> SwitchPlayerMon()
	jp SwitchPlayerMon

;@ path: engine/battle/core
TrainerAboutToUseText:
	db TX_FAR
	dw _TrainerAboutToUseText
	db BANK(_TrainerAboutToUseText)
	db TX_END

;@ path: engine/battle/core
TrainerSentOutText:
	db TX_FAR
	dw _TrainerSentOutText
	db BANK(_TrainerSentOutText)
	db TX_END

; tests if the player has any pokemon that are not fainted
; sets d = 0 if all fainted, d != 0 if some mons are still alive
;@ path: engine/battle/core
;@ def AnyPartyAlive() -> (a, d)
;@ Non-zero if any Pokemon in the party still has HP: all the HP bytes ORed together.
;@ test: wPartyCount = rand(1, 6)
AnyPartyAlive::
;> alive = 0
;> for i in range(wPartyCount):
	ld a, [wPartyCount]
	ld e, a
	xor a
	ld hl, wPartyMon1HP
	ld bc, PARTYMON_STRUCT_LENGTH - 1
.partyMonsLoop
;>     hp = wPartyMon1HP + i * PARTYMON_STRUCT_LENGTH
;>     alive |= mem[hp] | mem[hp + 1]
	or [hl]
	inc hl
	or [hl]
	add hl, bc
	dec e
	jr nz, .partyMonsLoop
;> return (alive, alive)
	ld d, a
	ret

; tests if player mon has fainted
; stores whether mon has fainted in Z flag
;@ path: engine/battle/core
;@ def HasMonFainted() -> zero
;@ Whether the party Pokemon wWhichPokemon has no HP left (zero set). Once the battle is under way, choosing a
;@ fainted Pokemon also prints "There's no will to fight!".
;@ test: wWhichPokemon = rand(0, 5)
HasMonFainted:
;> hp = wPartyMon1HP + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	ld hl, wPartyMon1HP
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> if mem[hp] | mem[hp + 1]:
;>     return False
	ld a, [hli]
	or [hl]
	ret nz
;> if not wFirstMonsNotOutYet:
;>     PrintText(NoWillText)
	ld a, [wFirstMonsNotOutYet]
	and a
	jr nz, .done
	ld hl, NoWillText
	call PrintText
.done
;> return True
	xor a
	ret

;@ path: engine/battle/core
NoWillText:
	db TX_FAR
	dw _NoWillText
	db BANK(_NoWillText)
	db TX_END

; try to run from battle (hl = player speed, de = enemy speed)
; stores whether the attempt was successful in carry flag
;@ path: engine/battle/core
;@ def TryRunningFromBattle(player_speed: hl, enemy_speed: de) -> carry
;@ Try to run (carry if it worked). Always possible from a ghost, in the Safari Zone and in link battles; never
;@ from a trainer. Otherwise a faster Pokemon always gets away; a slower one if a random number is at most
;@ Speed x 32 / (enemy Speed / 4) + 30 for each earlier attempt. A failed try costs the turn.
;@ test: skip plays sounds and prints texts
TryRunningFromBattle:
;> text = None
;> escape = IsGhostBattle()                         # always from a ghost,
	call IsGhostBattle
	jp z, .canEscape ; jump if it's a ghost battle
;> escape = escape or wBattleType == BATTLE_TYPE_SAFARI   # in the Safari Zone
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jp z, .canEscape ; jump if it's a safari battle
;> escape = escape or wLinkState == LINK_STATE_BATTLING   # and in link battles
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jp z, .canEscape
;> if not escape and wIsInBattle != 1:
;>     text = NoRunningText
	ld a, [wIsInBattle]
	dec a
	jr nz, .trainerBattle ; jump if it's a trainer battle
;> elif not escape:
;>     wNumRunAttempts += 1
	ld a, [wNumRunAttempts]
	inc a
	ld [wNumRunAttempts], a
;>     hMultiplicand[1] = mem[player_speed]
	ld a, [hli]
	ldh [hMultiplicand + 1], a
;>     hMultiplicand[2] = mem[player_speed + 1]
	ld a, [hl]
	ldh [hMultiplicand + 2], a
;>     hEnemySpeed[0] = mem[enemy_speed]
	ld a, [de]
	ldh [hEnemySpeed], a
;>     hEnemySpeed[1] = mem[enemy_speed + 1]
	inc de
	ld a, [de]
	ldh [hEnemySpeed + 1], a
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     slower, _ = StringCmp(hMultiplicand + 1, hEnemySpeed, 2)
	ld de, hMultiplicand + 1
	ld hl, hEnemySpeed
	ld c, 2
	call StringCmp
;>     escape = True
;>     if slower:
	jr nc, .canEscape ; jump if player speed greater than enemy speed
;>         hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;>         hMultiplier = 32
	ld a, 32
	ldh [hMultiplier], a
;>         Multiply()
	call Multiply ; multiply player speed by 32
;>         hDividend[0] = hProduct[2]
	ldh a, [hProduct + 2]
	ldh [hDividend], a
;>         hDividend[1] = hProduct[3]
	ldh a, [hProduct + 3]
	ldh [hDividend + 1], a
;>         speed = hEnemySpeed[0] << 8 | hEnemySpeed[1]
	ldh a, [hEnemySpeed]
	ld b, a
	ldh a, [hEnemySpeed + 1]
; divide enemy speed by 4
;>         divisor = speed >> 2 & 0xFF
	srl b
	rr a
	srl b
	rr a
;>         if divisor:
	and a
	jr z, .canEscape ; jump if enemy speed divided by 4, mod 256 is 0
;>             hDivisor = divisor
	ldh [hDivisor], a ; ((enemy speed / 4) % 256)
;>             Divide(2)
	ld b, $2
	call Divide ; divide (player speed * 32) by ((enemy speed / 4) % 256)
;>             if not hQuotient[2]:                  # odds below 256
	ldh a, [hQuotient + 2]
	and a ; is the quotient greater than 256?
	jr nz, .canEscape ; if so, the player can escape
;>                 escape = False
;>@ra                 for _ in range(wNumRunAttempts - 1):
	ld a, [wNumRunAttempts]
	ld c, a
; add 30 to the quotient for each run attempt
.loop
	dec c
	jr z, .compareWithRandomValue
;>                     odds = hQuotient[3] + 30
;>                     hQuotient[3] = odds & 0xFF
	ld b, 30
	ldh a, [hQuotient + 3]
	add b
	ldh [hQuotient + 3], a
;>                     if odds > 0xFF:
;>                         escape = True
	jr c, .canEscape
;>                         break
;=@ra
	jr .loop
.compareWithRandomValue
;>                 if not escape and hQuotient[3] >= BattleRandom():
;>                     escape = True
	call BattleRandom
	ld b, a
	ldh a, [hQuotient + 3]
	cp b
	jr nc, .canEscape ; if the random value was less than or equal to the quotient
	                  ; plus 30 times the number of attempts, the player can escape
; can't escape
;>     if not escape:
;>         wActionResultOrTookBattleTurn = 1
	ld a, $1
	ld [wActionResultOrTookBattleTurn], a ; you lose your turn when you can't escape
;>         text = CantEscapeText
	ld hl, CantEscapeText
	jr .printCantEscapeOrNoRunningText
.trainerBattle
	ld hl, NoRunningText
.printCantEscapeOrNoRunningText
;> if not escape:
;>     PrintText(text)
	call PrintText
;>     wForcePlayerToChooseMon = 1
	ld a, 1
	ld [wForcePlayerToChooseMon], a
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     return False
	and a ; reset carry
	ret
.canEscape
;> wBattleResult = 2
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ld a, $2
	jr nz, .playSound
; link battle
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     wActionResultOrTookBattleTurn = 0
	xor a
	ld [wActionResultOrTookBattleTurn], a
;>     wPlayerMoveListIndex = LINKBATTLE_RUN
	ld a, LINKBATTLE_RUN
	ld [wPlayerMoveListIndex], a
;>     LinkBattleExchangeData()
	call LinkBattleExchangeData
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     if wSerialExchangeNybbleReceiveData != LINKBATTLE_RUN:
;>         wBattleResult = 1
	ld a, [wSerialExchangeNybbleReceiveData]
	cp LINKBATTLE_RUN
	ld a, $2
	jr z, .playSound
	dec a
.playSound
	ld [wBattleResult], a
;> PlaySoundWaitForCurrent(SFX_RUN)
	ld a, SFX_RUN
	call PlaySoundWaitForCurrent
;> PrintText(GotAwayText)
	ld hl, GotAwayText
	call PrintText
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> return True
	scf ; set carry
	ret

;@ path: engine/battle/core
CantEscapeText:
	db TX_FAR
	dw _CantEscapeText
	db BANK(_CantEscapeText)
	db TX_END

;@ path: engine/battle/core
NoRunningText:
	db TX_FAR
	dw _NoRunningText
	db BANK(_NoRunningText)
	db TX_END

;@ path: engine/battle/core
GotAwayText:
	db TX_FAR
	dw _GotAwayText
	db BANK(_GotAwayText)
	db TX_END

; copies from party data to battle mon data when sending out a new player mon
;@ path: engine/battle/core
;@ def LoadBattleMonFromParty()
;@ Send out party Pokemon wWhichPokemon: copy its species, HP, status, types, moves, DVs, PP, level and stats
;@ into the battle variables (the party entry's middle part - OT ID and experience - is skipped), its nickname,
;@ keep the unmodified level and stats, apply burn, paralysis and badge boosts and reset all stat stages to 7.
LoadBattleMonFromParty:
;> src = wPartyMon1Species + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	ld bc, PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Species
	call AddNTimes
;> src, _ = CopyData(src, wBattleMonSpecies, wBattleMonDVs - wBattleMonSpecies)
	ld de, wBattleMonSpecies
	ld bc, wBattleMonDVs - wBattleMonSpecies
	call CopyData
;> src += MON_DVS - MON_OTID                # skip the OT ID and the experience
	ld bc, MON_DVS - MON_OTID
	add hl, bc
;> src, _ = CopyData(src, wBattleMonDVs, MON_PP - MON_DVS)
	ld de, wBattleMonDVs
	ld bc, MON_PP - MON_DVS
	call CopyData
;> src, _ = CopyData(src, wBattleMonPP, NUM_MOVES)
	ld de, wBattleMonPP
	ld bc, NUM_MOVES
	call CopyData
;> CopyData(src, wBattleMonLevel, wBattleMonPP - wBattleMonLevel)
	ld de, wBattleMonLevel
	ld bc, wBattleMonPP - wBattleMonLevel
	call CopyData
;> wCurSpecies = wBattleMonSpecies2
;> GetMonHeader()
	ld a, [wBattleMonSpecies2]
	ld [wCurSpecies], a
	call GetMonHeader
;> nick = SkipFixedLengthTextEntries(wPartyMonNicks, wPlayerMonNumber)
	ld hl, wPartyMonNicks
	ld a, [wPlayerMonNumber]
	call SkipFixedLengthTextEntries
;> CopyData(nick, wBattleMonNick, NAME_LENGTH)
	ld de, wBattleMonNick
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(wBattleMonLevel, addr(wPlayerMonUnmodifiedLevel), 1 + NUM_STATS * 2)   # the unmodified level and stats
	ld hl, wBattleMonLevel
	ld de, wPlayerMonUnmodifiedLevel ; block of memory used for unmodified stats
	ld bc, 1 + NUM_STATS * 2
	call CopyData
;> ApplyBurnAndParalysisPenaltiesToPlayer()
	call ApplyBurnAndParalysisPenaltiesToPlayer
;> ApplyBadgeStatBoosts()
	call ApplyBadgeStatBoosts
;> for i in range(NUM_STAT_MODS):
	ld a, $7 ; default stat modifier
	ld b, NUM_STAT_MODS
	ld hl, wPlayerMonAttackMod
.statModLoop
;>     mem[addr(wPlayerMonAttackMod) + i] = 7
	ld [hli], a
	dec b
	jr nz, .statModLoop
	ret

; copies from enemy party data to current enemy mon data when sending out a new enemy mon
;@ path: engine/battle/core
;@ def LoadEnemyMonFromParty()
;@ Send out the opponent's party Pokemon wWhichPokemon: like LoadBattleMonFromParty, plus its base stats from
;@ wMonHeader and its party position in wEnemyMonPartyPos (no badge boosts for the opponent).
LoadEnemyMonFromParty:
;> src = wEnemyMons + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	ld bc, PARTYMON_STRUCT_LENGTH
	ld hl, wEnemyMons
	call AddNTimes
;> src, _ = CopyData(src, wEnemyMonSpecies, wEnemyMonDVs - wEnemyMonSpecies)
	ld de, wEnemyMonSpecies
	ld bc, wEnemyMonDVs - wEnemyMonSpecies
	call CopyData
;> src += MON_DVS - MON_OTID                # skip the OT ID and the experience
	ld bc, MON_DVS - MON_OTID
	add hl, bc
;> src, _ = CopyData(src, wEnemyMonDVs, MON_PP - MON_DVS)
	ld de, wEnemyMonDVs
	ld bc, MON_PP - MON_DVS
	call CopyData
;> src, _ = CopyData(src, wEnemyMonPP, NUM_MOVES)
	ld de, wEnemyMonPP
	ld bc, NUM_MOVES
	call CopyData
;> CopyData(src, wEnemyMonLevel, wEnemyMonPP - wEnemyMonLevel)
	ld de, wEnemyMonLevel
	ld bc, wEnemyMonPP - wEnemyMonLevel
	call CopyData
;> wCurSpecies = mem[wEnemyMonSpecies]
;> GetMonHeader()
	ld a, [wEnemyMonSpecies]
	ld [wCurSpecies], a
	call GetMonHeader
;> nick = SkipFixedLengthTextEntries(wEnemyMonNicks, wWhichPokemon)
	ld hl, wEnemyMonNicks
	ld a, [wWhichPokemon]
	call SkipFixedLengthTextEntries
;> CopyData(nick, wEnemyMonNick, NAME_LENGTH)
	ld de, wEnemyMonNick
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(wEnemyMonLevel, addr(wEnemyMonUnmodifiedLevel), 1 + NUM_STATS * 2)   # the unmodified level and stats
	ld hl, wEnemyMonLevel
	ld de, wEnemyMonUnmodifiedLevel ; block of memory used for unmodified stats
	ld bc, 1 + NUM_STATS * 2
	call CopyData
;> ApplyBurnAndParalysisPenaltiesToEnemy()
	call ApplyBurnAndParalysisPenaltiesToEnemy
;> for i in range(NUM_STATS):               # its base stats from the header
	ld hl, wMonHBaseStats
	ld de, wEnemyMonBaseStats
	ld b, NUM_STATS
.copyBaseStatsLoop
;>     wEnemyMonBaseStats[i] = mem[addr(wMonHBaseStats) + i]
	ld a, [hli]
	ld [de], a
	inc de
	dec b
	jr nz, .copyBaseStatsLoop
;> for i in range(NUM_STAT_MODS):
	ld a, $7 ; default stat modifier
	ld b, NUM_STAT_MODS
	ld hl, wEnemyMonStatMods
.statModLoop
;>     mem[addr(wEnemyMonStatMods) + i] = 7
	ld [hli], a
	dec b
	jr nz, .statModLoop
;> mem[wEnemyMonPartyPos] = wWhichPokemon
	ld a, [wWhichPokemon]
	ld [wEnemyMonPartyPos], a
	ret

;@ path: engine/battle/core
;@ def SendOutMon()
;@ The player's Pokemon comes out: "Go! <MON>!", both HUDs, its back picture, fresh battle effects, the Poke Ball
;@ puff, the picture growing out of it and its cry.
;@ test: skip animates and plays the cry
SendOutMon:
;> farcall(PrintSendOutMonMessage)
	ld hl, PrintSendOutMonMessage
	ld b, BANK(PrintSendOutMonMessage)
	call Bankswitch
;> if mem[wEnemyMonHP] | mem[wEnemyMonHP + 1]:
	ld hl, wEnemyMonHP
	ld a, [hli]
	or [hl] ; is enemy mon HP zero?
	jp z, .skipDrawingEnemyHUDAndHPBar ; if HP is zero, skip drawing the HUD and HP bar
;>     DrawEnemyHUDAndHPBar()
	call DrawEnemyHUDAndHPBar
.skipDrawingEnemyHUDAndHPBar
;> DrawPlayerHUDAndHPBar()
	call DrawPlayerHUDAndHPBar
;> predef(LoadMonBackPic)
	ld a, (LoadMonBackPicPredef - PredefPointers) / 3
	call Predef
;> hStartTileID = 0
	xor a
	ldh [hStartTileID], a
;> mem[addr(wBattleAndStartSavedMenuItem)] = 0
	ld hl, wBattleAndStartSavedMenuItem
	ld [hli], a
;> mem[addr(wBattleAndStartSavedMenuItem) + 1] = 0
	ld [hl], a
;> wBoostExpByExpAll = 0
	ld [wBoostExpByExpAll], a
;> wDamageMultipliers = 0
	ld [wDamageMultipliers], a
;> wPlayerMoveNum = 0
	ld [wPlayerMoveNum], a
;> wPlayerUsedMove = 0
	ld hl, wPlayerUsedMove
	ld [hli], a
;> wEnemyUsedMove = 0
	ld [hl], a
;> fill(addr(wPlayerStatsToDouble), 0, 5)           # wPlayerStatsToDouble ... wPlayerBattleStatus3
	ld hl, wPlayerStatsToDouble
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wPlayerDisabledMove = 0
	ld [wPlayerDisabledMove], a
;> wPlayerDisabledMoveNumber = 0
	ld [wPlayerDisabledMoveNumber], a
;> wPlayerMonMinimized = 0
	ld [wPlayerMonMinimized], a
;> RunPaletteCommand(SET_PAL_BATTLE)
	ld b, SET_PAL_BATTLE
	call RunPaletteCommand
;> wEnemyBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld hl, wEnemyBattleStatus1
	res USING_TRAPPING_MOVE, [hl]
;> hWhoseTurn = 1
	ld a, $1
	ldh [hWhoseTurn], a
;> PlayMoveAnimation(POOF_ANIM)
	ld a, POOF_ANIM
	call PlayMoveAnimation
;> predef(AnimateSendingOutMon, hl=coord(4, 11))
	ld hl, (11) * SCREEN_WIDTH + (4) + wTileMap
	ld a, (AnimateSendingOutMonPredef - PredefPointers) / 3
	call Predef
;> PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry
;> PrintEmptyString()
	call PrintEmptyString
;> SaveScreenTilesToBuffer1()
	jp SaveScreenTilesToBuffer1

; show 2 stages of the player mon getting smaller before disappearing
;@ path: engine/battle/core
;@ def AnimateRetreatingPlayerMon()
;@ The player's Pokemon is called back: its picture shrinks to 5x5, then 3x3 tiles, then disappears.
;@ test: skip waits for frames
AnimateRetreatingPlayerMon:
;> ClearScreenArea(coord(1, 5), 7, 7)
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
	call ClearScreenArea
;> dest, size = coord(3, 7), 5 << 8 | 5             # 5 x 5 tiles
	ld hl, (7) * SCREEN_WIDTH + (3) + wTileMap
	ld bc, ((5) & $ff) << 8 + ((5) & $ff)
;> wDownscaledMonSize = 0
	xor a
	ld [wDownscaledMonSize], a
;> hBaseTileID = 0
	ldh [hBaseTileID], a
;> predef(CopyDownscaledMonTiles, hl=dest, bc=size)
	ld a, (CopyDownscaledMonTilesPredef - PredefPointers) / 3
	call Predef
;> DelayFrames(4)
	ld c, 4
	call DelayFrames
;> ClearScreenArea(coord(1, 5), 7, 7)
	call .clearScreenArea
;> dest, size = coord(4, 9), 3 << 8 | 3             # 3 x 3 tiles
	ld hl, (9) * SCREEN_WIDTH + (4) + wTileMap
	ld bc, ((3) & $ff) << 8 + ((3) & $ff)
;> wDownscaledMonSize = 1
	ld a, 1
	ld [wDownscaledMonSize], a
;> hBaseTileID = 0
	xor a
	ldh [hBaseTileID], a
;> predef(CopyDownscaledMonTiles, hl=dest, bc=size)
	ld a, (CopyDownscaledMonTilesPredef - PredefPointers) / 3
	call Predef
;> Delay3()
	call Delay3
;> ClearScreenArea(coord(1, 5), 7, 7)
	call .clearScreenArea
;> mem[coord(5, 11)] = 0x4C
	ld a, $4c
	ld [(11) * SCREEN_WIDTH + (5) + wTileMap], a
.clearScreenArea
;> ClearScreenArea(coord(1, 5), 7, 7)                # (which clears that tile again)
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
	jp ClearScreenArea

; Copies player's current pokemon's current HP, party pos, and status into the party
; struct data so it stays after battle or switching
;@ path: engine/battle/core
;@ def ReadPlayerMonCurHPAndStatus()
;@ Copy the battling Pokemon's HP and status (and the byte between them) back into its party entry, so they
;@ last after the battle or a switch.
;@ test: wPlayerMonNumber = rand(0, 5)
ReadPlayerMonCurHPAndStatus:
;> party_hp = wPartyMon1HP + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	ld a, [wPlayerMonNumber]
	ld hl, wPartyMon1HP
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> CopyData(wBattleMonHP, party_hp, MON_STATUS + 1 - MON_HP)
	ld d, h
	ld e, l
	ld hl, wBattleMonHP
	ld bc, MON_STATUS + 1 - MON_HP ; also copies party pos in-between HP and status
	jp CopyData

;@ path: engine/battle/core
;@ def DrawHUDsAndHPBars()
;@ Redraw both Pokemon's name, level, status and HP bar boxes.
;@ test: hLoadedROMBank = 0x0F; mem[0xD009 + rand(0, 10)] = 0x50; mem[0xCFDA + rand(0, 10)] = 0x50
DrawHUDsAndHPBars:
;> DrawPlayerHUDAndHPBar()
;> DrawEnemyHUDAndHPBar()
	call DrawPlayerHUDAndHPBar
	jp DrawEnemyHUDAndHPBar

;@ path: engine/battle/core
;@ def DrawPlayerHUDAndHPBar()
;@ Draw the player's Pokemon box at the bottom right: name (centered), status or level, HP bar and numbers, the
;@ bar color - and start or stop the low HP beeping (red bar), unless the battle is already won.
;@ test: hLoadedROMBank = 0x0F; mem[0xD009 + rand(0, 10)] = 0x50; mem[0xCFDA + rand(0, 10)] = 0x50
DrawPlayerHUDAndHPBar:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> ClearScreenArea(coord(9, 7), 11, 5)
	ld hl, (7) * SCREEN_WIDTH + (9) + wTileMap
	ld bc, ((5) & $ff) << 8 + ((11) & $ff)
	call ClearScreenArea
;> farcall(PlacePlayerHUDTiles)
	ld hl, PlacePlayerHUDTiles
	ld b, BANK(PlacePlayerHUDTiles)
	call Bankswitch
;> mem[coord(18, 9)] = 0x73
	ld hl, (9) * SCREEN_WIDTH + (18) + wTileMap
	ld [hl], $73
;> PlaceString(wBattleMonNick, CenterMonName(coord(10, 7), wBattleMonNick))
	ld de, wBattleMonNick
	ld hl, (7) * SCREEN_WIDTH + (10) + wTileMap
	call CenterMonName
	call PlaceString
;> CopyData(wBattleMonSpecies, wLoadedMon, wBattleMonDVs - wBattleMonSpecies)
	ld hl, wBattleMonSpecies
	ld de, wLoadedMon
	ld bc, wBattleMonDVs - wBattleMonSpecies
	call CopyData
;> CopyData(wBattleMonLevel, wLoadedMonLevel, wBattleMonPP - wBattleMonLevel)
	ld hl, wBattleMonLevel
	ld de, wLoadedMonLevel
	ld bc, wBattleMonPP - wBattleMonLevel
	call CopyData
;> PrintStatusConditionNotFainted(wLoadedMonStatus, coord(15, 8))
	ld hl, (8) * SCREEN_WIDTH + (14) + wTileMap
	push hl
	inc hl
	ld de, wLoadedMonStatus
	call PrintStatusConditionNotFainted
;> if not mem[wLoadedMonStatus]:
	pop hl
	jr nz, .doNotPrintLevel
;>     PrintLevel(coord(14, 8))
	call PrintLevel
.doNotPrintLevel
;> wCurPartySpecies = mem[wLoadedMonSpecies]
	ld a, [wLoadedMonSpecies]
	ld [wCurPartySpecies], a
;> pixels = predef(DrawHP, hl=coord(10, 9))
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ld a, (DrawHPPredef - PredefPointers) / 3
	call Predef
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> GetBattleHealthBarColor(addr(wPlayerHPBarColor), pixels)
	ld hl, wPlayerHPBarColor
	call GetBattleHealthBarColor
;> if mem[wBattleMonHP] | mem[wBattleMonHP + 1]:
	ld hl, wBattleMonHP
	ld a, [hli]
	or [hl]
	jr z, .fainted
;>     if wLowHealthAlarmDisabled:
;>         return
	ld a, [wLowHealthAlarmDisabled]
	and a ; has the alarm been disabled because the player has already won?
	ret nz ; if so, return
;>     if wPlayerHPBarColor == HP_BAR_RED:           # low HP: the alarm beeps
;>@la         wLowHealthAlarm |= 1 << BIT_LOW_HEALTH_ALARM
;>@lr         return
	ld a, [wPlayerHPBarColor]
	cp HP_BAR_RED
	jr z, .setLowHealthAlarm
.fainted
;> was_on = wLowHealthAlarm >> BIT_LOW_HEALTH_ALARM & 1
	ld hl, wLowHealthAlarm
	bit BIT_LOW_HEALTH_ALARM, [hl]
;> wLowHealthAlarm = 0
	ld [hl], 0
;> if was_on:
	ret z
;>     wChannelSoundIDs[CHAN5] = 0
	xor a
	ld [wChannelSoundIDs + CHAN5], a
	ret
.setLowHealthAlarm
;=@la
	ld hl, wLowHealthAlarm
	set BIT_LOW_HEALTH_ALARM, [hl]
;=@lr
	ret

;@ path: engine/battle/core
;@ def DrawEnemyHUDAndHPBar()
;@ Draw the enemy's box at the top left: name, status or level, and the HP bar (48 pixels wide: HP x 48 / max
;@ HP, both divided by 4 first if the max HP is over 255), then the bar color.
;@ test: hLoadedROMBank = 0x0F; mem[0xD009 + rand(0, 10)] = 0x50; mem[0xCFDA + rand(0, 10)] = 0x50
DrawEnemyHUDAndHPBar:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> ClearScreenArea(coord(0, 0), 12, 4)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((4) & $ff) << 8 + ((12) & $ff)
	call ClearScreenArea
;> farcall(PlaceEnemyHUDTiles)
	ld hl, PlaceEnemyHUDTiles
	ld b, BANK(PlaceEnemyHUDTiles)
	call Bankswitch
;> PlaceString(wEnemyMonNick, CenterMonName(coord(1, 0), wEnemyMonNick))
	ld de, wEnemyMonNick
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	call CenterMonName
	call PlaceString
;> PrintStatusConditionNotFainted(wEnemyMonStatus, coord(5, 1))
	ld hl, (1) * SCREEN_WIDTH + (4) + wTileMap
	push hl
	inc hl
	ld de, wEnemyMonStatus
	call PrintStatusConditionNotFainted
;> if not mem[wEnemyMonStatus]:
	pop hl
	jr nz, .skipPrintLevel ; if the mon has a status condition, skip printing the level
;>     mem[wLoadedMonLevel] = mem[wEnemyMonLevel]
	ld a, [wEnemyMonLevel]
	ld [wLoadedMonLevel], a
;>     PrintLevel(coord(4, 1))
	call PrintLevel
.skipPrintLevel
;> hp = mem[wEnemyMonHP] << 8 | mem[wEnemyMonHP + 1]
;> hMultiplicand[1] = hp >> 8
	ld hl, wEnemyMonHP
	ld a, [hli]
	ldh [hMultiplicand + 1], a
;> hMultiplicand[2] = hp & 0xFF
	ld a, [hld]
	ldh [hMultiplicand + 2], a
;> if not hp:
	or [hl] ; is current HP zero?
	jr nz, .hpNonzero
; current HP is 0
; set variables for DrawHPBar
;>     pixels, sliver = 0, 0
	ld c, a
	ld e, a
	ld d, $6
	jp .drawHPBar
.hpNonzero
;> else:
;>     hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;>     hMultiplier = 48
	ld a, 48
	ldh [hMultiplier], a
;>     Multiply()
	call Multiply ; multiply current HP by 48
;>     max_hp = mem[wEnemyMonMaxHP] << 8 | mem[wEnemyMonMaxHP + 1]
	ld hl, wEnemyMonMaxHP
	ld a, [hli]
	ld b, a
;>     hDivisor = max_hp & 0xFF
	ld a, [hl]
	ldh [hDivisor], a
;>     if max_hp > 0xFF:
	ld a, b
	and a ; is max HP > 255?
	jr z, .doDivide
; if max HP > 255, scale both (current HP * 48) and max HP by dividing by 4 so that max HP fits in one byte
; (it needs to be one byte so it can be used as the divisor for the Divide function)
;>         hDivisor = max_hp >> 2 & 0xFF
	ldh a, [hDivisor]
	srl b
	rr a
	srl b
	rr a
	ldh [hDivisor], a
;>         scaled = (hProduct[2] << 8 | hProduct[3]) >> 1
	ldh a, [hProduct + 2]
	ld b, a
	srl b
	ldh a, [hProduct + 3]
	rr a
;>         scaled >>= 1
	srl b
	rr a
;>         hProduct[3] = scaled & 0xFF
	ldh [hProduct + 3], a
;>         hProduct[2] = scaled >> 8
	ld a, b
	ldh [hProduct + 2], a
.doDivide
;>     hDividend[0] = hProduct[2]
	ldh a, [hProduct + 2]
	ldh [hDividend], a
;>     hDividend[1] = hProduct[3]
	ldh a, [hProduct + 3]
	ldh [hDividend + 1], a
;>     Divide(2)
	ld a, $2
	ld b, a
	call Divide ; divide (current HP * 48) by max HP
;>     pixels, sliver = hQuotient[3], 6
	ldh a, [hQuotient + 3]
; set variables for DrawHPBar
	ld e, a
	ld a, $6
	ld d, a
	ld c, a
.drawHPBar
;> wHPBarType = 0
	xor a
	ld [wHPBarType], a
;> DrawHPBar(coord(2, 2), 6, pixels, sliver)
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	call DrawHPBar
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> GetBattleHealthBarColor(addr(wEnemyHPBarColor), pixels)
	ld hl, wEnemyHPBarColor

;@ path: engine/battle/core
;@ def GetBattleHealthBarColor(color: hl, pixels: e)
;@ Pick the colour of an HP bar pixels long into color, and redo the battle palettes if it changed.
;@ test: color = rand_ram(1); hLoadedROMBank = 0x0F
GetBattleHealthBarColor:
;> old = mem[color]
	ld b, [hl]
;> GetHealthBarColor(pixels, color)
	call GetHealthBarColor
;> if mem[color] != old:
	ld a, [hl]
	cp b
	ret z
;>     RunPaletteCommand(SET_PAL_BATTLE)
	ld b, SET_PAL_BATTLE
	jp RunPaletteCommand

; center's mon's name on the battle screen
; if the name is 1 or 2 letters long, it is printed 2 spaces more to the right than usual
; (i.e. for names longer than 4 letters)
; if the name is 3 or 4 letters long, it is printed 1 space more to the right than usual
; (i.e. for names longer than 4 letters)
;@ path: engine/battle/core
;@ def CenterMonName(dest: hl, name: de) -> hl
;@ Where to print a Pokemon's name so it sits centered in the HUD: up to two tiles right of dest for short names.
;@ test: name = rand_ram(5)
CenterMonName:
;> dest += 2
	push de
	inc hl
	inc hl
;> for i in (1, 3):
	ld b, $2
.loop
;>     if mem[name + i] == charmap('@')[0]:
;>         break
	inc de
	ld a, [de]
	cp '@'
	jr z, .done
;>     if mem[name + i + 1] == charmap('@')[0]:
;>         break
	inc de
	ld a, [de]
	cp '@'
	jr z, .done
;>     dest -= 1
	dec hl
	dec b
	jr nz, .loop
.done
;> return dest
	pop de
	ret

;@ path: engine/battle/core
;@ def DisplayBattleMenu() -> carry
;@ The battle menu: FIGHT, <PK><MN> (party), ITEM, RUN - or BALL, BAIT, ROCK, RUN in the Safari Zone - in two
;@ columns the cursor moves between, starting where it was last time. In the old man's catching demonstration
;@ the menu "presses itself" (ITEM) while the player's name is replaced by OLD MAN. Carry if the battle ended
;@ (ran away, Pokemon caught).
;@ test: skip waits for the player's input
DisplayBattleMenu::
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1 ; restore saved screen
;> if not wBattleType:
	ld a, [wBattleType]
	and a
	jr nz, .nonstandardbattle
;>     DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;>     PrintEmptyString()
	call PrintEmptyString
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
.nonstandardbattle
;> safari = wBattleType == BATTLE_TYPE_SAFARI
;> wTextBoxID = SAFARI_BATTLE_MENU_TEMPLATE if safari else BATTLE_MENU_TEMPLATE
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	ld a, BATTLE_MENU_TEMPLATE
	jr nz, .menuselected
	ld a, SAFARI_BATTLE_MENU_TEMPLATE
.menuselected
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
 ; handle menu input if it's not the old man tutorial
;> if wBattleType == BATTLE_TYPE_OLD_MAN:
	ld a, [wBattleType]
	ASSERT BATTLE_TYPE_OLD_MAN == 1
	dec a
	jp nz, .handleBattleMenuInput
; the following happens for the old man tutorial
	; Temporarily save the player name in wLinkEnemyTrainerName.
	; Since wLinkEnemyTrainerName == wGrassRate, this affects wild encounters.
	; The wGrassRate byte and following wGrassMons buffer are supposed
	; to get overwritten when entering a map with wild Pokémon,
	; but an oversight prevents this in Cinnabar and Route 21,
	; so the infamous MissingNo. glitch can show up.
;>     # the player's name is parked in wLinkEnemyTrainerName, which is wGrassRate: where the MissingNo. glitch
;>     # comes from on routes that don't reload their wild Pokemon
;>     CopyData(wPlayerName, wLinkEnemyTrainerName, NAME_LENGTH)
	ld hl, wPlayerName
	ld de, wLinkEnemyTrainerName
	ld bc, NAME_LENGTH
	call CopyData
;>     CopyData(addr(DisplayBattleMenu) + 0x5F, wPlayerName, NAME_LENGTH)   # its local "OLD MAN@"
	ld hl, .oldManName
	ld de, wPlayerName
	ld bc, NAME_LENGTH
	call CopyData
; the following simulates the keystrokes by drawing menus on screen
;>     mem[coord(9, 14)] = charmap('▶')[0]
	ld hl, (14) * SCREEN_WIDTH + (9) + wTileMap
	ld [hl], '▶'
;>     DelayFrames(80)
	ld c, 80
	call DelayFrames
;>     mem[coord(9, 14)] = charmap(' ')[0]
	ld [hl], ' '
;>     mem[coord(9, 16)] = charmap('▶')[0]
	ld hl, (16) * SCREEN_WIDTH + (9) + wTileMap
	ld [hl], '▶'
;>     DelayFrames(50)
	ld c, 50
	call DelayFrames
;>     mem[coord(9, 16)] = charmap('▷')[0]
	ld [hl], '▷'
;>     choice = 2                                    # ITEM
	ld a, $2 ; select the "ITEM" menu
	jp .upperLeftMenuItemWasNotSelected
.oldManName
	db "OLD MAN@"
.handleBattleMenuInput
;> else:
;>     wCurrentMenuItem = wBattleAndStartSavedMenuItem
;>     wLastMenuItem = wBattleAndStartSavedMenuItem
	ld a, [wBattleAndStartSavedMenuItem]
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
;>     left = wBattleAndStartSavedMenuItem < 2
;>     if not left:
	sub 2 ; check if the cursor is in the left column
	jr c, .leftColumn
; cursor is in the right column
;>         wCurrentMenuItem -= 2
	ld [wCurrentMenuItem], a
;>         wLastMenuItem = wCurrentMenuItem
	ld [wLastMenuItem], a
;>     while True:
	jr .rightColumn
.leftColumn ; put cursor in left column of menu
;>         if left:
;>             if not safari:
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	ld a, ' '
	jr z, .safariLeftColumn
; put cursor in left column for normal battle menu (i.e. when it's not a Safari battle)
	; clear upper cursor position in right column
;>                 mem[coord(15, 14)] = charmap(' ')[0]
	ld [(14) * SCREEN_WIDTH + (15) + wTileMap], a
	; clear lower cursor position in right column
;>                 mem[coord(15, 16)] = charmap(' ')[0]
	ld [(16) * SCREEN_WIDTH + (15) + wTileMap], a
;>                 x = 9
	ld b, $9 ; top menu item X
	jr .leftColumn_WaitForInput
.safariLeftColumn
;>             else:                                 # Safari: the menu is wider, with the ball count
;>                 mem[coord(13, 14)] = charmap(' ')[0]
;>                 mem[coord(13, 16)] = charmap(' ')[0]
	ld [(14) * SCREEN_WIDTH + (13) + wTileMap], a
	ld [(16) * SCREEN_WIDTH + (13) + wTileMap], a
;>                 PrintNumber(wNumSafariBalls, coord(7, 14), 1, 2)
;>                 x = 1
	ld hl, (14) * SCREEN_WIDTH + (7) + wTileMap
	ld de, wNumSafariBalls
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
	ld b, $1 ; top menu item X
.leftColumn_WaitForInput
;>             wTopMenuItemY = 14
	ld hl, wTopMenuItemY
	ld a, $e
	ld [hli], a ; wTopMenuItemY
;>             wTopMenuItemX = x
	ld a, b
	ld [hli], a ; wTopMenuItemX
	inc hl
	inc hl
;>             wMaxMenuItem = 1
	ld a, $1
	ld [hli], a ; wMaxMenuItem
;>             wMenuWatchedKeys = PAD_RIGHT | PAD_A
	ld [hl], PAD_RIGHT | PAD_A ; wMenuWatchedKeys
;>             keys = HandleMenuInput()
	call HandleMenuInput
;>             if keys >> B_PAD_RIGHT & 1:
;>                 left = False
	bit B_PAD_RIGHT, a
;>                 continue
	jr nz, .rightColumn
;>             break
	jr .AButtonPressed ; the A button was pressed
.rightColumn ; put cursor in right column of menu
;>         if not safari:
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	ld a, ' '
	jr z, .safariRightColumn
; put cursor in right column for normal battle menu (i.e. when it's not a Safari battle)
	; clear upper cursor position in left column
;>             mem[coord(9, 14)] = charmap(' ')[0]
	ld [(14) * SCREEN_WIDTH + (9) + wTileMap], a
	; clear lower cursor position in left column
;>             mem[coord(9, 16)] = charmap(' ')[0]
	ld [(16) * SCREEN_WIDTH + (9) + wTileMap], a
;>             x = 15
	ld b, $f ; top menu item X
	jr .rightColumn_WaitForInput
.safariRightColumn
;>         else:
;>             mem[coord(1, 14)] = charmap(' ')[0]
	; clear upper cursor position in left column
	ld [(14) * SCREEN_WIDTH + (1) + wTileMap], a
	; clear lower cursor position in left column
;>             mem[coord(1, 16)] = charmap(' ')[0]
	ld [(16) * SCREEN_WIDTH + (1) + wTileMap], a
;>             PrintNumber(wNumSafariBalls, coord(7, 14), 1, 2)
;>             x = 13
	ld hl, (14) * SCREEN_WIDTH + (7) + wTileMap
	ld de, wNumSafariBalls
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
	ld b, $d ; top menu item X
.rightColumn_WaitForInput
;>         wTopMenuItemY = 14
	ld hl, wTopMenuItemY
	ld a, $e
	ld [hli], a ; wTopMenuItemY
;>         wTopMenuItemX = x
	ld a, b
	ld [hli], a ; wTopMenuItemX
	inc hl
	inc hl
;>         wMaxMenuItem = 1
	ld a, $1
	ld [hli], a ; wMaxMenuItem
;>         wMenuWatchedKeys = PAD_LEFT | PAD_A
	ld a, PAD_LEFT | PAD_A
	ld [hli], a ; wMenuWatchedKeys
;>         keys = HandleMenuInput()
	call HandleMenuInput
;>         if keys >> B_PAD_LEFT & 1:
;>             left = True
	bit B_PAD_LEFT, a
;>             continue
	jr nz, .leftColumn ; if left was pressed, jump
;>         wCurrentMenuItem += 2                     # right column: items 2 and 3
;>         break
	ld a, [wCurrentMenuItem]
	add $2 ; if we're in the right column, the actual id is +2
	ld [wCurrentMenuItem], a
.AButtonPressed
;>     PlaceUnfilledArrowMenuCursor(keys)
	call PlaceUnfilledArrowMenuCursor
;=@ns
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
;>     choice = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
;>     wBattleAndStartSavedMenuItem = choice
	ld [wBattleAndStartSavedMenuItem], a
;>@ns     if not safari:                               # on screen ITEM and the party swapped places
	jr z, .handleMenuSelection
; not Safari battle
; swap the IDs of the item menu and party menu (this is probably because they swapped the positions
; of these menu items in first generation English versions)
;>         if choice == 1:
;>             choice = 2
	cp $1 ; was the item menu selected?
	jr nz, .notItemMenu
; item menu was selected
	inc a ; increment a to 2
	jr .handleMenuSelection
.notItemMenu
;>         elif choice == 2:
;>             choice = 1
	cp $2 ; was the party menu selected?
	jr nz, .handleMenuSelection
; party menu selected
	dec a ; decrement a to 1
.handleMenuSelection
;>     if choice == 0:
	and a
	jr nz, .upperLeftMenuItemWasNotSelected
; the upper left menu item was selected
;>         if safari:
;>@sb             wCurItem = SAFARI_BALL
;>@sb2             return UseBagItem()
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jr z, .throwSafariBallWasSelected
; the "FIGHT" menu was selected
;>         wNumRunAttempts = 0                       # FIGHT
	xor a
	ld [wNumRunAttempts], a
;>         LoadScreenTilesFromBuffer1()
;>         return False
	jp LoadScreenTilesFromBuffer1 ; restore saved screen and return
.throwSafariBallWasSelected
;=@sb
	ld a, SAFARI_BALL
	ld [wCurItem], a
;=@sb2
	jr UseBagItem

.upperLeftMenuItemWasNotSelected ; a menu item other than the upper left item was selected
;> if choice != 2:
;>     return PartyMenuOrRockOrRun(choice)
	cp $2
	jp nz, PartyMenuOrRockOrRun

; either the bag (normal battle) or bait (safari battle) was selected
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .notLinkBattle

; can't use items in link battles
;>     PrintText(ItemsCantBeUsedHereText)
	ld hl, ItemsCantBeUsedHereText
	call PrintText
;>     return DisplayBattleMenu()
	jp DisplayBattleMenu

.notLinkBattle
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> if safari:
;>     wCurItem = SAFARI_BAIT
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jr nz, BagWasSelected

; bait was selected
	ld a, SAFARI_BAIT
	ld [wCurItem], a
;>     return UseBagItem()
	jr UseBagItem
;> return BagWasSelected()                           # (the jump above)

;@ path: engine/battle/core
;@ def BagWasSelected() -> carry
;@ Open the bag in battle (in the old man's demonstration his own list with the Poke Ball).
;@ test: skip waits for the player's input
BagWasSelected:
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> if not wBattleType:
	ld a, [wBattleType]
	and a ; is it a normal battle?
	jr nz, .next

; normal battle
;>     DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
.next
;> if wBattleType != BATTLE_TYPE_OLD_MAN:
;>     return DisplayPlayerBag()
	ld a, [wBattleType]
	dec a ; is it the old man tutorial?
	jr nz, DisplayPlayerBag ; no, it is a normal battle
;> wListPointer[0] = OldManItemList & 0xFF
	ld hl, OldManItemList
	ld a, l
	ld [wListPointer], a
;> wListPointer[1] = OldManItemList >> 8
	ld a, h
	ld [wListPointer + 1], a
;> return DisplayBagMenu()
	jr DisplayBagMenu

;@ path: engine/battle/core
OldManItemList:
	db 1 ; # items
	db POKE_BALL, 50
	db -1 ; end

;@ path: engine/battle/core
;@ def DisplayPlayerBag() -> carry
;@ Show the player's bag items as the list.
;@ test: skip waits for the player's input
DisplayPlayerBag:
;> wListPointer[0] = addr(wNumBagItems) & 0xFF
	; get the pointer to player's bag when in a normal battle
	ld hl, wNumBagItems
	ld a, l
	ld [wListPointer], a
;> wListPointer[1] = addr(wNumBagItems) >> 8
	ld a, h
	ld [wListPointer + 1], a
;> return DisplayBagMenu()

;@ path: engine/battle/core
;@ def DisplayBagMenu() -> carry
;@ The item list at the last bag position; cancelling goes back to the battle menu, choosing an item uses it.
;@ test: skip waits for the player's input
DisplayBagMenu:
;> wPrintItemPrices = 0
	xor a
	ld [wPrintItemPrices], a
;> wListMenuID = ITEMLISTMENU
	ld a, ITEMLISTMENU
	ld [wListMenuID], a
;> wCurrentMenuItem = wBagSavedMenuItem
	ld a, [wBagSavedMenuItem]
	ld [wCurrentMenuItem], a
;> cancelled = DisplayListMenuID()                   # carry: nothing chosen
	call DisplayListMenuID
;> wBagSavedMenuItem = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wBagSavedMenuItem], a
;> wMenuWatchMovingOutOfBounds = 0
	ld a, $0
	ld [wMenuWatchMovingOutOfBounds], a
;> wMenuItemToSwap = 0
	ld [wMenuItemToSwap], a
;> if cancelled:
;>     return DisplayBattleMenu()
	jp c, DisplayBattleMenu ; go back to battle menu if an item was not selected
;> return UseBagItem()                               # (it follows)

;@ path: engine/battle/core
;@ def UseBagItem() -> carry
;@ Use wCurItem in battle (also the Safari Ball, bait and rock). An item that didn't work leads back to the bag.
;@ Using an item counts as a turn of a Wrap-like move. Carry if a Pokemon was caught.
;@ test: skip uses an item with its texts and animations
UseBagItem:
	; either use an item from the bag or use a safari zone item
;> wNamedObjectIndex = wCurItem
	ld a, [wCurItem]
	ld [wNamedObjectIndex], a
;> CopyToStringBuffer(GetItemName())
	call GetItemName
	call CopyToStringBuffer
;> wPseudoItemID = 0
	xor a
	ld [wPseudoItemID], a
;> UseItem()
	call UseItem
;> LoadHudTilePatterns()
	call LoadHudTilePatterns
;> ClearSprites()
	call ClearSprites
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> if wBattleType != BATTLE_TYPE_SAFARI:
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jr z, .checkIfMonCaptured

;>     if not wActionResultOrTookBattleTurn:
;>         return BagWasSelected()                   # the item was not used
	ld a, [wActionResultOrTookBattleTurn]
	and a ; was the item used successfully?
	jp z, BagWasSelected ; if not, go back to the bag menu

;>     if wPlayerBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	ld a, [wPlayerBattleStatus1]
	bit USING_TRAPPING_MOVE, a ; is the player using a multi-turn move like wrap?
	jr z, .checkIfMonCaptured
;>         wPlayerNumAttacksLeft -= 1
	ld hl, wPlayerNumAttacksLeft
	dec [hl]
;>         if not wPlayerNumAttacksLeft:
	jr nz, .checkIfMonCaptured
;>             wPlayerBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld hl, wPlayerBattleStatus1
	res USING_TRAPPING_MOVE, [hl] ; not using multi-turn move any more

.checkIfMonCaptured
;> if wCapturedMonSpecies:                  # caught with a ball
;>@pal     GBPalNormal()
;>@clr     wCapturedMonSpecies = 0
;>@res     wBattleResult = 2
;>@yes     return True
	ld a, [wCapturedMonSpecies]
	and a ; was the enemy mon captured with a ball?
	jr nz, .returnAfterCapturingMon

;> if wBattleType != BATTLE_TYPE_SAFARI:
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jr z, .returnAfterUsingItem_NoCapture
; not a safari battle
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     DrawHUDsAndHPBars()
	call DrawHUDsAndHPBars
;>     Delay3()
	call Delay3
.returnAfterUsingItem_NoCapture

;> GBPalNormal()
	call GBPalNormal
;> return False
	and a ; reset carry
	ret

.returnAfterCapturingMon
;=@pal
	call GBPalNormal
;=@clr
	xor a
	ld [wCapturedMonSpecies], a
;=@res
	ld a, $2
	ld [wBattleResult], a
;=@yes
	scf ; set carry
	ret

;@ path: engine/battle/core
ItemsCantBeUsedHereText:
	db TX_FAR
	dw _ItemsCantBeUsedHereText
	db BANK(_ItemsCantBeUsedHereText)
	db TX_END

;@ path: engine/battle/core
;@ def PartyMenuOrRockOrRun(choice: a) -> carry
;@ Menu choice 1 is the party (or the rock in the Safari Zone), 3 is RUN. In the party menu a Pokemon offers
;@ SWITCH, STATS and CANCEL: STATS shows its two status screens (then the enemy picture is restored), SWITCH sends
;@ it out instead unless it is already out or fainted.
;@ test: skip waits for the player's input
PartyMenuOrRockOrRun:
;> if choice != 1:
;>     return BattleMenu_RunWasSelected()
	dec a ; was Run selected?
	jp nz, BattleMenu_RunWasSelected
; party menu or rock was selected
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> if wBattleType == BATTLE_TYPE_SAFARI:
	ld a, [wBattleType]
	cp BATTLE_TYPE_SAFARI
	jr nz, .partyMenuWasSelected
; safari battle
;>     wCurItem = SAFARI_ROCK
	ld a, SAFARI_ROCK
	ld [wCurItem], a
;>     return UseBagItem()
	jp UseBagItem
.partyMenuWasSelected
;> back = False
;>@outer while True:                                 # the party menu (again after the status screens)
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     wPartyMenuTypeOrMessageID = NORMAL_PARTY_MENU
	xor a ; NORMAL_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;>     wMenuItemToSwap = 0
	ld [wMenuItemToSwap], a
;>     cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
.checkIfPartyMonWasSelected
;>@inner     while True:
;>@back         if back:                           # B, or a Pokemon that can't switch in: back to the party
;>@fill             FillMemory(coord(11, 11), 6 * SCREEN_WIDTH + 9, charmap(' ')[0]); wPartyMenuTypeOrMessageID = NORMAL_PARTY_MENU
;>@go             cancelled, back = GoBackToPartyMenu(), False
;>         if cancelled:
	jp nc, .partyMonWasSelected ; if a party mon was selected, jump, else we quit the party menu
.quitPartyMenu
;>             ClearSprites()
	call ClearSprites
;>             GBPalWhiteOut()
	call GBPalWhiteOut
;>             LoadHudTilePatterns()
	call LoadHudTilePatterns
;>             LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;>             RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>             GBPalNormal()
	call GBPalNormal
;>             return DisplayBattleMenu()
	jp DisplayBattleMenu
.partyMonDeselected
;=@fill
	ld hl, (11) * SCREEN_WIDTH + (11) + wTileMap
	ld bc, 6 * SCREEN_WIDTH + 9
	ld a, ' '
	call FillMemory
	xor a ; NORMAL_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;=@go
	call GoBackToPartyMenu
;=@inner
	jr .checkIfPartyMonWasSelected
.partyMonWasSelected
;>         wTextBoxID = SWITCH_STATS_CANCEL_MENU_TEMPLATE
	ld a, SWITCH_STATS_CANCEL_MENU_TEMPLATE
	ld [wTextBoxID], a
;>         DisplayTextBoxID()
	call DisplayTextBoxID
;>         wTopMenuItemY = 12
	ld hl, wTopMenuItemY
	ld a, $c
	ld [hli], a ; wTopMenuItemY
;>         wTopMenuItemX = 12
	ld [hli], a ; wTopMenuItemX
;>         wCurrentMenuItem = 0
	xor a
	ld [hli], a ; wCurrentMenuItem
;>         wMaxMenuItem = 2
	inc hl
	ld a, $2
	ld [hli], a ; wMaxMenuItem
;>         wMenuWatchedKeys = PAD_B | PAD_A
	ld a, PAD_B | PAD_A
	ld [hli], a ; wMenuWatchedKeys
;>         wLastMenuItem = 0
	xor a
	ld [hl], a ; wLastMenuItem
;>         keys = HandleMenuInput()
	call HandleMenuInput
;>         if keys >> B_PAD_B & 1:
;>             back = True
	bit B_PAD_B, a
	jr nz, .partyMonDeselected ; if B was pressed, jump
; A was pressed
;>             continue
;>         PlaceUnfilledArrowMenuCursor(keys)
	call PlaceUnfilledArrowMenuCursor
;>         if wCurrentMenuItem == 2:                 # CANCEL
;>             cancelled = True
	ld a, [wCurrentMenuItem]
	cp $2 ; was Cancel selected?
	jr z, .quitPartyMenu ; if so, quit the party menu entirely
;>             continue
;>         if wCurrentMenuItem == 1:                 # STATS
	and a ; was Switch selected?
	jr z, .switchMon ; if so, jump
; Stats was selected
;>             wMonDataLocation = PLAYER_PARTY_DATA
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
	ld hl, wPartyMon1
;>             ClearSprites()
	call ClearSprites
; display the two status screens
;>             predef(StatusScreen)
	ld a, (StatusScreenPredef - PredefPointers) / 3
	call Predef
;>             predef(StatusScreen2)
	ld a, (StatusScreen2Predef - PredefPointers) / 3
	call Predef
; now we need to reload the enemy mon pic
;>             if wEnemyBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>@sub                 farcall(AnimationSubstitute)
	ld a, [wEnemyBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a ; does the enemy mon have a substitute?
	ld hl, AnimationSubstitute
	jr nz, .doEnemyMonAnimation
; enemy mon doesn't have substitute
;>             elif wEnemyMonMinimized:
;>                 farcall(AnimationMinimizeMon)     # (the same call below)
	ld a, [wEnemyMonMinimized]
	and a ; has the enemy mon used Minimize?
	ld hl, AnimationMinimizeMon
	jr nz, .doEnemyMonAnimation
; enemy mon is not minimized
;>             else:
;>                 wCurPartySpecies = mem[wEnemyMonSpecies]
	ld a, [wEnemyMonSpecies]
	ld [wCurPartySpecies], a
;>                 wCurSpecies = mem[wEnemyMonSpecies]
	ld [wCurSpecies], a
;>                 GetMonHeader()
	call GetMonHeader
;>                 LoadMonFrontSprite(vFrontPic)
	ld de, vFrontPic
	call LoadMonFrontSprite
	jr .enemyMonPicReloaded
.doEnemyMonAnimation
;=@sub
	ld b, BANK(AnimationSubstitute) ; BANK(AnimationMinimizeMon)
	call Bankswitch
.enemyMonPicReloaded ; enemy mon pic has been reloaded, so return to the party menu
;>@again             break                             # back to the party menu
	jp .partyMenuWasSelected
.switchMon
;>         if wWhichPokemon == wPlayerMonNumber:     # SWITCH
	ld a, [wPlayerMonNumber]
	ld d, a
	ld a, [wWhichPokemon]
	cp d ; check if the mon to switch to is already out
	jr nz, .notAlreadyOut
; mon is already out
;>             PrintText(AlreadyOutText)
	ld hl, AlreadyOutText
	call PrintText
;>             back = True
;>             continue
	jp .partyMonDeselected
.notAlreadyOut
;>         elif HasMonFainted():
	call HasMonFainted
;>             back = True
;>             continue
	jp z, .partyMonDeselected ; can't switch to fainted mon
;>         wActionResultOrTookBattleTurn = 1
	ld a, $1
	ld [wActionResultOrTookBattleTurn], a
;>         GBPalWhiteOut()
	call GBPalWhiteOut
;>         ClearSprites()
	call ClearSprites
;>         LoadHudTilePatterns()
	call LoadHudTilePatterns
;>         LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>         RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;>         GBPalNormal()
	call GBPalNormal
;>         return SwitchPlayerMon()
; fall through to SwitchPlayerMon

;@ path: engine/battle/core
;@ def SwitchPlayerMon() -> carry
;@ Call back the player's Pokemon ("<MON>, come back!") and send out party Pokemon wWhichPokemon. No carry.
;@ test: skip animates and prints texts
SwitchPlayerMon:
;> farcall(RetreatMon)
	ld hl, RetreatMon
	ld b, BANK(RetreatMon)
	call Bankswitch
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> AnimateRetreatingPlayerMon()
	call AnimateRetreatingPlayerMon
;> wPlayerMonNumber = wWhichPokemon
	ld a, [wWhichPokemon]
	ld [wPlayerMonNumber], a
;> predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=FLAG_SET << 8 | wWhichPokemon)
	ld c, a
	ld b, FLAG_SET
	push bc
	ld hl, wPartyGainExpFlags
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> predef(FlagActionPredef, hl=wPartyFoughtCurrentEnemyFlags, bc=FLAG_SET << 8 | wWhichPokemon)
	pop bc
	ld hl, wPartyFoughtCurrentEnemyFlags
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> LoadBattleMonFromParty()
	call LoadBattleMonFromParty
;> SendOutMon()
	call SendOutMon
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> wCurrentMenuItem = 2
	ld a, $2
	ld [wCurrentMenuItem], a
;> return False
	and a
	ret

;@ path: engine/battle/core
AlreadyOutText:
	db TX_FAR
	dw _AlreadyOutText
	db BANK(_AlreadyOutText)
	db TX_END

;@ path: engine/battle/core
;@ def BattleMenu_RunWasSelected() -> carry
;@ RUN: try to get away (carry if it worked); a failed try costs the turn, a refusal (trainer battle) leads back
;@ to the battle menu.
;@ test: skip prints texts and waits for the player
BattleMenu_RunWasSelected:
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> wCurrentMenuItem = 3
	ld a, $3
	ld [wCurrentMenuItem], a
;> escaped = TryRunningFromBattle(wBattleMonSpeed, wEnemyMonSpeed)
	ld hl, wBattleMonSpeed
	ld de, wEnemyMonSpeed
	call TryRunningFromBattle
;> wForcePlayerToChooseMon = 0
	ld a, 0
	ld [wForcePlayerToChooseMon], a
;> if escaped:
;>     return True
	ret c
;> if wActionResultOrTookBattleTurn:
;>     return False
	ld a, [wActionResultOrTookBattleTurn]
	and a
	ret nz ; return if the player couldn't escape
;> return DisplayBattleMenu()
	jp DisplayBattleMenu

;@ path: engine/battle/core
;@ def MoveSelectionMenu() -> zero
;@ The move list box: for choosing a move in battle (wMoveMenuType 0), for Mimic (1: the enemy's moves) or for
;@ the move relearner (2: party Pokemon wWhichPokemon's). In battle, if no move can be used, Struggle is picked
;@ right away. Zero if a move was chosen.
;@ test: skip waits for the player's input
MoveSelectionMenu:
;> if wMoveMenuType == 1:                            # Mimic: the enemy's moves
;>@mim     moves, box, text, x, y = wEnemyMonMoves, coord(0, 7), coord(2, 8), 1, 7
	ld a, [wMoveMenuType]
	dec a
	jr z, .mimicmenu
;> elif wMoveMenuType == 2:                          # relearning a move
;>@rel     moves = wPartyMon1Moves + wWhichPokemon * PARTYMON_STRUCT_LENGTH
;>@relxy     box, text, x, y = coord(4, 7), coord(6, 8), 5, 7
	dec a
	jr z, .relearnmenu
;> else:
	jr .regularmenu

.loadmoves
;=@load
	ld de, wMoves
	ld bc, NUM_MOVES
	call CopyData
;=@fmt
	ld hl, FormatMovesString
	ld b, BANK(FormatMovesString)
	call Bankswitch
	ret

.writemoves
;=@single
	ld de, wMovesString
	ldh a, [hUILayoutFlags]
	set BIT_SINGLE_SPACED_LINES, a
	ldh [hUILayoutFlags], a
;=@write
	call PlaceString
;=@double
	ldh a, [hUILayoutFlags]
	res BIT_SINGLE_SPACED_LINES, a
	ldh [hUILayoutFlags], a
	ret

.regularmenu
;>     if AnyMoveToSelect():
;>         return True                               # none usable: Struggle
	call AnyMoveToSelect
	ret z
;>@reg     moves, box, text, x, y = wBattleMonMoves, coord(4, 12), coord(6, 13), 5, 12
	ld hl, wBattleMonMoves
;>@load CopyData(moves, wMoves, NUM_MOVES)        # .loadmoves
;>@fmt farcall(FormatMovesString)
	call .loadmoves
;>@box TextBoxBorder(box, 4, 14)
	ld hl, (12) * SCREEN_WIDTH + (4) + wTileMap
	ld b, 4
	ld c, 14
	di ; out of pure coincidence, it is possible for vblank to occur between the di and ei
	   ; so it is necessary to put the di ei block to not cause tearing
	call TextBoxBorder
;> if wMoveMenuType not in (1, 2):                   # (drawn with interrupts off, against tearing)
;>     mem[coord(4, 12)] = charmap('─')[0]
	ld hl, (12) * SCREEN_WIDTH + (4) + wTileMap
	ld [hl], '─'
;>     mem[coord(10, 12)] = charmap('┘')[0]
	ld hl, (12) * SCREEN_WIDTH + (10) + wTileMap
	ld [hl], '┘'
	ei
;>@single hUILayoutFlags |= 1 << BIT_SINGLE_SPACED_LINES   # .writemoves
;>@write PlaceString(wMovesString, text)
	ld hl, (13) * SCREEN_WIDTH + (6) + wTileMap
	call .writemoves
;>@double hUILayoutFlags &= ~(1 << BIT_SINGLE_SPACED_LINES)
;=@reg
	ld b, $5
	ld a, $c
	jr .menuset
.mimicmenu
;=@mim
	ld hl, wEnemyMonMoves
;=@load
	call .loadmoves
;=@box
	ld hl, (7) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 4
	ld c, 14
	call TextBoxBorder
;=@write
	ld hl, (8) * SCREEN_WIDTH + (2) + wTileMap
	call .writemoves
;=@mim
	ld b, $1
	ld a, $7
	jr .menuset
.relearnmenu
;=@rel
	ld a, [wWhichPokemon]
	ld hl, wPartyMon1Moves
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;=@load
	call .loadmoves
;=@box
	ld hl, (7) * SCREEN_WIDTH + (4) + wTileMap
	ld b, 4
	ld c, 14
	call TextBoxBorder
;=@write
	ld hl, (8) * SCREEN_WIDTH + (6) + wTileMap
	call .writemoves
;=@relxy
	ld b, $5
	ld a, $7
.menuset
;> wTopMenuItemY = y
	ld hl, wTopMenuItemY
	ld [hli], a ; wTopMenuItemY
;> wTopMenuItemX = x
	ld a, b
	ld [hli], a ; wTopMenuItemX
;> item = wMoveMenuType
;> if item != 1:
	ld a, [wMoveMenuType]
	cp $1
	jr z, .selectedmoveknown
;>     item = 1
;>     if wMoveMenuType == 0:                        # in battle: the last move used
	ld a, $1
	jr nc, .selectedmoveknown
;>         item = wPlayerMoveListIndex + 1
	ld a, [wPlayerMoveListIndex]
	inc a
.selectedmoveknown
;> wCurrentMenuItem = item
	ld [hli], a ; wCurrentMenuItem
	inc hl ; wTileBehindCursor untouched
;> wMaxMenuItem = wNumMovesMinusOne + 2
	ld a, [wNumMovesMinusOne]
	inc a
	inc a
	ld [hli], a ; wMaxMenuItem
;> if wMoveMenuType == 1:
;>     keys = PAD_UP | PAD_DOWN | PAD_A
	ld a, [wMoveMenuType]
	dec a
	ld b, PAD_UP | PAD_DOWN | PAD_A
	jr z, .matchedkeyspicked
;> elif wMoveMenuType == 2:
;>     keys = PAD_UP | PAD_DOWN | PAD_A | PAD_B
	dec a
	ld b, PAD_UP | PAD_DOWN | PAD_A | PAD_B
	jr z, .matchedkeyspicked
;> elif wLinkState == LINK_STATE_BATTLING:           # (the same keys)
;>     keys = PAD_UP | PAD_DOWN | PAD_A | PAD_B
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr z, .matchedkeyspicked
	; Disable left, right, and START buttons in regular battles.
;> else:
;>     test = wStatusFlags7 >> BIT_TEST_BATTLE & 1
	ld a, [wStatusFlags7]
	bit BIT_TEST_BATTLE, a
;>     keys = ~(PAD_LEFT | PAD_RIGHT | PAD_START) & 0xFF
;>     if test:                                      # TestBattle: all keys
	ld b, ~(PAD_LEFT | PAD_RIGHT | PAD_START)
	jr z, .matchedkeyspicked
;>         keys = PAD_CTRL_PAD | PAD_BUTTONS
	ld b, PAD_CTRL_PAD | PAD_BUTTONS
.matchedkeyspicked
;> wMenuWatchedKeys = keys
	ld a, b
	ld [hli], a ; wMenuWatchedKeys
;> wLastMenuItem = 1 if wMoveMenuType == 1 else wPlayerMoveListIndex + 1
	ld a, [wMoveMenuType]
	cp $1
	jr z, .movelistindex1
	ld a, [wPlayerMoveListIndex]
	inc a
.movelistindex1
	ld [hl], a
;> return SelectMenuItem()
; fallthrough

;@ path: engine/battle/core
;@ def SelectMenuItem() -> zero
;@ Let the player pick from the move list. In battle the box beside it shows the move's type and PP (and a mark
;@ on a move picked for swapping); Select picks moves to swap, B backs out. A move without PP or a disabled one
;@ can't be chosen ("No PP left!", "The move is disabled!"). Zero if a move was chosen.
;@ test: skip waits for the player's input
SelectMenuItem:
;>@bat if wMoveMenuType == 0 and not wStatusFlags7 >> BIT_TEST_BATTLE & 1:   # (TestBattle: no info box)
;>@pmi     PrintMenuItem()
	ld a, [wMoveMenuType]
	and a
	jr z, .battleselect
;>@swp     if wMenuItemToSwap:
;>@mark         mem[coord(5, 13) + (wMenuItemToSwap - 1) * SCREEN_WIDTH] = charmap('▷')[0]
;> elif wMoveMenuType == 1:
	dec a
	jr nz, .select
;>     PlaceString(WhichTechniqueString, coord(1, 14))
	ld hl, (14) * SCREEN_WIDTH + (1) + wTileMap
	ld de, WhichTechniqueString
	call PlaceString
	jr .select
.battleselect
	; Hide move swap cursor in TestBattle.
;=@bat
	ld a, [wStatusFlags7]
	bit BIT_TEST_BATTLE, a
	; This causes PrintMenuItem to not run in TestBattle.
	; MoveSelectionMenu still draws part of its window, an issue
	; which did not seem to exist in the Japanese versions.
	jr nz, .select
;=@pmi
	call PrintMenuItem
;=@swp
	ld a, [wMenuItemToSwap]
	and a
	jr z, .select
;=@mark
	ld hl, (13) * SCREEN_WIDTH + (5) + wTileMap
	dec a
	ld bc, SCREEN_WIDTH
	call AddNTimes
	ld [hl], '▷'
.select
;> hUILayoutFlags |= 1 << BIT_DOUBLE_SPACED_MENU
	ld hl, hUILayoutFlags
	set BIT_DOUBLE_SPACED_MENU, [hl]
;> keys = HandleMenuInput()
	call HandleMenuInput
;> hUILayoutFlags &= ~(1 << BIT_DOUBLE_SPACED_MENU)
	ld hl, hUILayoutFlags
	res BIT_DOUBLE_SPACED_MENU, [hl]
;> if keys >> B_PAD_UP & 1:
;>     return SelectMenuItem_CursorUp()
	bit B_PAD_UP, a
	jp nz, SelectMenuItem_CursorUp
;> if keys >> B_PAD_DOWN & 1:
;>     return SelectMenuItem_CursorDown()
	bit B_PAD_DOWN, a
	jp nz, SelectMenuItem_CursorDown
;> if keys >> B_PAD_SELECT & 1:
;>     return SwapMovesInMenu()
	bit B_PAD_SELECT, a
	jp nz, SwapMovesInMenu
;> b_pressed = keys >> B_PAD_B & 1
	bit B_PAD_B, a
	push af
;> wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a
;> wCurrentMenuItem -= 1
	ld a, [wCurrentMenuItem]
	dec a
	ld [wCurrentMenuItem], a
	ld b, a
;> if wMoveMenuType == 1:
;>     return not b_pressed
	ld a, [wMoveMenuType]
	dec a ; if not mimic
	jr nz, .notB
	pop af
	ret
.notB
;> wPlayerMoveListIndex = wCurrentMenuItem
	dec a
	ld a, b
	ld [wPlayerMoveListIndex], a
;> if wMoveMenuType != 0 or b_pressed:
;>     return not b_pressed
	jr nz, .moveselected
	pop af
	ret
.moveselected
	pop af
	ret nz
;> pp = wBattleMonPP + wCurrentMenuItem
	ld hl, wBattleMonPP
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, $0
	add hl, bc
;> if not mem[pp] & PP_MASK:
;>     text = MoveNoPPText
	ld a, [hl]
	and PP_MASK
	jr z, .noPP
;> elif ((wPlayerDisabledMove >> 4) - 1) & 0xFF == wCurrentMenuItem:
;>     text = MoveDisabledText
	ld a, [wPlayerDisabledMove]
	swap a
	and $f
	dec a
	cp c
	jr z, .disabled
;> else:
	ld a, [wPlayerBattleStatus3]
	bit TRANSFORMED, a
	jr nz, .transformedMoveSelected
.transformedMoveSelected ; pointless
	; Allow moves copied by Transform to be used.
;>     entry = wBattleMonMoves + wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld hl, wBattleMonMoves
	ld c, a
	ld b, $0
	add hl, bc
;>     wPlayerSelectedMove = mem[entry]
	ld a, [hl]
	ld [wPlayerSelectedMove], a
;>     return True
	xor a
	ret
.disabled
	ld hl, MoveDisabledText
	jr .print
.noPP
	ld hl, MoveNoPPText
.print
;> PrintText(text)
	call PrintText
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> return MoveSelectionMenu()
	jp MoveSelectionMenu

;@ path: engine/battle/core
MoveNoPPText:
	db TX_FAR
	dw _MoveNoPPText
	db BANK(_MoveNoPPText)
	db TX_END

;@ path: engine/battle/core
MoveDisabledText:
	db TX_FAR
	dw _MoveDisabledText
	db BANK(_MoveDisabledText)
	db TX_END

;@ path: engine/battle/core
WhichTechniqueString:
	db "WHICH TECHNIQUE?@"

;@ path: engine/battle/core
;@ def SelectMenuItem_CursorUp() -> zero
;@ Up from the first move wraps around to the last.
;@ test: skip waits for the player's input
SelectMenuItem_CursorUp:
;> if not wCurrentMenuItem:                          # up from the first move
	ld a, [wCurrentMenuItem]
	and a
	jp nz, SelectMenuItem
;>     EraseMenuCursor()
	call EraseMenuCursor
;>     wCurrentMenuItem = wNumMovesMinusOne + 1      # to the last
	ld a, [wNumMovesMinusOne]
	inc a
	ld [wCurrentMenuItem], a
;> return SelectMenuItem()
	jp SelectMenuItem

;@ path: engine/battle/core
;@ def SelectMenuItem_CursorDown() -> zero
;@ Down from the last move wraps around to the first.
;@ test: skip waits for the player's input
SelectMenuItem_CursorDown:
;> item = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld b, a
;> last = wNumMovesMinusOne + 2
	ld a, [wNumMovesMinusOne]
	inc a
	inc a
;> if item == last:                                  # down from the last move
	cp b
	jp nz, SelectMenuItem
;>     EraseMenuCursor()
	call EraseMenuCursor
;>     wCurrentMenuItem = 1                          # to the first
	ld a, $1
	ld [wCurrentMenuItem], a
;> return SelectMenuItem()
	jp SelectMenuItem

;@ path: engine/battle/core
;@ def AnyMoveToSelect() -> zero
;@ Whether the player's Pokemon can use any move: if all have 0 PP (not counting a disabled one), "<MON> has no
;@ moves left!" and Struggle (zero). With a disabled move the whole PP bytes are checked, PP Up bits included.
AnyMoveToSelect:
; return z and Struggle as the selected move if all moves have 0 PP and/or are disabled
;> wPlayerSelectedMove = STRUGGLE
	ld a, STRUGGLE
	ld [wPlayerSelectedMove], a
;> left = 0
;> if not wPlayerDisabledMove:
	ld a, [wPlayerDisabledMove]
	and a
	ld hl, wBattleMonPP
	jr nz, .handleDisabledMove
;>     for i in range(NUM_MOVES):
;>         left |= mem[wBattleMonPP + i]
	ld a, [hli]
	or [hl]
	inc hl
	or [hl]
	inc hl
	or [hl]
;>     left &= PP_MASK
	and PP_MASK
	ret nz
	jr .noMovesLeft
.handleDisabledMove
;> else:
;>     disabled = wPlayerDisabledMove >> 4
	swap a
	and $f ; get disabled move
	ld b, a
;>     for i in range(NUM_MOVES):
	ld d, NUM_MOVES + 1
	xor a
.handleDisabledMovePPLoop
	dec d
	jr z, .allMovesChecked
;>         if i + 1 != disabled:
	ld c, [hl] ; get move PP
	inc hl
	dec b ; is this the disabled move?
	jr z, .handleDisabledMovePPLoop ; if so, ignore its PP value
;>             left |= mem[wBattleMonPP + i]
	or c
	jr .handleDisabledMovePPLoop
.allMovesChecked
;> if left:
;>     return False
	and a ; any PP left?
	ret nz ; return if a move has PP left
.noMovesLeft
;> PrintText(NoMovesLeftText)
	ld hl, NoMovesLeftText
	call PrintText
;> DelayFrames(60)
	ld c, 60
	call DelayFrames
;> return True
	xor a
	ret

;@ path: engine/battle/core
NoMovesLeftText:
	db TX_FAR
	dw _NoMovesLeftText
	db BANK(_NoMovesLeftText)
	db TX_END

;@ path: engine/battle/core
;@ def SwapMovesInMenu() -> zero
;@ Select in the move list: the first press marks a move, the second swaps it with the one under the cursor -
;@ moves and PP, in battle and in the party, keeping Disable on the same move.
;@ test: skip waits for the player's input
SwapMovesInMenu:
;> if not wMenuItemToSwap:                         # the first press marks the move
;>@mark     wMenuItemToSwap = wCurrentMenuItem
;>@back     return MoveSelectionMenu()
	ld a, [wMenuItemToSwap]
	and a
	jr z, .noMenuItemSelected
;> def swap_bytes(base):                        # .swapBytes: the marked entry and the one under the cursor
;>@x     x = base + wMenuItemToSwap - 1
;>@y     y = base + wCurrentMenuItem - 1
;>@ex     mem[x], mem[y] = mem[y], mem[x]
;> swap_bytes(wBattleMonMoves)
	ld hl, wBattleMonMoves
	call .swapBytes ; swap moves
;> swap_bytes(wBattleMonPP)
	ld hl, wBattleMonPP
	call .swapBytes ; swap move PP
; update the index of the disabled move if necessary
;> disabled = wPlayerDisabledMove >> 4         # Disable stays on the same move
	ld hl, wPlayerDisabledMove
	ld a, [hl]
	swap a
	and $f
	ld b, a
;> if wCurrentMenuItem == disabled:
	ld a, [wCurrentMenuItem]
	cp b
	jr nz, .next
;>     low = wPlayerDisabledMove & 0xF
	ld a, [hl]
	and $f
	ld b, a
;>     wPlayerDisabledMove = (wMenuItemToSwap << 4) + low & 0xFF
	ld a, [wMenuItemToSwap]
	swap a
	add b
	ld [hl], a
	jr .swapMovesInPartyMon
.next
;> elif wMenuItemToSwap == disabled:
	ld a, [wMenuItemToSwap]
	cp b
	jr nz, .swapMovesInPartyMon
;>     low = wPlayerDisabledMove & 0xF
	ld a, [hl]
	and $f
	ld b, a
;>     wPlayerDisabledMove = (wCurrentMenuItem << 4) + low & 0xFF
	ld a, [wCurrentMenuItem]
	swap a
	add b
	ld [hl], a
.swapMovesInPartyMon
;> party = wPartyMon1Moves + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Moves
	ld a, [wPlayerMonNumber]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> swap_bytes(party)                              # the same in the party
	push hl
	call .swapBytes ; swap moves
	pop hl
;> swap_bytes(party + MON_PP - MON_MOVES)
	ld bc, MON_PP - MON_MOVES
	add hl, bc
	call .swapBytes ; swap move PP
;> wMenuItemToSwap = 0
	xor a
	ld [wMenuItemToSwap], a ; deselect the item
;> return MoveSelectionMenu()
	jp MoveSelectionMenu
.swapBytes
;=@x
	push hl
	ld a, [wMenuItemToSwap]
	dec a
	ld c, a
	ld b, 0
	add hl, bc
;=@x
	ld d, h
	ld e, l
;=@y
	pop hl
	ld a, [wCurrentMenuItem]
	dec a
	ld c, a
	ld b, 0
	add hl, bc
;=@ex
	ld a, [de]
	ld b, [hl]
	ld [hl], a
	ld a, b
	ld [de], a
	ret
.noMenuItemSelected
;=@mark
	ld a, [wCurrentMenuItem]
	ld [wMenuItemToSwap], a ; select the current menu item for swapping
;=@back
	jp MoveSelectionMenu

;@ path: engine/battle/core
;@ def PrintMenuItem()
;@ The box beside the battle move list: "TYPE/" with the type and current/max PP of the move under the cursor
;@ (which also becomes wPlayerSelectedMove), or "disabled!".
;@ test: skip draws with the screen transfer paused and waits frames
PrintMenuItem:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> TextBoxBorder(coord(0, 8), 3, 9)
	ld hl, (8) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 3
	ld c, 9
	call TextBoxBorder
;> disabled = wPlayerDisabledMove >> 4               # (zero: no move disabled)
;> if wPlayerDisabledMove:
	ld a, [wPlayerDisabledMove]
	and a
	jr z, .notDisabled
	swap a
	and $f
	ld b, a
;>     if disabled == wCurrentMenuItem:
	ld a, [wCurrentMenuItem]
	cp b
	jr nz, .notDisabled
;>         PlaceString(DisabledText, coord(1, 10))
	ld hl, (10) * SCREEN_WIDTH + (1) + wTileMap
	ld de, DisabledText
	call PlaceString
	jr .moveDisabled
.notDisabled
;> if not wPlayerDisabledMove or disabled != wCurrentMenuItem:
;>     slot = wCurrentMenuItem = wCurrentMenuItem - 1   # the move under the cursor, from 0
	ld hl, wCurrentMenuItem
	dec [hl]
;>     hWhoseTurn = 0
	xor a
	ldh [hWhoseTurn], a
;>     entry = wBattleMonMoves + slot
	ld hl, wBattleMonMoves
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, $0 ; which item in the menu is the cursor pointing to? (0-3)
	add hl, bc ; point to the item (move) in memory
;>     wPlayerSelectedMove = mem[entry]
	ld a, [hl]
	ld [wPlayerSelectedMove], a ; update wPlayerSelectedMove even if the move
	                            ; isn't actually selected (just pointed to by the cursor)
;>     wWhichPokemon = wPlayerMonNumber
	ld a, [wPlayerMonNumber]
	ld [wWhichPokemon], a
;>     wMonDataLocation = BATTLE_MON_DATA
	ld a, BATTLE_MON_DATA
	ld [wMonDataLocation], a
;>     farcall(GetMaxPP)
	ld hl, GetMaxPP
	ld b, BANK(GetMaxPP)
	call Bankswitch
;>     wCurrentMenuItem = slot + 1
	ld hl, wCurrentMenuItem
	ld c, [hl]
	inc [hl]
;>     wBattleMenuCurrentPP = mem[wBattleMonPP + slot] & PP_MASK
	ld b, $0
	ld hl, wBattleMonPP
	add hl, bc
	ld a, [hl]
	and PP_MASK
	ld [wBattleMenuCurrentPP], a
; print TYPE/<type> and <curPP>/<maxPP>
;>     PlaceString(TypeText, coord(1, 9))
	ld hl, (9) * SCREEN_WIDTH + (1) + wTileMap
	ld de, TypeText
	call PlaceString
;>     mem[coord(7, 11)] = charmap('/')[0]
	ld hl, (11) * SCREEN_WIDTH + (7) + wTileMap
	ld [hl], '/'
;>     mem[coord(5, 9)] = charmap('/')[0]
	ld hl, (9) * SCREEN_WIDTH + (5) + wTileMap
	ld [hl], '/'
;>     PrintNumber(addr(wBattleMenuCurrentPP), coord(5, 11), 1, 2)
	ld hl, (11) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wBattleMenuCurrentPP
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
;>     PrintNumber(addr(wMaxPP), coord(8, 11), 1, 2)
	ld hl, (11) * SCREEN_WIDTH + (8) + wTileMap
	ld de, wMaxPP
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
;>     GetCurrentMove()
	call GetCurrentMove
;>     predef(PrintMoveType, hl=coord(2, 10))
	ld hl, (10) * SCREEN_WIDTH + (2) + wTileMap
	ld a, (PrintMoveTypePredef - PredefPointers) / 3
	call Predef
.moveDisabled
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	jp Delay3

;@ path: engine/battle/core
DisabledText:
	db "disabled!@"

;@ path: engine/battle/core
TypeText:
	db "TYPE@"

;@ path: engine/battle/core
;@ def SelectEnemyMove()
;@ The opponent's move for this turn: none while recharging, raging, charging, thrashing, asleep, frozen,
;@ trapping or biding; CANNOT_MOVE when caught in the player's Wrap; Struggle if its only move is disabled; else
;@ a random move (each slot 25%) that exists and isn't disabled - trainers' AI first rules some out. In a link
;@ battle it is what the other Game Boy sent.
;@ test: skip draws random numbers until one fits, which needs the running game's timer
SelectEnemyMove:
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	sub LINK_STATE_BATTLING
	jr nz, .noLinkBattle
; link battle
;>     SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;>     LinkBattleExchangeData()
	call LinkBattleExchangeData
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     received = wSerialExchangeNybbleReceiveData
	ld a, [wSerialExchangeNybbleReceiveData]
;>     if received == LINKBATTLE_STRUGGLE:
;>@lstr         wEnemySelectedMove = STRUGGLE
	cp LINKBATTLE_STRUGGLE
	jp z, .linkedOpponentUsedStruggle
;>     elif received == LINKBATTLE_NO_ACTION:
;>         wEnemySelectedMove = CANNOT_MOVE
	cp LINKBATTLE_NO_ACTION
	jr z, .unableToSelectMove
;>     elif received < 4:
	cp 4
	ret nc
;>         wEnemyMoveListIndex = received
	ld [wEnemyMoveListIndex], a
;>         wEnemySelectedMove = mem[wEnemyMonMoves + received]
	ld c, a
	ld hl, wEnemyMonMoves
	ld b, 0
	add hl, bc
	ld a, [hl]
;>     return                                        # 4 and up: it switched (or ran)
	jr .done
.noLinkBattle
;> if wEnemyBattleStatus2 & (1 << NEEDS_TO_RECHARGE | 1 << USING_RAGE):
;>     return
	ld a, [wEnemyBattleStatus2]
	and (1 << NEEDS_TO_RECHARGE) | (1 << USING_RAGE) ; need to recharge or using rage
	ret nz
;> if wEnemyBattleStatus1 & (1 << CHARGING_UP | 1 << THRASHING_ABOUT | 1 << USING_TRAPPING_MOVE | 1 << STORING_ENERGY):
;>     return
	ld hl, wEnemyBattleStatus1
	ld a, [hl]
	and (1 << CHARGING_UP) | (1 << THRASHING_ABOUT) ; using a charging move or thrash/petal dance
	ret nz
;> if mem[wEnemyMonStatus] & (1 << FRZ | SLP_MASK):
;>     return
	ld a, [wEnemyMonStatus]
	and (1 << FRZ) | SLP_MASK
	ret nz
	ld a, [wEnemyBattleStatus1]
	and (1 << USING_TRAPPING_MOVE) | (1 << STORING_ENERGY) ; using a trapping move like wrap or bide
	ret nz
;> if wPlayerBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	ld a, [wPlayerBattleStatus1]
	bit USING_TRAPPING_MOVE, a ; caught in player's trapping move (e.g. wrap)
	jr z, .canSelectMove
.unableToSelectMove
;>     wEnemySelectedMove = CANNOT_MOVE
;>     return
	ld a, $ff
	jr .done
.canSelectMove
;> if not mem[wEnemyMonMoves + 1] and wEnemyDisabledMove:
	ld hl, wEnemyMonMoves+1 ; 2nd enemy move
	ld a, [hld]
	and a
	jr nz, .atLeastTwoMovesAvailable
	ld a, [wEnemyDisabledMove]
	and a
;>     wEnemySelectedMove = STRUGGLE
;>     return
	ld a, STRUGGLE ; struggle if the only move is disabled
	jr nz, .done
.atLeastTwoMovesAvailable
;> moves = wEnemyMonMoves
;> if wIsInBattle != 1:
	ld a, [wIsInBattle]
	dec a
	jr z, .chooseRandomMove ; wild encounter
;>     moves = farcall(AIEnemyTrainerChooseMoves)            # the moves the AI allows (others are 0)
	ld hl, AIEnemyTrainerChooseMoves
	ld b, BANK(AIEnemyTrainerChooseMoves)
	call Bankswitch
.chooseRandomMove
;> while True:
;>     r = BattleRandom()
	push hl
	call BattleRandom
;>     slot = 1                                      # 25% each
;>     if r >= 25 * 255 // 100:
	ld b, 1 ; 25% chance to select move 1
	cp 25 * $ff / 100
	jr c, .moveChosen
;>         slot = 2
;>         if r >= 50 * 255 // 100:
	inc hl
	inc b ; 25% chance to select move 2
	cp 50 * $ff / 100
	jr c, .moveChosen
;>             slot = 3
;>             if r >= 75 * 255 // 100 - 1:
	inc hl
	inc b ; 25% chance to select move 3
	cp 75 * $ff / 100 - 1
	jr c, .moveChosen
;>                 slot = 4
	inc hl
	inc b ; 25% chance to select move 4
.moveChosen
;>     wEnemyMoveListIndex = slot - 1
	ld a, b
	dec a
	ld [wEnemyMoveListIndex], a
;>     disabled = wEnemyDisabledMove >> 4 == slot
	ld a, [wEnemyDisabledMove]
	swap a
	and $f
	cp b
;>     move = mem[moves + slot - 1]
	ld a, [hl]
	pop hl
;>     if not disabled and move:                     # else: try again
;>         break
	jr z, .chooseRandomMove ; move disabled, try again
	and a
	jr z, .chooseRandomMove ; move non-existent, try again
.done
;> wEnemySelectedMove = move
	ld [wEnemySelectedMove], a
	ret
.linkedOpponentUsedStruggle
;=@lstr
	ld a, STRUGGLE
	jr .done

; this appears to exchange data with the other gameboy during link battles
;@ path: engine/battle/core
;@ def LinkBattleExchangeData()
;@ Swap this turn's action with the other Game Boy: the move slot, LINKBATTLE_STRUGGLE, LINKBATTLE_NO_ACTION,
;@ LINKBATTLE_RUN or 4 + the Pokemon switched to. "Waiting...!" until its answer arrives, then some more
;@ exchanges and zero bytes to stay in step (10 frames each; 26 in the Virtual Console release).
;@ test: skip talks to the link cable
LinkBattleExchangeData:
;> wSerialExchangeNybbleReceiveData = 0xFF
	ld a, $ff
	ld [wSerialExchangeNybbleReceiveData], a
;> if wPlayerMoveListIndex == LINKBATTLE_RUN:
;>     send = LINKBATTLE_RUN
	ld a, [wPlayerMoveListIndex]
	cp LINKBATTLE_RUN ; is the player running from battle?
	jr z, .doExchange
;> elif wActionResultOrTookBattleTurn:
;>     send = wWhichPokemon + 4
	ld a, [wActionResultOrTookBattleTurn]
	and a ; is the player switching in another mon?
	jr nz, .switching
; the player used a move
;> elif wPlayerSelectedMove == STRUGGLE:
;>     send = LINKBATTLE_STRUGGLE
	ld a, [wPlayerSelectedMove]
	cp STRUGGLE
	ld b, LINKBATTLE_STRUGGLE
	jr z, .next
;> elif wPlayerSelectedMove == CANNOT_MOVE:
;>     send = LINKBATTLE_NO_ACTION
	dec b ; LINKBATTLE_NO_ACTION
	ASSERT CANNOT_MOVE == $ff
	inc a
	jr z, .next
;> else:
;>     send = wPlayerMoveListIndex
	ld a, [wPlayerMoveListIndex]
	jr .doExchange
.switching
	ld a, [wWhichPokemon]
	add 4
	ld b, a
.next
	ld a, b
.doExchange
;> wSerialExchangeNybbleSendData = send
	ld [wSerialExchangeNybbleSendData], a
;> farcall(PrintWaitingText)
	ld hl, PrintWaitingText
	ld b, BANK(PrintWaitingText)
	call Bankswitch
.syncLoop1
;> while True:
;>     Serial_ExchangeNybble()
	call Serial_ExchangeNybble
;>     DelayFrame()
	call DelayFrame
;>     if wSerialExchangeNybbleReceiveData != 0xFF:
;>         break
	ld a, [wSerialExchangeNybbleReceiveData]
	inc a
	jr z, .syncLoop1
;> for _ in range(10):
	ld b, 10
.syncLoop2
;>     DelayFrame()
	call DelayFrame
;>     Serial_ExchangeNybble()
	call Serial_ExchangeNybble
	dec b
	jr nz, .syncLoop2
;> for _ in range(10):
	ld b, 10
.syncLoop3
;>     DelayFrame()
	call DelayFrame
;>     Serial_SendZeroByte()
	call Serial_SendZeroByte
	dec b
	jr nz, .syncLoop3
	ret

;@ path: engine/battle/core
;@ def ExecutePlayerMove()
;@ The player's Pokemon takes its turn: unless it can't move or the turn was spent on an item, a switch or an
;@ escape attempt, check ghost fear, status conditions (sleep, freeze, confusion...) and obedience, then run the
;@ selected move through charging, damage, accuracy, animation and effects.
ExecutePlayerMove:
;> hWhoseTurn = 0
	xor a
	ldh [hWhoseTurn], a ; set player's turn
;> if wPlayerSelectedMove == CANNOT_MOVE:
;>     return ExecutePlayerMoveDone()
	ld a, [wPlayerSelectedMove]
	ASSERT CANNOT_MOVE == $ff
	inc a
	jp z, ExecutePlayerMoveDone ; if the player cannot move, skip most of their turn
;> wMoveMissed = 0
	xor a
	ld [wMoveMissed], a
;> wMonIsDisobedient = 0
	ld [wMonIsDisobedient], a
;> wMoveDidntMiss = 0
	ld [wMoveDidntMiss], a
;> wDamageMultipliers = EFFECTIVE
	ld a, EFFECTIVE
	ld [wDamageMultipliers], a
;> if wActionResultOrTookBattleTurn or PrintGhostText():
;>     return ExecutePlayerMoveDone()
	ld a, [wActionResultOrTookBattleTurn]
	and a ; has the player already used the turn (e.g. by using an item, trying to run or switching pokemon)
	jp nz, ExecutePlayerMoveDone
	call PrintGhostText
	jp z, ExecutePlayerMoveDone
;> can_move, continue_at = CheckPlayerStatusConditions()
	call CheckPlayerStatusConditions
;> if not can_move:
;>     return call(continue_at)     # where the status check says the turn goes on (or ends)
	jr nz, .playerHasNoSpecialCondition
	jp hl
.playerHasNoSpecialCondition
;> GetCurrentMove()
	call GetCurrentMove
;> if wPlayerBattleStatus1 >> CHARGING_UP & 1:
;>     return PlayerCanExecuteChargingMove()
	ld hl, wPlayerBattleStatus1
	bit CHARGING_UP, [hl] ; charging up for attack
	jr nz, PlayerCanExecuteChargingMove
;> if not CheckForDisobedience():
;>     return ExecutePlayerMoveDone()
	call CheckForDisobedience
	jp z, ExecutePlayerMoveDone
;> CheckIfPlayerNeedsToChargeUp()                    # (it follows)

;@ path: engine/battle/core
;@ def CheckIfPlayerNeedsToChargeUp()
;@ A two-turn move (Solar Beam, Fly, Dig...) only charges up on its first turn: its effect handles that turn.
CheckIfPlayerNeedsToChargeUp:
;> effect = wPlayerMoveEffect
	ld a, [wPlayerMoveEffect]
;> if effect == CHARGE_EFFECT:
;>     return JumpMoveEffect()
	cp CHARGE_EFFECT
	jp z, JumpMoveEffect
;> if effect == FLY_EFFECT:
;>     return JumpMoveEffect()
	cp FLY_EFFECT
	jp z, JumpMoveEffect
;> PlayerCanExecuteMove()
	jr PlayerCanExecuteMove

; in-battle stuff
;@ path: engine/battle/core
;@ def PlayerCanExecuteChargingMove()
;@ Second turn of a two-turn move: the Pokemon stops charging and is no longer out of reach (Fly, Dig), then
;@ attacks.
PlayerCanExecuteChargingMove:
;> wPlayerBattleStatus1 &= ~(1 << CHARGING_UP | 1 << INVULNERABLE)
;> PlayerCanExecuteMove()
	ld hl, wPlayerBattleStatus1
	res CHARGING_UP, [hl] ; reset charging up and invulnerability statuses if mon was charging up for an attack
	                    ; being fully paralyzed or hurting oneself in confusion removes charging up status
	                    ; resulting in the Pokemon being invulnerable for the whole battle
	res INVULNERABLE, [hl]
;@ path: engine/battle/core
;@ def PlayerCanExecuteMove()
;@ Print "<MON> used <MOVE>!" and take one PP. Moves whose whole job is their effect (status moves, stat
;@ changes...) run it now and stop; continuing effects (Wrap, Thrash) run and then the move deals damage.
PlayerCanExecuteMove:
;> DisplayUsedMoveText()
	call DisplayUsedMoveText
;> farcall(DecrementPP, addr(wPlayerSelectedMove))
	ld hl, DecrementPP
	ld de, wPlayerSelectedMove ; pointer to the move just used
	ld b, BANK(DecrementPP)
	call Bankswitch
;> if IsInArray(wPlayerMoveEffect, ResidualEffects1, 1)[2]:
;>     return JumpMoveEffect()
	ld a, [wPlayerMoveEffect] ; effect of the move just used
	ld hl, ResidualEffects1
	ld de, 1
	call IsInArray
	jp c, JumpMoveEffect ; ResidualEffects1 moves skip damage calculation and accuracy tests
	                    ; unless executed as part of their exclusive effect functions
;> if IsInArray(wPlayerMoveEffect, SpecialEffectsCont, 1)[2]:
;>     JumpMoveEffect()
	ld a, [wPlayerMoveEffect]
	ld hl, SpecialEffectsCont
	ld de, 1
	call IsInArray
	call c, JumpMoveEffect ; execute the effects of SpecialEffectsCont moves (e.g. Wrap, Thrash) but don't skip anything
;> PlayerCalcMoveDamage()                            # (it follows)
;@ path: engine/battle/core
;@ def PlayerCalcMoveDamage()
;@ Work out the damage: critical hit, Counter, the damage formula, type effectiveness and the random factor,
;@ then the accuracy test. Fixed-damage moves (Seismic Toss, Super Fang...) only take the accuracy test; moves
;@ with no power skip both.
PlayerCalcMoveDamage:
;> if not IsInArray(wPlayerMoveEffect, SetDamageEffects, 1)[2]:
	ld a, [wPlayerMoveEffect]
	ld hl, SetDamageEffects
	ld de, 1
	call IsInArray
	jp c, .moveHitTest ; SetDamageEffects moves (e.g. Seismic Toss and Super Fang) skip damage calculation
;>     CriticalHitTest()
	call CriticalHitTest
;>     if HandleCounterMove():
;>         return HandleIfPlayerMoveMissed()
	call HandleCounterMove
	jr z, HandleIfPlayerMoveMissed
;>     GetDamageVarsForPlayerAttack()
	call GetDamageVarsForPlayerAttack
;>     if CalculateDamage():
;>         return PlayerCheckIfFlyOrChargeEffect()
	call CalculateDamage
	jp z, PlayerCheckIfFlyOrChargeEffect ; for moves with 0 BP, skip any further damage calculation and, for now, skip MoveHitTest
	               ; for these moves, accuracy tests will only occur if they are called as part of the effect itself
;>     AdjustDamageForMoveType()
	call AdjustDamageForMoveType
;>     RandomizeDamage()
	call RandomizeDamage
.moveHitTest
;> MoveHitTest()
;> HandleIfPlayerMoveMissed()
	call MoveHitTest
;@ path: engine/battle/core
;@ def HandleIfPlayerMoveMissed()
;@ A move that hit gets its animation. A miss gets none, except Explosion and Selfdestruct, which go off anyway.
HandleIfPlayerMoveMissed:
;> if not wMoveMissed:
;>     GetPlayerAnimationType()
	ld a, [wMoveMissed]
	and a
	jr z, GetPlayerAnimationType
;> elif wPlayerMoveEffect == EXPLODE_EFFECT:
;>     PlayPlayerMoveAnimation(0)
	ld a, [wPlayerMoveEffect]
	sub EXPLODE_EFFECT
	jr z, PlayPlayerMoveAnimation ; don't play any animation if the move missed, unless it was EXPLODE_EFFECT
;> else:
;>     PlayerCheckIfFlyOrChargeEffect()
	jr PlayerCheckIfFlyOrChargeEffect
;@ path: engine/battle/core
;@ def GetPlayerAnimationType()
;@ How the enemy reacts to the hit: its sprite blinks for a plain damaging move, the screen shakes lightly for a
;@ move with an extra effect.
GetPlayerAnimationType:
;> plain = wPlayerMoveEffect == 0                    # nothing but damage
	ld a, [wPlayerMoveEffect]
	and a
;> anim = ANIMATIONTYPE_BLINK_ENEMY_MON_SPRITE
;> if not plain:
	ld a, ANIMATIONTYPE_BLINK_ENEMY_MON_SPRITE ; move has no effect other than dealing damage
	jr z, PlayPlayerMoveAnimation
;>     anim = ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_LIGHT
	ld a, ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_LIGHT ; move has effect
;> PlayPlayerMoveAnimation(anim)                     # (it follows)
;@ path: engine/battle/core
;@ def PlayPlayerMoveAnimation(anim_type: a)
;@ Play the move's animation (the Substitute doll steps aside for it), the explosion shake for Selfdestruct and
;@ Explosion, redraw the player's HUD and go on with the move's effects.
PlayPlayerMoveAnimation:
;> if wPlayerBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>     farcall(HideSubstituteShowMonAnim)
	push af
	ld a, [wPlayerBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a
	ld hl, HideSubstituteShowMonAnim
	ld b, BANK(HideSubstituteShowMonAnim)
	call nz, Bankswitch
;> wAnimationType = anim_type
	pop af
	ld [wAnimationType], a
;> PlayMoveAnimation(wPlayerMoveNum)
	ld a, [wPlayerMoveNum]
	call PlayMoveAnimation
;> HandleExplodingAnimation()
	call HandleExplodingAnimation
;> DrawPlayerHUDAndHPBar()
	call DrawPlayerHUDAndHPBar
;> if wPlayerBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>     farcall(ReshowSubstituteAnim)
	ld a, [wPlayerBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a
	ld hl, ReshowSubstituteAnim
	ld b, BANK(ReshowSubstituteAnim)
	call nz, Bankswitch
;> MirrorMoveCheck()
	jr MirrorMoveCheck
;@ path: engine/battle/core
;@ def PlayerCheckIfFlyOrChargeEffect()
;@ After a miss or a move without power: pause half a second; the first turn of a two-turn move still shows
;@ the status animation.
PlayerCheckIfFlyOrChargeEffect:
;> DelayFrames(30)
	ld c, 30
	call DelayFrames
;> if wPlayerMoveEffect in (FLY_EFFECT, CHARGE_EFFECT):   # the first turn of a two-turn move
	ld a, [wPlayerMoveEffect]
	cp FLY_EFFECT
	jr z, .playAnim
	cp CHARGE_EFFECT
	jr z, .playAnim
;>@type     wAnimationType = 0
;>@anim     PlayMoveAnimation(STATUS_AFFECTED_ANIM)
;> MirrorMoveCheck()                        # (the animation falls through to it)
	jr MirrorMoveCheck
.playAnim
;=@type
	xor a
	ld [wAnimationType], a
;=@anim
	ld a, STATUS_AFFECTED_ANIM
	call PlayMoveAnimation
;@ path: engine/battle/core
;@ def MirrorMoveCheck()
;@ The rest of the player's attack. Mirror Move and Metronome load another move and start over with it. Then
;@ the effect, the miss message or the damage with its "critical hit"/"super effective" texts, side effects,
;@ Rage, the hits of a multi-hit move and finally the move's remaining effect if the target is still standing.
MirrorMoveCheck:
;> if wPlayerMoveEffect == MIRROR_MOVE_EFFECT:
	ld a, [wPlayerMoveEffect]
	cp MIRROR_MOVE_EFFECT
	jr nz, .metronomeCheck
;>     if MirrorMoveCopyMove():
;>         return ExecutePlayerMoveDone()
	call MirrorMoveCopyMove
	jp z, ExecutePlayerMoveDone
;>     wMonIsDisobedient = 0
	xor a
	ld [wMonIsDisobedient], a
;>     return CheckIfPlayerNeedsToChargeUp()
	jp CheckIfPlayerNeedsToChargeUp ; if Mirror Move was successful go back to damage calculation for copied move
.metronomeCheck
;> if wPlayerMoveEffect == METRONOME_EFFECT:
	cp METRONOME_EFFECT
	jr nz, .next
;>     MetronomePickMove()
	call MetronomePickMove
;>     return CheckIfPlayerNeedsToChargeUp()
	jp CheckIfPlayerNeedsToChargeUp ; Go back to damage calculation for the move picked by Metronome
.next
;> if IsInArray(wPlayerMoveEffect, ResidualEffects2, 1)[2]:
;>     return JumpMoveEffect()
	ld a, [wPlayerMoveEffect]
	ld hl, ResidualEffects2
	ld de, 1
	call IsInArray
	jp c, JumpMoveEffect ; done here after executing effects of ResidualEffects2
;> if wMoveMissed:
	ld a, [wMoveMissed]
	and a
	jr z, .moveDidNotMiss
;>     PrintMoveFailureText()
	call PrintMoveFailureText
;>     if wPlayerMoveEffect != EXPLODE_EFFECT:
;>         return ExecutePlayerMoveDone()
	ld a, [wPlayerMoveEffect]
	cp EXPLODE_EFFECT ; even if Explosion or Selfdestruct missed, its effect still needs to be activated
	jr z, .notDone
	jp ExecutePlayerMoveDone ; otherwise, we're done if the move missed
.moveDidNotMiss
;> else:
;>     ApplyAttackToEnemyPokemon()
	call ApplyAttackToEnemyPokemon
;>     PrintCriticalOHKOText()
	call PrintCriticalOHKOText
;>     farcall(DisplayEffectiveness)
	ld hl, DisplayEffectiveness
	ld b, BANK(DisplayEffectiveness)
	call Bankswitch
;>     wMoveDidntMiss = 1
	ld a, 1
	ld [wMoveDidntMiss], a
.notDone
;> if IsInArray(wPlayerMoveEffect, AlwaysHappenSideEffects, 1)[2]:
;>     JumpMoveEffect()
	ld a, [wPlayerMoveEffect]
	ld hl, AlwaysHappenSideEffects
	ld de, 1
	call IsInArray
	call c, JumpMoveEffect ; not done after executing effects of AlwaysHappenSideEffects
;> if not (mem[wEnemyMonHP] | mem[wEnemyMonHP + 1]):
;>     return                        # the enemy fainted
	ld hl, wEnemyMonHP
	ld a, [hli]
	ld b, [hl]
	or b
	ret z ; don't do anything else if the enemy fainted
;> HandleBuildingRage()
	call HandleBuildingRage

;> if wPlayerBattleStatus1 >> ATTACKING_MULTIPLE_TIMES & 1:
	ld hl, wPlayerBattleStatus1
	bit ATTACKING_MULTIPLE_TIMES, [hl]
	jr z, .executeOtherEffects
;>     wPlayerNumAttacksLeft -= 1
	ld a, [wPlayerNumAttacksLeft]
	dec a
	ld [wPlayerNumAttacksLeft], a
;>     if wPlayerNumAttacksLeft:
;>         return GetPlayerAnimationType()  # the next hit of a multi-hit move
	jp nz, GetPlayerAnimationType ; for multi-hit moves, apply attack until PlayerNumAttacksLeft hits 0 or the enemy faints.
	                             ; damage calculation and accuracy tests only happen for the first hit
;>     wPlayerBattleStatus1 &= ~(1 << ATTACKING_MULTIPLE_TIMES)
	res ATTACKING_MULTIPLE_TIMES, [hl] ; clear attacking multiple times status when all attacks are over
;>     PrintText(MultiHitText)
	ld hl, MultiHitText
	call PrintText
;>     wPlayerNumHits = 0
	xor a
	ld [wPlayerNumHits], a
.executeOtherEffects
;> if wPlayerMoveEffect and not IsInArray(wPlayerMoveEffect, SpecialEffects, 1)[2]:
	ld a, [wPlayerMoveEffect]
	and a
	jp z, ExecutePlayerMoveDone
	ld hl, SpecialEffects
	ld de, 1
	call IsInArray
;>     JumpMoveEffect()
	call nc, JumpMoveEffect ; move effects not included in SpecialEffects or in either of the ResidualEffect arrays,
	; which are the effects not covered yet. Rage effect will be executed for a second time (though it's irrelevant).
	; Includes side effects that only need to be called if the target didn't faint.
	; Responsible for executing Twineedle's second side effect (poison).
;> ExecutePlayerMoveDone()
	jp ExecutePlayerMoveDone

;@ path: engine/battle/core
MultiHitText:
	db TX_FAR
	dw _MultiHitText
	db BANK(_MultiHitText)
	db TX_END

;@ path: engine/battle/core
;@ def ExecutePlayerMoveDone() -> b
;@ End of the player's turn: clear the "turn already used" flag. Returns b = 1.
ExecutePlayerMoveDone:
;> wActionResultOrTookBattleTurn = 0
;> return 1
	xor a
	ld [wActionResultOrTookBattleTurn], a
	ld b, 1
	ret

;@ path: engine/battle/core
;@ def PrintGhostText() -> zero
;@ In a ghost battle the player's Pokemon is too scared to move (unless it is asleep or frozen anyway), and the
;@ ghost's turn is just "Get out... Get out...". Zero if the turn is lost to it.
;@ test: wIsInBattle = rand(1, 2); wCurMap = rand(POKEMON_TOWER_1F - 1, POKEMON_TOWER_7F + 1)
PrintGhostText:
; print the ghost battle messages
;> if not IsGhostBattle():
;>     return False
	call IsGhostBattle
	ret nz
;> if hWhoseTurn:                                    # the ghost's turn
;>@go     PrintText(GetOutText)
;>@gr     return True
	ldh a, [hWhoseTurn]
	and a
	jr nz, .Ghost
;> if mem[wBattleMonStatus] & (1 << FRZ | SLP_MASK):
;>     return False
	ld a, [wBattleMonStatus] ; player's turn
	and (1 << FRZ) | SLP_MASK
	ret nz
;> PrintText(ScaredText)
	ld hl, ScaredText
	call PrintText
;> return True
	xor a
	ret
.Ghost ; ghost's turn
;=@go
	ld hl, GetOutText
	call PrintText
;=@gr
	xor a
	ret

;@ path: engine/battle/core
ScaredText:
	db TX_FAR
	dw _ScaredText
	db BANK(_ScaredText)
	db TX_END

;@ path: engine/battle/core
GetOutText:
	db TX_FAR
	dw _GetOutText
	db BANK(_GetOutText)
	db TX_END

;@ path: engine/battle/core
;@ def IsGhostBattle() -> zero
;@ A wild battle on floors 1-7 of the Pokemon Tower without the Silph Scope in the bag: the opponent appears as
;@ an unidentifiable ghost (zero set).
IsGhostBattle:
;> if wIsInBattle != 1:
;>     return False
	ld a, [wIsInBattle]
	dec a
	ret nz
;> if POKEMON_TOWER_1F <= wCurMap <= POKEMON_TOWER_7F:
	ld a, [wCurMap]
	cp POKEMON_TOWER_1F
	jr c, .next
	cp POKEMON_TOWER_7F + 1
	jr nc, .next
;>     if IsItemInBag(SILPH_SCOPE):                  # (True: the Silph Scope is not in the bag)
;>         return True
	ld b, SILPH_SCOPE
	call IsItemInBag
	ret z
.next
;> return False
	ld a, 1
	and a
	ret

; checks for various status conditions affecting the player mon
; stores whether the mon cannot use a move this turn in Z flag
;@ path: engine/battle/core
;@ def CheckPlayerStatusConditions() -> (zero, hl)
;@ Before the player's Pokemon moves: sleep, freeze, being trapped, flinching, recharging, Disable running out,
;@ confusion, a disabled move, full paralysis, and the turns of Bide, Thrash, Wrap-like moves and Rage.
;@ Zero if the turn does not go on normally; hl is then where it continues (often ExecutePlayerMoveDone).
CheckPlayerStatusConditions:
;> if mem[wBattleMonStatus] & SLP_MASK:
	ld hl, wBattleMonStatus
	ld a, [hl]
	and SLP_MASK
	jr z, .FrozenCheck
; sleeping
;>     mem[wBattleMonStatus] = (mem[wBattleMonStatus] & SLP_MASK) - 1
	dec a
	ld [wBattleMonStatus], a ; decrement number of turns left
;>     if mem[wBattleMonStatus]:
	and a
	jr z, .WakeUp ; if the number of turns hit 0, wake up
; fast asleep
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         PlayMoveAnimation(SLP_PLAYER_ANIM)
	ld a, SLP_PLAYER_ANIM
	call PlayMoveAnimation
;>         PrintText(FastAsleepText)
	ld hl, FastAsleepText
	call PrintText
	jr .sleepDone
.WakeUp
;>     else:
;>         PrintText(WokeUpText)
	ld hl, WokeUpText
	call PrintText
.sleepDone
;>     wPlayerUsedMove = 0
	xor a
	ld [wPlayerUsedMove], a
;>     return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone ; player can't move this turn
	jp .returnToHL

.FrozenCheck
;> if mem[wBattleMonStatus] >> FRZ & 1:
	bit FRZ, [hl] ; frozen?
	jr z, .HeldInPlaceCheck
;>     PrintText(IsFrozenText)
	ld hl, IsFrozenText
	call PrintText
;>     wPlayerUsedMove = 0
	xor a
	ld [wPlayerUsedMove], a
;>     return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone ; player can't move this turn
	jp .returnToHL

.HeldInPlaceCheck
;> if wEnemyBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	ld a, [wEnemyBattleStatus1]
	bit USING_TRAPPING_MOVE, a ; is enemy using a multi-turn move like wrap?
	jp z, .FlinchedCheck
;>     PrintText(CantMoveText)
	ld hl, CantMoveText
	call PrintText
;>     return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone ; player can't move this turn
	jp .returnToHL

.FlinchedCheck
;> if wPlayerBattleStatus1 >> FLINCHED & 1:
	ld hl, wPlayerBattleStatus1
	bit FLINCHED, [hl]
	jp z, .HyperBeamCheck
;>     wPlayerBattleStatus1 &= ~(1 << FLINCHED)
	res FLINCHED, [hl] ; reset player's flinch status
;>     PrintText(FlinchedText)
	ld hl, FlinchedText
	call PrintText
;>     return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone ; player can't move this turn
	jp .returnToHL

.HyperBeamCheck
;> if wPlayerBattleStatus2 >> NEEDS_TO_RECHARGE & 1:
	ld hl, wPlayerBattleStatus2
	bit NEEDS_TO_RECHARGE, [hl]
	jr z, .AnyMoveDisabledCheck
;>     wPlayerBattleStatus2 &= ~(1 << NEEDS_TO_RECHARGE)
	res NEEDS_TO_RECHARGE, [hl] ; reset player's recharge status
;>     PrintText(MustRechargeText)
	ld hl, MustRechargeText
	call PrintText
;>     return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone ; player can't move this turn
	jp .returnToHL

.AnyMoveDisabledCheck
;> if wPlayerDisabledMove:
	ld hl, wPlayerDisabledMove
	ld a, [hl]
	and a
	jr z, .ConfusedCheck
;>     wPlayerDisabledMove -= 1
	dec a
	ld [hl], a
;>     if not wPlayerDisabledMove & 0xF:       # Disable wore off
	and $f ; did Disable counter hit 0?
	jr nz, .ConfusedCheck
;>         wPlayerDisabledMove = 0
	ld [hl], a
;>         wPlayerDisabledMoveNumber = 0
	ld [wPlayerDisabledMoveNumber], a
;>         PrintText(DisabledNoMoreText)
	ld hl, DisabledNoMoreText
	call PrintText

.ConfusedCheck
;> lost_turn = False
;> if wPlayerBattleStatus1 >> CONFUSED & 1:
	ld a, [wPlayerBattleStatus1]
	add a ; is player confused?
	jr nc, .TriedToUseDisabledMoveCheck
;>     wPlayerConfusedCounter -= 1
	ld hl, wPlayerConfusedCounter
	dec [hl]
;>     if not wPlayerConfusedCounter:
	jr nz, .IsConfused
;>         wPlayerBattleStatus1 &= ~(1 << CONFUSED)
	ld hl, wPlayerBattleStatus1
	res CONFUSED, [hl] ; if confused counter hit 0, reset confusion status
;>         PrintText(ConfusedNoMoreText)
	ld hl, ConfusedNoMoreText
	call PrintText
	jr .TriedToUseDisabledMoveCheck
.IsConfused
;>     else:
;>         PrintText(IsConfusedText)
	ld hl, IsConfusedText
	call PrintText
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         PlayMoveAnimation(CONF_PLAYER_ANIM)
	ld a, CONF_PLAYER_ANIM
	call PlayMoveAnimation
;>         if BattleRandom() >= 128:           # half the time it hurts itself
	call BattleRandom
	cp 50 * $ff / 100 + 1 ; chance to hurt itself
	jr c, .TriedToUseDisabledMoveCheck
;>             wPlayerBattleStatus1 &= 1 << CONFUSED
	ld hl, wPlayerBattleStatus1
	ld a, [hl]
	and 1 << CONFUSED ; if mon hurts itself, clear every other status from wPlayerBattleStatus1
	ld [hl], a
;>             HandleSelfConfusionDamage()
	call HandleSelfConfusionDamage
;>             lost_turn = True
	jr .MonHurtItselfOrFullyParalysed

.TriedToUseDisabledMoveCheck
; prevents a disabled move that was selected before being disabled from being used
;> if not lost_turn:
;>     if wPlayerDisabledMoveNumber and wPlayerDisabledMoveNumber == wPlayerSelectedMove:
	ld a, [wPlayerDisabledMoveNumber]
	and a
	jr z, .ParalysisCheck
	ld hl, wPlayerSelectedMove
	cp [hl]
	jr nz, .ParalysisCheck
;>         PrintMoveIsDisabledText()
	call PrintMoveIsDisabledText
;>         return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone ; if a disabled move was somehow selected, player can't move this turn
	jp .returnToHL

.ParalysisCheck
;>     if mem[wBattleMonStatus] >> PAR & 1 and BattleRandom() < 63:   # 25%: fully paralyzed
	ld hl, wBattleMonStatus
	bit PAR, [hl]
	jr z, .BideCheck
	call BattleRandom
	cp 25 * $ff / 100 ; chance to be fully paralyzed
	jr nc, .BideCheck
;>         PrintText(FullyParalyzedText)
;>         lost_turn = True
	ld hl, FullyParalyzedText
	call PrintText

.MonHurtItselfOrFullyParalysed
;> if lost_turn:
;>     wPlayerBattleStatus1 &= ~(1 << STORING_ENERGY | 1 << THRASHING_ABOUT | 1 << CHARGING_UP | 1 << USING_TRAPPING_MOVE)
	ld hl, wPlayerBattleStatus1
	ld a, [hl]
	; clear bide, thrashing, charging up, and trapping moves such as warp (already cleared for confusion damage)
	and ~((1 << STORING_ENERGY) | (1 << THRASHING_ABOUT) | (1 << CHARGING_UP) | (1 << USING_TRAPPING_MOVE))
	ld [hl], a
;>     if wPlayerMoveEffect in (FLY_EFFECT, CHARGE_EFFECT):
	ld a, [wPlayerMoveEffect]
	cp FLY_EFFECT
	jr z, .FlyOrChargeEffect
	cp CHARGE_EFFECT
	jr z, .FlyOrChargeEffect
	jr .NotFlyOrChargeEffect

.FlyOrChargeEffect
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         PlayMoveAnimation(STATUS_AFFECTED_ANIM)
	ld a, STATUS_AFFECTED_ANIM
	call PlayMoveAnimation
.NotFlyOrChargeEffect
;>     return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone
	jp .returnToHL ; if using a two-turn move, we need to recharge the first turn

.BideCheck
;> if wPlayerBattleStatus1 >> STORING_ENERGY & 1:              # Bide
	ld hl, wPlayerBattleStatus1
	bit STORING_ENERGY, [hl] ; is mon using bide?
	jr z, .ThrashingAboutCheck
;>     wPlayerMoveNum = 0
	xor a
	ld [wPlayerMoveNum], a
;>     damage = wDamage[0] << 8 | wDamage[1]
	ld hl, wDamage
	ld a, [hli]
	ld b, a
	ld c, [hl]
;>     stored = (wPlayerBideAccumulatedDamage[0] << 8 | wPlayerBideAccumulatedDamage[1]) + damage
;>     wPlayerBideAccumulatedDamage[1] = stored & 0xFF
	ld hl, wPlayerBideAccumulatedDamage + 1
	ld a, [hl]
	add c ; accumulate damage taken
	ld [hld], a
;>     wPlayerBideAccumulatedDamage[0] = stored >> 8 & 0xFF
	ld a, [hl]
	adc b
	ld [hl], a
;>     wPlayerNumAttacksLeft -= 1
	ld hl, wPlayerNumAttacksLeft
	dec [hl] ; did Bide counter hit 0?
;>     if wPlayerNumAttacksLeft:
	jr z, .UnleashEnergy
;>         return True, addr(ExecutePlayerMoveDone)
	ld hl, ExecutePlayerMoveDone
	jp .returnToHL ; unless mon unleashes energy, can't move this turn
.UnleashEnergy
;>     wPlayerBattleStatus1 &= ~(1 << STORING_ENERGY)
	ld hl, wPlayerBattleStatus1
	res STORING_ENERGY, [hl] ; not using bide any more
;>     PrintText(UnleashedEnergyText)
	ld hl, UnleashedEnergyText
	call PrintText
;>     wPlayerMovePower = 1
	ld a, 1
	ld [wPlayerMovePower], a
;>     damage = stored * 2 & 0xFFFF                  # twice the damage taken
	ld hl, wPlayerBideAccumulatedDamage + 1
	ld a, [hld]
	add a
	ld b, a
;>     wDamage[1] = damage & 0xFF
	ld [wDamage + 1], a
;>     wDamage[0] = damage >> 8
	ld a, [hl]
	rl a ; double the damage
	ld [wDamage], a
;>     if not damage:
	or b
	jr nz, .next
;>         wMoveMissed = 1
	ld a, 1
	ld [wMoveMissed], a
.next
;>     wPlayerBideAccumulatedDamage[0] = 0
;>     wPlayerBideAccumulatedDamage[1] = 0
	xor a
	ld [hli], a
	ld [hl], a
;>     wPlayerMoveNum = BIDE
	ld a, BIDE
	ld [wPlayerMoveNum], a
;>     return True, addr(HandleIfPlayerMoveMissed)
	ld hl, HandleIfPlayerMoveMissed ; skip damage calculation, DecrementPP and MoveHitTest
	jp .returnToHL

.ThrashingAboutCheck
;> if wPlayerBattleStatus1 >> THRASHING_ABOUT & 1:             # Thrash, Petal Dance
	bit THRASHING_ABOUT, [hl] ; is mon using thrash or petal dance?
	jr z, .MultiturnMoveCheck
;>     wPlayerMoveNum = THRASH
	ld a, THRASH
	ld [wPlayerMoveNum], a
;>     PrintText(ThrashingAboutText)
	ld hl, ThrashingAboutText
	call PrintText
;>     wPlayerNumAttacksLeft -= 1
	ld hl, wPlayerNumAttacksLeft
	dec [hl] ; did Thrashing About counter hit 0?
;>     if not wPlayerNumAttacksLeft:                           # done: now it is confused for 2-5 turns
	ld hl, PlayerCalcMoveDamage ; skip DecrementPP
	jp nz, .returnToHL
;>         wPlayerBattleStatus1 = wPlayerBattleStatus1 & ~(1 << THRASHING_ABOUT) | 1 << CONFUSED
	push hl
	ld hl, wPlayerBattleStatus1
	res THRASHING_ABOUT, [hl] ; no longer thrashing about
	set CONFUSED, [hl] ; confused
;>         wPlayerConfusedCounter = (BattleRandom() & 3) + 2
	call BattleRandom
	and 3
	inc a
	inc a ; confused for 2-5 turns
	ld [wPlayerConfusedCounter], a
;>     return True, addr(PlayerCalcMoveDamage)
	pop hl ; skip DecrementPP
	jp .returnToHL

.MultiturnMoveCheck
;> if wPlayerBattleStatus1 >> USING_TRAPPING_MOVE & 1:         # Wrap, Bind...: the same damage again
	bit USING_TRAPPING_MOVE, [hl] ; is mon using multi-turn move?
	jp z, .RageCheck
;>     PrintText(AttackContinuesText)
	ld hl, AttackContinuesText
	call PrintText
;>     wPlayerNumAttacksLeft -= 1
	ld a, [wPlayerNumAttacksLeft]
	dec a
	ld [wPlayerNumAttacksLeft], a
;>     return True, addr(GetPlayerAnimationType)
	ld hl, GetPlayerAnimationType ; skip damage calculation (deal damage equal to last hit),
	                              ; DecrementPP and MoveHitTest
	jp nz, .returnToHL  ; redundant leftover code, the case wPlayerNumAttacksLeft == 0
						; is handled within CheckNumAttacksLeft
	jp .returnToHL

.RageCheck
;> if wPlayerBattleStatus2 >> USING_RAGE & 1:
	ld a, [wPlayerBattleStatus2]
	bit USING_RAGE, a ; is mon using rage?
	jp z, .checkPlayerStatusConditionsDone ; if we made it this far, mon can move normally this turn
;>     wNamedObjectIndex = RAGE
	ld a, RAGE
	ld [wNamedObjectIndex], a
;>     CopyToStringBuffer(GetMoveName())
	call GetMoveName
	call CopyToStringBuffer
;>     wPlayerMoveEffect = 0
	xor a
	ld [wPlayerMoveEffect], a
;>     return True, addr(PlayerCanExecuteMove)
	ld hl, PlayerCanExecuteMove
	jp .returnToHL

.returnToHL
	xor a
	ret

.checkPlayerStatusConditionsDone
;> return False, addr(wPlayerBattleStatus1)                  # (hl is not used then)
	ld a, $1
	and a
	ret

