;@ path: engine/battle/core
;@ def PrintMoveIsDisabledText()
;@ "<MON>'s <MOVE> is disabled!" - also ends the attacker's charging up.
;@ test: hLoadedROMBank = 0x0F; wPlayerSelectedMove = rand(1, NUM_ATTACKS); wEnemySelectedMove = rand(1, NUM_ATTACKS)
PrintMoveIsDisabledText:
;> if hWhoseTurn:
	ld hl, wPlayerSelectedMove
	ld de, wPlayerBattleStatus1
	ldh a, [hWhoseTurn]
	and a
	jr z, .removeChargingUp
;>     wEnemyBattleStatus1 &= ~(1 << CHARGING_UP)
;>     wNamedObjectIndex = wEnemySelectedMove
	inc hl
	ld de, wEnemyBattleStatus1
.removeChargingUp
;> else:
;>     wPlayerBattleStatus1 &= ~(1 << CHARGING_UP)
	ld a, [de]
	res CHARGING_UP, a ; end the pokemon's
	ld [de], a
;>     wNamedObjectIndex = wPlayerSelectedMove
	ld a, [hl]
	ld [wNamedObjectIndex], a
;> GetMoveName()
	call GetMoveName
;> PrintText(MoveIsDisabledText)
	ld hl, MoveIsDisabledText
	jp PrintText

;@ path: engine/battle/core
MoveIsDisabledText:
	db TX_FAR
	dw _MoveIsDisabledText
	db BANK(_MoveIsDisabledText)
	db TX_END

;@ path: engine/battle/core
;@ def HandleSelfConfusionDamage()
;@ "It hurt itself in its confusion!": a typeless 40-power hit of the Pokemon on itself (its own Defense in
;@ place of the enemy's, never critical, always hits), shown with the Pound animation.
HandleSelfConfusionDamage:
;> PrintText(HurtItselfText)
	ld hl, HurtItselfText
	call PrintText
;> saved_defense = mem[wEnemyMonDefense], mem[wEnemyMonDefense + 1]
	ld hl, wEnemyMonDefense
	ld a, [hli]
	push af
	ld a, [hld]
	push af
;> mem[wEnemyMonDefense] = mem[wBattleMonDefense]
	ld a, [wBattleMonDefense]
	ld [hli], a
;> mem[wEnemyMonDefense + 1] = mem[wBattleMonDefense + 1]
	ld a, [wBattleMonDefense + 1]
	ld [hl], a
;> saved_effect = wPlayerMoveEffect
	ld hl, wPlayerMoveEffect
	push hl
	ld a, [hl]
	push af
;> wPlayerMoveEffect = 0
	xor a
	ld [hli], a
;> wCriticalHitOrOHKO = 0
	ld [wCriticalHitOrOHKO], a ; self-inflicted confusion damage can't be a Critical Hit
;> wPlayerMovePower = 40
	ld a, 40 ; 40 base power
	ld [hli], a
;> wPlayerMoveType = 0
	xor a
	ld [hl], a
;> GetDamageVarsForPlayerAttack()
	call GetDamageVarsForPlayerAttack
;> CalculateDamage()
	call CalculateDamage ; ignores AdjustDamageForMoveType (type-less damage), RandomizeDamage,
	                     ; and MoveHitTest (always hits)
;> wPlayerMoveEffect = saved_effect
	pop af
	pop hl
	ld [hl], a
;> mem[wEnemyMonDefense], mem[wEnemyMonDefense + 1] = saved_defense
	ld hl, wEnemyMonDefense + 1
	pop af
	ld [hld], a
	pop af
	ld [hl], a
;> wAnimationType = 0
	xor a
	ld [wAnimationType], a
;> hWhoseTurn = 1
	inc a
	ldh [hWhoseTurn], a
;> PlayMoveAnimation(POUND)
	call PlayMoveAnimation
;> DrawPlayerHUDAndHPBar()
	call DrawPlayerHUDAndHPBar
;> hWhoseTurn = 0
	xor a
	ldh [hWhoseTurn], a
;> ApplyDamageToPlayerPokemon()
	jp ApplyDamageToPlayerPokemon

;@ path: engine/battle/core
;@ def DisplayUsedMoveText()
;@ Print "<MON> used <MOVE>!".
DisplayUsedMoveText:
;> PrintText(UsedMoveText)
	ld hl, UsedMoveText
	jp PrintText

;@ path: engine/battle/core
;@ def UsedMoveText() -> hl
;@ "<MON>" ... then "used <MOVE>!": remembers the move as the attacker's last used one (for Mirror Move) and
;@ looks up its grammar group.
;@ test: skip a text script: the code after text_asm runs from the text engine
UsedMoveText:
	db TX_FAR
	dw _ActorNameText
	db BANK(_ActorNameText)
	db TX_START_ASM

;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	ld a, [wPlayerMoveNum]
	ld hl, wPlayerUsedMove
	jr z, .playerTurn

;>     wEnemyUsedMove = wEnemyMoveNum
;>     wMoveGrammar = wEnemyMoveNum
	ld a, [wEnemyMoveNum]
	ld hl, wEnemyUsedMove

.playerTurn
;> else:
;>     wPlayerUsedMove = wPlayerMoveNum
	ld [hl], a
;>     wMoveGrammar = wPlayerMoveNum
	ld [wMoveGrammar], a
;> GetMoveGrammar()
	call GetMoveGrammar
;> if wMonIsDisobedient:
;>     return UsedMove2Text
	ld a, [wMonIsDisobedient]
	and a
	ld hl, UsedMove2Text
	ret nz

	; check move grammar
;> if wMoveGrammar < 3:
;>     return UsedMove2Text
	ld a, [wMoveGrammar]
	cp $3
	ld hl, UsedMove2Text
	ret c
;> return UsedMove1Text
	ld hl, UsedMove1Text
	ret

;@ path: engine/battle/core
;@ def UsedMove1Text() -> hl
;@ "used" and then the move name (or "instead," first for a disobedient Pokemon).
;@ test: skip a text script: the code after text_asm runs from the text engine
UsedMove1Text:
	db TX_FAR
	dw _UsedMove1Text
	db BANK(_UsedMove1Text)
	db TX_START_ASM
;> return UsedMoveText_CheckObedience()
	jr UsedMoveText_CheckObedience

;@ path: engine/battle/core
UsedMove2Text:
	db TX_FAR
	dw _UsedMove2Text
	db BANK(_UsedMove2Text)
	db TX_START_ASM
	; fall through

;@ path: engine/battle/core
;@ def UsedMoveText_CheckObedience() -> hl
;@ The next text piece: "instead," when the Pokemon disobeyed and used another move, else the move name.
UsedMoveText_CheckObedience:
;> if wMonIsDisobedient:
; check obedience
	ld a, [wMonIsDisobedient]
	and a
	jr z, .GetMoveNameText
;>     return addr(UsedMoveText_CheckObedience) + 10   # its local text right after this code: "instead,"
; print "instead,"
	ld hl, .UsedInsteadText
	ret

.UsedInsteadText:
	db TX_FAR
	dw _UsedInsteadText
	db BANK(_UsedInsteadText)
	db TX_START_ASM
	; fall through

.GetMoveNameText:
;> return addr(MoveNameText)
	ld hl, MoveNameText
	ret

;@ path: engine/battle/core
;@ def MoveNameText() -> hl
;@ "<MOVE>" and the ending of its grammar group (in English all five end in "!").
;@ test: skip a text script: the code after text_asm runs from the text engine
MoveNameText:
	db TX_FAR
	dw _MoveNameText
	db BANK(_MoveNameText)
	db TX_START_ASM
;> texts = (EndUsedMove1Text, EndUsedMove2Text, EndUsedMove3Text, EndUsedMove4Text, EndUsedMove5Text)
	ld hl, .endusedmovetexts
;> i = wMoveGrammar                                  # (doubled: two bytes an entry)
	ld a, [wMoveGrammar]
	add a
;> text = texts[i]
	push bc
	ld b, $0
	ld c, a
	add hl, bc
	pop bc
;> return text
	ld a, [hli]
	ld h, [hl]
	ld l, a
	ret

.endusedmovetexts:
; entries correspond to MoveGrammar sets
	dw EndUsedMove1Text
	dw EndUsedMove2Text
	dw EndUsedMove3Text
	dw EndUsedMove4Text
	dw EndUsedMove5Text

;@ path: engine/battle/core
EndUsedMove1Text:
	db TX_FAR
	dw _EndUsedMove1Text
	db BANK(_EndUsedMove1Text)
	db TX_END

;@ path: engine/battle/core
EndUsedMove2Text:
	db TX_FAR
	dw _EndUsedMove2Text
	db BANK(_EndUsedMove2Text)
	db TX_END

;@ path: engine/battle/core
EndUsedMove3Text:
	db TX_FAR
	dw _EndUsedMove3Text
	db BANK(_EndUsedMove3Text)
	db TX_END

;@ path: engine/battle/core
EndUsedMove4Text:
	db TX_FAR
	dw _EndUsedMove4Text
	db BANK(_EndUsedMove4Text)
	db TX_END

;@ path: engine/battle/core
EndUsedMove5Text:
	db TX_FAR
	dw _EndUsedMove5Text
	db BANK(_EndUsedMove5Text)
	db TX_END

; This function is redundant in the English localization.
; In Japanese, it selects one of 5 distinct sentence structures.
; In English, all of these sentences have the exact same structure,
; so this serves no purpose.
;@ path: engine/battle/core
;@ def GetMoveGrammar()
;@ Replace the move in wMoveGrammar with its grammar group (0-4) from MoveGrammar, a list of groups each ended
;@ by 0. The Japanese version words "used <MOVE>" differently per group; in English all are the same.
;@ test: wMoveGrammar = rand(0, NUM_ATTACKS)
GetMoveGrammar:
;> group = 0
	push bc
	ld a, [wMoveGrammar] ; move ID
	ld c, a
	ld b, $0
;> p = MoveGrammar
	ld hl, MoveGrammar
.loop
;> while True:
;>     move = mem[p]; p += 1
	ld a, [hli]
;>     if move == 0xFF or move == wMoveGrammar:
;>         break
; end of table?
	cp -1
	jr z, .end
; match?
	cp c
	jr z, .end
; advance grammar type at 0
;>     if move == 0:
	and a
	jr nz, .loop
; next grammar type
;>         group += 1
	inc b
	jr .loop

.end
; wMoveGrammar now contains move grammar
;> wMoveGrammar = group
	ld a, b
	ld [wMoveGrammar], a
	pop bc
	ret

; Used by GetMoveGrammar (see engine/battle/core.asm)
; Each move is given an identifier for what usedmovetext to use (0-4).
; Made redundant in English localization, where all are just "[mon]<LINE>used [move]!"

;@ path: engine/battle/core
MoveGrammar:
; 0: originally "[mon]は<LINE>[move]を　つかった！" ("[mon]<LINE>used [move]!")
	db SWORDS_DANCE
	db GROWTH
	db 0 ; end set

; 1: originally "[mon]は<LINE>[move]を　した！" ("[mon]<LINE>did [move]!")
	db RECOVER
	db BIDE
	db SELFDESTRUCT
	db AMNESIA
	db 0 ; end set

; 2: originally "[mon]は<LINE>[move]した！" ("[mon]<LINE>did [move]!")
	db MEDITATE
	db AGILITY
	db TELEPORT
	db MIMIC
	db DOUBLE_TEAM
	db BARRAGE
	db 0 ; end set

; 3: originally "[mon]の<LINE>[move]　こうげき！" ("[mon]'s<LINE>[move] attack!")
	db POUND
	db SCRATCH
	db VICEGRIP
	db WING_ATTACK
	db FLY
	db BIND
	db SLAM
	db HORN_ATTACK
	db BODY_SLAM
	db WRAP
	db THRASH
	db TAIL_WHIP
	db LEER
	db BITE
	db GROWL
	db ROAR
	db SING
	db PECK
	db COUNTER
	db STRENGTH
	db ABSORB
	db STRING_SHOT
	db EARTHQUAKE
	db FISSURE
	db DIG
	db TOXIC
	db SCREECH
	db HARDEN
	db MINIMIZE
	db WITHDRAW
	db DEFENSE_CURL
	db METRONOME
	db LICK
	db CLAMP
	db CONSTRICT
	db POISON_GAS
	db LEECH_LIFE
	db BUBBLE
	db FLASH
	db SPLASH
	db ACID_ARMOR
	db FURY_SWIPES
	db REST
	db SHARPEN
	db SLASH
	db SUBSTITUTE
	db 0 ; end set

; 4: originally "[mon]の<LINE>[move]!" ("[mon]'s<LINE>[move]!")
; Any move not listed above uses this grammar.
	db -1 ; end

;@ path: engine/battle/core
;@ def PrintMoveFailureText()
;@ Why the attack failed: "It doesn't affect <MON>!", "<MON> is unaffected!" (a failed one-hit KO) or "<MON>'s
;@ attack missed!". A missed Jump Kick or Hi Jump Kick hurts the user: 1/8 of wDamage, which is always 0 after a
;@ miss, so the crash damage is always 1.
PrintMoveFailureText:
;> effect = wEnemyMoveEffect if hWhoseTurn else wPlayerMoveEffect
	ld de, wPlayerMoveEffect
	ldh a, [hWhoseTurn]
	and a
	jr z, .playersTurn
	ld de, wEnemyMoveEffect
.playersTurn
;> if not wDamageMultipliers & EFFECTIVENESS_MASK:
;>     text = DoesntAffectMonText
	ld hl, DoesntAffectMonText
	ld a, [wDamageMultipliers]
	and EFFECTIVENESS_MASK
	jr z, .gotTextToPrint
;> else:
;>     text = AttackMissedText
	ld hl, AttackMissedText
;>     if wCriticalHitOrOHKO == 0xFF:                # a failed one-hit KO
	ld a, [wCriticalHitOrOHKO]
	cp $ff
	jr nz, .gotTextToPrint
;>         text = UnaffectedText
	ld hl, UnaffectedText
.gotTextToPrint
;> PrintText(text)
	push de
	call PrintText
;> wCriticalHitOrOHKO = 0
	xor a
	ld [wCriticalHitOrOHKO], a
;> if effect != JUMP_KICK_EFFECT:
;>     return
	pop de
	ld a, [de]
	cp JUMP_KICK_EFFECT
	ret nz

	; if you get here, the mon used jump kick or hi jump kick and missed
;> damage = wDamage[0] << 8 | wDamage[1]             # always 0 after a miss: the crash does 1
	ld hl, wDamage ; since the move missed, wDamage will always contain 0 at this point.
	                ; Thus, recoil damage will always be equal to 1
	                ; even if it was intended to be potential damage/8.
	ld a, [hli]
	ld b, [hl]
;> damage >>= 3
	srl a
	rr b
	srl a
	rr b
	srl a
	rr b
;> wDamage[0], wDamage[1] = damage >> 8, damage & 0xFF
	ld [hl], b
	dec hl
	ld [hli], a
;> if not damage:
	or b
	jr nz, .applyRecoil
;>     damage = 1
;>     wDamage[1] = 1
	inc a
	ld [hl], a
.applyRecoil
;> PrintText(KeptGoingAndCrashedText)
	ld hl, KeptGoingAndCrashedText
	call PrintText
;> predef(PredefShakeScreenHorizontally, bc=4 << 8)
	ld b, $4
	ld a, (PredefShakeScreenHorizontallyPredef - PredefPointers) / 3
	call Predef
;> if hWhoseTurn:
;>     ApplyDamageToEnemyPokemon()
	ldh a, [hWhoseTurn]
	and a
	jr nz, .enemyTurn
;> else:
;>     ApplyDamageToPlayerPokemon()
	jp ApplyDamageToPlayerPokemon
.enemyTurn
	jp ApplyDamageToEnemyPokemon

;@ path: engine/battle/core
AttackMissedText:
	db TX_FAR
	dw _AttackMissedText
	db BANK(_AttackMissedText)
	db TX_END

;@ path: engine/battle/core
KeptGoingAndCrashedText:
	db TX_FAR
	dw _KeptGoingAndCrashedText
	db BANK(_KeptGoingAndCrashedText)
	db TX_END

;@ path: engine/battle/core
UnaffectedText:
	db TX_FAR
	dw _UnaffectedText
	db BANK(_UnaffectedText)
	db TX_END

;@ path: engine/battle/core
;@ def PrintDoesntAffectText()
;@ Print "It doesn't affect <MON>!".
PrintDoesntAffectText:
;> PrintText(DoesntAffectMonText)
	ld hl, DoesntAffectMonText
	jp PrintText

;@ path: engine/battle/core
DoesntAffectMonText:
	db TX_FAR
	dw _DoesntAffectMonText
	db BANK(_DoesntAffectMonText)
	db TX_END

; if there was a critical hit or an OHKO was successful, print the corresponding text
;@ path: engine/battle/core
;@ def PrintCriticalOHKOText()
;@ "Critical hit!" or "One-hit KO!" if the attack was one, then a third of a second's pause.
PrintCriticalOHKOText:
;> if wCriticalHitOrOHKO:
	ld a, [wCriticalHitOrOHKO]
	and a
	jr z, .done ; do nothing if there was no critical hit or successful OHKO
;>     entry = CriticalOHKOTextPointers + (wCriticalHitOrOHKO - 1) * 2 % 256
	dec a
	add a
	ld hl, CriticalOHKOTextPointers
	ld b, $0
	ld c, a
	add hl, bc
;>     text = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     PrintText(text)
	call PrintText
;>     wCriticalHitOrOHKO = 0
	xor a
	ld [wCriticalHitOrOHKO], a
.done
;> DelayFrames(20)
	ld c, 20
	jp DelayFrames

;@ path: engine/battle/core
CriticalOHKOTextPointers:
	dw CriticalHitText
	dw OHKOText

;@ path: engine/battle/core
CriticalHitText:
	db TX_FAR
	dw _CriticalHitText
	db BANK(_CriticalHitText)
	db TX_END

;@ path: engine/battle/core
OHKOText:
	db TX_FAR
	dw _OHKOText
	db BANK(_OHKOText)
	db TX_END

; checks if a traded mon will disobey due to lack of badges
; stores whether the mon will use a move in Z flag
;@ path: engine/battle/core
;@ def CheckForDisobedience() -> zero
;@ A traded Pokemon (other trainer ID) over the level the badges allow (10, 30 with the Cascade, 50 Rainbow, 70
;@ Marsh, any with the Earth Badge) may disobey, the more likely the higher its level: it uses another move,
;@ naps, loafs around or hurts itself. Zero if the selected move is not used.
;@ test: skip it draws random numbers until one fits, which needs the running game's timer
CheckForDisobedience:
;> wMonIsDisobedient = 0
	xor a
	ld [wMonIsDisobedient], a
;> if wLinkState == LINK_STATE_BATTLING:
;>     return False
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .checkIfMonIsTraded
	ld a, $1
	and a
	ret
; compare the mon's original trainer ID with the player's ID to see if it was traded
.checkIfMonIsTraded
;> ot = wPartyMon1OTID + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1OTID
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wPlayerMonNumber]
	call AddNTimes
;> if mem[ot] == wPlayerID[0]:
	ld a, [wPlayerID]
	cp [hl]
	jr nz, .monIsTraded
;>     if mem[ot + 1] == wPlayerID[1]:
;>         return False                              # caught by the player: always obeys
	inc hl
	ld a, [wPlayerID + 1]
	cp [hl]
	jp z, .canUseMove
; it was traded
.monIsTraded
; what level might disobey?
;> if wObtainedBadges >> BIT_EARTHBADGE & 1:
;>     obeys = 101
	ld hl, wObtainedBadges
	bit BIT_EARTHBADGE, [hl]
	ld a, 101
	jr nz, .next
;> elif wObtainedBadges >> BIT_MARSHBADGE & 1:
;>     obeys = 70
	bit BIT_MARSHBADGE, [hl]
	ld a, 70
	jr nz, .next
;> elif wObtainedBadges >> BIT_RAINBOWBADGE & 1:
;>     obeys = 50
	bit BIT_RAINBOWBADGE, [hl]
	ld a, 50
	jr nz, .next
;> elif wObtainedBadges >> BIT_CASCADEBADGE & 1:
;>     obeys = 30
	bit BIT_CASCADEBADGE, [hl]
	ld a, 30
	jr nz, .next
;> else:
;>     obeys = 10
	ld a, 10
.next
;> level = mem[wBattleMonLevel]
	ld b, a
	ld c, a
	ld a, [wBattleMonLevel]
	ld d, a
;> limit = min(obeys + level, 0xFF)
	add b
	ld b, a
	jr nc, .noCarry
	ld b, $ff ; cap b at $ff
.noCarry
;> if obeys >= level:
;>     return False
	ld a, c
	cp d
	jp nc, .canUseMove
.loop1
;> while True:                                       # random number 0 to obeys + level - 1 (nybbles swapped)
;>     r = BattleRandom()
	call BattleRandom
;>     r = (r << 4 | r >> 4) & 0xFF
	swap a
;>     if r < limit:
;>         break
	cp b
	jr nc, .loop1
;> if r < obeys:
;>     return False
	cp c
	jp c, .canUseMove
.loop2
;> while True:
;>     r = BattleRandom()
	call BattleRandom
;>     if r < limit:
;>         break
	cp b
	jr nc, .loop2
;> if r < obeys:                                     # it uses another of its moves, if it can
;>@a1     can = mem[wBattleMonMoves + 1] != 0           # it knows more than one move,
;>@a2     can = can and not wPlayerDisabledMoveNumber   # none is disabled
;>@a3     if can and wPlayerSelectedMove != STRUGGLE:   # and it isn't struggling
;>@b         pp = [mem[wBattleMonPP + i] & PP_MASK for i in range(NUM_MOVES)]
;>@c         total = pp[0]
;>@c2         total += pp[1]
;>@d         total += pp[2]
;>@e         total = total + pp[3] & 0xFF
;>@f         i = wCurrentMenuItem
;>@f2         mine = pp[i]
;>@g         if total != mine:                     # another move has PP left
;>@h             wMonIsDisobedient = 1
;>@i             count, selected = wMaxMenuItem, wCurrentMenuItem
;>@w             while True:                       # a random other move that has PP
;>@j                 slot = BattleRandom() & 3
;>@k                 if slot < count and slot != selected:
;>@l                     wCurrentMenuItem = slot
;>@m                     entry = wBattleMonPP + slot
;>@m2                     if mem[entry]:
;>@wb                         break
;>@n             entry = wBattleMonMoves + wCurrentMenuItem
;>@n2             wPlayerSelectedMove = mem[entry]
;>@o             GetCurrentMove()
;>@p             return False
;>     loaf = True                                   # it can't: it loafs around
	cp c
	jr c, .useRandomMove
;> else:
;>     over = level - obeys
	ld a, d
	sub c
	ld b, a
;>     r = BattleRandom()
	call BattleRandom
;>     r = ((r << 4 | r >> 4) & 0xFF) - over
;>     loaf = False
	swap a
	sub b
;>     if r < 0:                                     # a nap of 1 to 7 turns
;>@nw         while True:
;>@t1             turns = BattleRandom() * 2 & 0xFF
;>@t2             turns = (turns << 4 | turns >> 4) & SLP_MASK
;>@t3             if turns:
;>@t4                 break
;>@st         mem[wBattleMonStatus] = turns
;>@bt         text = BeganToNapText
	jr c, .monNaps
;>     elif r >= over:
;>         loaf = True
	cp b
	jr nc, .monDoesNothing
;>     else:                                         # it hurts itself
;>         PrintText(WontObeyText)
	ld hl, WontObeyText
	call PrintText
;>         HandleSelfConfusionDamage()
	call HandleSelfConfusionDamage
;>         return True
	jp .cannotUseMove
.monNaps
;=@t1
	call BattleRandom
	add a
;=@t2
	swap a
	and SLP_MASK
;=@t3
	jr z, .monNaps ; keep trying until we get at least 1 turn of sleep
;=@st
	ld [wBattleMonStatus], a
;=@bt
	ld hl, BeganToNapText
	jr .printText
.monDoesNothing
;> if loaf:
;>     n = BattleRandom() & 3
	call BattleRandom
	and $3
;>     text = LoafingAroundText
;>     if n:
	ld hl, LoafingAroundText
	and a
	jr z, .printText
;>         text = WontObeyText
;>         if n != 1:
	ld hl, WontObeyText
	dec a
	jr z, .printText
;>             text = TurnedAwayText
;>             if n != 2:
	ld hl, TurnedAwayText
	dec a
	jr z, .printText
;>                 text = IgnoredOrdersText
	ld hl, IgnoredOrdersText
.printText
;> PrintText(text)
	call PrintText
;>@no return True
	jr .cannotUseMove
.useRandomMove
;=@a1
	ld a, [wBattleMonMoves + 1]
	and a ; is the second move slot empty?
	jr z, .monDoesNothing ; mon will not use move if it only knows one move
;=@a2
	ld a, [wPlayerDisabledMoveNumber]
	and a
	jr nz, .monDoesNothing
;=@a3
	ld a, [wPlayerSelectedMove]
	cp STRUGGLE
	jr z, .monDoesNothing ; mon will not use move if struggling
; check if only one move has remaining PP
;=@b
	ld hl, wBattleMonPP
	push hl
;=@c
	ld a, [hli]
	and PP_MASK
	ld b, a
;=@c2
	ld a, [hli]
	and PP_MASK
	add b
	ld b, a
;=@d
	ld a, [hli]
	and PP_MASK
	add b
	ld b, a
;=@e
	ld a, [hl]
	and PP_MASK
	add b
	pop hl
;=@f
	push af
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, $0
;=@f2
	add hl, bc
	ld a, [hl]
	and PP_MASK
	ld b, a
;=@g
	pop af
	cp b
	jr z, .monDoesNothing ; mon will not use move if only one move has remaining PP
;=@h
	ld a, $1
	ld [wMonIsDisobedient], a
;=@i
	ld a, [wMaxMenuItem]
	ld b, a
	ld a, [wCurrentMenuItem]
	ld c, a
.chooseMove
;=@j
	call BattleRandom
	and $3
;=@k
	cp b
	jr nc, .chooseMove ; if the random number is greater than the move count, choose another
	cp c
	jr z, .chooseMove ; if the random number matches the move the player selected, choose another
;=@l
	ld [wCurrentMenuItem], a
;=@m
	ld hl, wBattleMonPP
	ld e, a
	ld d, $0
	add hl, de
;=@m2
	ld a, [hl]
	and a ; does the move have any PP left?
	jr z, .chooseMove ; if the move has no PP left, choose another
;=@n
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, $0
	ld hl, wBattleMonMoves
	add hl, bc
;=@n2
	ld a, [hl]
	ld [wPlayerSelectedMove], a
;=@o
	call GetCurrentMove
.canUseMove
;=@p
	ld a, $1
	and a ; clear Z flag
	ret
.cannotUseMove
;=@no
	xor a ; set Z flag
	ret

