; sets b, c, d, and e for the CalculateDamage routine in the case of an attack by the player mon
;@ path: engine/battle/core
;@ def GetDamageVarsForPlayerAttack() -> (zero, b, c, d, e)
;@ The inputs for CalculateDamage when the player's Pokemon attacks: its Attack (physical move) or Special
;@ against the enemy's Defense or Special, doubled by Reflect or Light Screen; on a critical hit the unboosted
;@ party stats are used and the level counts double. Stats of 256 or more are divided by 4 so both fit a byte.
;@ Returns b = attack, c = defense, d = move power, e = level; zero if the move has no power.
;@ test: wPlayerMovePower = rand(1, 255); wLinkState = LINK_STATE_BATTLING
GetDamageVarsForPlayerAttack:
;> wDamage[0] = 0
;> wDamage[1] = 0
	xor a
	ld hl, wDamage ; damage to eventually inflict, initialise to zero
	ld [hli], a
	ld [hl], a
;> power = wPlayerMovePower
	ld hl, wPlayerMovePower
	ld a, [hli]
;> if not power:
;>     return (True, 0, 0, 0, 0)                     # b, c and e are left as they were
	and a
	ld d, a ; d = move power
	ret z ; return if move power is zero
;> if wPlayerMoveType < SPECIAL:                     # a physical move
	ld a, [hl] ; a = [wPlayerMoveType]
	cp SPECIAL ; types >= SPECIAL are all special
	jr nc, .specialAttack
; physical attack
;>     defense = mem[wEnemyMonDefense] << 8 | mem[wEnemyMonDefense + 1]
	ld hl, wEnemyMonDefense
	ld a, [hli]
	ld b, a
	ld c, [hl] ; bc = enemy defense
;>     if wEnemyBattleStatus3 >> HAS_REFLECT_UP & 1:
;>         defense = defense << 1 & 0xFFFF           # Reflect doubles it
	ld a, [wEnemyBattleStatus3]
	bit HAS_REFLECT_UP, a ; check for Reflect
	jr z, .physicalAttackCritCheck
; if the enemy has used Reflect, double the enemy's defense
	sla c
	rl b
.physicalAttackCritCheck
;>     attack = wBattleMonAttack
	ld hl, wBattleMonAttack
;>     if wCriticalHitOrOHKO:                        # a critical hit: the unboosted stats
	ld a, [wCriticalHitOrOHKO]
	and a ; check for critical hit
	jr z, .scaleStats
; in the case of a critical hit, reset the player's attack and the enemy's defense to their base values
;>         GetEnemyMonStat(STAT_DEFENSE)
	ld c, STAT_DEFENSE
	call GetEnemyMonStat
;>         defense = hProduct[2] << 8 | hProduct[3]
	ldh a, [hProduct + 2]
	ld b, a
	ldh a, [hProduct + 3]
	ld c, a
;>         attack = wPartyMon1Attack + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	push bc
	ld hl, wPartyMon1Attack
	ld a, [wPlayerMonNumber]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	pop bc
;> else:                                             # a special move
	jr .scaleStats
.specialAttack
;>     defense = mem[wEnemyMonSpecial] << 8 | mem[wEnemyMonSpecial + 1]
	ld hl, wEnemyMonSpecial
	ld a, [hli]
	ld b, a
	ld c, [hl] ; bc = enemy special
;>     if wEnemyBattleStatus3 >> HAS_LIGHT_SCREEN_UP & 1:
;>         defense = defense << 1 & 0xFFFF           # Light Screen doubles it
	ld a, [wEnemyBattleStatus3]
	bit HAS_LIGHT_SCREEN_UP, a ; check for Light Screen
	jr z, .specialAttackCritCheck
; if the enemy has used Light Screen, double the enemy's special
	sla c
	rl b
; reflect and light screen boosts do not cap the stat at MAX_STAT_VALUE, so weird things will happen during stats scaling
; if a Pokemon with 512 or more Defense has used Reflect, or if a Pokemon with 512 or more Special has used Light Screen
.specialAttackCritCheck
;>     attack = wBattleMonSpecial
	ld hl, wBattleMonSpecial
;>     if wCriticalHitOrOHKO:
	ld a, [wCriticalHitOrOHKO]
	and a ; check for critical hit
	jr z, .scaleStats
; in the case of a critical hit, reset the player's and enemy's specials to their base values
;>         GetEnemyMonStat(STAT_SPECIAL)
	ld c, STAT_SPECIAL
	call GetEnemyMonStat
;>         defense = hProduct[2] << 8 | hProduct[3]
	ldh a, [hProduct + 2]
	ld b, a
	ldh a, [hProduct + 3]
	ld c, a
;>         attack = wPartyMon1Special + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	push bc
	ld hl, wPartyMon1Special
	ld a, [wPlayerMonNumber]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	pop bc
; if either the offensive or defensive stat is too large to store in a byte, scale both stats by dividing them by 4
; this allows values with up to 10 bits (values up to 1023) to be handled
; anything larger will wrap around
.scaleStats
;> attack = mem[attack] << 8 | mem[attack + 1]
	ld a, [hli]
	ld l, [hl]
	ld h, a ; hl = player's offensive stat
;> if attack >> 8 or defense >> 8:                   # too big for a byte: both / 4
	or b ; is either high byte nonzero?
	jr z, .next ; if not, we don't need to scale
; bc /= 4 (scale enemy's defensive stat)
;>     defense >>= 2                                 # (it can become 0: a division by 0 freezes the game)
	srl b
	rr c
	srl b
	rr c
; defensive stat can actually end up as 0, leading to a division by 0 freeze during damage calculation
; hl /= 4 (scale player's offensive stat)
;>     attack >>= 2
	srl h
	rr l
	srl h
	rr l
;>     if not attack:
;>         attack = 1
	ld a, l
	or h ; is the player's offensive stat 0?
	jr nz, .next
	inc l ; if the player's offensive stat is 0, bump it up to 1
.next
;> level = mem[wBattleMonLevel]
	ld b, l ; b = player's offensive stat (possibly scaled)
	        ; (c already contains enemy's defensive stat (possibly scaled))
	ld a, [wBattleMonLevel]
	ld e, a ; e = level
;> if wCriticalHitOrOHKO:
;>     level = level << 1 & 0xFF                     # a critical hit doubles it
	ld a, [wCriticalHitOrOHKO]
	and a ; check for critical hit
	jr z, .done
	sla e ; double level if it was a critical hit
.done
;> return (False, attack & 0xFF, defense & 0xFF, power, level)
	ld a, 1
	and a
	ret

; sets b, c, d, and e for the CalculateDamage routine in the case of an attack by the enemy mon
;@ path: engine/battle/core
;@ def GetDamageVarsForEnemyAttack() -> (zero, b, c, d, e)
;@ The inputs for CalculateDamage when the enemy's Pokemon attacks (see GetDamageVarsForPlayerAttack).
;@ test: wEnemyMovePower = rand(1, 255); wLinkState = LINK_STATE_BATTLING; wPlayerMonNumber = rand(0, 5)
GetDamageVarsForEnemyAttack:
;> wDamage[0] = 0
;> wDamage[1] = 0
	ld hl, wDamage ; damage to eventually inflict, initialise to zero
	xor a
	ld [hli], a
	ld [hl], a
;> power = wEnemyMovePower
	ld hl, wEnemyMovePower
	ld a, [hli]
	ld d, a ; d = move power
;> if not power:
;>     return (True, 0, 0, 0, 0)                     # b, c and e are left as they were
	and a
	ret z ; return if move power is zero
;> if wEnemyMoveType < SPECIAL:                      # a physical move
	ld a, [hl] ; a = [wEnemyMoveType]
	cp SPECIAL ; types >= SPECIAL are all special
	jr nc, .specialAttack
; physical attack
;>     defense = mem[wBattleMonDefense] << 8 | mem[wBattleMonDefense + 1]
	ld hl, wBattleMonDefense
	ld a, [hli]
	ld b, a
	ld c, [hl] ; bc = player defense
;>     if wPlayerBattleStatus3 >> HAS_REFLECT_UP & 1:
;>         defense = defense << 1 & 0xFFFF           # Reflect doubles it
	ld a, [wPlayerBattleStatus3]
	bit HAS_REFLECT_UP, a ; check for Reflect
	jr z, .physicalAttackCritCheck
; if the player has used Reflect, double the player's defense
	sla c
	rl b
.physicalAttackCritCheck
;>     attack = wEnemyMonAttack
	ld hl, wEnemyMonAttack
;>     if wCriticalHitOrOHKO:                        # a critical hit: the unboosted stats
	ld a, [wCriticalHitOrOHKO]
	and a ; check for critical hit
	jr z, .scaleStats
; in the case of a critical hit, reset the player's defense and the enemy's attack to their base values
;>         p = wPartyMon1Defense + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Defense
	ld a, [wPlayerMonNumber]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>         defense = mem[p] << 8 | mem[p + 1]
	ld a, [hli]
	ld b, a
	ld c, [hl]
;>         GetEnemyMonStat(STAT_ATTACK)
	push bc
	ld c, STAT_ATTACK
	call GetEnemyMonStat
;>         attack = addr(hProduct) + 2
	ld hl, hProduct + 2
	pop bc
	jr .scaleStats
.specialAttack
;> else:                                             # a special move
;>     defense = mem[wBattleMonSpecial] << 8 | mem[wBattleMonSpecial + 1]
	ld hl, wBattleMonSpecial
	ld a, [hli]
	ld b, a
	ld c, [hl]
;>     if wPlayerBattleStatus3 >> HAS_LIGHT_SCREEN_UP & 1:
;>         defense = defense << 1 & 0xFFFF           # Light Screen doubles it
	ld a, [wPlayerBattleStatus3]
	bit HAS_LIGHT_SCREEN_UP, a ; check for Light Screen
	jr z, .specialAttackCritCheck
; if the player has used Light Screen, double the player's special
	sla c
	rl b
; reflect and light screen boosts do not cap the stat at MAX_STAT_VALUE, so weird things will happen during stats scaling
; if a Pokemon with 512 or more Defense has used Reflect, or if a Pokemon with 512 or more Special has used Light Screen
.specialAttackCritCheck
;>     attack = wEnemyMonSpecial
	ld hl, wEnemyMonSpecial
;>     if wCriticalHitOrOHKO:
	ld a, [wCriticalHitOrOHKO]
	and a ; check for critical hit
	jr z, .scaleStats
; in the case of a critical hit, reset the player's and enemy's specials to their base values
;>         p = wPartyMon1Special + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1Special
	ld a, [wPlayerMonNumber]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>         defense = mem[p] << 8 | mem[p + 1]
	ld a, [hli]
	ld b, a
	ld c, [hl]
;>         GetEnemyMonStat(STAT_SPECIAL)
	push bc
	ld c, STAT_SPECIAL
	call GetEnemyMonStat
;>         attack = addr(hProduct) + 2
	ld hl, hProduct + 2
	pop bc
; if either the offensive or defensive stat is too large to store in a byte, scale both stats by dividing them by 4
; this allows values with up to 10 bits (values up to 1023) to be handled
; anything larger will wrap around
.scaleStats
;> attack = mem[attack] << 8 | mem[attack + 1]
	ld a, [hli]
	ld l, [hl]
	ld h, a ; hl = enemy's offensive stat
;> if attack >> 8 or defense >> 8:                   # too big for a byte: both / 4
	or b ; is either high byte nonzero?
	jr z, .next ; if not, we don't need to scale
; bc /= 4 (scale player's defensive stat)
;>     defense >>= 2                                 # (it can become 0: a division by 0 freezes the game)
	srl b
	rr c
	srl b
	rr c
; defensive stat can actually end up as 0, leading to a division by 0 freeze during damage calculation
; hl /= 4 (scale enemy's offensive stat)
;>     attack >>= 2
	srl h
	rr l
	srl h
	rr l
;>     if not attack:
;>         attack = 1
	ld a, l
	or h ; is the enemy's offensive stat 0?
	jr nz, .next
	inc l ; if the enemy's offensive stat is 0, bump it up to 1
.next
;> level = mem[wEnemyMonLevel]
	ld b, l ; b = enemy's offensive stat (possibly scaled)
	        ; (c already contains player's defensive stat (possibly scaled))
	ld a, [wEnemyMonLevel]
	ld e, a
;> if wCriticalHitOrOHKO:
;>     level = level << 1 & 0xFF                     # a critical hit doubles it
	ld a, [wCriticalHitOrOHKO]
	and a ; check for critical hit
	jr z, .done
	sla e ; double level if it was a critical hit
.done
;> return (False, attack & 0xFF, defense & 0xFF, power, level)
	ld a, $1
	and a
	and a
	ret

; get stat c of enemy mon
; c: stat to get (STAT_* constant)
;@ path: engine/battle/core
;@ def GetEnemyMonStat(stat: c)
;@ The enemy Pokemon's stat `stat` (a STAT_* constant) without stat stages, into hMultiplicand + 1/2: read from
;@ the opponent's party in a link battle, otherwise calculated from its species, level and DVs.
;@ test: wLinkState = LINK_STATE_BATTLING; stat = rand(1, 5)
GetEnemyMonStat:
;> if wLinkState == LINK_STATE_BATTLING:
	push de
	push bc
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .notLinkBattle
;>     p = wEnemyMon1Stats + 2 * (stat - 1)
	ld hl, wEnemyMon1Stats
	dec c
	sla c
	ld b, $0
	add hl, bc
;>     p += mem[wEnemyMonPartyPos] * PARTYMON_STRUCT_LENGTH   # in the enemy's party data
	ld a, [wEnemyMonPartyPos]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     hMultiplicand[1] = mem[p]
	ld a, [hli]
	ldh [hMultiplicand + 1], a
;>     hMultiplicand[2] = mem[p + 1]
	ld a, [hl]
	ldh [hMultiplicand + 2], a
;>     return
	pop bc
	pop de
	ret
.notLinkBattle
;> wCurEnemyLevel = mem[wEnemyMonLevel]
	ld a, [wEnemyMonLevel]
	ld [wCurEnemyLevel], a
;> wCurSpecies = mem[wEnemyMonSpecies]
	ld a, [wEnemyMonSpecies]
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> mem[wLoadedMonSpeedExp] = mem[wEnemyMonDVs]
	ld hl, wEnemyMonDVs
	ld de, wLoadedMonSpeedExp
	ld a, [hli]
	ld [de], a
;> mem[wLoadedMonSpeedExp + 1] = mem[wEnemyMonDVs + 1]
	inc de
	ld a, [hl]
	ld [de], a
;> CalcStat(wLoadedMonSpeedExp - 0xB, stat, 0)
	pop bc
	ld b, $0
	ld hl, wLoadedMonSpeedExp - $b ; this base address makes CalcStat look in [wLoadedMonSpeedExp] for DVs
	call CalcStat
	pop de
	ret

;@ path: engine/battle/core
;@ def CalculateDamage(attack: b, defense: c, power: d, level: e) -> zero
;@ Damage = (2 * level / 5 + 2) * power * attack / defense / 50, added to wDamage and kept within 2..999.
;@ Self-destruct and Explosion halve the defense first; one-hit KO moves go to their effect instead. Returns
;@ zero only if the move has no power (or the one-hit KO move missed).
;@ test: defense = rand(1, 255); hLoadedROMBank = 0x0F; wPlayerMoveEffect = rand(0, 0x25); wEnemyMoveEffect = rand(0, 0x25)
CalculateDamage:
; input:
;   b: attack
;   c: opponent defense
;   d: base power
;   e: level

;> effect = wEnemyMoveEffect if hWhoseTurn else wPlayerMoveEffect
	ldh a, [hWhoseTurn] ; whose turn?
	and a
	ld a, [wPlayerMoveEffect]
	jr z, .effect
	ld a, [wEnemyMoveEffect]
.effect

; EXPLODE_EFFECT halves defense.
;> if effect == EXPLODE_EFFECT:                      # Self-Destruct, Explosion
;>     defense = defense >> 1 or 1                   # halved, at least 1 (it divides later)
	cp EXPLODE_EFFECT
	jr nz, .ok
	srl c
	jr nz, .ok
	inc c ; ...with a minimum value of 1 (used as a divisor later on)
.ok

; Multi-hit attacks may or may not have 0 bp.
;> if effect != TWO_TO_FIVE_ATTACKS_EFFECT and effect != EFFECT_1E:   # (multi-hit moves may have no power)
	cp TWO_TO_FIVE_ATTACKS_EFFECT
	jr z, .skipbp
	cp EFFECT_1E
	jr z, .skipbp

; Calculate OHKO damage based on remaining HP.
;>     if effect == OHKO_EFFECT:
;>         return JumpToOHKOMoveEffect()
	cp OHKO_EFFECT
	jp z, JumpToOHKOMoveEffect

; Don't calculate damage for moves that don't do any.
;>     if not power:
;>         return True
	ld a, d ; base power
	and a
	ret z
.skipbp

;> hDividend[0:3] = [0, 0, 0]
	xor a
	ld hl, hDividend
	ld [hli], a
	ld [hli], a
	ld [hl], a

; Multiply level by 2
;> level2 = level * 2
	ld a, e ; level
	add a
;> if level2 > 0xFF:
;>     hDividend[2] = 1
	jr nc, .nc
	push af
	ld a, 1
	ld [hl], a
	pop af
.nc
;> hDividend[3] = level2 & 0xFF
	inc hl
	ld [hli], a

; Divide by 5
;> hDivisor = 5
;> Divide(4)
	ld a, 5
	ld [hld], a
	push bc
	ld b, 4
	call Divide
	pop bc

; Add 2
;> hQuotient[3] = (hQuotient[3] + 2) & 0xFF
	inc [hl]
	inc [hl]

;> hMultiplier = power
;> Multiply()
	inc hl ; multiplier

; Multiply by attack base power
	ld [hl], d
	call Multiply

; Multiply by attack stat
;> hMultiplier = attack
;> Multiply()
	ld [hl], b
	call Multiply

; Divide by defender's defense stat
;> hDivisor = defense
;> Divide(4)
	ld [hl], c
	ld b, 4
	call Divide

; Divide by 50
;> hDivisor = 50
;> Divide(4)
	ld [hl], 50
	ld b, 4
	call Divide

; Update wCurDamage.
; Capped at MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE: 999 - 2 = 997.
;> # add to wDamage; anything from 998 up becomes 997
;> s = hQuotient[3] + wDamage[0]
	ld hl, wDamage
	ld b, [hl]
	ldh a, [hQuotient + 3]
	add b
;> hQuotient[3] = s & 0xFF
;> cap = False
	ldh [hQuotient + 3], a
;> if s > 0xFF:
	jr nc, .dont_cap_1

;>     hQuotient[2] = (hQuotient[2] + 1) & 0xFF
	ldh a, [hQuotient + 2]
	inc a
	ldh [hQuotient + 2], a
;>     cap = hQuotient[2] == 0
	and a
	jr z, .cap

.dont_cap_1
;> if not cap:
;>     cap = hQuotient[1] != 0
	ldh a, [hQuotient]
	ld b, a
	ldh a, [hQuotient + 1]
	or a
	jr nz, .cap

;>     if not cap:                                   # 998 or more?
;>         high = hQuotient[2]
	ldh a, [hQuotient + 2]
;>         if high >= hi(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1):
	cp HIGH(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	jr c, .dont_cap_2

;>             cap = high > hi(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	cp HIGH(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1) + 1
	jr nc, .cap

;>             if not cap:
;>                 cap = hQuotient[3] >= lo(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)

	ldh a, [hQuotient + 3]
	cp LOW(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	jr nc, .cap

.dont_cap_2
;> if not cap:
;>     total = (wDamage[0] << 8 | wDamage[1]) + (hQuotient[2] << 8 | hQuotient[3])
	inc hl

	ldh a, [hQuotient + 3]
	ld b, [hl]
	add b
;>     wDamage[1] = total & 0xFF
	ld [hld], a

;>     wDamage[0] = total >> 8 & 0xFF
	ldh a, [hQuotient + 2]
	ld b, [hl]
	adc b
	ld [hl], a
;>     cap = total > 0xFFFF
	jr c, .cap

;>     if not cap:
;>         high = wDamage[0]
	ld a, [hl]
;>         if high >= hi(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1):
	cp HIGH(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	jr c, .dont_cap_3

;>             cap = high > hi(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	cp HIGH(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1) + 1
	jr nc, .cap

;>             if not cap:
;>                 cap = wDamage[1] >= lo(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	inc hl
	ld a, [hld]
	cp LOW(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE + 1)
	jr c, .dont_cap_3

.cap
;> if cap:
;>     wDamage[0] = (MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE) >> 8
	ld a, HIGH(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE)
	ld [hli], a
;>     wDamage[1] = (MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE) & 0xFF
	ld a, LOW(MAX_NEUTRAL_DAMAGE - MIN_NEUTRAL_DAMAGE)
	ld [hld], a

.dont_cap_3
; Add back MIN_NEUTRAL_DAMAGE (capping at 999).
;> low = wDamage[1] + MIN_NEUTRAL_DAMAGE
;> wDamage[1] = low & 0xFF
	inc hl
	ld a, [hl]
	add MIN_NEUTRAL_DAMAGE
	ld [hld], a
;> if low > 0xFF:
;>     wDamage[0] = (wDamage[0] + 1) & 0xFF
	jr nc, .dont_floor
	inc [hl]
.dont_floor

; Returns nz and nc.
;> return False
	ld a, 1
	and a
	ret

;@ path: engine/battle/core
;@ def JumpToOHKOMoveEffect() -> zero
;@ A one-hit KO move: run its effect (which decides the damage); zero if it missed.
JumpToOHKOMoveEffect:
;> JumpMoveEffect()
;> return wMoveMissed == 1
	call JumpMoveEffect
	ld a, [wMoveMissed]
	dec a
	ret

;@ path: engine/battle/core
UnusedHighCriticalMoves:
	db KARATE_CHOP
	db RAZOR_LEAF
	db CRABHAMMER
	db SLASH
	db -1 ; end

; determines if attack is a critical hit
; Azure Heights claims "the fastest pokémon (who are, not coincidentally,
; among the most popular) tend to CH about 20 to 25% of the time."
;@ path: engine/battle/core
;@ def CriticalHitTest()
;@ Decide whether this attack is a critical hit (wCriticalHitOrOHKO = 1). The chance is base Speed / 512, times
;@ 8 for high critical-hit moves (Slash, Razor Leaf, Crabhammer, Karate Chop), at most 255/256. Focus Energy
;@ is meant to raise it but divides it by 4 instead.
CriticalHitTest:
;> wCriticalHitOrOHKO = 0
	xor a
	ld [wCriticalHitOrOHKO], a
;> wCurSpecies = mem[wEnemyMonSpecies] if hWhoseTurn else mem[wBattleMonSpecies]
	ldh a, [hWhoseTurn]
	and a
	ld a, [wEnemyMonSpecies]
	jr nz, .handleEnemy
	ld a, [wBattleMonSpecies]
.handleEnemy
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> rate = wMonHBaseSpeed >> 1
	ld a, [wMonHBaseSpeed]
	ld b, a
	srl b                        ; (effective (base speed/2))
;> if hWhoseTurn == 0:
;>     power, move, status2 = wPlayerMovePower, wPlayerMoveNum, wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	ld hl, wPlayerMovePower
	ld de, wPlayerBattleStatus2
	jr z, .calcCriticalHitProbability
;> else:
;>     power, move, status2 = wEnemyMovePower, wEnemyMoveNum, wEnemyBattleStatus2
	ld hl, wEnemyMovePower
	ld de, wEnemyBattleStatus2
.calcCriticalHitProbability
;> if not power:
;>     return
	ld a, [hld]                  ; read base power from RAM
	and a
	ret z                        ; do nothing if zero
;> if status2 >> GETTING_PUMPED & 1:                 # Focus Energy: a bug - it halves instead of doubling
;>@fe     rate >>= 1
	dec hl
	ld c, [hl]                   ; read move id
	ld a, [de]
	bit GETTING_PUMPED, a        ; test for focus energy
	jr nz, .focusEnergyUsed      ; bug: using focus energy causes a shift to the right instead of left,
	                             ; resulting in 1/4 the usual crit chance
;> else:
;>     rate = min(rate * 2, 0xFF)
	sla b                        ; (effective (base speed/2)*2)
	jr nc, .noFocusEnergyUsed
	ld b, $ff                    ; cap at 255/256
	jr .noFocusEnergyUsed
.focusEnergyUsed
;=@fe
	srl b
.noFocusEnergyUsed
;> entry = HighCriticalMoves
	ld hl, HighCriticalMoves     ; table of high critical hit moves
.Loop
;> while mem[entry] != move and mem[entry] != 0xFF:    # (the list ends with $FF)
;>     entry += 1
	ld a, [hli]                  ; read move from move table
	cp c                         ; does it match the move about to be used?
	jr z, .HighCritical          ; if so, the move about to be used is a high critical hit ratio move
	inc a                        ; move on to the next move, FF terminates loop
	jr nz, .Loop                 ; check the next move in HighCriticalMoves
;> if mem[entry] != move:                            # a regular move: halved again
;>     rate >>= 1
	srl b                        ; /2 for regular move (effective (base speed / 2))
	jr .SkipHighCritical         ; continue as a normal move
.HighCritical
;> else:                                             # a high critical-hit move: times 4
;>     rate = min(rate * 2, 0xFF)
	sla b                        ; *2 for high critical hit moves
	jr nc, .noCarry
	ld b, $ff                    ; cap at 255/256
.noCarry
;>     rate = min(rate * 2, 0xFF)
	sla b                        ; *4 for high critical move (effective (base speed/2)*8))
	jr nc, .SkipHighCritical
	ld b, $ff
.SkipHighCritical
;> r = BattleRandom()
;> r = (r << 3 | r >> 5) & 0xFF
	call BattleRandom            ; generates a random value, in "a"
	rlc a
	rlc a
	rlc a
;> if r < rate:
;>     wCriticalHitOrOHKO = 1
	cp b                         ; check a against calculated crit rate
	ret nc                       ; no critical hit if no borrow
	ld a, $1
	ld [wCriticalHitOrOHKO], a   ; set critical hit flag
	ret

;@ path: engine/battle/core
HighCriticalMoves:
	db KARATE_CHOP
	db RAZOR_LEAF
	db CRABHAMMER
	db SLASH
	db -1 ; end

; function to determine if Counter hits and if so, how much damage it does
;@ path: engine/battle/core
;@ def HandleCounterMove() -> zero
;@ Counter: when the attacker uses it, it hits back with double the last damage (at most $FFFF) - only if the
;@ target's last selected move was a Normal or Fighting move with power, was not Counter itself, and did damage.
;@ Returns zero when the attacker used Counter (whether it hit or not: wMoveMissed tells).
;@ test: hLoadedROMBank = 0x0F; wLinkState = LINK_STATE_BATTLING; hWhoseTurn = rand(0, 1)
;@ test: wEnemySelectedMove = COUNTER if hWhoseTurn else None; wPlayerSelectedMove = None if hWhoseTurn else COUNTER
;@ test: wPlayerMoveType = rand(0, 1) * FIGHTING; wEnemyMoveType = rand(0, 1) * FIGHTING
;@ test: wPlayerMonAccuracyMod = rand(1, 13); wEnemyMonEvasionMod = rand(1, 13); wEnemyMonAccuracyMod = rand(1, 13); wPlayerMonEvasionMod = rand(1, 13)
HandleCounterMove:
; The variables checked by Counter are updated whenever the cursor points to a new move in the battle selection menu.
; This is irrelevant for the opponent's side outside of link battles, since the move selection is controlled by the AI.
; However, in the scenario where the player switches out and the opponent uses Counter,
; the outcome may be affected by the player's actions in the move selection menu prior to switching the Pokemon.
; This might also lead to desync glitches in link battles.

;> if hWhoseTurn == 0:
;>     own, target_move, target_power, target_type = wPlayerSelectedMove, wEnemySelectedMove, wEnemyMovePower, wEnemyMoveType
	ldh a, [hWhoseTurn] ; whose turn
	and a
; player's turn
	ld hl, wEnemySelectedMove
	ld de, wEnemyMovePower
	ld a, [wPlayerSelectedMove]
	jr z, .next
; enemy's turn
;> else:
;>     own, target_move, target_power, target_type = wEnemySelectedMove, wPlayerSelectedMove, wPlayerMovePower, wPlayerMoveType
	ld hl, wPlayerSelectedMove
	ld de, wPlayerMovePower
	ld a, [wEnemySelectedMove]
.next
;> if own != COUNTER:
;>     return False
	cp COUNTER
	ret nz ; return if not using Counter
;> wMoveMissed = 1                                   # until it hits
	ld a, $01
	ld [wMoveMissed], a ; initialize the move missed variable to true (it is set to false below if the move hits)
;> if target_move == COUNTER or not target_power:    # the target's last selected move
;>     return True
	ld a, [hl]
	cp COUNTER
	ret z ; miss if the opponent's last selected move is Counter.
	ld a, [de]
	and a
	ret z ; miss if the opponent's last selected move's Base Power is 0.
; check if the move the target last selected was Normal or Fighting type
;> if target_type != NORMAL and target_type != FIGHTING:
	inc de
	ld a, [de]
	and a ; normal type
	jr z, .counterableType
	cp FIGHTING
	jr z, .counterableType
;>     return True                                   # other types can't be countered
; if the move wasn't Normal or Fighting type, miss
	xor a
	ret
.counterableType
;> damage = wDamage[0] << 8 | wDamage[1]
	ld hl, wDamage
	ld a, [hli]
	or [hl]
;> if not damage:                                    # (wDamage is shared: it may be the Counter user's own)
;>     return True
	ret z ; If we made it here, Counter still misses if the last move used in battle did no damage to its target.
	      ; wDamage is shared by both players, so Counter may strike back damage dealt by the Counter user itself
	      ; if the conditions meet, even though 99% of the times damage will come from the target.
; if it did damage, double it
;> damage *= 2
;> wDamage[0], wDamage[1] = damage >> 8 & 0xFF, damage & 0xFF
	ld a, [hl]
	add a
	ld [hld], a
	ld a, [hl]
	adc a
	ld [hl], a
;> if damage > 0xFFFF:
;>     wDamage[0] = wDamage[1] = 0xFF                # capped
	jr nc, .noCarry
; damage is capped at 0xFFFF
	ld a, $ff
	ld [hli], a
	ld [hl], a
.noCarry
;> wMoveMissed = 0
	xor a
	ld [wMoveMissed], a
;> MoveHitTest()                                     # the normal hit test still applies
	call MoveHitTest ; do the normal move hit test in addition to Counter's special rules
;> return True
	xor a
	ret

;@ path: engine/battle/core
;@ def ApplyAttackToEnemyPokemon()
;@ Set the damage of the player's special-damage moves, then hit the enemy: Super Fang takes half its HP (at
;@ least 1), Seismic Toss and Night Shade the user's level, Sonic Boom 20, Dragon Rage 40, Psywave a random
;@ 1 to 1.5 x level - 1. A move without power that isn't a one-hit KO deals nothing.
;@ test: mem[0xD022] = rand(2, 100)
ApplyAttackToEnemyPokemon:
;> effect = wPlayerMoveEffect
	ld a, [wPlayerMoveEffect]
;> if effect == OHKO_EFFECT:
;>     return ApplyDamageToEnemyPokemon()
	cp OHKO_EFFECT
	jr z, ApplyDamageToEnemyPokemon
;> if effect == SUPER_FANG_EFFECT:
	cp SUPER_FANG_EFFECT
	jr z, .superFangEffect
;=@sd
	cp SPECIAL_DAMAGE_EFFECT
	jr z, .specialDamage
;=@np
	ld a, [wPlayerMovePower]
	and a
	jp z, ApplyAttackToEnemyPokemonDone ; no attack to apply if base power is 0
;=@ap
	jr ApplyDamageToEnemyPokemon
.superFangEffect
; set the damage to half the target's HP
;>     damage = (mem[wEnemyMonHP] << 8 | mem[wEnemyMonHP + 1]) >> 1
;>     wDamage[0] = damage >> 8
	ld hl, wEnemyMonHP
	ld de, wDamage
	ld a, [hli]
	srl a
	ld [de], a
	inc de
;>     wDamage[1] = damage & 0xFF
	ld b, a
	ld a, [hl]
	rr a
	ld [de], a
;>     if not damage:
	or b
	jr nz, ApplyDamageToEnemyPokemon
; make sure Super Fang's damage is always at least 1
;>         wDamage[1] = 1                            # at least 1
	ld a, $01
	ld [de], a
	jr ApplyDamageToEnemyPokemon
.specialDamage
;>@sd elif effect == SPECIAL_DAMAGE_EFFECT:
;>     level = mem[wBattleMonLevel]
	ld hl, wBattleMonLevel
	ld a, [hl]
	ld b, a ; Seismic Toss deals damage equal to the user's level
;>     if wPlayerMoveNum in (SEISMIC_TOSS, NIGHT_SHADE):
;>         damage = level
	ld a, [wPlayerMoveNum]
	cp SEISMIC_TOSS
	jr z, .storeDamage
	cp NIGHT_SHADE
	jr z, .storeDamage
;>     elif wPlayerMoveNum == SONICBOOM:
;>         damage = SONICBOOM_DAMAGE
	ld b, SONICBOOM_DAMAGE ; 20
	cp SONICBOOM
	jr z, .storeDamage
;>     elif wPlayerMoveNum == DRAGON_RAGE:
;>         damage = DRAGON_RAGE_DAMAGE
	ld b, DRAGON_RAGE_DAMAGE ; 40
	cp DRAGON_RAGE
	jr z, .storeDamage
; Psywave
;>     else:                                         # Psywave
;>         limit = (level + level // 2) & 0xFF
	ld a, [hl]
	ld b, a
	srl a
	add b
	ld b, a ; b = level * 1.5
; loop until a random number in the range [1, b) is found
.loop
;>         while True:
;>             damage = BattleRandom()
	call BattleRandom
;>             if damage and damage < limit:
;>                 break
	and a
	jr z, .loop
	cp b
	jr nc, .loop
	ld b, a
.storeDamage ; store damage value at b
;>     wDamage[0] = 0
	ld hl, wDamage
	xor a
	ld [hli], a
;>     wDamage[1] = damage
	ld a, b
	ld [hl], a
;>@np elif not wPlayerMovePower: return ApplyAttackToEnemyPokemonDone()   # no power: nothing
;>@ap ApplyDamageToEnemyPokemon()

;@ path: engine/battle/core
;@ def ApplyDamageToEnemyPokemon()
;@ Take wDamage off the enemy Pokemon's HP (into its Substitute if it has one) and animate its HP bar. If the
;@ damage is more than the HP left, the HP becomes 0 and wDamage the HP it had.
ApplyDamageToEnemyPokemon:
;> damage = wDamage[0] << 8 | wDamage[1]
;> if damage:
	ld hl, wDamage
	ld a, [hli]
	ld b, a
	ld a, [hl]
	or b
	jr z, ApplyAttackToEnemyPokemonDone ; we're done if damage is 0
;>     if wEnemyBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>         return AttackSubstitute()
	ld a, [wEnemyBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a ; does the enemy have a substitute?
	jp nz, AttackSubstitute
; subtract the damage from the pokemon's current HP
; also, save the current HP at wHPBarOldHP
;>     wHPBarOldHP[0] = mem[wEnemyMonHP + 1]         # the old HP, low byte first
	ld a, [hld]
	ld b, a
	ld a, [wEnemyMonHP + 1]
	ld [wHPBarOldHP], a
;>     low = wHPBarOldHP[0] - wDamage[1]
;>     mem[wEnemyMonHP + 1] = low & 0xFF
	sub b
	ld [wEnemyMonHP + 1], a
;>     wHPBarOldHP[1] = mem[wEnemyMonHP]
	ld a, [hl]
	ld b, a
	ld a, [wEnemyMonHP]
	ld [wHPBarOldHP+1], a
;>     hp = (wHPBarOldHP[1] << 8 | wHPBarOldHP[0]) - damage
;>     mem[wEnemyMonHP] = hp >> 8 & 0xFF
	sbc b
	ld [wEnemyMonHP], a
;>     if hp < 0:                                    # more than it had: the damage is what it had
	jr nc, .animateHpBar
; if more damage was done than the current HP, zero the HP and set the damage (wDamage)
; equal to how much HP the pokemon had before the attack
;>         wDamage[0], wDamage[1] = wHPBarOldHP[1], wHPBarOldHP[0]
	ld a, [wHPBarOldHP+1]
	ld [hli], a
	ld a, [wHPBarOldHP]
	ld [hl], a
;>         hp = 0
;>         mem[wEnemyMonHP], mem[wEnemyMonHP + 1] = 0, 0
	xor a
	ld hl, wEnemyMonHP
	ld [hli], a
	ld [hl], a
.animateHpBar
;>     wHPBarMaxHP[1], wHPBarMaxHP[0] = mem[wEnemyMonMaxHP], mem[wEnemyMonMaxHP + 1]
	ld hl, wEnemyMonMaxHP
	ld a, [hli]
	ld [wHPBarMaxHP+1], a
	ld a, [hl]
	ld [wHPBarMaxHP], a
;>     wHPBarNewHP[1], wHPBarNewHP[0] = hp >> 8, hp & 0xFF
	ld hl, wEnemyMonHP
	ld a, [hli]
	ld [wHPBarNewHP+1], a
	ld a, [hl]
	ld [wHPBarNewHP], a
;>     wHPBarType = 0
;>     predef(UpdateHPBar2, hl=coord(2, 2))          # the bar shortens
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	xor a
	ld [wHPBarType], a
	; animate the HP bar shortening
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;> ApplyAttackToEnemyPokemonDone()                   # (falls through)
;@ path: engine/battle/core
;@ def ApplyAttackToEnemyPokemonDone()
;@ Redraw both HUDs and HP bars after an attack on the enemy.
;@ test: hLoadedROMBank = 0x0F; mem[0xD009 + rand(0, 10)] = 0x50; mem[0xCFDA + rand(0, 10)] = 0x50
ApplyAttackToEnemyPokemonDone:
;> DrawHUDsAndHPBars()
	jp DrawHUDsAndHPBars

;@ path: engine/battle/core
;@ def ApplyAttackToPlayerPokemon()
;@ The same for the enemy's attack on the player's Pokemon, except that its Psywave can deal 0 damage (a random
;@ 0 to 1.5 x level - 1).
;@ test: mem[0xCFF3] = rand(1, 100)
ApplyAttackToPlayerPokemon:
;> effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
;> if effect == OHKO_EFFECT:
;>     return ApplyDamageToPlayerPokemon()
	cp OHKO_EFFECT
	jr z, ApplyDamageToPlayerPokemon
;> if effect == SUPER_FANG_EFFECT:
	cp SUPER_FANG_EFFECT
	jr z, .superFangEffect
;=@sd
	cp SPECIAL_DAMAGE_EFFECT
	jr z, .specialDamage
;=@np
	ld a, [wEnemyMovePower]
	and a
	jp z, ApplyAttackToPlayerPokemonDone
;=@ap
	jr ApplyDamageToPlayerPokemon
.superFangEffect
; set the damage to half the target's HP
;>     damage = (mem[wBattleMonHP] << 8 | mem[wBattleMonHP + 1]) >> 1
;>     wDamage[0] = damage >> 8
	ld hl, wBattleMonHP
	ld de, wDamage
	ld a, [hli]
	srl a
	ld [de], a
	inc de
;>     wDamage[1] = damage & 0xFF
	ld b, a
	ld a, [hl]
	rr a
	ld [de], a
;>     if not damage:
	or b
	jr nz, ApplyDamageToPlayerPokemon
; make sure Super Fang's damage is always at least 1
;>         wDamage[1] = 1                            # at least 1
	ld a, $01
	ld [de], a
	jr ApplyDamageToPlayerPokemon
.specialDamage
;>@sd elif effect == SPECIAL_DAMAGE_EFFECT:
;>     level = mem[wEnemyMonLevel]
	ld hl, wEnemyMonLevel
	ld a, [hl]
	ld b, a
;>     if wEnemyMoveNum in (SEISMIC_TOSS, NIGHT_SHADE):
;>         damage = level
	ld a, [wEnemyMoveNum]
	cp SEISMIC_TOSS
	jr z, .storeDamage
	cp NIGHT_SHADE
	jr z, .storeDamage
;>     elif wEnemyMoveNum == SONICBOOM:
;>         damage = SONICBOOM_DAMAGE
	ld b, SONICBOOM_DAMAGE
	cp SONICBOOM
	jr z, .storeDamage
;>     elif wEnemyMoveNum == DRAGON_RAGE:
;>         damage = DRAGON_RAGE_DAMAGE
	ld b, DRAGON_RAGE_DAMAGE
	cp DRAGON_RAGE
	jr z, .storeDamage
; Psywave
;>     else:                                         # Psywave
;>         limit = (level + level // 2) & 0xFF
	ld a, [hl]
	ld b, a
	srl a
	add b
	ld b, a ; b = attacker's level * 1.5
; loop until a random number in the range [0, b) is found
; this differs from the range when the player attacks, which is [1, b)
; it's possible for the enemy to do 0 damage with Psywave, but the player always does at least 1 damage
.loop
;>         while True:
;>             damage = BattleRandom()
	call BattleRandom
;>             if damage < limit:
;>                 break
	cp b
	jr nc, .loop
	ld b, a
.storeDamage
;>     wDamage[0] = 0
	ld hl, wDamage
	xor a
	ld [hli], a
;>     wDamage[1] = damage
	ld a, b
	ld [hl], a
;>@np elif not wEnemyMovePower: return ApplyAttackToPlayerPokemonDone()   # no power: nothing
;>@ap ApplyDamageToPlayerPokemon()

;@ path: engine/battle/core
;@ def ApplyDamageToPlayerPokemon()
;@ Take wDamage off the player's Pokemon's HP (into its Substitute if it has one) and animate its HP bar. If the
;@ damage is more than the HP left, the HP becomes 0 and wDamage the HP it had.
ApplyDamageToPlayerPokemon:
;> damage = wDamage[0] << 8 | wDamage[1]
;> if damage:
	ld hl, wDamage
	ld a, [hli]
	ld b, a
	ld a, [hl]
	or b
	jr z, ApplyAttackToPlayerPokemonDone ; we're done if damage is 0
;>     if wPlayerBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>         return AttackSubstitute()
	ld a, [wPlayerBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a ; does the player have a substitute?
	jp nz, AttackSubstitute
; subtract the damage from the pokemon's current HP
; also, save the current HP at wHPBarOldHP and the new HP at wHPBarNewHP
;>     wHPBarOldHP[0] = mem[wBattleMonHP + 1]        # the old HP, low byte first
	ld a, [hld]
	ld b, a
	ld a, [wBattleMonHP + 1]
	ld [wHPBarOldHP], a
;>     low = wHPBarOldHP[0] - wDamage[1]
;>     mem[wBattleMonHP + 1] = wHPBarNewHP[0] = low & 0xFF
	sub b
	ld [wBattleMonHP + 1], a
	ld [wHPBarNewHP], a
;>     wHPBarOldHP[1] = mem[wBattleMonHP]
	ld b, [hl]
	ld a, [wBattleMonHP]
	ld [wHPBarOldHP+1], a
;>     hp = (wHPBarOldHP[1] << 8 | wHPBarOldHP[0]) - damage
;>     mem[wBattleMonHP] = wHPBarNewHP[1] = hp >> 8 & 0xFF
	sbc b
	ld [wBattleMonHP], a
	ld [wHPBarNewHP+1], a
;>     if hp < 0:                                    # more than it had: the damage is what it had
	jr nc, .animateHpBar
; if more damage was done than the current HP, zero the HP and set the damage (wDamage)
; equal to how much HP the pokemon had before the attack
;>         wDamage[0], wDamage[1] = wHPBarOldHP[1], wHPBarOldHP[0]
	ld a, [wHPBarOldHP+1]
	ld [hli], a
	ld a, [wHPBarOldHP]
	ld [hl], a
;>         mem[wBattleMonHP], mem[wBattleMonHP + 1] = 0, 0
	xor a
	ld hl, wBattleMonHP
	ld [hli], a
	ld [hl], a
;>         wHPBarNewHP[0], wHPBarNewHP[1] = 0, 0
	ld hl, wHPBarNewHP
	ld [hli], a
	ld [hl], a
.animateHpBar
;>     wHPBarMaxHP[1], wHPBarMaxHP[0] = mem[wBattleMonMaxHP], mem[wBattleMonMaxHP + 1]
	ld hl, wBattleMonMaxHP
	ld a, [hli]
	ld [wHPBarMaxHP+1], a
	ld a, [hl]
	ld [wHPBarMaxHP], a
;>     wHPBarType = 1
;>     predef(UpdateHPBar2, hl=coord(10, 9))         # the bar shortens
	ld hl, (9) * SCREEN_WIDTH + (10) + wTileMap
	ld a, $01
	ld [wHPBarType], a
	; animate the HP bar shortening
	ld a, (UpdateHPBar2Predef - PredefPointers) / 3
	call Predef
;> ApplyAttackToPlayerPokemonDone()                  # (falls through)
;@ path: engine/battle/core
;@ def ApplyAttackToPlayerPokemonDone()
;@ Redraw both HUDs and HP bars after an attack on the player's Pokemon.
;@ test: hLoadedROMBank = 0x0F; mem[0xD009 + rand(0, 10)] = 0x50; mem[0xCFDA + rand(0, 10)] = 0x50
ApplyAttackToPlayerPokemonDone:
;> DrawHUDsAndHPBars()
	jp DrawHUDsAndHPBars

;@ path: engine/battle/core
;@ def AttackSubstitute()
;@ The damage hits the target's Substitute instead. Damage over 255 always breaks it; otherwise its HP drops and
;@ it breaks when the HP would go below 0 ("<MON>'s SUBSTITUTE broke!"), cancelling the attack's extra effect.
AttackSubstitute:
; Unlike the two ApplyAttackToPokemon functions, Attack Substitute is shared by player and enemy.
; Self-confusion damage as well as Hi-Jump Kick and Jump Kick recoil cause a momentary turn swap before being applied.
; If the user has a Substitute up and would take damage because of that,
; damage will be applied to the other player's Substitute.
; Normal recoil such as from Double-Edge isn't affected by this glitch,
; because this function is never called in that case.

;> PrintText(SubstituteTookDamageText)
	ld hl, SubstituteTookDamageText
	call PrintText
;> sub_hp, status = addr(wEnemySubstituteHP), addr(wEnemyBattleStatus2)   # the target's
; values for player turn
	ld de, wEnemySubstituteHP
	ld bc, wEnemyBattleStatus2
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .applyDamageToSubstitute
; values for enemy turn
;>     sub_hp, status = addr(wPlayerSubstituteHP), addr(wPlayerBattleStatus2)
	ld de, wPlayerSubstituteHP
	ld bc, wPlayerBattleStatus2
.applyDamageToSubstitute
;> if not wDamage[0]:
	ld hl, wDamage
	ld a, [hli]
	and a
	jr nz, .substituteBroke ; damage > 0xFF always breaks substitutes
; subtract damage from HP of substitute
;>     hp = mem[sub_hp] - wDamage[1]
;>     mem[sub_hp] = hp & 0xFF
	ld a, [de]
	sub [hl]
	ld [de], a
;>     if hp >= 0:
;>         return
	ret nc
.substituteBroke
; If the target's Substitute breaks, wDamage isn't updated with the amount of HP
; the Substitute had before being attacked.
;> mem[status] &= ~(1 << HAS_SUBSTITUTE_UP)
	ld h, b
	ld l, c
	res HAS_SUBSTITUTE_UP, [hl] ; unset the substitute bit
;> PrintText(SubstituteBrokeText)
	ld hl, SubstituteBrokeText
	call PrintText
; flip whose turn it is for the next function call
;> hWhoseTurn ^= 1
	ldh a, [hWhoseTurn]
	xor $01
	ldh [hWhoseTurn], a
	; animate the substitute breaking
;> farcall(HideSubstituteShowMonAnim)
	ld hl, HideSubstituteShowMonAnim
	ld b, BANK(HideSubstituteShowMonAnim)
	call Bankswitch
; flip the turn back to the way it was
;> hWhoseTurn ^= 1
	ldh a, [hWhoseTurn]
	xor $01
	ldh [hWhoseTurn], a
;> effect = addr(wPlayerMoveEffect)                  # the attacker's extra effect is cancelled
	ld hl, wPlayerMoveEffect ; value for player's turn
;> if hWhoseTurn:
	and a
	jr z, .nullifyEffect
;>     effect = addr(wEnemyMoveEffect)
	ld hl, wEnemyMoveEffect ; value for enemy's turn
.nullifyEffect
;> mem[effect] = 0
	xor a
	ld [hl], a ; zero the effect of the attacker's move
;> DrawHUDsAndHPBars()
	jp DrawHUDsAndHPBars

;@ path: engine/battle/core
SubstituteTookDamageText:
	db TX_FAR
	dw _SubstituteTookDamageText
	db BANK(_SubstituteTookDamageText)
	db TX_END

;@ path: engine/battle/core
SubstituteBrokeText:
	db TX_FAR
	dw _SubstituteBrokeText
	db BANK(_SubstituteBrokeText)
	db TX_END

; this function raises the attack modifier of a pokemon using Rage when that pokemon is attacked
;@ path: engine/battle/core
;@ def HandleBuildingRage()
;@ A Pokemon using Rage that gets hit raises its Attack by one stage ("<MON>'s RAGE is building!"), unless it is
;@ already at the maximum: its move is briefly turned into an Attack-up effect for that.
HandleBuildingRage:
; values for the player turn
;> status, mod, move = wEnemyBattleStatus2, wEnemyMonStatMods, addr(wEnemyMoveNum)   # the target's
	ld hl, wEnemyBattleStatus2
	ld de, wEnemyMonStatMods
	ld bc, wEnemyMoveNum
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .next
; values for the enemy turn
;>     status, mod, move = wPlayerBattleStatus2, wPlayerMonStatMods, addr(wPlayerMoveNum)
	ld hl, wPlayerBattleStatus2
	ld de, wPlayerMonStatMods
	ld bc, wPlayerMoveNum
.next
;> if not status >> USING_RAGE & 1 or mod == 13:
;>     return
	bit USING_RAGE, [hl] ; is the pokemon being attacked under the effect of Rage?
	ret z ; return if not
	ld a, [de]
	cp $0d ; maximum stat modifier value
	ret z ; return if attack modifier is already maxed
;> hWhoseTurn ^= 1
	ldh a, [hWhoseTurn]
	xor $01 ; flip turn for the stat modifier raising function
	ldh [hWhoseTurn], a
; temporarily change the target pokemon's move to $00 and the effect to the one
; that causes the attack modifier to go up one stage
;> mem[move] = 0
	ld h, b
	ld l, c
	ld [hl], $00 ; null move number
;> mem[move + 1] = ATTACK_UP1_EFFECT
	inc hl
	ld [hl], ATTACK_UP1_EFFECT
;> PrintText(BuildingRageText)
	push hl
	ld hl, BuildingRageText
	call PrintText
;> StatModifierUpEffect()
	call StatModifierUpEffect ; stat modifier raising function
;> mem[move + 1] = 0
	pop hl
	xor a
	ld [hld], a ; null move effect
;> mem[move] = RAGE
	ld a, RAGE
	ld [hl], a ; restore the target pokemon's move number to Rage
;> hWhoseTurn ^= 1
	ldh a, [hWhoseTurn]
	xor $01 ; flip turn back to the way it was
	ldh [hWhoseTurn], a
	ret

;@ path: engine/battle/core
BuildingRageText:
	db TX_FAR
	dw _BuildingRageText
	db BANK(_BuildingRageText)
	db TX_END

; copy last move for Mirror Move
; sets zero flag on failure and unsets zero flag on success
;@ path: engine/battle/core
;@ def MirrorMoveCopyMove() -> zero
;@ Mirror Move: use the move the target used last. Fails (zero) if it used none yet or Mirror Move itself.
;@ test: hLoadedROMBank = 0x0F; wPlayerMoveListIndex = rand(0, 3); wEnemyMoveListIndex = rand(0, 3); wPlayerMonNumber = rand(0, 5); mem[0xCFE8] = rand(0, 5)
MirrorMoveCopyMove:
; Mirror Move makes use of wPlayerUsedMove and wEnemyUsedMove,
; which are mainly used to print the "[Pokemon] used [Move]" text.
; Both are set to 0 whenever a new Pokemon is sent out
; wPlayerUsedMove is also set to 0 whenever the player is fast asleep or frozen solid.
; wEnemyUsedMove is also set to 0 whenever the enemy is fast asleep or frozen solid.

;> if hWhoseTurn == 0:
;>     move, selected, dest = wEnemyUsedMove, addr(wPlayerSelectedMove), addr(wPlayerMoveNum)
	ldh a, [hWhoseTurn]
	and a
; values for player turn
	ld a, [wEnemyUsedMove]
	ld hl, wPlayerSelectedMove
	ld de, wPlayerMoveNum
	jr z, .next
; values for enemy turn
;> else:
;>     move, selected, dest = wPlayerUsedMove, addr(wEnemySelectedMove), addr(wEnemyMoveNum)
	ld a, [wPlayerUsedMove]
	ld de, wEnemyMoveNum
	ld hl, wEnemySelectedMove
.next
;> mem[selected] = move
	ld [hl], a
;> if move != MIRROR_MOVE and move:                  # the target used a move, and not Mirror Move
;>     return ReloadMoveData(move, dest)
	cp MIRROR_MOVE ; did the target Pokemon last use Mirror Move, and miss?
	jr z, .mirrorMoveFailed
	and a ; has the target selected any move yet?
	jr nz, ReloadMoveData
.mirrorMoveFailed
;> PrintText(MirrorMoveFailedText)
	ld hl, MirrorMoveFailedText
	call PrintText
;> return True
	xor a
	ret

;@ path: engine/battle/core
MirrorMoveFailedText:
	db TX_FAR
	dw _MirrorMoveFailedText
	db BANK(_MirrorMoveFailedText)
	db TX_END

; function used to reload move data for moves like Mirror Move and Metronome
;@ path: engine/battle/core
;@ def ReloadMoveData(move: a, dest: de) -> zero
;@ Load the data of another move into the attacker's move variables at dest (Mirror Move, Metronome), give back
;@ the PP the calling move used and put the new move's name in wStringBuffer. Returns not zero.
;@ test: hLoadedROMBank = 0x0F; move = rand(1, NUM_ATTACKS); wPlayerMoveListIndex = rand(0, 3); wEnemyMoveListIndex = rand(0, 3); wPlayerMonNumber = rand(0, 5); mem[0xCFE8] = rand(0, 5)
ReloadMoveData:
;> wNamedObjectIndex = move
	ld [wNamedObjectIndex], a
;> src = Moves + ((move - 1) & 0xFF) * MOVE_LENGTH
	dec a
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;> FarCopyData(BANK(Moves), src, dest, MOVE_LENGTH)
	ld a, BANK(Moves)
	call FarCopyData ; copy the move's stats
;> IncrementMovePP()
	call IncrementMovePP
; the follow two function calls are used to reload the move name
;> CopyToStringBuffer(GetMoveName())
;> return False
	call GetMoveName
	call CopyToStringBuffer
	ld a, $01
	and a
	ret

; function that picks a random move for metronome
;@ path: engine/battle/core
;@ def MetronomePickMove() -> zero
;@ Metronome: play its animation, then pick a random move (any but Metronome and Struggle) and load it.
;@ test: hLoadedROMBank = 0x0F; wPlayerMoveListIndex = rand(0, 3); wEnemyMoveListIndex = rand(0, 3); wPlayerMonNumber = rand(0, 5); mem[0xCFE8] = rand(0, 5)
MetronomePickMove:
;> wAnimationType = 0
	xor a
	ld [wAnimationType], a
;> PlayMoveAnimation(METRONOME)
	ld a, METRONOME
	call PlayMoveAnimation ; play Metronome's animation
; values for player turn
;> dest, selected = addr(wPlayerMoveNum), addr(wPlayerSelectedMove)
	ld de, wPlayerMoveNum
	ld hl, wPlayerSelectedMove
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .pickMoveLoop
; values for enemy turn
;>     dest, selected = addr(wEnemyMoveNum), addr(wEnemySelectedMove)
	ld de, wEnemyMoveNum
	ld hl, wEnemySelectedMove
; loop to pick a random number in the range of valid moves used by Metronome
.pickMoveLoop
;> while True:
;>     move = BattleRandom()
	call BattleRandom
;>     if move:
	and a
	jr z, .pickMoveLoop
;>         if move < STRUGGLE:                       # (the number of moves)
	cp STRUGGLE
	ASSERT NUM_ATTACKS == STRUGGLE ; random numbers greater than STRUGGLE are not moves
	jr nc, .pickMoveLoop
;>             if move != METRONOME:
;>                 break
	cp METRONOME
	jr z, .pickMoveLoop
;> mem[selected] = move
	ld [hl], a
;> return ReloadMoveData(move, dest)
	jr ReloadMoveData

; this function increments the current move's PP
; it's used to prevent moves that run another move within the same turn
; (like Mirror Move and Metronome) from losing 2 PP
;@ path: engine/battle/core
;@ def IncrementMovePP()
;@ Give back one PP of the attacker's current move, in battle and in the party: a move that runs another move
;@ (Mirror Move, Metronome) would otherwise use 2 PP.
;@ test: wPlayerMoveListIndex = rand(0, 3); wEnemyMoveListIndex = rand(0, 3); wPlayerMonNumber = rand(0, 5); mem[0xCFE8] = rand(0, 5)
IncrementMovePP:
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
; values for player turn
;> pp, party_pp, index = wBattleMonPP, wPartyMon1PP, wPlayerMoveListIndex
	ld hl, wBattleMonPP
	ld de, wPartyMon1PP
	ld a, [wPlayerMoveListIndex]
;> if not player:
	jr z, .next
; values for enemy turn
;>     pp, party_pp, index = wEnemyMonPP, wEnemyMon1PP, wEnemyMoveListIndex
	ld hl, wEnemyMonPP
	ld de, wEnemyMon1PP
	ld a, [wEnemyMoveListIndex]
.next
;> mem[pp + index] += 1
	ld b, $00
	ld c, a
	add hl, bc
	inc [hl] ; increment PP in the currently battling pokemon memory location
;> p = party_pp + index
	ld h, d
	ld l, e
	add hl, bc
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> mon = wPlayerMonNumber
;> if not player:
	ld a, [wPlayerMonNumber] ; value for player turn
	jr z, .updatePP
;>     mon = mem[wEnemyMonPartyPos]
	ld a, [wEnemyMonPartyPos] ; value for enemy turn
.updatePP
;> p += mon * PARTYMON_STRUCT_LENGTH
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;> mem[p] += 1
	inc [hl] ; increment PP in the party memory location
	ret

; function to adjust the base damage of an attack to account for type effectiveness
;@ path: engine/battle/core
;@ def AdjustDamageForMoveType()
;@ Same-type attack bonus and type matchups: x1.5 if the move's type is one of the attacker's types, then for
;@ every TypeEffects entry matching the move's type and one of the defender's types the damage is multiplied by
;@ its factor (in tenths). A move brought down to 0 damage this way misses.
;@ test: hLoadedROMBank = 0x0F
AdjustDamageForMoveType:
; values for player turn
;> attacker = wBattleMonType                         # the player's turn first
	ld hl, wBattleMonType
	ld a, [hli]
	ld b, a    ; b = type 1 of attacker
	ld c, [hl] ; c = type 2 of attacker
;> defender = wEnemyMonType
	ld hl, wEnemyMonType
	ld a, [hli]
	ld d, a    ; d = type 1 of defender
	ld e, [hl] ; e = type 2 of defender
;> wMoveType = wPlayerMoveType
	ld a, [wPlayerMoveType]
	ld [wMoveType], a
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .next
; values for enemy turn
;>     attacker = wEnemyMonType
	ld hl, wEnemyMonType
	ld a, [hli]
	ld b, a    ; b = type 1 of attacker
	ld c, [hl] ; c = type 2 of attacker
;>     defender = wBattleMonType
	ld hl, wBattleMonType
	ld a, [hli]
	ld d, a    ; d = type 1 of defender
	ld e, [hl] ; e = type 2 of defender
;>     wMoveType = wEnemyMoveType
	ld a, [wEnemyMoveType]
	ld [wMoveType], a
.next
;> if wMoveType == mem[attacker] or wMoveType == mem[attacker + 1]:   # same-type attack bonus
	ld a, [wMoveType]
	cp b ; does the move type match type 1 of the attacker?
	jr z, .sameTypeAttackBonus
	cp c ; does the move type match type 2 of the attacker?
	jr z, .sameTypeAttackBonus
	jr .skipSameTypeAttackBonus
.sameTypeAttackBonus
; if the move type matches one of the attacker's types
;>     damage = wDamage[0] << 8 | wDamage[1]
	ld hl, wDamage + 1
	ld a, [hld]
	ld h, [hl]
	ld l, a    ; hl = damage
;>     damage = (damage + (damage >> 1)) & 0xFFFF    # x1.5
	ld b, h
	ld c, l    ; bc = damage
	srl b
	rr c      ; bc = floor(0.5 * damage)
	add hl, bc ; hl = floor(1.5 * damage)
; store damage
;>     wDamage[0], wDamage[1] = damage >> 8, damage & 0xFF
	ld a, h
	ld [wDamage], a
	ld a, l
	ld [wDamage + 1], a
;>     wDamageMultipliers |= 1 << BIT_STAB_DAMAGE
	ld hl, wDamageMultipliers
	set BIT_STAB_DAMAGE, [hl]
.skipSameTypeAttackBonus
;> p = TypeEffects
	ld a, [wMoveType]
	ld b, a
	ld hl, TypeEffects
.loop
;> while mem[p] != 0xFF:
	ld a, [hli] ; a = "attacking type" of the current type pair
	cp $ff
	jr z, .done
;>     if mem[p] == wMoveType:
	cp b ; does move type match "attacking type"?
	jr nz, .nextTypePair
;>         if mem[p + 1] in (mem[defender], mem[defender + 1]):
	ld a, [hl] ; a = "defending type" of the current type pair
	cp d ; does type 1 of defender match "defending type"?
	jr z, .matchingPairFound
	cp e ; does type 2 of defender match "defending type"?
	jr z, .matchingPairFound
	jr .nextTypePair
.matchingPairFound
; if the move type matches the "attacking type" and one of the defender's types matches the "defending type"
;>             stab = wDamageMultipliers & 1 << BIT_STAB_DAMAGE
	push hl
	push bc
	inc hl
	ld a, [wDamageMultipliers]
	and 1 << BIT_STAB_DAMAGE
	ld b, a
;>             factor = mem[p + 2]                       # in tenths
;>             hMultiplier = factor
	ld a, [hl] ; a = damage multiplier
	ldh [hMultiplier], a
;>             wDamageMultipliers = (factor + stab) & 0xFF
	add b
	ld [wDamageMultipliers], a
;>             hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;>             hMultiplicand[1:3] = [wDamage[0], wDamage[1]]
	ld hl, wDamage
	ld a, [hli]
	ldh [hMultiplicand + 1], a
	ld a, [hld]
	ldh [hMultiplicand + 2], a
;>             Multiply()
	call Multiply
;>             hDivisor = 10
;>             Divide(4)
	ld a, 10
	ldh [hDivisor], a
	ld b, 4
	call Divide
;>             wDamage[0], wDamage[1] = hQuotient[2], hQuotient[3]
	ldh a, [hQuotient + 2]
	ld [hli], a
	ld b, a
	ldh a, [hQuotient + 3]
	ld [hl], a
;>             if not (hQuotient[2] or hQuotient[3]):    # brought down to 0: the move misses
;>                 wMoveMissed = 1
	or b ; is damage 0?
	jr nz, .skipTypeImmunity
; if damage is 0, make the move miss
; this only occurs if a move that would do 2 or 3 damage is 0.25x effective against the target
	inc a
	ld [wMoveMissed], a
.skipTypeImmunity
	pop bc
	pop hl
.nextTypePair
;>     p += 3
	inc hl
	inc hl
	jp .loop
.done
	ret

; function to tell how effective the type of an enemy attack is on the player's current pokemon
; this doesn't take into account the effects that dual types can have
; (e.g. 4x weakness / resistance, weaknesses and resistances canceling)
; the result is stored in [wTypeEffectiveness]
; as far is can tell, this is only used once in some AI code to help decide which move to use
;@ path: engine/battle/core
;@ def AIGetTypeEffectiveness()
;@ How effective the enemy's move is on the player's Pokemon, for the AI: the factor of the first TypeEffects
;@ entry that matches either of its types (dual types are not combined), into wTypeEffectiveness. The neutral
;@ start value is $10 where 10 was meant.
AIGetTypeEffectiveness:
;> t1, t2 = mem[wBattleMonType], mem[wBattleMonType + 1]
	ld a, [wEnemyMoveType]
	ld d, a                    ; d = type of enemy move
	ld hl, wBattleMonType
	ld b, [hl]                 ; b = type 1 of player's pokemon
	inc hl
	ld c, [hl]                 ; c = type 2 of player's pokemon
	; initialize to neutral effectiveness
;> wTypeEffectiveness = 0x10
	ld a, $10 ; bug: should be EFFECTIVE (10)
	ld [wTypeEffectiveness], a
;> p = TypeEffects
	ld hl, TypeEffects
.loop
;> while True:
;>     entry = mem[p]
	ld a, [hli]
;>     if entry == 0xFF:
;>         return
	cp $ff
	ret z
;>     if entry == wEnemyMoveType:
	cp d                      ; match the type of the move
	jr nz, .nextTypePair1
;>         if mem[p + 1] in (t1, t2):
	ld a, [hli]
	cp b                      ; match with type 1 of pokemon
	jr z, .done
	cp c                      ; or match with type 2 of pokemon
	jr z, .done
	jr .nextTypePair2
;>@ef             wTypeEffectiveness = mem[p + 2]
;>@er             return
;>     p += 3
.nextTypePair1
	inc hl
.nextTypePair2
	inc hl
	jr .loop
.done
;=@ef
	ld a, [hl]
	ld [wTypeEffectiveness], a ; store damage multiplier
;=@er
	ret

;@ path: engine/battle/core
TypeEffects:
	;  attacker,     defender,     *=
	db WATER,        FIRE,         SUPER_EFFECTIVE
	db FIRE,         GRASS,        SUPER_EFFECTIVE
	db FIRE,         ICE,          SUPER_EFFECTIVE
	db GRASS,        WATER,        SUPER_EFFECTIVE
	db ELECTRIC,     WATER,        SUPER_EFFECTIVE
