; some tests that need to pass for a move to hit
;@ path: engine/battle/core
;@ def MoveHitTest()
;@ Does the move about to be used hit? Dream Eater misses a target that is awake, Swift always hits, a target in
;@ the air (Fly) or underground (Dig) can't be hit, Mist blocks stat-lowering moves, X Accuracy always hits;
;@ otherwise a random number must be below the accuracy scaled by CalcHitChance. A miss zeroes the damage, sets
;@ wMoveMissed and ends the attacker's trapping move (Wrap...).
;@ test: hLoadedROMBank = 0x0F; wLinkState = LINK_STATE_BATTLING
;@ test: wPlayerMonAccuracyMod = rand(1, 13); wEnemyMonEvasionMod = rand(1, 13); wEnemyMonAccuracyMod = rand(1, 13); wPlayerMonEvasionMod = rand(1, 13)
MoveHitTest:
; player's turn
;> missed = False
;> target_status1, effect, target_status = addr(wEnemyBattleStatus1), wPlayerMoveEffect, wEnemyMonStatus
	ld hl, wEnemyBattleStatus1
	ld de, wPlayerMoveEffect
	ld bc, wEnemyMonStatus
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .dreamEaterCheck
; enemy's turn
;>     target_status1, effect, target_status = addr(wPlayerBattleStatus1), wEnemyMoveEffect, wBattleMonStatus
	ld hl, wPlayerBattleStatus1
	ld de, wEnemyMoveEffect
	ld bc, wBattleMonStatus
.dreamEaterCheck
;> if effect == DREAM_EATER_EFFECT and not mem[target_status] & SLP_MASK:   # Dream Eater needs a sleeping target
;>     missed = True
	ld a, [de]
	cp DREAM_EATER_EFFECT
	jr nz, .swiftCheck
	ld a, [bc]
	and SLP_MASK
	jp z, .moveMissed
.swiftCheck
;> elif effect == SWIFT_EFFECT:                      # Swift never misses
;>     return
	ld a, [de]
	cp SWIFT_EFFECT
	ret z ; Swift never misses (this was fixed from the Japanese versions)
;> else:
;>     # meant to make draining moves miss a Substitute - but the check compares the wrong value, so never
;>     CheckTargetSubstitute()
	call CheckTargetSubstitute ; substitute check (note that this overwrites a)
	jr z, .checkForDigOrFlyStatus
; The fix for Swift broke this code. It's supposed to prevent HP draining moves from working on Substitutes.
; Since CheckTargetSubstitute overwrites a with either $00 or $01, it never works.
	cp DRAIN_HP_EFFECT
	jp z, .moveMissed
	cp DREAM_EATER_EFFECT
	jp z, .moveMissed
.checkForDigOrFlyStatus
;>     if mem[target_status1] >> INVULNERABLE & 1:   # in the air or underground
;>         missed = True
	bit INVULNERABLE, [hl]
	jp nz, .moveMissed
;>     elif hWhoseTurn == 0:
	ldh a, [hWhoseTurn]
	and a
	jr nz, .enemyTurn
; player's turn
; this checks if the move effect is disallowed by mist
;>         e = wPlayerMoveEffect                     # a stat-lowering move? Mist blocks those
	ld a, [wPlayerMoveEffect]
;>         lowering = ATTACK_DOWN1_EFFECT <= e <= HAZE_EFFECT
	cp ATTACK_DOWN1_EFFECT
	jr c, .skipEnemyMistCheck
	cp HAZE_EFFECT + 1
	jr c, .enemyMistCheck
;>         lowering = lowering or ATTACK_DOWN2_EFFECT <= e <= REFLECT_EFFECT
	cp ATTACK_DOWN2_EFFECT
	jr c, .skipEnemyMistCheck
	cp REFLECT_EFFECT + 1
	jr c, .enemyMistCheck
	jr .skipEnemyMistCheck
.enemyMistCheck
; if move effect is from $12 to $19 inclusive or $3a to $41 inclusive
; i.e. the following moves
; GROWL, TAIL WHIP, LEER, STRING SHOT, SAND-ATTACK, SMOKESCREEN, KINESIS,
; FLASH, CONVERSION*, HAZE*, SCREECH, LIGHT SCREEN*, REFLECT*
; the moves that are marked with an asterisk are not affected since this
; function is not called when those moves are used
;>         if lowering and wEnemyBattleStatus2 >> PROTECTED_BY_MIST & 1:
;>             missed = True
	ld a, [wEnemyBattleStatus2]
	bit PROTECTED_BY_MIST, a ; is mon protected by mist?
	jp nz, .moveMissed
.skipEnemyMistCheck
;>         elif wPlayerBattleStatus2 >> USING_X_ACCURACY & 1:   # X Accuracy: always hits
;>             return
	ld a, [wPlayerBattleStatus2]
	bit USING_X_ACCURACY, a ; is the player using X Accuracy?
	ret nz ; if so, always hit regardless of accuracy/evasion
	jr .calcHitChance
.enemyTurn
;>     else:
;>         e = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
;>         lowering = ATTACK_DOWN1_EFFECT <= e <= HAZE_EFFECT
	cp ATTACK_DOWN1_EFFECT
	jr c, .skipPlayerMistCheck
	cp HAZE_EFFECT + 1
	jr c, .playerMistCheck
;>         lowering = lowering or ATTACK_DOWN2_EFFECT <= e <= REFLECT_EFFECT
	cp ATTACK_DOWN2_EFFECT
	jr c, .skipPlayerMistCheck
	cp REFLECT_EFFECT + 1
	jr c, .playerMistCheck
	jr .skipPlayerMistCheck
.playerMistCheck
; similar to enemy mist check
;>         if lowering and wPlayerBattleStatus2 >> PROTECTED_BY_MIST & 1:
;>             missed = True
	ld a, [wPlayerBattleStatus2]
	bit PROTECTED_BY_MIST, a ; is mon protected by mist?
	jp nz, .moveMissed
.skipPlayerMistCheck
;>         elif wEnemyBattleStatus2 >> USING_X_ACCURACY & 1:
;>             return
	ld a, [wEnemyBattleStatus2]
	bit USING_X_ACCURACY, a ; is the enemy using X Accuracy?
	ret nz ; if so, always hit regardless of accuracy/evasion
.calcHitChance
;> if not missed:
;>     CalcHitChance()                               # the accuracy, scaled by the stages
	call CalcHitChance ; scale the move accuracy according to attacker's accuracy and target's evasion
;>     accuracy = wPlayerMoveAccuracy
	ld a, [wPlayerMoveAccuracy]
	ld b, a
;>     if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .doAccuracyCheck
;>         accuracy = wEnemyMoveAccuracy
	ld a, [wEnemyMoveAccuracy]
	ld b, a
.doAccuracyCheck
; if the random number generated is greater than or equal to the scaled accuracy, the move misses
; note that this means that even the highest accuracy is still just a 255/256 chance, not 100%
;>     if BattleRandom() < accuracy:                 # (so even the best accuracy hits 255 times in 256)
;>         return
	call BattleRandom
	cp b
	jr nc, .moveMissed
	ret
.moveMissed
;> wDamage[0] = 0
;> wDamage[1] = 0
	xor a
	ld hl, wDamage ; zero the damage
	ld [hli], a
	ld [hl], a
;> wMoveMissed = 1
	inc a
	ld [wMoveMissed], a
;> if hWhoseTurn:                                    # the attacker's trapping move (Wrap...) ends
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
; enemy's turn
;>     wEnemyBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld hl, wEnemyBattleStatus1
	res USING_TRAPPING_MOVE, [hl] ; end multi-turn attack e.g. wrap
	ret
.playerTurn
;> else:
;>     wPlayerBattleStatus1 &= ~(1 << USING_TRAPPING_MOVE)
	ld hl, wPlayerBattleStatus1
	res USING_TRAPPING_MOVE, [hl] ; end multi-turn attack e.g. wrap
	ret

; values for player turn
;@ path: engine/battle/core
;@ def CalcHitChance()
;@ Scale the attacker's move accuracy by its accuracy stage and the target's evasion stage (mirrored: 14 - stage),
;@ each through StatModifierRatios, at least 1 after each step and at most 255.
;@ test: hLoadedROMBank = 0x0F
;@ test: wPlayerMonAccuracyMod = rand(1, 13); wEnemyMonEvasionMod = rand(1, 13); wEnemyMonAccuracyMod = rand(1, 13); wPlayerMonEvasionMod = rand(1, 13)
CalcHitChance:
;> accuracy = addr(wPlayerMoveAccuracy)
	ld hl, wPlayerMoveAccuracy
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> acc_mod, eva_mod = wPlayerMonAccuracyMod, wEnemyMonEvasionMod
	ld a, [wPlayerMonAccuracyMod]
	ld b, a
	ld a, [wEnemyMonEvasionMod]
	ld c, a
;> if not player:
	jr z, .next
; values for enemy turn
;>     accuracy, acc_mod, eva_mod = addr(wEnemyMoveAccuracy), wEnemyMonAccuracyMod, wPlayerMonEvasionMod
	ld hl, wEnemyMoveAccuracy
	ld a, [wEnemyMonAccuracyMod]
	ld b, a
	ld a, [wPlayerMonEvasionMod]
	ld c, a
.next
;> mods = (acc_mod, 14 - eva_mod)                    # evasion mirrored: more evasion, fewer hits
	ld a, $0e
	sub c
	ld c, a ; c = 14 - EVASIONMOD (this "reflects" the value over 7, so that an increase in the target's evasion
	       ; decreases the hit chance instead of increasing the hit chance)
; zero the high bytes of the multiplicand
;> hMultiplicand[0:3] = [0, 0, mem[accuracy]]
	xor a
	ldh [hMultiplicand], a
	ldh [hMultiplicand + 1], a
	ld a, [hl]
	ldh [hMultiplicand + 2], a ; set multiplicand to move accuracy
;>@mods for mod in mods:
	push hl
	ld d, $02 ; loop has two iterations
; loop to do the calculations, the first iteration multiplies by the accuracy ratio and
; the second iteration multiplies by the evasion ratio
.loop
;>     ratio = StatModifierRatios
	push bc
	ld hl, StatModifierRatios  ; stat modifier ratios
;>     ratio += (mod - 1) << 1 & 0xFF                # two bytes each
	dec b
	sla b
	ld c, b
	ld b, $00
	add hl, bc ; hl = address of stat modifier ratio
	pop bc
;>     hMultiplier = mem[ratio]
;>     Multiply()
	ld a, [hli]
	ldh [hMultiplier], a ; set multiplier to the numerator of the ratio
	call Multiply
;>     hDivisor = mem[ratio + 1]
;>     Divide(4)
	ld a, [hl]
	ldh [hDivisor], a ; set divisor to the the denominator of the ratio
	                 ; (the dividend is the product of the previous multiplication)
	ld b, $04 ; number of bytes in the dividend
	call Divide
;>     if not (hQuotient[2] or hQuotient[3]):        # at least 1
	ldh a, [hQuotient + 3]
	ld b, a
	ldh a, [hQuotient + 2]
	or b
	jp nz, .nextCalculation
;>         hQuotient[2], hQuotient[3] = 0, 1
; make sure the result is always at least one
	ldh [hQuotient + 2], a
	ld a, $01
	ldh [hQuotient + 3], a
.nextCalculation
;=@mods
	ld b, c
	dec d
	jr nz, .loop
;> big = hQuotient[2] != 0                           # over 255?
	ldh a, [hQuotient + 2]
	and a ; is the calculated hit chance over 0xFF?
;> result = hQuotient[3]
;> if big:
	ldh a, [hQuotient + 3]
	jr z, .storeAccuracy
; if calculated hit chance over 0xFF
;>     result = 0xFF                                 # at most 255
	ld a, $ff ; set the hit chance to 0xFF
.storeAccuracy
;> mem[accuracy] = result
	pop hl
	ld [hl], a ; store the hit chance in the move accuracy variable
	ret

; multiplies damage by a random percentage from ~85% to 100%
;@ path: engine/battle/core
;@ def RandomizeDamage()
;@ Multiply the damage by a random 217..255 / 255 (about 85% to 100%). Damage of 0 or 1 stays.
;@ test: hLoadedROMBank = 0x0F; wLinkState = LINK_STATE_BATTLING
RandomizeDamage:
;> if not wDamage[0]:
	ld hl, wDamage
	ld a, [hli]
	and a
	jr nz, .DamageGreaterThanOne
;>     if wDamage[1] < 2:                            # 0 or 1 stays
;>         return
	ld a, [hl]
	cp 2
	ret c ; return if damage is equal to 0 or 1
.DamageGreaterThanOne
;> hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;> hMultiplicand[1:3] = [wDamage[0], wDamage[1]]
	dec hl
	ld a, [hli]
	ldh [hMultiplicand + 1], a
	ld a, [hl]
	ldh [hMultiplicand + 2], a
; loop until a random number greater than or equal to 217 is generated
.loop
;> while True:                                       # a random 217..255 (85% of 255, plus 1)
;>     r = BattleRandom()
	call BattleRandom
;>     r = (r >> 1 | r << 7) & 0xFF
	rrca
;>     if r >= 85 * 255 // 100 + 1:
;>         break
	cp 85 * $ff / 100 + 1
	jr c, .loop
;> hMultiplier = r
;> Multiply()
	ldh [hMultiplier], a
	call Multiply ; multiply damage by the random number, which is in the range [217, 255]
;> hDivisor = 255
;> Divide(4)
	ld a, 255
	ldh [hDivisor], a
	ld b, $4
	call Divide ; divide the result by 255
; store the modified damage
;> wDamage[0] = hQuotient[2]
;> wDamage[1] = hQuotient[3]
	ldh a, [hQuotient + 2]
	ld hl, wDamage
	ld [hli], a
	ldh a, [hQuotient + 3]
	ld [hl], a
	ret

; for more detailed commentary, see equivalent function for player side (ExecutePlayerMove)
;@ path: engine/battle/core
;@ def ExecuteEnemyMove()
;@ The opponent's Pokemon takes its turn, like ExecutePlayerMove. In a link battle a received value of 4 or
;@ more (other than Struggle) means the other player switched or used an item: no move this turn.
ExecuteEnemyMove:
;> if wEnemySelectedMove == CANNOT_MOVE or PrintGhostText():
;>     return ExecuteEnemyMoveDone()
	ld a, [wEnemySelectedMove]
	ASSERT CANNOT_MOVE == $ff
	inc a
	jp z, ExecuteEnemyMoveDone
	call PrintGhostText
	jp z, ExecuteEnemyMoveDone
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .executeEnemyMove
;>     if wSerialExchangeNybbleReceiveData != LINKBATTLE_STRUGGLE and wSerialExchangeNybbleReceiveData >= 4:
;>         return
	ld b, $1
	ld a, [wSerialExchangeNybbleReceiveData]
	cp LINKBATTLE_STRUGGLE
	jr z, .executeEnemyMove
	cp 4
	ret nc
.executeEnemyMove
;> wAILayer2Encouragement += 1
	ld hl, wAILayer2Encouragement
	inc [hl]
;> wMoveMissed = 0
	xor a
	ld [wMoveMissed], a
;> wMoveDidntMiss = 0
	ld [wMoveDidntMiss], a
;> wDamageMultipliers = EFFECTIVE
	ld a, EFFECTIVE
	ld [wDamageMultipliers], a
;> can_move, continue_at = CheckEnemyStatusConditions()
	call CheckEnemyStatusConditions
;> if not can_move:
;>     return call(continue_at)
	jr nz, .enemyHasNoSpecialConditions
	jp hl
.enemyHasNoSpecialConditions
;> if wEnemyBattleStatus1 >> CHARGING_UP & 1:
;>     return EnemyCanExecuteChargingMove()
	ld hl, wEnemyBattleStatus1
	bit CHARGING_UP, [hl] ; is the enemy charging up for attack?
	jr nz, EnemyCanExecuteChargingMove ; if so, jump
;> GetCurrentMove()
;> CheckIfEnemyNeedsToChargeUp()
	call GetCurrentMove

;@ path: engine/battle/core
;@ def CheckIfEnemyNeedsToChargeUp()
;@ The first turn of an enemy two-turn move only charges up: its effect handles that turn.
CheckIfEnemyNeedsToChargeUp:
;> effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
;> if effect == CHARGE_EFFECT:
;>     return JumpMoveEffect()
	cp CHARGE_EFFECT
	jp z, JumpMoveEffect
;> if effect == FLY_EFFECT:
;>     return JumpMoveEffect()
	cp FLY_EFFECT
	jp z, JumpMoveEffect
;> EnemyCanExecuteMove()
	jr EnemyCanExecuteMove
;@ path: engine/battle/core
;@ def EnemyCanExecuteChargingMove()
;@ Second turn of an enemy two-turn move: stop charging, become reachable again and put the move's name in
;@ wStringBuffer for the "used" text.
;@ test: hLoadedROMBank = 0x0F
EnemyCanExecuteChargingMove:
;> wEnemyBattleStatus1 &= ~(1 << CHARGING_UP | 1 << INVULNERABLE)
	ld hl, wEnemyBattleStatus1
	res CHARGING_UP, [hl] ; no longer charging up for attack
	res INVULNERABLE, [hl] ; no longer invulnerable to typical attacks
;> wNameListIndex = wEnemyMoveNum
	ld a, [wEnemyMoveNum]
	ld [wNameListIndex], a
;> wPredefBank = BANK(MoveNames)
	ld a, BANK(MoveNames)
	ld [wPredefBank], a
;> wNameListType = MOVE_NAME
	ld a, MOVE_NAME
	ld [wNameListType], a
;> GetName()
	call GetName
;> CopyToStringBuffer(wNameBuffer)
;> EnemyCanExecuteMove()
	ld de, wNameBuffer
	call CopyToStringBuffer
;@ path: engine/battle/core
;@ def EnemyCanExecuteMove()
;@ Print "Enemy <MON> used <MOVE>!". Effect-only moves run their effect and stop; continuing effects run and
;@ the move goes on to deal damage. (The opponent's moves use no PP.)
EnemyCanExecuteMove:
;> wMonIsDisobedient = 0
	xor a
	ld [wMonIsDisobedient], a
;> DisplayUsedMoveText()
	call DisplayUsedMoveText
;> if IsInArray(wEnemyMoveEffect, ResidualEffects1, 1)[2]:
;>     return JumpMoveEffect()
	ld a, [wEnemyMoveEffect]
	ld hl, ResidualEffects1
	ld de, $1
	call IsInArray
	jp c, JumpMoveEffect
;> if IsInArray(wEnemyMoveEffect, SpecialEffectsCont, 1)[2]:
;>     JumpMoveEffect()
	ld a, [wEnemyMoveEffect]
	ld hl, SpecialEffectsCont
	ld de, $1
	call IsInArray
	call c, JumpMoveEffect
;> EnemyCalcMoveDamage()                             # (it follows)
;@ path: engine/battle/core
;@ def EnemyCalcMoveDamage()
;@ Damage for the enemy's move, with the levels swapped so the shared routines read the attacker's level.
;@ Fixed-damage moves only take the accuracy test; moves with no power skip both.
EnemyCalcMoveDamage:
;> SwapPlayerAndEnemyLevels()
	call SwapPlayerAndEnemyLevels
;> if IsInArray(wEnemyMoveEffect, SetDamageEffects, 1)[2]:
;>     return EnemyMoveHitTest()
	ld a, [wEnemyMoveEffect]
	ld hl, SetDamageEffects
	ld de, $1
	call IsInArray
	jp c, EnemyMoveHitTest
;> CriticalHitTest()
	call CriticalHitTest
;> if HandleCounterMove():
;>     return HandleIfEnemyMoveMissed()
	call HandleCounterMove
	jr z, HandleIfEnemyMoveMissed
;> SwapPlayerAndEnemyLevels()
	call SwapPlayerAndEnemyLevels
;> GetDamageVarsForEnemyAttack()
	call GetDamageVarsForEnemyAttack
;> SwapPlayerAndEnemyLevels()
	call SwapPlayerAndEnemyLevels
;> if CalculateDamage():
;>     return EnemyCheckIfFlyOrChargeEffect()
	call CalculateDamage
	jp z, EnemyCheckIfFlyOrChargeEffect
;> AdjustDamageForMoveType()
	call AdjustDamageForMoveType
;> RandomizeDamage()
;> EnemyMoveHitTest()
	call RandomizeDamage

;@ path: engine/battle/core
;@ def EnemyMoveHitTest()
;@ The accuracy test of the enemy's move.
EnemyMoveHitTest:
;> MoveHitTest()
;> HandleIfEnemyMoveMissed()
	call MoveHitTest
;@ path: engine/battle/core
;@ def HandleIfEnemyMoveMissed()
;@ A hit gets its animation (levels swapped back first). A miss gets none, except Explosion and Selfdestruct.
HandleIfEnemyMoveMissed:
;> if not wMoveMissed:
;>@sw     SwapPlayerAndEnemyLevels()
;>@an     GetEnemyAnimationType()
	ld a, [wMoveMissed]
	and a
	jr z, .moveDidNotMiss
;> elif wEnemyMoveEffect == EXPLODE_EFFECT:
;>     HandleExplosionMiss()
	ld a, [wEnemyMoveEffect]
	cp EXPLODE_EFFECT
	jr z, HandleExplosionMiss
;> else:
;>     EnemyCheckIfFlyOrChargeEffect()
	jr EnemyCheckIfFlyOrChargeEffect
.moveDidNotMiss
;=@sw
	call SwapPlayerAndEnemyLevels
;=@an

;@ path: engine/battle/core
;@ def GetEnemyAnimationType()
;@ How the screen reacts to the enemy's hit: a vertical shake for a plain damaging move, a heavy horizontal
;@ shake for a move with an extra effect.
GetEnemyAnimationType:
;> plain = wEnemyMoveEffect == 0                     # nothing but damage
	ld a, [wEnemyMoveEffect]
	and a
;> anim = ANIMATIONTYPE_SHAKE_SCREEN_VERTICALLY
;> if not plain:
	ld a, ANIMATIONTYPE_SHAKE_SCREEN_VERTICALLY
	jr z, PlayEnemyMoveAnimation
;>     anim = ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_HEAVY
	ld a, ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_HEAVY
;> PlayEnemyMoveAnimation(anim)
	jr PlayEnemyMoveAnimation
;@ path: engine/battle/core
;@ def HandleExplosionMiss()
;@ An enemy Explosion or Selfdestruct that missed still plays its animation (without a screen reaction).
HandleExplosionMiss:
;> SwapPlayerAndEnemyLevels()
;> PlayEnemyMoveAnimation(0)
	call SwapPlayerAndEnemyLevels
	xor a
;@ path: engine/battle/core
;@ def PlayEnemyMoveAnimation(anim_type: a)
;@ Play the enemy move's animation (its Substitute steps aside), the explosion shake, redraw the enemy HUD and
;@ go on with the move's effects.
PlayEnemyMoveAnimation:
;> if wEnemyBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>     farcall(HideSubstituteShowMonAnim)
	push af
	ld a, [wEnemyBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a ; does mon have a substitute?
	ld hl, HideSubstituteShowMonAnim
	ld b, BANK(HideSubstituteShowMonAnim)
	call nz, Bankswitch
;> wAnimationType = anim_type
	pop af
	ld [wAnimationType], a
;> PlayMoveAnimation(wEnemyMoveNum)
	ld a, [wEnemyMoveNum]
	call PlayMoveAnimation
;> HandleExplodingAnimation()
	call HandleExplodingAnimation
;> DrawEnemyHUDAndHPBar()
	call DrawEnemyHUDAndHPBar
;> if wEnemyBattleStatus2 >> HAS_SUBSTITUTE_UP & 1:
;>     farcall(ReshowSubstituteAnim)
	ld a, [wEnemyBattleStatus2]
	bit HAS_SUBSTITUTE_UP, a ; does mon have a substitute?
	ld hl, ReshowSubstituteAnim
	ld b, BANK(ReshowSubstituteAnim)
	call nz, Bankswitch ; slide the substitute's sprite out
;> EnemyCheckIfMirrorMoveEffect()
	jr EnemyCheckIfMirrorMoveEffect

;@ path: engine/battle/core
;@ def EnemyCheckIfFlyOrChargeEffect()
;@ After an enemy miss or a move without power: swap the levels back, pause half a second; the first turn of a
;@ two-turn move still shows the status animation.
EnemyCheckIfFlyOrChargeEffect:
;> SwapPlayerAndEnemyLevels()
	call SwapPlayerAndEnemyLevels
;> DelayFrames(30)
	ld c, 30
	call DelayFrames
;> if wEnemyMoveEffect in (FLY_EFFECT, CHARGE_EFFECT):
	ld a, [wEnemyMoveEffect]
	cp FLY_EFFECT
	jr z, .playAnim
	cp CHARGE_EFFECT
	jr z, .playAnim
	jr EnemyCheckIfMirrorMoveEffect
.playAnim
;>     wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>     PlayMoveAnimation(STATUS_AFFECTED_ANIM)
;> EnemyCheckIfMirrorMoveEffect()
	ld a, STATUS_AFFECTED_ANIM
	call PlayMoveAnimation
;@ path: engine/battle/core
;@ def EnemyCheckIfMirrorMoveEffect()
;@ The rest of the enemy's attack, like MirrorMoveCheck for the player: Mirror Move and Metronome, the effect,
;@ the miss or the damage with its texts, side effects, Rage, multi-hit moves and the remaining effect.
EnemyCheckIfMirrorMoveEffect:
;> if wEnemyMoveEffect == MIRROR_MOVE_EFFECT:
	ld a, [wEnemyMoveEffect]
	cp MIRROR_MOVE_EFFECT
	jr nz, .notMirrorMoveEffect
;>     if MirrorMoveCopyMove():
;>         ExecuteEnemyMoveDone()
	call MirrorMoveCopyMove
	jp z, ExecuteEnemyMoveDone
;>     else:
;>         CheckIfEnemyNeedsToChargeUp()
;>     return
	jp CheckIfEnemyNeedsToChargeUp
.notMirrorMoveEffect
;> if wEnemyMoveEffect == METRONOME_EFFECT:
	cp METRONOME_EFFECT
	jr nz, .notMetronomeEffect
;>     MetronomePickMove()
	call MetronomePickMove
;>     return CheckIfEnemyNeedsToChargeUp()
	jp CheckIfEnemyNeedsToChargeUp
.notMetronomeEffect
;> if IsInArray(wEnemyMoveEffect, ResidualEffects2, 1)[2]:
;>     return JumpMoveEffect()
	ld a, [wEnemyMoveEffect]
	ld hl, ResidualEffects2
	ld de, $1
	call IsInArray
	jp c, JumpMoveEffect
;> if wMoveMissed:
	ld a, [wMoveMissed]
	and a
	jr z, .moveDidNotMiss
;>     PrintMoveFailureText()
	call PrintMoveFailureText
;>     if wEnemyMoveEffect != EXPLODE_EFFECT:
;>         return ExecuteEnemyMoveDone()
	ld a, [wEnemyMoveEffect]
	cp EXPLODE_EFFECT
	jr z, .handleExplosionMiss
	jp ExecuteEnemyMoveDone
.moveDidNotMiss
;> else:
;>     ApplyAttackToPlayerPokemon()
	call ApplyAttackToPlayerPokemon
;>     PrintCriticalOHKOText()
	call PrintCriticalOHKOText
;>     farcall(DisplayEffectiveness)
	ld hl, DisplayEffectiveness
	ld b, BANK(DisplayEffectiveness)
	call Bankswitch
;>     wMoveDidntMiss = 1
	ld a, 1
	ld [wMoveDidntMiss], a
.handleExplosionMiss
;> if IsInArray(wEnemyMoveEffect, AlwaysHappenSideEffects, 1)[2]:
;>     JumpMoveEffect()
	ld a, [wEnemyMoveEffect]
	ld hl, AlwaysHappenSideEffects
	ld de, $1
	call IsInArray
	call c, JumpMoveEffect
;> if not (mem[wBattleMonHP] | mem[wBattleMonHP + 1]):
;>     return                        # the player's Pokemon fainted
	ld hl, wBattleMonHP
	ld a, [hli]
	ld b, [hl]
	or b
	ret z
;> HandleBuildingRage()
	call HandleBuildingRage
;> if wEnemyBattleStatus1 >> ATTACKING_MULTIPLE_TIMES & 1:
	ld hl, wEnemyBattleStatus1
	bit ATTACKING_MULTIPLE_TIMES, [hl] ; is mon hitting multiple times? (example: double kick)
	jr z, .notMultiHitMove
;>     wEnemyNumAttacksLeft -= 1
	push hl
	ld hl, wEnemyNumAttacksLeft
	dec [hl]
	pop hl
;>     if wEnemyNumAttacksLeft:
;>         return GetEnemyAnimationType()   # the next hit of a multi-hit move
	jp nz, GetEnemyAnimationType
;>     wEnemyBattleStatus1 &= ~(1 << ATTACKING_MULTIPLE_TIMES)
	res ATTACKING_MULTIPLE_TIMES, [hl] ; mon is no longer hitting multiple times
;>     PrintText(HitXTimesText)
	ld hl, HitXTimesText
	call PrintText
;>     wEnemyNumHits = 0
	xor a
	ld [wEnemyNumHits], a
.notMultiHitMove
;> if wEnemyMoveEffect and not IsInArray(wEnemyMoveEffect, SpecialEffects, 1)[2]:
	ld a, [wEnemyMoveEffect]
	and a
	jr z, ExecuteEnemyMoveDone
	ld hl, SpecialEffects
	ld de, $1
	call IsInArray
;>     JumpMoveEffect()
	call nc, JumpMoveEffect
;> ExecuteEnemyMoveDone()
	jr ExecuteEnemyMoveDone

;@ path: engine/battle/core
HitXTimesText:
	db TX_FAR
	dw _HitXTimesText
	db BANK(_HitXTimesText)
	db TX_END

;@ path: engine/battle/core
;@ def ExecuteEnemyMoveDone() -> b
;@ End of the enemy's turn. Returns b = 1.
ExecuteEnemyMoveDone:
;> return 1
	ld b, $1
	ret

; checks for various status conditions affecting the enemy mon
; stores whether the mon cannot use a move this turn in Z flag
;@ path: engine/battle/core
;@ def CheckEnemyStatusConditions() -> (zero, hl)
;@ Before the opponent's Pokemon moves: the same checks as for the player's (sleep, freeze, trapping, flinch,
;@ recharge, Disable, confusion, full paralysis, Bide, Thrash, Wrap-like moves, Rage). Zero if the turn does not
;@ go on normally; hl is then where it continues.
CheckEnemyStatusConditions:
;> if mem[wEnemyMonStatus] & SLP_MASK:
	ld hl, wEnemyMonStatus
	ld a, [hl]
	and SLP_MASK
	jr z, .checkIfFrozen
;>     mem[wEnemyMonStatus] = (mem[wEnemyMonStatus] & SLP_MASK) - 1
	dec a ; decrement number of turns left
	ld [wEnemyMonStatus], a
;>     if mem[wEnemyMonStatus]:
	and a
	jr z, .wokeUp ; if the number of turns hit 0, wake up
;>         PrintText(FastAsleepText)
	ld hl, FastAsleepText
	call PrintText
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         PlayMoveAnimation(SLP_ANIM)
	ld a, SLP_ANIM
	call PlayMoveAnimation
	jr .sleepDone
.wokeUp
;>     else:
;>         PrintText(WokeUpText)
	ld hl, WokeUpText
	call PrintText
.sleepDone
;>     wEnemyUsedMove = 0
	xor a
	ld [wEnemyUsedMove], a
;>     return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone ; enemy can't move this turn
	jp .enemyReturnToHL
.checkIfFrozen
;> if mem[wEnemyMonStatus] >> FRZ & 1:
	bit FRZ, [hl]
	jr z, .checkIfTrapped
;>     PrintText(IsFrozenText)
	ld hl, IsFrozenText
	call PrintText
;>     wEnemyUsedMove = 0
	xor a
	ld [wEnemyUsedMove], a
;>     return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone ; enemy can't move this turn
	jp .enemyReturnToHL
.checkIfTrapped
;> if wPlayerBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	ld a, [wPlayerBattleStatus1]
	bit USING_TRAPPING_MOVE, a ; is the player using a multi-turn attack like warp
	jp z, .checkIfFlinched
;>     PrintText(CantMoveText)
	ld hl, CantMoveText
	call PrintText
;>     return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone ; enemy can't move this turn
	jp .enemyReturnToHL
.checkIfFlinched
;> if wEnemyBattleStatus1 >> FLINCHED & 1:
	ld hl, wEnemyBattleStatus1
	bit FLINCHED, [hl] ; check if enemy mon flinched
	jp z, .checkIfMustRecharge
;>     wEnemyBattleStatus1 &= ~(1 << FLINCHED)
	res FLINCHED, [hl]
;>     PrintText(FlinchedText)
	ld hl, FlinchedText
	call PrintText
;>     return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone ; enemy can't move this turn
	jp .enemyReturnToHL
.checkIfMustRecharge
;> if wEnemyBattleStatus2 >> NEEDS_TO_RECHARGE & 1:
	ld hl, wEnemyBattleStatus2
	bit NEEDS_TO_RECHARGE, [hl] ; check if enemy mon has to recharge after using a move
	jr z, .checkIfAnyMoveDisabled
;>     wEnemyBattleStatus2 &= ~(1 << NEEDS_TO_RECHARGE)
	res NEEDS_TO_RECHARGE, [hl]
;>     PrintText(MustRechargeText)
	ld hl, MustRechargeText
	call PrintText
;>     return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone ; enemy can't move this turn
	jp .enemyReturnToHL
.checkIfAnyMoveDisabled
;> if wEnemyDisabledMove:
	ld hl, wEnemyDisabledMove
	ld a, [hl]
	and a
	jr z, .checkIfConfused
;>     wEnemyDisabledMove -= 1
	dec a ; decrement disable counter
	ld [hl], a
;>     if not wEnemyDisabledMove & 0xF:
	and $f ; did disable counter hit 0?
	jr nz, .checkIfConfused
;>         wEnemyDisabledMove = 0
	ld [hl], a
;>         wEnemyDisabledMoveNumber = 0
	ld [wEnemyDisabledMoveNumber], a
;>         PrintText(DisabledNoMoreText)
	ld hl, DisabledNoMoreText
	call PrintText
.checkIfConfused
;> lost_turn = False
;> if wEnemyBattleStatus1 >> CONFUSED & 1:
	ld a, [wEnemyBattleStatus1]
	add a ; check if enemy mon is confused
	jp nc, .checkIfTriedToUseDisabledMove
;>     wEnemyConfusedCounter -= 1
	ld hl, wEnemyConfusedCounter
	dec [hl]
;>     if not wEnemyConfusedCounter:
	jr nz, .isConfused
;>         wEnemyBattleStatus1 &= ~(1 << CONFUSED)
	ld hl, wEnemyBattleStatus1
	res CONFUSED, [hl] ; if confused counter hit 0, reset confusion status
;>         PrintText(ConfusedNoMoreText)
	ld hl, ConfusedNoMoreText
	call PrintText
	jp .checkIfTriedToUseDisabledMove
.isConfused
;>     else:
;>         PrintText(IsConfusedText)
	ld hl, IsConfusedText
	call PrintText
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         PlayMoveAnimation(CONF_ANIM)
	ld a, CONF_ANIM
	call PlayMoveAnimation
;>         if BattleRandom() >= 0x80:          # half the time it hurts itself: 40 power, its own Defense
	call BattleRandom
	cp $80
	jr c, .checkIfTriedToUseDisabledMove
;>             wEnemyBattleStatus1 &= 1 << CONFUSED
	ld hl, wEnemyBattleStatus1
	ld a, [hl]
	and 1 << CONFUSED ; if mon hurts itself, clear every other status from wEnemyBattleStatus1
	ld [hl], a
;>             PrintText(HurtItselfText)
	ld hl, HurtItselfText
	call PrintText
;>             saved_defense = mem[wBattleMonDefense], mem[wBattleMonDefense + 1]
	ld hl, wBattleMonDefense
	ld a, [hli]
	push af
	ld a, [hld]
	push af
;>             mem[wBattleMonDefense] = mem[wEnemyMonDefense]
	ld a, [wEnemyMonDefense]
	ld [hli], a
;>             mem[wBattleMonDefense + 1] = mem[wEnemyMonDefense + 1]
	ld a, [wEnemyMonDefense + 1]
	ld [hl], a
;>             saved_effect = wEnemyMoveEffect
	ld hl, wEnemyMoveEffect
	push hl
	ld a, [hl]
	push af
;>             wEnemyMoveEffect = 0
	xor a
	ld [hli], a
;>             wCriticalHitOrOHKO = 0
	ld [wCriticalHitOrOHKO], a
;>             wEnemyMovePower = 40
	ld a, 40
	ld [hli], a
;>             wEnemyMoveType = 0
	xor a
	ld [hl], a
;>             GetDamageVarsForEnemyAttack()
	call GetDamageVarsForEnemyAttack
;>             CalculateDamage()
	call CalculateDamage
;>             wEnemyMoveEffect = saved_effect
	pop af
	pop hl
	ld [hl], a
;>             mem[wBattleMonDefense], mem[wBattleMonDefense + 1] = saved_defense
	ld hl, wBattleMonDefense + 1
	pop af
	ld [hld], a
	pop af
	ld [hl], a
;>             wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>             hWhoseTurn = 0
	ldh [hWhoseTurn], a
;>             PlayMoveAnimation(POUND)
	ld a, POUND
	call PlayMoveAnimation
;>             hWhoseTurn = 1
	ld a, $1
	ldh [hWhoseTurn], a
;>             ApplyDamageToEnemyPokemon()
	call ApplyDamageToEnemyPokemon
;>             lost_turn = True
	jr .monHurtItselfOrFullyParalysed
.checkIfTriedToUseDisabledMove
; prevents a disabled move that was selected before being disabled from being used
;> if not lost_turn:
;>     if wEnemyDisabledMoveNumber and wEnemyDisabledMoveNumber == wEnemySelectedMove:
	ld a, [wEnemyDisabledMoveNumber]
	and a
	jr z, .checkIfParalysed
	ld hl, wEnemySelectedMove
	cp [hl]
	jr nz, .checkIfParalysed
;>         PrintMoveIsDisabledText()
	call PrintMoveIsDisabledText
;>         return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone ; if a disabled move was somehow selected, player can't move this turn
	jp .enemyReturnToHL
.checkIfParalysed
;>     if mem[wEnemyMonStatus] >> PAR & 1 and BattleRandom() < 63:   # 25%: fully paralyzed
	ld hl, wEnemyMonStatus
	bit PAR, [hl]
	jr z, .checkIfUsingBide
	call BattleRandom
	cp 25 * $ff / 100 ; chance to be fully paralysed
	jr nc, .checkIfUsingBide
;>         PrintText(FullyParalyzedText)
;>         lost_turn = True
	ld hl, FullyParalyzedText
	call PrintText
.monHurtItselfOrFullyParalysed
;> if lost_turn:
;>     wEnemyBattleStatus1 &= ~(1 << STORING_ENERGY | 1 << THRASHING_ABOUT | 1 << CHARGING_UP | 1 << USING_TRAPPING_MOVE)
	ld hl, wEnemyBattleStatus1
	ld a, [hl]
	; clear bide, thrashing about, charging up, and multi-turn moves such as warp
	and ~((1 << STORING_ENERGY) | (1 << THRASHING_ABOUT) | (1 << CHARGING_UP) | (1 << USING_TRAPPING_MOVE))
	ld [hl], a
;>     if wEnemyMoveEffect in (FLY_EFFECT, CHARGE_EFFECT):
	ld a, [wEnemyMoveEffect]
	cp FLY_EFFECT
	jr z, .flyOrChargeEffect
	cp CHARGE_EFFECT
	jr z, .flyOrChargeEffect
	jr .notFlyOrChargeEffect
.flyOrChargeEffect
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         PlayMoveAnimation(STATUS_AFFECTED_ANIM)
	ld a, STATUS_AFFECTED_ANIM
	call PlayMoveAnimation
.notFlyOrChargeEffect
;>     return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone
	jp .enemyReturnToHL ; if using a two-turn move, enemy needs to recharge the first turn
.checkIfUsingBide
;> if wEnemyBattleStatus1 >> STORING_ENERGY & 1:               # Bide
	ld hl, wEnemyBattleStatus1
	bit STORING_ENERGY, [hl] ; is mon using bide?
	jr z, .checkIfThrashingAbout
;>     wEnemyMoveNum = 0
	xor a
	ld [wEnemyMoveNum], a
;>     damage = wDamage[0] << 8 | wDamage[1]
	ld hl, wDamage
	ld a, [hli]
	ld b, a
	ld c, [hl]
;>     stored = (wEnemyBideAccumulatedDamage[0] << 8 | wEnemyBideAccumulatedDamage[1]) + damage
;>     wEnemyBideAccumulatedDamage[1] = stored & 0xFF
	ld hl, wEnemyBideAccumulatedDamage + 1
	ld a, [hl]
	add c ; accumulate damage taken
	ld [hld], a
;>     wEnemyBideAccumulatedDamage[0] = stored >> 8 & 0xFF
	ld a, [hl]
	adc b
	ld [hl], a
;>     wEnemyNumAttacksLeft -= 1
	ld hl, wEnemyNumAttacksLeft
	dec [hl] ; did Bide counter hit 0?
;>     if wEnemyNumAttacksLeft:
	jr z, .unleashEnergy
;>         return True, addr(ExecuteEnemyMoveDone)
	ld hl, ExecuteEnemyMoveDone
	jp .enemyReturnToHL ; unless mon unleashes energy, can't move this turn
.unleashEnergy
;>     wEnemyBattleStatus1 &= ~(1 << STORING_ENERGY)
	ld hl, wEnemyBattleStatus1
	res STORING_ENERGY, [hl] ; not using bide any more
;>     PrintText(UnleashedEnergyText)
	ld hl, UnleashedEnergyText
	call PrintText
;>     wEnemyMovePower = 1
	ld a, $1
	ld [wEnemyMovePower], a
;>     damage = stored * 2 & 0xFFFF                  # twice the damage taken
	ld hl, wEnemyBideAccumulatedDamage + 1
	ld a, [hld]
	add a
	ld b, a
;>     wDamage[1] = damage & 0xFF
	ld [wDamage + 1], a
;>     wDamage[0] = damage >> 8
	ld a, [hl]
	rl a ; double the damage
	ld [wDamage], a
;>     if not damage:
	or b
	jr nz, .next
;>         wMoveMissed = 1
	ld a, $1
	ld [wMoveMissed], a
.next
;>     wEnemyBideAccumulatedDamage[0] = 0
;>     wEnemyBideAccumulatedDamage[1] = 0
	xor a
	ld [hli], a
	ld [hl], a
;>     wEnemyMoveNum = BIDE
	ld a, BIDE
	ld [wEnemyMoveNum], a
;>     SwapPlayerAndEnemyLevels()
	call SwapPlayerAndEnemyLevels
;>     return True, addr(HandleIfEnemyMoveMissed)
	ld hl, HandleIfEnemyMoveMissed ; skip damage calculation, DecrementPP and MoveHitTest
	jp .enemyReturnToHL
.checkIfThrashingAbout
;> if wEnemyBattleStatus1 >> THRASHING_ABOUT & 1:
	bit THRASHING_ABOUT, [hl] ; is mon using thrash or petal dance?
	jr z, .checkIfUsingMultiturnMove
;>     wEnemyMoveNum = THRASH
	ld a, THRASH
	ld [wEnemyMoveNum], a
;>     PrintText(ThrashingAboutText)
	ld hl, ThrashingAboutText
	call PrintText
;>     wEnemyNumAttacksLeft -= 1
	ld hl, wEnemyNumAttacksLeft
	dec [hl] ; did Thrashing About counter hit 0?
;>     if not wEnemyNumAttacksLeft:
	ld hl, EnemyCalcMoveDamage ; skip DecrementPP
	jp nz, .enemyReturnToHL
;>         wEnemyBattleStatus1 = wEnemyBattleStatus1 & ~(1 << THRASHING_ABOUT) | 1 << CONFUSED
	push hl
	ld hl, wEnemyBattleStatus1
	res THRASHING_ABOUT, [hl] ; mon is no longer using thrash or petal dance
	set CONFUSED, [hl] ; mon is now confused
;>         wEnemyConfusedCounter = (BattleRandom() & 3) + 2
	call BattleRandom
	and $3
	inc a
	inc a ; confused for 2-5 turns
	ld [wEnemyConfusedCounter], a
;>     return True, addr(EnemyCalcMoveDamage)
	pop hl ; skip DecrementPP
	jp .enemyReturnToHL
.checkIfUsingMultiturnMove
;> if wEnemyBattleStatus1 >> USING_TRAPPING_MOVE & 1:
	bit USING_TRAPPING_MOVE, [hl] ; is mon using multi-turn move?
	jp z, .checkIfUsingRage
;>     PrintText(AttackContinuesText)
	ld hl, AttackContinuesText
	call PrintText
;>     wEnemyNumAttacksLeft -= 1
	ld hl, wEnemyNumAttacksLeft
	dec [hl]
;>     return True, addr(GetEnemyAnimationType)
	ld hl, GetEnemyAnimationType ; skip damage calculation (deal damage equal to last hit),
	                             ; DecrementPP and MoveHitTest
	jp nz, .enemyReturnToHL ; redundant leftover code, the case wEnemyNumAttacksLeft == 0
							; is handled within CheckNumAttacksLeft
	jp .enemyReturnToHL
.checkIfUsingRage
;> if wEnemyBattleStatus2 >> USING_RAGE & 1:
	ld a, [wEnemyBattleStatus2]
	bit USING_RAGE, a ; is mon using rage?
	jp z, .checkEnemyStatusConditionsDone ; if we made it this far, mon can move normally this turn
;>     wNamedObjectIndex = RAGE
	ld a, RAGE
	ld [wNamedObjectIndex], a
;>     CopyToStringBuffer(GetMoveName())
	call GetMoveName
	call CopyToStringBuffer
;>     wEnemyMoveEffect = 0
	xor a
	ld [wEnemyMoveEffect], a
;>     return True, addr(EnemyCanExecuteMove)
	ld hl, EnemyCanExecuteMove
	jp .enemyReturnToHL
.enemyReturnToHL
	xor a ; set Z flag
	ret
.checkEnemyStatusConditionsDone
;> return False, addr(wEnemyBattleStatus1)                   # (hl is not used then)
	ld a, $1
	and a ; clear Z flag
	ret

;@ path: engine/battle/core
;@ def GetCurrentMove()
;@ Load the data of the move the attacker selected (from Moves) into its move variables and its name into
;@ wStringBuffer. A debug test battle takes the player's move from wTestBattlePlayerSelectedMove.
;@ test: hLoadedROMBank = 0x0F; wPlayerSelectedMove = rand(1, NUM_ATTACKS); wEnemySelectedMove = rand(1, NUM_ATTACKS); wTestBattlePlayerSelectedMove = rand(1, NUM_ATTACKS)
GetCurrentMove:
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jp z, .player
;>     dest, move = addr(wEnemyMoveNum), wEnemySelectedMove
	ld de, wEnemyMoveNum
	ld a, [wEnemySelectedMove]
	jr .selected
.player
;> else:
;>     dest = addr(wPlayerMoveNum)
	ld de, wPlayerMoveNum
	; Apply InitBattleVariables to TestBattle.
;>     move = wTestBattlePlayerSelectedMove if wStatusFlags7 >> BIT_TEST_BATTLE & 1 else wPlayerSelectedMove
	ld a, [wStatusFlags7]
	bit BIT_TEST_BATTLE, a
	ld a, [wTestBattlePlayerSelectedMove]
	jr nz, .selected
	ld a, [wPlayerSelectedMove]
.selected
;> wNameListIndex = move
	ld [wNameListIndex], a
;> src = Moves + ((move - 1) & 0xFF) * MOVE_LENGTH
	dec a
	ld hl, Moves
	ld bc, MOVE_LENGTH
	call AddNTimes
;> FarCopyData(BANK(Moves), src, dest, MOVE_LENGTH)
	ld a, BANK(Moves)
	call FarCopyData

;> wPredefBank = BANK(MoveNames)
	ld a, BANK(MoveNames)
	ld [wPredefBank], a
;> wNameListType = MOVE_NAME
	ld a, MOVE_NAME
	ld [wNameListType], a
;> GetName()
	call GetName
;> CopyToStringBuffer(wNameBuffer)
	ld de, wNameBuffer
	jp CopyToStringBuffer

;@ path: engine/battle/core
;@ def LoadEnemyMonData()
;@ Build the opponent's battle Pokemon wEnemyMonSpecies2 at level wCurEnemyLevel: DVs (random for wild
;@ Pokemon, fixed for trainers', kept through Transform), stats, HP and status (full and healthy in the wild,
;@ from the party for trainers), types, catch rate, moves (the trainer's, or the four last learned by that
;@ level), PP, base stats and experience, name; mark it as seen in the Pokedex. A link battle loads the party
;@ data instead.
;@ test: skip loads the Pokemon's header and pictures from other banks
LoadEnemyMonData:
;> if wLinkState == LINK_STATE_BATTLING:
;>     return LoadEnemyMonFromParty()
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jp z, LoadEnemyMonFromParty
;> mem[wEnemyMonSpecies] = wEnemyMonSpecies2
	ld a, [wEnemyMonSpecies2]
	ld [wEnemyMonSpecies], a
;> wCurSpecies = wEnemyMonSpecies2
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> transformed = wEnemyBattleStatus3 >> TRANSFORMED & 1
	ld a, [wEnemyBattleStatus3]
	bit TRANSFORMED, a ; is enemy mon transformed?
;> if transformed:
;>     dvs = wTransformedEnemyMonOriginalDVs[0], wTransformedEnemyMonOriginalDVs[1]
	ld hl, wTransformedEnemyMonOriginalDVs ; original DVs before transforming
	ld a, [hli]
	ld b, [hl]
	jr nz, .storeDVs
;> elif wIsInBattle == TRAINER_BATTLE:
	ld a, [wIsInBattle]
	cp TRAINER_BATTLE
; fixed DVs for trainer mon
;>     dvs = ATKDEFDV_TRAINER, SPDSPCDV_TRAINER
	ld a, ATKDEFDV_TRAINER
	ld b, SPDSPCDV_TRAINER
	jr z, .storeDVs
; random DVs for wild mon
;> else:
;>     spd_spc = BattleRandom()
	call BattleRandom
;>     dvs = BattleRandom(), spd_spc
	ld b, a
	call BattleRandom
.storeDVs
;> mem[wEnemyMonDVs], mem[wEnemyMonDVs + 1] = dvs
	ld hl, wEnemyMonDVs
	ld [hli], a
	ld [hl], b
;> mem[wEnemyMonLevel] = wCurEnemyLevel
	ld de, wEnemyMonLevel
	ld a, [wCurEnemyLevel]
	ld [de], a
;> CalcStats(wEnemyMonLevel + 1, 0, wEnemyMonHP)
	inc de
	ld b, $0
	ld hl, wEnemyMonHP
	push hl
	call CalcStats
	pop hl
;> if wIsInBattle == TRAINER_BATTLE:                 # a trainer's: HP and status from its party data
;>@php     party_hp = wEnemyMon1HP + wWhichPokemon * (wEnemyMon2 - wEnemyMon1)
;>@hp     mem[wEnemyMonHP], mem[wEnemyMonHP + 1] = mem[party_hp], mem[party_hp + 1]
;>@pos     mem[wEnemyMonPartyPos] = wWhichPokemon
;>@st     mem[wEnemyMonStatus] = mem[party_hp + 3]
	ld a, [wIsInBattle]
	cp TRAINER_BATTLE
	jr z, .copyHPAndStatusFromPartyData
;> elif not transformed:
	ld a, [wEnemyBattleStatus3]
	bit TRANSFORMED, a ; is enemy mon transformed?
	jr nz, .copyTypes ; if transformed, jump
; if it's a wild mon and not transformed, init the current HP to max HP and the status to 0
;>     mem[wEnemyMonHP] = mem[wEnemyMonMaxHP]
	ld a, [wEnemyMonMaxHP]
	ld [hli], a
;>     mem[wEnemyMonHP + 1] = mem[wEnemyMonMaxHP + 1]
	ld a, [wEnemyMonMaxHP+1]
	ld [hli], a
;>     mem[wEnemyMonStatus] = 0
	xor a
	inc hl
	ld [hl], a ; init status to 0
	jr .copyTypes
; if it's a trainer mon, copy the HP and status from the enemy party data
.copyHPAndStatusFromPartyData
;=@php
	ld hl, wEnemyMon1HP
	ld a, [wWhichPokemon]
	ld bc, wEnemyMon2 - wEnemyMon1
	call AddNTimes
;=@hp
	ld a, [hli]
	ld [wEnemyMonHP], a
	ld a, [hli]
	ld [wEnemyMonHP + 1], a
;=@pos
	ld a, [wWhichPokemon]
	ld [wEnemyMonPartyPos], a
;=@st
	inc hl
	ld a, [hl]
	ld [wEnemyMonStatus], a
	jr .copyTypes
.copyTypes
;> mem[wEnemyMonType] = mem[addr(wMonHTypes)]       # type 1
	ld hl, wMonHTypes
	ld de, wEnemyMonType
	ld a, [hli]            ; copy type 1
	ld [de], a
	inc de
;> mem[wEnemyMonType + 1] = mem[addr(wMonHTypes) + 1]   # type 2
	ld a, [hli]            ; copy type 2
	ld [de], a
	inc de
;> mem[wEnemyMonType + 2] = mem[addr(wMonHTypes) + 2]   # and the catch rate
	ld a, [hli]            ; copy catch rate
	ld [de], a
	inc de
;> if wIsInBattle == TRAINER_BATTLE:
	ld a, [wIsInBattle]
	cp TRAINER_BATTLE
	jr nz, .copyStandardMoves
; if it's a trainer battle, copy moves from enemy party data
;>     moves = wEnemyMon1Moves + wWhichPokemon * PARTYMON_STRUCT_LENGTH
	ld hl, wEnemyMon1Moves
	ld a, [wWhichPokemon]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     CopyData(moves, wEnemyMonMoves, NUM_MOVES)
	ld bc, NUM_MOVES
	call CopyData
	jr .loadMovePPs
.copyStandardMoves
; for a wild mon, first copy default moves from the mon header
;> else:                                             # a wild one: the header's moves first
;>     mem[wEnemyMonMoves] = mem[wMonHMoves]
	ld hl, wMonHMoves
	ld a, [hli]
	ld [de], a
	inc de
;>     mem[wEnemyMonMoves + 1] = mem[wMonHMoves + 1]
	ld a, [hli]
	ld [de], a
	inc de
;>     mem[wEnemyMonMoves + 2] = mem[wMonHMoves + 2]
	ld a, [hli]
	ld [de], a
	inc de
;>     mem[wEnemyMonMoves + 3] = mem[wMonHMoves + 3]
	ld a, [hl]
	ld [de], a
	dec de
	dec de
	dec de
;>     wLearningMovesFromDayCare = 0
	xor a
	ld [wLearningMovesFromDayCare], a
	; get moves based on current level
;>     predef(WriteMonMoves, hl=wMonHMoves + 3, de=wEnemyMonMoves)
	ld a, (WriteMonMovesPredef - PredefPointers) / 3
	call Predef
.loadMovePPs
;> predef(LoadMovePPs, hl=wEnemyMonMoves, de=wEnemyMonPP - 1)
	ld hl, wEnemyMonMoves
	ld de, wEnemyMonPP - 1
	ld a, (LoadMovePPsPredef - PredefPointers) / 3
	call Predef
;>@bs for i in range(NUM_STATS):
	ld hl, wMonHBaseStats
	ld de, wEnemyMonBaseStats
	ld b, NUM_STATS
.copyBaseStatsLoop
;>     mem[wEnemyMonBaseStats + i] = mem[addr(wMonHBaseStats) + i]
	ld a, [hli]
	ld [de], a
	inc de
;=@bs
	dec b
	jr nz, .copyBaseStatsLoop
;> mem[wEnemyMonBaseStats + NUM_STATS] = wMonHCatchRate
	ld hl, wMonHCatchRate
	ld a, [hli]
	ld [de], a
	inc de
;> mem[wEnemyMonBaseStats + NUM_STATS + 1] = mem[addr(wMonHCatchRate) + 1]   # base experience
	ld a, [hl]     ; base exp
	ld [de], a
;> wNamedObjectIndex = wEnemyMonSpecies2
	ld a, [wEnemyMonSpecies2]
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> CopyData(wNameBuffer, wEnemyMonNick, NAME_LENGTH)
	ld hl, wNameBuffer
	ld de, wEnemyMonNick
	ld bc, NAME_LENGTH
	call CopyData
;> wPokedexNum = wEnemyMonSpecies2
	ld a, [wEnemyMonSpecies2]
	ld [wPokedexNum], a
;> predef(IndexToPokedex)
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> flag = FLAG_SET << 8 | (wPokedexNum - 1) & 0xFF   # seen in the Pokedex
	ld a, [wPokedexNum]
	dec a
	ld c, a
	ld b, FLAG_SET
;> predef(FlagActionPredef, hl=wPokedexSeen, bc=flag)
	ld hl, wPokedexSeen
	; mark this mon as seen in the pokedex
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> CopyData(wEnemyMonLevel, addr(wEnemyMonUnmodifiedLevel), 1 + NUM_STATS * 2)
	ld hl, wEnemyMonLevel
	ld de, wEnemyMonUnmodifiedLevel
	ld bc, 1 + NUM_STATS * 2
	call CopyData
;>@sm for i in range(NUM_STAT_MODS):
	ld a, $7 ; default stat mod
	ld b, NUM_STAT_MODS ; number of stat mods
	ld hl, wEnemyMonStatMods
.statModLoop
;>     mem[wEnemyMonStatMods + i] = 7                # the neutral stage
	ld [hli], a
;=@sm
	dec b
	jr nz, .statModLoop
	ret

; calls BattleTransition to show the battle transition animation and initializes some battle variables
;@ path: engine/battle/core
;@ def DoBattleTransitionAndInitBattleVariables()
;@ The transition into the battle (after the "versus" box in a link battle), the battle HUD tiles, a clear screen
;@ and fresh player battle effects.
;@ test: skip plays the battle transition
DoBattleTransitionAndInitBattleVariables:
;> if wLinkState == LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr nz, .next
; link battle
;>     wMenuJoypadPollCount = 0
	xor a
	ld [wMenuJoypadPollCount], a
;>     farcall(DisplayLinkBattleVersusTextBox)
	ld hl, DisplayLinkBattleVersusTextBox
	ld b, BANK(DisplayLinkBattleVersusTextBox)
	call Bankswitch
;>     wUpdateSpritesEnabled = 1
	ld a, $1
	ld [wUpdateSpritesEnabled], a
;>     ClearScreen()
	call ClearScreen
.next
;> DelayFrame()
	call DelayFrame
;> predef(BattleTransition)
	ld a, (BattleTransitionPredef - PredefPointers) / 3
	call Predef
;> LoadHudAndHpBarAndStatusTilePatterns()
	ld hl, LoadHudAndHpBarAndStatusTilePatterns
	ld b, BANK(LoadHudAndHpBarAndStatusTilePatterns)
	call Bankswitch
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> ClearSprites()
	call ClearSprites
;> ClearScreen()
	call ClearScreen
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> hWY = 0
	ldh [hWY], a
;> rWY = 0
	ldh [rWY], a
;> hTileAnimations = 0
	ldh [hTileAnimations], a
;> fill(addr(wPlayerStatsToDouble), 0, 5)
	ld hl, wPlayerStatsToDouble
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wPlayerDisabledMove = 0
	ld [wPlayerDisabledMove], a
	ret

; swaps the level values of the BattleMon and EnemyMon structs
;@ path: engine/battle/core
;@ def SwapPlayerAndEnemyLevels()
;@ Swap the levels of the two Pokemon in battle.
SwapPlayerAndEnemyLevels:
;> mine = mem[wBattleMonLevel]
	push bc
	ld a, [wBattleMonLevel]
	ld b, a
;> mem[wBattleMonLevel] = mem[wEnemyMonLevel]
	ld a, [wEnemyMonLevel]
	ld [wBattleMonLevel], a
;> mem[wEnemyMonLevel] = mine
	ld a, b
	ld [wEnemyMonLevel], a
	pop bc
	ret

; loads either red back pic or old man back pic
; also writes OAM data and loads tile patterns for the Red or Old Man back sprite's head
; (for use when scrolling the player sprite and enemy's silhouettes on screen)
;@ path: engine/battle/core
;@ def LoadPlayerBackPic()
;@ Load the back picture of the player (or the old man in his demonstration), scaled up by two. Its top three
;@ rows also become 21 sprites (7 columns of 3) for the head that slides in separately at the start of the
;@ battle; the picture is copied through the cartridge RAM sprite buffer and put on screen at coord(1, 5).
;@ test: skip decompresses and copies to VRAM
LoadPlayerBackPic:
;> src = OldManPicBack if wBattleType == BATTLE_TYPE_OLD_MAN else RedPicBack
	ld a, [wBattleType]
	dec a ; is it the old man tutorial?
	ld de, RedPicBack
	jr nz, .next
	ld de, OldManPicBack
.next
;> UncompressSpriteFromDE(BANK(RedPicBack), src)
	ld a, BANK(RedPicBack)
	ASSERT BANK(RedPicBack) == BANK(OldManPicBack)
	call UncompressSpriteFromDE
;> predef(ScaleSpriteByTwo)
	ld a, (ScaleSpriteByTwoPredef - PredefPointers) / 3
	call Predef
;> hOAMTile = 0
;> o = wShadowOAM
	ld hl, wShadowOAM
	xor a
	ldh [hOAMTile], a ; initial tile number
;>@col for col in range(7):
	ld b, $7 ; 7 columns
	ld e, $a0 ; X for the left-most column
.loop ; each loop iteration writes 3 OAM entries in a vertical column
;>     for row in range(3):
	ld c, $3 ; 3 tiles per column
	ld d, $38 ; Y for the top of each column
.innerLoop ; each loop iteration writes 1 OAM entry in the column
;>         mem[o] = 0x38 + row * TILE_HEIGHT         # Y
	ld [hl], d ; OAM Y
;>         mem[o + 1] = 0xA0 + col * TILE_WIDTH      # X
	inc hl
	ld [hl], e ; OAM X
	ld a, TILE_HEIGHT
	add d ; increase Y by height of tile
	ld d, a
	inc hl
;>         mem[o + 2] = hOAMTile
	ldh a, [hOAMTile]
	ld [hli], a ; OAM tile number
;>         hOAMTile += 1
	inc a ; increment tile number
	ldh [hOAMTile], a
;>         o += OBJ_SIZE
	inc hl
	dec c
	jr nz, .innerLoop
;>     hOAMTile += 4
	ldh a, [hOAMTile]
	add $4 ; increase tile number by 4
	ldh [hOAMTile], a
;=@col
	ld a, TILE_WIDTH
	add e ; increase X by width of tile
	ld e, a
	dec b
	jr nz, .loop
;> InterlaceMergeSpriteBuffers(vBackPic)
	ld de, vBackPic
	call InterlaceMergeSpriteBuffers
;> mem[rRAMG] = RAMG_SRAM_ENABLE
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
;> mem[rRAMB] = 0
	xor a
	ld [rRAMB], a
;> CopyVideoData(vSprites, sSpriteBuffer1, hLoadedROMBank, PIC_SIZE)
	ld hl, vSprites
	ld de, sSpriteBuffer1
	ldh a, [hLoadedROMBank]
	ld b, a
	ld c, PIC_SIZE
	call CopyVideoData
;> mem[rRAMG] = 0
	xor a
	ld [rRAMG], a
;> hStartTileID = 0x31
	ld a, $31
	ldh [hStartTileID], a
;> predef(CopyUncompressedPicToTilemap, hl=coord(1, 5))
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld a, (CopyUncompressedPicToTilemapPredef - PredefPointers) / 3
	jp Predef

; does nothing since no stats are ever selected (barring glitches)
;@ path: engine/battle/core
;@ def DoubleOrHalveSelectedStats()
;@ Run DoubleSelectedStats, then HalveSelectedStats (unused).
;@ test: hLoadedROMBank = 0x0F
DoubleOrHalveSelectedStats:
;> farcall(DoubleSelectedStats)
;> farcall(HalveSelectedStats)
	ld hl, DoubleSelectedStats
	ld b, BANK(DoubleSelectedStats)
	call Bankswitch
	ld hl, HalveSelectedStats
	ld b, BANK(HalveSelectedStats)
	jp Bankswitch

;@ path: engine/battle/core
;@ def ScrollTrainerPicAfterBattle()
;@ Slide the opponent trainer's picture back onto the screen after the battle.
;@ test: hLoadedROMBank = 0x0F
ScrollTrainerPicAfterBattle:
;> farcall(_ScrollTrainerPicAfterBattle)
	ld hl, _ScrollTrainerPicAfterBattle
	ld b, BANK(_ScrollTrainerPicAfterBattle)
	jp Bankswitch

;@ path: engine/battle/core
;@ def ApplyBurnAndParalysisPenaltiesToPlayer()
;@ Apply paralysis and burn to the player's Pokemon's stats (as on the enemy's turn).
ApplyBurnAndParalysisPenaltiesToPlayer:
;> ApplyBurnAndParalysisPenalties(1)
	ld a, $1
	jr ApplyBurnAndParalysisPenalties

;@ path: engine/battle/core
;@ def ApplyBurnAndParalysisPenaltiesToEnemy()
;@ Apply paralysis and burn to the enemy Pokemon's stats (as on the player's turn).
ApplyBurnAndParalysisPenaltiesToEnemy:
;> ApplyBurnAndParalysisPenalties(0)
	xor a

;@ path: engine/battle/core
;@ def ApplyBurnAndParalysisPenalties(turn: a)
;@ Quarter Speed for paralysis and halve Attack for a burn, for the Pokemon whose turn it is not.
ApplyBurnAndParalysisPenalties:
;> hWhoseTurn = turn
	ldh [hWhoseTurn], a
;> QuarterSpeedDueToParalysis()
	call QuarterSpeedDueToParalysis
;> HalveAttackDueToBurn()
	jp HalveAttackDueToBurn

;@ path: engine/battle/core
;@ def QuarterSpeedDueToParalysis()
;@ Paralysis quarters the Speed of the Pokemon whose turn it is not (at least 1).
QuarterSpeedDueToParalysis:
;> if hWhoseTurn:                                    # the player's Pokemon
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
; enemy's turn, quarter the player's speed
;>     status, speed = wBattleMonStatus, wBattleMonSpeed
;=@par
	ld a, [wBattleMonStatus]
	and 1 << PAR
	ret z ; return if player not paralysed
;=@v
	ld hl, wBattleMonSpeed + 1
	ld a, [hld]
	ld b, a
	ld a, [hl]
;=@v2
	srl a
	rr b
	srl a
	rr b
;=@hi
	ld [hli], a
;=@lo
	or b
	jr nz, .storePlayerSpeed
	ld b, 1 ; give the player a minimum of at least one speed point
.storePlayerSpeed
	ld [hl], b
	ret
.playerTurn ; quarter the enemy's speed
;> else:                                             # the enemy's
;>     status, speed = wEnemyMonStatus, wEnemyMonSpeed
;>@par if not mem[status] & 1 << PAR:
;>     return
	ld a, [wEnemyMonStatus]
	and 1 << PAR
	ret z ; return if enemy not paralysed
;>@v v = mem[speed] << 8 | mem[speed + 1]
	ld hl, wEnemyMonSpeed + 1
	ld a, [hld]
	ld b, a
	ld a, [hl]
;>@v2 v >>= 2                                       # a quarter
	srl a
	rr b
	srl a
	rr b
;>@hi mem[speed] = v >> 8
	ld [hli], a
;>@lo mem[speed + 1] = v & 0xFF if v else 1         # at least 1
	or b
	jr nz, .storeEnemySpeed
	ld b, 1 ; give the enemy a minimum of at least one speed point
.storeEnemySpeed
	ld [hl], b
	ret

;@ path: engine/battle/core
;@ def HalveAttackDueToBurn()
;@ A burn halves the Attack of the Pokemon whose turn it is not (at least 1).
HalveAttackDueToBurn:
;> if hWhoseTurn:                                    # the player's Pokemon
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
; enemy's turn, halve the player's attack
;>     status, attack = wBattleMonStatus, wBattleMonAttack
;=@brn
	ld a, [wBattleMonStatus]
	and 1 << BRN
	ret z ; return if player not burnt
;=@v
	ld hl, wBattleMonAttack + 1
	ld a, [hld]
	ld b, a
	ld a, [hl]
	srl a
	rr b
;=@hi
	ld [hli], a
;=@lo
	or b
	jr nz, .storePlayerAttack
	ld b, 1 ; give the player a minimum of at least one attack point
.storePlayerAttack
	ld [hl], b
	ret
.playerTurn ; halve the enemy's attack
;> else:                                             # the enemy's
;>     status, attack = wEnemyMonStatus, wEnemyMonAttack
;>@brn if not mem[status] & 1 << BRN:
;>     return
	ld a, [wEnemyMonStatus]
	and 1 << BRN
	ret z ; return if enemy not burnt
;>@v v = (mem[attack] << 8 | mem[attack + 1]) >> 1
	ld hl, wEnemyMonAttack + 1
	ld a, [hld]
	ld b, a
	ld a, [hl]
	srl a
	rr b
;>@hi mem[attack] = v >> 8
	ld [hli], a
;>@lo mem[attack + 1] = v & 0xFF if v else 1        # at least 1
	or b
	jr nz, .storeEnemyAttack
	ld b, 1 ; give the enemy a minimum of at least one attack point
.storeEnemyAttack
	ld [hl], b
	ret

;@ path: engine/battle/core
;@ def CalculateModifiedStats()
;@ Recalculate Attack, Defense, Speed and Special from the unmodified stats and the stat stages.
;@ test: hLoadedROMBank = 0x0F
;@ test: wPlayerMonAttackMod = rand(1, 13); wPlayerMonDefenseMod = rand(1, 13); wPlayerMonSpeedMod = rand(1, 13); wPlayerMonSpecialMod = rand(1, 13)
;@ test: wEnemyMonAttackMod = rand(1, 13); wEnemyMonDefenseMod = rand(1, 13); wEnemyMonSpeedMod = rand(1, 13); wEnemyMonSpecialMod = rand(1, 13)
CalculateModifiedStats:
;>@st for stat in range(NUM_STATS - 1):
	ld c, 0
.loop
;>     CalculateModifiedStat(stat)
	call CalculateModifiedStat
;=@st
	inc c
	ld a, c
	cp NUM_STATS - 1
	jr nz, .loop
	ret

; calculate modified stat for stat c (0 = attack, 1 = defense, 2 = speed, 3 = special)
;@ path: engine/battle/core
;@ def CalculateModifiedStat(stat: c)
;@ One stat (0 Attack, 1 Defense, 2 Speed, 3 Special) of the player's or the enemy's Pokemon
;@ (wCalculateWhoseStats): the unmodified stat times the ratio for its stage (StatModifierRatios), at most
;@ 999 and at least 1.
;@ test: stat = rand(0, 3); hLoadedROMBank = 0x0F
;@ test: wPlayerMonAttackMod = rand(1, 13); wPlayerMonDefenseMod = rand(1, 13); wPlayerMonSpeedMod = rand(1, 13); wPlayerMonSpecialMod = rand(1, 13)
;@ test: wEnemyMonAttackMod = rand(1, 13); wEnemyMonDefenseMod = rand(1, 13); wEnemyMonSpeedMod = rand(1, 13); wEnemyMonSpecialMod = rand(1, 13)
CalculateModifiedStat:
;> player = wCalculateWhoseStats == 0
	push bc
	push bc
	ld a, [wCalculateWhoseStats]
	and a
;> stats, unmodified, mods = wBattleMonAttack, wPlayerMonUnmodifiedAttack, addr(wPlayerMonStatMods)
	ld a, c
	ld hl, wBattleMonAttack
	ld de, wPlayerMonUnmodifiedAttack
	ld bc, wPlayerMonStatMods
;> if not player:
	jr z, .next
;>     stats, unmodified, mods = wEnemyMonAttack, wEnemyMonUnmodifiedAttack, addr(wEnemyMonStatMods)
	ld hl, wEnemyMonAttack
	ld de, wEnemyMonUnmodifiedAttack
	ld bc, wEnemyMonStatMods
.next
;> entry = mods + stat
	add c
	ld c, a
	jr nc, .noCarry1
	inc b
.noCarry1
;> stage = mem[entry]
	ld a, [bc]
	pop bc
	ld b, a
;> dest = stats + 2 * stat
	push bc
	sla c
	ld b, 0
	add hl, bc
;> src = unmodified + 2 * stat
	ld a, c
	add e
	ld e, a
	jr nc, .noCarry2
	inc d
.noCarry2
;> ratio = StatModifierRatios
	pop bc
	push hl
	ld hl, StatModifierRatios
;> ratio += 2 * (stage - 1)                          # two bytes each
	dec b
	sla b
	ld c, b
	ld b, 0
	add hl, bc
;> hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;> hMultiplicand[1:3] = [mem[src], mem[src + 1]]
	ld a, [de]
	ldh [hMultiplicand + 1], a
	inc de
	ld a, [de]
	ldh [hMultiplicand + 2], a
;> hMultiplier = mem[ratio]
;> Multiply()
	ld a, [hli]
	ldh [hMultiplier], a
	call Multiply
;> hDivisor = mem[ratio + 1]
;> Divide(4)
	ld a, [hl]
	ldh [hDivisor], a
	ld b, $4
	call Divide
;> value = hDividend[2] << 8 | hDividend[3]
;> if value >= MAX_STAT_VALUE:                       # at most 999
	pop hl
	ldh a, [hDividend + 3]
	sub LOW(MAX_STAT_VALUE)
	ldh a, [hDividend + 2]
	sbc HIGH(MAX_STAT_VALUE)
	jp c, .storeNewStatValue
; cap the stat at MAX_STAT_VALUE (999)
;>     value = MAX_STAT_VALUE
;>     hDividend[2], hDividend[3] = value >> 8, value & 0xFF
	ld a, HIGH(MAX_STAT_VALUE)
	ldh [hDividend + 2], a
	ld a, LOW(MAX_STAT_VALUE)
	ldh [hDividend + 3], a
.storeNewStatValue
;> mem[dest] = value >> 8
	ldh a, [hDividend + 2]
	ld [hli], a
	ld b, a
;> mem[dest + 1] = value & 0xFF
	ldh a, [hDividend + 3]
	ld [hl], a
;> if not value:
;>     mem[dest + 1] = 1                             # at least 1
	or b
	jr nz, .done
	inc [hl] ; if the stat is 0, bump it up to 1
.done
	pop bc
	ret

;@ path: engine/battle/core
;@ def ApplyBadgeStatBoosts()
;@ The Boulder, Thunder, Soul and Volcano Badges each raise one of the player's Pokemon's stats by 1/8 (at most
;@ 999): Attack, Defense, Speed and Special. Not in link battles.
ApplyBadgeStatBoosts:
;> if wLinkState == LINK_STATE_BATTLING:
;>     return
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ret z ; return if link battle
;>@for for i in range(4):                           # the even badge bits, in the order of the stats in RAM
	ld a, [wObtainedBadges]
	ld b, a
	ld hl, wBattleMonAttack
	ld c, $4
; the boost is applied for badges whose bit position is even
; the order of boosts matches the order they are laid out in RAM
; Boulder (bit 0) - attack
; Thunder (bit 2) - defense
; Soul (bit 4) - speed
; Volcano (bit 6) - special
.loop
;>     if wObtainedBadges >> 2 * i & 1:              # times 1.125 (.applyBoostToStat)
;>         p = wBattleMonAttack + 2 * i
;>@v         v = mem[p] << 8 | mem[p + 1]
;>@add         v = (v + (v >> 3)) & 0xFFFF
;>@st         mem[p], mem[p + 1] = v >> 8, v & 0xFF
;>@cmp         if v >= MAX_STAT_VALUE:              # at most 999
;>@cap             mem[p], mem[p + 1] = MAX_STAT_VALUE >> 8, MAX_STAT_VALUE & 0xFF
	srl b
	call c, .applyBoostToStat
;=@for
	inc hl
	inc hl
	srl b
	dec c
	jr nz, .loop
	ret

; multiply stat at hl by 1.125
; cap stat at MAX_STAT_VALUE
.applyBoostToStat
;=@v
	ld a, [hli]
	ld d, a
	ld e, [hl]
;=@add
	srl d
	rr e
	srl d
	rr e
	srl d
	rr e
;=@st
	ld a, [hl]
	add e
	ld [hld], a
	ld a, [hl]
	adc d
	ld [hli], a
;=@cmp
	ld a, [hld]
	sub LOW(MAX_STAT_VALUE)
	ld a, [hl]
	sbc HIGH(MAX_STAT_VALUE)
	ret c
;=@cap
	ld a, HIGH(MAX_STAT_VALUE)
	ld [hli], a
	ld a, LOW(MAX_STAT_VALUE)
	ld [hld], a
	ret

;@ path: engine/battle/core
;@ def LoadHudAndHpBarAndStatusTilePatterns()
;@ Load the tiles of the HP bar, the status abbreviations and the battle HUD.
;@ test: hLoadedROMBank = 0x0F; rLCDC = 0
LoadHudAndHpBarAndStatusTilePatterns:
;> LoadHpBarAndStatusTilePatterns()
;> LoadHudTilePatterns()
	call LoadHpBarAndStatusTilePatterns

;@ path: engine/battle/core
;@ def LoadHudTilePatterns()
;@ Load the battle HUD's frame and arrow tiles (1bpp, doubled) to tiles $6D-$7F, directly with the screen off or
;@ during VBlanks with it on.
;@ test: rLCDC = 0; hLoadedROMBank = 0x0F
LoadHudTilePatterns:
;> if not rLCDC >> 7 & 1:
	ldh a, [rLCDC]
	add a ; is LCD disabled?
	jr c, .lcdEnabled
; LCD disabled
;>     FarCopyDataDouble(BANK(BattleHudTiles1), BattleHudTiles1, vChars2 + 0x6D * 16, BattleHudTiles1End - BattleHudTiles1)
	ld hl, BattleHudTiles1
	ld de, vChars2 + TILE_SIZE * $6d
	ld bc, BattleHudTiles1End - BattleHudTiles1
	ld a, BANK(BattleHudTiles1)
	call FarCopyDataDouble
;>     FarCopyDataDouble(BANK(BattleHudTiles2), BattleHudTiles2, vChars2 + 0x73 * 16, BattleHudTiles3End - BattleHudTiles2)
	ld hl, BattleHudTiles2
	ld de, vChars2 + TILE_SIZE * $73
	ld bc, BattleHudTiles3End - BattleHudTiles2
	ld a, BANK(BattleHudTiles2)
	jp FarCopyDataDouble
.lcdEnabled
;> else:
;>     CopyVideoDataDouble(vChars2 + 0x6D * 16, BattleHudTiles1, BANK(BattleHudTiles1), (BattleHudTiles1End - BattleHudTiles1) // TILE_1BPP_SIZE)
	ld de, BattleHudTiles1
	ld hl, vChars2 + TILE_SIZE * $6d
	ld bc, ((BANK(BattleHudTiles1)) & $ff) << 8 + (((BattleHudTiles1End - BattleHudTiles1) / TILE_1BPP_SIZE) & $ff)
	call CopyVideoDataDouble
;>     CopyVideoDataDouble(vChars2 + 0x73 * 16, BattleHudTiles2, BANK(BattleHudTiles2), (BattleHudTiles3End - BattleHudTiles2) // TILE_1BPP_SIZE)
	ld de, BattleHudTiles2
	ld hl, vChars2 + TILE_SIZE * $73
	ld bc, ((BANK(BattleHudTiles2)) & $ff) << 8 + (((BattleHudTiles3End - BattleHudTiles2) / TILE_1BPP_SIZE) & $ff)
	jp CopyVideoDataDouble

;@ path: engine/battle/core
;@ def PrintEmptyString()
;@ Print an empty text (just "@", which follows this code).
PrintEmptyString:
;> PrintText(addr(PrintEmptyString) + 6)
	ld hl, .emptyString
	jp PrintText

.emptyString
	db "@"


;@ path: engine/battle/core
;@ def BattleRandom() -> a
;@ A random number for the battle. In a link battle both Game Boys draw from the same list of nine numbers;
;@ after the last one each is replaced by 5 * n + 1.
;@ test: wLinkState = LINK_STATE_BATTLING
BattleRandom:
; Link battles use a shared PRNG.

;> if wLinkState != LINK_STATE_BATTLING:
;>     return Random(wLinkState < LINK_STATE_BATTLING)   # the carry from that comparison
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jp nz, Random

;> i = wLinkBattleRandomNumberListIndex
	push hl
	push bc
	ld a, [wLinkBattleRandomNumberListIndex]
	ld c, a
	ld b, 0
;> entry = addr(wLinkBattleRandomNumberList) + i
	ld hl, wLinkBattleRandomNumberList
	add hl, bc
;> wLinkBattleRandomNumberListIndex = (i + 1) & 0xFF
	inc a
	ld [wLinkBattleRandomNumberListIndex], a
;> last = (i + 1) & 0xFF >= SERIAL_RNS_LENGTH - 1
	cp SERIAL_RNS_LENGTH - 1
;> r = mem[entry]
	ld a, [hl]
	pop bc
	pop hl
;> if not last:
;>     return r
	ret c

; if we picked the last seed, we need to recalculate the nine seeds
;> # that was the last one: the next starts at the first, and all nine become 5 * n + 1
;> wLinkBattleRandomNumberListIndex = 0
	push hl
	push bc
	push af

; point to seed 0 so we pick the first number the next time
	xor a
	ld [wLinkBattleRandomNumberListIndex], a

;>@k for k in range(SERIAL_RNS_LENGTH - 1):
	ld hl, wLinkBattleRandomNumberList
	ld b, SERIAL_RNS_LENGTH - 1
.loop
;>     n = wLinkBattleRandomNumberList[k]
	ld a, [hl]
	ld c, a
;>     wLinkBattleRandomNumberList[k] = (n * 5 + 1) & 0xFF
; multiply by 5
	add a
	add a
	add c
; add 1
	inc a
	ld [hli], a
;=@k
	dec b
	jr nz, .loop

;> return r
	pop af
	pop bc
	pop hl
	ret


;@ path: engine/battle/core
;@ def HandleExplodingAnimation()
;@ Selfdestruct and Explosion that hit shake the screen (the Mega Punch animation) - not against a Ghost type,
;@ and not when the target is out of reach. The out-of-reach check always looks at the enemy's status.
HandleExplodingAnimation:
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> types, move = wEnemyMonType1, wPlayerMoveNum     # the target's types, the attacker's move
	ld hl, wEnemyMonType1
	ld de, wEnemyBattleStatus1
	ld a, [wPlayerMoveNum]
;> if not player:
	jr z, .player
;>     types, move = wBattleMonType1, wEnemyMoveNum
	ld hl, wBattleMonType1
	ld de, wEnemyBattleStatus1
	ld a, [wEnemyMoveNum]
.player
;> if move not in (SELFDESTRUCT, EXPLOSION):
;>     return
	cp SELFDESTRUCT
	jr z, .isExplodingMove
	cp EXPLOSION
	ret nz
.isExplodingMove
;> if wEnemyBattleStatus1 >> INVULNERABLE & 1:       # (always the enemy's)
;>     return
	ld a, [de]
	bit INVULNERABLE, a ; fly/dig
	ret nz
;> if mem[types] == GHOST:
;>     return
	ld a, [hli]
	cp GHOST
	ret z
;> if mem[types + 1] == GHOST:
;>     return
	ld a, [hl]
	cp GHOST
	ret z
;> if wMoveMissed:
;>     return
	ld a, [wMoveMissed]
	and a
	ret nz
;> wAnimationType = ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_LIGHT
	ld a, ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_LIGHT
	ld [wAnimationType], a
	ASSERT ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_LIGHT == MEGA_PUNCH
;> PlayMoveAnimation(MEGA_PUNCH)
	; ld a, MEGA_PUNCH
; fallthrough
;@ path: engine/battle/core
;@ def PlayMoveAnimation(anim: a)
;@ Play battle animation anim (a move or a special effect) after a short pause.
PlayMoveAnimation:
;> wAnimationID = anim
	ld [wAnimationID], a
;> Delay3()
	call Delay3
;> predef(MoveAnimation)
	ld a, (MoveAnimationPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/battle/core
;@ def InitBattle()
;@ Start a battle against wCurOpponent (a Pokemon species or a trainer class + OPP_ID_OFFSET), or - if there is
;@ none - maybe a random wild encounter.
;@ test: skip runs the whole battle
InitBattle::
;> if not wCurOpponent:
;>     return DetermineWildOpponent()
	ld a, [wCurOpponent]
	and a
	jr z, DetermineWildOpponent
;> InitOpponent()                                    # (it follows)

;@ path: engine/battle/core
;@ def InitOpponent()
;@ Start the battle against wCurOpponent.
;@ test: skip runs the whole battle
InitOpponent:
;> wCurPartySpecies = wCurOpponent
	ld a, [wCurOpponent]
	ld [wCurPartySpecies], a
;> wEnemyMonSpecies2 = wCurOpponent
	ld [wEnemyMonSpecies2], a
;> InitBattleCommon()
	jr InitBattleCommon

;@ path: engine/battle/core
;@ def DetermineWildOpponent()
;@ A wild battle if TryDoWildEncounter decides one happens - not in the first steps after a battle, and not while
;@ B is held in debug mode.
;@ test: skip runs the whole battle
DetermineWildOpponent:
;> if wStatusFlags6 >> BIT_DEBUG_MODE & 1 and hJoyHeld >> B_PAD_B & 1:
;>     return
	ld a, [wStatusFlags6]
	bit BIT_DEBUG_MODE, a
	jr z, .notDebugMode
	ldh a, [hJoyHeld]
	bit B_PAD_B, a ; disable wild encounters
	ret nz
.notDebugMode
;> if wNumberOfNoRandomBattleStepsLeft:
;>     return
	ld a, [wNumberOfNoRandomBattleStepsLeft]
	and a
	ret nz
;> if not farcall(TryDoWildEncounter):
;>     return
	ld hl, TryDoWildEncounter
	ld b, BANK(TryDoWildEncounter)
	call Bankswitch
	ret nz
;> InitBattleCommon()                                # (it follows)
;@ path: engine/battle/core
;@ def InitBattleCommon()
;@ Set up the battle: text without delays, fresh battle variables; a trainer's data, the transition and the
;@ trainer's picture (wild Pokemon: InitWildBattle), then the battle itself.
;@ test: skip runs the whole battle
InitBattleCommon:
;> # wMapPalOffset and wLetterPrintingDelayFlags are saved on the stack until _InitBattleCommon ends
;> wLetterPrintingDelayFlags &= ~(1 << BIT_TEXT_DELAY)
	ld a, [wMapPalOffset]
	push af
	ld hl, wLetterPrintingDelayFlags
	ld a, [hl]
	push af
	res BIT_TEXT_DELAY, [hl] ; no delay
;> farcall(InitBattleVariables)
	ld hl, InitBattleVariables
	ld b, BANK(InitBattleVariables)
	call Bankswitch
;> if wEnemyMonSpecies2 < OPP_ID_OFFSET:
;>     return InitWildBattle()
	ld a, [wEnemyMonSpecies2]
	sub OPP_ID_OFFSET
	jp c, InitWildBattle
;> wTrainerClass = wEnemyMonSpecies2 - OPP_ID_OFFSET
	ld [wTrainerClass], a
;> GetTrainerInformation()
	call GetTrainerInformation
;> farcall(ReadTrainer)
	ld hl, ReadTrainer
	ld b, BANK(ReadTrainer)
	call Bankswitch
;> DoBattleTransitionAndInitBattleVariables()
	call DoBattleTransitionAndInitBattleVariables
;> _LoadTrainerPic()
	call _LoadTrainerPic
;> wEnemyMonSpecies2 = 0
	xor a
	ld [wEnemyMonSpecies2], a
;> hStartTileID = 0
	ldh [hStartTileID], a
;> wAICount = 0xFF
	dec a
	ld [wAICount], a
;> predef(CopyUncompressedPicToTilemap, hl=coord(12, 0))
	ld hl, (0) * SCREEN_WIDTH + (12) + wTileMap
	ld a, (CopyUncompressedPicToTilemapPredef - PredefPointers) / 3
	call Predef
;> mem[wEnemyMonPartyPos] = 0xFF
	ld a, $ff
	ld [wEnemyMonPartyPos], a
;> wIsInBattle = TRAINER_BATTLE
	ld a, TRAINER_BATTLE
	ld [wIsInBattle], a
;> _InitBattleCommon()
	jp _InitBattleCommon

;@ path: engine/battle/core
;@ def InitWildBattle()
;@ Set up a wild battle: the Pokemon's data and picture - or the unidentifiable GHOST in the Pokemon Tower
;@ without the Silph Scope (and for the restless soul of Marowak).
;@ test: skip runs the whole battle
InitWildBattle:
;> wIsInBattle = WILD_BATTLE
	ld a, WILD_BATTLE
	ld [wIsInBattle], a
;> LoadEnemyMonData()
	call LoadEnemyMonData
;> DoBattleTransitionAndInitBattleVariables()
	call DoBattleTransitionAndInitBattleVariables
;> if wCurOpponent == RESTLESS_SOUL or IsGhostBattle():
	ld a, [wCurOpponent]
	cp RESTLESS_SOUL
	jr z, .isGhost
	call IsGhostBattle
	jr nz, .isNoGhost
.isGhost
;>     wMonHSpriteDim = 0x66
	ld hl, wMonHSpriteDim
	ld a, $66
	ld [hli], a   ; write sprite dimensions
;>     wMonHFrontSprite[0] = GhostPic & 0xFF
	ld bc, GhostPic
	ld a, c
	ld [hli], a   ; write front sprite pointer
;>     wMonHFrontSprite[1] = GhostPic >> 8
	ld [hl], b
;>     ghost = charmap('GHOST@')                     # its name
;>     mem[wEnemyMonNick] = ghost[0]
	ld hl, wEnemyMonNick  ; set name to "GHOST"
	ld a, CHARVAL(STRCHAR("GHOST@", $0))
	ld [hli], a
;>     for i in range(1, 3):
;>         mem[wEnemyMonNick + i] = ghost[i]
	ld a, CHARVAL(STRCHAR("GHOST@", $1))
	ld [hli], a
	ld a, CHARVAL(STRCHAR("GHOST@", $2))
	ld [hli], a
;>     for i in range(3, 6):
;>         mem[wEnemyMonNick + i] = ghost[i]
	ld a, CHARVAL(STRCHAR("GHOST@", $3))
	ld [hli], a
	ld a, CHARVAL(STRCHAR("GHOST@", $4))
	ld [hli], a
	ld [hl], CHARVAL(STRCHAR("GHOST@", CHARLEN("GHOST@") - 1))
;>     species = wCurPartySpecies
	ld a, [wCurPartySpecies]
	push af
;>     wCurPartySpecies = MON_GHOST
	ld a, MON_GHOST
	ld [wCurPartySpecies], a
;>     LoadMonFrontSprite(vFrontPic)
	ld de, vFrontPic
	call LoadMonFrontSprite ; load ghost sprite
;>     wCurPartySpecies = species
	pop af
	ld [wCurPartySpecies], a
	jr .spriteLoaded
.isNoGhost
;> else:
;>     LoadMonFrontSprite(vFrontPic)
	ld de, vFrontPic
	call LoadMonFrontSprite ; load mon sprite
.spriteLoaded
;> wTrainerClass = 0
	xor a
	ld [wTrainerClass], a
;> hStartTileID = 0
	ldh [hStartTileID], a
;> predef(CopyUncompressedPicToTilemap, hl=coord(12, 0))
;> _InitBattleCommon()
	ld hl, (0) * SCREEN_WIDTH + (12) + wTileMap
	ld a, (CopyUncompressedPicToTilemapPredef - PredefPointers) / 3
	call Predef

; common code that executes after init battle code specific to trainer or wild battles
;@ path: engine/battle/core
;@ def _InitBattleCommon() -> carry
;@ The rest of the battle start for both kinds: dark palettes, the silhouettes sliding in, the screen set up
;@ with the enemy HUD for a wild Pokemon, then the battle (StartBattle) and its end (EndOfBattle). Afterwards the
;@ text settings, map palette and tile animations come back. Carry set.
;@ test: skip runs the whole battle
_InitBattleCommon:
;> RunPaletteCommand(SET_PAL_BATTLE_BLACK)
	ld b, SET_PAL_BATTLE_BLACK
	call RunPaletteCommand
;> SlidePlayerAndEnemySilhouettesOnScreen()
	call SlidePlayerAndEnemySilhouettesOnScreen
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> PrintText(addr(_InitBattleCommon) + 0x5F)         # its local empty text
	ld hl, .emptyString
	call PrintText
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> ClearScreen()
	call ClearScreen
;> hAutoBGTransferDest[1] = vBGMap0 >> 8
	ld a, HIGH(vBGMap0)
	ldh [hAutoBGTransferDest + 1], a
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> hAutoBGTransferDest[1] = vBGMap1 >> 8
	ld a, HIGH(vBGMap1)
	ldh [hAutoBGTransferDest + 1], a
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> ClearScreenArea(coord(9, 7), 10, 5)
	ld hl, (7) * SCREEN_WIDTH + (9) + wTileMap
	ld bc, ((5) & $ff) << 8 + ((10) & $ff)
	call ClearScreenArea
;> ClearScreenArea(coord(1, 0), 10, 4)
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, ((4) & $ff) << 8 + ((10) & $ff)
	call ClearScreenArea
;> ClearSprites()
	call ClearSprites
;> if wIsInBattle == 1:
;>     DrawEnemyHUDAndHPBar()
	ld a, [wIsInBattle]
	dec a ; is it a wild battle?
	call z, DrawEnemyHUDAndHPBar ; draw enemy HUD and HP bar if it's a wild battle
;> StartBattle()
	call StartBattle
;> farcall(EndOfBattle)
	ld hl, EndOfBattle
	ld b, BANK(EndOfBattle)
	call Bankswitch
;> # wLetterPrintingDelayFlags and wMapPalOffset get back the values InitBattleCommon left on the stack
	pop af
	ld [wLetterPrintingDelayFlags], a
	pop af
	ld [wMapPalOffset], a
;> hTileAnimations = wSavedTileAnimations
	ld a, [wSavedTileAnimations]
	ldh [hTileAnimations], a
;> return True
	scf
	ret
.emptyString
	db "@"

;@ path: engine/battle/core
;@ def _LoadTrainerPic()
;@ Load the opponent trainer's front picture from wTrainerPicPointer (from the trainer pictures bank, or the
;@ player's own bank for the link opponent) into the front picture tiles.
;@ test: skip decompresses and copies to VRAM
_LoadTrainerPic:
;> src = wTrainerPicPointer[0] | wTrainerPicPointer[1] << 8
	ld a, [wTrainerPicPointer]
	ld e, a
	ld a, [wTrainerPicPointer + 1]
	ld d, a ; de contains pointer to trainer pic
;> bank = BANK(RedPicFront) if wLinkState else BANK(YoungsterPic)   # YoungsterPic opens the trainer pictures
	ld a, [wLinkState]
	and a
	ld a, BANK("Trainer Pics")
	jr z, .loadSprite
	ld a, BANK(RedPicFront)
.loadSprite
;> UncompressSpriteFromDE(bank, src)
	call UncompressSpriteFromDE
;> LoadUncompressedSpriteData(vFrontPic, 0x77, 0x77)
	ld de, vFrontPic
	ld a, $77
	ld c, a
	jp LoadUncompressedSpriteData

;@ path: engine/battle/core
;@ def ResetCryModifiers()
;@ Clear the cry pitch and tempo changes and play sound 0 (unused).
ResetCryModifiers: ; unreferenced
;> wFrequencyModifier = 0
	xor a
	ld [wFrequencyModifier], a
;> wTempoModifier = 0
	ld [wTempoModifier], a
;> PlaySound(0)
	jp PlaySound

; animates the mon "growing" out of the pokeball
;@ path: engine/battle/core
;@ def AnimateSendingOutMon()
;@ A Pokemon's picture grows out of its Poke Ball (the predef's hl is its bottom-center tile): the ball tile, a
;@ 3x3 and a 5x5 version, then the full 7x7 picture. Outside battle only the full picture is drawn.
;@ test: skip waits for frames
AnimateSendingOutMon:
;> dest = wPredefHL[0] << 8 | wPredefHL[1]
	ld a, [wPredefHL]
	ld h, a
	ld a, [wPredefHL + 1]
	ld l, a
;> hBaseTileID = hStartTileID
	ldh a, [hStartTileID]
	ldh [hBaseTileID], a
;> if wIsInBattle:
	ld b, $4c
	ld a, [wIsInBattle]
	and a
	jr z, .notInBattle
;>     mem[dest] = (0x4C + wIsInBattle) & 0xFF
	add b
	ld [hl], a
;>     Delay3()
	call Delay3
;>     dest -= SCREEN_WIDTH * 2 + 1
	ld bc, -(SCREEN_WIDTH * 2 + 1)
	add hl, bc
;>     wDownscaledMonSize = 1
	ld a, 1
	ld [wDownscaledMonSize], a
;>     predef(CopyDownscaledMonTiles, hl=dest, bc=3 << 8 | 3)
	ld bc, ((3) & $ff) << 8 + ((3) & $ff)
	ld a, (CopyDownscaledMonTilesPredef - PredefPointers) / 3
	call Predef
;>     DelayFrames(4)
	ld c, 4
	call DelayFrames
;>     dest -= SCREEN_WIDTH * 2 + 1
	ld bc, -(SCREEN_WIDTH * 2 + 1)
	add hl, bc
;>     wDownscaledMonSize = 0
	xor a
	ld [wDownscaledMonSize], a
;>     predef(CopyDownscaledMonTiles, hl=dest, bc=5 << 8 | 5)
	ld bc, ((5) & $ff) << 8 + ((5) & $ff)
	ld a, (CopyDownscaledMonTilesPredef - PredefPointers) / 3
	call Predef
;>     DelayFrames(5)
	ld c, 5
	call DelayFrames
;>     dest -= SCREEN_WIDTH * 2 + 1
	ld bc, -(SCREEN_WIDTH * 2 + 1)
	jr .next
.notInBattle
;> else:
;>     dest -= SCREEN_WIDTH * 6 + 3
	ld bc, -(SCREEN_WIDTH * 6 + 3)
.next
;> CopyUncompressedPicToHL(dest, (hBaseTileID + 0x31) & 0xFF)
	add hl, bc
	ldh a, [hBaseTileID]
	add $31
	jr CopyUncompressedPicToHL

;@ path: engine/battle/core
;@ def CopyUncompressedPicToTilemap()
;@ Put a 7x7 tile picture on the screen at the address in wPredefHL, tile numbers counting from hStartTileID.
;@ test: mem[0xCC4F] = 0xC3; mem[0xCC50] = rand(0xA0, 0xC0)
CopyUncompressedPicToTilemap:
;> CopyUncompressedPicToHL(wPredefHL[0] << 8 | wPredefHL[1], hStartTileID)
	ld a, [wPredefHL]
	ld h, a
	ld a, [wPredefHL + 1]
	ld l, a
	ldh a, [hStartTileID]
;@ path: engine/battle/core
;@ def CopyUncompressedPicToHL(dest: hl, tile: a)
;@ Write a 7x7 Pokemon or trainer picture into the tile map at dest: tile numbers count up column by column,
;@ mirrored (columns right to left) when wSpriteFlipped is set.
;@ test: dest = rand_ram(7 * SCREEN_WIDTH)
CopyUncompressedPicToHL::
;> flipped = wSpriteFlipped
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
	ld de, SCREEN_WIDTH
	push af
	ld a, [wSpriteFlipped]
;> if not flipped:
	and a
	jr nz, .flipped
	pop af
.loop
;>@col     for col in range(7):
	push bc
	push hl
.innerLoop
;>@ri         for row in range(7):
;>             mem[dest + row * SCREEN_WIDTH + col] = tile
	ld [hl], a
	add hl, de
;>             tile = (tile + 1) & 0xFF
	inc a
;=@ri
	dec c
	jr nz, .innerLoop
;=@col
	pop hl
	inc hl
	pop bc
	dec b
	jr nz, .loop
	ret

.flipped
;> else:                                             # mirrored: from the right column leftwards
;>     dest += 6
	push bc
	ld b, 0
	dec c
	add hl, bc
	pop bc
	pop af
.flippedLoop
;>@fcol     for col in range(7):
	push bc
	push hl
.flippedInnerLoop
;>@rf         for row in range(7):
;>             mem[dest - col + row * SCREEN_WIDTH] = tile
	ld [hl], a
	add hl, de
;>             tile = (tile + 1) & 0xFF
	inc a
;=@rf
	dec c
	jr nz, .flippedInnerLoop
;=@fcol
	pop hl
	dec hl
	pop bc
	dec b
	jr nz, .flippedLoop
	ret

;@ path: engine/battle/core
;@ def LoadMonBackPic()
;@ Load the back picture of the battling Pokemon (its header already loaded): decompress, scale up by two and
;@ copy it to the back picture tiles; its area on screen is cleared first.
;@ test: skip decompresses and copies to VRAM
LoadMonBackPic:
; Assumes the monster's attributes have
; been loaded with GetMonHeader.
;> wCurPartySpecies = wBattleMonSpecies2
	ld a, [wBattleMonSpecies2]
	ld [wCurPartySpecies], a
;> ClearScreenArea(coord(1, 5), 8, 7)
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld b, 7
	ld c, 8
	call ClearScreenArea
;> UncompressMonSprite(wMonHBackSprite - wMonHeader)
	ld hl, wMonHBackSprite - wMonHeader
	call UncompressMonSprite
;> predef(ScaleSpriteByTwo)
	ld a, (ScaleSpriteByTwoPredef - PredefPointers) / 3
	call Predef
;> InterlaceMergeSpriteBuffers(vBackPic)
	ld de, vBackPic
	call InterlaceMergeSpriteBuffers ; combine the two buffers to a single 2bpp sprite
;> CopyVideoData(vSprites, vBackPic, hLoadedROMBank, 2 * SPRITEBUFFERSIZE // TILE_SIZE)
	ld hl, vSprites
	ld de, vBackPic
	ld c, (2 * SPRITEBUFFERSIZE) / TILE_SIZE ; count of 16-byte chunks to be copied
	ldh a, [hLoadedROMBank]
	ld b, a
	jp CopyVideoData
;@ path: engine/battle/effects
;@ def JumpMoveEffect() -> b
;@ Run the special effect of the move being used; b = 1 afterwards.
;@ test: hLoadedROMBank = 0x0F
JumpMoveEffect:
;> _JumpMoveEffect()
;> return 1
	call _JumpMoveEffect
	ld b, $1
	ret

;@ path: engine/battle/effects
;@ def _JumpMoveEffect()
;@ Jump to the handler of the current move's effect (MoveEffectPointerTable, effect 1 first).
;@ test: hLoadedROMBank = 0x0F
_JumpMoveEffect:
;> effect = wPlayerMoveEffect if hWhoseTurn == 0 else wEnemyMoveEffect
	ldh a, [hWhoseTurn]
	and a
	ld a, [wPlayerMoveEffect]
	jr z, .next
	ld a, [wEnemyMoveEffect]
.next
;> offset = 2 * (effect - 1) & 0xFF                 # there is no effect 0
	dec a ; subtract 1, there is no special effect for 00
	add a ; x2, 16bit pointers
;> entry = MoveEffectPointerTable + offset
	ld hl, MoveEffectPointerTable
	ld b, 0
	ld c, a
	add hl, bc
;> handler = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> call(handler)
	jp hl ; jump to special effect handler

;@ path: engine/battle/effects
MoveEffectPointerTable:
; entries correspond to *_EFFECT constants
	dw SleepEffect               ; EFFECT_01
