	dw StatModifierUpEffect      ; DEFENSE_UP2_EFFECT
	dw StatModifierUpEffect      ; SPEED_UP2_EFFECT
	dw StatModifierUpEffect      ; SPECIAL_UP2_EFFECT
	dw StatModifierUpEffect      ; ACCURACY_UP2_EFFECT
