;@ path: engine/battle/effects
;@ def SleepEffect()
;@ Sleep moves: the target sleeps for 1 to 7 turns. A target that is already asleep or has another status is not
;@ affected - except right after a Hyper Beam: then the move cannot miss and overrides any status.
;@ test: hLoadedROMBank = 0x0F
SleepEffect:
;> if hWhoseTurn == 0:
;>     status, flags = wEnemyMonStatus, addr(wEnemyBattleStatus2)
	ld de, wEnemyMonStatus
	ld bc, wEnemyBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	jp z, .sleepEffect
;> else:
;>     status, flags = wBattleMonStatus, addr(wPlayerBattleStatus2)
	ld de, wBattleMonStatus
	ld bc, wPlayerBattleStatus2

.sleepEffect
;> recharging = mem[flags] >> NEEDS_TO_RECHARGE & 1
;> mem[flags] &= ~(1 << NEEDS_TO_RECHARGE) & 0xFF
	ld a, [bc]
	bit NEEDS_TO_RECHARGE, a ; does the target need to recharge? (hyper beam)
	res NEEDS_TO_RECHARGE, a ; target no longer needs to recharge
	ld [bc], a
;> if not recharging:                                # right after a Hyper Beam it can't fail
	jr nz, .setSleepCounter ; if the target had to recharge, all hit tests will be skipped
	                        ; including the event where the target already has another status
;>     if mem[status] & SLP_MASK:
;>         return PrintText(AlreadyAsleepText)
	ld a, [de]
	ld b, a
	and SLP_MASK
	jr z, .notAlreadySleeping ; can't affect a mon that is already asleep
	ld hl, AlreadyAsleepText
	jp PrintText
.notAlreadySleeping
;>     if mem[status]:                               # another status
;>@na         return PrintDidntAffectText()
	ld a, b
	and a
	jr nz, .didntAffect ; can't affect a mon that is already statused
;>     MoveHitTest()
	push de
	call MoveHitTest ; apply accuracy tests
	pop de
;>     if wMoveMissed:
;>         return PrintDidntAffectText()
	ld a, [wMoveMissed]
	and a
	jr nz, .didntAffect
.setSleepCounter
; set target's sleep counter to a random number between 1 and 7
;> while True:                                       # 1 to 7 turns
;>     turns = BattleRandom() & SLP_MASK
	call BattleRandom
	and SLP_MASK
;>     if turns:
;>         break
	jr z, .setSleepCounter
;> mem[status] = turns
	ld [de], a
;> PlayCurrentMoveAnimation2()
	call PlayCurrentMoveAnimation2
;> PrintText(FellAsleepText)
	ld hl, FellAsleepText
	jp PrintText
.didntAffect
;=@na
	jp PrintDidntAffectText

;@ path: engine/battle/effects
FellAsleepText:
	db TX_FAR
	dw _FellAsleepText
	db BANK(_FellAsleepText)
	db TX_END

;@ path: engine/battle/effects
AlreadyAsleepText:
	db TX_FAR
	dw _AlreadyAsleepText
	db BANK(_AlreadyAsleepText)
	db TX_END

;@ path: engine/battle/effects
;@ def PoisonEffect()
;@ Poison moves and poison side effects (20% or 40%). Poison-type targets, statused targets and substitutes are
;@ immune. Toxic poisons badly: the damage grows every turn, counted from 0.
;@ test: hLoadedROMBank = 0x0F
PoisonEffect:
;> if hWhoseTurn == 0:
;>     status, effect = wEnemyMonStatus, wPlayerMoveEffect
	ld hl, wEnemyMonStatus
	ld de, wPlayerMoveEffect
	ldh a, [hWhoseTurn]
	and a
	jr z, .poisonEffect
;> else:
;>     status, effect = wBattleMonStatus, wEnemyMoveEffect
	ld hl, wBattleMonStatus
	ld de, wEnemyMoveEffect
.poisonEffect
;> immune = CheckTargetSubstitute() or mem[status]   # behind a substitute, or already statused
	call CheckTargetSubstitute
	jr nz, .noEffect ; can't poison a substitute target
	ld a, [hli]
	ld b, a
	and a
	jr nz, .noEffect ; miss if target is already statused
;> immune = immune or mem[status + 1] == POISON     # or a Poison type (the types follow the status)
	ld a, [hli]
	cp POISON ; can't poison a poison-type target
	jr z, .noEffect
;> immune = immune or mem[status + 2] == POISON
;> if immune:
;>@quiet     if effect != POISON_EFFECT:                  # only the poison move itself says so
;>@ret         return
;>@wait     DelayFrames(50)
;>@say     return PrintDidntAffectText()
	ld a, [hld]
	cp POISON ; can't poison a poison-type target
	jr z, .noEffect
;> if effect == POISON_SIDE_EFFECT1:                 # a side effect: 20%
;>     chance = 20 * 255 // 100 + 1
	ld a, [de]
	cp POISON_SIDE_EFFECT1
	ld b, 20 * $ff / 100 + 1 ; chance of poisoning
	jr z, .sideEffectTest
;> elif effect == POISON_SIDE_EFFECT2:               # or 40%
;>     chance = 40 * 255 // 100 + 1
	cp POISON_SIDE_EFFECT2
	ld b, 40 * $ff / 100 + 1 ; chance of poisoning
	jr z, .sideEffectTest
;> else:                                             # the move itself: the hit test
;>     chance = None
;>     MoveHitTest()
	push hl
	push de
	call MoveHitTest ; apply accuracy tests
	pop de
	pop hl
;>     if wMoveMissed:
;>         return PrintDidntAffectText()             # (after 50 frames, as above)
	ld a, [wMoveMissed]
	and a
	jr nz, .didntAffect
	jr .inflictPoison
.sideEffectTest
;> if chance is not None and BattleRandom() >= chance:
;>     return
	call BattleRandom
	cp b ; was side effect successful?
	ret nc
.inflictPoison
;> mem[status] |= 1 << PSN
	dec hl
	set PSN, [hl]
;>@mv move = wEnemyMoveNum if hWhoseTurn else wPlayerMoveNum   # the byte before the effect
	push de
	dec de
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
;>     anim = SHAKE_SCREEN_ANIM                      # the screen shakes
	ld b, SHAKE_SCREEN_ANIM
;>     flags = addr(wPlayerBattleStatus3)
	ld hl, wPlayerBattleStatus3
;=@mv
	ld a, [de]
;>     toxic = addr(wPlayerToxicCounter)
	ld de, wPlayerToxicCounter
	jr nz, .ok
;> else:
;>     anim = ENEMY_HUD_SHAKE_ANIM                   # the enemy's HUD shakes
	ld b, ENEMY_HUD_SHAKE_ANIM
;>     flags = addr(wEnemyBattleStatus3)
	ld hl, wEnemyBattleStatus3
;>     toxic = addr(wEnemyToxicCounter)
	ld de, wEnemyToxicCounter
.ok
;> if move == TOXIC:                                 # badly poisoned: the damage grows each turn
	cp TOXIC
	jr nz, .normalPoison ; done if move is not Toxic
;>     mem[flags] |= 1 << BADLY_POISONED
;>     mem[toxic] = 0
	set BADLY_POISONED, [hl] ; else set Toxic battstatus
	xor a
	ld [de], a
;>     text = BadlyPoisonedText
	ld hl, BadlyPoisonedText
	jr .continue
.normalPoison
;> else:
;>     text = PoisonedText
	ld hl, PoisonedText
.continue
;> if effect == POISON_EFFECT:
;>@reg     PlayCurrentMoveAnimation2()
	pop de
	ld a, [de]
	cp POISON_EFFECT
	jr z, .regularPoisonEffect
;> else:                                             # a side effect: the HUD or the screen shakes
;>     PlayBattleAnimation2(anim)
	ld a, b
	call PlayBattleAnimation2
;>@pt PrintText(text)
	jp PrintText
.regularPoisonEffect
;=@reg
	call PlayCurrentMoveAnimation2
;=@pt
	jp PrintText
.noEffect
;=@quiet
	ld a, [de]
	cp POISON_EFFECT
;=@ret
	ret nz
.didntAffect
;=@wait
	ld c, 50
	call DelayFrames
;=@say
	jp PrintDidntAffectText

;@ path: engine/battle/effects
PoisonedText:
	db TX_FAR
	dw _PoisonedText
	db BANK(_PoisonedText)
	db TX_END

;@ path: engine/battle/effects
BadlyPoisonedText:
	db TX_FAR
	dw _BadlyPoisonedText
	db BANK(_BadlyPoisonedText)
	db TX_END

;@ path: engine/battle/effects
;@ def DrainHPEffect()
;@ Absorb, Mega Drain, Leech Life and Dream Eater (the work is done in another bank).
;@ test: hLoadedROMBank = 0x0F
DrainHPEffect:
;> return Bankswitch(BANK(DrainHPEffect_), DrainHPEffect_)
	ld hl, DrainHPEffect_
	ld b, BANK(DrainHPEffect_)
	jp Bankswitch

;@ path: engine/battle/effects
;@ def ExplodeEffect()
;@ Explosion and Selfdestruct: the user faints - HP and status to 0 - and loses Leech Seed.
;@ test: hLoadedROMBank = 0x0F
ExplodeEffect:
;> hp, flags = wBattleMonHP, addr(wPlayerBattleStatus2)   # the user's
	ld hl, wBattleMonHP
	ld de, wPlayerBattleStatus2
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .faintUser
;>     hp, flags = wEnemyMonHP, addr(wEnemyBattleStatus2)
	ld hl, wEnemyMonHP
	ld de, wEnemyBattleStatus2
.faintUser
;> fill(hp, 0, 2)
	xor a
	ld [hli], a ; set the mon's HP to 0
	ld [hli], a
;> mem[hp + 3] = 0  # the status byte
	inc hl
	ld [hl], a ; set mon's status to 0
;> mem[flags] &= ~(1 << SEEDED) & 0xFF
	ld a, [de]
	res SEEDED, a ; clear mon's leech seed status
	ld [de], a
	ret

;@ path: engine/battle/effects
;@ def FreezeBurnParalyzeEffect()
;@ Side effects that freeze, burn or paralyze: 10% (30% for the stronger ones) if the target has no status, no
;@ substitute and no type matching the move's. A target that is already statused may be thawed by a fire move
;@ instead. A burn halves the Attack and paralysis quarters the Speed. Only the enemy's HUD shakes, and only the
;@ enemy loses its recharge turn when frozen.
;@ test: hLoadedROMBank = 0x0F
FreezeBurnParalyzeEffect:
;> wAnimationType = 0
	xor a
	ld [wAnimationType], a
;> if CheckTargetSubstitute():                       # a substitute takes no status
;>     return
	call CheckTargetSubstitute
	ret nz ; return if they have a substitute, can't effect them
;> if hWhoseTurn == 0:                               # the player attacks
	ldh a, [hWhoseTurn]
	and a
	jp nz, .opponentAttacker
;>     if wEnemyMonStatus:                           # already statused: a fire move may thaw it instead
;>         return CheckDefrost(wEnemyMonStatus)
	ld a, [wEnemyMonStatus]
	and a
	jp nz, CheckDefrost ; can't inflict status if opponent is already statused
;>     if wPlayerMoveType == wEnemyMonType1:         # an Ice move can't freeze an Ice type, ...
;>         return
	ld a, [wPlayerMoveType]
	ld b, a
	ld a, [wEnemyMonType1]
	cp b ; do target type 1 and move type match?
	ret z  ; return if they match (an ice move can't freeze an ice-type, body slam can't paralyze a normal-type, etc.)
;>     if wPlayerMoveType == wEnemyMonType2:
;>         return
	ld a, [wEnemyMonType2]
	cp b ; do target type 2 and move type match?
	ret z  ; return if they match
;>     effect = wPlayerMoveEffect
	ld a, [wPlayerMoveEffect]
;=@big
	cp PARALYZE_SIDE_EFFECT1 + 1
;>     chance = 10 * 255 // 100 + 1                  # 10%
	ld b, 10 * $ff / 100 + 1
;>@big     if effect > PARALYZE_SIDE_EFFECT1:        # the stronger versions: 30%
	jr c, .regular_effectiveness
; extra effectiveness
;>         chance = 30 * 255 // 100 + 1
;>         effect -= PARALYZE_SIDE_EFFECT2 - PARALYZE_SIDE_EFFECT1   # and then like the weaker ones
	ld b, 30 * $ff / 100 + 1
	ASSERT PARALYZE_SIDE_EFFECT2 - PARALYZE_SIDE_EFFECT1 == BURN_SIDE_EFFECT2 - BURN_SIDE_EFFECT1
	ASSERT PARALYZE_SIDE_EFFECT2 - PARALYZE_SIDE_EFFECT1 == FREEZE_SIDE_EFFECT2 - FREEZE_SIDE_EFFECT1
	sub PARALYZE_SIDE_EFFECT2 - PARALYZE_SIDE_EFFECT1 ; treat extra effective as regular from now on
.regular_effectiveness
;>     if BattleRandom() >= chance:
;>         return
	push af
	call BattleRandom ; get random 8bit value for probability test
	cp b
	pop bc
	ret nc ; do nothing if random value is >= 1A or 4D [no status applied]
;>     if effect == BURN_SIDE_EFFECT1:
;>@b1         wEnemyMonStatus = 1 << BRN
;>@b2         HalveAttackDueToBurn()
;>@b3         PlayBattleAnimation(ENEMY_HUD_SHAKE_ANIM)
;>@b4         PrintText(BurnedText)
	ld a, b ; what type of effect is this?
	cp BURN_SIDE_EFFECT1
	jr z, .burn1
;>     elif effect == FREEZE_SIDE_EFFECT1:
;>@f1         ClearHyperBeam()                      # it loses its recharge turn
;>@f2         wEnemyMonStatus = 1 << FRZ
;>@f3         PlayBattleAnimation(ENEMY_HUD_SHAKE_ANIM)
;>@f4         PrintText(FrozenText)
	cp FREEZE_SIDE_EFFECT1
	jr z, .freeze1
; paralyze1
;>     else:
;>         wEnemyMonStatus = 1 << PAR
	ld a, 1 << PAR
	ld [wEnemyMonStatus], a
;>         QuarterSpeedDueToParalysis()
	call QuarterSpeedDueToParalysis ; quarter speed of affected mon
;>         PlayBattleAnimation(ENEMY_HUD_SHAKE_ANIM)
	ld a, ENEMY_HUD_SHAKE_ANIM
	call PlayBattleAnimation
;>         PrintMayNotAttackText()
	jp PrintMayNotAttackText ; print paralysis text
.burn1
;=@b1
	ld a, 1 << BRN
	ld [wEnemyMonStatus], a
;=@b2
	call HalveAttackDueToBurn ; halve attack of affected mon
;=@b3
	ld a, ENEMY_HUD_SHAKE_ANIM
	call PlayBattleAnimation
;=@b4
	ld hl, BurnedText
	jp PrintText
.freeze1
;=@f1
	call ClearHyperBeam ; resets hyper beam (recharge) condition from target
;=@f2
	ld a, 1 << FRZ
	ld [wEnemyMonStatus], a
;=@f3
	ld a, ENEMY_HUD_SHAKE_ANIM
	call PlayBattleAnimation
;=@f4
	ld hl, FrozenText
	jp PrintText
.opponentAttacker
;> else:                                             # the enemy attacks: the same on the player's Pokemon
;>     if wBattleMonStatus:
;>         return CheckDefrost(wBattleMonStatus)
	ld a, [wBattleMonStatus] ; mostly same as above with addresses swapped for opponent
	and a
	jp nz, CheckDefrost
;>     if wEnemyMoveType == wBattleMonType1:
;>         return
	ld a, [wEnemyMoveType]
	ld b, a
	ld a, [wBattleMonType1]
	cp b
	ret z
;>     if wEnemyMoveType == wBattleMonType2:
;>         return
	ld a, [wBattleMonType2]
	cp b
	ret z
;>     effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
;=@big2
	cp PARALYZE_SIDE_EFFECT1 + 1
;>     chance = 10 * 255 // 100 + 1
	ld b, 10 * $ff / 100 + 1
;>@big2     if effect > PARALYZE_SIDE_EFFECT1:
	jr c, .regular_effectiveness2
; extra effectiveness
;>         chance = 30 * 255 // 100 + 1
;>         effect -= BURN_SIDE_EFFECT2 - BURN_SIDE_EFFECT1
	ld b, 30 * $ff / 100 + 1
	sub BURN_SIDE_EFFECT2 - BURN_SIDE_EFFECT1 ; treat extra effective as regular from now on
.regular_effectiveness2
;>     if BattleRandom() >= chance:
;>         return
	push af
	call BattleRandom
	cp b
	pop bc
	ret nc
;>     if effect == BURN_SIDE_EFFECT1:
;>@b5         wBattleMonStatus = 1 << BRN
;>@b6         HalveAttackDueToBurn()
;>@b7         PrintText(BurnedText)                 # (no shaking on this side)
	ld a, b
	cp BURN_SIDE_EFFECT1
	jr z, .burn2
;>     elif effect == FREEZE_SIDE_EFFECT1:           # (and no recharge reset)
;>@f5         wBattleMonStatus = 1 << FRZ
;>@f6         PrintText(FrozenText)
	cp FREEZE_SIDE_EFFECT1
	jr z, .freeze2
; paralyze2
;>     else:
;>         wBattleMonStatus = 1 << PAR
	ld a, 1 << PAR
	ld [wBattleMonStatus], a
;>         QuarterSpeedDueToParalysis()
	call QuarterSpeedDueToParalysis
;>         PrintMayNotAttackText()
	jp PrintMayNotAttackText
.burn2
;=@b5
	ld a, 1 << BRN
	ld [wBattleMonStatus], a
;=@b6
	call HalveAttackDueToBurn
;=@b7
	ld hl, BurnedText
	jp PrintText
.freeze2
; hyper beam bits aren't reset for opponent's side
;=@f5
	ld a, 1 << FRZ
	ld [wBattleMonStatus], a
;=@f6
	ld hl, FrozenText
	jp PrintText

;@ path: engine/battle/effects
BurnedText:
	db TX_FAR
	dw _BurnedText
	db BANK(_BurnedText)
	db TX_END

;@ path: engine/battle/effects
FrozenText:
	db TX_FAR
	dw _FrozenText
	db BANK(_FrozenText)
	db TX_END

;@ path: engine/battle/effects
;@ def CheckDefrost(status: a)
;@ A fire move that can burn thaws a frozen target: its status is cleared in battle and in its party.
;@ test: hLoadedROMBank = 0x0F
CheckDefrost:
; any fire-type move that has a chance inflict burn (all but Fire Spin) will defrost a frozen target
;> if not status & 1 << FRZ:
;>     return
	and 1 << FRZ ; are they frozen?
	ret z ; return if so
;> if hWhoseTurn == 0:
	ldh a, [hWhoseTurn]
	and a
	jr nz, .opponent
	;player [attacker]
;>     if wPlayerMoveType != FIRE:
;>         return
	ld a, [wPlayerMoveType]
	sub FIRE
	ret nz ; return if type of move used isn't fire
;>     mem[wEnemyMonStatus] = 0
	ld [wEnemyMonStatus], a ; set opponent status to 00 ["defrost" a frozen monster]
;>     st = wEnemyMon1Status + mem[wEnemyMonPartyPos] * PARTYMON_STRUCT_LENGTH   # in the party data too
	ld hl, wEnemyMon1Status
	ld a, [wEnemyMonPartyPos]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     mem[st] = 0
	xor a
	ld [hl], a ; clear status in roster
;>     text = FireDefrostedText
	ld hl, FireDefrostedText
	jr .common
.opponent
;> else:
;>     if wEnemyMoveType != FIRE:
;>         return
	ld a, [wEnemyMoveType] ; same as above with addresses swapped
	sub FIRE
	ret nz
;>     mem[wBattleMonStatus] = 0
	ld [wBattleMonStatus], a
;>     st = wPartyMon1Status + wPlayerMonNumber * PARTYMON_STRUCT_LENGTH   # in the party data too
	ld hl, wPartyMon1Status
	ld a, [wPlayerMonNumber]
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
;>     mem[st] = 0
	xor a
	ld [hl], a
;>     text = FireDefrostedText
	ld hl, FireDefrostedText
.common
;> PrintText(text)
	jp PrintText

;@ path: engine/battle/effects
FireDefrostedText:
	db TX_FAR
	dw _FireDefrostedText
	db BANK(_FireDefrostedText)
	db TX_END

;@ path: engine/battle/effects
;@ def StatModifierUpEffect()
;@ Moves that raise one of the user's stat stages by 1 or 2 (at most +6). Attack, Defense, Speed and Special are
;@ recomputed from the unmodified stat and the stage's ratio, capped at 999; a stat already at 999 cancels the move -
;@ but only one stage is taken back, so a +2 move still leaves +1.
;@ test: e = rand(0, 11); wPlayerMoveEffect = ATTACK_UP1_EFFECT + e if e < 6 else ATTACK_UP2_EFFECT + e - 6; wEnemyMoveEffect = wPlayerMoveEffect; hLoadedROMBank = 0x0F
StatModifierUpEffect:
;> mods, effect = addr(wPlayerMonStatMods), wPlayerMoveEffect   # the user's
	ld hl, wPlayerMonStatMods
	ld de, wPlayerMoveEffect
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .statModifierUpEffect
;>     mods, effect = addr(wEnemyMonStatMods), wEnemyMoveEffect
	ld hl, wEnemyMonStatMods
	ld de, wEnemyMoveEffect
.statModifierUpEffect
;> stat = effect - ATTACK_UP1_EFFECT & 0xFF
	ld a, [de]
	sub ATTACK_UP1_EFFECT
;> if stat >= EVASION_UP1_EFFECT + 3 - ATTACK_UP1_EFFECT:   # a +2 effect: the stat of its +1 effect
	cp EVASION_UP1_EFFECT + $3 - ATTACK_UP1_EFFECT ; covers all +1 effects
	jr c, .incrementStatMod
;>     stat = stat - (ATTACK_UP2_EFFECT - ATTACK_UP1_EFFECT) & 0xFF
	sub ATTACK_UP2_EFFECT - ATTACK_UP1_EFFECT ; map +2 effects to equivalent +1 effect
.incrementStatMod
;> stage = mem[mods + stat] + 1 & 0xFF
	ld c, a
	ld b, $0
	add hl, bc
	ld b, [hl]
	inc b ; increment corresponding stat mod
;> if stage > 13:                                    # +6 at most
;>     return PrintNothingHappenedText()
	ld a, $d
	cp b ; can't raise stat past +6 ($d or 13)
	jp c, PrintNothingHappenedText
;> if effect >= ATTACK_UP1_EFFECT + 8:               # +2
	ld a, [de]
	cp ATTACK_UP1_EFFECT + $8 ; is it a +2 effect?
	jr c, .ok
;>     stage = min(stage + 1, 13)
	inc b ; if so, increment stat mod again
	ld a, $d
	cp b ; unless it's already +6
	jr nc, .ok
	ld b, a
.ok
;> mem[mods + stat] = stage
	ld [hl], b
;> if stat >= 4:
;>     return UpdateStatDone(stat)                   # accuracy and evasion have no stat to recompute
	ld a, c
	cp $4
	jr nc, UpdateStatDone ; jump if mod affected is evasion/accuracy
;> value, base = wBattleMonAttack, wPlayerMonUnmodifiedAttack   # the user's stats
	push hl
	ld hl, wBattleMonAttack + 1
	ld de, wPlayerMonUnmodifiedAttack
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .pointToStats
;>     value, base = wEnemyMonAttack, wEnemyMonUnmodifiedAttack
	ld hl, wEnemyMonAttack + 1
	ld de, wEnemyMonUnmodifiedAttack
.pointToStats
;> value += 2 * stat
	push bc
	sla c
	ld b, $0
	add hl, bc ; hl = modified stat
;> base += 2 * stat
	ld a, c
	add e
	ld e, a
	jr nc, .checkIf999
	inc d ; de = unmodified (original) stat
.checkIf999
;> if mem[value] << 8 | mem[value + 1] == MAX_STAT_VALUE:   # already 999
	pop bc
	; check if stat is already 999
	ld a, [hld]
	sub LOW(MAX_STAT_VALUE)
	jr nz, .recalculateStat
	ld a, [hl]
	sbc HIGH(MAX_STAT_VALUE)
;>     return RestoreOriginalStatModifier(mods + stat)          # the stage back down, "Nothing happened!"
	jp z, RestoreOriginalStatModifier
.recalculateStat ; recalculate affected stat
                 ; paralysis and burn penalties, as well as badge boosts are ignored
;> ratio = StatModifierRatios
	push hl
	push bc
	ld hl, StatModifierRatios
;> ratio += 2 * (stage - 1) & 0xFF                   # two bytes each
	dec b
	sla b
	ld c, b
	ld b, $0
	add hl, bc
	pop bc
;> hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;> hMultiplicand[1:3] = [mem[base], mem[base + 1]]
	ld a, [de]
	ldh [hMultiplicand + 1], a
	inc de
	ld a, [de]
	ldh [hMultiplicand + 2], a
;> hMultiplier = mem[ratio]
;> Multiply()
	ld a, [hli]
	ldh [hMultiplier], a
	call Multiply
;> hDivisor = mem[ratio + 1]
;> Divide(4)
	ld a, [hl]
	ldh [hDivisor], a
	ld b, $4
	call Divide
	pop hl
; cap at MAX_STAT_VALUE (999)
;> if hProduct[2] << 8 | hProduct[3] >= MAX_STAT_VALUE:   # at most 999
	ldh a, [hProduct + 3]
	sub LOW(MAX_STAT_VALUE)
	ldh a, [hProduct + 2]
	sbc HIGH(MAX_STAT_VALUE)
	jp c, UpdateStat
;>     hProduct[2], hProduct[3] = hi(MAX_STAT_VALUE), lo(MAX_STAT_VALUE)
	ld a, HIGH(MAX_STAT_VALUE)
	ldh [hMultiplicand + 1], a
	ld a, LOW(MAX_STAT_VALUE)
	ldh [hMultiplicand + 2], a
;> UpdateStat(value, stat)                                   # (it follows: stores the stat)

;@ path: engine/battle/effects
;@ def UpdateStat(value: hl, stat: c)
;@ The end of StatModifierUpEffect: store the new stat from hProduct and go on with UpdateStatDone.
;@ test: skip takes the stat stage's address back from the stack
UpdateStat:
;> mem[value], mem[value + 1] = hProduct[2], hProduct[3]
;> return UpdateStatDone(stat)
	ldh a, [hProduct + 2]
	ld [hli], a
	ldh a, [hProduct + 3]
	ld [hl], a
	pop hl
;@ path: engine/battle/effects
;@ def UpdateStatDone(stat: c)
;@ After a stat went up: "<mon>'s <stat> rose!" with the move's animation. Minimize sets the minimized flag (and
;@ briefly takes down a substitute for its animation). Using any such move reapplies the player's badge boosts to
;@ every stat, and the other side's paralysis and burn penalties again.
;@ test: hLoadedROMBank = 0x0F
UpdateStatDone:
;> PrintStatText(stat + 1 & 0xFF)
	ld b, c
	inc b
	call PrintStatText
;> flags, move, minimized = wPlayerBattleStatus2, wPlayerMoveNum, addr(wPlayerMonMinimized)
	ld hl, wPlayerBattleStatus2
	ld de, wPlayerMoveNum
	ld bc, wPlayerMonMinimized
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;>     flags, move, minimized = wEnemyBattleStatus2, wEnemyMoveNum, addr(wEnemyMonMinimized)
	ld hl, wEnemyBattleStatus2
	ld de, wEnemyMoveNum
	ld bc, wEnemyMonMinimized
.playerTurn
;> if move == MINIMIZE:
	ld a, [de]
	cp MINIMIZE
	jr nz, .notMinimize
 ; if a substitute is up, slide off the substitute and show the mon pic before
 ; playing the minimize animation
;>     substitute = flags >> HAS_SUBSTITUTE_UP & 1
	bit HAS_SUBSTITUTE_UP, [hl]
	push af
	push bc
;>     if substitute:                                # it slides off for the animation
;>         farcall(HideSubstituteShowMonAnim)
	ld hl, HideSubstituteShowMonAnim
	ld b, BANK(HideSubstituteShowMonAnim)
	push de
	call nz, Bankswitch
	pop de
.notMinimize
;> PlayCurrentMoveAnimation()
	call PlayCurrentMoveAnimation
;> if move == MINIMIZE:
	ld a, [de]
	cp MINIMIZE
	jr nz, .applyBadgeBoostsAndStatusPenalties
;>     mem[minimized] = 1
	pop bc
	ld a, $1
	ld [bc], a
;>     if substitute:                                # and comes back
;>         farcall(ReshowSubstituteAnim)
	ld hl, ReshowSubstituteAnim
	ld b, BANK(ReshowSubstituteAnim)
	pop af
	call nz, Bankswitch
.applyBadgeBoostsAndStatusPenalties
;> if hWhoseTurn == 0:                              # badge boosts again, on every stat
;>     ApplyBadgeStatBoosts()
	ldh a, [hWhoseTurn]
	and a
	call z, ApplyBadgeStatBoosts ; whenever the player uses a stat-up move, badge boosts get reapplied again to every stat,
	                             ; even to those not affected by the stat-up move (will be boosted further)
;> PrintText(MonsStatsRoseText)
	ld hl, MonsStatsRoseText
	call PrintText

; these shouldn't be here
;> QuarterSpeedDueToParalysis()                      # (the other side's penalties again)
	call QuarterSpeedDueToParalysis ; apply speed penalty to the player whose turn is not, if it's paralyzed
;> HalveAttackDueToBurn()
	jp HalveAttackDueToBurn ; apply attack penalty to the player whose turn is not, if it's burned

;@ path: engine/battle/effects
;@ def RestoreOriginalStatModifier(stage)
;@ The stat is already at 999: take one stage back and print "Nothing happened!".
;@ test: skip takes the stat stage's address from the stack
RestoreOriginalStatModifier:
;> mem[stage] -= 1
;> return PrintNothingHappenedText()
	pop hl
	dec [hl]

;@ path: engine/battle/effects
;@ def PrintNothingHappenedText()
;@ "Nothing happened!"
;@ test: hLoadedROMBank = 0x0F
PrintNothingHappenedText:
;> return PrintText(NothingHappenedText)
	ld hl, NothingHappenedText
	jp PrintText

;@ path: engine/battle/effects
;@ def MonsStatsRoseText() -> hl
;@ "<mon>'s <stat>" and then "greatly rose!" for a +2 move or "rose!" for a +1 move.
;@ test: skip a text script: the code after text_asm runs from the text engine
MonsStatsRoseText:
	db TX_FAR
	dw _MonsStatsRoseText
	db BANK(_MonsStatsRoseText)
	db TX_START_ASM
;> text = GreatlyRoseText
	ld hl, GreatlyRoseText
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> effect = wPlayerMoveEffect
;> if not player:
	ld a, [wPlayerMoveEffect]
	jr z, .playerTurn
;>     effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
.playerTurn
;> if effect >= ATTACK_DOWN1_EFFECT:                 # the +2 effects come after the -1 ones
;>     return text
	cp ATTACK_DOWN1_EFFECT
	ret nc
;> return RoseText
	ld hl, RoseText
	ret

;@ path: engine/battle/effects
GreatlyRoseText:
	db TX_PAUSE
	db TX_FAR
	dw _GreatlyRoseText
	db BANK(_GreatlyRoseText)
; fallthrough
;@ path: engine/battle/effects
RoseText:
	db TX_FAR
	dw _RoseText
	db BANK(_RoseText)
	db TX_END

;@ path: engine/battle/effects
;@ def StatModifierDownEffect()
;@ Moves that lower one of the target's stat stages by 1 or 2 (at least -6), and the side effects that lower one by
;@ 1 a third of the time. Outside link battles the enemy's moves of this kind miss a quarter of the time. Substitutes
;@ block them; Fly and Dig dodge them. The stat is recomputed and never drops below 1.
;@ test: e = rand(0, 15); wPlayerMoveEffect = ATTACK_DOWN1_EFFECT + e if e < 6 else ATTACK_DOWN2_EFFECT + e - 6 if e < 12 else ATTACK_DOWN_SIDE_EFFECT + e - 12; wEnemyMoveEffect = wPlayerMoveEffect; hLoadedROMBank = 0x0F
StatModifierDownEffect:
;> mods, effect, flags = addr(wEnemyMonStatMods), addr(wPlayerMoveEffect), addr(wEnemyBattleStatus1)
	ld hl, wEnemyMonStatMods
	ld de, wPlayerMoveEffect
	ld bc, wEnemyBattleStatus1
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .statModifierDownEffect
;>     mods, effect, flags = addr(wPlayerMonStatMods), addr(wEnemyMoveEffect), addr(wPlayerBattleStatus1)
	ld hl, wPlayerMonStatMods
	ld de, wEnemyMoveEffect
	ld bc, wPlayerBattleStatus1
;>     if wLinkState != LINK_STATE_BATTLING:
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr z, .statModifierDownEffect
;>         if BattleRandom() < 25 * 255 // 100 + 1:  # the enemy misses a quarter of the time
;>             return MoveMissed(effect)
	call BattleRandom
	cp 25 * $ff / 100 + 1 ; chance to miss by in regular battle
	jp c, MoveMissed
.statModifierDownEffect
;> if not CheckTargetSubstitute():
;>     return MoveMissed(effect)
	call CheckTargetSubstitute ; can't hit through substitute
	jp nz, MoveMissed
;> if mem[effect] >= ATTACK_DOWN_SIDE_EFFECT:        # a side effect: a third of the time
	ld a, [de]
	cp ATTACK_DOWN_SIDE_EFFECT
	jr c, .nonSideEffect
;>     if BattleRandom() >= 33 * 255 // 100 + 1:
;>         return CantLowerAnymore(effect)
	call BattleRandom
	cp 33 * $ff / 100 + 1 ; chance for side effects
	jp nc, CantLowerAnymore
;>     stat = mem[effect] - ATTACK_DOWN_SIDE_EFFECT
	ld a, [de]
	sub ATTACK_DOWN_SIDE_EFFECT ; map each stat to 0-3
;> else:
	jr .decrementStatMod
.nonSideEffect ; non-side effects only
;>     MoveHitTest()
	push hl
	push de
	push bc
	call MoveHitTest ; apply accuracy tests
;>     if wMoveMissed:
;>         return MoveMissed(effect)
	pop bc
	pop de
	pop hl
	ld a, [wMoveMissed]
	and a
	jp nz, MoveMissed
;>     if mem[flags] >> INVULNERABLE & 1:            # Fly, Dig
;>         return MoveMissed(effect)
	ld a, [bc]
	bit INVULNERABLE, a ; fly/dig
	jp nz, MoveMissed
;>     stat = mem[effect] - ATTACK_DOWN1_EFFECT & 0xFF
	ld a, [de]
	sub ATTACK_DOWN1_EFFECT
;>     if stat >= EVASION_DOWN1_EFFECT + 3 - ATTACK_DOWN1_EFFECT:   # a -2 effect: the stat of its -1 effect
	cp EVASION_DOWN1_EFFECT + $3 - ATTACK_DOWN1_EFFECT ; covers all -1 effects
	jr c, .decrementStatMod
;>         stat = stat - (ATTACK_DOWN2_EFFECT - ATTACK_DOWN1_EFFECT) & 0xFF
	sub ATTACK_DOWN2_EFFECT - ATTACK_DOWN1_EFFECT ; map -2 effects to corresponding -1 effect
.decrementStatMod
;> stage = mem[mods + stat] - 1 & 0xFF
	ld c, a
	ld b, $0
	add hl, bc
	ld b, [hl]
	dec b ; dec corresponding stat mod
;> if stage == 0:                                    # -6 at most
;>     return CantLowerAnymore(effect)
	jp z, CantLowerAnymore ; if stat mod is 1 (-6), can't lower anymore
;> if ATTACK_DOWN2_EFFECT - 0x16 <= mem[effect] < ATTACK_DOWN_SIDE_EFFECT:   # -2 moves only
	ld a, [de]
	cp ATTACK_DOWN2_EFFECT - $16 ; $24
	jr c, .ok
	cp ATTACK_DOWN_SIDE_EFFECT ; move side effects, stat mod decrease is always 1
	jr nc, .ok
;>     stage = max(stage - 1, 1)
	dec b ; stat down 2 effects only (dec mod again)
	jr nz, .ok
	inc b ; increment mod to 1 (-6) if it would become 0 (-7)
.ok
;> mem[mods + stat] = stage
	ld [hl], b ; save modified mod
;> if stat >= 4:
;>     return UpdateLoweredStatDone(stat, effect)    # accuracy and evasion have no stat to recompute
	ld a, c
	cp $4
	jr nc, UpdateLoweredStatDone ; jump for evasion/accuracy
;> value, base = wEnemyMonAttack, wEnemyMonUnmodifiedAttack   # the target's stats
	push hl
	push de
	ld hl, wEnemyMonAttack + 1
	ld de, wEnemyMonUnmodifiedAttack
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .pointToStat
;>     value, base = wBattleMonAttack, wPlayerMonUnmodifiedAttack
	ld hl, wBattleMonAttack + 1
	ld de, wPlayerMonUnmodifiedAttack
.pointToStat
;> value += 2 * stat
	push bc
	sla c
	ld b, $0
	add hl, bc ; hl = modified stat
;> base += 2 * stat
	ld a, c
	add e
	ld e, a
	jr nc, .noCarry
	inc d ; de = unmodified stat
.noCarry
;> if mem[value] << 8 | mem[value + 1] == 1:         # already down to 1
	pop bc
	ld a, [hld]
	sub $1 ; can't lower stat below 1 (-6)
	jr nz, .recalculateStat
	ld a, [hl]
	and a
;>     return CantLowerAnymore_Pop(effect, mods + stat)              # the stage back up, "Nothing happened!"
	jp z, CantLowerAnymore_Pop
.recalculateStat
; recalculate affected stat
; paralysis and burn penalties, as well as badge boosts are ignored
;> ratio = StatModifierRatios
	push hl
	push bc
	ld hl, StatModifierRatios
;> ratio += 2 * (stage - 1) & 0xFF                   # two bytes each
	dec b
	sla b
	ld c, b
	ld b, $0
	add hl, bc
	pop bc
;> hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;> hMultiplicand[1:3] = [mem[base], mem[base + 1]]
	ld a, [de]
	ldh [hMultiplicand + 1], a
	inc de
	ld a, [de]
	ldh [hMultiplicand + 2], a
;> hMultiplier = mem[ratio]
;> Multiply()
	ld a, [hli]
	ldh [hMultiplier], a
	call Multiply
;> hDivisor = mem[ratio + 1]
;> Divide(4)
	ld a, [hl]
	ldh [hDivisor], a
	ld b, $4
	call Divide
	pop hl
;> if hProduct[2] == 0 and hProduct[3] == 0:
	ldh a, [hProduct + 3]
	ld b, a
	ldh a, [hProduct + 2]
	or b
	jp nz, UpdateLoweredStat
;>     hProduct[2], hProduct[3] = 0, 1               # at least 1
	ldh [hMultiplicand + 1], a
	ld a, $1
	ldh [hMultiplicand + 2], a
;> UpdateLoweredStat(value, stat, effect)                            # (it follows: stores the stat)

;@ path: engine/battle/effects
;@ def UpdateLoweredStat(value: hl, stat: c, effect)
;@ The end of StatModifierDownEffect: store the new stat from hProduct and go on with UpdateLoweredStatDone.
;@ test: skip takes the move effect's and the stat stage's addresses back from the stack
UpdateLoweredStat:
;> mem[value], mem[value + 1] = hProduct[2], hProduct[3]
;> return UpdateLoweredStatDone(stat, effect)
	ldh a, [hProduct + 2]
	ld [hli], a
	ldh a, [hProduct + 3]
	ld [hl], a
	pop de
	pop hl
;@ path: engine/battle/effects
;@ def UpdateLoweredStatDone(stat: c, effect: de)
;@ After a stat went down: "<mon>'s <stat> fell!", with the move's animation unless a side effect already showed
;@ it. Every such move of the enemy reapplies the player's badge boosts to every stat, and the paralysis and burn
;@ penalties are applied again whichever stat fell.
;@ test: hLoadedROMBank = 0x0F
UpdateLoweredStatDone:
;> PrintStatText(stat + 1 & 0xFF)
	ld b, c
	inc b
	push de
	call PrintStatText
	pop de
;> if mem[effect] < ATTACK_DOWN_SIDE_EFFECT:
	ld a, [de]
	cp ATTACK_DOWN_SIDE_EFFECT ; for all side effects, move animation has already played, skip it
	jr nc, .ApplyBadgeBoostsAndStatusPenalties
;>     PlayCurrentMoveAnimation2()
	call PlayCurrentMoveAnimation2
.ApplyBadgeBoostsAndStatusPenalties
;> if hWhoseTurn != 0:
;>     ApplyBadgeStatBoosts()
	ldh a, [hWhoseTurn]
	and a
	call nz, ApplyBadgeStatBoosts ; whenever the opponent uses a stat-down move, badge boosts get reapplied again to every stat,
	                              ; even to those not affected by the stat-down move (will be boosted further)
;> PrintText(MonsStatsFellText)
	ld hl, MonsStatsFellText
	call PrintText

; These where probably added given that a stat-down move affecting speed or attack will override
; the stat penalties from paralysis and burn respectively.
; But they are always called regardless of the stat affected by the stat-down move.
;> QuarterSpeedDueToParalysis()
	call QuarterSpeedDueToParalysis
;> HalveAttackDueToBurn()
	jp HalveAttackDueToBurn

;@ path: engine/battle/effects
;@ def CantLowerAnymore_Pop(effect, stage)
;@ The stat is already 1: give the stage back and go on with CantLowerAnymore.
;@ test: skip takes the move effect's and the stat stage's addresses from the stack
CantLowerAnymore_Pop:
;> mem[stage] += 1
;> return CantLowerAnymore(effect)
	pop de
	pop hl
	inc [hl]

;@ path: engine/battle/effects
;@ def CantLowerAnymore(effect: de)
;@ "Nothing happened!" - but not for side effects, which fail silently.
;@ test: hLoadedROMBank = 0x0F
CantLowerAnymore:
;> if mem[effect] >= ATTACK_DOWN_SIDE_EFFECT:        # side effects fail silently
;>     return
	ld a, [de]
	cp ATTACK_DOWN_SIDE_EFFECT
	ret nc
;> PrintText(NothingHappenedText)
	ld hl, NothingHappenedText
	jp PrintText

;@ path: engine/battle/effects
;@ def MoveMissed(effect: de)
;@ A stat-lowering move missed: "But it failed!" - but not for side effects, which fail silently.
;@ test: hLoadedROMBank = 0x0F
MoveMissed:
;> if mem[effect] >= ATTACK_DOWN_SIDE_EFFECT:        # side effects fail silently
;>     return
	ld a, [de]
	cp ATTACK_DOWN_SIDE_EFFECT
	ret nc
;> ConditionalPrintButItFailed()
	jp ConditionalPrintButItFailed

;@ path: engine/battle/effects
;@ def MonsStatsFellText() -> hl
;@ "<mon>'s <stat>" and then "greatly fell!" for a -2 move or "fell!" for the others.
;@ test: skip a text script: the code after text_asm runs from the text engine
MonsStatsFellText:
	db TX_FAR
	dw _MonsStatsFellText
	db BANK(_MonsStatsFellText)
	db TX_START_ASM
;> text = FellText
	ld hl, FellText
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> effect = wPlayerMoveEffect
;> if not player:
	ld a, [wPlayerMoveEffect]
	jr z, .playerTurn
;>     effect = wEnemyMoveEffect
	ld a, [wEnemyMoveEffect]
.playerTurn
; check if the move's effect decreases a stat by 2
;> if effect < BIDE_EFFECT:                          # the -1 effects
;>     return text
	cp BIDE_EFFECT
	ret c
;> if effect >= ATTACK_DOWN_SIDE_EFFECT:             # side effects
;>     return text
	cp ATTACK_DOWN_SIDE_EFFECT
	ret nc
;> return GreatlyFellText                            # the -2 effects
	ld hl, GreatlyFellText
	ret

;@ path: engine/battle/effects
GreatlyFellText:
	db TX_PAUSE
	db TX_FAR
	dw _GreatlyFellText
	db BANK(_GreatlyFellText)
; fallthrough
;@ path: engine/battle/effects
FellText:
	db TX_FAR
	dw _FellText
	db BANK(_FellText)
	db TX_END

;@ path: engine/battle/effects
;@ def PrintStatText(stat: b)
;@ Copy the name of a stat (1 = attack, ..., 6 = evasion: StatModTextStrings) to wStringBuffer.
;@ test: stat = rand(1, 6); hLoadedROMBank = 0x0F
PrintStatText:
;> text = StatModTextStrings
	ld hl, StatModTextStrings
	ld c, '@'
.findStatName_outer
;> for _ in range(stat - 1 & 0xFF):
	dec b
	jr z, .foundStatName
.findStatName_inner
;>@skip     while True:                               # past the next name
;>         ch = mem[text]; text += 1
	ld a, [hli]
;>         if ch == charmap('@')[0]:
;>             break
	cp c
	jr z, .findStatName_outer
;=@skip
	jr .findStatName_inner
.foundStatName
;> CopyData(text, wStringBuffer + 0, STAT_NAME_LENGTH)
	ld de, wStringBuffer
	ld bc, STAT_NAME_LENGTH
	jp CopyData

; Stats that move effects can raise or lower
; The relevant move effect IDs correspond to the stats

;@ path: engine/battle/effects
StatModTextStrings:
	db "ATTACK", "@"
	db "DEFENSE", "@"
	db "SPEED", "@"
	db "SPECIAL", "@"
	db "ACCURACY", "@"
	db "EVADE", "@"
	; two bytes are unused

;@ path: engine/battle/effects
StatModifierRatios:
; first byte is numerator, second byte is denominator
	db 25, 100  ; 0.25
	db 28, 100  ; 0.28
	db 33, 100  ; 0.33
	db 40, 100  ; 0.40
	db 50, 100  ; 0.50
	db 66, 100  ; 0.66
	db  1,   1  ; 1.00
	db 15,  10  ; 1.50
	db  2,   1  ; 2.00
	db 25,  10  ; 2.50
	db  3,   1  ; 3.00
	db 35,  10  ; 3.50
	db  4,   1  ; 4.00

;@ path: engine/battle/effects
;@ def BideEffect()
;@ Bide: the user stores energy for 2 or 3 turns, counting the damage it takes from 0.
;@ test: hLoadedROMBank = 0x0F
BideEffect:
;> flags, damage, counter = addr(wPlayerBattleStatus1), wPlayerBideAccumulatedDamage, addr(wPlayerNumAttacksLeft)
	ld hl, wPlayerBattleStatus1
	ld de, wPlayerBideAccumulatedDamage
	ld bc, wPlayerNumAttacksLeft
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .bideEffect
;>     flags, damage, counter = addr(wEnemyBattleStatus1), wEnemyBideAccumulatedDamage, addr(wEnemyNumAttacksLeft)
	ld hl, wEnemyBattleStatus1
	ld de, wEnemyBideAccumulatedDamage
	ld bc, wEnemyNumAttacksLeft
.bideEffect
;> mem[flags] |= 1 << STORING_ENERGY
	set STORING_ENERGY, [hl] ; mon is now using bide
;> damage[0] = 0
	xor a
	ld [de], a
;> damage[1] = 0
	inc de
	ld [de], a
;> wPlayerMoveEffect = 0
	ld [wPlayerMoveEffect], a
;> wEnemyMoveEffect = 0
	ld [wEnemyMoveEffect], a
;> mem[counter] = 2 + (BattleRandom() & 1)
	call BattleRandom
	and $1
	inc a
	inc a
	ld [bc], a ; set Bide counter to 2 or 3 at random
;> PlayBattleAnimation2(XSTATITEM_ANIM + hWhoseTurn & 0xFF)
	ldh a, [hWhoseTurn]
	add XSTATITEM_ANIM
	jp PlayBattleAnimation2

;@ path: engine/battle/effects
;@ def ThrashPetalDanceEffect()
;@ Thrash and Petal Dance: the user keeps attacking for 2 or 3 more turns.
;@ test: hLoadedROMBank = 0x0F
ThrashPetalDanceEffect:
;> flags, counter = addr(wPlayerBattleStatus1), addr(wPlayerNumAttacksLeft)
	ld hl, wPlayerBattleStatus1
	ld de, wPlayerNumAttacksLeft
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .thrashPetalDanceEffect
;>     flags, counter = addr(wEnemyBattleStatus1), addr(wEnemyNumAttacksLeft)
	ld hl, wEnemyBattleStatus1
	ld de, wEnemyNumAttacksLeft
.thrashPetalDanceEffect
;> mem[flags] |= 1 << THRASHING_ABOUT
	set THRASHING_ABOUT, [hl] ; mon is now using thrash/petal dance
;> mem[counter] = 2 + (BattleRandom() & 1)
	call BattleRandom
	and $1
	inc a
	inc a
	ld [de], a ; set thrash/petal dance counter to 2 or 3 at random
;> PlayBattleAnimation2(SHRINKING_SQUARE_ANIM + hWhoseTurn & 0xFF)
	ldh a, [hWhoseTurn]
	add SHRINKING_SQUARE_ANIM
	jp PlayBattleAnimation2

;@ path: engine/battle/effects
;@ def SwitchAndTeleportEffect()
;@ Teleport, Roar and Whirlwind end a wild battle. They always work if the user's level is at least the target's;
;@ otherwise a random number below the sum of both levels (plus 1) must reach a quarter of the target's level.
;@ They do nothing in trainer battles.
;@ test: wCurEnemyLevel = rand(1, 100); mem[0xD022] = rand(1, 100); hLoadedROMBank = 0x0F
SwitchAndTeleportEffect:
;> if hWhoseTurn == 0:                                # the player's move
	ldh a, [hWhoseTurn]
	and a
	jr nz, .handleEnemy
;>     if wIsInBattle == 1:                          # a wild battle
	ld a, [wIsInBattle]
	dec a
	jr nz, .notWildBattle1
;>         other = wCurEnemyLevel
	ld a, [wCurEnemyLevel]
	ld b, a
;>         own = mem[wBattleMonLevel]
;>         if own < other:                           # else it always works
	ld a, [wBattleMonLevel]
	cp b ; is the player's level greater than the enemy's level?
	jr nc, .playerMoveWasSuccessful ; if so, teleport will always succeed
;>             limit = own + other + 1 & 0xFF
	add b
	ld c, a
	inc c ; c = playerLevel + enemyLevel + 1
.rejectionSampleLoop1
;>             while True:
;>                 r = BattleRandom()
	call BattleRandom
;>                 if r < limit:
;>                     break
	cp c ; get a random number between 0 and c
	jr nc, .rejectionSampleLoop1
;>             if r < other >> 2:                    # a quarter of the other's level
	srl b
	srl b  ; b = enemyLevel / 4
	cp b ; is rand[0, playerLevel + enemyLevel] >= (enemyLevel / 4)?
	jr nc, .playerMoveWasSuccessful ; if so, allow teleporting
;>                 DelayFrames(50)
	ld c, 50
	call DelayFrames
;>                 if wPlayerMoveNum != TELEPORT:
;>                     return PrintDidntAffectText()
	ld a, [wPlayerMoveNum]
	cp TELEPORT
	jp nz, PrintDidntAffectText
;>                 return PrintButItFailedText_()
	jp PrintButItFailedText_
.playerMoveWasSuccessful
;>         ReadPlayerMonCurHPAndStatus()
	call ReadPlayerMonCurHPAndStatus
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         wEscapedFromBattle = 1
	inc a
	ld [wEscapedFromBattle], a
;>         move = wPlayerMoveNum
	ld a, [wPlayerMoveNum]
	jr .playAnimAndPrintText
.notWildBattle1
;>     else:                                         # a trainer battle: no effect
;>         DelayFrames(50)
	ld c, 50
	call DelayFrames
;>         if wPlayerMoveNum != TELEPORT:
;>             return PrintText(IsUnaffectedText)
	ld hl, IsUnaffectedText
	ld a, [wPlayerMoveNum]
	cp TELEPORT
	jp nz, PrintText
;>         return PrintButItFailedText_()
	jp PrintButItFailedText_
.handleEnemy
;> else:                                             # the enemy's
;>     if wIsInBattle == 1:                          # a wild battle
	ld a, [wIsInBattle]
	dec a
	jr nz, .notWildBattle2
;>         other = mem[wBattleMonLevel]
	ld a, [wBattleMonLevel]
	ld b, a
;>         own = wCurEnemyLevel
;>         if own < other:                           # else it always works
	ld a, [wCurEnemyLevel]
	cp b
	jr nc, .enemyMoveWasSuccessful
;>             limit = own + other + 1 & 0xFF
	add b
	ld c, a
	inc c
.rejectionSampleLoop2
;>             while True:
;>                 r = BattleRandom()
	call BattleRandom
;>                 if r < limit:
;>                     break
	cp c
	jr nc, .rejectionSampleLoop2
;>             if r < other >> 2:                    # a quarter of the other's level
	srl b
	srl b
	cp b
	jr nc, .enemyMoveWasSuccessful
;>                 DelayFrames(50)
	ld c, 50
	call DelayFrames
;>                 if wEnemyMoveNum != TELEPORT:
;>                     return PrintDidntAffectText()
	ld a, [wEnemyMoveNum]
	cp TELEPORT
	jp nz, PrintDidntAffectText
;>                 return PrintButItFailedText_()
	jp PrintButItFailedText_
.enemyMoveWasSuccessful
;>         ReadPlayerMonCurHPAndStatus()
	call ReadPlayerMonCurHPAndStatus
;>         wAnimationType = 0
	xor a
	ld [wAnimationType], a
;>         wEscapedFromBattle = 1
	inc a
	ld [wEscapedFromBattle], a
;>         move = wEnemyMoveNum
	ld a, [wEnemyMoveNum]
	jr .playAnimAndPrintText
.notWildBattle2
;>     else:                                         # a trainer battle: no effect
;>         DelayFrames(50)
	ld c, 50
	call DelayFrames
;>         if wEnemyMoveNum != TELEPORT:
;>             return PrintText(IsUnaffectedText)
	ld hl, IsUnaffectedText
	ld a, [wEnemyMoveNum]
	cp TELEPORT
	jp nz, PrintText
;>         return ConditionalPrintButItFailed()
	jp ConditionalPrintButItFailed
.playAnimAndPrintText
;> PlayBattleAnimation(move)
	push af
	call PlayBattleAnimation
;> DelayFrames(20)
	ld c, 20
	call DelayFrames
	pop af
;> text = RanFromBattleText
;> if move != TELEPORT:
	ld hl, RanFromBattleText
	cp TELEPORT
	jr z, .printText
;>     text = RanAwayScaredText
;>     if move != ROAR:
	ld hl, RanAwayScaredText
	cp ROAR
	jr z, .printText
;>         text = WasBlownAwayText                   # Whirlwind
	ld hl, WasBlownAwayText
.printText
;> PrintText(text)
	jp PrintText

;@ path: engine/battle/effects
RanFromBattleText:
	db TX_FAR
	dw _RanFromBattleText
	db BANK(_RanFromBattleText)
	db TX_END

;@ path: engine/battle/effects
RanAwayScaredText:
	db TX_FAR
	dw _RanAwayScaredText
	db BANK(_RanAwayScaredText)
	db TX_END

;@ path: engine/battle/effects
WasBlownAwayText:
	db TX_FAR
	dw _WasBlownAwayText
	db BANK(_WasBlownAwayText)
	db TX_END

;@ path: engine/battle/effects
;@ def TwoToFiveAttacksEffect()
;@ Moves that hit several times: 2 (Double Kick and the like; also Twineedle, whose effect becomes the poison side
;@ effect), else 2 or 3 hits with 3/8 chance each and 4 or 5 with 1/8.
;@ test: hLoadedROMBank = 0x0F
TwoToFiveAttacksEffect:
;> flags, left, hits = addr(wPlayerBattleStatus1), addr(wPlayerNumAttacksLeft), addr(wPlayerNumHits)
	ld hl, wPlayerBattleStatus1
	ld de, wPlayerNumAttacksLeft
	ld bc, wPlayerNumHits
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .twoToFiveAttacksEffect
;>     flags, left, hits = addr(wEnemyBattleStatus1), addr(wEnemyNumAttacksLeft), addr(wEnemyNumHits)
	ld hl, wEnemyBattleStatus1
	ld de, wEnemyNumAttacksLeft
	ld bc, wEnemyNumHits
.twoToFiveAttacksEffect
;> if mem[flags] >> ATTACKING_MULTIPLE_TIMES & 1:
;>     return
	bit ATTACKING_MULTIPLE_TIMES, [hl] ; is mon attacking multiple times?
	ret nz
;> mem[flags] |= 1 << ATTACKING_MULTIPLE_TIMES
	set ATTACKING_MULTIPLE_TIMES, [hl] ; mon is now attacking multiple times
;> effect = addr(wPlayerMoveEffect)
	ld hl, wPlayerMoveEffect
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .setNumberOfHits
;>     effect = addr(wEnemyMoveEffect)
	ld hl, wEnemyMoveEffect
.setNumberOfHits
;> if mem[effect] == TWINEEDLE_EFFECT:
;>@tw1     n = POISON_SIDE_EFFECT1                       # which happens to be 2
;>@tw2     mem[effect] = POISON_SIDE_EFFECT1
	ld a, [hl]
	cp TWINEEDLE_EFFECT
	jr z, .twineedle
;> elif mem[effect] == ATTACK_TWICE_EFFECT:
;>     n = 2
	cp ATTACK_TWICE_EFFECT
	ld a, $2 ; number of hits it's always 2 for ATTACK_TWICE_EFFECT
	jr z, .saveNumberOfHits
; for TWO_TO_FIVE_ATTACKS_EFFECT 3/8 chance for 2 and 3 hits, and 1/8 chance for 4 and 5 hits
;> else:
;>     n = BattleRandom() & 3
	call BattleRandom
	and $3
;>     if n >= 2:
	cp $2
	jr c, .gotNumHits
; if the number of hits was greater than 2, re-roll again for a lower chance
;>         n = BattleRandom() & 3                    # a second roll for more than 3 hits
	call BattleRandom
	and $3
.gotNumHits
;>     n += 2
	inc a
	inc a
.saveNumberOfHits
;> mem[left] = n
	ld [de], a
;> mem[hits] = n
	ld [bc], a
	ret
.twineedle
;=@tw1
	ld a, POISON_SIDE_EFFECT1
;=@tw2
	ld [hl], a ; set Twineedle's effect to poison effect
	jr .saveNumberOfHits

;@ path: engine/battle/effects
;@ def FlinchSideEffect()
;@ Flinch side effects: 10% or 30%; a flinching target also loses its recharge turn. Not through a substitute.
;@ test: hLoadedROMBank = 0x0F
FlinchSideEffect:
;> if not CheckTargetSubstitute():
;>     return
	call CheckTargetSubstitute
	ret nz
;> flags, effect = addr(wEnemyBattleStatus1), wPlayerMoveEffect
	ld hl, wEnemyBattleStatus1
	ld de, wPlayerMoveEffect
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .flinchSideEffect
;>     flags, effect = addr(wPlayerBattleStatus1), wEnemyMoveEffect
	ld hl, wPlayerBattleStatus1
	ld de, wEnemyMoveEffect
.flinchSideEffect
;> chance = 10 * 255 // 100 + 1 if effect == FLINCH_SIDE_EFFECT1 else 30 * 255 // 100 + 1
	ld a, [de]
	cp FLINCH_SIDE_EFFECT1
	ld b, 10 * $ff / 100 + 1 ; chance of flinch (FLINCH_SIDE_EFFECT1)
	jr z, .gotEffectChance
	ld b, 30 * $ff / 100 + 1 ; chance of flinch otherwise
.gotEffectChance
;> if BattleRandom() >= chance:
;>     return
	call BattleRandom
	cp b
	ret nc
;> mem[flags] |= 1 << FLINCHED
	set FLINCHED, [hl] ; set mon's status to flinching
;> ClearHyperBeam()
	call ClearHyperBeam
	ret

;@ path: engine/battle/effects
;@ def OneHitKOEffect()
;@ Fissure, Guillotine and Horn Drill (the work is done in another bank).
;@ test: hLoadedROMBank = 0x0F
OneHitKOEffect:
;> return Bankswitch(BANK(OneHitKOEffect_), OneHitKOEffect_)
	ld hl, OneHitKOEffect_
	ld b, BANK(OneHitKOEffect_)
	jp Bankswitch

;@ path: engine/battle/effects
;@ def ChargeEffect()
;@ Moves that charge up for a turn. Fly and Dig also make the user unreachable for most attacks; each move gets its
;@ own animation and message.
;@ test: hLoadedROMBank = 0x0F
ChargeEffect:
;> flags, effect, move = addr(wPlayerBattleStatus1), wPlayerMoveEffect, wPlayerMoveNum   # the user's
	ld hl, wPlayerBattleStatus1
	ld de, wPlayerMoveEffect
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> anim = XSTATITEM_ANIM
;> if not player:
	ld b, XSTATITEM_ANIM
	jr z, .chargeEffect
;>     flags, effect, move = addr(wEnemyBattleStatus1), wEnemyMoveEffect, wEnemyMoveNum
	ld hl, wEnemyBattleStatus1
	ld de, wEnemyMoveEffect
;>     anim = XSTATITEM_DUPLICATE_ANIM
	ld b, XSTATITEM_DUPLICATE_ANIM
.chargeEffect
;> mem[flags] |= 1 << CHARGING_UP
	set CHARGING_UP, [hl]
;> if effect == FLY_EFFECT:
	ld a, [de]
	dec de ; de contains enemy or player MOVENUM
	cp FLY_EFFECT
	jr nz, .notFly
;>     mem[flags] |= 1 << INVULNERABLE               # out of reach
;>     anim = TELEPORT                               # Teleport's animation
	set INVULNERABLE, [hl] ; mon is now invulnerable to typical attacks (fly/dig)
	ld b, TELEPORT ; load Teleport's animation
.notFly
;> if move == DIG:
	ld a, [de]
	cp DIG
	jr nz, .notDigOrFly
;>     mem[flags] |= 1 << INVULNERABLE
;>     anim = SLIDE_DOWN_ANIM
	set INVULNERABLE, [hl] ; mon is now invulnerable to typical attacks (fly/dig)
	ld b, SLIDE_DOWN_ANIM
.notDigOrFly
;> wAnimationType = 0
	xor a
	ld [wAnimationType], a
;> PlayBattleAnimation(anim)
	ld a, b
	call PlayBattleAnimation
;> wChargeMoveNum[0] = move
	ld a, [de]
	ld [wChargeMoveNum], a
;> PrintText(ChargeMoveEffectText)
	ld hl, ChargeMoveEffectText
	jp PrintText

;@ path: engine/battle/effects
;@ def ChargeMoveEffectText() -> hl
;@ "<mon>" and then the charging move's own words (Razor Wind, Solarbeam, Skull Bash, Sky Attack, Fly, Dig).
;@ test: skip a text script: the code after text_asm runs from the text engine
ChargeMoveEffectText:
	db TX_FAR
	dw _ChargeMoveEffectText
	db BANK(_ChargeMoveEffectText)
	db TX_START_ASM
;> move = wChargeMoveNum[0]
	ld a, [wChargeMoveNum]
;> if move == RAZOR_WIND:
;>     return MadeWhirlwindText
	cp RAZOR_WIND
	ld hl, MadeWhirlwindText
	jr z, .gotText
;> if move == SOLARBEAM:
;>     return TookInSunlightText
	cp SOLARBEAM
	ld hl, TookInSunlightText
	jr z, .gotText
;> if move == SKULL_BASH:
;>     return LoweredItsHeadText
	cp SKULL_BASH
	ld hl, LoweredItsHeadText
	jr z, .gotText
;> if move == SKY_ATTACK:
;>     return SkyAttackGlowingText
	cp SKY_ATTACK
	ld hl, SkyAttackGlowingText
	jr z, .gotText
;> if move == FLY:
;>     return FlewUpHighText
	cp FLY
	ld hl, FlewUpHighText
	jr z, .gotText
;> return DugAHoleText                              # (Dig; anything else gets it too)
	cp DIG
	ld hl, DugAHoleText
.gotText
	ret

;@ path: engine/battle/effects
MadeWhirlwindText:
	db TX_FAR
	dw _MadeWhirlwindText
	db BANK(_MadeWhirlwindText)
	db TX_END

;@ path: engine/battle/effects
TookInSunlightText:
	db TX_FAR
	dw _TookInSunlightText
	db BANK(_TookInSunlightText)
	db TX_END

;@ path: engine/battle/effects
LoweredItsHeadText:
	db TX_FAR
	dw _LoweredItsHeadText
	db BANK(_LoweredItsHeadText)
	db TX_END

;@ path: engine/battle/effects
SkyAttackGlowingText:
	db TX_FAR
	dw _SkyAttackGlowingText
	db BANK(_SkyAttackGlowingText)
	db TX_END

;@ path: engine/battle/effects
FlewUpHighText:
	db TX_FAR
	dw _FlewUpHighText
	db BANK(_FlewUpHighText)
	db TX_END

;@ path: engine/battle/effects
DugAHoleText:
	db TX_FAR
	dw _DugAHoleText
	db BANK(_DugAHoleText)
	db TX_END

;@ path: engine/battle/effects
;@ def TrappingEffect()
;@ Wrap, Bind, Clamp and Fire Spin: the user traps the target for 2 to 5 turns (3/8 chance each for 2 and 3, 1/8
;@ for 4 and 5). The target loses its recharge turn even if the move then misses.
;@ test: hLoadedROMBank = 0x0F
TrappingEffect:
;> flags, counter = addr(wPlayerBattleStatus1), addr(wPlayerNumAttacksLeft)
	ld hl, wPlayerBattleStatus1
	ld de, wPlayerNumAttacksLeft
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .trappingEffect
;>     flags, counter = addr(wEnemyBattleStatus1), addr(wEnemyNumAttacksLeft)
	ld hl, wEnemyBattleStatus1
	ld de, wEnemyNumAttacksLeft
.trappingEffect
;> if mem[flags] >> USING_TRAPPING_MOVE & 1:
;>     return
	bit USING_TRAPPING_MOVE, [hl]
	ret nz
;> ClearHyperBeam()
	call ClearHyperBeam ; since this effect is called before testing whether the move will hit,
                        ; the target won't need to recharge even if the trapping move missed
;> mem[flags] |= 1 << USING_TRAPPING_MOVE
	set USING_TRAPPING_MOVE, [hl] ; mon is now using a trapping move
;> n = BattleRandom() & 3
	call BattleRandom ; 3/8 chance for 2 and 3 attacks, and 1/8 chance for 4 and 5 attacks
	and $3
;> if n >= 2:
	cp $2
	jr c, .setTrappingCounter
;>     n = BattleRandom() & 3
	call BattleRandom
	and $3
.setTrappingCounter
;> mem[counter] = n + 1  # turns left after this one
	inc a
	ld [de], a
	ret

;@ path: engine/battle/effects
;@ def MistEffect()
;@ Mist (the work is done in another bank).
;@ test: hLoadedROMBank = 0x0E
MistEffect:
;> return Bankswitch(BANK(MistEffect_), MistEffect_)
	ld hl, MistEffect_
	ld b, BANK(MistEffect_)
	jp Bankswitch

;@ path: engine/battle/effects
;@ def FocusEnergyEffect()
;@ Focus Energy (the work is done in another bank).
;@ test: hLoadedROMBank = 0x0F
FocusEnergyEffect:
;> return Bankswitch(BANK(FocusEnergyEffect_), FocusEnergyEffect_)
	ld hl, FocusEnergyEffect_
	ld b, BANK(FocusEnergyEffect_)
	jp Bankswitch

;@ path: engine/battle/effects
;@ def RecoilEffect()
;@ Recoil moves hurt the attacker too (the work is done in another bank).
;@ test: hLoadedROMBank = 0x0F
RecoilEffect:
;> return Bankswitch(BANK(RecoilEffect_), RecoilEffect_)
	ld hl, RecoilEffect_
	ld b, BANK(RecoilEffect_)
	jp Bankswitch

;@ path: engine/battle/effects
;@ def ConfusionSideEffect()
;@ Confusion as a side effect (Psybeam, Confusion): a 10% chance.
;@ test: hLoadedROMBank = 0x0F
ConfusionSideEffect:
;> if BattleRandom() >= 10 * 255 // 100:            # 10%
;>     return
	call BattleRandom
	cp 10 * $ff / 100 ; chance of confusion
	ret nc
;> return ConfusionSideEffectSuccess()
	jr ConfusionSideEffectSuccess

;@ path: engine/battle/effects
;@ def ConfusionEffect()
;@ Confusion moves (Supersonic, Confuse Ray...): fail against a substitute or when the accuracy test misses.
;@ test: hLoadedROMBank = 0x0F
ConfusionEffect:
;> if not CheckTargetSubstitute():
;>     return ConfusionEffectFailed(hWhoseTurn)  # a still holds hWhoseTurn here, never the side effect
	call CheckTargetSubstitute
	jr nz, ConfusionEffectFailed
;> MoveHitTest()
	call MoveHitTest
;> if wMoveMissed:
;>     return ConfusionEffectFailed(wMoveMissed)
	ld a, [wMoveMissed]
	and a
	jr nz, ConfusionEffectFailed
;> ConfusionSideEffectSuccess()                      # (it follows)

;@ path: engine/battle/effects
;@ def ConfusionSideEffectSuccess()
;@ Confuse the target for 2 to 5 turns, unless it already is. A confusion move shows its animation; the side effect
;@ has shown it already.
;@ test: hLoadedROMBank = 0x0F
ConfusionSideEffectSuccess:
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> flags, counter, effect = addr(wEnemyBattleStatus1), addr(wEnemyConfusedCounter), wPlayerMoveEffect   # the target's
;> if not player:
	ld hl, wEnemyBattleStatus1
	ld bc, wEnemyConfusedCounter
	ld a, [wPlayerMoveEffect]
	jr z, .confuseTarget
;>     flags, counter, effect = addr(wPlayerBattleStatus1), addr(wPlayerConfusedCounter), wEnemyMoveEffect
	ld hl, wPlayerBattleStatus1
	ld bc, wPlayerConfusedCounter
	ld a, [wEnemyMoveEffect]
.confuseTarget
;> if mem[flags] >> CONFUSED & 1:
;>     return ConfusionEffectFailed(effect)
	bit CONFUSED, [hl] ; is mon confused?
	jr nz, ConfusionEffectFailed
;> mem[flags] |= 1 << CONFUSED
	set CONFUSED, [hl] ; mon is now confused
;> mem[counter] = (BattleRandom() & 3) + 2
	push af
	call BattleRandom
	and $3
	inc a
	inc a
	ld [bc], a ; confusion status will last 2-5 turns
;> if effect != CONFUSION_SIDE_EFFECT:
	pop af
	cp CONFUSION_SIDE_EFFECT
;>     PlayCurrentMoveAnimation2()
	call nz, PlayCurrentMoveAnimation2
;> PrintText(BecameConfusedText)
	ld hl, BecameConfusedText
	jp PrintText

;@ path: engine/battle/effects
BecameConfusedText:
	db TX_FAR
	dw _BecameConfusedText
	db BANK(_BecameConfusedText)
	db TX_END

;@ path: engine/battle/effects
;@ def ConfusionEffectFailed(effect: a)
;@ "But it failed!" after a pause - but a failed side effect stays silent.
;@ test: hLoadedROMBank = 0x0F
ConfusionEffectFailed:
;> if effect == CONFUSION_SIDE_EFFECT:               # a side effect fails silently
;>     return
	cp CONFUSION_SIDE_EFFECT
	ret z
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> ConditionalPrintButItFailed()
	jp ConditionalPrintButItFailed

