ClearHyperBeam:
;> status2 = addr(wEnemyBattleStatus2)
	push hl
	ld hl, wEnemyBattleStatus2
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;>     status2 = addr(wPlayerBattleStatus2)
	ld hl, wPlayerBattleStatus2
.playerTurn
;> mem[status2] &= ~(1 << NEEDS_TO_RECHARGE) & 0xFF
	res NEEDS_TO_RECHARGE, [hl] ; mon no longer needs to recharge
	pop hl
	ret

;@ path: engine/battle/effects
