	jr z, .player
;>     status2 = addr(wEnemyBattleStatus2)
	ld hl, wEnemyBattleStatus2
.player
;> mem[status2] |= 1 << USING_RAGE
	set USING_RAGE, [hl] ; mon is now in "rage" mode
