;@ path: engine/battle/effects
;@ def MimicEffect()
;@ Mimic: the user's Mimic slot becomes one of the target's moves. The player picks it from the enemy's moves in a
;@ menu; the enemy (and the player in a link battle) gets a random one. A target in the air or underground can't be
;@ copied.
;@ test: hLoadedROMBank = 0x0F
MimicEffect:
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> MoveHitTest()
	call MoveHitTest
;> if wMoveMissed:
;>     return PrintButItFailedText_()
	ld a, [wMoveMissed]
	and a
	jr nz, .mimicMissed
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> source, status = wBattleMonMoves, wPlayerBattleStatus1   # the target's (on the enemy's turn)
	ld hl, wBattleMonMoves
	ld a, [wPlayerBattleStatus1]
;> if player:
	jr nz, .enemyTurn
;>     menu = wLinkState != LINK_STATE_BATTLING      # the player picks, except in link battles
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
;>     if menu:
;>@inv         if wEnemyBattleStatus1 >> INVULNERABLE & 1:
;>             return PrintButItFailedText_()
;>@sl         slot = wCurrentMenuItem
;>@mt         wMoveMenuType = 1                     # a pick from the enemy's moves
;>@ms         MoveSelectionMenu()
;>@lb         LoadScreenTilesFromBuffer1()
;>@en         entry = wEnemyMonMoves + wCurrentMenuItem
;>@mv         move = mem[entry]
;>@mo         moves = wBattleMonMoves
	jr nz, .letPlayerChooseMove
;>     else:
;>         source, status = wEnemyMonMoves, wEnemyBattleStatus1
	ld hl, wEnemyMonMoves
	ld a, [wEnemyBattleStatus1]
.enemyTurn
;> if not (player and menu):                         # a random move
;>     if status >> INVULNERABLE & 1:                # in the air or underground
;>@mm         return PrintButItFailedText_()
	bit INVULNERABLE, a
	jr nz, .mimicMissed
.getRandomMove
;>     while True:
;>         slot = BattleRandom() & 3
	push hl
	call BattleRandom
	and $3
;>         move = mem[source + slot]
	ld c, a
	ld b, $0
	add hl, bc
	ld a, [hl]
	pop hl
;>         if move:
;>             break
	and a
	jr z, .getRandomMove
;>     player = hWhoseTurn == 0
	ld d, a
	ldh a, [hWhoseTurn]
	and a
;>     moves, slot = wBattleMonMoves, wPlayerMoveListIndex   # the user's
;>     if not player:
	ld hl, wBattleMonMoves
	ld a, [wPlayerMoveListIndex]
	jr z, .playerTurn
;>         moves, slot = wEnemyMonMoves, wEnemyMoveListIndex
	ld hl, wEnemyMonMoves
	ld a, [wEnemyMoveListIndex]
	jr .playerTurn
.letPlayerChooseMove
;=@inv
	ld a, [wEnemyBattleStatus1]
	bit INVULNERABLE, a
	jr nz, .mimicMissed
;=@sl
	ld a, [wCurrentMenuItem]
	push af
;=@mt
	ld a, $1
	ld [wMoveMenuType], a
;=@ms
	call MoveSelectionMenu
;=@lb
	call LoadScreenTilesFromBuffer1
;=@en
	ld hl, wEnemyMonMoves
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, $0
	add hl, bc
;=@mv
	ld d, [hl]
	pop af
;=@mo
	ld hl, wBattleMonMoves
.playerTurn
;> mem[moves + slot] = move
	ld c, a
	ld b, $0
	add hl, bc
	ld a, d
	ld [hl], a
;> wNamedObjectIndex = move
	ld [wNamedObjectIndex], a
;> GetMoveName()
	call GetMoveName
;> PlayCurrentMoveAnimation()
	call PlayCurrentMoveAnimation
;> PrintText(MimicLearnedMoveText)
	ld hl, MimicLearnedMoveText
	jp PrintText
.mimicMissed
;=@mm
	jp PrintButItFailedText_

;@ path: engine/battle/effects
MimicLearnedMoveText:
	db TX_FAR
	dw _MimicLearnedMoveText
	db BANK(_MimicLearnedMoveText)
	db TX_END

