;@ path: engine/battle/effects
;@ def SplashEffect()
;@ Splash: its animation, then "No effect!".
;@ test: hLoadedROMBank = 0x0F
SplashEffect:
;> PlayCurrentMoveAnimation()
;> PrintNoEffectText()
	call PlayCurrentMoveAnimation
	jp PrintNoEffectText

;@ path: engine/battle/effects
;@ def DisableEffect()
;@ Disable: one of the target's moves, picked at random, can't be used for 1 to 8 turns. Fails if the target has a
;@ move disabled already. Moves without PP are not picked, and if no move has PP left it fails - except against the
;@ enemy outside link battles, whose PP never run out.
;@ test: hLoadedROMBank = 0x0F
DisableEffect:
;> MoveHitTest()
	call MoveHitTest
;> if wMoveMissed:
;>     return PrintButItFailedText_()
	ld a, [wMoveMissed]
	and a
	jr nz, .moveMissed
;> disabled, moves = addr(wEnemyDisabledMove), wEnemyMonMoves   # the target's
	ld de, wEnemyDisabledMove
	ld hl, wEnemyMonMoves
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .disableEffect
;>     disabled, moves = addr(wPlayerDisabledMove), wBattleMonMoves
	ld de, wPlayerDisabledMove
	ld hl, wBattleMonMoves
.disableEffect
; no effect if target already has a move disabled
;> if mem[disabled]:                                 # one at a time
;>     return PrintButItFailedText_()
	ld a, [de]
	and a
	jr nz, .moveMissed
.pickMoveToDisable
;> while True:
;>     slot = BattleRandom() & 3
	push hl
	call BattleRandom
	and $3
;>     move = mem[moves + slot]
	ld c, a
	ld b, $0
	add hl, bc
	ld a, [hl]
	pop hl
;>     if move == 0:
;>         continue
	and a
	jr z, .pickMoveToDisable ; loop until a non-00 move slot is found
;>     wNamedObjectIndex = move
	ld [wNamedObjectIndex], a ; store move number
;>     player = hWhoseTurn == 0
	push hl
	ldh a, [hWhoseTurn]
	and a
;>     pp = wBattleMonPP                             # the target's PP
;>     if player:
	ld hl, wBattleMonPP
	jr nz, .enemyTurn
;>         if wLinkState != LINK_STATE_BATTLING:     # the enemy's PP never run out
;>             break
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	pop hl ; wEnemyMonMoves
	jr nz, .playerTurnNotLinkBattle
; player's turn, Link Battle
;>         pp = wEnemyMonPP
	push hl
	ld hl, wEnemyMonPP
.enemyTurn
;>     anypp = mem[pp] | mem[pp + 1]
	push hl
	ld a, [hli]
	or [hl]
;>     anypp |= mem[pp + 2] | mem[pp + 3]
	inc hl
	or [hl]
	inc hl
	or [hl]
;>     if anypp & PP_MASK == 0:                      # no PP left at all
;>         return PrintButItFailedText_()
	and PP_MASK
	pop hl ; wBattleMonPP or wEnemyMonPP
	jr z, .moveMissedPopHL ; nothing to do if all moves have no PP left
;>     if mem[pp + slot]:                            # else another one
;>         break
	add hl, bc
	ld a, [hl]
	pop hl
	and a
	jr z, .pickMoveToDisable ; pick another move if this one had 0 PP
.playerTurnNotLinkBattle
; non-link battle enemies have unlimited PP so the previous checks aren't needed
;> turns = (BattleRandom() & 7) + 1
	call BattleRandom
	and $7
	inc a ; 1-8 turns disabled
;> mem[disabled] = (slot + 1 << 4) + turns           # the move's slot (1-4) in the high nibble
	inc c ; move 1-4 will be disabled
	swap c
	add c ; map disabled move to high nibble of wEnemyDisabledMove / wPlayerDisabledMove
	ld [de], a
;> PlayCurrentMoveAnimation2()
	call PlayCurrentMoveAnimation2
;> number = addr(wPlayerDisabledMoveNumber)
	ld hl, wPlayerDisabledMoveNumber
;> if hWhoseTurn == 0:
	ldh a, [hWhoseTurn]
	and a
	jr nz, .printDisableText
;>     number = addr(wEnemyDisabledMoveNumber)
	inc hl ; wEnemyDisabledMoveNumber
.printDisableText
;> mem[number] = wNamedObjectIndex
	ld a, [wNamedObjectIndex] ; move number
	ld [hl], a
;> GetMoveName()
	call GetMoveName
;> PrintText(MoveWasDisabledText)
	ld hl, MoveWasDisabledText
	jp PrintText
.moveMissedPopHL
	pop hl
.moveMissed
	jp PrintButItFailedText_

;@ path: engine/battle/effects
MoveWasDisabledText:
	db TX_FAR
	dw _MoveWasDisabledText
	db BANK(_MoveWasDisabledText)
	db TX_END

