;@ path: engine/battle/effects
;@ def CheckTargetSubstitute() -> zero
;@ Zero unless the target hides behind a substitute; keeps hl.
;@ test: hLoadedROMBank = 0x0F
CheckTargetSubstitute:
;> status2 = wEnemyBattleStatus2                    # the target's
	push hl
	ld hl, wEnemyBattleStatus2
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .next
;>     status2 = wPlayerBattleStatus2
	ld hl, wPlayerBattleStatus2
.next
;> return not status2 >> HAS_SUBSTITUTE_UP & 1
	bit HAS_SUBSTITUTE_UP, [hl]
	pop hl
	ret

;@ path: engine/battle/effects
;@ def PlayCurrentMoveAnimation2()
;@ Play the animation of the move being used (if any) with the shaking that hurts the other side.
;@ test: hLoadedROMBank = 0x0F
PlayCurrentMoveAnimation2:
; animation at MOVENUM will be played unless MOVENUM is 0
; plays wAnimationType 3 or 6
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> move = wPlayerMoveNum
;> if not player:
	ld a, [wPlayerMoveNum]
	jr z, .notEnemyTurn
;>     move = wEnemyMoveNum
	ld a, [wEnemyMoveNum]
.notEnemyTurn
;> if move == 0:
;>     return
	and a
	ret z
; fallthrough
;> PlayBattleAnimation2(move)

;@ path: engine/battle/effects
;@ def PlayBattleAnimation2(anim: a)
;@ Play an animation, then shake the screen slowly - on the enemy's turn the shaking that hits the player.
;@ test: hLoadedROMBank = 0x0F
PlayBattleAnimation2:
; play animation ID at a and animation type 6 or 3
;> wAnimationID = anim
	ld [wAnimationID], a
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> kind = ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_SLOW_2
;> if not player:                                    # the enemy's: the shaking that hits the player
	ld a, ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_SLOW_2
	jr z, .storeAnimationType
;>     kind = ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_SLOW
	ld a, ANIMATIONTYPE_SHAKE_SCREEN_HORIZONTALLY_SLOW
.storeAnimationType
;> wAnimationType = kind
	ld [wAnimationType], a
;> PlayBattleAnimationGotID()
	jp PlayBattleAnimationGotID

;@ path: engine/battle/effects
;@ def PlayCurrentMoveAnimation()
;@ Play the animation of the move being used (if any) with no extra effect.
;@ test: hLoadedROMBank = 0x0F
PlayCurrentMoveAnimation:
; animation at MOVENUM will be played unless MOVENUM is 0
; resets wAnimationType
;> wAnimationType = 0
	xor a
	ld [wAnimationType], a
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> move = wPlayerMoveNum
;> if not player:
	ld a, [wPlayerMoveNum]
	jr z, .notEnemyTurn
;>     move = wEnemyMoveNum
	ld a, [wEnemyMoveNum]
.notEnemyTurn
;> if move == 0:
;>     return
	and a
	ret z
; fallthrough
;> PlayBattleAnimation(move)

;@ path: engine/battle/effects
;@ def PlayBattleAnimation(anim: a)
;@ Play an animation with the effect already in wAnimationType.
;@ test: hLoadedROMBank = 0x0F
PlayBattleAnimation:
; play animation ID at a and predefined animation type
;> wAnimationID = anim
;> PlayBattleAnimationGotID()
	ld [wAnimationID], a

;@ path: engine/battle/effects
;@ def PlayBattleAnimationGotID()
;@ Play the animation in wAnimationID; keeps hl, de and bc.
;@ test: hLoadedROMBank = 0x0F
PlayBattleAnimationGotID:
; play animation at wAnimationID
;> predef(MoveAnimation)
	push hl
	push de
	push bc
	ld a, (MoveAnimationPredef - PredefPointers) / 3
	call Predef
;> return                                            # (hl, de and bc kept)
	pop bc
	pop de
	pop hl
	ret


SECTION "bank10", ROMX

;@ def ShowPokedexMenu()
;@ The Pokédex: the list of Pokémon, and for a chosen one the DATA / CRY / AREA / QUIT side menu, until QUIT or B.
;@ path: engine/menus/pokedex
ShowPokedexMenu:
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> scroll = wListScrollOffset
	ld a, [wListScrollOffset]
	push af
;> wCurrentMenuItem = wListScrollOffset = wLastMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
	ld [wListScrollOffset], a
	ld [wLastMenuItem], a
;> wPokedexNum = 1
	inc a
	ld [wPokedexNum], a
;> hJoy7 = 1
;> graphics = True
	ldh [hJoy7], a
;>@lp while True:
;>     if graphics:
.setUpGraphics
;>         RunPaletteCommand(SET_PAL_GENERIC)
	ld b, SET_PAL_GENERIC
	call RunPaletteCommand
;>         farcall(LoadPokedexTilePatterns)
	ld hl, LoadPokedexTilePatterns
	ld b, BANK(LoadPokedexTilePatterns)
	call Bankswitch
.doPokemonListMenu
;>     wTopMenuItemY = 3
	ld hl, wTopMenuItemY
	ld a, 3
	ld [hli], a ; top menu item Y
;>     wTopMenuItemX = 0
	xor a
	ld [hli], a ; top menu item X
;>     wMenuWatchMovingOutOfBounds = 1
	inc a
	ld [wMenuWatchMovingOutOfBounds], a
;>     wMaxMenuItem = 6
	inc hl
	inc hl
	ld a, 6
	ld [hli], a ; max menu item ID
;>     wMenuWatchedKeys = PAD_LEFT | PAD_RIGHT | PAD_B | PAD_A
	ld [hl], PAD_LEFT | PAD_RIGHT | PAD_B | PAD_A
;>     if not HandlePokedexListMenu():         # B
;>         break
	call HandlePokedexListMenu
	jr c, .goToSideMenu ; if the player chose a pokemon from the list
;>@side     reason = HandlePokedexSideMenu()        # 0 data or area shown, 1 QUIT, 2 back to the list
;>@quit     if reason == 1:
;>@quit2         break
;>@gfx     graphics = reason != 2                  # the list needs its graphics again after DATA or AREA
.exitPokedex
;> wMenuWatchMovingOutOfBounds = wCurrentMenuItem = wLastMenuItem = 0
	xor a
	ld [wMenuWatchMovingOutOfBounds], a
	ld [wCurrentMenuItem], a
	ld [wLastMenuItem], a
;> hJoy7 = 0
	ldh [hJoy7], a
;> wUnusedOverrideSimulatedJoypadStatesIndex = 0
	ld [wUnusedOverrideSimulatedJoypadStatesIndex], a
;> wOverrideSimulatedJoypadStatesMask = 0
	ld [wOverrideSimulatedJoypadStatesMask], a
;> wListScrollOffset = scroll
	pop af
	ld [wListScrollOffset], a
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> return ReloadMapData()
	jp ReloadMapData
.goToSideMenu
;=@side
	call HandlePokedexSideMenu
;=@quit
	dec b
	jr z, .exitPokedex ; if the player chose Quit
;=@gfx
	dec b
	jr z, .doPokemonListMenu ; if pokemon not seen or player pressed B button
;=@lp
	jp .setUpGraphics ; if pokemon data or area was shown

; handles the menu on the lower right in the pokedex screen
; OUTPUT:
; b = reason for exiting menu
; 00: showed pokemon data or area
; 01: the player chose Quit
; 02: the pokemon has not been seen yet or the player pressed the B button
;@ def HandlePokedexSideMenu() -> b
;@ The side menu for the Pokémon under the list cursor: DATA, CRY (stays in the menu), AREA or QUIT. Returns 0
;@ after DATA or AREA, 1 for QUIT, 2 for B or a Pokémon not seen yet.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/menus/pokedex
HandlePokedexSideMenu:
;> PlaceUnfilledArrowMenuCursor(0)
	call PlaceUnfilledArrowMenuCursor
;> item = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	push af
	ld b, a
;> last = wLastMenuItem
	ld a, [wLastMenuItem]
	push af
;> scroll = wListScrollOffset
	ld a, [wListScrollOffset]
	push af
;> wPokedexNum = (scroll + item + 1) & 0xFF
	add b
	inc a
	ld [wPokedexNum], a
;> number = wPokedexNum
	ld a, [wPokedexNum]
	push af
;> max_seen = wDexMaxSeenMon                   # (kept for no reason)
	ld a, [wDexMaxSeenMon]
	push af ; this doesn't need to be preserved
;> if not IsPokemonBitSet(addr(wPokedexSeen)):  # not seen yet
;>     reason = 2
	ld hl, wPokedexSeen
	call IsPokemonBitSet
	ld b, 2
	jr z, .exitSideMenu
;> else:
;>     PokedexToIndex()
	call PokedexToIndex
;>     wTopMenuItemY = 10
	ld hl, wTopMenuItemY
	ld a, 10
	ld [hli], a ; top menu item Y
;>     wTopMenuItemX = 15
	ld a, 15
	ld [hli], a ; top menu item X
;>     wCurrentMenuItem = 0
	xor a
	ld [hli], a ; current menu item ID
;>     wMaxMenuItem = 3
	inc hl
	ld a, 3
	ld [hli], a ; max menu item ID
;>     wMenuWatchedKeys = PAD_A | PAD_B        # (that is 3 too)
	;ld a, PAD_A | PAD_B
	ld [hli], a ; menu watched keys (A button and B button)
;>     wLastMenuItem = 0
	xor a
	ld [hli], a ; old menu item ID
;>     wMenuWatchMovingOutOfBounds = 0
	ld [wMenuWatchMovingOutOfBounds], a
.handleMenuInput
;>@lp     while True:
;>         if HandleMenuInput() & PAD_B:
;>@bb2             reason = 2
	call HandleMenuInput
	bit B_PAD_B, a
	ld b, 2
	jr nz, .buttonBPressed
;>@bb1             DrawTileLine(coord(15, 10), 0x7F, 7, 20)   # erase the side menu's cursor
;>@bb3             break
;>         if wCurrentMenuItem == 0:              # DATA
	ld a, [wCurrentMenuItem]
	and a
	jr z, .choseData
;>@d1             ShowPokedexDataInternal()
;>@d2             reason = 0
;>@d3             break
;>         if wCurrentMenuItem == 1:              # CRY
	dec a
	jr z, .choseCry
;>@c1             PlaySound(GetCryData(wPokedexNum))
;>@c2             continue
;>         if wCurrentMenuItem == 2:              # AREA
	dec a
	jr z, .choseArea
;>@a1             LoadTownMap_Nest()
;>@a2             reason = 0
;>@a3             break
; chose Quit
;>         reason = 1                             # QUIT
;>         break
	ld b, 1
.exitSideMenu
;> wDexMaxSeenMon = max_seen
	pop af
	ld [wDexMaxSeenMon], a
;> wPokedexNum = number
	pop af
	ld [wPokedexNum], a
;> wListScrollOffset = scroll
	pop af
	ld [wListScrollOffset], a
;> wLastMenuItem = last
	pop af
	ld [wLastMenuItem], a
;> wCurrentMenuItem = item
	pop af
	ld [wCurrentMenuItem], a
;> DrawTileLine(coord(0, 3), 0x7F, 13, 20)     # erase the list's cursor
	push bc
	ld hl, (3) * SCREEN_WIDTH + (0) + wTileMap
	ld de, 20
	ld bc, ((' ') & $ff) << 8 + ((13) & $ff)
	call DrawTileLine ; cover up the menu cursor in the pokemon list
;> return reason
	pop bc
	ret

.buttonBPressed
;=@bb1
	push bc
	ld hl, (10) * SCREEN_WIDTH + (15) + wTileMap
	ld de, 20
	ld bc, ((' ') & $ff) << 8 + ((7) & $ff)
	call DrawTileLine ; cover up the menu cursor in the side menu
	pop bc
;=@bb3
	jr .exitSideMenu

.choseData
;=@d1
	call ShowPokedexDataInternal
;=@d2
	ld b, 0
;=@d3
	jr .exitSideMenu

; play pokemon cry
.choseCry
;=@c1
	ld a, [wPokedexNum]
	call GetCryData
	call PlaySound
;=@c2
	jr .handleMenuInput

.choseArea
	; display pokemon areas
;=@a1
	ld a, (LoadTownMap_NestPredef - PredefPointers) / 3
	call Predef
;=@a2
	ld b, 0
;=@a3
	jr .exitSideMenu

; handles the list of pokemon on the left of the pokedex screen
; sets carry flag if player presses A, unsets carry flag if player presses B
;@ path: engine/menus/pokedex
;@ def HandlePokedexListMenu() -> carry
;@ The Pokédex list: SEEN and OWN counts, and seven rows of numbers and names (dashes for Pokémon not seen, a ball
;@ for those owned) up to the highest number seen. UP/DOWN scroll one row, LEFT/RIGHT seven. Carry for A, none for B.
HandlePokedexListMenu:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
; draw the horizontal line separating the seen and owned amounts from the menu
;> p = coord(15, 8)
	ld hl, (8) * SCREEN_WIDTH + (15) + wTileMap
;> for i in range(5):
;>     mem[p + i] = 0x7A                       # '─'
	ld a, '─'
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hli], a
;> mem[coord(14, 0)] = 0x71                    # vertical line
	ld hl, (0) * SCREEN_WIDTH + (14) + wTileMap
	ld [hl], $71 ; vertical line tile
;> DrawPokedexVerticalLine(coord(14, 1))
	ld hl, (1) * SCREEN_WIDTH + (14) + wTileMap
	call DrawPokedexVerticalLine
;> DrawPokedexVerticalLine(coord(14, 9))
	ld hl, (9) * SCREEN_WIDTH + (14) + wTileMap
	call DrawPokedexVerticalLine
;> CountSetBits(addr(wPokedexSeen), addr(wPokedexSeenEnd) - addr(wPokedexSeen))
	ld hl, wPokedexSeen
	ld b, wPokedexSeenEnd - wPokedexSeen
	call CountSetBits
;> PrintNumber(addr(wNumSetBits), coord(16, 3), 1, 3)
	ld de, wNumSetBits
	ld hl, (3) * SCREEN_WIDTH + (16) + wTileMap
	ld bc, ((1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber ; print number of seen pokemon
;> CountSetBits(addr(wPokedexOwned), addr(wPokedexOwnedEnd) - addr(wPokedexOwned))
	ld hl, wPokedexOwned
	ld b, wPokedexOwnedEnd - wPokedexOwned
	call CountSetBits
;> PrintNumber(addr(wNumSetBits), coord(16, 6), 1, 3)
	ld de, wNumSetBits
	ld hl, (6) * SCREEN_WIDTH + (16) + wTileMap
	ld bc, ((1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber ; print number of owned pokemon
;> PlaceString(PokedexSeenText, coord(16, 2))
	ld hl, (2) * SCREEN_WIDTH + (16) + wTileMap
	ld de, PokedexSeenText
	call PlaceString
;> PlaceString(PokedexOwnText, coord(16, 5))
	ld hl, (5) * SCREEN_WIDTH + (16) + wTileMap
	ld de, PokedexOwnText
	call PlaceString
;> PlaceString(PokedexContentsText, coord(1, 1))
	ld hl, (1) * SCREEN_WIDTH + (1) + wTileMap
	ld de, PokedexContentsText
	call PlaceString
;> PlaceString(PokedexMenuItemsText, coord(16, 10))
	ld hl, (10) * SCREEN_WIDTH + (16) + wTileMap
	ld de, PokedexMenuItemsText
	call PlaceString
; find the highest pokedex number among the pokemon the player has seen
;> p = addr(wPokedexSeenEnd) - 1               # the highest Pokédex number seen
	ld hl, wPokedexSeenEnd - 1
;> n = (addr(wPokedexSeenEnd) - addr(wPokedexSeen)) * 8 + 1
	ld b, (wPokedexSeenEnd - wPokedexSeen) * 8 + 1
;>@ms max_seen = None
;>@mw while max_seen is None:
.maxSeenPokemonLoop
;>     bits = mem[p]
;>     p -= 1
	ld a, [hld]
;>@ik     for k in range(8):
	ld c, 8
.maxSeenPokemonInnerLoop
;>         n = (n - 1) & 0xFF
	dec b
;>         if bits & (0x80 >> k):
;>@sv             max_seen = n
;>             break
	sla a
	jr c, .storeMaxSeenPokemon
;=@ik
	dec c
	jr nz, .maxSeenPokemonInnerLoop
;=@mw
	jr .maxSeenPokemonLoop

.storeMaxSeenPokemon
;> wDexMaxSeenMon = max_seen
	ld a, b
	ld [wDexMaxSeenMon], a
;> while True:
.loop
;>     hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;>     ClearScreenArea(coord(4, 2), 10, 14)
	ld hl, (2) * SCREEN_WIDTH + (4) + wTileMap
	ld bc, ((14) & $ff) << 8 + ((10) & $ff)
	call ClearScreenArea
;>     pos = coord(1, 3)
	ld hl, (3) * SCREEN_WIDTH + (1) + wTileMap
;>     wPokedexNum = wListScrollOffset
	ld a, [wListScrollOffset]
	ld [wPokedexNum], a
;>     rows = 7
	ld d, 7
;>     if wDexMaxSeenMon < 7:
	ld a, [wDexMaxSeenMon]
	cp 7
	jr nc, .printPokemonLoop
;>         rows = wDexMaxSeenMon
	ld d, a
;>         wMaxMenuItem = (wDexMaxSeenMon - 1) & 0xFF
	dec a
	ld [wMaxMenuItem], a
; loop to print pokemon pokedex numbers and names
; if the player has owned the pokemon, it puts a pokeball beside the name
;>@pl     for _ in range(rows or 256):
.printPokemonLoop
;>         wPokedexNum += 1
	ld a, [wPokedexNum]
	inc a
	ld [wPokedexNum], a
;>         number = wPokedexNum
	push af
	push de
	push hl
;>         num_pos = pos - SCREEN_WIDTH
	ld de, -SCREEN_WIDTH
	add hl, de
;>         end = PrintNumber(addr(wPokedexNum), num_pos, LEADING_ZEROES | 1, 3)
	ld de, wPokedexNum
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;>         mark = end + SCREEN_WIDTH - 1         # left of the name
	ld de, SCREEN_WIDTH
	add hl, de
	dec hl
;>         owned = IsPokemonBitSet(addr(wPokedexOwned))
	push hl
	ld hl, wPokedexOwned
	call IsPokemonBitSet
	pop hl
;>         tile = 0x7F
	ld a, ' '
;>         if owned:
;>             tile = 0x72                     # a ball
	jr z, .writeTile
	ld a, $72 ; pokeball tile
.writeTile
;>         mem[mark] = tile
	ld [hl], a ; put a pokeball next to pokemon that the player has owned
;>         seen = IsPokemonBitSet(addr(wPokedexSeen))
	push hl
	ld hl, wPokedexSeen
	call IsPokemonBitSet
;>         if seen:
;>@gn1             PokedexToIndex()
;>@gn2             name = GetMonName()
;>         else:
;>             name = label('HandlePokedexListMenu.dashedLine')
	jr nz, .getPokemonName ; if the player has seen the pokemon
	ld de, .dashedLine ; print a dashed line in place of the name if the player hasn't seen the pokemon
	jr .skipGettingName
.dashedLine ; for unseen pokemon in the list
	db "----------@"
.getPokemonName
;=@gn1
	call PokedexToIndex
;=@gn2
	call GetMonName
.skipGettingName
;>         PlaceString(name, mark + 1)
	pop hl
	inc hl
	call PlaceString
;>         pos += 2 * SCREEN_WIDTH
	pop hl
	ld bc, 2 * SCREEN_WIDTH
	add hl, bc
;>         wPokedexNum = number
	pop de
	pop af
	ld [wPokedexNum], a
;=@pl
	dec d
	jr nz, .printPokemonLoop
;>     hAutoBGTransferEnabled = 1
	ld a, 01
	ldh [hAutoBGTransferEnabled], a
;>     Delay3()
	call Delay3
;>     GBPalNormal()
	call GBPalNormal
;>     keys = HandleMenuInput()
	call HandleMenuInput
;>     if keys & PAD_B:
;>         return False
	bit B_PAD_B, a
	jp nz, .buttonBPressed
; check if Up pressed
;>     if keys & PAD_UP:
	bit B_PAD_UP, a
	jr z, .checkIfDownPressed
.upPressed ; scroll up one row
;>         if wListScrollOffset:
	ld a, [wListScrollOffset]
	and a
	jp z, .loop
;>             wListScrollOffset -= 1
	dec a
	ld [wListScrollOffset], a
	jp .loop
.checkIfDownPressed
;>     elif keys & PAD_DOWN:
	bit B_PAD_DOWN, a
	jr z, .checkIfRightPressed
; Down pressed, scroll down one row
;>         most = wDexMaxSeenMon
	ld a, [wDexMaxSeenMon]
;>         if most >= 7:                       # longer than the screen
	cp 7
	jp c, .loop ; can't if the list is shorter than 7
;>             last = most - 7
	sub 7
	ld b, a
;>             if wListScrollOffset != last:
	ld a, [wListScrollOffset]
	cp b
	jp z, .loop
;>                 wListScrollOffset += 1
	inc a
	ld [wListScrollOffset], a
	jp .loop
.checkIfRightPressed
;>     elif keys & PAD_RIGHT:
	bit B_PAD_RIGHT, a
	jr z, .checkIfLeftPressed
; Right pressed, scroll down 7 rows
;>         if wDexMaxSeenMon >= 7:
	ld a, [wDexMaxSeenMon]
	cp 7
	jp c, .loop ; can't if the list is shorter than 7
;>             end = wDexMaxSeenMon - 6
	sub 6
	ld b, a
;>             wListScrollOffset = (wListScrollOffset + 7) & 0xFF
	ld a, [wListScrollOffset]
	add 7
	ld [wListScrollOffset], a
;>             if wListScrollOffset >= end:
	cp b
	jp c, .loop
;>                 wListScrollOffset = end - 1
	dec b
	ld a, b
	ld [wListScrollOffset], a
	jp .loop
.checkIfLeftPressed ; scroll up 7 rows
;>     elif keys & PAD_LEFT:
	bit B_PAD_LEFT, a
	jr z, .buttonAPressed
; Left pressed
;>         offset = wListScrollOffset - 7
	ld a, [wListScrollOffset]
	sub 7
;>         wListScrollOffset = offset & 0xFF
	ld [wListScrollOffset], a
;>         if offset < 0:
	jp nc, .loop
;>             wListScrollOffset = 0
	xor a
	ld [wListScrollOffset], a
	jp .loop
.buttonAPressed
;>     else:
;>         return True                         # A
	scf
	ret
.buttonBPressed
	and a
	ret

;@ def DrawPokedexVerticalLine(dest: hl) -> hl
;@ The Pokédex's dividing line: nine tiles down from dest, alternating the line tile $71 and the box tile $70.
;@ test: dest = rand(0xC3A0, 0xC3C0)
;@ path: engine/menus/pokedex
DrawPokedexVerticalLine:
;> tile = 0x71
;> for i in range(9):
	ld c, 9 ; height of line
	ld de, SCREEN_WIDTH
	ld a, $71 ; vertical line tile
.loop
;>     mem[dest] = tile
	ld [hl], a
;>     dest += SCREEN_WIDTH
	add hl, de
;>     tile ^= 1
	xor 1 ; toggle between vertical line tile and box tile
	dec c
	jr nz, .loop
;> return dest
	ret

;@ path: engine/menus/pokedex
PokedexSeenText:
	db "SEEN@"

;@ path: engine/menus/pokedex
PokedexOwnText:
	db "OWN@"

;@ path: engine/menus/pokedex
PokedexContentsText:
	db "CONTENTS@"

;@ path: engine/menus/pokedex
PokedexMenuItemsText:
	db   "DATA"
	db "<NEXT>", "CRY"
	db "<NEXT>", "AREA"
	db "<NEXT>", "QUIT@"

; tests if a pokemon's bit is set in the seen or owned pokemon bit fields
; INPUT:
; [wPokedexNum] = pokedex number
; hl = address of bit field
;@ def IsPokemonBitSet(flags: hl) -> a
;@ Test the bit of Pokémon wPokedexNum in a Pokédex flag array (seen or owned): nonzero if set.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/menus/pokedex
IsPokemonBitSet:
;> bit = (wPokedexNum - 1) & 0xFF
	ld a, [wPokedexNum]
	dec a
	ld c, a
;> result = FlagAction(flags, bit, FLAG_TEST)
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> return result
	ld a, c
	and a
	ret

; function to display pokedex data from outside the pokedex
;@ path: engine/menus/pokedex
;@ def ShowPokedexData()
;@ A Pokédex entry shown from outside the Pokédex (after a catch): load the Pokédex tiles first.
ShowPokedexData:
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
	; load pokedex tiles
;> farcall(LoadPokedexTilePatterns)
	ld hl, LoadPokedexTilePatterns
	ld b, BANK(LoadPokedexTilePatterns)
	call Bankswitch
;> return ShowPokedexDataInternal()             # it follows

; function to display pokedex data from inside the pokedex
;@ path: engine/menus/pokedex
;@ def ShowPokedexDataInternal()
;@ The Pokédex entry of wPokedexNum: picture and cry, name, species and number; for an owned Pokémon also height,
;@ weight and the description. The music is turned down meanwhile; A or B closes it.
ShowPokedexDataInternal:
;> wStatusFlags2 |= 1 << BIT_NO_AUDIO_FADE_OUT
	ld hl, wStatusFlags2
	set BIT_NO_AUDIO_FADE_OUT, [hl]
;> rAUDVOL = 0x33                              # music at 3/7
	ld a, $33 ; 3/7 volume
	ldh [rAUDVOL], a
;> GBPalWhiteOut()
	call GBPalWhiteOut ; zero all palettes
;> ClearScreen()
	call ClearScreen
;> wCurPartySpecies = wPokedexNum
	ld a, [wPokedexNum]
	ld [wCurPartySpecies], a
;> number = wPokedexNum
	push af
;> RunPaletteCommand(SET_PAL_POKEDEX)
	ld b, SET_PAL_POKEDEX
	call RunPaletteCommand
;> wPokedexNum = number
	pop af
	ld [wPokedexNum], a
;> animations = hTileAnimations
	ldh a, [hTileAnimations]
	push af
;> hTileAnimations = 0
	xor a
	ldh [hTileAnimations], a

;> DrawTileLine(coord(0, 0), 0x64, SCREEN_WIDTH, 1)      # the frame
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld de, 1
	ld bc, (($64) & $ff) << 8 + ((SCREEN_WIDTH) & $ff)
	call DrawTileLine ; draw top border

;> DrawTileLine(coord(0, 17), 0x6F, SCREEN_WIDTH, 1)
	ld hl, (17) * SCREEN_WIDTH + (0) + wTileMap
	ld b, $6f
	call DrawTileLine ; draw bottom border

;> DrawTileLine(coord(0, 1), 0x66, 0x10, 20)
	ld hl, (1) * SCREEN_WIDTH + (0) + wTileMap
	ld de, 20
	ld bc, (($66) & $ff) << 8 + (($10) & $ff)
	call DrawTileLine ; draw left border

;> DrawTileLine(coord(19, 1), 0x67, 0x10, 20)
	ld hl, (1) * SCREEN_WIDTH + (19) + wTileMap
	ld b, $67
	call DrawTileLine ; draw right border

;> mem[coord(0, 0)] = 0x63
	ld a, $63 ; upper left corner tile
	ld [(0) * SCREEN_WIDTH + (0) + wTileMap], a
;> mem[coord(19, 0)] = 0x65
	ld a, $65 ; upper right corner tile
	ld [(0) * SCREEN_WIDTH + (19) + wTileMap], a
;> mem[coord(0, 17)] = 0x6C
	ld a, $6c ; lower left corner tile
	ld [(17) * SCREEN_WIDTH + (0) + wTileMap], a
;> mem[coord(19, 17)] = 0x6E
	ld a, $6e ; lower right corner tile
	ld [(17) * SCREEN_WIDTH + (19) + wTileMap], a

;> PlaceString(PokedexDataDividerLine, coord(0, 9))
	ld hl, (9) * SCREEN_WIDTH + (0) + wTileMap
	ld de, PokedexDataDividerLine
	call PlaceString ; draw horizontal divider line

;> PlaceString(HeightWeightText, coord(9, 6))
	ld hl, (6) * SCREEN_WIDTH + (9) + wTileMap
	ld de, HeightWeightText
	call PlaceString

;> name = GetMonName()
	call GetMonName
;> PlaceString(name, coord(9, 2))
	ld hl, (2) * SCREEN_WIDTH + (9) + wTileMap
	call PlaceString

;> i = (wPokedexNum - 1) & 0xFF
	ld hl, PokedexEntryPointers
	ld a, [wPokedexNum]
	dec a
	ld e, a
	ld d, 0
;> entry = mem16[PokedexEntryPointers + 2 * i]
	add hl, de
	add hl, de
	ld a, [hli]
	ld e, a
	ld d, [hl] ; de = address of pokedex entry

;> _, end = PlaceString(entry, coord(9, 4))    # the species ("SEED")
	ld hl, (4) * SCREEN_WIDTH + (9) + wTileMap
	call PlaceString ; print species name

;> kept = end                                  # the entry goes on after the species
	ld h, b
	ld l, c
	push de
;> number = wPokedexNum
	ld a, [wPokedexNum]
	push af
;> IndexToPokedex()
	call IndexToPokedex

;> mem[coord(2, 8)] = 0x74                     # "№"
	ld hl, (8) * SCREEN_WIDTH + (2) + wTileMap
	ld a, '№'
	ld [hli], a
;> mem[coord(3, 8)] = 0xF2                     # "."
	ld a, '<DOT>'
	ld [hli], a
;> PrintNumber(addr(wPokedexNum), coord(4, 8), LEADING_ZEROES | 1, 3)
	ld de, wPokedexNum
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber ; print pokedex number

;> owned = IsPokemonBitSet(addr(wPokedexOwned))
	ld hl, wPokedexOwned
	call IsPokemonBitSet
;> wPokedexNum = number
	pop af
	ld [wPokedexNum], a
;> wCurSpecies = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wCurSpecies], a
;> # (owned and the entry pointer are kept across the picture)
	pop de

	push af
	push bc
	push de
	push hl

;> Delay3()
	call Delay3
;> GBPalNormal()
	call GBPalNormal
;> GetMonHeader()
	call GetMonHeader ; load pokemon picture location
;> LoadFlippedFrontSpriteByMonIndex(coord(1, 1))
	ld hl, (1) * SCREEN_WIDTH + (1) + wTileMap
	call LoadFlippedFrontSpriteByMonIndex ; draw pokemon picture
;> PlayCry(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call PlayCry

	pop hl
	pop de
	pop bc
	pop af

;> if owned:
	ld a, c
	and a
	jp z, .waitForButtonPress ; if the pokemon has not been owned, don't print the height, weight, or description
;>     info = kept + 1                         # feet, inches, weight (tenths of pounds), description
	inc de ; de = address of feet (height)
	ld a, [de] ; reads feet, but a is overwritten without being used
;>     end = PrintNumber(info, coord(12, 6), 1, 2)                     # feet
	ld hl, (6) * SCREEN_WIDTH + (12) + wTileMap
	ld bc, ((1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber ; print feet (height)
;>     mem[end] = 0x60                         # ′
	ld a, '′'
	ld [hl], a
;>     end = PrintNumber(info + 1, coord(15, 6), LEADING_ZEROES | 1, 2)  # inches
	inc de
	inc de ; de = address of inches (height)
	ld hl, (6) * SCREEN_WIDTH + (15) + wTileMap
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber ; print inches (height)
;>     mem[end] = 0x61                         # ″
	ld a, '″'
	ld [hl], a
; now print the weight (note that weight is stored in tenths of pounds internally)
;>     w = addr(hDexWeight)                    # the weight goes there big-endian, for PrintNumber
	inc de
	inc de
	inc de ; de = address of upper byte of weight
	push de
; put weight in big-endian order at hDexWeight
	ld hl, hDexWeight
;>     saved_hi = mem[w]
	ld a, [hl] ; save existing value of [hDexWeight]
	push af
;>     mem[w] = mem[info + 3]
	ld a, [de] ; a = upper byte of weight
	ld [hli], a ; store upper byte of weight in [hDexWeight]
;>     saved_lo = mem[w + 1]
	ld a, [hl] ; save existing value of [hDexWeight + 1]
	push af
;>     mem[w + 1] = mem[info + 2]
	dec de
	ld a, [de] ; a = lower byte of weight
	ld [hl], a ; store lower byte of weight in [hDexWeight + 1]
;>     PrintNumber(w, coord(11, 8), 2, 5)
	ld de, hDexWeight
	ld hl, (8) * SCREEN_WIDTH + (11) + wTileMap
	; 2 bytes, 5 digits
	ld bc, ((2) & $ff) << 8 + ((5) & $ff)
	call PrintNumber ; print weight
;>     if (mem[w] << 8 | mem[w + 1]) < 10:
	ld hl, (8) * SCREEN_WIDTH + (14) + wTileMap
	ldh a, [hDexWeight + 1]
	sub 10
	ldh a, [hDexWeight]
	sbc 0
	jr nc, .next
;>         mem[coord(14, 8)] = 0xF6            # "0" before the point
	ld [hl], '0' ; if the weight is less than 10, put a 0 before the decimal point
.next
;>     mem[coord(16, 8)] = mem[coord(15, 8)]   # the last digit moves right
	inc hl
	ld a, [hli]
	ld [hld], a ; make space for the decimal point by moving the last digit forward one tile
;>     mem[coord(15, 8)] = 0xF2                # the decimal point
	ld [hl], '<DOT>' ; decimal point tile
;>     mem[w + 1] = saved_lo
	pop af
	ldh [hDexWeight + 1], a ; restore original value of [hDexWeight + 1]
;>     mem[w] = saved_hi
	pop af
	ldh [hDexWeight], a ; restore original value of [hDexWeight]
;>     text = info + 4                         # the description
	pop hl
	inc hl ; hl = address of pokedex description text
	ld bc, (11) * SCREEN_WIDTH + (1) + wTileMap
;>     hClearLetterPrintingDelayFlags = 0b10
	ld a, %10
	ldh [hClearLetterPrintingDelayFlags], a
;>     TextCommandProcessor(text, coord(1, 11))
	call TextCommandProcessor ; print pokedex description text
;>     hClearLetterPrintingDelayFlags = 0
	xor a
	ldh [hClearLetterPrintingDelayFlags], a
.waitForButtonPress
;>@lp while True:
;>     JoypadLowSensitivity()
	call JoypadLowSensitivity
;>     if hJoy5 & (PAD_A | PAD_B):
;>         break
	ldh a, [hJoy5]
	and PAD_A | PAD_B
	jr z, .waitForButtonPress
;> hTileAnimations = animations
	pop af
	ldh [hTileAnimations], a
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> ClearScreen()
	call ClearScreen
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> GBPalNormal()
	call GBPalNormal
;> wStatusFlags2 &= ~(1 << BIT_NO_AUDIO_FADE_OUT) & 0xFF
	ld hl, wStatusFlags2
	res BIT_NO_AUDIO_FADE_OUT, [hl]
;> rAUDVOL = 0x77
	ld a, $77 ; max volume
	ldh [rAUDVOL], a
	ret

;@ path: engine/menus/pokedex
HeightWeightText:
	db   "HT  ?′??″"
	db "<NEXT>", "WT   ???lb@"

; leftover from JPN Pokedex, where species have the suffix "Pokemon"
;@ path: engine/menus/pokedex
PokeText: ; unreferenced
	db "#@"

; horizontal line that divides the pokedex text description from the rest of the data
;@ path: engine/menus/pokedex
PokedexDataDividerLine:
	db $68, $69, $6B, $69, $6B, $69, $6B, $69, $6B, $6B
	db $6B, $6B, $69, $6B, $69, $6B, $69, $6B, $69, $6A
	db "@"

; draws a line of tiles
; INPUT:
; b = tile ID
; c = number of tile ID's to write
; de = amount to destination address after each tile (1 for horizontal, 20 for vertical)
; hl = destination address
;@ def DrawTileLine(dest: hl, tile: b, count: c, step: de) -> hl
;@ Put `tile` count times, step bytes apart (step SCREEN_WIDTH draws a vertical line).
;@ test: count = rand(1, 10); step = rand(1, 20); dest = rand(0xC3A0, 0xC400)
;@ path: engine/menus/pokedex
DrawTileLine:
;> # (count and step are kept)
	push bc
	push de
.loop
;>@lp for _ in range(count or 256):
;>     mem[dest] = tile
	ld [hl], b
;>     dest += step
	add hl, de
;=@lp
	dec c
	jr nz, .loop
;> return dest
	pop de
	pop bc
	ret

