;@ def PokedexToIndex()
;@ Turn the Pokédex number in wPokedexNum into the species' internal index, in place (its position in
;@ PokedexOrder, from 1).
;@ test: wPokedexNum = rand(1, 151)
;@ path: engine/menus/pokedex
PokedexToIndex:
	; converts the Pokédex number at [wPokedexNum] to an index
;> # (bc and hl are kept)
	push bc
	push hl
;> number = wPokedexNum
	ld a, [wPokedexNum]
	ld b, a
;> i = 0
	ld c, 0
	ld hl, PokedexOrder

;>@lp while True:
.loop ; go through the list until we find an entry with a matching dex number
;>     i += 1
	inc c
;>     if mem[PokedexOrder + i - 1] == number:
;>         break
	ld a, [hli]
	cp b
	jr nz, .loop

;> wPokedexNum = i
	ld a, c
	ld [wPokedexNum], a
;> return
	pop hl
	pop bc
	ret

;@ def IndexToPokedex()
;@ Turn the internal species index in wPokedexNum into its Pokédex number, in place.
;@ path: engine/menus/pokedex
IndexToPokedex:
	; converts the index number at [wPokedexNum] to a Pokédex number
;> i = (wPokedexNum - 1) & 0xFF                # (bc and hl are kept)
	push bc
	push hl
	ld a, [wPokedexNum]
	dec a
;> wPokedexNum = mem[PokedexOrder + i]
	ld hl, PokedexOrder
	ld b, 0
	ld c, a
	add hl, bc
	ld a, [hl]
	ld [wPokedexNum], a
;> return
	pop hl
	pop bc
	ret

