;@ path: engine/movie/trade
;@ def InternalClockTradeAnim()
;@ The trade animation with the player's Game Boy on the left (in-game trades, and the clocking side of a link
;@ trade).
;@ test: skip runs the trade animation
InternalClockTradeAnim:
; Do the trading animation with the player's gameboy on the left.
; In-game trades and internally clocked link cable trades use this.
;> wLeftGBMonSpecies = wTradedPlayerMonSpecies
	ld a, [wTradedPlayerMonSpecies]
	ld [wLeftGBMonSpecies], a
;> wRightGBMonSpecies = wTradedEnemyMonSpecies
	ld a, [wTradedEnemyMonSpecies]
	ld [wRightGBMonSpecies], a
;> TradeAnimCommon(InternalClockTradeFuncSequence)
	ld de, InternalClockTradeFuncSequence
	jr TradeAnimCommon

;@ path: engine/movie/trade
;@ def ExternalClockTradeAnim()
;@ The trade animation with the player's Game Boy on the right (the clocked side of a link trade).
;@ test: skip runs the trade animation
ExternalClockTradeAnim:
; Do the trading animation with the player's gameboy on the right.
; Externally clocked link cable trades use this.
;> wLeftGBMonSpecies = wTradedEnemyMonSpecies
	ld a, [wTradedEnemyMonSpecies]
	ld [wLeftGBMonSpecies], a
;> wRightGBMonSpecies = wTradedPlayerMonSpecies
	ld a, [wTradedPlayerMonSpecies]
	ld [wRightGBMonSpecies], a
;> TradeAnimCommon(ExternalClockTradeFuncSequence)      # it follows
	ld de, ExternalClockTradeFuncSequence

;@ path: engine/movie/trade
;@ def TradeAnimCommon(sequence: de)
;@ Run the trade functions listed in `sequence` (indexes into TradeFuncPointerTable, $FF ends), with fast text
;@ options and no scrolling; options and scroll are put back after.
;@ test: skip runs the trade animation
TradeAnimCommon:
;> options = wOptions
	ld a, [wOptions]
	push af
;> scy = hSCY
	ldh a, [hSCY]
	push af
;> scx = hSCX
	ldh a, [hSCX]
	push af
;> wOptions = 0
	xor a
	ld [wOptions], a
;> hSCY = 0
	ldh [hSCY], a
;> hSCX = 0
	ldh [hSCX], a
;> while mem[sequence] != 0xFF:
	push de
.loop
	pop de
	ld a, [de]
	cp $ff
	jr z, .done
;>     step = mem[sequence]
;>     sequence += 1
	inc de
	push de
;>     p = TradeFuncPointerTable + 2 * step
	ld hl, TradeFuncPointerTable
	add a
	ld c, a
	ld b, $0
	add hl, bc
;>     function = mem16[p]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     call(function)                            # it returns to the top of the loop
	ld de, .loop
	push de
	jp hl ; call trade func, which will return to the top of the loop
.done
;> hSCX = scx
	pop af
	ldh [hSCX], a
;> hSCY = scy
	pop af
	ldh [hSCY], a
;> wOptions = options
	pop af
	ld [wOptions], a
	ret



; The functions in the sequences below are executed in order by TradeFuncCommon.
; They are from opposite perspectives. The external clock one makes use of
; Trade_SwapNames to swap the player and enemy names for some functions.

;@ path: engine/movie/trade
InternalClockTradeFuncSequence:
	db (LoadTradingGFXAndMonNamesTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowPlayerMonTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_DrawOpenEndOfLinkCableTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_AnimateBallEnteringLinkCableTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_AnimLeftToRightTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_Delay100TradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowClearedWindowTradeFunc - TradeFuncPointerTable) / 2
	db (PrintTradeWentToTextTradeFunc - TradeFuncPointerTable) / 2
	db (PrintTradeForSendsTextTradeFunc - TradeFuncPointerTable) / 2
	db (PrintTradeFarewellTextTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_AnimRightToLeftTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowClearedWindowTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_DrawOpenEndOfLinkCableTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowEnemyMonTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_Delay100TradeFunc - TradeFuncPointerTable) / 2
	db (Trade_CleanupTradeFunc - TradeFuncPointerTable) / 2
	db -1 ; end

;@ path: engine/movie/trade
ExternalClockTradeFuncSequence:
	db (LoadTradingGFXAndMonNamesTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowClearedWindowTradeFunc - TradeFuncPointerTable) / 2
	db (PrintTradeWillTradeTextTradeFunc - TradeFuncPointerTable) / 2
	db (PrintTradeFarewellTextTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_SwapNamesTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_AnimLeftToRightTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_SwapNamesTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowClearedWindowTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_DrawOpenEndOfLinkCableTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowEnemyMonTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_SlideTextBoxOffScreenTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowPlayerMonTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_DrawOpenEndOfLinkCableTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_AnimateBallEnteringLinkCableTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_SwapNamesTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_AnimRightToLeftTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_SwapNamesTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_Delay100TradeFunc - TradeFuncPointerTable) / 2
	db (Trade_ShowClearedWindowTradeFunc - TradeFuncPointerTable) / 2
	db (PrintTradeWentToTextTradeFunc - TradeFuncPointerTable) / 2
	db (Trade_CleanupTradeFunc - TradeFuncPointerTable) / 2
	db -1 ; end

;@ path: engine/movie/trade
TradeFuncPointerTable:
LoadTradingGFXAndMonNamesTradeFunc::
	dw LoadTradingGFXAndMonNames
Trade_ShowPlayerMonTradeFunc::
	dw Trade_ShowPlayerMon
Trade_DrawOpenEndOfLinkCableTradeFunc::
	dw Trade_DrawOpenEndOfLinkCable
Trade_AnimateBallEnteringLinkCableTradeFunc::
	dw Trade_AnimateBallEnteringLinkCable
Trade_ShowEnemyMonTradeFunc::
	dw Trade_ShowEnemyMon
Trade_AnimLeftToRightTradeFunc::
	dw Trade_AnimLeftToRight
Trade_AnimRightToLeftTradeFunc::
	dw Trade_AnimRightToLeft
Trade_Delay100TradeFunc::
	dw Trade_Delay100
Trade_ShowClearedWindowTradeFunc::
	dw Trade_ShowClearedWindow
PrintTradeWentToTextTradeFunc::
	dw PrintTradeWentToText
PrintTradeForSendsTextTradeFunc::
	dw PrintTradeForSendsText
PrintTradeFarewellTextTradeFunc::
	dw PrintTradeFarewellText
PrintTradeTakeCareTextTradeFunc::
	dw PrintTradeTakeCareText
PrintTradeWillTradeTextTradeFunc::
	dw PrintTradeWillTradeText
Trade_CleanupTradeFunc::
	dw Trade_Cleanup
Trade_SlideTextBoxOffScreenTradeFunc::
	dw Trade_SlideTextBoxOffScreen
Trade_SwapNamesTradeFunc::
	dw Trade_SwapNames

;@ path: engine/movie/trade
;@ def Trade_Delay100()
;@ Wait 100 frames.
;@ test: skip waits for frames
Trade_Delay100:
;> DelayFrames(100)
	ld c, 100
	jp DelayFrames

;@ path: engine/movie/trade
;@ def Trade_CopyTileMapToVRAM()
;@ Copy the screen buffer to VRAM once, over the next VBlanks.
;@ test: skip waits for frames
Trade_CopyTileMapToVRAM:
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
	ret

;@ path: engine/movie/trade
;@ def Trade_Delay80()
;@ Wait 80 frames.
;@ test: skip waits for frames
Trade_Delay80:
;> DelayFrames(80)
	ld c, 80
	jp DelayFrames

;@ path: engine/movie/trade
;@ def Trade_ClearTileMap()
;@ Blank the screen buffer.
Trade_ClearTileMap:
;> FillMemory(coord(0, 0), SCREEN_AREA, charmap(' ')[0])
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_AREA
	ld a, ' '
	jp FillMemory

;@ path: engine/movie/trade
;@ def LoadTradingGFXAndMonNames()
;@ Set up the trade animation: its tiles, blank BG maps, no sprites, fast text, and the two Pokémon's names
;@ (the player's in wStringBuffer, the other in wNameBuffer).
;@ test: skip turns the LCD off
LoadTradingGFXAndMonNames:
;> Trade_ClearTileMap()
	call Trade_ClearTileMap
;> DisableLCD()
	call DisableLCD
;> FarCopyData2(BANK(TradingAnimationGraphics), TradingAnimationGraphics, vChars2 + 0x31 * TILE_SIZE, TradingAnimationGraphicsEnd - TradingAnimationGraphics)
	ld hl, TradingAnimationGraphics
	ld de, vChars2 + TILE_SIZE * $31
	ld bc, TradingAnimationGraphicsEnd - TradingAnimationGraphics
	ld a, BANK(TradingAnimationGraphics)
	call FarCopyData2
;> FarCopyData2(BANK(TradingAnimationGraphics2), TradingAnimationGraphics2, vSprites + 0x7C * TILE_SIZE, TradingAnimationGraphics2End - TradingAnimationGraphics2)
	ld hl, TradingAnimationGraphics2
	ld de, vSprites + TILE_SIZE * $7c
	ld bc, TradingAnimationGraphics2End - TradingAnimationGraphics2
	ld a, BANK(TradingAnimationGraphics2)
	call FarCopyData2
;> FillMemory(vBGMap0, 2 * TILEMAP_AREA, charmap(' ')[0])
	ld hl, vBGMap0
	ld bc, 2 * TILEMAP_AREA
	ld a, ' '
	call FillMemory
;> ClearSprites()
	call ClearSprites
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> rOBP0 = 0xF0 if wOnSGB else 0xE4
	ld a, [wOnSGB]
	and a
	ld a, $e4 ; non-SGB OBP0
	jr z, .next
	ld a, $f0 ; SGB OBP0
.next
	ldh [rOBP0], a
;> EnableLCD()
	call EnableLCD
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> wNamedObjectIndex = wTradedPlayerMonSpecies
	ld a, [wTradedPlayerMonSpecies]
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> CopyData(addr(wNameBuffer), addr(wStringBuffer), NAME_LENGTH)
	ld hl, wNameBuffer
	ld de, wStringBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> wNamedObjectIndex = wTradedEnemyMonSpecies
	ld a, [wTradedEnemyMonSpecies]
	ld [wNamedObjectIndex], a
;> GetMonName()
	jp GetMonName

;@ path: engine/movie/trade
;@ def Trade_LoadMonPartySpriteGfx()
;@ Load the party icons for the Pokémon travelling through the cable.
;@ test: skip copies to VRAM over several VBlanks
Trade_LoadMonPartySpriteGfx:
;> rOBP1 = 0b11010000
;> LoadMonPartySpriteGfx()
	ld a, %11010000
	ldh [rOBP1], a
	ld b, BANK(LoadMonPartySpriteGfx)
	ld hl, LoadMonPartySpriteGfx
	jp Bankswitch

;@ path: engine/movie/trade
;@ def Trade_SwapNames()
;@ Swap the player's and the other player's names (the clocked side shows the trade from the other side).
Trade_SwapNames:
;> CopyData(addr(wPlayerName), addr(wBuffer), NAME_LENGTH)
	ld hl, wPlayerName
	ld de, wBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(addr(wLinkEnemyTrainerName), addr(wPlayerName), NAME_LENGTH)
	ld hl, wLinkEnemyTrainerName
	ld de, wPlayerName
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(addr(wBuffer), addr(wLinkEnemyTrainerName), NAME_LENGTH)
	ld hl, wBuffer
	ld de, wLinkEnemyTrainerName
	ld bc, NAME_LENGTH
	jp CopyData

;@ path: engine/movie/trade
;@ def Trade_Cleanup()
;@ After the animation: the normal palettes and text delay again.
;@ test: skip sets the palettes
Trade_Cleanup:
;> LoadGBPal()
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	xor a
	call LoadGBPal
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
	ret

;@ path: engine/movie/trade
;@ def Trade_ShowPlayerMon()
;@ The player's Pokémon slides in with its info box, goes into its Poké Ball, and the ball drops.
;@ test: skip runs the trade animation
Trade_ShowPlayerMon:
;> rLCDC = LCDC_ON | LCDC_WIN_9800 | LCDC_WIN_ON | LCDC_BLOCK21 | LCDC_BG_9C00 | LCDC_OBJ_8 | LCDC_OBJ_ON | LCDC_BG_ON
	ld a, LCDC_ON | LCDC_WIN_9800 | LCDC_WIN_ON | LCDC_BLOCK21 | LCDC_BG_9C00 | LCDC_OBJ_8 | LCDC_OBJ_ON | LCDC_BG_ON
	ldh [rLCDC], a
;> hWY = 0x50
	ld a, $50
	ldh [hWY], a
;> rWX = 0x86
	ld a, $86
	ldh [rWX], a
;> hSCX = 0x86
	ldh [hSCX], a
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> TextBoxBorder(coord(4, 0), 6, 10)
	ld hl, (0) * SCREEN_WIDTH + (4) + wTileMap
	ld b, 6
	ld c, 10
	call TextBoxBorder
;> Trade_PrintPlayerMonInfoText()
	call Trade_PrintPlayerMonInfoText
;> CopyScreenTileBufferToVRAM(vBGMap0 >> 8)
	ld b, HIGH(vBGMap0)
	call CopyScreenTileBufferToVRAM
;> ClearScreen()
	call ClearScreen
;> Trade_LoadMonSprite(wTradedPlayerMonSpecies)
	ld a, [wTradedPlayerMonSpecies]
	call Trade_LoadMonSprite
;> x = 0x7E
	ld a, $7e
;> while x:                                          # window and picture slide in together
.slideScreenLoop
;>     DelayFrame()
	push af
	call DelayFrame
	pop af
;>     rWX = x
	ldh [rWX], a
;>     hSCX = x
	ldh [hSCX], a
;>     x -= 2
	dec a
	dec a
	and a
	jr nz, .slideScreenLoop
;> Trade_Delay80()
	call Trade_Delay80
;> Trade_ShowAnimation(TRADE_BALL_POOF_ANIM)
	ld a, TRADE_BALL_POOF_ANIM
	call Trade_ShowAnimation
;> Trade_ShowAnimation(TRADE_BALL_DROP_ANIM)         # clears the picture
	ld a, TRADE_BALL_DROP_ANIM
	call Trade_ShowAnimation ; clears mon pic
;> PlayCry(wTradedPlayerMonSpecies)
	ld a, [wTradedPlayerMonSpecies]
	call PlayCry
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
	ret

;@ path: engine/movie/trade
;@ def Trade_DrawOpenEndOfLinkCable()
;@ The open end of the link cable scrolls in from the right.
;@ test: skip runs the trade animation
Trade_DrawOpenEndOfLinkCable:
;> Trade_ClearTileMap()
	call Trade_ClearTileMap
;> CopyScreenTileBufferToVRAM(vBGMap0 >> 8)
	ld b, HIGH(vBGMap0)
	call CopyScreenTileBufferToVRAM
;> RunPaletteCommand(SET_PAL_GENERIC)
	ld b, SET_PAL_GENERIC
	call RunPaletteCommand

; This function call is pointless. It just copies blank tiles to VRAM that was
; already filled with blank tiles.
;> Trade_CopyCableTilesOffScreen(vBGMap1 + 0x8C)     # copies blank tiles: has no effect
	ld hl, vBGMap1 + $8c
	call Trade_CopyCableTilesOffScreen

;> hSCX = 0xA0
	ld a, $a0
	ldh [hSCX], a
;> DelayFrame()
	call DelayFrame
;> rLCDC = LCDC_ON | LCDC_WIN_9800 | LCDC_WIN_OFF | LCDC_BLOCK21 | LCDC_BG_9C00 | LCDC_OBJ_8 | LCDC_OBJ_ON | LCDC_BG_ON
	ld a, LCDC_ON | LCDC_WIN_9800 | LCDC_WIN_OFF | LCDC_BLOCK21 | LCDC_BG_9C00 | LCDC_OBJ_8 | LCDC_OBJ_ON | LCDC_BG_ON
	ldh [rLCDC], a
;> CopyTileIDsFromList_ZeroBaseTileID(coord(6, 2), TILEMAP_LINK_CABLE)
	ld hl, (2) * SCREEN_WIDTH + (6) + wTileMap
	ld b, TILEMAP_LINK_CABLE
	call CopyTileIDsFromList_ZeroBaseTileID
;> Trade_CopyTileMapToVRAM()
	call Trade_CopyTileMapToVRAM
;> PlaySound(SFX_HEAL_HP)
	ld a, SFX_HEAL_HP
	call PlaySound
;> for _ in range(20):
	ld c, 20
.loop
;>     hSCX = u8(hSCX + 4)
	ldh a, [hSCX]
	add 4
	ldh [hSCX], a
	dec c
	jr nz, .loop
	ret

;@ path: engine/movie/trade
;@ def Trade_AnimateBallEnteringLinkCable()
;@ The Poké Ball shakes, then travels into the cable as a bulge moving right, with a tink each step.
;@ test: skip runs the trade animation
Trade_AnimateBallEnteringLinkCable:
;> Trade_ShowAnimation(TRADE_BALL_SHAKE_ANIM)
	ld a, TRADE_BALL_SHAKE_ANIM
	call Trade_ShowAnimation
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> rOBP0 = 0b11100100
	ld a, %11100100
	ldh [rOBP0], a
;> wLinkCableAnimBulgeToggle = 0
	xor a
	ld [wLinkCableAnimBulgeToggle], a
;> x = 0x60
	ld bc, (($20) & $ff) << 8 + (($60) & $ff)
;>@move while True:
.moveBallInsideLinkCableLoop
;>     WriteOAMBlock(0, 0x20, x, Trade_BallInsideLinkCableOAMBlock)
	push bc
	xor a
	ld de, Trade_BallInsideLinkCableOAMBlock
	call WriteOAMBlock
;>     wLinkCableAnimBulgeToggle ^= 1
	ld a, [wLinkCableAnimBulgeToggle]
	xor $1
	ld [wLinkCableAnimBulgeToggle], a
;>     tile = 0x7E + wLinkCableAnimBulgeToggle   # the bulge's two shapes
	add $7e
;>     p = addr(wShadowOAMSprite00TileID)
	ld hl, wShadowOAMSprite00TileID
;>     step = OBJ_SIZE
	ld de, OBJ_SIZE
;>@bulge     for _ in range(OBJ_SIZE):                 # 4 sprites (OBJ_SIZE is 4 as well)
	ld c, e
.cycleLinkCableBulgeTile
;>         mem[p] = tile
	ld [hl], a
;>         p += step
	add hl, de
;=@bulge
	dec c
	jr nz, .cycleLinkCableBulgeTile
;>     Delay3()
	call Delay3
;>     x = u8(x + 4)
	pop bc
	ld a, c
	add $4
	ld c, a
;>     if x >= 0xA0:
;>         break
	cp $a0
	jr nc, .ballSpriteReachedEdgeOfScreen
;>     PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;=@move
	jr .moveBallInsideLinkCableLoop
.ballSpriteReachedEdgeOfScreen
;> ClearSprites()
	call ClearSprites
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> ClearScreen()
	call ClearScreen
;> CopyScreenTileBufferToVRAM(vBGMap0 >> 8)
	ld b, HIGH(vBGMap0)
	call CopyScreenTileBufferToVRAM
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
	ret

;@ path: engine/movie/trade
Trade_BallInsideLinkCableOAMBlock:
	db $7e, 0
	db $7e, OAM_XFLIP
	db $7e, OAM_YFLIP
	db $7e, OAM_XFLIP | OAM_YFLIP

