;@ def Trade_InitGameboyTransferGfx()
;@ A blank screen with the party icon tiles loaded, the window off screen.
;@ test: skip copies to VRAM over several VBlanks
Trade_InitGameboyTransferGfx:
; Initialises the graphics for showing a mon moving between gameboys.
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> ClearScreen()
	call ClearScreen
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> Trade_LoadMonPartySpriteGfx()
	call Trade_LoadMonPartySpriteGfx
;> DelayFrame()
	call DelayFrame
;> rLCDC = LCDC_ON | LCDC_WIN_9800 | LCDC_WIN_ON | LCDC_BLOCK21 | LCDC_BG_9C00 | LCDC_OBJ_8 | LCDC_OBJ_ON | LCDC_BG_ON
	ld a, LCDC_ON | LCDC_WIN_9800 | LCDC_WIN_ON | LCDC_BLOCK21 | LCDC_BG_9C00 | LCDC_OBJ_8 | LCDC_OBJ_ON | LCDC_BG_ON
	ldh [rLCDC], a
;> hSCX = 0
	xor a
	ldh [hSCX], a
;> hWY = 0x90
	ld a, $90
	ldh [hWY], a
	ret

;@ path: engine/movie/trade
;@ def Trade_DrawLeftGameboy()
;@ The left Game Boy with the cable going right from it, and the player's name below.
;@ test: skip waits a frame
Trade_DrawLeftGameboy:
;> Trade_ClearTileMap()
	call Trade_ClearTileMap

; draw link cable
;> mem[coord(11, 4)] = 0x5D                          # the cable's plug
	ld hl, (4) * SCREEN_WIDTH + (11) + wTileMap
	ld a, $5d
	ld [hli], a
;> for i in range(8):
;>     mem[coord(12 + i, 4)] = 0x5E
	ld a, $5e
	ld c, 8
.loop
	ld [hli], a
	dec c
	jr nz, .loop

; draw gameboy pic
;> CopyTileIDsFromList_ZeroBaseTileID(coord(5, 3), TILEMAP_GAME_BOY)
	ld hl, (3) * SCREEN_WIDTH + (5) + wTileMap
	ld b, TILEMAP_GAME_BOY
	call CopyTileIDsFromList_ZeroBaseTileID

; draw text box with player name below gameboy pic
;> TextBoxBorder(coord(4, 12), 2, 7)
	ld hl, (12) * SCREEN_WIDTH + (4) + wTileMap
	ld b, 2
	ld c, 7
	call TextBoxBorder
;> PlaceString(addr(wPlayerName), coord(5, 14))
	ld hl, (14) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wPlayerName
	call PlaceString

;> DelayFrame()
	jp DelayFrame

;@ path: engine/movie/trade
;@ def Trade_DrawRightGameboy()
;@ The right Game Boy with the cable coming from the left and down into it, and the other player's name above.
;@ test: skip waits a frame
Trade_DrawRightGameboy:
;> Trade_ClearTileMap()
	call Trade_ClearTileMap

; draw horizontal segment of link cable
;> at = coord(0, 4)
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
;> tile = 0x5E
	ld a, $5e
;>@h for _ in range(14):                         # the horizontal segment
	ld c, $e
.loop
;>     mem[at] = tile
;>     at += 1
	ld [hli], a
;=@h
	dec c
	jr nz, .loop

; draw vertical segment of link cable
;> mem[at] = 0x5F                                # the bend, at coord(14, 4)
	ld a, $5f
	ld [hl], a
;> step = SCREEN_WIDTH
	ld de, SCREEN_WIDTH
;> at += step
	add hl, de
;> tile = 0x61                                   # down rows 5 to 8
	ld a, $61
;> mem[at] = tile
	ld [hl], a
;> at += step
;> mem[at] = tile
	add hl, de
	ld [hl], a
;> at += step
;> mem[at] = tile
	add hl, de
	ld [hl], a
;> at += step
;> mem[at] = tile
	add hl, de
	ld [hl], a
;> at += step
	add hl, de
;> mem[at] = 0x60                                # coord(14, 9)
;> at -= 1
	ld a, $60
	ld [hld], a
;> mem[at] = 0x5D                                # the plug
	ld a, $5d
	ld [hl], a

; draw gameboy pic
;> CopyTileIDsFromList_ZeroBaseTileID(coord(7, 8), TILEMAP_GAME_BOY)
	ld hl, (8) * SCREEN_WIDTH + (7) + wTileMap
	ld b, TILEMAP_GAME_BOY
	call CopyTileIDsFromList_ZeroBaseTileID

; draw text box with enemy name above link cable
;> TextBoxBorder(coord(6, 0), 2, 7)
	ld hl, (0) * SCREEN_WIDTH + (6) + wTileMap
	ld b, 2
	ld c, 7
	call TextBoxBorder
;> PlaceString(addr(wLinkEnemyTrainerName), coord(7, 2))
	ld hl, (2) * SCREEN_WIDTH + (7) + wTileMap
	ld de, wLinkEnemyTrainerName
	call PlaceString

;> DelayFrame()
	jp DelayFrame

;@ path: engine/movie/trade
;@ def Trade_DrawCableAcrossScreen()
;@ Just the cable across the whole screen.
Trade_DrawCableAcrossScreen:
; Draws the link cable across the screen.
