	call Trade_ClearTileMap
;> at = coord(0, 4)
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
;> tile = 0x5E
	ld a, $5e
;>@lp for _ in range(SCREEN_WIDTH):
	ld c, SCREEN_WIDTH
.loop
;>     mem[at] = tile
;>     at += 1
	ld [hli], a
;=@lp
	dec c
	jr nz, .loop
	ret

;@ path: engine/movie/trade
;@ def Trade_CopyCableTilesOffScreen(dest: hl)
;@ Have the VBlank handler copy the cable row to `dest` in the second BG map, so the cable goes on when the
;@ screen scrolls; then wait 10 frames.
;@ test: skip waits for frames
Trade_CopyCableTilesOffScreen:
; This is used to copy the link cable tiles off screen so that the cable
; continues when the screen is scrolled.
;> # (dest is kept)
	push hl
;> CopyToRedrawRowOrColumnSrcTiles(coord(0, 4))
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
	call CopyToRedrawRowOrColumnSrcTiles
	pop hl
;> hRedrawRowOrColumnDest[1] = dest >> 8
	ld a, h
	ldh [hRedrawRowOrColumnDest + 1], a
;> hRedrawRowOrColumnDest[0] = dest & 0xFF
	ld a, l
	ldh [hRedrawRowOrColumnDest], a
;> hRedrawRowOrColumnMode = REDRAW_ROW
	ld a, REDRAW_ROW
	ldh [hRedrawRowOrColumnMode], a
;> DelayFrames(10)
	ld c, 10
	jp DelayFrames

;@ path: engine/movie/trade
;@ def Trade_AnimMonMoveHorizontal(units: b)
;@ Scroll the screen under the travelling icon by `units` steps of 16 pixels (2 pixels a frame), animating the
;@ icon after each step.
;@ test: skip waits for frames
Trade_AnimMonMoveHorizontal:
; Animates the mon going through the link cable horizontally over a distance of
; b 16-pixel units.
;>@units for _ in range(units):
;>     moving = wTradedMonMovingRight
	ld a, [wTradedMonMovingRight]
	ld e, a
;>@px     for _ in range(8):
	ld d, $8
.scrollLoop
;>         if moving == 1:                       # to the right
;>@right             hSCX = u8(hSCX + 2)
	ld a, e
	dec a
	jr z, .movingRight
; moving left
;>         else:
;>             hSCX = u8(hSCX - 2)
	ldh a, [hSCX]
	sub $2
	jr .next
.movingRight
;=@right
	ldh a, [hSCX]
	add $2
.next
	ldh [hSCX], a
;>         DelayFrame()
	call DelayFrame
;=@px
	dec d
	jr nz, .scrollLoop
;>     Trade_AnimCircledMon()
	call Trade_AnimCircledMon
;=@units
	dec b
	jr nz, Trade_AnimMonMoveHorizontal
	ret

;@ path: engine/movie/trade
;@ def Trade_AnimCircledMon()
;@ Flash the cable (palette) and switch the 20 sprites of the icon and its circle to their other frame.
Trade_AnimCircledMon:
; Cycles between the two animation frames of the mon party sprite, cycles
; between a circle and an oval around the mon sprite, and makes the cable flash.
;> # (de, bc and hl are kept)
	push de
	push bc
	push hl
;> rBGP ^= 0x3C                                  # the cable flashes
	ldh a, [rBGP]
	xor $3c ; make link cable flash
	ldh [rBGP], a
;> tile = addr(wShadowOAMSprite00TileID)
	ld hl, wShadowOAMSprite00TileID
;> step = OBJ_SIZE
	ld de, OBJ_SIZE
;>@lp for _ in range(0x14):
	ld c, $14
.loop
;>     mem[tile] ^= ICONOFFSET                   # the other frame
	ld a, [hl]
	xor ICONOFFSET
	ld [hl], a
;>     tile += step
	add hl, de
;=@lp
	dec c
	jr nz, .loop
	pop hl
	pop bc
	pop de
	ret

;@ path: engine/movie/trade
;@ def Trade_WriteCircledMonOAM()
;@ The travelling Pokémon: its party icon inside a circle, moved to (wBaseCoordX, wBaseCoordY).
;@ test: hLoadedROMBank = 0x1C; wMonPartySpriteSpecies = rand(1, 190)
Trade_WriteCircledMonOAM:
;> WriteMonPartySpriteOAMBySpecies()
	ld b, BANK(WriteMonPartySpriteOAMBySpecies)
	ld hl, WriteMonPartySpriteOAMBySpecies
	call Bankswitch
;> Trade_WriteCircleOAMBlock()
	call Trade_WriteCircleOAMBlock
;> Trade_AddOffsetsToOAMCoords()                 # it follows

;@ path: engine/movie/trade
;@ def Trade_AddOffsetsToOAMCoords()
;@ Move the first 20 sprites by (wBaseCoordX, wBaseCoordY).
Trade_AddOffsetsToOAMCoords:
;> oam = addr(wShadowOAM)
	ld hl, wShadowOAM
;>@lp for _ in range(0x14):
	ld c, $14
.loop
;>     mem[oam] = u8(wBaseCoordY + mem[oam])
;>     oam += 1
	ld a, [wBaseCoordY]
	add [hl]
	ld [hli], a
;>     mem[oam] = u8(wBaseCoordX + mem[oam])
;>     oam += 1
	ld a, [wBaseCoordX]
	add [hl]
	ld [hli], a
;>     oam += 2                                  # past the tile and the attributes
	inc hl
	inc hl
;=@lp
	dec c
	jr nz, .loop
	ret

;@ path: engine/movie/trade
;@ def Trade_AnimMonMoveVertical()
;@ Move the icon sprites themselves where the cable bends: moving right, 16 pixels right then 40 down into the
;@ Game Boy; moving left, 40 up then 16 left. Four steps each, 8 frames apart.
;@ test: skip waits for frames
Trade_AnimMonMoveVertical:
; Animates the mon going through the link cable vertically as well as
; horizontally for a bit. The last bit of horizontal movement (when moving
; right) or the first bit of horizontal movement (when moving left) are done
; here instead of Trade_AnimMonMoveHorizontal because this function moves the
; sprite itself rather than scrolling the screen around the sprite. Moving the
; sprite itself is necessary because the vertical segment of the link cable is
; to the right of the screen position that the mon sprite has when
; Trade_AnimMonMoveHorizontal is executing.
;> if wTradedMonMovingRight:
	ld a, [wTradedMonMovingRight]
	and a
	jr z, .movingLeft
; moving right
	; move right
;>     moves = ((4, 0), (0, 10))                 # right, then down (each through .doAnim)
	ld bc, ((4) & $ff) << 8 + ((0) & $ff)
	call .doAnim
	; move down
	ld bc, ((0) & $ff) << 8 + ((10) & $ff)
	jr .doAnim
.movingLeft
;> else:
	; move up
;>     moves = ((0, u8(-10)), (u8(-4), 0))       # up, then left
	ld bc, ((0) & $ff) << 8 + ((-10) & $ff)
	call .doAnim
	; move left
	ld bc, ((-4) & $ff) << 8 + ((0) & $ff)
.doAnim
;> for dx, dy in moves:
;>     wBaseCoordX = dx
	ld a, b
	ld [wBaseCoordX], a
;>     wBaseCoordY = dy
	ld a, c
	ld [wBaseCoordY], a
;>     for _ in range(4):
	ld d, $4
.loop
;>         Trade_AddOffsetsToOAMCoords()
	call Trade_AddOffsetsToOAMCoords
;>         Trade_AnimCircledMon()
	call Trade_AnimCircledMon
;>         DelayFrames(8)
	ld c, 8
	call DelayFrames
	dec d
	jr nz, .loop
	ret

;@ path: engine/movie/trade
;@ def Trade_WriteCircleOAMBlock()
;@ The four quarters of the circle around the icon, as OAM blocks 1 to 4 from Trade_CircleOAMBlocks.
Trade_WriteCircleOAMBlock:
; Writes the OAM blocks for the circle around the traded mon as it passes
; the link cable.
;> entry = Trade_CircleOAMBlocks
	ld hl, Trade_CircleOAMBlocks
;> count = 4
	ld c, 4
;> block = 0
	xor a
;>@lp for _ in range(count):
.loop
;>     # (the counter is kept)
	push bc
;>     src = mem16[entry]
;>     entry += 2
	ld e, [hl]
	inc hl
	ld d, [hl]
	inc hl
;>     x = mem[entry]
;>     entry += 1
	ld c, [hl]
	inc hl
;>     y = mem[entry]
;>     entry += 1
	ld b, [hl]
	inc hl
;>     # (entry is kept)
	push hl
;>     block += 1
	inc a
;>     # (block is kept)
	push af
;>     WriteOAMBlock(block, y, x, src)
	call WriteOAMBlock
	pop af
	pop hl
	pop bc
;=@lp
	dec c
	jr nz, .loop
	ret


;@ path: engine/movie/trade
Trade_CircleOAMBlocks:
	dw .OAMBlock0
	db 8, 8
	dw .OAMBlock1
	db 24, 8
	dw .OAMBlock2
	db 8, 24
	dw .OAMBlock3
	db 24, 24

.OAMBlock0:
	db ICON_TRADEBUBBLE << 2 + 0, OAM_PAL1
	db ICON_TRADEBUBBLE << 2 + 1, OAM_PAL1
	db ICON_TRADEBUBBLE << 2 + 2, OAM_PAL1
	db ICON_TRADEBUBBLE << 2 + 3, OAM_PAL1

.OAMBlock1:
	db ICON_TRADEBUBBLE << 2 + 1, OAM_PAL1 | OAM_XFLIP
	db ICON_TRADEBUBBLE << 2 + 0, OAM_PAL1 | OAM_XFLIP
	db ICON_TRADEBUBBLE << 2 + 3, OAM_PAL1 | OAM_XFLIP
	db ICON_TRADEBUBBLE << 2 + 2, OAM_PAL1 | OAM_XFLIP

.OAMBlock2:
	db ICON_TRADEBUBBLE << 2 + 2, OAM_PAL1 | OAM_YFLIP
	db ICON_TRADEBUBBLE << 2 + 3, OAM_PAL1 | OAM_YFLIP
	db ICON_TRADEBUBBLE << 2 + 0, OAM_PAL1 | OAM_YFLIP
	db ICON_TRADEBUBBLE << 2 + 1, OAM_PAL1 | OAM_YFLIP

.OAMBlock3:
	db ICON_TRADEBUBBLE << 2 + 3, OAM_PAL1 | OAM_XFLIP | OAM_YFLIP
	db ICON_TRADEBUBBLE << 2 + 2, OAM_PAL1 | OAM_XFLIP | OAM_YFLIP
	db ICON_TRADEBUBBLE << 2 + 1, OAM_PAL1 | OAM_XFLIP | OAM_YFLIP
	db ICON_TRADEBUBBLE << 2 + 0, OAM_PAL1 | OAM_XFLIP | OAM_YFLIP

