;@ path: engine/movie/trade
;@ def Trade_SlideTextBoxOffScreen()
;@ After a pause, slide the window (the text box, and sometimes a picture) off to the right, 2 pixels a frame.
;@ test: skip waits for frames
Trade_SlideTextBoxOffScreen:
; Slides the window right until it's off screen. The window usually just has
; a text box at the bottom when this is called. However, when this is called
; after Trade_ShowEnemyMon in the external clock sequence, there is a mon pic
; above the text box and it is also scrolled off the screen.
;> DelayFrames(50)
	ld c, 50
	call DelayFrames
;> while True:
.loop
;>     DelayFrame()
	call DelayFrame
;>     rWX = u8(rWX + 2)
	ldh a, [rWX]
	inc a
	inc a
	ldh [rWX], a
;>     if rWX == 0xA1:
;>         break
	cp $a1
	jr nz, .loop
;> Trade_ClearTileMap()
	call Trade_ClearTileMap
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> rWX = 7
	ld a, $7
	ldh [rWX], a
	ret

