	jp Predef
DEF MOVE_NIDORINO_RIGHT EQU $FFFFFFFF
DEF MOVE_GENGAR_RIGHT EQU 0
DEF MOVE_GENGAR_LEFT EQU 1

DEF ANIMATION_END EQU 80

;@ path: engine/movie/intro
;@ def PlayIntro()
;@ The intro: the Game Freak shooting star, then the fight between Nidorino and Gengar.
;@ test: skip runs the intro
PlayIntro:
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hAutoBGTransferEnabled = 1
	inc a
	ldh [hAutoBGTransferEnabled], a
;> PlayShootingStar()
	call PlayShootingStar
;> PlayIntroScene()
	call PlayIntroScene
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> hSCX = 0
	xor a
	ldh [hSCX], a
;> hAutoBGTransferEnabled = 0
	ldh [hAutoBGTransferEnabled], a
;> ClearSprites()
	call ClearSprites
;> DelayFrame()
	call DelayFrame
	ret

;@ path: engine/movie/intro
;@ def PlayIntroScene()
;@ The intro fight: Nidorino (sprites) walks in, hops twice, Gengar (background) raises its arm and slashes,
;@ Nidorino is knocked back, hops again and lunges. Any button ends it early.
;@ test: skip runs the intro
PlayIntroScene:
;> RunPaletteCommand(SET_PAL_NIDORINO_INTRO)
	ld b, SET_PAL_NIDORINO_INTRO
	call RunPaletteCommand
;> rBGP = 0b11100100
	ld a, SHADE_BLACK << 6 | SHADE_DARK << 4 | SHADE_LIGHT << 2 | SHADE_WHITE
	ldh [rBGP], a
;> rOBP0 = 0b11100100
	ldh [rOBP0], a
;> rOBP1 = 0b11100100
	ldh [rOBP1], a
;> hSCX = 0
	xor a
	ldh [hSCX], a
;> IntroCopyTiles(TILEMAP_GENGAR_INTRO_1)
	ld b, TILEMAP_GENGAR_INTRO_1
	call IntroCopyTiles
;> wBaseCoordX = 0
	ld a, 0
	ld [wBaseCoordX], a
;> wBaseCoordY = 80
	ld a, 80
	ld [wBaseCoordY], a
;> InitIntroNidorinoOAM(6, 6)
	ld bc, ((6) & $ff) << 8 + ((6) & $ff)
	call InitIntroNidorinoOAM
;> if IntroMoveMon(80 // 2, MOVE_NIDORINO_RIGHT):
;>     return
	ld de, ((80 / 2) & $ff) << 8 + ((MOVE_NIDORINO_RIGHT) & $ff)
	call IntroMoveMon
	ret c

; hip
;> PlaySound(SFX_INTRO_HIP)                      # Nidorino hops twice, two times
	ld a, SFX_INTRO_HIP
	call PlaySound
;> wIntroNidorinoBaseTile = 0
	xor a
	ld [wIntroNidorinoBaseTile], a
;> AnimateIntroNidorino(IntroNidorinoAnimation1)
	ld de, IntroNidorinoAnimation1
	call AnimateIntroNidorino
; hop
;> PlaySound(SFX_INTRO_HOP)
	ld a, SFX_INTRO_HOP
	call PlaySound
;> AnimateIntroNidorino(IntroNidorinoAnimation2)
	ld de, IntroNidorinoAnimation2
	call AnimateIntroNidorino
;> if CheckForUserInterruption(10):
;>     return
	ld c, 10
	call CheckForUserInterruption
	ret c

; hip
;> PlaySound(SFX_INTRO_HIP)
	ld a, SFX_INTRO_HIP
	call PlaySound
;> AnimateIntroNidorino(IntroNidorinoAnimation1)
	ld de, IntroNidorinoAnimation1
	call AnimateIntroNidorino
; hop
;> PlaySound(SFX_INTRO_HOP)
	ld a, SFX_INTRO_HOP
	call PlaySound
;> AnimateIntroNidorino(IntroNidorinoAnimation2)
	ld de, IntroNidorinoAnimation2
	call AnimateIntroNidorino
;> if CheckForUserInterruption(30):
;>     return
	ld c, 30
	call CheckForUserInterruption
	ret c

; raise
;> # Gengar raises its arm
;> IntroCopyTiles(TILEMAP_GENGAR_INTRO_2)
	ld b, TILEMAP_GENGAR_INTRO_2
	call IntroCopyTiles
;> PlaySound(SFX_INTRO_RAISE)
	ld a, SFX_INTRO_RAISE
	call PlaySound
;> IntroMoveMon(8 // 2, MOVE_GENGAR_LEFT)
	ld de, ((8 / 2) & $ff) << 8 + ((MOVE_GENGAR_LEFT) & $ff)
	call IntroMoveMon
;> if CheckForUserInterruption(30):
;>     return
	ld c, 30
	call CheckForUserInterruption
	ret c

; slash
;> # and slashes; Nidorino is pushed back
;> IntroCopyTiles(TILEMAP_GENGAR_INTRO_3)
	ld b, TILEMAP_GENGAR_INTRO_3
	call IntroCopyTiles
;> PlaySound(SFX_INTRO_CRASH)
	ld a, SFX_INTRO_CRASH
	call PlaySound
;> IntroMoveMon(16 // 2, MOVE_GENGAR_RIGHT)
	ld de, ((16 / 2) & $ff) << 8 + ((MOVE_GENGAR_RIGHT) & $ff)
	call IntroMoveMon
; hip
;> PlaySound(SFX_INTRO_HIP)
	ld a, SFX_INTRO_HIP
	call PlaySound
;> wIntroNidorinoBaseTile = (FightIntroFrontMon2 - FightIntroFrontMon) // TILE_SIZE
	ld a, (FightIntroFrontMon2 - FightIntroFrontMon) / TILE_SIZE
	ld [wIntroNidorinoBaseTile], a
;> AnimateIntroNidorino(IntroNidorinoAnimation3)
	ld de, IntroNidorinoAnimation3
	call AnimateIntroNidorino
;> if CheckForUserInterruption(30):
;>     return
	ld c, 30
	call CheckForUserInterruption
	ret c

;> IntroMoveMon(8 // 2, MOVE_GENGAR_LEFT)
	ld de, ((8 / 2) & $ff) << 8 + ((MOVE_GENGAR_LEFT) & $ff)
	call IntroMoveMon
;> IntroCopyTiles(TILEMAP_GENGAR_INTRO_1)
	ld b, TILEMAP_GENGAR_INTRO_1
	call IntroCopyTiles
;> if CheckForUserInterruption(60):
;>     return
	ld c, 60
	call CheckForUserInterruption
	ret c

; hip
;> PlaySound(SFX_INTRO_HIP)
	ld a, SFX_INTRO_HIP
	call PlaySound
;> wIntroNidorinoBaseTile = 0
	xor a
	ld [wIntroNidorinoBaseTile], a
;> AnimateIntroNidorino(IntroNidorinoAnimation4)
	ld de, IntroNidorinoAnimation4
	call AnimateIntroNidorino
; hop
;> PlaySound(SFX_INTRO_HOP)
	ld a, SFX_INTRO_HOP
	call PlaySound
;> AnimateIntroNidorino(IntroNidorinoAnimation5)
	ld de, IntroNidorinoAnimation5
	call AnimateIntroNidorino
;> if CheckForUserInterruption(20):
;>     return
	ld c, 20
	call CheckForUserInterruption
	ret c

;> wIntroNidorinoBaseTile = (FightIntroFrontMon2 - FightIntroFrontMon) // TILE_SIZE
	ld a, (FightIntroFrontMon2 - FightIntroFrontMon) / TILE_SIZE
	ld [wIntroNidorinoBaseTile], a
;> AnimateIntroNidorino(IntroNidorinoAnimation6)
	ld de, IntroNidorinoAnimation6
	call AnimateIntroNidorino
;> if CheckForUserInterruption(30):
;>     return
	ld c, 30
	call CheckForUserInterruption
	ret c

; lunge
;> # Nidorino lunges
;> PlaySound(SFX_INTRO_LUNGE)
	ld a, SFX_INTRO_LUNGE
	call PlaySound
;> wIntroNidorinoBaseTile = (FightIntroFrontMon3 - FightIntroFrontMon) // TILE_SIZE
	ld a, (FightIntroFrontMon3 - FightIntroFrontMon) / TILE_SIZE
	ld [wIntroNidorinoBaseTile], a
;> AnimateIntroNidorino(IntroNidorinoAnimation7)
	ld de, IntroNidorinoAnimation7
	jp AnimateIntroNidorino

;@ path: engine/movie/intro
;@ def AnimateIntroNidorino(frames: de)
;@ Move Nidorino's 36 sprites by each (Y, X) step of an animation, 5 frames apart, up to ANIMATION_END.
;@ test: skip waits for frames
AnimateIntroNidorino:
;> while mem[frames] != ANIMATION_END:
	ld a, [de]
	cp ANIMATION_END
	ret z
;>     wBaseCoordY = mem[frames]
	ld [wBaseCoordY], a
;>     wBaseCoordX = mem[frames + 1]
	inc de
	ld a, [de]
	ld [wBaseCoordX], a
;>     UpdateIntroNidorinoOAM(6 * 6)
	push de
	ld c, 6 * 6
	call UpdateIntroNidorinoOAM
;>     DelayFrames(5)
	ld c, 5
	call DelayFrames
;>     frames += 2
	pop de
	inc de
	jr AnimateIntroNidorino

;@ path: engine/movie/intro
;@ def UpdateIntroNidorinoOAM(count: c)
;@ Move the first `count` sprites by (wBaseCoordX, wBaseCoordY) and give them tiles from wIntroNidorinoBaseTile
;@ on.
;@ test: count = rand(1, 36)
UpdateIntroNidorinoOAM:
;> oam = addr(wShadowOAM)
	ld hl, wShadowOAM
;> tile = wIntroNidorinoBaseTile
	ld a, [wIntroNidorinoBaseTile]
	ld d, a
;> for _ in range(count):
.loop
;>     mem[oam] = u8(wBaseCoordY + mem[oam])
	ld a, [wBaseCoordY]
	add [hl]
	ld [hli], a ; Y
;>     mem[oam + 1] = u8(wBaseCoordX + mem[oam + 1])
	ld a, [wBaseCoordX]
	add [hl]
	ld [hli], a ; X
;>     mem[oam + 2] = tile
	ld a, d
	ld [hli], a ; tile
;>     tile = u8(tile + 1)
;>     oam += OBJ_SIZE
	inc hl
	inc d
	dec c
	jr nz, .loop
	ret

;@ path: engine/movie/intro
;@ def InitIntroNidorinoOAM(columns: b, rows: c)
;@ Lay out Nidorino as `columns` columns of `rows` sprites below (wBaseCoordX, wBaseCoordY), tiles 0 on, behind
;@ the background.
;@ test: columns = rand(1, 6); rows = rand(1, 6)
InitIntroNidorinoOAM:
;> oam = addr(wShadowOAM)
	ld hl, wShadowOAM
;> tile = 0
	ld d, 0
;>@cols for _ in range(columns):
.loop
;>     y = wBaseCoordY
	push bc
	ld a, [wBaseCoordY]
	ld e, a
;>     for _ in range(rows):
.innerLoop
;>         y = u8(y + 8)
	ld a, e
	add 8
	ld e, a
;>         mem[oam] = y
	ld [hli], a ; Y
;>         mem[oam + 1] = wBaseCoordX
	ld a, [wBaseCoordX]
	ld [hli], a ; X
;>         mem[oam + 2] = tile
	ld a, d
	ld [hli], a ; tile
;>         mem[oam + 3] = OAM_PRIO
	ld a, OAM_PRIO
	ld [hli], a ; attributes
;>         tile = u8(tile + 1)
;>         oam += OBJ_SIZE
	inc d
	dec c
	jr nz, .innerLoop
;>     wBaseCoordX = u8(wBaseCoordX + 8)
	ld a, [wBaseCoordX]
	add 8
	ld [wBaseCoordX], a
;=@cols
	pop bc
	dec b
	jr nz, .loop
	ret

;@ path: engine/movie/intro
;@ def IntroClearScreen()
;@ Clear the second BG map's visible rows (tile 0, white).
IntroClearScreen:
;> IntroClearCommon(vBGMap1, TILEMAP_WIDTH * SCREEN_HEIGHT)
	ld hl, vBGMap1
	ld bc, TILEMAP_WIDTH * SCREEN_HEIGHT
	jr IntroClearCommon

;@ path: engine/movie/intro
;@ def IntroClearMiddleOfScreen()
;@ Clear the screen between the intro's black bars.
IntroClearMiddleOfScreen:
; clear the area of the tile map between the black bars on the top and bottom
;> IntroClearCommon(coord(0, 4), SCREEN_WIDTH * 10)
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_WIDTH * 10

;@ path: engine/movie/intro
;@ def IntroClearCommon(dest: hl, count: bc)
;@ Set `count` bytes from dest to tile 0.
;@ test: dest = rand(0xC000, 0xCC00); count = rand(1, 600)
IntroClearCommon:
;> for i in range(count):
;>     mem[dest + i] = 0
	ld [hl], 0
	inc hl
	dec bc
	ld a, b
	or c
	jr nz, IntroClearCommon
;> return
	ret

;@ path: engine/movie/intro
;@ def IntroPlaceBlackTiles(dest: hl, count: c) -> hl
;@ `count` black tiles (tile 1) from dest.
;@ test: dest = rand(0xC000, 0xCE00); count = rand(1, 255)
IntroPlaceBlackTiles:
;> for i in range(count):
	ld a, 1
.loop
;>     mem[dest + i] = 1
	ld [hli], a
	dec c
	jr nz, .loop
;> return dest + count
	ret

;@ path: engine/movie/intro
;@ def IntroMoveMon(times: d, how: e) -> carry
;@ Move the intro's fighters `times` times by 2 pixels: Nidorino right (its sprites and the background
;@ together), or Gengar (the background) left or right. Any button stops it (carry).
;@ test: skip waits for frames
IntroMoveMon:
; d = number of times to move the mon (2 pixels each time)
;>@times for _ in range(times):
;>     if how == MOVE_NIDORINO_RIGHT:            # its sprites move along with the background
	ld a, e
	cp MOVE_NIDORINO_RIGHT
	jr z, .moveNidorinoRight
;>@nx         wBaseCoordX = 2
;>@ny         wBaseCoordY = 0
;>@nu         UpdateIntroNidorinoOAM(6 * 6)
;>     if how not in (MOVE_NIDORINO_RIGHT, MOVE_GENGAR_LEFT):
	cp MOVE_GENGAR_LEFT
	jr z, .moveGengarLeft
; move Gengar right
;>         scx = u8(hSCX - 2)                    # Gengar to the right
	ldh a, [hSCX]
	dec a
	dec a
	jr .next
;>@else     else:
;>@plus         scx = u8(hSCX + 2)
.moveNidorinoRight
;=@nx
	push de
	ld a, 2
	ld [wBaseCoordX], a
;=@ny
	xor a
	ld [wBaseCoordY], a
;=@nu
	ld c, 6 * 6
	call UpdateIntroNidorinoOAM
	pop de
.moveGengarLeft
;=@plus
	ldh a, [hSCX]
	inc a
	inc a
.next
;>     hSCX = scx
	ldh [hSCX], a
;>     if CheckForUserInterruption(2):
;>         return True
	push de
	ld c, 2
	call CheckForUserInterruption
	pop de
	ret c
;=@times
	dec d
	jr nz, IntroMoveMon
;> return False
	ret

;@ path: engine/movie/intro
;@ def IntroCopyTiles(tilemap: b)
;@ Put Gengar's tile map `tilemap` at coord(13, 7).
;@ test: skip goes through the predef table
IntroCopyTiles:
;> CopyTileIDsFromList_ZeroBaseTileID(coord(13, 7), tilemap)
	ld hl, (7) * SCREEN_WIDTH + (13) + wTileMap

;@ path: engine/movie/intro
;@ def CopyTileIDsFromList_ZeroBaseTileID(dest: hl, tilemap: b)
;@ CopyTileIDsFromList with tile IDs from 0.
;@ test: skip goes through the predef table
CopyTileIDsFromList_ZeroBaseTileID:
;> CopyTileIDsFromList()                             # through the predef table, base tile 0
	ld c, 0
	ld a, (CopyTileIDsFromListPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/movie/intro
;@ def PlayIntroMoveSound()
;@ Unused: play the sound GetIntroMoveSound picks.
;@ test: skip goes through the predef table
PlayIntroMoveSound: ; unreferenced
;> sound = GetIntroMoveSound()                       # through the predef table, result in b
;> PlaySound(sound)
	ld a, (GetIntroMoveSoundPredef - PredefPointers) / 3
	call Predef
	ld a, b
	jp PlaySound

;@ path: engine/movie/intro
;@ def LoadIntroGraphics()
;@ Load the intro's tiles: Gengar and the Game Freak logo for the background (the logo also as sprites) and
;@ Nidorino as sprites.
;@ test: skip copies to VRAM
LoadIntroGraphics:
;> FarCopyData2(BANK(FightIntroBackMon), FightIntroBackMon, vChars2, FightIntroBackMonEnd - FightIntroBackMon)
	ld hl, FightIntroBackMon
	ld de, vChars2
	ld bc, FightIntroBackMonEnd - FightIntroBackMon
	ld a, BANK(FightIntroBackMon)
	call FarCopyData2
;> FarCopyData2(BANK(GameFreakIntro), GameFreakIntro, vChars2 + (FightIntroBackMonEnd - FightIntroBackMon), GameFreakIntroEnd - GameFreakIntro)
	ld hl, GameFreakIntro
	ld de, vChars2 + (FightIntroBackMonEnd - FightIntroBackMon)
	ld bc, GameFreakIntroEnd - GameFreakIntro
	ld a, BANK(GameFreakIntro)
	call FarCopyData2
;> FarCopyData2(BANK(GameFreakIntro), GameFreakIntro, vChars1, GameFreakIntroEnd - GameFreakIntro)
	ld hl, GameFreakIntro
	ld de, vChars1
	ld bc, GameFreakIntroEnd - GameFreakIntro
	ld a, BANK(GameFreakIntro)
	call FarCopyData2
;> FarCopyData2(BANK(FightIntroFrontMon), FightIntroFrontMon, vChars0, FightIntroFrontMonEnd - FightIntroFrontMon)
	ld hl, FightIntroFrontMon
	ld de, vChars0
	ld bc, FightIntroFrontMonEnd - FightIntroFrontMon
	ld a, BANK(FightIntroFrontMon)
	jp FarCopyData2

;@ path: engine/movie/intro
;@ def PlayShootingStar()
;@ The copyright screen for 3 seconds, then the Game Freak logo with its shooting star between black bars, and
;@ the start of the intro music.
;@ test: skip runs the intro
PlayShootingStar:
;> RunPaletteCommand(SET_PAL_GAME_FREAK_INTRO)
	ld b, SET_PAL_GAME_FREAK_INTRO
	call RunPaletteCommand
;> LoadCopyrightAndTextBoxTiles()
	ld b, BANK(LoadCopyrightAndTextBoxTiles)
	ld hl, LoadCopyrightAndTextBoxTiles
	call Bankswitch
;> rBGP = 0b11100100
	ld a, SHADE_BLACK << 6 | SHADE_DARK << 4 | SHADE_LIGHT << 2 | SHADE_WHITE
	ldh [rBGP], a
;> DelayFrames(180)
	ld c, 180
	call DelayFrames
;> ClearScreen()
	call ClearScreen
;> DisableLCD()
	call DisableLCD
;> wCurOpponent = 0
	xor a
	ld [wCurOpponent], a
;> IntroDrawBlackBars()
	call IntroDrawBlackBars
;> LoadIntroGraphics()
	call LoadIntroGraphics
;> EnableLCD()
	call EnableLCD
;> rLCDC = (rLCDC & ~(1 << B_LCDC_WINDOW) | 1 << B_LCDC_BG_MAP) & 0xFF
	ld hl, rLCDC
	res B_LCDC_WINDOW, [hl]
	set B_LCDC_BG_MAP, [hl]
;> DelayFrames(64)
	ld c, 64
	call DelayFrames
;> if not AnimateShootingStar():
	ld b, BANK(AnimateShootingStar)
	ld hl, AnimateShootingStar
	call Bankswitch
	push af
	; A `call LoadPresentsGraphic` here was removed in localization
	pop af
	jr c, .next ; skip the delay if the user interrupted the animation
;>     DelayFrames(40)                               # not after a button press
	ld c, 40
	call DelayFrames
.next
;> wAudioROMBank = BANK(Music_IntroBattle)
	ld a, BANK(Music_IntroBattle)
	ld [wAudioROMBank], a
;> wAudioSavedROMBank = BANK(Music_IntroBattle)
	ld [wAudioSavedROMBank], a
;> wNewSoundID = MUSIC_INTRO_BATTLE
	ld a, MUSIC_INTRO_BATTLE
	ld [wNewSoundID], a
;> PlaySound(MUSIC_INTRO_BATTLE)
	call PlaySound
;> IntroClearMiddleOfScreen()
	call IntroClearMiddleOfScreen
;> ClearSprites()
	call ClearSprites
;> Delay3()
	jp Delay3

;@ path: engine/movie/intro
;@ def IntroDrawBlackBars()
;@ Clear the screen and draw 4-row black bars at the top and bottom, in the screen buffer and the second BG map.
IntroDrawBlackBars:
; clear the screen and draw black bars on the top and bottom
;> IntroClearScreen()
	call IntroClearScreen
;> IntroPlaceBlackTiles(coord(0, 0), SCREEN_WIDTH * 4)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld c, SCREEN_WIDTH * 4
	call IntroPlaceBlackTiles
;> IntroPlaceBlackTiles(coord(0, 14), SCREEN_WIDTH * 4)
	ld hl, (14) * SCREEN_WIDTH + (0) + wTileMap
	ld c, SCREEN_WIDTH * 4
	call IntroPlaceBlackTiles
;> IntroPlaceBlackTiles(vBGMap1, TILEMAP_WIDTH * 4)
	ld hl, vBGMap1
	ld c,  TILEMAP_WIDTH * 4
	call IntroPlaceBlackTiles
;> IntroPlaceBlackTiles(vBGMap1 + 14 * TILEMAP_WIDTH, TILEMAP_WIDTH * 4)
	ld hl, (14) * TILEMAP_WIDTH + (0) + vBGMap1
	ld c,  TILEMAP_WIDTH * 4
	jp IntroPlaceBlackTiles

;@ path: engine/movie/intro
;@ def LoadPresentsGraphic()
;@ Unused: in the Japanese versions it showed "PRESENTS" under the Game Freak logo; here it does nothing.
LoadPresentsGraphic: ; unreferenced
	; This routine loaded the "PRESENTS" text graphic (tiles
	; $67, $68, $69, $6A, $6B, and $6C from gamefreak_presents.2bpp)
	; at coordinates (11, 7) in the Japanese versions.
	; It was dummied out in the English localization.
;> return
	ret

;@ path: engine/movie/intro
IntroNidorinoAnimation0:
	db 0, 0
	db ANIMATION_END

;@ path: engine/movie/intro
IntroNidorinoAnimation1:
; This is a sequence of pixel movements for part of the Nidorino animation. This
; list describes how Nidorino should hop.
; First byte is y movement, second byte is x movement
	db  0, 0
	db -2, 2
	db -1, 2
	db  1, 2
	db  2, 2
	db ANIMATION_END

;@ path: engine/movie/intro
IntroNidorinoAnimation2:
; This is a sequence of pixel movements for part of the Nidorino animation.
; First byte is y movement, second byte is x movement
	db  0,  0
	db -2, -2
	db -1, -2
	db  1, -2
	db  2, -2
	db ANIMATION_END

;@ path: engine/movie/intro
IntroNidorinoAnimation3:
