;@ path: engine/movie/trade2
;@ def Trade_PrintPlayerMonInfoText()
;@ In the trade animation: the player's Pokémon's number, name, original trainer and ID at the top.
Trade_PrintPlayerMonInfoText:
;> PlaceString(Trade_MonInfoText, coord(5, 0))
	ld hl, (0) * SCREEN_WIDTH + (5) + wTileMap
	ld de, Trade_MonInfoText
	call PlaceString
;> wPokedexNum = wTradedPlayerMonSpecies
	ld a, [wTradedPlayerMonSpecies]
	ld [wPokedexNum], a
;> Predef((IndexToPokedexPredef - PredefPointers) // 3)      # IndexToPokedex
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> PrintNumber(addr(wPokedexNum), coord(9, 0), LEADING_ZEROES | 1, 3)
	ld hl, (0) * SCREEN_WIDTH + (9) + wTileMap
	ld de, wPokedexNum
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> PlaceString(addr(wStringBuffer), coord(5, 2))
	ld hl, (2) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wStringBuffer
	call PlaceString
;> PlaceString(addr(wTradedPlayerMonOT), coord(8, 4))
	ld hl, (4) * SCREEN_WIDTH + (8) + wTileMap
	ld de, wTradedPlayerMonOT
	call PlaceString
;> PrintNumber(addr(wTradedPlayerMonOTID), coord(8, 6), LEADING_ZEROES | 2, 5)
	ld hl, (6) * SCREEN_WIDTH + (8) + wTileMap
	ld de, wTradedPlayerMonOTID
	ld bc, ((LEADING_ZEROES | 2) & $ff) << 8 + ((5) & $ff)
	jp PrintNumber

;@ path: engine/movie/trade2
;@ def Trade_PrintEnemyMonInfoText()
;@ The same for the other player's Pokémon, in the lower half.
Trade_PrintEnemyMonInfoText:
;> PlaceString(Trade_MonInfoText, coord(5, 10))
	ld hl, (10) * SCREEN_WIDTH + (5) + wTileMap
	ld de, Trade_MonInfoText
	call PlaceString
;> wPokedexNum = wTradedEnemyMonSpecies
	ld a, [wTradedEnemyMonSpecies]
	ld [wPokedexNum], a
;> Predef((IndexToPokedexPredef - PredefPointers) // 3)      # IndexToPokedex
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> PrintNumber(addr(wPokedexNum), coord(9, 10), LEADING_ZEROES | 1, 3)
	ld hl, (10) * SCREEN_WIDTH + (9) + wTileMap
	ld de, wPokedexNum
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> PlaceString(addr(wNameBuffer), coord(5, 12))
	ld hl, (12) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wNameBuffer
	call PlaceString
;> PlaceString(addr(wTradedEnemyMonOT), coord(8, 14))
	ld hl, (14) * SCREEN_WIDTH + (8) + wTileMap
	ld de, wTradedEnemyMonOT
	call PlaceString
;> PrintNumber(addr(wTradedEnemyMonOTID), coord(8, 16), LEADING_ZEROES | 2, 5)
	ld hl, (16) * SCREEN_WIDTH + (8) + wTileMap
	ld de, wTradedEnemyMonOTID
	ld bc, ((LEADING_ZEROES | 2) & $ff) << 8 + ((5) & $ff)
	jp PrintNumber

