Trade_MonInfoText:
	db   "──№<DOT>"
	db "<NEXT>", ""
	db "<NEXT>", "OT/"
	db "<NEXT>", "<ID>№<DOT>@"


SECTION "Pokédex Rating", ROMX

;@ path: engine/events/pokedex_rating
;@ def DisplayDexRating()
;@ Oak's Pokédex rating: count the Pokémon seen and owned and pick the comment for the number owned from
;@ DexRatingsTable. Normally it is printed with a jingle; for the Hall of Fame (event flag, cleared here) the
;@ counts and the comment are copied to wDexRatingNumMonsSeen instead.
DisplayDexRating:
;> CountSetBits(addr(wPokedexSeen), addr(wPokedexSeenEnd) - addr(wPokedexSeen))
	ld hl, wPokedexSeen
	ld b, wPokedexSeenEnd - wPokedexSeen
	call CountSetBits
;> hDexRatingNumMonsSeen = wNumSetBits
	ld a, [wNumSetBits]
	ldh [hDexRatingNumMonsSeen], a
;> CountSetBits(addr(wPokedexOwned), addr(wPokedexOwnedEnd) - addr(wPokedexOwned))
	ld hl, wPokedexOwned
	ld b, wPokedexOwnedEnd - wPokedexOwned
	call CountSetBits
;> hDexRatingNumMonsOwned = wNumSetBits
	ld a, [wNumSetBits]
	ldh [hDexRatingNumMonsOwned], a
;> p = DexRatingsTable                          # entries: owned below this, text
	ld hl, DexRatingsTable
.findRating
;>@rating while hDexRatingNumMonsOwned >= mem[p]:
	ld a, [hli]
	ld b, a
	ldh a, [hDexRatingNumMonsOwned]
	cp b
	jr c, .foundRating
;>     p += 3
	inc hl
	inc hl
;=@rating
	jr .findRating
.foundRating
;> text = mem16[p + 1]
	ld a, [hli]
	ld h, [hl]
	ld l, a ; load text pointer into hl
;> hallOfFame = event(EVENT_HALL_OF_FAME_DEX_RATING)
	ld a, [wEventFlags + ((EVENT_HALL_OF_FAME_DEX_RATING) / 8)]
	bit (EVENT_HALL_OF_FAME_DEX_RATING) % 8, a
;> reset_event(EVENT_HALL_OF_FAME_DEX_RATING)
	res (EVENT_HALL_OF_FAME_DEX_RATING) % 8, a
	ld [wEventFlags + ((EVENT_HALL_OF_FAME_DEX_RATING) / 8)], a
;> if not hallOfFame:
	jr nz, .hallOfFame
;>     PrintText(DexCompletionText)
	push hl
	ld hl, DexCompletionText
	call PrintText
;>     PrintText(text)
	pop hl
	call PrintText
;>     PlayPokedexRatingSfx()                   # in another bank
	ld b, BANK(PlayPokedexRatingSfx)
	ld hl, PlayPokedexRatingSfx
	call Bankswitch
;>     WaitForTextScrollButtonPress()
;>     return
	jp WaitForTextScrollButtonPress
.hallOfFame
;> out = addr(wDexRatingNumMonsSeen)
	ld de, wDexRatingNumMonsSeen
;> mem[out] = hDexRatingNumMonsSeen
	ldh a, [hDexRatingNumMonsSeen]
	ld [de], a
	inc de
;> mem[out + 1] = hDexRatingNumMonsOwned
	ldh a, [hDexRatingNumMonsOwned]
	ld [de], a
;> out += 2
	inc de
.copyRatingTextLoop
;> while mem[text] != charmap('@')[0]:
	ld a, [hli]
	cp '@'
	jr z, .doneCopying
;>     mem[out] = mem[text]
	ld [de], a
;>     out += 1
;>     text += 1
	inc de
	jr .copyRatingTextLoop
.doneCopying
;> mem[out] = charmap('@')[0]
	ld [de], a
	ret

