SECTION "Hidden Events Core", ROMX

;@ path: engine/overworld/hidden_events
;@ def IsPlayerOnDungeonWarp(coords: hl)
;@ Has the player just stepped onto one of the dungeon warp tiles in `coords` (Seafoam holes, Victory
;@ Road...)? Then remember which one and arm the dungeon warp. Nothing happens while still standing on
;@ one.
;@ test: coords = rand_ram(9); mem[coords + 2 * rand(0, 4)] = 0xFF
IsPlayerOnDungeonWarp::
;> wWhichDungeonWarp = 0
	xor a
	ld [wWhichDungeonWarp], a
;> if wStatusFlags3 & (1 << BIT_ON_DUNGEON_WARP):
;>     return
	ld a, [wStatusFlags3]
	bit BIT_ON_DUNGEON_WARP, a
	ret nz
;> if not ArePlayerCoordsInArray(coords):
;>     return
	call ArePlayerCoordsInArray
	ret nc
;> wWhichDungeonWarp = wCoordIndex[0]
	ld a, [wCoordIndex]
	ld [wWhichDungeonWarp], a
;> wStatusFlags3 = wStatusFlags3 | 1 << BIT_ON_DUNGEON_WARP
	ld hl, wStatusFlags3
	set BIT_ON_DUNGEON_WARP, [hl]
;> wStatusFlags6 = wStatusFlags6 | 1 << BIT_DUNGEON_WARP
	ld hl, wStatusFlags6
	set BIT_DUNGEON_WARP, [hl]
	ret

; if a hidden event was found, stores $00 in [hDidntFindAnyHiddenEvent], else stores $ff
;@ path: engine/overworld/hidden_events
;@ def CheckForHiddenEvent() -> hl
;@ Is there a hidden event (item, sign, PC, bookshelf...) on the tile the player faces? Looks through the
;@ current map's list of (y, x, argument, bank, function). If found, the argument and bank are stored and
;@ the function returned; otherwise hDidntFindAnyHiddenEvent becomes $FF.
;@ test: wCurMap = rand(0, NUM_MAPS - 1); mem[0xC109] = 4 * rand(0, 3)
CheckForHiddenEvent::
;> hItemAlreadyFound = 0
	ld hl, hItemAlreadyFound
	xor a
	ld [hli], a ; [hItemAlreadyFound]
;> hSavedMapTextPtr[0] = 0
	ld [hli], a ; [hSavedMapTextPtr]
;> hSavedMapTextPtr[1] = 0
	ld [hli], a ; [hSavedMapTextPtr + 1]
;> hDidntFindAnyHiddenEvent = 0
	ld [hl], a  ; [hDidntFindAnyHiddenEvent]
;> p = HiddenEventMaps
;> k = 0
	ld de, $0
	ld hl, HiddenEventMaps
.hiddenMapLoop
;>@maps while mem[p] != 0xFF and mem[p] != wCurMap:
	ld a, [hli]
	ld b, a
	cp $ff
	jr z, .noMatch
;=@maps
	ld a, [wCurMap]
	cp b
	jr z, .foundMatchingMap
;>     p += 1
;>     k += 2
	inc de
	inc de
	jr .hiddenMapLoop
.foundMatchingMap
;> if mem[p] != 0xFF:                           # the map has hidden events: its list
;>     p = mem16[HiddenEventPointers + k]
	ld hl, HiddenEventPointers
	add hl, de
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     wHiddenEventFunctionArgument = 0
	push hl
	ld hl, wHiddenEventFunctionArgument
	xor a
	ld [hli], a
;>     wHiddenEventFunctionRomBank = 0
	ld [hli], a
;>     wHiddenEventIndex = 0
	ld [hl], a
	pop hl
.hiddenEventLoop
;>     while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
	jr z, .noMatch
;>         wHiddenEventY = mem[p]
	ld [wHiddenEventY], a
	ld b, a
;>         wHiddenEventX = mem[p + 1]
	ld a, [hli]
	ld [wHiddenEventX], a
	ld c, a
;>         CheckIfCoordsInFrontOfPlayerMatch(wHiddenEventY, wHiddenEventX)
	call CheckIfCoordsInFrontOfPlayerMatch
;>         if hCoordsInFrontOfPlayerMatch == 0:     # found
;>@arg             wHiddenEventFunctionArgument = mem[p + 2]
;>@bank             wHiddenEventFunctionRomBank = mem[p + 3]
;>@func             return mem16[p + 4]
	ldh a, [hCoordsInFrontOfPlayerMatch]
	and a
	jr z, .foundMatchingEvent
;>         p += 6
	inc hl
	inc hl
	inc hl
	inc hl
;>         wHiddenEventIndex = u8(wHiddenEventIndex + 1)
	push hl
	ld hl, wHiddenEventIndex
	inc [hl]
	pop hl
	jr .hiddenEventLoop
.foundMatchingEvent
;=@arg
	ld a, [hli]
	ld [wHiddenEventFunctionArgument], a
;=@bank
	ld a, [hli]
	ld [wHiddenEventFunctionRomBank], a
;=@func
	ld a, [hli]
	ld h, [hl]
	ld l, a
	ret
.noMatch
;> hDidntFindAnyHiddenEvent = 0xFF
	ld a, $ff
	ldh [hDidntFindAnyHiddenEvent], a
;> return p + 1
	ret

; checks if the coordinates in front of the player's sprite match Y in b and X in c
; [hCoordsInFrontOfPlayerMatch] = $00 if they match, $ff if they don't match
;@ path: engine/overworld/hidden_events
;@ def CheckIfCoordsInFrontOfPlayerMatch(y: b, x: c)
;@ Is (y, x) the tile the player faces? hCoordsInFrontOfPlayerMatch becomes $00 if so, else $FF.
;@ test: wYCoord = rand(0, 3); wXCoord = rand(0, 3); y = rand(0, 4); x = rand(0, 4); mem[0xC109] = 4 * rand(0, 3)
CheckIfCoordsInFrontOfPlayerMatch:
;> facing = wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
;> if facing == SPRITE_FACING_UP:
	cp SPRITE_FACING_UP
	jr z, .facingUp
;>@up     same = y == u8(wYCoord - 1) and x == wXCoord
;> elif facing == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr z, .facingLeft
;>@left     same = x == u8(wXCoord - 1) and y == wYCoord
;> elif facing == SPRITE_FACING_RIGHT:
	cp SPRITE_FACING_RIGHT
	jr z, .facingRight
; facing down
;>@right     same = x == u8(wXCoord + 1) and y == wYCoord
;> else:
;>     same = y == u8(wYCoord + 1) and x == wXCoord
	ld a, [wYCoord]
	inc a
	jr .upDownCommon
.facingUp
;=@up
	ld a, [wYCoord]
	dec a
.upDownCommon
;=@up
	cp b
	jr nz, .didNotMatch
	ld a, [wXCoord]
	cp c
	jr nz, .didNotMatch
	jr .matched
.facingLeft
;=@left
	ld a, [wXCoord]
	dec a
	jr .leftRightCommon
.facingRight
;=@right
	ld a, [wXCoord]
	inc a
.leftRightCommon
;=@right
	cp c
	jr nz, .didNotMatch
	ld a, [wYCoord]
	cp b
	jr nz, .didNotMatch
.matched
;> hCoordsInFrontOfPlayerMatch = 0 if same else 0xFF
	xor a
	jr .done
.didNotMatch
	ld a, $ff
.done
	ldh [hCoordsInFrontOfPlayerMatch], a
	ret



