SECTION "Screen Effects", ROMX

; b = new color for BG color 0 (usually white) for 4 frames
;@ path: engine/gfx/screen_effects
;@ def ChangeBGPalColor0_4Frames()
;@ Set the bits of the predef's b in the background palette for 4 frames, then clear color 0 again (a flash).
;@ test: skip waits for frames
ChangeBGPalColor0_4Frames:
;> _, _, bc = GetPredefRegisters()
	call GetPredefRegisters
;> rBGP |= bc >> 8
	ldh a, [rBGP]
	or b
	ldh [rBGP], a
;> DelayFrames(4)
	ld c, 4
	call DelayFrames
;> rBGP &= 0b11111100
	ldh a, [rBGP]
	and %11111100
	ldh [rBGP], a
	ret

;@ path: engine/gfx/screen_effects
;@ def PredefShakeScreenVertically()
;@ Shake the screen up and down by moving the window: b pixels (the predef's b) and back, then one pixel less
;@ each time down to 1.
;@ test: skip waits for frames
PredefShakeScreenVertically:
; Moves the window down and then back in a sequence of progressively smaller
; numbers of pixels, starting at b.
;> _, _, bc = GetPredefRegisters()
;> amount = bc >> 8
	call GetPredefRegisters
;> wDisableVBlankWYUpdate = 1
	ld a, 1
	ld [wDisableVBlankWYUpdate], a
;> start = 0
	xor a
;> while True:
.loop
;>     hMutateWY = start
	ldh [hMutateWY], a
;>     for _ in range(2):                        # .MutateWY below: down, then back
;>@wy1         hMutateWY ^= amount
;>@wy2         rWY = hMutateWY
;>@wy3         DelayFrames(3)
	call .MutateWY
	call .MutateWY
;>     amount = u8(amount - 1)
	dec b
;>     start = amount
	ld a, b
;>     if amount == 0:
;>         break
	jr nz, .loop
;> wDisableVBlankWYUpdate = 0
	xor a
	ld [wDisableVBlankWYUpdate], a
	ret

.MutateWY
;=@wy1
	ldh a, [hMutateWY]
	xor b
	ldh [hMutateWY], a
;=@wy2
	ldh [rWY], a
;=@wy3
	ld c, 3
	jp DelayFrames

;@ path: engine/gfx/screen_effects
;@ def PredefShakeScreenHorizontally()
;@ Shake the screen sideways by moving the window: b pixels (the predef's b) right and back, then one pixel
;@ less each time down to 1.
;@ test: skip waits for frames
PredefShakeScreenHorizontally:
; Moves the window right and then back in a sequence of progressively smaller
; numbers of pixels, starting at b.
;> _, _, bc = GetPredefRegisters()
;> amount = bc >> 8
	call GetPredefRegisters
;> start = 0
	xor a
;> while True:
.loop
;>     hMutateWX = start
	ldh [hMutateWX], a
;>@wx1     hMutateWX ^= amount                       # .MutateWX below: right
;>@wx2     rWX = (0 if hMutateWX >> 7 else hMutateWX) + 7     # never left of the screen edge
	call .MutateWX
;>@wx3     DelayFrames(4)
;>     DelayFrames(1)
	ld c, 1
	call DelayFrames
;>@wxb1     hMutateWX ^= amount                       # and back
;>@wxb2     rWX = (0 if hMutateWX >> 7 else hMutateWX) + 7
	call .MutateWX
;>@wxb3     DelayFrames(4)
;>     amount = u8(amount - 1)
	dec b
;>     start = amount
	ld a, b
;>     if amount == 0:
;>         break
	jr nz, .loop

; restore normal WX
;> rWX = 7
	ld a, 7
	ldh [rWX], a
	ret

.MutateWX
;=@wx1
	ldh a, [hMutateWX]
	xor b
	ldh [hMutateWX], a
;=@wx2
	bit 7, a ; negative?
	jr z, .skipZeroing
	xor a ; zero a if it's negative
.skipZeroing
	add 7
	ldh [rWX], a
;=@wx3
	ld c, 4
	jp DelayFrames


SECTION "Predefs", ROMX

;@ path: engine/events/give_pokemon
;@ def _GivePokemon() -> carry
;@ Give the player wCurPartySpecies: into the party if there is room (wAddedToParty = 1), else into the
;@ current PC box with a "sent to BOX n" text. Carry clear only when the box is full too.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
_GivePokemon::
; returns success in carry
; and whether the mon was added to the party in [wAddedToParty]
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wAddedToParty = 0
	xor a
	ld [wAddedToParty], a
;> if wPartyCount < PARTY_LENGTH:               # room in the party
;>@owned     SetPokedexOwnedFlag()
;>@add     AddPartyMon()
;>@flags     wDoNotWaitForButtonPressAfterDisplayingText = wAddedToParty = 1
	ld a, [wPartyCount]
	cp PARTY_LENGTH
	jr c, .addToParty
;>@yes     return True
;> if wBoxCount >= MONS_PER_BOX:
;>@full     PrintText(BoxIsFullText)
;>@no     return False
	ld a, [wBoxCount]
	cp MONS_PER_BOX
	jr nc, .boxFull
; add to box
;> wEnemyBattleStatus3 = 0
	xor a
	ld [wEnemyBattleStatus3], a
;> wEnemyMonSpecies2 = wCurPartySpecies
	ld a, [wCurPartySpecies]
	ld [wEnemyMonSpecies2], a
;> LoadEnemyMonData()                           # in another bank
	ld hl, LoadEnemyMonData
	ld b, BANK(LoadEnemyMonData)
	call Bankswitch
;> SetPokedexOwnedFlag()
	call SetPokedexOwnedFlag
;> SendNewMonToBox()                            # in another bank
	ld hl, SendNewMonToBox
	ld b, BANK(SendNewMonToBox)
	call Bankswitch
;> box = wCurrentBoxNum & BOX_NUM_MASK          # 0-based
;> s = addr(wStringBuffer)
	ld hl, wStringBuffer
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
;> if box >= 9:
	cp 9
	jr c, .singleDigitBoxNum
;>     mem[s] = charmap('1')[0]
	sub 9
	ld [hl], '1'
;>     s += 1
	inc hl
;>     mem[s] = u8(box - 9 + charmap('0')[0])
	add '0'
	jr .next
.singleDigitBoxNum
;> else:
;>     mem[s] = u8(box + charmap('1')[0])
	add '1'
.next
	ld [hli], a
;> mem[s + 1] = charmap('@')[0]
	ld [hl], '@'
;> PrintText(SentToBoxText)
	ld hl, SentToBoxText
	call PrintText
;> return True
	scf
	ret
.boxFull
;=@full
	ld hl, BoxIsFullText
	call PrintText
;=@no
	and a
	ret
.addToParty
;=@owned
	call SetPokedexOwnedFlag
;=@add
	call AddPartyMon
;=@flags
	ld a, 1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
	ld [wAddedToParty], a
;=@yes
	scf
	ret

;@ path: engine/events/give_pokemon
;@ def SetPokedexOwnedFlag()
;@ Mark wCurPartySpecies as owned in the Pokédex and print "<PLAYER> got <MON>!"
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
SetPokedexOwnedFlag:
;> species = wCurPartySpecies
	ld a, [wCurPartySpecies]
	push af
;> wPokedexNum = species
	ld [wPokedexNum], a
;> IndexToPokedex()                             # a predef
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> index = u8(wPokedexNum - 1)
	ld a, [wPokedexNum]
	dec a
	ld c, a
;> FlagAction(addr(wPokedexOwned), index, FLAG_SET)  # owned; through FlagActionPredef
	ld hl, wPokedexOwned
	ld b, FLAG_SET
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> wNamedObjectIndex = species
	pop af
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> PrintText(GotMonText)
	ld hl, GotMonText
	jp PrintText

;@ path: engine/events/give_pokemon
GotMonText:
	db TX_FAR
	dw _GotMonText
	db BANK(_GotMonText)
	db TX_SOUND_GET_ITEM_1
	db TX_END

;@ path: engine/events/give_pokemon
SentToBoxText:
	db TX_FAR
	dw _SentToBoxText
	db BANK(_SentToBoxText)
	db TX_END

;@ path: engine/events/give_pokemon
BoxIsFullText:
	db TX_FAR
	dw _BoxIsFullText
	db BANK(_BoxIsFullText)
	db TX_END
;@ path: engine/predefs
;@ def GetPredefPointer(saved_hl: hl, saved_de: de, saved_bc: bc) -> hl
;@ Save hl, de and bc for the predef (big-endian, in wPredefHL/DE/BC), look up entry wPredefID of PredefPointers
;@ (bank, address) and return the address, with the bank in wPredefBank.
GetPredefPointer::
; Back up the contents of the registers (hl, de, bc).
; Then put the bank and address of predef
; wPredefID in [wPredefBank] and hl.

;> wPredefHL[0] = saved_hl >> 8
	ld a, h
	ld [wPredefHL], a
;> wPredefHL[1] = saved_hl & 0xFF
	ld a, l
	ld [wPredefHL + 1], a

;> wPredefDE[0] = saved_de >> 8
	ld hl, wPredefDE
	ld a, d
	ld [hli], a
;> wPredefDE[1] = saved_de & 0xFF
	ld a, e
	ld [hli], a

	ASSERT wPredefDE + 2 == wPredefBC
;> wPredefBC[0] = saved_bc >> 8
	ld a, b
	ld [hli], a
;> wPredefBC[1] = saved_bc & 0xFF
	ld [hl], c

;> entry = PredefPointers                        # 3 bytes each: bank, address
	ld hl, PredefPointers
	ld de, 0

;> id = wPredefID
	ld a, [wPredefID]
	ld e, a
;> offset = (2 * id & 0xFF) + id                 # 3 * id with the doubling in 8 bits: right below 128
	add a
	add e
	ld e, a
	jr nc, .nocarry
	inc d

.nocarry
;> entry += offset
	add hl, de
	ld d, h
	ld e, l

	; get bank of predef routine
;> wPredefBank = mem[entry]
	ld a, [de]
	ld [wPredefBank], a

	; get pointer
;> low = mem[entry + 1]
	inc de
	ld a, [de]
	ld l, a
;> return low | mem[entry + 2] << 8
	inc de
	ld a, [de]
	ld h, a

	ret


;@ path: engine/predefs
PredefPointers::
; these are pointers to ASM routines.
; they appear to be used in overworld map scripts.
DrawPlayerHUDAndHPBarPredef::
	db BANK(DrawPlayerHUDAndHPBar)
	dw DrawPlayerHUDAndHPBar
CopyUncompressedPicToTilemapPredef::
	db BANK(CopyUncompressedPicToTilemap)
	dw CopyUncompressedPicToTilemap
AnimateSendingOutMonPredef::
	db BANK(AnimateSendingOutMon)
	dw AnimateSendingOutMon
ScaleSpriteByTwoPredef::
