SECTION "Battle Engine 8", ROMX

;@ path: engine/battle/init_battle_variables
;@ def InitBattleVariables()
;@ Clear the battle state before a battle starts, mark Safari Zone battles as such and start the battle music.
InitBattleVariables:
;> wSavedTileAnimations = hTileAnimations
	ldh a, [hTileAnimations]
	ld [wSavedTileAnimations], a
;> wActionResultOrTookBattleTurn = wBattleResult = 0
	xor a
	ld [wActionResultOrTookBattleTurn], a
	ld [wBattleResult], a
;> fill(addr(wPartyAndBillsPCSavedMenuItem), 0, 4)
	ld hl, wPartyAndBillsPCSavedMenuItem
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;> wListScrollOffset = wCriticalHitOrOHKO = 0
	ld [wListScrollOffset], a
	ld [wCriticalHitOrOHKO], a
;> mem[wBattleMonSpecies] = 0
	ld [wBattleMonSpecies], a
;> wPartyGainExpFlags = wPlayerMonNumber = wEscapedFromBattle = wMapPalOffset = 0
	ld [wPartyGainExpFlags], a
	ld [wPlayerMonNumber], a
	ld [wEscapedFromBattle], a
	ld [wMapPalOffset], a
;> wPlayerHPBarColor = wEnemyHPBarColor = 0
	ld hl, wPlayerHPBarColor
	ld [hli], a ; wPlayerHPBarColor
	ld [hl], a ; wEnemyHPBarColor
;> fill(addr(wCanEvolveFlags), 0, addr(wMiscBattleDataEnd) - addr(wMiscBattleData))
	ld hl, wCanEvolveFlags
	ld b, wMiscBattleDataEnd - wMiscBattleData
.loop
	ld [hli], a
	dec b
	jr nz, .loop
;> wTestBattlePlayerSelectedMove = POUND
	inc a ; POUND
	ld [wTestBattlePlayerSelectedMove], a
;> if SAFARI_ZONE_EAST <= wCurMap < SAFARI_ZONE_CENTER_REST_HOUSE:
	ld a, [wCurMap]
	cp SAFARI_ZONE_EAST
	jr c, .notSafariBattle
	cp SAFARI_ZONE_CENTER_REST_HOUSE
	jr nc, .notSafariBattle
;>     wBattleType = BATTLE_TYPE_SAFARI
	ld a, BATTLE_TYPE_SAFARI
	ld [wBattleType], a
.notSafariBattle
;> PlayBattleMusic()
	ld hl, PlayBattleMusic
	ld b, BANK(PlayBattleMusic)
	jp Bankswitch
;@ path: engine/battle/move_effects/paralyze
;@ def ParalyzeEffect_()
;@ Thunder Wave, Glare and Stun Spore: paralyze the target unless it already has a status, an Electric-type move
;@ meets a Ground-type target, or the move misses. Paralysis quarters its speed.
ParalyzeEffect_:
;> if hWhoseTurn == 0:
;>     status, move_type = wEnemyMonStatus, wPlayerMoveType
	ld hl, wEnemyMonStatus
	ld de, wPlayerMoveType
	ldh a, [hWhoseTurn]
	and a
	jp z, .next
;> else:
;>     status, move_type = wBattleMonStatus, wEnemyMoveType
	ld hl, wBattleMonStatus
	ld de, wEnemyMoveType
.next
;> if mem[status]:                          # it already has a status
;>@d1     DelayFrames(50)
;>@d2     return PrintDidntAffectText()
	ld a, [hl]
	and a ; does the target already have a status ailment?
	jr nz, .didntAffect
; check if the target is immune due to types
;> if move_type == ELECTRIC:                # no effect on Ground types
	ld a, [de]
	cp ELECTRIC
	jr nz, .hitTest
;>     ground = mem[status + 1] == GROUND            # the two types follow the status byte
	ld b, h
	ld c, l
	inc bc
	ld a, [bc]
	cp GROUND
;>     if not ground:
;>         ground = mem[status + 2] == GROUND
	jr z, .doesntAffect
	inc bc
	ld a, [bc]
	cp GROUND
;>     if ground:
;>@e1         DelayFrames(50)
;>@e2         return PrintDoesntAffectText()
	jr z, .doesntAffect
.hitTest
;> MoveHitTest()
	push hl
	ld hl, MoveHitTest
	ld b, BANK(MoveHitTest)
	call Bankswitch
	pop hl
;> if wMoveMissed:
;>@m1     DelayFrames(50)                               # (the same code as above)
;>@m2     return PrintDidntAffectText()
	ld a, [wMoveMissed]
	and a
	jr nz, .didntAffect
;> mem[status] |= 1 << PAR
	set PAR, [hl]
;> QuarterSpeedDueToParalysis()
	ld hl, QuarterSpeedDueToParalysis
	ld b, BANK(QuarterSpeedDueToParalysis)
	call Bankswitch
;> DelayFrames(30)
	ld c, 30
	call DelayFrames
;> PlayCurrentMoveAnimation()
	ld hl, PlayCurrentMoveAnimation
	ld b, BANK(PlayCurrentMoveAnimation)
	call Bankswitch
;> return PrintMayNotAttackText()
	ld hl, PrintMayNotAttackText
	ld b, BANK(PrintMayNotAttackText)
	jp Bankswitch
.didntAffect
;=@d1
	ld c, 50
	call DelayFrames
;=@d2
	ld hl, PrintDidntAffectText
	ld b, BANK(PrintDidntAffectText)
	jp Bankswitch
.doesntAffect
;=@e1
	ld c, 50
	call DelayFrames
;=@e2
	ld hl, PrintDoesntAffectText
	ld b, BANK(PrintDoesntAffectText)
	jp Bankswitch


SECTION "Hidden Events 2", ROMX

;@ path: engine/events/card_key
;@ def PrintCardKeyText()
;@ In Silph Co.: facing a card key door? With the Card Key it opens (the door's block becomes floor, with a
;@ sound and a text), without it a text says it needs a key.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
PrintCardKeyText:
;> p = SilphCoMapList
	ld hl, SilphCoMapList
	ld a, [wCurMap]
	ld b, a
.silphCoMapListLoop
;>@scan while True:
;>     m = mem[p]
;>@inc     p += 1
	ld a, [hli]
;>     if m == 0xFF:
;>         return
	cp -1
	ret z
;>     if m == wCurMap:
;>         break
	cp b
	jr nz, .silphCoMapListLoop
;> GetTileAndCoordsInFrontOfPlayer()            # a predef
	ld a, (GetTileAndCoordsInFrontOfPlayerPredef - PredefPointers) / 3
	call Predef
;> tile = wTileInFrontOfPlayer
	ld a, [wTileInFrontOfPlayer]
;> if tile != 0x18 and tile != 0x24:            # the card key doors
	cp $18
	jr z, .cardKeyDoorInFrontOfPlayer
	cp $24
	jr z, .cardKeyDoorInFrontOfPlayer
;>     if wCurMap != SILPH_CO_11F: return       # (the one on 11F is a different tile)
	ld b, a
	ld a, [wCurMap]
	cp SILPH_CO_11F
	ret nz
;>     if tile != 0x5E: return
	ld a, b
	cp $5e
	ret nz
.cardKeyDoorInFrontOfPlayer
;> if IsItemInBag(CARD_KEY):                    # zero: no Card Key
;>@fail     hTextID = (CardKeyFailText_id - TextPredefs) // 2 + 1
;>@failtext     PrintPredefTextID(hTextID)
;>@failret     return
	ld b, CARD_KEY
	call IsItemInBag
	jr z, .noCardKey
;> y, x = GetCoordsInFrontOfPlayer()
	call GetCoordsInFrontOfPlayer
	push de
;> hTextID = (CardKeySuccessText_id - TextPredefs) // 2 + 1
	ld a, (CardKeySuccessText_id - TextPredefs) / 2 + 1
	ldh [hTextID], a
;> PrintPredefTextID(hTextID)
	call PrintPredefTextID
	pop de
;> wCardKeyDoorY = y >> 1                       # in blocks
	srl d
	ld a, d
	ld b, a
	ld [wCardKeyDoorY], a
;> wCardKeyDoorX = x >> 1
	srl e
	ld a, e
	ld c, a
	ld [wCardKeyDoorX], a
;>@floor floor = 0x03 if wCurMap == SILPH_CO_11F else 0x0E     # the open door's block
	ld a, [wCurMap]
	cp SILPH_CO_11F
	jr nz, .notSilphCo11F
	ld a, $3
	jr .replaceCardKeyDoorTileBlock
.notSilphCo11F
;=@floor
	ld a, $e
.replaceCardKeyDoorTileBlock
;> wNewTileBlockID = floor
	ld [wNewTileBlockID], a
;> ReplaceTileBlock()                           # a predef, at (wCardKeyDoorY, wCardKeyDoorX)
	ld a, (ReplaceTileBlockPredef - PredefPointers) / 3
	call Predef
;> wCurrentMapScriptFlags = wCurrentMapScriptFlags | 1 << BIT_CUR_MAP_LOADED_1
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_1, [hl]
;> PlaySound(SFX_GO_INSIDE)
	ld a, SFX_GO_INSIDE
	jp PlaySound
.noCardKey
;=@fail
	ld a, (CardKeyFailText_id - TextPredefs) / 2 + 1
	ldh [hTextID], a
;=@failtext
	jp PrintPredefTextID

;@ path: engine/events/card_key
SilphCoMapList:
	db SILPH_CO_2F
	db SILPH_CO_3F
	db SILPH_CO_4F
	db SILPH_CO_5F
	db SILPH_CO_6F
	db SILPH_CO_7F
	db SILPH_CO_8F
	db SILPH_CO_9F
	db SILPH_CO_10F
	db SILPH_CO_11F
	db -1 ; end

;@ path: engine/events/card_key
CardKeySuccessText::
	db TX_FAR
	dw _CardKeySuccessText1
	db BANK(_CardKeySuccessText1)
	db TX_SOUND_GET_ITEM_1
	db TX_FAR
	dw _CardKeySuccessText2
	db BANK(_CardKeySuccessText2)
	db TX_END

;@ path: engine/events/card_key
CardKeyFailText::
	db TX_FAR
	dw _CardKeyFailText
	db BANK(_CardKeyFailText)
	db TX_END

; d = Y
; e = X
;@ path: engine/events/card_key
;@ def GetCoordsInFrontOfPlayer() -> (d, e)
;@ The (y, x) step coordinates of the tile the player faces.
;@ test: mem[0xC109] = 4 * rand(0, 3)
GetCoordsInFrontOfPlayer:
;> facing = mem[wSpritePlayerStateData1FacingDirection]
	ld a, [wYCoord]
	ld d, a
	ld a, [wXCoord]
	ld e, a
	ld a, [wSpritePlayerStateData1FacingDirection]
;> if facing == SPRITE_FACING_DOWN:
	and a
	jr nz, .notFacingDown
; facing down
;>     return u8(wYCoord + 1), wXCoord
	inc d
	ret
.notFacingDown
;> if facing == SPRITE_FACING_UP:
	cp SPRITE_FACING_UP
	jr nz, .notFacingUp
; facing up
;>     return u8(wYCoord - 1), wXCoord
	dec d
	ret
.notFacingUp
;> if facing == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr nz, .notFacingLeft
; facing left
;>     return wYCoord, u8(wXCoord - 1)
	dec e
	ret
.notFacingLeft
; facing right
;> return wYCoord, u8(wXCoord + 1)
	inc e
	ret
;@ path: engine/events/prize_menu
;@ def CeladonPrizeMenu()
;@ A Game Corner prize counter (with the Coin Case only): the player's coins, the three prizes of this
;@ counter with their prices, and NO THANKS.
;@ test: skip shows a menu
CeladonPrizeMenu::
;> if IsItemInBag(COIN_CASE):                   # zero: no Coin Case
	ld b, COIN_CASE
	call IsItemInBag
	jr nz, .havingCoinCase
;>     PrintText(RequireCoinCaseText)
;>@noret     return
	ld hl, RequireCoinCaseText
	jp PrintText
.havingCoinCase
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> PrintText(ExchangeCoinsForPrizesText)
	ld hl, ExchangeCoinsForPrizesText
	call PrintText
; the following are the menu settings
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 3
	ld a, $03
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 4
	ld a, $04
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, $01
	ld [wTopMenuItemX], a
;> PrintPrizePrice()
	call PrintPrizePrice
;> TextBoxBorder(coord(0, 2), 8, 16)
	ld hl, (2) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 8
	ld c, 16
	call TextBoxBorder
;> GetPrizeMenuId()
	call GetPrizeMenuId
;> UpdateSprites()
	call UpdateSprites
;> PrintText(WhichPrizeText)
	ld hl, WhichPrizeText
	call PrintText
;> if not HandleMenuInput() & (1 << B_PAD_B) and wCurrentMenuItem != 3:    # 3: NO THANKS
	call HandleMenuInput ; menu choice handler
	bit B_PAD_B, a
	jr nz, .noChoice
	ld a, [wCurrentMenuItem]
	cp 3 ; "NO,THANKS" choice
	jr z, .noChoice
;>     HandlePrizeChoice()
	call HandlePrizeChoice
.noChoice
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
	ret

;@ path: engine/events/prize_menu
RequireCoinCaseText:
	db TX_FAR
	dw _RequireCoinCaseText
	db BANK(_RequireCoinCaseText)
	db TX_WAIT_BUTTON
	db TX_END

;@ path: engine/events/prize_menu
ExchangeCoinsForPrizesText:
	db TX_FAR
	dw _ExchangeCoinsForPrizesText
	db BANK(_ExchangeCoinsForPrizesText)
	db TX_END

;@ path: engine/events/prize_menu
WhichPrizeText:
	db TX_FAR
	dw _WhichPrizeText
	db BANK(_WhichPrizeText)
	db TX_END

;@ path: engine/events/prize_menu
;@ def GetPrizeMenuId()
;@ Which prize counter is this (from the text ID)? Load its three prizes and BCD prices from
;@ PrizeDifferentMenuPtrs and draw the menu: TM names at the third counter, Pokémon names at the others.
GetPrizeMenuId:
; determine which one among the three prize texts has been selected using the text ID (stored in [hTextID])
; prize texts' IDs are TEXT_GAMECORNERPRIZEROOM_PRIZE_VENDOR_1-TEXT_GAMECORNERPRIZEROOM_PRIZE_VENDOR_3
; load the three prizes at wPrize1-wPrice3
; load the three prices at wPrize1Price-wPrize3Price
; display the three prizes' names, distinguishing between Pokemon names and item names (specifically TMs)
;> wWhichPrizeWindow = u8(hTextID - TEXT_GAMECORNERPRIZEROOM_PRIZE_VENDOR_1)
	ldh a, [hTextID]
	sub TEXT_GAMECORNERPRIZEROOM_PRIZE_VENDOR_1
	ld [wWhichPrizeWindow], a ; prize texts' relative ID (i.e. 0-2)
;> p = PrizeDifferentMenuPtrs + u8(4 * wWhichPrizeWindow)
	add a
	add a
	ld d, 0
	ld e, a
	ld hl, PrizeDifferentMenuPtrs
	add hl, de
;> names = mem16[p]                             # the three prizes
	ld a, [hli]
	ld d, [hl]
	ld e, a
	inc hl
;> CopyString(names, addr(wPrize1))
	push hl
	ld hl, wPrize1
	call CopyString
	pop hl
;> CopyData(mem16[p + 2], addr(wPrize1Price), 6)
	ld a, [hli]
	ld h, [hl]
	ld l, a
	ld de, wPrize1Price
	ld bc, 6
	call CopyData
;> if wWhichPrizeWindow == 2:                   # the TM counter: item names
	ld a, [wWhichPrizeWindow]
	cp 2 ; is TM_menu?
	jr nz, .putMonName
;>     wNamedObjectIndex = wPrize1
	ld a, [wPrize1]
	ld [wNamedObjectIndex], a
;>     PlaceString(GetItemName(), coord(2, 4))
	call GetItemName
	ld hl, (4) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
;>     wNamedObjectIndex = wPrize2
	ld a, [wPrize2]
	ld [wNamedObjectIndex], a
;>     PlaceString(GetItemName(), coord(2, 6))
	call GetItemName
	ld hl, (6) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
;>     wNamedObjectIndex = wPrize3
	ld a, [wPrize3]
	ld [wNamedObjectIndex], a
;>     PlaceString(GetItemName(), coord(2, 8))
	call GetItemName
	ld hl, (8) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
	jr .putNoThanksText
.putMonName
;> else:                                        # Pokémon names
;>     wNamedObjectIndex = wPrize1
	ld a, [wPrize1]
	ld [wNamedObjectIndex], a
;>     PlaceString(GetMonName(), coord(2, 4))
	call GetMonName
	ld hl, (4) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
;>     wNamedObjectIndex = wPrize2
	ld a, [wPrize2]
	ld [wNamedObjectIndex], a
;>     PlaceString(GetMonName(), coord(2, 6))
	call GetMonName
	ld hl, (6) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
;>     wNamedObjectIndex = wPrize3
	ld a, [wPrize3]
	ld [wNamedObjectIndex], a
;>     PlaceString(GetMonName(), coord(2, 8))
	call GetMonName
	ld hl, (8) * SCREEN_WIDTH + (2) + wTileMap
	call PlaceString
.putNoThanksText
;> PlaceString(NoThanksText, coord(2, 10))
	ld hl, (10) * SCREEN_WIDTH + (2) + wTileMap
	ld de, NoThanksText
	call PlaceString
; put prices on the right side of the textbox
;> PrintBCDNumber(addr(wPrize1Price), coord(13, 5), 2 | LEADING_ZEROES)
	ld de, wPrize1Price
	ld hl, (5) * SCREEN_WIDTH + (13) + wTileMap
	ld c, 2 | LEADING_ZEROES
	call PrintBCDNumber
;> PrintBCDNumber(addr(wPrize2Price), coord(13, 7), 2 | LEADING_ZEROES)
	ld de, wPrize2Price
	ld hl, (7) * SCREEN_WIDTH + (13) + wTileMap
	ld c, 2 | LEADING_ZEROES
	call PrintBCDNumber
;> PrintBCDNumber(addr(wPrize3Price), coord(13, 9), 2 | LEADING_ZEROES)
	ld de, wPrize3Price
	ld hl, (9) * SCREEN_WIDTH + (13) + wTileMap
	ld c, 2 | LEADING_ZEROES
	jp PrintBCDNumber

