;@ path: engine/events/prize_menu
;@ def LoadCoinsToSubtract()
;@ The chosen prize's price into hCoins.
;@ test: wWhichPrize = rand(0, 2)
LoadCoinsToSubtract:
;> p = addr(wPrize1Price) + u8(2 * wWhichPrize)
	ld a, [wWhichPrize]
	add a
	ld d, 0
	ld e, a
	ld hl, wPrize1Price
	add hl, de ; get selected prize's price
;> hUnusedCoinsByte = 0
	xor a
	ldh [hUnusedCoinsByte], a
;> hCoins[0] = mem[p]
	ld a, [hli]
	ldh [hCoins], a
;> hCoins[1] = mem[p + 1]
	ld a, [hl]
	ldh [hCoins + 1], a
	ret

;@ path: engine/events/prize_menu
;@ def HandlePrizeChoice()
;@ "So, you want <PRIZE>?" On YES with enough coins: a TM goes into the bag, a Pokémon (at its prize level) to
;@ the party or a box; then the coins are paid. Otherwise an apology.
;@ test: skip asks the player a question
HandlePrizeChoice:
;> wWhichPrize = wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ld [wWhichPrize], a
;> wNamedObjectIndex = mem[addr(wPrize1) + wCurrentMenuItem]
	ld d, 0
	ld e, a
	ld hl, wPrize1
	add hl, de
	ld a, [hl]
	ld [wNamedObjectIndex], a
;> if wWhichPrizeWindow == 2:                   # TMs
	ld a, [wWhichPrizeWindow]
	cp 2 ; is prize a TM?
	jr nz, .getMonName
;>     GetItemName()
	call GetItemName
	jr .givePrize
.getMonName
;> else:
;>     GetMonName()
	call GetMonName
.givePrize
;> PrintText(SoYouWantPrizeText)
	ld hl, SoYouWantPrizeText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:                         # NO
;>@fine     PrintText(OhFineThenText)
;>@fineret     return
	ld a, [wCurrentMenuItem] ; yes/no answer (Y=0, N=1)
	and a
	jr nz, .printOhFineThen
;> LoadCoinsToSubtract()
	call LoadCoinsToSubtract
;> notEnough, _ = HasEnoughCoins()
	call HasEnoughCoins
;> if notEnough:
;>@poor     PrintText(SorryNeedMoreCoinsText)
;>@poorret     return
	jr c, .notEnoughCoins
;> if wWhichPrizeWindow == 2:
	ld a, [wWhichPrizeWindow]
	cp 2 ; is prize a TM?
	jr nz, .giveMon
;>     given = GiveItem(wNamedObjectIndex, 1)
	ld a, [wNamedObjectIndex]
	ld b, a
	ld a, 1
	ld c, a
	call GiveItem
;>     if not given:
;>@full         PrintText(PrizeRoomBagIsFullText)
;>@fullret         return
	jr nc, .bagFull
	jr .subtractCoins
.giveMon
;> else:
;>     wCurPartySpecies = wNamedObjectIndex
	ld a, [wNamedObjectIndex]
	ld [wCurPartySpecies], a
;>     given = GivePokemon(wNamedObjectIndex, GetPrizeMonLevel())
	push af
	call GetPrizeMonLevel
	ld c, a
	pop af
	ld b, a
	call GivePokemon

; If either the party or box was full, wait after displaying message.
;>     if not wAddedToParty:                    # party or box full: wait after the message
;>         WaitForTextScrollButtonPress()
	push af
	ld a, [wAddedToParty]
	and a
	call z, WaitForTextScrollButtonPress
	pop af

; If the mon couldn't be given to the player (because both the party and box
; were full), return without subtracting coins.
;>     if not given:
;>         return
	ret nc

.subtractCoins
;> LoadCoinsToSubtract()
	call LoadCoinsToSubtract
;> SubBCD(addr(wPlayerCoins) + 1, addr(hCoins) + 1, 2)     # through SubBCDPredef
	ld hl, hCoins + 1
	ld de, wPlayerCoins + 1
	ld c, $02 ; how many bytes
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;> PrintPrizePrice()
	jp PrintPrizePrice
.bagFull
;=@full
	ld hl, PrizeRoomBagIsFullText
	jp PrintText
.notEnoughCoins
;=@poor
	ld hl, SorryNeedMoreCoinsText
	jp PrintText
.printOhFineThen
;=@fine
	ld hl, OhFineThenText
	jp PrintText

