;@ path: engine/events/prize_menu
;@ def GetPrizeMonLevel() -> a
;@ The level of prize Pokémon wCurPartySpecies, from PrizeMonLevelDictionary (species, level); also stored in
;@ wCurEnemyLevel.
;@ test: wCurPartySpecies = [ABRA, CLEFAIRY, PORYGON][rand(0, 2)]
GetPrizeMonLevel:
;> p = PrizeMonLevelDictionary
	ld a, [wCurPartySpecies]
	ld b, a
	ld hl, PrizeMonLevelDictionary
.loop
;> while mem[p] != wCurPartySpecies:
;>     p += 2
	ld a, [hli]
	cp b
	jr z, .matchFound
	inc hl
	jr .loop
.matchFound
;> wCurEnemyLevel = mem[p + 1]
	ld a, [hl]
	ld [wCurEnemyLevel], a
;> return wCurEnemyLevel
	ret

