SECTION "Battle Engine 9", ROMX

;@ path: engine/battle/experience
;@ def GainExperience()
;@ After the opponent faints, every party Pokémon that took part (and has HP) gains stat experience (the enemy's
;@ base stats) and experience: base experience * level / 7, split between the participants, x1.5 for traded
;@ Pokémon and again x1.5 in trainer battles, capped at the level 100 amount. Pokémon that level up get new
;@ stats (the battling one also in battle), the "grew to level" box, new moves, and are marked to evolve.
GainExperience:
;> if wLinkState == LINK_STATE_BATTLING:
;>     return
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	ret z ; return if link battle
;> DivideExpDataByNumMonsGainingExp()
	call DivideExpDataByNumMonsGainingExp
;> mon = wPartyMon1
	ld hl, wPartyMon1
;> wWhichPokemon = 0
	xor a
	ld [wWhichPokemon], a
.partyMonLoop ; loop over each mon and add gained exp
;>@loop for wWhichPokemon in range(wPartyCount):        # each party Pokémon
;>@mon     mon = wPartyMon1 + wWhichPokemon * PARTYMON_STRUCT_LENGTH
;>     hp = mem[mon + MON_HP] | mem[mon + MON_HP + 1]
	inc hl
	ld a, [hli]
	or [hl] ; is mon's HP 0?
;>     if not hp:
;>         continue
	jp z, .nextMon ; if so, go to next mon
;>     flag = FLAG_TEST << 8 | wWhichPokemon
	push hl
	ld hl, wPartyGainExpFlags
	ld a, [wWhichPokemon]
	ld c, a
	ld b, FLAG_TEST
;>     took_part = predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=flag)
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;>     if not took_part:
;>         continue
	ld a, c
	and a ; is mon's gain exp flag set?
	pop hl
	jp z, .nextMon ; if mon's gain exp flag not set, go to next mon
;>     stat_exp = mon + MON_HP_EXP + 1              # the low byte of the first one
	ld de, (MON_HP_EXP + 1) - (MON_HP + 1)
	add hl, de
	ld d, h
	ld e, l
;>@st     for i in range(NUM_STATS):                  # stat experience: + the enemy's base stats
	ld hl, wEnemyMonBaseStats
	ld c, NUM_STATS
.gainStatExpLoop
;>         low = mem[stat_exp + 2 * i] + wEnemyMonBaseStats[i]
;>         mem[stat_exp + 2 * i] = low & 0xFF
	ld a, [hli]
	ld b, a ; enemy mon base stat
	ld a, [de] ; stat exp
	add b ; add enemy mon base state to stat exp
	ld [de], a
;>         if low > 0xFF:
	jr nc, .nextBaseStat
; if there was a carry, increment the upper byte
;>             high = mem[stat_exp + 2 * i - 1] + 1 & 0xFF
	dec de
	ld a, [de]
	inc a
;>             if high:
	jr z, .maxStatExp ; jump if the value overflowed
;>                 mem[stat_exp + 2 * i - 1] = high
	ld [de], a
	inc de
	jr .nextBaseStat
.maxStatExp ; if the upper byte also overflowed, then we have hit the max stat exp
;>             else:                                 # at the top: 0xFFFF
;>                 mem[stat_exp + 2 * i - 1] = mem[stat_exp + 2 * i] = 0xFF
	ld a, $ff
	ld [de], a
	inc de
	ld [de], a
.nextBaseStat
;=@st
	dec c
	jr z, .statExpDone
	inc de
	inc de
	jr .gainStatExpLoop
.statExpDone
;>     hMultiplicand[0:3] = [0, 0, wEnemyMonBaseExp]   # experience: base experience * level / 7
	xor a
	ldh [hMultiplicand], a
	ldh [hMultiplicand + 1], a
	ld a, [wEnemyMonBaseExp]
	ldh [hMultiplicand + 2], a
;>     hMultiplier = mem[wEnemyMonLevel]
;>     Multiply()
	ld a, [wEnemyMonLevel]
	ldh [hMultiplier], a
	call Multiply
;>     hDivisor = 7
;>     Divide(4)
	ld a, 7
	ldh [hDivisor], a
	ld b, 4
	call Divide
;>     ot = mon + MON_OTID
	ld hl, MON_OTID - (MON_DVS - 1)
	add hl, de
;>     traded = mem[ot] != wPlayerID[0]
	ld b, [hl] ; wPartyMon*OTID
	inc hl
	ld a, [wPlayerID]
	cp b
	jr nz, .tradedMon
;>     if not traded:
;>         traded = mem[ot + 1] != wPlayerID[1]
	ld b, [hl]
	ld a, [wPlayerID + 1]
	cp b
	ld a, 0
	jr z, .next
.tradedMon
;>     if traded:                                    # x1.5 for a traded Pokémon
;>         BoostExp()
	call BoostExp ; traded mon exp boost
	ld a, 1
.next
;>     wGainBoostedExp = 1 if traded else 0
	ld [wGainBoostedExp], a
;>     if wIsInBattle != 1:                          # and x1.5 in trainer battles
;>         BoostExp()
	ld a, [wIsInBattle]
	dec a ; is it a trainer battle?
	call nz, BoostExp ; if so, boost exp
;>     exp = mon + MON_EXP
	inc hl
	inc hl
	inc hl
; add the gained exp to the party mon's exp
;>     wExpAmountGained[1] = hQuotient[3]
	ld b, [hl]
	ldh a, [hQuotient + 3]
	ld [wExpAmountGained + 1], a
;>     total = (mem[exp] << 16 | mem[exp + 1] << 8 | mem[exp + 2]) + (hQuotient[2] << 8 | hQuotient[3])
;>     mem[exp + 2] = total & 0xFF
	add b
	ld [hld], a
;>     wExpAmountGained[0] = hQuotient[2]
	ld b, [hl]
	ldh a, [hQuotient + 2]
	ld [wExpAmountGained], a
;>     mem[exp + 1] = total >> 8 & 0xFF
	adc b
	ld [hl], a
;>     mem[exp] = total >> 16 & 0xFF
	jr nc, .noCarry
	dec hl
	inc [hl]
	inc hl
.noCarry
; calculate exp for the mon at max level, and cap the exp at that value
;>     i = wWhichPokemon
	inc hl
	push hl
	ld a, [wWhichPokemon]
	ld c, a
	ld b, 0
;>     wCurSpecies = wPartySpecies[i]
	ld hl, wPartySpecies
	add hl, bc
	ld a, [hl]
	ld [wCurSpecies], a
;>     GetMonHeader()
	call GetMonHeader
;>     CalcExperience(MAX_LEVEL)                     # the amount at level 100
	ld d, MAX_LEVEL
	; get max exp
	ld hl, CalcExperience
	ld b, BANK(CalcExperience)
	call Bankswitch
; compare max exp with current exp
;>     top = hExperience[0] << 16 | hExperience[1] << 8 | hExperience[2]
	ldh a, [hExperience]
	ld b, a
	ldh a, [hExperience + 1]
	ld c, a
	ldh a, [hExperience + 2]
	ld d, a
;>     low = mem[exp + 2] - (top & 0xFF)
	pop hl
	ld a, [hld]
	sub d
;>     if total & 0xFFFFFF >= top:                   # at most that
	ld a, [hld]
	sbc c
	ld a, [hl]
	sbc b
	jr c, .next2
; the mon's exp is greater than the max exp, so overwrite it with the max exp
;>         mem[exp] = top >> 16
	ld a, b
	ld [hli], a
;>         mem[exp + 1] = top >> 8 & 0xFF
	ld a, c
	ld [hli], a
;>         mem[exp + 2] = top & 0xFF
	ld a, d
	ld [hld], a
	dec hl
.next2
;>     GetPartyMonName(wWhichPokemon, wPartyMonNicks)
	push hl
	ld a, [wWhichPokemon]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;>     PrintText(GainedText)
	ld hl, GainedText
	call PrintText
;>     wMonDataLocation = 0                          # PLAYER_PARTY_DATA
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;>     LoadMonData()
	call LoadMonData
	pop hl
;>     level_at = mon + MON_LEVEL
	ld bc, MON_LEVEL - MON_EXP
	add hl, bc
	push hl
;>     level = CalcLevelFromExperience()
	ld b, BANK(CalcLevelFromExperience)
	ld hl, CalcLevelFromExperience
	call Bankswitch
	pop hl
;>     if level == mem[level_at]:
;>         continue
	ld a, [hl] ; current level
	cp d
	jp z, .nextMon ; if level didn't change, go to next mon
;>     saved = wCurEnemyLevel                        # it grew a level
	ld a, [wCurEnemyLevel]
	push af
	push hl
;>     wCurEnemyLevel = level
	ld a, d
	ld [wCurEnemyLevel], a
;>     mem[level_at] = level
	ld [hl], a
;>     species = mem[mon + MON_SPECIES]
	ld bc, MON_SPECIES - MON_LEVEL
	add hl, bc
	ld a, [hl]
;>     wCurSpecies = wPokedexNum = species
	ld [wCurSpecies], a
	ld [wPokedexNum], a
;>     GetMonHeader()
	call GetMonHeader
;>     max_at = mon + MON_MAXHP
	ld bc, (MON_MAXHP + 1) - MON_SPECIES
	add hl, bc
	push hl
;>     old_max = mem[max_at] << 8 | mem[max_at + 1]
	ld a, [hld]
	ld c, a
	ld b, [hl]
	push bc ; push max HP (from before levelling up)
;>     CalcStats(mon + MON_HP_EXP - 1, max_at, 1)    # with the stat experience
	ld d, h
	ld e, l
	ld bc, (MON_HP_EXP - 1) - MON_MAXHP
	add hl, bc
	ld b, $1 ; consider stat exp when calculating stats
	call CalcStats
;>     low = mem[max_at + 1] - (old_max & 0xFF)
	pop bc ; pop max HP (from before levelling up)
	pop hl
	ld a, [hld]
	sub c
	ld c, a
;>     gain = (mem[max_at] << 8 | mem[max_at + 1]) - old_max
	ld a, [hl]
	sbc b
	ld b, a ; bc = difference between old max HP and new max HP after levelling
;>     hp_at = mon + MON_HP
	ld de, (MON_HP + 1) - MON_MAXHP
	add hl, de
; add to the current HP the amount of max HP gained when levelling
;>     hp = (mem[hp_at] << 8 | mem[hp_at + 1]) + gain   # the HP go up by as much as the maximum
;>     mem[hp_at + 1] = hp & 0xFF
	ld a, [hl] ; wPartyMon*HP + 1
	add c
	ld [hld], a
;>     mem[hp_at] = hp >> 8 & 0xFF
	ld a, [hl] ; wPartyMon*HP + 1
	adc b
	ld [hl], a ; wPartyMon*HP
;>     if wWhichPokemon == wPlayerMonNumber:         # the Pokémon in battle
	ld a, [wPlayerMonNumber]
	ld b, a
	ld a, [wWhichPokemon]
	cp b ; is the current mon in battle?
	jr nz, .printGrewLevelText
; current mon is in battle
;>         mem[wBattleMonHP] = mem[hp_at]
	ld de, wBattleMonHP
; copy party mon HP to battle mon HP
	ld a, [hli]
	ld [de], a
	inc de
;>         mem[wBattleMonHP + 1] = mem[hp_at + 1]
	ld a, [hl]
	ld [de], a
; copy other stats from party mon to battle mon
;>         src = level_at
	ld bc, MON_LEVEL - (MON_HP + 1)
	add hl, bc
	push hl
;>         CopyData(src, wBattleMonLevel, 1 + NUM_STATS * 2)
	ld de, wBattleMonLevel
	ld bc, 1 + NUM_STATS * 2 ; size of stats
	call CopyData
	pop hl
;>         if not wPlayerBattleStatus3 >> TRANSFORMED & 1:
	ld a, [wPlayerBattleStatus3]
	bit TRANSFORMED, a
	jr nz, .recalcStatChanges
; the mon is not transformed, so update the unmodified stats
;>             CopyData(src, addr(wPlayerMonUnmodifiedLevel), 1 + NUM_STATS * 2)
	ld de, wPlayerMonUnmodifiedLevel
	ld bc, 1 + NUM_STATS * 2
	call CopyData
.recalcStatChanges
;>         wCalculateWhoseStats = 0
	xor a ; battle mon
	ld [wCalculateWhoseStats], a
;>         farcall(CalculateModifiedStats)
	ld hl, CalculateModifiedStats
	ld b, BANK(CalculateModifiedStats)
	call Bankswitch
;>         farcall(ApplyBurnAndParalysisPenaltiesToPlayer)
	ld hl, ApplyBurnAndParalysisPenaltiesToPlayer
	ld b, BANK(ApplyBurnAndParalysisPenaltiesToPlayer)
	call Bankswitch
;>         farcall(ApplyBadgeStatBoosts)
	ld hl, ApplyBadgeStatBoosts
	ld b, BANK(ApplyBadgeStatBoosts)
	call Bankswitch
;>         farcall(DrawPlayerHUDAndHPBar)
	ld hl, DrawPlayerHUDAndHPBar
	ld b, BANK(DrawPlayerHUDAndHPBar)
	call Bankswitch
;>         farcall(PrintEmptyString)
	ld hl, PrintEmptyString
	ld b, BANK(PrintEmptyString)
	call Bankswitch
;>         SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
.printGrewLevelText
;>     PrintText(GrewLevelText)
	ld hl, GrewLevelText
	call PrintText
;>     wMonDataLocation = 0
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;>     LoadMonData()
	call LoadMonData
;>     PrintStatsBox(LEVEL_UP_STATS_BOX)
	ld d, LEVEL_UP_STATS_BOX
	ld hl, PrintStatsBox
	ld b, BANK(PrintStatsBox)
	call Bankswitch
;>     WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;>     LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;>     wMonDataLocation = 0
	xor a ; PLAYER_PARTY_DATA
	ld [wMonDataLocation], a
;>     wPokedexNum = wCurSpecies
	ld a, [wCurSpecies]
	ld [wPokedexNum], a
;>     predef(LearnMoveFromLevelUp)
	ld a, (LearnMoveFromLevelUpPredef - PredefPointers) / 3
	call Predef
;>     flag = FLAG_SET << 8 | wWhichPokemon
	ld hl, wCanEvolveFlags
	ld a, [wWhichPokemon]
	ld c, a
	ld b, FLAG_SET
;>     predef(FlagActionPredef, hl=wCanEvolveFlags, bc=flag)   # it may evolve after the battle
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;>     wCurEnemyLevel = saved
	pop hl
	pop af
	ld [wCurEnemyLevel], a

.nextMon
;=@loop
	ld a, [wPartyCount]
	ld b, a
	ld a, [wWhichPokemon]
	inc a
	cp b
	jr z, .done
;=@mon
	ld [wWhichPokemon], a
	ld bc, PARTYMON_STRUCT_LENGTH
	ld hl, wPartyMon1
	call AddNTimes
	jp .partyMonLoop
.done
;> wPartyGainExpFlags = 0                            # from now on only the Pokémon that is out
	ld hl, wPartyGainExpFlags
	xor a
	ld [hl], a ; clear gain exp flags
;> flag = FLAG_SET << 8 | wPlayerMonNumber
	ld a, [wPlayerMonNumber]
	ld c, a
	ld b, FLAG_SET
	push bc
	; set the gain exp flag for the mon that is currently out
;> predef(FlagActionPredef, hl=wPartyGainExpFlags, bc=flag)
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> wPartyFoughtCurrentEnemyFlags = 0
	ld hl, wPartyFoughtCurrentEnemyFlags
	xor a
	ld [hl], a
;> predef(FlagActionPredef, hl=wPartyFoughtCurrentEnemyFlags, bc=flag)
	pop bc
	; set the fought current enemy flag for the mon that is currently out
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	jp Predef

; divide enemy base stats, catch rate, and base exp by the number of mons gaining exp
;@ path: engine/battle/experience
;@ def DivideExpDataByNumMonsGainingExp()
;@ When several Pokémon share the experience, divide the enemy's base stats and base experience (the numbers they
;@ gain from) by their count.
;@ test: hLoadedROMBank = 0x15
DivideExpDataByNumMonsGainingExp:
;> flags = wPartyGainExpFlags
	ld a, [wPartyGainExpFlags]
	ld b, a
	xor a
;> n = 0
;>@cnt for _ in range(8):                             # count the Pokémon that gain experience
	ld c, $8
	ld d, $0
.countSetBitsLoop ; loop to count set bits in wPartyGainExpFlags
;>     n += flags & 1
;>     flags >>= 1
	xor a
	srl b
	adc d
	ld d, a
;=@cnt
	dec c
	jr nz, .countSetBitsLoop
;> if n < 2:
;>     return
	cp $2
	ret c ; return if only one mon is gaining exp
;> wTempByteValue = n
	ld [wTempByteValue], a ; store number of mons gaining exp
;> for i in range(addr(wEnemyMonBaseExp) + 1 - addr(wEnemyMonBaseStats)):
	ld hl, wEnemyMonBaseStats
	ld c, wEnemyMonBaseExp + 1 - wEnemyMonBaseStats
.divideLoop
;>     hDividend[0] = 0
	xor a
	ldh [hDividend], a
;>     hDividend[1] = mem[wEnemyMonBaseStats + i]
	ld a, [hl]
	ldh [hDividend + 1], a
;>     hDivisor = n
	ld a, [wTempByteValue]
	ldh [hDivisor], a
;>     Divide(2)
	ld b, $2
	call Divide ; divide value by number of mons gaining exp
;>     mem[wEnemyMonBaseStats + i] = hQuotient[3]
	ldh a, [hQuotient + 3]
	ld [hli], a
	dec c
	jr nz, .divideLoop
	ret

; multiplies exp by 1.5
;@ path: engine/battle/experience
;@ def BoostExp()
;@ Multiply the experience in hQuotient (its low two bytes) by 1.5.
BoostExp:
;> q = hQuotient[2] << 8 | hQuotient[3]
	ldh a, [hQuotient + 2]
	ld b, a
	ldh a, [hQuotient + 3]
	ld c, a
;> half = q >> 1
	srl b
	rr c
;> q += half                                         # x1.5
;> hQuotient[2], hQuotient[3] = hi(q), lo(q)
	add c
	ldh [hQuotient + 3], a
	ldh a, [hQuotient + 2]
	adc b
	ldh [hQuotient + 2], a
	ret

;@ path: engine/battle/experience
;@ def GainedText() -> hl
;@ "<MON> gained" ... and then which ending: "with EXP.ALL,", "a boosted" or just the number of EXP. Points.
;@ test: skip a text script: the code after text_asm runs from the text engine
GainedText:
	db TX_FAR
	dw _GainedText
	db BANK(_GainedText)
	db TX_START_ASM
;> if wBoostExpByExpAll:
;>     return WithExpAllText
	ld a, [wBoostExpByExpAll]
	ld hl, WithExpAllText
	and a
	ret nz
;> text = ExpPointsText
	ld hl, ExpPointsText
;> if not wGainBoostedExp:
;>     return text
	ld a, [wGainBoostedExp]
	and a
	ret z
;> return BoostedText
	ld hl, BoostedText
	ret

;@ path: engine/battle/experience
;@ def WithExpAllText() -> hl
;@ "with EXP.ALL," then the number of EXP. Points.
;@ test: skip a text script: the code after text_asm runs from the text engine
WithExpAllText:
	db TX_FAR
	dw _WithExpAllText
	db BANK(_WithExpAllText)
	db TX_START_ASM
;> return ExpPointsText
	ld hl, ExpPointsText
	ret

;@ path: engine/battle/experience
BoostedText:
	db TX_FAR
	dw _BoostedText
	db BANK(_BoostedText)

;@ path: engine/battle/experience
ExpPointsText:
	db TX_FAR
	dw _ExpPointsText
	db BANK(_ExpPointsText)
	db TX_END

;@ path: engine/battle/experience
GrewLevelText:
	db TX_FAR
	dw _GrewLevelText
	db BANK(_GrewLevelText)
	db TX_SOUND_GET_ITEM_1
	db TX_END


SECTION "Diploma", ROMX

DEF CIRCLE_TILE_ID EQU $70

;@ path: engine/events/diploma
;@ def DisplayDiploma()
;@ The Game Freak diploma for a complete Pokédex: a framed certificate with its texts, the player's name and
;@ the player's picture (moved behind the frame's background), until a button is pressed.
DisplayDiploma::
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> DisableLCD()
	call DisableLCD
;> FarCopyData2(BANK(CircleTile), CircleTile, addr(vChars2) + CIRCLE_TILE_ID * TILE_SIZE, TILE_SIZE)
	ld hl, CircleTile
	ld de, vChars2 + TILE_SIZE * CIRCLE_TILE_ID
	ld bc, TILE_SIZE
	ld a, BANK(CircleTile)
	call FarCopyData2
;> Diploma_TextBoxBorder()                      # a predef: the frame at (0, 0), 16 x 18
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((16) & $ff) << 8 + ((18) & $ff)
	ld a, (Diploma_TextBoxBorderPredef - PredefPointers) / 3
	call Predef

;> p = DiplomaTextPointersAndCoords             # entries: text, screen address
	ld hl, DiplomaTextPointersAndCoords
;>@texts for _ in range(5):
	ld c, $5
.placeTextLoop
;>     text = mem16[p]
	push bc
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;>     dest = mem16[p + 2]
	ld a, [hli]
	push hl
	ld h, [hl]
	ld l, a
;>     PlaceString(text, dest)
	call PlaceString
;>     p += 4
	pop hl
	inc hl
;=@texts
	pop bc
	dec c
	jr nz, .placeTextLoop
;> PlaceString(addr(wPlayerName), coord(10, 4))
	ld hl, (4) * SCREEN_WIDTH + (10) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> DrawPlayerCharacter()                        # in another bank
	ld b, BANK(DrawPlayerCharacter)
	ld hl, DrawPlayerCharacter
	call Bankswitch

; Move the player 33 pixels right and set the priority bit so he appears
; behind the background layer.
;>@oam for i in range(0x28):                        # 33 pixels right, behind the background
	ld hl, wShadowOAMSprite00XCoord
	ld bc, (($80) & $ff) << 8 + (($28) & $ff)
.adjustPlayerGfxLoop
;>     o = addr(wShadowOAMSprite00XCoord) + 4 * i
;>     mem[o] = u8(mem[o] + 33)
	ld a, [hl] ; X
	add 33
	ld [hli], a
	inc hl
;>     mem[o + 2] = OAM_PRIO
	ld a, b
	ld [hli], a ; attributes
	inc hl
;=@oam
	dec c
	jr nz, .adjustPlayerGfxLoop

;> EnableLCD()
	call EnableLCD
;> LoadTrainerInfoTextBoxTiles()                # in another bank
	ld b, BANK(LoadTrainerInfoTextBoxTiles)
	ld hl, LoadTrainerInfoTextBoxTiles
	call Bankswitch
;> RunPaletteCommand(SET_PAL_GENERIC)
	ld b, SET_PAL_GENERIC
	call RunPaletteCommand
;> Delay3()
	call Delay3
;> GBPalNormal()
	call GBPalNormal
;> rOBP0 = 0x90
	ld a, $90
	ldh [rOBP0], a
;> WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;> Delay3()
	call Delay3
;> GBPalNormal()
	jp GBPalNormal

;@ path: engine/events/diploma
;@ def UnusedPlayerNameLengthFunc() -> bc
;@ Unused: minus the length of the player's name (bc = -length).
;@ test: mem[wPlayerName + rand(0, 10)] = 0x50
UnusedPlayerNameLengthFunc:
; Unused function that performs bc = -(player name's length)
; leftover from the JPN versions
;> c = 0
;> p = addr(wPlayerName)
	ld hl, wPlayerName
	ld bc, (($ff) & $ff) << 8 + (($00) & $ff)
.loop
;>@scan while mem[p] != charmap('@')[0]:
	ld a, [hli]
	cp '@'
;=@ret
	ret z
;>     c = u8(c - 1)
	dec c
;>@next     p += 1
;=@scan
	jr .loop
;>@ret return 0xFF00 | c


;@ path: engine/events/diploma
DiplomaTextPointersAndCoords:
	; x, y, text
	dw DiplomaText
	dw (2) * SCREEN_WIDTH + (5) + wTileMap
	dw DiplomaPlayer
	dw (4) * SCREEN_WIDTH + (3) + wTileMap
	dw DiplomaEmptyText
	dw (4) * SCREEN_WIDTH + (15) + wTileMap
	dw DiplomaCongrats
	dw (6) * SCREEN_WIDTH + (2) + wTileMap
	dw DiplomaGameFreak
	dw (16) * SCREEN_WIDTH + (9) + wTileMap

;@ path: engine/events/diploma
DiplomaText:
	db CIRCLE_TILE_ID, "Diploma", CIRCLE_TILE_ID, "@"

;@ path: engine/events/diploma
DiplomaPlayer:
	db "Player@"

;@ path: engine/events/diploma
DiplomaEmptyText:
	db "@"

;@ path: engine/events/diploma
DiplomaCongrats:
	db   "Congrats! This"
	db "<NEXT>", "diploma certifies"
	db "<NEXT>", "that you have"
	db "<NEXT>", "completed your"
	db "<NEXT>", "#DEX.@"

;@ path: engine/events/diploma
DiplomaGameFreak:
	db "GAME FREAK@"


SECTION "Trainer Sight", ROMX

;@ path: engine/overworld/trainer_sight
;@ def _GetSpritePosition1()
;@ Copy sprite wSpriteIndex's screen and map position to hSpriteScreenYCoord/XCoord and
;@ hSpriteMapYCoord/XCoord.
;@ test: wSpriteIndex = rand(0, 15)
_GetSpritePosition1::
;> hSpriteIndex = wSpriteIndex
;> s = GetSpriteDataPointer(addr(wSpriteStateData1), SPRITESTATEDATA1_YPIXELS)
	ld hl, wSpriteStateData1
	ld de, SPRITESTATEDATA1_YPIXELS
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
	call GetSpriteDataPointer
;> hSpriteScreenYCoord = mem[s]
	ld a, [hli] ; x#SPRITESTATEDATA1_YPIXELS
	ldh [hSpriteScreenYCoord], a
;> hSpriteScreenXCoord = mem[s + 2]
	inc hl
	ld a, [hl] ; x#SPRITESTATEDATA1_XPIXELS
	ldh [hSpriteScreenXCoord], a
;> m = s + 2 + wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	ld de, wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	add hl, de
;> hSpriteMapYCoord = mem[m]
	ld a, [hli] ; x#SPRITESTATEDATA2_MAPY
	ldh [hSpriteMapYCoord], a
;> hSpriteMapXCoord = mem[m + 1]
	ld a, [hl] ; x#SPRITESTATEDATA2_MAPX
	ldh [hSpriteMapXCoord], a
	ret

;@ path: engine/overworld/trainer_sight
;@ def _GetSpritePosition2()
;@ Save sprite wSpriteIndex's screen and map position in wSavedSpriteScreenY/X and wSavedSpriteMapY/X.
;@ test: wSpriteIndex = rand(0, 15)
_GetSpritePosition2::
;> hSpriteIndex = wSpriteIndex
;> s = GetSpriteDataPointer(addr(wSpriteStateData1), SPRITESTATEDATA1_YPIXELS)
	ld hl, wSpriteStateData1
	ld de, SPRITESTATEDATA1_YPIXELS
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
	call GetSpriteDataPointer
;> wSavedSpriteScreenY = mem[s]
	ld a, [hli] ; x#SPRITESTATEDATA1_YPIXELS
	ld [wSavedSpriteScreenY], a
;> wSavedSpriteScreenX = mem[s + 2]
	inc hl
	ld a, [hl] ; x#SPRITESTATEDATA1_XPIXELS
	ld [wSavedSpriteScreenX], a
;> m = s + 2 + wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	ld de, wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	add hl, de
;> wSavedSpriteMapY = mem[m]
	ld a, [hli] ; x#SPRITESTATEDATA2_MAPY
	ld [wSavedSpriteMapY], a
;> wSavedSpriteMapX = mem[m + 1]
	ld a, [hl] ; x#SPRITESTATEDATA2_MAPX
	ld [wSavedSpriteMapX], a
	ret

;@ path: engine/overworld/trainer_sight
;@ def _SetSpritePosition1()
;@ Move sprite wSpriteIndex to the screen and map position in hSpriteScreenYCoord/XCoord and
;@ hSpriteMapYCoord/XCoord.
;@ test: wSpriteIndex = rand(0, 15)
_SetSpritePosition1::
;> hSpriteIndex = wSpriteIndex
;> s = GetSpriteDataPointer(addr(wSpriteStateData1), SPRITESTATEDATA1_YPIXELS)
	ld hl, wSpriteStateData1
	ld de, SPRITESTATEDATA1_YPIXELS
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
	call GetSpriteDataPointer
;> mem[s] = hSpriteScreenYCoord
	ldh a, [hSpriteScreenYCoord] ; x#SPRITESTATEDATA1_YPIXELS
	ld [hli], a
;> mem[s + 2] = hSpriteScreenXCoord
	inc hl
	ldh a, [hSpriteScreenXCoord] ; x#SPRITESTATEDATA1_XPIXELS
	ld [hl], a
;> m = s + 2 + wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	ld de, wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	add hl, de
;> mem[m] = hSpriteMapYCoord
	ldh a, [hSpriteMapYCoord] ; x#SPRITESTATEDATA2_MAPY
	ld [hli], a
;> mem[m + 1] = hSpriteMapXCoord
	ldh a, [hSpriteMapXCoord] ; x#SPRITESTATEDATA2_MAPX
	ld [hl], a
	ret

;@ path: engine/overworld/trainer_sight
;@ def _SetSpritePosition2()
;@ Put sprite wSpriteIndex back at the position saved in wSavedSpriteScreenY/X and wSavedSpriteMapY/X.
;@ test: wSpriteIndex = rand(0, 15)
_SetSpritePosition2::
;> hSpriteIndex = wSpriteIndex
;> s = GetSpriteDataPointer(addr(wSpriteStateData1), SPRITESTATEDATA1_YPIXELS)
	ld hl, wSpriteStateData1
	ld de, SPRITESTATEDATA1_YPIXELS
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
	call GetSpriteDataPointer
;> mem[s] = wSavedSpriteScreenY
	ld a, [wSavedSpriteScreenY]
	ld [hli], a ; x#SPRITESTATEDATA1_YPIXELS
;> mem[s + 2] = wSavedSpriteScreenX
	inc hl
	ld a, [wSavedSpriteScreenX]
	ld [hl], a ; x#SPRITESTATEDATA1_XPIXELS
;> m = s + 2 + wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	ld de, wSpritePlayerStateData2MapY - wSpritePlayerStateData1XPixels
	add hl, de
;> mem[m] = wSavedSpriteMapY
	ld a, [wSavedSpriteMapY]
	ld [hli], a ; x#SPRITESTATEDATA2_MAPY
;> mem[m + 1] = wSavedSpriteMapX
	ld a, [wSavedSpriteMapX]
	ld [hl], a ; x#SPRITESTATEDATA2_MAPX
	ret

;@ path: engine/overworld/trainer_sight
;@ def TrainerWalkUpToPlayer()
;@ A trainer who spotted the player walks up to them: one step less than the distance in the direction the
;@ trainer faces (the player is always at screen position $3C, $40). Nothing to do when already next to
;@ the player.
;@ test: k = rand(1, 15); wSpriteIndex = k; wTrainerFacingDirection = 4 * rand(0, 3); mem[0xC104 + 16 * k] = 0x3C - 16 * rand(1, 4); mem[0xC106 + 16 * k] = 0x40 + 16 * rand(1, 4)
TrainerWalkUpToPlayer::
;> wTrainerSpriteOffset = swap(wSpriteIndex)
	ld a, [wSpriteIndex]
	swap a
	ld [wTrainerSpriteOffset], a
;> ReadTrainerScreenPosition()
	call ReadTrainerScreenPosition
;> facing = wTrainerFacingDirection
	ld a, [wTrainerFacingDirection]
;> if facing == SPRITE_FACING_DOWN:
	and a ; SPRITE_FACING_DOWN
	jr z, .facingDown
;=@up
	cp SPRITE_FACING_UP
	jr z, .facingUp
;=@right
	cp SPRITE_FACING_LEFT
	jr z, .facingLeft
	jr .facingRight
.facingDown
;>     distance, _ = CalcDifference(0x3C, wTrainerScreenY)    # the player is at y $3C
	ld a, [wTrainerScreenY]
	ld b, a
	ld a, $3c           ; (fixed) player screen Y pos
	call CalcDifference
;>     if distance == 0x10: return             # right next to the player
	cp $10              ; trainer is right above player
	ret z
;>     steps = u8(swap(distance) - 1)
	swap a
	dec a
	ld c, a             ; bc = steps yet to go to reach player
;>     direction = NPC_MOVEMENT_DOWN
	xor a ; NPC_MOVEMENT_DOWN
	ld b, a
	jr .writeWalkScript
.facingUp
;>@up elif facing == SPRITE_FACING_UP:
;>     distance, _ = CalcDifference(0x3C, wTrainerScreenY)
	ld a, [wTrainerScreenY]
	ld b, a
	ld a, $3c           ; (fixed) player screen Y pos
	call CalcDifference
;>     if distance == 0x10: return
	cp $10              ; trainer is right below player
	ret z
;>     steps = u8(swap(distance) - 1)
	swap a
	dec a
	ld c, a             ; bc = steps yet to go to reach player
	ld b, $0
;>     direction = NPC_MOVEMENT_UP
	ld a, NPC_MOVEMENT_UP
	jr .writeWalkScript
.facingRight
;>@right elif facing != SPRITE_FACING_LEFT:            # facing right; the player is at x $40
;>     distance, _ = CalcDifference(0x40, wTrainerScreenX)
	ld a, [wTrainerScreenX]
	ld b, a
	ld a, $40           ; (fixed) player screen X pos
	call CalcDifference
;>     if distance == 0x10: return
	cp $10              ; trainer is directly left of player
	ret z
;>     steps = u8(swap(distance) - 1)
	swap a
	dec a
	ld c, a             ; bc = steps yet to go to reach player
	ld b, $0
;>     direction = NPC_MOVEMENT_RIGHT
	ld a, NPC_MOVEMENT_RIGHT
	jr .writeWalkScript
.facingLeft
;> else:                                        # facing left
;>     distance, _ = CalcDifference(0x40, wTrainerScreenX)
	ld a, [wTrainerScreenX]
	ld b, a
	ld a, $40           ; (fixed) player screen X pos
	call CalcDifference
;>     if distance == 0x10: return
	cp $10              ; trainer is directly right of player
	ret z
;>     steps = u8(swap(distance) - 1)
	swap a
	dec a
	ld c, a             ; bc = steps yet to go to reach player
	ld b, $0
;>     direction = NPC_MOVEMENT_LEFT
	ld a, NPC_MOVEMENT_LEFT
.writeWalkScript
;> end = FillMemory(addr(wNPCMovementDirections2), steps, direction)
	ld hl, wNPCMovementDirections2
	ld de, wNPCMovementDirections2
	call FillMemory     ; write the necessary steps to reach player
;> mem[end] = 0xFF
	ld [hl], $ff        ; write end of list sentinel
;> hSpriteIndex = wSpriteIndex
	ld a, [wSpriteIndex]
	ldh [hSpriteIndex], a
;> MoveSprite_(addr(wNPCMovementDirections2))
	jp MoveSprite_

; input: de = offset within sprite entry
; output: hl = pointer to sprite data
;@ path: engine/overworld/trainer_sight
;@ def GetSpriteDataPointer(table: hl, field: de) -> hl
;@ Address of field `field` of sprite hSpriteIndex in sprite data table `table`.
;@ test: hSpriteIndex = rand(0, 15); table = 0xC100; field = rand(0, 15)
GetSpriteDataPointer:
;> p = table + field
	push de
	add hl, de
;> p += swap(hSpriteIndex)                      # 16 bytes per sprite
	ldh a, [hSpriteIndex]
	swap a
	ld d, $0
	ld e, a
	add hl, de
;> return p
	pop de
	ret

; tests if this trainer is in the right position to engage the player and do so if she is.
;@ path: engine/overworld/trainer_sight
;@ def TrainerEngage()
;@ Does the trainer at wTrainerSpriteOffset start a battle? It must be on screen, in line with the player,
;@ within its sight distance, looking at the player and not standing on them. Then the battle is set up and
;@ wTrainerSpriteOffset becomes $FF, otherwise 0.
;@ test: k = rand(1, 15); wTrainerSpriteOffset = 16 * k; mem[0xC104 + 16 * k] = [0x3C, rand(0, 255)][rand(0, 1)]; mem[0xC106 + 16 * k] = [0x40, rand(0, 255)][rand(0, 1)]
TrainerEngage:
;>@engaged engaged = False
;>@image image = mem[addr(wSpriteStateData1) + u8(wTrainerSpriteOffset + SPRITESTATEDATA1_IMAGEINDEX)]
;=@done
	push hl
	push de
;=@image
	ld a, [wTrainerSpriteOffset]
	add SPRITESTATEDATA1_IMAGEINDEX
	ld d, $0
	ld e, a
	ld hl, wSpriteStateData1
	add hl, de
;=@image
	ld a, [hl]             ; x#SPRITESTATEDATA1_IMAGEINDEX
;> if image != 0xFF:                            # on screen
	sub $ff
	jr nz, .spriteOnScreen ; test if sprite is on screen
	jp .noEngage
.spriteOnScreen
;>@facing     wTrainerFacingDirection = mem[addr(wSpriteStateData1) + u8(wTrainerSpriteOffset + SPRITESTATEDATA1_FACINGDIRECTION)]
	ld a, [wTrainerSpriteOffset]
	add SPRITESTATEDATA1_FACINGDIRECTION
	ld d, $0
	ld e, a
	ld hl, wSpriteStateData1
	add hl, de
;=@facing
	ld a, [hl]             ; x#SPRITESTATEDATA1_FACINGDIRECTION
	ld [wTrainerFacingDirection], a
;>     ReadTrainerScreenPosition()
	call ReadTrainerScreenPosition
;>     if wTrainerScreenY == 0x3C:              # in line: the player's row
	ld a, [wTrainerScreenY]          ; sprite screen Y pos
	ld b, a
	ld a, $3c
	cp b
	jr z, .linedUpY
;=@column
	ld a, [wTrainerScreenX]          ; sprite screen X pos
	ld b, a
	ld a, $40
	cp b
	jr z, .linedUpX
;=@nodist
	xor a
	jp .noEngage
.linedUpY
;>         distance, _ = CalcDifference(0x40, wTrainerScreenX)
	ld a, [wTrainerScreenX]        ; sprite screen X pos
	ld b, a
	ld a, $40            ; (fixed) player X position
	call CalcDifference  ; calc distance
;=@sees
	jr z, .noEngage      ; exact same position as player
	call CheckSpriteCanSeePlayer
	jr c, .engage
	xor a
	jr .noEngage
.linedUpX
;>@column     elif wTrainerScreenX == 0x40:            # or the player's column
;>         distance, _ = CalcDifference(0x3C, wTrainerScreenY)
	ld a, [wTrainerScreenY]        ; sprite screen Y pos
	ld b, a
	ld a, $3c            ; (fixed) player Y position
	call CalcDifference  ; calc distance
;>     else:
;>@nodist         distance = 0
;>@sees     if distance and CheckSpriteCanSeePlayer(distance):    # 0: standing on the player
;=@sees
	jr z, .noEngage      ; exact same position as player
	call CheckSpriteCanSeePlayer
	jr c, .engage
	xor a
	jp .noEngage
.engage
;>         CheckPlayerIsInFrontOfSprite()
	call CheckPlayerIsInFrontOfSprite
;>         if wTrainerSpriteOffset:              # looking at the player
	ld a, [wTrainerSpriteOffset]
	and a
	jr z, .noEngage
;>             wMiscFlags = wMiscFlags | 1 << BIT_SEEN_BY_TRAINER
	ld hl, wMiscFlags
	set BIT_SEEN_BY_TRAINER, [hl]
;>             EngageMapTrainer()
	call EngageMapTrainer
;>             engaged = True
	ld a, $ff
.noEngage
;> wTrainerSpriteOffset = 0xFF if engaged else 0
	ld [wTrainerSpriteOffset], a
;>@done return
	pop de
	pop hl
	ret

; reads trainer's Y position to wTrainerScreenY and X position to wTrainerScreenX
;@ path: engine/overworld/trainer_sight
;@ def ReadTrainerScreenPosition()
;@ Copy the screen position of the trainer at wTrainerSpriteOffset to wTrainerScreenY and wTrainerScreenX.
ReadTrainerScreenPosition:
;> p = addr(wSpriteStateData1) + u8(wTrainerSpriteOffset + SPRITESTATEDATA1_YPIXELS)
	ld a, [wTrainerSpriteOffset]
	add SPRITESTATEDATA1_YPIXELS
	ld d, $0
	ld e, a
	ld hl, wSpriteStateData1
	add hl, de
;> wTrainerScreenY = mem[p]
	ld a, [hl] ; x#SPRITESTATEDATA1_YPIXELS
	ld [wTrainerScreenY], a
;> p = addr(wSpriteStateData1) + u8(wTrainerSpriteOffset + SPRITESTATEDATA1_XPIXELS)
	ld a, [wTrainerSpriteOffset]
	add SPRITESTATEDATA1_XPIXELS
	ld d, $0
	ld e, a
	ld hl, wSpriteStateData1
	add hl, de
;> wTrainerScreenX = mem[p]
	ld a, [hl] ; x#SPRITESTATEDATA1_XPIXELS
	ld [wTrainerScreenX], a
	ret

; checks if the sprite is properly lined up with the player with respect to the direction it's looking. Also checks the distance between player and sprite
; note that this does not necessarily mean the sprite is seeing the player, he could be behind it's back
; a: distance player to sprite
;@ path: engine/overworld/trainer_sight
;@ def CheckSpriteCanSeePlayer(distance: a) -> carry
;@ Is the player within the trainer's sight distance and on the trainer's line of sight (same column when
;@ it faces up or down, same row when it faces left or right)? Whether it looks towards or away from the
;@ player is checked later.
CheckSpriteCanSeePlayer:
;> if distance > wTrainerEngageDistance: return False      # too far away
	ld b, a
	ld a, [wTrainerEngageDistance] ; how far the trainer can see
	cp b
	jr nc, .checkIfLinedUp
	jr .notInLine         ; player too far away
.checkIfLinedUp
;> facing = wTrainerFacingDirection
	ld a, [wTrainerFacingDirection]         ; sprite facing direction
;>@vertical if facing in (SPRITE_FACING_DOWN, SPRITE_FACING_UP):     # looking along a column
	cp SPRITE_FACING_DOWN
	jr z, .checkXCoord
	cp SPRITE_FACING_UP
	jr z, .checkXCoord
;>@column     return wTrainerScreenX == 0x40
;>@horizontal if facing in (SPRITE_FACING_LEFT, SPRITE_FACING_RIGHT):  # along a row
;=@horizontal
	cp SPRITE_FACING_LEFT
	jr z, .checkYCoord
	cp SPRITE_FACING_RIGHT
	jr z, .checkYCoord
;>@row     return wTrainerScreenY == 0x3C
;>@no return False
;=@no
	jr .notInLine
.checkXCoord
;=@column
	ld a, [wTrainerScreenX]         ; sprite screen X position
	ld b, a
	cp $40
	jr z, .inLine
	jr .notInLine
.checkYCoord
;=@row
	ld a, [wTrainerScreenY]         ; sprite screen Y position
	ld b, a
	cp $3c
	jr nz, .notInLine
.inLine
	scf
	ret
.notInLine
;=@no
	and a
	ret

; tests if the player is in front of the sprite (rather than behind it)
;@ path: engine/overworld/trainer_sight
;@ def CheckPlayerIsInFrontOfSprite()
;@ Is the player in front of the trainer rather than behind it? wTrainerSpriteOffset becomes $FF if so,
;@ else 0. Always true in the Power Plant, where the Voltorb "items" must work from any side. A sprite on the
;@ topmost tile counts as one block lower.
;@ test: wCurMap = rand(0, NUM_MAPS - 1); wTrainerSpriteOffset = 16 * rand(1, 15)
CheckPlayerIsInFrontOfSprite:
;> front = True
;> if wCurMap != POWER_PLANT:
	ld a, [wCurMap]
	cp POWER_PLANT
	jp z, .engage       ; bypass this for power plant to get voltorb fake items to work
;>     p = addr(wSpriteStateData1) + u8(wTrainerSpriteOffset + SPRITESTATEDATA1_YPIXELS)
	ld a, [wTrainerSpriteOffset]
	add SPRITESTATEDATA1_YPIXELS
	ld d, $0
	ld e, a
	ld hl, wSpriteStateData1
	add hl, de
;>     y = mem[p]
	ld a, [hl]          ; x#SPRITESTATEDATA1_YPIXELS
;>     wTrainerScreenY = 0x0C if y == 0xFC else y    # on the topmost tile: one block lower
	cp $fc
	jr nz, .notOnTopmostTile ; special case if sprite is on topmost tile (Y = $fc (-4)), make it come down a block
	ld a, $c
.notOnTopmostTile
	ld [wTrainerScreenY], a
;>     p = addr(wSpriteStateData1) + u8(wTrainerSpriteOffset + SPRITESTATEDATA1_XPIXELS)
	ld a, [wTrainerSpriteOffset]
	add SPRITESTATEDATA1_XPIXELS
	ld d, $0
	ld e, a
	ld hl, wSpriteStateData1
	add hl, de
;>     wTrainerScreenX = mem[p]
	ld a, [hl]          ; x#SPRITESTATEDATA1_XPIXELS
	ld [wTrainerScreenX], a
;>     if wTrainerFacingDirection == SPRITE_FACING_DOWN:
	ld a, [wTrainerFacingDirection]       ; facing direction
	cp SPRITE_FACING_DOWN
	jr nz, .notFacingDown
;>         front = wTrainerScreenY < 0x3C          # above the player
	ld a, [wTrainerScreenY]       ; sprite screen Y pos
	cp $3c
	jr c, .engage       ; sprite above player
	jr .noEngage        ; sprite below player
.notFacingDown
;>     elif wTrainerFacingDirection == SPRITE_FACING_UP:
	cp SPRITE_FACING_UP
	jr nz, .notFacingUp
;>         front = wTrainerScreenY >= 0x3C
	ld a, [wTrainerScreenY]       ; sprite screen Y pos
	cp $3c
	jr nc, .engage      ; sprite below player
	jr .noEngage        ; sprite above player
.notFacingUp
;>     elif wTrainerFacingDirection == SPRITE_FACING_LEFT:
	cp SPRITE_FACING_LEFT
	jr nz, .notFacingLeft
;>         front = wTrainerScreenX >= 0x40         # right of the player
	ld a, [wTrainerScreenX]       ; sprite screen X pos
	cp $40
	jr nc, .engage      ; sprite right of player
	jr .noEngage        ; sprite left of player
.notFacingLeft
;>     else:
;>         front = wTrainerScreenX < 0x40
	ld a, [wTrainerScreenX]       ; sprite screen X pos
	cp $40
	jr nc, .noEngage    ; sprite right of player
.engage
;> wTrainerSpriteOffset = 0xFF if front else 0
	ld a, $ff
	jr .done
.noEngage
	xor a
.done
	ld [wTrainerSpriteOffset], a
	ret


SECTION "Battle Engine 10", ROMX

;@ path: engine/battle/common_text
;@ def PrintBeginningBattleText()
;@ The battle's first message. A trainer: its jingle, then "<trainer> wants to fight!". A wild mon: its cry and
;@ "Wild <mon> appeared!" (or "The hooked <mon> attacked!"). In Pokémon Tower without the Silph Scope a ghost can't
;@ be identified; with it the ghost shows its true form - and the Marowak's ghost gets its own scene, oddly followed
;@ by the trainer jingle.
;@ test: skip waits for the sound
PrintBeginningBattleText:
;> def play_jingle():                                # .playSFX: the trainer jingle
;>@f1     wFrequencyModifier = 0
;>@f2     wTempoModifier = 0x80
;>@f3     PlaySound(SFX_TRAINER_APPEARED)
;>@f4     WaitForSoundToFinish()
;> if wIsInBattle == 1:                              # a wild Pokémon
	ld a, [wIsInBattle]
	dec a
	jr nz, .trainerBattle
;>     if POKEMON_TOWER_3F <= wCurMap <= POKEMON_TOWER_7F:   # Pokémon Tower: a ghost
;>@sc         no_scope = IsItemInBag(SILPH_SCOPE)       # (True: the Silph Scope is not in the bag)
;>@sp         wCurPartySpecies = wEnemyMonSpecies2
;>@mw         marowak = wEnemyMonSpecies2 == RESTLESS_SOUL
;>@ns         if no_scope:                              # it can't be identified
;>@na             PrintText(EnemyAppearedText)
;>@gc             return PrintText(GhostCantBeIDdText)
;>@mk         if marowak:                               # the Marowak's ghost shows its true form
;>@m1             PrintText(EnemyAppearedText)
;>@m2             PrintText(UnveiledGhostText)
;>@m3             farcall(LoadEnemyMonData)
;>@m4             farcall(MarowakAnim)
;>@m5             PrintText(WildMonAppearedText)
;>@m6             return play_jingle()                  # (it falls into it)
;>@ld         farcall(LoadEnemyMonData)                 # the true form
	ld a, [wCurMap]
	cp POKEMON_TOWER_3F
	jr c, .notPokemonTower
	cp POKEMON_TOWER_7F + 1
	jr c, .pokemonTower
.notPokemonTower
;>     PlayCry(wEnemyMonSpecies2)
	ld a, [wEnemyMonSpecies2]
	call PlayCry
;>     text = WildMonAppearedText
;>     if wMoveMissed:                               # (set when it was hooked)
	ld hl, WildMonAppearedText
	ld a, [wMoveMissed]
	and a
	jr z, .notFishing
;>         text = HookedMonAttackedText
	ld hl, HookedMonAttackedText
.notFishing
;> else:                                             # a trainer
	jr .wildBattle
.trainerBattle
;>     play_jingle()
	call .playSFX
;>     DelayFrames(20)
	ld c, 20
	call DelayFrames
;>     text = TrainerWantsToFightText
	ld hl, TrainerWantsToFightText
.wildBattle
;> farcall(DrawAllPokeballs)
	push hl
	ld hl, DrawAllPokeballs
	ld b, BANK(DrawAllPokeballs)
	call Bankswitch
	pop hl
;> PrintText(text)
	call PrintText
	jr .done
.pokemonTower
;=@sc
	ld b, SILPH_SCOPE
	call IsItemInBag
;=@sp
	ld a, [wEnemyMonSpecies2]
	ld [wCurPartySpecies], a
;=@mw
	cp RESTLESS_SOUL
	jr z, .isMarowak
;=@ns
	ld a, b
	and a
	jr z, .noSilphScope
;=@ld
	ld hl, LoadEnemyMonData
	ld b, BANK(LoadEnemyMonData)
	call Bankswitch
	jr .notPokemonTower
.noSilphScope
;=@na
	ld hl, EnemyAppearedText
	call PrintText
;=@gc
	ld hl, GhostCantBeIDdText
	call PrintText
	jr .done
.isMarowak
;=@ns
	ld a, b
	and a
	jr z, .noSilphScope
;=@m1
	ld hl, EnemyAppearedText
	call PrintText
;=@m2
	ld hl, UnveiledGhostText
	call PrintText
;=@m3
	ld hl, LoadEnemyMonData
	ld b, BANK(LoadEnemyMonData)
	call Bankswitch
;=@m4
	ld hl, MarowakAnim
	ld b, BANK(MarowakAnim)
	call Bankswitch
;=@m5
	ld hl, WildMonAppearedText
	call PrintText

.playSFX
;=@f1
	xor a
	ld [wFrequencyModifier], a
;=@f2
	ld a, $80
	ld [wTempoModifier], a
;=@f3
	ld a, SFX_TRAINER_APPEARED
	call PlaySound
;=@f4
	jp WaitForSoundToFinish
.done
	ret

;@ path: engine/battle/common_text
WildMonAppearedText:
	db TX_FAR
	dw _WildMonAppearedText
	db BANK(_WildMonAppearedText)
	db TX_END

;@ path: engine/battle/common_text
HookedMonAttackedText:
	db TX_FAR
	dw _HookedMonAttackedText
	db BANK(_HookedMonAttackedText)
	db TX_END

;@ path: engine/battle/common_text
EnemyAppearedText:
	db TX_FAR
	dw _EnemyAppearedText
	db BANK(_EnemyAppearedText)
	db TX_END

