;@ path: engine/battle/common_text
;@ def PrintSendOutMonMessage()
;@ "Go! <mon>!" when the player sends out a mon, more urgent the weaker the enemy's mon is: "Go!" at 70% of its HP
;@ or more (or when it has fainted), "Do it!" from 40%, "Get'm!" from 10%, else "The enemy's weak!". The enemy's HP
;@ is noted for the message when the mon comes back.
PrintSendOutMonMessage:
;> hp = mem[wEnemyMonHP] << 8 | mem[wEnemyMonHP + 1]
	ld hl, wEnemyMonHP
	ld a, [hli]
	or [hl]
;> if hp == 0:
;>     return PrintText(GoText)
	ld hl, GoText
	jr z, .printText
;> hMultiplicand[0] = 0
	xor a
	ldh [hMultiplicand], a
;> wLastSwitchInEnemyMonHP[0] = hMultiplicand[1] = hi(hp)   # noted for the message when it comes back
	ld hl, wEnemyMonHP
	ld a, [hli]
	ld [wLastSwitchInEnemyMonHP], a
	ldh [hMultiplicand + 1], a
;> wLastSwitchInEnemyMonHP[1] = hMultiplicand[2] = lo(hp)
	ld a, [hl]
	ld [wLastSwitchInEnemyMonHP + 1], a
	ldh [hMultiplicand + 2], a
;> hMultiplier = 25
	ld a, 25
	ldh [hMultiplier], a
;> Multiply()
	call Multiply
;> max_hp = mem[wEnemyMonMaxHP] << 8 | mem[wEnemyMonMaxHP + 1]
	ld hl, wEnemyMonMaxHP
	ld a, [hli]
	ld b, [hl]
;> quarter = max_hp >> 2
	srl a
	rr b
	srl a
	rr b
;> hDivisor = quarter & 0xFF
	ld a, b
	ld b, 4
	ldh [hDivisor], a ; enemy mon max HP divided by 4
;> Divide(4)
	call Divide
;> percent = hQuotient[3]  # about the percentage of HP left
	ldh a, [hQuotient + 3] ; a = (enemy mon current HP * 25) / (enemy max HP / 4); this approximates the current percentage of max HP
;> if percent >= 70:
;>     PrintText(GoText)
	ld hl, GoText ; 70% or greater
	cp 70
	jr nc, .printText
;> elif percent >= 40:
;>     PrintText(DoItText)
	ld hl, DoItText ; 40% - 69%
	cp 40
	jr nc, .printText
;> elif percent >= 10:
;>     PrintText(GetmText)
	ld hl, GetmText ; 10% - 39%
	cp 10
	jr nc, .printText
;> else:
;>     PrintText(EnemysWeakText)
	ld hl, EnemysWeakText ; 0% - 9%
.printText
	jp PrintText

