;@ path: engine/battle/common_text
;@ def PlayerMon2Text() -> hl
;@ "<mon>," and then words for how much HP the enemy lost since this mon came out: "enough!" for none, "come back!"
;@ up to 29%, "OK!" up to 69%, "good!" for more. If the enemy has gained HP, the number wraps around and the words
;@ are any.
;@ test: skip a text script: the code after text_asm runs from the text engine
PlayerMon2Text:
	db TX_FAR
	dw _PlayerMon2Text
	db BANK(_PlayerMon2Text)
	db TX_START_ASM
;> hp = mem[wEnemyMonHP] << 8 | mem[wEnemyMonHP + 1]
	push de
	push bc
	ld hl, wEnemyMonHP + 1
	ld de, wLastSwitchInEnemyMonHP + 1
	ld b, [hl]
	dec hl
;> lost = (wLastSwitchInEnemyMonHP[0] << 8 | wLastSwitchInEnemyMonHP[1]) - hp & 0xFFFF
	ld a, [de]
	sub b
;> hMultiplicand[2] = lo(lost)
	ldh [hMultiplicand + 2], a
;> hMultiplicand[1] = hi(lost)
	dec de
	ld b, [hl]
	ld a, [de]
	sbc b
	ldh [hMultiplicand + 1], a
;> hMultiplier = 25
	ld a, 25
	ldh [hMultiplier], a
;> Multiply()
	call Multiply
;> max_hp = mem[wEnemyMonMaxHP] << 8 | mem[wEnemyMonMaxHP + 1]
	ld hl, wEnemyMonMaxHP
	ld a, [hli]
	ld b, [hl]
;> quarter = max_hp >> 2
	srl a
	rr b
	srl a
	rr b
;> hDivisor = quarter & 0xFF
	ld a, b
	ld b, 4
	ldh [hDivisor], a
;> Divide(4)
	call Divide
	pop bc
	pop de
;> percent = hQuotient[3]
	ldh a, [hQuotient + 3] ; a = ((LastSwitchInEnemyMonHP - CurrentEnemyMonHP) / 25) / (EnemyMonMaxHP / 4)
; Assuming that the enemy mon hasn't gained HP since the last switch in,
; a approximates the percentage that the enemy mon's total HP has decreased
; since the last switch in.
; If the enemy mon has gained HP, then a is garbage due to wrap-around and
; can fall in any of the ranges below.
;> if percent == 0:
;>     return EnoughText
	ld hl, EnoughText ; HP stayed the same
	and a
	ret z
;> if percent < 30:
;>     return ComeBackText
	ld hl, ComeBackText ; HP went down 1% - 29%
	cp 30
	ret c
;> if percent < 70:
;>     return OKExclamationText
	ld hl, OKExclamationText ; HP went down 30% - 69%
	cp 70
	ret c
;> return GoodText
	ld hl, GoodText ; HP went down 70% or more
	ret

