; calculates the level a mon should be based on its current exp
;@ path: engine/pokemon/experience
;@ def CalcLevelFromExperience() -> d
;@ The level wLoadedMon's experience points reach: the highest level whose experience it has.
CalcLevelFromExperience::
;> wCurSpecies = mem[wLoadedMonSpecies]
	ld a, [wLoadedMonSpecies]
	ld [wCurSpecies], a
;> GetMonHeader()
	call GetMonHeader
;> level = 1
	ld d, $1 ; init level to 1
;> while True:
.loop
;>     level = u8(level + 1)
	inc d ; increment level
;>     CalcExperience(level)
	call CalcExperience
;>     # its experience minus the experience of that level, from the low byte up
;>     low = mem[wLoadedMonExp + 2] - hProduct[3]
	push hl
	ld hl, wLoadedMonExp + 2 ; current exp
; compare exp needed for level d with current exp
	ldh a, [hExperience + 2]
	ld c, a
	ld a, [hld]
	sub c
;>     mid = mem[wLoadedMonExp + 1] - hProduct[2] - (low < 0)
	ldh a, [hExperience + 1]
	ld c, a
	ld a, [hld]
	sbc c
;>     high = mem[wLoadedMonExp] - hProduct[1] - (mid < 0)
	ldh a, [hExperience]
	ld c, a
	ld a, [hl]
	sbc c
	pop hl
;>     if high < 0:                              # it does not have that much
	jr nc, .loop ; if exp needed for level d is not greater than exp, try the next level
;>         return u8(level - 1)
	dec d ; since the exp was too high on the last loop iteration, go back to the previous value and return
	ret

; calculates the amount of experience needed for level d
;@ path: engine/pokemon/experience
;@ def CalcExperience(level: d)
;@ hExperience (3 bytes, big-endian) = the experience points needed for `level` in growth rate
;@ wMonHGrowthRate: a / b * level³ + c * level² + d * level - e, with the coefficients from GrowthRateTable.
;@ test: hLoadedROMBank = 0x16; wMonHGrowthRate = rand(0, NUM_GROWTH_RATES - 1); level = rand(1, 100)
CalcExperience::
;> offset = 4 * wMonHGrowthRate
	ld a, [wMonHGrowthRate]
	add a
	add a
;> rate = GrowthRateTable + offset              # a/b, c, d, e
	ld c, a
	ld b, 0
	ld hl, GrowthRateTable
	add hl, bc
;> # level³ * a / b
;> CalcDSquared(level)
	call CalcDSquared
;> hMultiplier = level
	ld a, d
	ldh [hMultiplier], a
;> Multiply()
	call Multiply
;> hMultiplier = mem[rate] >> 4
	ld a, [hl]
	and $f0
	swap a
	ldh [hMultiplier], a
;> Multiply()
	call Multiply
;> hDivisor = mem[rate] & 0xF
;> rate += 1
	ld a, [hli]
	and $f
	ldh [hDivisor], a
;> Divide(4)
	ld b, $4
	call Divide
;> cubed = hQuotient[1] << 16 | hQuotient[2] << 8 | hQuotient[3]     # kept on the stack
	ldh a, [hQuotient + 1]
	push af
	ldh a, [hQuotient + 2]
	push af
	ldh a, [hQuotient + 3]
	push af
;> # c * level², c stored as sign and magnitude
;> CalcDSquared(level)
	call CalcDSquared
;> hMultiplier = mem[rate] & 0x7F
	ld a, [hl]
	and $7f
	ldh [hMultiplier], a
;> Multiply()
	call Multiply
;> squared = hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3]
	ldh a, [hProduct + 1]
	push af
	ldh a, [hProduct + 2]
	push af
	ldh a, [hProduct + 3]
	push af
;> negative = mem[rate] & 0x80
;> rate += 1
	ld a, [hli]
	push af
;> # d * level - e
;> hMultiplicand[0] = 0
;> hMultiplicand[1] = 0
	xor a
	ldh [hMultiplicand], a
	ldh [hMultiplicand + 1], a
;> hMultiplicand[2] = level
	ld a, d
	ldh [hMultiplicand + 2], a
;> hMultiplier = mem[rate]
;> rate += 1
	ld a, [hli]
	ldh [hMultiplier], a
;> Multiply()
	call Multiply
;> total = (hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3]) - mem[rate]
	ld b, [hl]
;> hProduct[3] = total & 0xFF
	ldh a, [hProduct + 3]
	sub b
	ldh [hProduct + 3], a
;> hProduct[2] = total >> 8 & 0xFF
	ld b, $0
	ldh a, [hProduct + 2]
	sbc b
	ldh [hProduct + 2], a
;> hProduct[1] = total >> 16 & 0xFF
	ldh a, [hProduct + 1]
	sbc b
	ldh [hProduct + 1], a
; The difference of the linear term and the constant term consists of 3 bytes
; starting at hProduct + 1. Below, hExperience (an alias of that address) will
; be used instead for the further work of adding or subtracting the squared
; term and adding the cubed term.
;> if not negative:
	pop af
	and $80
	jr nz, .subtractSquaredTerm ; check sign
;>     total = (hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3]) + squared
;>     hProduct[3] = total & 0xFF
	pop bc
	ldh a, [hExperience + 2]
	add b
	ldh [hExperience + 2], a
;>     hProduct[2] = total >> 8 & 0xFF
	pop bc
	ldh a, [hExperience + 1]
	adc b
	ldh [hExperience + 1], a
;>     hProduct[1] = total >> 16 & 0xFF
	pop bc
	ldh a, [hExperience]
	adc b
	ldh [hExperience], a
	jr .addCubedTerm
.subtractSquaredTerm
;> else:
;>     total = (hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3]) - squared
;>     hProduct[3] = total & 0xFF
	pop bc
	ldh a, [hExperience + 2]
	sub b
	ldh [hExperience + 2], a
;>     hProduct[2] = total >> 8 & 0xFF
	pop bc
	ldh a, [hExperience + 1]
	sbc b
	ldh [hExperience + 1], a
;>     hProduct[1] = total >> 16 & 0xFF
	pop bc
	ldh a, [hExperience]
	sbc b
	ldh [hExperience], a
.addCubedTerm
;> total = (hProduct[1] << 16 | hProduct[2] << 8 | hProduct[3]) + cubed
;> hProduct[3] = total & 0xFF
	pop bc
	ldh a, [hExperience + 2]
	add b
	ldh [hExperience + 2], a
;> hProduct[2] = total >> 8 & 0xFF
	pop bc
	ldh a, [hExperience + 1]
	adc b
	ldh [hExperience + 1], a
;> hProduct[1] = total >> 16 & 0xFF
	pop bc
	ldh a, [hExperience]
	adc b
	ldh [hExperience], a
	ret

; calculates d*d
;@ path: engine/pokemon/experience
;@ def CalcDSquared(n: d)
;@ hProduct = n * n.
;@ test: hLoadedROMBank = 0x16; n = rand(0, 255)
CalcDSquared:
;> hMultiplicand[0] = 0
;> hMultiplicand[1] = 0
	xor a
	ldh [hMultiplicand], a
	ldh [hMultiplicand + 1], a
;> hMultiplicand[2] = n
	ld a, d
	ldh [hMultiplicand + 2], a
;> hMultiplier = n
	ldh [hMultiplier], a
;> Multiply()
	jp Multiply


;@ path: engine/pokemon/experience
GrowthRateTable:
; entries correspond to GROWTH_* (see constants/pokemon_data_constants.asm)
	; Medium Fast
	db ((1) << 4) | (1)
	db 0
	db 0, 0
	; Slightly Fast
	db ((3) << 4) | (4)
	db 10
	db 0, 30
	; Slightly Slow
	db ((3) << 4) | (4)
	db 20
	db 0, 70
	; Medium Slow
	db ((6) << 4) | (5)
	db --15 | $80
	db 100, 140
	; Fast
	db ((4) << 4) | (5)
	db 0
	db 0, 0
	; Slow
	db ((5) << 4) | (4)
	db 0
	db 0, 0
;@ path: engine/events/oaks_aide
;@ def OaksAideScript()
;@ One of Oak's aides: with at least hOaksAideRequirement Pokémon owned the player gets hOaksAideRewardItem
;@ (if there is room). hOaksAideResult tells the map script what happened.
;@ test: skip asks the player a question
OaksAideScript:
;> PrintText(OaksAideHiText)
	ld hl, OaksAideHiText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:                         # NO
;>@no     PrintText(OaksAideComeBackText)
;>@refused     hOaksAideResult = OAKS_AIDE_REFUSED
;>@noret     return
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .choseNo
;> CountSetBits(addr(wPokedexOwned), addr(wPokedexOwnedEnd) - addr(wPokedexOwned))
	ld hl, wPokedexOwned
	ld b, wPokedexOwnedEnd - wPokedexOwned
	call CountSetBits
;> hOaksAideNumMonsOwned = wNumSetBits
	ld a, [wNumSetBits]
	ldh [hOaksAideNumMonsOwned], a
;> if hOaksAideRequirement > hOaksAideNumMonsOwned:
;>@few     PrintText(OaksAideUhOhText)
;>@notenough     hOaksAideResult = OAKS_AIDE_NOT_ENOUGH_MONS
;>@fewret     return
	ld b, a
	ldh a, [hOaksAideRequirement]
	cp b
	jr z, .giveItem
	jr nc, .notEnoughOwnedMons
.giveItem
;> PrintText(OaksAideHereYouGoText)
	ld hl, OaksAideHereYouGoText
	call PrintText
;> given = GiveItem(hOaksAideRewardItem, 1)
	ldh a, [hOaksAideRewardItem]
	ld b, a
	ld c, 1
	call GiveItem
;> if given:
	jr nc, .bagFull
;>     PrintText(OaksAideGotItemText)
	ld hl, OaksAideGotItemText
	call PrintText
;>     hOaksAideResult = OAKS_AIDE_GOT_ITEM
	ld a, OAKS_AIDE_GOT_ITEM
	jr .done
.bagFull
;> else:
;>     PrintText(OaksAideNoRoomText)
	ld hl, OaksAideNoRoomText
	call PrintText
;>     hOaksAideResult = OAKS_AIDE_BAG_FULL
	xor a ; OAKS_AIDE_BAG_FULL
	jr .done
.notEnoughOwnedMons
;=@few
	ld hl, OaksAideUhOhText
	call PrintText
;=@notenough
	ld a, OAKS_AIDE_NOT_ENOUGH_MONS
	jr .done
.choseNo
;=@no
	ld hl, OaksAideComeBackText
	call PrintText
;=@refused
	ld a, OAKS_AIDE_REFUSED
.done
	ldh [hOaksAideResult], a
	ret

;@ path: engine/events/oaks_aide
OaksAideHiText:
	db TX_FAR
	dw _OaksAideHiText
	db BANK(_OaksAideHiText)
	db TX_END

;@ path: engine/events/oaks_aide
OaksAideUhOhText:
	db TX_FAR
	dw _OaksAideUhOhText
	db BANK(_OaksAideUhOhText)
	db TX_END

;@ path: engine/events/oaks_aide
OaksAideComeBackText:
	db TX_FAR
	dw _OaksAideComeBackText
	db BANK(_OaksAideComeBackText)
	db TX_END

;@ path: engine/events/oaks_aide
OaksAideHereYouGoText:
	db TX_FAR
	dw _OaksAideHereYouGoText
	db BANK(_OaksAideHereYouGoText)
	db TX_END

