SECTION "Saffron Guards", ROMX

;@ path: engine/events/saffron_guards
;@ def RemoveGuardDrink()
;@ Give one of the thirsty Saffron guards a drink: the first drink of GuardDrinksList found in the bag is
;@ removed.
RemoveGuardDrink::
;> p = GuardDrinksList
	ld hl, GuardDrinksList
;>@drinks while True:
.drinkLoop
;>     hItemToRemoveID = mem[p]
	ld a, [hli]
	ldh [hItemToRemoveID], a
;>@next     p += 1
;>     if hItemToRemoveID == 0: return           # none of them in the bag
	and a
	ret z
;>     if not IsItemInBag(hItemToRemoveID):     # zero: not in the bag
	push hl
	ld b, a
	call IsItemInBag
	pop hl
	jr z, .drinkLoop
;>         RemoveItemByID()                     # in another bank
;>         return
	ld b, BANK(RemoveItemByID)
	ld hl, RemoveItemByID
	jp Bankswitch

;@ path: engine/events/saffron_guards
GuardDrinksList:
	db FRESH_WATER
	db SODA_POP
	db LEMONADE
	db 0 ; end


SECTION "Starter Dex", ROMX

; this function temporarily makes the starters (and Ivysaur) owned
; so that the full Pokedex information gets displayed in Oak's lab
;@ path: engine/events/starter_dex
;@ def StarterDex()
;@ Oak shows the Pokédex with only the four starter lines owned for the moment.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
StarterDex:
;> wPokedexOwned[0] = 1 << (DEX_BULBASAUR - 1) | 1 << (DEX_IVYSAUR - 1) | 1 << (DEX_CHARMANDER - 1) | 1 << (DEX_SQUIRTLE - 1)
	ld a, 1 << (DEX_BULBASAUR - 1) | 1 << (DEX_IVYSAUR - 1) | 1 << (DEX_CHARMANDER - 1) | 1 << (DEX_SQUIRTLE - 1)
	ld [wPokedexOwned], a
;> ShowPokedexData()                            # a predef
	ld a, (ShowPokedexDataPredef - PredefPointers) / 3
	call Predef
;> wPokedexOwned[0] = 0
	xor a
	ld [wPokedexOwned], a
	ret


SECTION "Hidden Events 3", ROMX

; updates the types of a party mon (pointed to in hl) to the ones of the mon specified in [wPokedexNum]
;@ path: engine/pokemon/set_types
;@ def SetPartyMonTypes()
;@ Give the Pokémon struct at the predef's hl the two types of species wPokedexNum.
SetPartyMonTypes:
;> mon = wPredefHL[0] << 8 | wPredefHL[1]       # the predef's hl
	call GetPredefRegisters
;> types = mon + MON_TYPE
	ld bc, MON_TYPE
	add hl, bc
;> wCurSpecies = wPokedexNum
	ld a, [wPokedexNum]
	ld [wCurSpecies], a
