	ld de, vChars1 + TILE_SIZE * $31
	call LoadMonFrontSprite
;> hStartTileID = 0x80
	ld a, $80
	ldh [hStartTileID], a
;> AnimateSendingOutMon(coord(10, 11))          # a predef
	ld hl, (11) * SCREEN_WIDTH + (10) + wTileMap
	ld a, (AnimateSendingOutMonPredef - PredefPointers) / 3
	call Predef
