;@ path: engine/events/hidden_events/school_blackboard
;@ def LinkCableHelp() -> hl
;@ The link cable help poster: a menu of three topics (how to link, colosseum, trade center) that can be
;@ read in any order until STOP READING or B.
;@ test: skip a text script: the code after text_asm is run by the text engine
LinkCableHelp::
	db TX_START_ASM
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> PrintText(LinkCableHelpText1)
	ld hl, LinkCableHelpText1
	call PrintText
;> wMenuItemOffset = 0
	xor a
	ld [wMenuItemOffset], a ; not used
;> wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 3
	ld a, 3
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> while True:
.linkHelpLoop
;>     wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;>     TextBoxBorder(coord(0, 0), 8, 13)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 8
	ld c, 13
	call TextBoxBorder
;>     PlaceString(HowToLinkText, coord(2, 2))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ld de, HowToLinkText
	call PlaceString
;>     PrintText(LinkCableHelpText2)
	ld hl, LinkCableHelpText2
	call PrintText
;>     if HandleMenuInput() & (1 << B_PAD_B) or wCurrentMenuItem == 3:     # STOP READING
;>         break
	call HandleMenuInput
	bit B_PAD_B, a
	jr nz, .exit
	ld a, [wCurrentMenuItem]
	cp 3 ; pressed a on "STOP READING"
	jr z, .exit
;>     wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;>     entry = LinkCableInfoTexts + u8(2 * wCurrentMenuItem)
	ld hl, LinkCableInfoTexts
	add a
	ld d, 0
	ld e, a
	add hl, de
;>     text = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     PrintText(text)
	call PrintText
	jp .linkHelpLoop
.exit
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> return TextScriptEnd()
	jp TextScriptEnd

