;@ path: engine/events/hidden_events/school_blackboard
;@ def ViridianSchoolBlackboard() -> hl
;@ The Viridian school blackboard: two columns of status conditions (left/right switch columns); A explains
;@ the chosen one, QUIT or B leaves.
;@ test: skip a text script: the code after text_asm is run by the text engine
ViridianSchoolBlackboard::
	db TX_START_ASM
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> PrintText(ViridianSchoolBlackboardText1)
	ld hl, ViridianSchoolBlackboardText1
	call PrintText
;> wMenuItemOffset = 0
	xor a
	ld [wMenuItemOffset], a
;> wCurrentMenuItem = 0
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuWatchedKeys = PAD_LEFT | PAD_RIGHT | PAD_A | PAD_B
	ld a, PAD_LEFT | PAD_RIGHT | PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 2
	ld a, 2
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> while True:
.blackboardLoop
;>     wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;>     TextBoxBorder(coord(0, 0), 6, 10)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((6) & $ff) << 8 + ((10) & $ff)
	call TextBoxBorder
;>     PlaceString(StatusAilmentText1, coord(1, 2))
	ld hl, (2) * SCREEN_WIDTH + (1) + wTileMap
	ld de, StatusAilmentText1
	call PlaceString
;>     PlaceString(StatusAilmentText2, coord(6, 2))
	ld hl, (2) * SCREEN_WIDTH + (6) + wTileMap
	ld de, StatusAilmentText2
	call PlaceString
;>     PrintText(ViridianSchoolBlackboardText2)
	ld hl, ViridianSchoolBlackboardText2
	call PrintText
;>     keys = HandleMenuInput()
	call HandleMenuInput ; pressing up and down is handled in here
;>     if keys & (1 << B_PAD_B):
;>         break
	bit B_PAD_B, a ; pressed b
	jr nz, .exitBlackboard
;>     if keys & (1 << B_PAD_RIGHT):            # right column: items 3-5
	bit B_PAD_RIGHT, a
	jr z, .didNotPressRight
	; move cursor to right column
;>         wMaxMenuItem = 2
	ld a, 2
	ld [wMaxMenuItem], a
;>         wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;>         wTopMenuItemX = 6
	ld a, 6
	ld [wTopMenuItemX], a
;>         wMenuItemOffset = 3
	ld a, 3 ; in the the right column, use an offset to prevent overlap
	ld [wMenuItemOffset], a
;>         continue
	jr .blackboardLoop
.didNotPressRight
;>     if keys & (1 << B_PAD_LEFT):
	bit B_PAD_LEFT, a
	jr z, .didNotPressLeftOrRight
	; move cursor to left column
;>         wMaxMenuItem = 2
	ld a, 2
	ld [wMaxMenuItem], a
;>         wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;>         wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;>         wMenuItemOffset = 0
	xor a
	ld [wMenuItemOffset], a
;>         continue
	jr .blackboardLoop
.didNotPressLeftOrRight
;>     item = u8(wCurrentMenuItem + wMenuItemOffset)
	ld a, [wCurrentMenuItem]
	ld b, a
	ld a, [wMenuItemOffset]
	add b
;>     if item == 5:                            # QUIT
;>         break
	cp 5 ; cursor is pointing to "QUIT"
	jr z, .exitBlackboard
	; we must have pressed a on a status condition
	; so print the text
;>     wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;>     entry = ViridianBlackboardStatusPointers + u8(2 * item)
	ld hl, ViridianBlackboardStatusPointers
	add a
	ld d, 0
	ld e, a
	add hl, de
;>     text = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     PrintText(text)
	call PrintText
	jp .blackboardLoop
.exitBlackboard
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> return TextScriptEnd()
	jp TextScriptEnd

