;@ path: engine/events/hidden_events/vermilion_gym_trash
VermilionGymTrashText::
	db TX_FAR
	dw _VermilionGymTrashText
	db BANK(_VermilionGymTrashText)
	db TX_END

;@ path: engine/events/hidden_events/vermilion_gym_trash
;@ def GymTrashScript()
;@ The Vermilion Gym trash can puzzle. The first switch hides in can wFirstLockTrashCanIndex; finding it
;@ picks the can of the second switch at random among that can's neighbours (GymTrashCans: count mask, then
;@ candidates). A wrong can for the second switch resets the puzzle with a new random first can.
;@ test: skip prints a text
GymTrashScript:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wGymTrashCanIndex = wHiddenEventFunctionArgument
	ld a, [wHiddenEventFunctionArgument]
	ld [wGymTrashCanIndex], a

; Don't do the trash can puzzle if it's already been done.
;> if event(EVENT_2ND_LOCK_OPENED):             # puzzle already solved
	ld a, [wEventFlags + $2C]
	bit (EVENT_2ND_LOCK_OPENED) % 8, a
	jr z, .ok

;>     PrintPredefTextID((VermilionGymTrashText_id - TextPredefs) // 2 + 1)
;>     return
	ld a, (VermilionGymTrashText_id - TextPredefs) / 2 + 1
	jp PrintPredefTextID

.ok
;> if not event(EVENT_1ST_LOCK_OPENED):
	bit (EVENT_1ST_LOCK_OPENED) % 8, a
	jr nz, .trySecondLock

;>     if wGymTrashCanIndex == wFirstLockTrashCanIndex:
	ld a, [wFirstLockTrashCanIndex]
	ld b, a
	ld a, [wGymTrashCanIndex]
	cp b
	jr z, .openFirstLock

;=@wrong
	ld a, (VermilionGymTrashText_id - TextPredefs) / 2 + 1
	jr .done

.openFirstLock
; Next can is trying for the second switch.
;>         set_event(EVENT_1ST_LOCK_OPENED)
	ld hl, wEventFlags + $2C
	set (EVENT_1ST_LOCK_OPENED) % 8, [hl]

;>@p         p = GymTrashCans + u8(5 * wGymTrashCanIndex)
	ld hl, GymTrashCans
	ld a, [wGymTrashCanIndex]
	; * 5
	ld b, a
	add a
	add a
	add b

;=@p
	ld d, 0
	ld e, a
	add hl, de
;>         hGymTrashCanRandNumMask[0] = mem[p]
	ld a, [hli]

; Bug: This code should calculate a value in the range [0, 3],
; but if the mask and random number don't have any 1 bits in common, then
; the result of the AND will be 0. When 1 is subtracted from that, the value
; will become $ff. This will result in 255 being added to hl, which will cause
; hl to point to one of the zero bytes that pad the end of the ROM bank.
; Trash can 0 was intended to be able to have the second lock only when the
; first lock was in trash can 1 or 3. However, due to this bug, trash can 0 can
; have the second lock regardless of which trash can had the first lock.

	ldh [hGymTrashCanRandNumMask], a
;>         r = swap(Random())
	push hl
	call Random
	swap a
	ld b, a
;>         pick = u8((r & hGymTrashCanRandNumMask[0]) - 1)    # $FF when the AND gives 0
	ldh a, [hGymTrashCanRandNumMask]
	and b
	dec a
	pop hl

;>         wSecondLockTrashCanIndex = mem[p + 1 + pick] & 0xF
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
	and $f
	ld [wSecondLockTrashCanIndex], a

;>         text = VermilionGymTrashSuccessText1_id
;>     else:
;>@wrong         text = VermilionGymTrashText_id
	ld a, (VermilionGymTrashSuccessText1_id - TextPredefs) / 2 + 1
	jr .done

.trySecondLock
;> elif wGymTrashCanIndex == wSecondLockTrashCanIndex:
	ld a, [wSecondLockTrashCanIndex]
	ld b, a
	ld a, [wGymTrashCanIndex]
	cp b
	jr z, .openSecondLock

;>@lock2     set_event(EVENT_2ND_LOCK_OPENED)
;>@reload     wCurrentMapScriptFlags = wCurrentMapScriptFlags | 1 << BIT_CUR_MAP_LOADED_2
;>@text3     text = VermilionGymTrashSuccessText3_id
;> else:
; Reset the cans.
;>     reset_event(EVENT_1ST_LOCK_OPENED)
	ld hl, wEventFlags + $2C
	res (EVENT_1ST_LOCK_OPENED) % 8, [hl]
;>     wFirstLockTrashCanIndex = Random() & 0xE
	call Random

	and $e
	ld [wFirstLockTrashCanIndex], a

;>     text = VermilionGymTrashFailText_id
	ld a, (VermilionGymTrashFailText_id - TextPredefs) / 2 + 1
	jr .done

.openSecondLock
; Completed the trash can puzzle.
;=@lock2
	ld hl, wEventFlags + $2C
	set (EVENT_2ND_LOCK_OPENED) % 8, [hl]
;=@reload
	ld hl, wCurrentMapScriptFlags
	set BIT_CUR_MAP_LOADED_2, [hl]

;=@text3
	ld a, (VermilionGymTrashSuccessText3_id - TextPredefs) / 2 + 1

.done
;> PrintPredefTextID((text - TextPredefs) // 2 + 1)
	jp PrintPredefTextID

;@ path: engine/events/hidden_events/vermilion_gym_trash
GymTrashCans:
; byte 0: mask for random number
; bytes 1-4: indices of the trash cans that can have the second lock
;            (but see the comment above explaining a bug regarding this)
; Note that the mask is simply the number of valid trash can indices that
; follow. The remaining bytes are filled with 0 to pad the length of each entry
; to 5 bytes.
	db 2,  1,  3,  0,  0 ; 0
	db 3,  0,  2,  4,  0 ; 1
	db 2,  1,  5,  0,  0 ; 2
	db 3,  0,  4,  6,  0 ; 3
	db 4,  1,  3,  5,  7 ; 4
	db 3,  2,  4,  8,  0 ; 5
	db 3,  3,  7,  9,  0 ; 6
	db 4,  4,  6,  8, 10 ; 7
	db 3,  5,  7, 11,  0 ; 8
	db 3,  6, 10, 12,  0 ; 9
	db 4,  7,  9, 11, 13 ; 10
	db 3,  8, 10, 14,  0 ; 11
	db 2,  9, 13,  0,  0 ; 12
	db 3, 10, 12, 14,  0 ; 13
