SECTION "Cinnabar Lab Fossils", ROMX

;@ path: engine/events/cinnabar_lab
;@ def GiveFossilToCinnabarLab()
;@ The Cinnabar Lab scientist: choose a fossil from the bag (Dome, Helix or Old Amber), confirm, and it is
;@ taken away to be revived as Kabuto, Omanyte or Aerodactyl.
;@ test: skip shows a menu
GiveFossilToCinnabarLab::
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = u8(wFilteredBagItemsCount - 1)
	ld a, [wFilteredBagItemsCount]
	dec a
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 2
	ld a, 2
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> rows = u8(AddNTimes(3, 2, u8(wFilteredBagItemsCount - 1)) - 1)    # 2 per fossil
	ld a, [wFilteredBagItemsCount]
	dec a
	ld bc, 2
	ld hl, 3
	call AddNTimes
	dec l
;> TextBoxBorder(coord(0, 0), rows, 13)
	ld b, l
	ld c, $d
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> PrintFossilsInBag()
	call PrintFossilsInBag
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> keys = HandleMenuInput()
	call HandleMenuInput
;> if keys & (1 << B_PAD_B):
;>@cancel     PrintText(0x50BD)                        # .ComeAgainText
;>@cancelret     return
	bit B_PAD_B, a
	jr nz, .cancelledGivingFossil
;> item = wFilteredBagItems[wCurrentMenuItem]
	ld hl, wFilteredBagItems
	ld a, [wCurrentMenuItem]
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
;> hItemToRemoveID = item
	ldh [hItemToRemoveID], a
;> if item == DOME_FOSSIL:
;>@kabuto     mon = KABUTO
	cp DOME_FOSSIL
	jr z, .choseDomeFossil
;> elif item == HELIX_FOSSIL:
;>@omanyte     mon = OMANYTE
	cp HELIX_FOSSIL
	jr z, .choseHelixFossil
;> else:
;>     mon = AERODACTYL
	ld b, AERODACTYL
	jr .fossilSelected
.choseHelixFossil
;=@omanyte
	ld b, OMANYTE
	jr .fossilSelected
.choseDomeFossil
;=@kabuto
	ld b, KABUTO
.fossilSelected
;> wFossilItem = item
	ld [wFossilItem], a
;> wFossilMon = mon
	ld a, b
	ld [wFossilMon], a
;> LoadFossilItemAndMonName()
	call LoadFossilItemAndMonName
;> PrintText(0x50AE)                            # .ScientistSeesFossilText
	ld hl, .ScientistSeesFossilText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:                         # NO: the same text, at .cancelledGivingFossil
;>@no     PrintText(0x50BD)                        # .ComeAgainText
;>@noret     return
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .cancelledGivingFossil
;> PrintText(0x50B3)                            # .ScientistTakesFossilText
	ld hl, .ScientistTakesFossilText
	call PrintText
;> hItemToRemoveID = wFossilItem
	ld a, [wFossilItem]
	ldh [hItemToRemoveID], a
;> RemoveItemByID()                             # in another bank
	ld b, BANK(RemoveItemByID)
	ld hl, RemoveItemByID
	call Bankswitch
;> PrintText(0x50B8)                            # .GoForAWalkText
	ld hl, .GoForAWalkText
	call PrintText
;> set_event(EVENT_GAVE_FOSSIL_TO_LAB)
	ld hl, wEventFlags + $5C
	set (EVENT_GAVE_FOSSIL_TO_LAB) % 8, [hl]
;> set_event(EVENT_LAB_STILL_REVIVING_FOSSIL)
	set (EVENT_LAB_STILL_REVIVING_FOSSIL) % 8, [hl]
	ret
.cancelledGivingFossil
;=@cancel
	ld hl, .ComeAgainText
	call PrintText
;=@cancelret
	ret

.ScientistSeesFossilText:
	db TX_FAR
	dw _CinnabarLabFossilRoomScientist1SeesFossilText
	db BANK(_CinnabarLabFossilRoomScientist1SeesFossilText)
	db TX_END

.ScientistTakesFossilText:
	db TX_FAR
	dw _CinnabarLabFossilRoomScientist1TakesFossilText
	db BANK(_CinnabarLabFossilRoomScientist1TakesFossilText)
	db TX_END

.GoForAWalkText:
	db TX_FAR
	dw _CinnabarLabFossilRoomScientist1GoForAWalkText2
	db BANK(_CinnabarLabFossilRoomScientist1GoForAWalkText2)
	db TX_END

.ComeAgainText:
	db TX_FAR
	dw _CinnabarLabFossilRoomScientist1ComeAgainText
	db BANK(_CinnabarLabFossilRoomScientist1ComeAgainText)
	db TX_END

;@ path: engine/events/cinnabar_lab
;@ def PrintFossilsInBag()
;@ List the fossils of wFilteredBagItems (ended by $FF) in the menu, one every two lines.
PrintFossilsInBag:
; Prints each fossil in the player's bag on a separate line in the menu.
;> p = addr(wFilteredBagItems)
	ld hl, wFilteredBagItems
;> mem[addr(hItemCounter)] = 0
	xor a
	ldh [hItemCounter], a
.loop
;> while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
	ret z
;>     wNamedObjectIndex = mem[p]
	push hl
	ld [wNamedObjectIndex], a
;>     GetItemName()
	call GetItemName
;>     PlaceString(addr(wNameBuffer), AddNTimes(coord(2, 2), SCREEN_WIDTH * 2, mem[addr(hItemCounter)]))
	ld hl, (2) * SCREEN_WIDTH + (2) + wTileMap
	ldh a, [hItemCounter]
	ld bc, SCREEN_WIDTH * 2
	call AddNTimes
	ld de, wNameBuffer
	call PlaceString
;>     mem[addr(hItemCounter)] = u8(mem[addr(hItemCounter)] + 1)
	ld hl, hItemCounter
	inc [hl]
;>     p += 1
	pop hl
	jr .loop

; loads the names of the fossil item and the resulting mon
;@ path: engine/events/cinnabar_lab
;@ def LoadFossilItemAndMonName()
;@ Names for the fossil texts: the Pokémon's into wStringBuffer, the fossil's into wNameBuffer.
;@ test: hLoadedROMBank = 0x18; wFossilMon = rand(1, 190); wFossilItem = rand(1, 0x53)
LoadFossilItemAndMonName::
;> wNamedObjectIndex = wFossilMon
	ld a, [wFossilMon]
	ld [wNamedObjectIndex], a
;> CopyToStringBuffer(GetMonName())
	call GetMonName
	call CopyToStringBuffer
;> wNamedObjectIndex = wFossilItem
	ld a, [wFossilItem]
	ld [wNamedObjectIndex], a
;> GetItemName()
	call GetItemName
	ret


SECTION "Hidden Events 4", ROMX

;@ path: engine/events/hidden_events/gym_statues
;@ def GymStatues()
;@ A statue in a gym, from below: it lists the gym's winners - with the player's name once the gym's badge
;@ (MapBadgeFlags: map, badge bit) is won.
;@ test: skip prints a text
GymStatues:
; if in a gym and have the corresponding badge, a = GymStatueText2_id and jp PrintPredefTextID
; if in a gym and don't have the corresponding badge, a = GymStatueText1_id and jp PrintPredefTextID
; else ret
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> if wSpritePlayerStateData1FacingDirection != SPRITE_FACING_UP: return
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp SPRITE_FACING_UP
	ret nz
;> p = MapBadgeFlags
	ld hl, MapBadgeFlags
	ld a, [wCurMap]
	ld b, a
.loop
;>@loop while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
	ret z
;>     if mem[p] == wCurMap:
	cp b
	jr z, .match
;=@step
	inc hl
;=@loop
	jr .loop
.match
;>         badge = mem[p + 1]
	ld b, [hl]
;>         text = GymStatueText2_id if wBeatGymFlags & badge == badge else GymStatueText1_id
	ld a, [wBeatGymFlags]
	and b
	cp b
	ld a, (GymStatueText2_id - TextPredefs) / 2 + 1
	jr z, .haveBadge
	ld a, (GymStatueText1_id - TextPredefs) / 2 + 1
.haveBadge
;>         PrintPredefTextID((text - TextPredefs) // 2 + 1)
;>         return
;>@step     p += 2
	jp PrintPredefTextID

;@ path: engine/events/hidden_events/gym_statues
MapBadgeFlags:
	db PEWTER_GYM,    1 << BIT_BOULDERBADGE
	db CERULEAN_GYM,  1 << BIT_CASCADEBADGE
	db VERMILION_GYM, 1 << BIT_THUNDERBADGE
	db CELADON_GYM,   1 << BIT_RAINBOWBADGE
	db FUCHSIA_GYM,   1 << BIT_SOULBADGE
	db SAFFRON_GYM,   1 << BIT_MARSHBADGE
	db CINNABAR_GYM,  1 << BIT_VOLCANOBADGE
	db VIRIDIAN_GYM,  1 << BIT_EARTHBADGE
	db -1 ; end

