;@ path: engine/events/hidden_events/bench_guys
;@ def PrintBenchGuyText()
;@ A man on a Pokémon Center bench: BenchGuyTextPointers lists (map, facing direction, text). When the player
;@ faces another way, the search goes on one byte off (the text byte is read as the next map).
;@ test: skip prints a text
PrintBenchGuyText:
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> p = BenchGuyTextPointers
	ld hl, BenchGuyTextPointers
	ld a, [wCurMap]
	ld b, a
;>@loop while True:
.loop
;>     m = mem[p]
;>@inc     p += 1
	ld a, [hli]
;>     if m == 0xFF: return
	cp -1
	ret z
;>     if m != wCurMap:
;>@skip         p += 2
;>@cont         continue
	cp b
	jr z, .match
;=@skip
	inc hl
	inc hl
;=@cont
	jr .loop
.match
;>     facing = mem[p]
;>     p += 1
	ld a, [hli]
	ld b, a
;>     if facing == wSpritePlayerStateData1FacingDirection:
	ld a, [wSpritePlayerStateData1FacingDirection]
	cp b

	; bug: an 'inc hl' instruction is needed before looping back. When trying to
	; talk to a bench guy from above, this Sprite Facing test will fail, and the
	; next loop iteration will be misaligned within BenchGuyTextPointers table.
	; As a result, the routine will miss the terminator byte, and continue to
	; process data beyond the table boundary.
	; It seems that it will only return after starting to read data from VRAM
	; (According to Pan Docs, during PPU mode 3, reads return garbage value,
	; usually $FF).
	jr nz, .loop ; player isn't facing the bench guy
;>         PrintPredefTextID(mem[p])
;>         return
	ld a, [hl]
	jp PrintPredefTextID


;@ path: engine/events/hidden_events/bench_guys
BenchGuyTextPointers:
	; map id, player facing direction, predef text
	db VIRIDIAN_POKECENTER, SPRITE_FACING_LEFT
	db (ViridianCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db PEWTER_POKECENTER, SPRITE_FACING_LEFT
	db (PewterCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db CERULEAN_POKECENTER, SPRITE_FACING_LEFT
	db (CeruleanCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db LAVENDER_POKECENTER, SPRITE_FACING_LEFT
	db (LavenderCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db VERMILION_POKECENTER, SPRITE_FACING_LEFT
	db (VermilionCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db CELADON_POKECENTER, SPRITE_FACING_LEFT
	db (CeladonCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db CELADON_HOTEL, SPRITE_FACING_LEFT
	db (CeladonCityHotelText_id - TextPredefs) / 2 + 1
	db FUCHSIA_POKECENTER, SPRITE_FACING_LEFT
	db (FuchsiaCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db CINNABAR_POKECENTER, SPRITE_FACING_LEFT
	db (CinnabarIslandPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db SAFFRON_POKECENTER, SPRITE_FACING_LEFT
	db (SaffronCityPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db MT_MOON_POKECENTER, SPRITE_FACING_LEFT
	db (MtMoonPokecenterBenchGuyText_id - TextPredefs) / 2 + 1
	db ROCK_TUNNEL_POKECENTER, SPRITE_FACING_LEFT
