SECTION "Battle Engine 11", ROMX

;@ path: engine/battle/decrement_pp
;@ def DecrementPP(move: de)
;@ Use up one PP of the player's selected move - in battle and, unless transformed, in the party too. Struggle,
;@ the later turns of multi-turn moves and Rage cost nothing.
;@ test: wPlayerMonNumber = rand(0, 5); wPlayerMoveListIndex = rand(0, 3)
DecrementPP:
; after using a move, decrement pp in battle and (if not transformed?) in party
;> if mem[move] == STRUGGLE:
;>     return
	ld a, [de]
	cp STRUGGLE
	ret z                ; if the pokemon is using "struggle", there's nothing to do
	                     ; we don't decrement PP for "struggle"
;> if wPlayerBattleStatus1 & (1 << STORING_ENERGY | 1 << THRASHING_ABOUT | 1 << ATTACKING_MULTIPLE_TIMES):
;>     return
	ld hl, wPlayerBattleStatus1
	ld a, [hli]          ; load the wPlayerBattleStatus1 pokemon status flags and increment hl to load the
	                     ; wPlayerBattleStatus2 status flags later
	and (1 << STORING_ENERGY) | (1 << THRASHING_ABOUT) | (1 << ATTACKING_MULTIPLE_TIMES)
	ret nz               ; if any of these statuses are true, don't decrement PP
;> if wPlayerBattleStatus2 >> USING_RAGE & 1:
;>     return
	bit USING_RAGE, [hl]
	ret nz               ; don't decrement PP either if Pokemon is using Rage
;> mem[wBattleMonPP + wPlayerMoveListIndex] -= 1
	ld hl, wBattleMonPP  ; PP of first move (in battle)

; decrement PP in the battle struct
	call .DecrementPP

; decrement PP in the party struct
;> if wPlayerBattleStatus3 >> TRANSFORMED & 1:
;>     return
	ld a, [wPlayerBattleStatus3]
	bit TRANSFORMED, a
	ret nz               ; Return if transformed. Pokemon Red stores the "current pokemon's" PP
	                     ; separately from the "Pokemon in your party's" PP.  This is
	                     ; duplication -- in all cases *other* than Pokemon with Transform.
	                     ; Normally, this means we have to go on and make the same
	                     ; modification to the "party's pokemon" PP that we made to the
	                     ; "current pokemon's" PP.  But, if we're dealing with a Transformed
	                     ; Pokemon, it has separate PP for the move set that it copied from
	                     ; its opponent, which is *not* the same as its real PP as part of your
	                     ; party.  So we return, and don't do that part.

;> pp = AddNTimes(wPartyMon1PP, PARTYMON_STRUCT_LENGTH, wPlayerMonNumber)
	ld hl, wPartyMon1PP  ; PP of first move (in party)
	ld a, [wPlayerMonNumber] ; which mon in party is active
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes       ; calculate address of the mon to modify
.DecrementPP:
;> mem[pp + wPlayerMoveListIndex] -= 1
	ld a, [wPlayerMoveListIndex] ; which move (0, 1, 2, 3) did we use?
	ld c, a
	ld b, 0
	add hl, bc           ; calculate the address in memory of the PP we need to decrement
	                     ; based on the move chosen.
	dec [hl]             ; Decrement PP
	ret
;@ path: gfx/version
Version_GFX:
	; 10 tiles
	db $00, $00, $00, $f0, $d9, $f3, $db, $d9, $00, $00, $00, $03, $cf, $5b, $9b, $cf
	db $00, $00, $00, $78, $c3, $db, $db, $7b, $00, $00, $00, $00, $dc, $35, $39, $1c
	db $00, $00, $00, $00, $ee, $ad, $cd, $ed, $00, $00, $00, $cc, $cc, $cd, $79, $30
	db $00, $00, $00, $00, $ef, $ac, $cc, $ec, $00, $00, $00, $01, $3c, $71, $1d, $79
	db $00, $00, $00, $80, $1c, $b6, $b6, $9c, $00, $00, $00, $00, $e0, $d0, $d0, $d0
;@ path: gfx/version
Version_GFXEnd:


SECTION "bank1C", ROMX

;@ path: engine/movie/splash
;@ def LoadShootingStarGraphics()
;@ Set up the Game Freak logo scene: sprite palettes, the star tiles, and the OAM entries of the logo and the
;@ big shooting star.
;@ test: skip copies to VRAM over several VBlanks
LoadShootingStarGraphics:
;> rOBP0 = 0xF9
	ld a, $f9
	ldh [rOBP0], a
;> rOBP1 = 0xA4
	ld a, $a4
	ldh [rOBP1], a
;> CopyVideoData(vChars1 + 0x20 * TILE_SIZE, MoveAnimationTiles1 + 3 * TILE_SIZE, BANK(MoveAnimationTiles1), 1)    # star, top left
	ld de, MoveAnimationTiles1 + TILE_SIZE * 3 ; star tile (top left quadrant)
	ld hl, vChars1 + TILE_SIZE * $20
	ld bc, ((BANK(MoveAnimationTiles1)) & $ff) << 8 + ((1) & $ff)
	call CopyVideoData
;> CopyVideoData(vChars1 + 0x21 * TILE_SIZE, MoveAnimationTiles1 + 19 * TILE_SIZE, BANK(MoveAnimationTiles1), 1)   # star, bottom left
	ld de, MoveAnimationTiles1 + TILE_SIZE * 19 ; star tile (bottom left quadrant)
	ld hl, vChars1 + TILE_SIZE * $21
	ld bc, ((BANK(MoveAnimationTiles1)) & $ff) << 8 + ((1) & $ff)
	call CopyVideoData
;> CopyVideoData(vChars1 + 0x22 * TILE_SIZE, FallingStar, BANK(FallingStar), (FallingStarEnd - FallingStar) // TILE_SIZE)
	ld de, FallingStar
	ld hl, vChars1 + TILE_SIZE * $22
	ld bc, ((BANK(FallingStar)) & $ff) << 8 + (((FallingStarEnd - FallingStar) / TILE_SIZE) & $ff)
	call CopyVideoData
;> CopyData(GameFreakLogoOAMData, addr(wShadowOAMSprite24), GameFreakLogoOAMDataEnd - GameFreakLogoOAMData)
	ld hl, GameFreakLogoOAMData
	ld de, wShadowOAMSprite24
	ld bc, GameFreakLogoOAMDataEnd - GameFreakLogoOAMData
	call CopyData
;> CopyData(GameFreakShootingStarOAMData, addr(wShadowOAM), GameFreakShootingStarOAMDataEnd - GameFreakShootingStarOAMData)
	ld hl, GameFreakShootingStarOAMData
	ld de, wShadowOAM
	ld bc, GameFreakShootingStarOAMDataEnd - GameFreakShootingStarOAMData
	jp CopyData

;@ path: engine/movie/splash
;@ def AnimateShootingStar() -> carry
;@ The Game Freak logo scene: a big star shoots down and left across the screen, the logo flashes three times,
;@ then six waves of small stars fall from it. Any button cuts it short (carry).
;@ test: skip waits for frames
AnimateShootingStar:
;> LoadShootingStarGraphics()
	call LoadShootingStarGraphics
;> PlaySound(SFX_SHOOTING_STAR)
	ld a, SFX_SHOOTING_STAR
	call PlaySound

; Move the big star down and left across the screen.
;> star = addr(wShadowOAM)
	ld hl, wShadowOAM
	ld bc, (($a0) & $ff) << 8 + (($4) & $ff)
;> while True:
.bigStarLoop
;>     for i in range(4):                            # the star's four sprites: 4 down, 4 left
	push hl
	push bc
.bigStarInnerLoop
;>         mem[star + i * OBJ_SIZE] = u8(mem[star + i * OBJ_SIZE] + 4)
	ld a, [hl] ; Y
	add 4
	ld [hli], a
;>         mem[star + i * OBJ_SIZE + 1] = u8(mem[star + i * OBJ_SIZE + 1] - 4)
	ld a, [hl] ; X
	add -4
	ld [hli], a
;>         # on to the next tile
	inc hl
	inc hl
	dec c
	jr nz, .bigStarInnerLoop
;>     if CheckForUserInterruption(1):
;>         return True
	ld c, 1
	call CheckForUserInterruption
	pop bc
	pop hl
	ret c
;>     if mem[star] == 0xA0:                         # off the bottom
;>         break
	ld a, [hl]
	cp 80
	jr nz, .next
	jr .bigStarLoop
.next
	cp b
	jr nz, .bigStarLoop

; Clear big star OAM.
;> for i in range(4):
	ld hl, wShadowOAMSprite00YCoord
	ld c, 4
	ld de, OBJ_SIZE
.clearOAMLoop
;>     mem[addr(wShadowOAMSprite00YCoord) + i * OBJ_SIZE] = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [hl], SCREEN_HEIGHT_PX + OAM_Y_OFS
	add hl, de
	dec c
	jr nz, .clearOAMLoop

; Make Gamefreak logo flash.
;> for _ in range(3):
	ld b, 3
.flashLogoLoop
;>     rOBP0 = (rOBP0 >> 2 | rOBP0 << 6) & 0xFF       # rotate the logo's palette
	ld hl, rOBP0
	rrc [hl]
	rrc [hl]
;>     if CheckForUserInterruption(10):
;>         return True
	ld c, 10
	call CheckForUserInterruption
	ret c
	dec b
	jr nz, .flashLogoLoop

; Copy 24 instances of the small stars OAM data.
; Note that their coordinates put them off-screen.
;> # 24 copies of the small stars' OAM data, off screen at first
;> at = addr(wShadowOAM)
	ld de, wShadowOAM
;> for _ in range(24):
	ld a, 24
.initSmallStarsOAMLoop
;>     CopyData(SmallStarsOAM, at, SmallStarsOAMEnd - SmallStarsOAM)
;>     at += SmallStarsOAMEnd - SmallStarsOAM
	push af
	ld hl, SmallStarsOAM
	ld bc, SmallStarsOAMEnd - SmallStarsOAM
	call CopyData
;>     # (counting the copies)
	pop af
	dec a
	jr nz, .initSmallStarsOAMLoop

; Animate the small stars falling from the Gamefreak logo.
;> wMoveDownSmallStarsOAMCount = 0
	xor a
	ld [wMoveDownSmallStarsOAMCount], a
;> for wave in range(6):
	ld hl, SmallStarsWaveCoordsPointerTable
	ld c, 6
.smallStarsLoop
;>     coords = mem16[SmallStarsWaveCoordsPointerTable + 2 * wave]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;>     oam = addr(wShadowOAMSprite20)
	push bc
	push hl
	ld hl, wShadowOAMSprite20
;>     complete = True
;>     for i in range(4):                            # bring in a new wave of 4 stars
	ld c, 4
.smallStarsInnerLoop ; introduce new wave of 4 small stars OAM entries
;>         if mem[coords] == 0xFF:
;>@notyet             complete = False
;>@stop             break
	ld a, [de]
	cp -1
	jr z, .next2
;>         mem[oam] = mem[coords]
	ld [hli], a ; Y
;>         mem[oam + 1] = mem[coords + 1]
	inc de
	ld a, [de]
	ld [hli], a ; X
;>         coords += 2
;>         oam += OBJ_SIZE
	inc de
	inc hl
	inc hl
	dec c
	jr nz, .smallStarsInnerLoop
;>     if complete and wMoveDownSmallStarsOAMCount != 24:
	ld a, [wMoveDownSmallStarsOAMCount]
	cp 24
	jr z, .next2
;>         wMoveDownSmallStarsOAMCount += 6          # 4 would do; the other 2 are off screen
	add 6 ; should be 4, but the extra 2 aren't visible on screen
	ld [wMoveDownSmallStarsOAMCount], a
.next2
;>     interrupted = MoveDownSmallStars()
	call MoveDownSmallStars
	push af

; shift the existing OAM entries down to make room for the next wave
;>     CopyData(addr(wShadowOAMSprite04), addr(wShadowOAM), OBJ_SIZE * 20)     # make room for the next wave
	ld hl, wShadowOAMSprite04
	ld de, wShadowOAM
	ld bc, OBJ_SIZE * 20
	call CopyData

;>     if interrupted:
;>         return True
	pop af
	pop hl
	pop bc
	ret c
	dec c
	jr nz, .smallStarsLoop
;> return False
	and a
	ret

;@ path: engine/movie/splash
SmallStarsOAM:
	db (0 * TILE_WIDTH) % $100 + 0, (0 * TILE_WIDTH) % $100 + 0, $A2, OAM_PRIO | OAM_PAL1
;@ path: engine/movie/splash
SmallStarsOAMEnd:

;@ path: engine/movie/splash
SmallStarsWaveCoordsPointerTable:
	dw SmallStarsWave1Coords
	dw SmallStarsWave2Coords
	dw SmallStarsWave3Coords
	dw SmallStarsWave4Coords
	dw SmallStarsEmptyWave
	dw SmallStarsEmptyWave

; The stars that fall from the Gamefreak logo come in 4 waves of 4 OAM entries.
; These arrays contain the Y and X coordinates of each OAM entry.

;@ path: engine/movie/splash
SmallStarsWave1Coords:
	db $68, $30
	db $68, $40
	db $68, $58
	db $68, $78
;@ path: engine/movie/splash
SmallStarsWave2Coords:
	db $68, $38
	db $68, $48
	db $68, $60
	db $68, $70
;@ path: engine/movie/splash
SmallStarsWave3Coords:
	db $68, $34
	db $68, $4C
	db $68, $54
	db $68, $64
;@ path: engine/movie/splash
SmallStarsWave4Coords:
	db $68, $3C
	db $68, $5C
	db $68, $6C
	db $68, $74
;@ path: engine/movie/splash
SmallStarsEmptyWave:
	db -1 ; end

;@ path: engine/movie/splash
;@ def MoveDownSmallStars() -> carry
;@ Move the falling small stars down 8 pixels, a pixel every 3 frames, blinking their lower stars. Any button
;@ stops it (carry).
;@ test: skip waits for frames
MoveDownSmallStars:
;> for _ in range(8):
	ld b, 8
.loop
;>     oam = addr(wShadowOAMSprite23)
;>     for _ in range(wMoveDownSmallStarsOAMCount):
	ld hl, wShadowOAMSprite23
	ld a, [wMoveDownSmallStarsOAMCount]
	ld de, -4
	ld c, a
.innerLoop
;>         mem[oam] = u8(mem[oam] + 1)               # Y
	inc [hl] ; Y
;>         oam -= OBJ_SIZE
	add hl, de
	dec c
	jr nz, .innerLoop
; Toggle the palette so that the lower star in the small stars tile blinks in
; and out.
;>     rOBP1 ^= 0b10100000
	ldh a, [rOBP1]
	xor %10100000
	ldh [rOBP1], a

;>     if CheckForUserInterruption(3):
;>         return True
	ld c, 3
	call CheckForUserInterruption
	ret c
	dec b
	jr nz, .loop
;> return False
	ret

