;@ path: engine/movie/hall_of_fame
;@ def AnimateHallOfFame()
;@ Entering the Hall of Fame: each party Pokémon in turn scrolls in with name, level and types (and is written
;@ into the Hall of Fame record), then the player with play time, money and the Pokédex rating.
;@ test: skip runs the Hall of Fame scene
AnimateHallOfFame:
;> HoFFadeOutScreenAndMusic()
	call HoFFadeOutScreenAndMusic
;> ClearScreen()
	call ClearScreen
;> DelayFrames(100)
	ld c, 100
	call DelayFrames
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> DisableLCD()
	call DisableLCD
;> FillMemory(vBGMap0, 2 * TILEMAP_AREA, charmap(' ')[0])
	ld hl, vBGMap0
	ld bc, 2 * TILEMAP_AREA
	ld a, ' '
	call FillMemory
;> EnableLCD()
	call EnableLCD
;> rLCDC |= 1 << B_LCDC_BG_MAP
	ld hl, rLCDC
	set B_LCDC_BG_MAP, [hl]
;> FillMemory(addr(wHallOfFame), HOF_TEAM, 0)
	xor a
	ld hl, wHallOfFame
	ld bc, HOF_TEAM
	call FillMemory
;> wUpdateSpritesEnabled = 0
	xor a
	ld [wUpdateSpritesEnabled], a
;> hTileAnimations = 0
	ldh [hTileAnimations], a
;> wSpriteFlipped = 0
	ld [wSpriteFlipped], a
;> wLetterPrintingDelayFlags = 0                     # no text delay
	ld [wLetterPrintingDelayFlags], a ; no delay
;> wHoFMonOrPlayer = 0                               # Pokémon
	ld [wHoFMonOrPlayer], a ; mon
;> hAutoBGTransferEnabled = 1
	inc a
	ldh [hAutoBGTransferEnabled], a
;> if wNumHoFTeams != 0xFF:
	ld hl, wNumHoFTeams
	ld a, [hl]
	inc a
	jr z, .skipInc ; don't wrap around to 0
;>     wNumHoFTeams += 1
	inc [hl]
.skipInc
;> hWY = 0x90
	ld a, $90
	ldh [hWY], a
;> PlayMusic(MUSIC_HALL_OF_FAME, BANK(Music_HallOfFame))
	ld c, BANK(Music_HallOfFame)
	ld a, MUSIC_HALL_OF_FAME
	call PlayMusic
;> index = 0
	ld hl, wPartySpecies
	ld c, $ff
;> while wPartySpecies[index] != 0xFF:
.partyMonLoop
	ld a, [hli]
	cp $ff
	jr z, .doneShowingParty
	inc c
	push hl
	push bc
;>     wHoFMonSpecies = wPartySpecies[index]
	ld [wHoFMonSpecies], a
;>     wHoFPartyMonIndex = index
	ld a, c
	ld [wHoFPartyMonIndex], a
;>     wHoFMonLevel = mem[wPartyMon1Level + index * PARTYMON_STRUCT_LENGTH]
	ld hl, wPartyMon1Level
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld a, [hl]
	ld [wHoFMonLevel], a
;>     HoFShowMonOrPlayer()
	call HoFShowMonOrPlayer
;>     HoFDisplayAndRecordMonInfo()
	call HoFDisplayAndRecordMonInfo
;>     DelayFrames(80)
	ld c, 80
	call DelayFrames
;>     TextBoxBorder(coord(2, 13), 3, 14)
	ld hl, (13) * SCREEN_WIDTH + (2) + wTileMap
	ld b, 3
	ld c, 14
	call TextBoxBorder
;>     PlaceString(HallOfFameText, coord(4, 15))
	ld hl, (15) * SCREEN_WIDTH + (4) + wTileMap
	ld de, HallOfFameText
	call PlaceString
;>     DelayFrames(180)
	ld c, 180
	call DelayFrames
;>     GBFadeOutToWhite()
	call GBFadeOutToWhite
;>     index += 1
	pop bc
	pop hl
	jr .partyMonLoop
.doneShowingParty
;> mem[addr(wHallOfFame) + index * HOF_MON] = 0xFF   # end of the team
	ld a, c
	inc a
	ld hl, wHallOfFame
	ld bc, HOF_MON
	call AddNTimes
	ld [hl], $ff
;> SaveHallOfFameTeams()
	call SaveHallOfFameTeams
;> wHoFMonSpecies = 0
	xor a
	ld [wHoFMonSpecies], a
;> wHoFMonOrPlayer = 1                               # the player
	inc a
	ld [wHoFMonOrPlayer], a ; player
;> HoFShowMonOrPlayer()
	call HoFShowMonOrPlayer
;> HoFDisplayPlayerStats()
	call HoFDisplayPlayerStats
;> HoFFadeOutScreenAndMusic()
	call HoFFadeOutScreenAndMusic
;> hWY = 0
	xor a
	ldh [hWY], a
;> rLCDC &= ~(1 << B_LCDC_BG_MAP) & 0xFF
	ld hl, rLCDC
	res B_LCDC_BG_MAP, [hl]
	ret

;@ path: engine/movie/hall_of_fame
HallOfFameText:
	db "HALL OF FAME@"

;@ path: engine/movie/hall_of_fame
;@ def HoFShowMonOrPlayer()
;@ Show the Pokémon wHoFMonSpecies (or the player): its back picture scrolls in from the right and leaves to
;@ the left, then the front picture scrolls in from the left.
;@ test: skip waits for frames
HoFShowMonOrPlayer:
;> ClearScreen()
	call ClearScreen
;> hSCY = 0xD0
	ld a, $d0
	ldh [hSCY], a
;> hSCX = 0xC0
	ld a, $c0
	ldh [hSCX], a
;> wCurPartySpecies = wHoFMonSpecies
	ld a, [wHoFMonSpecies]
	ld [wCurPartySpecies], a
;> wCurSpecies = wHoFMonSpecies
	ld [wCurSpecies], a
;> wBattleMonSpecies2 = wHoFMonSpecies
	ld [wBattleMonSpecies2], a
;> wWholeScreenPaletteMonSpecies = wHoFMonSpecies
	ld [wWholeScreenPaletteMonSpecies], a
;> if wHoFMonOrPlayer:
	ld a, [wHoFMonOrPlayer]
	and a
	jr z, .showMon
; show player
;>     HoFLoadPlayerPics()
	call HoFLoadPlayerPics
	jr .next1
;> else:
.showMon
;>     GetMonHeader()
;>     LoadFrontSpriteByMonIndex(coord(12, 5))
	ld hl, (5) * SCREEN_WIDTH + (12) + wTileMap
	call GetMonHeader
	call LoadFrontSpriteByMonIndex
;>     LoadMonBackPic()                              # through the predef table
	ld a, (LoadMonBackPicPredef - PredefPointers) / 3
	call Predef
.next1
;> RunPaletteCommand(SET_PAL_POKEMON_WHOLE_SCREEN)   # with c = 0: the Pokémon's palette
	ld b, SET_PAL_POKEMON_WHOLE_SCREEN
	ld c, 0
	call RunPaletteCommand
;> rBGP = 0b11100100
	ld a, %11100100
	ldh [rBGP], a
;> HoFLoadMonPlayerPicTileIDs(0x31)                  # the back picture
	ld c, $31 ; back pic
	call HoFLoadMonPlayerPicTileIDs
;> step = 4
	ld d, $a0
	ld e, 4
;> if wOnSGB:
	ld a, [wOnSGB]
	and a
	jr z, .next2
;>     step = 8                                  # slower on the SGB
	sla e ; scroll more slowly on SGB
.next2
;>@sp1 while True:                                   # .ScrollPic below: the back picture leaves to the left
;>@sp2     DelayFrame()
	call .ScrollPic ; scroll back pic left
;>@sp3     hSCX = u8(hSCX + step)
;>@sp4     if hSCX == 0xA0:
;>@sp5         break
;> hSCY = 0
	xor a
	ldh [hSCY], a
;> HoFLoadMonPlayerPicTileIDs(0)                     # the front picture
	ld c, a ; front pic
	call HoFLoadMonPlayerPicTileIDs
;> while True:                                   # the front picture comes in
	ld d, 0
	ld e, -4
; scroll front pic right

.ScrollPic
;>     DelayFrame()
	call DelayFrame
;>     hSCX = u8(hSCX - 4)
	ldh a, [hSCX]
	add e
	ldh [hSCX], a
;>     if hSCX == 0:
;>         break
	cp d
	jr nz, .ScrollPic
	ret

;@ path: engine/movie/hall_of_fame
;@ def HoFDisplayAndRecordMonInfo()
;@ Show the Hall of Fame Pokémon's name, level and types, and write it into the record.
;@ test: skip prints and plays a cry
HoFDisplayAndRecordMonInfo:
;> GetPartyMonName(wHoFPartyMonIndex, addr(wPartyMonNicks))
	ld a, [wHoFPartyMonIndex]
	ld hl, wPartyMonNicks
	call GetPartyMonName
;> HoFDisplayMonInfo()
	call HoFDisplayMonInfo
;> HoFRecordMonInfo()
	jp HoFRecordMonInfo

;@ path: engine/movie/hall_of_fame
;@ def HoFDisplayMonInfo()
;@ A box with the Pokémon's nickname, level and types, and its cry.
;@ test: skip prints and plays a cry
HoFDisplayMonInfo:
;> TextBoxBorder(coord(0, 2), 9, 10)
	ld hl, (2) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 9
	ld c, 10
	call TextBoxBorder
;> PlaceString(HoFMonInfoText, coord(2, 6))
	ld hl, (6) * SCREEN_WIDTH + (2) + wTileMap
	ld de, HoFMonInfoText
	call PlaceString
;> end, _ = PlaceString(addr(wNameBuffer), coord(1, 4))
	ld hl, (4) * SCREEN_WIDTH + (1) + wTileMap
	ld de, wNameBuffer
	call PlaceString
;> PrintLevelCommon(coord(8, 7), end & 0xFF, wHoFMonLevel)      # the digit count is what PlaceString left in c
	ld a, [wHoFMonLevel]
	ld hl, (7) * SCREEN_WIDTH + (8) + wTileMap
	call PrintLevelCommon
;> wCurSpecies = wHoFMonSpecies
	ld a, [wHoFMonSpecies]
	ld [wCurSpecies], a
;> PrintMonType()                                    # through the predef table, at coord(3, 9)
	ld hl, (9) * SCREEN_WIDTH + (3) + wTileMap
	ld a, (PrintMonTypePredef - PredefPointers) / 3
	call Predef
;> PlayCry(wHoFMonSpecies)
	ld a, [wHoFMonSpecies]
	jp PlayCry

;@ path: engine/movie/hall_of_fame
HoFMonInfoText:
	db   "LEVEL/"
	db "<NEXT>", "TYPE1/"
	db "<NEXT>", "TYPE2/@"

;@ path: engine/movie/hall_of_fame
;@ def HoFLoadPlayerPics()
;@ Load the player's front picture and the back picture scaled to double size, and use the front tile IDs.
;@ test: skip decompresses into VRAM
HoFLoadPlayerPics:
;> UncompressSpriteFromDE(BANK(RedPicFront), RedPicFront)
	ld de, RedPicFront
	ld a, BANK(RedPicFront)
	call UncompressSpriteFromDE
;> CopyData(sSpriteBuffer1, sSpriteBuffer0, 2 * SPRITEBUFFERSIZE)
	ld hl, sSpriteBuffer1
	ld de, sSpriteBuffer0
	ld bc, 2 * SPRITEBUFFERSIZE
	call CopyData
;> InterlaceMergeSpriteBuffers(vFrontPic)
	ld de, vFrontPic
	call InterlaceMergeSpriteBuffers
;> UncompressSpriteFromDE(BANK(RedPicBack), RedPicBack)
	ld de, RedPicBack
	ld a, BANK(RedPicBack)
	call UncompressSpriteFromDE
;> ScaleSpriteByTwo()                                # through the predef table
	ld a, (ScaleSpriteByTwoPredef - PredefPointers) / 3
	call Predef
;> InterlaceMergeSpriteBuffers(vBackPic)
	ld de, vBackPic
	call InterlaceMergeSpriteBuffers
;> HoFLoadMonPlayerPicTileIDs(1)
	ld c, $1

;@ path: engine/movie/hall_of_fame
;@ def HoFLoadMonPlayerPicTileIDs(first: c)
;@ Put the 7x7 picture tile IDs from `first` on at coord(12, 5).
;@ test: skip goes through the predef table
HoFLoadMonPlayerPicTileIDs:
; c = base tile ID
;> CopyTileIDsFromList()                             # through the predef table: TILEMAP_MON_PIC from `first` at coord(12, 5)
	ld b, TILEMAP_MON_PIC
	ld hl, (5) * SCREEN_WIDTH + (12) + wTileMap
	ld a, (CopyTileIDsFromListPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/movie/hall_of_fame
;@ def HoFDisplayPlayerStats()
;@ The player's name, play time and money, then the Pokédex seen / owned counts and Prof. Oak's rating.
;@ test: skip prints texts with delays
HoFDisplayPlayerStats:
;> set_event(EVENT_HALL_OF_FAME_DEX_RATING)
	ld hl, wEventFlags + $0
	set (EVENT_HALL_OF_FAME_DEX_RATING) % 8, [hl]
;> DisplayDexRating()                                # through the predef table
	ld a, (DisplayDexRatingPredef - PredefPointers) / 3
	call Predef
;> TextBoxBorder(coord(0, 4), 6, 10)
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 6
	ld c, 10
	call TextBoxBorder
;> TextBoxBorder(coord(5, 0), 2, 9)
	ld hl, (0) * SCREEN_WIDTH + (5) + wTileMap
	ld b, 2
	ld c, 9
	call TextBoxBorder
;> PlaceString(addr(wPlayerName), coord(7, 2))
	ld hl, (2) * SCREEN_WIDTH + (7) + wTileMap
	ld de, wPlayerName
	call PlaceString
;> PlaceString(HoFPlayTimeText, coord(1, 6))
	ld hl, (6) * SCREEN_WIDTH + (1) + wTileMap
	ld de, HoFPlayTimeText
	call PlaceString
;> end = PrintNumber(addr(wPlayTimeHours), coord(5, 7), 1, 3)
	ld hl, (7) * SCREEN_WIDTH + (5) + wTileMap
	ld de, wPlayTimeHours
	ld bc, ((1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> mem[end] = 0x6D                                   # ':'
	ld [hl], $6d
;> PrintNumber(addr(wPlayTimeMinutes), end + 1, LEADING_ZEROES | 1, 2)
	inc hl
	ld de, wPlayTimeMinutes
	ld bc, ((LEADING_ZEROES | 1) & $ff) << 8 + ((2) & $ff)
	call PrintNumber
;> PlaceString(HoFMoneyText, coord(1, 9))
	ld hl, (9) * SCREEN_WIDTH + (1) + wTileMap
	ld de, HoFMoneyText
	call PlaceString
;> PrintBCDNumber(addr(wPlayerMoney), coord(4, 10), 3 | LEADING_ZEROES | MONEY_SIGN)
	ld hl, (10) * SCREEN_WIDTH + (4) + wTileMap
	ld de, wPlayerMoney
	ld c, 3 | LEADING_ZEROES | MONEY_SIGN
	call PrintBCDNumber
;> HoFPrintTextAndDelay(DexSeenOwnedText)
	ld hl, DexSeenOwnedText
	call HoFPrintTextAndDelay
;> HoFPrintTextAndDelay(DexRatingText)
	ld hl, DexRatingText
	call HoFPrintTextAndDelay
;> HoFPrintTextAndDelay(addr(wDexRatingText))
	ld hl, wDexRatingText

;@ path: engine/movie/hall_of_fame
;@ def HoFPrintTextAndDelay(text: hl)
;@ Print a text, then wait two seconds.
;@ test: skip prints a text
HoFPrintTextAndDelay:
;> PrintText(text)
;> DelayFrames(120)
	call PrintText
	ld c, 120
	jp DelayFrames

;@ path: engine/movie/hall_of_fame
HoFPlayTimeText:
	db "PLAY TIME@"

;@ path: engine/movie/hall_of_fame
HoFMoneyText:
	db "MONEY@"

;@ path: engine/movie/hall_of_fame
DexSeenOwnedText:
	db TX_FAR
	dw _DexSeenOwnedText
	db BANK(_DexSeenOwnedText)
	db TX_END

;@ path: engine/movie/hall_of_fame
DexRatingText:
	db TX_FAR
	dw _DexRatingText
	db BANK(_DexRatingText)
	db TX_END

;@ path: engine/movie/hall_of_fame
;@ def HoFRecordMonInfo()
;@ Write the Hall of Fame Pokémon into entry wHoFPartyMonIndex of the record: species, level, nickname.
;@ test: wHoFPartyMonIndex = rand(0, 5)
HoFRecordMonInfo:
;> entry = addr(wHallOfFame) + wHoFPartyMonIndex * HOF_MON
	ld hl, wHallOfFame
	ld bc, HOF_MON
	ld a, [wHoFPartyMonIndex]
	call AddNTimes
;> mem[entry] = wHoFMonSpecies
	ld a, [wHoFMonSpecies]
	ld [hli], a
;> mem[entry + 1] = wHoFMonLevel
	ld a, [wHoFMonLevel]
	ld [hli], a
;> CopyData(addr(wNameBuffer), entry + 2, NAME_LENGTH)
	ld e, l
	ld d, h
	ld hl, wNameBuffer
	ld bc, NAME_LENGTH
	jp CopyData

;@ path: engine/movie/hall_of_fame
;@ def HoFFadeOutScreenAndMusic()
;@ Fade the music out (step every 10 frames) and the screen to white.
;@ test: skip waits for frames
HoFFadeOutScreenAndMusic:
;> wAudioFadeOutCounterReloadValue = 10          # a music step every 10 frames
	ld a, 10
	ld [wAudioFadeOutCounterReloadValue], a
;> wAudioFadeOutCounter = 10
	ld [wAudioFadeOutCounter], a
;> wAudioFadeOutControl = 0xFF
	ld a, $ff
	ld [wAudioFadeOutControl], a
;> GBFadeOutToWhite()
	jp GBFadeOutToWhite
;@ path: engine/overworld/healing_machine
;@ def AnimateHealingMachine()
;@ The Pokémon Center healing machine: the music fades out, one Poké Ball per party Pokémon appears on the
;@ machine with a jingle each, then the "healed" tune plays while the balls flash, and the screen goes back
;@ to normal.
AnimateHealingMachine:
;> CopyVideoData(addr(vChars0) + 0x7C * TILE_SIZE, PokeCenterFlashingMonitorAndHealBall, BANK(PokeCenterFlashingMonitorAndHealBall), 3)
	ld de, PokeCenterFlashingMonitorAndHealBall
	ld hl, vChars0 + TILE_SIZE * $7c
	; should be 2
	ld bc, ((BANK(PokeCenterFlashingMonitorAndHealBall)) & $ff) << 8 + ((3) & $ff)
	call CopyVideoData
;> savedEnabled = wUpdateSpritesEnabled
	ld hl, wUpdateSpritesEnabled
	ld a, [hl]
	push af
;> wUpdateSpritesEnabled = 0xFF
	ld [hl], $ff
	push hl
;> savedPalette = rOBP1
	ldh a, [rOBP1]
	push af
;> rOBP1 = 0xE0
	ld a, $e0
	ldh [rOBP1], a
;> oam, src = CopyHealingMachineOAM(wShadowOAMSprite33, PokeCenterOAMData)     # the flashing monitor
	ld hl, wShadowOAMSprite33
	ld de, PokeCenterOAMData
	call CopyHealingMachineOAM
;> wAudioFadeOutControl = 4
	ld a, 4
	ld [wAudioFadeOutControl], a
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
.waitLoop
;> while wAudioFadeOutControl:                  # counted down by the sound engine each frame
;>     wait_vblank_flag()    # the audio engine runs in the VBlank interrupt
	ld a, [wAudioFadeOutControl]
	and a ; is fade-out finished?
	jr nz, .waitLoop ; if not, check again
;> for _ in range(wPartyCount or 256):
	ld a, [wPartyCount]
	ld b, a
.partyLoop
;>     oam, src = CopyHealingMachineOAM(oam, src)
	call CopyHealingMachineOAM
;>     PlaySound(SFX_HEALING_MACHINE)
	ld a, SFX_HEALING_MACHINE
	call PlaySound
;>     DelayFrames(30)
	ld c, 30
	call DelayFrames
	dec b
	jr nz, .partyLoop
;> wAudioSavedROMBank = wAudioROMBank
;> if wAudioROMBank == BANK(Audio3_UpdateMusic):
	ld a, [wAudioROMBank]
	cp BANK("Audio Engine 3")
	ld [wAudioSavedROMBank], a
	jr nz, .next
;>     wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;>     PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;>     wAudioROMBank = BANK(Music_PkmnHealed)
	ld a, BANK(Music_PkmnHealed)
	ld [wAudioROMBank], a
.next
;> wNewSoundID = MUSIC_PKMN_HEALED
	ld a, MUSIC_PKMN_HEALED
	ld [wNewSoundID], a
;> PlaySound(MUSIC_PKMN_HEALED)
	call PlaySound
;> FlashSprite8Times(0x28)
	ld d, $28
	call FlashSprite8Times
.waitLoop2
;> while wChannelSoundIDs[0] == MUSIC_PKMN_HEALED:     # until the tune has ended
;>     wait_vblank_flag()    # the audio engine runs in the VBlank interrupt
	ld a, [wChannelSoundIDs]
	cp MUSIC_PKMN_HEALED ; is the healed music still playing?
	jr z, .waitLoop2 ; if so, check gain
;> DelayFrames(32)
	ld c, 32
	call DelayFrames
;> rOBP1 = savedPalette
	pop af
	ldh [rOBP1], a
;> wUpdateSpritesEnabled = savedEnabled
	pop hl
	pop af
	ld [hl], a
;> UpdateSprites()
	jp UpdateSprites

;@ path: engine/overworld/healing_machine
PokeCenterFlashingMonitorAndHealBall:
	db $00, $00, $00, $00, $7e, $00, $7e, $00, $7e, $00, $00, $00, $00, $00, $00, $00
	db $00, $00, $00, $00, $0c, $0c, $12, $1e, $21, $3f, $33, $2d, $1e, $12, $0c, $0c

;@ path: engine/overworld/healing_machine
PokeCenterOAMData:
	; heal machine monitor
	db (4 * TILE_WIDTH) % $100 + 4, (6 * TILE_WIDTH) % $100 + 4, $7c, OAM_PAL1
	; poke balls 1-6
	db (5 * TILE_WIDTH) % $100 + 3, (6 * TILE_WIDTH) % $100 + 0, $7d, OAM_PAL1
	db (5 * TILE_WIDTH) % $100 + 3, (7 * TILE_WIDTH) % $100 + 0, $7d, OAM_PAL1 | OAM_XFLIP
	db (6 * TILE_WIDTH) % $100 + 0, (6 * TILE_WIDTH) % $100 + 0, $7d, OAM_PAL1
	db (6 * TILE_WIDTH) % $100 + 0, (7 * TILE_WIDTH) % $100 + 0, $7d, OAM_PAL1 | OAM_XFLIP
	db (6 * TILE_WIDTH) % $100 + 5, (6 * TILE_WIDTH) % $100 + 0, $7d, OAM_PAL1
	db (6 * TILE_WIDTH) % $100 + 5, (7 * TILE_WIDTH) % $100 + 0, $7d, OAM_PAL1 | OAM_XFLIP

; d = value to xor with palette
;@ path: engine/overworld/healing_machine
;@ def FlashSprite8Times(mask: d)
;@ Flash the sprites 8 times by toggling the bits `mask` of the sprite palette every 10 frames.
FlashSprite8Times:
;>@loop for _ in range(8):
	ld b, 8
.loop
;>     rOBP1 = rOBP1 ^ mask
	ldh a, [rOBP1]
	xor d
	ldh [rOBP1], a
;>     DelayFrames(10)
	ld c, 10
	call DelayFrames
;=@loop
	dec b
	jr nz, .loop
	ret

;@ path: engine/overworld/healing_machine
;@ def CopyHealingMachineOAM(dest: hl, src: de) -> (hl, de)
;@ Copy one 4-byte OAM entry and return both pointers moved past it.
;@ test: dest = rand_ram(4); src = rand_ram(4)
CopyHealingMachineOAM:
; copy one OAM entry and advance the pointers
;> mem[dest] = mem[src]
	ld a, [de]
	inc de
	ld [hli], a
;> mem[dest + 1] = mem[src + 1]
	ld a, [de]
	inc de
	ld [hli], a
;> mem[dest + 2] = mem[src + 2]
	ld a, [de]
	inc de
	ld [hli], a
;> mem[dest + 3] = mem[src + 3]
	ld a, [de]
	inc de
	ld [hli], a
;> return dest + 4, src + 4
	ret
;@ path: engine/overworld/player_animations
;@ def EnterMapAnim()
;@ The player's arrival after a warp by Fly, Teleport, Dig/Escape Rope or a dungeon warp: the bird lands, or
;@ the player spins down from the top of the screen (and, when not on a warp pad or hole, spins in place
;@ slower and slower). Then the saved facing direction and screen position come back.
EnterMapAnim::
;> InitFacingDirectionList()
	call InitFacingDirectionList
;> wSpritePlayerStateData1YPixels = 0xEC        # above the top of the screen
	ld a, $ec
	ld [wSpritePlayerStateData1YPixels], a
;> Delay3()
	call Delay3
	push hl
;> GBFadeInFromWhite()
	call GBFadeInFromWhite
;> flew = wStatusFlags7 & (1 << BIT_USED_FLY)
	ld hl, wStatusFlags7
	bit BIT_USED_FLY, [hl]
;> wStatusFlags7 = wStatusFlags7 & ~(1 << BIT_USED_FLY) & 0xFF
	res BIT_USED_FLY, [hl]
;> if flew:
;>@fly1     CopyVideoData(addr(vNPCSprites), BirdSprite, BANK(BirdSprite), 12)
;>@fly2     LoadBirdSpriteGraphics()
;>@fly3     PlaySound(SFX_FLY)
;>@fly4     wFlyAnimUsingCoordList = 0
;>@fly5     wFlyAnimCounter = 12
;>@fly6     wFlyAnimBirdSpriteImageIndex = 8         # facing right
;>@fly7     DoFlyAnimation(FlyAnimationEnterScreenCoords)
;>@fly8     LoadPlayerSpriteGraphics()
;>@fly9     PlayDefaultMusic()
;> else:
	jr nz, .flyAnimation
;>     PlaySound(SFX_TELEPORT_ENTER_1)
	ld a, SFX_TELEPORT_ENTER_1
	call PlaySound
;>     dungeon = wStatusFlags6 & (1 << BIT_DUNGEON_WARP)
	ld hl, wStatusFlags6
	bit BIT_DUNGEON_WARP, [hl]
;>     wStatusFlags6 = wStatusFlags6 & ~(1 << BIT_DUNGEON_WARP) & 0xFF
	res BIT_DUNGEON_WARP, [hl]
;>     if dungeon:
;>@dw1         DelayFrames(50)
;>@dw2         PlayerSpinWhileMovingDown()
;>     else:
	pop hl
	jr nz, .dungeonWarpAnimation
;>         PlayerSpinWhileMovingDown()
	call PlayerSpinWhileMovingDown
;>         PlaySound(SFX_TELEPORT_ENTER_2)
	ld a, SFX_TELEPORT_ENTER_2
	call PlaySound
;>         if IsPlayerStandingOnWarpPadOrHole() == 0:
	call IsPlayerStandingOnWarpPadOrHole
	ld a, b
	and a
	jr nz, .done
; if the player is not standing on a warp pad or hole
;>             wPlayerSpinInPlaceAnimFrameDelay = 0
	ld hl, wPlayerSpinInPlaceAnimFrameDelay
	xor a
	ld [hli], a ; wPlayerSpinInPlaceAnimFrameDelay
;>             wPlayerSpinInPlaceAnimFrameDelayDelta = 1
	inc a
	ld [hli], a ; wPlayerSpinInPlaceAnimFrameDelayDelta
;>             wPlayerSpinInPlaceAnimFrameDelayEndValue = 8
	ld a, $8
	ld [hli], a ; wPlayerSpinInPlaceAnimFrameDelayEndValue
;>             wPlayerSpinInPlaceAnimSoundID = 0xFF     # no sound
	ld [hl], $ff ; wPlayerSpinInPlaceAnimSoundID
;>             PlayerSpinInPlace(addr(wFacingDirectionList))
	ld hl, wFacingDirectionList
	call PlayerSpinInPlace
.restoreDefaultMusic
;>             PlayDefaultMusic()
	call PlayDefaultMusic
.done
;> RestoreFacingDirectionAndYScreenPos()
	jp RestoreFacingDirectionAndYScreenPos
.dungeonWarpAnimation
;=@dw1
	ld c, 50
	call DelayFrames
;=@dw2
	call PlayerSpinWhileMovingDown
	jr .done
.flyAnimation
;=@fly1
	pop hl
	ld de, BirdSprite
	ld hl, vNPCSprites
	ld bc, ((BANK(BirdSprite)) & $ff) << 8 + (($0c) & $ff)
	call CopyVideoData
;=@fly2
	call LoadBirdSpriteGraphics
;=@fly3
	ld a, SFX_FLY
	call PlaySound
;=@fly4
	ld hl, wFlyAnimUsingCoordList
	xor a ; is using coord list
	ld [hli], a ; wFlyAnimUsingCoordList
;=@fly5
	ld a, 12
	ld [hli], a ; wFlyAnimCounter
;=@fly6
	ld [hl], $8 ; wFlyAnimBirdSpriteImageIndex (facing right)
;=@fly7
	ld de, FlyAnimationEnterScreenCoords
	call DoFlyAnimation
;=@fly8
	call LoadPlayerSpriteGraphics
;=@fly9
	jr .restoreDefaultMusic

;@ path: engine/overworld/player_animations
FlyAnimationEnterScreenCoords:
; y, x pairs
; This is the sequence of screen coordinates used by the overworld
; Fly animation when the player is entering a map.
	db $05, $98
	db $0F, $90
	db $18, $88
	db $20, $80
	db $27, $78
	db $2D, $70
	db $32, $68
	db $36, $60
	db $39, $58
	db $3B, $50
	db $3C, $48
	db $3C, $40

;@ path: engine/overworld/player_animations
;@ def PlayerSpinWhileMovingDown()
;@ Spin the player down the screen 16 pixels per step until y $3C (the normal standing position).
PlayerSpinWhileMovingDown:
;> wPlayerSpinWhileMovingUpOrDownAnimDeltaY = 0x10
	ld hl, wPlayerSpinWhileMovingUpOrDownAnimDeltaY
	ld a, $10
	ld [hli], a ; wPlayerSpinWhileMovingUpOrDownAnimDeltaY
;> wPlayerSpinWhileMovingUpOrDownAnimMaxY = 0x3C
	ld a, $3c
	ld [hli], a ; wPlayerSpinWhileMovingUpOrDownAnimMaxY
;> wPlayerSpinWhileMovingUpOrDownAnimFrameDelay = GetPlayerTeleportAnimFrameDelay()
	call GetPlayerTeleportAnimFrameDelay
	ld [hl], a ; wPlayerSpinWhileMovingUpOrDownAnimFrameDelay
;> PlayerSpinWhileMovingUpOrDown(addr(wPlayerSpinWhileMovingUpOrDownAnimFrameDelay))    # hl is left there
	jp PlayerSpinWhileMovingUpOrDown

;@ path: engine/overworld/player_animations
;@ def _LeaveMapAnim()
;@ The player's departure: on a warp pad spin up off the screen; through a hole drop out of sight; by
;@ Teleport/Escape (to the last Pokémon Center) first spin in place faster and faster, then up; by Fly the
;@ bird flaps in place and flies off. The screen fades to white at the end.
;@ test: skip StopMusic waits for the sound engine (run by VBlank) to finish the fade
_LeaveMapAnim::
;> InitFacingDirectionList()
	call InitFacingDirectionList
;> kind = IsPlayerStandingOnWarpPadOrHole()
	call IsPlayerStandingOnWarpPadOrHole
	ld a, b
;> if kind == 0:
;>@stop     StopMusic(4)
;>@esc     if not wStatusFlags6 & (1 << BIT_ESCAPE_WARP):          # Fly
;>@f1         LoadBirdSpriteGraphics()
;>@f2         wFlyAnimUsingCoordList = 0xFF        # flap in place
;>@f3         wFlyAnimCounter = 8
;>@f4         wFlyAnimBirdSpriteImageIndex = 0xC
;>@f5         DoFlyAnimation(0)                    # no coordinates needed
;>@f6         PlaySound(SFX_FLY)
;>@f7         wFlyAnimUsingCoordList = 0
;>@f8         wFlyAnimCounter = 0xC
;>@f9         wFlyAnimBirdSpriteImageIndex = 0xC   # facing right
;>@f10         DoFlyAnimation(FlyAnimationScreenCoords1)
;>@f11         DelayFrames(40)
;>@f12         wFlyAnimCounter = 11
;>@f13         wFlyAnimBirdSpriteImageIndex = 8     # facing left
;>@f14         DoFlyAnimation(FlyAnimationScreenCoords2)
;>@f15         GBFadeOutToWhite()
;>@f16         RestoreFacingDirectionAndYScreenPos()
;>@f17         return
;>@s1     wPlayerSpinInPlaceAnimFrameDelay = 16
;>@s2     wPlayerSpinInPlaceAnimFrameDelayDelta = 0xFF        # -1: faster and faster
;>@s3     wPlayerSpinInPlaceAnimFrameDelayEndValue = 0
;>@s4     wPlayerSpinInPlaceAnimSoundID = SFX_TELEPORT_EXIT_2
;>@s5     PlayerSpinInPlace(addr(wFacingDirectionList))
	and a
	jr z, .playerNotStandingOnWarpPadOrHole
;> elif kind != 1: return LeaveMapThroughHoleAnim()     # a hole
	dec a
	jp nz, LeaveMapThroughHoleAnim
.spinWhileMovingUp
;> PlaySound(SFX_TELEPORT_EXIT_1)
	ld a, SFX_TELEPORT_EXIT_1
	call PlaySound
;> wPlayerSpinWhileMovingUpOrDownAnimDeltaY = 0xF0     # -16
	ld hl, wPlayerSpinWhileMovingUpOrDownAnimDeltaY
	ld a, -$10
	ld [hli], a ; wPlayerSpinWhileMovingUpOrDownAnimDeltaY
;> wPlayerSpinWhileMovingUpOrDownAnimMaxY = 0xEC
	ld a, $ec
	ld [hli], a ; wPlayerSpinWhileMovingUpOrDownAnimMaxY
;> wPlayerSpinWhileMovingUpOrDownAnimFrameDelay = GetPlayerTeleportAnimFrameDelay()
	call GetPlayerTeleportAnimFrameDelay
	ld [hl], a ; wPlayerSpinWhileMovingUpOrDownAnimFrameDelay
;> PlayerSpinWhileMovingUpOrDown(addr(wPlayerSpinWhileMovingUpOrDownAnimFrameDelay))
	call PlayerSpinWhileMovingUpOrDown
;> if IsPlayerStandingOnWarpPadOrHole() != 1:  # extra pause when not on a warp pad
	call IsPlayerStandingOnWarpPadOrHole
	ld a, b
	dec a
	jr z, .playerStandingOnWarpPad
; if not standing on a warp pad, there is an extra delay
;>     DelayFrames(10)
	ld c, 10
	call DelayFrames
.playerStandingOnWarpPad
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> RestoreFacingDirectionAndYScreenPos()
	jp RestoreFacingDirectionAndYScreenPos
.playerNotStandingOnWarpPadOrHole
;=@stop
	ld a, $4
	call StopMusic
;=@esc
	ld a, [wStatusFlags6]
	bit BIT_ESCAPE_WARP, a
	jr z, .flyAnimation
; if going to the last used pokemon center
;=@s1
	ld hl, wPlayerSpinInPlaceAnimFrameDelay
	ld a, 16
	ld [hli], a ; wPlayerSpinInPlaceAnimFrameDelay
;=@s2
	ld a, -1
	ld [hli], a ; wPlayerSpinInPlaceAnimFrameDelayDelta
;=@s3
	xor a
	ld [hli], a ; wPlayerSpinInPlaceAnimFrameDelayEndValue
;=@s4
	ld [hl], SFX_TELEPORT_EXIT_2 ; wPlayerSpinInPlaceAnimSoundID
;=@s5
	ld hl, wFacingDirectionList
	call PlayerSpinInPlace
	jr .spinWhileMovingUp
.flyAnimation
;=@f1
	call LoadBirdSpriteGraphics
;=@f2
	ld hl, wFlyAnimUsingCoordList
	ld a, $ff ; is not using coord list (flap in place)
	ld [hli], a ; wFlyAnimUsingCoordList
;=@f3
	ld a, 8
	ld [hli], a ; wFlyAnimCounter
;=@f4
	ld [hl], $c ; wFlyAnimBirdSpriteImageIndex
;=@f5
	call DoFlyAnimation
;=@f6
	ld a, SFX_FLY
	call PlaySound
;=@f7
	ld hl, wFlyAnimUsingCoordList
	xor a ; is using coord list
	ld [hli], a ; wFlyAnimUsingCoordList
;=@f8
	ld a, $c
	ld [hli], a ; wFlyAnimCounter
;=@f9
	ld [hl], $c ; wFlyAnimBirdSpriteImageIndex (facing right)
;=@f10
	ld de, FlyAnimationScreenCoords1
	call DoFlyAnimation
;=@f11
	ld c, 40
	call DelayFrames
;=@f12
	ld hl, wFlyAnimCounter
	ld a, 11
	ld [hli], a ; wFlyAnimCounter
;=@f13
	ld [hl], $8 ; wFlyAnimBirdSpriteImageIndex (facing left)
;=@f14
	ld de, FlyAnimationScreenCoords2
	call DoFlyAnimation
;=@f15
	call GBFadeOutToWhite
;=@f16
	jp RestoreFacingDirectionAndYScreenPos

;@ path: engine/overworld/player_animations
FlyAnimationScreenCoords1:
; y, x pairs
; This is the sequence of screen coordinates used by the first part
; of the Fly overworld animation.
	db $3C, $48
	db $3C, $50
	db $3B, $58
	db $3A, $60
	db $39, $68
	db $37, $70
	db $37, $78
	db $33, $80
	db $30, $88
	db $2D, $90
	db $2A, $98
	db $27, $A0

;@ path: engine/overworld/player_animations
FlyAnimationScreenCoords2:
; y, x pairs
; This is the sequence of screen coordinates used by the second part
; of the Fly overworld animation.
	db $1A, $90
	db $19, $80
	db $17, $70
	db $15, $60
	db $12, $50
	db $0F, $40
	db $0C, $30
	db $09, $20
	db $05, $10
	db $00, $00

	db $F0, $00

;@ path: engine/overworld/player_animations
;@ def LeaveMapThroughHoleAnim()
;@ The player falls through a hole: the upper half of the sprite moves down 8 pixels while the lower half
;@ disappears, two frames later the rest is gone, and the screen fades to white.
LeaveMapThroughHoleAnim:
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a ; disable UpdateSprites
	; shift upper half of player's sprite down 8 pixels and hide lower half
;> mem[wShadowOAMSprite02TileID] = mem[wShadowOAMSprite00TileID]
	ld a, [wShadowOAMSprite00TileID]
	ld [wShadowOAMSprite02TileID], a
;> mem[wShadowOAMSprite03TileID] = mem[wShadowOAMSprite01TileID]
	ld a, [wShadowOAMSprite01TileID]
	ld [wShadowOAMSprite03TileID], a
;> mem[wShadowOAMSprite00YCoord] = SCREEN_HEIGHT_PX + OAM_Y_OFS    # off screen
	ld a, SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [wShadowOAMSprite00YCoord], a
;> mem[wShadowOAMSprite01YCoord] = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [wShadowOAMSprite01YCoord], a
;> DelayFrames(2)
	ld c, 2
	call DelayFrames
	; hide upper half of player's sprite
;> mem[wShadowOAMSprite02YCoord] = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld a, SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [wShadowOAMSprite02YCoord], a
;> mem[wShadowOAMSprite03YCoord] = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [wShadowOAMSprite03YCoord], a
;> GBFadeOutToWhite()
	call GBFadeOutToWhite
;> wUpdateSpritesEnabled = 1
	ld a, $1
	ld [wUpdateSpritesEnabled], a ; enable UpdateSprites
;> RestoreFacingDirectionAndYScreenPos()
	jp RestoreFacingDirectionAndYScreenPos

;@ path: engine/overworld/player_animations
;@ def DoFlyAnimation(coords: de) -> de
;@ Flap the bird's wings wFlyAnimCounter times, every 3 frames. Unless wFlyAnimUsingCoordList is $FF, each
;@ flap also moves the bird to the next (y, x) screen position from `coords`.
;@ test: coords = rand_ram(40); wFlyAnimCounter = rand(1, 20)
DoFlyAnimation:
;> while True:
;>     wFlyAnimBirdSpriteImageIndex = wFlyAnimBirdSpriteImageIndex ^ 1
	ld a, [wFlyAnimBirdSpriteImageIndex]
	xor $1 ; make the bird flap its wings
	ld [wFlyAnimBirdSpriteImageIndex], a
;>     mem[wSpritePlayerStateData1ImageIndex] = wFlyAnimBirdSpriteImageIndex
	ld [wSpritePlayerStateData1ImageIndex], a
;>     Delay3()
	call Delay3
;>     if wFlyAnimUsingCoordList != 0xFF:
	ld a, [wFlyAnimUsingCoordList]
	cp $ff
	jr z, .skipCopyingCoords ; if the bird is flapping its wings in place
;>         mem[wSpritePlayerStateData1YPixels] = mem[coords]
	ld hl, wSpritePlayerStateData1YPixels
	ld a, [de]
	inc de
	ld [hli], a ; y
;>         mem[wSpritePlayerStateData1XPixels] = mem[coords + 1]
;>         coords += 2
	inc hl
	ld a, [de]
	inc de
	ld [hl], a ; x
.skipCopyingCoords
;>     wFlyAnimCounter = u8(wFlyAnimCounter - 1)
	ld a, [wFlyAnimCounter]
	dec a
	ld [wFlyAnimCounter], a
;>     if wFlyAnimCounter == 0:
;>         return coords
	jr nz, DoFlyAnimation
	ret

;@ path: engine/overworld/player_animations
;@ def LoadBirdSpriteGraphics()
;@ Put the bird's standing and flying frames where the player's sprite graphics normally are.
LoadBirdSpriteGraphics:
;> CopyVideoData(addr(vNPCSprites), BirdSprite, BANK(BirdSprite), 12)
	ld de, BirdSprite
	ld hl, vNPCSprites
	ld bc, ((BANK(BirdSprite)) & $ff) << 8 + ((12) & $ff)
	call CopyVideoData
;> CopyVideoData(addr(vNPCSprites2), BirdSprite + 12 * TILE_SIZE, BANK(BirdSprite), 12)
	ld de, BirdSprite + TILE_SIZE * 12 ; moving animation sprite
	ld hl, vNPCSprites2
	ld bc, ((BANK(BirdSprite)) & $ff) << 8 + ((12) & $ff)
	jp CopyVideoData

;@ path: engine/overworld/player_animations
;@ def InitFacingDirectionList() -> hl
;@ Prepare a spin: save the player's facing direction and screen y, copy the spinning order (down, left,
;@ up, right) to wFacingDirectionList and return the entry of the current direction.
;@ test: mem[0xC102] = 4 * rand(0, 3)
InitFacingDirectionList:
;> wSavedPlayerFacingDirection = mem[wSpritePlayerStateData1ImageIndex]
	ld a, [wSpritePlayerStateData1ImageIndex] ; (image index is locked to standing images)
	ld [wSavedPlayerFacingDirection], a
;> wSavedPlayerScreenY = mem[wSpritePlayerStateData1YPixels]
	ld a, [wSpritePlayerStateData1YPixels]
	ld [wSavedPlayerScreenY], a
;> CopyData(PlayerSpinningFacingOrder, addr(wFacingDirectionList), OBJ_SIZE)
	ld hl, PlayerSpinningFacingOrder
	ld de, wFacingDirectionList
	ld bc, OBJ_SIZE
	call CopyData
;> p = addr(wFacingDirectionList)
	ld a, [wSpritePlayerStateData1ImageIndex] ; (image index is locked to standing images)
	ld hl, wFacingDirectionList
; find the place in the list that matches the current facing direction
.loop
;> while mem[p] != mem[wSpritePlayerStateData1ImageIndex]:
;>     p += 1
	cp [hl]
	inc hl
	jr nz, .loop
;> return p
	dec hl
	ret

;@ path: engine/overworld/player_animations
PlayerSpinningFacingOrder:
; The order of the direction the player's sprite is facing when teleporting
; away. Creates a spinning effect.
	db SPRITE_FACING_DOWN, SPRITE_FACING_LEFT, SPRITE_FACING_UP, SPRITE_FACING_RIGHT

;@ path: engine/overworld/player_animations
;@ def SpinPlayerSprite(entry: hl) -> hl
;@ One step of a spin: show the facing direction at `entry` and rotate wFacingDirectionList one place
;@ forward.
;@ test: entry = wFacingDirectionList + rand(0, 3)
SpinPlayerSprite:
; copy the current value from the list into the sprite data and rotate the list
;> wSpritePlayerStateData1ImageIndex = mem[entry]
	ld a, [hl]
	ld [wSpritePlayerStateData1ImageIndex], a ; (image index is locked to standing images)
;> CopyData(addr(wFacingDirectionList), addr(wFacingDirectionList) - 1, OBJ_SIZE)
	push hl
	ld hl, wFacingDirectionList
	ld de, wFacingDirectionList - 1
	ld bc, OBJ_SIZE
	call CopyData
;> mem[addr(wFacingDirectionList) + 3] = mem[addr(wFacingDirectionList) - 1]
	ld a, [wFacingDirectionList - 1]
	ld [wFacingDirectionList + 3], a
;> return entry
	pop hl
	ret

;@ path: engine/overworld/player_animations
;@ def PlayerSpinInPlace(entry: hl)
;@ Spin the player in place, waiting wPlayerSpinInPlaceAnimFrameDelay frames between turns. The delay
;@ changes by the delta each turn until it reaches the end value; the sound (unless $FF) plays whenever the
;@ last delay was a multiple of 4.
PlayerSpinInPlace:
;> while True:
;>     SpinPlayerSprite(entry)
	call SpinPlayerSprite
;>     delay = wPlayerSpinInPlaceAnimFrameDelay
	ld a, [wPlayerSpinInPlaceAnimFrameDelay]
	ld c, a
;>     if delay & 3 == 0 and wPlayerSpinInPlaceAnimSoundID != 0xFF:
	and $3
	jr nz, .skipPlayingSound
; when the last delay was a multiple of 4, play a sound if there is one
	ld a, [wPlayerSpinInPlaceAnimSoundID]
	cp $ff
;>         PlaySound(wPlayerSpinInPlaceAnimSoundID)
	call nz, PlaySound
.skipPlayingSound
;>     wPlayerSpinInPlaceAnimFrameDelay = u8(delay + wPlayerSpinInPlaceAnimFrameDelayDelta)
	ld a, [wPlayerSpinInPlaceAnimFrameDelayDelta]
	add c
	ld [wPlayerSpinInPlaceAnimFrameDelay], a
;>     if wPlayerSpinInPlaceAnimFrameDelay == wPlayerSpinInPlaceAnimFrameDelayEndValue:
;>         return
	ld c, a
	ld a, [wPlayerSpinInPlaceAnimFrameDelayEndValue]
	cp c
	ret z
;>     DelayFrames(wPlayerSpinInPlaceAnimFrameDelay)
	call DelayFrames
	jr PlayerSpinInPlace

;@ path: engine/overworld/player_animations
;@ def PlayerSpinWhileMovingUpOrDown(entry: hl)
;@ Spin the player while moving the sprite by the y delta per turn, until it reaches the end y.
PlayerSpinWhileMovingUpOrDown:
;> while True:
;>     SpinPlayerSprite(entry)
	call SpinPlayerSprite
;>     y = u8(mem[wSpritePlayerStateData1YPixels] + wPlayerSpinWhileMovingUpOrDownAnimDeltaY)
	ld a, [wPlayerSpinWhileMovingUpOrDownAnimDeltaY]
	ld c, a
	ld a, [wSpritePlayerStateData1YPixels]
	add c
;>     mem[wSpritePlayerStateData1YPixels] = y
	ld [wSpritePlayerStateData1YPixels], a
;>     if y == wPlayerSpinWhileMovingUpOrDownAnimMaxY:
;>         return
	ld c, a
	ld a, [wPlayerSpinWhileMovingUpOrDownAnimMaxY]
	cp c
	ret z
;>     DelayFrames(wPlayerSpinWhileMovingUpOrDownAnimFrameDelay)
	ld a, [wPlayerSpinWhileMovingUpOrDownAnimFrameDelay]
	ld c, a
	call DelayFrames
	jr PlayerSpinWhileMovingUpOrDown

;@ path: engine/overworld/player_animations
;@ def RestoreFacingDirectionAndYScreenPos()
;@ Put back the facing direction and screen y saved by InitFacingDirectionList.
RestoreFacingDirectionAndYScreenPos:
;> mem[wSpritePlayerStateData1YPixels] = wSavedPlayerScreenY
;> mem[wSpritePlayerStateData1ImageIndex] = wSavedPlayerFacingDirection
	ld a, [wSavedPlayerScreenY]
	ld [wSpritePlayerStateData1YPixels], a
	ld a, [wSavedPlayerFacingDirection]
	ld [wSpritePlayerStateData1ImageIndex], a ; (image index is locked to standing images)
	ret

; if SGB, 2 frames, else 3 frames
;@ path: engine/overworld/player_animations
;@ def GetPlayerTeleportAnimFrameDelay() -> a
;@ Frames between spin steps: 2 on a Super Game Boy, else 3.
;@ test: wOnSGB = rand(0, 1)
GetPlayerTeleportAnimFrameDelay:
;> return u8((wOnSGB ^ 1) + 2)
	ld a, [wOnSGB]
	xor $1
	inc a
	inc a
	ret

;@ path: engine/overworld/player_animations
;@ def IsPlayerStandingOnWarpPadOrHole() -> b
;@ What is the player standing on: 0 nothing special, 1 a warp pad, 2 a hole? WarpPadAndHoleData lists
;@ (tileset, tile, kind). The answer is also stored in wStandingOnWarpPadOrHole.
;@ test: wCurMapTileset = rand(0, NUM_TILESETS - 1)
IsPlayerStandingOnWarpPadOrHole::
;> kind = 0
	ld b, 0
;> p = WarpPadAndHoleData
	ld hl, WarpPadAndHoleData
	ld a, [wCurMapTileset]
	ld c, a
.loop
;>@loop while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
	jr z, .done
;>     if mem[p] == wCurMapTileset and mem[coord(8, 9)] == mem[p + 1]:
	cp c
	jr nz, .nextEntry
	ld a, [(9) * SCREEN_WIDTH + (8) + wTileMap]
	cp [hl]
	jr z, .foundMatch
.nextEntry
;=@step
	inc hl
	inc hl
;=@loop
	jr .loop
.foundMatch
;>         kind = mem[p + 2]
;>         break
;>@step     p += 3
	inc hl
	ld b, [hl]
.done
;> wStandingOnWarpPadOrHole = kind
	ld a, b
	ld [wStandingOnWarpPadOrHole], a
;> return kind
	ret

;@ path: engine/overworld/player_animations
WarpPadAndHoleData:
	; tileset id, tile id, value for [wStandingOnWarpPadOrHole]
	db FACILITY, $20, 1 ; warp pad
	db FACILITY, $11, 2 ; hole
	db CAVERN,   $22, 2 ; hole
	db INTERIOR, $55, 1 ; warp pad
	db -1 ; end

;@ path: engine/overworld/player_animations
;@ def FishingAnim()
;@ The player casts the rod: fishing graphics and the rod sprite for the facing direction, a wait, then
;@ "Not even a nibble!", "Looks like there's nothing here." or, on a bite, a shake and an exclamation
;@ bubble before "Oh! It's a bite!".
FishingAnim:
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> wMovementFlags = wMovementFlags | 1 << BIT_LEDGE_OR_FISHING
	ld hl, wMovementFlags
	set BIT_LEDGE_OR_FISHING, [hl]
;> CopyVideoData(addr(vNPCSprites), RedSprite, BANK(RedSprite), 12)
	ld de, RedSprite
	ld hl, vNPCSprites + TILE_SIZE * $00
	ld bc, ((BANK(RedSprite)) & $ff) << 8 + ((12) & $ff)
	call CopyVideoData
;> LoadAnimSpriteGfx(RedFishingTiles, 4)
	ld a, $4
	ld hl, RedFishingTiles
	call LoadAnimSpriteGfx
;> rod = FishingRodOAM + wSpritePlayerStateData1ImageIndex     # the entry for the facing direction
	ld a, [wSpritePlayerStateData1ImageIndex]
	ld c, a
	ld b, $0
	ld hl, FishingRodOAM
	add hl, bc
;> CopyData(rod, addr(wShadowOAMSprite39), OBJ_SIZE)
	ld de, wShadowOAMSprite39
	ld bc, OBJ_SIZE
	call CopyData
;> DelayFrames(100)
	ld c, 100
	call DelayFrames
;> if wRodResponse[0] == 0:
	ld a, [wRodResponse]
	and a
;>     text = NoNibbleText
	ld hl, NoNibbleText
	jr z, .done
;> elif wRodResponse[0] == 2:
	cp $2
;>     text = NothingHereText
	ld hl, NothingHereText
	jr z, .done

; there was a bite

; shake the player's sprite vertically
;> else:                                        # a bite: shake the player and the rod
;>     for _ in range(10):
	ld b, 10
.loop
;>         wSpritePlayerStateData1YPixels = wSpritePlayerStateData1YPixels ^ 1
	ld hl, wSpritePlayerStateData1YPixels
	call .ShakePlayerSprite
;>         wShadowOAMSprite39 = wShadowOAMSprite39 ^ 1
	ld hl, wShadowOAMSprite39
	call .ShakePlayerSprite
;>         Delay3()
	call Delay3
	dec b
	jr nz, .loop

; If the player is facing up, hide the fishing rod so it doesn't overlap with
; the exclamation bubble that will be shown next.
;>     if wSpritePlayerStateData1ImageIndex == SPRITE_FACING_UP:    # keep the rod out of the bubble
	ld a, [wSpritePlayerStateData1ImageIndex] ; (image index is locked to standing images)
	cp SPRITE_FACING_UP
	jr nz, .skipHidingFishingRod
;>         wShadowOAMSprite39YCoord = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld a, SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [wShadowOAMSprite39YCoord], a

.skipHidingFishingRod
;>     wEmotionBubbleSpriteIndex = 0            # the player
	ld hl, wEmotionBubbleSpriteIndex
	xor a
	ld [hli], a ; player's sprite
;>     wWhichEmotionBubble = EXCLAMATION_BUBBLE
	ld [hl], a ; EXCLAMATION_BUBBLE
;>     EmotionBubble()                          # a predef
	ld a, (EmotionBubblePredef - PredefPointers) / 3
	call Predef

; If the player is facing up, unhide the fishing rod.
;>     if wSpritePlayerStateData1ImageIndex == SPRITE_FACING_UP:
	ld a, [wSpritePlayerStateData1ImageIndex] ; (image index is locked to standing images)
	cp SPRITE_FACING_UP
	jr nz, .skipUnhidingFishingRod
;>         wShadowOAMSprite39YCoord = 0x44
	ld a, $44
	ld [wShadowOAMSprite39YCoord], a

.skipUnhidingFishingRod
;>     text = ItsABiteText
	ld hl, ItsABiteText

.done
;> PrintText(text)
	call PrintText
;> wMovementFlags = wMovementFlags & ~(1 << BIT_LEDGE_OR_FISHING) & 0xFF
	ld hl, wMovementFlags
	res BIT_LEDGE_OR_FISHING, [hl]
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
	ret

.ShakePlayerSprite
	ld a, [hl]
	xor $1
	ld [hl], a
	ret

;@ path: engine/overworld/player_animations
NoNibbleText:
	db TX_FAR
	dw _NoNibbleText
	db BANK(_NoNibbleText)
	db TX_END

;@ path: engine/overworld/player_animations
NothingHereText:
	db TX_FAR
	dw _NothingHereText
	db BANK(_NothingHereText)
	db TX_END

;@ path: engine/overworld/player_animations
ItsABiteText:
	db TX_FAR
	dw _ItsABiteText
	db BANK(_ItsABiteText)
	db TX_END

;@ path: engine/overworld/player_animations
FishingRodOAM:
; specifies how the fishing rod should be drawn on the screen
	; down
	db (11 * TILE_WIDTH) % $100 + 3, (9 * TILE_WIDTH) % $100 + 4, $fd, 0
	; up
	db (8 * TILE_WIDTH) % $100 + 4, (9 * TILE_WIDTH) % $100 + 4, $fd, 0
	; left
	db (10 * TILE_WIDTH) % $100 + 0, (8 * TILE_WIDTH) % $100 + 0, $fe, 0
	; right
	db (10 * TILE_WIDTH) % $100 + 0, (11 * TILE_WIDTH) % $100 + 0, $fe, OAM_XFLIP


;@ path: engine/overworld/player_animations
RedFishingTiles:
	dw RedFishingTilesFront
	db 2
	db BANK(RedFishingTilesFront)
	dw vNPCSprites + TILE_SIZE * $02
	dw RedFishingTilesBack
	db 2
	db BANK(RedFishingTilesBack)
	dw vNPCSprites + TILE_SIZE * $06
	dw RedFishingTilesSide
	db 2
	db BANK(RedFishingTilesSide)
	dw vNPCSprites + TILE_SIZE * $0a
	dw RedFishingRodTiles
	db 3
	db BANK(RedFishingRodTiles)
	dw vNPCSprites + TILE_SIZE * $fd

;@ path: engine/overworld/player_animations
;@ def _HandleMidJump()
;@ One frame of a ledge jump: the player's sprite follows the 16 heights of PlayerJumpingYScreenCoords. After
;@ the last one, once the step is done, the jump ends: buttons and the jumping flags are cleared.
;@ test: wPlayerJumpingYScreenCoordsIndex = rand(0, 15)
_HandleMidJump::
;> i = wPlayerJumpingYScreenCoordsIndex
	ld a, [wPlayerJumpingYScreenCoordsIndex]
	ld c, a
;> if u8(i + 1) < 0x10:
	inc a
	cp $10
	jr nc, .finishedJump
;>     wPlayerJumpingYScreenCoordsIndex = u8(i + 1)
	ld [wPlayerJumpingYScreenCoordsIndex], a
;>     mem[wSpritePlayerStateData1YPixels] = mem[PlayerJumpingYScreenCoords + i]
	ld b, 0
	ld hl, PlayerJumpingYScreenCoords
	add hl, bc
	ld a, [hl]
	ld [wSpritePlayerStateData1YPixels], a
;>     return
	ret
.finishedJump
;> if wWalkCounter:
;>     return
	ld a, [wWalkCounter]
	cp 0
	ret nz
;> UpdateSprites()
	call UpdateSprites
;> Delay3()
	call Delay3
;> hJoyHeld = 0
	xor a
	ldh [hJoyHeld], a
;> hJoyPressed = 0
	ldh [hJoyPressed], a
;> hJoyReleased = 0
	ldh [hJoyReleased], a
;> wPlayerJumpingYScreenCoordsIndex = 0
	ld [wPlayerJumpingYScreenCoordsIndex], a
;> wMovementFlags = wMovementFlags & ~(1 << BIT_LEDGE_OR_FISHING) & 0xFF
	ld hl, wMovementFlags
	res BIT_LEDGE_OR_FISHING, [hl]
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_SCRIPTED_MOVEMENT_STATE) & 0xFF
	ld hl, wStatusFlags5
	res BIT_SCRIPTED_MOVEMENT_STATE, [hl]
;> wJoyIgnore = 0
	xor a
	ld [wJoyIgnore], a
	ret

;@ path: engine/overworld/player_animations
PlayerJumpingYScreenCoords:
; Sequence of y screen coordinates for player's sprite when jumping over a ledge.
	db $38, $36, $34, $32, $31, $30, $30, $30, $31, $32, $33, $34, $36, $38, $3C, $3C
;@ path: engine/battle/ghost_marowak_anim
;@ def MarowakAnim()
;@ The Pokémon Tower ghost is unmasked by the Silph Scope: a sprite copy of the ghost flashes and fades out,
;@ revealing Marowak, which fades in.
MarowakAnim:
; animate the ghost being unveiled as a Marowak
;> rOBP1 = 0xE4
	ld a, $e4
	ldh [rOBP1], a
;> CopyMonPicFromBGToSpriteVRAM()
	call CopyMonPicFromBGToSpriteVRAM ; cover the BG ghost pic with a sprite ghost pic that looks the same
; now that the ghost pic is being displayed using sprites, clear the ghost pic from the BG tilemap
;> ClearScreenArea(coord(12, 0), 7, 7)
	ld hl, (0) * SCREEN_WIDTH + (12) + wTileMap
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
	call ClearScreenArea
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a ; disable BG transfer so we don't see the Marowak too soon
; replace ghost pic with Marowak in BG
;> wChangeMonPicEnemyTurnSpecies = RESTLESS_SOUL
	ld a, RESTLESS_SOUL
	ld [wChangeMonPicEnemyTurnSpecies], a
;> hWhoseTurn = 1
	ld a, $1
	ldh [hWhoseTurn], a
;> ChangeMonPic()
	ld hl, ChangeMonPic
	ld b, BANK(ChangeMonPic)
	call Bankswitch
 ; alternate between black and light gray 8 times.
 ; this makes the ghost's body appear to flash
;> FlashSprite8Times(0x80)
	ld d, $80
	call FlashSprite8Times
.fadeOutGhostLoop
;> while True:
;>     DelayFrames(10)
	ld c, 10
	call DelayFrames
;>     rOBP1 = rOBP1 << 2 & 0xFF
	ldh a, [rOBP1]
	sla a
	sla a
	ldh [rOBP1], a
;>     if rOBP1 == 0:
;>         break
	jr nz, .fadeOutGhostLoop
;> ClearSprites()
	call ClearSprites
;> CopyMonPicFromBGToSpriteVRAM()
	call CopyMonPicFromBGToSpriteVRAM ; copy Marowak pic from BG to sprite VRAM
;> b = 0xE4
	ld b, $e4
.fadeInMarowakLoop
;>@fi while b:                                      # the palette slides in two bits at a time
;>     DelayFrames(10)
	ld c, 10
	call DelayFrames
;>     rOBP1 = (rOBP1 >> 2) | (b & 3) << 6
;>     b >>= 2
	ldh a, [rOBP1]
	srl b
	rra
	srl b
	rra
	ldh [rOBP1], a
;=@fi
	ld a, b
	and a
	jr nz, .fadeInMarowakLoop
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a ; enable BG transfer so the BG Marowak pic will be visible after the sprite one is cleared
;> Delay3()
	call Delay3
;> ClearSprites()
	jp ClearSprites

; copies a mon pic's from background VRAM to sprite VRAM and sets up OAM
;@ path: engine/battle/ghost_marowak_anim
;@ def CopyMonPicFromBGToSpriteVRAM()
;@ Copy the enemy's front picture into sprite tiles and cover it with a 6 x 6 block of sprites at the same place,
;@ so it can be faded with the sprite palette.
CopyMonPicFromBGToSpriteVRAM:
;> CopyVideoData(vSprites, vFrontPic, hi(PIC_SIZE), lo(PIC_SIZE))   # bc = PIC_SIZE: bank 0, 49 tiles
	ld de, vFrontPic
	ld hl, vSprites
	ld bc, PIC_SIZE
	call CopyVideoData
;> wBaseCoordY = 0x10
	ld a, $10
	ld [wBaseCoordY], a
;> wBaseCoordX = 0x70
	ld a, $70
	ld [wBaseCoordX], a
;> oam = wShadowOAM
	ld hl, wShadowOAM
;> tile = 8
;>@col for column in range(6):
	ld bc, ((6) & $ff) << 8 + ((6) & $ff)
	ld d, $8
.oamLoop
;>     y = wBaseCoordY
	push bc
	ld a, [wBaseCoordY]
	ld e, a
;>     for row in range(6):
.oamInnerLoop
;>         y = y + 8 & 0xFF
	ld a, e
	add $8
	ld e, a
;>         mem[oam] = y
	ld [hli], a
;>         mem[oam + 1] = wBaseCoordX
	ld a, [wBaseCoordX]
	ld [hli], a
;>         mem[oam + 2] = tile
	ld a, d
	ld [hli], a
;>         mem[oam + 3] = OAM_PAL1
;>         oam += 4
	ld a, OAM_PAL1
	ld [hli], a
;>         tile += 1
	inc d
	dec c
	jr nz, .oamInnerLoop
;>     tile += 1
	inc d
;>     wBaseCoordX = wBaseCoordX + 8 & 0xFF
	ld a, [wBaseCoordX]
	add $8
	ld [wBaseCoordX], a
;=@col
	pop bc
	dec b
	jr nz, .oamLoop
	ret
;@ path: engine/battle/battle_transitions
;@ def BattleTransition()
;@ The animation that leads into a battle. All sprites but the player's and the enemy trainer's are cleared, then
;@ the transition is picked (BattleTransitions) from three bits: trainer battle, enemy at least 3 levels above the
;@ player's first healthy mon, dungeon map. Link battles always use the first one.
BattleTransition:
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> hWY = 0
	xor a
	ldh [hWY], a
;> wUpdateSpritesEnabled = 0xFF
	dec a
	ld [wUpdateSpritesEnabled], a
;> DelayFrame()
	call DelayFrame

; Determine which OAM block is being used by the enemy trainer sprite (if there
; is one).
;> # The trainer's OAM block: the number of sprites in use before it (hSpriteIndex is 0 in a wild battle).
;> block = 0
;>@l1 for i in range(hSpriteIndex or 256):
	ld hl, wSpritePlayerStateData1ImageIndex
	ldh a, [hSpriteIndex] ; enemy trainer sprite index (0 if wild battle)
	ld c, a
	ld b, 0
	ld de, SPRITESTATEDATA1_LENGTH
.loop1
;>     if mem[wSpritePlayerStateData1ImageIndex + i * SPRITESTATEDATA1_LENGTH & 0xFFFF] != 0xFF:
	ld a, [hl]
	cp $ff
	jr z, .skip1
;>         block += 1
	inc b
.skip1
;=@l1
	add hl, de
	dec c
	jr nz, .loop1

; Clear OAM except for the blocks used by the player and enemy trainer sprites.
;> oam = wShadowOAMSprite04
	ld hl, wShadowOAMSprite04
;>@l2 for _ in range(9):
	ld c, 9
.loop2
;>     if (block << 4 | block >> 4) & 0xFF != oam & 0xFF:   # all but the trainer's block
	ld a, b
	swap a
	cp l
	jr z, .skip2 ; skip clearing the block if the enemy trainer is using it
;>         FillMemory(oam, OBJ_SIZE * 4, 0)
	push hl
	push bc
	ld bc, OBJ_SIZE * 4
	xor a
	call FillMemory
;>     oam += OBJ_SIZE * 4
	pop bc
	pop hl
.skip2
	ld de, OBJ_SIZE * 4
	add hl, de
;=@l2
	dec c
	jr nz, .loop2

;> Delay3()
;> LoadBattleTransitionTile()
	call Delay3
	call LoadBattleTransitionTile
;> transition = 0
	ld bc, 0
;> if wLinkState != LINK_STATE_BATTLING:             # link battles: always the first
	ld a, [wLinkState]
	cp LINK_STATE_BATTLING
	jr z, .linkBattle
;>     transition = GetBattleTransitionID_WildOrTrainer(transition)
	call GetBattleTransitionID_WildOrTrainer
;>     transition = GetBattleTransitionID_CompareLevels(transition)
	call GetBattleTransitionID_CompareLevels
;>     transition = GetBattleTransitionID_IsDungeonMap(transition)
	call GetBattleTransitionID_IsDungeonMap
.linkBattle
;> entry = BattleTransitions + 2 * transition
	ld hl, BattleTransitions
	add hl, bc
	add hl, bc
;> call(mem16[entry])
	ld a, [hli]
	ld h, [hl]
	ld l, a
	jp hl

;> # (the bits of the transition number: trainer battle, stronger enemy, dungeon)
	; 0
DEF BIT_TRAINER_BATTLE_TRANSITION EQU 0
	; 1
DEF BIT_STRONGER_BATTLE_TRANSITION EQU 1
	; 2
DEF BIT_DUNGEON_BATTLE_TRANSITION EQU 2
DEF NUM_BATTLE_TRANSITION_BITS EQU 3

; the three GetBattleTransitionID functions set the first
; three bits of c, which determines what transition animation
; to play at the beginning of a battle
; bit 0: set if trainer battle
; bit 1: set if enemy is at least 3 levels higher than player
; bit 2: set if dungeon map
;@ path: engine/battle/battle_transitions
BattleTransitions:
	dw BattleTransition_DoubleCircle      ; %000
	dw BattleTransition_Spiral            ; %001
	dw BattleTransition_Circle            ; %010
	dw BattleTransition_Spiral            ; %011
	dw BattleTransition_HorizontalStripes ; %100
	dw BattleTransition_Shrink            ; %101
	dw BattleTransition_VerticalStripes   ; %110
	dw BattleTransition_Split             ; %111

;@ path: engine/battle/battle_transitions
;@ def GetBattleTransitionID_WildOrTrainer(bits: c) -> c
;@ Bit 0 of the transition: set for a trainer battle.
GetBattleTransitionID_WildOrTrainer:
;> if wCurOpponent >= OPP_ID_OFFSET:                # a trainer
;>@ts     return bits | 1 << BIT_TRAINER_BATTLE_TRANSITION
	ld a, [wCurOpponent]
	cp OPP_ID_OFFSET
	jr nc, .trainer
;> return bits & ~(1 << BIT_TRAINER_BATTLE_TRANSITION) & 0xFF
	res BIT_TRAINER_BATTLE_TRANSITION, c
	ret
.trainer
;=@ts
	set BIT_TRAINER_BATTLE_TRANSITION, c
	ret

;@ path: engine/battle/battle_transitions
;@ def GetBattleTransitionID_CompareLevels(bits: c) -> c
;@ Bit 1 of the transition: set if the enemy is at least 3 levels above the player's first mon that hasn't
;@ fainted. It also picks the spiral of the trainer transition: outward for a stronger enemy, else inward.
GetBattleTransitionID_CompareLevels:
;> mon = wPartyMon1HP
	ld hl, wPartyMon1HP
.faintedLoop
;> while mem[mon] == 0 and mem[mon + 1] == 0:
	ld a, [hli]
	or [hl]
	jr nz, .notFainted
;>     mon += PARTYMON_STRUCT_LENGTH
	ld de, PARTYMON_STRUCT_LENGTH - 1
	add hl, de
	jr .faintedLoop
.notFainted
;> level = mem[mon + MON_LEVEL - MON_HP]
	ld de, MON_LEVEL - (MON_HP + 1)
	add hl, de
	ld a, [hl]
;> if wCurEnemyLevel >= level + 3 & 0xFF:           # at least 3 levels above
;>@hs     bits |= 1 << BIT_STRONGER_BATTLE_TRANSITION
;>@hd     wBattleTransitionSpiralDirection = 0          # the spiral goes outward
;>@hr     return bits
	add $3
	ld e, a
	ld a, [wCurEnemyLevel]
	sub e
	jr nc, .highLevelEnemy
;> bits &= ~(1 << BIT_STRONGER_BATTLE_TRANSITION) & 0xFF
	res BIT_STRONGER_BATTLE_TRANSITION, c
;> wBattleTransitionSpiralDirection = 1              # inward
	ld a, 1
	ld [wBattleTransitionSpiralDirection], a
;> return bits
	ret
.highLevelEnemy
;=@hs
	set BIT_STRONGER_BATTLE_TRANSITION, c
;=@hd
	xor a
	ld [wBattleTransitionSpiralDirection], a
;=@hr
	ret

;@ path: engine/battle/battle_transitions
;@ def GetBattleTransitionID_IsDungeonMap(bits: c) -> c
;@ Bit 2 of the transition: set on a dungeon map - one listed in DungeonMaps1, or in one of the ranges of
;@ DungeonMaps2. The search through the ranges stops at the first range that ends at or after the map, so maps
;@ that come later are missed (Victory Road 2F and 3F, the Rocket Hideout, Seafoam Islands and others).
GetBattleTransitionID_IsDungeonMap:
;> p = DungeonMaps1
	ld a, [wCurMap]
	ld e, a
	ld hl, DungeonMaps1
.loop1
;> while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
	jr z, .noMatch1
;>     if mem[p] == wCurMap:
	cp e
	jr nz, .loop1
.match
;>         return bits | 1 << BIT_DUNGEON_BATTLE_TRANSITION
;>     p += 1
	set BIT_DUNGEON_BATTLE_TRANSITION, c
	ret
.noMatch1
;> p = DungeonMaps2
	ld hl, DungeonMaps2
.loop2
;> while mem[p] != 0xFF:
	ld a, [hli]
	cp $ff
	jr z, .noMatch2
;>     first, last = mem[p], mem[p + 1]
;>     p += 2
	ld d, a
	ld a, [hli]
;>     if last >= wCurMap:
	cp e
	jr c, .loop2
;>         if wCurMap >= first:
;>             return bits | 1 << BIT_DUNGEON_BATTLE_TRANSITION
	ld a, e
	cp d
	jr nc, .match
.noMatch2
;>         break                                     # (the first range that ends at or after the map)
;> return bits & ~(1 << BIT_DUNGEON_BATTLE_TRANSITION) & 0xFF
	res BIT_DUNGEON_BATTLE_TRANSITION, c
	ret

; GetBattleTransitionID_IsDungeonMap fails to recognize
; VICTORY_ROAD_2F, VICTORY_ROAD_3F, all ROCKET_HIDEOUT maps,
; POKEMON_MANSION_1F, SEAFOAM_ISLANDS_[B1F-B4F], POWER_PLANT,
; DIGLETTS_CAVE, and SILPH_CO_[9-11]F as dungeon maps

; GetBattleTransitionID_IsDungeonMap checks if wCurMap
; is equal to one of these maps
;@ path: engine/battle/battle_transitions
DungeonMaps1:
	db VIRIDIAN_FOREST
	db ROCK_TUNNEL_1F
	db SEAFOAM_ISLANDS_1F
	db ROCK_TUNNEL_B1F
	db -1 ; end

; GetBattleTransitionID_IsDungeonMap checks if wCurMap
; is in between or equal to each pair of maps
;@ path: engine/battle/battle_transitions
DungeonMaps2:
	; all MT_MOON maps
	db MT_MOON_1F, MT_MOON_B2F
	; all SS_ANNE maps, VICTORY_ROAD_1F, LANCES_ROOM, and HALL_OF_FAME
	db SS_ANNE_1F, HALL_OF_FAME
	; all POKEMON_TOWER maps and Lavender Town buildings
	db LAVENDER_POKECENTER, LAVENDER_CUBONE_HOUSE
	; SILPH_CO_[2-8]F, POKEMON_MANSION[2F-B1F], SAFARI_ZONE, and
	; CERULEAN_CAVE maps, except for SILPH_CO_1F
	db SILPH_CO_2F, CERULEAN_CAVE_1F
	db -1 ; end

;@ path: engine/battle/battle_transitions
;@ def LoadBattleTransitionTile()
;@ Load the black tile the transitions draw with into background tile $FF.
LoadBattleTransitionTile:
;> CopyVideoData(vChars1 + 0x7F * TILE_SIZE, BattleTransitionTile, BANK(BattleTransitionTile), 1)
	ld hl, vChars1 + TILE_SIZE * $7f
	ld de, BattleTransitionTile
	ld bc, ((BANK(BattleTransitionTile)) & $ff) << 8 + ((1) & $ff)
	jp CopyVideoData

;@ path: engine/battle/battle_transitions
BattleTransitionTile:
	db $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff, $ff

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_BlackScreen()
;@ All palettes black.
BattleTransition_BlackScreen:
;> rBGP = 0xFF
	ld a, $ff
	ldh [rBGP], a
;> rOBP0 = 0xFF
	ldh [rOBP0], a
;> rOBP1 = 0xFF
	ldh [rOBP1], a
	ret

; for non-dungeon trainer battles
; called regardless of mon levels, but does an
; outward spiral if enemy is at least 3 levels
; higher than player and does an inward spiral otherwise
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Spiral()
;@ Trainer battles outside dungeons: the screen fills with black in a spiral - inward from the edges, or outward
;@ from the middle (3 tiles a frame for 120 frames) against a stronger enemy.
BattleTransition_Spiral:
;> if wBattleTransitionSpiralDirection:
;>     BattleTransition_InwardSpiral()
;> else:
	ld a, [wBattleTransitionSpiralDirection]
	and a
	jr z, .outwardSpiral
	call BattleTransition_InwardSpiral
	jr .done
.outwardSpiral
;>     pos = coord(10, 10)                           # from the middle
	ld hl, (10) * SCREEN_WIDTH + (10) + wTileMap
;>     wOutwardSpiralCurrentDirection = 3            # going right
	ld a, $3
	ld [wOutwardSpiralCurrentDirection], a
;>     mem[addr(wOutwardSpiralTileMapPointer) + 1] = lo(pos)
	ld a, l
	ld [wOutwardSpiralTileMapPointer + 1], a
;>     mem[addr(wOutwardSpiralTileMapPointer)] = hi(pos)
	ld a, h
	ld [wOutwardSpiralTileMapPointer], a
;>@ob     for _ in range(120):
	ld b, 120
.loop
;>@ib         for _ in range(3):                        # 3 tiles a frame
	ld c, 3
.innerLoop
;>             BattleTransition_OutwardSpiral_()
	push bc
	call BattleTransition_OutwardSpiral_
	pop bc
;=@ib
	dec c
	jr nz, .innerLoop
;>         DelayFrame()
	call DelayFrame
;=@ob
	dec b
	jr nz, .loop
.done
;> BattleTransition_BlackScreen()
	call BattleTransition_BlackScreen
;> fill(addr(wOutwardSpiralTileMapPointer), 0, 2)
	xor a
	ld [wOutwardSpiralTileMapPointer + 1], a
	ld [wOutwardSpiralTileMapPointer], a
	ret

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_InwardSpiral()
;@ Black in from the edges of the screen, clockwise: down the left column, along the bottom, up the right column,
;@ back along the top, each lap one tile further in.
BattleTransition_InwardSpiral:
;> wInwardSpiralUpdateScreenCounter = 7
	ld a, 7
	ld [wInwardSpiralUpdateScreenCounter], a
;> pos = BattleTransition_InwardSpiral_(coord(0, 0), SCREEN_HEIGHT - 1, SCREEN_WIDTH)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld c, SCREEN_HEIGHT - 1
	ld de, SCREEN_WIDTH
	call BattleTransition_InwardSpiral_
;> n = SCREEN_HEIGHT
	inc c
;> while True:
	jr .skip
.loop
;=@dn
	ld de, SCREEN_WIDTH
	call BattleTransition_InwardSpiral_
.skip
;>     n += 1
	inc c
;>     pos = BattleTransition_InwardSpiral_(pos, n, 1)
	ld de, 1
	call BattleTransition_InwardSpiral_
;>     n -= 2
	dec c
	dec c
;>     pos = BattleTransition_InwardSpiral_(pos, n, -SCREEN_WIDTH & 0xFFFF)
	ld de, -SCREEN_WIDTH
	call BattleTransition_InwardSpiral_
;>     n += 1
	inc c
;>     pos = BattleTransition_InwardSpiral_(pos, n, -1 & 0xFFFF)
	ld de, -1
	call BattleTransition_InwardSpiral_
;>     n -= 2
	dec c
	dec c
;>     if n == 0:                                    # all black
;>         return
	ld a, c
	and a
	jr nz, .loop
	ret
;>@dn     pos = BattleTransition_InwardSpiral_(pos, n, SCREEN_WIDTH)   # (down the next column)

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_InwardSpiral_(pos: hl, n: c, step: de) -> hl
;@ n black tiles from pos on, step apart; the screen is updated every 7 tiles. Returns where the next tile goes.
;@ test: pos = rand(0xC3A0, 0xC400); n = rand(1, 8); step = 1; wInwardSpiralUpdateScreenCounter = rand(9, 20)
BattleTransition_InwardSpiral_:
;> for _ in range(n or 256):
	push bc
.loop
;>     mem[pos] = 0xFF
	ld [hl], $ff
;>     pos = pos + step & 0xFFFF
	add hl, de
;>     count = wInwardSpiralUpdateScreenCounter - 1 & 0xFF
	push bc
	ld a, [wInwardSpiralUpdateScreenCounter]
	dec a
;>     if count == 0:
	jr nz, .skip
;>         BattleTransition_TransferDelay3()
	call BattleTransition_TransferDelay3
;>         count = 7
	ld a, 7
.skip
;>     wInwardSpiralUpdateScreenCounter = count
	ld [wInwardSpiralUpdateScreenCounter], a
	pop bc
	dec c
	jr nz, .loop
;> return pos
	pop bc
	ret

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_OutwardSpiral_()
;@ One more black tile of the outward spiral (wOutwardSpiralTileMapPointer, big-endian). Going in the direction in
;@ wOutwardSpiralCurrentDirection (0 up, 1 left, 2 down, 3 right), it turns as soon as the tile on its turning side
;@ isn't black yet.
;@ test: p = rand(0xC3C0, 0xC4C0); mem[0xD09A] = p >> 8; mem[0xD09B] = p & 0xFF; wOutwardSpiralCurrentDirection = rand(0, 4)
BattleTransition_OutwardSpiral_:
;> pos = mem[addr(wOutwardSpiralTileMapPointer)] << 8 | mem[addr(wOutwardSpiralTileMapPointer) + 1]
	ld bc, -SCREEN_WIDTH
	ld de, SCREEN_WIDTH
	ld a, [wOutwardSpiralTileMapPointer + 1]
	ld l, a
	ld a, [wOutwardSpiralTileMapPointer]
	ld h, a
;> direction = wOutwardSpiralCurrentDirection
;> turn = False
	ld a, [wOutwardSpiralCurrentDirection]
;> if direction == 0:                                # up: it turns left as soon as it can
;>@u1     pos = pos - 1 & 0xFFFF
;>@u2     turn = mem[pos] != 0xFF
;>@u3     if not turn: pos = pos + 1 - SCREEN_WIDTH & 0xFFFF   # else straight on
	cp $0
	jr z, .up
;> elif direction == 1:                              # left: it turns down
;>@l1     pos = pos + SCREEN_WIDTH & 0xFFFF
;>@l2     turn = mem[pos] != 0xFF
;>@l3     if not turn: pos = pos - SCREEN_WIDTH - 1 & 0xFFFF
	cp $1
	jr z, .left
;> elif direction == 2:                              # down: it turns right
;>@d1     pos = pos + 1 & 0xFFFF
;>@d2     turn = mem[pos] != 0xFF
;>@d3     if not turn: pos = pos - 1 + SCREEN_WIDTH & 0xFFFF
	cp $2
	jr z, .down
;> elif direction == 3:                              # right: it turns up
;>@r1     pos = pos - SCREEN_WIDTH & 0xFFFF
;>@r2     turn = mem[pos] != 0xFF
;>@r3     if not turn: pos = pos + SCREEN_WIDTH + 1 & 0xFFFF
	cp $3
	jr z, .right
.keepSameDirection
;>@mk mem[pos] = 0xFF
	ld [hl], $ff
.done
;> if turn:
;>@t1     direction = wOutwardSpiralCurrentDirection + 1
;>@t2     wOutwardSpiralCurrentDirection = direction & 3
;> mem[addr(wOutwardSpiralTileMapPointer) + 1] = lo(pos)
	ld a, l
	ld [wOutwardSpiralTileMapPointer + 1], a
;> mem[addr(wOutwardSpiralTileMapPointer)] = hi(pos)
	ld a, h
	ld [wOutwardSpiralTileMapPointer], a
	ret
.up
;=@u1
	dec hl
;=@u2
	ld a, [hl]
	cp $ff
	jr nz, .changeDirection
;=@u3
	inc hl
	add hl, bc
	jr .keepSameDirection
.left
;=@l1
	add hl, de
;=@l2
	ld a, [hl]
	cp $ff
	jr nz, .changeDirection
;=@l3
	add hl, bc
	dec hl
	jr .keepSameDirection
.down
;=@d1
	inc hl
;=@d2
	ld a, [hl]
	cp $ff
	jr nz, .changeDirection
;=@d3
	dec hl
	add hl, de
	jr .keepSameDirection
.right
;=@r1
	add hl, bc
;=@r2
	ld a, [hl]
	cp $ff
	jr nz, .changeDirection
;=@r3
	add hl, de
	inc hl
	jr .keepSameDirection
.changeDirection
;=@mk
	ld [hl], $ff
;=@t1
	ld a, [wOutwardSpiralCurrentDirection]
	inc a
;=@t2
	cp $4
	jr nz, .skip
	xor a
.skip
	ld [wOutwardSpiralCurrentDirection], a
	jr .done

;@ path: engine/battle/battle_transitions
FlashScreen:
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_FlashScreen_(times: b)
;@ Flash the screen `times` times: the background palettes of BattleTransition_FlashScreenPalettes (up to the 1
;@ that ends them), 2 frames each.
BattleTransition_FlashScreen_:
;> for _ in range(times or 256):
;>     p = BattleTransition_FlashScreenPalettes
	ld hl, BattleTransition_FlashScreenPalettes
.loop
;>     while mem[p] != 1:
	ld a, [hli]
	cp 1
	jr z, .done
;>         rBGP = mem[p]
;>         p += 1
	ldh [rBGP], a
;>         DelayFrames(2)
	ld c, 2
	call DelayFrames
	jr .loop
.done
	dec b
	jr nz, BattleTransition_FlashScreen_
	ret

;@ path: engine/battle/battle_transitions
BattleTransition_FlashScreenPalettes:
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (1)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (2)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (3)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (2)
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (1)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)
	db ((2) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((1) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((0) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((1) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((2) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)
	db 1 ; end

; used for low level trainer dungeon battles
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Shrink()
;@ Trainer battles in dungeons against a weaker enemy: the picture is squeezed towards the middle, rows from top
;@ and bottom and columns from left and right, leaving black behind; then all black.
BattleTransition_Shrink:
;> for _ in range(SCREEN_HEIGHT // 2):
	ld c, SCREEN_HEIGHT / 2
.loop
	push bc
;>     hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;>     BattleTransition_CopyTiles1(coord(0, 7), coord(0, 8), -SCREEN_WIDTH * 2 & 0xFFFF)
	ld hl, (7) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (8) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, -SCREEN_WIDTH * 2
	call BattleTransition_CopyTiles1
;>     BattleTransition_CopyTiles1(coord(0, 10), coord(0, 9), SCREEN_WIDTH * 2)
	ld hl, (10) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (9) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_WIDTH * 2
	call BattleTransition_CopyTiles1
;>     BattleTransition_CopyTiles2(coord(8, 0), coord(9, 0), -2 & 0xFFFF)
	ld hl, (0) * SCREEN_WIDTH + (8) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (9) + wTileMap
	ld bc, -2
	call BattleTransition_CopyTiles2
;>     BattleTransition_CopyTiles2(coord(11, 0), coord(10, 0), 2)
	ld hl, (0) * SCREEN_WIDTH + (11) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (10) + wTileMap
	ld bc, 2
	call BattleTransition_CopyTiles2
;>     hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;>     DelayFrames(6)
	ld c, 6
	call DelayFrames
	pop bc
	dec c
	jr nz, .loop
;> BattleTransition_BlackScreen()
	call BattleTransition_BlackScreen
;> DelayFrames(10)
	ld c, 10
	jp DelayFrames

; used for high level trainer dungeon battles
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Split()
;@ Trainer battles in dungeons against a stronger enemy: the picture splits from the middle, rows towards top and
;@ bottom and columns towards left and right, leaving black behind; then all black.
BattleTransition_Split:
;> hAutoBGTransferEnabled = 0
;> for _ in range(SCREEN_HEIGHT // 2):
	ld c, SCREEN_HEIGHT / 2
	xor a
	ldh [hAutoBGTransferEnabled], a
.loop
	push bc
;>     BattleTransition_CopyTiles1(coord(0, 16), coord(0, 17), -SCREEN_WIDTH * 2 & 0xFFFF)
	ld hl, (16) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (17) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, -SCREEN_WIDTH * 2
	call BattleTransition_CopyTiles1
;>     BattleTransition_CopyTiles1(coord(0, 1), coord(0, 0), SCREEN_WIDTH * 2)
	ld hl, (1) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_WIDTH * 2
	call BattleTransition_CopyTiles1
;>     BattleTransition_CopyTiles2(coord(18, 0), coord(19, 0), -2 & 0xFFFF)
	ld hl, (0) * SCREEN_WIDTH + (18) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (19) + wTileMap
	ld bc, -2
	call BattleTransition_CopyTiles2
;>     BattleTransition_CopyTiles2(coord(1, 0), coord(0, 0), 2)
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, 2
	call BattleTransition_CopyTiles2
;>     BattleTransition_TransferDelay3()
	call BattleTransition_TransferDelay3
;>     Delay3()
	call Delay3
	pop bc
	dec c
	jr nz, .loop
;> BattleTransition_BlackScreen()
	call BattleTransition_BlackScreen
;> DelayFrames(10)
	ld c, 10
	jp DelayFrames

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_CopyTiles1(src: hl, dest: de, step: bc)
;@ Move 8 screen rows one row over: each row is copied to dest, then the next pair is the row `step` beyond the
;@ old destination and the old source. The last row left behind turns black.
;@ test: src = rand(0xC400, 0xC420); dest = src + 20; step = 40
BattleTransition_CopyTiles1:
;> wBattleTransitionCopyTilesOffset[0], wBattleTransitionCopyTilesOffset[1] = lo(step), hi(step)
	ld a, c
	ld [wBattleTransitionCopyTilesOffset], a
	ld a, b
	ld [wBattleTransitionCopyTilesOffset + 1], a
;>@t1 for _ in range(8):
	ld c, 8
.loop1
;>     CopyData(src, dest, SCREEN_WIDTH)
	push bc
	push hl
	push de
	ld bc, SCREEN_WIDTH
	call CopyData
;>     src, dest = dest, src
	pop hl
	pop de
;>     src = src + step & 0xFFFF
	ld a, [wBattleTransitionCopyTilesOffset]
	ld c, a
	ld a, [wBattleTransitionCopyTilesOffset + 1]
	ld b, a
	add hl, bc
;=@t1
	pop bc
	dec c
	jr nz, .loop1
;>@f1 for i in range(SCREEN_WIDTH):                    # the row left behind turns black
	ld l, e
	ld h, d
	ld a, $ff
	ld c, SCREEN_WIDTH
.loop2
;>     mem[dest + i] = 0xFF
	ld [hli], a
;=@f1
	dec c
	jr nz, .loop2
	ret

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_CopyTiles2(src: hl, dest: de, step: bc)
;@ The same with screen columns: 9 columns are moved one column over, and the last one left behind turns black.
;@ test: src = rand(0xC3A0, 0xC3B0); dest = src + 1; step = 2
BattleTransition_CopyTiles2:
;> wBattleTransitionCopyTilesOffset[0], wBattleTransitionCopyTilesOffset[1] = lo(step), hi(step)
	ld a, c
	ld [wBattleTransitionCopyTilesOffset], a
	ld a, b
	ld [wBattleTransitionCopyTilesOffset + 1], a
;>@c1 for _ in range(SCREEN_HEIGHT // 2):
	ld c, SCREEN_HEIGHT / 2
.loop1
;>     s, d = src, dest
	push bc
	push hl
	push de
;>@c2     for row in range(SCREEN_HEIGHT):
	ld c, SCREEN_HEIGHT
.loop2
;>         mem[d] = mem[s]
	ld a, [hl]
	ld [de], a
;>         d = d + SCREEN_WIDTH & 0xFFFF
	ld a, e
	add SCREEN_WIDTH
	jr nc, .noCarry1
	inc d
.noCarry1
	ld e, a
;>         s = s + SCREEN_WIDTH & 0xFFFF
	ld a, l
	add SCREEN_WIDTH
	jr nc, .noCarry2
	inc h
.noCarry2
	ld l, a
;=@c2
	dec c
	jr nz, .loop2
;>     src, dest = dest, src
	pop hl
	pop de
;>     src = src + step & 0xFFFF
	ld a, [wBattleTransitionCopyTilesOffset]
	ld c, a
	ld a, [wBattleTransitionCopyTilesOffset + 1]
	ld b, a
	add hl, bc
;=@c1
	pop bc
	dec c
	jr nz, .loop1
;> for row in range(SCREEN_HEIGHT):
	ld l, e
	ld h, d
	ld de, SCREEN_WIDTH
	ld c, SCREEN_HEIGHT
.loop3
;>     mem[dest + row * SCREEN_WIDTH & 0xFFFF] = 0xFF
	ld [hl], $ff
	add hl, de
	dec c
	jr nz, .loop3
	ret

; used for high level wild dungeon battles
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_VerticalStripes()
;@ Wild battles in dungeons against a stronger mon: every other tile of a row turns black, from the top and (one
;@ tile shifted) from the bottom at once, until they meet.
BattleTransition_VerticalStripes:
;> n = SCREEN_HEIGHT
	ld c, SCREEN_HEIGHT
;> top, bottom = coord(0, 0), coord(1, 17)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (17) * SCREEN_WIDTH + (1) + wTileMap
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
.loop
;> while n:
;>     BattleTransition_VerticalStripes_(top)
	push bc
	push hl
	push de
	push de
	call BattleTransition_VerticalStripes_
;>     BattleTransition_VerticalStripes_(bottom)
	pop hl
	call BattleTransition_VerticalStripes_
;>     BattleTransition_TransferDelay3()
	call BattleTransition_TransferDelay3
;>     bottom = bottom - SCREEN_WIDTH & 0xFFFF
	pop hl
	ld bc, -SCREEN_WIDTH
	add hl, bc
	ld e, l
	ld d, h
;>     top = top + SCREEN_WIDTH & 0xFFFF
	pop hl
	ld bc, SCREEN_WIDTH
	add hl, bc
;>     n -= 1
	pop bc
	dec c
	jr nz, .loop
;> BattleTransition_BlackScreen()
	jp BattleTransition_BlackScreen

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_VerticalStripes_(pos: hl) -> hl
;@ Every other tile of a row from pos on turns black.
;@ test: pos = rand(0xC3A0, 0xC4E0)
BattleTransition_VerticalStripes_:
;>@vl for _ in range(SCREEN_WIDTH // 2):
	ld c, SCREEN_WIDTH / 2
.loop
;>     mem[pos] = 0xFF
	ld [hl], $ff
;>     pos += 2
	inc hl
	inc hl
;=@vl
	dec c
	jr nz, .loop
;> return pos
	ret

; used for low level wild dungeon battles
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_HorizontalStripes()
;@ Wild battles in dungeons against a weaker mon: every other tile of a column turns black, from the left and (one
;@ row shifted) from the right at once, until they meet.
BattleTransition_HorizontalStripes:
;> n = SCREEN_WIDTH
	ld c, SCREEN_WIDTH
;> left, right = coord(0, 0), coord(19, 1)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (1) * SCREEN_WIDTH + (19) + wTileMap
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
.loop
;> while n:
;>     BattleTransition_HorizontalStripes_(left)
	push bc
	push hl
	push de
	push de
	call BattleTransition_HorizontalStripes_
;>     BattleTransition_HorizontalStripes_(right)
	pop hl
	call BattleTransition_HorizontalStripes_
;>     BattleTransition_TransferDelay3()
	call BattleTransition_TransferDelay3
	pop de
	pop hl
	pop bc
;>     left += 1
	inc hl
;>     right -= 1
	dec de
;>     n -= 1
	dec c
	jr nz, .loop
;> BattleTransition_BlackScreen()
	jp BattleTransition_BlackScreen

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_HorizontalStripes_(pos: hl) -> hl
;@ Every other tile of a column from pos down turns black.
;@ test: pos = rand(0xC3A0, 0xC3C8)
BattleTransition_HorizontalStripes_:
;>@hl for _ in range(SCREEN_HEIGHT // 2):
	ld c, SCREEN_HEIGHT / 2
	ld de, SCREEN_WIDTH * 2
.loop
;>     mem[pos] = 0xFF
	ld [hl], $ff
;>     pos += SCREEN_WIDTH * 2                       # every other tile of the column
	add hl, de
;=@hl
	dec c
	jr nz, .loop
;> return pos
	ret

; used for high level wild non-dungeon battles
; makes one full circle around the screen
; by animating each half circle one at a time
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Circle()
;@ Wild battles outside dungeons against a stronger mon: three flashes, then black sweeps around the screen like a
;@ clock hand, one half after the other.
BattleTransition_Circle:
;> BattleTransition_FlashScreen()
	call BattleTransition_FlashScreen
;> BattleTransition_Circle_Sub1(BattleTransition_HalfCircle1, 0, SCREEN_WIDTH // 2)   # the lower half
	ld bc, ((0) & $ff) << 8 + ((SCREEN_WIDTH / 2) & $ff)
	ld hl, BattleTransition_HalfCircle1
	call BattleTransition_Circle_Sub1
;> BattleTransition_Circle_Sub1(BattleTransition_HalfCircle2, 1, SCREEN_WIDTH // 2)   # the upper half
	ld c, SCREEN_WIDTH / 2
	ld b, 1
	ld hl, BattleTransition_HalfCircle2
	call BattleTransition_Circle_Sub1
;> BattleTransition_BlackScreen()
	jp BattleTransition_BlackScreen

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_FlashScreen()
;@ Three flashes.
BattleTransition_FlashScreen:
;> BattleTransition_FlashScreen_(3)
;> hAutoBGTransferEnabled = 0
	ld b, $3
	call BattleTransition_FlashScreen_
	xor a
	ldh [hAutoBGTransferEnabled], a
	ret

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Circle_Sub1(halves: hl, upper: b, n: c)
;@ Draw n steps of a half circle (5-byte entries, see BattleTransition_Circle_Sub2), one per screen update.
BattleTransition_Circle_Sub1:
;>@s1 for _ in range(n or 256):
;>     BattleTransition_Circle_Sub2(halves, upper)
	push bc
	push hl
	ld a, b
	call BattleTransition_Circle_Sub2
;>     halves += 5
	pop hl
	ld bc, 5
	add hl, bc
;>     BattleTransition_TransferDelay3()
	call BattleTransition_TransferDelay3
;=@s1
	pop bc
	dec c
	jr nz, BattleTransition_Circle_Sub1
	ret

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_TransferDelay3()
;@ Copy the tile map to the screen during the next 3 frames, then stop the copying again.
BattleTransition_TransferDelay3:
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
	ret

; used for low level wild non-dungeon battles
; makes two half circles around the screen
; by animating both half circles at the same time
;@ path: engine/battle/battle_transitions
;@ def BattleTransition_DoubleCircle()
;@ Wild battles outside dungeons against a weaker mon: three flashes, then black sweeps around both halves of the
;@ screen at once.
BattleTransition_DoubleCircle:
;> BattleTransition_FlashScreen()
	call BattleTransition_FlashScreen
;> left, right = BattleTransition_HalfCircle1, BattleTransition_HalfCircle2
;> for _ in range(SCREEN_WIDTH // 2):
	ld c, SCREEN_WIDTH / 2
	ld hl, BattleTransition_HalfCircle1
	ld de, BattleTransition_HalfCircle2
.loop
;>     BattleTransition_Circle_Sub2(left, 0)
	push bc
	push hl
	push de
	push de
	xor a
	call BattleTransition_Circle_Sub2
;>     BattleTransition_Circle_Sub2(right, 1)
	pop hl
	ld a, $1
	call BattleTransition_Circle_Sub2
;>     right += 5
	pop hl
	ld bc, 5
	add hl, bc
	ld e, l
	ld d, h
;>     left += 5
	pop hl
	add hl, bc
;>     BattleTransition_TransferDelay3()
	call BattleTransition_TransferDelay3
	pop bc
	dec c
	jr nz, .loop
;> BattleTransition_BlackScreen()
	jp BattleTransition_BlackScreen

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Circle_Sub2(entry: hl, upper: a)
;@ One step of a half circle. The entry holds the side (0 left: the rows grow leftwards), the shape data and the
;@ tile map position where the shape starts; upper (1) draws the shape upwards from there, else downwards.
;@ test: entry = 0x4D61 + 5 * rand(0, 19); upper = rand(0, 1)
BattleTransition_Circle_Sub2:
;> wBattleTransitionCircleScreenQuadrantY = upper
	ld [wBattleTransitionCircleScreenQuadrantY], a
;> wBattleTransitionCircleScreenQuadrantX = mem[entry]   # the side
	ld a, [hli]
	ld [wBattleTransitionCircleScreenQuadrantX], a
;> shape = mem16[entry + 1]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;> pos = mem16[entry + 3]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> return BattleTransition_Circle_Sub3(pos, shape)
	jp BattleTransition_Circle_Sub3

; halves
DEF CIRCLE_LEFT EQU 0
DEF CIRCLE_RIGHT EQU 1


;@ path: engine/battle/battle_transitions
BattleTransition_HalfCircle1:
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData1
	dw (6) * SCREEN_WIDTH + (18) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData2
	dw (3) * SCREEN_WIDTH + (19) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData3
	dw (0) * SCREEN_WIDTH + (18) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData4
	dw (0) * SCREEN_WIDTH + (14) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData5
	dw (0) * SCREEN_WIDTH + (10) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData5
	dw (0) * SCREEN_WIDTH + (9) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData4
	dw (0) * SCREEN_WIDTH + (5) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData3
	dw (0) * SCREEN_WIDTH + (1) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData2
	dw (3) * SCREEN_WIDTH + (0) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData1
	dw (6) * SCREEN_WIDTH + (1) + wTileMap

;@ path: engine/battle/battle_transitions
BattleTransition_HalfCircle2:
	db CIRCLE_LEFT
	dw BattleTransition_CircleData1
	dw (11) * SCREEN_WIDTH + (1) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData2
	dw (14) * SCREEN_WIDTH + (0) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData3
	dw (17) * SCREEN_WIDTH + (1) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData4
	dw (17) * SCREEN_WIDTH + (5) + wTileMap
	db CIRCLE_LEFT
	dw BattleTransition_CircleData5
	dw (17) * SCREEN_WIDTH + (9) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData5
	dw (17) * SCREEN_WIDTH + (10) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData4
	dw (17) * SCREEN_WIDTH + (14) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData3
	dw (17) * SCREEN_WIDTH + (18) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData2
	dw (14) * SCREEN_WIDTH + (19) + wTileMap
	db CIRCLE_RIGHT
	dw BattleTransition_CircleData1
	dw (11) * SCREEN_WIDTH + (18) + wTileMap

;@ path: engine/battle/battle_transitions
;@ def BattleTransition_Circle_Sub3(pos: hl, shape: de)
;@ Draw a shape row by row: a row of black tiles of the given length from pos (rightwards on the right side,
;@ leftwards on the left), then the next row up or down, its start moved inwards by the next number, until $FF.
;@ test: shape = rand_ram(8); [mem.__setitem__(shape + i, rand(1, 3)) for i in range(7)]; mem[shape + 7] = 0xFF; pos = rand(0xC400, 0xC480); wBattleTransitionCircleScreenQuadrantX = rand(0, 1); wBattleTransitionCircleScreenQuadrantY = rand(0, 1)
BattleTransition_Circle_Sub3:
;>@w while True:                                     # row by row
;>     p = pos
	push hl
;>     n = mem[shape]
	ld a, [de]
	ld c, a
;>     shape += 1
	inc de
.loop1
;>@r     for _ in range(n or 256):
;>         mem[p] = 0xFF
	ld [hl], $ff
;>         if wBattleTransitionCircleScreenQuadrantX:    # the right side: rightwards
	ld a, [wBattleTransitionCircleScreenQuadrantX]
	and a
	jr z, .skip1
;>             p += 1
	inc hl
	jr .skip2
.skip1
;>         else:
;>             p -= 1
	dec hl
.skip2
;=@r
	dec c
	jr nz, .loop1
;>     up = wBattleTransitionCircleScreenQuadrantY
	pop hl
	ld a, [wBattleTransitionCircleScreenQuadrantY]
	and a
;>     step = SCREEN_WIDTH
;>     if up:
	ld bc, SCREEN_WIDTH
	jr z, .skip3
;>         step = -SCREEN_WIDTH & 0xFFFF
	ld bc, -SCREEN_WIDTH
.skip3
;>     pos = pos + step & 0xFFFF                     # the next row
	add hl, bc
;>     shift = mem[shape]
;>     shape += 1
	ld a, [de]
	inc de
;>     if shift == 0xFF:
;>         return
	cp -1
	ret z
;>     if shift == 0:
;>         continue
	and a
	jr z, BattleTransition_Circle_Sub3
;>@s     for _ in range(shift):                        # its start moves inwards
	ld c, a
.loop2
;>         if wBattleTransitionCircleScreenQuadrantX:
	ld a, [wBattleTransitionCircleScreenQuadrantX]
	and a
	jr z, .skip4
;>             pos -= 1
	dec hl
	jr .skip5
.skip4
;>         else:
;>             pos += 1
	inc hl
.skip5
;=@s
	dec c
	jr nz, .loop2
;=@w
	jr BattleTransition_Circle_Sub3

;@ path: engine/battle/battle_transitions
BattleTransition_CircleData1: db 2, 3, 5, 4, 9, -1
;@ path: engine/battle/battle_transitions
BattleTransition_CircleData2: db 1, 1, 2, 2, 4, 2, 4, 2, 3, -1
;@ path: engine/battle/battle_transitions
BattleTransition_CircleData3: db 2, 1, 3, 1, 4, 1, 4, 1, 4, 1, 3, 1, 2, 1, 1, 1, 1, -1
;@ path: engine/battle/battle_transitions
BattleTransition_CircleData4: db 4, 1, 4, 0, 3, 1, 3, 0, 2, 1, 2, 0, 1, -1
;@ path: engine/battle/battle_transitions
BattleTransition_CircleData5: db 4, 0, 3, 0, 3, 0, 2, 0, 2, 0, 1, 0, 1, 0, 1, -1
DEF NOT_VISITED EQU $fe

DEF BIRD_BASE_TILE EQU $04

;@ def DisplayTownMap()
;@ The Town Map item: the map with the player's position, and a blinking cursor that UP and DOWN move through the
;@ towns and routes in TownMapOrder, naming each one at the top. A or B closes it.
;@ test: wCurMap = rand(0, 0xF7)
;@ path: engine/items/town_map
DisplayTownMap:
;> LoadTownMap()
	call LoadTownMap
;> saved = wUpdateSpritesEnabled
	ld hl, wUpdateSpritesEnabled
	ld a, [hl]
	push af
;> wUpdateSpritesEnabled = 0xFF
	ld [hl], $ff
	push hl
;> hJoy7 = 1
	ld a, $1
	ldh [hJoy7], a
;> DrawPlayerOrBirdSprite(wCurMap, 0)
	ld a, [wCurMap]
	push af
	ld b, $0
	call DrawPlayerOrBirdSprite
;> PlaceString(addr(wNameBuffer), coord(1, 0))
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	ld de, wNameBuffer
	call PlaceString
;> CopyData(addr(wShadowOAMSprite00), addr(wShadowOAMBackupSprite00), OBJ_SIZE * 4)
	ld hl, wShadowOAMSprite00
	ld de, wShadowOAMBackupSprite00
	ld bc, OBJ_SIZE * 4
	call CopyData
;> CopyVideoDataDouble(addr(vSprites) + BIRD_BASE_TILE * 16, TownMapCursor, BANK(TownMapCursor),
;>                     (TownMapCursorEnd - TownMapCursor) // TILE_1BPP_SIZE)
	ld hl, vSprites + TILE_SIZE * BIRD_BASE_TILE
	ld de, TownMapCursor
	ld bc, ((BANK(TownMapCursor)) & $ff) << 8 + (((TownMapCursorEnd - TownMapCursor) / TILE_1BPP_SIZE) & $ff)
	call CopyVideoDataDouble
;> wWhichTownMapLocation = 0
	xor a
	ld [wWhichTownMapLocation], a
;> place = wCurMap                             # the cursor starts on the player
	pop af
	jr .enterLoop

.townMapLoop
;=@cs
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((1) & $ff) << 8 + ((20) & $ff)
	call ClearScreenArea
;=@pl1
	ld hl, TownMapOrder
	ld a, [wWhichTownMapLocation]
	ld c, a
	ld b, 0
	add hl, bc
;=@pl2
	ld a, [hl]
.enterLoop
;> while True:
;>     name = LoadTownMapEntry(place, addr(wTownMapCoords))
	ld de, wTownMapCoords
	call LoadTownMapEntry
;>     # (TownMapCoordsToOAMCoords also writes its two bytes to the name's ROM address: the cartridge ignores them)
;>     y, x, _ = TownMapCoordsToOAMCoords(mem[addr(wTownMapCoords)], name)
	ld a, [de]
	push hl
	call TownMapCoordsToOAMCoords
;>     wOAMBaseTile = 4
	ld a, $4
	ld [wOAMBaseTile], a
;>     WriteTownMapSpriteOAM(addr(wShadowOAMSprite04), y, x)      # the cursor
	ld hl, wShadowOAMSprite04
	call WriteTownMapSpriteOAM ; town map cursor sprite
;>     d = addr(wNameBuffer)
	pop hl
	ld de, wNameBuffer
;>@cm     while True:
.copyMapName
;>         ch = mem[name]
;>         name += 1
	ld a, [hli]
;>         mem[d] = ch
	ld [de], a
;>         d += 1
	inc de
;>         if ch == 0x50:                      # '@'
;>             break
	cp '@'
	jr nz, .copyMapName
;>     PlaceString(addr(wNameBuffer), coord(1, 0))
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	ld de, wNameBuffer
	call PlaceString
;>     CopyData(addr(wShadowOAMSprite04), addr(wShadowOAMBackupSprite04), OBJ_SIZE * 4)
	ld hl, wShadowOAMSprite04
	ld de, wShadowOAMBackupSprite04
	ld bc, OBJ_SIZE * 4
	call CopyData
;>     while True:
.inputLoop
;>         TownMapSpriteBlinkingAnimation()
	call TownMapSpriteBlinkingAnimation
;>         JoypadLowSensitivity()
	call JoypadLowSensitivity
;>         pressed = hJoy5
	ldh a, [hJoy5]
	ld b, a
;>         if pressed & (PAD_A | PAD_B | PAD_UP | PAD_DOWN):
;>             break
	and PAD_A | PAD_B | PAD_UP | PAD_DOWN
	jr z, .inputLoop
;>     PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;>     if pressed & PAD_UP:
;>@u1         n = (wWhichTownMapLocation + 1) & 0xFF
;>@u2         if n == TownMapOrderEnd - TownMapOrder:     # after the last comes the first
;>@u3             n = 0
;>@u4         wWhichTownMapLocation = n
	bit B_PAD_UP, b
	jr nz, .pressedUp
;>     elif pressed & PAD_DOWN:
;>@d1         n = (wWhichTownMapLocation - 1) & 0xFF
;>@d2         if n == 0xFF:                       # before the first comes the last
;>@d3             n = TownMapOrderEnd - TownMapOrder - 1
;>@d4         wWhichTownMapLocation = n
	bit B_PAD_DOWN, b
	jr nz, .pressedDown
;>     else:
;>         break                               # A or B
;>@cs     ClearScreenArea(coord(0, 0), 20, 1)
;>@pl1     p = TownMapOrder + wWhichTownMapLocation
;>@pl2     place = mem[p]
;> wTownMapSpriteBlinkingEnabled = 0
	xor a
	ld [wTownMapSpriteBlinkingEnabled], a
;> hJoy7 = 0
	ldh [hJoy7], a
;> wAnimCounter = 0
	ld [wAnimCounter], a
;> ExitTownMap()
	call ExitTownMap
;> wUpdateSpritesEnabled = saved
	pop hl
	pop af
	ld [hl], a
;> return
	ret
.pressedUp
;=@u1
	ld a, [wWhichTownMapLocation]
	inc a
;=@u2
	cp TownMapOrderEnd - TownMapOrder ; number of list items + 1
	jr nz, .noOverflow
;=@u3
	xor a
.noOverflow
;=@u4
	ld [wWhichTownMapLocation], a
	jp .townMapLoop
.pressedDown
;=@d1
	ld a, [wWhichTownMapLocation]
	dec a
;=@d2
	cp -1
	jr nz, .noUnderflow
;=@d3
	ld a, TownMapOrderEnd - TownMapOrder - 1 ; number of list items
.noUnderflow
;=@d4
	ld [wWhichTownMapLocation], a
	jp .townMapLoop

