	db $fe, $fe, $c0, $c0, $c0, $c0, $c0, $00, $7f, $7f, $03, $03, $03, $03, $03, $00
	db $00, $c0, $c0, $c0, $c0, $c0, $fe, $fe, $00, $03, $03, $03, $03, $03, $7f, $7f
