;@ def LoadTownMap_Nest()
;@ The Pokédex AREA page: the Town Map with a nest icon on every place where species wPokedexNum lives, and
;@ "<MON>'s NEST" at the top, until a button press.
;@ test: wCurMap = rand(0, 0xF7)
;@ path: engine/items/town_map
LoadTownMap_Nest:
;> LoadTownMap()
	call LoadTownMap
;> saved = wUpdateSpritesEnabled
	ld hl, wUpdateSpritesEnabled
	ld a, [hl]
	push af
;> wUpdateSpritesEnabled = 0xFF
	ld [hl], $ff
	push hl
;> DisplayWildLocations()
	call DisplayWildLocations
;> end, _ = PlaceString(GetMonName(), coord(1, 0))
	call GetMonName
	ld hl, (0) * SCREEN_WIDTH + (1) + wTileMap
	call PlaceString
;> PlaceString(MonsNestText, end)
	ld h, b
	ld l, c
	ld de, MonsNestText
	call PlaceString
;> WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;> ExitTownMap()
	call ExitTownMap
;> wUpdateSpritesEnabled = saved
	pop hl
	pop af
	ld [hl], a
	ret

;@ path: engine/items/town_map
MonsNestText:
	db "'s NEST@"

;@ def LoadTownMap_Fly()
;@ FLY: the Town Map with a bird on the chosen town. UP and DOWN step through the visited towns (wrapping round),
;@ A flies there (wDestinationMap and the fly-warp flags), B cancels.
;@ test: wCurMap = rand(0, 0xF7)
;@ path: engine/items/town_map
LoadTownMap_Fly::
;> ClearSprites()
	call ClearSprites
;> LoadTownMap()
	call LoadTownMap
;> LoadPlayerSpriteGraphics()
	call LoadPlayerSpriteGraphics
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> CopyVideoData(addr(vSprites) + BIRD_BASE_TILE * 16, BirdSprite, BANK(BirdSprite), 12)
	ld de, BirdSprite
	ld hl, vSprites + TILE_SIZE * BIRD_BASE_TILE
	ld bc, ((BANK(BirdSprite)) & $ff) << 8 + ((12) & $ff)
	call CopyVideoData
;> CopyVideoDataDouble(addr(vChars1) + 0x6D * 16, TownMapUpArrow, BANK(TownMapUpArrow),
;>                     (TownMapUpArrowEnd - TownMapUpArrow) // TILE_1BPP_SIZE)
	ld de, TownMapUpArrow
	ld hl, vChars1 + TILE_SIZE * $6d
	ld bc, ((BANK(TownMapUpArrow)) & $ff) << 8 + (((TownMapUpArrowEnd - TownMapUpArrow) / TILE_1BPP_SIZE) & $ff)
	call CopyVideoDataDouble
;> BuildFlyLocationsList()
	call BuildFlyLocationsList
;> saved = wUpdateSpritesEnabled
	ld hl, wUpdateSpritesEnabled
	ld a, [hl]
	push af
;> wUpdateSpritesEnabled = 0xFF
	ld [hl], $ff
	push hl
;> PlaceString(ToText, coord(0, 0))
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld de, ToText
	call PlaceString
;> DrawPlayerOrBirdSprite(wCurMap, 0)
	ld a, [wCurMap]
	ld b, $0
	call DrawPlayerOrBirdSprite
;> p = addr(wFlyLocationsList)
	ld hl, wFlyLocationsList
;> arrow = coord(18, 0)
	ld de, (0) * SCREEN_WIDTH + (18) + wTileMap
;> while True:
.townMapFlyLoop
;>     mem[arrow] = 0x7F                       # ' ': the arrow just pressed blinks off
	ld a, ' '
	ld [de], a
;>     ClearScreenArea(coord(3, 0), 15, 1)
	push hl
	push hl
	ld hl, (0) * SCREEN_WIDTH + (3) + wTileMap
	ld bc, ((1) & $ff) << 8 + ((15) & $ff)
	call ClearScreenArea
;>     DrawPlayerOrBirdSprite(mem[p], BIRD_BASE_TILE)
	pop hl
	ld a, [hl]
	ld b, BIRD_BASE_TILE
	call DrawPlayerOrBirdSprite
;>     PlaceString(addr(wNameBuffer), coord(3, 0))
	ld hl, (0) * SCREEN_WIDTH + (3) + wTileMap
	ld de, wNameBuffer
	call PlaceString
;>     DelayFrames(15)
	ld c, 15
	call DelayFrames
;>     mem[coord(18, 0)] = 0xED                # '▲'
	ld hl, (0) * SCREEN_WIDTH + (18) + wTileMap
	ld [hl], '▲'
;>     mem[coord(19, 0)] = 0xEE                # '▼'
	ld hl, (0) * SCREEN_WIDTH + (19) + wTileMap
	ld [hl], '▼'
	pop hl
;>     while True:
.inputLoop
;>         DelayFrame()
	push hl
	call DelayFrame
;>         JoypadLowSensitivity()
	call JoypadLowSensitivity
;>         pressed = hJoy5
	ldh a, [hJoy5]
	ld b, a
;>         if pressed & (PAD_A | PAD_B | PAD_UP | PAD_DOWN):
;>             break
	pop hl
	and PAD_A | PAD_B | PAD_UP | PAD_DOWN
	jr z, .inputLoop
;>     if pressed & PAD_A:
;>@a1         PlaySound(SFX_HEAL_AILMENT)
;>@a2         wDestinationMap = mem[p]
;>@a3         wStatusFlags6 |= 1 << BIT_FLY_WARP
;>@a4         wStatusFlags7 |= 1 << BIT_USED_FLY
;>@a5         break
	bit B_PAD_A, b
	jr nz, .pressedA
;>     PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;>     if pressed & PAD_UP:
;>@u0         while True:                         # the next visited town; after the last comes the first
;>@u1             arrow = coord(18, 0)
;>@u3             p += 1
;>@u4             if mem[p] == 0xFF:
;>@u5                 p = addr(wFlyLocationsList)
;>@u6                 break
;>@u7             if mem[p] != NOT_VISITED:
;>@u8                 break
	bit B_PAD_UP, b
	jr nz, .pressedUp
;>     elif pressed & PAD_DOWN:
;>@d0         while True:                         # the previous visited town; before the first comes the last
;>@d1             arrow = coord(19, 0)
;>@d3             p -= 1
;>@d4             if mem[p] == 0xFF:
;>@d5                 p = addr(wFlyLocationsList) + NUM_CITY_MAPS
;>@d6                 continue
;>@d7             if mem[p] != NOT_VISITED:
;>@d8                 break
	bit B_PAD_DOWN, b
	jr nz, .pressedDown
;>     else:
;>         break                               # B
	jr .pressedB
.pressedA
;=@a1
	ld a, SFX_HEAL_AILMENT
	call PlaySound
;=@a2
	ld a, [hl]
	ld [wDestinationMap], a
;=@a3
	ld hl, wStatusFlags6
	set BIT_FLY_WARP, [hl]
	ASSERT wStatusFlags6 + 1 == wStatusFlags7
;=@a4
	inc hl
	set BIT_USED_FLY, [hl]
.pressedB
;> wTownMapSpriteBlinkingEnabled = 0
	xor a
	ld [wTownMapSpriteBlinkingEnabled], a
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> wUpdateSpritesEnabled = saved
	pop hl
	pop af
	ld [hl], a
;> return
	ret
.pressedUp
;=@u1
	ld de, (0) * SCREEN_WIDTH + (18) + wTileMap
;=@u3
	inc hl
;=@u4
	ld a, [hl]
	cp $ff
	jr z, .wrapToStartOfList
;=@u7
	cp NOT_VISITED
	jr z, .pressedUp ; skip past unvisited towns
;=@u8
	jp .townMapFlyLoop
.wrapToStartOfList
;=@u5
	ld hl, wFlyLocationsList
;=@u6
	jp .townMapFlyLoop
.pressedDown
;=@d1
	ld de, (0) * SCREEN_WIDTH + (19) + wTileMap
;=@d3
	dec hl
;=@d4
	ld a, [hl]
	cp $ff
	jr z, .wrapToEndOfList
;=@d7
	cp NOT_VISITED
	jr z, .pressedDown ; skip past unvisited towns
;=@d8
	jp .townMapFlyLoop
.wrapToEndOfList
;=@d5
	ld hl, wFlyLocationsList + NUM_CITY_MAPS
;=@d6
	jr .pressedDown

;@ path: engine/items/town_map
ToText:
	db "To@"

;@ def BuildFlyLocationsList()
;@ wFlyLocationsList: each town's map number if its bit in wTownVisitedFlag is set, else NOT_VISITED, with $FF
;@ before and after the list.
;@ path: engine/items/town_map
BuildFlyLocationsList:
;> base = addr(wFlyAnimUsingCoordList)
;> mem[base] = 0xFF
	ld hl, wFlyAnimUsingCoordList
	ld [hl], $ff
;> p = base + 1
	inc hl
;> visited = mem[addr(wTownVisitedFlag)] | mem[addr(wTownVisitedFlag) + 1] << 8
	ld a, [wTownVisitedFlag]
	ld e, a
	ld a, [wTownVisitedFlag + 1]
	ld d, a
;>@lp for town in range(NUM_CITY_MAPS):
	ld bc, ((0) & $ff) << 8 + ((NUM_CITY_MAPS) & $ff)
.loop
;>     here = visited & 1
;>     visited >>= 1
	srl d
	rr e
;>     value = NOT_VISITED
	ld a, NOT_VISITED
;>     if here:
;>         value = town                        # its map number
	jr nc, .notVisited
	ld a, b ; store the map number of the town if it has been visited
.notVisited
;>     mem[p] = value
;>     p += 1
	ld [hl], a
	inc hl
;=@lp
	inc b
	dec c
	jr nz, .loop
;> mem[p] = 0xFF
	ld [hl], $ff
;> return
	ret

;@ path: engine/items/town_map
TownMapUpArrow:
	db $00, $00, $10, $38, $7c, $fe, $fe, $00
;@ path: engine/items/town_map
TownMapUpArrowEnd:

;@ def LoadTownMap()
;@ Draw the Town Map screen: a border, the map tiles and nest icon loaded with the LCD off, then the map itself
;@ unpacked from CompressedMap (each byte: tile $60 + high nibble, repeated low-nibble times; 0 ends it).
;@ path: engine/items/town_map
LoadTownMap:
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> UpdateSprites()
	call UpdateSprites
;> TextBoxBorder(coord(0, 0), 0x12, 0x12)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, $12
	ld c, $12
	call TextBoxBorder
;> DisableLCD()
	call DisableLCD
;> FarCopyData2(BANK(WorldMapTileGraphics), WorldMapTileGraphics, addr(vChars2) + 0x60 * 16,
;>              WorldMapTileGraphicsEnd - WorldMapTileGraphics)
	ld hl, WorldMapTileGraphics
	ld de, vChars2 + TILE_SIZE * $60
	ld bc, WorldMapTileGraphicsEnd - WorldMapTileGraphics
	ld a, BANK(WorldMapTileGraphics)
	call FarCopyData2
;> FarCopyDataDouble(BANK(MonNestIcon), MonNestIcon, addr(vSprites) + 4 * 16, MonNestIconEnd - MonNestIcon)
	ld hl, MonNestIcon
	ld de, vSprites + TILE_SIZE * $04
	ld bc, MonNestIconEnd - MonNestIcon
	ld a, BANK(MonNestIcon)
	call FarCopyDataDouble
;> dest = coord(0, 0)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
;> src = CompressedMap
	ld de, CompressedMap
;>@nt while mem[src]:
.nextTile
	ld a, [de]
	and a
	jr z, .done
;>     run = mem[src]
	ld b, a
;>     n = run & 0xF or 256                    # how often
	and $f
	ld c, a
;>     tile = 0x60 + (run >> 4)                # which tile
	ld a, b
	swap a
	and $f
	add $60
.writeRunLoop
;>@wr     for _ in range(n):
;>         mem[dest] = tile
;>         dest += 1
	ld [hli], a
;=@wr
	dec c
	jr nz, .writeRunLoop
;>     src += 1
	inc de
;=@nt
	jr .nextTile
.done
;> EnableLCD()
	call EnableLCD
;> RunPaletteCommand(SET_PAL_TOWN_MAP)
	ld b, SET_PAL_TOWN_MAP
	call RunPaletteCommand
;> Delay3()
	call Delay3
;> GBPalNormal()
	call GBPalNormal
;> wAnimCounter = 0
	xor a
	ld [wAnimCounter], a
;> wTownMapSpriteBlinkingEnabled = 1
	inc a
	ld [wTownMapSpriteBlinkingEnabled], a
	ret

;@ path: engine/items/town_map
CompressedMap:
	db $7f, $75, $6c, $73, $81, $44, $6c, $71, $64, $81, $42, $62, $51, $64, $71, $c1
	db $73, $51, $74, $62, $41, $62, $71, $61, $51, $73, $64, $71, $63, $c1, $61, $b1
	db $41, $62, $c1, $61, $c1, $67, $71, $63, $71, $b1, $42, $62, $71, $61, $71, $61
	db $73, $51, $72, $51, $73, $51, $43, $62, $71, $61, $71, $61, $71, $65, $71, $63
	db $71, $43, $62, $71, $61, $71, $61, $71, $b1, $a1, $63, $71, $63, $71, $43, $62
	db $72, $51, $61, $71, $43, $a1, $61, $71, $63, $71, $43, $61, $b1, $a1, $61, $71
	db $61, $71, $61, $43, $61, $51, $74, $91, $42, $b1, $42, $61, $71, $61, $71, $b1
	db $43, $a1, $64, $71, $b1, $42, $43, $61, $51, $b1, $f1, $45, $61, $74, $43, $43
	db $a1, $71, $41, $f1, $42, $91, $63, $71, $62, $44, $44, $f1, $41, $d1, $e1, $72
	db $51, $73, $61, $b1, $44, $43, $91, $71, $81, $42, $a1, $61, $71, $b1, $48, $43
	db $61, $51, $71, $e1, $c1, $e2, $d1, $49, $4f, $45, $00

;@ def ExitTownMap()
;@ Leave the Town Map: stop the blinking, clear the screen and sprites and load the usual graphics again.
;@ path: engine/items/town_map
ExitTownMap:
; clear town map graphics data and load usual graphics data
;> wTownMapSpriteBlinkingEnabled = 0
	xor a
	ld [wTownMapSpriteBlinkingEnabled], a
;> GBPalWhiteOut()
	call GBPalWhiteOut
;> ClearScreen()
	call ClearScreen
;> ClearSprites()
	call ClearSprites
;> LoadPlayerSpriteGraphics()
	call LoadPlayerSpriteGraphics
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> UpdateSprites()
	call UpdateSprites
;> return RunDefaultPaletteCommand()
	jp RunDefaultPaletteCommand

;@ def DrawPlayerOrBirdSprite(place: a, tile: b)
;@ Put the player (tile 0) or the bird (BIRD_BASE_TILE) on the map at place's position, copy its name into
;@ wNameBuffer and save the sprites to wShadowOAMBackup.
;@ test: place = rand(0, 0xF7)
;@ path: engine/items/town_map
DrawPlayerOrBirdSprite:
; a = map number
; b = OAM base tile
;> wOAMBaseTile = tile
	push af
	ld a, b
	ld [wOAMBaseTile], a
	pop af
;> name = LoadTownMapEntry(place, addr(wTownMapCoords))
	ld de, wTownMapCoords
	call LoadTownMapEntry
;> # (TownMapCoordsToOAMCoords also writes its two bytes to the name's ROM address: the cartridge ignores them)
;> y, x, _ = TownMapCoordsToOAMCoords(mem[addr(wTownMapCoords)], name)
	ld a, [de]
	push hl
	call TownMapCoordsToOAMCoords
;> WritePlayerOrBirdSpriteOAM(y, x)
	call WritePlayerOrBirdSpriteOAM
;> d = addr(wNameBuffer)
	pop hl
	ld de, wNameBuffer
;>@lp while True:
.loop
;>     ch = mem[name]
;>     name += 1
	ld a, [hli]
;>     mem[d] = ch
	ld [de], a
;>     d += 1
	inc de
;>     if ch == 0x50:                          # '@'
;>         break
	cp '@'
	jr nz, .loop
;> return CopyData(addr(wShadowOAM), addr(wShadowOAMBackup), OAM_COUNT * 4)
	ld hl, wShadowOAM
	ld de, wShadowOAMBackup
	ld bc, OAM_COUNT * 4
	jp CopyData

;@ def DisplayWildLocations()
;@ A nest icon on the Town Map for every place species wPokedexNum lives (Cerulean Cave is never shown), and the
;@ player; "AREA UNKNOWN" if there is none.
;@ test: hLoadedROMBank = 0x1C    # the bank this code runs in (the far call returns to it)
;@ test: wCurMap = rand(0, 0xF7)
;@ test: wStatusFlags5 = 1 << BIT_NO_TEXT_DELAY    # print without waiting for frames
;@ path: engine/items/town_map
DisplayWildLocations:
;> farcall(FindWildLocationsOfMon)           # the list of map indexes, in wBuffer (= wTownMapCoords)
	ld b, BANK(FindWildLocationsOfMon)
	ld hl, FindWildLocationsOfMon
	call Bankswitch
;> ZeroOutDuplicatesInList()
	call ZeroOutDuplicatesInList
;> oam = addr(wShadowOAM)
	ld hl, wShadowOAM
;> p = addr(wTownMapCoords)
	ld de, wTownMapCoords
;> while mem[p] != 0xFF:
.loop
	ld a, [de]
	cp $ff
	jr z, .exitLoop
;>     if mem[p]:
	and a
	jr z, .nextEntry
;>         LoadTownMapEntry(mem[p], p)         # the map number becomes its map position
	push hl
	call LoadTownMapEntry
	pop hl
;>         if mem[p] != 0x19:                  # Cerulean Cave
	ld a, [de]
	cp $19 ; Cerulean Cave's coordinates
	jr z, .nextEntry ; skip Cerulean Cave
;>             _, _, oam = TownMapCoordsToOAMCoords(mem[p], oam)
	call TownMapCoordsToOAMCoords
;>             mem[oam] = 4                    # the nest icon tile
	ld a, $4 ; nest icon tile no.
	ld [hli], a
;>             mem[oam + 1] = 0
;>             oam += 2
	xor a
	ld [hli], a
.nextEntry
;>     p += 1
	inc de
	jr .loop
.exitLoop
;> if oam & 0xFF == 0:                         # no icon written
	ld a, l
	and a ; were any OAM entries written?
	jr nz, .drawPlayerSprite
; if no OAM entries were written, print area unknown text
;>     TextBoxBorder(coord(1, 7), 2, 15)
	ld hl, (7) * SCREEN_WIDTH + (1) + wTileMap
	ld b, 2
	ld c, 15
	call TextBoxBorder
;>     PlaceString(AreaUnknownText, coord(2, 9))
	ld hl, (9) * SCREEN_WIDTH + (2) + wTileMap
	ld de, AreaUnknownText
	call PlaceString
	jr .done
;> else:
;>     DrawPlayerOrBirdSprite(wCurMap, 0)
.drawPlayerSprite
	ld a, [wCurMap]
	ld b, $0
	call DrawPlayerOrBirdSprite
.done
;> return CopyData(addr(wShadowOAM), addr(wShadowOAMBackup), OAM_COUNT * 4)
	ld hl, wShadowOAM
	ld de, wShadowOAMBackup
	ld bc, OAM_COUNT * 4
	jp CopyData

;@ path: engine/items/town_map
AreaUnknownText:
	db " AREA UNKNOWN@"

;@ def TownMapCoordsToOAMCoords(pos: a, oam: hl) -> (b, c, hl)
;@ A map position (y in the high nibble, x in the low one, in 8-pixel steps) as sprite coordinates y * 8 + 24 and
;@ x * 8 + 24, returned and written to oam.
;@ test: oam = rand(0xC000, 0xDE00)
;@ path: engine/items/town_map
TownMapCoordsToOAMCoords:
; in: lower nybble of a = x, upper nybble of a = y
; out: b and [hl] = (y * 8) + 24, c and [hl+1] = (x * 8) + 24
;> # (pos is kept)
	push af
;> y = (pos & 0xF0) // 2 + 24
	and $f0
	srl a
	add 24
	ld b, a
;> mem[oam] = y
;> oam += 1
	ld [hli], a
;> x = (pos & 0x0F) * 8 + 24
	pop af
	and $f
	swap a
	srl a
	add 24
	ld c, a
;> mem[oam] = x
;> oam += 1
	ld [hli], a
;> return y, x, oam
	ret

;@ def WritePlayerOrBirdSpriteOAM(y: b, x: c)
;@ The player's 2x2 sprite goes into OAM slots 36-39, the bird's (wOAMBaseTile not 0) into slots 32-35.
;@ path: engine/items/town_map
WritePlayerOrBirdSpriteOAM:
;> return WriteTownMapSpriteOAM(addr(wShadowOAMSprite36) if wOAMBaseTile == 0 else addr(wShadowOAMSprite32), y, x)
	ld a, [wOAMBaseTile]
	and a
	ld hl, wShadowOAMSprite36 ; for player sprite
	jr z, WriteTownMapSpriteOAM
	ld hl, wShadowOAMSprite32 ; for bird sprite

;@ def WriteTownMapSpriteOAM(oam: hl, y: b, x: c)
;@ A 2x2 sprite centred on (y, x): 4 pixels left and, through the carry out of x - 4, 3 or 4 pixels up.
;@ test: oam = rand(0xC000, 0xDE00)
;@ path: engine/items/town_map
WriteTownMapSpriteOAM:
;> yx = ((y << 8 | x) + 0xFCFC) & 0xFFFF
;> return WriteAsymmetricMonPartySpriteOAM(oam, yx >> 8, yx & 0xFF)
	push hl

; Subtract 4 from c (X coord) and 4 from b (Y coord). However, the carry from c
; is added to b, so the net result is that only 3 is subtracted from b.
	ld hl, ((-4) & $ff) << 8 + ((-4) & $ff)
	add hl, bc

	ld b, h
	ld c, l
	pop hl

;@ def WriteAsymmetricMonPartySpriteOAM(oam: hl, y: b, x: c)
;@ Four OAM entries for a 2x2 sprite with four different tiles from wOAMBaseTile on (which it advances by 4), for
;@ sprites that are not mirror-symmetric.
;@ test: oam = rand(0xC000, 0xDE00)
;@ path: engine/items/town_map
WriteAsymmetricMonPartySpriteOAM:
; Writes 4 OAM blocks for a helix mon party sprite, since it does not have
; a vertical line of symmetry.
;>@ro for row in range(2):
	ld de, ((2) & $ff) << 8 + ((2) & $ff)
.loop
;>     x0 = x                                  # (the counts are kept too)
	push de
	push bc
.innerLoop
;>@co     for col in range(2):
;>         mem[oam] = y
;>         oam += 1
	ld a, b
	ld [hli], a
;>         mem[oam] = x
;>         oam += 1
	ld a, c
	ld [hli], a
;>         mem[oam] = wOAMBaseTile
;>         oam += 1
	ld a, [wOAMBaseTile]
	ld [hli], a
;>         wOAMBaseTile += 1
	inc a
	ld [wOAMBaseTile], a
;>         mem[oam] = 0                        # attributes
;>         oam += 1
	xor a
	ld [hli], a
;>         # (the row count is raised too; it comes back below)
	inc d
;>         x = (x + 8) & 0xFF
	ld a, 8
	add c
	ld c, a
;=@co
	dec e
	jr nz, .innerLoop
;>     x = x0
	pop bc
;>     # (the counts come back)
	pop de
;>     y = (y + 8) & 0xFF
	ld a, 8
	add b
	ld b, a
;=@ro
	dec d
	jr nz, .loop
;> return
	ret

;@ def WriteSymmetricMonPartySpriteOAM(oam: hl, y: b, x: c)
;@ Four OAM entries for a mirror-symmetric 2x2 sprite: each row shows one tile twice, the right half X-flipped,
;@ so it needs only two tiles from wOAMBaseTile on (which it advances by 4).
;@ test: oam = rand(0xC000, 0xDE00)
;@ path: engine/items/town_map
WriteSymmetricMonPartySpriteOAM:
; Writes 4 OAM blocks for a mon party sprite other than a helix. All the
; sprites other than the helix one have a vertical line of symmetry which allows
; the X-flip OAM bit to be used so that only 2 rather than 4 tile patterns are
; needed.
;> wSymmetricSpriteOAMAttributes = 0
	xor a
	ld [wSymmetricSpriteOAMAttributes], a
;>@ro for row in range(2):
	ld de, ((2) & $ff) << 8 + ((2) & $ff)
.loop
;>     x0 = x                                  # (the counts are kept too)
	push de
	push bc
.innerLoop
;>@co     for col in range(2):
;>         mem[oam] = y
;>         oam += 1
	ld a, b
	ld [hli], a ; Y
;>         mem[oam] = x
;>         oam += 1
	ld a, c
	ld [hli], a ; X
;>         mem[oam] = wOAMBaseTile
;>         oam += 1
	ld a, [wOAMBaseTile]
	ld [hli], a ; tile
;>         mem[oam] = wSymmetricSpriteOAMAttributes
;>         oam += 1
	ld a, [wSymmetricSpriteOAMAttributes]
	ld [hli], a ; attributes
;>         wSymmetricSpriteOAMAttributes ^= OAM_XFLIP     # the right half mirrored
	xor OAM_XFLIP
	ld [wSymmetricSpriteOAMAttributes], a
;>         # (the row count is raised too; it comes back below)
	inc d
;>         x = (x + 8) & 0xFF
	ld a, 8
	add c
	ld c, a
;=@co
	dec e
	jr nz, .innerLoop
;>     x = x0
	pop bc
;>     # (the counts come back)
	pop de
;>     wOAMBaseTile += 2
	push hl
	ld hl, wOAMBaseTile
	inc [hl]
	inc [hl]
	pop hl
;>     y = (y + 8) & 0xFF
	ld a, 8
	add b
	ld b, a
;=@ro
	dec d
	jr nz, .loop
;> return
	ret

;@ def ZeroOutDuplicatesInList()
;@ In the $FF-terminated list at wBuffer, replace every repeat of an earlier entry with 0.
;@ test: n = rand(0, 40); [mem.__setitem__(wBuffer + i, rand(0, 12)) for i in range(n)]; mem[wBuffer + n] = 0xFF
;@ path: engine/items/town_map
ZeroOutDuplicatesInList:
; replace duplicate bytes in the list of wild pokemon locations with 0
;> p = addr(wBuffer)
	ld de, wBuffer
;>@ol while True:
;>     value = mem[p]
;>     p += 1
.loop
	ld a, [de]
	inc de
;>     if value == 0xFF:
;>         return
	cp $ff
	ret z
;>     q = p
	ld c, a
	ld l, e
	ld h, d
;>@il     while mem[q] != 0xFF:
.zeroDuplicatesLoop
	ld a, [hl]
	cp $ff
	jr z, .loop
;>         if mem[q] == value:
	cp c
	jr nz, .skipZeroing
;>             mem[q] = 0                      # a repeat
	xor a
	ld [hl], a
.skipZeroing
;>         q += 1
	inc hl
;=@il
	jr .zeroDuplicatesLoop

;@ def LoadTownMapEntry(place: a, pos: de) -> hl
;@ Look up a map's Town Map entry: its position goes to [pos], and the address of its name is returned. Outdoor
;@ maps have one entry each; an indoor map takes the first InternalMapEntries entry whose map bound is above it.
;@ test: place = rand(0, 0xF7); pos = rand(0xC000, 0xDE00)
;@ path: engine/items/town_map
LoadTownMapEntry:
; in: a = map number
; out: lower nybble of [de] = x, upper nybble of [de] = y, hl = address of name
;> if place < FIRST_INDOOR_MAP:
;>@ex     entry = ExternalMapEntries + 3 * place
;> else:
	cp FIRST_INDOOR_MAP
	jr c, .external
;>     entry = InternalMapEntries               # 4 bytes each: map bound, position, name
	ld bc, 4
	ld hl, InternalMapEntries
;>@lp     while place >= mem[entry]:
.loop
	cp [hl]
	jr c, .foundEntry
;>         entry += 4
	add hl, bc
;=@lp
	jr .loop
.foundEntry
;>     entry += 1                               # past the bound
	inc hl
	jr .readEntry
.external
;=@ex
	ld hl, ExternalMapEntries
	ld c, a
	ld b, 0
	add hl, bc
	add hl, bc
	add hl, bc
.readEntry
;> mem[pos] = mem[entry]
	ld a, [hli]
	ld [de], a
;> return mem16[entry + 1]
	ld a, [hli]
	ld h, [hl]
	ld l, a
	ret


