;@ def TownMapSpriteBlinkingAnimation()
;@ One frame of the Town Map's blinking: on frame 25 of each 50 the sprites (but the last four) are hidden below
;@ the screen, on frame 50 they come back from wShadowOAMBackup.
;@ path: engine/items/town_map
TownMapSpriteBlinkingAnimation::
;> count = (wAnimCounter + 1) & 0xFF
	ld a, [wAnimCounter]
	inc a
;> if count == 25:                             # hide the sprites below the screen
;>@h1     p = addr(wShadowOAMSprite00YCoord)
;>@h2     step = OBJ_SIZE
;>@h3     for _ in range(OAM_COUNT - 4):
;>@h4         mem[p] = SCREEN_HEIGHT_PX + OAM_Y_OFS
;>@h5         p += step
;>@h6     count = 25
	cp 25
	jr z, .hideSprites
;> elif count == 50:
	cp 50
	jr nz, .done
; show sprites when the counter reaches 50
;>     CopyData(addr(wShadowOAMBackup), addr(wShadowOAM), (OAM_COUNT - 4) * 4)
	ld hl, wShadowOAMBackup
	ld de, wShadowOAM
	ld bc, (OAM_COUNT - 4) * 4
	call CopyData
;>     count = 0
	xor a
	jr .done
.hideSprites
;=@h1
	ld hl, wShadowOAMSprite00YCoord
;=@h3
	ld b, OAM_COUNT - 4
;=@h2
	ld de, OBJ_SIZE
.hideSpritesLoop
;=@h4
	ld [hl], SCREEN_HEIGHT_PX + OAM_Y_OFS
;=@h5
	add hl, de
;=@h3
	dec b
	jr nz, .hideSpritesLoop
;=@h6
	ld a, 25
.done
;> wAnimCounter = count
	ld [wAnimCounter], a
;> return DelayFrame()
	jp DelayFrame
;@ path: engine/gfx/mon_icons
;@ def AnimatePartyMon_ForceSpeed1()
;@ Animate the first party icon at the middle speed (as on the naming screen).
;@ test: skip waits a frame
AnimatePartyMon_ForceSpeed1:
;> wCurrentMenuItem = 0
;> return GetAnimationSpeed(1)
	xor a
	ld [wCurrentMenuItem], a
	ld b, a
	inc a
	jr GetAnimationSpeed

; wPartyMenuHPBarColors contains the party mon's health bar colors
; 0: green
; 1: yellow
; 2: red
;@ path: engine/gfx/mon_icons
;@ def AnimatePartyMon()
;@ Animate the selected party menu icon at the speed of its HP bar color: the lower the HP, the slower.
;@ test: skip waits a frame
AnimatePartyMon::
;> return GetAnimationSpeed(wPartyMenuHPBarColors[wCurrentMenuItem])
	ld hl, wPartyMenuHPBarColors
	ld a, [wCurrentMenuItem]
	ld c, a
	ld b, 0
	add hl, bc
	ld a, [hl]

;@ path: engine/gfx/mon_icons
;@ def GetAnimationSpeed(color: a)
;@ One frame of the party icon animation for icon wCurrentMenuItem: wAnimCounter counts up to twice the speed
;@ for the HP bar color (one frame more on a plain Game Boy than on an SGB). At the speed the icon
;@ switches to its second frame (balls and helix fossils hop a pixel instead), and at 0 all icons go back to
;@ their first frame.
;@ test: skip waits a frame
GetAnimationSpeed:
;> p = PartyMonSpeeds + color
	ld c, a
	ld hl, PartyMonSpeeds
	add hl, bc
;> speed = u8((wOnSGB ^ 1) + mem[p])            # one frame more on a plain Game Boy
	ld a, [wOnSGB]
	xor $1
	add [hl]
	ld c, a
;> double = u8(2 * speed)
	add a
	ld b, a
;> counter = wAnimCounter
	ld a, [wAnimCounter]
;> if counter == 0:                              # all icons back to their first frame
;>@reset     CopyData(addr(wMonPartySpritesSavedOAM), addr(wShadowOAM), OBJ_SIZE * 4 * PARTY_LENGTH)
	and a
	jr z, .resetSprites
;> elif counter == speed:                        # this icon's second frame
;>@tile     tile = addr(wShadowOAMSprite00TileID) + OBJ_SIZE * 4 * wCurrentMenuItem
;>@step     step = ICONOFFSET
;>@hop     if mem[tile] in (ICON_BALL << 2, ICON_HELIX << 2):
;>@up         tile -= 2                                 # move the Y coordinate instead
;>@one         step = 1
;>@for     for i in range(4):
;>@add         mem[tile + i * OBJ_SIZE] = u8(mem[tile + i * OBJ_SIZE] + step)
	cp c
	jr z, .animateSprite
.incTimer
;> counter = u8(counter + 1)
	inc a
;> if counter == double:
	cp b
	jr nz, .skipResetTimer
;>     counter = 0
	xor a ; reset timer
.skipResetTimer
;> wAnimCounter = counter
	ld [wAnimCounter], a
;> DelayFrame()
	jp DelayFrame
.resetSprites
;=@reset
	push bc
	ld hl, wMonPartySpritesSavedOAM
	ld de, wShadowOAM
	ld bc, OBJ_SIZE * 4 * PARTY_LENGTH
	call CopyData
	pop bc
;=@reset
	xor a
	jr .incTimer
.animateSprite
;=@tile
	push bc
	ld hl, wShadowOAMSprite00TileID
	ld bc, OBJ_SIZE * 4
	ld a, [wCurrentMenuItem]
	call AddNTimes
;=@step
	ld c, ICONOFFSET
;=@hop
	ld a, [hl]
	cp ICON_BALL << 2
	jr z, .editCoords
	cp ICON_HELIX << 2
	jr nz, .editTileIDS
; ICON_BALL and ICON_HELIX only shake up and down
.editCoords
;=@up
	dec hl
	dec hl ; dec hl to the OAM y coord
;=@one
	ld c, $1 ; amount to increase the y coord by
; otherwise, load a second sprite frame
.editTileIDS
;=@for
	ld b, 4
	ld de, OBJ_SIZE
.loop
;=@add
	ld a, [hl]
	add c
	ld [hl], a
	add hl, de
;=@for
	dec b
	jr nz, .loop
;=@tile
	pop bc
	ld a, c
	jr .incTimer

; Party mon animations cycle between 2 frames.
; The members of the PartyMonSpeeds array specify the number of V-blanks
; that each frame lasts for green HP, yellow HP, and red HP in order.
; On the naming screen, the yellow HP speed is always used.
;@ path: engine/gfx/mon_icons
PartyMonSpeeds:
	db 5, 16, 32

;@ path: engine/gfx/mon_icons
;@ def LoadMonPartySpriteGfx()
;@ Load the tiles of all party icons into VRAM during VBlanks.
;@ test: skip copies to VRAM over several VBlanks
LoadMonPartySpriteGfx:
; Load mon party sprite tile patterns into VRAM during V-blank.
;> return LoadAnimSpriteGfx(MonPartySpritePointers, 0x1C)
	ld hl, MonPartySpritePointers
	ld a, $1c

;@ path: engine/gfx/mon_icons
;@ def LoadAnimSpriteGfx(table: hl, count: a)
;@ Copy `count` tile sets to VRAM during VBlanks, each given by a 6-byte entry at `table`: source, tile count,
;@ bank, destination.
;@ test: skip copies to VRAM over several VBlanks
LoadAnimSpriteGfx:
; Load animated sprite tile patterns into VRAM during V-blank. hl is the address
; of an array of structures that contain arguments for CopyVideoData and a is
; the number of structures in the array.
;> offset = 0
	ld bc, $0
;>@lp for _ in range(count):
.loop
;>     # (count, offset and table are kept)
	push af
	push bc
	push hl
;>     entry = table + offset
	add hl, bc
;>     src = mem16[entry]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;>     tiles = mem[entry + 2]
	ld a, [hli]
	ld c, a
;>     bank = mem[entry + 3]
	ld a, [hli]
	ld b, a
;>     dest = mem16[entry + 4]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     CopyVideoData(dest, src, bank, tiles)
	call CopyVideoData
	pop hl
	pop bc
;>     offset += 6
	ld a, $6
	add c
	ld c, a
;=@lp
	pop af
	dec a
	jr nz, .loop
;> return
	ret

;@ path: engine/gfx/mon_icons
;@ def LoadMonPartySpriteGfxWithLCDDisabled()
;@ Load the tiles of all party icons into VRAM at once, with the screen turned off meanwhile.
;@ test: skip turns the LCD off
LoadMonPartySpriteGfxWithLCDDisabled:
; Load mon party sprite tile patterns into VRAM immediately by disabling the
; LCD.
;> DisableLCD()
	call DisableLCD
;> table = MonPartySpritePointers
	ld hl, MonPartySpritePointers
;> count = 0x1C
	ld a, $1c
;> offset = 0
	ld bc, $0
;>@lp for _ in range(count):
.loop
;>     # (count, offset and table are kept)
	push af
	push bc
	push hl
;>     entry = table + offset
	add hl, bc
;>     src = mem16[entry]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
	push de
;>     size = mem[entry + 2] * TILE_SIZE
	ld a, [hli]
	ld c, a
	swap c
	ld b, $0
;>     bank = mem[entry + 3]
	ld a, [hli]
;>     dest = mem16[entry + 4]
	ld e, [hl]
	inc hl
	ld d, [hl]
;>     FarCopyData2(bank, src, dest, size)
	pop hl
	call FarCopyData2
	pop hl
	pop bc
;>     offset += 6
	ld a, $6
	add c
	ld c, a
;=@lp
	pop af
	dec a
	jr nz, .loop
;> EnableLCD()
	jp EnableLCD


;@ path: engine/gfx/mon_icons
