;@ path: engine/gfx/mon_icons
;@ def WriteMonPartySpriteOAMByPartyIndex()
;@ Put the icon of party Pokémon hPartyMonIndex into its row of the party menu OAM.
;@ test: hLoadedROMBank = 0x1C; hPartyMonIndex = rand(0, 5); mem[wPartySpecies + hPartyMonIndex] = rand(1, 190)
WriteMonPartySpriteOAMByPartyIndex:
; Write OAM blocks for the party mon in [hPartyMonIndex].
;> # (hl, de and bc are kept)
	push hl
	push de
	push bc
;> species = mem[addr(wPartySpecies) + hPartyMonIndex]
	ldh a, [hPartyMonIndex]
	ld hl, wPartySpecies
	ld e, a
	ld d, 0
	add hl, de
	ld a, [hl]
;> wOAMBaseTile = GetPartyMonSpriteID(species)
	call GetPartyMonSpriteID
	ld [wOAMBaseTile], a
;> WriteMonPartySpriteOAM(wOAMBaseTile)
	call WriteMonPartySpriteOAM
	pop bc
	pop de
	pop hl
	ret

;@ path: engine/gfx/mon_icons
;@ def WriteMonPartySpriteOAMBySpecies()
;@ Put the icon of species wMonPartySpriteSpecies at the top of the OAM.
;@ test: hLoadedROMBank = 0x1C; wMonPartySpriteSpecies = rand(1, 190)
WriteMonPartySpriteOAMBySpecies:
; Write OAM blocks for the party sprite of the species in
; [wMonPartySpriteSpecies].
;> hPartyMonIndex = 0
	xor a
	ldh [hPartyMonIndex], a
;> wOAMBaseTile = GetPartyMonSpriteID(wMonPartySpriteSpecies)
	ld a, [wMonPartySpriteSpecies]
	call GetPartyMonSpriteID
	ld [wOAMBaseTile], a
;> return WriteMonPartySpriteOAM(wOAMBaseTile)
	jr WriteMonPartySpriteOAM

;@ path: engine/gfx/mon_icons
;@ def UnusedPartyMonSpriteFunction()
;@ Unused, and broken: meant to load the icon tiles for wCurPartySpecies and show it, but it picks the wrong
;@ table entries.
;@ test: skip copies to VRAM over several VBlanks
UnusedPartyMonSpriteFunction:
; This function is unused and doesn't appear to do anything useful. It looks
; like it may have been intended to load the tile patterns and OAM data for
; the mon party sprite associated with the species in [wCurPartySpecies].
; However, its calculations are off and it loads garbage data.
;> icon = GetPartyMonSpriteID(wCurPartySpecies)
	ld a, [wCurPartySpecies]
	call GetPartyMonSpriteID
;> dest = addr(vSprites)                         # (icon is kept)
	push af
	ld hl, vSprites + TILE_SIZE * $00
;>@lt1 offset = u8(2 * icon)                        # .LoadTilePatterns below
;>@lt2 entry = MonPartySpritePointers + 3 * offset
	call .LoadTilePatterns
;>@lt6 CopyVideoData(dest, mem16[entry], mem[entry + 3], mem[entry + 2])
;> index = u8(icon + 0x54)
	pop af
	add $54
;> dest = addr(vSprites) + 4 * TILE_SIZE
	ld hl, vSprites + TILE_SIZE * $04
;>@ltb1 offset = u8(2 * index)
;>@ltb2 entry = MonPartySpritePointers + 3 * offset
	call .LoadTilePatterns
;>@ltb6 CopyVideoData(dest, mem16[entry], mem[entry + 3], mem[entry + 2])
;> wMonPartySpriteSpecies = 0
	xor a
	ld [wMonPartySpriteSpecies], a
;> return WriteMonPartySpriteOAMBySpecies()
	jr WriteMonPartySpriteOAMBySpecies

.LoadTilePatterns
;=@lt6
	push hl
;=@lt1
	add a
	ld c, a
	ld b, 0
;=@lt2
	ld hl, MonPartySpritePointers
	add hl, bc
	add hl, bc
	add hl, bc
;=@lt6
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;=@lt6
	ld a, [hli]
	ld c, a
;=@lt6
	ld a, [hli]
	ld b, a
;=@lt6
	pop hl
	jp CopyVideoData

;@ path: engine/gfx/mon_icons
;@ def WriteMonPartySpriteOAM(icon: a)
;@ Write the four OAM entries of the icon `icon` for party slot hPartyMonIndex (16 pixels per row), then save
;@ the whole party's OAM to wMonPartySpritesSavedOAM for the animation to come back to.
;@ test: hPartyMonIndex = rand(0, 5); icon = 4 * rand(0, 9)
WriteMonPartySpriteOAM:
; Write the OAM blocks for the first animation frame into the OAM buffer and
; make a copy at wMonPartySpritesSavedOAM.
;> # (icon is kept)
	push af
;> x = 0x10
	ld c, $10
;=@oam
	ld h, HIGH(wShadowOAM)
;> row = swap(hPartyMonIndex)                    # 16 bytes and 16 pixels per party slot
	ldh a, [hPartyMonIndex]
	swap a
;>@oam oam = addr(wShadowOAM) & 0xFF00 | row
	ld l, a
;> y = u8(row + 0x10)
	add $10
	ld b, a
;> if icon == ICON_HELIX << 2:
;>@asym     WriteAsymmetricMonPartySpriteOAM(oam, y, x)
	pop af
	cp ICON_HELIX << 2
	jr z, .helix
;> else:
;>     WriteSymmetricMonPartySpriteOAM(oam, y, x)
	call WriteSymmetricMonPartySpriteOAM
	jr .makeCopy
.helix
;=@asym
	call WriteAsymmetricMonPartySpriteOAM
; Make a copy of the OAM buffer with the first animation frame written so that
; we can flip back to it from the second frame by copying it back.
.makeCopy
;> CopyData(addr(wShadowOAM), addr(wMonPartySpritesSavedOAM), OBJ_SIZE * 4 * PARTY_LENGTH)
	ld hl, wShadowOAM
	ld de, wMonPartySpritesSavedOAM
	ld bc, OBJ_SIZE * 4 * PARTY_LENGTH
	jp CopyData

;@ path: engine/gfx/mon_icons
;@ def GetPartyMonSpriteID(species: a) -> a
;@ The party icon (ICON_* << 2) of `species`, from MonPartyData: one nybble per Pokédex number, two per byte.
;@ test: hLoadedROMBank = 0x1C; species = rand(1, 190)
GetPartyMonSpriteID:
;> wPokedexNum = species
	ld [wPokedexNum], a
;> Predef((IndexToPokedexPredef - PredefPointers) // 3)      # IndexToPokedex
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
;> number = wPokedexNum
	ld a, [wPokedexNum]
	ld c, a
;> index = u8(number - 1) // 2                   # two icons per byte
	dec a
	srl a
;> icons = mem[MonPartyData + index]
	ld hl, MonPartyData
	ld e, a
	ld d, 0
	add hl, de
	ld a, [hl]
;> icon = icons >> 4 if number & 1 else icons & 0xF
	bit 0, c ; even or odd?
	jr nz, .skipSwap
	swap a ; use lower nybble if pokedex num is even
.skipSwap
;> return icon << 2
	and $f0
	srl a ; value == ICON constant << 2
	srl a
	ret

;@ path: engine/gfx/mon_icons
MonPartyData:
	; Bulbasaur
	; Ivysaur
	db $77
	; Venusaur
	; Charmander
	db $70
	; Charmeleon
	; Charizard
	db $0
	; Squirtle
	; Wartortle
	db $55
	; Blastoise
	; Caterpie
	db $56
	; Metapod
	; Butterfree
	db $66
	; Weedle
	; Kakuna
	db $66
	; Beedrill
	; Pidgey
	db $64
	; Pidgeotto
	; Pidgeot
	db $44
	; Rattata
	; Raticate
	db $99
	; Spearow
	; Fearow
	db $44
	; Ekans
	; Arbok
	db $88
	; Pikachu
	; Raichu
	db $33
	; Sandshrew
	; Sandslash
	db $0
	; NidoranF
	; Nidorina
	db $0
