;@ path: engine/events/in_game_trades
;@ def DoInGameTradeDialogue()
;@ An NPC's in-game trade (wWhichTrade). TradeMons gives the Pokémon wanted and offered, the dialog set and the
;@ nickname. A finished trade only gets the "after" text. Otherwise the NPC asks, and on YES the trade is
;@ tried; the matching text follows.
;@ test: skip asks the player a question
DoInGameTradeDialogue:
; trigger the trade offer/action specified by wWhichTrade
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;>@p p = TradeMons + u8(16 * wWhichTrade - 2 * wWhichTrade)    # 14 bytes per trade
	ld hl, TradeMons
	ld a, [wWhichTrade]
	ld b, a
	swap a
	sub b
	sub b
;=@p
	ld c, a
	ld b, 0
	add hl, bc
;> wInGameTradeGiveMonSpecies = mem[p]
	ld a, [hli]
	ld [wInGameTradeGiveMonSpecies], a
;> wInGameTradeReceiveMonSpecies = mem[p + 1]
	ld a, [hli]
	ld [wInGameTradeReceiveMonSpecies], a
;> dialog = mem[p + 2]
	ld a, [hli]
	push af
;> CopyData(p + 3, addr(wInGameTradeMonNick), NAME_LENGTH)
	ld de, wInGameTradeMonNick
	ld bc, NAME_LENGTH
	call CopyData
;> t = InGameTradeTextPointers + 2 * dialog
	pop af
	ld l, a
	ld h, 0
	ld de, InGameTradeTextPointers
	add hl, hl
	add hl, de
;> wInGameTradeTextPointerTablePointer[0] = mem[t]
	ld a, [hli]
	ld [wInGameTradeTextPointerTablePointer], a
;> wInGameTradeTextPointerTablePointer[1] = mem[t + 1]
	ld a, [hl]
	ld [wInGameTradeTextPointerTablePointer + 1], a
;> InGameTrade_GetMonName(wInGameTradeGiveMonSpecies, addr(wInGameTradeGiveMonName))
	ld a, [wInGameTradeGiveMonSpecies]
	ld de, wInGameTradeGiveMonName
	call InGameTrade_GetMonName
;> InGameTrade_GetMonName(wInGameTradeReceiveMonSpecies, addr(wInGameTradeReceiveMonName))
	ld a, [wInGameTradeReceiveMonSpecies]
	ld de, wInGameTradeReceiveMonName
	call InGameTrade_GetMonName
;>@done done = FlagAction(addr(wCompletedInGameTradeFlags), wWhichTrade, FLAG_TEST)   # through FlagActionPredef
	ld hl, wCompletedInGameTradeFlags
	ld a, [wWhichTrade]
	ld c, a
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;=@done
	ld a, c
	and a
;> wInGameTradeTextPointerTableIndex = TRADETEXT_AFTER_TRADE
	ld a, TRADETEXT_AFTER_TRADE
	ld [wInGameTradeTextPointerTableIndex], a
;> if not done:
	jr nz, .printText
; if the trade hasn't been done yet
;>     wInGameTradeTextPointerTableIndex = TRADETEXT_WANNA_TRADE
	ASSERT TRADETEXT_WANNA_TRADE == 0
	xor a
	ld [wInGameTradeTextPointerTableIndex], a
;>     texts = wInGameTradeTextPointerTablePointer[0] | wInGameTradeTextPointerTablePointer[1] << 8
;>     PrintText(mem16[texts + 2 * wInGameTradeTextPointerTableIndex])
	call .printText
;>     wInGameTradeTextPointerTableIndex = TRADETEXT_NO_TRADE
	ld a, TRADETEXT_NO_TRADE
	ld [wInGameTradeTextPointerTableIndex], a
;>     YesNoChoice()
	call YesNoChoice
;>     if wCurrentMenuItem == 0 and not InGameTrade_DoTrade():
	ld a, [wCurrentMenuItem]
	and a
	jr nz, .printText
	call InGameTrade_DoTrade
	jr c, .printText
;>         PrintText(TradedForText)
	ld hl, TradedForText
	call PrintText
.printText
;> index = wInGameTradeTextPointerTableIndex
	ld hl, wInGameTradeTextPointerTableIndex
	ld a, [hld] ; wInGameTradeTextPointerTableIndex
	ld e, a
	ld d, 0
;> texts = wInGameTradeTextPointerTablePointer[0] | wInGameTradeTextPointerTablePointer[1] << 8
	ld a, [hld] ; wInGameTradeTextPointerTablePointer + 1
	ld l, [hl] ; wInGameTradeTextPointerTablePointer
	ld h, a
;> entry = texts + 2 * index
	add hl, de
	add hl, de
;> PrintText(mem16[entry])
	ld a, [hli]
	ld h, [hl]
	ld l, a
	jp PrintText

; copies name of species a to hl
;@ path: engine/events/in_game_trades
;@ def InGameTrade_GetMonName(species: a, dest: de)
;@ Copy the name of `species` to `dest`.
;@ test: hLoadedROMBank = 0x1C; species = rand(1, 190); dest = rand_ram(11)
InGameTrade_GetMonName:
;> wNamedObjectIndex = species
	push de
	ld [wNamedObjectIndex], a
;> GetMonName()
	call GetMonName
;> CopyData(addr(wNameBuffer), dest, NAME_LENGTH)
	ld hl, wNameBuffer
	pop de
	ld bc, NAME_LENGTH
	jp CopyData


;@ path: engine/events/in_game_trades
TradeMons:
; entries correspond to TRADE_FOR_* constants
	; The two instances of TRADE_DIALOGSET_EVOLUTION are a leftover
	; from the Japanese Blue trades, which used species that evolve.
	; TRADE_DIALOGSET_EVOLUTION did not refer to evolution in Japanese
	; Red/Green. Japanese Blue changed _AfterTrade2Text to say your Pokémon
	; "went and evolved" and also changed the trades to match. English
	; Red/Blue uses the original JP Red/Green trades but with the JP Blue
	; post-trade text. English Yellow changed _AfterTrade2Text to
	; not mention evolution.
	; used in ROUTE_11_GATE_2F
	db NIDORINO, NIDORINA, TRADE_DIALOGSET_CASUAL
	db "TERRY"
	ds $B - CHARLEN("TERRY"), '@'
	; used in ROUTE_2_TRADE_HOUSE
	db ABRA, MR_MIME, TRADE_DIALOGSET_CASUAL
	db "MARCEL"
	ds $B - CHARLEN("MARCEL"), '@'
	; unused
	db BUTTERFREE, BEEDRILL, TRADE_DIALOGSET_HAPPY
	db "CHIKUCHIKU"
	ds $B - CHARLEN("CHIKUCHIKU"), '@'
	; used in CINNABAR_LAB_FOSSIL_ROOM
	db PONYTA, SEEL, TRADE_DIALOGSET_CASUAL
	db "SAILOR"
	ds $B - CHARLEN("SAILOR"), '@'
	; used in VERMILION_TRADE_HOUSE
	db SPEAROW, FARFETCHD, TRADE_DIALOGSET_HAPPY
	db "DUX"
	ds $B - CHARLEN("DUX"), '@'
	; used in ROUTE_18_GATE_2F
	db SLOWBRO, LICKITUNG, TRADE_DIALOGSET_CASUAL
	db "MARC"
	ds $B - CHARLEN("MARC"), '@'
	; used in CERULEAN_TRADE_HOUSE
	db POLIWHIRL, JYNX, TRADE_DIALOGSET_EVOLUTION
	db "LOLA"
	ds $B - CHARLEN("LOLA"), '@'
	; used in CINNABAR_LAB_TRADE_ROOM
	db RAICHU, ELECTRODE, TRADE_DIALOGSET_EVOLUTION
	db "DORIS"
	ds $B - CHARLEN("DORIS"), '@'
	; used in CINNABAR_LAB_TRADE_ROOM
	db VENONAT, TANGELA, TRADE_DIALOGSET_HAPPY
	db "CRINKLES"
	ds $B - CHARLEN("CRINKLES"), '@'
	; used in UNDERGROUND_PATH_ROUTE_5
	db NIDORAN_M, NIDORAN_F, TRADE_DIALOGSET_HAPPY
	db "SPOT"
	ds $B - CHARLEN("SPOT"), '@'

;@ path: engine/events/in_game_trades
;@ def InGameTrade_DoTrade() -> carry
;@ The trade itself: the player picks a party Pokémon (carry if cancelled or the wrong species). It is marked
;@ as traded, the trade animation runs, the Pokémon is replaced by the NPC's (nickname, OT name and ID from
;@ the trade), which may evolve, and the map comes back.
;@ test: skip shows the party menu
InGameTrade_DoTrade:
;> wPartyMenuTypeOrMessageID = NORMAL_PARTY_MENU
	xor a ; NORMAL_PARTY_MENU
	ld [wPartyMenuTypeOrMessageID], a
;> wUpdateSpritesEnabled = 0xFF
	dec a
	ld [wUpdateSpritesEnabled], a
;> cancelled = DisplayPartyMenu()
	call DisplayPartyMenu
	push af
;> InGameTrade_RestoreScreen()
	call InGameTrade_RestoreScreen
	pop af
;> if cancelled:
;>@nt     wInGameTradeTextPointerTableIndex = TRADETEXT_NO_TRADE
;>@fail     return True
	ld a, TRADETEXT_NO_TRADE
	jp c, .tradeFailed ; jump if the player didn't select a pokemon
;> if wCurPartySpecies != wInGameTradeGiveMonSpecies:     # the same failure exit, at .tradeFailed
;>@wrong     wInGameTradeTextPointerTableIndex = TRADETEXT_WRONG_MON
;>@wrongret     return True
	ld a, [wInGameTradeGiveMonSpecies]
	ld b, a
	ld a, [wCurPartySpecies]
	cp b
	ld a, TRADETEXT_WRONG_MON
	jr nz, .tradeFailed ; jump if the selected mon's species is not the required one
;> wCurEnemyLevel = mem[AddNTimes(wPartyMon1Level, PARTYMON_STRUCT_LENGTH, wWhichPokemon)]
	ld a, [wWhichPokemon]
	ld hl, wPartyMon1Level
	ld bc, PARTYMON_STRUCT_LENGTH
	call AddNTimes
	ld a, [hl]
	ld [wCurEnemyLevel], a
;> FlagAction(addr(wCompletedInGameTradeFlags), wWhichTrade, FLAG_SET)     # through FlagActionPredef
	ld hl, wCompletedInGameTradeFlags
	ld a, [wWhichTrade]
	ld c, a
	ld b, FLAG_SET
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> PrintText(ConnectCableText)
	ld hl, ConnectCableText
	call PrintText
;> which, level = wWhichPokemon, wCurEnemyLevel
	ld a, [wWhichPokemon]
	push af
	ld a, [wCurEnemyLevel]
	push af
;> LoadHpBarAndStatusTilePatterns()
	call LoadHpBarAndStatusTilePatterns
;> InGameTrade_PrepareTradeData()
	call InGameTrade_PrepareTradeData
;> InternalClockTradeAnim()                     # a predef
	ld a, (InternalClockTradeAnimPredef - PredefPointers) / 3
	call Predef
;> wCurEnemyLevel = level
	pop af
	ld [wCurEnemyLevel], a
;> wWhichPokemon = which
	pop af
	ld [wWhichPokemon], a
;> wCurPartySpecies = wInGameTradeReceiveMonSpecies
	ld a, [wInGameTradeReceiveMonSpecies]
	ld [wCurPartySpecies], a
;> wMonDataLocation = 0
	xor a
	ld [wMonDataLocation], a ; not used
;> wRemoveMonFromBox = 0
	ld [wRemoveMonFromBox], a
;> RemovePokemon()
	call RemovePokemon
;> wMonDataLocation = 0x80                      # no nickname prompt
	ld a, $80 ; prevent the player from naming the mon
	ld [wMonDataLocation], a
;> AddPartyMon()
	call AddPartyMon
;> InGameTrade_CopyDataToReceivedMon()
	call InGameTrade_CopyDataToReceivedMon
;> InGameTrade_CheckForTradeEvo()               # in another bank
	ld hl, InGameTrade_CheckForTradeEvo
	ld b, BANK(InGameTrade_CheckForTradeEvo)
	call Bankswitch
;> ClearScreen()
	call ClearScreen
;> InGameTrade_RestoreScreen()
	call InGameTrade_RestoreScreen
;> RedrawMapView()                              # in another bank
	ld b, BANK(RedrawMapView)
	ld hl, RedrawMapView
	call Bankswitch
;> wInGameTradeTextPointerTableIndex = TRADETEXT_THANKS
;> return False
	and a
	ld a, TRADETEXT_THANKS
	jr .tradeSucceeded
.tradeFailed
;=@fail
	scf
.tradeSucceeded
	ld [wInGameTradeTextPointerTableIndex], a
	ret

;@ path: engine/events/in_game_trades
;@ def InGameTrade_RestoreScreen()
;@ Back from the party menu or trade animation: restore the map screen, its tiles and palettes, and reload the
;@ map's wild Pokémon data.
InGameTrade_RestoreScreen:
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> RestoreScreenTilesAndReloadTilePatterns()
	call RestoreScreenTilesAndReloadTilePatterns
;> ReloadTilesetTilePatterns()
	call ReloadTilesetTilePatterns
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> Delay3()
	call Delay3
;> LoadGBPal()
	call LoadGBPal
;> DelayFrames(10)
	ld c, 10
	call DelayFrames
;> LoadWildData()                               # in another bank
	ld b, BANK(LoadWildData)
	ld hl, LoadWildData
	jp Bankswitch

;@ path: engine/events/in_game_trades
;@ def InGameTrade_PrepareTradeData()
;@ Fill in the trade animation's data: both species, both OT names (the NPC's is "TRAINER"), the player's OT
;@ ID and a random one for the NPC.
;@ test: hLoadedROMBank = 0x1C; wWhichPokemon = rand(0, 5)
InGameTrade_PrepareTradeData:
;> wTradedPlayerMonSpecies = wInGameTradeGiveMonSpecies
	ld hl, wTradedPlayerMonSpecies
	ld a, [wInGameTradeGiveMonSpecies]
	ld [hli], a ; wTradedPlayerMonSpecies
;> wTradedEnemyMonSpecies = wInGameTradeReceiveMonSpecies
	ld a, [wInGameTradeReceiveMonSpecies]
	ld [hl], a ; wTradedEnemyMonSpecies
;> ot = AddNTimes(addr(wPartyMonOT), NAME_LENGTH, wWhichPokemon)
	ld hl, wPartyMonOT
	ld bc, NAME_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;> InGameTrade_CopyData(ot, addr(wTradedPlayerMonOT), NAME_LENGTH)
	ld de, wTradedPlayerMonOT
	ld bc, NAME_LENGTH
	call InGameTrade_CopyData
;> InGameTrade_CopyData(InGameTrade_TrainerString, addr(wTradedEnemyMonOT), NAME_LENGTH)
	ld hl, InGameTrade_TrainerString
	ld de, wTradedEnemyMonOT
	call InGameTrade_CopyData
;> InGameTrade_CopyData(InGameTrade_TrainerString, addr(wLinkEnemyTrainerName), NAME_LENGTH)
	ld de, wLinkEnemyTrainerName
	call InGameTrade_CopyData
;> otid = AddNTimes(addr(wPartyMon1OTID), PARTYMON_STRUCT_LENGTH, wWhichPokemon)
	ld hl, wPartyMon1OTID
	ld bc, PARTYMON_STRUCT_LENGTH
	ld a, [wWhichPokemon]
	call AddNTimes
;> InGameTrade_CopyData(otid, addr(wTradedPlayerMonOTID), 2)
	ld de, wTradedPlayerMonOTID
	ld bc, $2
	call InGameTrade_CopyData
;> Random()
	call Random
;> CopyData(addr(hRandomAdd), addr(wTradedEnemyMonOTID), 2)
	ld hl, hRandomAdd
	ld de, wTradedEnemyMonOTID
	jp CopyData

;@ path: engine/events/in_game_trades
;@ def InGameTrade_CopyData(src: hl, dest: de, count: bc) -> de
;@ CopyData that keeps hl and bc; returns the address after the copy.
;@ test: src = rand_ram(16); dest = rand_ram(16); count = rand(1, 16)
InGameTrade_CopyData:
;> _, end = CopyData(src, dest, count)
;> return end
	push hl
	push bc
	call CopyData
	pop bc
	pop hl
	ret

;@ path: engine/events/in_game_trades
;@ def InGameTrade_CopyDataToReceivedMon()
;@ Give the received Pokémon (the last in the party) its nickname, the OT name "TRAINER" and the random OT ID.
;@ test: wPartyCount = rand(1, 6)
InGameTrade_CopyDataToReceivedMon:
;> dest, _ = InGameTrade_GetReceivedMonPointer(addr(wPartyMonNicks), NAME_LENGTH)
	ld hl, wPartyMonNicks
	ld bc, NAME_LENGTH
	call InGameTrade_GetReceivedMonPointer
;> CopyData(addr(wInGameTradeMonNick), dest, NAME_LENGTH)
	ld hl, wInGameTradeMonNick
	ld bc, NAME_LENGTH
	call CopyData
;> dest, _ = InGameTrade_GetReceivedMonPointer(addr(wPartyMonOT), NAME_LENGTH)
	ld hl, wPartyMonOT
	ld bc, NAME_LENGTH
	call InGameTrade_GetReceivedMonPointer
;> CopyData(InGameTrade_TrainerString, dest, NAME_LENGTH)
	ld hl, InGameTrade_TrainerString
	ld bc, NAME_LENGTH
	call CopyData
;> dest, _ = InGameTrade_GetReceivedMonPointer(wPartyMon1OTID, PARTYMON_STRUCT_LENGTH)
	ld hl, wPartyMon1OTID
	ld bc, PARTYMON_STRUCT_LENGTH
	call InGameTrade_GetReceivedMonPointer
;> CopyData(addr(wTradedEnemyMonOTID), dest, 2)
	ld hl, wTradedEnemyMonOTID
	ld bc, 2
	jp CopyData

; the received mon's index is (partyCount - 1),
; so this adds bc to hl (partyCount - 1) times and moves the result to de
;@ path: engine/events/in_game_trades
;@ def InGameTrade_GetReceivedMonPointer(base: hl, step: bc) -> (de, hl)
;@ The entry of the last party Pokémon in a table at `base` with entries of `step` bytes (in de and hl).
;@ test: base = rand_ram(1); step = rand(1, 44); wPartyCount = rand(1, 6)
InGameTrade_GetReceivedMonPointer:
;> p = AddNTimes(base, step, u8(wPartyCount - 1))
;> return p, p
	ld a, [wPartyCount]
	dec a
	call AddNTimes
	ld e, l
	ld d, h
	ret

