;@ path: engine/gfx/palettes
;@ def _RunPaletteCommand()
;@ Run SGB palette command b (from the predef registers; SET_PAL_DEFAULT means wDefaultPaletteCommand): its
;@ SetPal_* function picks a palette packet and an attribute packet, which then go to the SGB (or become the
;@ CGB palettes). SET_PAL_PARTY_MENU_HP_BARS only updates the party menu's attribute packet.
;@ test: skip jumps through a table of functions
_RunPaletteCommand:
;> _, _, bc = GetPredefRegisters()
	call GetPredefRegisters
;> command = bc >> 8
	ld a, b
;> if command == SET_PAL_DEFAULT:
	cp SET_PAL_DEFAULT
	jr nz, .not_default
;>     command = wDefaultPaletteCommand
	ld a, [wDefaultPaletteCommand]
.not_default
;> if command == SET_PAL_PARTY_MENU_HP_BARS:
;>     return UpdatePartyMenuBlkPacket()
	cp SET_PAL_PARTY_MENU_HP_BARS
	jp z, UpdatePartyMenuBlkPacket
;> p = SetPalFunctions + 2 * command
	ld l, a
	ld h, 0
	add hl, hl
	ld de, SetPalFunctions
	add hl, de
;> function = mem16[p]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>@call palettes, attributes = call(function)
;>@send SendSGBPackets(palettes, attributes)      # the function returns into it
;=@send
	ld de, SendSGBPackets
	push de
;=@call
	jp hl

;@ path: engine/gfx/palettes
;@ def SetPal_BattleBlack() -> (hl, de)
;@ Battle layout, all black.
SetPal_BattleBlack:
;> return PalPacket_Black, BlkPacket_Battle
	ld hl, PalPacket_Black
	ld de, BlkPacket_Battle
	ret

; uses PalPacket_Empty to build a packet based on mon IDs and health color
;@ path: engine/gfx/palettes
;@ def SetPal_Battle() -> (hl, de)
;@ Battle layout: the two HP bars in their colors and both Pokémon in their own palettes (a transformed one in
;@ Ditto's gray). Becomes the default command.
SetPal_Battle:
;> CopyData(PalPacket_Empty, addr(wPalPacket), 16)
	ld hl, PalPacket_Empty
	ld de, wPalPacket
	ld bc, $10
	call CopyData
;> player = DeterminePaletteID(wPlayerBattleStatus3, addr(wBattleMonSpecies))
	ld a, [wPlayerBattleStatus3]
	ld hl, wBattleMonSpecies
	call DeterminePaletteID
	ld b, a
;> enemy = DeterminePaletteID(wEnemyBattleStatus3, addr(wEnemyMonSpecies2))
	ld a, [wEnemyBattleStatus3]
	ld hl, wEnemyMonSpecies2
	call DeterminePaletteID
	ld c, a
;> mem[addr(wPalPacket) + 1] = u8(wPlayerHPBarColor + PAL_GREENBAR)
	ld hl, wPalPacket + 1
	ld a, [wPlayerHPBarColor]
	add PAL_GREENBAR
	ld [hli], a
;> mem[addr(wPalPacket) + 3] = u8(wEnemyHPBarColor + PAL_GREENBAR)
	inc hl
	ld a, [wEnemyHPBarColor]
	add PAL_GREENBAR
	ld [hli], a
;> mem[addr(wPalPacket) + 5] = player
	inc hl
	ld a, b
	ld [hli], a
;> mem[addr(wPalPacket) + 7] = enemy
	inc hl
	ld a, c
	ld [hl], a
;> wDefaultPaletteCommand = SET_PAL_BATTLE
;> return addr(wPalPacket), BlkPacket_Battle
	ld hl, wPalPacket
	ld de, BlkPacket_Battle
	ld a, SET_PAL_BATTLE
	ld [wDefaultPaletteCommand], a
	ret

;@ path: engine/gfx/palettes
