	ret

; uses PalPacket_Empty to build a packet based the mon ID
;@ path: engine/gfx/palettes
;@ def SetPal_StatusScreen() -> (hl, de)
;@ Status screen: the HP bar in its color and the Pokémon (wCurPartySpecies) in its palette.
SetPal_StatusScreen:
;> CopyData(PalPacket_Empty, addr(wPalPacket), 16)
	ld hl, PalPacket_Empty
	ld de, wPalPacket
	ld bc, $10
	call CopyData
;> species = wCurPartySpecies if wCurPartySpecies < NUM_POKEMON_INDEXES + 1 else 1
	ld a, [wCurPartySpecies]
	cp NUM_POKEMON_INDEXES + 1
	jr c, .pokemon
	ld a, $1 ; not pokemon
.pokemon
;> palette = DeterminePaletteIDOutOfBattle(species)
	call DeterminePaletteIDOutOfBattle
	push af
;> mem[addr(wPalPacket) + 1] = u8(wStatusScreenHPBarColor + PAL_GREENBAR)
	ld hl, wPalPacket + 1
	ld a, [wStatusScreenHPBarColor]
	add PAL_GREENBAR
	ld [hli], a
;> mem[addr(wPalPacket) + 3] = palette
	inc hl
	pop af
	ld [hl], a
;> return addr(wPalPacket), BlkPacket_StatusScreen
	ld hl, wPalPacket
	ld de, BlkPacket_StatusScreen
	ret

