; uses PalPacket_Empty to build a packet based on the current map
;@ path: engine/gfx/palettes
;@ def SetPal_Overworld() -> (hl, de)
;@ The overworld palette for the current map: each town has its own, routes share one, buildings and dungeons
;@ use the palette of the town or route they are in. Pokémon Tower and Agatha's room are gray, caves (Cerulean
;@ Cave, Bruno's room) cave-colored, and Lorelei's room uses Pallet Town's. Becomes the default command.
SetPal_Overworld:
;> CopyData(PalPacket_Empty, addr(wPalPacket), 16)
	ld hl, PalPacket_Empty
	ld de, wPalPacket
	ld bc, $10
	call CopyData
;>@area area = wCurMap
;> if wCurMapTileset == CEMETERY:
;>@gray     palette = PAL_GRAYMON
	ld a, [wCurMapTileset]
	cp CEMETERY
	jr z, .PokemonTowerOrAgatha
;> elif wCurMapTileset == CAVERN:
;>@cave     palette = PAL_CAVE
	cp CAVERN
	jr z, .caveOrBruno
;=@area
	ld a, [wCurMap]
;> elif area >= FIRST_INDOOR_MAP and CERULEAN_CAVE_2F <= area <= CERULEAN_CAVE_1F:
;>@cave2     palette = PAL_CAVE
	cp FIRST_INDOOR_MAP
	jr c, .townOrRoute
	cp CERULEAN_CAVE_2F
	jr c, .normalDungeonOrBuilding
	cp CERULEAN_CAVE_1F + 1
	jr c, .caveOrBruno
;> elif area == LORELEIS_ROOM:
;>@pallet     palette = PAL_PALLET
	cp LORELEIS_ROOM
	jr z, .Lorelei
;> elif area == BRUNOS_ROOM:
;>@cave3     palette = PAL_CAVE
	cp BRUNOS_ROOM
	jr z, .caveOrBruno
;> else:
;>     if area >= FIRST_INDOOR_MAP:
;>         area = wLastMap                           # the town or route outside
.normalDungeonOrBuilding
	ld a, [wLastMap] ; town or route that current dungeon or building is located
.townOrRoute
;>     palette = area + 1 if area < NUM_CITY_MAPS else PAL_ROUTE     # a town's palette is its map + 1
	cp NUM_CITY_MAPS
	jr c, .town
	ld a, PAL_ROUTE - 1
.town
	inc a ; a town's palette ID is its map ID + 1
;> mem[addr(wPalPacket) + 1] = palette
	ld hl, wPalPacket + 1
	ld [hld], a
;=@ret
	ld de, BlkPacket_WholeScreen
;> wDefaultPaletteCommand = SET_PAL_OVERWORLD
	ld a, SET_PAL_OVERWORLD
	ld [wDefaultPaletteCommand], a
;>@ret return addr(wPalPacket), BlkPacket_WholeScreen
	ret
.PokemonTowerOrAgatha
;=@gray
	ld a, PAL_GRAYMON - 1
	jr .town
.caveOrBruno
;=@cave
	ld a, PAL_CAVE - 1
	jr .town
.Lorelei
;=@pallet
	xor a
	jr .town

; used when a Pokemon is the only thing on the screen
; such as evolution, trading and the Hall of Fame
;@ path: engine/gfx/palettes
;@ def SetPal_PokemonWholeScreen(black: c) -> (hl, de)
;@ The whole screen in the palette of wWholeScreenPaletteMonSpecies (evolution, trades, Hall of Fame), or black.
SetPal_PokemonWholeScreen:
;> CopyData(PalPacket_Empty, addr(wPalPacket), 16)  # (black is kept)
	push bc
	ld hl, PalPacket_Empty
	ld de, wPalPacket
	ld bc, $10
	call CopyData
	pop bc
;> if black:
;>@black     palette = PAL_BLACK
	ld a, c
	and a
;=@black
	ld a, PAL_BLACK
	jr nz, .next
;> else:
;>     palette = DeterminePaletteIDOutOfBattle(wWholeScreenPaletteMonSpecies)
	ld a, [wWholeScreenPaletteMonSpecies]
	call DeterminePaletteIDOutOfBattle
.next
;> mem[addr(wPalPacket) + 1] = palette
	ld [wPalPacket + 1], a
;> return addr(wPalPacket), BlkPacket_WholeScreen
	ld hl, wPalPacket
	ld de, BlkPacket_WholeScreen
	ret

;@ path: engine/gfx/palettes
;@ def SetPal_TrainerCard() -> (hl, de)
;@ Trainer card: each badge in its own colors, with the attribute blocks of badges not yet won left out.
SetPal_TrainerCard:
;> CopyData(BlkPacket_TrainerCard, addr(wTrainerCardBlkPacket), 0x40)
	ld hl, BlkPacket_TrainerCard
	ld de, wTrainerCardBlkPacket
	ld bc, $40
	call CopyData
;> lengths = BadgeBlkDataLengths                 # the badges' block data lengths
	ld de, BadgeBlkDataLengths
;> at = addr(wTrainerCardBlkPacket) + 2
	ld hl, wTrainerCardBlkPacket + 2
;> badges = wObtainedBadges
	ld a, [wObtainedBadges]
;>@lp for _ in range(NUM_BADGES):
	ld c, NUM_BADGES
.badgeLoop
;>     have = badges & 1
;>     badges >>= 1
	srl a
;>     # (badges are kept)
	push af
;>     if not have:
	jr c, .haveBadge
; The player doesn't have the badge, so zero the badge's blk data.
;>         # (the badge counter is kept)
	push bc
;>@zero         for _ in range(mem[lengths]):          # zero this badge's blocks
	ld a, [de]
	ld c, a
	xor a
.zeroBadgeDataLoop
;>             mem[at] = 0
;>             at += 1
	ld [hli], a
;=@zero
	dec c
	jr nz, .zeroBadgeDataLoop
	pop bc
	jr .nextBadge
.haveBadge
; The player does have the badge, so skip past the badge's blk data.
;>     else:
;>@skip         for _ in range(mem[lengths]):          # skip this badge's blocks
	ld a, [de]
.skipBadgeDataLoop
;>             at += 1
	inc hl
;=@skip
	dec a
	jr nz, .skipBadgeDataLoop
.nextBadge
;>     # (the badges back)
	pop af
;>     lengths += 1
	inc de
;=@lp
	dec c
	jr nz, .badgeLoop
;> return PalPacket_TrainerCard, addr(wTrainerCardBlkPacket)
	ld hl, PalPacket_TrainerCard
	ld de, wTrainerCardBlkPacket
	ret

;@ path: engine/gfx/palettes
SetPalFunctions:
; entries correspond to SET_PAL_* constants
	dw SetPal_BattleBlack
	dw SetPal_Battle
	dw SetPal_TownMap
	dw SetPal_StatusScreen
	dw SetPal_Pokedex
	dw SetPal_Slots
	dw SetPal_TitleScreen
	dw SetPal_NidorinoIntro
	dw SetPal_Generic
	dw SetPal_Overworld
	dw SetPal_PartyMenu
	dw SetPal_PokemonWholeScreen
	dw SetPal_GameFreakIntro
	dw SetPal_TrainerCard

; The length of the blk data of each badge on the Trainer Card.
; The Rainbow Badge has 3 entries because of its many colors.
;@ path: engine/gfx/palettes
BadgeBlkDataLengths:
	db 6     ; Boulder Badge
	db 6     ; Cascade Badge
	db 6     ; Thunder Badge
	db 6 * 3 ; Rainbow Badge
	db 6     ; Soul Badge
	db 6     ; Marsh Badge
	db 6     ; Volcano Badge
	db 6     ; Earth Badge

;@ path: engine/gfx/palettes
;@ def DeterminePaletteID(battle_status3: a, species: hl) -> a
;@ The palette of the battling Pokémon whose species is at `species`: Ditto's gray once it has transformed.
DeterminePaletteID:
;> if battle_status3 >> TRANSFORMED & 1:
;>     return PAL_GRAYMON
	bit TRANSFORMED, a ; a is battle status 3
	ld a, PAL_GRAYMON  ; if the mon has used Transform, use Ditto's palette
	ret nz
;> return DeterminePaletteIDOutOfBattle(mem[species])      # it follows
	ld a, [hl]
;@ path: engine/gfx/palettes
;@ def DeterminePaletteIDOutOfBattle(species: a) -> a
;@ The palette of `species` from MonsterPalettes, by Pokédex number (trainer pictures have entries too).
DeterminePaletteIDOutOfBattle:
;> wPokedexNum = species
	ld [wPokedexNum], a
;> if species:                                   # 0 stays 0
	and a ; is the mon index 0?
	jr z, .skipDexNumConversion
;>     # (bc is kept)
	push bc
;>     Predef((IndexToPokedexPredef - PredefPointers) // 3)      # IndexToPokedex
	ld a, (IndexToPokedexPredef - PredefPointers) / 3
	call Predef
	pop bc
;>     species = wPokedexNum                     # now the Pokédex number
	ld a, [wPokedexNum]
.skipDexNumConversion
;> return mem[MonsterPalettes + species]
	ld e, a
	ld d, 0
	ld hl, MonsterPalettes ; not just for Pokemon, Trainers use it too
	add hl, de
	ld a, [hl]
	ret

;@ path: engine/gfx/palettes
;@ def InitPartyMenuBlkPacket()
;@ Start the party menu's attribute packet from its template.
InitPartyMenuBlkPacket:
;> CopyData(BlkPacket_PartyMenu, addr(wPartyMenuBlkPacket), 0x30)
	ld hl, BlkPacket_PartyMenu
	ld de, wPartyMenuBlkPacket
	ld bc, $30
	jp CopyData

;@ path: engine/gfx/palettes
;@ def UpdatePartyMenuBlkPacket()
;@ Set the color of HP bar wWhichPartyMenuHPBar in the party menu's attribute packet: green, yellow or red.
;@ test: wWhichPartyMenuHPBar = rand(0, 5)
UpdatePartyMenuBlkPacket:
; Update the blk packet with the palette of the HP bar that is
; specified in [wWhichPartyMenuHPBar].
;> p = addr(wPartyMenuHPBarColors) + wWhichPartyMenuHPBar
	ld hl, wPartyMenuHPBarColors
	ld a, [wWhichPartyMenuHPBar]
	ld e, a
	ld d, 0
	add hl, de
;> color = mem[p]
	ld e, l
	ld d, h
	ld a, [de]
;> if color == 0:
;>@green     attr = 1 << 2 | 1                         # green
	and a
;=@green
	ld e, (1 << 2) | 1 ; green
	jr z, .next
;> elif color == 1:
;>@yellow     attr = 2 << 2 | 2                         # yellow
	dec a
;=@yellow
	ld e, (2 << 2) | 2 ; yellow
	jr z, .next
;> else:
;>     attr = 3 << 2 | 3                         # red
	ld e, (3 << 2) | 3 ; red
.next
;> # (attr is kept)
	push de
;> p = addr(wPartyMenuBlkPacket) + 8 + 1 + 6 * wWhichPartyMenuHPBar
	ld hl, wPartyMenuBlkPacket + 8 + 1
	ld bc, 6
	ld a, [wWhichPartyMenuHPBar]
	call AddNTimes
	pop de
;> mem[p] = attr
	ld [hl], e
	ret

;@ path: engine/gfx/palettes
;@ def SendSGBPacket(packet: hl)
;@ Send an SGB command over the joypad lines: the low 3 bits of its first byte give the number of 16-byte
;@ packets. Each starts with a reset pulse, then the bits go out lowest first, ending with a 0 stop bit and a
;@ pause for the SGB.
;@ test: skip drives the joypad port with long waits
SendSGBPacket:
;check number of packets
;> count = mem[packet] & 7
	ld a, [hl]
	and $07
;> if count == 0:
;>     return
	ret z
; store number of packets in B
;> # (count goes to b)
	ld b, a
.loop2
;>@lp while True:
; save B for later use
;>     # (count is kept)
	push bc
; disable ReadJoypad to prevent it from interfering with sending the packet
;>     hDisableJoypadPolling = 1
	ld a, 1
	ldh [hDisableJoypadPolling], a
; send RESET signal (P14=LOW, P15=LOW)
;>     rJOYP = JOYP_SGB_START
	xor a ; JOYP_SGB_START
	ldh [rJOYP], a
; set P14=HIGH, P15=HIGH
;>     rJOYP = JOYP_SGB_FINISH
	ld a, JOYP_SGB_FINISH
	ldh [rJOYP], a
;load length of packets (16 bytes)
;>@bytes     for _ in range(16):
	ld b, 16
.nextByte
;set bit counter (8 bits per byte)
;=@bits
	ld e, 8
; get next byte in the packet
;>         byte = mem[packet]
;>         packet += 1
	ld a, [hli]
	ld d, a
;>@bits         for _ in range(8):
.nextBit0
;>             rJOYP = JOYP_SGB_ONE if byte & 1 else JOYP_SGB_ZERO
	bit 0, d
; if 0th bit is not zero set P14=HIGH, P15=LOW (send bit 1)
	ld a, JOYP_SGB_ONE
	jr nz, .next0
; else (if 0th bit is zero) set P14=LOW, P15=HIGH (send bit 0)
	ld a, JOYP_SGB_ZERO
.next0
	ldh [rJOYP], a
; must set P14=HIGH,P15=HIGH between each "pulse"
;>             rJOYP = JOYP_SGB_FINISH
	ld a, JOYP_SGB_FINISH
	ldh [rJOYP], a
; rotation will put next bit in 0th position (so  we can always use command
; "bit 0, d" to fetch the bit that has to be sent)
;>             byte >>= 1
	rr d
; decrease bit counter so we know when we have sent all 8 bits of current byte
;=@bits
	dec e
	jr nz, .nextBit0
;=@bytes
	dec b
	jr nz, .nextByte
; send bit 0 as a "stop bit" (end of parameter data)
;>     rJOYP = JOYP_SGB_ZERO                         # stop bit
	ld a, JOYP_SGB_ZERO
	ldh [rJOYP], a
; set P14=HIGH,P15=HIGH
;>     rJOYP = JOYP_SGB_FINISH
	ld a, JOYP_SGB_FINISH
	ldh [rJOYP], a
;>     hDisableJoypadPolling = 0
	xor a
	ldh [hDisableJoypadPolling], a
; wait for about 70000 cycles
;>     Wait7000()
	call Wait7000
; restore (previously pushed) number of packets
;>     # (count back)
	pop bc
;>     count -= 1
	dec b
; return if there are no more packets
;>     if count == 0:
;>         return
	ret z
; else send 16 more bytes
;=@lp
	jr .loop2

;@ path: engine/gfx/palettes
;@ def LoadSGB()
;@ At start-up, find out whether this is a Super Game Boy, and if so (and not a Game Boy Color) send it the
;@ border tiles, the border palettes and the game's palettes.
;@ test: skip talks to the SGB
LoadSGB:
;> wOnSGB = 0
	xor a
	ld [wOnSGB], a
;> if not CheckSGB():
;>     return
	call CheckSGB
	ret nc
;> wOnSGB = 1
	ld a, 1
	ld [wOnSGB], a
;> if wOnCGB:
;>     return
	ld a, [wOnCGB]
	and a
	jr z, .notCGB
	ret
.notCGB
;> PrepareSuperNintendoVRAMTransfer()
	di
	call PrepareSuperNintendoVRAMTransfer
	ei
;> wCopyingSGBTileData = 1
	ld a, 1
	ld [wCopyingSGBTileData], a
;> CopyGfxToSuperNintendoVRAM(SGBBorderGraphics, ChrTrnPacket)
	ld de, ChrTrnPacket
	ld hl, SGBBorderGraphics
	call CopyGfxToSuperNintendoVRAM
;> wCopyingSGBTileData = 0
	xor a
	ld [wCopyingSGBTileData], a
;> CopyGfxToSuperNintendoVRAM(BorderPalettes, PctTrnPacket)
	ld de, PctTrnPacket
	ld hl, BorderPalettes
	call CopyGfxToSuperNintendoVRAM
;> wCopyingSGBTileData = 0
	xor a
	ld [wCopyingSGBTileData], a
;> CopyGfxToSuperNintendoVRAM(SuperPalettes, PalTrnPacket)
	ld de, PalTrnPacket
	ld hl, SuperPalettes
	call CopyGfxToSuperNintendoVRAM
;> ClearVram()
	call ClearVram
;> return SendSGBPacket(MaskEnCancelPacket)
	ld hl, MaskEnCancelPacket
	jp SendSGBPacket

;@ path: engine/gfx/palettes
;@ def PrepareSuperNintendoVRAMTransfer()
;@ Freeze the SGB's screen for the transfers, then send eight DATA_SND packets (only the freeze is needed).
;@ test: skip talks to the SGB
PrepareSuperNintendoVRAMTransfer:
;>@lp for packet in (MaskEnFreezePacket, DataSndPacket1, DataSndPacket2, DataSndPacket3, DataSndPacket4, DataSndPacket5, DataSndPacket6, DataSndPacket7, DataSndPacket8):   # .packetPointers
	ld hl, .packetPointers
	ld c, 9
.loop
;>     # (the counter is kept)
	push bc
;>     SendSGBPacket(packet)
	ld a, [hli]
	push hl
	ld h, [hl]
	ld l, a
	call SendSGBPacket
	pop hl
;>     # on to the next pointer
	inc hl
	pop bc
;=@lp
	dec c
	jr nz, .loop
;> return
	ret

.packetPointers
; Only the first packet is needed.
	dw MaskEnFreezePacket
	dw DataSndPacket1
	dw DataSndPacket2
	dw DataSndPacket3
	dw DataSndPacket4
	dw DataSndPacket5
	dw DataSndPacket6
	dw DataSndPacket7
	dw DataSndPacket8

;@ path: engine/gfx/palettes
;@ def CheckSGB() -> carry
;@ Whether this is a Super Game Boy: ask it for two-player mode, then see whether the joypad port reports a
;@ second controller after stepping through the lines. Back to one player at the end.
;@ test: skip talks to the SGB
CheckSGB:
; Returns whether the game is running on an SGB in carry.
;> SendSGBPacket(MltReq2Packet)
	ld hl, MltReq2Packet
	di
	call SendSGBPacket
;> hDisableJoypadPolling = 1
	ld a, 1
	ldh [hDisableJoypadPolling], a
	ei
;> Wait7000()
	call Wait7000
;> if rJOYP & JOYP_SGB_MLT_REQ != JOYP_SGB_MLT_REQ:     # another controller already answers
;>@sgb     SendMltReq1Packet()
;>@yes     return True
	ldh a, [rJOYP]
	and JOYP_SGB_MLT_REQ
	cp JOYP_SGB_MLT_REQ
	jr nz, .isSGB
;> # step to the next controller
;> rJOYP = JOYP_SGB_ZERO
	ld a, JOYP_SGB_ZERO
	ldh [rJOYP], a
;> _ = rJOYP
	ldh a, [rJOYP]
;> _ = rJOYP
	ldh a, [rJOYP]
;> Wait7000()
	call Wait7000
;> Wait7000()
	call Wait7000
;> rJOYP = JOYP_SGB_FINISH
	ld a, JOYP_SGB_FINISH
	ldh [rJOYP], a
;> Wait7000()
	call Wait7000
;> Wait7000()
	call Wait7000
;> rJOYP = JOYP_SGB_ONE
	ld a, JOYP_SGB_ONE
	ldh [rJOYP], a
;> for _ in range(6):
;>     _ = rJOYP
	ldh a, [rJOYP]
	ldh a, [rJOYP]
	ldh a, [rJOYP]
	ldh a, [rJOYP]
	ldh a, [rJOYP]
	ldh a, [rJOYP]
;> Wait7000()
	call Wait7000
;> Wait7000()
	call Wait7000
;> rJOYP = JOYP_SGB_FINISH
	ld a, JOYP_SGB_FINISH
	ldh [rJOYP], a
;> for _ in range(3):
;>     _ = rJOYP
	ldh a, [rJOYP]
	ldh a, [rJOYP]
	ldh a, [rJOYP]
;> Wait7000()
	call Wait7000
;> Wait7000()
	call Wait7000
;> is_sgb = rJOYP & JOYP_SGB_MLT_REQ != JOYP_SGB_MLT_REQ
	ldh a, [rJOYP]
	and JOYP_SGB_MLT_REQ
	cp JOYP_SGB_MLT_REQ
	jr nz, .isSGB
;> SendMltReq1Packet()
	call SendMltReq1Packet
;> return is_sgb
	and a
	ret
.isSGB
;=@sgb
	call SendMltReq1Packet
;=@yes
	scf
	ret

;@ path: engine/gfx/palettes
;@ def SendMltReq1Packet()
;@ Back to one-player mode on the SGB.
;@ test: skip talks to the SGB
SendMltReq1Packet:
;> SendSGBPacket(MltReq1Packet)
;> Wait7000()
	ld hl, MltReq1Packet
	call SendSGBPacket
	jp Wait7000

;@ path: engine/gfx/palettes
;@ def CopyGfxToSuperNintendoVRAM(gfx: hl, packet: de)
;@ Send 256 tiles of data to the SGB: with the screen off, put them in VRAM (border tiles converted to 4 bits
;@ per pixel), show them all on the screen, and send the transfer command `packet`, which makes the SGB copy
;@ the screen.
;@ test: skip turns the LCD off
CopyGfxToSuperNintendoVRAM:
;> DisableLCD()                                  # (interrupts off, packet kept)
	di
	push de
	call DisableLCD
;> rBGP = 0xE4
	ld a, $e4
	ldh [rBGP], a
;> dest = vChars1
	ld de, vChars1
;> if wCopyingSGBTileData:
	ld a, [wCopyingSGBTileData]
	and a
	jr z, .notCopyingTileData
;>     CopySGBBorderTiles(gfx, dest)
	call CopySGBBorderTiles
	jr .next
;> else:
;>     CopyData(gfx, dest, 256 * TILE_SIZE)
.notCopyingTileData
	ld bc, 256 * TILE_SIZE
	call CopyData
.next
;> at = vBGMap0
	ld hl, vBGMap0
;> gap = TILEMAP_WIDTH - SCREEN_WIDTH
	ld de, TILEMAP_WIDTH - SCREEN_WIDTH
;> tile = 0x80
	ld a, $80
;>@rows for row in range((256 + SCREEN_WIDTH - 1) // SCREEN_WIDTH):     # enough rows for 256 tiles
	ld c, (256 + SCREEN_WIDTH - 1) / SCREEN_WIDTH ; enough rows to fit 256 tiles
.loop
;>@cols     for column in range(SCREEN_WIDTH):
	ld b, SCREEN_WIDTH
.innerLoop
;>         mem[at] = tile
;>         at += 1
	ld [hli], a
;>         tile = u8(tile + 1)
	inc a
;=@cols
	dec b
	jr nz, .innerLoop
;>     at += gap
	add hl, de
;=@rows
	dec c
	jr nz, .loop
;> rLCDC = LCDC_DEFAULT
	ld a, LCDC_DEFAULT
	ldh [rLCDC], a
;> SendSGBPacket(packet)
	pop hl
	call SendSGBPacket
;> rBGP = 0
	xor a
	ldh [rBGP], a
	ei
	ret

;@ path: engine/gfx/palettes
;@ def Wait7000()
;@ Wait about 63000 cycles (7000 loops), the pause the SGB needs between packets.
Wait7000:
; Each loop takes 9 cycles so this routine actually waits 63000 cycles.
;> count = 7000
	ld de, 7000
.loop
;> while True:
;>     # three nops: 9 cycles a round with the rest
	nop
	nop
	nop
;>     count -= 1
	dec de
;>     if count == 0:
;>         break
	ld a, d
	or e
	jr nz, .loop
;> return
	ret

;@ path: engine/gfx/palettes
;@ def SendSGBPackets(palettes: hl, attributes: de)
;@ Send a palette packet and an attribute packet to the SGB; on a Game Boy Color, turn the palette packet into
;@ CGB background palettes instead.
;@ test: skip talks to the SGB
SendSGBPackets:
;> if wOnCGB:
	ld a, [wOnCGB]
	and a
	jr z, .notCGB
;>     InitCGBPalettes(palettes)
	push de
	call InitCGBPalettes
;>     EmptyFunc3()
	pop hl
	call EmptyFunc3
;>     return
	ret
.notCGB
;> SendSGBPacket(palettes)
	push de
	call SendSGBPacket
;> SendSGBPacket(attributes)
	pop hl
	jp SendSGBPacket

;@ path: engine/gfx/palettes
;@ def InitCGBPalettes(packet: hl)
;@ Meant to fill the CGB background palettes from the palette IDs in an SGB palette packet (8 bytes of
;@ SuperPalettes per ID), but the offset is dropped: every byte comes from the start of SuperPalettes (or 256
;@ bytes on).
;@ test: skip writes the CGB palette port
InitCGBPalettes:
;> rBGPI = 0x80                                  # index 0, counting up
	ld a, $80 ; index 0 with auto-increment
	ldh [rBGPI], a
;> at = packet + 1
	inc hl
;>@lp for _ in range(0x20):
	ld c, $20
.loop
;>     pal = mem[at]
;>     at += 2
	ld a, [hli]
	inc hl
;>     offset = u8(8 * pal)
	add a
	add a
	add a
;>     p = SuperPalettes
	ld de, SuperPalettes
;>     if (SuperPalettes & 0xFF) + offset > 0xFF:  # only the carry is used: the offset never reaches e
	add e
	jr nc, .noCarry
;>         p += 0x100
	inc d
.noCarry
;>     rBGPD = mem[p]
	ld a, [de]
	ldh [rBGPD], a
;=@lp
	dec c
	jr nz, .loop
;> return
	ret

;@ path: engine/gfx/palettes
;@ def EmptyFunc3()
;@ Does nothing.
EmptyFunc3:
;> return
	ret

;@ path: engine/gfx/palettes
;@ def CopySGBBorderTiles(src: hl, dest: de)
;@ Convert 128 tiles from 2 to 4 bits per pixel for the SGB: copy each tile's two bit planes, then add two
;@ empty ones.
;@ test: src = rand(0x4000, 0x7000); dest = rand(0xC000, 0xCE00)
CopySGBBorderTiles:
; SGB tile data is stored in a 4BPP planar format.
; Each tile is 32 bytes. The first 16 bytes contain bit planes 1 and 2, while
; the second 16 bytes contain bit planes 3 and 4.
; This function converts 2BPP planar data into this format by mapping
; 2BPP colors 0-3 to 4BPP colors 0-3. 4BPP colors 4-15 are not used.
;>@tiles for _ in range(128):
	ld b, 128
.tileLoop
; Copy bit planes 1 and 2 of the tile data.
;>@copy     for _ in range(TILE_SIZE):                 # bit planes 1 and 2
	ld c, TILE_SIZE
.copyLoop
;>         mem[dest] = mem[src]
;>         src += 1
	ld a, [hli]
	ld [de], a
;>         dest += 1
	inc de
;=@copy
	dec c
	jr nz, .copyLoop

; Zero bit planes 3 and 4.
;>@zero     for _ in range(16):                        # bit planes 3 and 4 stay empty
	ld c, 16
	xor a
.zeroLoop
;>         mem[dest] = 0
	ld [de], a
;>         dest += 1
	inc de
;=@zero
	dec c
	jr nz, .zeroLoop

;=@tiles
	dec b
	jr nz, .tileLoop
	ret











;@ path: engine/gfx/palettes
BlkPacket_WholeScreen:
	db ($4 << 3) + ((1 * 6) / 16 + 1)
	db 1
	db %011
	db 0 + (0 << 2) + (0 << 4)
	db 00, 00, 19, 17
	ds 8, 0

; unused
	db $03, 00,00, 19,17, $00
	db $00

;@ path: engine/gfx/palettes
BlkPacket_Battle:
	db ($4 << 3) + ((5 * 6) / 16 + 1)
	db 5
	; message box: pal 2
	db %111
	db 2 + (2 << 2) + (0 << 4)
	db 00, 12, 19, 17
	; enemy HP bar: pal 1
	db %011
	db 1 + (1 << 2) + (0 << 4)
	db 01, 00, 10, 03
	; player HP bar: pal 0
	db %011
	db 0 + (0 << 2) + (0 << 4)
	db 10, 07, 19, 10
	; player mon: pal 2
	db %011
	db 2 + (2 << 2) + (0 << 4)
	db 00, 04, 08, 11
	; enemy mon : pal 3
	db %011
	db 3 + (3 << 2) + (0 << 4)
	db 11, 00, 19, 06

; unused
	db $03, 00,00, 19,11, $00
	db $03, 00,12, 19,17, $02
	db $03, 01,00, 10,03, $01
	db $03, 10,08, 19,10, $00
	db $03, 00,04, 08,11, $02
	db $03, 11,00, 19,07, $03
	db $00

