	; falling stars (right): pal 3
	db %011
	db 3 + (3 << 2) + (0 << 4)
	db 12, 11, 14, 13
	ds 12, 0

; unused
	db $03, 00,00, 19,10, $00
	db $03, 00,11, 04,13, $00
	db $03, 05,11, 07,13, $01
	db $03, 08,11, 19,13, $00
	db $03, 00,14, 19,17, $00
	db $03, 08,11, 09,13, $02
	db $03, 12,11, 14,13, $03
	db $00


