; These are DATA_SND packets containing SNES code.
; This set of packets is found in several Japanese SGB-compatible titles.
; It appears to be part of NCL's SGB devkit.

;@ path: engine/gfx/palettes
DataSndPacket1:
	db ($f << 3) + 1
	dw $85d
	db $0
	db 11
	db  $8C                 ; cpx #$8c (2)
	db  $D0, $F4            ; bne -$0c
	db  $60                 ; rts
	ds  7, 0

;@ path: engine/gfx/palettes
DataSndPacket2:
	db ($f << 3) + 1
	dw $852
	db $0
	db 11
	db  $A9, $E7            ; lda #$e7
	db  $9F, $01, $C0, $7E  ; sta $7ec001, x
	db  $E8                 ; inx
	db  $E8                 ; inx
	db  $E8                 ; inx
	db  $E8                 ; inx
	db  $E0                 ; cpx #$8c (1)

;@ path: engine/gfx/palettes
DataSndPacket3:
	db ($f << 3) + 1
	dw $847
	db $0
	db 11
	db  $C4                 ; cmp #$c4 (2)
	db  $D0, $16            ; bne +$16
	db  $A5                 ; lda dp
	db  $CB                 ; wai
	db  $C9, $05            ; cmp #$05
	db  $D0, $10            ; bne +$10
	db  $A2, $28            ; ldx #$28

;@ path: engine/gfx/palettes
DataSndPacket4:
	db ($f << 3) + 1
	dw $83c
	db $0
	db 11
	db  $F0, $12            ; beq +$12
	db  $A5                 ; lda dp
	db  $C9, $C9            ; cmp #$c9
	db  $C8                 ; iny
	db  $D0, $1C            ; bne +$1c
	db  $A5                 ; lda dp
	db  $CA                 ; dex
	db  $C9                 ; cmp #$c4 (1)

;@ path: engine/gfx/palettes
DataSndPacket5:
	db ($f << 3) + 1
	dw $831
	db $0
	db 11
	; tsb $caa5
	db $0C
	dw $CAA5
	db  $C9, $7E            ; cmp #$7e
	db  $D0, $06            ; bne +$06
	db  $A5                 ; lda dp
	db  $CB                 ; wai
	db  $C9, $7E            ; cmp #$7e

;@ path: engine/gfx/palettes
DataSndPacket6:
	db ($f << 3) + 1
	dw $826
	db $0
	db 11
	db  $39                 ; bne +$39 (2)
	; cmp $c48
	db $CD
	dw $C48
	db  $D0, $34            ; bne +$34
	db  $A5                 ; lda dp
	db  $C9, $C9            ; cmp #$c9
	db  $80, $D0            ; bra -$30

;@ path: engine/gfx/palettes
DataSndPacket7:
	db ($f << 3) + 1
	dw $81b
	db $0
	db 11
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $EA                 ; nop
	                        ; $820:
	db  $A9,$01             ; lda #01
	; cmp $c4f
	db $CD
	dw $C4F
	db  $D0                 ; bne +$39 (1)

;@ path: engine/gfx/palettes
DataSndPacket8:
	db ($f << 3) + 1
	dw $810
	db $0
	db 11
	; jmp $820
	db $4C
	dw $820
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $EA                 ; nop
	db  $60                 ; rts
	db  $EA                 ; nop
	db  $EA                 ; nop

