;@ def TryLoadSaveFile()
;@ Load the save file from SRAM at power-on. A bad checksum shows "the file data is destroyed"; wSaveFileStatus
;@ ends up 2 for a good file, 1 for a damaged one.
;@ path: engine/menus/save
TryLoadSaveFile:
;> ClearScreen()
	call ClearScreen
;> LoadFontTilePatterns()
	call LoadFontTilePatterns
;> LoadTextBoxTilePatterns()
	call LoadTextBoxTilePatterns
;> if not (LoadMainData() or LoadCurrentBoxData() or LoadPartyAndDexData()):
	call LoadMainData
	jr c, .badsum
	call LoadCurrentBoxData
	jr c, .badsum
	call LoadPartyAndDexData
	jr c, .badsum
;>     wSaveFileStatus = 2                        # the save file is good
	ld a, $2 ; good checksum
	jr .done
.badsum
;> else:
;>     wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY    # print the message at once
	ld hl, wStatusFlags5
	push hl
	set BIT_NO_TEXT_DELAY, [hl]
;>     PrintText(FileDataDestroyedText)
	ld hl, FileDataDestroyedText
	call PrintText
;>     DelayFrames(100)
	ld c, 100
	call DelayFrames
;>     wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY)
	pop hl
	res BIT_NO_TEXT_DELAY, [hl]
;>     wSaveFileStatus = 1                        # damaged
	ld a, $1 ; bad checksum
.done
	ld [wSaveFileStatus], a
	ret

;@ path: engine/menus/save
FileDataDestroyedText:
	db TX_FAR
	dw _FileDataDestroyedText
	db BANK(_FileDataDestroyedText)
	db TX_END

;@ def LoadMainData() -> carry
;@ Check the save file's checksum and copy the player's name, the main game data and the map sprites from SRAM
;@ back to WRAM. Carry if the checksum is wrong.
;@ path: engine/menus/save
LoadMainData:
;> open_sram(1)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ASSERT BANK("Save Data") == BMODE_ADVANCED
	ld [rRAMB], a
; This vc_hook does not have to be in any particular location.
; It is defined here because it refers to the same labels as the two lines below.
;> total = CalcCheckSum(sGameData, addr(sGameDataEnd) - sGameData)
	ld hl, sGameData
	ld bc, sGameDataEnd - sGameData
	call CalcCheckSum
;> if total != sMainDataCheckSum:
	ld c, a
	ld a, [sMainDataCheckSum]
	cp c
	jp z, .checkSumMatched

; If the computed checksum didn't match the saved on, try again.
;>     total = CalcCheckSum(sGameData, addr(sGameDataEnd) - sGameData)    # a second try decides
	ld hl, sGameData
	ld bc, sGameDataEnd - sGameData
	call CalcCheckSum
;>     if total != sMainDataCheckSum:
;>         return CheckSumFailed()
	ld c, a
	ld a, [sMainDataCheckSum]
	cp c
	jp nz, CheckSumFailed

.checkSumMatched
;> CopyData(sPlayerName, wPlayerName, NAME_LENGTH)
	ld hl, sPlayerName
	ld de, wPlayerName
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(sMainData, wMainDataStart, addr(wMainDataEnd) - wMainDataStart)
	ld hl, sMainData
	ld de, wMainDataStart
	ld bc, wMainDataEnd - wMainDataStart
	call CopyData
;> wCurMapTileset |= 1 << BIT_NO_PREVIOUS_MAP
	ld hl, wCurMapTileset
	set BIT_NO_PREVIOUS_MAP, [hl]
;> CopyData(sSpriteData, wSpriteDataStart, addr(wSpriteDataEnd) - wSpriteDataStart)
	ld hl, sSpriteData
	ld de, wSpriteDataStart
	ld bc, wSpriteDataEnd - wSpriteDataStart
	call CopyData
;> hTileAnimations = sTileAnimations
	ld a, [sTileAnimations]
	ldh [hTileAnimations], a

; this part is redundant, LoadCurrentBoxData is always called next
;> CopyData(sCurBoxData, addr(wBoxDataStart), addr(wBoxDataEnd) - addr(wBoxDataStart))     # LoadCurrentBoxData does it again
	ld hl, sCurBoxData
	ld de, wBoxDataStart
	ld bc, wBoxDataEnd - wBoxDataStart
	call CopyData

;> return GoodCheckSum(False)
	and a
	jp GoodCheckSum

;@ def LoadCurrentBoxData() -> carry
;@ Copy the current PC box from SRAM to WRAM if the save file's checksum is right (carry if not).
;@ path: engine/menus/save
LoadCurrentBoxData:
;> open_sram(1)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ASSERT BANK("Save Data") == BMODE_ADVANCED
	ld [rRAMB], a
;> total = CalcCheckSum(sGameData, addr(sGameDataEnd) - sGameData)
	ld hl, sGameData
	ld bc, sGameDataEnd - sGameData
	call CalcCheckSum
;> if total != sMainDataCheckSum:
;>     return CheckSumFailed()
	ld c, a
	ld a, [sMainDataCheckSum]
	cp c
	jr nz, CheckSumFailed
;> CopyData(sCurBoxData, addr(wBoxDataStart), addr(wBoxDataEnd) - addr(wBoxDataStart))
	ld hl, sCurBoxData
	ld de, wBoxDataStart
	ld bc, wBoxDataEnd - wBoxDataStart
	call CopyData
;> return GoodCheckSum(False)
	and a
	jp GoodCheckSum

;@ def LoadPartyAndDexData() -> carry
;@ Copy the party and the Pokédex flags from SRAM to WRAM if the save file's checksum is right (carry if not).
;@ path: engine/menus/save
LoadPartyAndDexData:
;> open_sram(1)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ASSERT BANK("Save Data") == BMODE_ADVANCED
	ld [rRAMB], a
;> total = CalcCheckSum(sGameData, addr(sGameDataEnd) - sGameData)
	ld hl, sGameData
	ld bc, sGameDataEnd - sGameData
	call CalcCheckSum
;> if total != sMainDataCheckSum:
;>     return CheckSumFailed()
	ld c, a
	ld a, [sMainDataCheckSum]
	cp c
	jp nz, CheckSumFailed
;> CopyData(sPartyData, addr(wPartyDataStart), addr(wPartyDataEnd) - addr(wPartyDataStart))
	ld hl, sPartyData
	ld de, wPartyDataStart
	ld bc, wPartyDataEnd - wPartyDataStart
	call CopyData
;> CopyData(sMainData, wPokedexOwned, addr(wPokedexSeenEnd) - wPokedexOwned)     # the Pokédex flags open the main data
	ld hl, sMainData
	ld de, wPokedexOwned
	ld bc, wPokedexSeenEnd - wPokedexOwned
	call CopyData
;> return GoodCheckSum(False)
	and a
	jp GoodCheckSum

;@ def CheckSumFailed() -> carry
;@ Close SRAM and report a failed checksum (carry set).
;@ path: engine/menus/save
CheckSumFailed:
;> return GoodCheckSum(True)
	scf
	; fallthrough

;@ def GoodCheckSum(failed: carry) -> carry
;@ Close SRAM again, keeping the result in carry.
;@ path: engine/menus/save
GoodCheckSum:
;> close_sram()
;> return failed
	ld a, BMODE_SIMPLE ; preserve flags
	ld [rBMODE], a
	ASSERT RAMG_SRAM_DISABLE == BMODE_SIMPLE
	ld [rRAMG], a
	ret

;@ def TryLoadSaveFileIgnoreChecksum() -> carry
;@ Load all three parts of the save file without the "destroyed" message or a new wSaveFileStatus. Unused.
;@ path: engine/menus/save
TryLoadSaveFileIgnoreChecksum: ; unreferenced
; don't update wSaveFileStatus upon success or failure
; don't display warning in case of failed checksum
;> LoadMainData()
	call LoadMainData
;> LoadCurrentBoxData()
	call LoadCurrentBoxData
;> return LoadPartyAndDexData()
	jp LoadPartyAndDexData

;@ def SaveMenu()
;@ The SAVE option of the start menu: show the player's progress, ask "Would you like to SAVE the game?", warn
;@ before overwriting another player's file, then save and play the save jingle.
;@ path: engine/menus/save
SaveMenu:
;> farcall(PrintSaveScreenText)
	ld b, BANK(PrintSaveScreenText)
	ld hl, PrintSaveScreenText
	call Bankswitch
;> if SaveTheGame_YesOrNo(WouldYouLikeToSaveText):     # 1: NO
;>     return
	ld hl, WouldYouLikeToSaveText
	call SaveTheGame_YesOrNo
	and a   ;|0 = Yes|1 = No|
	ret nz
;> if wSaveFileStatus != 1 and not CheckPreviousSaveFile():
	ld a, [wSaveFileStatus]
	dec a
	jr z, .save
	call CheckPreviousSaveFile
	jr z, .save
;>     if SaveTheGame_YesOrNo(OlderFileWillBeErasedText):
;>         return
	ld hl, OlderFileWillBeErasedText
	call SaveTheGame_YesOrNo
	and a
	ret nz
.save
;> SaveGameData()
	call SaveGameData
;> ClearScreenArea(coord(1, 13), 18, 4)
	ld hl, (13) * SCREEN_WIDTH + (1) + wTileMap
	ld bc, ((4) & $ff) << 8 + ((18) & $ff)
	call ClearScreenArea
;> PlaceString(NowSavingString, coord(1, 14))
	ld hl, (14) * SCREEN_WIDTH + (1) + wTileMap
	ld de, NowSavingString
	call PlaceString
;> DelayFrames(120)
	ld c, 120
	call DelayFrames
;> PrintText(GameSavedText)
	ld hl, GameSavedText
	call PrintText
;> PlaySoundWaitForCurrent(SFX_SAVE)
	ld a, SFX_SAVE
	call PlaySoundWaitForCurrent
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> DelayFrames(30)
	ld c, 30
	jp DelayFrames

;@ path: engine/menus/save
NowSavingString:
	db "Now saving...@"

;@ def SaveTheGame_YesOrNo(text: hl) -> a
;@ Print a question and let the player answer YES / NO: 0 for YES, 1 for NO.
;@ path: engine/menus/save
SaveTheGame_YesOrNo:
;> PrintText(text)
	call PrintText
;> wTextBoxID = TWO_OPTION_MENU
;> DisplayTextBoxID(coord(0, 7), 8, 1)
	ld hl, (7) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, ((8) & $ff) << 8 + ((1) & $ff)
	ld a, TWO_OPTION_MENU
	ld [wTextBoxID], a
	call DisplayTextBoxID
;> return wCurrentMenuItem
	ld a, [wCurrentMenuItem]
	ret

;@ path: engine/menus/save
WouldYouLikeToSaveText:
	db TX_FAR
	dw _WouldYouLikeToSaveText
	db BANK(_WouldYouLikeToSaveText)
	db TX_END

;@ path: engine/menus/save
GameSavedText:
	db TX_FAR
	dw _GameSavedText
	db BANK(_GameSavedText)
	db TX_END

;@ path: engine/menus/save
OlderFileWillBeErasedText:
	db TX_FAR
	dw _OlderFileWillBeErasedText
	db BANK(_OlderFileWillBeErasedText)
	db TX_END

;@ def SaveMainData()
;@ Copy the player's name, the main game data, the map sprites and the current box to SRAM and store the new
;@ checksum.
;@ writes: sMainDataCheckSum, sTileAnimations
;@ path: engine/menus/save
SaveMainData:
;> open_sram(1)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ASSERT BANK("Save Data") == BMODE_ADVANCED
	ld [rRAMB], a

;> CopyData(wPlayerName, sPlayerName, NAME_LENGTH)
	ld hl, wPlayerName
	ld de, sPlayerName
	ld bc, NAME_LENGTH
	call CopyData
;> CopyData(wMainDataStart, sMainData, addr(wMainDataEnd) - wMainDataStart)
	ld hl, wMainDataStart
	ld de, sMainData
	ld bc, wMainDataEnd - wMainDataStart
	call CopyData
;> CopyData(wSpriteDataStart, sSpriteData, addr(wSpriteDataEnd) - wSpriteDataStart)
	ld hl, wSpriteDataStart
	ld de, sSpriteData
	ld bc, wSpriteDataEnd - wSpriteDataStart
	call CopyData

; this part is redundant, SaveCurrentBoxData is always called next
;> CopyData(addr(wBoxDataStart), sCurBoxData, addr(wBoxDataEnd) - addr(wBoxDataStart))     # SaveCurrentBoxData does it again
	ld hl, wBoxDataStart
	ld de, sCurBoxData
	ld bc, wBoxDataEnd - wBoxDataStart
	call CopyData

;> sTileAnimations = hTileAnimations
	ldh a, [hTileAnimations]
	ld [sTileAnimations], a
;> sMainDataCheckSum = CalcCheckSum(sGameData, addr(sGameDataEnd) - sGameData)
	ld hl, sGameData
	ld bc, sGameDataEnd - sGameData
	call CalcCheckSum
	ld [sMainDataCheckSum], a
;> close_sram()
	xor a
	ld [rBMODE], a
	ld [rRAMG], a
	ret

