;@ def SaveGameData()
;@ Save the whole game: main data, current box, party and Pokédex. The file counts as good from now on.
;@ path: engine/menus/save
SaveGameData::
;> wSaveFileStatus = 2
	ld a, $2
	ld [wSaveFileStatus], a
;> SaveMainData()
	call SaveMainData
;> SaveCurrentBoxData()
	call SaveCurrentBoxData
;> SavePartyAndDexData()
	jp SavePartyAndDexData

;@ def CalcCheckSum(src: hl, count: bc) -> a
;@ The save file checksum: the sum of count bytes, complemented.
;@ test: count = rand(1, 600); src = rand(0xC000, 0xD800)
;@ path: engine/menus/save
CalcCheckSum:
;Check Sum (result[1 byte] is complemented)
;> total = 0
	ld d, 0
.loop
;>@lp while True:                              # (count 0 means 65536)
;>     total = (total + mem[src]) & 0xFF
;>     src += 1
	ld a, [hli]
	add d
	ld d, a
;>     count = (count - 1) & 0xFFFF
	dec bc
;>     if count == 0:
;>         break
	ld a, b
	or c
	jr nz, .loop
;> return total ^ 0xFF
	ld a, d
	cpl
	ret

;@ def CalcIndividualBoxCheckSums()
;@ Store a checksum for each of the six boxes in the SRAM bank switched in (boxes 1-6 or 7-12).
;@ path: engine/menus/save
CalcIndividualBoxCheckSums:
;> size = addr(wBoxDataEnd) - addr(wBoxDataStart)
;> box = sBox1                                 # (sBox7 in the other bank)
	ld hl, sBox1 ; sBox7
;> out = sBank2IndividualBoxChecksums          # (sBank3... in the other bank)
	ld de, sBank2IndividualBoxChecksums ; sBank3IndividualBoxChecksums
;>@lp for i in range(NUM_BOXES // 2):
	ld b, NUM_BOXES / 2
.loop
;>     sum = CalcCheckSum(box + i * size, size)
	push bc
	push de
	ld bc, wBoxDataEnd - wBoxDataStart
	call CalcCheckSum
;>     out[i] = sum
	pop de
	ld [de], a
	inc de
;=@lp
	pop bc
	dec b
	jr nz, .loop
;> return
	ret

;@ def GetBoxSRAMLocation() -> (b, hl)
;@ Where the current box (wCurrentBoxNum) lives in SRAM: boxes 1-6 in bank 2, boxes 7-12 in bank 3. Returns
;@ the bank and the address.
;@ path: engine/menus/save
GetBoxSRAMLocation:
; in: a = box num
; out: b = box SRAM bank, hl = pointer to start of box
;> table = BoxSRAMPointerTable
	ld hl, BoxSRAMPointerTable
;> box = wCurrentBoxNum & BOX_NUM_MASK
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
;> bank = 2
;> if box >= NUM_BOXES // 2:
	cp NUM_BOXES / 2
	ld b, 2
	jr c, .next
;>     bank = 3
	inc b
;>     box -= NUM_BOXES // 2
	sub NUM_BOXES / 2
.next
;> p = table + 2 * box
	ld e, a
	ld d, 0
	add hl, de
	add hl, de
;> return (bank, mem16[p])
	ld a, [hli]
	ld h, [hl]
	ld l, a
	ret

;@ path: engine/menus/save
BoxSRAMPointerTable:
	dw sBox1 ; sBox7
	dw sBox2 ; sBox8
	dw sBox3 ; sBox9
	dw sBox4 ; sBox10
	dw sBox5 ; sBox11
	dw sBox6 ; sBox12

;@ def ChangeBox()
;@ CHANGE BOX in Bill's PC: after a warning that the game will be saved, let the player pick a box, put the
;@ current box back into SRAM, bring the chosen one to WRAM and save. The first change also empties every SRAM box.
;@ path: engine/menus/save
ChangeBox::
;> PrintText(WhenYouChangeBoxText)
	ld hl, WhenYouChangeBoxText
	call PrintText
;> YesNoChoice()
	call YesNoChoice
;> if wCurrentMenuItem:                              # NO
;>     return
	ld a, [wCurrentMenuItem]
	and a
	ret nz ; return if No was chosen
;> if not wCurrentBoxNum >> BIT_HAS_CHANGED_BOXES & 1:
;>     EmptyAllSRAMBoxes()                           # the SRAM boxes have never been set up
	ld hl, wCurrentBoxNum
	bit BIT_HAS_CHANGED_BOXES, [hl] ; is it the first time player is changing the box?
	call z, EmptyAllSRAMBoxes ; if so, empty all boxes in SRAM
;> DisplayChangeBoxMenu()
	call DisplayChangeBoxMenu
;> UpdateSprites()
	call UpdateSprites
;> hUILayoutFlags |= 1 << BIT_DOUBLE_SPACED_MENU
	ld hl, hUILayoutFlags
	set BIT_DOUBLE_SPACED_MENU, [hl]
;> keys = HandleMenuInput()
	call HandleMenuInput
;> hUILayoutFlags &= ~(1 << BIT_DOUBLE_SPACED_MENU)
	ld hl, hUILayoutFlags
	res BIT_DOUBLE_SPACED_MENU, [hl]
;> if keys >> B_PAD_B & 1:
;>     return
	bit B_PAD_B, a
	ret nz
;> bank, old = GetBoxSRAMLocation()
	call GetBoxSRAMLocation
;> CopyBoxToOrFromSRAM(addr(wBoxDataStart), old, bank)    # the current box goes back to SRAM
	ld e, l
	ld d, h
	ld hl, wBoxDataStart
	call CopyBoxToOrFromSRAM ; copy old box from WRAM to SRAM
;> wCurrentBoxNum = wCurrentMenuItem | 1 << BIT_HAS_CHANGED_BOXES
	ld a, [wCurrentMenuItem]
	set BIT_HAS_CHANGED_BOXES, a
	ld [wCurrentBoxNum], a
;> bank, new = GetBoxSRAMLocation()
	call GetBoxSRAMLocation
;> CopyBoxToOrFromSRAM(new, addr(wBoxDataStart), bank)    # the chosen box comes to WRAM
	ld de, wBoxDataStart
	call CopyBoxToOrFromSRAM ; copy new box from SRAM to WRAM
;> src = addr(wCurMapTextPtr)
;> dest = addr(wChangeBoxSavedMapTextPointer)
	ld hl, wCurMapTextPtr
	ld de, wChangeBoxSavedMapTextPointer
;> mem[dest] = mem[src]
	ld a, [hli]
	ld [de], a
;> mem[dest + 1] = mem[src + 1]
	inc de
	ld a, [hl]
	ld [de], a
;> RestoreMapTextPointer()
	call RestoreMapTextPointer
;> SaveGameData()
	call SaveGameData
;> SetMapTextPointer(wChangeBoxSavedMapTextPointer)
	ld hl, wChangeBoxSavedMapTextPointer
	call SetMapTextPointer
;> PlaySoundWaitForCurrent(SFX_SAVE)
	ld a, SFX_SAVE
	call PlaySoundWaitForCurrent
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> return
	ret

;@ path: engine/menus/save
WhenYouChangeBoxText:
	db TX_FAR
	dw _WhenYouChangeBoxText
	db BANK(_WhenYouChangeBoxText)
	db TX_END

;@ def CopyBoxToOrFromSRAM(src: hl, dest: de, bank: b)
;@ Copy a whole box from src to dest with SRAM bank `bank` switched in, mark the source box as empty and
;@ update that bank's box checksums.
;@ test: bank = rand(0, 3); src = rand(0xC000, 0xCA00); dest = rand(0xA000, 0xB900)
;@ path: engine/menus/save
CopyBoxToOrFromSRAM:
; copy an entire box from hl to de with b as the SRAM bank
;> # (src is kept)
	push hl
;> open_sram(bank)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ld a, b
	ld [rRAMB], a
;> CopyData(src, dest, addr(wBoxDataEnd) - addr(wBoxDataStart))
	ld bc, wBoxDataEnd - wBoxDataStart
	call CopyData
	pop hl

; mark the source box as an empty box
;> mem[src] = 0                                     # the box left behind is empty
;> mem[src + 1] = 0xFF
	xor a
	ld [hli], a
	dec a
	ld [hl], a

;> sBank2AllBoxesChecksum = CalcCheckSum(sBox1, addr(sBank2AllBoxesChecksum) - sBox1)
	ld hl, sBox1 ; sBox7
	ld bc, sBank2AllBoxesChecksum - sBox1
	call CalcCheckSum
	ld [sBank2AllBoxesChecksum], a ; sBank3AllBoxesChecksum
;> CalcIndividualBoxCheckSums()
	call CalcIndividualBoxCheckSums
;> close_sram()
	xor a
	ld [rBMODE], a
	ld [rRAMG], a
	ret

;@ def DisplayChangeBoxMenu()
;@ Draw the box menu: "Choose a box", the twelve box names with a Poké Ball next to every box that holds
;@ Pokémon, and the current box number.
;@ path: engine/menus/save
DisplayChangeBoxMenu:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 11
	ld a, 11
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 1
	ld a, 1
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 12
	ld a, 12
	ld [wTopMenuItemX], a
;> wMenuWatchMovingOutOfBounds = 0
	xor a
	ld [wMenuWatchMovingOutOfBounds], a
;> wCurrentMenuItem = wCurrentBoxNum & BOX_NUM_MASK
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
	ld [wCurrentMenuItem], a
;> wLastMenuItem = wCurrentMenuItem
	ld [wLastMenuItem], a
;> TextBoxBorder(coord(0, 0), 2, 9)
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 2
	ld c, 9
	call TextBoxBorder
;> PrintText(ChooseABoxText)
	ld hl, ChooseABoxText
	call PrintText
;> TextBoxBorder(coord(11, 0), 12, 7)
	ld hl, (0) * SCREEN_WIDTH + (11) + wTileMap
	ld b, 12
	ld c, 7
	call TextBoxBorder
;> hUILayoutFlags |= 1 << BIT_SINGLE_SPACED_LINES
	ld hl, hUILayoutFlags
	set BIT_SINGLE_SPACED_LINES, [hl]
;> PlaceString(BoxNames, coord(13, 1))
	ld de, BoxNames
	ld hl, (1) * SCREEN_WIDTH + (13) + wTileMap
	call PlaceString
;> hUILayoutFlags &= ~(1 << BIT_SINGLE_SPACED_LINES)
	ld hl, hUILayoutFlags
	res BIT_SINGLE_SPACED_LINES, [hl]
;> box = wCurrentBoxNum & BOX_NUM_MASK
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
;> if box >= 9:                                # boxes 10-12: a "1" in front
	cp 9
	jr c, .singleDigitBoxNum
;>     digit = box - 9
	sub 9
;>     mem[coord(8, 2)] = 0xF7                 # "1"
	ld hl, (2) * SCREEN_WIDTH + (8) + wTileMap
	ld [hl], '1'
;>     digit += 0xF6                           # its tile ("0" is $F6)
	add '0'
	jr .next
;> else:
;>     digit = box + 0xF7                      # box 0 is "1"
.singleDigitBoxNum
	add '1'
.next
;> mem[coord(9, 2)] = digit
	ld [(2) * SCREEN_WIDTH + (9) + wTileMap], a
;> PlaceString(BoxNoText, coord(1, 2))
	ld hl, (2) * SCREEN_WIDTH + (1) + wTileMap
	ld de, BoxNoText
	call PlaceString
;> GetMonCountsForAllBoxes()
	call GetMonCountsForAllBoxes
;>@bx for i in range(NUM_BOXES):
	ld hl, (1) * SCREEN_WIDTH + (18) + wTileMap
	ld de, wBoxMonCounts
	ld bc, SCREEN_WIDTH
	ld a, NUM_BOXES
.loop
;>     if wBoxMonCounts[i]:
	push af
	ld a, [de]
	and a ; is the box empty?
	jr z, .skipPlacingPokeball
;>         mem[coord(18, 1) + i * SCREEN_WIDTH] = 0x78     # a Poké Ball next to the name
	ld [hl], $78 ; place pokeball tile next to box name if box not empty
.skipPlacingPokeball
;=@bx
	add hl, bc
	inc de
	pop af
	dec a
	jr nz, .loop
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
	ret

