	db "<NEXT>", "BOX 6"
	db "<NEXT>", "BOX 7"
	db "<NEXT>", "BOX 8"
	db "<NEXT>", "BOX 9"
	db "<NEXT>", "BOX10"
	db "<NEXT>", "BOX11"
	db "<NEXT>", "BOX12@"

;@ path: engine/menus/save
BoxNoText:
	db "BOX No.@"

;@ def EmptyAllSRAMBoxes()
;@ Mark all twelve SRAM boxes as empty: done the first time the player changes boxes.
;@ path: engine/menus/save
EmptyAllSRAMBoxes:
; marks all boxes in SRAM as empty (initialisation for the first time the
; player changes the box)
;> open_sram(2)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ld a, BANK("Saved Boxes 1")
	ld [rRAMB], a
;> EmptySRAMBoxesInBank()
	call EmptySRAMBoxesInBank
;> rRAMB = 3
	ld a, BANK("Saved Boxes 2")
	ld [rRAMB], a
;> EmptySRAMBoxesInBank()
	call EmptySRAMBoxesInBank
;> close_sram()
	xor a
	ld [rBMODE], a
	ld [rRAMG], a
	ret

;@ def EmptySRAMBoxesInBank()
;@ Mark the six boxes of the SRAM bank switched in as empty and update its checksums.
;@ writes: sBank2AllBoxesChecksum
;@ path: engine/menus/save
EmptySRAMBoxesInBank:
; marks every box in the current SRAM bank as empty
;> EmptySRAMBox(sBox1)                         # (sBox7-12 in the other bank)
	ld hl, sBox1 ; sBox7
	call EmptySRAMBox
;> EmptySRAMBox(sBox2)
	ld hl, sBox2 ; sBox8
	call EmptySRAMBox
;> EmptySRAMBox(sBox3)
	ld hl, sBox3 ; sBox9
	call EmptySRAMBox
;> EmptySRAMBox(sBox4)
	ld hl, sBox4 ; sBox10
	call EmptySRAMBox
;> EmptySRAMBox(sBox5)
	ld hl, sBox5 ; sBox11
	call EmptySRAMBox
;> EmptySRAMBox(sBox6)
	ld hl, sBox6 ; sBox12
	call EmptySRAMBox
;> sBank2AllBoxesChecksum = CalcCheckSum(sBox1, addr(sBank2AllBoxesChecksum) - sBox1)
	ld hl, sBox1 ; sBox7
	ld bc, sBank2AllBoxesChecksum - sBox1
	call CalcCheckSum
	ld [sBank2AllBoxesChecksum], a ; sBank3AllBoxesChecksum
;> CalcIndividualBoxCheckSums()
	call CalcIndividualBoxCheckSums
	ret

;@ def EmptySRAMBox(box: hl) -> hl
;@ An empty box: count 0, then the end-of-list byte.
;@ test: box = rand_ram(2)
;@ path: engine/menus/save
EmptySRAMBox:
;> mem[box] = 0
	xor a
	ld [hli], a
;> mem[box + 1] = 0xFF
	dec a
	ld [hl], a
;> return box + 1
	ret

;@ def GetMonCountsForAllBoxes()
;@ Fill wBoxMonCounts with the number of Pokémon in each of the twelve boxes; the current box's count comes
;@ from WRAM.
;@ path: engine/menus/save
GetMonCountsForAllBoxes:
;> counts = addr(wBoxMonCounts)
	ld hl, wBoxMonCounts
	push hl
;> open_sram(2)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ld a, BANK("Saved Boxes 1")
	ld [rRAMB], a
;> rest = GetMonCountsForBoxesInBank(wBoxMonCounts)
	call GetMonCountsForBoxesInBank
;> rRAMB = 3
	ld a, BANK("Saved Boxes 2")
	ld [rRAMB], a
;> GetMonCountsForBoxesInBank(rest)
	call GetMonCountsForBoxesInBank
;> close_sram()
	xor a
	ld [rBMODE], a
	ld [rRAMG], a
	pop hl

; copy the count for the current box from WRAM
;> box = wCurrentBoxNum & BOX_NUM_MASK
	ld a, [wCurrentBoxNum]
	and BOX_NUM_MASK
;> p = counts + box
	ld c, a
	ld b, 0
	add hl, bc
;> mem[p] = wBoxCount
	ld a, [wBoxCount]
	ld [hl], a

;> return
	ret

;@ def GetMonCountsForBoxesInBank(dest: hl) -> hl
;@ Copy the counts of the six boxes in the SRAM bank switched in to dest (each box starts with its count).
;@ test: dest = rand_ram(6)
;@ path: engine/menus/save
GetMonCountsForBoxesInBank:
;> mem[dest] = mem[sBox1]                      # (sBox7-12 in the other bank)
	ld a, [sBox1] ; sBox7
	ld [hli], a
;> mem[dest + 1] = mem[sBox2]
	ld a, [sBox2] ; sBox8
	ld [hli], a
;> mem[dest + 2] = mem[sBox3]
	ld a, [sBox3] ; sBox9
	ld [hli], a
;> mem[dest + 3] = mem[sBox4]
	ld a, [sBox4] ; sBox10
	ld [hli], a
;> mem[dest + 4] = mem[sBox5]
	ld a, [sBox5] ; sBox11
	ld [hli], a
;> mem[dest + 5] = mem[sBox6]
	ld a, [sBox6] ; sBox12
	ld [hli], a
;> return dest + 6
	ret

; check if we're trying to save over a different playthrough
; return result in zero flag
; z set: a valid save file was found, and saved PlayerID is different from wPlayerID
;@ def CheckPreviousSaveFile() -> zero
;@ Before saving: zero if SRAM holds no save file or this player's own (same player ID); not zero if it holds
;@ another game or a damaged one, which saving would overwrite.
;@ path: engine/menus/save
CheckPreviousSaveFile:
;> open_sram(1)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	ASSERT BANK("Save Data") == BMODE_ADVANCED
	ld [rRAMB], a
;> same = True                                       # no save file at all
;> if sPlayerName[0] != 0:
	ld a, [sPlayerName]
	and a
	jr z, .next
;>     total = CalcCheckSum(sGameData, addr(sGameDataEnd) - sGameData)
	ld hl, sGameData
	ld bc, sGameDataEnd - sGameData
	call CalcCheckSum
;>     if total != sMainDataCheckSum:
;>         same = False                              # damaged
;>     else:
	ld c, a
	ld a, [sMainDataCheckSum]
	cp c
	jr nz, .next ; return z set if save data is corrupted
;>         saved = mem16[sMainData + (wPlayerID - wMainDataStart)]   # the saved player ID
	ld hl, sMainData + (wPlayerID - wMainDataStart) ; player ID
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>         same = wPlayerID[0] == saved & 0xFF
	ld a, [wPlayerID]
	cp l
	jr nz, .next
;>         if same:
;>             same = wPlayerID[1] == saved >> 8
	ld a, [wPlayerID + 1]
	cp h
.next
;> close_sram()
;> return same
	ld a, BMODE_SIMPLE
	ld [rBMODE], a
	ASSERT RAMG_SRAM_DISABLE == BMODE_SIMPLE
	ld [rRAMG], a
	ret

;@ def SaveHallOfFameTeams()
;@ Add the new champions (wHallOfFame) to the Hall of Fame in SRAM. When all HOF_TEAM_CAPACITY slots are full,
;@ every team moves up one slot and the oldest is lost.
;@ path: engine/menus/save
SaveHallOfFameTeams:
;> n = (wNumHoFTeams - 1) & 0xFF
;> if n < HOF_TEAM_CAPACITY:
	ld a, [wNumHoFTeams]
	dec a
	cp HOF_TEAM_CAPACITY
	jr nc, .shiftHOFTeams
;>     dest = sHallOfFame + n * HOF_TEAM
	ld hl, sHallOfFame
	ld bc, HOF_TEAM
	call AddNTimes
;>     return HallOfFame_Copy(wHallOfFame, dest, HOF_TEAM)
	ld e, l
	ld d, h
	ld hl, wHallOfFame
	ld bc, HOF_TEAM
	jr HallOfFame_Copy

.shiftHOFTeams
; if the space designated for HOF teams is full, then shift all HOF teams to the next slot, making space for the new HOF team
; this deletes the last HOF team though
;> HallOfFame_Copy(sHallOfFame + HOF_TEAM, sHallOfFame, HOF_TEAM * (HOF_TEAM_CAPACITY - 1))
	ld hl, sHallOfFame + HOF_TEAM
	ld de, sHallOfFame
	ld bc, HOF_TEAM * (HOF_TEAM_CAPACITY - 1)
	call HallOfFame_Copy
;> HallOfFame_Copy(wHallOfFame, sHallOfFame + HOF_TEAM * (HOF_TEAM_CAPACITY - 1), HOF_TEAM)
	ld hl, wHallOfFame
	ld de, sHallOfFame + HOF_TEAM * (HOF_TEAM_CAPACITY - 1)
	ld bc, HOF_TEAM
	jr HallOfFame_Copy

;@ def LoadHallOfFameTeams()
;@ Copy Hall of Fame team number wHoFTeamIndex from SRAM to wHallOfFame.
;@ test: wHoFTeamIndex = rand(0, 49)
;@ path: engine/menus/save
LoadHallOfFameTeams:
;> HallOfFame_Copy(sHallOfFame + wHoFTeamIndex * HOF_TEAM, wHallOfFame, HOF_TEAM)
	ld hl, sHallOfFame
	ld bc, HOF_TEAM
	ld a, [wHoFTeamIndex]
	call AddNTimes
	ld de, wHallOfFame
	ld bc, HOF_TEAM
	; fallthrough

;@ def HallOfFame_Copy(src: hl, dest: de, count: bc)
;@ Copy count bytes with SRAM bank 0 (the Hall of Fame) switched in.
;@ test: count = rand(1, 200); src = rand(0xA000, 0xBF00); dest = rand_ram(200)
;@ path: engine/menus/save
HallOfFame_Copy:
;> open_sram(0)
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
	xor a
	ld [rRAMB], a
;> CopyData(src, dest, count)
	call CopyData
;> close_sram()
	xor a
	ld [rBMODE], a
	ld [rRAMG], a
	ret

; Fill SRAM with $ff, erasing save data. Used by DoClearSaveDialogue
;@ def ClearAllSRAMBanks()
;@ Erase the save file: fill all four SRAM banks with $FF.
;@ path: engine/menus/save
ClearAllSRAMBanks:
;> rRAMG = RAMG_SRAM_ENABLE
;> rBMODE = BMODE_ADVANCED
	ld a, RAMG_SRAM_ENABLE
	ld [rRAMG], a
	ld a, BMODE_ADVANCED
	ld [rBMODE], a
;> for bank in range(4):                       # each bank filled with $FF (.PadSRAM_FF below)
;>@b0     rRAMB = bank
	xor a
;>@f0     FillMemory(0xA000, 0x2000, 0xFF)
	call .PadSRAM_FF
;=@b0
	ld a, 1
;=@f0
	call .PadSRAM_FF
;=@b0
	ld a, 2
;=@f0
	call .PadSRAM_FF
;=@b0
	ld a, 3
;=@f0
	call .PadSRAM_FF
;> close_sram()
	xor a
	ld [rBMODE], a
	ld [rRAMG], a
;> return
	ret

.PadSRAM_FF
;> # pad_sram(bank): rRAMB = bank
	ld [rRAMB], a
;> #     FillMemory(STARTOF(SRAM), SIZEOF(SRAM), 0xFF)      # the whole bank
	ld hl, STARTOF(SRAM)
	ld bc, SIZEOF(SRAM)
	ld a, $ff
	jp FillMemory


SECTION "Itemfinder 1", ROMX

;@ path: engine/movie/credits
;@ def HallOfFamePC()
;@ The ending: the Hall of Fame scene, then the credits between black bars to the credits music, the text fading
;@ in through its palette.
;@ test: skip runs the ending
HallOfFamePC:
;> AnimateHallOfFame()
	ld b, BANK(AnimateHallOfFame)
	ld hl, AnimateHallOfFame
	call Bankswitch
;> ClearScreen()
	call ClearScreen
;> DelayFrames(100)
	ld c, 100
	call DelayFrames
;> DisableLCD()
	call DisableLCD
;> ShiftFontColorIndex(vFont, 0x80 * TILE_SIZE // 2)
	ld hl, vFont
	ld bc, ($80 * TILE_SIZE) / 2
	call ShiftFontColorIndex
;> ShiftFontColorIndex(vChars2 + 0x60 * TILE_SIZE, 0x20 * TILE_SIZE // 2)
	ld hl, vChars2 + TILE_SIZE * $60
	ld bc, ($20 * TILE_SIZE) / 2
	call ShiftFontColorIndex
;> FillMemory(vChars2 + 0x7E * TILE_SIZE, TILE_SIZE, 0xFF)     # a solid black tile
	ld hl, vChars2 + TILE_SIZE * $7e
	ld bc, TILE_SIZE
	ld a, $ff ; solid black
	call FillMemory
;> FillFourRowsWithBlack(coord(0, 0))
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	call FillFourRowsWithBlack
;> FillFourRowsWithBlack(coord(0, 14))
	ld hl, (14) * SCREEN_WIDTH + (0) + wTileMap
	call FillFourRowsWithBlack
;> rBGP = 0b11000000
	ld a, %11000000
	ldh [rBGP], a
;> EnableLCD()
	call EnableLCD
;> PlaySoundWaitForCurrent(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySoundWaitForCurrent
;> PlayMusic(MUSIC_CREDITS, BANK(Music_Credits))
	ld c, BANK(Music_Credits)
	ld a, MUSIC_CREDITS
	call PlayMusic
;> DelayFrames(128)
	ld c, 128
	call DelayFrames
;> wUnusedCreditsByte = 0
	xor a
	ld [wUnusedCreditsByte], a ; not read
;> wNumCreditsMonsDisplayed = 0
	ld [wNumCreditsMonsDisplayed], a
;> Credits()
	jp Credits

;@ path: engine/movie/credits
;@ def FadeInCredits()
;@ Fade the credits text in through four palettes, 5 frames each.
;@ test: skip waits for frames
FadeInCredits:
;> for i in range(4):
	ld hl, HoFGBPalettes
	ld b, 4
.loop
;>     rBGP = mem[HoFGBPalettes + i]
	ld a, [hli]
	ldh [rBGP], a
;>     DelayFrames(5)
	ld c, 5
	call DelayFrames
	dec b
	jr nz, .loop
	ret

;@ path: engine/movie/credits
;@ def DisplayCreditsMon()
;@ Between credits pages: the next Pokémon of CreditsMons runs across the screen as a black silhouette, the
;@ window hiding the text that wraps around.
;@ test: skip waits for frames
DisplayCreditsMon:
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> FillMiddleOfScreenWithWhite()
	call FillMiddleOfScreenWithWhite

	; display the next monster from CreditsMons
;> index = wNumCreditsMonsDisplayed
	ld hl, wNumCreditsMonsDisplayed
	ld c, [hl] ; how many monsters have we displayed so far?
;> wNumCreditsMonsDisplayed += 1
	inc [hl]
;> species = mem[CreditsMons + index]
	ld b, 0
	ld hl, CreditsMons
	add hl, bc ; go that far in the list of monsters and get the next one
	ld a, [hl]
;> wCurPartySpecies = species
;> wCurSpecies = species
	ld [wCurPartySpecies], a
	ld [wCurSpecies], a
;> GetMonHeader()
;> LoadFrontSpriteByMonIndex(coord(8, 6))
	ld hl, (6) * SCREEN_WIDTH + (8) + wTileMap
	call GetMonHeader
	call LoadFrontSpriteByMonIndex
;> CreditsCopyTileMapToVRAM(vBGMap0 + 0xC)
	ld hl, vBGMap0 + $c
	call CreditsCopyTileMapToVRAM
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> CreditsCopyTileMapToVRAM(vBGMap0)
	ld hl, vBGMap0
	call CreditsCopyTileMapToVRAM
;> rWX = 0xA7
	ld a, $A7
	ldh [rWX], a
;> CreditsCopyTileMapToVRAM(vBGMap1)
	ld hl, vBGMap1
	call CreditsCopyTileMapToVRAM
;> FillMiddleOfScreenWithWhite()
	call FillMiddleOfScreenWithWhite
;> rBGP = 0b11111100                                 # a black silhouette
	ld a, %11111100 ; make the mon a black silhouette
	ldh [rBGP], a

; scroll the mon left by one tile 7 times
;> scx = 0
;> for _ in range(7):                                # left a tile at a time
	ld bc, 7
.scrollLoop1
;>     scx = ScrollCreditsMonLeft(scx)
	call ScrollCreditsMonLeft
	dec c
	jr nz, .scrollLoop1

; scroll the mon left by one tile 20 times
; This time, we have to move the window left too in order to hide the text that
; is wrapping around to the right side of the screen.
;> for _ in range(20):                               # and the window with it
	ld c, 20
.scrollLoop2
;>     scx = ScrollCreditsMonLeft(scx)
	call ScrollCreditsMonLeft
;>     rWX = u8(rWX - 8)
	ldh a, [rWX]
	sub 8
	ldh [rWX], a
	dec c
	jr nz, .scrollLoop2

;> hWY = 0
	xor a
	ldh [hWY], a
;> rBGP = 0b11000000
	ld a, %11000000
	ldh [rBGP], a
	ret

;@ path: engine/movie/credits
CreditsMons:
; one entry per CRED_TEXT_MON or CRED_TEXT_FADE_MON in CreditsOrder
	db VENUSAUR
	db ARBOK
	db RHYHORN
	db FEAROW
	db ABRA
	db GRAVELER
	db HITMONLEE
	db TANGELA
	db STARMIE
	db GYARADOS
	db DITTO
	db OMASTAR
	db VILEPLUME
	db NIDOKING
	db PARASECT

;@ path: engine/movie/credits
;@ def ScrollCreditsMonLeft(scx: b) -> b
;@ For one frame, scroll the middle band of the screen (lines $20 to $70) to `scx`, the rest not; returns scx + 8.
;@ test: skip waits for screen lines
ScrollCreditsMonLeft:
;> ScrollCreditsMonLeft_SetSCX(0x20, scx)
	ld h, b
	ld l, $20
	call ScrollCreditsMonLeft_SetSCX
;> ScrollCreditsMonLeft_SetSCX(0x70, 0)
	ld h, $0
	ld l, $70
	call ScrollCreditsMonLeft_SetSCX
;> return u8(scx + 8)
	ld a, b
	add $8
	ld b, a
	ret

;@ path: engine/movie/credits
;@ def ScrollCreditsMonLeft_SetSCX(line: l, scx: h)
;@ Wait for screen line `line`, set the horizontal scroll to `scx`, then wait while the line equals `scx`.
;@ test: skip waits for screen lines
ScrollCreditsMonLeft_SetSCX:
;> wait_ly(line)
	ldh a, [rLY]
	cp l
	jr nz, ScrollCreditsMonLeft_SetSCX
;> rSCX = scx
	ld a, h
	ldh [rSCX], a
;> while rLY == scx:
;>     wait_ly()    # the LCD moves rLY on
.loop
	ldh a, [rLY]
	cp h
	jr z, .loop
	ret

;@ path: engine/movie/credits
HoFGBPalettes:
	db ((3) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((3) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((3) << 6) | ((2) << 4) | ((0) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((0) << 2) | (0)

;@ path: engine/movie/credits
;@ def CreditsCopyTileMapToVRAM(dest: hl)
;@ Copy the screen buffer to the BG map at dest during the next VBlanks.
;@ test: skip waits for frames
CreditsCopyTileMapToVRAM:
;> hAutoBGTransferDest[0] = dest & 0xFF
	ld a, l
	ldh [hAutoBGTransferDest], a
;> hAutoBGTransferDest[1] = dest >> 8
	ld a, h
	ldh [hAutoBGTransferDest + 1], a
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	jp Delay3

;@ path: engine/movie/credits
;@ def ShiftFontColorIndex(dest: hl, count: bc)
;@ Clear every second byte of count byte pairs from dest: in black-and-white tiles this turns black into light
;@ gray, so the credits text can fade in through the palette while the black bars stay black.
;@ test: dest = rand(0xC000, 0xCE00); count = rand(1, 256)
ShiftFontColorIndex:
; Zero every second byte at hl, writing a total of bc bytes.
; When used on VRAM font characters that contain only black and white shades,
; it shifts the color index: black -> light gray, allowing palette-controlled
; text fade-in during the Credits roll, while the black bars remain solid.
;>@pairs for i in range(count):
;>     mem[dest + 2 * i] = 0
	ld [hl], 0
	inc hl
	inc hl
;=@pairs
	dec bc
	ld a, b
	or c
	jr nz, ShiftFontColorIndex
;> return
	ret

;@ path: engine/movie/credits
;@ def FillFourRowsWithBlack(dest: hl)
;@ Four screen rows of black tiles from dest (the credits' bars).
;@ test: dest = rand(0xC000, 0xCF00)
FillFourRowsWithBlack:
;> FillMemory(dest, SCREEN_WIDTH * 4, 0x7E)
	ld bc, SCREEN_WIDTH * 4
	ld a, $7e
	jp FillMemory

;@ path: engine/movie/credits
;@ def FillMiddleOfScreenWithWhite()
;@ Blank the ten screen rows between the credits' black bars.
FillMiddleOfScreenWithWhite:
;> FillMemory(coord(0, 4), SCREEN_WIDTH * 10, charmap(' ')[0])
	ld hl, (4) * SCREEN_WIDTH + (0) + wTileMap
	ld bc, SCREEN_WIDTH * 10
	ld a, ' '
	jp FillMemory

;@ path: engine/movie/credits
;@ def Credits()
;@ Run the credits from CreditsOrder: each name line is placed two rows below the last, centered by an offset
;@ in its text; the commands end a page (with or without fade-in, with or without a Pokémon running across
;@ after it), show the copyright, or THE END.
;@ test: skip runs the credits
Credits:
;> command_at = CreditsOrder
	ld de, CreditsOrder
	push de
;> while True:
.nextCreditsScreen
;>     at = coord(9, 6)                              # a new page
	pop de
	ld hl, (6) * SCREEN_WIDTH + (9) + wTileMap
	push hl
;>     FillMiddleOfScreenWithWhite()
	call FillMiddleOfScreenWithWhite
;>     while True:
	pop hl
.nextCreditsCommand
;>         command = mem[command_at]
;>         command_at += 1
	ld a, [de]
	inc de
	push de
;>         if command == CRED_TEXT_FADE_MON:     # the page ends: fade in, then a Pokémon runs across
	cp CRED_TEXT_FADE_MON
	jr z, .fadeInTextAndShowMon
;>@a1             FadeInCredits()
;>@a2             DelayFrames(90)
;>@a3             DisplayCreditsMon()
;>@a4             break
;>         elif command == CRED_TEXT_MON:        # the page ends, then a Pokémon runs across
	cp CRED_TEXT_MON
	jr z, .showTextAndShowMon
;>@b1             DelayFrames(110)
;>@b2             DisplayCreditsMon()
;>@b3             break
;>         elif command == CRED_TEXT_FADE:       # the page ends with a fade-in
	cp CRED_TEXT_FADE
	jr z, .fadeInText
;>@c1             FadeInCredits()
;>@c2             DelayFrames(120)
;>@c3             break
;>         elif command == CRED_TEXT:            # the page ends
	cp CRED_TEXT
	jr z, .showText
;>@d1             DelayFrames(140)
;>@d2             break
;>         elif command == CRED_COPYRIGHT:
	cp CRED_COPYRIGHT
	jr z, .showCopyrightText
;>@e1             LoadCopyrightTiles()
;>@e2             continue
;>         elif command == CRED_THE_END:
	cp CRED_THE_END
	jr z, .showTheEnd
;>@f1             DelayFrames(16)
;>@f2             FillMiddleOfScreenWithWhite()
;>@f3             CopyVideoData(vChars2 + 0x60 * TILE_SIZE, TheEndGfx, BANK(TheEndGfx), (TheEndGfxEnd - TheEndGfx) // TILE_SIZE)
;>@f4             _, after = PlaceString(TheEndTextString, coord(4, 8))
;>@f5             PlaceString(after + 1, coord(4, 9))
;>@f6             return FadeInCredits()
;>         # any other command is a name line
;>         line_at = at                              # (kept on the stack)
	push hl
	push hl
;>         entry_at = CreditsTextPointers + 2 * command
	ld hl, CreditsTextPointers
	add a
	ld c, a
	ld b, 0
	add hl, bc
;>         text = mem16[entry_at]
	ld e, [hl]
	inc hl
	ld d, [hl]
;>         offset = mem[text] - 0x100                # the first byte: a negative offset from the center
	ld a, [de]
	inc de
	ld c, a
	ld b, -1
;>         PlaceString(text + 1, at + offset)
	pop hl
	add hl, bc
	call PlaceString
;>         at += SCREEN_WIDTH * 2
	pop hl
	ld bc, SCREEN_WIDTH * 2
	add hl, bc
	pop de
	jr .nextCreditsCommand
.fadeInTextAndShowMon
;=@a1
	call FadeInCredits
;=@a2
	ld c, 90
	jr .next1
.showTextAndShowMon
;=@b1
	ld c, 110
.next1
	call DelayFrames
;=@a3
	call DisplayCreditsMon
;=@a4
	jr .nextCreditsScreen
.fadeInText
;=@c1
	call FadeInCredits
;=@c2
	ld c, 120
	jr .next2
.showText
;=@d1
	ld c, 140
.next2
	call DelayFrames
;=@c3
	jr .nextCreditsScreen
.showCopyrightText
;=@e1
	push de
	ld b, BANK(LoadCopyrightTiles)
	ld hl, LoadCopyrightTiles
	call Bankswitch
	pop de
;=@e2
	pop de
	jr .nextCreditsCommand
.showTheEnd
;=@f1
	ld c, 16
	call DelayFrames
;=@f2
	call FillMiddleOfScreenWithWhite
;=@f3
	pop de
	ld de, TheEndGfx
	ld hl, vChars2 + TILE_SIZE * $60
	ld bc, ((BANK(TheEndGfx)) & $ff) << 8 + (((TheEndGfxEnd - TheEndGfx) / TILE_SIZE) & $ff)
	call CopyVideoData
;=@f4
	ld hl, (8) * SCREEN_WIDTH + (4) + wTileMap
	ld de, TheEndTextString
	call PlaceString
;=@f5
	ld hl, (9) * SCREEN_WIDTH + (4) + wTileMap
	inc de
	call PlaceString
;=@f6
	jp FadeInCredits

