;@ path: engine/pokemon/status_ailments
;@ def PrintStatusAilment(status: de, dest: hl) -> hl
;@ Write the 3-letter abbreviation of the status at `status` to dest: PSN, BRN, FRZ, PAR or SLP (nothing if
;@ healthy). Returns the address of its last letter.
;@ test: dest = rand_ram(4)
PrintStatusAilment::
;> s = mem[status]
	ld a, [de]
;> if s >> PSN & 1:
	bit PSN, a
	jr nz, .psn
;>     text = "PSN"
;> elif s >> BRN & 1:
	bit BRN, a
	jr nz, .brn
;>     text = "BRN"
;> elif s >> FRZ & 1:
	bit FRZ, a
	jr nz, .frz
;>     text = "FRZ"
;> elif s >> PAR & 1:
	bit PAR, a
	jr nz, .par
;>     text = "PAR"
;> elif s & SLP_MASK:
	and SLP_MASK
;>     text = "SLP"
;> else:
;>     return dest                               # healthy
	ret z
;>@c0 mem[dest] = charmap(text)[0]
	ld a, CHARVAL(STRCHAR("SLP", $0))
	ld [hli], a
;>@c1 mem[dest + 1] = charmap(text)[1]
	ld a, CHARVAL(STRCHAR("SLP", $1))
	ld [hli], a
;>@c2 mem[dest + 2] = charmap(text)[2]
	ld [hl], CHARVAL(STRCHAR("SLP", CHARLEN("SLP") - 1))
;>@end return dest + 2
	ret
.psn
;=@c0
	ld a, CHARVAL(STRCHAR("PSN", $0))
	ld [hli], a
;=@c1
	ld a, CHARVAL(STRCHAR("PSN", $1))
	ld [hli], a
;=@c2
	ld [hl], CHARVAL(STRCHAR("PSN", CHARLEN("PSN") - 1))
;=@end
	ret
.brn
;=@c0
	ld a, CHARVAL(STRCHAR("BRN", $0))
	ld [hli], a
;=@c1
	ld a, CHARVAL(STRCHAR("BRN", $1))
	ld [hli], a
;=@c2
	ld [hl], CHARVAL(STRCHAR("BRN", CHARLEN("BRN") - 1))
;=@end
	ret
.frz
;=@c0
	ld a, CHARVAL(STRCHAR("FRZ", $0))
	ld [hli], a
;=@c1
	ld a, CHARVAL(STRCHAR("FRZ", $1))
	ld [hli], a
;=@c2
	ld [hl], CHARVAL(STRCHAR("FRZ", CHARLEN("FRZ") - 1))
;=@end
	ret
.par
;=@c0
	ld a, CHARVAL(STRCHAR("PAR", $0))
	ld [hli], a
;=@c1
	ld a, CHARVAL(STRCHAR("PAR", $1))
	ld [hli], a
;=@c2
	ld [hl], CHARVAL(STRCHAR("PAR", CHARLEN("PAR") - 1))
;=@end
	ret
;@ def HiddenItemNear() -> carry
;@ The Itemfinder: carry if a hidden item not yet found on this map lies within reach - up to 4 or 5 tiles away in
;@ each direction.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
;@ path: engine/items/itemfinder
HiddenItemNear:
;> p = HiddenItemCoords
	ld hl, HiddenItemCoords
;> i = 0
	ld b, 0
.loop
;>@lp while True:
;>     i, p, here = IsInRestOfArray(wCurMap, p, 3, i)
	ld de, 3
	ld a, [wCurMap]
	call IsInRestOfArray
;>     if not here:
;>         return False                        # no more hidden items on this map
	ret nc ; return if current map has no hidden items
;>     # (i and p are kept)
	push bc
	push hl
;>     found = FlagAction(wObtainedHiddenItemsFlags, i, FLAG_TEST)
	ld hl, wObtainedHiddenItemsFlags
	ld c, b
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
	ld a, c
;>     # (i and p come back)
	pop hl
	pop bc
;>     i = u8(i + 1)
	inc b
;>     taken = found != 0                      # found already
	and a
;>     y = mem[p + 1]
	inc hl
	ld d, [hl]
;>     x = mem[p + 2]
	inc hl
	ld e, [hl]
;>     p += 3
	inc hl
;>     if taken:
;>         continue
	jr nz, .loop ; if the item has already been obtained
; check if the item is within 4-5 tiles (depending on the direction of item)
;>     top = Sub5ClampTo0(wYCoord)
	ld a, [wYCoord]
	call Sub5ClampTo0
;>     if top >= y:
;>         continue
	cp d
	jr nc, .loop
;>     if u8(wYCoord + 4) < y:
;>         continue
	ld a, [wYCoord]
	add 4
	cp d
	jr c, .loop
;>     left = Sub5ClampTo0(wXCoord)
	ld a, [wXCoord]
	call Sub5ClampTo0
;>     if left >= x:
;>         continue
	cp e
	jr nc, .loop
;>     if u8(wXCoord + 5) < x:
;>         continue
	ld a, [wXCoord]
	add 5
	cp e
	jr c, .loop
;>     return True                             # within reach
	scf
	ret

;@ def Sub5ClampTo0(n: a) -> a
;@ n - 5, but not below 0.
;@ path: engine/items/itemfinder
Sub5ClampTo0:
; subtract 5 but clamp to 0
;> v = (n - 5) & 0xFF
;> return v if v < 0xF0 else 0
	sub 5
	cp $f0
	ret c
	xor a
	ret


SECTION "Vending Machine", ROMX

;@ path: engine/events/vending_machine
;@ def VendingMachineMenu()
;@ The Celadon vending machines: choose Fresh Water, Soda Pop or Lemonade (if the player has at least ¥200),
;@ the drink rumbles out and its price is paid.
;@ test: skip shows a menu
VendingMachineMenu::
;> PrintText(VendingMachineText1)
	ld hl, VendingMachineText1
	call PrintText
;> wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	call DisplayTextBoxID
;> wCurrentMenuItem = 0
	xor a
	ld [wCurrentMenuItem], a
;> wLastMenuItem = 0
	ld [wLastMenuItem], a
;> wMenuWatchedKeys = PAD_A | PAD_B
	ld a, PAD_A | PAD_B
	ld [wMenuWatchedKeys], a
;> wMaxMenuItem = 3
	ld a, 3
	ld [wMaxMenuItem], a
;> wTopMenuItemY = 5
	ld a, 5
	ld [wTopMenuItemY], a
;> wTopMenuItemX = 1
	ld a, 1
	ld [wTopMenuItemX], a
;> wStatusFlags5 = wStatusFlags5 | 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> TextBoxBorder(coord(0, 3), 8, 12)
	ld hl, (3) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 8
	ld c, 12
	call TextBoxBorder
;> UpdateSprites()
	call UpdateSprites
;> PlaceString(DrinkText, coord(2, 5))
	ld hl, (5) * SCREEN_WIDTH + (2) + wTileMap
	ld de, DrinkText
	call PlaceString
;> PlaceString(DrinkPriceText, coord(9, 6))
	ld hl, (6) * SCREEN_WIDTH + (9) + wTileMap
	ld de, DrinkPriceText
	call PlaceString
;> wStatusFlags5 = wStatusFlags5 & ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	ld hl, wStatusFlags5
	res BIT_NO_TEXT_DELAY, [hl]
;> keys = HandleMenuInput()
	call HandleMenuInput
;> if keys & (1 << B_PAD_B) or wCurrentMenuItem == 3:      # CANCEL
;>@cancel     PrintText(VendingMachineText7)
;>@cancelret     return
	bit B_PAD_B, a
	jr nz, .notThirsty
	ld a, [wCurrentMenuItem]
	cp 3 ; chose Cancel?
	jr z, .notThirsty
;> hMoney[0] = 0
	xor a
	ldh [hMoney], a
;> hMoney[2] = 0
	ldh [hMoney + 2], a
;> hMoney[1] = 0x02                             # ¥200 (BCD)
	ld a, $2
	ldh [hMoney + 1], a
;> notEnough, _ = HasEnoughMoney()
	call HasEnoughMoney
;> if notEnough:
	jr nc, .enoughMoney
;>     PrintText(VendingMachineText4)
;>     return
	ld hl, VendingMachineText4
	jp PrintText
.enoughMoney
;> LoadVendingMachineItem()
	call LoadVendingMachineItem
;> given = GiveItem(hVendingMachineItem, 1)
	ldh a, [hVendingMachineItem]
	ld b, a
	ld c, 1
	call GiveItem
;> if not given:
;>@full     PrintText(VendingMachineText6)
;>@fullret     return
	jr nc, .BagFull

;>@rumble for _ in range(60):                          # the machine rumbles
	ld b, 60 ; number of times to play the "brrrrr" sound
.playDeliverySound
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
;>     PlaySound(SFX_PUSH_BOULDER)
	push bc
	ld a, SFX_PUSH_BOULDER
	call PlaySound
;=@rumble
	pop bc
	dec b
	jr nz, .playDeliverySound

;> PrintText(VendingMachineText5)
	ld hl, VendingMachineText5
	call PrintText
;> SubBCD(addr(wPlayerMoney) + 2, addr(hVendingMachinePrice) + 2, 3)   # through SubBCDPredef
	ld hl, hVendingMachinePrice + 2
	ld de, wPlayerMoney + 2
	ld c, $3
	ld a, (SubBCDPredefPredef - PredefPointers) / 3
	call Predef
;> wTextBoxID = MONEY_BOX
	ld a, MONEY_BOX
	ld [wTextBoxID], a
;> DisplayTextBoxID()
	jp DisplayTextBoxID
.BagFull
;=@full
	ld hl, VendingMachineText6
	jp PrintText
.notThirsty
;=@cancel
	ld hl, VendingMachineText7
	jp PrintText

