;@ path: engine/events/vending_machine
;@ def LoadVendingMachineItem()
;@ The chosen drink and its price (3 BCD bytes) from VendingPrices.
;@ test: wCurrentMenuItem = rand(0, 2)
LoadVendingMachineItem:
;>@p p = VendingPrices + u8(4 * wCurrentMenuItem)
	ld hl, VendingPrices
	ld a, [wCurrentMenuItem]
	add a
	add a
;=@p
	ld d, 0
	ld e, a
	add hl, de
;> hVendingMachineItem = mem[p]
	ld a, [hli]
	ldh [hVendingMachineItem], a
;> hVendingMachinePrice[0] = mem[p + 1]
	ld a, [hli]
	ldh [hVendingMachinePrice], a
;> hVendingMachinePrice[1] = mem[p + 2]
	ld a, [hli]
	ldh [hVendingMachinePrice + 1], a
;> hVendingMachinePrice[2] = mem[p + 3]
	ld a, [hl]
	ldh [hVendingMachinePrice + 2], a
	ret


;@ path: engine/events/vending_machine
VendingPrices:
	; item id, price
	db FRESH_WATER
	db ((((200) / 100000) % 10) << 4) | (((200) / 10000) % 10)
	db ((((200) / 1000) % 10) << 4) | (((200) / 100) % 10)
	db ((((200) / 10) % 10) << 4) | ((200) % 10)
	db SODA_POP
	db ((((300) / 100000) % 10) << 4) | (((300) / 10000) % 10)
	db ((((300) / 1000) % 10) << 4) | (((300) / 100) % 10)
	db ((((300) / 10) % 10) << 4) | ((300) % 10)
	db LEMONADE
	db ((((350) / 100000) % 10) << 4) | (((350) / 10000) % 10)
	db ((((350) / 1000) % 10) << 4) | (((350) / 100) % 10)
	db ((((350) / 10) % 10) << 4) | ((350) % 10)


SECTION "Itemfinder 2", ROMX

;@ def PKMNLeaguePC()
;@ The Hall of Fame PC: show every recorded champion team, oldest first, Pokémon by Pokémon; B stops. Only the
;@ last HOF_TEAM_CAPACITY teams are kept, so the numbering starts later once there have been more.
;@ path: engine/menus/league_pc
PKMNLeaguePC:
;> PrintText(AccessedHoFPCText)
	ld hl, AccessedHoFPCText
	call PrintText
;> wStatusFlags5 |= 1 << BIT_NO_TEXT_DELAY
	ld hl, wStatusFlags5
	set BIT_NO_TEXT_DELAY, [hl]
;> sprites, animations = wUpdateSpritesEnabled, hTileAnimations
	push hl
	ld a, [wUpdateSpritesEnabled]
	push af
	ldh a, [hTileAnimations]
	push af
;> hTileAnimations = 0
	xor a
	ldh [hTileAnimations], a
;> wSpriteFlipped = 0
	ld [wSpriteFlipped], a
;> wUpdateSpritesEnabled = 0
	ld [wUpdateSpritesEnabled], a
;> wHoFTeamIndex2 = 0
	ld [wHoFTeamIndex2], a
;> wHoFTeamNo = 0
	ld [wHoFTeamNo], a
;> count = wNumHoFTeams
	ld a, [wNumHoFTeams]
	ld b, a
;> if count > HOF_TEAM_CAPACITY:
	cp HOF_TEAM_CAPACITY + 1
	jr c, .loop
; If the total number of hall of fame teams is greater than the storage
; capacity, then calculate the number of the first team that is still recorded.
;>     wHoFTeamNo = count - HOF_TEAM_CAPACITY
;>     count = HOF_TEAM_CAPACITY
	ld b, HOF_TEAM_CAPACITY
	sub b
	ld [wHoFTeamNo], a
;> while True:
.loop
;>     wHoFTeamNo += 1
	ld hl, wHoFTeamNo
	inc [hl]
;>     wHoFTeamIndex = wHoFTeamIndex2
	push bc
	ld a, [wHoFTeamIndex2]
	ld [wHoFTeamIndex], a
;>     farcall(LoadHallOfFameTeams)
	ld b, BANK(LoadHallOfFameTeams)
	ld hl, LoadHallOfFameTeams
	call Bankswitch
;>     if LeaguePCShowTeam():                  # B pressed
;>         break
	call LeaguePCShowTeam
	pop bc
	jr c, .doneShowingTeams
;>     wHoFTeamIndex2 += 1
	ld hl, wHoFTeamIndex2
	inc [hl]
;>     if wHoFTeamIndex2 == count:
;>         break
	ld a, [hl]
	cp b
	jr nz, .loop
.doneShowingTeams
;> hTileAnimations = animations
	pop af
	ldh [hTileAnimations], a
;> wUpdateSpritesEnabled = sprites
	pop af
	ld [wUpdateSpritesEnabled], a
;> wStatusFlags5 &= ~(1 << BIT_NO_TEXT_DELAY) & 0xFF
	pop hl
	res BIT_NO_TEXT_DELAY, [hl]
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> RunDefaultPaletteCommand()
	call RunDefaultPaletteCommand
;> return GBPalNormal()
	jp GBPalNormal

;@ path: engine/menus/league_pc
;@ def LeaguePCShowTeam() -> carry
;@ Show the team in wHallOfFame one Pokémon at a time, each after a button press, shifting the list up as it goes.
;@ Carry if the player pressed B to stop.
LeaguePCShowTeam:
;> for _ in range(PARTY_LENGTH):
	ld c, PARTY_LENGTH
.loop
;>     LeaguePCShowMon()
	push bc
	call LeaguePCShowMon
;>     WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress
;>     if hJoyHeld & PAD_B:
;>         return True
	ldh a, [hJoyHeld]
	bit B_PAD_B, a
	jr nz, .exit
;>     CopyData(addr(wHallOfFame) + HOF_MON, addr(wHallOfFame), HOF_TEAM - HOF_MON)
	ld hl, wHallOfFame + HOF_MON
	ld de, wHallOfFame
	ld bc, HOF_TEAM - HOF_MON
	call CopyData
;>     if mem[addr(wHallOfFame)] == 0xFF:     # the end of the team
;>         break
	pop bc
	ld a, [wHallOfFame + 0]
	cp $ff
	jr z, .done
	dec c
	jr nz, .loop
.done
;> return False
	and a
	ret
.exit
	pop bc
	scf
	ret

;@ path: engine/menus/league_pc
;@ def LeaguePCShowMon()
;@ One Hall of Fame Pokémon (the first in wHallOfFame): its picture in its colours, "HALL OF FAME No" with the
;@ team's number, and its name, level and species details.
LeaguePCShowMon:
;> GBPalWhiteOutWithDelay3()
	call GBPalWhiteOutWithDelay3
;> ClearScreen()
	call ClearScreen
;> h = addr(wHallOfFame)
	ld hl, wHallOfFame
;> wHoFMonSpecies = wCurPartySpecies = wCurSpecies = wBattleMonSpecies2 = wWholeScreenPaletteMonSpecies = mem[h]
	ld a, [hli]
	ld [wHoFMonSpecies], a
	ld [wCurPartySpecies], a
	ld [wCurSpecies], a
	ld [wBattleMonSpecies2], a
	ld [wWholeScreenPaletteMonSpecies], a
;> wHoFMonLevel = mem[h + 1]
	ld a, [hli]
	ld [wHoFMonLevel], a
;> CopyData(h + 2, addr(wNameBuffer), NAME_LENGTH)
	ld de, wNameBuffer
	ld bc, NAME_LENGTH
	call CopyData
;> RunPaletteCommand(SET_PAL_POKEMON_WHOLE_SCREEN)
	ld b, SET_PAL_POKEMON_WHOLE_SCREEN
	ld c, 0
	call RunPaletteCommand
;> GetMonHeader()
;> LoadFrontSpriteByMonIndex(coord(12, 5))
	ld hl, (5) * SCREEN_WIDTH + (12) + wTileMap
	call GetMonHeader
	call LoadFrontSpriteByMonIndex
;> GBPalNormal()
	call GBPalNormal
;> TextBoxBorder(coord(0, 13), 2, 18)
	ld hl, (13) * SCREEN_WIDTH + (0) + wTileMap
	ld b, 2
	ld c, $12
	call TextBoxBorder
;> PlaceString(HallOfFameNoText, coord(1, 15))
	ld hl, (15) * SCREEN_WIDTH + (1) + wTileMap
	ld de, HallOfFameNoText
	call PlaceString
;> PrintNumber(addr(wHoFTeamNo), coord(16, 15), 1, 3)
	ld hl, (15) * SCREEN_WIDTH + (16) + wTileMap
	ld de, wHoFTeamNo
	ld bc, ((1) & $ff) << 8 + ((3) & $ff)
	call PrintNumber
;> return farcall(HoFDisplayMonInfo)
	ld b, BANK(HoFDisplayMonInfo)
	ld hl, HoFDisplayMonInfo
	jp Bankswitch

