;@ path: engine/events/hidden_items
;@ def HiddenItems()
;@ A hidden item: unless already found (wObtainedHiddenItemsFlags, by its place in HiddenItemCoords), name it
;@ and show "found an item".
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
HiddenItems:
;> wHiddenItemOrCoinsIndex = FindHiddenItemOrCoinsIndex(HiddenItemCoords)
	ld hl, HiddenItemCoords
	call FindHiddenItemOrCoinsIndex
	ld [wHiddenItemOrCoinsIndex], a
;>@found found = FlagAction(addr(wObtainedHiddenItemsFlags), wHiddenItemOrCoinsIndex, FLAG_TEST)    # through FlagActionPredef
	ld hl, wObtainedHiddenItemsFlags
	ld a, [wHiddenItemOrCoinsIndex]
	ld c, a
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;=@found
	ld a, c
	and a
;> if found: return
	ret nz
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> wDoNotWaitForButtonPressAfterDisplayingText = 1
	ld a, 1
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;> wNamedObjectIndex = wHiddenEventFunctionArgument
	ld a, [wHiddenEventFunctionArgument] ; item ID
	ld [wNamedObjectIndex], a
;> GetItemName()
	call GetItemName
;> PrintPredefTextID((FoundHiddenItemText_id - TextPredefs) // 2 + 1)
	ld a, (FoundHiddenItemText_id - TextPredefs) / 2 + 1
	jp PrintPredefTextID


