;@ path: engine/events/hidden_items
;@ def FoundHiddenItemText() -> hl
;@ "<PLAYER> found <ITEM>!": the item goes into the bag and is marked as found, with a jingle - or the bag is
;@ full and it stays hidden.
;@ test: skip a text script: the code after text_asm is run by the text engine
FoundHiddenItemText::
	db TX_FAR
	dw _FoundHiddenItemText
	db BANK(_FoundHiddenItemText)
	db TX_START_ASM
;> if GiveItem(wHiddenEventFunctionArgument, 1):
	ld a, [wHiddenEventFunctionArgument] ; item ID
	ld b, a
	ld c, 1
	call GiveItem
	jr nc, .bagFull
;>     FlagAction(addr(wObtainedHiddenItemsFlags), wHiddenItemOrCoinsIndex, FLAG_SET)   # through FlagActionPredef
	ld hl, wObtainedHiddenItemsFlags
	ld a, [wHiddenItemOrCoinsIndex]
	ld c, a
	ld b, FLAG_SET
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;>     PlaySoundWaitForCurrent(SFX_GET_ITEM_2)
	ld a, SFX_GET_ITEM_2
	call PlaySoundWaitForCurrent
;>     WaitForSoundToFinish()
	call WaitForSoundToFinish
	jp TextScriptEnd
.bagFull
;> else:
;>     WaitForTextScrollButtonPress()
	call WaitForTextScrollButtonPress ; wait for button press
;>     wDoNotWaitForButtonPressAfterDisplayingText = 0
	xor a
	ld [wDoNotWaitForButtonPressAfterDisplayingText], a
;>     PrintText(HiddenItemBagFullText)
	ld hl, HiddenItemBagFullText
	call PrintText
;> return TextScriptEnd()
	jp TextScriptEnd

;@ path: engine/events/hidden_items
HiddenItemBagFullText::
	db TX_FAR
	dw _HiddenItemBagFullText
	db BANK(_HiddenItemBagFullText)
	db TX_END

;@ path: engine/events/hidden_items
;@ def HiddenCoins()
;@ Hidden coins on the Game Corner floor (only with the Coin Case, once per spot): 10, 20 or 100 coins are
;@ added - a 40-coin spot also gives only 20. With 9999 coins the coins are dropped instead.
;@ test: skip calls through the predef table (which keeps its registers in wPredefHL/DE/BC)
HiddenCoins:
;> if not GetQuantityOfItemInBag():             # a predef, asked for COIN_CASE
;>     return
	ld b, COIN_CASE
	ld a, (GetQuantityOfItemInBagPredef - PredefPointers) / 3
	call Predef
	ld a, b
	and a
	ret z
;> wHiddenItemOrCoinsIndex = FindHiddenItemOrCoinsIndex(HiddenCoinCoords)
	ld hl, HiddenCoinCoords
	call FindHiddenItemOrCoinsIndex
	ld [wHiddenItemOrCoinsIndex], a
;>@found found = FlagAction(addr(wObtainedHiddenCoinsFlags), wHiddenItemOrCoinsIndex, FLAG_TEST)    # through FlagActionPredef
	ld hl, wObtainedHiddenCoinsFlags
	ld a, [wHiddenItemOrCoinsIndex]
	ld c, a
	ld b, FLAG_TEST
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;=@found
	ld a, c
	and a
;> if found: return
	ret nz
;> hUnusedCoinsByte = 0
	xor a
	ldh [hUnusedCoinsByte], a
;> hCoins[0] = 0
	ldh [hCoins], a
;> hCoins[1] = 0
	ldh [hCoins + 1], a
;> amount = u8(wHiddenEventFunctionArgument - COIN)
	ld a, [wHiddenEventFunctionArgument]
	sub COIN
;> if amount == 10:
;>@b10     hCoins[1] = 0x10
	cp 10
	jr z, .bcd10
;> elif amount == 20 or amount == 40:          # 40 should have its own case (.bcd40 is never reached)
;>@b20     hCoins[1] = 0x20
	cp 20
	jr z, .bcd20
	cp 40
	jr z, .bcd20 ; should be bcd40
;> else:
;>@b100     hCoins[0] = 0x01                         # 100 (BCD)
	jr .bcd100
.bcd10
;=@b10
	ld a, $10
	ldh [hCoins + 1], a
	jr .bcdDone
.bcd20
;=@b20
	ld a, $20
	ldh [hCoins + 1], a
	jr .bcdDone
.bcd40 ; due to a typo, this is never used
	ld a, $40
	ldh [hCoins + 1], a
	jr .bcdDone
.bcd100
;=@b100
	ld a, $1
	ldh [hCoins], a
.bcdDone
;> AddBCD(addr(wPlayerCoins) + 1, addr(hCoins) + 1, 2)                  # through AddBCDPredef
	ld de, wPlayerCoins + 1
	ld hl, hCoins + 1
	ld c, $2
	ld a, (AddBCDPredefPredef - PredefPointers) / 3
	call Predef
;> FlagAction(addr(wObtainedHiddenCoinsFlags), wHiddenItemOrCoinsIndex, FLAG_SET)      # through FlagActionPredef
	ld hl, wObtainedHiddenCoinsFlags
	ld a, [wHiddenItemOrCoinsIndex]
	ld c, a
	ld b, FLAG_SET
	ld a, (FlagActionPredefPredef - PredefPointers) / 3
	call Predef
;> EnableAutoTextBoxDrawing()
	call EnableAutoTextBoxDrawing
;> if wPlayerCoins[0] == 0x99 and wPlayerCoins[1] == 0x99:
	ld a, [wPlayerCoins]
	cp $99
	jr nz, .roomInCoinCase
	ld a, [wPlayerCoins + 1]
	cp $99
	jr nz, .roomInCoinCase
;>     PrintPredefTextID((DroppedHiddenCoinsText_id - TextPredefs) // 2 + 1)
	ld a, (DroppedHiddenCoinsText_id - TextPredefs) / 2 + 1
	jr .done
.roomInCoinCase
;> else:
;>     PrintPredefTextID((FoundHiddenCoinsText_id - TextPredefs) // 2 + 1)
	ld a, (FoundHiddenCoinsText_id - TextPredefs) / 2 + 1
.done
	jp PrintPredefTextID


