;@ path: engine/events/hidden_items
;@ def FindHiddenItemOrCoinsIndex(table: hl) -> a
;@ The index of the hidden item or coin spot (map, y, x) at wHiddenEventY/X on this map in `table`, or $FF
;@ when there is none.
;@ test: table = rand_ram(31); mem[table + 3 * rand(0, 9)] = 0xFF
FindHiddenItemOrCoinsIndex:
;> y = wHiddenEventY
	ld a, [wHiddenEventY]
	ld d, a
;> x = wHiddenEventX
	ld a, [wHiddenEventX]
	ld e, a
;> m = wCurMap
	ld a, [wCurMap]
	ld b, a
;> index = 0xFF                                 # counted up to 0 at the top of the loop
	ld c, -1
.loop
;>@loop while True:
;>     index = u8(index + 1)
	inc c
;>     entry = mem[table]
;>@t1     table += 1
	ld a, [hli]
;>     if entry == 0xFF: return 0xFF            # end of the list
	cp -1 ; end of the list?
	ret z  ; if so, we're done here
;>     if entry == m:
	cp b
	jr nz, .next1
;>         ey = mem[table]
;>@t2         table += 1
	ld a, [hli]
;>         if ey == y:
	cp d
	jr nz, .next2
;>             ex = mem[table]
;>@t3             table += 1
	ld a, [hli]
;>             if ex == x: return index
	cp e
	jr nz, .loop
	ld a, c
	ret
;>         else:
;>@skip1             table += 1
;>     else:
;>         table += 2
.next1
	inc hl
.next2
;=@skip1
	inc hl
;=@loop
	jr .loop


SECTION "bank1E", ROMX

; Draws a "frame block". Frame blocks are blocks of tiles that are put
; together to form frames in battle animations.
;@ path: engine/battle/animations
;@ def DrawFrameBlock(block: bc)
;@ Write a frame block's sprites to the OAM buffer at wFBDestAddr (big-endian): each tile's offsets are added to the
;@ base coordinates, mirrored as wSubAnimTransform says, and its tile number moved up to the animation tiles ($31).
;@ Then, by wFBMode: mode 2 goes straight on after these sprites; the others wait wSubAnimFrameDelay frames first -
;@ mode 3 goes on after them, mode 4 stays, and the rest clear the sprites (not for Growl) and start over at the
;@ beginning of the buffer.
;@ test: block = rand_ram(48); mem[block] = rand(1, 10); mem[wFBDestAddr] = 0xC3; mem[wFBDestAddr + 1] = 0; wFBMode = FRAMEBLOCKMODE_02
DrawFrameBlock:
;> src = block
	ld l, c
	ld h, b
;> wNumFBTiles = mem[src]
;> src += 1
	ld a, [hli]
	ld [wNumFBTiles], a
;> dest = wFBDestAddr[0] << 8 | wFBDestAddr[1]
	ld a, [wFBDestAddr + 1]
	ld e, a
	ld a, [wFBDestAddr]
	ld d, a
;> wFBTileCounter = 0
	xor a
	ld [wFBTileCounter], a ; loop counter
.loop
;> while True:                                       # each tile: Y, X, tile, flags
;>     wFBTileCounter = wFBTileCounter + 1 & 0xFF
	ld a, [wFBTileCounter]
	inc a
	ld [wFBTileCounter], a
;>     transform = wSubAnimTransform
	ld a, [wSubAnimTransform]
;>     if transform == SUBANIMTYPE_HVFLIP:           # mirrored both ways
;>@v1         y = wBaseCoordY + mem[src]
;>@v2         mem[dest] = 136 - y & 0xFF
;>@v3         x = wBaseCoordX + mem[src + 1]
;>@v4         mem[dest + 1] = 168 - x & 0xFF
;>@v5         mem[dest + 2] = mem[src + 2] + 0x31 & 0xFF
;>@v6         flags = mem[src + 3]
;>@v7         if flags == 0: new = OAM_YFLIP | OAM_XFLIP   # both flips toggled
;>@v8         elif flags == OAM_XFLIP: new = OAM_YFLIP
;>@v9         elif flags == OAM_YFLIP: new = OAM_XFLIP
;>@va         else: new = 0
;>@vb         mem[dest + 3] = new
	dec a
	jr z, .flipHorizontalAndVertical   ; SUBANIMTYPE_HVFLIP
;>     elif transform == SUBANIMTYPE_HFLIP:          # mirrored left-right and moved down
;>@h1         mem[dest] = wBaseCoordY + mem[src] + 40 & 0xFF
;>@h2         x = wBaseCoordX + mem[src + 1]
;>@h3         mem[dest + 1] = 168 - x & 0xFF
;>@h4         mem[dest + 2] = mem[src + 2] + 0x31 & 0xFF
;>@h5         flags = mem[src + 3]
;>@h6         if not flags >> B_OAM_XFLIP & 1: flags |= OAM_XFLIP
;>@h7         else: flags &= ~OAM_XFLIP & 0xFF
;>@h8         mem[dest + 3] = flags
	dec a
	jp z, .flipHorizontalTranslateDown ; SUBANIMTYPE_HFLIP
;>     else:
;>         if transform == SUBANIMTYPE_COORDFLIP:    # the base coordinates mirrored
;>@c1             y = 136 - wBaseCoordY & 0xFF
;>@c2             mem[dest] = y + mem[src] & 0xFF
;>@c3             x = 168 - wBaseCoordX & 0xFF
	dec a
	jr z, .flipBaseCoords              ; SUBANIMTYPE_COORDFLIP
; no transformation
;>         else:
;>             mem[dest] = wBaseCoordY + mem[src] & 0xFF
	ld a, [wBaseCoordY]
	add [hl]
	ld [de], a ; store Y
	inc hl
	inc de
;>             x = wBaseCoordX
	ld a, [wBaseCoordX]
	jr .finishCopying
.flipBaseCoords
;=@c1
	ld a, [wBaseCoordY]
	ld b, a
	ld a, 136
	sub b ; flip Y base coordinate
;=@c2
	add [hl] ; Y offset
	ld [de], a ; store Y
	inc hl
	inc de
;=@c3
	ld a, [wBaseCoordX]
	ld b, a
	ld a, 168
	sub b ; flip X base coordinate
.finishCopying ; finish copying values to OAM (when subanimation not transformed)
;>         mem[dest + 1] = x + mem[src + 1] & 0xFF
	add [hl] ; X offset
	ld [de], a ; store X
	inc hl
	inc de
;>         mem[dest + 2] = mem[src + 2] + 0x31 & 0xFF   # the battle animation tiles start at $31
	ld a, [hli]
	add $31 ; base tile ID for battle animations
	ld [de], a ; store tile ID
	inc de
;>         mem[dest + 3] = mem[src + 3]
;>     src, dest = src + 4, dest + 4 & 0xFFFF
	ld a, [hli]
	ld [de], a ; store flags
	inc de
	jp .nextTile
.flipHorizontalAndVertical
;=@v1
	ld a, [wBaseCoordY]
	add [hl] ; Y offset
	ld b, a
;=@v2
	ld a, 136
	sub b ; flip Y coordinate
	ld [de], a ; store Y
	inc hl
	inc de
;=@v3
	ld a, [wBaseCoordX]
	add [hl] ; X offset
	ld b, a
;=@v4
	ld a, 168
	sub b ; flip X coordinate
	ld [de], a ; store X
	inc hl
	inc de
;=@v5
	ld a, [hli]
	add $31 ; base tile ID for battle animations
	ld [de], a ; store tile ID
	inc de
; toggle horizontal and vertical flip
;=@v6
	ld a, [hli] ; flags
;=@v7
	and a
	ld b, OAM_YFLIP | OAM_XFLIP
	jr z, .storeFlags1
;=@v8
	cp OAM_XFLIP
	ld b, OAM_YFLIP
	jr z, .storeFlags1
;=@v9
	cp OAM_YFLIP
	ld b, OAM_XFLIP
	jr z, .storeFlags1
;=@va
	ld b, 0
.storeFlags1
;=@vb
	ld a, b
	ld [de], a
	inc de
	jp .nextTile
.flipHorizontalTranslateDown
;=@h1
	ld a, [wBaseCoordY]
	add [hl]
	add 40 ; translate Y coordinate downwards
	ld [de], a ; store Y
	inc hl
	inc de
;=@h2
	ld a, [wBaseCoordX]
	add [hl]
	ld b, a
;=@h3
	ld a, 168
	sub b ; flip X coordinate
	ld [de], a ; store X
	inc hl
	inc de
;=@h4
	ld a, [hli]
	add $31 ; base tile ID for battle animations
	ld [de], a ; store tile ID
	inc de
;=@h5
	ld a, [hli]
;=@h6
	bit B_OAM_XFLIP, a
	jr nz, .disableHorizontalFlip
; enable horizontal flip
	set B_OAM_XFLIP, a
	jr .storeFlags2
.disableHorizontalFlip
;=@h7
	res B_OAM_XFLIP, a
.storeFlags2
;=@h8
	ld [de], a
	inc de
.nextTile
;>     if wFBTileCounter == wNumFBTiles:
;>         break
	ld a, [wFBTileCounter]
	ld c, a
	ld a, [wNumFBTiles]
	cp c
	jp nz, .loop ; go back up if there are more tiles to draw
; after drawing tiles
;> if wFBMode != FRAMEBLOCKMODE_02:                  # mode 2: no wait, no clearing
	ld a, [wFBMode]
	cp FRAMEBLOCKMODE_02
	jr z, .advanceFrameBlockDestAddr ; skip delay and don't clean OAM buffer
;>     DelayFrames(wSubAnimFrameDelay)
	ld a, [wSubAnimFrameDelay]
	ld c, a
	call DelayFrames
;>     mode = wFBMode
	ld a, [wFBMode]
;>     if mode != FRAMEBLOCKMODE_03:                 # mode 3 goes on after these sprites
	cp FRAMEBLOCKMODE_03
	jr z, .advanceFrameBlockDestAddr ; skip cleaning OAM buffer
;>         if mode == FRAMEBLOCKMODE_04:             # mode 4 stays
;>@d4             return
	cp FRAMEBLOCKMODE_04
	jr z, .done ; skip cleaning OAM buffer and don't advance the frame block destination address
;>         if wAnimationID != GROWL:
	ld a, [wAnimationID]
	cp GROWL
	jr z, .resetFrameBlockDestAddr
;>             AnimationCleanOAM()
	call AnimationCleanOAM
.resetFrameBlockDestAddr
;>         wFBDestAddr[1] = lo(wShadowOAM + 0)       # the others start over
	ld hl, wShadowOAM
	ld a, l
	ld [wFBDestAddr + 1], a
;>         wFBDestAddr[0] = hi(wShadowOAM + 0)
;>         return
	ld a, h
	ld [wFBDestAddr], a ; set destination address to beginning of OAM buffer
	ret
.advanceFrameBlockDestAddr
;> wFBDestAddr[1] = lo(dest)
	ld a, e
	ld [wFBDestAddr + 1], a
;> wFBDestAddr[0] = hi(dest)
	ld a, d
	ld [wFBDestAddr], a
.done
;=@d4
	ret

;@ path: engine/battle/animations
;@ def PlayAnimation()
;@ Run the animation script of wAnimationID (AttackAnimationPointers), up to $FF. Commands from FIRST_SE_ID on are
;@ special effects (SpecialEffectPointers), with a sound; the others are subanimations: the command's top two bits
;@ pick the tileset and the rest the frame delay, followed by a sound and the subanimation's number.
PlayAnimation:
;> hROMBankTemp = 0
	xor a
	ldh [hROMBankTemp], a ; it looks like nothing reads this
;> wSubAnimTransform = 0
	ld [wSubAnimTransform], a
;> i = wAnimationID - 1 & 0xFF
	ld a, [wAnimationID] ; get animation number
	dec a
	ld l, a
	ld h, 0
;> entry = AttackAnimationPointers + 2 * i
	add hl, hl
	ld de, AttackAnimationPointers  ; animation command stream pointers
	add hl, de
;> script = mem16[entry]
	ld a, [hli]
	ld h, [hl]
	ld l, a
.animationLoop
;> while True:
;>     command, script = mem[script], script + 1
	ld a, [hli]
;>     if command == 0xFF:
;>@ao         return
	cp -1
	jr z, .AnimationOver
;>     if command >= FIRST_SE_ID:                    # a special effect
	cp FIRST_SE_ID ; is this subanimation or a special effect?
	jr c, .playSubanimation
; do Special Effect
;>         entry = SpecialEffectPointers
	ld c, a
	ld de, SpecialEffectPointers
.searchSpecialEffectTableLoop
;>         while mem[entry] != command:
	ld a, [de]
	cp c
	jr z, .foundMatch
;>             entry += 3
	inc de
	inc de
	inc de
	jr .searchSpecialEffectTableLoop
.foundMatch
;>         sound, script = mem[script], script + 1
	ld a, [hli]
;>         if sound != NO_MOVE - 1 & 0xFF:           # a sound to play
	cp NO_MOVE - 1 ; is there a sound to play?
	jr z, .skipPlayingSound
;>             wAnimSoundID = sound
	ld [wAnimSoundID], a ; store sound
;>             PlaySound(GetMoveSound(wAnimSoundID))
	push hl
	push de
	call GetMoveSound
	call PlaySound
	pop de
	pop hl
.skipPlayingSound
;>         effect = mem[entry + 1]
	push hl
	inc de
	ld a, [de]
	ld l, a
;>         effect |= mem[entry + 2] << 8
	inc de
	ld a, [de]
	ld h, a
;>         call(effect)
	ld de, .nextAnimationCommand
	push de
	jp hl ; jump to special effect function
.playSubanimation
;>     else:                                         # a subanimation
;>         wSubAnimFrameDelay = command & 0x3F
	ld c, a
	and %00111111
	ld [wSubAnimFrameDelay], a
;>         wWhichBattleAnimTileset = command >> 6
	xor a
	sla c
	rla
	sla c
	rla
	ld [wWhichBattleAnimTileset], a
;>         wAnimSoundID = mem[script]
;>         script += 1
	ld a, [hli] ; sound
	ld [wAnimSoundID], a ; store sound
;>         number, script = mem[script], script + 1
	ld a, [hli] ; subanimation ID
	ld c, l
	ld b, h
;>         subanimation = SubanimationPointers + 2 * number
	ld l, a
	ld h, 0
	add hl, hl
	ld de, SubanimationPointers
	add hl, de
;>         wSubAnimAddrPtr[0] = lo(subanimation)
	ld a, l
	ld [wSubAnimAddrPtr], a
;>         wSubAnimAddrPtr[1] = hi(subanimation)
	ld a, h
	ld [wSubAnimAddrPtr + 1], a
	ld l, c
	ld h, b
	push hl
;>         palette = rOBP0
	ldh a, [rOBP0]
	push af
;>         rOBP0 = wAnimPalette
	ld a, [wAnimPalette]
	ldh [rOBP0], a
;>         LoadMoveAnimationTiles()
;>         LoadSubanimation()
	call LoadMoveAnimationTiles
	call LoadSubanimation
;>         PlaySubanimation()
	call PlaySubanimation
;>         rOBP0 = palette
	pop af
	ldh [rOBP0], a
.nextAnimationCommand
	pop hl
	jr .animationLoop
.AnimationOver
;=@ao
	ret

;@ path: engine/battle/animations
;@ def LoadSubanimation()
;@ Start the subanimation that wSubAnimAddrPtr points at: its first byte holds the number of frame blocks and its
;@ type, which becomes wSubAnimTransform for the side whose turn it is. A reversed one starts at its last entry.
LoadSubanimation:
;> ptr = wSubAnimAddrPtr[1] << 8 | wSubAnimAddrPtr[0]
	ld a, [wSubAnimAddrPtr + 1]
	ld h, a
	ld a, [wSubAnimAddrPtr]
	ld l, a
;> subanimation = mem16[ptr]
	ld a, [hli]
	ld e, a
	ld a, [hl]
	ld d, a ; de = address of subanimation
;> header = mem[subanimation]
	ld a, [de]
	ld b, a
;> wSubAnimCounter = header & 0x1F                   # the number of frame blocks
	and %00011111
	ld [wSubAnimCounter], a ; number of frame blocks
;> kind = header & 0xE0
	ld a, b
	and %11100000
;> if kind == SUBANIMTYPE_ENEMY << 5:
	cp SUBANIMTYPE_ENEMY << 5
	jr nz, .isNotTypeEnemy
; subanim type enemy
;>     kind = GetSubanimationTransform2()
	call GetSubanimationTransform2
	jr .saveTransformation
.isNotTypeEnemy
;> else:
;>     kind = GetSubanimationTransform1(kind)
	call GetSubanimationTransform1
.saveTransformation
; place the upper 3 bits of a into bits 0-2 of a before storing
;> wSubAnimTransform = kind >> 5
	srl a
	swap a
	ld [wSubAnimTransform], a
;> offset = 0
;> if wSubAnimTransform == SUBANIMTYPE_REVERSE:      # it starts at its last entry
	cp SUBANIMTYPE_REVERSE
	ld hl, 0
	jr nz, .storeSubentryAddr
; if the animation is reversed, then place the initial subentry address at the end of the list of subentries
;>     n = wSubAnimCounter - 1 & 0xFF
	ld a, [wSubAnimCounter]
	dec a
	ld bc, 3
.loop
;>     offset = 3 * (n or 256) & 0xFFFF
	add hl, bc
	dec a
	jr nz, .loop
.storeSubentryAddr
;> entry = subanimation + 1 + offset & 0xFFFF
	inc de
	add hl, de
;> wSubAnimSubEntryAddr[0] = lo(entry)
	ld a, l
	ld [wSubAnimSubEntryAddr], a
;> wSubAnimSubEntryAddr[1] = hi(entry)
	ld a, h
	ld [wSubAnimSubEntryAddr + 1], a
	ret

; called if the subanimation type is not SUBANIMTYPE_ENEMY
; sets the transform to SUBANIMTYPE_NORMAL if it's the player's turn
; sets the transform to the subanimation type if it's the enemy's turn
;@ path: engine/battle/animations
;@ def GetSubanimationTransform1(kind: a) -> a
;@ An ordinary subanimation plays as it is on the player's turn, and as its type says on the enemy's.
GetSubanimationTransform1:
;> if hWhoseTurn:                                    # the enemy's turn: as its type says
;>     return kind
	ld b, a
	ldh a, [hWhoseTurn]
	and a
	ld a, b
	ret nz
;> return SUBANIMTYPE_NORMAL << 5
	xor a ; SUBANIMTYPE_NORMAL << 5
	ret

; called if the subanimation type is SUBANIMTYPE_ENEMY
; sets the transform to SUBANIMTYPE_HFLIP if it's the player's turn
; sets the transform to SUBANIMTYPE_NORMAL if it's the enemy's turn
;@ path: engine/battle/animations
;@ def GetSubanimationTransform2() -> a
;@ A subanimation of type "enemy" is mirrored on the player's turn and plays as it is on the enemy's.
GetSubanimationTransform2:
;> return SUBANIMTYPE_HFLIP << 5 if hWhoseTurn == 0 else SUBANIMTYPE_NORMAL << 5
	ldh a, [hWhoseTurn]
	and a
	ld a, SUBANIMTYPE_HFLIP << 5
	ret z
	xor a ; SUBANIMTYPE_NORMAL << 5
	ret

; loads tile patterns for battle animations
;@ path: engine/battle/animations
;@ def LoadMoveAnimationTiles()
;@ Load the animation tileset wWhichBattleAnimTileset (MoveAnimationTilesPointers) into sprite tiles from $31 on.
LoadMoveAnimationTiles:
;> i = 4 * wWhichBattleAnimTileset & 0xFF
	ld a, [wWhichBattleAnimTileset]
	add a
	add a
;> entry = MoveAnimationTilesPointers + i
	ld hl, MoveAnimationTilesPointers
	ld e, a
	ld d, 0
	add hl, de
;> wTempTilesetNumTiles = mem[entry]
	ld a, [hli]
	ld [wTempTilesetNumTiles], a ; number of tiles
;> tiles = mem16[entry + 1]
	ld a, [hli]
	ld e, a
	ld a, [hl]
	ld d, a ; de = address of tileset
;> CopyVideoData(vSprites + 0x31 * TILE_SIZE, tiles, BANK(MoveAnimationTiles0), wTempTilesetNumTiles)
	ld hl, vSprites + TILE_SIZE * $31
	ld b, BANK(MoveAnimationTiles0) ; ROM bank
	ld a, [wTempTilesetNumTiles]
	ld c, a ; number of tiles
	jp CopyVideoData ; load tileset


;@ path: engine/battle/animations
MoveAnimationTilesPointers:
	; number of tiles, gfx pointer
	db 79
	dw MoveAnimationTiles0
	db -1
	db 79
	dw MoveAnimationTiles1
	db -1
	db 64
	dw MoveAnimationTiles2
	db -1

;@ path: engine/battle/animations
MoveAnimationTiles0:
;@ path: engine/battle/animations
MoveAnimationTiles2:
	db $0f, $0f, $1f, $10, $3f, $20, $7f, $68, $bf, $e8, $7f, $60, $3f, $21, $7f, $41
	db $80, $80, $c0, $40, $e0, $20, $f8, $38, $fc, $64, $fc, $84, $fe, $06, $ff, $05
	db $00, $00, $00, $00, $00, $00, $00, $00, $03, $03, $0c, $0f, $11, $1e, $11, $1e
	db $18, $18, $34, $24, $62, $42, $d1, $81, $a1, $81, $d1, $81, $ab, $81, $d5, $81
	db $00, $00, $00, $00, $00, $00, $00, $28, $00, $00, $00, $8e, $00, $3f, $20, $5f
	db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $0e, $0e, $31, $1f, $60
	db $00, $00, $00, $00, $00, $00, $00, $00, $07, $07, $18, $1f, $23, $3c, $23, $3c
	db $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $60, $e0, $10, $f0, $10, $f0
	db $00, $00, $00, $00, $00, $00, $00, $1c, $00, $3e, $00, $67, $00, $6f, $00, $7f
	db $00, $00, $00, $00, $00, $00, $00, $38, $00, $7c, $00, $fe, $00, $fe, $00, $fe
	db $03, $03, $06, $05, $0d, $0a, $3a, $35, $55, $6a, $6a, $55, $d5, $aa, $ea, $d5
	db $00, $00, $e0, $e0, $50, $b0, $b0, $50, $58, $a8, $ac, $54, $56, $aa, $0e, $f6
	db $00, $00, $00, $00, $01, $03, $08, $19, $04, $0d, $24, $6c, $12, $36, $12, $36
	db $10, $10, $48, $58, $24, $6c, $92, $b6, $92, $b6, $49, $db, $49, $db, $49, $db
	db $07, $07, $1f, $1f, $3f, $3f, $73, $73, $61, $61, $73, $73, $7f, $7f, $3d, $3d
	db $07, $07, $65, $65, $78, $78, $0e, $0e, $03, $03, $0e, $0e, $78, $78, $60, $60
	db $7f, $40, $7f, $40, $3f, $20, $3f, $20, $1f, $18, $07, $07, $00, $00, $00, $00
	db $ff, $09, $fe, $f2, $fc, $04, $f8, $08, $f0, $30, $d8, $d8, $30, $30, $60, $60
	db $20, $3f, $20, $3f, $38, $27, $3f, $20, $1f, $10, $1f, $10, $0f, $0c, $03, $03
	db $eb, $81, $ff, $81, $ff, $81, $ff, $81, $81, $f1, $42, $72, $24, $34, $18, $18
	db $3b, $44, $0e, $f1, $40, $bf, $66, $99, $7f, $80, $3b, $c4, $00, $7f, $00, $33
	db $04, $7b, $71, $8e, $3f, $c0, $19, $e6, $00, $ff, $44, $bb, $33, $4c, $00, $33
	db $40, $7f, $40, $7f, $40, $7f, $41, $7e, $3f, $20, $3f, $20, $1f, $18, $07, $07
	db $08, $f8, $18, $e8, $38, $c8, $f8, $08, $f0, $10, $f0, $10, $e0, $60, $80, $80
