	db $48, $79, $61, $73, $52, $5e, $52, $5e, $31, $3f, $18, $1f, $07, $07, $00, $00
	db $02, $f2, $82, $f2, $42, $72, $22, $32, $1a, $1a, $f6, $f6, $80, $80, $00, $00
	db $00, $00, $01, $01, $02, $02, $04, $04, $1b, $1f, $20, $33, $28, $39, $48, $79
	db $00, $00, $00, $00, $c0, $c0, $20, $20, $26, $26, $ea, $ea, $3a, $fa, $12, $f2
	db $40, $40, $40, $60, $40, $60, $20, $20, $10, $10, $4c, $4c, $33, $33, $00, $00
	db $88, $88, $84, $8c, $44, $5c, $3c, $3c, $20, $20, $54, $54, $98, $98, $00, $00
	db $00, $00, $03, $03, $0c, $0f, $10, $1f, $10, $1f, $20, $3c, $20, $38, $40, $78
	db $00, $00, $c0, $c0, $20, $e0, $98, $98, $b0, $b0, $20, $20, $60, $60, $30, $30
	db $50, $70, $40, $60, $64, $64, $e4, $e4, $30, $30, $78, $78, $67, $67, $00, $00
	db $14, $1c, $04, $0c, $8c, $8c, $8c, $8c, $16, $16, $70, $70, $98, $98, $18, $18
	db $00, $00, $27, $27, $18, $18, $03, $03, $0c, $0c, $30, $38, $28, $2c, $64, $64
	db $00, $00, $f0, $f0, $08, $08, $c4, $c4, $34, $34, $18, $38, $28, $68, $4c, $4c
;@ path: engine/battle/animations
SlotMachineTiles2End:

;@ path: engine/battle/animations
;@ def MoveAnimation()
;@ Play the battle animation wAnimationID: a ball toss has its own code; a move's animation (or half a second
;@ without it when animations are off in the options) is followed by the shaking or blinking of wAnimationType.
;@ Keeps all registers.
;@ test: skip waits for the sound
MoveAnimation:
;> WaitForSoundToFinish()                            # (all registers are kept)
	push hl
	push de
	push bc
	push af
	call WaitForSoundToFinish
;> SetAnimationPalette()
	call SetAnimationPalette
;> if wAnimationID:
	ld a, [wAnimationID]
	and a
	jr z, .animationFinished

	; if throwing a Poké Ball, skip the regular animation code
;>     if wAnimationID == TOSS_ANIM:                 # a ball toss has its own code
	cp TOSS_ANIM
	jr nz, .moveAnimation
;>         TossBallAnimation()
	ld de, .animationFinished
	push de
	jp TossBallAnimation

.moveAnimation
	; check if battle animations are disabled in the options
;>     else:
;>         if wOptions >> BIT_BATTLE_ANIMATION & 1:  # animations off: a pause instead
;>@of             DelayFrames(30)
	ld a, [wOptions]
	bit BIT_BATTLE_ANIMATION, a
	jr nz, .animationsDisabled
;>         else:
;>             ShareMoveAnimations()
	call ShareMoveAnimations
;>             PlayAnimation()
	call PlayAnimation
	jr .next
.animationsDisabled
;=@of
	ld c, 30
	call DelayFrames
.next
;>         PlayApplyingAttackAnimation()             # the shaking or blinking
	call PlayApplyingAttackAnimation ; shake the screen or flash the pic in and out (to show damage)
.animationFinished
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> wSubAnimSubEntryAddr[0] = 0
	xor a
	ld [wSubAnimSubEntryAddr], a
;> wUnusedMoveAnimByte = 0
;> wSubAnimTransform = 0
	ld [wUnusedMoveAnimByte], a
	ld [wSubAnimTransform], a
;> wAnimSoundID = NO_MOVE - 1 & 0xFF
	dec a ; NO_MOVE - 1
	ld [wAnimSoundID], a
;> return                                            # (the registers back)
	pop af
	pop bc
	pop de
	pop hl
	ret

;@ path: engine/battle/animations
;@ def ShareMoveAnimations()
;@ On the enemy's turn Amnesia shows the confusion animation and Rest the sleep animation.
ShareMoveAnimations:
; some moves just reuse animations from status conditions
;> if hWhoseTurn == 0:
;>     return
	ldh a, [hWhoseTurn]
	and a
	ret z

	; opponent's turn

;> if wAnimationID == AMNESIA:
;>     wAnimationID = CONF_ANIM
	ld a, [wAnimationID]

	cp AMNESIA
	ld b, CONF_ANIM
	jr z, .replaceAnim

;> elif wAnimationID == REST:
;>     wAnimationID = SLP_ANIM
	cp REST
	ld b, SLP_ANIM
	ret nz

.replaceAnim
	ld a, b
	ld [wAnimationID], a
	ret

;@ path: engine/battle/animations
;@ def PlayApplyingAttackAnimation()
;@ The shaking or blinking that follows a move's animation, picked by wAnimationType (AnimationTypePointerTable).
;@ test: wAnimationType = rand(0, 6)
PlayApplyingAttackAnimation:
; Generic animation that shows after the move's individual animation
; Different animation depending on whether the move has an additional effect and on whose turn it is
;> if wAnimationType == 0:
;>     return
	ld a, [wAnimationType]
	and a
	ret z
;> entry = AnimationTypePointerTable + 2 * (wAnimationType - 1 & 0xFF)
	dec a
	add a
	ld c, a
	ld b, 0
	ld hl, AnimationTypePointerTable
	add hl, bc
;> call(mem16[entry])
	ld a, [hli]
	ld h, [hl]
	ld l, a
	jp hl

;@ path: engine/battle/animations
AnimationTypePointerTable:
	dw ShakeScreenVertically        ; enemy mon has used a damaging move without a side effect
	dw ShakeScreenHorizontallyHeavy ; enemy mon has used a damaging move with a side effect
	dw ShakeScreenHorizontallySlow  ; enemy mon has used a non-damaging move
	dw BlinkEnemyMonSprite          ; player mon has used a damaging move without a side effect
	dw ShakeScreenHorizontallyLight ; player mon has used a damaging move with a side effect
	dw ShakeScreenHorizontallySlow2 ; player mon has used a non-damaging move

;@ path: engine/battle/animations
;@ def ShakeScreenVertically()
;@ The hit sound and the screen shaking up and down (8).
ShakeScreenVertically:
;> PlayApplyingAttackSound()
;> AnimationShakeScreenVertically(8)
	call PlayApplyingAttackSound
	ld b, 8
	jp AnimationShakeScreenVertically

;@ path: engine/battle/animations
;@ def ShakeScreenHorizontallyHeavy()
;@ The hit sound and a strong horizontal shake (8).
ShakeScreenHorizontallyHeavy:
;> PlayApplyingAttackSound()
;> AnimationShakeScreenHorizontallyFast(8)
	call PlayApplyingAttackSound
	ld b, 8
	jp AnimationShakeScreenHorizontallyFast

;@ path: engine/battle/animations
;@ def ShakeScreenHorizontallySlow()
;@ The screen slides 6 pixels sideways and back, twice.
ShakeScreenHorizontallySlow:
;> AnimationShakeScreenHorizontallySlow(6, 2)
	ld bc, ((6) & $ff) << 8 + ((2) & $ff)
	jr AnimationShakeScreenHorizontallySlow

;@ path: engine/battle/animations
;@ def BlinkEnemyMonSprite()
;@ The hit sound and the enemy's mon blinking.
BlinkEnemyMonSprite:
;> PlayApplyingAttackSound()
;> AnimationBlinkEnemyMon()
	call PlayApplyingAttackSound
	jp AnimationBlinkEnemyMon

;@ path: engine/battle/animations
;@ def ShakeScreenHorizontallyLight()
;@ The hit sound and a light horizontal shake (2).
ShakeScreenHorizontallyLight:
;> PlayApplyingAttackSound()
;> AnimationShakeScreenHorizontallyFast(2)
	call PlayApplyingAttackSound
	ld b, 2
	jp AnimationShakeScreenHorizontallyFast

;@ path: engine/battle/animations
;@ def ShakeScreenHorizontallySlow2()
;@ The screen slides 3 pixels sideways and back, twice.
ShakeScreenHorizontallySlow2:
;> AnimationShakeScreenHorizontallySlow(3, 2)
	ld bc, ((3) & $ff) << 8 + ((2) & $ff)

;@ path: engine/battle/animations
;@ def AnimationShakeScreenHorizontallySlow(distance: b, times: c)
;@ Slide the window (the battle screen) `distance` pixels right and back, a pixel every 2 frames, `times` times.
AnimationShakeScreenHorizontallySlow:
;>@t for _ in range(times or 256):
	push bc
;>@o     for _ in range(distance or 256):              # right
	push bc
.loop1
;>         rWX = rWX + 1 & 0xFF
	ldh a, [rWX]
	inc a
	ldh [rWX], a
;>         DelayFrames(2)
	ld c, 2
	call DelayFrames
;=@o
	dec b
	jr nz, .loop1
;>@b     for _ in range(distance or 256):              # and back
	pop bc
.loop2
;>         rWX = rWX - 1 & 0xFF
	ldh a, [rWX]
	dec a
	ldh [rWX], a
;>         DelayFrames(2)
	ld c, 2
	call DelayFrames
;=@b
	dec b
	jr nz, .loop2
;=@t
	pop bc
	dec c
	jr nz, AnimationShakeScreenHorizontallySlow
	ret

;@ path: engine/battle/animations
;@ def SetAnimationPalette()
;@ The sprite palettes for animations: $E4 (on the Super Game Boy $F0, also for the trade animation's ball drop and
;@ poof), and $6C for the second palette.
SetAnimationPalette:
;> if wOnSGB:
	ld a, [wOnSGB]
	and a
	ld a, $e4
	jr z, .notSGB
;>     wAnimPalette = 0xF0
	ld a, $f0
	ld [wAnimPalette], a
;>     pal = 0xE4
	ld b, $e4
;>     if TRADE_BALL_DROP_ANIM <= wAnimationID <= TRADE_BALL_POOF_ANIM:   # the trade's ball drop and poof
	ld a, [wAnimationID]
	cp TRADE_BALL_DROP_ANIM
	jr c, .next
	cp TRADE_BALL_POOF_ANIM + 1
	jr nc, .next
;>         pal = 0xF0
	ld b, $f0
.next
;>     rOBP0 = pal
	ld a, b
	ldh [rOBP0], a
;>     rOBP1 = 0x6C
;>     return
	ld a, $6c
	ldh [rOBP1], a
	ret
.notSGB
;> else:
;>     wAnimPalette = 0xE4
	ld a, $e4
	ld [wAnimPalette], a
;>     rOBP0 = 0xE4
	ldh [rOBP0], a
;> rOBP1 = 0x6C
	ld a, $6c
	ldh [rOBP1], a
	ret

;@ path: engine/battle/animations
;@ def PlaySubanimation()
;@ Play the subanimation set up by LoadSubanimation: its sound, then one frame block per entry (frame block, base
;@ coordinates, mode), each followed by the animation's special effect if it has one; backwards for a reversed one.
PlaySubanimation:
;> if wAnimSoundID != NO_MOVE - 1 & 0xFF:
	ld a, [wAnimSoundID]
	cp NO_MOVE - 1
	jr z, .skipPlayingSound
;>     PlaySound(GetMoveSound(wAnimSoundID))
	call GetMoveSound
	call PlaySound
.skipPlayingSound
;> wFBDestAddr[0], wFBDestAddr[1] = hi(wShadowOAM + 0), lo(wShadowOAM + 0)
	ld hl, wShadowOAM
	ld a, l
	ld [wFBDestAddr + 1], a
	ld a, h
	ld [wFBDestAddr], a
;> entry = wSubAnimSubEntryAddr[1] << 8 | wSubAnimSubEntryAddr[0]
	ld a, [wSubAnimSubEntryAddr + 1]
	ld h, a
	ld a, [wSubAnimSubEntryAddr]
	ld l, a
.loop
;> while True:
;>     number = mem[entry]
	push hl
	ld c, [hl] ; frame block ID
	ld b, 0
;>     ptr = FrameBlockPointers + 2 * number
	ld hl, FrameBlockPointers
	add hl, bc
	add hl, bc
;>     block = mem16[ptr]
	ld a, [hli]
	ld c, a
	ld a, [hli]
	ld b, a
;>     number = mem[entry + 1]
	pop hl
	inc hl
	push hl
	ld e, [hl] ; base coordinate ID
	ld d, 0
;>     coords = FrameBlockBaseCoords + 2 * number
	ld hl, FrameBlockBaseCoords  ; base coordinate table
	add hl, de
	add hl, de
;>     wBaseCoordY = mem[coords]
	ld a, [hli]
	ld [wBaseCoordY], a
;>     wBaseCoordX = mem[coords + 1]
	ld a, [hl]
	ld [wBaseCoordX], a
;>     wFBMode = mem[entry + 2]
	pop hl
	inc hl
	ld a, [hl] ; frame block mode
	ld [wFBMode], a
;>     DrawFrameBlock(block)
	call DrawFrameBlock
;>     DoSpecialEffectByAnimationId()
	call DoSpecialEffectByAnimationId ; run animation-specific function (if there is one)
;>     wSubAnimCounter = wSubAnimCounter - 1 & 0xFF
	ld a, [wSubAnimCounter]
	dec a
	ld [wSubAnimCounter], a
;>     if wSubAnimCounter == 0:
;>         return
	ret z
;>     entry = wSubAnimSubEntryAddr[1] << 8 | wSubAnimSubEntryAddr[0]
	ld a, [wSubAnimSubEntryAddr + 1]
	ld h, a
	ld a, [wSubAnimSubEntryAddr]
	ld l, a
;>     step = 3
;>     if wSubAnimTransform == SUBANIMTYPE_REVERSE:  # backwards
	ld a, [wSubAnimTransform]
	cp SUBANIMTYPE_REVERSE
	ld bc, 3
	jr nz, .nextSubanimationSubentry
;>         step = -3 & 0xFFFF
	ld bc, -3
.nextSubanimationSubentry
;>     entry = entry + step & 0xFFFF
	add hl, bc
;>     wSubAnimSubEntryAddr[1], wSubAnimSubEntryAddr[0] = hi(entry), lo(entry)
	ld a, h
	ld [wSubAnimSubEntryAddr + 1], a
	ld a, l
	ld [wSubAnimSubEntryAddr], a
	jp .loop

;@ path: engine/battle/animations
;@ def AnimationCleanOAM()
;@ Clear all sprites after a frame; keeps all registers.
AnimationCleanOAM:
;> DelayFrame()                                      # (all registers are kept)
	push hl
	push de
	push bc
	push af
	call DelayFrame
;> ClearSprites()
	call ClearSprites
	pop af
	pop bc
	pop de
	pop hl
	ret

; this runs after each frame block is drawn in a subanimation
; it runs a particular special effect based on the animation ID
;@ path: engine/battle/animations
;@ def DoSpecialEffectByAnimationId()
;@ Run the extra effect of the current animation after a frame block, if AnimationIdSpecialEffects lists one; keeps
;@ hl, de and bc.
DoSpecialEffectByAnimationId:
;> wanted = wAnimationID                            # (hl, de and bc are kept)
	push hl
	push de
	push bc
	ld a, [wAnimationID]
;> _, entry, found = IsInArray(wanted, AnimationIdSpecialEffects, 3)
	ld hl, AnimationIdSpecialEffects
	ld de, 3
	call IsInArray
;> if found:
	jr nc, .done
;>     effect = mem16[entry + 1]
	inc hl
	ld a, [hli]
	ld h, [hl]
	ld l, a
;>     call(effect)
	ld de, .done
	push de
	jp hl
.done
;> return
	pop bc
	pop de
	pop hl
	ret


;@ path: engine/battle/animations
AnimationIdSpecialEffects:
	; animation id, effect routine address
	db MEGA_PUNCH
	dw AnimationFlashScreen
	db GUILLOTINE
	dw AnimationFlashScreen
	db MEGA_KICK
	dw AnimationFlashScreen
	db HEADBUTT
	dw AnimationFlashScreen
	db TAIL_WHIP
	dw TailWhipAnimationUnused
	db GROWL
	dw DoGrowlSpecialEffects
	db DISABLE
	dw AnimationFlashScreen
	db BLIZZARD
	dw DoBlizzardSpecialEffects
	db BUBBLEBEAM
	dw AnimationFlashScreen
	db HYPER_BEAM
	dw FlashScreenEveryFourFrameBlocks
	db THUNDERBOLT
	dw FlashScreenEveryEightFrameBlocks
	db REFLECT
	dw AnimationFlashScreen
	db SELFDESTRUCT
	dw DoExplodeSpecialEffects
	db SPORE
	dw AnimationFlashScreen
	db EXPLOSION
	dw DoExplodeSpecialEffects
	db ROCK_SLIDE
	dw DoRockSlideSpecialEffects
	db TRADE_BALL_DROP_ANIM
	dw TradeHidePokemon
	db TRADE_BALL_SHAKE_ANIM
	dw TradeShakePokeball
	db TRADE_BALL_TILT_ANIM
	dw TradeJumpPokeball
	db TOSS_ANIM
	dw DoBallTossSpecialEffects
	db SHAKE_ANIM
	dw DoBallShakeSpecialEffects
	db POOF_ANIM
	dw DoPoofSpecialEffects
	db GREATTOSS_ANIM
	dw DoBallTossSpecialEffects
	db ULTRATOSS_ANIM
	dw DoBallTossSpecialEffects
	db -1 ; end

;@ path: engine/battle/animations
;@ def DoBallTossSpecialEffects()
;@ During the ball toss: Master and Ultra Balls flash, the toss sound starts with the subanimation, a trainer's
;@ toss is one frame shorter, and the ghost Marowak dodges in the last 3 frames (its picture moves left).
DoBallTossSpecialEffects:
;> if wCurItem <= ULTRA_BALL:
	ld a, [wCurItem]
	cp ULTRA_BALL + 1 ; is it a Master Ball or Ultra Ball?
	jr nc, .skipFlashingEffect
.flashingEffect ; do a flashing effect if it's Master Ball or Ultra Ball
;>     rOBP0 = rOBP0 ^ 0x3C  # colors 1 and 2 swapped
	ldh a, [rOBP0]
	xor %00111100 ; complement colors 1 and 2
	ldh [rOBP0], a
.skipFlashingEffect
;> if wSubAnimCounter == 11:
	ld a, [wSubAnimCounter]
	cp 11 ; is it the beginning of the subanimation?
	jr nz, .skipPlayingSound
; if it is the beginning of the subanimation, play a sound
;>     PlaySound(SFX_BALL_TOSS)
	ld a, SFX_BALL_TOSS
	call PlaySound
.skipPlayingSound
;> if wIsInBattle == TRAINER_BATTLE:                 # one frame shorter
;>@t1     if wSubAnimCounter == 3:
;>@t2         wSubAnimCounter = 2
;>@t3     return
	ld a, [wIsInBattle]
	cp TRAINER_BATTLE
	jr z, .isTrainerBattle
;> if wPokeBallAnimData != 0x10:                     # the ghost Marowak dodges
;>     return
	ld a, [wPokeBallAnimData]
	cp $10 ; is the enemy pokemon the Ghost Marowak?
	ret nz
; if the enemy pokemon is the Ghost Marowak, make it dodge during the last 3 frames
;> n = wSubAnimCounter
	ld a, [wSubAnimCounter]
;> if n != 3 and n != 2:                             # (the last 3 frames)
	cp 3
	jr z, .moveGhostMarowakLeft
	cp 2
	jr z, .moveGhostMarowakLeft
;>     if n != 1:
;>         return
	cp 1
	ret nz
.moveGhostMarowakLeft
;> pos = coord(17, 0)
	ld hl, (0) * SCREEN_WIDTH + (17) + wTileMap
;>@rw for _ in range(7):
	ld de, 20
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
.loop
;>     AnimCopyRowRight(pos, 7)
	push hl
	push bc
	call AnimCopyRowRight ; move row of tiles left
	pop bc
	pop hl
;>     pos += SCREEN_WIDTH
	add hl, de
;=@rw
	dec b
	jr nz, .loop
;> rAUD1SWEEP = 0x08
	ld a, %00001000
	ldh [rAUD1SWEEP], a ; Channel 1 sweep register
	ret
.isTrainerBattle ; if it's a trainer battle, shorten the animation by one frame
;=@t1
	ld a, [wSubAnimCounter]
	cp 3
	ret nz
;=@t2
	dec a
	ld [wSubAnimCounter], a
;=@t3
	ret

;@ path: engine/battle/animations
;@ def DoBallShakeSpecialEffects()
;@ The ball shaking: a tink and a pause at the start of each shake, and the subanimation starts over until
;@ wNumShakes runs out.
DoBallShakeSpecialEffects:
;> if wSubAnimCounter == 4:
	ld a, [wSubAnimCounter]
	cp 4 ; is it the beginning of a shake?
	jr nz, .skipPlayingSound
; if it is the beginning of a shake, play a sound and wait 2/3 of a second
;>     PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;>     DelayFrames(40)
	ld c, 40
	call DelayFrames
.skipPlayingSound
;> if wSubAnimCounter != 1:
;>     return
	ld a, [wSubAnimCounter]
	dec a
	ret nz
; if it's the end of the ball shaking subanimation, check if more shakes are left and restart the subanimation
;> wNumShakes = wNumShakes - 1 & 0xFF
	ld a, [wNumShakes] ; number of shakes
	dec a ; decrement number of shakes
	ld [wNumShakes], a
;> if wNumShakes == 0:
;>     return
	ret z
; if there are shakes left, restart the subanimation
;> entry = (wSubAnimSubEntryAddr[1] << 8 | wSubAnimSubEntryAddr[0]) - 4 * 3 & 0xFFFF  # 4 entries of 3 bytes back
	ld a, [wSubAnimSubEntryAddr]
	ld l, a
	ld a, [wSubAnimSubEntryAddr + 1]
	ld h, a
	ld de, -(4 * 3) ; 4 subentries and 3 bytes per subentry
	add hl, de
;> wSubAnimSubEntryAddr[0], wSubAnimSubEntryAddr[1] = lo(entry), hi(entry)
	ld a, l
	ld [wSubAnimSubEntryAddr], a
	ld a, h
	ld [wSubAnimSubEntryAddr + 1], a
;> wSubAnimCounter = 5
	ld a, 5 ; number of subentries in the ball shaking subanimation plus one
	ld [wSubAnimCounter], a
	ret

; plays a sound after the second frame of the poof animation
;@ path: engine/battle/animations
;@ def DoPoofSpecialEffects()
;@ The poof sound after the second frame of the poof animation.
DoPoofSpecialEffects:
;> if wSubAnimCounter == 5:
;>     PlaySound(SFX_BALL_POOF)
	ld a, [wSubAnimCounter]
	cp 5
	ret nz
	ld a, SFX_BALL_POOF
	jp PlaySound

;@ path: engine/battle/animations
;@ def DoRockSlideSpecialEffects()
;@ Rock Slide: the screen shakes both ways during frames 8-11 (counted down) and flashes at the end.
DoRockSlideSpecialEffects:
;> n = wSubAnimCounter
	ld a, [wSubAnimCounter]
;> if n >= 12:
;>     return
	cp 12
	ret nc
;> if n >= 8:                                        # frames 8-11: it shakes
;>@s1     predef(PredefShakeScreenHorizontally, bc=0x100)   # b = 1
;>@s2     predef(PredefShakeScreenVertically, bc=0x100)
	cp 8
	jr nc, .shakeScreen
;> elif n == 1:
;>     AnimationFlashScreen()
	cp 1
	jp z, AnimationFlashScreen ; if it's the end of the subanimation, flash the screen
	ret
; if the subanimation counter is between 8 and 11, shake the screen horizontally and vertically
.shakeScreen
;=@s1
	ld b, 1
	; shake horizontally
	ld a, (PredefShakeScreenHorizontallyPredef - PredefPointers) / 3
	call Predef
;=@s2
	ld b, 1
	; shake vertically
	ld a, (PredefShakeScreenVerticallyPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/battle/animations
;@ def FlashScreenEveryEightFrameBlocks()
;@ Flash the screen whenever the frame block counter is a multiple of 8.
FlashScreenEveryEightFrameBlocks:
;> if wSubAnimCounter & 7 == 0:
;>     AnimationFlashScreen()
	ld a, [wSubAnimCounter]
	and 7 ; is the subanimation counter exactly 8?
	call z, AnimationFlashScreen ; if so, flash the screen
	ret

; flashes the screen if the subanimation counter is divisible by 4
;@ path: engine/battle/animations
;@ def FlashScreenEveryFourFrameBlocks()
;@ Flash the screen whenever the frame block counter is a multiple of 4.
FlashScreenEveryFourFrameBlocks:
;> if wSubAnimCounter & 3 == 0:
;>     AnimationFlashScreen()
	ld a, [wSubAnimCounter]
	and 3
	call z, AnimationFlashScreen
	ret

; used for Explosion and Selfdestruct
;@ path: engine/battle/animations
;@ def DoExplodeSpecialEffects()
;@ Explosion and Selfdestruct: the screen flashes every 4 frame blocks, and at the end the user's picture vanishes.
DoExplodeSpecialEffects:
;> if wSubAnimCounter != 1:
;>     return FlashScreenEveryFourFrameBlocks()
	ld a, [wSubAnimCounter]
	cp 1 ; is it the end of the subanimation?
	jr nz, FlashScreenEveryFourFrameBlocks
; if it's the end of the subanimation, make the attacking pokemon disappear
;> AnimationHideMonPic()
	ld hl, (5) * SCREEN_WIDTH + (1) + wTileMap
	jp AnimationHideMonPic ; make pokemon disappear

; flashes the screen when subanimation counter is 1 modulo 4
;@ path: engine/battle/animations
;@ def DoBlizzardSpecialEffects()
;@ Blizzard: the screen flashes at frame blocks 13, 9, 5 and 1 (counted down).
DoBlizzardSpecialEffects:
;> n = wSubAnimCounter
	ld a, [wSubAnimCounter]
;> if n == 13:
;>     return AnimationFlashScreen()
	cp 13
	jp z, AnimationFlashScreen
;> if n == 9:
;>     return AnimationFlashScreen()
	cp 9
	jp z, AnimationFlashScreen
;> if n == 5:
;>     return AnimationFlashScreen()
	cp 5
	jp z, AnimationFlashScreen
;> if n == 1:
;>     return AnimationFlashScreen()
	cp 1
	jp z, AnimationFlashScreen
	ret

; flashes the screen at 3 points in the subanimation
; unused
;@ path: engine/battle/animations
;@ def FlashScreenUnused()
;@ The screen flashes at frame blocks 14, 9 and 2 (counted down); not used.
FlashScreenUnused:
;> n = wSubAnimCounter
	ld a, [wSubAnimCounter]
;> if n == 14:
;>     return AnimationFlashScreen()
	cp 14
	jp z, AnimationFlashScreen
;> if n == 9:
;>     return AnimationFlashScreen()
	cp 9
	jp z, AnimationFlashScreen
;> if n == 2:
;>     return AnimationFlashScreen()
	cp 2
	jp z, AnimationFlashScreen
	ret

; function to make the pokemon disappear at the beginning of the animation
;@ path: engine/battle/animations
;@ def TradeHidePokemon()
;@ The trade animation: the mon's picture vanishes at the start (frame block 6).
TradeHidePokemon:
;> if wSubAnimCounter == 6:
;>     ClearMonPicFromTileMap(2 * SCREEN_WIDTH + 7)
	ld a, [wSubAnimCounter]
	cp 6
	ret nz
	ld a, 2 * SCREEN_WIDTH + 7
	jp ClearMonPicFromTileMap ; make pokemon disappear

; function to make a shaking pokeball jump up at the end of the animation
;@ path: engine/battle/animations
;@ def TradeShakePokeball()
;@ The trade animation: at the end of the shaking the ball (the first 4 sprites) jumps up by the distances in
;@ BallMoveDistances1, one step every 3 frames; then the sprites are cleared and the trade machine sound plays.
TradeShakePokeball:
;> if wSubAnimCounter != 1:
;>     return
	ld a, [wSubAnimCounter]
	cp 1
	ret nz
; if it's the end of the animation, make the ball jump up
;> distances = BallMoveDistances1
	ld de, BallMoveDistances1
.loop
;> while mem[distances] != 0xFF:
;>     for i in range(4):
	ld hl, wShadowOAM
	ld bc, 4
.innerLoop
	ld a, [de]
	cp $ff
	jr z, .done
;>         mem[wShadowOAM + 4 * i] = mem[wShadowOAM + 4 * i] + mem[distances] & 0xFF  # the sprites' Y
	add [hl] ; add to Y value of OAM entry
	ld [hl], a
	add hl, bc
	ld a, l
	cp 4 * 4 ; there are 4 entries, each 4 bytes
	jr nz, .innerLoop
;>     distances += 1
	inc de
;>     Delay3()
	push bc
	call Delay3
	pop bc
	jr .loop
.done
;> AnimationCleanOAM()
	call AnimationCleanOAM
;> PlaySound(SFX_TRADE_MACHINE)
	ld a, SFX_TRADE_MACHINE
	jp PlaySound

;@ path: engine/battle/animations
BallMoveDistances1:
	db -12, -12, -8
	db -1 ; end

; function to make the pokeball jump up
;@ path: engine/battle/animations
;@ def TradeJumpPokeball()
;@ The trade animation: the ball bounces along by the distances in BallMoveDistances2 while the background scrolls
;@ left 8 pixels every 5 frames, with a sound at each bounce; then the screen is cleared.
TradeJumpPokeball:
;> distances = BallMoveDistances2
	ld de, BallMoveDistances2
.loop
;> while mem[distances] != 0xFF:
;>     for i in range(4):
	ld hl, wShadowOAM
	ld bc, 4
.innerLoop
	ld a, [de]
	cp $ff
	jp z, ClearScreen
;>         mem[wShadowOAM + 4 * i] = mem[wShadowOAM + 4 * i] + mem[distances] & 0xFF
	add [hl]
	ld [hl], a
	add hl, bc
	ld a, l
	cp 4 * 4 ; there are 4 entries, each 4 bytes
	jr nz, .innerLoop
;>     distances += 1
	inc de
;>     if mem[distances] in (12, 0xFF):
	push de
	ld a, [de]
	cp 12
	jr z, .playSound
	cp $ff
	jr nz, .skipPlayingSound
.playSound ; play sound if next move distance is 12 or this is the last one
;>         PlaySound(SFX_SWAP)
	ld a, SFX_SWAP
	call PlaySound
.skipPlayingSound
;>     DelayFrames(5)
	push bc
	ld c, 5
	call DelayFrames
	pop bc
;>     hSCX = hSCX - 8 & 0xFF
	ldh a, [hSCX] ; background scroll X
	sub 8 ; scroll to the left
	ldh [hSCX], a
	pop de
	jr .loop
;> ClearScreen()

;@ path: engine/battle/animations
BallMoveDistances2:
	db 11, 12, -12, -7, 7, 12, -8, 8
	db -1 ; end

; this function copies the current musical note graphic
; so that there are two musical notes flying towards the defending pokemon
;@ path: engine/battle/animations
;@ def DoGrowlSpecialEffects()
;@ Growl: the note sprites are copied to a second set of 4 sprites; the sprites are cleared at the end.
DoGrowlSpecialEffects:
;> CopyData(wShadowOAM + 0, wShadowOAMSprite04, OBJ_SIZE * 4)   # the notes twice
	ld hl, wShadowOAM
	ld de, wShadowOAMSprite04
	ld bc, OBJ_SIZE * 4
	call CopyData ; copy the musical note graphic
;> if wSubAnimCounter == 1:                          # the end
;>     AnimationCleanOAM()
	ld a, [wSubAnimCounter]
	dec a
	call z, AnimationCleanOAM ; clean up at the end of the subanimation
	ret

; this is associated with Tail Whip, but Tail Whip doesn't use any subanimations
;@ path: engine/battle/animations
;@ def TailWhipAnimationUnused()
;@ Meant for Tail Whip (which has no subanimations): ends the subanimation and waits 20 frames.
TailWhipAnimationUnused:
;> wSubAnimCounter = 1
;> DelayFrames(20)
	ld a, 1
	ld [wSubAnimCounter], a
	ld c, 20
	jp DelayFrames


