;@ path: engine/battle/animations
;@ def AnimationDelay10()
;@ Wait 10 frames.
AnimationDelay10:
;> DelayFrames(10)
	ld c, 10
	jp DelayFrames

; calls a function with the turn flipped from player to enemy or vice versa
; input - hl - address of function to call
;@ path: engine/battle/animations
;@ def CallWithTurnFlipped(func: hl)
;@ Run func as if it were the other side's turn.
;@ test: skip jumps to the routine whose address is in hl
CallWithTurnFlipped:
;> saved = hWhoseTurn
	ldh a, [hWhoseTurn]
	push af
;> hWhoseTurn = saved ^ 1
	xor 1
	ldh [hWhoseTurn], a
;> call(func)
	ld de, .returnAddress
	push de
	jp hl
.returnAddress
;> hWhoseTurn = saved
	pop af
	ldh [hWhoseTurn], a
	ret

; flashes the screen for an extended period (48 frames)
;@ path: engine/battle/animations
;@ def AnimationFlashScreenLong()
;@ Flash the screen for a long time: three times through FlashScreenLongMonochrome (or FlashScreenLongSGB).
AnimationFlashScreenLong:
;> wFlashScreenLongCounter = 3
	ld a, 3 ; cycle through the palettes 3 times
	ld [wFlashScreenLongCounter], a
;> palettes = FlashScreenLongSGB if wOnSGB else FlashScreenLongMonochrome
	ld a, [wOnSGB] ; running on SGB?
	and a
	ld hl, FlashScreenLongMonochrome
	jr z, .loop
	ld hl, FlashScreenLongSGB
.loop
;> while True:
;>     p = palettes
	push hl
.innerLoop
;>     while mem[p] != 1:
	ld a, [hli]
	cp 1
	jr z, .endOfPalettes
;>         rBGP = mem[p]
;>         p += 1
	ldh [rBGP], a
;>         FlashScreenLongDelay()
	call FlashScreenLongDelay
	jr .innerLoop
.endOfPalettes
;>     wFlashScreenLongCounter = wFlashScreenLongCounter - 1 & 0xFF
	ld a, [wFlashScreenLongCounter]
	dec a
	ld [wFlashScreenLongCounter], a
;>     if wFlashScreenLongCounter == 0:
;>         return
	pop hl
	jr nz, .loop
	ret

; BG palettes
;@ path: engine/battle/animations
FlashScreenLongMonochrome:
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (1)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (2)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (3)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (2)
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (1)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)
	db ((2) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((1) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((0) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((1) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((2) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)
	db 1 ; end

; BG palettes
;@ path: engine/battle/animations
FlashScreenLongSGB:
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (3)
	db ((3) << 6) | ((3) << 4) | ((3) << 2) | (0)
	db ((3) << 6) | ((3) << 4) | ((2) << 2) | (0)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)
	db ((2) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((1) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((0) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((1) << 6) | ((0) << 4) | ((0) << 2) | (0)
	db ((2) << 6) | ((1) << 4) | ((0) << 2) | (0)
	db ((3) << 6) | ((2) << 4) | ((1) << 2) | (0)
	db 1 ; end

; causes a delay of 2 frames for the first cycle
; causes a delay of 1 frame for the second and third cycles
;@ path: engine/battle/animations
;@ def FlashScreenLongDelay()
;@ The pause after each palette of the long flash: 2 frames in the first round, 1 in the others.
FlashScreenLongDelay:
;> counter = wFlashScreenLongCounter
	ld a, [wFlashScreenLongCounter]
;> frames = 4
;> if counter != 4:                                  # (never 4: it starts at 3)
	cp 4 ; never true since [wFlashScreenLongCounter] starts at 3
	ld c, 4
	jr z, .delayFrames
;>     frames = 2
;>     if counter != 3:
	cp 3
	ld c, 2
	jr z, .delayFrames
;>         frames = 1
	cp 2 ; nothing is done with this
	ld c, 1
.delayFrames
;> DelayFrames(frames)
	jp DelayFrames

;@ path: engine/battle/animations
;@ def AnimationFlashScreen()
;@ Flash the screen: inverted for 2 frames, white for 2, then the palette it had.
AnimationFlashScreen:
;> saved = rBGP
	ldh a, [rBGP]
	push af ; save initial palette
;> rBGP = 0b00011011
	ld a, %00011011 ; 0, 1, 2, 3 (inverted colors)
	ldh [rBGP], a
;> DelayFrames(2)
	ld c, 2
	call DelayFrames
;> rBGP = 0
	xor a ; white out background
	ldh [rBGP], a
;> DelayFrames(2)
	ld c, 2
	call DelayFrames
;> rBGP = saved
	pop af
	ldh [rBGP], a ; restore initial palette
	ret

;@ path: engine/battle/animations
;@ def AnimationDarkScreenPalette()
;@ A dark background palette.
AnimationDarkScreenPalette:
; Changes the screen's palette to a dark palette.
;> SetAnimationBGPalette(0x6F, 0x6F)
	ld bc, (($6f) & $ff) << 8 + (($6f) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationDarkenMonPalette()
;@ A darker palette for the mon's picture.
AnimationDarkenMonPalette:
; Darkens the mon sprite's palette.
;> SetAnimationBGPalette(0xF9, 0xF4)
	ld bc, (($f9) & $ff) << 8 + (($f4) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationUnusedPalette1()
;@ An unused background palette.
AnimationUnusedPalette1:
;> SetAnimationBGPalette(0xFE, 0xF8)
	ld bc, (($fe) & $ff) << 8 + (($f8) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationUnusedPalette2()
;@ An unused background palette (all black).
AnimationUnusedPalette2:
;> SetAnimationBGPalette(0xFF, 0xFF)
	ld bc, (($ff) & $ff) << 8 + (($ff) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationResetScreenPalette()
;@ The normal background palette again.
AnimationResetScreenPalette:
; Restores the screen's palette to the normal palette.
;> SetAnimationBGPalette(0xE4, 0xE4)
	ld bc, (($e4) & $ff) << 8 + (($e4) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationUnusedPalette3()
;@ An unused background palette (all white).
AnimationUnusedPalette3:
;> SetAnimationBGPalette(0x00, 0x00)
	ld bc, (($00) & $ff) << 8 + (($00) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationLightScreenPalette()
;@ A light background palette.
AnimationLightScreenPalette:
; Changes the screen to use a palette with light colors.
;> SetAnimationBGPalette(0x90, 0x90)
	ld bc, (($90) & $ff) << 8 + (($90) & $ff)
	jr SetAnimationBGPalette

;@ path: engine/battle/animations
;@ def AnimationUnusedPalette4()
;@ An unused background palette.
AnimationUnusedPalette4:
;> SetAnimationBGPalette(0x40, 0x40)
	ld bc, (($40) & $ff) << 8 + (($40) & $ff)

;@ path: engine/battle/animations
;@ def SetAnimationBGPalette(palette: b, sgb_palette: c)
;@ Set the background palette - the second one on the Super Game Boy.
SetAnimationBGPalette:
;> sgb = wOnSGB
	ld a, [wOnSGB]
	and a
;> value = palette
;> if sgb:
	ld a, b
	jr z, .next
;>     value = sgb_palette
	ld a, c
.next
;> rBGP = value
	ldh [rBGP], a
	ret

;@ path: engine/battle/animations
;@ def AnimationUnusedShakeScreen()
;@ Shake the screen up and down for a while; not used.
AnimationUnusedShakeScreen: ; unreferenced
; Shakes the screen for a while.
;> AnimationShakeScreenVertically(5)
	ld b, $5

;@ path: engine/battle/animations
;@ def AnimationShakeScreenVertically(times: b)
;@ Shake the screen up and down.
AnimationShakeScreenVertically:
;> predef(PredefShakeScreenVertically, bc=times << 8)
	ld a, (PredefShakeScreenVerticallyPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/battle/animations
;@ def AnimationShakeScreen()
;@ Shake the screen sideways for a while (Earthquake, Fissure...).
AnimationShakeScreen:
; Shakes the screen for a while. Used in Earthquake/Fissure/etc. animations.
;> AnimationShakeScreenHorizontallyFast(8)
	ld b, $8

;@ path: engine/battle/animations
;@ def AnimationShakeScreenHorizontallyFast(times: b)
;@ Shake the screen sideways.
AnimationShakeScreenHorizontallyFast:
;> predef(PredefShakeScreenHorizontally, bc=times << 8)
	ld a, (PredefShakeScreenHorizontallyPredef - PredefPointers) / 3
	jp Predef

;@ path: engine/battle/animations
;@ def AnimationWaterDropletsEverywhere()
;@ Surf, Mist, Toxic: water droplets all over the screen, drifting along for 32 rounds.
AnimationWaterDropletsEverywhere:
; Draws water droplets all over the screen and makes them
; scroll. It's hard to describe, but it's the main animation
; in Surf/Mist/Toxic.
;> wWhichBattleAnimTileset = 0
	xor a
	ld [wWhichBattleAnimTileset], a
;> LoadMoveAnimationTiles()
	call LoadMoveAnimationTiles
;> wBaseCoordX = -16 & 0xFF
	ld d, 32
	ld a, -16
	ld [wBaseCoordX], a
;> wDropletTile = 0x71
	ld a, $71
	ld [wDropletTile], a
;> for _ in range(32):
.loop
;>     wBaseCoordY = 16
	ld a, 16
	ld [wBaseCoordY], a
;>     wUnusedWaterDropletsByte = 0
	ld a, 0
	ld [wUnusedWaterDropletsByte], a
;>     _AnimationWaterDroplets()
	call _AnimationWaterDroplets
;>     wBaseCoordY = 24
	ld a, 24
	ld [wBaseCoordY], a
;>     wUnusedWaterDropletsByte = 32
	ld a, 32
	ld [wUnusedWaterDropletsByte], a
;>     _AnimationWaterDroplets()
	call _AnimationWaterDroplets
	dec d
	jr nz, .loop
	ret

;@ path: engine/battle/animations
;@ def _AnimationWaterDroplets()
;@ One screen of droplets: rows 16 pixels apart from wBaseCoordY down to 112, a droplet every 27 pixels; then the
;@ frame is shown and cleared.
_AnimationWaterDroplets:
;> oam = wShadowOAM + 0
	ld hl, wShadowOAM
.loop
;> while True:
;>     mem[oam] = wBaseCoordY
	ld a, [wBaseCoordY]
	ld [hli], a ; Y
;>     wBaseCoordX = wBaseCoordX + 27 & 0xFF
	ld a, [wBaseCoordX]
	add 27
	ld [wBaseCoordX], a
;>     mem[oam + 1] = wBaseCoordX
	ld [hli], a ; X
;>     mem[oam + 2] = wDropletTile
	ld a, [wDropletTile]
	ld [hli], a ; tile
;>     mem[oam + 3] = 0
;>     oam += 4
	xor a
	ld [hli], a ; attribute
;>     if wBaseCoordX < 144:
;>         continue
	ld a, [wBaseCoordX]
	cp 144
	jr c, .loop
;>     wBaseCoordX = wBaseCoordX - 168 & 0xFF
	sub 168
	ld [wBaseCoordX], a
;>     wBaseCoordY = wBaseCoordY + 16 & 0xFF
	ld a, [wBaseCoordY]
	add 16
	ld [wBaseCoordY], a
;>     if wBaseCoordY >= 112:
;>         break
	cp 112
	jr c, .loop
;> AnimationCleanOAM()
	call AnimationCleanOAM
;> DelayFrame()
	jp DelayFrame

;@ path: engine/battle/animations
;@ def AnimationSlideMonUp()
;@ Slide the attacker's picture up by one tile, seven times.
AnimationSlideMonUp:
; Slides the mon's sprite upwards.
;> n = 7
	ld c, 7
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> src, dest, tile = coord(1, 6), coord(1, 5), 0x30
;> if not player:
	ld hl, (6) * SCREEN_WIDTH + (1) + wTileMap
	ld de, (5) * SCREEN_WIDTH + (1) + wTileMap
	ld a, $30
	jr z, .next
;>     src, dest, tile = coord(12, 1), coord(12, 0), 0xFF
	ld hl, (1) * SCREEN_WIDTH + (12) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (12) + wTileMap
	ld a, $ff
.next
;> wSlideMonUpBottomRowLeftTile = tile
	ld [wSlideMonUpBottomRowLeftTile], a
;> _AnimationSlideMonUp(dest, src, n)
	jp _AnimationSlideMonUp

;@ path: engine/battle/animations
;@ def AnimationSlideMonDown()
;@ Slide the attacker's picture down out of its box, one row per step.
AnimationSlideMonDown:
; Slides the mon's sprite down out of the screen.
;> ids, rows, cols = GetTileIDList(TILEMAP_MON_PIC)
	xor a ; TILEMAP_MON_PIC
	call GetTileIDList
.loop
;> while True:
;>     CopyPicTiles(GetMonSpriteTileMapPointerFromRowCount(rows), ids, rows, cols)
	call GetMonSpriteTileMapPointerFromRowCount
	push bc
	push de
	call CopyPicTiles
;>     Delay3()
	call Delay3
;>     AnimationHideMonPic()
	call AnimationHideMonPic
;>     rows = rows - 1 & 0xFF
	pop de
	pop bc
	dec b
;>     if rows == 0:
;>         return
	jr nz, .loop
	ret

;@ path: engine/battle/animations
;@ def AnimationSlideMonOff()
;@ Slide the attacker's picture sideways off the screen.
AnimationSlideMonOff:
; Slides the mon's sprite off the screen horizontally.
;> wSlideMonDelay = 3
;> _AnimationSlideMonOff(8)
	ld e, 8
	ld a, 3
	ld [wSlideMonDelay], a
	jp _AnimationSlideMonOff

;@ path: engine/battle/animations
;@ def AnimationSlideEnemyMonOff()
;@ Slide the target's picture sideways off the screen.
AnimationSlideEnemyMonOff:
; Slides the enemy mon off the screen horizontally.
;> CallWithTurnFlipped(AnimationSlideMonOff)
	ld hl, AnimationSlideMonOff
	jp CallWithTurnFlipped

;@ path: engine/battle/animations
;@ def _AnimationSlideMonUp(dest: de, src: hl, times: c)
;@ Move the picture's rows up one tile row `times` times (2 frames each); the bottom row gets the next tile numbers
;@ after wSlideMonUpBottomRowLeftTile, so a picture from further down the tiles slides in.
_AnimationSlideMonUp:
;>@sl for _ in range(times or 256):
;>     s, d = src, dest
	push de
	push hl
	push bc

; In each iteration, slide up all rows but the top one (which is overwritten).
;>@rw     for _ in range(PIC_HEIGHT - 1):
	ld b, PIC_HEIGHT - 1
.slideLoop
;>         CopyData(s, d, PIC_WIDTH)
	push bc
	push de
	push hl
	ld bc, PIC_WIDTH
	call CopyData
; Note that de and hl are popped in the same order they are pushed, swapping
; their values. When CopyData is called, hl points to a tile 1 row below
; the one de points to. To maintain this relationship, after swapping, we add 2
; rows to hl so that it is 1 row below again.
;>         s, d = d, s
	pop de
	pop hl
;>         s = s + SCREEN_WIDTH * 2 & 0xFFFF         # again one row below d
	ld bc, SCREEN_WIDTH * 2
	add hl, bc
;=@rw
	pop bc
	dec b
	jr nz, .slideLoop

; Fill in the bottom row of the mon pic with the next row's tile IDs.
;>     player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;>     row = coord(1, 11)
;>     if not player:
	ld hl, (11) * SCREEN_WIDTH + (1) + wTileMap
	jr z, .next
;>         row = coord(12, 6)
	ld hl, (6) * SCREEN_WIDTH + (12) + wTileMap
.next
;>     wSlideMonUpBottomRowLeftTile = wSlideMonUpBottomRowLeftTile + 1 & 0xFF
;>     tile = wSlideMonUpBottomRowLeftTile
	ld a, [wSlideMonUpBottomRowLeftTile]
	inc a
	ld [wSlideMonUpBottomRowLeftTile], a
;>@fb     for i in range(PIC_WIDTH):                    # the bottom row: the next tiles
	ld c, PIC_WIDTH
.fillBottomRowLoop
;>         mem[row + i] = tile
	ld [hli], a
;>         tile = tile + PIC_WIDTH & 0xFF
	add PIC_WIDTH
;=@fb
	dec c
	jr nz, .fillBottomRowLoop

;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
;=@sl
	pop bc
	pop hl
	pop de
	dec c
	jr nz, _AnimationSlideMonUp
	ret

;@ path: engine/battle/animations
;@ def ShakeEnemyHUD_WritePlayerMonPicOAM()
;@ Copy the player's mon's picture into sprites (7 columns of 5 tiles, from (16, 56) on), so it can stay put while
;@ the background shakes.
ShakeEnemyHUD_WritePlayerMonPicOAM:
; Writes the OAM entries for a copy of the player mon's pic in OAM.
; The top 5 rows are reproduced in OAM, although only 2 are actually needed.
;> wBaseCoordX = 0x10
	ld a, $10
	ld [wBaseCoordX], a
;> wBaseCoordY = 0x30
	ld a, $30
	ld [wBaseCoordY], a
;> oam, tile = wShadowOAM + 0, 0
	ld hl, wShadowOAM
	ld d, 0
;> for column in range(7):
	ld c, 7
.loop
;>     y = wBaseCoordY
	ld a, [wBaseCoordY]
	ld e, a
;>     for _ in range(5):
	ld b, 5
.innerLoop
;>         oam, y = BattleAnimWriteOAMEntry(oam, y, tile)
	call BattleAnimWriteOAMEntry
;>         tile += 1
	inc d
	dec b
	jr nz, .innerLoop
;>     if column == 6:
;>         return
	dec c
	ret z
;>     tile += 2
	inc d
	inc d
;>     wBaseCoordX = wBaseCoordX + 8 & 0xFF
	ld a, [wBaseCoordX]
	add 8
	ld [wBaseCoordX], a
	jr .loop

;@ path: engine/battle/animations
;@ def BattleAnimWriteOAMEntry(oam: hl, y: e, tile: d) -> (hl, e)
;@ One sprite 8 pixels below y, at x = wBaseCoordX; returns the next OAM entry and the new y.
;@ test: oam = rand_ram(4)
BattleAnimWriteOAMEntry:
; Y coordinate = e (increased by 8 each call, before the write to OAM)
; X coordinate = [wBaseCoordX]
; tile = d
; attributes = 0
;> y = y + 8 & 0xFF
	ld a, e
	add 8
	ld e, a
;> mem[oam] = y
	ld [hli], a
;> mem[oam + 1] = wBaseCoordX
	ld a, [wBaseCoordX]
	ld [hli], a
;> mem[oam + 2] = tile
	ld a, d
	ld [hli], a
;> mem[oam + 3] = 0
;> return oam + 4 & 0xFFFF, y
	xor a
	ld [hli], a
	ret

;@ path: engine/battle/animations
;@ def AdjustOAMBlockXPos(oam: de, n: c) -> hl
;@ AdjustOAMBlockXPos2 for the X bytes from de on.
;@ test: oam = rand_ram(40) + 1; n = rand(1, 8)
AdjustOAMBlockXPos:
;> return AdjustOAMBlockXPos2(oam, n)
	ld l, e
	ld h, d

;@ path: engine/battle/animations
;@ def AdjustOAMBlockXPos2(oam: hl, n: c) -> hl
;@ Move n sprites sideways by wCoordAdjustmentAmount (hl points at the first X); one that reaches x 168 is moved off
;@ the screen.
;@ test: oam = rand_ram(40) + 1; n = rand(1, 8)
AdjustOAMBlockXPos2:
;> for _ in range(n or 256):
	ld de, OBJ_SIZE
.loop
;>     x = mem[oam] + wCoordAdjustmentAmount & 0xFF
	ld a, [wCoordAdjustmentAmount]
	ld b, a
	ld a, [hl]
	add b
;>     if x >= 168:
	cp 168
	jr c, .skipPuttingEntryOffScreen
; put off-screen if X >= 168
;>         x = SCREEN_HEIGHT_PX + OAM_Y_OFS
;>         mem[oam - 1] = x
	dec hl
	ld a, SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld [hli], a
.skipPuttingEntryOffScreen
;>     mem[oam] = x
	ld [hl], a
;>     oam = oam + OBJ_SIZE & 0xFFFF
	add hl, de
	dec c
	jr nz, .loop
;> return oam
	ret

;@ path: engine/battle/animations
;@ def AdjustOAMBlockYPos(oam: de, n: c) -> hl
;@ AdjustOAMBlockYPos2 for the Y bytes from de on.
;@ test: oam = rand_ram(40) + 1; n = rand(1, 8)
AdjustOAMBlockYPos:
;> return AdjustOAMBlockYPos2(oam, n)
	ld l, e
	ld h, d

;@ path: engine/battle/animations
;@ def AdjustOAMBlockYPos2(oam: hl, n: c) -> hl
;@ Move n sprites up or down by wCoordAdjustmentAmount (hl points at the first Y). One that reaches y 112 gets y
;@ 160 - and so does the byte before it, the previous sprite's attributes.
;@ test: oam = rand_ram(40) + 1; n = rand(1, 8)
AdjustOAMBlockYPos2:
;> for _ in range(n or 256):
	ld de, OBJ_SIZE
.loop
;>     y = mem[oam] + wCoordAdjustmentAmount & 0xFF
	ld a, [wCoordAdjustmentAmount]
	ld b, a
	ld a, [hl]
	add b
;>     if y >= 112:
	cp 112
	jr c, .skipSettingPreviousEntrysAttribute
;>         y = 160
;>         mem[oam - 1] = y
	dec hl
	ld a, 160 ; bug, sets previous OAM entry's attribute
	ld [hli], a
.skipSettingPreviousEntrysAttribute
;>     mem[oam] = y
	ld [hl], a
;>     oam = oam + OBJ_SIZE & 0xFFFF
	add hl, de
	dec c
	jr nz, .loop
;> return oam
	ret

;@ path: engine/battle/animations
;@ def AnimationBlinkEnemyMon()
;@ The target's picture blinks.
AnimationBlinkEnemyMon:
; Make the enemy mon's sprite blink on and off for a second or two
;> CallWithTurnFlipped(AnimationBlinkMon)
	ld hl, AnimationBlinkMon
	jp CallWithTurnFlipped

;@ path: engine/battle/animations
;@ def AnimationBlinkMon()
;@ The attacker's picture blinks six times, 5 frames off and 5 on.
AnimationBlinkMon:
; Make the mon's sprite blink on and off for a second or two.
;>@bl for _ in range(6):
	push af
	ld c, 6
.loop
;>     AnimationHideMonPic()
	push bc
	call AnimationHideMonPic
;>     DelayFrames(5)
	ld c, 5
	call DelayFrames
;>     AnimationShowMonPic()
	call AnimationShowMonPic
;>     DelayFrames(5)
	ld c, 5
	call DelayFrames
;=@bl
	pop bc
	dec c
	jr nz, .loop
	pop af
	ret

;@ path: engine/battle/animations
;@ def AnimationFlashMonPic()
;@ ChangeMonPic with both mons' own species: the picture flashes off and on.
AnimationFlashMonPic:
; Flashes the mon's sprite on and off
;> wChangeMonPicPlayerTurnSpecies = mem[wBattleMonSpecies]
	ld a, [wBattleMonSpecies]
	ld [wChangeMonPicPlayerTurnSpecies], a
;> wChangeMonPicEnemyTurnSpecies = mem[wEnemyMonSpecies]
	ld a, [wEnemyMonSpecies]
	ld [wChangeMonPicEnemyTurnSpecies], a
;> ChangeMonPic()
	jp ChangeMonPic

;@ path: engine/battle/animations
;@ def AnimationFlashEnemyMonPic()
;@ The target's picture flashes off and on.
AnimationFlashEnemyMonPic:
; Flashes the enemy mon's sprite on and off
;> CallWithTurnFlipped(AnimationFlashMonPic)
	ld hl, AnimationFlashMonPic
	jp CallWithTurnFlipped

;@ path: engine/battle/animations
;@ def AnimationShowMonPic()
;@ Draw the attacker's picture in its place.
AnimationShowMonPic:
;> ids, rows, cols = GetTileIDList(TILEMAP_MON_PIC)
	xor a ; TILEMAP_MON_PIC
	call GetTileIDList
;> pos = GetMonSpriteTileMapPointerFromRowCount(rows)
	call GetMonSpriteTileMapPointerFromRowCount
;> CopyPicTiles(pos, ids, rows, cols)
	call CopyPicTiles
;> Delay3()
	jp Delay3

;@ path: engine/battle/animations
;@ def AnimationShowEnemyMonPic()
;@ Draw the target's picture in its place again (after Seismic Toss and the like).
AnimationShowEnemyMonPic:
; Shows the enemy mon's front sprite. Used in animations like Seismic Toss
; to make the mon's sprite reappear after disappears offscreen.
;> CallWithTurnFlipped(AnimationShowMonPic)
	ld hl, AnimationShowMonPic
	jp CallWithTurnFlipped

;@ path: engine/battle/animations
;@ def AnimationShakeBackAndForth()
;@ Double Team: the attacker's picture jumps between two places 2 tiles apart, 16 times; it is gone afterwards.
AnimationShakeBackAndForth:
; Shakes the mon's sprite back and forth rapidly. This is used in Double Team.
; The mon's sprite disappears after this animation.
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> left, right = coord(0, 5), coord(2, 5)
;> if not player:
	ld hl, (5) * SCREEN_WIDTH + (0) + wTileMap
	ld de, (5) * SCREEN_WIDTH + (2) + wTileMap
	jr z, .next
;>     left, right = coord(11, 0), coord(13, 0)
	ld hl, (0) * SCREEN_WIDTH + (11) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (13) + wTileMap

.next
;>@sb for _ in range(16):
	xor a ; TILEMAP_MON_PIC
	ld c, $10
.loop
;=@sb
	push af
	push bc
	push de
	push hl
;>     ids, rows, cols = GetTileIDList(TILEMAP_MON_PIC)
	push hl
	push de
	push af
	push hl
	push hl
	call GetTileIDList
;>     CopyPicTiles(left, ids, rows, cols)
	pop hl
	call CopyPicTiles
;>     Delay3()
	call Delay3
;>     ClearScreenArea(left, 9, 7)                   # 9 columns wide: both places
	pop hl
	ld bc, ((7) & $ff) << 8 + ((9) & $ff)
	call ClearScreenArea
;>     ids, rows, cols = GetTileIDList(TILEMAP_MON_PIC)
	pop af
	call GetTileIDList
;>     CopyPicTiles(right, ids, rows, cols)
	pop hl
	call CopyPicTiles
;>     Delay3()
	call Delay3
;>     ClearScreenArea(left, 9, 7)
	pop hl
	ld bc, ((7) & $ff) << 8 + ((9) & $ff)
	call ClearScreenArea
	pop hl
;=@sb
	pop de
	pop bc
	pop af
	dec c
	jr nz, .loop
	ret

;@ path: engine/battle/animations
;@ def AnimationMoveMonHorizontally()
;@ Tackle, Body Slam and many more: the attacker's picture jumps one tile towards the target for 3 frames.
AnimationMoveMonHorizontally:
; Shifts the mon's sprite horizontally to a fixed location. Used by lots of
; animations like Tackle/Body Slam.
;> AnimationHideMonPic()
	call AnimationHideMonPic
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> pos = coord(2, 5)                                 # one tile towards the target
;> if not player:
	ld hl, (5) * SCREEN_WIDTH + (2) + wTileMap
	jr z, .next
;>     pos = coord(11, 0)
	ld hl, (0) * SCREEN_WIDTH + (11) + wTileMap
.next
;> ids, rows, cols = GetTileIDList(TILEMAP_MON_PIC)
	xor a ; TILEMAP_MON_PIC
	push hl
	call GetTileIDList
	pop hl
;> CopyPicTiles(pos, ids, rows, cols)
	call CopyPicTiles
;> DelayFrames(3)
	ld c, 3
	jp DelayFrames

;@ path: engine/battle/animations
;@ def AnimationResetMonPosition()
;@ The attacker's picture back in its normal place.
AnimationResetMonPosition:
; Resets the mon's sprites to be located at the normal coordinates.
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> pos = 5 * SCREEN_WIDTH + 2
;> if not player:
	ld a, 5 * SCREEN_WIDTH + 2
	jr z, .next
;>     pos = 11
	ld a, 11
.next
;> ClearMonPicFromTileMap(pos)
	call ClearMonPicFromTileMap
;> AnimationShowMonPic()
	jp AnimationShowMonPic

;@ path: engine/battle/animations
;@ def AnimationSpiralBallsInward()
;@ Focus Energy and others: three balls spiral in onto the attacker (SpiralBallAnimationCoordinates, a step every 5
;@ frames), then the screen flashes.
AnimationSpiralBallsInward:
; Creates an effect that looks like energy balls spiralling into the
; player mon's sprite.  Used in Focus Energy, for example.
;> if hWhoseTurn == 0:
;>@p1     wSpiralBallsBaseY = 0
;>@p2     wSpiralBallsBaseX = 0
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;> else:
;>     wSpiralBallsBaseY = -40 & 0xFF
	ld a, -40
	ld [wSpiralBallsBaseY], a
;>     wSpiralBallsBaseX = 80
	ld a, 80
	ld [wSpiralBallsBaseX], a
	jr .next
.playerTurn
;=@p1
	xor a
	ld [wSpiralBallsBaseY], a
;=@p2
	ld [wSpiralBallsBaseX], a
.next
;> InitMultipleObjectsOAM(0, 3, 0x7A)
	ld d, $7a ; ball tile
	ld c, 3 ; number of balls
	xor a
	call InitMultipleObjectsOAM
;> coords = SpiralBallAnimationCoordinates
	ld hl, SpiralBallAnimationCoordinates
.loop
;>@ol while True:
;>     p, oam = coords, wShadowOAM + 0
;>@il     for _ in range(3):                            # three balls
	push hl
	ld c, 3
	ld de, wShadowOAM
.innerLoop
;>         if mem[p] == 0xFF:                        # the end of the coordinates
;>@d1             AnimationCleanOAM()
;>@d2             return AnimationFlashScreen()
	ld a, [hl]
	cp $ff
	jr z, .done
;>         mem[oam] = wSpiralBallsBaseY + mem[p] & 0xFF
	ld a, [wSpiralBallsBaseY]
	add [hl]
	ld [de], a ; Y
	inc de
	inc hl
;>         mem[oam + 1] = wSpiralBallsBaseX + mem[p + 1] & 0xFF
	ld a, [wSpiralBallsBaseX]
	add [hl]
	ld [de], a ; X
;>         p += 2
;>         oam += 4
	inc hl
	inc de
	inc de
	inc de
;=@il
	dec c
	jr nz, .innerLoop
;>     DelayFrames(5)
	ld c, 5
	call DelayFrames
;>     coords += 2
	pop hl
	inc hl
	inc hl
;=@ol
	jr .loop
.done
;=@d1
	pop hl
	call AnimationCleanOAM
;=@d2
	jp AnimationFlashScreen

;@ path: engine/battle/animations
SpiralBallAnimationCoordinates:
; y, x pairs
; This is the sequence of screen coordinates that the spiralling
; balls are positioned at.
	db $38, $28
	db $40, $18
	db $50, $10
	db $60, $18
	db $68, $28
	db $60, $38
	db $50, $40
	db $40, $38
	db $40, $28
	db $46, $1E
	db $50, $18
	db $5B, $1E
	db $60, $28
	db $5B, $32
	db $50, $38
	db $46, $32
	db $48, $28
	db $50, $20
	db $58, $28
	db $50, $30
	db $50, $28
	db -1 ; end

;@ path: engine/battle/animations
;@ def AnimationSquishMonPic()
;@ Teleport, Sky Attack: the attacker's picture is squeezed together from both sides until it is gone.
AnimationSquishMonPic:
; Squishes the mon's sprite horizontally making it
; disappear. Used by Teleport/Sky Attack animations.
;> for _ in range(4):
	ld c, 4
.loop
;>     if hWhoseTurn:
	push bc
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;>         left_half, right_half = coord(16, 0), coord(14, 0)
	ld hl, (0) * SCREEN_WIDTH + (16) + wTileMap
	ld de, (0) * SCREEN_WIDTH + (14) + wTileMap
	jr .next
.playerTurn
;>     else:
;>         left_half, right_half = coord(5, 5), coord(3, 5)
	ld hl, (5) * SCREEN_WIDTH + (5) + wTileMap
	ld de, (5) * SCREEN_WIDTH + (3) + wTileMap
.next
;>     wSquishMonCurrentDirection = 0
	push de
	xor a ; left
	ld [wSquishMonCurrentDirection], a
;>     _AnimationSquishMonPic(left_half)
	call _AnimationSquishMonPic
;>     wSquishMonCurrentDirection = 1
	pop hl
	ld a, 1 ; right
	ld [wSquishMonCurrentDirection], a
;>     _AnimationSquishMonPic(right_half)
	call _AnimationSquishMonPic
	pop bc
	dec c
	jr nz, .loop
;> AnimationHideMonPic()
	call AnimationHideMonPic
;> DelayFrame()
	ld c, 2
	jp DelayFrame

;@ path: engine/battle/animations
;@ def _AnimationSquishMonPic(pos: hl)
;@ Move 3 tiles of each of the picture's 7 rows one tile towards the middle (left for direction 0, else right),
;@ blanking the tile they leave.
_AnimationSquishMonPic:
;> for _ in range(7):
	ld c, 7
.loop
;>     if wSquishMonCurrentDirection == 0:
	push bc
	push hl
	ld c, 3
	ld a, [wSquishMonCurrentDirection]
	cp 0
	jr nz, .right
;>         end = AnimCopyRowLeft(pos, 3) - 1
	call AnimCopyRowLeft
	dec hl
	jr .next
.right
;>     else:
;>         end = AnimCopyRowRight(pos, 3) + 1
	call AnimCopyRowRight
	inc hl
.next
;>     mem[end & 0xFFFF] = 0x7F  # ' '
	ld [hl], ' '
;>     pos += SCREEN_WIDTH
	pop hl
	ld de, SCREEN_WIDTH
	add hl, de
	pop bc
	dec c
	jr nz, .loop
;> Delay3()
	jp Delay3

;@ path: engine/battle/animations
;@ def AnimationShootBallsUpward()
;@ Teleport, Sky Attack: a pillar of energy balls rises from the attacker.
AnimationShootBallsUpward:
; Shoots one pillar of "energy" balls upwards. Used in Teleport/Sky Attack
; animations.
;> if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;>     wBaseCoordY = 0
;>     wBaseCoordX = 16 * 8
	ld bc, ((0) & $ff) << 8 + ((16 * 8) & $ff)
	jr .next
.playerTurn
;> else:
;>     wBaseCoordY = 6 * 8
;>     wBaseCoordX = 5 * 8
	ld bc, ((6 * 8) & $ff) << 8 + ((5 * 8) & $ff)
.next
	ld a, b
	ld [wBaseCoordY], a
	ld a, c
	ld [wBaseCoordX], a
;> _AnimationShootBallsUpward(5, 1)
	ld bc, ((5) & $ff) << 8 + ((1) & $ff)
	call _AnimationShootBallsUpward
;> AnimationCleanOAM()
	jp AnimationCleanOAM

;@ path: engine/battle/animations
;@ def _AnimationShootBallsUpward(balls: b, delay: c)
;@ A column of balls below (wBaseCoordX, wBaseCoordY) moves up 4 pixels every `delay` frames; each ball vanishes
;@ when it reaches the top.
_AnimationShootBallsUpward:
;> wWhichBattleAnimTileset = 0
	push bc
	xor a
	ld [wWhichBattleAnimTileset], a
;> LoadMoveAnimationTiles()
	call LoadMoveAnimationTiles
;> oam, y = wShadowOAM + 0, wBaseCoordY
	pop bc
	ld d, $7a ; ball tile
	ld hl, wShadowOAM
	push bc
	ld a, [wBaseCoordY]
	ld e, a
.initOAMLoop
;>@io for _ in range(balls or 256):
;>     oam, y = BattleAnimWriteOAMEntry(oam, y, 0x7A)
	call BattleAnimWriteOAMEntry
;=@io
	dec b
	jr nz, .initOAMLoop
;> DelayFrame()
	call DelayFrame
;> wNumShootingBalls = balls
	pop bc
	ld a, b
	ld [wNumShootingBalls], a
.loop
;> while True:
;>     oam = wShadowOAM + 0
	push bc
	ld hl, wShadowOAM
.innerLoop
;>@bl     for _ in range(balls or 256):
;>         top = wBaseCoordY + 8 & 0xFF
	ld a, [wBaseCoordY]
	add 8
	ld e, a
;>         if mem[oam] == top:                       # at the top it vanishes
;>@r1             mem[oam] = 0
;>@r2             wNumShootingBalls = wNumShootingBalls - 1 & 0xFF
	ld a, [hl]
	cp e ; has the ball reached the top?
	jr z, .reachedTop
;>         else:
;>             mem[oam] = mem[oam] - 4 & 0xFF        # 4 pixels up
	add -4 ; ball hasn't reached the top. move it up 4 pixels
	ld [hl], a
	jr .next
.reachedTop
; remove the ball once it has reached the top
;=@r1
	ld [hl], 0 ; put it off-screen
;=@r2
	ld a, [wNumShootingBalls]
	dec a
	ld [wNumShootingBalls], a
.next
;>         oam += OBJ_SIZE
	ld de, OBJ_SIZE
	add hl, de ; next OAM entry
;=@bl
	dec b
	jr nz, .innerLoop
;>     DelayFrames(delay)
	call DelayFrames
;>     if wNumShootingBalls == 0:
;>         return
	pop bc
	ld a, [wNumShootingBalls]
	and a
	jr nz, .loop
	ret

;@ path: engine/battle/animations
;@ def AnimationShootManyBallsUpward()
;@ Several pillars of energy balls rise, at the x coordinates of UpwardBallsAnimXCoordinatesPlayerTurn (or
;@ ...EnemyTurn).
AnimationShootManyBallsUpward:
; Shoots several pillars of "energy" balls upward.
;> if hWhoseTurn == 0:
;>     xs, y = UpwardBallsAnimXCoordinatesPlayerTurn, 0x50
	ldh a, [hWhoseTurn]
	and a
	ld hl, UpwardBallsAnimXCoordinatesPlayerTurn
	ld a, $50 ; y coordinate for "energy" ball pillar
	jr z, .player
;> else:
;>     xs, y = UpwardBallsAnimXCoordinatesEnemyTurn, 0x28
	ld hl, UpwardBallsAnimXCoordinatesEnemyTurn
	ld a, $28 ; y coordinate for "energy" ball pillar
.player
;> wSavedY = y
	ld [wSavedY], a
.loop
;> while True:
;>     wBaseCoordY = wSavedY
	ld a, [wSavedY]
	ld [wBaseCoordY], a
;>     x = mem[xs]
;>     xs += 1
	ld a, [hli]
;>     if x == 0xFF:
;>         return AnimationCleanOAM()
	cp $ff
	jp z, AnimationCleanOAM
;>     wBaseCoordX = x
	ld [wBaseCoordX], a
;>     _AnimationShootBallsUpward(4, 1)
	ld bc, ((4) & $ff) << 8 + ((1) & $ff)
	push hl
	call _AnimationShootBallsUpward
	pop hl
	jr .loop

;@ path: engine/battle/animations
UpwardBallsAnimXCoordinatesPlayerTurn:
; List of x coordinates for each pillar of "energy" balls in the
; AnimationShootManyBallsUpward animation. It's unused in the game.
	db $10, $40, $28, $18, $38, $30
	db -1 ; end

;@ path: engine/battle/animations
UpwardBallsAnimXCoordinatesEnemyTurn:
; List of x coordinates for each pillar of "energy" balls in the
; AnimationShootManyBallsUpward animation. It's unused in the game.
	db $60, $90, $78, $68, $88, $80
	db -1 ; end

;@ path: engine/battle/animations
;@ def AnimationMinimizeMon()
;@ Minimize: the attacker's picture becomes a small black blob (MinimizedMonSprite).
AnimationMinimizeMon:
; Changes the mon's sprite to a mini black sprite. Used by the
; Minimize animation.
;> FillMemory(wTempPic + 0, PIC_SIZE * TILE_SIZE, 0)
	ld hl, wTempPic
	push hl
	xor a
	ld bc, PIC_SIZE * TILE_SIZE
	call FillMemory
;> dest = wTempPic + (PIC_WIDTH * 3 + 4) * TILE_SIZE + TILE_SIZE // 4
	pop hl
	ld de, (PIC_WIDTH * 3 + 4) * TILE_SIZE + TILE_SIZE / 4
	add hl, de
;> for i in range(MinimizedMonSpriteEnd - MinimizedMonSprite):
	ld de, MinimizedMonSprite
	ld c, MinimizedMonSpriteEnd - MinimizedMonSprite
.loop
;>     mem[dest] = mem[MinimizedMonSprite + i]  # both bitplanes: black
	ld a, [de]
	ld [hli], a
;>     mem[dest + 1] = mem[MinimizedMonSprite + i]
;>     dest += 2
	ld [hli], a
	inc de
	dec c
	jr nz, .loop
;> CopyTempPicToMonPic()
	call CopyTempPicToMonPic
;> Delay3()
	call Delay3
;> AnimationShowMonPic()
	jp AnimationShowMonPic

;@ path: engine/battle/animations
MinimizedMonSprite:
; 8x5 partial tile graphic
pusho b.X ; . = 0, X = 1
	db %...XX...
	db %..XXXX..
	db %.XXXXXX.
	db %..XXXX..
	db %..X..X..
popo
;@ path: engine/battle/animations
MinimizedMonSpriteEnd:

;@ path: engine/battle/animations
;@ def AnimationSlideMonDownAndHide()
;@ Acid Armor: the attacker's picture sinks in two steps and is gone.
AnimationSlideMonDownAndHide:
; Slides the mon's sprite down and disappears. Used in Acid Armor.
;> kind = TILEMAP_SLIDE_DOWN_MON_PIC_7X5
	ld a, TILEMAP_SLIDE_DOWN_MON_PIC_7X5
;> for _ in range(2):
	ld c, 2
.loop
;>     AnimationHideMonPic()
	push bc
	push af
	call AnimationHideMonPic
;>     ids, rows, cols = GetTileIDList(kind)
	pop af
	push af
	call GetTileIDList
;>     CopyPicTiles(GetMonSpriteTileMapPointerFromRowCount(rows), ids, rows, cols)
	call GetMonSpriteTileMapPointerFromRowCount
	call CopyPicTiles
;>     DelayFrames(8)
	ld c, 8
	call DelayFrames
;>     kind += 1
	pop af
	inc a
	pop bc
	dec c
	jr nz, .loop
;> AnimationHideMonPic()
	call AnimationHideMonPic
;> FillMemory(wTempPic + 0, PIC_SIZE * TILE_SIZE, 0)
	ld hl, wTempPic
	ld bc, PIC_SIZE * TILE_SIZE
	xor a
	call FillMemory
;> CopyTempPicToMonPic()
	jp CopyTempPicToMonPic

;@ path: engine/battle/animations
;@ def _AnimationSlideMonOff(steps: e)
;@ Slide the attacker's picture `steps` tiles towards the edge of the screen, waiting wSlideMonDelay frames after
;@ each. Every tile becomes its neighbour's (the tile number plus or minus the picture's height), or blank past the
;@ edge of the picture. The player's check is one off, so the corner tile at the bottom right goes blank too.
_AnimationSlideMonOff:
; Slides the mon's sprite off the screen horizontally by e tiles and waits
; [wSlideMonDelay] V-blanks each time the pic is slid by one tile.
;>@pd def player_next_tile(pos):                     # .PlayerNextTile: the tile one column to the right
;>@pn1     tile = mem[pos] + 7 & 0xFF
;>@pn2     if tile < 0x61:                               # (one too few: the corner tile goes blank too)
;>@pn3         return tile
;>@pn4     return 0x7F                                   # ' '
;>@ed def enemy_next_tile(pos):                      # .EnemyNextTile: one column to the left
;>@en1     tile = mem[pos] - 7 & 0xFF
;>@en2     if tile < 0x30:
;>@en3         return tile
;>@en4     return 0x7F
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> if not player:
;>     start = coord(12, 0)
	jr z, .playerTurn
	ld hl, (0) * SCREEN_WIDTH + (12) + wTileMap
	jr .next
.playerTurn
;> else:
;>     start = coord(0, 5)
	ld hl, (5) * SCREEN_WIDTH + (0) + wTileMap
.next
;>@sl for _ in range(steps or 256):
	ld d, 8 ; d's value is unused
.slideLoop ; iterates once for each time the pic slides by one tile
;>     pos = start
	push hl
;>@rw     for _ in range(7):
	ld b, 7
.rowLoop ; iterates once for each row
;>@tl         for _ in range(8):
	ld c, 8
.tileLoop ; iterates once for each tile in the row
;>             if hWhoseTurn:
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn2
;>                 tile = enemy_next_tile(pos)
	call .EnemyNextTile
	jr .next2
.playerTurn2
;>             else:
;>                 tile = player_next_tile(pos)
	call .PlayerNextTile
.next2
;>             mem[pos] = tile
;>             pos += 1
	ld [hli], a
;=@tl
	dec c
	jr nz, .tileLoop
;>         pos += SCREEN_WIDTH - 8
	push de
	ld de, SCREEN_WIDTH - 8
	add hl, de
	pop de
;=@rw
	dec b
	jr nz, .rowLoop
;>     DelayFrames(wSlideMonDelay)
	ld a, [wSlideMonDelay]
	ld c, a
	call DelayFrames
;=@sl
	pop hl
	dec d
	dec e
	jr nz, .slideLoop
	ret

; Since mon pic tile numbers go from top to bottom, left to right in order,
; adding the height of the mon pic in tiles to a tile number gives the tile
; number of the tile one column to the right (and thus subtracting the height
; gives the reverse). If the next tile would be past the edge of the pic, the 2
; functions below catch it by checking if the tile number is within the valid
; range and if not, replacing it with a blank tile.

.PlayerNextTile
;=@pn1
	ld a, [hl]
	add 7
; This is a bug. The lower right corner tile of the mon back pic is blanked
; while the mon is sliding off the screen. It should compare with the max tile
; plus one instead.
;=@pn2
	cp $61
;=@pn3
	ret c
;=@pn4
	ld a, ' '
	ret

.EnemyNextTile
;=@en1
	ld a, [hl]
	sub 7
; This has the same problem as above, but it has no visible effect because
; the lower right tile is in the first column to slide off the screen.
;=@en2
	cp $30
;=@en3
	ret c
;=@en4
	ld a, ' '
	ret

;@ path: engine/battle/animations
;@ def AnimationSlideMonHalfOff()
;@ Softboiled: the attacker's picture slides halfway off the screen.
AnimationSlideMonHalfOff:
; Slides the mon's sprite halfway off the screen. It's used in Softboiled.
;> wSlideMonDelay = 4
	ld e, 4
	ld a, 4
	ld [wSlideMonDelay], a
;> _AnimationSlideMonOff(4)                          # half way
	call _AnimationSlideMonOff
;> Delay3()
	jp Delay3

;@ path: engine/battle/animations
;@ def CopyTempPicToMonPic()
;@ Copy the picture in wTempPic to the attacker's picture tiles in VRAM.
CopyTempPicToMonPic:
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> dest = vBackPic + 0
;> if not player:
	ld hl, vBackPic ; player turn
	jr z, .next
;>     dest = vFrontPic + 0
	ld hl, vFrontPic ; enemy turn
.next
;> CopyVideoData(dest, wTempPic + 0, hi(PIC_SIZE), lo(PIC_SIZE))
	ld de, wTempPic
	ld bc, PIC_SIZE
	jp CopyVideoData

;@ path: engine/battle/animations
;@ def AnimationWavyScreen()
;@ Psywave, Psychic: the screen waves - in each of 255 frames every line gets its own horizontal scroll from
;@ WavyScreenLineOffsets, each frame starting one line further on.
AnimationWavyScreen:
; used in Psywave/Psychic etc.
;> BattleAnimCopyTileMapToVRAM(vBGMap0 + 0)
	ld hl, vBGMap0
	call BattleAnimCopyTileMapToVRAM
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> hWY = SCREEN_HEIGHT_PX
	ld a, SCREEN_HEIGHT_PX
	ldh [hWY], a
;> offsets = WavyScreenLineOffsets
;> for _ in range(255):
	ld d, $80 ; terminator
	ld e, SCREEN_HEIGHT_PX - 1
	ld c, $ff
	ld hl, WavyScreenLineOffsets
.loop
;>     p = offsets
;>     while True:
	push hl
.innerLoop
;>         p = WavyScreen_SetSCX(p, 0x80)
	call WavyScreen_SetSCX
;>         if rLY == SCREEN_HEIGHT_PX - 1:
;>             break
	ldh a, [rLY]
	cp e ; is it the last visible line in the frame?
	jr nz, .innerLoop ; keep going if not
;>     offsets += 1
	pop hl
	inc hl
;>     if mem[offsets] == 0x80:
	ld a, [hl]
	cp d ; have we reached the end?
	jr nz, .next
;>         offsets = WavyScreenLineOffsets
	ld hl, WavyScreenLineOffsets ; go back to the beginning if so
.next
	dec c
	jr nz, .loop
;> hWY = 0
	xor a
	ldh [hWY], a
;> SaveScreenTilesToBuffer2()
	call SaveScreenTilesToBuffer2
;> ClearScreen()
	call ClearScreen
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
;> LoadScreenTilesFromBuffer2()
	call LoadScreenTilesFromBuffer2
;> BattleAnimCopyTileMapToVRAM(vBGMap1 + 0)
	ld hl, vBGMap1
	call BattleAnimCopyTileMapToVRAM
	ret

;@ path: engine/battle/animations
;@ def WavyScreen_SetSCX(offsets: hl, end: d) -> hl
;@ At the next H-blank, scroll the line by the next offset; the offsets start over at `end`.
WavyScreen_SetSCX:
;> wait_hblank()
	ldh a, [rSTAT]
	and $3 ; is it H-blank?
	jr nz, WavyScreen_SetSCX ; wait until it's H-blank
;> rSCX = mem[offsets]
	ld a, [hl]
	ldh [rSCX], a
;> offsets += 1
	inc hl
;> if mem[offsets] == end:
	ld a, [hl]
	cp d ; have we reached the end?
;>     return WavyScreenLineOffsets
;> return offsets
	ret nz
	ld hl, WavyScreenLineOffsets ; go back to the beginning if so
	ret

;@ path: engine/battle/animations
WavyScreenLineOffsets:
; Sequence of horizontal line pixel offsets for the wavy screen animation.
; This sequence vaguely resembles a sine wave.
	db 0, 0, 0, 0, 0,  1,  1,  1,  2,  2,  2,  2,  2,  1,  1,  1
	db 0, 0, 0, 0, 0, -1, -1, -1, -2, -2, -2, -2, -2, -1, -1, -1
	db $80 ; terminator

;@ path: engine/battle/animations
;@ def AnimationSubstitute()
;@ The attacker's picture becomes the little doll of Substitute (from MonsterSprite: its front for the enemy, its
;@ back for the player).
AnimationSubstitute:
; Changes the pokemon's sprite to the mini sprite
;> FillMemory(wTempPic + 0, PIC_SIZE * TILE_SIZE, 0)
	ld hl, wTempPic
	xor a
	ld bc, PIC_SIZE * TILE_SIZE
	call FillMemory
;> if hWhoseTurn:                                    # the enemy: the doll's front (its tiles go down the columns)
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;>     CopyMonsterSpriteData(MonsterSprite + 0 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 2 + 4) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 0 ; facing down sprite
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 2 + 4) ; x=2, y=4, in the 7*7 tiles pic data ; the tile data is organised rows>columns unlike the usual columns>rows tilemapping
	call CopyMonsterSpriteData
;>     CopyMonsterSpriteData(MonsterSprite + 1 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 3 + 4) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 1
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 3 + 4) ; x=3, y=4
	call CopyMonsterSpriteData
;>     CopyMonsterSpriteData(MonsterSprite + 2 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 2 + 5) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 2
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 2 + 5) ; x=2, y=5
	call CopyMonsterSpriteData
;>     CopyMonsterSpriteData(MonsterSprite + 3 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 3 + 5) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 3
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 3 + 5) ; x=3, y=5
	call CopyMonsterSpriteData
	jr .next
.playerTurn
;> else:                                             # the player: its back
;>     CopyMonsterSpriteData(MonsterSprite + 4 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 3 + 4) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 4 ; facing up sprite
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 3 + 4) ; x=3, y=4
	call CopyMonsterSpriteData
;>     CopyMonsterSpriteData(MonsterSprite + 5 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 4 + 4) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 5
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 4 + 4) ; x=4, y=4
	call CopyMonsterSpriteData
;>     CopyMonsterSpriteData(MonsterSprite + 6 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 3 + 5) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 6
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 3 + 5) ; x=3, y=5
	call CopyMonsterSpriteData
;>     CopyMonsterSpriteData(MonsterSprite + 7 * TILE_SIZE, wTempPic + (PIC_HEIGHT * 4 + 5) * TILE_SIZE)
	ld hl, MonsterSprite + TILE_SIZE * 7
	ld de, wTempPic + + TILE_SIZE * (PIC_HEIGHT * 4 + 5) ; x=4, y=5
	call CopyMonsterSpriteData
.next
;> CopyTempPicToMonPic()
	call CopyTempPicToMonPic
;> AnimationShowMonPic()
	jp AnimationShowMonPic

;@ path: engine/battle/animations
;@ def CopyMonsterSpriteData(src: hl, dest: de)
;@ Copy one tile of MonsterSprite from its bank.
CopyMonsterSpriteData:
;> FarCopyData2(BANK(MonsterSprite), src, dest, TILE_SIZE)
	ld bc, TILE_SIZE
	ld a, BANK(MonsterSprite)
	jp FarCopyData2

;@ path: engine/battle/animations
;@ def HideSubstituteShowMonAnim()
;@ Take the substitute away to show the mon: it slides off sideways, or down if it broke. A minimized mon is shown
;@ minimized.
HideSubstituteShowMonAnim:
;> if hWhoseTurn == 0:
;>     minimized, flags = addr(wPlayerMonMinimized), wPlayerBattleStatus2
	ldh a, [hWhoseTurn]
	and a
	ld hl, wPlayerMonMinimized
	ld a, [wPlayerBattleStatus2]
	jr z, .next1
;> else:
;>     minimized, flags = addr(wEnemyMonMinimized), wEnemyBattleStatus2
	ld hl, wEnemyMonMinimized
	ld a, [wEnemyBattleStatus2]
.next1
	push hl
; if the substitute broke, slide it down, else slide it offscreen horizontally
;> if flags >> HAS_SUBSTITUTE_UP & 1:
;>     AnimationSlideMonOff()
	bit HAS_SUBSTITUTE_UP, a
	jr nz, .substituteStillUp
;> else:
;>     AnimationSlideMonDown()
	call AnimationSlideMonDown
	jr .next2
.substituteStillUp
	call AnimationSlideMonOff
.next2
;> if mem[minimized]:
;>     return AnimationMinimizeMon()
	pop hl
	ld a, [hl]
	and a
	jp nz, AnimationMinimizeMon
;> AnimationFlashMonPic()
	call AnimationFlashMonPic
;> AnimationShowMonPic()
	jp AnimationShowMonPic

;@ path: engine/battle/animations
;@ def ReshowSubstituteAnim()
;@ The mon slides off and the substitute comes back.
ReshowSubstituteAnim:
;> AnimationSlideMonOff()
	call AnimationSlideMonOff
;> AnimationSubstitute()
	call AnimationSubstitute
;> AnimationShowMonPic()
	jp AnimationShowMonPic

;@ path: engine/battle/animations
;@ def AnimationBoundUpAndDown()
;@ Splash: the attacker's picture slides down five times.
AnimationBoundUpAndDown:
; Bounces the mon's sprite up and down several times. It is used
; by Splash's animation.
;>@bd for _ in range(5):
	ld c, 5
.loop
;>     AnimationSlideMonDown()
	push bc
	call AnimationSlideMonDown
;=@bd
	pop bc
	dec c
	jr nz, .loop
;> AnimationShowMonPic()
	jp AnimationShowMonPic

;@ path: engine/battle/animations
;@ def AnimationTransformMon()
;@ Transform: the attacker's picture becomes the target's species.
AnimationTransformMon:
; Redraws this mon's sprite as the back/front sprite of the opposing mon.
; Used in Transform.
;> wChangeMonPicPlayerTurnSpecies = mem[wEnemyMonSpecies]   # each side as the other's species
	ld a, [wEnemyMonSpecies]
	ld [wChangeMonPicPlayerTurnSpecies], a
;> wChangeMonPicEnemyTurnSpecies = mem[wBattleMonSpecies]
	ld a, [wBattleMonSpecies]
	ld [wChangeMonPicEnemyTurnSpecies], a
;> ChangeMonPic()                                    # (it follows)

;@ path: engine/battle/animations
;@ def ChangeMonPic()
;@ Redraw the attacker's picture as wChangeMonPicPlayerTurnSpecies (back picture) or
;@ wChangeMonPicEnemyTurnSpecies (front picture), and set the battle palettes again.
ChangeMonPic:
;> if hWhoseTurn:                                    # the enemy's: the front picture
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
;>     wCurPartySpecies = wChangeMonPicEnemyTurnSpecies
	ld a, [wChangeMonPicEnemyTurnSpecies]
	ld [wCurPartySpecies], a
;>     wCurSpecies = wChangeMonPicEnemyTurnSpecies
	ld [wCurSpecies], a
;>     wSpriteFlipped = 0
	xor a
	ld [wSpriteFlipped], a
;>     GetMonHeader()
	call GetMonHeader
;>     LoadFrontSpriteByMonIndex(coord(12, 0))
	ld hl, (0) * SCREEN_WIDTH + (12) + wTileMap
	call LoadFrontSpriteByMonIndex
	jr .done
.playerTurn
;> else:                                             # the player's: the back picture
;>     saved = wBattleMonSpecies2
	ld a, [wBattleMonSpecies2]
	push af
;>     wBattleMonSpecies2 = wChangeMonPicPlayerTurnSpecies
	ld a, [wChangeMonPicPlayerTurnSpecies]
	ld [wBattleMonSpecies2], a
;>     wCurSpecies = wChangeMonPicPlayerTurnSpecies
	ld [wCurSpecies], a
;>     GetMonHeader()
	call GetMonHeader
;>     predef(LoadMonBackPic)
	ld a, (LoadMonBackPicPredef - PredefPointers) / 3
	call Predef
;>     ids, rows, cols = GetTileIDList(TILEMAP_MON_PIC)
	xor a ; TILEMAP_MON_PIC
	call GetTileIDList
;>     pos = GetMonSpriteTileMapPointerFromRowCount(rows)
	call GetMonSpriteTileMapPointerFromRowCount
;>     CopyPicTiles(pos, ids, rows, cols)
	call CopyPicTiles
;>     wBattleMonSpecies2 = saved
	pop af
	ld [wBattleMonSpecies2], a
.done
;> RunPaletteCommand(SET_PAL_BATTLE)
	ld b, SET_PAL_BATTLE
	jp RunPaletteCommand

;@ path: engine/battle/animations
;@ def AnimationHideEnemyMonPic()
;@ The target's picture vanishes.
AnimationHideEnemyMonPic:
; Hides the enemy mon's sprite
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> CallWithTurnFlipped(AnimationHideMonPic)
	ld hl, AnimationHideMonPic
	call CallWithTurnFlipped
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	jp Delay3

;@ path: engine/battle/animations
;@ def InitMultipleObjectsOAM(tileset: a, n: c, tile: d)
;@ Load animation tileset `tileset` and set up n sprites of `tile` in a column at x = 0, y = 8, 16, ...
InitMultipleObjectsOAM:
; Writes c OAM entries with tile d.
; Sets their Y coordinates to sequential multiples of 8, starting from 0.
; Sets their X coordinates to 0.
; Loads animation tileset a.
;> wWhichBattleAnimTileset = tileset
	push bc
	push de
	ld [wWhichBattleAnimTileset], a
;> LoadMoveAnimationTiles()
	call LoadMoveAnimationTiles
;> wBaseCoordX = 0
	pop de
	pop bc
	xor a
	ld e, a
	ld [wBaseCoordX], a
;> oam, y = wShadowOAM + 0, 0
	ld hl, wShadowOAM
.loop
;> for _ in range(n or 256):
;>     oam, y = BattleAnimWriteOAMEntry(oam, y, tile)
	call BattleAnimWriteOAMEntry
	dec c
	jr nz, .loop
	ret

;@ path: engine/battle/animations
;@ def AnimationHideMonPic()
;@ The attacker's picture vanishes.
AnimationHideMonPic:
; Hides the mon's sprite.
;> ClearMonPicFromTileMap(12 if hWhoseTurn else 5 * SCREEN_WIDTH + 1)
	ldh a, [hWhoseTurn]
	and a
	jr z, .playerTurn
	ld a, 12
	jr ClearMonPicFromTileMap
.playerTurn
	ld a, 5 * SCREEN_WIDTH + 1

;@ path: engine/battle/animations
;@ def ClearMonPicFromTileMap(offset: a)
;@ Blank the 7x7 tiles at tile map offset `offset`; keeps hl, de and bc.
;@ test: offset = rand(0, 12)
ClearMonPicFromTileMap:
;> pos = coord(0, 0) + offset                        # (hl, de and bc are kept)
	push hl
	push de
	push bc
	ld e, a
	ld d, 0
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
;> ClearScreenArea(pos, 7, 7)
	add hl, de
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
	call ClearScreenArea
;> return
	pop bc
	pop de
	pop hl
	ret

; puts the tile map destination address of a mon sprite in hl, given the row count in b
; The usual row count is 7, but it may be smaller when sliding a mon sprite in/out,
; in order to show only a portion of the mon sprite.
;@ path: engine/battle/animations
;@ def GetMonSpriteTileMapPointerFromRowCount(rows: b) -> hl
;@ Where the attacker's picture goes in the tile map when only its bottom `rows` rows (of 7) are shown; keeps de.
GetMonSpriteTileMapPointerFromRowCount:
;> if hWhoseTurn == 0:
	push de
	ldh a, [hWhoseTurn]
	and a
	jr nz, .enemyTurn
;>     offset = 5 * SCREEN_WIDTH + 1
	ld a, 5 * SCREEN_WIDTH + 1
	jr .next
.enemyTurn
;> else:
;>     offset = 12
	ld a, 12
.next
;> pos = coord(0, 0) + offset
	ld hl, (0) * SCREEN_WIDTH + (0) + wTileMap
	ld e, a
	ld d, 0
	add hl, de
;> hidden = 7 - rows & 0xFF                          # the rows not shown
	ld a, 7
	sub b
;> if hidden:
	and a
	jr z, .done
;>@hr     for _ in range(hidden):
;>         pos += SCREEN_WIDTH
	ld de, SCREEN_WIDTH
.loop
	add hl, de
;=@hr
	dec a
	jr nz, .loop
.done
;> return pos                                        # (de is kept)
	pop de
	ret

; Input:
; a = tile ID list index
; Output:
; de = tile ID list pointer
; b = number of rows
; c = number of columns
;@ path: engine/battle/animations
;@ def GetTileIDList(kind: a) -> (de, b, c)
;@ The tile number list of a picture layout (TileIDListPointerTable) with its number of rows and columns.
GetTileIDList:
;> entry = TileIDListPointerTable + 3 * kind
	ld hl, TileIDListPointerTable
	ld e, a
	ld d, 0
	add hl, de
	add hl, de
	add hl, de
;> ids = mem16[entry]
	ld a, [hli]
	ld e, a
	ld a, [hli]
	ld d, a
;> size = mem[entry + 2]
	ld a, [hli]
	ld b, a
;> cols = size & 0xF
	and $f
	ld c, a
;> rows = size >> 4
	ld a, b
	swap a
	and $f
	ld b, a
;> return ids, rows, cols
	ret

;@ path: engine/battle/animations
;@ def AnimCopyRowLeft(pos: hl, n: c) -> hl
;@ Move n tiles one tile left, from pos rightwards; returns the tile after them.
;@ test: pos = rand(0xC3B0, 0xC4C0); n = rand(1, 8)
AnimCopyRowLeft:
; copy a row of c tiles 1 tile left
;>@cl for _ in range(n or 256):
;>     mem[pos - 1] = mem[pos]
	ld a, [hld]
	ld [hli], a
;>     pos += 1
	inc hl
;=@cl
	dec c
	jr nz, AnimCopyRowLeft
;> return pos
	ret

;@ path: engine/battle/animations
;@ def AnimCopyRowRight(pos: hl, n: c) -> hl
;@ Move n tiles one tile right, from pos leftwards; returns the tile before them.
;@ test: pos = rand(0xC3B0, 0xC4C0); n = rand(1, 8)
AnimCopyRowRight:
; copy a row of c tiles 1 tile right
;>@cr for _ in range(n or 256):
;>     mem[pos + 1] = mem[pos]
	ld a, [hli]
	ld [hld], a
;>     pos -= 1
	dec hl
;=@cr
	dec c
	jr nz, AnimCopyRowRight
;> return pos
	ret

; only used by the unreferenced PlayIntroMoveSound
;@ path: engine/battle/animations
;@ def GetIntroMoveSound(move: b) -> b
;@ GetMoveSound for b (only used by unused code).
GetIntroMoveSound:
;> return GetMoveSound(move)
	ld a, b
	call GetMoveSound
	ld b, a
	ret

;@ path: engine/battle/animations
;@ def GetMoveSound(move: a) -> a
;@ The sound of a move's animation and its pitch and tempo (MoveSoundTable). Growl and Roar use the attacker's cry,
;@ with the table's pitch and tempo added to the current ones.
;@ test: hLoadedROMBank = 0x1E
GetMoveSound:
;> entry = MoveSoundTable + 3 * move
	ld hl, MoveSoundTable
	ld e, a
	ld d, 0
	add hl, de
	add hl, de
	add hl, de
;> sound = mem[entry]
	ld a, [hli]
	ld b, a
;> if IsCryMove():
	call IsCryMove
	jr nc, .NotCryMove
;>     if hWhoseTurn == 0:                           # the attacker's cry
	ldh a, [hWhoseTurn]
	and a
	jr nz, .next
;>         species = mem[wBattleMonSpecies]
	ld a, [wBattleMonSpecies] ; get number of current monster
	jr .Continue
.next
;>     else:
;>         species = mem[wEnemyMonSpecies]
	ld a, [wEnemyMonSpecies]
.Continue
;>     sound = GetCryData(species)
	push hl
	call GetCryData
	ld b, a
	pop hl
;>     wFrequencyModifier = wFrequencyModifier + mem[entry + 1] & 0xFF
	ld a, [wFrequencyModifier]
	add [hl]
	ld [wFrequencyModifier], a
;>     wTempoModifier = wTempoModifier + mem[entry + 2] & 0xFF
	inc hl
	ld a, [wTempoModifier]
	add [hl]
	ld [wTempoModifier], a
	jr .done
.NotCryMove
;> else:
;>     wFrequencyModifier = mem[entry + 1]
	ld a, [hli]
	ld [wFrequencyModifier], a
;>     wTempoModifier = mem[entry + 2]
	ld a, [hli]
	ld [wTempoModifier], a
.done
;> return sound
	ld a, b
	ret

;@ path: engine/battle/animations
;@ def IsCryMove() -> carry
;@ Carry for Growl and Roar, whose animations play a cry.
IsCryMove:
; set carry if the move animation involves playing a monster cry
;> if wAnimationID == GROWL:
;>@cm     return True
	ld a, [wAnimationID]
	cp GROWL
	jr z, .CryMove
;> if wAnimationID == ROAR:
;>     return True
	cp ROAR
	jr z, .CryMove
;> return False
	and a ; clear carry
	ret
.CryMove
;=@cm
	scf
	ret

