;@ path: engine/battle/animations
;@ def CopyPicTiles(dest: hl, ids: de, rows: b, cols: c) -> (hl, de)
;@ Draw the attacker's picture with a tile number list (the player's tiles start at $31, the enemy's at 0).
;@ test: dest = rand(0xC3A0, 0xC400); ids = rand(0x4000, 0x7000); rows = rand(1, 7); cols = rand(1, 7)
CopyPicTiles:
;> player = hWhoseTurn == 0
	ldh a, [hWhoseTurn]
	and a
;> base = 0x31                                       # the player's tiles start at $31
;> if not player:
	ld a, $31 ; base tile ID of player mon sprite
	jr z, .next
; enemy turn
;>     base = 0
	xor a ; base tile ID of enemy mon sprite
.next
;> hBaseTileID = base
	ldh [hBaseTileID], a
;> return CopyTileIDs_NoBGTransfer(dest, ids, rows, cols)
	jr CopyTileIDs_NoBGTransfer

; copy the tiles used when a mon is being sent out of or into a pokeball
;@ path: engine/battle/animations
;@ def CopyDownscaledMonTiles()
;@ Draw the small picture of a mon going into or out of its ball (5x5 or, for wDownscaledMonSize, 3x3 tiles) at
;@ the predef's hl, with b rows and c columns.
;@ test: mem[wPredefHL] = 0xC3; mem[wPredefHL + 1] = rand(0xB0, 0xF0); mem[wPredefBC] = rand(1, 5); mem[wPredefBC + 1] = rand(1, 5)
CopyDownscaledMonTiles:
;> dest, _, size = GetPredefRegisters()
	call GetPredefRegisters
;> if not wDownscaledMonSize:
;>     return CopyTileIDs_NoBGTransfer(dest, DownscaledMonTiles_5x5, hi(size), lo(size))
	ld a, [wDownscaledMonSize]
	and a
	jr nz, .smallerSize
	ld de, DownscaledMonTiles_5x5
	jr CopyTileIDs_NoBGTransfer
.smallerSize
;> return CopyTileIDs_NoBGTransfer(dest, DownscaledMonTiles_3x3, hi(size), lo(size))   # (it follows)
	ld de, DownscaledMonTiles_3x3
; fall through

;@ path: engine/battle/animations
;@ def CopyTileIDs_NoBGTransfer(dest: hl, ids: de, rows: b, cols: c) -> (hl, de)
;@ CopyTileIDs, with the tile map copying to VRAM held back while it writes.
;@ test: dest = rand(0xC3A0, 0xC400); ids = rand(0x4000, 0x7000); rows = rand(1, 7); cols = rand(1, 7)
CopyTileIDs_NoBGTransfer:
;> hAutoBGTransferEnabled = 0
;> return CopyTileIDs(dest, ids, rows, cols)
	xor a
	ldh [hAutoBGTransferEnabled], a
; fall through

; b = number of rows
; c = number of columns
;@ path: engine/battle/animations
;@ def CopyTileIDs(dest: hl, ids: de, rows: b, cols: c) -> (hl, de)
;@ Draw rows x cols tiles from a tile number list, each plus hBaseTileID, then let the tile map be copied to VRAM.
;@ Returns dest and the end of the list.
;@ test: dest = rand(0xC3A0, 0xC400); ids = rand(0x4000, 0x7000); rows = rand(1, 7); cols = rand(1, 7)
CopyTileIDs:
;> row = dest
	push hl
.rowLoop
;>@rl for _ in range(rows or 256):
;>     base = hBaseTileID
	push bc
	push hl
	ldh a, [hBaseTileID]
	ld b, a
.columnLoop
;>@cl     for i in range(cols or 256):
;>         mem[row + i & 0xFFFF] = mem[ids] + base & 0xFF
;>         ids = ids + 1 & 0xFFFF
	ld a, [de]
	add b
	inc de
	ld [hli], a
;=@cl
	dec c
	jr nz, .columnLoop
;>     row = row + SCREEN_WIDTH & 0xFFFF
	pop hl
	ld bc, SCREEN_WIDTH
	add hl, bc
;=@rl
	pop bc
	dec b
	jr nz, .rowLoop
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> return dest, ids
	pop hl
	ret


;@ path: engine/battle/animations
TileIDListPointerTable:
; entries correspond to TILEMAP_* constants (see constants/gfx_constants.asm)
	; tilemap pointer, width, height
	dw MonTiles
	db ((7) << 4) | (7)
	dw SlideDownMonTiles_7x5
	db ((5) << 4) | (7)
	dw SlideDownMonTiles_7x3
	db ((3) << 4) | (7)
	dw GengarIntroTiles1
	db ((7) << 4) | (7)
	dw GengarIntroTiles2
	db ((7) << 4) | (7)
	dw GengarIntroTiles3
	db ((7) << 4) | (7)
	dw GameBoyTiles
	db ((8) << 4) | (6)
	dw LinkCableTiles
	db ((3) << 4) | (12)

;@ path: engine/battle/animations
DownscaledMonTiles_5x5:
	db $31, $38, $46, $54, $5b, $32, $39, $47, $55, $5c, $34, $3b, $49, $57, $5e, $36
	db $3d, $4b, $59, $60, $37, $3e, $4c, $5a, $61

;@ path: engine/battle/animations
