;@ path: engine/battle/animations
;@ def AnimationLeavesFalling()
;@ Razor Leaf: three leaves float down, drawn with the animation palette.
AnimationLeavesFalling:
; Makes leaves float down from the top of the screen. This is used
; in Razor Leaf's animation.
;> saved = rOBP0
	ldh a, [rOBP0]
	push af
;> rOBP0 = wAnimPalette
	ld a, [wAnimPalette]
	ldh [rOBP0], a
;> wNumFallingObjects = 3                            # three leaves
	ld d, $37 ; leaf tile
	ld a, 3 ; number of leaves
	ld [wNumFallingObjects], a
;> AnimationFallingObjects(3, 0x37)
	call AnimationFallingObjects
;> rOBP0 = saved
	pop af
	ldh [rOBP0], a
	ret

;@ path: engine/battle/animations
;@ def AnimationPetalsFalling()
;@ Petal Dance: twenty petals float down.
AnimationPetalsFalling:
; Makes lots of petals fall down from the top of the screen. It's used in
; the animation for Petal Dance.
;> wNumFallingObjects = 20                           # twenty petals
	ld d, $71 ; petal tile
	ld a, 20 ; number of petals
	ld [wNumFallingObjects], a
;> AnimationFallingObjects(20, 0x71)
	call AnimationFallingObjects
;> ClearSprites()
	jp ClearSprites

;@ path: engine/battle/animations
;@ def AnimationFallingObjects(n: a, tile: d)
;@ n sprites of `tile` swing down from the top of the screen, 2 pixels every 3 frames, until the first one reaches
;@ y 104.
AnimationFallingObjects:
;> InitMultipleObjectsOAM(1, n, tile)
	ld c, a
	ld a, 1
	call InitMultipleObjectsOAM
;> FallingObjects_InitXCoords()
	call FallingObjects_InitXCoords
;> FallingObjects_InitMovementData()
	call FallingObjects_InitMovementData
;> mem[wShadowOAM] = 0
	ld hl, wShadowOAM
	ld [hl], 0
.loop
;> while True:
;>     offset = 0
;>@il     for i in range(wNumFallingObjects or 256):
	ld hl, wFallingObjectsMovementData
	ld de, 0
	ld a, [wNumFallingObjects]
	ld c, a
.innerLoop
;>         wFallingObjectMovementByte = mem[wFallingObjectsMovementData + i]
	push bc
	push hl
	push de
	ld a, [hl]
	ld [wFallingObjectMovementByte], a
;>         FallingObjects_UpdateMovementByte()
	call FallingObjects_UpdateMovementByte
;>         FallingObjects_UpdateOAMEntry(offset)
	call FallingObjects_UpdateOAMEntry
;>         offset += 4                               # the next sprite
	pop de
	ld hl, 4
	add hl, de
	ld e, l
	ld d, h
	pop hl
;>         mem[wFallingObjectsMovementData + i] = wFallingObjectMovementByte
	ld a, [wFallingObjectMovementByte]
	ld [hli], a
;=@il
	pop bc
	dec c
	jr nz, .innerLoop
;>     Delay3()
	call Delay3
;>     if mem[wShadowOAM] == 104:
;>         return
	ld hl, wShadowOAM
	ld a, [hl] ; Y
	cp 104 ; has the top falling object reached 104 yet?
	jr nz, .loop ; keep moving the falling objects down until it does
	ret

;@ path: engine/battle/animations
;@ def FallingObjects_UpdateOAMEntry(offset: de)
;@ Move a falling object's sprite 2 pixels down (off the screen from y 112) and sideways by the step in its
;@ movement byte (FallingObjects_DeltaXs; bit 7: to the left, drawn mirrored).
;@ test: offset = 4 * rand(0, 20)
FallingObjects_UpdateOAMEntry:
; Increases Y by 2 pixels and adjusts X and X flip based on the falling object's
; movement byte.
;> oam = wShadowOAM + offset & 0xFFFF
	ld hl, wShadowOAM
	add hl, de
;> y = mem[oam] + 2 & 0xFF
	ld a, [hl]
	inc a
	inc a
;> if y >= 112:
	cp 112
	jr c, .next
;>     y = SCREEN_HEIGHT_PX + OAM_Y_OFS
	ld a, SCREEN_HEIGHT_PX + OAM_Y_OFS ; if Y >= 112, put it off-screen
.next
;> mem[oam] = y
	ld [hli], a ; Y
;> byte = wFallingObjectMovementByte
	ld a, [wFallingObjectMovementByte]
	ld b, a
;> delta = mem[FallingObjects_DeltaXs + (byte & 0x7F)]
	ld de, FallingObjects_DeltaXs
	and $7f
	add e
	jr nc, .noCarry
	inc d
.noCarry
	ld e, a
;> if byte & 0x80:                                   # swinging left (mirrored)
;>@l1     mem[oam + 1] = mem[oam + 1] - delta & 0xFF
;>@l2     attr = OAM_XFLIP
	ld a, b
	and $80
	jr nz, .movingLeft
; moving right
;> else:
;>     mem[oam + 1] = mem[oam + 1] + delta & 0xFF
	ld a, [de]
	add [hl]
	ld [hli], a ; X
;>     attr = 0
	inc hl
	xor a ; no horizontal flip
	jr .next2
.movingLeft
;=@l1
	ld a, [de]
	ld b, a
	ld a, [hl]
	sub b
	ld [hli], a ; X
;=@l2
	inc hl
	ld a, OAM_XFLIP
.next2
;> mem[oam + 3] = attr
	ld [hl], a ; attribute
	ret

;@ path: engine/battle/animations
FallingObjects_DeltaXs:
	db 0, 1, 3, 5, 7, 9, 11, 13, 15

;@ path: engine/battle/animations
;@ def FallingObjects_UpdateMovementByte()
;@ The next step of a falling object's swing; after the 9th the steps start over in the other direction.
FallingObjects_UpdateMovementByte:
;> byte = wFallingObjectMovementByte + 1 & 0xFF
	ld a, [wFallingObjectMovementByte]
	inc a
	ld b, a
;> if byte & 0x7F == 9:                              # the end of the swing: back the other way
	and $7f
	cp 9 ; have we reached the end of the delta-Xs?
	ld a, b
	jr nz, .next
; We've reached the end of the delta-Xs, so wrap to the start and change
; direction from right to left or vice versa.
;>     byte = byte & 0x80 ^ 0x80
	and $80
	xor $80
.next
;> wFallingObjectMovementByte = byte
	ld [wFallingObjectMovementByte], a
	ret

;@ path: engine/battle/animations
;@ def FallingObjects_InitXCoords()
;@ The falling objects' starting x coordinates (FallingObjects_InitialXCoords).
;@ test: wNumFallingObjects = rand(1, 20)
FallingObjects_InitXCoords:
;>@xl for i in range(wNumFallingObjects or 256):
	ld hl, wShadowOAMSprite00XCoord
	ld de, FallingObjects_InitialXCoords
	ld a, [wNumFallingObjects]
	ld c, a
.loop
;>     mem[wShadowOAMSprite00XCoord + 4 * i] = mem[FallingObjects_InitialXCoords + i]
	ld a, [de]
	ld [hli], a
	inc hl
	inc hl
	inc hl
	inc de
;=@xl
	dec c
	jr nz, .loop
	ret

;@ path: engine/battle/animations
FallingObjects_InitialXCoords:
	db $38, $40, $50, $60, $70, $88, $90, $56, $67, $4A, $77, $84, $98, $32, $22, $5C, $6C, $7D, $8E, $99

;@ path: engine/battle/animations
