	ld a, [wNumFallingObjects]
	ld c, a
.loop
;>     mem[wFallingObjectsMovementData + i] = mem[FallingObjects_InitialMovementData + i]
	ld a, [de]
	ld [hli], a
	inc de
;=@ml
	dec c
	jr nz, .loop
	ret

;@ path: engine/battle/animations
FallingObjects_InitialMovementData:
