;@ path: engine/battle/animations
;@ def AnimationShakeEnemyHUD()
;@ The enemy's HUD shakes sideways. The background is scrolled while the window keeps the lower part of the screen
;@ in place, and the player's mon's picture is shown as sprites meanwhile so it doesn't shake along.
AnimationShakeEnemyHUD:
; Shakes the enemy HUD.

; Make a copy of the back pic's tile patterns in sprite tile pattern VRAM.
;> CopyVideoData(vSprites + 0, vBackPic + 0, hi(PIC_SIZE), lo(PIC_SIZE))
	ld de, vBackPic
	ld hl, vSprites
	ld bc, PIC_SIZE
	call CopyVideoData

;> hSCX = 0
	xor a
	ldh [hSCX], a

; Copy wTileMap to BG map 0. The regular BG (not the window) is set to use
; map 0 and can be scrolled with SCX, which allows a shaking effect.
;> BattleAnimCopyTileMapToVRAM(vBGMap0 + 0)
	ld hl, vBGMap0
	call BattleAnimCopyTileMapToVRAM

; Now that the regular BG is showing the same thing the window was, move the
; window off the screen so that we can modify its contents below.
;> hWY = SCREEN_HEIGHT_PX
	ld a, SCREEN_HEIGHT_PX
	ldh [hWY], a

; Copy wTileMap to VRAM such that the row below the enemy HUD (in wTileMap) is
; lined up with row 0 of the window.
;> # the row below the enemy's HUD becomes the window's first row
;> BattleAnimCopyTileMapToVRAM(vBGMap1 + 0 - TILEMAP_WIDTH * 7)
	ld hl, vBGMap1 - TILEMAP_WIDTH * 7
	call BattleAnimCopyTileMapToVRAM

; Move the window so that the row below the enemy HUD (in BG map 0) lines up
; with the top row of the window on the screen. This makes it so that the window
; covers everything below the enemy HD with a copy that looks just like what
; was there before.
;> hWY = 7 * TILE_HEIGHT
	ld a, 7 * TILE_HEIGHT
	ldh [hWY], a

; Write OAM entries so that the copy of the back pic from the top of this
; function shows up on screen. We need this because the back pic's Y coordinates
; range overlaps with that of the enemy HUD and we don't want to shake the top
; of the back pic when we shake the enemy HUD. The OAM copy won't be affected
; by SCX.
;> ShakeEnemyHUD_WritePlayerMonPicOAM()
	call ShakeEnemyHUD_WritePlayerMonPicOAM

;> BattleAnimCopyTileMapToVRAM(vBGMap0 + 0)
	ld hl, vBGMap0
	call BattleAnimCopyTileMapToVRAM

; Remove the back pic from the BG map.
;> AnimationHideMonPic()
	call AnimationHideMonPic
;> Delay3()
	call Delay3

; Use SCX to shake the regular BG. The window and the back pic OAM copy are
; not affected.
;> ShakeEnemyHUD_ShakeBG(2, 8)
	ld de, ((2) & $ff) << 8 + ((8) & $ff)
	call ShakeEnemyHUD_ShakeBG

; Restore the original graphics.
;> AnimationShowMonPic()
	call AnimationShowMonPic
;> ClearSprites()
	call ClearSprites
;> hWY = SCREEN_HEIGHT_PX
	ld a, SCREEN_HEIGHT_PX
	ldh [hWY], a
;> BattleAnimCopyTileMapToVRAM(vBGMap1 + 0)
	ld hl, vBGMap1
	call BattleAnimCopyTileMapToVRAM
;> hWY = 0
	xor a
	ldh [hWY], a
;> SaveScreenTilesToBuffer1()
	call SaveScreenTilesToBuffer1
;> BattleAnimCopyTileMapToVRAM(vBGMap0 + 0)
	ld hl, vBGMap0
	call BattleAnimCopyTileMapToVRAM
;> ClearScreen()
	call ClearScreen
;> Delay3()
	call Delay3
;> LoadScreenTilesFromBuffer1()
	call LoadScreenTilesFromBuffer1
;> BattleAnimCopyTileMapToVRAM(vBGMap1 + 0)
	ld hl, vBGMap1
	jp BattleAnimCopyTileMapToVRAM

; b = tile ID list index
; c = base tile ID
;@ path: engine/battle/animations
;@ def CopyTileIDsFromList()
;@ Draw a picture layout (TileIDListPointerTable entry b) at the predef's hl, with tile numbers from c on.
;@ test: mem[wPredefHL] = 0xC3; mem[wPredefHL + 1] = rand(0xB0, 0xF0); mem[wPredefBC] = rand(0, 7); mem[wPredefBC + 1] = rand(0, 0x30)
CopyTileIDsFromList:
;> dest, _, args = GetPredefRegisters()
	call GetPredefRegisters
;> hBaseTileID = lo(args)
	ld a, c
	ldh [hBaseTileID], a
;> ids, rows, cols = GetTileIDList(hi(args))
	ld a, b
	push hl
	call GetTileIDList
	pop hl
;> return CopyTileIDs(dest, ids, rows, cols)
	jp CopyTileIDs

;@ path: engine/battle/animations
;@ def ShakeEnemyHUD_ShakeBG(distance: d, times: e)
;@ Scroll the background `distance` pixels right and left, 2 frames each, `times` times; then back where it was.
ShakeEnemyHUD_ShakeBG:
;> wTempSCX = hSCX
	ldh a, [hSCX]
	ld [wTempSCX], a
.loop
;> for _ in range(times or 256):
;>     hSCX = wTempSCX + distance & 0xFF
	ld a, [wTempSCX]
	add d
	ldh [hSCX], a
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
;>     hSCX = wTempSCX - distance & 0xFF
	ld a, [wTempSCX]
	sub d
	ldh [hSCX], a
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
	dec e
	jr nz, .loop
;> hSCX = wTempSCX
	ld a, [wTempSCX]
	ldh [hSCX], a
	ret

;@ path: engine/battle/animations
;@ def BattleAnimCopyTileMapToVRAM(dest: hl)
;@ Copy the tile map to the background map at dest during the next 3 frames.
BattleAnimCopyTileMapToVRAM:
;> hAutoBGTransferDest[0], hAutoBGTransferDest[1] = lo(dest), hi(dest)
;> Delay3()
	ld a, h
	ldh [hAutoBGTransferDest + 1], a
	ld a, l
	ldh [hAutoBGTransferDest], a
	jp Delay3

;@ path: engine/battle/animations
;@ def TossBallAnimation()
;@ Throwing a ball: the toss (Poké, Great or Ultra Ball) and then, as wPokeBallAnimData's upper nibble says, the
;@ poof, the mon vanishing, the shaking (lower nibble: how often) and for a breakout the poof and the mon again. A
;@ trainer blocks the ball.
TossBallAnimation:
;> if wIsInBattle == TRAINER_BATTLE:                 # a trainer blocks the ball
;>@b1     wAnimationID = TOSS_ANIM
;>@b2     PlayAnimation()
;>@b3     PlaySound(SFX_FAINT_THUD)
;>@b4     wAnimationID = BLOCKBALL_ANIM
;>@b5     return PlayAnimation()
	ld a, [wIsInBattle]
	cp TRAINER_BATTLE
	jr z, .BlockBall
;> count = wPokeBallAnimData >> 4
	ld a, [wPokeBallAnimData]
	ld b, a

	; upper nybble: how many animations (from PokeBallAnimations) to play
	; this will be 4 for successful capture, 6 for breakout
	and $F0
	swap a
	ld c, a

	; lower nybble: number of shakes
	; store these for later
;> wNumShakes = wPokeBallAnimData & 0xF
	ld a, b
	and $F
	ld [wNumShakes], a

	ld hl, .PokeBallAnimations
	; choose which toss animation to use
;> if wCurItem == POKE_BALL:
	ld a, [wCurItem]
	cp POKE_BALL
;>     toss = TOSS_ANIM
	ld b, TOSS_ANIM
	jr z, .done
;> elif wCurItem == GREAT_BALL:
	cp GREAT_BALL
;>     toss = GREATTOSS_ANIM
	ld b, GREATTOSS_ANIM
	jr z, .done
;> else:
;>     toss = ULTRATOSS_ANIM
	ld b, ULTRATOSS_ANIM
.done
;>@ta for anim in ((toss, POOF_ANIM, HIDEPIC_ANIM, SHAKE_ANIM, POOF_ANIM, SHOWPIC_ANIM))[:count]:  # .PokeBallAnimations
	ld a, b
.PlayNextAnimation
;>     wAnimationID = anim
	ld [wAnimationID], a
;>     PlayAnimation()
	push bc
	push hl
	call PlayAnimation
	pop hl
;=@ta
	ld a, [hli]
	pop bc
	dec c
	jr nz, .PlayNextAnimation
	ret

.PokeBallAnimations:
; sequence of animations that make up the Poké Ball toss
	db POOF_ANIM, HIDEPIC_ANIM, SHAKE_ANIM, POOF_ANIM, SHOWPIC_ANIM

.BlockBall
;=@b1
	ld a, TOSS_ANIM
	ld [wAnimationID], a
;=@b2
	call PlayAnimation
;=@b3
	ld a, SFX_FAINT_THUD
	call PlaySound
;=@b4
	ld a, BLOCKBALL_ANIM
	ld [wAnimationID], a
;=@b5
	jp PlayAnimation

;@ path: engine/battle/animations
;@ def PlayApplyingAttackSound()
;@ The hit sound for the damage multiplier: normal, super effective (higher, faster) or not very effective (lower);
;@ none for no effect.
;@ test: skip waits for the sound
PlayApplyingAttackSound:
; play a different sound depending if move is not very effective, neutral, or super-effective
; don't play any sound at all if move is ineffective
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> multiplier = wDamageMultipliers & 0x7F
	ld a, [wDamageMultipliers]
	and $7f
;> if multiplier == 0:
;>     return
	ret z
;> if multiplier == 10:
	cp 10
;>     frequency, tempo, sound = 0x20, 0x30, SFX_DAMAGE
	ld a, $20
	ld b, $30
	ld c, SFX_DAMAGE
	jr z, .playSound
;> elif multiplier > 10:
;>     frequency, tempo, sound = 0xE0, 0xFF, SFX_SUPER_EFFECTIVE
	ld a, $e0
	ld b, $ff
	ld c, SFX_SUPER_EFFECTIVE
	jr nc, .playSound
;> else:
;>     frequency, tempo, sound = 0x50, 1, SFX_NOT_VERY_EFFECTIVE
	ld a, $50
	ld b, $1
	ld c, SFX_NOT_VERY_EFFECTIVE
.playSound
;> wFrequencyModifier = frequency
	ld [wFrequencyModifier], a
;> wTempoModifier = tempo
	ld a, b
	ld [wTempoModifier], a
;> PlaySound(sound)
	ld a, c
	jp PlaySound
;@ path: engine/overworld/cut2
;@ def AnimCut()
;@ The cut animation: a tree's two halves slide apart over 8 frames; grass leaves fly outwards, swap places
;@ and sink, twice. The sprite palette flickers each frame.
AnimCut:
;> if wCutTile == 0x52:                         # grass
;>@g     for _ in range(2):
;>@g1         AnimCutGrass_UpdateOAMEntries(8)
;>@g2         AnimCutGrass_SwapOAMEntries()
;>@g3         AnimCutGrass_UpdateOAMEntries(8)
;>@g4         AnimCutGrass_SwapOAMEntries()
;>@g5         wCoordAdjustmentAmount = 2
;>@g6         AdjustOAMBlockYPos2(addr(wShadowOAMSprite36YCoord), 4)
;>@gret     return
	ld a, [wCutTile]
	cp $52
	jr z, .grass
;>@tree for _ in range(8):
	ld c, $8
.cutTreeLoop
;>     wCoordAdjustmentAmount = 1
	push bc
	ld hl, wShadowOAMSprite36XCoord
	ld a, 1
	ld [wCoordAdjustmentAmount], a
;>     AdjustOAMBlockXPos2(addr(wShadowOAMSprite36XCoord), 2)
	ld c, 2
	call AdjustOAMBlockXPos2
;>     wCoordAdjustmentAmount = 0xFF            # -1
	ld hl, wShadowOAMSprite38XCoord
	ld a, -1
	ld [wCoordAdjustmentAmount], a
;>     AdjustOAMBlockXPos2(addr(wShadowOAMSprite38XCoord), 2)
	ld c, 2
	call AdjustOAMBlockXPos2
;>     rOBP1 = rOBP1 ^ 0x64
	ldh a, [rOBP1]
	xor $64
	ldh [rOBP1], a
;>     DelayFrame()
	call DelayFrame
;=@tree
	pop bc
	dec c
	jr nz, .cutTreeLoop
	ret
.grass
;=@g
	ld c, 2
.cutGrassLoop
	push bc
;=@g1
	ld c, $8
	call AnimCutGrass_UpdateOAMEntries
;=@g2
	call AnimCutGrass_SwapOAMEntries
;=@g3
	ld c, $8
	call AnimCutGrass_UpdateOAMEntries
;=@g4
	call AnimCutGrass_SwapOAMEntries
;=@g5
	ld hl, wShadowOAMSprite36YCoord
	ld a, 2
	ld [wCoordAdjustmentAmount], a
;=@g6
	ld c, 4
	call AdjustOAMBlockYPos2
;=@g
	pop bc
	dec c
	jr nz, .cutGrassLoop
;=@gret
	ret

;@ path: engine/overworld/cut2
;@ def AnimCutGrass_UpdateOAMEntries(frames: c)
;@ For `frames` frames, move the four leaf sprites sideways by 1, 2, -2 and -1 pixels and flicker the
;@ sprite palette.
AnimCutGrass_UpdateOAMEntries:
;>@frames for _ in range(frames or 256):
	push bc
;>     wCoordAdjustmentAmount = 1
	ld hl, wShadowOAMSprite36XCoord
	ld a, 1
	ld [wCoordAdjustmentAmount], a
;>     AdjustOAMBlockXPos2(addr(wShadowOAMSprite36XCoord), 1)
	ld c, 1
	call AdjustOAMBlockXPos2
;>     wCoordAdjustmentAmount = 2
	ld hl, wShadowOAMSprite37XCoord
	ld a, 2
	ld [wCoordAdjustmentAmount], a
;>     AdjustOAMBlockXPos2(addr(wShadowOAMSprite37XCoord), 1)
	ld c, 1
	call AdjustOAMBlockXPos2
;>     wCoordAdjustmentAmount = 0xFE            # -2
	ld hl, wShadowOAMSprite38XCoord
	ld a, -2
	ld [wCoordAdjustmentAmount], a
;>     AdjustOAMBlockXPos2(addr(wShadowOAMSprite38XCoord), 1)
	ld c, 1
	call AdjustOAMBlockXPos2
;>     wCoordAdjustmentAmount = 0xFF            # -1
	ld hl, wShadowOAMSprite39XCoord
	ld a, -1
	ld [wCoordAdjustmentAmount], a
;>     AdjustOAMBlockXPos2(addr(wShadowOAMSprite39XCoord), 1)
	ld c, 1
	call AdjustOAMBlockXPos2
;>     rOBP1 = rOBP1 ^ 0x64
	ldh a, [rOBP1]
	xor $64
	ldh [rOBP1], a
;>     DelayFrame()
	call DelayFrame
;=@frames
	pop bc
	dec c
	jr nz, AnimCutGrass_UpdateOAMEntries
	ret

;@ path: engine/overworld/cut2
;@ def AnimCutGrass_SwapOAMEntries()
;@ Swap the first two leaf sprites with the last two (through wBuffer).
AnimCutGrass_SwapOAMEntries:
;> CopyData(addr(wShadowOAMSprite36), addr(wBuffer), 2 * OBJ_SIZE)
	ld hl, wShadowOAMSprite36
	ld de, wBuffer
	ld bc, 2 * OBJ_SIZE
	call CopyData
;> CopyData(addr(wShadowOAMSprite38), addr(wShadowOAMSprite36), 2 * OBJ_SIZE)
	ld hl, wShadowOAMSprite38
	ld de, wShadowOAMSprite36
	ld bc, 2 * OBJ_SIZE
	call CopyData
;> CopyData(addr(wBuffer), addr(wShadowOAMSprite38), 2 * OBJ_SIZE)
	ld hl, wBuffer
	ld de, wShadowOAMSprite38
	ld bc, 2 * OBJ_SIZE
	jp CopyData
;@ path: engine/overworld/dust_smoke
;@ def AnimateBoulderDust()
;@ The dust cloud behind a pushed boulder: four smoke tiles in front of the player drift in the push
;@ direction for 8 steps while the palette flickers, then the player's own graphics are reloaded.
AnimateBoulderDust:
;> wWhichAnimationOffsets = 1                   # the boulder dust offsets
	ld a, $1
	ld [wWhichAnimationOffsets], a ; select the boulder dust offsets
;> saved = wUpdateSpritesEnabled
	ld a, [wUpdateSpritesEnabled]
	push af
;> wUpdateSpritesEnabled = 0xFF
	ld a, $ff
	ld [wUpdateSpritesEnabled], a
;> rOBP1 = 0b11100100
	ld a, %11100100
	ldh [rOBP1], a
;> LoadSmokeTileFourTimes()
	call LoadSmokeTileFourTimes
;> WriteCutOrBoulderDustAnimationOAMBlock()     # in another bank
	ld b, BANK(WriteCutOrBoulderDustAnimationOAMBlock)
	ld hl, WriteCutOrBoulderDustAnimationOAMBlock
	call Bankswitch
;> for _ in range(8):
	ld c, 8 ; number of steps in animation
.loop
;>     adjust, oam = GetMoveBoulderDustFunctionPointer()
	push bc
	call GetMoveBoulderDustFunctionPointer
;>     adjust(oam, 4)                           # AdjustOAMBlockXPos/YPos for the facing direction
	ld bc, .returnAddress
	push bc
	ld c, 4
	jp hl
.returnAddress
;>     rOBP1 = rOBP1 ^ 0b01100100
	ldh a, [rOBP1]
	xor %01100100
	ldh [rOBP1], a
;>     Delay3()
	call Delay3
	pop bc
	dec c
	jr nz, .loop
;> wUpdateSpritesEnabled = saved
	pop af
	ld [wUpdateSpritesEnabled], a
;> LoadPlayerSpriteGraphics()
	jp LoadPlayerSpriteGraphics

;@ path: engine/overworld/dust_smoke
;@ def GetMoveBoulderDustFunctionPointer() -> (hl, de)
;@ For the player's facing direction: the step of the dust movement (into wCoordAdjustmentAmount), the
;@ function that moves the dust sprites along x or y, and the OAM coordinate it moves.
;@ test: mem[0xC109] = 4 * rand(0, 3)
GetMoveBoulderDustFunctionPointer:
;> p = MoveBoulderDustFunctionPointerTable + wSpritePlayerStateData1FacingDirection
	ld a, [wSpritePlayerStateData1FacingDirection]
	ld hl, MoveBoulderDustFunctionPointerTable
	ld c, a
	ld b, $0
	add hl, bc
;> wCoordAdjustmentAmount = mem[p]
	ld a, [hli]
	ld [wCoordAdjustmentAmount], a
;> coord = mem[p + 1]
	ld a, [hli]
	ld e, a
;> func = mem16[p + 2]
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> oam = addr(wShadowOAMSprite36) + coord
	push hl
	ld hl, wShadowOAMSprite36
	ld d, $0
	add hl, de
	ld e, l
	ld d, h
;> return func, oam
	pop hl
	ret


;@ path: engine/overworld/dust_smoke
MoveBoulderDustFunctionPointerTable:
	; down
	db -1, 0
	dw AdjustOAMBlockYPos
	; up
	db 1, 0
	dw AdjustOAMBlockYPos
	; left
	db 1, 1
	dw AdjustOAMBlockXPos
	; right
	db -1, 1
	dw AdjustOAMBlockXPos

;@ path: engine/overworld/dust_smoke
;@ def LoadSmokeTileFourTimes()
;@ Put the smoke puff tile into sprite tiles $7C-$7F.
LoadSmokeTileFourTimes::
;> dest = addr(vChars1) + 0x7C * TILE_SIZE
	ld hl, vChars1 + TILE_SIZE * $7c
;>@loop for _ in range(4):
	ld c, 4
.loop
;>     LoadSmokeTile(dest)
	push bc
	push hl
	call LoadSmokeTile
	pop hl
;>     dest += TILE_SIZE
	ld bc, TILE_SIZE
	add hl, bc
;=@loop
	pop bc
	dec c
	jr nz, .loop
	ret

;@ path: engine/overworld/dust_smoke
;@ def LoadSmokeTile(dest: hl)
;@ Copy the smoke puff tile to `dest` in video memory.
LoadSmokeTile:
;> CopyVideoData(dest, SSAnneSmokePuffTile, BANK(SSAnneSmokePuffTile), (SSAnneSmokePuffTileEnd - SSAnneSmokePuffTile) // TILE_SIZE)
	ld de, SSAnneSmokePuffTile
	ld bc, ((BANK(SSAnneSmokePuffTile)) & $ff) << 8 + (((SSAnneSmokePuffTileEnd - SSAnneSmokePuffTile) / TILE_SIZE) & $ff)
	jp CopyVideoData

;@ path: engine/overworld/dust_smoke
SSAnneSmokePuffTile:
	db $00, $18, $1a, $66, $04, $42, $0b, $81, $56, $89, $1a, $2e, $4c, $12, $38, $38
;@ path: engine/overworld/dust_smoke
