	db $29, $70 ; BASECOORD_A9
	db $16, $60 ; BASECOORD_AA
	db $14, $58 ; BASECOORD_AB
	db $12, $54 ; BASECOORD_AC
	db $14, $50 ; BASECOORD_AD
	db $18, $4C ; BASECOORD_AE
	db $1C, $48 ; BASECOORD_AF
	db $48, $28 ; BASECOORD_B0

;@ path: data/battle_anims/frame_blocks
FrameBlock00:
	db 0 ; #

	db $00 ; unused
;@ path: engine/movie/evolution
;@ def EvolveMon() -> carry
;@ The evolution scene: the old Pokémon's cry, then to the Safari Zone music it flickers between its old and new
;@ shapes as a silhouette, faster and faster. B cancels (carry, wEvoCancelled) unless the evolution is forced;
;@ at the end the new Pokémon appears with its cry.
;@ test: skip runs the evolution scene
EvolveMon:
;> saved_party_species = wCurPartySpecies
	push hl
	push de
	push bc
	ld a, [wCurPartySpecies]
	push af
;> saved_species = wCurSpecies
	ld a, [wCurSpecies]
	push af
;> wLowHealthAlarm = 0
	xor a
	ld [wLowHealthAlarm], a
;> wChannelSoundIDs[CHAN5] = 0
	ld [wChannelSoundIDs + CHAN5], a
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	dec a ; SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> PlaySound(SFX_TINK)
	ld a, SFX_TINK
	call PlaySound
;> Delay3()
	call Delay3
;> hAutoBGTransferEnabled = 0
	xor a
	ldh [hAutoBGTransferEnabled], a
;> hTileAnimations = 0
	ldh [hTileAnimations], a
;> wWholeScreenPaletteMonSpecies = wEvoOldSpecies
	ld a, [wEvoOldSpecies]
	ld [wWholeScreenPaletteMonSpecies], a
;> EvolutionSetWholeScreenPalette(0)
	ld c, 0
	call EvolutionSetWholeScreenPalette
;> # the new picture goes to the back picture's VRAM, the old one is shown
;> wCurPartySpecies = wEvoNewSpecies
	ld a, [wEvoNewSpecies]
	ld [wCurPartySpecies], a
;> wCurSpecies = wEvoNewSpecies
	ld [wCurSpecies], a
;> Evolution_LoadPic()
	call Evolution_LoadPic
;> CopyVideoData(vBackPic, vFrontPic, PIC_SIZE >> 8, PIC_SIZE & 0xFF)     # bc = PIC_SIZE, read as bank and tile count
	ld de, vFrontPic
	ld hl, vBackPic
	ld bc, PIC_SIZE
	call CopyVideoData
;> wCurPartySpecies = wEvoOldSpecies
	ld a, [wEvoOldSpecies]
	ld [wCurPartySpecies], a
;> wCurSpecies = wEvoOldSpecies
	ld [wCurSpecies], a
;> Evolution_LoadPic()
	call Evolution_LoadPic
;> hAutoBGTransferEnabled = 1
	ld a, $1
	ldh [hAutoBGTransferEnabled], a
;> PlayCry(wEvoOldSpecies)
	ld a, [wEvoOldSpecies]
	call PlayCry
;> WaitForSoundToFinish()
	call WaitForSoundToFinish
;> PlayMusic(MUSIC_SAFARI_ZONE, BANK(Music_SafariZone))
	ld c, BANK(Music_SafariZone)
	ld a, MUSIC_SAFARI_ZONE
	call PlayMusic
;> DelayFrames(80)
	ld c, 80
	call DelayFrames
;> EvolutionSetWholeScreenPalette(1)                 # black
	ld c, 1 ; set PAL_BLACK instead of mon palette
	call EvolutionSetWholeScreenPalette
;> flips, frames, cancelled = 1, 0x10, False
;> while True:                                   # flickering faster and faster
	ld bc, (($1) & $ff) << 8 + (($10) & $ff)
.animLoop
;>     if Evolution_CheckForCancel(frames):      # B
;>@cancel         cancelled = True
;>@cancelbrk         break
	push bc
	call Evolution_CheckForCancel
	jr c, .evolutionCancelled
;>     Evolution_BackAndForthAnim(flips)
	call Evolution_BackAndForthAnim
;>     flips += 1
	pop bc
	inc b
;>     frames -= 2
	dec c
	dec c
;>     if frames == 0:
;>         break
	jr nz, .animLoop
;> if cancelled:
;>@cx1     wEvoCancelled = 1
;>@cx2     shown = wEvoOldSpecies
;> else:
;>     wEvoCancelled = 0
	xor a
	ld [wEvoCancelled], a
;>     wEvoMonTileOffset = 0x31
	ld a, $31
	ld [wEvoMonTileOffset], a
;>     Evolution_ChangeMonPic()                      # the new shape
	call Evolution_ChangeMonPic ; show the new species pic
;>     shown = wEvoNewSpecies
	ld a, [wEvoNewSpecies]
.done
;> wWholeScreenPaletteMonSpecies = shown
	ld [wWholeScreenPaletteMonSpecies], a
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> PlayCry(wWholeScreenPaletteMonSpecies)
	ld a, [wWholeScreenPaletteMonSpecies]
	call PlayCry
;> EvolutionSetWholeScreenPalette(0)
	ld c, 0
	call EvolutionSetWholeScreenPalette
;> wCurSpecies = saved_species
	pop af
	ld [wCurSpecies], a
;> wCurPartySpecies = saved_party_species
	pop af
	ld [wCurPartySpecies], a
;> # hl, de and bc back
	pop bc
	pop de
	pop hl
;> return wEvoCancelled != 0
	ld a, [wEvoCancelled]
	and a
	ret z
	scf
	ret
.evolutionCancelled
;=@cx1
	pop bc
	ld a, 1
	ld [wEvoCancelled], a
;=@cx2
	ld a, [wEvoOldSpecies]
	jr .done

;@ path: engine/movie/evolution
;@ def EvolutionSetWholeScreenPalette(black: c)
;@ The whole screen in the palette of wWholeScreenPaletteMonSpecies, or black.
;@ test: skip talks to the SGB
EvolutionSetWholeScreenPalette:
;> RunPaletteCommand(SET_PAL_POKEMON_WHOLE_SCREEN)
	ld b, SET_PAL_POKEMON_WHOLE_SCREEN
	jp RunPaletteCommand

;@ path: engine/movie/evolution
;@ def Evolution_LoadPic()
;@ Load wCurPartySpecies' front picture, mirrored, at coord(7, 2).
;@ test: skip decompresses into VRAM
Evolution_LoadPic:
;> GetMonHeader()
;> LoadFlippedFrontSpriteByMonIndex(coord(7, 2))
	call GetMonHeader
	ld hl, (2) * SCREEN_WIDTH + (7) + wTileMap
	jp LoadFlippedFrontSpriteByMonIndex

;@ path: engine/movie/evolution
;@ def Evolution_BackAndForthAnim(times: b)
;@ Switch the picture to the new shape and back, `times` times.
;@ test: skip waits for frames
Evolution_BackAndForthAnim:
; show the mon change back and forth between the new and old species b times
;> for _ in range(times):
;>     wEvoMonTileOffset = 0x31                  # the new shape
	ld a, $31
	ld [wEvoMonTileOffset], a
;>     Evolution_ChangeMonPic()
	call Evolution_ChangeMonPic
;>     wEvoMonTileOffset = u8(-0x31)             # the old one
	ld a, -$31
	ld [wEvoMonTileOffset], a
;>     Evolution_ChangeMonPic()
	call Evolution_ChangeMonPic
	dec b
	jr nz, Evolution_BackAndForthAnim
	ret

;@ path: engine/movie/evolution
;@ def Evolution_ChangeMonPic()
;@ Add wEvoMonTileOffset to the 7x7 picture tiles at coord(7, 2): the old picture's tiles and the new one's
;@ (in the back picture's VRAM) are $31 apart.
;@ test: skip waits for frames
Evolution_ChangeMonPic:
;> hAutoBGTransferEnabled = 0
	push bc
	xor a
	ldh [hAutoBGTransferEnabled], a
;> for row in range(7):
	ld hl, (2) * SCREEN_WIDTH + (7) + wTileMap
	ld bc, ((7) & $ff) << 8 + ((7) & $ff)
	ld de, SCREEN_WIDTH - 7
.loop
;>     for column in range(7):
	push bc
.innerLoop
;>         at = coord(7 + column, 2 + row)
;>         mem[at] = u8(mem[at] + wEvoMonTileOffset)
	ld a, [wEvoMonTileOffset]
	add [hl]
	ld [hli], a
	dec c
	jr nz, .innerLoop
;>     # down to the next row
	pop bc
	add hl, de
	dec b
	jr nz, .loop
;> hAutoBGTransferEnabled = 1
	ld a, 1
	ldh [hAutoBGTransferEnabled], a
;> Delay3()
	call Delay3
	pop bc
	ret

;@ path: engine/movie/evolution
;@ def Evolution_CheckForCancel(frames: c) -> carry
;@ Wait `frames` frames; carry if B was pressed and the evolution may be cancelled.
;@ test: skip waits for frames
Evolution_CheckForCancel:
;>@frames for _ in range(frames):
;>     DelayFrame()
	call DelayFrame
;>     JoypadLowSensitivity()
	push bc
	call JoypadLowSensitivity
;>     pressed = hJoy5 & PAD_B
	ldh a, [hJoy5]
	pop bc
	and PAD_B
;>@cancel     if pressed and not wForceEvolution:    # a forced evolution cannot be stopped
	jr nz, .pressedB
;>@yes         return True
.notAllowedToCancel
;=@frames
	dec c
	jr nz, Evolution_CheckForCancel
;> return False
	and a
	ret
.pressedB
;=@cancel
	ld a, [wForceEvolution]
	and a
	jr nz, .notAllowedToCancel
;=@yes
	scf
	ret
;@ path: engine/overworld/elevator
;@ def ShakeElevator()
;@ The elevator ride: redraw the rows just outside the screen, shake the picture up and down 100 times with
;@ a bump sound, then play the arrival announcement to its end and restore the map music.
ShakeElevator::
;> ShakeElevatorRedrawRow(0x10000 - 0x20)
	ld de, -$20
	call ShakeElevatorRedrawRow
;> ShakeElevatorRedrawRow(SCREEN_HEIGHT * 0x20)
	ld de, SCREEN_HEIGHT * $20
	call ShakeElevatorRedrawRow
;> Delay3()
	call Delay3
;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> base = hSCY
	ldh a, [hSCY]
	ld d, a
;> step = 1
	ld e, $1
;> for _ in range(100):
	ld b, 100
.shakeLoop ; scroll the BG up and down and play a sound effect
;>     step = step ^ 0xFE                       # -1, +1, -1, ...
	ld a, e
	xor $fe
	ld e, a
;>     hSCY = u8(base + step)
	add d
	ldh [hSCY], a
;>     PlayMusic(SFX_COLLISION, BANK(SFX_Collision_1))
	push bc
	ld c, BANK(SFX_Collision_1)
	ld a, SFX_COLLISION
	call PlayMusic
	pop bc
;>     DelayFrames(2)
	ld c, 2
	call DelayFrames
	dec b
	jr nz, .shakeLoop
;> hSCY = base
	ld a, d
	ldh [hSCY], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	ld a, SFX_STOP_ALL_MUSIC
	call PlaySound
;> PlayMusic(SFX_SAFARI_ZONE_PA, BANK(SFX_Safari_Zone_PA))
	ld c, BANK(SFX_Safari_Zone_PA)
	ld a, SFX_SAFARI_ZONE_PA
	call PlayMusic
.musicLoop
;> while wChannelSoundIDs[CHAN5] == SFX_SAFARI_ZONE_PA:    # until the announcement has ended
;>     wait_vblank_flag()    # the audio engine runs in the VBlank interrupt
	ld a, [wChannelSoundIDs + CHAN5]
	cp SFX_SAFARI_ZONE_PA
	jr z, .musicLoop
;> UpdateSprites()
	call UpdateSprites
;> PlayDefaultMusic()
	jp PlayDefaultMusic

;@ path: engine/overworld/elevator
;@ def ShakeElevatorRedrawRow(offset: de)
;@ Draw the map row `offset` bytes away from the top of the visible background (wrapping inside the
;@ background map), so no blank lines show while the screen shakes.
ShakeElevatorRedrawRow:
; Redraws slightly above the top and bottom edges of the screen in the bgmap
; This prevents small white lines from showing during the shaking animation if the bgmap hasn't been loaded outside the boundaries of the screen yet
; (For example, after loading a save in an elevator)
;> saved = wMapViewVRAMPointer[0], wMapViewVRAMPointer[1]
	ld hl, wMapViewVRAMPointer + 1
	ld a, [hld]
	push af
	ld a, [hl]
	push af
;> view = mem16[addr(wMapViewVRAMPointer)]
	push hl
	push hl
	ld a, [hli]
	ld h, [hl]
	ld l, a
;> p = (view + offset) & 0xFFFF
	add hl, de
;> high = (p >> 8) & 3 | addr(vBGMap0) >> 8      # wraps inside the background map
	ld a, h
	and $3
	or HIGH(vBGMap0)
	ld d, a
;> wMapViewVRAMPointer[0] = p & 0xFF
	ld a, l
	pop hl
	ld [hli], a
;> wMapViewVRAMPointer[1] = high
	ld [hl], d
;> ScheduleNorthRowRedraw()
	call ScheduleNorthRowRedraw
;> wMapViewVRAMPointer[0], wMapViewVRAMPointer[1] = saved
	pop hl
	pop af
	ld [hli], a
	pop af
	ld [hl], a
;> Delay3()
	jp Delay3
;@ def GetMachinePrice()
;@ The price of TM wCurItem as a 3-byte BCD number in hItemPrice. Each byte of TechnicalMachinePrices holds two
;@ prices in thousands, one per nibble. HMs have no price (hItemPrice is left alone).
;@ path: engine/items/tm_prices
GetMachinePrice::
; Input:  [wCurItem] = Item ID of a TM
; Output: Stores the TM price at hItemPrice
;> if wCurItem < TM01:
;>     return
	ld a, [wCurItem]
	sub TM01 ; underflows below 0 for HM items (before TM items)
	ret c ; HMs are priceless
;> tm = wCurItem - TM01
	ld d, a
;> p = TechnicalMachinePrices + tm // 2
	ld hl, TechnicalMachinePrices
	srl a
	ld c, a
	ld b, 0
	add hl, bc
;> b = mem[p]                                  # one nibble is the price in thousands
	ld a, [hl] ; a contains byte whose high or low nybble is the TM price (in thousands)
;> if tm & 1:
;>     b = swap(b)
	srl d
	jr nc, .highNybbleIsPrice ; is TM id odd?
	swap a
.highNybbleIsPrice
;> hItemPrice[1] = b & 0xF0
	and $f0
	ldh [hItemPrice + 1], a
;> hItemPrice[0] = 0
	xor a
	ldh [hItemPrice], a
;> hItemPrice[2] = 0
	ldh [hItemPrice + 2], a
;> return
	ret

;@ path: engine/items/tm_prices
TechnicalMachinePrices:
; In thousands (nybbles).
	; TM01
	; TM02
	db $32
	; TM03
	; TM04
	db $21
	; TM05
	; TM06
	db $34
	; TM07
	; TM08
	db $24
	; TM09
	; TM10
	db $34
	; TM11
	; TM12
	db $21
	; TM13
	; TM14
	db $45
	; TM15
	; TM16
	db $55
	; TM17
	; TM18
	db $32
	; TM19
	; TM20
	db $32
	; TM21
	; TM22
	db $55
	; TM23
	; TM24
	db $52
	; TM25
	; TM26
	db $54
	; TM27
	; TM28
	db $52
	; TM29
	; TM30
	db $41
	; TM31
	; TM32
	db $21
	; TM33
	; TM34
	db $12
	; TM35
	; TM36
	db $42
	; TM37
	; TM38
	db $25
	; TM39
	; TM40
	db $24
	; TM41
	; TM42
	db $22
	; TM43
	; TM44
